# True 8x8 Attribute Grid (32 columns x 24 rows)
ATTR_COLS = 32
ATTR_ROWS = 24
attr_ink = [[0 for _ in range(ATTR_COLS)] for _ in range(ATTR_ROWS)]
attr_paper = [[7 for _ in range(ATTR_COLS)] for _ in range(ATTR_ROWS)]
