# 1-bit monochrome bitmap array for up to 512x192 pixels (Modes 0, 1, 2 use 256, Mode 6 uses 512)
gfx_bits = [[False for _ in range(192)] for _ in range(512)]

# Precomputed VRAM address mapping: 6144 entries (0x4000..0x57FF)
# Each entry is (base_x, basin_y, cell_y, cell_x)
_VRAM_MAP = []
for _offset in range(6144):
    _third = (_offset >> 11) & 3
    _scanline = (_offset >> 8) & 7
    _row_in_third = (_offset >> 5) & 7
    _col = _offset & 31
    _scr_y = (_third << 6) | (_row_in_third << 3) | _scanline
    _basin_y = 191 - _scr_y
    _base_x = _col << 3
    _cell_y = (_third << 3) | _row_in_third
    _VRAM_MAP.append((_base_x, _basin_y, _cell_y, _col))

# Precomputed byte-to-8-pixels lookup table: 256 entries
_BYTE_BITS = [[bool((_b >> (7 - _i)) & 1) for _i in range(8)] for _b in range(256)]

# Precomputed (vram_addr, base_x, basin_y) for ultra-fast bidirectional memory sync
_VRAM_BYTES = [(0x4000 + _off, _entry[0], _entry[1]) for _off, _entry in enumerate(_VRAM_MAP)]

def sync_screen_memory(force=False):
    """
    Syncs display arrays (gfx_bits, attr_ink, attr_paper, attr_bright, attr_flash)
    into Spectrum Video RAM (memory[0x4000..0x5AFF]) and CPU memory if dirty.
    """
    global screen_bitmap_dirty, memory
    if not force and not globals().get('screen_bitmap_dirty', False):
        return
    mem = memory
    gfx = gfx_bits
    for addr, bx, by in _VRAM_BYTES:
        col0 = gfx[bx]
        col1 = gfx[bx+1]
        col2 = gfx[bx+2]
        col3 = gfx[bx+3]
        col4 = gfx[bx+4]
        col5 = gfx[bx+5]
        col6 = gfx[bx+6]
        col7 = gfx[bx+7]
        mem[addr] = ((128 if col0[by] else 0) |
                     (64 if col1[by] else 0) |
                     (32 if col2[by] else 0) |
                     (16 if col3[by] else 0) |
                     (8 if col4[by] else 0) |
                     (4 if col5[by] else 0) |
                     (2 if col6[by] else 0) |
                     (1 if col7[by] else 0))
    for r in range(24):
        r_base = 0x5800 + (r << 5)
        ink_r = attr_ink[r]
        paper_r = attr_paper[r]
        bright_r = attr_bright[r]
        flash_r = attr_flash[r]
        for c in range(32):
            mem[r_base + c] = ((128 if flash_r[c] else 0) |
                               (64 if bright_r[c] else 0) |
                               ((paper_r[c] & 7) << 3) |
                               (ink_r[c] & 7))
    cpu = get_z80_cpu() if 'get_z80_cpu' in globals() else globals().get('z80_cpu', None)
    if cpu is not None and hasattr(cpu, 'memory') and cpu.memory is not mem:
        cpu.memory[0x4000:0x5B00] = mem[0x4000:0x5B00]
    screen_bitmap_dirty = False

def sync_from_screen_memory():
    """
    Syncs Spectrum Video RAM (memory[0x4000..0x5AFF]) into display arrays
    (gfx_bits, attr_ink, attr_paper, attr_bright, attr_flash).
    """
    global gfx_bits, attr_ink, attr_paper, attr_bright, attr_flash, attr_used, canvas_dirty, canvas_dirty_cells, screen_bitmap_dirty, cell_bitmap
    mem = memory
    gfx = gfx_bits
    for addr, bx, by in _VRAM_BYTES:
        b = mem[addr]
        gfx[bx][by] = bool(b & 128)
        gfx[bx+1][by] = bool(b & 64)
        gfx[bx+2][by] = bool(b & 32)
        gfx[bx+3][by] = bool(b & 16)
        gfx[bx+4][by] = bool(b & 8)
        gfx[bx+5][by] = bool(b & 4)
        gfx[bx+6][by] = bool(b & 2)
        gfx[bx+7][by] = bool(b & 1)
    for r in range(24):
        r_base = 0x5800 + (r << 5)
        for c in range(32):
            val = mem[r_base + c]
            attr_ink[r][c] = val & 7
            attr_paper[r][c] = (val >> 3) & 7
            attr_bright[r][c] = bool(val & 64)
            attr_flash[r][c] = bool(val & 128)
            attr_used[r][c] = True
            if 'cell_bitmap' in globals() and cell_bitmap:
                cell_bitmap[r][c] = None
    canvas_dirty = True
    canvas_dirty_cells.clear()
    screen_bitmap_dirty = False

# Set of dirty (cell_y, cell_x) for ultra-fast incremental screen redraws
canvas_dirty_cells = set()

# Timex Sinclair 2068 (TS2068 / TC2068) Video System
# Mode 0: Normal Spectrum 256x192 (Screen 0 at 0x4000, attributes at 0x5800)
# Mode 1: Alternate Screen 1 256x192 (Screen 1 at 0x6000, attributes at 0x7800)
# Mode 2: Hi-Colour 256x192 (8x1 attribute resolution! Bitmap at 0x4000, attributes at 0x6000)
# Mode 6: Hi-Res 512x192 (Screen 0 even columns at 0x4000, Screen 1 odd columns at 0x6000)
timex_screen_mode = 0
timex_port_255 = 0
timex_hires_palette = 0
timex_port_f4 = 0
timex_dock_bank_select = 0  # 0 = DOCK, 1 = EX-ROM (Port 255 bit 7)
timex_timer_interrupt_enabled = True
timex_ay_selected_reg = 0
timex_dock_memory = bytearray(64 * 1024)
timex_exrom_memory = bytearray(64 * 1024)
timex_home_backup = bytearray(64 * 1024)
timex_current_paged_banks = [0] * 8  # 0 = HOME, 1 = DOCK, 2 = EX-ROM

TIMEX_HIRES_COLORS = [(0, 7), (1, 6), (2, 5), (3, 4), (4, 3), (5, 2), (6, 1), (7, 0)]

def update_timex_mmu(new_f4, new_dock_sel):
    global timex_port_f4, timex_dock_bank_select, memory
    new_f4 &= 0xFF
    new_dock_sel = 1 if new_dock_sel else 0
    for b in range(8):
        start_a = b * 8192
        end_a = (b + 1) * 8192
        bit_set = bool((new_f4 >> b) & 1)
        target_src = 0 if not bit_set else (2 if new_dock_sel == 1 else 1)
        curr_src = timex_current_paged_banks[b]
        if target_src == curr_src:
            continue
        if curr_src == 0:
            timex_home_backup[start_a:end_a] = memory[start_a:end_a]
        elif curr_src == 1:
            timex_dock_memory[start_a:end_a] = memory[start_a:end_a]
        elif curr_src == 2:
            timex_exrom_memory[start_a:end_a] = memory[start_a:end_a]

        if target_src == 0:
            memory[start_a:end_a] = timex_home_backup[start_a:end_a]
        elif target_src == 1:
            memory[start_a:end_a] = timex_dock_memory[start_a:end_a]
        elif target_src == 2:
            memory[start_a:end_a] = timex_exrom_memory[start_a:end_a]
        timex_current_paged_banks[b] = target_src
    timex_port_f4 = new_f4
    timex_dock_bank_select = new_dock_sel

def set_timex_mode(mode, palette=None, raw_val=None):
    global timex_screen_mode, timex_port_255, timex_hires_palette, canvas, canvas_dirty
    global timex_dock_bank_select, timex_timer_interrupt_enabled
    try:
        mode = int(mode)
    except Exception:
        mode = 0
    if mode not in (0, 1, 2, 6):
        mode = 0
    timex_screen_mode = mode
    if palette is not None:
        try:
            timex_hires_palette = int(palette) & 7
        except Exception:
            timex_hires_palette = 0
    if raw_val is not None:
        try:
            timex_port_255 = int(raw_val) & 0xFF
            timex_hires_palette = (timex_port_255 >> 3) & 7
            timex_dock_bank_select = 1 if (timex_port_255 & 0x80) else 0
            timex_timer_interrupt_enabled = bool(timex_port_255 & 0x40)
        except Exception:
            pass
    else:
        timex_port_255 = (mode & 7) | ((timex_hires_palette & 7) << 3) | ((1 if timex_dock_bank_select else 0) << 7) | ((1 if timex_timer_interrupt_enabled else 0) << 6)
    new_w = 512 if mode == 6 else 256
    if 'canvas' in globals() and canvas and canvas.get_width() != new_w and 'pygame' in globals() and pygame.get_init():
        canvas = pygame.Surface((new_w, 192))
    canvas_dirty = True

def handle_mode_command(cmd_str):
    global timex_screen_mode, timex_hires_palette
    s = cmd_str.strip()
    if s.upper().startswith("MODE"):
        s = s[4:].strip()
    if s.startswith(":"):
        s = s[1:].strip()
    if not s:
        canvas_print(f"Timex Screen Mode: {timex_screen_mode} (Port 255: {timex_port_255})")
        return
    upper_s = s.upper()
    if upper_s in ("NEXT", "ZXNEXT", "SPECTRUMNEXT", "NEXTBASIC"):
        set_zxnext_mode()
        return
    elif upper_s in ("48", "48K"):
        set_zx48_mode()
        return
    elif upper_s in ("128", "128K"):
        set_zx128_mode()
        return
    elif upper_s in ("+3", "PLUS3", "P3", "ZXP3"):
        set_zxp3_mode()
        return
    elif upper_s in ("TIMEX", "TS2068", "2068", "2048"):
        set_timex_machine_mode()
        return
    tokens = split_top_level_commas(s) if 'split_top_level_commas' in globals() else [p.strip() for p in s.split(',')]
    try:
        m = int(evaluate_expr(tokens[0]))
        pal = int(evaluate_expr(tokens[1])) if len(tokens) > 1 and tokens[1].strip() else None
        set_timex_mode(m, pal)
    except Exception as e:
        canvas_print(f"Invalid MODE argument: {e}")

def handle_poke_vram(addr, val):
    global canvas_dirty, canvas_dirty_cells, cell_bitmap
    if 0x4000 <= addr < 0x5800:
        base_x, basin_y, cell_y, col = _VRAM_MAP[addr - 0x4000]
        bits = _BYTE_BITS[val]
        if timex_screen_mode == 6:
            x_start = col * 16
            for i in range(8):
                gfx_bits[x_start + i][basin_y] = bits[i]
        else:
            for i in range(8):
                gfx_bits[base_x + i][basin_y] = bits[i]
        if 'cell_bitmap' in globals() and cell_bitmap and cell_y < len(cell_bitmap) and col < len(cell_bitmap[0]):
            cell_bitmap[cell_y][col] = None
        canvas_dirty_cells.add((cell_y, col))
        canvas_dirty = True
    elif 0x5800 <= addr < 0x5B00:
        offset = addr - 0x5800
        cell_y = offset >> 5
        col = offset & 31
        attr_ink[cell_y][col] = val & 7
        attr_paper[cell_y][col] = (val >> 3) & 7
        attr_bright[cell_y][col] = bool((val >> 6) & 1)
        attr_flash[cell_y][col] = bool((val >> 7) & 1)
        attr_used[cell_y][col] = True
        if 'cell_bitmap' in globals() and cell_bitmap and cell_y < len(cell_bitmap) and col < len(cell_bitmap[0]):
            cell_bitmap[cell_y][col] = None
        canvas_dirty_cells.add((cell_y, col))
        canvas_dirty = True
    elif 0x6000 <= addr < 0x7800:
        base_x, basin_y, cell_y, col = _VRAM_MAP[addr - 0x6000]
        bits = _BYTE_BITS[val]
        if timex_screen_mode == 6:
            x_start = col * 16 + 8
            for i in range(8):
                gfx_bits[x_start + i][basin_y] = bits[i]
        elif timex_screen_mode == 1:
            for i in range(8):
                gfx_bits[base_x + i][basin_y] = bits[i]
        canvas_dirty = True
    elif 0x7800 <= addr < 0x7B00:
        if timex_screen_mode == 1:
            offset = addr - 0x7800
            cell_y = offset >> 5
            col = offset & 31
            attr_ink[cell_y][col] = val & 7
            attr_paper[cell_y][col] = (val >> 3) & 7
            attr_bright[cell_y][col] = bool((val >> 6) & 1)
            attr_flash[cell_y][col] = bool((val >> 7) & 1)
            attr_used[cell_y][col] = True
        canvas_dirty = True

def evaluate_timex_stick(port_num=1, req_type=1):
    res = 0
    try:
        if pygame.display.get_init():
            keys = pygame.key.get_pressed()
            if port_num == 1:
                if keys[pygame.K_UP] or keys[pygame.K_KP8] or keys[pygame.K_7]: res |= 1
                if keys[pygame.K_DOWN] or keys[pygame.K_KP2] or keys[pygame.K_6]: res |= 2
                if keys[pygame.K_LEFT] or keys[pygame.K_KP4] or keys[pygame.K_5]: res |= 4
                if keys[pygame.K_RIGHT] or keys[pygame.K_KP6] or keys[pygame.K_8]: res |= 8
                if keys[pygame.K_SPACE] or keys[pygame.K_KP0] or keys[pygame.K_0]:
                    if req_type == 2: return 128.0
                    res |= 128
            else:
                if keys[pygame.K_w] or keys[pygame.K_4]: res |= 1
                if keys[pygame.K_s] or keys[pygame.K_3]: res |= 2
                if keys[pygame.K_a] or keys[pygame.K_1]: res |= 4
                if keys[pygame.K_d] or keys[pygame.K_2]: res |= 8
                if keys[pygame.K_LCTRL] or keys[pygame.K_5]:
                    if req_type == 2: return 128.0
                    res |= 128
    except Exception:
        pass
    if req_type == 2:
        return 128.0 if (res & 128) else 0.0
    return float(res & 15)

def get_free_memory():
    try:
        ramtop = memory[23730] | (memory[23731] << 8)
        if ramtop <= 0 or ramtop > 65535:
            ramtop = 65367
        vars_addr = memory[23627] | (memory[23628] << 8)
        if vars_addr <= 23755 or vars_addr >= ramtop:
            prog_len = sum(len(stmt) + 5 for stmt in program.values()) if 'program' in globals() else 0
            vars_len = len(variables) * 8 + len(string_variables) * 16 + sum(len(v) for v in string_variables.values())
            return max(0.0, float(ramtop - (23755 + prog_len + vars_len)))
        return max(0.0, float(ramtop - vars_addr))
    except Exception:
        return 41000.0

# Precomputed contention delay and scanline tables for high-performance emulation
_CONTENTION_DELAY = (6, 5, 4, 3, 2, 1, 0, 0)

# Ultra-fast 64K lookup table for direct 8-bit VRAM rasterization: (attr << 8) | byte_val -> 8 bytes
_VRAM_PIXEL_TABLE = [None] * 65536
_VRAM_PIXEL_TABLE_FLASH = [None] * 65536
for _attr in range(256):
    _ink = (_attr & 7) | ((_attr & 0x40) >> 3)
    _paper = ((_attr >> 3) & 7) | ((_attr & 0x40) >> 3)
    _f_ink = _paper if (_attr & 0x80) else _ink
    _f_paper = _ink if (_attr & 0x80) else _paper
    _base = _attr << 8
    for _b in range(256):
        _VRAM_PIXEL_TABLE[_base | _b] = bytes([_ink if (_b & (1 << (7 - _bit))) else _paper for _bit in range(8)])
        _VRAM_PIXEL_TABLE_FLASH[_base | _b] = bytes([_f_ink if (_b & (1 << (7 - _bit))) else _f_paper for _bit in range(8)])

# Precomputed scanline offsets for direct VRAM rendering (192 scanlines)
_VRAM_SCANLINE_OFFSETS = [
    (
        0x4000 | ((_y & 0xC0) << 5) | ((_y & 0x07) << 8) | ((_y & 0x38) << 2),
        0x5800 | ((_y >> 3) << 5),
        _y * 256
    )
    for _y in range(192)
]

# Fast 8-bit palette surface for hardware-accelerated VRAM blitting
_fast_vram_surf = None
_vram_raw_buf = bytearray(49152)
def _get_fast_vram_surf():
    global _fast_vram_surf
    if _fast_vram_surf is None and 'pygame' in globals() and pygame.get_init():
        _fast_vram_surf = pygame.Surface((256, 192), depth=8)
        _pal = [
            (0,0,0), (0,0,205), (205,0,0), (205,0,205), (0,205,0), (0,205,205), (205,205,0), (205,205,205),
            (0,0,0), (0,0,255), (255,0,0), (255,0,255), (0,255,0), (0,255,255), (255,255,0), (255,255,255)
        ]
        _fast_vram_surf.set_palette(_pal)
    return _fast_vram_surf

