def load_rom_file(rom_name, fallback_bytes=None):
    """
    Search for a ROM file in ./Roms, ./roms, <script_dir>/Roms, <script_dir>/roms.
    If found and valid length (>0), return bytes(data). Otherwise return fallback_bytes.
    """
    search_dirs = [
        os.path.join(os.getcwd(), "Roms"),
        os.path.join(os.getcwd(), "roms"),
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "Roms"),
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "roms"),
    ]
    for d in search_dirs:
        p = os.path.join(d, rom_name)
        if os.path.isfile(p):
            try:
                with open(p, "rb") as f:
                    data = f.read()
                    if data:
                        return data
            except Exception:
                pass
    return fallback_bytes


