def init_system_variables():
    # Authentic Sinclair ZX Spectrum ROM image in memory (0x0000 - 0x3FFF, 16384 bytes)
    if cartridge_inserted and cartridge_rom:
        memory[0 : min(16384, len(cartridge_rom))] = cartridge_rom[:16384]
    elif 'plus3_mode' in globals() and plus3_mode and 'rom_banks' in globals() and rom_banks:
        c_rom = current_rom_bank if 'current_rom_bank' in globals() else (0 if ('spectrum_128k_mode' in globals() and spectrum_128k_mode) else 3)
        memory[0 : 16384] = rom_banks[c_rom]
    else:
        memory[0 : 16384] = basic_rom_backup if ('basic_rom_backup' in globals() and basic_rom_backup) else ZX_48K_ROM
    # Authentic Sinclair ZX Spectrum 48K ROM character generator table (15616-16383)
    memory[15616 : 15616 + 768] = ZX_ROM_FONT
    # CHARS system variable (23606-23607) points 256 bytes before first char (space=32): 15616 - 256 = 15360 (0x3C00)
    chars_base = 15616 - 256
    memory[23606] = chars_base & 0xFF
    memory[23607] = (chars_base >> 8) & 0xFF

    memory[23610] = 255                    # ERR_NR (23610)
    memory[23611] = 0                      # FLAGS (23611)
    memory[23612] = 0                      # TVFLAG (23612)
    memory[23624] = (current_border & 7)   # BORDCR (23624)
    if memory[23627] == 0 and memory[23628] == 0:
        memory[23627] = 23756 & 0xFF       # VARS (23627)
        memory[23628] = (23756 >> 8) & 0xFF
    if memory[23635] == 0 and memory[23636] == 0:
        memory[23635] = 23755 & 0xFF       # PROG (23635)
        memory[23636] = (23755 >> 8) & 0xFF
    if memory[23639] == 0 and memory[23640] == 0:
        memory[23639] = 23755 & 0xFF       # DATADD (23639)
        memory[23640] = (23755 >> 8) & 0xFF
    memory[23658] = 0                      # FLAGS2
    memory[23659] = 2                      # DF_SZ
    memory[23670] = 0                      # SEED
    memory[23671] = 0
    memory[23672] = 0                      # FRAMES
    memory[23673] = 0
    memory[23674] = 0
    
    udg_base = 65368                       # UDG (23675-23676)
    memory[23675] = udg_base & 0xFF
    memory[23676] = (udg_base >> 8) & 0xFF
    if 'load_default_udgs' in globals() and not any(memory[65368 : 65368 + 168]):
        load_default_udgs()
    
    memory[23677] = gfx_x & 0xFF           # COORDS (23677-23678)
    memory[23678] = gfx_y & 0xFF
    
    attr_p = (current_paper << 3) | (current_ink & 7)
    if current_bright: attr_p |= 64
    if current_flash: attr_p |= 128
    memory[23693] = attr_p                 # ATTR_P (23693)
    memory[23695] = attr_p                 # ATTR_T (23695)
    memory[23696] = 0                      # MASK_T (23696)
    
    stkend_base = 23698                    # STKEND / STKBOT (23651-23654 default calculator stack)
    if memory[23651] == 0 and memory[23652] == 0:
        memory[23651] = stkend_base & 0xFF
        memory[23652] = (stkend_base >> 8) & 0xFF
    if memory[23653] == 0 and memory[23654] == 0:
        memory[23653] = stkend_base & 0xFF
        memory[23654] = (stkend_base >> 8) & 0xFF
    if memory[23730] == 0 and memory[23731] == 0:
        memory[23730] = 0xFF               # RAMTOP (23730-23731)
        memory[23731] = 0xFF
    if memory[23732] == 0 and memory[23733] == 0:
        memory[23732] = 0xFF               # P_RAMT (23732-23733)
        memory[23733] = 0xFF
    current_udg_bank = 0
    global udg_editor_active, active_udg_editor, music_editor_active, active_music_editor, sfx_editor_active, active_sfx_editor, drum_editor_active, active_drum_editor
    udg_editor_active = False
    active_udg_editor = None
    music_editor_active = False
    active_music_editor = None
    sfx_editor_active = False
    active_sfx_editor = None
    drum_editor_active = False
    active_drum_editor = None


