def get_next_inkey():
    global last_keypress
    if key_press_buffer:
        k = key_press_buffer.popleft()
        last_keypress = key_press_buffer[0] if key_press_buffer else ""
        return k
    if last_keypress:
        k = last_keypress
        last_keypress = ""
        return k
    try:
        if pygame.display.get_init():
            pressed = pygame.key.get_pressed()
            if pressed[pygame.K_UP] or pressed[pygame.K_KP7]:
                return '7'
            if pressed[pygame.K_DOWN] or pressed[pygame.K_KP6]:
                return '6'
            if pressed[pygame.K_LEFT] or pressed[pygame.K_KP4] or pressed[pygame.K_KP5]:
                return '5'
            if pressed[pygame.K_RIGHT] or pressed[pygame.K_KP8]:
                return '8'
            if pressed[pygame.K_SPACE]:
                return ' '
            if pressed[pygame.K_RETURN] or pressed[pygame.K_KP_ENTER]:
                return '\r'
            for num in range(10):
                k_code = getattr(pygame, f"K_{num}")
                kp_code = getattr(pygame, f"K_KP{num}", None)
                if pressed[k_code] or (kp_code and pressed[kp_code]):
                    return str(num)
            for ch in "abcdefghijklmnopqrstuvwxyz":
                k_code = getattr(pygame, f"K_{ch}")
                if pressed[k_code]:
                    mods = pygame.key.get_mods()
                    is_shift = bool(mods & (pygame.KMOD_SHIFT | pygame.KMOD_CAPS))
                    return ch.upper() if is_shift else ch
    except Exception:
        pass
    return get_joystick_inkey()
