def display_startup_splash():
    global current_paper, current_ink, current_border, current_bright, canvas_dirty, canvas_lines
    current_paper = 0
    current_ink = 7
    current_border = 0
    current_bright = True
    memory[23624] = 0
    memory[23693] = 0x47

    for r in range(ATTR_ROWS):
        for c in range(ATTR_COLS):
            attr_ink[r][c] = 7
            attr_paper[r][c] = 0
            attr_bright[r][c] = True
            attr_flash[r][c] = False
            attr_used[r][c] = True
            screen_chars[r][c] = ' '
            cell_bitmap[r][c] = None

    for x in range(256):
        for y in range(192):
            gfx_bits[x][y] = False

    # 1. "s i n c l a i r" on Row 2
    sinclair_text = "s i n c l a i r"
    s_col = (32 - len(sinclair_text)) // 2
    for i, ch in enumerate(sinclair_text):
        screen_chars[2][s_col + i] = ch
        attr_ink[2][s_col + i] = 7
        attr_bright[2][s_col + i] = False

    # 2. "ZX Spectrum" on Row 3 (cols 8..18)
    zx_text = "ZX Spectrum"
    for i, ch in enumerate(zx_text):
        screen_chars[3][8 + i] = ch
        attr_ink[3][8 + i] = 7
        attr_bright[3][8 + i] = True

    # 4 color diagonal stripes in cols 19, 20, 21, 22 on Rows 3 and 4
    # Slashes are strictly confined to each column's 8 pixels:
    # Col 19: Red (2), Col 20: Yellow (6), Col 21: Green (4), Col 22: Cyan (5)
    stripe_colors = [2, 6, 4, 5]
    for i, col_val in enumerate(stripe_colors):
        c = 19 + i
        attr_ink[3][c] = col_val
        attr_bright[3][c] = True
        attr_ink[4][c] = col_val
        attr_bright[4][c] = True
        col_base_x = c * 8
        for py in range(24, 40):
            rel_y = py - 24
            shift = int(round(3.0 - (rel_y * 3.0 / 15.0)))
            for w in range(4):
                px = col_base_x + shift + w
                if col_base_x <= px < col_base_x + 8:
                    gfx_bits[px][191 - py] = True

    # 4-color underline on Row 5 (cols 8..22)
    bar_cols = [
        (8, 12, 2),   # Cols 8..11: Red
        (12, 16, 6),  # Cols 12..15: Yellow
        (16, 20, 4),  # Cols 16..19: Green
        (20, 23, 5),  # Cols 20..22: Cyan
    ]
    for start_c, end_c, color_val in bar_cols:
        for c in range(start_c, end_c):
            attr_ink[5][c] = color_val
            attr_bright[5][c] = True
            for px in range(c * 8, (c + 1) * 8):
                for py in range(41, 44):
                    gfx_bits[px][191 - py] = True

    # 3. Centered text lines
    lines_info = [
        (7, "BasinPy Extended", 6, True),           # Bright Yellow
        (9, "Produced by Gemini AI", 5, True),        # Bright Cyan
        (11, "Devised by Karl Sheldon", 7, True),      # Bright White
        (13, "Influenced by BasicC", 4, True),         # Bright Green
        (15, "(C) 2003 Paul Dunn", 7, True),           # Bright White
        (16, "(C) 2011 Arda Erdikmen", 7, True),       # Bright White
    ]

    for row, text, ink, bright in lines_info:
        col = (32 - len(text)) // 2
        for i, ch in enumerate(text):
            screen_chars[row][col + i] = ch
            attr_ink[row][col + i] = ink
            attr_bright[row][col + i] = bright

    canvas_lines.clear()
    for row, text, _, _ in lines_info:
        canvas_lines.append(text.center(32))

    for scr_y in range(192):
        y_bmp = 191 - scr_y
        third = scr_y // 64
        row_in_third = (scr_y % 64) // 8
        line_in_row = scr_y % 8
        for col in range(32):
            addr = 0x4000 | (third << 11) | (line_in_row << 8) | (row_in_third << 5) | col
            byte_val = 0
            x_base = col * 8
            for bit in range(8):
                if gfx_bits[x_base + bit][y_bmp]:
                    byte_val |= (1 << (7 - bit))
            memory[addr] = byte_val
    for r in range(24):
        for c in range(32):
            attr_byte = (128 if attr_flash[r][c] else 0) | (64 if attr_bright[r][c] else 0) | (attr_paper[r][c] << 3) | (attr_ink[r][c] & 7)
            memory[0x5800 + r * 32 + c] = attr_byte

    canvas.fill(COLORS[current_paper])
    canvas_dirty = True
    if "redraw_canvas" in globals():
        redraw_canvas(force=True)

display_startup_splash()


