def get_vars_listing_lines():
    global variables, string_variables, arrays, ram_disk_arrays
    lines = []

    # 1. Simple numeric variables
    if "variables" in globals() and variables:
        for k in sorted(variables.keys()):
            val = variables[k]
            if isinstance(val, float) and val.is_integer():
                val_str = str(int(val))
            else:
                val_str = str(val)
            lines.append(f"{k} = {val_str}")

    # 2. Simple string variables
    if "string_variables" in globals() and string_variables:
        for k in sorted(string_variables.keys()):
            val = string_variables[k]
            lines.append(f'{k} = "{val}"')

    # 3. Dimensioned arrays
    all_arrays = {}
    if "arrays" in globals() and arrays:
        for k, v in arrays.items():
            all_arrays[k] = v
    if "ram_disk_arrays" in globals() and ram_disk_arrays:
        for k, v in ram_disk_arrays.items():
            all_arrays[k] = v

    if all_arrays:
        for arr_name in sorted(all_arrays.keys()):
            arr_obj = all_arrays[arr_name]
            dims = []
            base_val = None

            if isinstance(arr_obj, list):
                curr = arr_obj
                while isinstance(curr, list) and len(curr) > 0:
                    dims.append(len(curr) - 1)
                    curr = curr[1] if len(curr) > 1 else curr[0]
                base_val = curr
            elif isinstance(arr_obj, tuple) and len(arr_obj) == 2:
                dims = list(arr_obj[0])
                d_dict = arr_obj[1]
                if isinstance(d_dict, dict):
                    k1 = tuple([1] * len(dims)) if dims else (1,)
                    base_val = d_dict.get(k1, d_dict.get((1,), 0.0))
                else:
                    base_val = 0.0
            elif isinstance(arr_obj, dict):
                dims = list(arr_obj.get("dims", []))
                d_dict = arr_obj.get("data", {})
                base_val = d_dict.get("1", 0.0) if isinstance(d_dict, dict) else 0.0

            dims_str = ",".join(str(d) for d in dims) if dims else ""
            if isinstance(base_val, float) and base_val.is_integer():
                base_str = str(int(base_val))
            elif isinstance(base_val, str):
                base_str = f'"{base_val}"'
            else:
                base_str = str(base_val if base_val is not None else 0)

            arr_display_name = arr_name
            if not arr_display_name.endswith(")") and dims_str:
                arr_display_name = f"{arr_name}({dims_str})"
            lines.append(f"{arr_display_name} = {base_str} (base value)")

    if not lines:
        lines.append("(No variables defined)")

    return lines


def ensure_compiled_code_blocks():
    """
    Scans current program and Zeus buffer to ensure any FORTH or Z80 blocks
    are pre-compiled into machine code with computed start addresses and lengths,
    populating _forth_compiled_blocks and _z80_compiled_blocks.
    Does NOT invoke CPU execution.
    """
    global _forth_compiled_blocks, _last_compiled_forth, _z80_compiled_blocks
    global program, memory, zeus_source

    if "_forth_compiled_blocks" not in globals():
        return
    if "_z80_compiled_blocks" not in globals():
        return

    if "program" in globals() and program:
        line_numbers = sorted(program.keys())
        idx = 0
        while idx < len(line_numbers):
            ln = line_numbers[idx]
            line_raw = program.get(ln, "")
            line_clean = line_raw.strip()
            if line_clean.upper().startswith("REM") or line_clean.startswith(";") or line_clean.startswith("'"):
                idx += 1
                continue

            # 1. Single-line or multi-line FORTH in program
            m_forth_same = re.search(r'\bFORTH\b(.*?)\b(?:END\s+FORTH|ENDFORTH|END_FORTH)\b', line_raw, re.IGNORECASE)
            if m_forth_same:
                f_code = m_forth_same.group(1).strip()
                if f_code and (ln, "single") not in _forth_compiled_blocks:
                    try:
                        compiler = SinclairForthCompiler()
                        asm_code = compiler.compile(f_code)
                        asm = get_zeus_assembler()
                        cbytes = asm.assemble(asm_code, target_memory=memory)
                        _forth_compiled_blocks[(ln, "single")] = {
                            "compiled": True,
                            "address": compiler.org,
                            "code_hash": hash(f_code),
                            "length": len(cbytes),
                            "code_bytes": bytes(cbytes),
                            "source": f_code
                        }
                    except Exception:
                        pass
                idx += 1
                continue

            m_f_start = re.search(r'\bFORTH\b', line_raw, re.IGNORECASE)
            if m_f_start:
                f_blocks = []
                tail = line_raw[m_f_start.end():].strip()
                if tail.startswith(":"): tail = tail[1:].strip()
                if tail: f_blocks.append(tail)

                scan_idx = idx + 1
                found_end = False
                while scan_idx < len(line_numbers):
                    sln = line_numbers[scan_idx]
                    sline = program.get(sln, "")
                    m_end = re.search(r'\b(?:END\s+FORTH|ENDFORTH|END_FORTH)\b', sline, re.IGNORECASE)
                    if m_end:
                        found_end = True
                        pre = sline[:m_end.start()].strip()
                        if pre: f_blocks.append(pre)
                        scan_idx += 1
                        break
                    elif re.match(r'^\s*FORTH\s*$', sline, re.IGNORECASE):
                        found_end = True
                        scan_idx += 1
                        break
                    else:
                        f_blocks.append(sline)
                    scan_idx += 1

                if f_blocks and (ln, "multi") not in _forth_compiled_blocks:
                    combined_forth = "\n".join(f_blocks).strip()
                    try:
                        compiler = SinclairForthCompiler()
                        asm_code = compiler.compile(combined_forth)
                        asm = get_zeus_assembler()
                        cbytes = asm.assemble(asm_code, target_memory=memory)
                        _forth_compiled_blocks[(ln, "multi")] = {
                            "compiled": True,
                            "address": compiler.org,
                            "code_hash": hash(combined_forth),
                            "length": len(cbytes),
                            "code_bytes": bytes(cbytes),
                            "source": combined_forth
                        }
                    except Exception:
                        pass
                idx = scan_idx
                continue

            # 2. Single-line or multi-line Z80 in program
            m_z80_same = re.search(r'\bZ80\b(.*?)\b(?:END\s+Z80|ENDZ80|END_Z80)\b', line_raw, re.IGNORECASE)
            if m_z80_same:
                z_code = m_z80_same.group(1).strip()
                if z_code and (ln, "single") not in _z80_compiled_blocks:
                    try:
                        asm = get_zeus_assembler()
                        cbytes = asm.assemble(z_code, target_memory=memory)
                        _z80_compiled_blocks[(ln, "single")] = {
                            "compiled": True,
                            "address": asm.org_address,
                            "code_hash": hash(z_code),
                            "length": len(cbytes),
                            "has_code": True,
                            "source": z_code
                        }
                    except Exception:
                        pass
                idx += 1
                continue

            m_z_start = re.search(r'\bZ80\b', line_raw, re.IGNORECASE)
            if m_z_start:
                z_blocks = []
                tail = line_raw[m_z_start.end():].strip()
                if tail.startswith(":"): tail = tail[1:].strip()
                if tail: z_blocks.append(tail)

                scan_idx = idx + 1
                while scan_idx < len(line_numbers):
                    sln = line_numbers[scan_idx]
                    sline = program.get(sln, "")
                    m_end = re.search(r'\b(?:END\s+Z80|ENDZ80|END_Z80)\b', sline, re.IGNORECASE)
                    if m_end:
                        pre = sline[:m_end.start()].strip()
                        if pre: z_blocks.append(pre)
                        scan_idx += 1
                        break
                    elif re.match(r'^\s*Z80\s*$', sline, re.IGNORECASE):
                        scan_idx += 1
                        break
                    else:
                        z_blocks.append(sline)
                    scan_idx += 1

                if z_blocks and (ln, "multi") not in _z80_compiled_blocks:
                    combined_z80 = "\n".join(z_blocks).strip()
                    try:
                        asm = get_zeus_assembler()
                        cbytes = asm.assemble(combined_z80, target_memory=memory)
                        _z80_compiled_blocks[(ln, "multi")] = {
                            "compiled": True,
                            "address": asm.org_address,
                            "code_hash": hash(combined_z80),
                            "length": len(cbytes),
                            "has_code": True,
                            "source": combined_z80
                        }
                    except Exception:
                        pass
                idx = scan_idx
                continue

            idx += 1

    # 3. Check Zeus editor buffer
    if "zeus_source" in globals() and zeus_source:
        full_src = "\n".join(zeus_source[k] for k in sorted(zeus_source.keys())).strip()
        if full_src:
            try:
                asm = get_zeus_assembler()
                asm.assemble(full_src, target_memory=memory)
            except Exception:
                pass


def get_code_listing_lines_with_summary():
    """
    Returns (listing_lines, summary_strings)
    listing_lines: list of (text, color) tuples for rendering in listing_rect
    summary_strings: list of plain text strings for canvas_print
    """
    global _forth_compiled_blocks, _last_compiled_forth, _z80_compiled_blocks
    global zeus_source

    ensure_compiled_code_blocks()

    listing_lines = []
    summary_strings = []
    blocks = []

    # 1. Forth compiled blocks
    if "_forth_compiled_blocks" in globals() and _forth_compiled_blocks:
        for k, info in sorted(_forth_compiled_blocks.items(), key=lambda item: str(item[0])):
            if not isinstance(info, dict): continue
            addr = info.get("address", 32768)
            length = info.get("length", 0)
            if length <= 0 and "code_bytes" in info:
                length = len(info["code_bytes"])
            origin = f"Line {k[0]}" if isinstance(k, tuple) and len(k) > 0 else str(k)
            src = info.get("source", "").strip().splitlines()[0] if info.get("source") else ""
            blocks.append({
                "type": "FORTH",
                "origin": origin,
                "address": addr,
                "length": length,
                "source": src,
                "color": (0, 135, 140)
            })

    if "_last_compiled_forth" in globals() and _last_compiled_forth and isinstance(_last_compiled_forth, dict):
        addr = _last_compiled_forth.get("address", 32768)
        length = _last_compiled_forth.get("length", 0)
        if not any(b["type"] == "FORTH" and b["address"] == addr and b["length"] == length for b in blocks):
            src = _last_compiled_forth.get("source", "").strip().splitlines()[0] if _last_compiled_forth.get("source") else ""
            blocks.append({
                "type": "FORTH",
                "origin": "Last Forth",
                "address": addr,
                "length": length,
                "source": src,
                "color": (0, 135, 140)
            })

    # 2. Z80 compiled blocks
    if "_z80_compiled_blocks" in globals() and _z80_compiled_blocks:
        for k, info in sorted(_z80_compiled_blocks.items(), key=lambda item: str(item[0])):
            if not isinstance(info, dict): continue
            addr = info.get("address", 32768)
            length = info.get("length", 0)
            origin = f"Line {k[0]}" if isinstance(k, tuple) and len(k) > 0 else str(k)
            src = info.get("source", "").strip().splitlines()[0] if info.get("source") else ""
            blocks.append({
                "type": "Z80",
                "origin": origin,
                "address": addr,
                "length": length,
                "source": src,
                "color": (0, 50, 200)
            })

    # 3. Zeus Assembler
    if "get_zeus_assembler" in globals() and "zeus_source" in globals() and zeus_source and any(v.strip() for v in zeus_source.values()):
        try:
            asm = get_zeus_assembler()
            cbytes = getattr(asm, "code_bytes", None)
            if cbytes and len(cbytes) > 0:
                blocks.append({
                    "type": "ZEUS",
                    "origin": f"Buffer ({len(zeus_source)} lines)",
                    "address": asm.org_address,
                    "length": len(cbytes),
                    "source": f"ORG #{asm.org_address:04X} ({asm.org_address})",
                    "color": (160, 40, 0)
                })
        except Exception:
            pass

    if not blocks:
        listing_lines.append(("(No compiled Forth or Z80 code in memory)", (120, 120, 120)))
        listing_lines.append(("", (0, 0, 0)))
        listing_lines.append(("To compile code:", (80, 80, 80)))
        listing_lines.append(("  - Write FORTH ... END FORTH in BASIC", (60, 60, 100)))
        listing_lines.append(("  - Write Z80 ... END Z80 in BASIC", (60, 60, 100)))
        listing_lines.append(("  - Assemble code in Zeus Assembler (ZEUS)", (60, 60, 100)))
        listing_lines.append(("", (0, 0, 0)))
        listing_lines.append(("(Type LIST to return to program code)", (130, 130, 130)))
        return listing_lines, summary_strings

    total_bytes = 0
    for b in blocks:
        b_type = b["type"]
        b_orig = b["origin"]
        addr = b["address"]
        length = b["length"]
        total_bytes += length
        end_addr = (addr + length - 1) & 0xFFFF if length > 0 else addr

        line1 = f"[{b_type}] {b_orig}: Addr {addr} (#{addr:04X})  Len: {length} B"
        listing_lines.append((line1, b["color"]))

        src_snippet = f"  Src: {b['source'][:24]}" if b["source"] else ""
        line2 = f"  Range: #{addr:04X}..#{end_addr:04X}{src_snippet}"
        listing_lines.append((line2, (70, 80, 90)))

        summary_strings.append(f"{b_type} {b_orig}: Addr {addr} (#{addr:04X}) Len {length}B")

    listing_lines.append(("", (0, 0, 0)))
    listing_lines.append((f"Total: {len(blocks)} blocks, {total_bytes} bytes compiled code", (20, 20, 30)))
    listing_lines.append(("(Type LIST to return to program code)", (120, 120, 140)))

    return listing_lines, summary_strings


def get_code_listing_lines():
    lines, _ = get_code_listing_lines_with_summary()
    return lines


def handle_list_code_command():
    global listing_code_active, listing_vars_active, listing_monitor_active
    global listing_scroll_index, canvas_dirty

    listing_code_active = True
    listing_vars_active = False
    listing_monitor_active = False
    listing_scroll_index = 0
    if "cancel_listing_edit" in globals():
        cancel_listing_edit()

    lines, summary_strings = get_code_listing_lines_with_summary()

    canvas_print("--- COMPILED CODE LISTING ---")
    if not summary_strings:
        canvas_print("No compiled Forth or Z80 code in memory.")
    else:
        for s in summary_strings:
            canvas_print(s)
        total_len = 0
        for s in summary_strings:
            m_len = re.search(r'Len (\d+)B', s)
            if m_len:
                total_len += int(m_len.group(1))
        canvas_print(f"Total: {len(summary_strings)} blocks, {total_len} bytes")
    canvas_print("Output displayed in list area.")
    canvas_print("Type LIST to return to program.")

    canvas_dirty = True
    if "update_display" in globals():
        update_display()


