def tokenize_basic_line(line_str):
    """
    Tokenizes a BASIC code line into a list of tuples: (token_text, category_name, rgb_color).
    Preserves exact string reconstruction: "".join(t[0] for t in tokens) == line_str.
    """
    tokens = []
    i = 0
    n = len(line_str)

    # 1. Leading line number
    m_ln = re.match(r"^(\s*)(\d+)", line_str)
    if m_ln:
        if m_ln.group(1):
            tokens.append((m_ln.group(1), "DEFAULT", COMPLIANCE_COLORS["DEFAULT"]))
        tokens.append((m_ln.group(2), "LINENUM", COMPLIANCE_COLORS["LINENUM"]))
        i = m_ln.end()

    word_re = re.compile(r"^[A-Za-z][A-Za-z0-9_]*(\$|%)?")

    while i < n:
        # Whitespace
        if line_str[i].isspace():
            j = i
            while j < n and line_str[j].isspace():
                j += 1
            tokens.append((line_str[i:j], "DEFAULT", COMPLIANCE_COLORS["DEFAULT"]))
            i = j
            continue

        # String literal
        if line_str[i] == '"':
            j = i + 1
            while j < n:
                if line_str[j] == '"':
                    if j + 1 < n and line_str[j + 1] == '"':
                        j += 2
                        continue
                    else:
                        j += 1
                        break
                j += 1
            str_tok = line_str[i:j]
            tokens.append((str_tok, "STRING", COMPLIANCE_COLORS["STRING"]))
            i = j
            continue

        # REM comment - spans to end of line
        rem_m = re.match(r"^\bREM\b", line_str[i:], re.IGNORECASE)
        if rem_m:
            tokens.append((line_str[i:], "COMMENT", COMPLIANCE_COLORS["COMMENT"]))
            break

        # Multi-word keywords
        sub = line_str[i:]
        matched_mw = False
        for pattern, cat in MULTI_WORD_KEYWORDS:
            m = pattern.match(sub)
            if m:
                tok_str = m.group(0)
                tokens.append((tok_str, cat, COMPLIANCE_COLORS[cat]))
                i += len(tok_str)
                matched_mw = True
                break
        if matched_mw:
            continue

        # Spectranet % commands highlight
        if line_str[i] == '%':
            m_spec = re.match(r"^%[A-Za-z][A-Za-z0-9_]*", sub)
            if m_spec:
                tok_str = m_spec.group(0)
                tokens.append((tok_str, "PERIPH", COMPLIANCE_COLORS["PERIPH"]))
                i += len(tok_str)
                continue

        # NextZXOS / ESXDOS dot commands highlight (e.g. .ls, .cd, .pwd, .mkdir)
        if line_str[i] == '.':
            m_dot = re.match(r"^\.[A-Za-z][A-Za-z0-9_]*", sub)
            if m_dot:
                tok_str = m_dot.group(0)
                tokens.append((tok_str, "NEXT", COMPLIANCE_COLORS["NEXT"]))
                i += len(tok_str)
                continue

        # EXDOS colon commands highlight (e.g. :DIR, :CD, :ERASE)
        if line_str[i] == ':':
            m_col = re.match(r"^:[A-Za-z][A-Za-z0-9_]*", sub)
            if m_col:
                tok_str = m_col.group(0)
                tokens.append((tok_str, "NEXT", COMPLIANCE_COLORS["NEXT"]))
                i += len(tok_str)
                continue

        # Single-word keywords / identifiers
        m_word = word_re.match(sub)
        if m_word:
            tok_str = m_word.group(0)
            u_word = tok_str.upper()
            if u_word in SINGLE_KEYWORDS:
                cat = SINGLE_KEYWORDS[u_word]
                tokens.append((tok_str, cat, COMPLIANCE_COLORS[cat]))
            else:
                tokens.append((tok_str, "DEFAULT", COMPLIANCE_COLORS["DEFAULT"]))
            i += len(tok_str)
            continue

        # Single punctuation / operator / symbol
        tokens.append((line_str[i], "DEFAULT", COMPLIANCE_COLORS["DEFAULT"]))
        i += 1

    return tokens


def render_highlighted_code_line(surface, font_obj, full_text, start_x, row_y, max_x=None):
    """
    Renders a syntax-highlighted line of BASIC code across tokens horizontally.
    """
    toks = tokenize_basic_line(full_text)
    curr_x = start_x
    for tok_str, cat, color in toks:
        if not tok_str:
            continue
        t_surf = font_obj.render(tok_str, True, color)
        surface.blit(t_surf, (curr_x, row_y))
        curr_x += t_surf.get_width()
        if max_x is not None and curr_x > max_x:
            break


