class BASICJump(Exception):
    def __init__(self, target_line_idx, target_sub_idx=0, is_gosub=False):
        self.target_line_idx = target_line_idx
        self.target_sub_idx = target_sub_idx
        self.is_gosub = is_gosub


class BASICStop(Exception):
    pass


class BASICBreak(Exception):
    def __init__(self, msg="L BREAK into program"):
        self.msg = msg


def is_break_event(event):
    if event.type == pygame.KEYDOWN:
        if event.key == pygame.K_ESCAPE:
            return True
        mods = getattr(event, "mod", 0) | pygame.key.get_mods()
        if event.key == pygame.K_SPACE and (mods & pygame.KMOD_SHIFT):
            return True
        if event.key == pygame.K_c and (mods & pygame.KMOD_CTRL):
            return True
    return False


def to_float(val):
    if isinstance(val, (int, float)):
        return float(val)
    try:
        return float(val)
    except (ValueError, TypeError):
        raise Exception("Type mismatch")


def format_val(val):
    if isinstance(val, float) and val.is_integer():
        return str(int(val))
    return str(val)


class Channel:
    def __init__(self, name, write=None, readline=None, readchar=None, close=None):
        self.name = name
        self.write = write or (lambda s: None)
        self.readline = readline or (lambda: "")
        self.readchar = readchar or (lambda: "")
        self.close = close or (lambda: None)


class MDRChannelStream:
    def __init__(self, drive, name):
        self.drive = drive
        self.name = name
        existing = mdr_read_file_bytes(drive, name)
        self.buffer = bytearray(existing)
        self.read_ptr = 0

    def write(self, s):
        data = s.encode('latin-1', errors='ignore') if isinstance(s, str) else s
        self.buffer.extend(data)

    def readline(self):
        if self.read_ptr >= len(self.buffer):
            return ""
        end_idx = -1
        for i in range(self.read_ptr, len(self.buffer)):
            if self.buffer[i] in (10, 13):
                end_idx = i
                break
        if end_idx == -1:
            line = self.buffer[self.read_ptr:].decode('latin-1', errors='ignore')
            self.read_ptr = len(self.buffer)
            return line
        else:
            line = self.buffer[self.read_ptr:end_idx].decode('latin-1', errors='ignore')
            self.read_ptr = end_idx + 1
            if self.read_ptr < len(self.buffer) and self.buffer[self.read_ptr] in (10, 13):
                self.read_ptr += 1
            return line

    def readchar(self):
        if self.read_ptr >= len(self.buffer):
            return ""
        ch = chr(self.buffer[self.read_ptr])
        self.read_ptr += 1
        return ch

    def close(self):
        mdr_write_file_bytes(self.drive, self.name, bytes(self.buffer), file_type="PRINT")


class MGTChannelStream:
    def __init__(self, drive, name):
        self.drive = drive
        self.name = name
        disk = mgt_drives.get(drive)
        self.buffer = bytearray()
        if disk:
            try:
                ftype, file_bytes, meta = disk.load_file(name)
                self.buffer = bytearray(file_bytes)
            except Exception:
                self.buffer = bytearray()
        self.read_ptr = 0

    def write(self, s):
        data = s.encode('latin-1', errors='ignore') if isinstance(s, str) else s
        self.buffer.extend(data)

    def readline(self):
        if self.read_ptr >= len(self.buffer):
            return ""
        end_idx = -1
        for i in range(self.read_ptr, len(self.buffer)):
            if self.buffer[i] in (10, 13):
                end_idx = i
                break
        if end_idx == -1:
            line = self.buffer[self.read_ptr:].decode('latin-1', errors='ignore')
            self.read_ptr = len(self.buffer)
            return line
        else:
            line = self.buffer[self.read_ptr:end_idx].decode('latin-1', errors='ignore')
            self.read_ptr = end_idx + 1
            if self.read_ptr < len(self.buffer) and self.buffer[self.read_ptr] in (10, 13):
                self.read_ptr += 1
            return line

    def readchar(self):
        if self.read_ptr >= len(self.buffer):
            return ""
        ch = chr(self.buffer[self.read_ptr])
        self.read_ptr += 1
        return ch

    def close(self):
        disk = mgt_drives.get(self.drive)
        if disk and len(self.buffer) > 0:
            disk.save_file(self.name, MGTDisk.TYPE_CODE, bytes(self.buffer))


class SerialBinChannel:
    def __init__(self, filepath=None, baud=9600):
        self.filepath = filepath
        self.baud = baud
        self.file = open(filepath, "a+b") if filepath else None
        if self.file:
            self.file.seek(0)

    def write_byte(self, b):
        if isinstance(b, int):
            self.write(bytes([b]))
        else:
            self.write(b)

    def write(self, s):
        data = s.encode('latin-1', errors='ignore') if isinstance(s, str) else s
        if self.file:
            self.file.write(data)
            self.file.flush()
        if 'VT100Terminal' in globals():
            vt = getattr(VT100Terminal, 'active_instance', None)
            if vt and getattr(vt, 'active', False):
                try:
                    text = s if isinstance(s, str) else data.decode('latin-1', errors='replace')
                    vt.write(text)
                except Exception:
                    pass

    def readline(self):
        if not self.file:
            return ""
        line = self.file.readline()
        return line.decode('latin-1', errors='ignore').rstrip('\r\n')

    def readchar(self):
        if not self.file:
            return ""
        b = self.file.read(1)
        return b.decode('latin-1', errors='ignore') if b else ""

    def close(self):
        if self.file:
            self.file.close()


class SerialTextChannel:
    def __init__(self, filepath=None, baud=9600):
        self.filepath = filepath
        self.baud = baud
        self.file = open(filepath, "a+", encoding="utf-8") if filepath else None
        if self.file:
            self.file.seek(0)

    def write_char(self, ch):
        self.write(str(ch))

    def write(self, s):
        if self.file:
            self.file.write(s)
            self.file.flush()
        if 'VT100Terminal' in globals():
            vt = getattr(VT100Terminal, 'active_instance', None)
            if vt and getattr(vt, 'active', False):
                try:
                    vt.write(s)
                except Exception:
                    pass

    def readline(self):
        if not self.file:
            return ""
        return self.file.readline().rstrip('\r\n')

    def readchar(self):
        if not self.file:
            return ""
        return self.file.read(1)

    def close(self):
        if self.file:
            self.file.close()


class NetChannel:
    def __init__(self, filepath, station):
        self.filepath = filepath
        self.station = station
        self.file = open(filepath, "a+", encoding="utf-8")
        self.file.seek(0)

    def write(self, s):
        self.file.write(s)
        self.file.flush()

    def readline(self):
        return self.file.readline().rstrip('\r\n')

    def readchar(self):
        return self.file.read(1)

    def close(self):
        self.file.close()


class SocketNetworkChannel:
    def __init__(self, host, port, proto="tcp"):
        self.host = str(host).strip()
        self.port = int(port)
        self.proto = proto.lower()
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM if self.proto == "tcp" else socket.SOCK_DGRAM)
        self.sock.settimeout(5.0)
        if self.proto == "tcp":
            self.sock.connect((self.host, self.port))
        self.rx_buffer = bytearray()

    def write(self, s):
        data = s.encode('latin1', errors='ignore') if isinstance(s, str) else bytes(s)
        try:
            if self.proto == "tcp":
                self.sock.sendall(data)
            else:
                self.sock.sendto(data, (self.host, self.port))
        except Exception:
            pass

    def readline(self):
        line = bytearray()
        while True:
            ch = self.readchar()
            if not ch:
                break
            if ch in ('\r', '\n'):
                break
            line.append(ord(ch))
        return line.decode('latin1', errors='ignore')

    def readchar(self):
        if self.rx_buffer:
            return chr(self.rx_buffer.pop(0))
        try:
            self.sock.settimeout(0.05)
            data = self.sock.recv(512)
            if data:
                self.rx_buffer.extend(data)
                return chr(self.rx_buffer.pop(0))
        except Exception:
            pass
        return ""

    def close(self):
        try:
            self.sock.close()
        except Exception:
            pass


