def zx_inkey_stream(stream_idx):
    try:
        s_idx = int(stream_idx)
        if s_idx in (0, 1, 2):
            return get_next_inkey()
        if 0 <= s_idx < 16 and streams[s_idx] is not None:
            return streams[s_idx].readchar()
    except Exception:
        pass
    return ""


def get_zx_folder():
    docs = os.path.join(os.path.expanduser("~"), "Documents", "ZXBASIC")
    os.makedirs(docs, exist_ok=True)
    return docs


def calc_mdr_checksum(data_bytes):
    chk = 0
    for b in data_bytes:
        chk = (chk + b) % 255
    return chk


def get_mdr_path(drive_num=1):
    drive_num = max(1, min(8, int(drive_num)))
    filename = microdrive_attachments.get(drive_num, f"{drive_num}.mdr")
    folder = get_zx_folder()
    path = os.path.join(folder, filename)
    if not os.path.exists(path):
        create_blank_mdr(path, f"cart{drive_num}")
    return path


def create_blank_mdr(path, cart_name="blank"):
    mdr_data = bytearray(137923)
    name_padded = cart_name[:10].ljust(10, ' ').encode('latin-1', errors='ignore')
    
    for i in range(254):
        sector_num = 254 - i
        offset = i * 543
        
        mdr_data[offset + 0] = 1  # HDFLAG
        mdr_data[offset + 1] = sector_num  # HDNUMB
        mdr_data[offset + 2] = 0  # Unused
        mdr_data[offset + 3] = 0  # Unused
        mdr_data[offset + 4:offset + 14] = name_padded  # HDNAME
        mdr_data[offset + 14] = calc_mdr_checksum(mdr_data[offset:offset + 14])  # HDCHK
        
        rec_offset = offset + 15
        mdr_data[rec_offset + 0] = 0xFF  # RECFLG = 0xFF unallocated / free block
        mdr_data[rec_offset + 1] = 0  # RECNUM
        mdr_data[rec_offset + 2] = 0  # RECLEN LSB
        mdr_data[rec_offset + 3] = 0  # RECLEN MSB
        mdr_data[rec_offset + 4:rec_offset + 14] = b'          '  # RECNAM blank
        data_area_start = rec_offset + 15
        data_chk_offset = offset + 542
        mdr_data[data_chk_offset] = calc_mdr_checksum(mdr_data[data_area_start:data_chk_offset])

    mdr_data[137922] = 0  # Write protection flag (0 = writable)
    with open(path, "wb") as f:
        f.write(mdr_data)


def mdr_cat(drive_num, stream_idx=None):
    path = get_mdr_path(drive_num)
    lines_out = []
    lines_out.append(f"--- MDR MICRODRIVE {drive_num} CAT ---")
    try:
        with open(path, "rb") as f:
            data = f.read()
        
        found_files = {}
        file_types = {}
        cart_name = ""
        for i in range(254):
            offset = i * 543
            if i == 0:
                cart_name = data[offset + 4:offset + 14].decode('latin-1', errors='ignore').strip()
            
            rec_offset = offset + 15
            recflg = data[rec_offset + 0]
            reclen = data[rec_offset + 2] + (data[rec_offset + 3] * 256)
            rec_name = data[rec_offset + 4:rec_offset + 14]
            if recflg != 0xFF and reclen > 0 and rec_name.strip() != b'':
                fname = rec_name.decode('latin-1', errors='ignore').strip()
                if fname:
                    found_files[fname] = found_files.get(fname, 0) + 1
                    ftype = "PRINT" if (recflg & 2) != 0 else "PROG/DATA"
                    file_types[fname] = ftype
        
        lines_out.append(f"Cartridge ({os.path.basename(path)}): '{cart_name}'")
        if found_files:
            for f in sorted(found_files.keys()):
                sec_cnt = found_files[f]
                ftype = file_types[f]
                lines_out.append(f"  {f:<10}  {ftype:<9}  {sec_cnt} sector{'s' if sec_cnt != 1 else ''}")
        else:
            lines_out.append("  (Empty cartridge)")
        used_sectors = sum(found_files.values())
        free_sectors = max(0, 254 - used_sectors)
        lines_out.append(f"Free: {free_sectors}/254 sectors ({free_sectors * 512 // 1024}K)")
    except Exception as e:
        lines_out.append(f"Error reading MDR: {e}")
        
    for l in lines_out:
        if stream_idx is not None and 0 <= stream_idx < 16 and streams[stream_idx]:
            streams[stream_idx].write(l + "\n")
        else:
            canvas_print(l)


def mdr_erase_file(drive_num, fname, quiet=False):
    path = get_mdr_path(drive_num)
    try:
        with open(path, "rb") as f:
            data = bytearray(f.read())
        
        target_name = fname[:10].ljust(10, ' ').encode('latin-1', errors='ignore')
        erased = False
        for i in range(254):
            rec_offset = (i * 543) + 15
            rec_name = data[rec_offset + 4:rec_offset + 14]
            if rec_name == target_name:
                data[rec_offset + 0] = 0xFF  # Mark as free block
                data[rec_offset + 1] = 0
                data[rec_offset + 2] = 0
                data[rec_offset + 3] = 0
                data[rec_offset + 4:rec_offset + 14] = b'          '
                data[rec_offset + 14] = calc_mdr_checksum(data[rec_offset:rec_offset + 14])
                erased = True
        
        if erased:
            with open(path, "wb") as f:
                f.write(data)
            if not quiet:
                canvas_print(f"Erased '{fname}' from Microdrive {drive_num}")
        else:
            if not quiet:
                canvas_print(f"File not found on Microdrive {drive_num}: {fname}")
    except Exception as e:
        if not quiet:
            canvas_print(f"Erase error: {e}")


def mdr_read_file_bytes(drive_num, fname):
    path = get_mdr_path(drive_num)
    try:
        with open(path, "rb") as f:
            data = f.read()
        target_name = fname[:10].ljust(10, ' ').encode('latin-1', errors='ignore')
        sectors = []
        for i in range(254):
            rec_offset = (i * 543) + 15
            rec_name = data[rec_offset + 4:rec_offset + 14]
            if rec_name == target_name:
                recnum = data[rec_offset + 1]
                reclen = data[rec_offset + 2] + (data[rec_offset + 3] * 256)
                data_area_start = rec_offset + 15
                sectors.append((recnum, data[data_area_start : data_area_start + reclen]))
        sectors.sort(key=lambda s: s[0])
        payload = bytearray()
        for _, chunk in sectors:
            payload.extend(chunk)
        return bytes(payload)
    except Exception:
        return b""


def mdr_write_file_bytes(drive_num, fname, content_bytes, file_type=""):
    path = get_mdr_path(drive_num)
    try:
        mdr_erase_file(drive_num, fname, quiet=True)
        chunks = [content_bytes[i:i+512] for i in range(0, max(1, len(content_bytes)), 512)]
        with open(path, "rb") as f:
            data = bytearray(f.read())
        
        chunk_idx = 0
        target_name = fname[:10].ljust(10, ' ').encode('latin-1', errors='ignore')
        
        for i in range(254):
            sec_base = i * 543
            rec_offset = sec_base + 15
            recflg = data[rec_offset + 0]
            reclen = data[rec_offset + 2] + (data[rec_offset + 3] * 256)
            rec_name = data[rec_offset + 4:rec_offset + 14]
            
            is_free = (recflg == 0xFF or reclen == 0 or rec_name.strip() == b'')
            if is_free:
                if chunk_idx < len(chunks):
                    chunk = chunks[chunk_idx]
                    is_last = (chunk_idx == len(chunks) - 1)
                    
                    flag_val = (1 if is_last else 0)
                    if file_type == "PRINT":
                        flag_val |= 2
                    data[rec_offset + 0] = flag_val
                    data[rec_offset + 1] = chunk_idx
                    data[rec_offset + 2] = len(chunk) & 0xFF
                    data[rec_offset + 3] = (len(chunk) >> 8) & 0xFF
                    data[rec_offset + 4:rec_offset + 14] = target_name
                    data[rec_offset + 14] = calc_mdr_checksum(data[rec_offset:rec_offset + 14])
                    
                    data_area_start = rec_offset + 15
                    data[data_area_start : data_area_start + len(chunk)] = chunk
                    if len(chunk) < 512:
                        for p in range(len(chunk), 512):
                            data[data_area_start + p] = 0
                    
                    data[sec_base + 542] = calc_mdr_checksum(data[data_area_start:data_area_start + 512])
                    chunk_idx += 1
                else:
                    break
        
        with open(path, "wb") as f:
            f.write(data)
    except Exception as e:
        print(f"MDR Write error: {e}")


def mdr_save_program(drive_num, fname, prog_dict=None, autorun_line=None):
    if prog_dict is None:
        prog_dict = program
    lines_data = bytearray()
    if autorun_line is not None:
        lines_data.extend(f"AUTORUN={autorun_line}\r\n".encode('latin-1', errors='ignore'))
    for ln in sorted(prog_dict.keys()):
        line_str = f"{ln} {prog_dict[ln]}\r\n"
        lines_data.extend(line_str.encode('latin-1', errors='ignore'))
    mdr_write_file_bytes(drive_num, fname, bytes(lines_data))
    canvas_print(f"Saved '{fname}' to Microdrive {drive_num} ({microdrive_attachments.get(drive_num, f'{drive_num}.mdr')})")


def mdr_load_program(drive_num, fname):
    global program, autorun_enabled
    payload = mdr_read_file_bytes(drive_num, fname)
    if payload:
        program.clear()
        clean_bytes = bytes(b if 32 <= b < 127 or b in (10, 13, 9) else 32 for b in payload)
        decoded = clean_bytes.decode('latin-1', errors='ignore')
        count = 0
        autorun_ln = None
        for line_candidate in decoded.splitlines():
            line_candidate = line_candidate.strip()
            if not line_candidate:
                continue
            if line_candidate.startswith("AUTORUN="):
                try: autorun_ln = int(line_candidate.split("=")[1])
                except: pass
                continue
            match = re.match(r'^(\d+)\s+(.+)$', line_candidate)
            if match:
                ln = int(match.group(1))
                code_str = match.group(2).strip()
                if 0 <= ln <= 65535:
                    program[ln] = code_str
                    count += 1
        if not is_execution_mode():
            canvas_print(f"Loaded '{fname}' ({count} lines) from Microdrive {drive_num}")
        if autorun_enabled and autorun_ln is not None and autorun_ln in program:
            line_nums = sorted(program.keys())
            run_program(get_target_line_idx(autorun_ln, line_nums))
    else:
        canvas_print(f"File not found on Microdrive {drive_num}: {fname}")

def mdr_merge_program(drive_num, fname):
    global program
    payload = mdr_read_file_bytes(drive_num, fname)
    if payload:
        clean_bytes = bytes(b if 32 <= b < 127 or b in (10, 13, 9) else 32 for b in payload)
        decoded = clean_bytes.decode('latin-1', errors='ignore')
        count = 0
        for line_candidate in decoded.splitlines():
            line_candidate = line_candidate.strip()
            if not line_candidate: continue
            match = re.match(r'^(\d+)\s+(.+)$', line_candidate)
            if match:
                ln = int(match.group(1))
                code_str = match.group(2).strip()
                if 0 <= ln <= 65535:
                    program[ln] = code_str
                    count += 1
        canvas_print(f"Merged {count} lines from '{fname}' on Microdrive {drive_num}")
    else:
        canvas_print(f"File not found on Microdrive {drive_num}: {fname}")


def mdr_verify_program(drive_num, fname):
    payload = mdr_read_file_bytes(drive_num, fname)
    if not payload:
        canvas_print(f"File not found on Microdrive {drive_num}: {fname}")
        return False
    clean_bytes = bytes(b if 32 <= b < 127 or b in (10, 13, 9) else 32 for b in payload)
    decoded = clean_bytes.decode('latin-1', errors='ignore')
    mdr_lines = {}
    for line_candidate in decoded.splitlines():
        line_candidate = line_candidate.strip()
        if not line_candidate: continue
        match = re.match(r'^(\d+)\s+(.+)$', line_candidate)
        if match:
            ln = int(match.group(1))
            mdr_lines[ln] = match.group(2).strip()
    if mdr_lines == program:
        canvas_print("0 OK")
        return True
    else:
        canvas_print("Verify failed: program differences found")
        return False


def mdr_save_screen(drive_num, fname):
    block = bytearray(6912)
    for scr_y in range(192):
        third = scr_y // 64
        row_in_third = (scr_y % 64) // 8
        line_in_row = scr_y % 8
        y = 191 - scr_y
        for x in range(32):
            addr = (third * 2048) + (row_in_third * 32) + (line_in_row * 256) + x
            byte_val = 0
            for bit in range(8):
                px = x * 8 + bit
                if px < 256 and gfx_bits[px][y]:
                    byte_val |= (1 << (7 - bit))
            block[addr] = byte_val

    for r in range(24):
        for c in range(32):
            addr = 6144 + (r * 32) + c
            ink = attr_ink[r][c] & 7
            paper = (attr_paper[r][c] & 7) << 3
            bright = 64 if attr_bright[r][c] else 0
            flash = 128 if attr_flash[r][c] else 0
            block[addr] = ink | paper | bright | flash

    mdr_write_file_bytes(drive_num, fname, bytes(block))
    canvas_print(f"Saved SCREEN$ '{fname}' to Microdrive {drive_num}")


def mdr_load_screen(drive_num, fname):
    global gfx_bits, attr_ink, attr_paper, attr_bright, attr_flash, attr_used, canvas_dirty
    block = mdr_read_file_bytes(drive_num, fname)
    if len(block) < 6912:
        canvas_print(f"Error: Invalid or missing screen file on Microdrive {drive_num}: {fname}")
        return
    for scr_y in range(192):
        third = scr_y // 64
        row_in_third = (scr_y % 64) // 8
        line_in_row = scr_y % 8
        y = 191 - scr_y
        for x in range(32):
            addr = (third * 2048) + (row_in_third * 32) + (line_in_row * 256) + x
            if addr < len(block):
                byte_val = block[addr]
                for bit in range(8):
                    px = x * 8 + bit
                    if px < 256:
                        gfx_bits[px][y] = bool((byte_val >> (7 - bit)) & 1)

    for r in range(24):
        for c in range(32):
            addr = 6144 + (r * 32) + c
            if addr < len(block):
                attr_byte = block[addr]
                attr_ink[r][c] = attr_byte & 7
                attr_paper[r][c] = (attr_byte >> 3) & 7
                attr_bright[r][c] = bool(attr_byte & 64)
                attr_flash[r][c] = bool(attr_byte & 128)
                attr_used[r][c] = True
    canvas_dirty = True
    if not is_execution_mode():
        canvas_print(f"Loaded SCREEN$ '{fname}' from Microdrive {drive_num}")


def mdr_save_code(drive_num, fname, start, length):
    start = int(start) & 0xFFFF
    length = int(length) & 0xFFFF
    block = memory[start : start + length]
    hdr = bytearray()
    hdr.append(start & 0xFF)
    hdr.append((start >> 8) & 0xFF)
    hdr.append(length & 0xFF)
    hdr.append((length >> 8) & 0xFF)
    hdr.extend(block)
    mdr_write_file_bytes(drive_num, fname, bytes(hdr))
    canvas_print(f"Saved CODE '{fname}' ({start}, {length}) to Microdrive {drive_num}")


def mdr_load_code(drive_num, fname, dest_start=None):
    payload = mdr_read_file_bytes(drive_num, fname)
    if not payload:
        canvas_print(f"File not found on Microdrive {drive_num}: {fname}")
        return
    if len(payload) >= 4:
        orig_start = payload[0] + (payload[1] * 256)
        orig_len = payload[2] + (payload[3] * 256)
        code_bytes = payload[4: 4 + orig_len] if len(payload) >= 4 + orig_len else payload[4:]
    else:
        orig_start = 16384
        code_bytes = payload
    target_addr = int(dest_start) if dest_start is not None else orig_start
    target_addr &= 0xFFFF
    memory[target_addr : target_addr + len(code_bytes)] = code_bytes
    if not is_execution_mode():
        canvas_print(f"Loaded CODE '{fname}' at {target_addr} ({len(code_bytes)} bytes)")


