# ==============================================================================
# MGT DISCiPLE / Plus D (G+DOS) Floppy Disk & UKV FDI Emulation
# ==============================================================================

mgt_drives = {1: None, 2: None}
mgt_default_drive = 1
attached_tape_path = None
attached_load_source = None  # "FILE" | "ZXDB" | None — tracks how the last tape was loaded


class MGTDisk:
    """Emulates a 3.5-inch DS/DD 800KB floppy disk using the UKV FDI file format
    with the Miles Gordon Technology (DISCiPLE / +D / G+DOS) filesystem.
    """
    CYLINDERS = 80
    HEADS = 2
    TOTAL_TRACKS = CYLINDERS * HEADS  # 160
    SECTORS_PER_TRACK = 10
    SECTOR_SIZE = 512
    BYTES_PER_TRACK = SECTORS_PER_TRACK * SECTOR_SIZE  # 5120
    RAW_DISK_SIZE = TOTAL_TRACKS * BYTES_PER_TRACK     # 819,200 bytes (800 KB)
    DIR_TRACKS = 4                                    # Tracks 0..3
    DIR_SECTORS = DIR_TRACKS * SECTORS_PER_TRACK       # 40 sectors
    DIR_ENTRIES = DIR_SECTORS * 2                      # 80 entries (256 bytes each)
    DATA_START_TRACK = 4
    TOTAL_DATA_SECTORS = (TOTAL_TRACKS - DIR_TRACKS) * SECTORS_PER_TRACK  # 1560 sectors (780 KB)

    TYPE_BASIC = 1
    TYPE_NUM_ARRAY = 2
    TYPE_CHAR_ARRAY = 3
    TYPE_CODE = 4
    TYPE_48K_SNAP = 5
    TYPE_MDR = 6
    TYPE_SCREEN = 7
    TYPE_SPECIAL = 8
    TYPE_128K_SNAP = 9

    def __init__(self, filepath=None, disk_name="DISC 1"):
        self.filepath = filepath
        self.raw_data = bytearray(self.RAW_DISK_SIZE)
        self.write_protect = 0
        self.description = "MGT Plus D Floppy Disk"
        self.dirty = False

        if filepath and os.path.exists(filepath):
            try:
                self.load_fdi(filepath)
            except Exception:
                try:
                    with open(filepath, "rb") as f:
                        content = f.read()
                    if len(content) == self.RAW_DISK_SIZE or (filepath.lower().endswith(".dsk") and len(content) >= 512):
                        self.raw_data = bytearray(self.RAW_DISK_SIZE)
                        self.raw_data[:min(len(content), self.RAW_DISK_SIZE)] = content[:self.RAW_DISK_SIZE]
                    else:
                        raise
                except Exception:
                    raise
        else:
            self.format_disk(disk_name)
            if filepath:
                self.save_fdi(filepath)

    @classmethod
    def get_track_sector_offset(cls, track, sector):
        if not (0 <= track < cls.TOTAL_TRACKS):
            raise ValueError(f"Track {track} out of range (0..{cls.TOTAL_TRACKS - 1})")
        if not (1 <= sector <= cls.SECTORS_PER_TRACK):
            raise ValueError(f"Sector {sector} out of range (1..{cls.SECTORS_PER_TRACK})")
        return (track * cls.BYTES_PER_TRACK) + ((sector - 1) * cls.SECTOR_SIZE)

    def format_disk(self, disk_name="DISC 1"):
        self.raw_data = bytearray([0xE5] * self.RAW_DISK_SIZE)
        for i in range(self.DIR_ENTRIES):
            entry_offset = i * 256
            self.raw_data[entry_offset : entry_offset + 256] = bytes(256)
        clean_name = disk_name.strip()[:10].ljust(10)
        self.raw_data[210:220] = clean_name.encode('ascii', errors='replace')
        self.dirty = True

    def get_disk_name(self):
        name_bytes = bytes(self.raw_data[210:220])
        try:
            return name_bytes.decode('ascii').strip()
        except:
            return "DISC"

    def set_disk_name(self, name):
        clean_name = name.strip()[:10].ljust(10)
        self.raw_data[210:220] = clean_name.encode('ascii', errors='replace')
        self.dirty = True

    def save_fdi(self, filepath=None):
        target_path = filepath or self.filepath
        if not target_path:
            raise ValueError("No filepath specified for saving FDI")

        desc_bytes = (self.description.strip() + "\x00").encode('ascii', errors='replace')
        track_headers_len = self.TOTAL_TRACKS * 77
        track_headers_start = 14
        desc_offset = track_headers_start + track_headers_len
        data_offset = desc_offset + len(desc_bytes)

        if data_offset % 4 != 0:
            pad = 4 - (data_offset % 4)
            desc_bytes += b'\x00' * pad
            data_offset += pad

        out = bytearray()
        out.extend(b"FDI")
        out.append(self.write_protect & 0xFF)
        out.extend(struct.pack("<H", self.CYLINDERS))
        out.extend(struct.pack("<H", self.HEADS))
        out.extend(struct.pack("<H", desc_offset))
        out.extend(struct.pack("<H", data_offset))
        out.extend(struct.pack("<H", 0))

        for t in range(self.TOTAL_TRACKS):
            cyl = t // self.HEADS
            head = t % self.HEADS
            track_data_offset = t * self.BYTES_PER_TRACK
            out.extend(struct.pack("<I", track_data_offset))
            out.extend(struct.pack("<H", 0))
            out.append(self.SECTORS_PER_TRACK)
            for s in range(self.SECTORS_PER_TRACK):
                sec_num = s + 1
                sec_offset = s * self.SECTOR_SIZE
                out.append(cyl & 0xFF)
                out.append(head & 0xFF)
                out.append(2)
                out.append(sec_num & 0xFF)
                out.append(0x04)
                out.extend(struct.pack("<H", sec_offset))

        out.extend(desc_bytes)
        out.extend(self.raw_data)

        try:
            with open(target_path, "wb") as f:
                f.write(out)
            self.filepath = target_path
            self.dirty = False
        except (OSError, PermissionError):
            pass

    def load_fdi(self, filepath):
        with open(filepath, "rb") as f:
            content = f.read()

        if len(content) < 14 or content[:3] != b"FDI":
            raise ValueError(f"Not a valid FDI file: {filepath}")

        self.write_protect = content[3]
        cylinders = struct.unpack_from("<H", content, 4)[0]
        heads = struct.unpack_from("<H", content, 6)[0]
        desc_offset = struct.unpack_from("<H", content, 8)[0]
        data_offset = struct.unpack_from("<H", content, 10)[0]
        extra_len = struct.unpack_from("<H", content, 12)[0]

        if desc_offset < len(content):
            nul_idx = content.find(b"\x00", desc_offset)
            if nul_idx != -1:
                self.description = content[desc_offset:nul_idx].decode('ascii', errors='replace')

        track_headers_pos = 14 + extra_len
        self.raw_data = bytearray(self.RAW_DISK_SIZE)

        num_tracks = cylinders * heads
        for t in range(min(num_tracks, self.TOTAL_TRACKS)):
            if track_headers_pos + 7 > len(content):
                break
            track_off = struct.unpack_from("<I", content, track_headers_pos)[0]
            num_sec = content[track_headers_pos + 6]
            track_headers_pos += 7

            for s in range(num_sec):
                if track_headers_pos + 7 > len(content):
                    break
                cyl = content[track_headers_pos]
                hd = content[track_headers_pos + 1]
                sz_code = content[track_headers_pos + 2]
                sec_num = content[track_headers_pos + 3]
                flags = content[track_headers_pos + 4]
                sec_off = struct.unpack_from("<H", content, track_headers_pos + 5)[0]
                track_headers_pos += 7

                sec_size = 128 << sz_code
                abs_src = data_offset + track_off + sec_off
                if abs_src + sec_size <= len(content):
                    sec_bytes = content[abs_src : abs_src + sec_size]
                    if 1 <= sec_num <= self.SECTORS_PER_TRACK:
                        dest_off = self.get_track_sector_offset(t, sec_num)
                        copy_len = min(sec_size, self.SECTOR_SIZE)
                        self.raw_data[dest_off : dest_off + copy_len] = sec_bytes[:copy_len]

        self.filepath = filepath
        self.dirty = False

    def get_master_sector_map(self):
        used = [False] * self.TOTAL_DATA_SECTORS
        for i in range(1, self.DIR_ENTRIES):
            entry_off = i * 256
            ftype = self.raw_data[entry_off]
            if ftype != 0 and self.raw_data[entry_off + 1] != 0:
                bitmap = self.raw_data[entry_off + 15 : entry_off + 210]
                for byte_idx in range(195):
                    b = bitmap[byte_idx]
                    if b == 0:
                        continue
                    for bit_idx in range(8):
                        if (b >> bit_idx) & 1:
                            sec_idx = (byte_idx * 8) + bit_idx
                            if sec_idx < self.TOTAL_DATA_SECTORS:
                                used[sec_idx] = True
        return used

    def list_files(self):
        files = []
        for i in range(1, self.DIR_ENTRIES):
            off = i * 256
            ftype = self.raw_data[off]
            if ftype != 0 and self.raw_data[off + 1] != 0:
                raw_name = bytes(self.raw_data[off + 1 : off + 11])
                name = raw_name.decode('ascii', errors='replace').rstrip()
                sectors = (self.raw_data[off + 11] << 8) | self.raw_data[off + 12]
                start_track = self.raw_data[off + 13]
                start_sec = self.raw_data[off + 14]
                files.append({
                    "index": i,
                    "type": ftype,
                    "name": name,
                    "sectors": sectors,
                    "start_track": start_track,
                    "start_sec": start_sec,
                    "meta": bytes(self.raw_data[off + 210 : off + 232])
                })
        return files

    def find_file(self, filename):
        clean_name = filename.strip()[:10].upper()
        for f in self.list_files():
            if f["name"].upper() == clean_name:
                return f
        return None

    def save_file(self, filename, file_type, data_bytes, autorun_line=None, start_addr=None, data_length=None):
        if self.write_protect:
            raise PermissionError("Disk is write-protected")

        clean_name = filename.strip()[:10].ljust(10)
        existing = self.find_file(clean_name.rstrip())
        if existing:
            self.erase_file(existing["name"])

        slot = None
        for i in range(1, self.DIR_ENTRIES):
            off = i * 256
            if self.raw_data[off] == 0 or self.raw_data[off + 1] == 0:
                slot = i
                break
        if slot is None:
            raise Exception("Directory full (maximum 79 files)")

        file_len = len(data_bytes)
        sectors_needed = max(1, (file_len + self.SECTOR_SIZE - 1) // self.SECTOR_SIZE)
        if sectors_needed > self.TOTAL_DATA_SECTORS:
            raise Exception("File too large for disk")

        master_map = self.get_master_sector_map()
        allocated_indices = []
        for idx in range(self.TOTAL_DATA_SECTORS):
            if not master_map[idx]:
                allocated_indices.append(idx)
                if len(allocated_indices) == sectors_needed:
                    break

        if len(allocated_indices) < sectors_needed:
            raise Exception(f"Disk full: needed {sectors_needed} sectors, but only {len(allocated_indices)} free")

        data_pos = 0
        bitmap = bytearray(195)
        for sec_idx in allocated_indices:
            trk = self.DATA_START_TRACK + (sec_idx // self.SECTORS_PER_TRACK)
            sec = 1 + (sec_idx % self.SECTORS_PER_TRACK)
            sec_off = self.get_track_sector_offset(trk, sec)

            chunk = data_bytes[data_pos : data_pos + self.SECTOR_SIZE]
            data_pos += len(chunk)
            if len(chunk) < self.SECTOR_SIZE:
                chunk = chunk + bytes(self.SECTOR_SIZE - len(chunk))
            self.raw_data[sec_off : sec_off + self.SECTOR_SIZE] = chunk

            byte_i = sec_idx // 8
            bit_i = sec_idx % 8
            bitmap[byte_i] |= (1 << bit_i)

        first_idx = allocated_indices[0]
        start_trk = self.DATA_START_TRACK + (first_idx // self.SECTORS_PER_TRACK)
        start_sec = 1 + (first_idx % self.SECTORS_PER_TRACK)

        entry_off = slot * 256
        entry = bytearray(256)
        entry[0] = file_type & 0xFF
        entry[1:11] = clean_name.encode('ascii', errors='replace')
        entry[11] = (sectors_needed >> 8) & 0xFF
        entry[12] = sectors_needed & 0xFF
        entry[13] = start_trk & 0xFF
        entry[14] = start_sec & 0xFF
        entry[15:210] = bitmap

        if file_type == self.TYPE_BASIC:
            line_val = 32768 if autorun_line is None else autorun_line
            entry[221] = (line_val >> 8) & 0xFF
            entry[222] = line_val & 0xFF
            entry[223] = (file_len >> 8) & 0xFF
            entry[224] = file_len & 0xFF
        elif file_type == self.TYPE_CODE:
            addr = 16384 if start_addr is None else start_addr
            l_val = file_len if data_length is None else data_length
            entry[221] = (addr >> 8) & 0xFF
            entry[222] = addr & 0xFF
            entry[223] = (l_val >> 8) & 0xFF
            entry[224] = l_val & 0xFF
        elif file_type == self.TYPE_SCREEN:
            entry[221] = 0
            entry[222] = 0x40
            entry[223] = 0x00
            entry[224] = 0x1B
            entry[225] = 0x00

        self.raw_data[entry_off : entry_off + 256] = entry
        self.dirty = True

        if self.filepath:
            self.save_fdi()

    def load_file(self, filename):
        entry = self.find_file(filename)
        if not entry:
            raise FileNotFoundError(f"File not found on disk: '{filename}'")

        off = entry["index"] * 256
        ftype = entry["type"]
        sectors_count = entry["sectors"]
        bitmap = self.raw_data[off + 15 : off + 210]

        if ftype == self.TYPE_BASIC:
            file_len = (self.raw_data[off + 223] << 8) | self.raw_data[off + 224]
            autorun = (self.raw_data[off + 221] << 8) | self.raw_data[off + 222]
            autorun_line = autorun if autorun < 32768 else None
            meta = {"autorun_line": autorun_line, "length": file_len}
        elif ftype == self.TYPE_CODE:
            start_addr = (self.raw_data[off + 221] << 8) | self.raw_data[off + 222]
            file_len = (self.raw_data[off + 223] << 8) | self.raw_data[off + 224]
            meta = {"start_addr": start_addr, "length": file_len}
        elif ftype == self.TYPE_SCREEN:
            file_len = 6912
            meta = {"start_addr": 16384, "length": 6912}
        else:
            file_len = sectors_count * self.SECTOR_SIZE
            meta = {"length": file_len}

        if file_len <= 0 or file_len > sectors_count * self.SECTOR_SIZE:
            file_len = sectors_count * self.SECTOR_SIZE

        file_bytes = bytearray()
        collected_sectors = 0
        for byte_idx in range(195):
            b = bitmap[byte_idx]
            if b == 0:
                continue
            for bit_idx in range(8):
                if (b >> bit_idx) & 1:
                    sec_idx = (byte_idx * 8) + bit_idx
                    if sec_idx < self.TOTAL_DATA_SECTORS:
                        trk = self.DATA_START_TRACK + (sec_idx // self.SECTORS_PER_TRACK)
                        sec = 1 + (sec_idx % self.SECTORS_PER_TRACK)
                        sec_off = self.get_track_sector_offset(trk, sec)
                        file_bytes.extend(self.raw_data[sec_off : sec_off + self.SECTOR_SIZE])
                        collected_sectors += 1
                        if collected_sectors >= sectors_count:
                            break
            if collected_sectors >= sectors_count:
                break

        return ftype, bytes(file_bytes[:file_len]), meta

    def erase_file(self, filename):
        if self.write_protect:
            raise PermissionError("Disk is write-protected")

        entry = self.find_file(filename)
        if not entry:
            raise FileNotFoundError(f"File not found on disk: '{filename}'")

        off = entry["index"] * 256
        self.raw_data[off : off + 256] = bytes(256)
        self.dirty = True

        if self.filepath:
            self.save_fdi()

    def rename_file(self, old_name, new_name):
        if self.write_protect:
            raise PermissionError("Disk is write-protected")

        entry = self.find_file(old_name)
        if not entry:
            raise FileNotFoundError(f"File not found on disk: '{old_name}'")

        clean_new = new_name.strip()[:10].ljust(10)
        existing = self.find_file(clean_new.rstrip())
        if existing and existing["index"] != entry["index"]:
            raise FileExistsError(f"File already exists on disk: '{new_name}'")

        off = entry["index"] * 256
        self.raw_data[off + 1 : off + 11] = clean_new.encode('ascii', errors='replace')
        self.dirty = True

        if self.filepath:
            self.save_fdi()

    def get_free_kb(self):
        used = self.get_master_sector_map()
        free_sectors = used.count(False)
        return free_sectors * self.SECTOR_SIZE // 1024


