class CPMDiskImage:
    """
    Unified Multi-Format CP/M Disk Image Engine.
    Supports .IMG (raw sector), .DSK (CPCEMU / Extended DSK), and .IMD (ImageDisk)
    with automatic geometry detection across Sinclair +3 (180K/720K), Amstrad CPC/PCW,
    IBM 3740 standard 8" SSSD, Kaypro II/4, Osborne 1, Apple II SoftCard, Commodore 128,
    and Generic PC CP/M disk images for both reading and writing.
    """
    def __init__(self, filename=None, tracks=40, sides=1, sectors=9, sec_size=512,
                 reserved_tracks=1, block_size=1024, dir_entries=64, skew=None):
        self.filename = filename
        self.num_tracks = tracks
        self.num_sides = sides
        self.sectors_per_track = sectors
        self.sector_size = sec_size
        self.reserved_tracks = reserved_tracks
        self.block_size = block_size
        self.dir_entries = dir_entries
        self.skew_table = skew
        self.format_type = "dsk"
        self.format_name = "Sinclair +3 / PCW 180K (CF2)"
        self.comment = "BasinPy CP/M Disk"

        self.sectors_per_block = max(1, self.block_size // self.sector_size)
        tot_bytes = self.num_tracks * self.num_sides * self.sectors_per_track * self.sector_size
        res_bytes = self.reserved_tracks * self.sectors_per_track * self.sector_size
        self.total_blocks = max(1, (tot_bytes - res_bytes) // self.block_size)
        self.is_16bit_blocks = self.total_blocks > 256
        self.dir_blocks = max(1, (self.dir_entries * 32 + self.block_size - 1) // self.block_size)

        # Initialize formatted disk tracks filled with 0xE5
        self.tracks_raw = []
        for _ in range(self.num_tracks * self.num_sides):
            self.tracks_raw.append(bytearray([0xE5] * (self.sectors_per_track * self.sector_size)))

    @staticmethod
    def score_directory(data, offset, num_entries=64):
        if offset + num_entries * 32 > len(data):
            return -1
        score = 0
        non_empty = 0
        for i in range(num_entries):
            entry = data[offset + i * 32 : offset + (i + 1) * 32]
            u = entry[0]
            if u == 0xE5:
                if all(b == 0xE5 for b in entry[1:16]):
                    score += 1
            elif 0 <= u <= 15:
                name = entry[1:9]
                ext = entry[9:12]
                if all(32 <= (b & 0x7F) <= 126 for b in name) and all(32 <= (b & 0x7F) <= 126 for b in ext):
                    if entry[12] <= 31 and entry[15] <= 128:
                        score += 10
                        non_empty += 1
        return score + (non_empty * 50)

    @classmethod
    def auto_detect_geometry(cls, data):
        size = len(data)
        candidates = [f for f in CPM_STANDARD_FORMATS.values() if f['total_size'] == size]
        if len(candidates) == 1:
            return candidates[0]
        elif len(candidates) > 1:
            best_score = -1
            best_cand = candidates[0]
            for cand in candidates:
                track_bytes = cand['sectors'] * cand['sec_size']
                dir_off = cand['reserved_tracks'] * track_bytes
                s = cls.score_directory(data, dir_off, cand['dir_entries'])
                if s > best_score:
                    best_score = s
                    best_cand = cand
            return best_cand

        # Generic search across standard track/sector candidates
        best_score = -1
        best_fmt = CPM_STANDARD_FORMATS['plus3_180k']
        for cand in CPM_STANDARD_FORMATS.values():
            track_bytes = cand['sectors'] * cand['sec_size']
            for res_t in (0, 1, 2, 3, 4):
                dir_off = res_t * track_bytes
                s = cls.score_directory(data, dir_off, cand['dir_entries'])
                if s > best_score:
                    best_score = s
                    best_fmt = dict(cand)
                    best_fmt['reserved_tracks'] = res_t
        return best_fmt

    @classmethod
    def from_data(cls, data, filepath=None):
        inst = cls(filepath)
        if data.startswith(b"IMD "):
            inst.format_type = "imd"
            inst._parse_imd(data)
        elif data.startswith(b"MV - CPC") or data.startswith(b"EXTENDED CPC DSK"):
            inst.format_type = "dsk"
            inst._parse_dsk(data)
        else:
            inst.format_type = "img"
            inst._parse_img(data)
        return inst

    @classmethod
    def load(cls, filepath):
        ext = os.path.splitext(filepath)[1].lower()
        with open(filepath, "rb") as f:
            data = f.read()
        inst = cls.from_data(data, filepath)
        if ext in (".imd", ".dsk", ".img", ".cpm", ".raw", ".flp"):
            inst.format_type = ext[1:]
        return inst

    def _apply_geometry(self, geo):
        self.format_name = geo.get('name', 'Custom CP/M')
        self.num_tracks = geo['tracks']
        self.num_sides = geo['sides']
        self.sectors_per_track = geo['sectors']
        self.sector_size = geo['sec_size']
        self.reserved_tracks = geo['reserved_tracks']
        self.block_size = geo['block_size']
        self.dir_entries = geo['dir_entries']
        self.skew_table = geo.get('skew')
        self.sectors_per_block = max(1, self.block_size // self.sector_size)
        tot_bytes = self.num_tracks * self.num_sides * self.sectors_per_track * self.sector_size
        res_bytes = self.reserved_tracks * self.sectors_per_track * self.sector_size
        self.total_blocks = max(1, (tot_bytes - res_bytes) // self.block_size)
        self.is_16bit_blocks = self.total_blocks > 256
        self.dir_blocks = max(1, (self.dir_entries * 32 + self.block_size - 1) // self.block_size)

    def _parse_img(self, data):
        geo = self.auto_detect_geometry(data)
        self._apply_geometry(geo)
        track_size = self.sectors_per_track * self.sector_size
        total_tracks = self.num_tracks * self.num_sides
        self.tracks_raw = []
        for t in range(total_tracks):
            chunk = data[t * track_size : (t + 1) * track_size]
            if len(chunk) < track_size:
                chunk = chunk + bytearray([0xE5] * (track_size - len(chunk)))
            self.tracks_raw.append(bytearray(chunk))

    def _parse_dsk(self, data):
        is_extended = data.startswith(b"EXTENDED CPC DSK")
        if data.startswith(b"MV - CPC") or is_extended:
            self.num_tracks = data[0x30]
            self.num_sides = data[0x31]
            self.tracks_raw = []
            offset = 256
            for t in range(self.num_tracks * self.num_sides):
                if offset >= len(data): break
                if not data[offset:offset+12].startswith(b"Track-Info"): break
                t_hdr = data[offset:offset+256]
                sec_count = t_hdr[0x15]
                sec_size_code = t_hdr[0x14]
                sec_len_std = 128 << sec_size_code
                self.sectors_per_track = sec_count
                self.sector_size = sec_len_std
                sec_data_start = offset + 256
                track_buf = bytearray()
                for s in range(sec_count):
                    s_info_off = 0x18 + s * 8
                    if is_extended:
                        sec_len = struct.unpack_from("<H", t_hdr, s_info_off + 6)[0]
                    else:
                        sec_len = sec_len_std
                    track_buf.extend(data[sec_data_start : sec_data_start + sec_len])
                    sec_data_start += sec_len
                self.tracks_raw.append(track_buf)
                if is_extended:
                    track_alloc = data[0x34 + t] * 256
                    offset += track_alloc if track_alloc > 0 else (sec_data_start - offset)
                else:
                    track_len = struct.unpack_from("<H", data, 0x32)[0] if len(data) >= 0x34 else (256 + 9 * 512)
                    offset += track_len if track_len > 0 else (256 + 9 * 512)

            raw_bytes = b"".join(self.tracks_raw)
            geo = self.auto_detect_geometry(raw_bytes)
            self.reserved_tracks = geo.get('reserved_tracks', 1)
            self.block_size = geo.get('block_size', 1024 if len(raw_bytes) <= 200000 else 2048)
            self.dir_entries = geo.get('dir_entries', 64 if len(raw_bytes) <= 200000 else 256)
            self.skew_table = geo.get('skew')
            self.format_name = geo.get('name', f"CPC DSK {self.num_tracks}T {self.num_sides}S")
            self.sectors_per_block = max(1, self.block_size // self.sector_size)
            tot_bytes = len(raw_bytes)
            res_bytes = self.reserved_tracks * self.sectors_per_track * self.sector_size
            self.total_blocks = max(1, (tot_bytes - res_bytes) // self.block_size)
            self.is_16bit_blocks = self.total_blocks > 256
            self.dir_blocks = max(1, (self.dir_entries * 32 + self.block_size - 1) // self.block_size)
        else:
            self._parse_img(data)

    def _parse_imd(self, data):
        eof_idx = data.find(b"\x1A")
        if eof_idx != -1:
            try:
                self.comment = data[:eof_idx].decode("ascii", errors="replace")
            except Exception:
                self.comment = ""
            pos = eof_idx + 1
        else:
            pos = 0

        self.tracks_raw = []
        last_sec_count = 9
        last_sec_size = 512
        while pos < len(data):
            if pos + 5 > len(data): break
            mode = data[pos]
            cyl = data[pos+1]
            head = data[pos+2]
            n_sec = data[pos+3]
            sec_size_code = data[pos+4]
            sec_size = 128 << sec_size_code
            pos += 5

            if pos + n_sec > len(data): break
            sec_map = list(data[pos : pos + n_sec])
            pos += n_sec

            if (head & 0x40): pos += n_sec
            if (head & 0x80): pos += n_sec

            track_sectors = {}
            for s_idx in range(n_sec):
                if pos >= len(data): break
                sec_type = data[pos]
                pos += 1
                if sec_type == 0:
                    sdata = bytearray([0xE5] * sec_size)
                elif sec_type in (1, 3, 5, 7):
                    sdata = bytearray(data[pos : pos + sec_size])
                    pos += sec_size
                elif sec_type in (2, 4, 6, 8):
                    fill_byte = data[pos]
                    pos += 1
                    sdata = bytearray([fill_byte] * sec_size)
                else:
                    sdata = bytearray([0xE5] * sec_size)

                sec_id = sec_map[s_idx] if s_idx < len(sec_map) else (s_idx + 1)
                track_sectors[sec_id] = sdata

            sorted_sec_ids = sorted(track_sectors.keys())
            track_buf = bytearray()
            for sid in sorted_sec_ids:
                track_buf.extend(track_sectors[sid])

            self.tracks_raw.append(track_buf)
            last_sec_count = n_sec
            last_sec_size = sec_size

        self.num_tracks = len(self.tracks_raw)
        self.num_sides = 1
        self.sectors_per_track = last_sec_count
        self.sector_size = last_sec_size
        raw_bytes = b"".join(self.tracks_raw)
        geo = self.auto_detect_geometry(raw_bytes)
        self.reserved_tracks = geo.get('reserved_tracks', 1)
        self.block_size = geo.get('block_size', 1024 if len(raw_bytes) <= 200000 else 2048)
        self.dir_entries = geo.get('dir_entries', 64 if len(raw_bytes) <= 200000 else 256)
        self.skew_table = geo.get('skew')
        self.format_name = geo.get('name', f"IMD {self.num_tracks}T")
        self.sectors_per_block = max(1, self.block_size // self.sector_size)
        tot_bytes = len(raw_bytes)
        res_bytes = self.reserved_tracks * self.sectors_per_track * self.sector_size
        self.total_blocks = max(1, (tot_bytes - res_bytes) // self.block_size)
        self.is_16bit_blocks = self.total_blocks > 256
        self.dir_blocks = max(1, (self.dir_entries * 32 + self.block_size - 1) // self.block_size)

    def _read_block(self, blk):
        sec_base = self.reserved_tracks * self.sectors_per_track + blk * self.sectors_per_block
        buf = bytearray()
        for s_idx in range(self.sectors_per_block):
            tot_sec = sec_base + s_idx
            t = tot_sec // self.sectors_per_track
            s = tot_sec % self.sectors_per_track
            if self.skew_table and s < len(self.skew_table):
                s = self.skew_table[s]
            if t < len(self.tracks_raw):
                off = s * self.sector_size
                buf.extend(self.tracks_raw[t][off : off + self.sector_size])
        return buf

    def _write_block(self, blk, chunk):
        sec_base = self.reserved_tracks * self.sectors_per_track + blk * self.sectors_per_block
        pos = 0
        for s_idx in range(self.sectors_per_block):
            tot_sec = sec_base + s_idx
            t = tot_sec // self.sectors_per_track
            s = tot_sec % self.sectors_per_track
            if self.skew_table and s < len(self.skew_table):
                s = self.skew_table[s]
            if t < len(self.tracks_raw):
                off = s * self.sector_size
                s_data = chunk[pos : pos + self.sector_size]
                self.tracks_raw[t][off : off + len(s_data)] = s_data
            pos += self.sector_size

    def get_files(self):
        if not self.tracks_raw:
            return {}

        dir_bytes = self.dir_entries * 32
        dir_raw = bytearray()
        for b in range(self.dir_blocks):
            dir_raw.extend(self._read_block(b))
        dir_raw = dir_raw[:dir_bytes]

        extents = {}
        for i in range(0, len(dir_raw), 32):
            entry = dir_raw[i : i + 32]
            user = entry[0]
            if user == 0xE5 or user > 15:
                continue
            name = "".join(chr(b & 0x7F) for b in entry[1:9]).strip()
            ext = "".join(chr(b & 0x7F) for b in entry[9:12]).strip()
            fname = f"{name}.{ext}" if ext else name
            ex = entry[12]
            s2 = entry[14]
            extent_num = ex + (s2 * 32)
            rc = entry[15]
            if not self.is_16bit_blocks:
                block_nums = [b for b in entry[16:32] if b != 0]
            else:
                block_nums = [(entry[16 + j*2] | (entry[17 + j*2] << 8)) for j in range(8) if (entry[16 + j*2] | (entry[17 + j*2] << 8)) != 0]
            if fname not in extents:
                extents[fname] = []
            extents[fname].append((extent_num, rc, block_nums))

        files = {}
        for fname, ext_list in extents.items():
            ext_list.sort(key=lambda x: x[0])
            file_bytes = bytearray()
            for ext_num, rc, blk_nums in ext_list:
                extent_data = bytearray()
                for blk in blk_nums:
                    extent_data.extend(self._read_block(blk))
                total_rc_bytes = rc * 128
                file_bytes.extend(extent_data[:total_rc_bytes])
            files[fname] = bytes(file_bytes)

        return files

    def _get_used_blocks(self):
        used = set()
        if not self.tracks_raw:
            return used
        dir_bytes = self.dir_entries * 32
        dir_raw = bytearray()
        for b in range(self.dir_blocks):
            dir_raw.extend(self._read_block(b))
        dir_raw = dir_raw[:dir_bytes]

        for i in range(0, len(dir_raw), 32):
            entry = dir_raw[i : i + 32]
            if entry[0] == 0xE5 or entry[0] > 15:
                continue
            if not self.is_16bit_blocks:
                for b in entry[16:32]:
                    if b != 0: used.add(b)
            else:
                for j in range(8):
                    blk = entry[16 + j*2] | (entry[17 + j*2] << 8)
                    if blk != 0: used.add(blk)
        return used

    def put_file(self, filename, data, user=0):
        if not self.tracks_raw:
            return False

        self.delete_file(filename, user)

        fn_parts = filename.upper().strip().split('.')
        base = (fn_parts[0] + "        ")[:8]
        ext = ((fn_parts[1] if len(fn_parts) > 1 else "") + "   ")[:3]

        used_blocks = self._get_used_blocks()
        dir_bytes = self.dir_entries * 32
        dir_raw = bytearray()
        for b in range(self.dir_blocks):
            dir_raw.extend(self._read_block(b))
        dir_raw = dir_raw[:dir_bytes]

        free_dir_indices = [i for i in range(0, dir_bytes, 32) if dir_raw[i] == 0xE5]

        file_len = len(data)
        block_size = self.block_size
        total_blocks = (file_len + block_size - 1) // block_size if file_len > 0 else 0
        blocks_allocated = []

        curr_blk = self.dir_blocks
        while len(blocks_allocated) < total_blocks and curr_blk < self.total_blocks:
            if curr_blk not in used_blocks:
                blocks_allocated.append(curr_blk)
            curr_blk += 1

        if len(blocks_allocated) < total_blocks:
            raise Exception("Disk full: insufficient allocation blocks")

        data_pos = 0
        for blk in blocks_allocated:
            chunk = bytearray(data[data_pos : data_pos + block_size])
            data_pos += block_size
            if len(chunk) < block_size:
                chunk.extend(bytearray([0x1A] * (block_size - len(chunk))))
            self._write_block(blk, chunk)

        blocks_per_extent = 8 if self.is_16bit_blocks else 16
        extents_needed = max(1, (total_blocks + blocks_per_extent - 1) // blocks_per_extent)
        if len(free_dir_indices) < extents_needed:
            raise Exception("Directory full: no free directory entries")

        blk_idx = 0
        bytes_left = file_len
        for ext_num in range(extents_needed):
            dir_pos = free_dir_indices[ext_num]
            ext_blocks = blocks_allocated[blk_idx : blk_idx + blocks_per_extent]
            blk_idx += blocks_per_extent

            ext_bytes = min(bytes_left, blocks_per_extent * block_size)
            bytes_left -= ext_bytes
            rc = (ext_bytes + 127) // 128

            entry = bytearray(32)
            entry[0] = user
            entry[1:9] = base.encode('ascii', errors='replace')
            entry[9:12] = ext.encode('ascii', errors='replace')
            entry[12] = ext_num & 0x1F
            entry[13] = 0
            entry[14] = (ext_num >> 5) & 0x0F
            entry[15] = min(128, rc)
            if not self.is_16bit_blocks:
                for b_i, blk in enumerate(ext_blocks):
                    entry[16 + b_i] = blk
            else:
                for b_i, blk in enumerate(ext_blocks):
                    entry[16 + b_i*2] = blk & 0xFF
                    entry[17 + b_i*2] = (blk >> 8) & 0xFF

            d_blk = dir_pos // self.block_size
            d_off = dir_pos % self.block_size
            blk_chunk = self._read_block(d_blk)
            blk_chunk[d_off : d_off + 32] = entry
            self._write_block(d_blk, blk_chunk)

        return True

    def delete_file(self, filename, user=None):
        if not self.tracks_raw:
            return False
        fn_parts = filename.upper().strip().split('.')
        base = (fn_parts[0] + "        ")[:8]
        ext = ((fn_parts[1] if len(fn_parts) > 1 else "") + "   ")[:3]
        deleted_any = False

        dir_bytes = self.dir_entries * 32
        for dir_pos in range(0, dir_bytes, 32):
            d_blk = dir_pos // self.block_size
            d_off = dir_pos % self.block_size
            blk_chunk = self._read_block(d_blk)
            if len(blk_chunk) < d_off + 32:
                continue
            entry = blk_chunk[d_off : d_off + 32]
            if len(entry) < 32 or entry[0] == 0xE5 or entry[0] > 15:
                continue
            if user is not None and entry[0] != user:
                continue
            e_base = "".join(chr(b & 0x7F) for b in entry[1:9])
            e_ext = "".join(chr(b & 0x7F) for b in entry[9:12])
            if e_base == base and e_ext == ext:
                blk_chunk[d_off] = 0xE5
                self._write_block(d_blk, blk_chunk)
                deleted_any = True

        return deleted_any

    def save(self, filepath=None):
        out_path = filepath if filepath else self.filename
        if not out_path:
            raise ValueError("No output path specified for disk image")

        ext = os.path.splitext(out_path)[1].lower()
        if ext == ".imd" or self.format_type == "imd":
            data = self._serialize_imd()
        elif ext == ".dsk" or self.format_type == "dsk":
            data = self._serialize_dsk()
        else:
            data = self._serialize_img()

        with open(out_path, "wb") as f:
            f.write(data)

    def to_bytes(self):
        fmt = getattr(self, 'format_type', 'dsk').lower()
        if fmt == "imd":
            return self._serialize_imd()
        elif fmt == "dsk":
            return self._serialize_dsk()
        else:
            return self._serialize_img()

    def get_file_data(self, filename, user=None):
        files = self.get_files()
        fn = filename.upper().strip()
        if fn in files:
            val = files[fn]
            if isinstance(val, dict):
                return val.get('data', b'')
            return val
        return None


    def _serialize_img(self):
        return bytes(b"".join(self.tracks_raw))

    def _serialize_dsk(self):
        out = bytearray()
        hdr = bytearray(256)
        hdr[:34] = b"MV - CPCEMU Disk-File\r\nDisk-Info\r\n"
        hdr[0x22:0x30] = b"BasinPy       "
        hdr[0x30] = self.num_tracks
        hdr[0x31] = self.num_sides
        struct.pack_into("<H", hdr, 0x32, 256 + self.sectors_per_track * self.sector_size)
        out.extend(hdr)

        sec_size_code = 0
        temp_s = self.sector_size
        while temp_s > 128:
            temp_s >>= 1
            sec_size_code += 1

        for t in range(self.num_tracks * self.num_sides):
            t_hdr = bytearray(256)
            t_hdr[:12] = b"Track-Info\r\n"
            t_hdr[0x10] = t // self.num_sides
            t_hdr[0x11] = t % self.num_sides
            t_hdr[0x14] = sec_size_code
            t_hdr[0x15] = self.sectors_per_track
            t_hdr[0x16] = 0x4E
            t_hdr[0x17] = 0xE5
            for s in range(self.sectors_per_track):
                s_off = 0x18 + s * 8
                t_hdr[s_off] = t // self.num_sides
                t_hdr[s_off + 1] = t % self.num_sides
                t_hdr[s_off + 2] = s + 1
                t_hdr[s_off + 3] = sec_size_code
                t_hdr[s_off + 4] = 0
                t_hdr[s_off + 5] = 0
                struct.pack_into("<H", t_hdr, s_off + 6, self.sector_size)
            out.extend(t_hdr)

            t_data = self.tracks_raw[t] if t < len(self.tracks_raw) else bytearray([0xE5] * (self.sectors_per_track * self.sector_size))
            out.extend(t_data[: self.sectors_per_track * self.sector_size])

        return bytes(out)

    def _serialize_imd(self):
        out = bytearray()
        header_text = "IMD 1.18: BasinPy CP/M Disk\r\n\x1A"
        out.extend(header_text.encode('ascii'))

        sec_size_code = 0
        temp_s = self.sector_size
        while temp_s > 128:
            temp_s >>= 1
            sec_size_code += 1

        for t in range(self.num_tracks * self.num_sides):
            t_data = self.tracks_raw[t] if t < len(self.tracks_raw) else bytearray([0xE5] * (self.sectors_per_track * self.sector_size))
            out.append(3) # 500 kbps MFM
            out.append(t // self.num_sides)
            out.append(t % self.num_sides)
            out.append(self.sectors_per_track)
            out.append(sec_size_code)

            for s in range(self.sectors_per_track):
                out.append(s + 1)

            for s in range(self.sectors_per_track):
                s_start = s * self.sector_size
                sec_bytes = t_data[s_start : s_start + self.sector_size]
                first_byte = sec_bytes[0] if sec_bytes else 0xE5
                if len(sec_bytes) == self.sector_size and all(b == first_byte for b in sec_bytes):
                    out.append(2)
                    out.append(first_byte)
                else:
                    out.append(1)
                    out.extend(sec_bytes)

        return bytes(out)



class Plus3Disk:
    """
    Sinclair ZX Spectrum +3 Floppy Disk Container.
    Wraps CPMDiskImage (.DSK, .IMG, .IMD) with authentic +3DOS 128-byte headers,
    standard MGTDisk-compatible method interface, and persistent write-through.
    """
    TYPE_BASIC = 1
    TYPE_NUM_ARRAY = 2
    TYPE_CHAR_ARRAY = 3
    TYPE_CODE = 4
    TYPE_48K_SNAP = 5
    TYPE_MDR = 6
    TYPE_SCREEN = 7
    TYPE_SPECIAL = 8
    TYPE_128K_SNAP = 9

    SECTOR_SIZE = 512
    SECTORS_PER_TRACK = 9
    TOTAL_TRACKS = 40
    TOTAL_SIDES = 1

    def __init__(self, filepath=None, disk_name=None):
        self.filepath = filepath
        self.description = disk_name or "PLUS3 DISK"
        self.write_protect = 0
        self.dirty = False

        if filepath and os.path.exists(filepath):
            self.cpm_img = CPMDiskImage.load(filepath)
            if disk_name:
                self.cpm_img.comment = disk_name
            elif hasattr(self.cpm_img, 'comment') and self.cpm_img.comment:
                self.description = self.cpm_img.comment
        else:
            self.cpm_img = CPMDiskImage(
                filepath,
                tracks=self.TOTAL_TRACKS,
                sides=self.TOTAL_SIDES,
                sectors=self.SECTORS_PER_TRACK,
                sec_size=self.SECTOR_SIZE
            )
            ext = os.path.splitext(filepath)[1].lower() if filepath else ".dsk"
            if ext in (".imd", ".dsk", ".img"):
                self.cpm_img.format_type = ext[1:]
            else:
                self.cpm_img.format_type = "dsk"
            self.cpm_img.comment = self.description
            if filepath:
                self.cpm_img.save(filepath)

    def get_disk_name(self):
        return getattr(self.cpm_img, 'comment', None) or self.description or "PLUS3 DISK"

    def format_disk(self, disk_name=None):
        label = disk_name or self.description or "PLUS3 DISK"
        self.description = label
        self.cpm_img = CPMDiskImage(
            self.filepath,
            tracks=self.TOTAL_TRACKS,
            sides=self.TOTAL_SIDES,
            sectors=self.SECTORS_PER_TRACK,
            sec_size=self.SECTOR_SIZE
        )
        ext = os.path.splitext(self.filepath)[1].lower() if self.filepath else ".dsk"
        if ext in (".imd", ".dsk", ".img"):
            self.cpm_img.format_type = ext[1:]
        else:
            self.cpm_img.format_type = "dsk"
        self.cpm_img.comment = label
        self.dirty = True
        if self.filepath:
            self.cpm_img.save(self.filepath)

    def _normalize_name(self, filename):
        clean = filename.strip()
        if re.match(r'^[A-Za-z0-9]:', clean):
            clean = clean[2:].strip()
        clean = clean.strip("'\"")
        return clean.upper()

    def list_files(self):
        files_dict = self.cpm_img.get_files()
        file_list = []
        idx = 1
        for fname, data in files_dict.items():
            ftype = self.TYPE_CODE
            sectors = (len(data) + 511) // 512
            meta = {}
            if len(data) >= 128 and data[:8] == b"PLUS3DOS" and data[8] == 0x1A:
                ck = sum(data[:127]) & 0xFF
                if ck == data[127]:
                    p3_type = data[15]
                    payload_len = struct.unpack_from("<H", data, 16)[0]
                    param1 = struct.unpack_from("<H", data, 18)[0]
                    if p3_type == 0:
                        ftype = self.TYPE_BASIC
                        autorun = param1 if param1 < 32768 else None
                        meta = {"autorun_line": autorun, "length": payload_len}
                    elif p3_type == 1:
                        ftype = self.TYPE_NUM_ARRAY
                        meta = {"length": payload_len}
                    elif p3_type == 2:
                        ftype = self.TYPE_CHAR_ARRAY
                        meta = {"length": payload_len}
                    elif p3_type == 3:
                        if param1 == 16384 and payload_len == 6912:
                            ftype = self.TYPE_SCREEN
                        else:
                            ftype = self.TYPE_CODE
                        meta = {"start_addr": param1, "length": payload_len}
            file_list.append({
                "index": idx,
                "type": ftype,
                "name": fname,
                "sectors": sectors,
                "size": len(data),
                "meta": meta
            })
            idx += 1
        return file_list

    def find_file(self, filename):
        target = self._normalize_name(filename)
        all_files = self.list_files()
        for f in all_files:
            if f["name"].upper() == target:
                return f
        for f in all_files:
            fn_u = f["name"].upper()
            if fn_u == target:
                return f
            base = fn_u.split('.')[0]
            if base == target or fn_u in (f"{target}.BAS", f"{target}.BIN", f"{target}.SCR", f"{target}.DAT"):
                return f
        if '.' not in target:
            for f in all_files:
                if f["name"].upper().split('.')[0] == target:
                    return f
        return None

    def save_file(self, filename, file_type, data_bytes, autorun_line=None, start_addr=None, data_length=None):
        if self.write_protect:
            raise PermissionError("Disk is write-protected")

        clean_name = self._normalize_name(filename)
        if '.' not in clean_name:
            if file_type == self.TYPE_BASIC:
                clean_name += ".BAS"
            elif file_type == self.TYPE_SCREEN:
                clean_name += ".SCR"
            elif file_type == self.TYPE_CODE:
                clean_name += ".BIN"
            else:
                clean_name += ".DAT"

        header = bytearray(128)
        header[:8] = b"PLUS3DOS"
        header[8] = 0x1A
        header[9] = 1   # Issue 1
        header[10] = 0  # Version 0

        payload_len = len(data_bytes)
        total_len = payload_len + 128
        struct.pack_into("<I", header, 11, total_len)

        if file_type == self.TYPE_BASIC:
            p3_type = 0
            addr_val = autorun_line if (autorun_line is not None and autorun_line < 32768) else 0x8000
            prog_len = payload_len
        elif file_type == self.TYPE_NUM_ARRAY:
            p3_type = 1
            addr_val = 0
            prog_len = 0
        elif file_type == self.TYPE_CHAR_ARRAY:
            p3_type = 2
            addr_val = 0
            prog_len = 0
        elif file_type == self.TYPE_SCREEN:
            p3_type = 3
            addr_val = 16384
            prog_len = 0
        else:
            p3_type = 3
            addr_val = 16384 if start_addr is None else start_addr
            prog_len = 0

        header[15] = p3_type
        struct.pack_into("<H", header, 16, payload_len & 0xFFFF)
        struct.pack_into("<H", header, 18, addr_val & 0xFFFF)
        struct.pack_into("<H", header, 20, prog_len & 0xFFFF)
        header[127] = sum(header[:127]) & 0xFF

        full_data = bytes(header) + bytes(data_bytes)
        self.cpm_img.put_file(clean_name, full_data)
        self.dirty = True

        if self.filepath:
            self.cpm_img.save(self.filepath)

    def load_file(self, filename):
        entry = self.find_file(filename)
        if not entry:
            raise FileNotFoundError(f"File not found on disk: '{filename}'")

        actual_name = entry["name"]
        files = self.cpm_img.get_files()
        if actual_name not in files:
            raise FileNotFoundError(f"File not found on disk: '{filename}'")

        raw_data = files[actual_name]
        if len(raw_data) >= 128 and raw_data[:8] == b"PLUS3DOS" and raw_data[8] == 0x1A:
            ck = sum(raw_data[:127]) & 0xFF
            p3_type = raw_data[15]
            payload_len = struct.unpack_from("<H", raw_data, 16)[0]
            param1 = struct.unpack_from("<H", raw_data, 18)[0]
            payload = raw_data[128 : 128 + payload_len]

            if p3_type == 0:
                ftype = self.TYPE_BASIC
                autorun = param1 if param1 < 32768 else None
                meta = {"autorun_line": autorun, "length": len(payload)}
            elif p3_type == 1:
                ftype = self.TYPE_NUM_ARRAY
                meta = {"length": len(payload)}
            elif p3_type == 2:
                ftype = self.TYPE_CHAR_ARRAY
                meta = {"length": len(payload)}
            elif p3_type == 3:
                if param1 == 16384 and len(payload) >= 6912:
                    ftype = self.TYPE_SCREEN
                else:
                    ftype = self.TYPE_CODE
                meta = {"start_addr": param1, "length": len(payload)}
            else:
                ftype = self.TYPE_CODE
                meta = {"start_addr": param1, "length": len(payload)}

            return ftype, payload, meta
        else:
            meta = {"start_addr": 24576, "length": len(raw_data)}
            return self.TYPE_CODE, raw_data, meta

    def erase_file(self, filename):
        if self.write_protect:
            raise PermissionError("Disk is write-protected")

        entry = self.find_file(filename)
        if not entry:
            raise FileNotFoundError(f"File not found on disk: '{filename}'")

        self.cpm_img.delete_file(entry["name"])
        self.dirty = True

        if self.filepath:
            self.cpm_img.save(self.filepath)

    def rename_file(self, old_name, new_name):
        if self.write_protect:
            raise PermissionError("Disk is write-protected")

        entry = self.find_file(old_name)
        if not entry:
            raise FileNotFoundError(f"File not found on disk: '{old_name}'")

        actual_old = entry["name"]
        clean_new = self._normalize_name(new_name)
        existing = self.find_file(clean_new)
        if existing and existing["name"].upper() != actual_old.upper():
            raise FileExistsError(f"File already exists on disk: '{new_name}'")

        files = self.cpm_img.get_files()
        if actual_old not in files:
            raise FileNotFoundError(f"File not found on disk: '{old_name}'")

        raw_data = files[actual_old]
        self.cpm_img.delete_file(actual_old)
        self.cpm_img.put_file(clean_new, raw_data)
        self.dirty = True

        if self.filepath:
            self.cpm_img.save(self.filepath)

    def get_free_kb(self):
        used_blocks = self.cpm_img._get_used_blocks()
        total_data_blocks = 175 - 2
        free_blocks = max(0, total_data_blocks - len(used_blocks))
        return free_blocks

    def save(self, filepath=None):
        target = filepath or self.filepath
        if target:
            self.cpm_img.save(target)
            self.filepath = target
            self.dirty = False

    def save_fdi(self, filepath=None):
        self.save(filepath)


class TRDOSDisk:
    """Emulates 640KB Double Sided 80-Track TR-DOS floppy disk image (.TRD / .SCL).
    Provides MGTDisk-compatible interface for BasinPy.
    """
    CYLINDERS = 80
    HEADS = 2
    TOTAL_TRACKS = CYLINDERS * HEADS  # 160
    SECTORS_PER_TRACK = 16
    SECTOR_SIZE = 256
    DISK_SIZE = TOTAL_TRACKS * SECTORS_PER_TRACK * SECTOR_SIZE  # 655,360 bytes (640 KB)

    TYPE_BASIC = 1
    TYPE_NUM_ARRAY = 2
    TYPE_CHAR_ARRAY = 3
    TYPE_CODE = 4
    TYPE_48K_SNAP = 5
    TYPE_MDR = 6
    TYPE_SCREEN = 7
    TYPE_SPECIAL = 8
    TYPE_128K_SNAP = 9

    def __init__(self, filepath=None, disk_name="TRDISK"):
        self.filepath = filepath
        self.description = disk_name or "TRDISK"
        self.write_protect = 0
        self.dirty = False
        self.raw_data = bytearray(self.DISK_SIZE)
        if filepath and os.path.exists(filepath):
            with open(filepath, "rb") as f:
                data = f.read()
            if filepath.lower().endswith(".scl"):
                self._load_scl(data)
            else:
                self.raw_data[:min(len(data), self.DISK_SIZE)] = data[:self.DISK_SIZE]
        else:
            self.format_disk(self.description)

    def format_disk(self, disk_name="TRDISK"):
        self.raw_data = bytearray(self.DISK_SIZE)
        # System sector at Track 0, Sector 8 (offset 0x800)
        sys_sec = 0x800
        self.raw_data[sys_sec + 0xE1] = 0x00  # First free sector (0)
        self.raw_data[sys_sec + 0xE2] = 0x01  # First free track (1)
        self.raw_data[sys_sec + 0xE3] = 0x16  # Disk type: 80 tracks, double sided
        self.raw_data[sys_sec + 0xE4] = 0x00  # Number of files (0)
        self.raw_data[sys_sec + 0xE5] = 0xF0  # Free sectors low (2544 = 0x09F0)
        self.raw_data[sys_sec + 0xE6] = 0x09  # Free sectors high
        self.raw_data[sys_sec + 0xE7] = 0x10  # TR-DOS marker (0x10)
        clean_title = (disk_name.upper()[:8]).ljust(8)
        self.raw_data[sys_sec + 0xF5 : sys_sec + 0xFD] = clean_title.encode('latin-1', errors='ignore')

    def get_disk_name(self):
        sys_sec = 0x800
        title = self.raw_data[sys_sec + 0xF5 : sys_sec + 0xFD].decode('latin-1', errors='ignore').strip()
        return title or self.description or "TRDISK"

    def get_free_kb(self):
        sys_sec = 0x800
        free_sec = self.raw_data[sys_sec + 0xE5] | (self.raw_data[sys_sec + 0xE6] << 8)
        return (free_sec * 256) // 1024

    def list_files(self):
        files = []
        for i in range(128):
            offset = i * 16
            if self.raw_data[offset] == 0x00:
                break
            if self.raw_data[offset] == 0x01:  # Deleted file marker
                continue
            fname = self.raw_data[offset : offset + 8].decode('latin-1', errors='ignore').strip()
            ftype_char = chr(self.raw_data[offset + 8])
            start_addr = self.raw_data[offset + 9] | (self.raw_data[offset + 10] << 8)
            length = self.raw_data[offset + 11] | (self.raw_data[offset + 12] << 8)
            sectors = self.raw_data[offset + 13]
            start_sec = self.raw_data[offset + 14]
            start_trk = self.raw_data[offset + 15]
            if ftype_char == 'B':
                ftype_int = self.TYPE_BASIC
            elif ftype_char == 'C':
                if start_addr == 16384 and length >= 6912:
                    ftype_int = self.TYPE_SCREEN
                else:
                    ftype_int = self.TYPE_CODE
            elif ftype_char == 'D':
                ftype_int = self.TYPE_NUM_ARRAY
            else:
                ftype_int = self.TYPE_SPECIAL
            files.append({
                "name": fname,
                "type": ftype_int,
                "raw_type": ftype_char,
                "start_addr": start_addr,
                "length": length,
                "sectors": sectors,
                "start_sec": start_sec,
                "start_trk": start_trk
            })
        return files

    def load_file(self, fname):
        clean_target = fname.strip().upper()
        if "." in clean_target:
            target_base, target_ext = clean_target.split(".", 1)
        else:
            target_base, target_ext = clean_target, None

        for f in self.list_files():
            if f["name"].upper() == target_base and (target_ext is None or f["raw_type"].upper() == target_ext[:1].upper()):
                offset = (f["start_trk"] * 16 + f["start_sec"]) * 256
                dlen = min(f["length"], f["sectors"] * 256)
                fdata = self.raw_data[offset : offset + dlen]
                meta = {
                    "autorun_line": f["start_addr"] if f["raw_type"] == 'B' and f["start_addr"] < 32768 else None,
                    "start_addr": f["start_addr"],
                    "length": dlen
                }
                return f["type"], bytes(fdata), meta
        raise FileNotFoundError(f"File '{fname}' not found on TR-DOS disk")

    def save_file(self, filename, file_type, data_bytes, start_addr=None, autorun_line=None):
        if self.write_protect:
            raise PermissionError("Disk is write-protected")
        clean_name = os.path.splitext(filename)[0].upper()[:8].ljust(8)
        if file_type == self.TYPE_BASIC:
            t_char = ord('B')
            param = (autorun_line if autorun_line is not None else 32768) & 0xFFFF
        elif file_type == self.TYPE_SCREEN:
            t_char = ord('C')
            param = 16384
        elif file_type in (self.TYPE_NUM_ARRAY, self.TYPE_CHAR_ARRAY):
            t_char = ord('D')
            param = 0
        else:
            t_char = ord('C')
            param = (start_addr if start_addr is not None else 16384) & 0xFFFF

        sec_count = (len(data_bytes) + 255) // 256
        if sec_count == 0:
            sec_count = 1

        sys_sec = 0x800
        free_sec_total = self.raw_data[sys_sec + 0xE5] | (self.raw_data[sys_sec + 0xE6] << 8)
        if sec_count > free_sec_total:
            raise IOError("No space left on TR-DOS disk")

        num_files = self.raw_data[sys_sec + 0xE4]
        if num_files >= 128:
            raise IOError("TR-DOS directory full (128 files max)")

        nxt_sec = self.raw_data[sys_sec + 0xE1]
        nxt_trk = self.raw_data[sys_sec + 0xE2]

        entry_offset = num_files * 16
        self.raw_data[entry_offset : entry_offset + 8] = clean_name.encode('latin-1', errors='ignore')
        self.raw_data[entry_offset + 8] = t_char
        self.raw_data[entry_offset + 9] = param & 0xFF
        self.raw_data[entry_offset + 10] = (param >> 8) & 0xFF
        self.raw_data[entry_offset + 11] = len(data_bytes) & 0xFF
        self.raw_data[entry_offset + 12] = (len(data_bytes) >> 8) & 0xFF
        self.raw_data[entry_offset + 13] = sec_count
        self.raw_data[entry_offset + 14] = nxt_sec
        self.raw_data[entry_offset + 15] = nxt_trk

        data_offset = (nxt_trk * 16 + nxt_sec) * 256
        self.raw_data[data_offset : data_offset + len(data_bytes)] = data_bytes

        nxt_sec += sec_count
        nxt_trk += nxt_sec // 16
        nxt_sec %= 16

        free_sec_total -= sec_count
        self.raw_data[sys_sec + 0xE1] = nxt_sec
        self.raw_data[sys_sec + 0xE2] = nxt_trk
        self.raw_data[sys_sec + 0xE4] = num_files + 1
        self.raw_data[sys_sec + 0xE5] = free_sec_total & 0xFF
        self.raw_data[sys_sec + 0xE6] = (free_sec_total >> 8) & 0xFF

        if self.filepath:
            with open(self.filepath, "wb") as f:
                f.write(self.raw_data)

    def _load_scl(self, data):
        if not data.startswith(b"SINCLAIR"):
            raise ValueError("Not a valid SCL file")
        n_files = data[8]
        self.format_disk("SCL_DISK")
        cat_pos = 9
        data_pos = 9 + n_files * 14
        cur_trk = 1
        cur_sec = 0
        for f_idx in range(n_files):
            entry = data[cat_pos : cat_pos + 14]
            cat_pos += 14
            fname = entry[:8]
            ftype = entry[8:9]
            start_addr = entry[9:11]
            flen = entry[11:13]
            sec_count = entry[13]
            raw_file = data[data_pos : data_pos + sec_count * 256]
            data_pos += sec_count * 256

            e_offset = f_idx * 16
            self.raw_data[e_offset : e_offset + 8] = fname
            self.raw_data[e_offset + 8] = ftype[0]
            self.raw_data[e_offset + 9 : e_offset + 11] = start_addr
            self.raw_data[e_offset + 11 : e_offset + 13] = flen
            self.raw_data[e_offset + 13] = sec_count
            self.raw_data[e_offset + 14] = cur_sec
            self.raw_data[e_offset + 15] = cur_trk

            f_offset = (cur_trk * 16 + cur_sec) * 256
            self.raw_data[f_offset : f_offset + len(raw_file)] = raw_file

            cur_sec += sec_count
            cur_trk += cur_sec // 16
            cur_sec %= 16


# ---------------------------------------------------------------------------
# SINCLAIR ZX SPECTRUM UNIFIED MULTI-DISK & MICRODRIVE EMULATION SUBSYSTEM
# Supported Systems: MGT, Plus3, Opus Discovery, TR-DOS, Beta Disk / BetaDos
# ---------------------------------------------------------------------------

class OpusDisk:
    """
    Emulates Opus Discovery 3.5" floppy disk image (.OPD / .DSK).
    Geometry:
    - 40 tracks (single-sided 180KB) or 80 tracks (double-sided 360KB)
    - 18 sectors per track
    - 256 bytes per sector
    - Track 0 is directory and system allocation track
    """
    CYLINDERS = 40
    HEADS = 1
    SECTORS_PER_TRACK = 18
    SECTOR_SIZE = 256
    DISK_SIZE_180K = 40 * 18 * 256  # 184,320 bytes
    DISK_SIZE_360K = 80 * 18 * 256  # 368,640 bytes

    TYPE_BASIC = 1
    TYPE_NUM_ARRAY = 2
    TYPE_CHAR_ARRAY = 3
    TYPE_CODE = 4
    TYPE_SCREEN = 7

    def __init__(self, filepath=None, disk_name="OPUS"):
        self.filepath = filepath
        self.description = disk_name or "OPUS"
        self.write_protect = False
        self.dirty = False
        self.heads = 1
        self.tracks = 40
        self.raw_data = bytearray(self.DISK_SIZE_180K)

        if filepath and os.path.exists(filepath):
            with open(filepath, "rb") as f:
                data = f.read()
            if len(data) >= self.DISK_SIZE_360K:
                self.heads = 2
                self.tracks = 80
                self.raw_data = bytearray(data[:self.DISK_SIZE_360K])
            else:
                self.heads = 1
                self.tracks = 40
                self.raw_data = bytearray(self.DISK_SIZE_180K)
                self.raw_data[:min(len(data), self.DISK_SIZE_180K)] = data[:self.DISK_SIZE_180K]
        else:
            self.format_disk(self.description)

    def format_disk(self, disk_name="OPUS"):
        self.raw_data = bytearray(self.DISK_SIZE_180K)
        clean_name = (disk_name.upper()[:10]).ljust(10).encode('latin-1', errors='ignore')
        self.raw_data[0:10] = clean_name
        self.raw_data[10] = 0x4F # 'O' - Opus marker
        self.raw_data[11] = 0x50 # 'P'
        self.raw_data[12] = 40   # 40 tracks
        self.raw_data[13] = 18   # 18 sectors
        self.dirty = True

    def get_disk_name(self):
        name = self.raw_data[0:10].decode('latin-1', errors='ignore').strip()
        return name or self.description or "OPUS"

    def get_free_kb(self):
        used_sectors = 18 # Track 0 reserved
        files = self.list_files()
        for f in files:
            used_sectors += f.get("sectors", 1)
        total_sectors = self.tracks * self.SECTORS_PER_TRACK
        free_sec = max(0, total_sectors - used_sectors)
        return (free_sec * self.SECTOR_SIZE) // 1024

    def _sector_offset(self, track, sector):
        sec_idx = max(1, min(18, sector)) - 1
        return (track * self.SECTORS_PER_TRACK + sec_idx) * self.SECTOR_SIZE

    def list_files(self):
        files = []
        for sec in range(2, 19):
            sec_off = self._sector_offset(0, sec)
            for entry_idx in range(8):
                entry_off = sec_off + entry_idx * 32
                entry = self.raw_data[entry_off : entry_off + 32]
                if entry[0] in (0x00, 0xE5, 0xFF):
                    continue
                raw_name = entry[0:10].decode('latin-1', errors='ignore').strip()
                if not raw_name:
                    continue
                ftype = entry[10]
                flen = entry[11] | (entry[12] << 8)
                start_addr = entry[13] | (entry[14] << 8)
                start_track = entry[15]
                start_sec = entry[16]
                sec_count = max(1, (flen + 255) // 256)
                files.append({
                    "name": raw_name,
                    "type": ftype,
                    "length": flen,
                    "start_addr": start_addr,
                    "track": start_track,
                    "sector": start_sec,
                    "sectors": sec_count
                })
        return files

    def load_file(self, fname):
        target = fname.strip().upper()
        for f in self.list_files():
            if f["name"].upper() == target:
                start_track = f["track"]
                start_sec = f["sector"]
                flen = f["length"]
                data = bytearray()
                cur_trk = start_track
                cur_sec = start_sec
                bytes_left = flen
                while bytes_left > 0 and cur_trk < self.tracks:
                    sec_off = self._sector_offset(cur_trk, cur_sec)
                    chunk = self.raw_data[sec_off : sec_off + min(bytes_left, self.SECTOR_SIZE)]
                    data.extend(chunk)
                    bytes_left -= len(chunk)
                    cur_sec += 1
                    if cur_sec > self.SECTORS_PER_TRACK:
                        cur_sec = 1
                        cur_trk += 1
                meta = {
                    "start_addr": f["start_addr"],
                    "length": f["length"],
                    "type": f["type"]
                }
                return f["type"], bytes(data), meta
        raise FileNotFoundError(f"File not found on Opus disk: {fname}")

    def save_file(self, filename, file_type, data_bytes, start_addr=None, autorun_line=None):
        clean_name = (filename.strip().upper()[:10]).ljust(10)
        flen = len(data_bytes)

        try: self.erase_file(clean_name.strip())
        except Exception: pass

        files = self.list_files()
        next_track = 1
        next_sec = 1
        for f in files:
            end_trk = f["track"] + (f["sector"] - 1 + f["sectors"]) // self.SECTORS_PER_TRACK
            end_sec = ((f["sector"] - 1 + f["sectors"]) % self.SECTORS_PER_TRACK) + 1
            if (end_trk > next_track) or (end_trk == next_track and end_sec > next_sec):
                next_track = end_trk
                next_sec = end_sec

        if next_track >= self.tracks:
            raise IOError("Opus disk full!")

        bytes_left = flen
        cur_trk = next_track
        cur_sec = next_sec
        offset = 0
        while bytes_left > 0 and cur_trk < self.tracks:
            sec_off = self._sector_offset(cur_trk, cur_sec)
            chunk_size = min(bytes_left, self.SECTOR_SIZE)
            self.raw_data[sec_off : sec_off + chunk_size] = data_bytes[offset : offset + chunk_size]
            if chunk_size < self.SECTOR_SIZE:
                self.raw_data[sec_off + chunk_size : sec_off + self.SECTOR_SIZE] = b'\x00' * (self.SECTOR_SIZE - chunk_size)
            offset += chunk_size
            bytes_left -= chunk_size
            cur_sec += 1
            if cur_sec > self.SECTORS_PER_TRACK:
                cur_sec = 1
                cur_trk += 1

        slot_found = False
        for sec in range(2, 19):
            sec_off = self._sector_offset(0, sec)
            for entry_idx in range(8):
                entry_off = sec_off + entry_idx * 32
                if self.raw_data[entry_off] in (0x00, 0xE5, 0xFF):
                    self.raw_data[entry_off : entry_off + 10] = clean_name.encode('latin-1', errors='ignore')
                    self.raw_data[entry_off + 10] = int(file_type) & 0xFF
                    self.raw_data[entry_off + 11] = flen & 0xFF
                    self.raw_data[entry_off + 12] = (flen >> 8) & 0xFF
                    s_addr = int(start_addr or autorun_line or 0)
                    self.raw_data[entry_off + 13] = s_addr & 0xFF
                    self.raw_data[entry_off + 14] = (s_addr >> 8) & 0xFF
                    self.raw_data[entry_off + 15] = next_track & 0xFF
                    self.raw_data[entry_off + 16] = next_sec & 0xFF
                    slot_found = True
                    break
            if slot_found:
                break

        if not slot_found:
            raise IOError("Opus directory full!")

        self.dirty = True
        if self.filepath:
            with open(self.filepath, "wb") as f:
                f.write(self.raw_data)

    def erase_file(self, filename):
        target = filename.strip().upper()
        erased = False
        for sec in range(2, 19):
            sec_off = self._sector_offset(0, sec)
            for entry_idx in range(8):
                entry_off = sec_off + entry_idx * 32
                raw_name = self.raw_data[entry_off : entry_off + 10].decode('latin-1', errors='ignore').strip()
                if raw_name.upper() == target:
                    self.raw_data[entry_off] = 0xE5
                    erased = True
                    break
            if erased:
                break
        if erased:
            self.dirty = True
            if self.filepath:
                with open(self.filepath, "wb") as f:
                    f.write(self.raw_data)
            return True
        return False

    def rename_file(self, old_name, new_name):
        target = old_name.strip().upper()
        clean_new = (new_name.strip().upper()[:10]).ljust(10).encode('latin-1', errors='ignore')
        for sec in range(2, 19):
            sec_off = self._sector_offset(0, sec)
            for entry_idx in range(8):
                entry_off = sec_off + entry_idx * 32
                raw_name = self.raw_data[entry_off : entry_off + 10].decode('latin-1', errors='ignore').strip()
                if raw_name.upper() == target:
                    self.raw_data[entry_off : entry_off + 10] = clean_new
                    self.dirty = True
                    if self.filepath:
                        with open(self.filepath, "wb") as f:
                            f.write(self.raw_data)
                    return True
        return False


# -------------------------------------------------------------
# Disk Subsystem State & Hardware Controller Emulation
# -------------------------------------------------------------
active_disk_system = "PLUS3"  # "MGT", "PLUS3", "OPUS", "TRD", "BETA"
disk_drives = {1: None, 2: None, 3: None, 4: None}

# WD1793 / KR1818VG93 (TR-DOS / Beta Disk)
wd1793_status = 0x00
wd1793_command = 0x00
wd1793_track = 0
wd1793_sector = 1
wd1793_data = 0
wd1793_system_reg = 0x0C
wd1793_buf = bytearray(256)
wd1793_buf_pos = 0

# WD1770 (Opus Discovery)
wd1770_status = 0x00
wd1770_command = 0x00
wd1770_track = 0
wd1770_sector = 1
wd1770_data = 0
opus_drive_ctrl = 0x01
opus_buf = bytearray(256)
opus_buf_pos = 0


def init_disk_system_variables(system_type="PLUS3"):
    global memory, active_disk_system
    sys_upper = (system_type or "").upper()
    if sys_upper in ("TRD", "TR-DOS", "TRDOS", "BETA", "BETADOS", "BETA DISK"):
        memory[23734] = 0x00  # Track/sector buffer pointer low
        memory[23735] = 0x5D  # Track/sector buffer pointer high (0x5D00)
        memory[23746] = 0     # Current track
        memory[23747] = 1     # Current sector
        memory[23756] = 0     # Current drive (0=A, 1=B, 2=C, 3=D)
        memory[23757] = 4     # Number of connected drives (4)
        memory[23766] = ord('B') # File type
        memory[23796] = 0     # Status / Error register (0 = OK)
        memory[23801] = 1     # Sector counter
        memory[23825] = 0     # Track counter
    elif sys_upper in ("OPUS", "OPUS DISCOVERY", "OPUSDOS"):
        memory[23734] = 1     # Current drive (1)
        memory[23735] = 0     # Directory track (0)
        memory[23736] = 1     # Current sector (1)
        memory[23737] = 0     # FDC status
        memory[23738] = 0x00  # Sector buffer pointer low
        memory[23739] = 0x20  # Sector buffer pointer high (0x2000 in Opus shadow RAM)
    elif sys_upper in ("PLUS3", "+3", "PLUS 3", "PLUS3DOS"):
        memory[23611] |= 0x10 # FLAGS2: bit 4 = +3DOS active
        memory[23734] = 0     # Current drive (0=A, 1=B)
        memory[23735] = 0     # Disk motor status
    elif sys_upper in ("MGT", "DISCIPLE", "+D", "GDOS", "G+DOS"):
        memory[23734] = 1     # System drive (1)
        memory[23735] = 9     # DF_SZ (directory sector size)
        memory[23736] = 0     # Cylinder
        memory[23737] = 0     # Status


def handle_set_drive_command(cmd_str=""):
    global active_disk_system, mgt_default_drive, canvas_dirty, disk_drives, mgt_drives
    s = (cmd_str or "").strip()
    if s.upper().startswith("SET DRIVE"):
        s = s[9:].strip()
    elif s.upper().startswith("SETDRIVE"):
        s = s[8:].strip()
    elif s.upper().startswith("DRIVE"):
        s = s[5:].strip()

    if s.startswith(":") or s.startswith("="):
        s = s[1:].strip()
    s = s.strip().strip('"\'')
    s_upper = s.upper()

    if not s_upper or s_upper in ("?", "/?", "STATUS", "-STATUS", "/STATUS", "HELP", "/HELP", "LIST"):
        canvas_print("--- SINCLAIR DISK DRIVE SYSTEM ---")
        canvas_print(f"Active System : {active_disk_system}")
        canvas_print("Connected Drives:")
        d1 = disk_drives.get(1) or mgt_drives.get(1)
        d2 = disk_drives.get(2) or mgt_drives.get(2)
        d3 = disk_drives.get(3)
        d4 = disk_drives.get(4)
        canvas_print(f"  Drive 1 (A:): {d1.get_disk_name() if d1 else '[No disk in drive]'}")
        canvas_print(f"  Drive 2 (B:): {d2.get_disk_name() if d2 else '[No disk in drive]'}")
        if active_disk_system in ("TRD", "BETA"):
            canvas_print(f"  Drive 3 (C:): {d3.get_disk_name() if d3 else '[No disk in drive]'}")
            canvas_print(f"  Drive 4 (D:): {d4.get_disk_name() if d4 else '[No disk in drive]'}")
        canvas_print("Profiles: MGT, Plus3, Opus, TRD, Beta")
        canvas_print("Note: Microdrives run concurrently via SET MDR / Interface 1")
        canvas_dirty = True
        try: update_display()
        except Exception: pass
        return

    if s_upper in ("MGT", "DISCIPLE", "+D", "PLUS D", "PLUSD", "GDOS", "G+DOS"):
        active_disk_system = "MGT"
        init_disk_system_variables("MGT")
        canvas_print("Disk System: MGT DISCiPLE / +D (G+DOS)")
        canvas_print("  Ports: #E7, #EB, #EF, #F7, #FB | Syntax: CAT 1, LOAD d1\"file\"")
    elif s_upper in ("PLUS3", "+3", "PLUS 3", "PLUS3DOS", "PLUS-3"):
        active_disk_system = "PLUS3"
        init_disk_system_variables("PLUS3")
        canvas_print("Disk System: Sinclair +3DOS (Spectrum +3)")
        canvas_print("  Ports: #1FFD, #2FFD, #3FFD | Syntax: CAT \"a:\", LOAD \"a:file\"")
    elif s_upper in ("OPUS", "OPUS DISCOVERY", "OPUSDOS", "DISCOVERY"):
        active_disk_system = "OPUS"
        init_disk_system_variables("OPUS")
        canvas_print("Disk System: Opus Discovery (WD1770)")
        canvas_print("  Ports: #38..#3B, #EE | Syntax: CAT 1, LOAD d1\"file\", FORMAT d1")
    elif s_upper in ("TRD", "TR-DOS", "TRDOS", "TR_DOS"):
        active_disk_system = "TRD"
        init_disk_system_variables("TRD")
        canvas_print("Disk System: TR-DOS (Beta 128 Disc Interface)")
        canvas_print("  Ports: #1F, #3F, #5F, #7F, #FF | Hook: USR 15619 (0x3D13)")
        canvas_print("  Syntax: RANDOMIZE USR 15619: REM: CAT | * \"A:\" | LOAD \"file\"")
    elif s_upper in ("BETA", "BETADOS", "BETA DISK", "BETADISK", "BETA48"):
        active_disk_system = "BETA"
        init_disk_system_variables("BETA")
        canvas_print("Disk System: Beta Disk / BetaDos (WD1793)")
        canvas_print("  Ports: #1F, #3F, #5F, #7F, #FF | Hook: USR 15619 (0x3D13)")
        canvas_print("  Syntax: USR 15619: REM: <cmd> | Drives A, B, C, D")
    else:
        canvas_print(f"Unknown disk system '{s}'. Valid: MGT, Plus3, Opus, TRD, Beta")

    canvas_dirty = True
    try: update_display()
    except Exception: pass


def handle_set_mdr_command(cmd_str=""):
    global microdrive_attachments, canvas_dirty
    s = (cmd_str or "").strip()
    if s.upper().startswith("SET MDR"):
        s = s[7:].strip()
    elif s.upper().startswith("SETMDR"):
        s = s[6:].strip()
    elif s.upper().startswith("MDR"):
        s = s[3:].strip()

    if s.startswith(":") or s.startswith("="):
        s = s[1:].strip()
    s = s.strip()
    s_upper = s.upper()

    folder = get_zx_folder()
    launch_folder = os.getcwd()

    if not s or s_upper in ("?", "/?", "STATUS", "-STATUS", "/STATUS", "HELP", "/HELP", "LIST"):
        canvas_print("--- SINCLAIR MICRODRIVE SYSTEM (INTERFACE 1) ---")
        for d in range(1, 9):
            fname = microdrive_attachments.get(d, f"{d}.mdr")
            p = fname if os.path.isabs(fname) else (os.path.join(launch_folder, fname) if os.path.exists(os.path.join(launch_folder, fname)) else os.path.join(folder, fname))
            if os.path.exists(p):
                cart_name = ""
                try:
                    with open(p, "rb") as f:
                        hdr = f.read(14)
                        cart_name = hdr[4:14].decode('latin-1', errors='ignore').strip()
                except Exception:
                    pass
                status = f"Ready ({cart_name or 'Cart'})"
            else:
                status = "Not Created"
            canvas_print(f"  Drive {d}: {fname} [{status}]")
        canvas_print("Commands:")
        canvas_print("  SET MDR 1 2 ...   - Create blank 1.mdr, 2.mdr (up to 8)")
        canvas_print("  SET MDR \"file.mdr\"- Attach cartridge to Microdrive 1")
        canvas_print("  SET MDR <d> \"file\"- Attach cartridge to Microdrive <d>")
        canvas_dirty = True
        try: update_display()
        except Exception: pass
        return

    parts = [p.strip() for p in re.split(r'[\s,]+', s) if p.strip()]
    if all(p.isdigit() and 1 <= int(p) <= 8 for p in parts) or s_upper == "ALL":
        target_drives = list(range(1, 9)) if s_upper == "ALL" else [int(p) for p in parts]
        created_count = 0
        for d in target_drives:
            mdr_name = f"{d}.mdr"
            p = os.path.join(launch_folder, mdr_name)
            create_blank_mdr(p, f"cart{d}")
            microdrive_attachments[d] = mdr_name
            canvas_print(f"Microdrive {d}: Created blank cartridge '{mdr_name}' (254 sectors free)")
            created_count += 1
        canvas_print(f"Microdrive setup complete: {created_count} cartridge(s) mounted.")
        canvas_dirty = True
        try: update_display()
        except Exception: pass
        return

    drive_target = 1
    filename_target = ""
    m_drive_pre = re.match(r'^([1-8])[\s,]+(.*)$', s)
    if m_drive_pre:
        drive_target = int(m_drive_pre.group(1))
        filename_target = m_drive_pre.group(2).strip().strip('"\'')
    else:
        filename_target = s.strip().strip('"\'')

    if filename_target:
        if not filename_target.lower().endswith(".mdr"):
            filename_target += ".mdr"
        p = filename_target if os.path.isabs(filename_target) else (os.path.join(launch_folder, filename_target) if os.path.exists(os.path.join(launch_folder, filename_target)) else os.path.join(folder, filename_target))
        if not os.path.exists(p):
            create_blank_mdr(p, f"cart{drive_target}")
            canvas_print(f"Microdrive {drive_target}: Created new cartridge '{os.path.basename(p)}'")
        microdrive_attachments[drive_target] = filename_target
        canvas_print(f"Attached '{os.path.basename(filename_target)}' to Microdrive {drive_target}")
    else:
        canvas_print("Error: Specify drive number (1-8) or filename for SET MDR")

    canvas_dirty = True
    try: update_display()
    except Exception: pass


def handle_set_sprites_command(cmd_str=""):
    """
    SET SPRITES [ZX | NEXT]
    Switches active sprite engine between ZX (48K monochrome machine-code compiler engine)
    and NEXT (ZX Spectrum Next hardware sprite engine).
    Query form: SET SPRITES displays current engine mode.
    """
    global current_sprite_mode, canvas_dirty
    s = (cmd_str or "").strip()
    m = re.match(r'^(?:SET[\s\-_]*SPRITES?)\s*[:=]?\s*(.*)$', s, re.IGNORECASE)
    tail = m.group(1).strip() if m else s.strip()
    if tail.startswith(":") or tail.startswith("="):
        tail = tail[1:].strip()
    upper = tail.upper().strip()

    if not upper or upper in ("?", "/?", "STATUS", "-STATUS", "/STATUS", "HELP", "/HELP"):
        cur = globals().get('current_sprite_mode', 'ZX')
        canvas_print("--- SPRITE ENGINE STATUS ---")
        canvas_print(f"ACTIVE: {cur}")
        canvas_print("COMMANDS:")
        canvas_print("  SET SPRITES ZX   (48K Mono)")
        canvas_print("  SET SPRITES NEXT (Next HW)")
    elif upper in ("ZX", "48K", "MONO", "MONOCHROME", "CLASSIC"):
        current_sprite_mode = "ZX"
        canvas_print("SPRITE ENGINE: ZX (48K MONO)")
    elif upper in ("NEXT", "ZXNEXT", "COLOR", "COLOUR", "HW", "HARDWARE"):
        current_sprite_mode = "NEXT"
        canvas_print("SPRITE ENGINE: NEXT (HARDWARE)")
    else:
        canvas_print("Error: Unknown sprite type")
        canvas_print("Usage: SET SPRITES ZX | NEXT")

    canvas_dirty = True
    try:
        update_display()
    except Exception:
        pass


def get_trdos_disk(drv_idx):
    global mgt_drives, disk_drives
    d = mgt_drives.get(drv_idx)
    if d is not None and getattr(d, '__class__', None).__name__ == 'TRDOSDisk':
        return d
    d2 = disk_drives.get(drv_idx)
    if d2 is not None and getattr(d2, '__class__', None).__name__ == 'TRDOSDisk':
        return d2
    return d or d2


def get_opus_disk(drv_idx):
    global mgt_drives, disk_drives
    d = disk_drives.get(drv_idx)
    if d is not None and getattr(d, '__class__', None).__name__ == 'OpusDisk':
        return d
    d2 = mgt_drives.get(drv_idx)
    if d2 is not None and getattr(d2, '__class__', None).__name__ == 'OpusDisk':
        return d2
    return d or d2


def execute_trdos_command(cmd_str):
    global disk_drives, mgt_drives, memory
    s = (cmd_str or "").strip()
    s_upper = s.upper()

    drv_idx = (memory[23756] & 3) + 1
    drv_letter = chr(ord('A') + drv_idx - 1)
    disk = get_trdos_disk(drv_idx)

    if s_upper.startswith("*"):
        rem = s[1:].strip().strip('"\'')
        m_drv = re.match(r'^([ABCDabcd]):?$', rem)
        if m_drv:
            new_idx = ord(m_drv.group(1).upper()) - ord('A')
            memory[23756] = new_idx
            drv_letter = chr(ord('A') + new_idx)
            canvas_print(f"TR-DOS: Selected Drive {drv_letter}:")
            return
        elif not rem:
            canvas_print(f"TR-DOS Current Drive: {drv_letter}:")
            return

    if s_upper in ("CAT", "CAT #", "DIR") or s_upper.startswith("CAT ") or s_upper.startswith("DIR "):
        if disk is None:
            canvas_print(f"TR-DOS Drive {drv_letter}: No disk in drive")
            return
        files = disk.list_files() if hasattr(disk, 'list_files') else []
        canvas_print(f"--- TR-DOS DRIVE {drv_letter}: CAT (\"{disk.get_disk_name()}\") ---")
        if not files:
            canvas_print("  (Disk Empty)")
        else:
            for f in files:
                t_str = "B" if f.get("type") == 1 else ("C" if f.get("type") == 4 else "D")
                canvas_print(f"  {f['name']:<10} <{t_str}>  {f.get('sectors', 1):>3} sec")
        free_kb = disk.get_free_kb() if hasattr(disk, 'get_free_kb') else 640
        canvas_print(f"Files: {len(files)}  Free: {free_kb}K / 640K")
        return

    if s_upper.startswith("LOAD "):
        args = s[5:].strip()
        m_fname = re.match(r'^["\']?([^"\']+)["\']?(.*)$', args)
        if m_fname:
            fn = m_fname.group(1).strip()
            if disk:
                try:
                    ftype, data, meta = disk.load_file(fn)
                    if ftype == 1: # BASIC
                        load_program_from_bytes(data)
                        canvas_print(f"Loaded '{fn}' from TR-DOS {drv_letter}:")
                    else:
                        start_addr = meta.get("start_addr", 16384)
                        for i, b in enumerate(data):
                            if start_addr + i < 65536:
                                memory[start_addr + i] = b
                        canvas_print(f"Loaded CODE '{fn}' to {start_addr} ({len(data)} bytes)")
                except Exception as e:
                    canvas_print(f"TR-DOS load error: {e}")
            else:
                canvas_print(f"TR-DOS Drive {drv_letter}: No disk in drive")
        return

    if s_upper.startswith("SAVE "):
        args = s[5:].strip()
        m_fname = re.match(r'^["\']?([^"\']+)["\']?(.*)$', args)
        if m_fname:
            fn = m_fname.group(1).strip()
            rest = m_fname.group(2).strip().upper()
            if disk:
                try:
                    if "CODE" in rest:
                        start = 16384
                        length = 6912
                        c_parts = [p.strip() for p in rest.replace("CODE", "").split(",") if p.strip()]
                        if len(c_parts) >= 1: start = int(c_parts[0])
                        if len(c_parts) >= 2: length = int(c_parts[1])
                        code_bytes = bytes(memory[start : start + length])
                        disk.save_file(fn, 4, code_bytes, start_addr=start)
                        canvas_print(f"Saved CODE '{fn}' ({length} bytes) to TR-DOS {drv_letter}:")
                    else:
                        prog_bytes = export_basic_program_bytes()
                        disk.save_file(fn, 1, prog_bytes, start_addr=10)
                        canvas_print(f"Saved BASIC '{fn}' to TR-DOS {drv_letter}:")
                except Exception as e:
                    canvas_print(f"TR-DOS save error: {e}")
        return

    if s_upper.startswith("ERASE "):
        fn = s[6:].strip().strip('"\'')
        if disk and hasattr(disk, 'erase_file'):
            disk.erase_file(fn)
            canvas_print(f"Erased '{fn}' from TR-DOS {drv_letter}:")
        return

    if s_upper.startswith("FORMAT "):
        name = s[7:].strip().strip('"\'') or "TRDISK"
        if disk and hasattr(disk, 'format_disk'):
            disk.format_disk(name)
            canvas_print(f"Formatted TR-DOS Drive {drv_letter}: \"{name}\"")
        return

    if s_upper == "RETURN":
        canvas_print("TR-DOS: Returned to BASIC")
        return

    canvas_print(f"TR-DOS: Executed '{s}'")


def handle_trdos_rom_hook(cpu):
    global memory, disk_drives, mgt_drives
    func = cpu.C
    drv_idx = (memory[23756] & 3) + 1
    disk = get_trdos_disk(drv_idx)

    # C = 0x00: Seek track 0 / Restore
    if func == 0x00:
        memory[23746] = 0
        memory[23825] = 0
        cpu.A = 0
        cpu.F |= FLAG_C
        cpu.PC = cpu.pop_word()
        return True

    # C = 0x01: Select Drive
    elif func == 0x01:
        memory[23756] = cpu.A & 3
        cpu.A = 0
        cpu.F |= FLAG_C
        cpu.PC = cpu.pop_word()
        return True

    # C = 0x05: Read Sector(s)
    elif func == 0x05:
        count = cpu.B if cpu.B > 0 else 1
        sec_num = cpu.DE
        dest_addr = cpu.HL
        if disk and hasattr(disk, 'raw_data'):
            for i in range(count):
                offset = (sec_num + i) * 256
                if offset + 256 <= len(disk.raw_data) and dest_addr + 256 <= 65536:
                    memory[dest_addr : dest_addr + 256] = disk.raw_data[offset : offset + 256]
                    dest_addr += 256
            cpu.A = 0
            cpu.F |= FLAG_C
        else:
            cpu.A = 0xFF
            cpu.F &= ~FLAG_C
        cpu.PC = cpu.pop_word()
        return True

    # C = 0x06: Write Sector(s)
    elif func == 0x06:
        count = cpu.B if cpu.B > 0 else 1
        sec_num = cpu.DE
        src_addr = cpu.HL
        if disk and hasattr(disk, 'raw_data'):
            for i in range(count):
                offset = (sec_num + i) * 256
                if offset + 256 <= len(disk.raw_data) and src_addr + 256 <= 65536:
                    disk.raw_data[offset : offset + 256] = memory[src_addr : src_addr + 256]
                    src_addr += 256
            disk.dirty = True
            cpu.A = 0
            cpu.F |= FLAG_C
        else:
            cpu.A = 0xFF
            cpu.F &= ~FLAG_C
        cpu.PC = cpu.pop_word()
        return True

    # C = 0x08: Read file descriptor from directory
    elif func == 0x08:
        file_idx = cpu.B
        dest_addr = cpu.HL
        if disk and hasattr(disk, 'raw_data') and file_idx < 128:
            offset = file_idx * 16
            memory[dest_addr : dest_addr + 16] = disk.raw_data[offset : offset + 16]
            cpu.A = 0
            cpu.F |= FLAG_C
        else:
            cpu.A = 0xFF
            cpu.F &= ~FLAG_C
        cpu.PC = cpu.pop_word()
        return True

    # Default / Command string execution
    ret_addr = cpu.pop_word()
    cmd_text = ""
    if ret_addr < 65530 and memory[ret_addr] == 0xEA: # REM token
        p = ret_addr + 1
        rem_bytes = []
        while p < 65536 and memory[p] not in (0x0D, 0x00):
            rem_bytes.append(memory[p])
            p += 1
        raw_cmd = bytes(rem_bytes).decode('latin-1', errors='ignore').strip()
        if raw_cmd.startswith(":"):
            raw_cmd = raw_cmd[1:].strip()
        cmd_text = raw_cmd
        ret_addr = p + (1 if p < 65536 and memory[p] == 0x0D else 0)

    if cmd_text:
        execute_trdos_command(cmd_text)
        cpu.A = 0
        cpu.F |= FLAG_C
    else:
        cpu.A = 0
        cpu.F |= FLAG_C

    cpu.PC = ret_addr
    return True


# -------------------------------------------------------------
# Hardware Port Handlers (WD1793, WD1770)
# -------------------------------------------------------------

def handle_wd1793_command(cmd):
    global wd1793_status, wd1793_command, wd1793_track, wd1793_sector, wd1793_data, wd1793_buf, wd1793_buf_pos
    global disk_drives, mgt_drives, memory
    wd1793_command = cmd & 0xFF
    c_type = cmd & 0xF0

    drv_idx = (memory[23756] & 3) + 1
    disk = get_trdos_disk(drv_idx)

    # Restore (Seek Track 0)
    if c_type == 0x00:
        wd1793_track = 0
        wd1793_status = 0x04 # Track 0 flag
    # Seek
    elif c_type == 0x10:
        wd1793_track = wd1793_data
        wd1793_status = 0x04 if wd1793_track == 0 else 0x00
    # Step / Step in / Step out
    elif c_type in (0x20, 0x30, 0x40, 0x50, 0x60, 0x70):
        if c_type in (0x40, 0x50): # Step In
            wd1793_track = min(79, wd1793_track + 1)
        elif c_type in (0x60, 0x70): # Step Out
            wd1793_track = max(0, wd1793_track - 1)
        wd1793_status = 0x04 if wd1793_track == 0 else 0x00
    # Read Sector
    elif c_type in (0x80, 0x90):
        wd1793_buf_pos = 0
        sec = max(0, min(15, wd1793_sector))
        trk = max(0, min(79, wd1793_track))
        if disk and hasattr(disk, 'raw_data'):
            off = (trk * 16 + sec) * 256
            if off + 256 <= len(disk.raw_data):
                wd1793_buf[:] = disk.raw_data[off : off + 256]
            else:
                wd1793_buf[:] = b'\x00' * 256
            wd1793_status = 0x03 # Busy + DRQ
        else:
            wd1793_status = 0x80 # Not ready
    # Write Sector
    elif c_type in (0xA0, 0xB0):
        wd1793_buf_pos = 0
        wd1793_status = 0x03 # Busy + DRQ
    # Force Interrupt
    elif c_type == 0xD0:
        wd1793_status = 0x04 if wd1793_track == 0 else 0x00


def handle_wd1793_data_write(val):
    global wd1793_data, wd1793_buf, wd1793_buf_pos, wd1793_status, wd1793_track, wd1793_sector
    global disk_drives, mgt_drives, memory
    wd1793_data = val & 0xFF
    if (wd1793_command & 0xE0) == 0xA0: # Write Sector active
        if wd1793_buf_pos < 256:
            wd1793_buf[wd1793_buf_pos] = val & 0xFF
            wd1793_buf_pos += 1
            if wd1793_buf_pos >= 256:
                drv_idx = (memory[23756] & 3) + 1
                disk = get_trdos_disk(drv_idx)
                if disk and hasattr(disk, 'raw_data'):
                    sec = max(0, min(15, wd1793_sector))
                    trk = max(0, min(79, wd1793_track))
                    off = (trk * 16 + sec) * 256
                    if off + 256 <= len(disk.raw_data):
                        disk.raw_data[off : off + 256] = wd1793_buf
                        disk.dirty = True
                wd1793_status = 0x00


def handle_wd1793_data_read():
    global wd1793_data, wd1793_buf, wd1793_buf_pos, wd1793_status
    if wd1793_buf_pos < 256:
        val = wd1793_buf[wd1793_buf_pos]
        wd1793_buf_pos += 1
        if wd1793_buf_pos >= 256:
            wd1793_status = 0x00
        return val
    return 0


def get_wd1793_status():
    global wd1793_status, wd1793_track
    st = wd1793_status
    if wd1793_track == 0:
        st |= 0x04 # Track 0 flag
    return st


def handle_wd1793_system_out(val):
    global wd1793_system_reg, memory
    wd1793_system_reg = val & 0xFF
    # Bits 0-1: Drive select (0=A, 1=B, 2=C, 3=D)
    new_drv = val & 3
    memory[23756] = new_drv


def handle_wd1770_command(cmd):
    global wd1770_status, wd1770_command, wd1770_track, wd1770_sector, wd1770_data, opus_buf, opus_buf_pos
    global disk_drives, mgt_drives, opus_drive_ctrl
    wd1770_command = cmd & 0xFF
    c_type = cmd & 0xF0

    drv_idx = (opus_drive_ctrl & 1) + 1
    disk = get_opus_disk(drv_idx)

    if c_type == 0x00: # Restore
        wd1770_track = 0
        wd1770_status = 0x04
    elif c_type == 0x10: # Seek
        wd1770_track = wd1770_data
        wd1770_status = 0x04 if wd1770_track == 0 else 0x00
    elif c_type in (0x80, 0x90): # Read Sector
        opus_buf_pos = 0
        sec = max(1, min(18, wd1770_sector))
        trk = max(0, min(39, wd1770_track))
        if disk and hasattr(disk, '_sector_offset'):
            off = disk._sector_offset(trk, sec)
            if off + 256 <= len(disk.raw_data):
                opus_buf[:] = disk.raw_data[off : off + 256]
            else:
                opus_buf[:] = b'\x00' * 256
            wd1770_status = 0x03
        else:
            wd1770_status = 0x80
    elif c_type in (0xA0, 0xB0): # Write Sector
        opus_buf_pos = 0
        wd1770_status = 0x03
    elif c_type == 0xD0: # Force Interrupt
        wd1770_status = 0x04 if wd1770_track == 0 else 0x00


def handle_wd1770_data_read():
    global opus_buf, opus_buf_pos, wd1770_status
    if opus_buf_pos < 256:
        val = opus_buf[opus_buf_pos]
        opus_buf_pos += 1
        if opus_buf_pos >= 256:
            wd1770_status = 0x00
        return val
    return 0


def get_wd1770_status():
    global wd1770_status, wd1770_track
    st = wd1770_status
    if wd1770_track == 0:
        st |= 0x04
    return st



class _WildcardByte:
    def __eq__(self, other): return True
