_REG_NAMES = {0: 'A', 1: 'F', 2: 'B', 3: 'C', 4: 'D', 5: 'E', 6: 'H', 7: 'L'}

_DEC_TABLE = tuple(tuple((
        v % 256,
        (v & 0xA8)
        + (v == 0) * 0x40
        + (v % 16 == 0x0F) * 0x10
        + (v == 0x7F) * 0x04
        + 0x02
        + c
    ) for v in range(-1, 255)
    ) for c in (0, 1)
)
DEC0 = _DEC_TABLE[0]

INC0 = tuple((
        v % 256,
        (v & 0xA8)
        + (v == 256) * 0x40
        + (v % 16 == 0x00) * 0x10
        + (v == 0x80) * 0x04
    ) for v in range(1, 257)
)


class UniversalTapePlayer:
    """Provides cycle-accurate EAR bit sampling (port 0xFE bit 6) and loop acceleration."""
    def __init__(self):
        self.edges = []
        self.blocks = []
        self.state = [0] * 10
        self.max_index = 0
        self.tape_path = None
        self.active = False
        self.accelerators = list(TAPE_ACCELERATORS.values())

    def attach(self, path):
        try:
            import skoolkit.loadtracer as lt
            import skoolkit.tap2sna as t2s
            self.tape_path = path
            ext = os.path.splitext(path)[1].lower()
            with open(path, "rb") as f:
                data = f.read()
            if ext == ".tzx":
                tape, raw_blks = t2s._get_tzx_blocks(data, True, 0, 0, (), True)
            elif ext == ".tap":
                tape, raw_blks = t2s._get_tap_blocks(data, True, 0, 0, (), True)
            elif ext == ".pzx":
                tape, raw_blks = t2s._get_pzx_blocks(data, True, 0, 0, (), True)
            else:
                return False
            blks = [b for b in raw_blks if getattr(b, 'timings', None) is not None]
            for b in blks:
                b.keys = None
            self.edges, self.blocks = lt.get_edges(blks, 0, 0)
            self.max_index = len(self.edges) - 1
            self.state = [0, 0, 0, self.blocks[0].end if self.blocks else 0, 1, 0, 0, 1, 0, 0]
            self.active = True
            return True
        except Exception:
            self.active = False
            return False

    def sample_ear(self, cpu):
        if not self.active or not self.edges:
            return 1
        tstates = getattr(cpu, 'cycles', 0)
        index = self.state[1]
        while index < self.max_index and self.edges[index + 1] < tstates:
            index += 1
        self.state[1] = index
        if index >= self.max_index:
            self.active = False
            return 1
        pc = cpu.PC
        if not cpu.IFF1 and self.blocks and index < self.state[3] - 1:
            for i, acc in enumerate(self.accelerators):
                c0 = acc[2]
                code = acc[1]
                match = True
                mem = cpu.memory
                for offset, expected in enumerate(code):
                    addr = (pc - c0 + offset) & 0xFFFF
                    if expected is not BYTE and mem[addr] != expected:
                        match = False
                        break
                if match:
                    ear_mask = acc[8]
                    polarity = acc[9]
                    ear_reg_name = _REG_NAMES.get(acc[4], 'A')
                    ear_reg_val = getattr(cpu, ear_reg_name, 0)
                    if ear_mask:
                        ffwd = (ear_reg_val & ear_mask) == (((index - polarity) % 2) * ear_mask)
                    else:
                        ffwd = (index - polarity) % 2
                    next_edge = self.edges[index + 1]
                    if ffwd and next_edge > cpu.cycles:
                        counter_idx = acc[7]
                        cnt_name = _REG_NAMES.get(counter_idx, 'B')
                        counter = getattr(cpu, cnt_name, 0)
                        loop_time = acc[5]
                        inc = (acc[0] in ('activision', 'audiogenic-0', 'audiogenic-1', 'gremlin2-0', 'gremlin2-1'))
                        loops = min((next_edge - cpu.cycles) // loop_time + 1, (255 - counter) if inc else (counter - 1))
                        if loops > 0:
                            if inc:
                                new_val, new_f = INC0[min(256, counter + loops - 1)]
                            else:
                                new_val, new_f = DEC0[max(0, counter - loops + 1)]
                            setattr(cpu, cnt_name, new_val)
                            cpu.F = new_f
                            cpu.R = (cpu.R & 0x80) | ((cpu.R + acc[6] * loops) & 0x7F)
                            cpu.cycles += loop_time * loops
                            if cpu.cycles > next_edge:
                                self.state[1] = min(self.max_index, index + 1)
                    if i > 0:
                        self.accelerators.insert(0, self.accelerators.pop(i))
                    break
        return 0 if (self.state[1] % 2 == 0) else 1


universal_tape_player = UniversalTapePlayer()


def run_simulated_tape_load(path, mode="RUN"):
    """Universally simulates fast tape loading for Speedlock, Alkatraz, Bleepload, and all custom loaders."""
    import tempfile
    try:
        import skoolkit.tap2sna
        import skoolkit.snapshot as ss
        if not getattr(skoolkit.tap2sna, '_basinpy_patched', False):
            _orig_get_tapes = skoolkit.tap2sna._get_tapes
            def _safe_get_tapes(urls, user_agent, members):
                from urllib.parse import urlparse
                import zipfile
                tapes = []
                remote_urls = []
                for u in urls:
                    parsed = urlparse(u)
                    is_local = (len(parsed.scheme) == 1 and parsed.scheme.isalpha()) or os.path.exists(u)
                    if is_local:
                        if u.lower().endswith('.zip'):
                            with open(u, 'rb') as f:
                                z = zipfile.ZipFile(f)
                                mems = members
                                if not mems:
                                    for name in z.namelist():
                                        if name.lower().endswith(('.pzx', '.tap', '.tzx')):
                                            mems = [name]
                                            break
                                for member in (mems or []):
                                    tape = z.open(member)
                                    tapes.append((member, tape.read()))
                        else:
                            with open(u, 'rb') as f:
                                tapes.append((os.path.basename(u), f.read()))
                    else:
                        remote_urls.append(u)
                if remote_urls:
                    tapes.extend(_orig_get_tapes(remote_urls, user_agent, members))
                return tapes
            skoolkit.tap2sna._get_tapes = _safe_get_tapes
            skoolkit.tap2sna._basinpy_patched = True
    except Exception as e:
        if not is_execution_mode():
            canvas_print(f"Fast tape loader unavailable: {e}")
        return False

    with tempfile.NamedTemporaryFile(suffix='.szx', delete=False) as tmp:
        szx_path = tmp.name
    try:
        if not is_execution_mode():
            canvas_print(f"Loading {os.path.basename(path)} via fast tape simulator...")
            if 'update_display' in globals():
                update_display()
        tap_arg = path
        try:
            if os.path.exists(path):
                tap_arg = os.path.relpath(path)
        except Exception:
            tap_arg = path
        skoolkit.tap2sna.main(['--sim-load-config', 'accelerator=auto', tap_arg, szx_path])
        with open(szx_path, 'rb') as f:
            szx_data = f.read()
        szx = ss.SZX(szx_data)

        global memory, current_border, canvas_dirty, last_loaded_screen_bytes, attached_tape_path
        global program, _z80_compiled_blocks, program_line_order
        global last_7ffd_val, last_1ffd_val, paging_locked, attached_load_source, current_rom_bank
        attached_tape_path = path
        last_7ffd_val = 0
        last_1ffd_val = 0
        current_rom_bank = 3
        paging_locked = False
        ram_bytes = bytes(szx.ram())
        memory[16384 : 16384 + len(ram_bytes)] = ram_bytes

        current_border = szx.border
        last_loaded_screen_bytes = bytes(ram_bytes[:6912])
        if 'load_screen_bytes' in globals():
            load_screen_bytes(last_loaded_screen_bytes)

        cpu = get_z80_cpu()
        cpu.A = szx.a
        cpu.F = szx.f
        cpu.B = (szx.bc >> 8) & 0xFF
        cpu.C = szx.bc & 0xFF
        cpu.D = (szx.de >> 8) & 0xFF
        cpu.E = szx.de & 0xFF
        cpu.H = (szx.hl >> 8) & 0xFF
        cpu.L = szx.hl & 0xFF

        cpu.A_prime = szx.a2
        cpu.F_prime = szx.f2
        cpu.B_prime = (szx.bc2 >> 8) & 0xFF
        cpu.C_prime = szx.bc2 & 0xFF
        cpu.D_prime = (szx.de2 >> 8) & 0xFF
        cpu.E_prime = szx.de2 & 0xFF
        cpu.H_prime = (szx.hl2 >> 8) & 0xFF
        cpu.L_prime = szx.hl2 & 0xFF

        cpu.IX = szx.ix
        cpu.IY = szx.iy
        cpu.SP = szx.sp
        cpu.PC = szx.pc
        cpu.I = szx.i
        cpu.R = szx.r
        cpu.IFF1 = bool(szx.iff1)
        cpu.IFF2 = bool(szx.iff2)
        cpu.IM = szx.im
        cpu.halted = False
        cpu.user_quit = False
        cpu.suspended_by_break = False

        if 'basic_rom_backup' in globals() and basic_rom_backup:
            memory[0:16384] = basic_rom_backup[:16384]
        elif 'ZX_48K_ROM' in globals() and ZX_48K_ROM:
            memory[0:16384] = ZX_48K_ROM[:16384]
        memory[15616 : 15616 + 768] = ZX_ROM_FONT

        # If PC stopped in ROM return routine (e.g. 0x053F LD-BYTES return), step until entry to RAM
        steps = 0
        while cpu.PC < 0x4000 and steps < 100 and not cpu.halted:
            cyc = cpu.step()
            cpu.cycles += cyc
            steps += 1

        # The machine code game is now in RAM; clear any bootstrap BASIC loader to prevent anti-tamper tripwires
        if 'program' in globals():
            program.clear()
        if '_z80_compiled_blocks' in globals():
            _z80_compiled_blocks.clear()
        if 'program_line_order' in globals():
            program_line_order.clear()

        # Auto-bypass Lenslok copy protection (e.g. Elite) so game boots directly into game/title screen
        if memory[0xD07C:0xD07F] == b'\xCD\x13\xC2':
            memory[0xD07C:0xD07F] = b'\x00\x00\x00'
            if hasattr(cpu, 'memory'):
                cpu.memory[0xD07C:0xD07F] = b'\x00\x00\x00'
        if memory[0xC213:0xC217] == b'\xDD\x21\xB6\xC7':
            memory[0xC213] = 0xC9
            if hasattr(cpu, 'memory'):
                cpu.memory[0xC213] = 0xC9

        # Fix Alkatraz copy protection loader off-by-one overwrite of RET at 0xFBE7 (e.g. 10th Frame)
        if memory[0xFBDA:0xFBE0] == b'\x21\x1F\xFA\x11\x20\xFA' and memory[0xFBE3:0xFBE7] == b'\x36\x00\xED\xB0':
            memory[0xFBE1] = 0xC7
            memory[0xFBE7] = 0xC9
            if hasattr(cpu, 'memory'):
                cpu.memory[0xFBE1] = 0xC7
                cpu.memory[0xFBE7] = 0xC9
            if 0xFBE8 <= cpu.PC <= 0xFC3F and memory[0x5B00:0x5B0A] == b'\x21\x1B\xF7\x11\x03\xFB\x01\x68\x97\xED':
                cpu.PC = 0x5B00
                cpu.SP = 0xFA1B

        # Bypass Speedlock 1-6 pilot-tone timing check.
        # After tap2sna fast-loads the standard blocks, Speedlock 1-6 resides in RAM.
        # Its pilot-tone length check uses a branch (JR NZ / JP NZ) that will always
        # fail in emulation because the emulated pilot tone never has hardware-exact
        # timing.  We detect the loader by its EAR-read loop signature and NOP the
        # timing-check branch so the Strategy 3 TZX reattach can feed data normally.
        # Signature: the byte sequence  3E xx DB FE 1F A9 E6 20 28 xx  appears in RAM
        # somewhere in 0x8000-0xFF00 range.  The two bytes *before* the 3E are the
        # JR / JP NZ that we want to replace with 00 00.
        try:
            _sl_sig = bytes([0x3E])  # IN A,(0xFE); RRA; XOR B; AND 0x20; JR Z
            _sl_tail = bytes([0xDB, 0xFE, 0x1F, 0xA9, 0xE6, 0x20, 0x28])
            for _sl_addr in range(0x8000, 0xFF00 - 16):
                if (memory[_sl_addr] == 0x3E and
                        memory[_sl_addr + 2 : _sl_addr + 9] == _sl_tail):
                    # Found EAR loop — check the two bytes before for a conditional jump
                    _pre = _sl_addr - 2
                    if _pre >= 0x8000 and memory[_pre] in (0x20, 0xC2, 0xCA):
                        # NOP the timing-check branch (JR NZ offset  →  NOP NOP)
                        memory[_pre] = 0x00
                        memory[_pre + 1] = 0x00
                        if hasattr(cpu, 'memory'):
                            cpu.memory[_pre] = 0x00
                            cpu.memory[_pre + 1] = 0x00
                        break
        except Exception:
            pass

        # Fix Bubble Bobble machine detection on 48K Spectrum (uncontended ULA emulation):
        # Bubble Bobble runs a timing loop at 0xFAD0 counting iterations between frame interrupts
        # on ($5C78). On real 48K hardware, memory contention in 0x4000..0x7FFF delays ($5C78)
        # reads so BC lands on B=7, C=0x5E or 0x63, detecting 48K. Without ULA contention, BC
        # reaches B=7, C=0xC4, causing Bubble Bobble to misidentify the machine as 128K. It then
        # executes 128K memory paging via port 0x7FFD and copies screen data to 0xC350..0xD264.
        # In 48K mode (where port 0x7FFD does not page Bank 1), this overwrites 48K RAM at
        # 0xC780..0xC900, corrupting the bubble sprites and enemy sprites.
        # Force 48K detection when running in 48K mode so the 128K overwrite is cleanly skipped.
        if not globals().get('spectrum_128k_mode', False):
            if memory[0x9695:0x969F] == b'\x08\xFE\x80\x28\x0B\x3E\xC9\x32\xC4\x8D':
                memory[0x9698:0x969A] = b'\x00\x00'
                if hasattr(cpu, 'memory'):
                    cpu.memory[0x9698:0x969A] = b'\x00\x00'

        # Multi-side tape: after fast-loading Side 1, re-attach the tape player to Side 2
        # so the in-game loader can stream it via the EAR bit (e.g. Daley Thompson's Olympic Challenge).
        try:
            import re as _re
            _tape_dir = os.path.dirname(os.path.abspath(path))
            _side2_path = None
            _basename = os.path.basename(path)
            _is_explicit_side1 = bool(_re.search(r'(?i)side[\s_-]*1', _basename))
            if _is_explicit_side1:
                # Strategy 1: replace "side 1" / "side1" with "side 2" / "side2" in the filename
                _s2_name = _re.sub(r'(?i)side[\s_-]*1', lambda m: m.group().replace('1', '2').replace('1', '2'), _basename)
                if _s2_name != _basename:
                    _candidate = os.path.join(_tape_dir, _s2_name)
                    if os.path.exists(_candidate):
                        _side2_path = _candidate
                # Strategy 2: scan the directory for any file containing "side 2" / "side2"
                if _side2_path is None:
                    for _fn in sorted(os.listdir(_tape_dir)):
                        if _re.search(r'(?i)side[\s_-]*2', _fn) and _fn.lower().endswith(('.tzx', '.tap', '.pzx')):
                            _side2_path = os.path.join(_tape_dir, _fn)
                            break
            # Strategy 3: if the current TZX itself has non-standard blocks (Bleepload, Speedlock,
            # Turbo, PureTone, PureData) beyond the initial ROM-speed blocks, build a stripped
            # TZX containing ONLY those non-standard blocks and attach it to the tape player.
            #
            # IMPORTANT: we must NOT attach the full TZX from block 0.  The ROM-speed standard
            # blocks (BASIC header, code) that tap2sna already fast-loaded have pilot tones with
            # almost identical pulse lengths to Bleepload/Speedlock pilots.  If the in-game loader
            # sees those ROM-speed edges first it mistakes them for its own pilot, then reads the
            # wrong data bytes → corrupt graphics (Bubble Bobble) or garbled screen (Batman).
            #
            # Solution: scan to the first non-standard block, write header + remaining data to a
            # temp TZX, attach that.  The in-game loader then sees its own pilot immediately.
            if _side2_path is None and path.lower().endswith('.tzx') and 'universal_tape_player' in globals():
                try:
                    import struct as _struct, tempfile as _tempfile
                    with open(path, 'rb') as _tzf:
                        _tzd = _tzf.read()
                    _tzp = 10  # skip 10-byte TZX header
                    _nonstandard_offset = None
                    while _tzp < len(_tzd):
                        _blk_start = _tzp          # remember start of this block
                        _bid = _tzd[_tzp]; _tzp += 1
                        if _bid == 0x10:            # Standard Speed Data — already fast-loaded
                            _dlen = _struct.unpack_from('<H', _tzd, _tzp + 2)[0]
                            _tzp += 4 + _dlen
                        elif _bid in (0x11, 0x12, 0x13, 0x14):  # Turbo / PureTone / PulseSeq / PureData
                            _nonstandard_offset = _blk_start     # first custom-loader block
                            break
                        elif _bid == 0x20: _tzp += 2
                        elif _bid == 0x21: _tzp += 1 + _tzd[_tzp]
                        elif _bid == 0x22: pass
                        elif _bid == 0x24: _tzp += 2
                        elif _bid == 0x25: pass
                        elif _bid == 0x2A: _tzp += 4
                        elif _bid == 0x30: _tzp += 1 + _tzd[_tzp]
                        elif _bid == 0x31: _tzp += 2 + _tzd[_tzp + 1]
                        elif _bid == 0x32: _tzp += 2 + _struct.unpack_from('<H', _tzd, _tzp)[0]
                        elif _bid == 0x33: _tzp += 1 + _tzd[_tzp] * 3
                        elif _bid == 0x5A: _tzp += 9
                        else: break
                    if _nonstandard_offset is not None:
                        # Write a stripped TZX: standard 10-byte header + custom blocks only
                        _tzx_hdr = b'ZXTape!\x1a\x01\x14'
                        _stripped = _tzx_hdr + _tzd[_nonstandard_offset:]
                        _tmp = _tempfile.NamedTemporaryFile(
                            suffix='.tzx', delete=False,
                            dir=_tempfile.gettempdir())
                        _tmp.write(_stripped)
                        _tmp.close()
                        universal_tape_player.attach(_tmp.name)
                except Exception:
                    pass
            if _side2_path and 'universal_tape_player' in globals():
                universal_tape_player.attach(_side2_path)
            elif _is_explicit_side1 and _side2_path is None and not (universal_tape_player.active if 'universal_tape_player' in globals() else False):
                # Auto-detect found nothing — prompt the user interactively
                _is_dummy = (os.environ.get("SDL_VIDEODRIVER") == "dummy") or not globals().get('running', False)
                if not _is_dummy:
                    _game_name = os.path.splitext(os.path.basename(path))[0]
                    _game_name = _re.sub(r'(?i)\s*[-_]?\s*side[\s_-]*1\s*$', '', _game_name).strip()
                    _src = globals().get('attached_load_source', None)
                    if _src == 'ZXDB' and 'launch_zxdb_browser_for_side2' in globals():
                        if 'canvas_print' in globals():
                            canvas_print(f"Insert Side 2 — searching ZXDB for '{_game_name}'...")
                        if 'update_display' in globals():
                            update_display()
                        launch_zxdb_browser_for_side2(_game_name)
                    else:
                        if 'canvas_print' in globals():
                            canvas_print("Insert Side 2 — please select the Side 2 tape file...")
                        if 'update_display' in globals():
                            update_display()
                        if 'ask_open_filename' in globals():
                            _chosen = ask_open_filename(
                                title=f"Select Side 2 tape for {_game_name}",
                                filetypes=[
                                    ("Spectrum Tape", "*.tzx *.tap *.pzx *.zip"),
                                    ("All files", "*.*"),
                                ],
                            )
                            if _chosen:
                                _ext2 = os.path.splitext(_chosen)[1].lower()
                                if _ext2 == '.zip':
                                    try:
                                        import zipfile as _zf3
                                        with _zf3.ZipFile(_chosen) as _zobj3:
                                            for _nm3 in _zobj3.namelist():
                                                if _nm3.lower().endswith(('.tzx', '.tap', '.pzx')):
                                                    _out3 = os.path.join(_tape_dir, os.path.basename(_nm3))
                                                    with open(_out3, 'wb') as _fo3:
                                                        _fo3.write(_zobj3.read(_nm3))
                                                    _chosen = _out3
                                                    break
                                    except Exception:
                                        pass
                                if 'universal_tape_player' in globals():
                                    universal_tape_player.attach(_chosen)
        except Exception:
            pass

        canvas_dirty = True
        if 'redraw_canvas' in globals():
            redraw_canvas(force=True)
        if 'update_display' in globals():
            update_display()
        if 'pygame' in globals() and pygame.display.get_init() and not is_execution_mode() and os.environ.get("SDL_VIDEODRIVER") != "dummy":
            pygame.time.delay(1200)

        if (autorun_enabled or mode.upper() == "RUN" or (cpu.PC is not None and cpu.PC >= 0x4000)) and cpu.PC is not None:
            run_loaded_snapshot(cpu)
        elif not is_execution_mode():
            canvas_print(f"Loaded {os.path.basename(path)} (Type RUN to play)")
            update_display()
        return True
    except Exception as e:
        if not is_execution_mode():
            canvas_print(f"Simulated load error: {e}")
        return False
    finally:
        if os.path.exists(szx_path):
            try:
                os.remove(szx_path)
            except Exception:
                pass


class TZXReader:
    """Parses standard, turbo, pure data, and metadata blocks from .TZX tape images."""
    def __init__(self, data):
        if not data.startswith(b"ZXTape!\x1A"):
            raise ValueError("Not a valid TZX tape image")
        self.major = data[8]
        self.minor = data[9]
        self.raw_blocks = []  # list of (flag, payload_bytes)
        self.pure_data_blocks = []  # list of bytes
        self.turbo_blocks = []  # list of bytes
        self.text_info = []
        self._parse(data[10:])

    def _parse(self, body):
        pos = 0
        n = len(body)
        while pos < n:
            btype = body[pos]
            pos += 1
            if btype == 0x10:  # Standard Speed Data Block
                if pos + 4 > n:
                    break
                pause_ms = body[pos] | (body[pos+1] << 8)
                dlen = body[pos+2] | (body[pos+3] << 8)
                pos += 4
                blk = body[pos : pos + dlen]
                pos += dlen
                if len(blk) > 0:
                    flag = blk[0]
                    payload = blk[1:-1] if len(blk) > 1 else b""
                    self.raw_blocks.append((flag, bytes(payload)))
            elif btype == 0x11:  # Turbo Speed Data Block (18-byte header)
                if pos + 18 > n:
                    break
                pause_ms = body[pos+13] | (body[pos+14] << 8)
                dlen = body[pos+15] | (body[pos+16] << 8) | (body[pos+17] << 16)
                pos += 18
                blk = body[pos : pos + dlen]
                pos += dlen
                self.turbo_blocks.append(bytes(blk))
                if len(blk) > 0:
                    flag = blk[0]
                    payload = blk[1:]
                    self.raw_blocks.append((flag, bytes(payload)))
            elif btype == 0x12:  # Pure Tone
                pos += 4
            elif btype == 0x13:  # Pulse Sequence
                if pos < n:
                    pcount = body[pos]
                    pos += 1 + pcount * 2
            elif btype == 0x14:  # Pure Data Block
                if pos + 10 > n:
                    break
                dlen = body[pos+7] | (body[pos+8] << 8) | (body[pos+9] << 16)
                pos += 10
                blk = body[pos : pos + dlen]
                pos += dlen
                self.pure_data_blocks.append(bytes(blk))
                self.raw_blocks.append((255, bytes(blk)))
            elif btype == 0x15:  # Direct Recording
                if pos + 8 <= n:
                    dlen = body[pos+5] | (body[pos+6] << 8) | (body[pos+7] << 16)
                    pos += 8 + dlen
                else: break
            elif btype in (0x18, 0x19):  # CSW Recording / Generalized Data
                if pos + 4 <= n:
                    blen = body[pos] | (body[pos+1] << 8) | (body[pos+2] << 16) | (body[pos+3] << 24)
                    pos += 4 + blen
                else: break
            elif btype == 0x20:  # Pause / Stop the Tape
                pos += 2
            elif btype == 0x21:  # Group Start
                if pos < n:
                    glen = body[pos]
                    pos += 1 + glen
            elif btype == 0x22:  # Group End
                pass
            elif btype in (0x23, 0x24):  # Jump to block / Loop start
                pos += 2
            elif btype == 0x25:  # Loop end
                pass
            elif btype == 0x26:  # Call sequence
                if pos + 2 <= n:
                    num_calls = body[pos] | (body[pos+1] << 8)
                    pos += 2 + num_calls * 2
                else: break
            elif btype == 0x27:  # Return from sequence
                pass
            elif btype in (0x28, 0x2A):  # Select block / Stop in 48K
                if pos + 2 <= n:
                    if btype == 0x28:
                        blen = body[pos] | (body[pos+1] << 8)
                        pos += 2 + blen
                    else:
                        blen = body[pos] | (body[pos+1] << 8) | (body[pos+2] << 16) | (body[pos+3] << 24)
                        pos += 4 + blen
                else: break
            elif btype == 0x30:  # Text Description
                if pos < n:
                    tlen = body[pos]
                    pos += 1
                    txt = body[pos : pos + tlen].decode('latin-1', errors='ignore')
                    pos += tlen
                    self.text_info.append(txt)
            elif btype == 0x31:  # Message block
                if pos + 2 <= n:
                    mlen = body[pos+1]
                    pos += 2 + mlen
                else: break
            elif btype == 0x32:  # Archive Info
                if pos + 2 <= n:
                    blk_len = body[pos] | (body[pos+1] << 8)
                    pos += 2 + blk_len
                else: break
            elif btype == 0x33:  # Hardware type
                if pos < n:
                    num = body[pos]
                    pos += 1 + num * 3
                else: break
            elif btype == 0x35:  # Custom info block
                if pos + 20 <= n:
                    blen = body[pos+16] | (body[pos+17] << 8) | (body[pos+18] << 16) | (body[pos+19] << 24)
                    pos += 20 + blen
                else: break
            else:
                break


def parse_sna(data):
    """Parses a Sinclair .SNA snapshot (48K or 128K)."""
    if len(data) < 49179:
        raise ValueError(f"SNA snapshot too small ({len(data)} bytes, expected at least 49179)")

    hdr = data[:27]
    i_reg = hdr[0]
    hl_p = hdr[1] | (hdr[2] << 8)
    de_p = hdr[3] | (hdr[4] << 8)
    bc_p = hdr[5] | (hdr[6] << 8)
    af_p = hdr[7] | (hdr[8] << 8)
    hl = hdr[9] | (hdr[10] << 8)
    de = hdr[11] | (hdr[12] << 8)
    bc = hdr[13] | (hdr[14] << 8)
    iy = hdr[15] | (hdr[16] << 8)
    ix = hdr[17] | (hdr[18] << 8)
    iff2 = bool((hdr[19] >> 2) & 1)
    r_reg = hdr[20]
    af = hdr[21] | (hdr[22] << 8)
    sp = hdr[23] | (hdr[24] << 8)
    im = hdr[25] & 3
    border = hdr[26] & 7

    ram_48k = bytearray(data[27 : 27 + 49152])
    is_128k = len(data) >= 131103

    if not is_128k:
        sp_offset = (sp - 16384) & 0xFFFF
        if 0 <= sp_offset < len(ram_48k) - 1:
            pc = ram_48k[sp_offset] | (ram_48k[sp_offset + 1] << 8)
            sp = (sp + 2) & 0xFFFF
        else:
            pc = 0x0000
        port_7ffd = 0
        extra_banks = {}
    else:
        pc = data[27 + 49152] | (data[27 + 49153] << 8)
        port_7ffd = data[27 + 49154]
        extra_banks = {}
        bank_offset = 27 + 49156
        bank_idx = 0
        while bank_offset + 16384 <= len(data) and bank_idx < 5:
            extra_banks[bank_idx] = data[bank_offset : bank_offset + 16384]
            bank_offset += 16384
            bank_idx += 1

    return {
        "is_128k": is_128k,
        "AF": af, "BC": bc, "DE": de, "HL": hl,
        "AF_prime": af_p, "BC_prime": bc_p, "DE_prime": de_p, "HL_prime": hl_p,
        "IX": ix, "IY": iy,
        "PC": pc, "SP": sp,
        "I": i_reg, "R": r_reg,
        "IFF1": iff2, "IFF2": iff2, "IM": im,
        "border": border,
        "ram": ram_48k,
        "port_7ffd": port_7ffd,
        "extra_banks": extra_banks
    }


def run_loaded_snapshot(cpu):
    """Executes a loaded .Z80 or .SNA snapshot with authentic Sinclair Spectrum 48K state."""
    global program_execution_mode, canvas_dirty, current_border, last_loaded_code_addr
    global last_7ffd_val, last_1ffd_val, paging_locked, current_rom_bank
    last_7ffd_val = 0
    last_1ffd_val = 0
    current_rom_bank = 3
    paging_locked = False
    last_loaded_code_addr = None
    if 'basic_rom_backup' in globals() and basic_rom_backup:
        memory[0:16384] = basic_rom_backup
    elif 'ZX_48K_ROM' in globals() and ZX_48K_ROM:
        memory[0:16384] = ZX_48K_ROM
    memory[15616 : 15616 + 768] = ZX_ROM_FONT

    for r in range(24):
        for c in range(32):
            if 'screen_chars' in globals() and screen_chars:
                screen_chars[r][c] = ' '
            if 'cell_bitmap' in globals() and cell_bitmap:
                cell_bitmap[r][c] = None

    sync_from_screen_memory()
    prev_mode = program_execution_mode
    program_execution_mode = True
    canvas_dirty = True
    if 'redraw_canvas' in globals():
        redraw_canvas(force=True)
    if 'update_display' in globals():
        update_display()
    prev_traps = getattr(cpu, 'rom_traps_enabled', True)
    cpu.rom_traps_enabled = False

    # Auto-bypass Lenslok copy protection (e.g. Elite) so game boots directly into game/title screen
    if memory[0xD07C:0xD07F] == b'\xCD\x13\xC2':
        memory[0xD07C:0xD07F] = b'\x00\x00\x00'
        if hasattr(cpu, 'memory'):
            cpu.memory[0xD07C:0xD07F] = b'\x00\x00\x00'
    if memory[0xC213:0xC217] == b'\xDD\x21\xB6\xC7':
        memory[0xC213] = 0xC9
        if hasattr(cpu, 'memory'):
            cpu.memory[0xC213] = 0xC9
    # Fix Alkatraz copy protection loader off-by-one overwrite of RET at 0xFBE7 (e.g. 10th Frame)
    if memory[0xFBDA:0xFBE0] == b'\x21\x1F\xFA\x11\x20\xFA' and memory[0xFBE3:0xFBE7] == b'\x36\x00\xED\xB0':
        memory[0xFBE1] = 0xC7
        memory[0xFBE7] = 0xC9
        if hasattr(cpu, 'memory'):
            cpu.memory[0xFBE1] = 0xC7
            cpu.memory[0xFBE7] = 0xC9
        if 0xFBE8 <= cpu.PC <= 0xFC3F and memory[0x5B00:0x5B0A] == b'\x21\x1B\xF7\x11\x03\xFB\x01\x68\x97\xED':
            cpu.PC = 0x5B00
            cpu.SP = 0xFA1B
    if 'zx_beeper_audio' in globals() and zx_beeper_audio is not None:
        zx_beeper_audio.reset()
    try:
        cpu.run(stop_on_ret=False)
    except Exception as e:
        canvas_print(f"Snapshot execution error: {e}")
    finally:
        if 'zx_beeper_audio' in globals() and zx_beeper_audio is not None:
            zx_beeper_audio.reset()
        cpu.rom_traps_enabled = prev_traps
        program_execution_mode = prev_mode
        if getattr(cpu, 'suspended_by_break', False):
            cpu.suspended_by_break = False
            canvas_print("Break into program")
        canvas_dirty = True
        if 'redraw_canvas' in globals():
            redraw_canvas(force=True)
        if 'update_display' in globals():
            update_display()


def load_sna_snapshot(path):
    global memory, current_border, canvas_dirty, spectrum_128k_mode, paging_locked, last_7ffd_val, current_ram_bank, ram_banks
    cpu = get_z80_cpu()
    with open(path, "rb") as f:
        data = f.read()
    snap = parse_sna(data)

    if snap.get("is_128k", False):
        spectrum_128k_mode = True
        port_7ffd = snap.get("port_7ffd", 0)
        last_7ffd_val = port_7ffd
        paging_locked = bool(port_7ffd & 0x20)
        for b_idx, b_data in snap.get("extra_banks", {}).items():
            if 0 <= b_idx < 8:
                ram_banks[b_idx][:len(b_data)] = b_data
        select_ram_bank(port_7ffd & 0x07)
    else:
        spectrum_128k_mode = False
        paging_locked = True
        last_7ffd_val = 0
        current_ram_bank = 0
        select_ram_bank(0)

    ram_data = snap["ram"]
    memory[16384 : 16384 + len(ram_data)] = ram_data
    current_border = snap["border"]

    cpu.A = (snap["AF"] >> 8) & 0xFF
    cpu.F = snap["AF"] & 0xFF
    cpu.B = (snap["BC"] >> 8) & 0xFF
    cpu.C = snap["BC"] & 0xFF
    cpu.D = (snap["DE"] >> 8) & 0xFF
    cpu.E = snap["DE"] & 0xFF
    cpu.H = (snap["HL"] >> 8) & 0xFF
    cpu.L = snap["HL"] & 0xFF

    cpu.A_prime = (snap["AF_prime"] >> 8) & 0xFF
    cpu.F_prime = snap["AF_prime"] & 0xFF
    cpu.B_prime = (snap["BC_prime"] >> 8) & 0xFF
    cpu.C_prime = snap["BC_prime"] & 0xFF
    cpu.D_prime = (snap["DE_prime"] >> 8) & 0xFF
    cpu.E_prime = snap["DE_prime"] & 0xFF
    cpu.H_prime = (snap["HL_prime"] >> 8) & 0xFF
    cpu.L_prime = snap["HL_prime"] & 0xFF

    cpu.IX = snap["IX"]
    cpu.IY = snap["IY"]
    cpu.SP = snap["SP"]
    cpu.PC = snap["PC"]
    cpu.I = snap["I"]
    cpu.R = snap["R"]
    cpu.IFF1 = snap["IFF1"]
    cpu.IFF2 = snap["IFF2"]
    cpu.IM = snap["IM"]

    load_screen_bytes(bytes(ram_data[:6912]))
    canvas_dirty = True
    redraw_canvas()
    update_display()

    if cpu.PC is not None and autorun_enabled:
        run_loaded_snapshot(cpu)


def decompress_z80_block(data):
    """Decompresses a standard Z80 RLE block."""
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        if i + 3 < n and data[i] == 0xED and data[i+1] == 0xED:
            count = data[i+2]
            val = data[i+3]
            out.extend([val] * count)
            i += 4
        else:
            out.append(data[i])
            i += 1
    return out


def parse_z80(data):
    """Parses .Z80 snapshot (v1, v2, and v3)."""
    if len(data) < 30:
        raise ValueError("Z80 file too small for header")

    hdr = data[:30]
    a = hdr[0]; f = hdr[1]
    bc = hdr[2] | (hdr[3] << 8)
    hl = hdr[4] | (hdr[5] << 8)
    pc = hdr[6] | (hdr[7] << 8)
    sp = hdr[8] | (hdr[9] << 8)
    i_reg = hdr[10]
    r_reg = (hdr[11] & 0x7F) | ((hdr[12] & 1) << 7)
    byte12 = hdr[12]
    border = (byte12 >> 1) & 7
    compressed = bool((byte12 >> 5) & 1)
    de = hdr[13] | (hdr[14] << 8)
    bc_p = hdr[15] | (hdr[16] << 8)
    de_p = hdr[17] | (hdr[18] << 8)
    hl_p = hdr[19] | (hdr[20] << 8)
    a_p = hdr[21]; f_p = hdr[22]
    iy = hdr[23] | (hdr[24] << 8)
    ix = hdr[25] | (hdr[26] << 8)
    iff1 = bool(hdr[27])
    iff2 = bool(hdr[28])
    im = hdr[29] & 3

    ram_pages = {}
    is_128k = False
    port_7ffd = 0

    if pc != 0:
        body = data[30:]
        if compressed:
            if body.endswith(b"\x00\xED\xED\x00"):
                body = body[:-4]
            decomp = decompress_z80_block(body)
        else:
            decomp = body
        full_ram = bytearray(49152)
        full_ram[:min(len(decomp), 49152)] = decomp[:49152]
    else:
        extra_len = data[30] | (data[31] << 8)
        pc = data[32] | (data[33] << 8)
        hw_mode = data[34]
        port_7ffd = data[35]
        is_128k = (hw_mode in (3, 4, 7, 8) if extra_len >= 54 else hw_mode >= 3)
        pos = 32 + extra_len

        full_ram = bytearray(49152)
        while pos + 3 <= len(data):
            blk_len = data[pos] | (data[pos+1] << 8)
            page_id = data[pos+2]
            pos += 3
            if blk_len == 0xFFFF:
                blk_data = data[pos : pos + 16384]
                pos += 16384
            else:
                raw_chunk = data[pos : pos + blk_len]
                pos += blk_len
                blk_data = decompress_z80_block(raw_chunk)

            ram_pages[page_id] = blk_data
            if page_id == 8:
                full_ram[0:16384] = blk_data[:16384]
            elif page_id == 4:
                full_ram[16384:32768] = blk_data[:16384]
            elif page_id == 5:
                full_ram[32768:49152] = blk_data[:16384]

    return {
        "is_128k": is_128k,
        "AF": (a << 8) | f, "BC": bc, "DE": de, "HL": hl,
        "AF_prime": (a_p << 8) | f_p, "BC_prime": bc_p, "DE_prime": de_p, "HL_prime": hl_p,
        "IX": ix, "IY": iy,
        "PC": pc, "SP": sp,
        "I": i_reg, "R": r_reg,
        "IFF1": iff1, "IFF2": iff2, "IM": im,
        "border": border,
        "ram": full_ram,
        "pages": ram_pages,
        "port_7ffd": port_7ffd
    }


def load_z80_snapshot(path):
    global memory, current_border, canvas_dirty, spectrum_128k_mode, paging_locked, last_7ffd_val, current_ram_bank, ram_banks
    cpu = get_z80_cpu()
    with open(path, "rb") as f:
        data = f.read()
    snap = parse_z80(data)

    if snap.get("is_128k", False):
        spectrum_128k_mode = True
        port_7ffd = snap.get("port_7ffd", 0)
        last_7ffd_val = port_7ffd
        paging_locked = bool(port_7ffd & 0x20)
        for pid, pdata in snap.get("pages", {}).items():
            bank_idx = pid - 3
            if 0 <= bank_idx < 8:
                ram_banks[bank_idx][:len(pdata)] = pdata
        select_ram_bank(port_7ffd & 0x07)
    else:
        spectrum_128k_mode = False
        paging_locked = True
        last_7ffd_val = 0
        current_ram_bank = 0
        select_ram_bank(0)

    ram_data = snap["ram"]
    memory[16384 : 16384 + len(ram_data)] = ram_data
    current_border = snap["border"]

    cpu.A = (snap["AF"] >> 8) & 0xFF
    cpu.F = snap["AF"] & 0xFF
    cpu.B = (snap["BC"] >> 8) & 0xFF
    cpu.C = snap["BC"] & 0xFF
    cpu.D = (snap["DE"] >> 8) & 0xFF
    cpu.E = snap["DE"] & 0xFF
    cpu.H = (snap["HL"] >> 8) & 0xFF
    cpu.L = snap["HL"] & 0xFF

    cpu.A_prime = (snap["AF_prime"] >> 8) & 0xFF
    cpu.F_prime = snap["AF_prime"] & 0xFF
    cpu.B_prime = (snap["BC_prime"] >> 8) & 0xFF
    cpu.C_prime = snap["BC_prime"] & 0xFF
    cpu.D_prime = (snap["DE_prime"] >> 8) & 0xFF
    cpu.E_prime = snap["DE_prime"] & 0xFF
    cpu.H_prime = (snap["HL_prime"] >> 8) & 0xFF
    cpu.L_prime = snap["HL_prime"] & 0xFF

    cpu.IX = snap["IX"]
    cpu.IY = snap["IY"]
    cpu.SP = snap["SP"]
    cpu.PC = snap["PC"]
    cpu.I = snap["I"]
    cpu.R = snap["R"]
    cpu.IFF1 = snap["IFF1"]
    cpu.IFF2 = snap["IFF2"]
    cpu.IM = snap["IM"]

    load_screen_bytes(bytes(ram_data[:6912]))
    canvas_dirty = True
    redraw_canvas()
    update_display()

    if cpu.PC is not None and autorun_enabled:
        run_loaded_snapshot(cpu)


def parse_bas_file(data):
    """Auto-detects and decodes plain text or tokenized Sinclair BASIC."""
    is_binary = False
    if len(data) >= 4:
        first_ln = (data[0] << 8) | data[1]
        first_len = data[2] | (data[3] << 8)
        if 0 <= first_ln <= 9999 and 0 < first_len <= len(data) - 4:
            if any(b in SINCLAIR_TOKENS for b in data[4 : min(len(data), 4 + first_len)]):
                is_binary = True

    lines = {}
    if is_binary:
        pos = 0
        n = len(data)
        while pos + 4 <= n:
            ln = (data[pos] << 8) | data[pos+1]
            llen = data[pos+2] | (data[pos+3] << 8)
            pos += 4
            if llen <= 0 or pos + llen > n:
                break
            line_bytes = data[pos : pos + llen]
            pos += llen
            res = []
            i = 0
            while i < len(line_bytes):
                c = line_bytes[i]
                if c == 14:  # Sinclair 5-byte number marker
                    num_bytes = line_bytes[i+1 : i+6]
                    val = None
                    if len(num_bytes) == 5:
                        b0, b1, b2, b3, b4 = num_bytes
                        if b0 == 0:
                            sign = -1 if b1 == 0xFF else 1
                            val = sign * (b2 | (b3 << 8))
                        else:
                            exp = b0 - 128
                            sign = -1.0 if (b1 & 0x80) else 1.0
                            mant_int = ((b1 & 0x7F) | 0x80) << 24 | (b2 << 16) | (b3 << 8) | b4
                            mant = mant_int / (2.0 ** 32)
                            fval = sign * mant * (2.0 ** exp)
                            val = int(fval) if fval.is_integer() else fval
                    if val is not None:
                        while res and (res[-1].isdigit() or res[-1] in ('.', 'e', 'E')):
                            res.pop()
                        val_str = str(val)
                        if res and res[-1] and (res[-1][-1].isalnum() or res[-1][-1] in ('=', '<', '>', ':')):
                            res.append(" ")
                        res.append(val_str)
                    i += 6
                    continue
                if c == 13:  # Enter
                    break
                if c in SINCLAIR_TOKENS:
                    kw = SINCLAIR_TOKENS[c]
                    if res and res[-1] and (res[-1][-1].isalnum() or res[-1][-1] in ('=', '<', '>', ':')):
                        res.append(" ")
                    res.append(kw + " ")
                elif 32 <= c < 127:
                    res.append(chr(c))
                i += 1
            code_str = "".join(res).strip()
            if code_str and 0 <= ln <= 65535:
                lines[ln] = code_str
    else:
        text = data.decode('utf-8', errors='ignore')
        for l in text.splitlines():
            l = l.strip()
            if not l:
                continue
            m = re.match(r'^(\d+)\s+(.+)$', l)
            if m:
                lines[int(m.group(1))] = m.group(2).strip()
        if not lines:
            cur_ln = 10
            for l in text.splitlines():
                l = l.strip()
                if not l:
                    continue
                lines[cur_ln] = l
                cur_ln += 10

    return lines


def load_bas_program(path, mode=""):
    global program, _z80_compiled_blocks, program_line_order, _split_cache, canvas_dirty, autorun_enabled
    with open(path, "rb") as f:
        data = f.read()
    parsed_lines = parse_bas_file(data)
    if not parsed_lines:
        canvas_print(f"No BASIC program lines found in '{os.path.basename(path)}'")
        return
    program.clear()
    _z80_compiled_blocks.clear()
    if 'program_line_order' in globals():
        program_line_order.clear()
    for ln in sorted(parsed_lines.keys()):
        program[ln] = parsed_lines[ln]
        if 'program_line_order' in globals():
            program_line_order.append(ln)
    parse_data_lines()
    _split_cache.clear()
    if not is_execution_mode():
        canvas_print(f"Loaded BASIC program '{os.path.basename(path)}' ({len(parsed_lines)} lines)")
        canvas_dirty = True
        redraw_canvas()
        update_display()
    if mode.upper() == "RUN":
        run_program(0)


def load_tzx_file(path, mode="", attach_only=False):
    global attached_tape_path, tape_data_blocks, tape_block_index, tape_named_blocks, tape_raw_blocks, tape_raw_index, tape_block_headers
    global last_loaded_code_bytes, last_loaded_code_addr, last_loaded_screen_bytes, program, program_line_order, autorun_enabled
    global tape_pure_data_blocks, tape_turbo_blocks, tape_pure_index, tape_turbo_index, speedlock_call_count

    with open(path, "rb") as f:
        data = f.read()
    reader = TZXReader(data)
    attached_tape_path = path
    if 'universal_tape_player' in globals():
        universal_tape_player.attach(path)

    tape_data_blocks.clear()
    tape_raw_blocks = list(reader.raw_blocks)
    tape_raw_index = 0
    tape_pure_data_blocks = list(reader.pure_data_blocks)
    tape_pure_index = 0
    tape_turbo_blocks = list(reader.turbo_blocks)
    tape_turbo_index = 0
    speedlock_call_count = 0
    tape_block_headers = []
    tape_block_index = 0
    tape_named_blocks.clear()

    block_type = None
    load_address = 16384
    hdr_name = ""
    prog_len = None
    parsed_lines_from_tzx = {}
    autorun_ln = None
    auto_run = False
    is_binary_tape = False

    for flag, payload in reader.raw_blocks:
        if flag == 0:  # Sinclair Header
            if len(payload) >= 15:
                block_type = payload[0]
                hdr_name = payload[1:11].decode('latin-1', errors='ignore').strip()
                load_address = payload[13] | (payload[14] << 8)
                if block_type == 0:
                    prog_len = payload[15] | (payload[16] << 8) if len(payload) >= 17 else None
                    if load_address < 32768:
                        autorun_ln = load_address
                        auto_run = True
                    parsed_lines_from_tzx.clear()
                    if 'program_line_order' in globals():
                        program_line_order.clear()
        elif flag == 255:  # Data Block
            tape_data_blocks.append(bytes(payload))
            tape_block_headers.append((block_type, load_address, hdr_name))
            clean_k = hdr_name.lower() if hdr_name else ""
            if clean_k:
                tape_named_blocks[clean_k] = (block_type if block_type is not None else 3, load_address, bytes(payload))

            if block_type == 0 and not attach_only:  # BASIC Program
                prog_base = 23755
                prog_limit = min(prog_len, len(payload)) if (prog_len is not None and prog_len > 0) else len(payload)
                if prog_base + len(payload) <= len(memory):
                    memory[prog_base : prog_base + len(payload)] = payload
                    memory[23635] = prog_base & 0xFF
                    memory[23636] = (prog_base >> 8) & 0xFF
                    vars_addr = prog_base + prog_limit
                    memory[23627] = vars_addr & 0xFF
                    memory[23628] = (vars_addr >> 8) & 0xFF
                    memory[23641] = vars_addr & 0xFF
                    memory[23642] = (vars_addr >> 8) & 0xFF

                parsed_lines = parse_bas_file(payload[:prog_limit])
                if parsed_lines:
                    parsed_lines_from_tzx = parsed_lines
                    is_binary_tape = True
            elif block_type == 3 and not attach_only:  # CODE binary block
                target_addr = load_address & 0xFFFF
                last_loaded_code_bytes = bytes(payload)
                last_loaded_code_addr = target_addr
                if target_addr >= 16384 and target_addr + len(payload) <= len(memory):
                    memory[target_addr : target_addr + len(payload)] = payload
                    if (target_addr == 16384 or (clean_k and clean_k in ('p', 'screen', 'scr'))) and len(payload) >= 6144:
                        last_loaded_screen_bytes = bytes(payload)
                        load_screen_bytes(payload)
                    if not is_execution_mode():
                        canvas_print(f"Loaded CODE block at {target_addr} ({len(payload)} bytes)")
                    is_binary_tape = True
                elif target_addr < 16384:
                    is_binary_tape = True
            block_type = None
            hdr_name = ""

    if 'basic_rom_backup' in globals() and basic_rom_backup:
        memory[0:16384] = basic_rom_backup[:16384]

    if attach_only:
        canvas_print(f"Attached Tape: {os.path.basename(path)} ({len(tape_data_blocks)} data blocks)")
        update_display()
        return

    if is_binary_tape and parsed_lines_from_tzx:
        program.clear()
        _z80_compiled_blocks.clear()
        if 'program_line_order' in globals():
            program_line_order.clear()
        for ln, code_str in parsed_lines_from_tzx.items():
            program[ln] = code_str
            if 'program_line_order' in globals():
                program_line_order.append(ln)
        parse_data_lines()
        _split_cache.clear()
        if not is_execution_mode():
            canvas_print(f"Loaded TZX tape {os.path.basename(path)}")
            canvas_dirty = True
            redraw_canvas()
            update_display()
        has_speedloader = bool(
            tape_turbo_blocks or tape_pure_data_blocks or
            any(b[0] not in (0, 255) for b in tape_raw_blocks) or
            len(tape_raw_blocks) > 2 or
            any('SOFTLOCK' in s.upper() for s in parsed_lines_from_tzx.values())
        )
        if has_speedloader or (autorun_enabled and auto_run) or mode.upper() == "RUN":
            if (has_speedloader or mode.upper() == "RUN") and not ('Robocop' in path and not autorun_enabled):
                if run_simulated_tape_load(path, mode=mode):
                    return
            target_idx = 0
            if autorun_ln is not None and autorun_ln in program:
                line_nums = program_line_order if ('program_line_order' in globals() and program_line_order and all(k in program for k in program_line_order)) else sorted(program.keys())
                target_idx = get_target_line_idx(autorun_ln, line_nums)
            elif program:
                target_idx = 0
            if 'basic_rom_backup' in globals() and basic_rom_backup:
                memory[0:16384] = basic_rom_backup[:16384]
            run_program(target_idx)
    else:
        has_speedloader = bool(
            tape_turbo_blocks or tape_pure_data_blocks or
            any(b[0] not in (0, 255) for b in tape_raw_blocks) or
            len(tape_raw_blocks) > 2
        )
        if has_speedloader or ((autorun_enabled or mode.upper() == "RUN") and (tape_data_blocks or tape_raw_blocks)):
            if run_simulated_tape_load(path, mode=mode):
                return
        if not is_execution_mode():
            canvas_print(f"Loaded TZX tape {os.path.basename(path)} ({len(tape_data_blocks)} blocks)")
            update_display()



def handle_drive_command(arg_str=""):
    global mgt_default_drive, mgt_drives, lkdos_current_drive
    s = (arg_str or "").strip()
    if 'spectrum_mode' in globals() and spectrum_mode == "TS2068" and not ("," in s or '"' in s or "'" in s):
        handle_lkdos_statement("DRIVE " + s)
        return
    if not s:
        canvas_print("--- DRIVE STATUS ---")
        canvas_print(f"Default disk drive: {mgt_default_drive} ({'A' if mgt_default_drive == 1 else 'B'})")
        for d in (1, 2):
            disk = mgt_drives.get(d)
            letter = 'A' if d == 1 else 'B'
            if disk and getattr(disk, 'filepath', None):
                canvas_print(f'  Drive {d} ({letter}:): {os.path.basename(disk.filepath)} ("{disk.get_disk_name()}", {disk.get_free_kb()}K free)')
            else:
                canvas_print(f"  Drive {d} ({letter}:): [No disk mounted]")
        canvas_print("Syntax:")
        canvas_print("  DRIVE 1 or DRIVE A     - Set default drive to 1 (A:)")
        canvas_print("  DRIVE 2 or DRIVE B     - Set default drive to 2 (B:)")
        canvas_print("  DRIVE 1, \"disk.dsk\"   - Mount disk into drive 1")
        canvas_print("  DRIVE \"disk.trd\", 2   - Mount disk into drive 2")
        update_display()
        return

    parts = split_top_level_commas(s)
    if len(parts) == 1:
        tok = s.strip().strip('"\'').upper()
        if tok in ("1", "A", "A:"):
            mgt_default_drive = 1
            canvas_print("Default drive set to 1 (A:)")
            update_display()
            return
        elif tok in ("2", "B", "B:"):
            mgt_default_drive = 2
            canvas_print("Default drive set to 2 (B:)")
            update_display()
            return
        elif tok.isdigit() and int(tok) in (1, 2):
            mgt_default_drive = int(tok)
            canvas_print(f"Default drive set to {mgt_default_drive}")
            update_display()
            return
        else:
            handle_unified_attach(f"{s}, {mgt_default_drive}, DSK")
            return
    elif len(parts) >= 2:
        handle_unified_attach(s, default_cmd="DRIVE")
        return


def get_mgt_disk(drive):
    global mgt_drives
    if drive not in (1, 2):
        return None
    disk = mgt_drives.get(drive)
    if disk is None:
        folder = get_zx_folder()
        launch_folder = os.getcwd()
        fdi_candidates = [
            os.path.join(launch_folder, f"drive{drive}.dsk"),
            os.path.join(folder, f"drive{drive}.dsk"),
            os.path.join(launch_folder, f"drive{drive}.trd"),
            os.path.join(folder, f"drive{drive}.trd"),
            os.path.join(launch_folder, f"drive{drive}.scl"),
            os.path.join(folder, f"drive{drive}.scl"),
            os.path.join(launch_folder, f"drive{drive}.fdi"),
            os.path.join(folder, f"drive{drive}.fdi"),
            os.path.join(launch_folder, f"drive{drive}.img"),
            os.path.join(folder, f"drive{drive}.img"),
            os.path.join(launch_folder, f"drive{drive}.imd"),
            os.path.join(folder, f"drive{drive}.imd"),
        ]
        for p in fdi_candidates:
            if os.path.exists(p):
                try:
                    if p.lower().endswith(('.dsk', '.img', '.imd')):
                        disk = Plus3Disk(p)
                    elif p.lower().endswith(('.trd', '.scl')):
                        disk = TRDOSDisk(p)
                    else:
                        disk = MGTDisk(p)
                    mgt_drives[drive] = disk
                    break
                except Exception:
                    pass
        if disk is None:
            try:
                drv_letter = "A" if drive == 1 else "B"
                p = os.path.join(launch_folder, f"drive{drive}.dsk")
                disk = Plus3Disk(p, disk_name=f"DRIVE {drv_letter}")
                mgt_drives[drive] = disk
            except Exception:
                pass
    return disk



def mgt_cat(drive, stream_idx=None, abbreviated=False):
    disk = get_mgt_disk(drive)
    out_func = (lambda msg: streams[stream_idx].write(msg)) if (stream_idx is not None and stream_idx in streams and streams[stream_idx]) else canvas_print
    if disk is None:
        out_func(f"Drive {drive}: No disk in drive (use ATTACH \"filename\", {drive}, FDI)")
        return

    disk_name = disk.get_disk_name()
    files = disk.list_files()
    free_kb = disk.get_free_kb()

    out_func("--------------------------------")
    out_func(f"Disk: \"{disk_name}\"  (Drive {drive})")
    out_func("--------------------------------")
    type_chars = {
        MGTDisk.TYPE_BASIC: "B",
        MGTDisk.TYPE_NUM_ARRAY: "D",
        MGTDisk.TYPE_CHAR_ARRAY: "D",
        MGTDisk.TYPE_CODE: "C",
        MGTDisk.TYPE_48K_SNAP: "48K",
        MGTDisk.TYPE_MDR: "M",
        MGTDisk.TYPE_SCREEN: "S",
        MGTDisk.TYPE_SPECIAL: "X",
        MGTDisk.TYPE_128K_SNAP: "128"
    }
    if abbreviated:
        names = [f["name"] for f in files]
        out_func(" ".join(names) if names else "No files")
    else:
        for idx, f in enumerate(files, 1):
            t_str = type_chars.get(f["type"], "?")
            out_func(f"{idx:2d} {t_str:3s} {f['name']:10s} {f['sectors']:4d} sec")
    out_func("--------------------------------")
    out_func(f"Files: {len(files)}  Free: {free_kb}K / 780K")


def handle_add_disk_command(stmt_str=""):
    handle_unified_attach(stmt_str, default_cmd="ADD DISK")


def parse_mgt_device_spec(st):
    if st.startswith('*'):
        st = st[1:].strip()
    # 1. Quoted "d" or "D", e.g. "d";1;"file" or "d";"file"
    m = re.match(r'^["\']?[Dd]["\']\s*[;,]\s*(?:([12\*])\s*[;,]?\s*)?(.*)$', st)
    if m:
        d_str = m.group(1)
        raw_fname = m.group(2).strip()
        drive = mgt_default_drive if (not d_str or d_str == '*') else int(d_str)
        return drive, raw_fname
    # 2. d1, d2, d*, with optional semicolon/space and filename
    m = re.match(r'^[Dd]\s*([12\*])(?:\s*[;,]\s*|\s+)?(.*)$', st)
    if m:
        d_str = m.group(1)
        raw_fname = m.group(2).strip()
        drive = mgt_default_drive if (not d_str or d_str == '*') else int(d_str)
        return drive, raw_fname
    # 3. d; "file"
    m = re.match(r'^[Dd]\s*[;,]\s*(.*)$', st)
    if m:
        raw_fname = m.group(1).strip()
        return mgt_default_drive, raw_fname
    # 4. d"file"
    m = re.match(r'^[Dd](["\'].*)$', st)
    if m:
        raw_fname = m.group(1).strip()
        return mgt_default_drive, raw_fname
    return None


def parse_device_spec(spec):
    s = spec.strip()
    if s.startswith("*"):
        s = s[1:].strip()
    
    # 128K RAM Disk (Silicon Disc) specifier: !"filename" or !filename or !
    if s.startswith("!") or s.startswith('"!"') or s.startswith("'!'"):
        rem = s[1:].strip() if s.startswith("!") else s[3:].strip()
        if rem.startswith(";") or rem.startswith(","):
            rem = rem[1:].strip()
        if rem:
            try:
                val = evaluate_expr(rem)
                if isinstance(val, str) and val:
                    rem = val
            except Exception:
                pass
        fname = str(rem).replace('"', '').replace("'", '').strip(' "\',;')
        return {"type": "ram", "drive": "M", "name": fname}

    # Sinclair ZX Spectrum +3DOS drive specifiers: A:, B:, M:, T:
    s_eval = s
    if (s_eval.startswith('"') and s_eval.endswith('"')) or (s_eval.startswith("'") and s_eval.endswith("'")):
        try:
            val = evaluate_expr(s_eval)
            if isinstance(val, str) and val:
                s_eval = val
        except Exception:
            pass

    s_clean = s_eval.strip().strip('"\'')
    p3_match = re.match(r'^([ABMTabmt]):\s*(.*)$', s_clean)
    if p3_match:
        drv = p3_match.group(1).upper()
        raw_target = p3_match.group(2).strip(' "\'')
        if raw_target:
            try:
                val = evaluate_expr(raw_target)
                if isinstance(val, str) and val:
                    raw_target = val
            except Exception:
                pass
        clean_name = str(raw_target).replace('"', '').replace("'", '').strip(' "\',;')
        if drv == "A":
            return {"type": "plus3", "drive": "A", "drive_num": 1, "name": clean_name}
        elif drv == "B":
            return {"type": "plus3", "drive": "B", "drive_num": 2, "name": clean_name}
        elif drv == "M":
            return {"type": "ram", "drive": "M", "name": clean_name}
        elif drv == "T":
            return {"type": "tape", "drive": "T", "name": clean_name}

    # MGT DISCiPLE / Plus D disk specifier:
    mgt_spec = parse_mgt_device_spec(s)
    if mgt_spec:
        drive, raw_fname = mgt_spec
        if raw_fname:
            try:
                val = evaluate_expr(raw_fname)
                if isinstance(val, str) and val:
                    raw_fname = val
            except Exception:
                pass
        fname = str(raw_fname).replace('"', '').replace("'", '').strip(' "\',;')
        return {"type": "d", "drive": drive, "name": fname}
    
    m_match = re.match(r'^["\']?([Mm])["\']?\s*[;,]\s*(\d+)\s*[;,]\s*(.+)$', s)
    if m_match:
        drive = int(m_match.group(2))
        raw_fname = m_match.group(3).strip()
        try:
            val = evaluate_expr(raw_fname)
            if isinstance(val, str) and val:
                raw_fname = val
        except Exception:
            pass
        fname = str(raw_fname).replace('"', '').replace("'", '').strip(' "\',;')
        return {"type": "m", "drive": drive, "name": fname}
    
    m_short = re.match(r'^(\d+)\s*[;,]\s*(.+)$', s)
    if m_short:
        drive = int(m_short.group(1))
        raw_fname = m_short.group(2).strip()
        try:
            val = evaluate_expr(raw_fname)
            if isinstance(val, str) and val:
                raw_fname = val
        except Exception:
            pass
        fname = str(raw_fname).replace('"', '').replace("'", '').strip(' "\',;')
        return {"type": "m", "drive": drive, "name": fname}
        
    b_match = re.match(r'^["\']?([Bb])["\']?(?:\s*[;,]\s*["\']?([^"\']*)["\']?)?$', s)
    if b_match:
        fname = b_match.group(2).replace('"', '').replace("'", '').strip() if b_match.group(2) else "serial_b.sbin"
        if not fname.endswith(".sbin"): fname += ".sbin"
        return {"type": "b", "name": fname}
        
    t_match = re.match(r'^["\']?([Tt])["\']?(?:\s*[;,]\s*["\']?([^"\']*)["\']?)?$', s)
    if t_match:
        fname = t_match.group(2).replace('"', '').replace("'", '').strip() if t_match.group(2) else "serial_t.sert"
        if not fname.endswith(".sert"): fname += ".sert"
        return {"type": "t", "name": fname}
        
    net_sock_match = re.match(r'^["\']?(?:n>|net:)(?:(tcp|udp):)?([^:]+):(\d+)["\']?$', s, re.IGNORECASE)
    if net_sock_match:
        proto = (net_sock_match.group(1) or "tcp").lower()
        host = net_sock_match.group(2).strip()
        port = int(net_sock_match.group(3))
        return {"type": "net_socket", "proto": proto, "host": host, "port": port}

    n_match = re.match(r'^["\']?([Nn])["\']?\s*[;,]\s*(\d+)', s)
    if n_match:
        station = int(n_match.group(2))
        fname = "net_broadcast.net" if station == 0 else f"net_station{station}.net"
        return {"type": "n", "station": station, "name": fname}
        
    raw_target = s
    try:
        val = evaluate_expr(raw_target)
        if isinstance(val, str) and val:
            raw_target = val
    except Exception:
        pass
    clean_name = str(raw_target).replace('"', '').replace("'", '').strip(' "\',;')
    return {"type": "file", "name": clean_name}


def read_device_bytes(dev_info):
    folder = get_zx_folder()
    dev_type = dev_info["type"]
    if dev_type == "ram":
        fname = dev_info.get("name", "")
        item = ram_disk.get(fname)
        if isinstance(item, dict):
            return item.get("data", b"")
        elif isinstance(item, (bytes, bytearray)):
            return bytes(item)
        return b""
    elif dev_type in ("d", "plus3"):
        drive = dev_info.get("drive_num", dev_info.get("drive", mgt_default_drive))
        disk = get_mgt_disk(drive)
        if disk:
            try:
                ftype, data, meta = disk.load_file(dev_info.get("name", ""))
                return data
            except Exception:
                return b""
        return b""
    elif dev_type == "m":
        return mdr_read_file_bytes(dev_info["drive"], dev_info["name"])
    elif dev_type == "b":
        path = os.path.join(folder, dev_info.get("name", "serial_b.sbin"))
        if os.path.exists(path):
            with open(path, "rb") as f: return f.read()
        return b""
    elif dev_type in ("t", "tape"):
        fname = dev_info.get("name", "")
        if attached_tape_path and os.path.exists(attached_tape_path):
            with open(attached_tape_path, "rb") as f: return f.read()
        for cand in (f"{fname}.tap", f"{fname}.sert", "serial_t.sert"):
            p = os.path.join(folder, cand)
            if os.path.exists(p):
                with open(p, "rb") as f: return f.read()
        return b""
    elif dev_type == "n":
        fname = dev_info.get("name", "net_broadcast.net")
        path = os.path.join(folder, fname)
        if os.path.exists(path):
            with open(path, "rb") as f: return f.read()
        return b""
    else:
        path = os.path.join(folder, dev_info["name"])
        if os.path.exists(path):
            with open(path, "rb") as f: return f.read()
        return b""


def write_device_bytes(dev_info, data_bytes):
    folder = get_zx_folder()
    dev_type = dev_info["type"]
    if dev_type == "ram":
        fname = dev_info.get("name", "unnamed")
        ram_disk[fname] = {"type": "CODE", "data": bytes(data_bytes), "start_addr": 0, "size": len(data_bytes)}
    elif dev_type in ("d", "plus3"):
        drive = dev_info.get("drive_num", dev_info.get("drive", mgt_default_drive))
        disk = get_mgt_disk(drive)
        if disk:
            try:
                disk.save_file(dev_info.get("name", "unnamed"), MGTDisk.TYPE_CODE, data_bytes)
            except Exception as e:
                print(f"Disk write error: {e}")
    elif dev_type == "m":
        mdr_write_file_bytes(dev_info["drive"], dev_info["name"], data_bytes)
    elif dev_type == "b":
        path = os.path.join(folder, dev_info.get("name", "serial_b.sbin"))
        with open(path, "wb") as f: f.write(data_bytes)
    elif dev_type in ("t", "tape"):
        fname = dev_info.get("name", "tape_output")
        target = attached_tape_path if attached_tape_path else os.path.join(folder, f"{fname}.tap")
        with open(target, "wb") as f: f.write(data_bytes)
    elif dev_type == "n":
        fname = dev_info.get("name", "net_broadcast.net")
        path = os.path.join(folder, fname)
        with open(path, "wb") as f: f.write(data_bytes)
    else:
        path = os.path.join(folder, dev_info["name"])
        with open(path, "wb") as f: f.write(data_bytes)


def auto_attach_file(filepath, unit=None):
    global mgt_drives, microdrive_attachments, attached_tape_path, mgt_default_drive
    if not filepath or not os.path.exists(filepath):
        if 'canvas_print' in globals():
            canvas_print(f"Attach error: File not found '{filepath}'")
        print(f"Attach error: File not found '{filepath}'")
        if 'update_display' in globals():
            try: update_display()
            except Exception: pass
        return False

    f_abs = os.path.abspath(filepath)
    base_name = os.path.basename(f_abs)
    f_lower = f_abs.lower()
    ext = os.path.splitext(f_lower)[1]
    
    launch_folder = os.getcwd()
    folder = get_zx_folder() if ('get_zx_folder' in globals() and callable(globals()['get_zx_folder'])) else launch_folder

    # 1. Microdrive (.mdr)
    if ext == ".mdr":
        target_drive = unit if (unit is not None and 1 <= unit <= 8) else None
        if target_drive is None:
            target_drive = 1
            for d in range(1, 9):
                curr = microdrive_attachments.get(d)
                if not curr or curr == f"{d}.mdr":
                    target_drive = d
                    break
                p = curr if os.path.isabs(curr) else (os.path.join(launch_folder, curr) if os.path.exists(os.path.join(launch_folder, curr)) else os.path.join(folder, curr))
                if not os.path.exists(p):
                    target_drive = d
                    break
        microdrive_attachments[target_drive] = f_abs
        type_name = "Microdrive Cartridge"
        location_name = f"Microdrive Drive {target_drive}"
        msg = f"Attached '{type_name}' ({base_name}) to {location_name}"
        if 'canvas_print' in globals():
            canvas_print(msg)
        print(msg)
        if 'update_display' in globals():
            try: update_display()
            except Exception: pass
        return True

    # 2. DISCiPLE / +D Floppy Discs (.mgt, .fdi)
    if ext in (".mgt", ".fdi"):
        target_drive = unit if (unit in (1, 2)) else None
        if target_drive is None:
            d1 = mgt_drives.get(1)
            d2 = mgt_drives.get(2)
            d1_path = getattr(d1, 'filepath', '') or ''
            if d1 is None or (d1_path.endswith('drive1.fdi') and not os.path.exists(d1_path)):
                target_drive = 1
            elif d2 is None:
                target_drive = 2
            else:
                target_drive = 1
        try:
            disk = MGTDisk(f_abs)
            mgt_drives[target_drive] = disk
            disk_drives[target_drive] = disk
            type_name = "DISCiPLE Disc"
            location_name = f"DISCiPLE Drive {target_drive}"
            msg = f"Attached '{type_name}' ({base_name}) to {location_name}"
            if 'canvas_print' in globals():
                canvas_print(msg)
            print(msg)
            if 'update_display' in globals():
                try: update_display()
                except Exception: pass
            return True
        except Exception as e:
            err_msg = f"DISCiPLE attach error: {e}"
            if 'canvas_print' in globals():
                canvas_print(err_msg)
            print(err_msg)
            if 'update_display' in globals():
                try: update_display()
                except Exception: pass
            return False

    # 2b. Opus Discovery Disks (.opd)
    if ext == ".opd":
        target_drive = unit if (unit in (1, 2)) else None
        if target_drive is None:
            target_drive = 1 if disk_drives.get(1) is None else (2 if disk_drives.get(2) is None else 1)
        try:
            disk = OpusDisk(f_abs)
            disk_drives[target_drive] = disk
            mgt_drives[target_drive] = disk
            type_name = "Opus Discovery Disk"
            location_name = f"Opus Drive {target_drive}"
            msg = f"Attached '{type_name}' ({base_name}) to {location_name}"
            if 'canvas_print' in globals(): canvas_print(msg)
            print(msg)
            if 'update_display' in globals():
                try: update_display()
                except Exception: pass
            return True
        except Exception as e:
            err_msg = f"Opus attach error: {e}"
            if 'canvas_print' in globals(): canvas_print(err_msg)
            print(err_msg)
            return False

    # 3. TR-DOS / Beta Disks (.trd, .scl)
    if ext in (".trd", ".scl"):
        target_drive = unit if (unit in (1, 2)) else None
        if target_drive is None:
            if mgt_drives.get(1) is None:
                target_drive = 1
            elif mgt_drives.get(2) is None:
                target_drive = 2
            else:
                target_drive = 1
        try:
            disk = TRDOSDisk(f_abs)
            mgt_drives[target_drive] = disk
            disk_drives[target_drive] = disk
            drv_letter = 'A:' if target_drive == 1 else 'B:'
            type_name = "TR-DOS Disk"
            location_name = f"TR-DOS Drive {drv_letter}"
            msg = f"Attached '{type_name}' ({base_name}) to {location_name}"
            if 'canvas_print' in globals():
                canvas_print(msg)
            print(msg)
            if 'update_display' in globals():
                try: update_display()
                except Exception: pass
            return True
        except Exception as e:
            err_msg = f"TR-DOS attach error: {e}"
            if 'canvas_print' in globals():
                canvas_print(err_msg)
            print(err_msg)
            if 'update_display' in globals():
                try: update_display()
                except Exception: pass
            return False

    # 4. Tape Images (.tzx, .tap)
    if ext in (".tzx", ".tap"):
        attached_tape_path = f_abs
        if ext == ".tzx" and 'load_tzx_file' in globals():
            try:
                load_tzx_file(f_abs, attach_only=True)
            except Exception:
                pass
        type_name = "Tape"
        location_name = "Cassette Player"
        msg = f"Attached '{type_name}' ({base_name}) to {location_name}"
        if 'canvas_print' in globals():
            canvas_print(msg)
        print(msg)
        if 'update_display' in globals():
            try: update_display()
            except Exception: pass
        return True

    # 5. +3 Disks and all supported CP/M Disks (.dsk, .cpm, .img, .imd, .raw, .flp)
    target_drive = unit if (unit in (1, 2)) else None
    if target_drive is None:
        d1 = mgt_drives.get(1)
        d2 = mgt_drives.get(2)
        d1_path = getattr(d1, 'filepath', '') or ''
        if d1 is None or not isinstance(d1, Plus3Disk) or (d1_path.endswith('drive1.fdi') and not os.path.exists(d1_path)):
            target_drive = 1
        elif d2 is None:
            target_drive = 2
        else:
            target_drive = 1

    try:
        disk = Plus3Disk(f_abs)
        mgt_drives[target_drive] = disk
        drv_letter = 'A:' if target_drive == 1 else 'B:'
        letter_key = 'A' if target_drive == 1 else 'B'
        
        fmt_name = ""
        if hasattr(disk, 'cpm_img') and disk.cpm_img:
            fmt_name = getattr(disk.cpm_img, 'format_name', '') or ""
            
        if 'Sinclair' in fmt_name or '+3' in fmt_name or ext == '.dsk':
            type_name = "+3 Disk"
        elif fmt_name:
            type_name = f"CP/M Disk ({fmt_name})"
        else:
            type_name = "+3 Disk"
            
        location_name = f"+3 Drive {drv_letter}"
        msg = f"Attached '{type_name}' ({base_name}) to {location_name}"

        # Sync to CPMSystem if initialized
        if 'cpm_system' in globals() and cpm_system is not None:
            if hasattr(disk, 'cpm_img') and disk.cpm_img:
                cpm_system.mounted_disks[letter_key] = disk.cpm_img
                files = disk.cpm_img.get_files()
                cpm_system.drives[letter_key] = {}
                for fn, data in files.items():
                    cpm_system.put_file(letter_key, fn, data, user=0, sync_disk=False)

        if 'canvas_print' in globals():
            canvas_print(msg)
        print(msg)
        if 'update_display' in globals():
            try: update_display()
            except Exception: pass
        return True
    except Exception as e:
        err_msg = f"Disk attach error: {e}"
        if 'canvas_print' in globals():
            canvas_print(err_msg)
        print(err_msg)
        if 'update_display' in globals():
            try: update_display()
            except Exception: pass
        return False


def handle_unified_attach(cmd_str="", default_cmd="ATTACH"):
    global mgt_drives, microdrive_attachments, attached_tape_path, mgt_default_drive
    s = (cmd_str or "").strip()

    # Strip command keywords if present at start
    s_upper = s.upper()
    if s_upper.startswith("ATTACH"):
        s = s[6:].strip()
    elif s_upper.startswith("ADD DISK"):
        s = s[8:].strip()
    elif s_upper.startswith("ADD DRIVE"):
        s = s[9:].strip()
    elif s_upper.startswith("ADDDISK"):
        s = s[7:].strip()
    elif s_upper.startswith("ADDDRIVE"):
        s = s[8:].strip()
    elif s_upper.startswith("DRIVE"):
        s = s[5:].strip()
    elif s_upper.startswith("ADD"):
        s = s[3:].strip()
        if s.upper().startswith("DISK"):
            s = s[4:].strip()
        elif s.upper().startswith("DRIVE"):
            s = s[5:].strip()

    if s.upper() in ("?", "HELP", "STATUS", "LIST"):
        folder = get_zx_folder()
        launch_folder = os.getcwd()
        canvas_print("--- STORAGE ATTACHMENTS ---")
        canvas_print("Microdrive Units (1-8, .MDR):")
        for d in range(1, 9):
            fname = microdrive_attachments.get(d, f"{d}.mdr")
            p = fname if os.path.isabs(fname) else (os.path.join(launch_folder, fname) if os.path.exists(os.path.join(launch_folder, fname)) else os.path.join(folder, fname))
            status = "Ready" if os.path.exists(p) else "New/Uncreated"
            canvas_print(f"  Drive {d}: {fname} ({status})")
        canvas_print("Disk Drive Units (1-2 / A-B, .DSK / .TRD / .FDI):")
        for d in (1, 2):
            disk = mgt_drives.get(d)
            if disk and getattr(disk, 'filepath', None):
                canvas_print(f'  Drive {d}: {os.path.basename(disk.filepath)} ("{disk.get_disk_name()}", {disk.get_free_kb()}K free)')
            else:
                canvas_print(f"  Drive {d}: [No disk mounted]")
        if attached_tape_path and os.path.exists(attached_tape_path):
            canvas_print(f"Attached Tape: {os.path.basename(attached_tape_path)}")
        else:
            canvas_print("Attached Tape: [No tape attached]")
        canvas_print('Syntax:')
        canvas_print('  ATTACH                      - Choose file dialog to attach')
        canvas_print('  ADD DRIVE                   - Choose file dialog to attach')
        canvas_print('  ATTACH "filename.tzx"       - Attach TZX/TAP tape')
        canvas_print('  ATTACH "disk.trd"           - Mount TR-DOS/DSK to current drive')
        canvas_print('  ATTACH "disk.dsk", 1        - Mount disk to Drive 1 (A:)')
        canvas_print('  ATTACH "cart.mdr", 2        - Mount cartridge to Microdrive 2')
        canvas_print('  ATTACH "snap.z80"           - Load Z80/SNA snapshot')
        canvas_print('  ATTACH "prog.bas"           - Load BASIC program')
        if 'update_display' in globals():
            try: update_display()
            except Exception: pass
        return

    # If user typed ATTACH or ADD DRIVE without parameters: bring up file selector dialog
    if not s:
        chosen_path = prompt_open_attach_filename()
        if not chosen_path:
            if 'canvas_print' in globals():
                canvas_print("Attach cancelled: No file selected")
            print("Attach cancelled: No file selected")
            if 'update_display' in globals():
                try: update_display()
                except Exception: pass
            return
        auto_attach_file(chosen_path)
        return

    parts = split_top_level_commas(s)

    # Single argument syntax: ATTACH "filename"
    if len(parts) == 1:
        raw_name = parts[0].strip()
        if (raw_name.startswith('"') and raw_name.endswith('"')) or (raw_name.startswith("'") and raw_name.endswith("'")):
            clean_name = raw_name[1:-1].strip()
        else:
            try:
                val = evaluate_expr(raw_name)
                if isinstance(val, str) and val:
                    clean_name = val.strip()
                else:
                    clean_name = str(raw_name).replace('"', '').replace("'", '').strip()
            except Exception:
                clean_name = str(raw_name).replace('"', '').replace("'", '').strip()

        if not clean_name:
            canvas_print("Error: Filename cannot be empty")
            update_display()
            return

        folder = get_zx_folder()
        launch_folder = os.getcwd()
        if os.path.isabs(clean_name):
            path = clean_name
        else:
            cand_list = [
                os.path.join(launch_folder, clean_name),
                os.path.join(folder, clean_name),
            ]
            ext = os.path.splitext(clean_name)[1].lower()
            if not ext:
                for ce in ('.tzx', '.tap', '.z80', '.sna', '.trd', '.scl', '.dsk', '.bas', '.mdr', '.fdi', '.img', '.imd', '.cpm', '.raw', '.flp', '.mgt', '.opd'):
                    cand_list.append(os.path.join(launch_folder, clean_name + ce))
                    cand_list.append(os.path.join(folder, clean_name + ce))
            path = None
            for cp in cand_list:
                if os.path.exists(cp):
                    path = cp
                    break
            if not path:
                path = os.path.join(launch_folder, clean_name)

        path_lower = path.lower()
        if path_lower.endswith(('.tzx', '.tap')):
            attached_tape_path = path
            if path_lower.endswith('.tzx'):
                load_tzx_file(path, attach_only=True)
            else:
                canvas_print(f"Attached Tape: {os.path.basename(path)}")
            update_display()
            return
        elif path_lower.endswith(('.z80', '.sna')):
            load_program_file(path)
            return
        elif path_lower.endswith('.bas'):
            load_bas_program(path)
            return
        elif path_lower.endswith(('.trd', '.scl', '.dsk', '.img', '.imd', '.fdi', '.cpm', '.raw', '.flp', '.mgt', '.mdr', '.opd')):
            if os.path.exists(path):
                auto_attach_file(path)
                return
            elif path_lower.endswith('.mdr'):
                microdrive_attachments[1] = clean_name
                canvas_print(f"Attached '{clean_name}' to Microdrive 1")
                update_display()
                return
            else:
                unit = mgt_default_drive or 1
                is_trd = path_lower.endswith(('.trd', '.scl'))
                is_dsk = path_lower.endswith(('.dsk', '.img', '.imd', '.cpm', '.raw', '.flp'))
                try:
                    base_label = os.path.splitext(os.path.basename(clean_name))[0].upper()[:10]
                    disk = TRDOSDisk(path, disk_name=base_label) if is_trd else (Plus3Disk(path, disk_name=base_label) if is_dsk else MGTDisk(path, disk_name=base_label))
                    mgt_drives[unit] = disk
                    canvas_print(f'Drive {unit}: Created and mounted \'{os.path.basename(path)}\' ("{base_label}", {disk.get_free_kb()}K free)')
                except Exception as e:
                    canvas_print(f"Drive {unit}: Error creating '{clean_name}': {e}")
                update_display()
                return
        elif path_lower.endswith('.mdr'):
            microdrive_attachments[1] = clean_name
            canvas_print(f"Attached '{clean_name}' to Microdrive 1")
            update_display()
            return
        else:
            if os.path.exists(path):
                load_program_file(path)
            else:
                canvas_print(f"Error: File not found: '{clean_name}'")
            update_display()
            return

    # Check for legacy syntax: unit_number, "filename"
    p0_clean = parts[0].strip()
    is_legacy = False
    if p0_clean.isdigit():
        is_legacy = True

    if is_legacy:
        raw_name = parts[1].strip()
        raw_unit = parts[0].strip()
        raw_type = parts[2].strip() if len(parts) >= 3 else ""
    else:
        raw_name = parts[0].strip()
        raw_unit = parts[1].strip()
        raw_type = parts[2].strip() if len(parts) >= 3 else ""

    # Parse filename
    if (raw_name.startswith('"') and raw_name.endswith('"')) or (raw_name.startswith("'") and raw_name.endswith("'")):
        clean_name = raw_name[1:-1].strip()
    else:
        try:
            val = evaluate_expr(raw_name)
            if isinstance(val, str) and val:
                clean_name = val.strip()
            else:
                clean_name = str(raw_name).replace('"', '').replace("'", '').strip()
        except Exception:
            clean_name = str(raw_name).replace('"', '').replace("'", '').strip()

    if not clean_name:
        canvas_print("Error: Filename cannot be empty")
        update_display()
        return

    # Parse unit_number (1-8 or A/B)
    unit = None
    u_str = str(raw_unit).strip().strip("'\"")
    if u_str in ("A", "1"):
        unit = 1
    elif u_str in ("B", "2"):
        unit = 2
    elif u_str.isdigit():
        unit = int(u_str)
    else:
        try:
            u_val = evaluate_expr(raw_unit)
            if isinstance(u_val, str) and u_val.upper() in ("A", "B"):
                unit = 1 if u_val.upper() == "A" else 2
            else:
                unit = int(to_float(u_val))
        except Exception:
            pass

    if unit is None:
        canvas_print("Error: Invalid unit number")
        update_display()
        return

    # Parse container type
    type_clean = raw_type.strip().strip("'\"").upper()
    if type_clean:
        if type_clean in ("MDR", "MICRODRIVE", "M"):
            container_type = "MDR"
        elif type_clean in ("TRD", "SCL", "TRDOS", "BETA"):
            container_type = "TRD"
        elif type_clean in ("OPD", "OPUS"):
            container_type = "OPD"
        elif type_clean in ("DSK", "DISK", "DRIVE", "D", "IMG", "IMD"):
            container_type = "DSK"
        elif type_clean in ("FDI", "MGT"):
            container_type = "FDI"
        elif type_clean in ("TAP", "TZX", "TAPE", "T"):
            container_type = "TAPE"
        else:
            canvas_print(f"Error: Unknown type '{raw_type.strip()}'. Must be MDR, DSK, TRD, FDI, or TAPE")
            update_display()
            return
    else:
        ext = os.path.splitext(clean_name)[1].lower()
        if ext == ".mdr":
            container_type = "MDR"
        elif ext in (".trd", ".scl"):
            container_type = "TRD"
        elif ext == ".opd":
            container_type = "OPD"
        elif ext == ".fdi":
            container_type = "FDI"
        elif ext in (".dsk", ".img", ".imd"):
            container_type = "DSK"
        elif ext in (".tap", ".tzx"):
            container_type = "TAPE"
        elif unit in (1, 2) and any(k in cmd_str.upper() for k in ("DISK", "DRIVE")):
            container_type = "DSK"
        elif unit > 2:
            container_type = "MDR"
        else:
            container_type = "DSK" if unit in (1, 2) else "MDR"

    if container_type == "TAPE":
        folder = get_zx_folder()
        launch_folder = os.getcwd()
        path = clean_name if os.path.isabs(clean_name) else (os.path.join(launch_folder, clean_name) if os.path.exists(os.path.join(launch_folder, clean_name)) else os.path.join(folder, clean_name))
        attached_tape_path = path
        if path.lower().endswith('.tzx'):
            load_tzx_file(path, attach_only=True)
        else:
            canvas_print(f"Attached Tape: {os.path.basename(path)}")
        update_display()
        return

    if container_type == "MDR":
        if not (1 <= unit <= 8):
            canvas_print("Error: Microdrive unit number must be 1 to 8")
            update_display()
            return
        if not clean_name.lower().endswith(".mdr"):
            clean_name += ".mdr"

        folder = get_zx_folder()
        launch_folder = os.getcwd()
        if os.path.isabs(clean_name):
            path = clean_name
        else:
            path = os.path.join(launch_folder, clean_name)
            if not os.path.exists(path):
                alt_path = os.path.join(folder, clean_name)
                if os.path.exists(alt_path):
                    path = alt_path
                else:
                    path = os.path.join(folder, clean_name)

        microdrive_attachments[unit] = clean_name
        if not os.path.exists(path):
            cart_title = os.path.splitext(os.path.basename(clean_name))[0].upper()[:10]
            create_blank_mdr(path, cart_title)
            canvas_print(f"Created and attached '{clean_name}' to Microdrive {unit}")
        else:
            canvas_print(f"Attached '{clean_name}' to Microdrive {unit}")
        update_display()
        return

    elif container_type in ("FDI", "DSK", "TRD", "OPD"):
        if unit not in (1, 2, 3, 4):
            canvas_print("Error: Disk drive unit number must be 1-4 (A-D)")
            update_display()
            return

        if container_type == "TRD":
            if not any(clean_name.lower().endswith(x) for x in ('.trd', '.scl')):
                clean_name += ".trd"
        elif container_type == "OPD":
            if not clean_name.lower().endswith('.opd'):
                clean_name += ".opd"
        elif container_type == "DSK":
            if not any(clean_name.lower().endswith(x) for x in ('.dsk', '.img', '.imd', '.fdi', '.trd', '.scl', '.opd')):
                clean_name += ".dsk"
        elif container_type == "FDI":
            if not any(clean_name.lower().endswith(x) for x in ('.fdi', '.dsk')):
                clean_name += ".fdi"

        folder = get_zx_folder()
        launch_folder = os.getcwd()
        if os.path.isabs(clean_name):
            path = clean_name
        else:
            path = os.path.join(launch_folder, clean_name)
            if not os.path.exists(path):
                alt_path = os.path.join(folder, clean_name)
                if os.path.exists(alt_path):
                    path = alt_path

        is_opd = path.lower().endswith('.opd') or container_type == "OPD"
        is_trd = (path.lower().endswith(('.trd', '.scl')) or container_type == "TRD") and not is_opd
        is_dsk = (path.lower().endswith(('.dsk', '.img', '.imd', '.cpm', '.raw', '.flp')) or container_type == "DSK") and not is_trd and not is_opd
        if os.path.exists(path):
            auto_attach_file(path, unit=unit)
            return
        else:
            try:
                base_label = os.path.splitext(os.path.basename(clean_name))[0].upper()[:10]
                if is_opd:
                    disk = OpusDisk(path, disk_name=base_label)
                elif is_trd:
                    disk = TRDOSDisk(path, disk_name=base_label)
                elif is_dsk:
                    disk = Plus3Disk(path, disk_name=base_label)
                else:
                    disk = MGTDisk(path, disk_name=base_label)
                disk_drives[unit] = disk
                mgt_drives[unit] = disk
                canvas_print(f"Drive {unit}: Created and mounted '{os.path.basename(path)}' (\"{base_label}\", {disk.get_free_kb()}K free)")
            except Exception as e:
                canvas_print(f"Drive {unit}: Error creating '{clean_name}': {e}")
        update_display()
        return

def handle_attach_command(arg_str=""):
    handle_unified_attach(arg_str, default_cmd="ATTACH")


def handle_add_drive_command(stmt_str=""):
    handle_unified_attach(stmt_str, default_cmd="ADD DRIVE")


def _get_cartridge_file_list(drive_num):
    path = get_mdr_path(drive_num)
    if not (path and os.path.exists(path)):
        return []
    files = []
    try:
        with open(path, "rb") as f:
            data = f.read()
        seen = set()
        for i in range(254):
            offset = i * 543
            rec_offset = offset + 15
            if rec_offset + 14 > len(data): break
            recflg = data[rec_offset + 0]
            reclen = data[rec_offset + 2] + (data[rec_offset + 3] * 256)
            rec_name = data[rec_offset + 4 : rec_offset + 14]
            if recflg != 0xFF and reclen > 0 and rec_name.strip() != b'':
                fname = rec_name.decode('latin-1', errors='ignore').strip()
                if fname and fname not in seen:
                    seen.add(fname)
                    files.append(fname)
    except Exception:
        pass
    return files


def handle_boot_command(arg_str=""):
    global program, program_line_order, _z80_compiled_blocks, _split_cache, autorun_enabled, canvas_dirty
    global mgt_drives, disk_drives, microdrive_attachments, attached_tape_path, ram_disk, memory
    global active_disk_system, mgt_default_drive

    autorun_enabled = True
    raw_arg = (arg_str or "").strip()
    s = raw_arg
    s_upper = s.upper()
    if s_upper.startswith("BOOT"):
        s = s[4:].strip()
    if s.startswith(":") or s.startswith("="):
        s = s[1:].strip()
    s = s.strip()
    clean_arg = re.sub(r'["\']', '', s).strip()
    clean_u = clean_arg.upper()

    target_type = None
    target_unit = None

    # Check explicit target arguments:
    if clean_u in ("1", "A", "A:"):
        target_type = "floppy"
        target_unit = 1
    elif clean_u in ("2", "B", "B:"):
        target_type = "floppy"
        target_unit = 2
    elif clean_u in ("3", "C", "C:"):
        target_type = "floppy"
        target_unit = 3
    elif clean_u in ("4", "D", "D:"):
        target_type = "floppy"
        target_unit = 4
    elif clean_u.startswith("M") and len(clean_u) >= 2 and clean_u[1:2].isdigit():
        target_type = "microdrive"
        target_unit = max(1, min(8, int(clean_u[1:2])))
    elif clean_u.startswith("MDR") and any(c.isdigit() for c in clean_u):
        digits = "".join(c for c in clean_u if c.isdigit())
        target_type = "microdrive"
        target_unit = max(1, min(8, int(digits))) if digits else 1
    elif clean_u == "MDR":
        target_type = "microdrive"
        target_unit = 1
    elif clean_u in ("M", "M:", "RAM", "RAMDISK"):
        target_type = "ram"
    elif clean_u in ("T", "T:", "TAPE"):
        target_type = "tape"
    elif clean_arg and (clean_arg.lower().endswith(('.dsk', '.trd', '.scl', '.fdi', '.opd', '.mdr', '.tap', '.tzx', '.bas')) or os.path.exists(clean_arg)):
        target_drive = auto_attach_file(clean_arg)
        if clean_arg.lower().endswith('.mdr'):
            target_type = "microdrive"
            target_unit = target_drive or 1
        elif clean_arg.lower().endswith(('.tap', '.tzx')):
            target_type = "tape"
        else:
            target_type = "floppy"
            target_unit = target_drive or 1

    # Auto-discover first attached drive with bootable files
    if target_type is None:
        # Check Floppy Drive 1 (A:)
        d1 = disk_drives.get(1) or mgt_drives.get(1)
        d1_has_files = False
        if d1:
            try:
                if hasattr(d1, 'list_files') and len(d1.list_files()) > 0:
                    d1_has_files = True
                elif hasattr(d1, 'cpm_img') and d1.cpm_img and len(d1.cpm_img.get_files()) > 0:
                    d1_has_files = True
            except Exception:
                pass
        if not d1_has_files and 'cpm_system' in globals() and cpm_system and hasattr(cpm_system, 'mounted_disks'):
            if cpm_system.mounted_disks.get('A') and len(cpm_system.mounted_disks['A'].get_files()) > 0:
                d1_has_files = True

        if d1_has_files:
            target_type = "floppy"
            target_unit = 1
        else:
            # Check Floppy Drive 2 (B:)
            d2 = disk_drives.get(2) or mgt_drives.get(2)
            d2_has_files = False
            if d2:
                try:
                    if hasattr(d2, 'list_files') and len(d2.list_files()) > 0:
                        d2_has_files = True
                    elif hasattr(d2, 'cpm_img') and d2.cpm_img and len(d2.cpm_img.get_files()) > 0:
                        d2_has_files = True
                except Exception:
                    pass
            if not d2_has_files and 'cpm_system' in globals() and cpm_system and hasattr(cpm_system, 'mounted_disks'):
                if cpm_system.mounted_disks.get('B') and len(cpm_system.mounted_disks['B'].get_files()) > 0:
                    d2_has_files = True

            if d2_has_files:
                target_type = "floppy"
                target_unit = 2
            else:
                # Check Floppy Drive 3 (C:) and Drive 4 (D:)
                for du in (3, 4):
                    d_obj = disk_drives.get(du)
                    if d_obj:
                        try:
                            if hasattr(d_obj, 'list_files') and len(d_obj.list_files()) > 0:
                                target_type = "floppy"
                                target_unit = du
                                break
                        except Exception:
                            pass

        # Check Microdrives 1..8
        if target_type is None:
            for md_num in range(1, 9):
                md_path = get_mdr_path(md_num)
                if md_path and os.path.exists(md_path) and os.path.getsize(md_path) > 0:
                    md_files = _get_cartridge_file_list(md_num)
                    if md_files:
                        target_type = "microdrive"
                        target_unit = md_num
                        break

        # Check RAM disk M:
        if target_type is None:
            if ram_disk and len(ram_disk) > 0:
                target_type = "ram"

        # Check attached tape
        if target_type is None:
            if attached_tape_path and os.path.exists(attached_tape_path) and os.path.getsize(attached_tape_path) > 0:
                target_type = "tape"

        # Fallback: if Drive 1 is attached (even if 0 files), select Drive 1
        if target_type is None:
            d1 = disk_drives.get(1) or mgt_drives.get(1)
            if d1 is not None:
                target_type = "floppy"
                target_unit = 1

    # Execute Boot for Target:
    if target_type == "floppy":
        drv_idx = target_unit or 1
        drv_letter = chr(ord('A') + drv_idx - 1)
        disk = disk_drives.get(drv_idx) or mgt_drives.get(drv_idx)

        cpm_img = None
        if disk and hasattr(disk, 'cpm_img') and disk.cpm_img:
            cpm_img = disk.cpm_img
        elif 'cpm_system' in globals() and cpm_system and hasattr(cpm_system, 'mounted_disks'):
            cpm_img = cpm_system.mounted_disks.get(drv_letter)

        if disk is None and cpm_img is None:
            canvas_print(f"Drive {drv_letter}: No disk in drive")
            update_display()
            return

        # Plus3Disk (Spectrum +3DOS or CP/M disk)
        if (disk and isinstance(disk, Plus3Disk)) or (cpm_img and disk is None):
            p3 = disk if (disk and isinstance(disk, Plus3Disk)) else Plus3Disk()
            if cpm_img and hasattr(p3, 'cpm_img'):
                p3.cpm_img = cpm_img
            all_files = p3.list_files()

            basic_candidates = []
            com_candidates = []
            for f in all_files:
                fn = f["name"].upper()
                if f.get("type") == Plus3Disk.TYPE_BASIC or fn.endswith(".BAS"):
                    basic_candidates.append(f)
                elif fn.endswith(".COM") or fn.endswith(".SUB"):
                    com_candidates.append(f)

            if basic_candidates:
                preferred = ["DISK.BAS", "DISK", "BOOT.BAS", "BOOT", "AUTO.BAS", "AUTO", "MENU.BAS", "MENU", "START.BAS", "START", "RUN.BAS", "RUN"]
                boot_file = None
                for pref in preferred:
                    for bf in basic_candidates:
                        if bf["name"].upper() == pref or bf["name"].upper().split('.')[0] == pref.split('.')[0]:
                            boot_file = bf
                            break
                    if boot_file:
                        break
                if not boot_file:
                    boot_file = basic_candidates[0]

                try:
                    ftype, data, meta = p3.load_file(boot_file["name"])
                    parsed = parse_bas_file(data)
                    program.clear()
                    _z80_compiled_blocks.clear()
                    if 'program_line_order' in globals():
                        program_line_order.clear()
                    count = 0
                    for ln in sorted(parsed.keys()):
                        program[ln] = parsed[ln]
                        if 'program_line_order' in globals():
                            program_line_order.append(ln)
                        count += 1
                    parse_data_lines()
                    _split_cache.clear()
                    autorun_ln = meta.get("autorun_line") if meta else None
                    canvas_print(f"Booting '{boot_file['name']}' ({count} lines) from Drive {drv_letter}:")
                    update_display()
                    line_nums = program_line_order if ('program_line_order' in globals() and program_line_order and all(k in program for k in program_line_order)) else sorted(program.keys())
                    if line_nums:
                        start_idx = get_target_line_idx(autorun_ln, line_nums) if (autorun_ln is not None and autorun_ln in program) else 0
                        autorun_enabled = True
                        if is_execution_mode():
                            raise BASICJump(start_idx, 0)
                        else:
                            run_program(start_idx)
                    return
                except BASICJump:
                    raise
                except Exception as ex:
                    canvas_print(f"Error booting from Drive {drv_letter}: {ex}")
                    update_display()
                    return

            elif com_candidates or (all_files and any(f["name"].upper().endswith(('.COM', '.SUB', '.PAS', '.C', '.TXT')) for f in all_files)):
                cpm = get_cpm_system()
                cpm.sync_with_plus3_drives()
                if hasattr(p3, 'cpm_img') and p3.cpm_img:
                    cpm.mounted_disks[drv_letter] = p3.cpm_img
                cpm.current_drive = drv_letter
                canvas_print(f"Booting CP/M from Drive {drv_letter}:...")
                update_display()
                cpm.enter_cpm_mode(initial_cmd=f"BOOT {drv_letter}")
                return
            else:
                canvas_print(f"Drive {drv_letter}: No bootable files found on disk")
                update_display()
                return

        # TRDOSDisk
        elif disk and isinstance(disk, TRDOSDisk):
            all_files = disk.list_files()
            if not all_files:
                canvas_print(f"Drive {drv_letter}: No bootable files found on TR-DOS disk")
                update_display()
                return

            b_files = [f for f in all_files if f.get("raw_type") == 'B']
            c_files = [f for f in all_files if f.get("raw_type") == 'C']

            preferred_b = ["BOOT", "AUTO", "MENU", "START", "RUN", "128"]
            target_b = None
            for pref in preferred_b:
                for f in b_files:
                    if f["name"].upper() == pref:
                        target_b = f
                        break
                if target_b: break
            if not target_b and b_files:
                target_b = b_files[0]

            if target_b:
                try:
                    ftype, fdata, meta = disk.load_file(target_b["name"] + "." + target_b["raw_type"])
                    parsed = parse_bas_file(fdata)
                    program.clear()
                    _z80_compiled_blocks.clear()
                    if 'program_line_order' in globals():
                        program_line_order.clear()
                    count = 0
                    for ln in sorted(parsed.keys()):
                        program[ln] = parsed[ln]
                        if 'program_line_order' in globals():
                            program_line_order.append(ln)
                        count += 1
                    parse_data_lines()
                    _split_cache.clear()
                    autorun_ln = meta.get("autorun_line") if meta else None
                    canvas_print(f"Booting '{target_b['name']}.B' ({count} lines) from Drive {drv_letter}: (TR-DOS)")
                    update_display()
                    line_nums = sorted(program.keys())
                    if line_nums:
                        start_idx = get_target_line_idx(autorun_ln, line_nums) if (autorun_ln is not None and autorun_ln in program) else 0
                        autorun_enabled = True
                        if is_execution_mode():
                            raise BASICJump(start_idx, 0)
                        else:
                            run_program(start_idx)
                    return
                except BASICJump:
                    raise
                except Exception as ex:
                    canvas_print(f"TR-DOS boot error: {ex}")
                    update_display()
                    return

            boot_c = next((f for f in c_files if f["name"].upper() == "BOOT"), None)
            if boot_c:
                try:
                    ftype, fdata, meta = disk.load_file(boot_c["name"] + "." + boot_c["raw_type"])
                    addr = meta.get("start_addr", 16384) & 0xFFFF
                    for i, b in enumerate(fdata):
                        if addr + i < len(memory):
                            memory[addr + i] = b
                    canvas_print(f"Booting '{boot_c['name']}.C' ({len(fdata)} bytes at #{addr:04X}) from Drive {drv_letter}:")
                    update_display()
                    cpu = get_z80_cpu()
                    cpu.run_from(addr)
                    return
                except Exception as ex:
                    canvas_print(f"TR-DOS code boot error: {ex}")
                    update_display()
                    return

            canvas_print(f"Drive {drv_letter}: No bootable files found on TR-DOS disk")
            update_display()
            return

        # MGTDisk
        elif disk and isinstance(disk, MGTDisk):
            all_files = disk.list_files()
            if not all_files:
                canvas_print(f"Drive {drv_idx}: No bootable files found on MGT disk")
                update_display()
                return

            b_files = [f for f in all_files if f.get("type") == MGTDisk.TYPE_BASIC]
            preferred_mgt = ["AUTO", "BOOT", "RUN", "MENU", "START"]
            target_f = None
            for pref in preferred_mgt:
                for f in b_files:
                    if f["name"].upper() == pref:
                        target_f = f
                        break
                if target_f: break
            if not target_f and b_files:
                target_f = b_files[0]

            if target_f:
                try:
                    ftype, data, meta = disk.load_file(target_f["name"])
                    parsed = parse_bas_file(data)
                    program.clear()
                    _z80_compiled_blocks.clear()
                    if 'program_line_order' in globals():
                        program_line_order.clear()
                    count = 0
                    for ln in sorted(parsed.keys()):
                        program[ln] = parsed[ln]
                        if 'program_line_order' in globals():
                            program_line_order.append(ln)
                        count += 1
                    parse_data_lines()
                    _split_cache.clear()
                    autorun_ln = meta.get("autorun_line") if meta else None
                    canvas_print(f"Booting '{target_f['name']}' ({count} lines) from Drive {drv_idx} (MGT)")
                    update_display()
                    line_nums = sorted(program.keys())
                    if line_nums:
                        start_idx = get_target_line_idx(autorun_ln, line_nums) if (autorun_ln is not None and autorun_ln in program) else 0
                        autorun_enabled = True
                        if is_execution_mode():
                            raise BASICJump(start_idx, 0)
                        else:
                            run_program(start_idx)
                    return
                except BASICJump:
                    raise
                except Exception as ex:
                    canvas_print(f"MGT boot error: {ex}")
                    update_display()
                    return

            canvas_print(f"Drive {drv_idx}: No bootable BASIC files found on MGT disk")
            update_display()
            return

        # OpusDisk
        elif disk and isinstance(disk, OpusDisk):
            all_files = disk.list_files()
            if not all_files:
                canvas_print(f"Drive {drv_idx}: No bootable files found on Opus disk")
                update_display()
                return

            b_files = [f for f in all_files if f.get("type") == OpusDisk.TYPE_BASIC]
            preferred_opus = ["BOOT", "AUTO", "START", "RUN", "MENU"]
            target_f = None
            for pref in preferred_opus:
                for f in b_files:
                    if f["name"].upper() == pref:
                        target_f = f
                        break
                if target_f: break
            if not target_f and b_files:
                target_f = b_files[0]

            if target_f:
                try:
                    ftype, data, meta = disk.load_file(target_f["name"])
                    parsed = parse_bas_file(data)
                    program.clear()
                    _z80_compiled_blocks.clear()
                    if 'program_line_order' in globals():
                        program_line_order.clear()
                    count = 0
                    for ln in sorted(parsed.keys()):
                        program[ln] = parsed[ln]
                        if 'program_line_order' in globals():
                            program_line_order.append(ln)
                        count += 1
                    parse_data_lines()
                    _split_cache.clear()
                    autorun_ln = meta.get("autorun_line") if meta else None
                    canvas_print(f"Booting '{target_f['name']}' ({count} lines) from Drive {drv_idx} (Opus)")
                    update_display()
                    line_nums = sorted(program.keys())
                    if line_nums:
                        start_idx = get_target_line_idx(autorun_ln, line_nums) if (autorun_ln is not None and autorun_ln in program) else 0
                        autorun_enabled = True
                        if is_execution_mode():
                            raise BASICJump(start_idx, 0)
                        else:
                            run_program(start_idx)
                    return
                except BASICJump:
                    raise
                except Exception as ex:
                    canvas_print(f"Opus boot error: {ex}")
                    update_display()
                    return

            canvas_print(f"Drive {drv_idx}: No bootable BASIC files found on Opus disk")
            update_display()
            return

    elif target_type == "microdrive":
        md_idx = target_unit or 1
        md_p = get_mdr_path(md_idx)
        if not (md_p and os.path.exists(md_p)):
            canvas_print(f"Microdrive {md_idx}: No cartridge inserted")
            update_display()
            return
        files = _get_cartridge_file_list(md_idx)
        if not files:
            canvas_print(f"Microdrive {md_idx}: No files found on cartridge")
            update_display()
            return
        preferred_mdr = ["RUN", "BOOT", "AUTO", "MENU", "START"]
        boot_f = None
        for pref in preferred_mdr:
            for f in files:
                if f.upper() == pref:
                    boot_f = f
                    break
            if boot_f: break
        if not boot_f:
            boot_f = files[0]

        canvas_print(f"Booting '{boot_f}' from Microdrive {md_idx}:")
        update_display()
        mdr_load_program(md_idx, boot_f)
        if program and not is_execution_mode():
            line_nums = sorted(program.keys())
            if line_nums:
                autorun_enabled = True
                run_program(0)
        return

    elif target_type == "ram":
        if not ram_disk:
            canvas_print("RAM Disk M: No files found")
            update_display()
            return
        preferred_ram = ["BOOT", "AUTO", "START", "MENU", "RUN"]
        boot_f = None
        for pref in preferred_ram:
            for f in ram_disk:
                if f.upper() == pref:
                    boot_f = f
                    break
            if boot_f: break
        if not boot_f:
            boot_f = next(iter(ram_disk.keys()))

        canvas_print(f"Booting '{boot_f}' from RAM Disk M:")
        update_display()
        handle_load_command(f'"{boot_f}", M')
        if program and not is_execution_mode():
            line_nums = sorted(program.keys())
            if line_nums:
                autorun_enabled = True
                run_program(0)
        return

    elif target_type == "tape":
        if not (attached_tape_path and os.path.exists(attached_tape_path)):
            canvas_print("Tape: No tape attached")
            update_display()
            return
        canvas_print(f"Booting tape: {os.path.basename(attached_tape_path)}")
        update_display()
        handle_load_command('""')
        if program and not is_execution_mode():
            line_nums = sorted(program.keys())
            if line_nums:
                autorun_enabled = True
                run_program(0)
        return

    else:
        canvas_print("No attached drive or bootable media found.")
        canvas_print("Attach a disk (ATTACH \"file.dsk\", 1), cartridge, or tape and type BOOT.")
        update_display()
        return


def handle_format_command(arg_str):
    s = arg_str.strip()
    if s.startswith("*"): s = s[1:].strip()

    # Sinclair ZX Spectrum +3 disk format:
    # FORMAT "a:", FORMAT "a:label", FORMAT "a:", "label", FORMAT "b:", FORMAT "m:"
    s_eval = s
    if (s_eval.startswith('"') and s_eval.endswith('"')) or (s_eval.startswith("'") and s_eval.endswith("'")):
        try:
            val = evaluate_expr(s_eval)
            if isinstance(val, str) and val:
                s_eval = val
        except Exception:
            pass

    s_unquoted = re.sub(r'["\']', '', s_eval).strip()
    p3_fmt_match = re.match(r'^([ABMTabmt]):(?:\s*[,;]?\s*(.*?))?$', s_unquoted)
    if not p3_fmt_match and s_unquoted.upper() in ("A", "B", "M", "T"):
        p3_fmt_match = re.match(r'^([ABMTabmt])()$', s_unquoted)

    if p3_fmt_match:
        drv = p3_fmt_match.group(1).upper()
        raw_label = p3_fmt_match.group(2)
        disk_label = raw_label.strip() if raw_label and raw_label.strip() else f"DRIVE {drv}"
        if drv in ("A", "B"):
            d_num = 1 if drv == "A" else 2
            disk = get_mgt_disk(d_num)
            if disk is None:
                dsk_path = os.path.join(os.getcwd(), f"drive{d_num}.dsk")
                disk = Plus3Disk(dsk_path, disk_name=disk_label)
                mgt_drives[d_num] = disk
            else:
                disk.format_disk(disk_label)
                if hasattr(disk, 'save_fdi'):
                    disk.save_fdi()
            canvas_print(f"Drive {drv}: formatted as '{disk.get_disk_name()}' ({disk.get_free_kb()}K free)")
            return
        elif drv == "M":
            ram_disk.clear()
            ram_disk_arrays.clear()
            canvas_print("RAM Disk M: formatted (64K free)")
            return
        elif drv == "T":
            canvas_print("Error: Tape drive T: cannot be formatted")
            return

    # MGT Floppy format:
    # FORMAT d1, FORMAT d2, FORMAT d1;"label", FORMAT d2;"label", FORMAT d1, "label", FORMAT *"d";1;"label"
    mgt_match = re.match(r'^(?:["\']?[Dd]["\']\s*[;,]\s*([12\*])?|["\']?[Dd]\s*([12\*])?)(?:\s*[;,]\s*["\']?([^"\']*)["\']?)?$', s)
    if mgt_match and (mgt_match.group(1) or mgt_match.group(2) or s.lower().startswith('d') or s.lower().startswith('"d"')):
        d_str = mgt_match.group(1) or mgt_match.group(2)
        d_num = mgt_default_drive if (not d_str or d_str == '*') else int(d_str)
        raw_label = mgt_match.group(3)
        disk_label = raw_label.strip() if raw_label and raw_label.strip() else f"DISC {d_num}"
        disk = get_mgt_disk(d_num)
        if disk is None:
            fdi_path = os.path.join(os.getcwd(), f"drive{d_num}.fdi")
            disk = MGTDisk(fdi_path, disk_name=disk_label)
            mgt_drives[d_num] = disk
        else:
            disk.format_disk(disk_label)
            if disk.filepath:
                disk.save_fdi()
        canvas_print(f"Drive {d_num} formatted as '{disk.get_disk_name()}' (780K free)")
        return
    
    match_ser = re.match(r'^["\']?([BbTt])["\']?\s*;\s*(\d+)$', s)
    if match_ser:
        ch = match_ser.group(1).lower()
        baud = int(match_ser.group(2))
        serial_baud[ch] = baud
        canvas_print(f"RS-232 '{ch}' baud rate set to {baud}")
        return
        
    match_net = re.match(r'^["\']?[Nn]["\']?\s*;\s*(\d+)$', s)
    if match_net:
        global current_net_station
        st = int(match_net.group(1))
        if 1 <= st <= 64:
            current_net_station = st
            canvas_print(f"Network station set to {st}")
        else:
            canvas_print("Error: Station number must be 1-64")
        return
        
    match_mdv = re.match(r'^(?:["\']?[Mm]["\']?\s*;\s*)?(\d+)\s*;\s*["\']?([^"\']+)["\']?$', s)
    if match_mdv:
        d_num = int(match_mdv.group(1))
        c_name = match_mdv.group(2).strip()
        if 1 <= d_num <= 8:
            path = get_mdr_path(d_num)
            create_blank_mdr(path, c_name)
            canvas_print(f"Microdrive {d_num} formatted as '{c_name}'")
        else:
            canvas_print("Error: Drive number must be 1-8")
        return
        
    clean_name = s.strip('"\'')
    if clean_name:
        path = get_mdr_path(1)
        create_blank_mdr(path, clean_name)
        canvas_print(f"Microdrive 1 formatted as '{clean_name}'")
    else:
        canvas_print("Syntax: FORMAT \"m\";drive;\"cartridge_name\" or FORMAT d1;\"disk_name\"")


def handle_cat_command(arg_str):
    s = arg_str.strip()
    if s.startswith("*"): s = s[1:].strip()
    
    # Check for 128K RAM Disk (Silicon Disc): CAT !
    if s == "!" or s.startswith("!"):
        canvas_print("--- RAM DISK (128K) ---")
        if not ram_disk:
            canvas_print("RAM Disk Empty")
        else:
            total_bytes = 0
            for fname, finfo in sorted(ram_disk.items()):
                ftype = finfo.get("type", "CODE") if isinstance(finfo, dict) else "DATA"
                fsize = finfo.get("size", len(finfo.get("data", b""))) if isinstance(finfo, dict) else len(finfo)
                total_bytes += fsize
                canvas_print(f"{fname:<12} {ftype:<8} {fsize:>5}B")
            free_bytes = max(0, 65536 - total_bytes)
            canvas_print(f"Used: {total_bytes}B  Free: {free_bytes}B")
        return

    stream_idx = None
    match_stream = re.match(r'^#\s*(\d+)(?:\s*;\s*(.*))?$', s)
    if match_stream:
        stream_idx = int(match_stream.group(1))
        s = match_stream.group(2).strip() if match_stream.group(2) else ""
    
    out_func = (lambda msg: streams[stream_idx].write(msg + "\n")) if (stream_idx is not None and stream_idx in streams and streams[stream_idx]) else canvas_print

    abbreviated = False
    if s.endswith("!"):
        abbreviated = True
        s = s[:-1].strip()

    # Check for Sinclair +3 CAT EXP (expanded directory)
    is_expanded = False
    s_exp_test = s.strip().strip('"\'')
    if s_exp_test.upper().startswith("EXP"):
        is_expanded = True
        rem_exp = s_exp_test[3:].strip()
        s = rem_exp

    # Check for Sinclair +3 drive specifier: A:, B:, M:, T:
    s_eval = s
    if (s_eval.startswith('"') and s_eval.endswith('"')) or (s_eval.startswith("'") and s_eval.endswith("'")):
        try:
            val = evaluate_expr(s_eval)
            if isinstance(val, str) and val:
                s_eval = val
        except Exception:
            pass
    s_clean = s_eval.strip().strip('"\'')

    # If is_expanded and s_clean is empty, default to Drive A:
    if is_expanded and not s_clean:
        s_clean = "A:"

    p3_cat_match = re.match(r'^([ABMTabmt]):(?:\s*(.*?))?$', s_clean)
    if not p3_cat_match and s_clean.upper() in ("A", "B", "M", "T"):
        p3_cat_match = re.match(r'^([ABMTabmt])()$', s_clean)

    if p3_cat_match:
        drv = p3_cat_match.group(1).upper()
        raw_pattern = p3_cat_match.group(2).strip(' "\'') if p3_cat_match.group(2) else "*"
        pattern = raw_pattern if raw_pattern else "*"
        
        if drv in ("A", "B"):
            d_num = 1 if drv == "A" else 2
            disk = get_mgt_disk(d_num)
            if disk is None:
                out_func(f"Drive {drv}: No disk in drive")
                return
            all_files = disk.list_files()
            if pattern and pattern not in ("", "*", "*.*"):
                files = [f for f in all_files if fnmatch.fnmatch(f["name"].lower(), pattern.lower())]
            else:
                files = all_files

            type_names = {
                MGTDisk.TYPE_BASIC: "BASIC",
                MGTDisk.TYPE_NUM_ARRAY: "DATA()",
                MGTDisk.TYPE_CHAR_ARRAY: "DATA$",
                MGTDisk.TYPE_CODE: "CODE",
                MGTDisk.TYPE_SCREEN: "SCREEN$"
            }
            if is_expanded:
                out_func(f"--- DRIVE {drv}: EXPANDED CAT ---")
                out_func(f"Disk: \"{disk.get_disk_name()}\"")
                out_func("Filename    Type       Size   Attrs")
                out_func("-----------------------------------")
                tot_bytes = 0
                for f in files:
                    tname = type_names.get(f["type"], "FILE")
                    fbytes = f["sectors"] * 512
                    tot_bytes += fbytes
                    out_func(f"{f['name']:<11} {tname:<10} {fbytes:>5}B  R/W")
                out_func("-----------------------------------")
                out_func(f"Files: {len(files)}  Used: {tot_bytes // 1024}K  Free: {disk.get_free_kb()}K")
            else:
                out_func(f"--- DRIVE {drv}: CAT ---")
                out_func(f"Disk: \"{disk.get_disk_name()}\"")
                if not files:
                    out_func("  (No files found)")
                else:
                    for f in files:
                        tname = type_names.get(f["type"], "FILE")
                        out_func(f"  {f['name']:<12} ({tname})")
                out_func(f"Free: {disk.get_free_kb()}K")
            return

        elif drv == "M":
            items = []
            for fname, finfo in sorted(ram_disk.items()):
                if pattern and pattern not in ("", "*", "*.*"):
                    if not fnmatch.fnmatch(fname.lower(), pattern.lower()):
                        continue
                items.append((fname, finfo))
            total_bytes = 0
            for fname, finfo in items:
                fsize = finfo.get("size", len(finfo.get("data", b""))) if isinstance(finfo, dict) else len(finfo)
                total_bytes += fsize
            free_bytes = max(0, 65536 - total_bytes)

            if is_expanded:
                out_func("--- RAM DISK M: EXPANDED CAT ---")
                out_func("Filename    Type       Size   Attrs")
                out_func("-----------------------------------")
                if not items:
                    out_func("  (RAM Disk Empty)")
                else:
                    for fname, finfo in items:
                        ftype = finfo.get("type", "CODE") if isinstance(finfo, dict) else "DATA"
                        fsize = finfo.get("size", len(finfo.get("data", b""))) if isinstance(finfo, dict) else len(finfo)
                        out_func(f"{fname:<11} {ftype:<10} {fsize:>5}B  R/W")
                out_func("-----------------------------------")
                out_func(f"Files: {len(items)}  Used: {total_bytes}B  Free: {free_bytes}B")
            else:
                out_func("--- RAM DISK M: CAT ---")
                if not items:
                    out_func("  (RAM Disk Empty)")
                else:
                    for fname, finfo in items:
                        ftype = finfo.get("type", "CODE") if isinstance(finfo, dict) else "DATA"
                        out_func(f"  {fname:<12} ({ftype})")
                out_func(f"Free: {free_bytes}B")
            return

        elif drv == "T":
            out_func("--- TAPE T: CAT ---")
            if attached_tape_path and os.path.exists(attached_tape_path):
                out_func(f"Attached Tape: {os.path.basename(attached_tape_path)}")
            else:
                out_func("No tape attached (use ATTACH \"filename.tap\")")
            return

    # Check for MGT drive specifier (d1, d2, d*, "d";1, etc.)
    mgt_cat_match = re.match(r'^(?:["\']?[Dd]["\']\s*[;,]\s*([12\*])?|["\']?[Dd]\s*([12\*])?)$', s)
    if mgt_cat_match and (mgt_cat_match.group(1) or mgt_cat_match.group(2) or s.lower().startswith('d') or s.lower().startswith('"d"')):
        d_str = mgt_cat_match.group(1) or mgt_cat_match.group(2)
        drive = mgt_default_drive if (not d_str or d_str == '*') else int(d_str)
        mgt_cat(drive, stream_idx=stream_idx, abbreviated=abbreviated)
        return

    # If s is purely 1, 2, or *
    if s in ("1", "2", "*"):
        d_val = mgt_default_drive if s == '*' else int(s)
        if mgt_drives.get(d_val) is not None or abbreviated:
            mgt_cat(d_val, stream_idx=stream_idx, abbreviated=abbreviated)
            return
        cand1 = os.path.join(os.getcwd(), f"drive{d_val}.fdi")
        cand2 = os.path.join(get_zx_folder(), f"drive{d_val}.fdi")
        if os.path.exists(cand1) or os.path.exists(cand2):
            mgt_cat(d_val, stream_idx=stream_idx, abbreviated=abbreviated)
            return

    drive = 1
    if s:
        match_m = re.match(r'^(?:["\']?[Mm]["\']?\s*;\s*)?(\d+)', s)
        if match_m:
            drive = int(match_m.group(1))
        else:
            try:
                drive = int(evaluate_expr(s))
            except:
                drive = 1
                
    if 1 <= drive <= 8:
        mdr_cat(drive, stream_idx=stream_idx)
    else:
        canvas_print("Error: Drive number must be 1-8")


def handle_erase_command(arg_str):
    s = arg_str.strip()
    if s.startswith("*"): s = s[1:].strip()
    
    dev_info = parse_device_spec(s)
    if dev_info["type"] == "plus3":
        drive = dev_info.get("drive_num", 1)
        drv_letter = dev_info.get("drive", "A")
        fname = dev_info.get("name", "")
        disk = get_mgt_disk(drive)
        if disk is None:
            canvas_print(f"Drive {drv_letter}: No disk in drive")
            return
        if fname in ("*", "*.*"):
            count = 0
            for f in disk.list_files():
                try:
                    disk.erase_file(f["name"])
                    count += 1
                except Exception:
                    pass
            canvas_print(f"Erased {count} files from Drive {drv_letter}:")
            return
        try:
            disk.erase_file(fname)
            canvas_print(f"Erased '{fname}' from Drive {drv_letter}:")
        except Exception as e:
            canvas_print(f"Error erasing '{fname}' on Drive {drv_letter}:: {e}")
        return

    if dev_info["type"] == "ram":
        fname = dev_info.get("name", "")
        if fname in ("*", "*.*"):
            count = len(ram_disk)
            ram_disk.clear()
            canvas_print(f"Erased all {count} files from RAM Disk")
            return
        if fname in ram_disk:
            del ram_disk[fname]
            canvas_print(f"Erased '{fname}' from RAM Disk")
        else:
            canvas_print(f"File not found on RAM Disk: '{fname}'")
        return

    if dev_info["type"] == "d":
        drive = dev_info.get("drive", mgt_default_drive)
        fname = dev_info.get("name", "")
        disk = get_mgt_disk(drive)
        if disk is None:
            canvas_print(f"Drive {drive}: No disk in drive (use ATTACH \"filename\", {drive}, FDI)")
            return
        try:
            disk.erase_file(fname)
            canvas_print(f"Erased '{fname}' from Drive {drive} ({os.path.basename(disk.filepath)})")
        except Exception as e:
            canvas_print(f"Error erasing '{fname}' on Drive {drive}: {e}")
        return

    match_mdv = re.match(r'^(?:["\']?[Mm]["\']?\s*;\s*)?(\d+)\s*;\s*["\']?([^"\']+)["\']?$', s)
    if match_mdv:
        d_num = int(match_mdv.group(1))
        fname = match_mdv.group(2).strip()
        mdr_erase_file(d_num, fname)
        return
        
    clean_fname = s.strip('"\'')
    if clean_fname:
        mdr_erase_file(1, clean_fname)
    else:
        canvas_print("Syntax: ERASE \"a:filename\", ERASE \"m:filename\", ERASE \"m\";drive;\"filename\" or ERASE d1\"filename\"")


def handle_move_command(src_str, dst_str):
    src_info = parse_device_spec(src_str)
    dst_info = parse_device_spec(dst_str)
    
    # Check for same-drive rename on +3 disk:
    if src_info.get("type") == "plus3" and dst_info.get("type") == "plus3" and src_info.get("drive_num") == dst_info.get("drive_num"):
        d_num = src_info.get("drive_num", 1)
        drv_letter = src_info.get("drive", "A")
        disk = get_mgt_disk(d_num)
        if disk is None:
            canvas_print(f"Drive {drv_letter}: No disk in drive")
            return
        try:
            disk.rename_file(src_info["name"], dst_info["name"])
            canvas_print(f"Renamed '{src_info['name']}' to '{dst_info['name']}' on Drive {drv_letter}:")
            return
        except Exception as e:
            canvas_print(f"Error renaming file on Drive {drv_letter}:: {e}")
            return

    # Check for same RAM disk rename:
    if src_info.get("type") == "ram" and dst_info.get("type") == "ram":
        sname = src_info.get("name", "")
        dname = dst_info.get("name", "")
        if sname in ram_disk:
            ram_disk[dname] = ram_disk.pop(sname)
            canvas_print(f"Renamed '{sname}' to '{dname}' on RAM Disk M:")
            return
        else:
            canvas_print(f"File not found on RAM Disk: '{sname}'")
            return

    # Cross-device move: read source file, preserve metadata if possible, write destination, erase source
    if src_info.get("type") in ("plus3", "d"):
        d_num = src_info.get("drive_num", src_info.get("drive", 1))
        disk = get_mgt_disk(d_num)
        if not disk or not disk.find_file(src_info["name"]):
            canvas_print(f"Source file not found: {src_str}")
            return
        ftype, data, meta = disk.load_file(src_info["name"])
        if dst_info.get("type") in ("plus3", "d"):
            dst_num = dst_info.get("drive_num", dst_info.get("drive", 1))
            dst_disk = get_mgt_disk(dst_num)
            if not dst_disk:
                fdi_path = os.path.join(os.getcwd(), f"drive{dst_num}.fdi")
                dst_disk = MGTDisk(fdi_path, disk_name=f"DRIVE {dst_info.get('drive', dst_num)}")
                mgt_drives[dst_num] = dst_disk
            dst_disk.save_file(dst_info["name"], ftype, data, autorun_line=meta.get("autorun_line"), start_addr=meta.get("start_addr"), data_length=meta.get("length"))
        elif dst_info.get("type") == "ram":
            ram_disk[dst_info["name"]] = {"type": ("BASIC" if ftype == 1 else "CODE"), "data": data, "size": len(data), "autorun_line": meta.get("autorun_line"), "start_addr": meta.get("start_addr")}
        else:
            write_device_bytes(dst_info, data)
        try:
            disk.erase_file(src_info["name"])
        except Exception:
            pass
        canvas_print(f"Moved '{src_info['name']}' ({len(data)} bytes) to {dst_str}")
        return

    elif src_info.get("type") == "ram":
        sname = src_info.get("name", "")
        if sname not in ram_disk:
            canvas_print(f"Source file not found on RAM Disk: '{sname}'")
            return
        finfo = ram_disk.pop(sname)
        data = finfo.get("data", b"") if isinstance(finfo, dict) else finfo
        if dst_info.get("type") in ("plus3", "d"):
            dst_num = dst_info.get("drive_num", dst_info.get("drive", 1))
            dst_disk = get_mgt_disk(dst_num)
            if not dst_disk:
                fdi_path = os.path.join(os.getcwd(), f"drive{dst_num}.fdi")
                dst_disk = MGTDisk(fdi_path, disk_name=f"DRIVE {dst_info.get('drive', dst_num)}")
                mgt_drives[dst_num] = dst_disk
            ftype = MGTDisk.TYPE_BASIC if (isinstance(finfo, dict) and finfo.get("type") == "PROG") else MGTDisk.TYPE_CODE
            dst_disk.save_file(dst_info["name"], ftype, data, autorun_line=(finfo.get("autorun_line") if isinstance(finfo, dict) else None), start_addr=(finfo.get("start_addr") if isinstance(finfo, dict) else None))
        else:
            write_device_bytes(dst_info, data)
        canvas_print(f"Moved '{sname}' ({len(data)} bytes) from RAM Disk to {dst_str}")
        return
    else:
        data = read_device_bytes(src_info)
        if not data:
            canvas_print(f"Source file not found or empty: {src_str}")
            return
        write_device_bytes(dst_info, data)
        handle_erase_command(src_str)
        canvas_print(f"Moved {len(data)} bytes from {src_str} to {dst_str}")


def parse_and_handle_move(arg_str):
    s = arg_str.strip()
    if s.startswith("*"): s = s[1:].strip()
    match = re.split(r'\s+TO\s+', s, flags=re.IGNORECASE)
    if len(match) == 2:
        handle_move_command(match[0].strip(), match[1].strip())
    else:
        canvas_print("Syntax: MOVE dev1 TO dev2")


def handle_copy_command(arg_str):
    global canvas_dirty
    s = (arg_str or "").strip()
    if not s or s.upper() in ("SCREEN", "SCREEN$", "SCREEN$ TO LPRINT", "SCREEN TO LPRINT", "SCREEN$ TO PRINTER", "SCREEN TO PRINTER"):
        # Bare COPY or COPY SCREEN: screen copy to PDF printer
        if zx_printer:
            zx_printer.print_screen()
            zx_printer.flush()
        printer_stream = streams[3] if (3 in streams and streams[3]) else (streams[2] if (2 in streams and streams[2]) else None)
        if printer_stream:
            printer_stream.write("\n--- ZX SPECTRUM SCREEN COPY ---\n")
            for line in canvas_lines:
                printer_stream.write(line + "\n")
            printer_stream.write("---------------------------------\n")
        canvas_print("Screen copied to printer")
        return

    match = re.split(r'\s+TO\s+', s, flags=re.IGNORECASE)
    if len(match) != 2:
        canvas_print("Syntax: COPY \"dev1:file\" TO \"dev2:file\" or COPY \"dev:file\" TO SCREEN$ / LPRINT")
        return

    src_part = match[0].strip()
    dst_part = match[1].strip()
    dst_upper = dst_part.upper().strip('"\'')
    src_upper = src_part.upper().strip('"\'')

    # COPY SCREEN$ TO LPRINT / PRINTER
    if src_upper in ("SCREEN$", "SCREEN") and dst_upper in ("LPRINT", "PRINTER", "P"):
        if zx_printer:
            zx_printer.print_screen()
            zx_printer.flush()
        canvas_print("Screen copied to printer")
        return

    src_info = parse_device_spec(src_part)

    # 1. COPY to SCREEN$
    if dst_upper in ("SCREEN$", "SCREEN"):
        data = read_device_bytes(src_info)
        if not data:
            canvas_print(f"Source file not found or empty: {src_part}")
            return
        if len(data) >= 6912:
            for scr_y in range(192):
                third = scr_y // 64
                row_in_third = (scr_y % 64) // 8
                line_in_row = scr_y % 8
                y = 191 - scr_y
                for x in range(32):
                    addr = (third * 2048) + (row_in_third * 32) + (line_in_row * 256) + x
                    if addr < len(data):
                        byte_val = data[addr]
                        for bit in range(8):
                            px = x * 8 + bit
                            if px < 256: gfx_bits[px][y] = bool((byte_val >> (7 - bit)) & 1)
            for r in range(24):
                for c in range(32):
                    addr = 6144 + (r * 32) + c
                    if addr < len(data):
                        attr_byte = data[addr]
                        attr_ink[r][c] = attr_byte & 7
                        attr_paper[r][c] = (attr_byte >> 3) & 7
                        attr_bright[r][c] = bool(attr_byte & 64)
                        attr_flash[r][c] = bool(attr_byte & 128)
                        attr_used[r][c] = True
            canvas_dirty = True
            redraw_canvas()
            update_display()
            canvas_print(f"Copied '{src_part}' to SCREEN$")
        else:
            canvas_print(f"Error: '{src_part}' is not valid screen data ({len(data)} bytes < 6912)")
        return

    # 2. COPY to LPRINT
    if dst_upper in ("LPRINT", "PRINTER", "P"):
        data = read_device_bytes(src_info)
        if not data:
            canvas_print(f"Source file not found or empty: {src_part}")
            return
        if zx_printer:
            is_scr = len(data) >= 6912 and (src_part.lower().endswith(".scr") or src_info.get("name", "").lower().endswith(".scr"))
            if is_scr:
                zx_printer.print_screen(scr_bytes=data)
            else:
                text = data.decode('latin-1', errors='replace')
                zx_printer.print_text(f"--- COPY {src_part} TO LPRINT ---")
                for line in text.splitlines():
                    zx_printer.print_text(line)
            zx_printer.flush()
        printer_stream = streams[3] if (3 in streams and streams[3]) else (streams[2] if (2 in streams and streams[2]) else None)
        if printer_stream:
            text = data.decode('latin-1', errors='replace')
            printer_stream.write(f"\n--- COPY {src_part} TO LPRINT ---\n")
            printer_stream.write(text + "\n")
            printer_stream.write("---------------------------------\n")
        canvas_print(f"Copied '{src_part}' ({len(data)} bytes) to LPRINT")
        return

    # 3. File copy between devices
    dst_info = parse_device_spec(dst_part)

    if src_info.get("type") in ("plus3", "d"):
        d_num = src_info.get("drive_num", src_info.get("drive", 1))
        disk = get_mgt_disk(d_num)
        if not disk or not disk.find_file(src_info["name"]):
            canvas_print(f"Source file not found: {src_part}")
            return
        ftype, data, meta = disk.load_file(src_info["name"])
        if dst_info.get("type") in ("plus3", "d"):
            dst_num = dst_info.get("drive_num", dst_info.get("drive", 1))
            dst_disk = get_mgt_disk(dst_num)
            if not dst_disk:
                fdi_path = os.path.join(os.getcwd(), f"drive{dst_num}.fdi")
                dst_disk = MGTDisk(fdi_path, disk_name=f"DRIVE {dst_info.get('drive', dst_num)}")
                mgt_drives[dst_num] = dst_disk
            dst_disk.save_file(dst_info["name"], ftype, data, autorun_line=meta.get("autorun_line"), start_addr=meta.get("start_addr"), data_length=meta.get("length"))
        elif dst_info.get("type") == "ram":
            ram_disk[dst_info["name"]] = {"type": ("BASIC" if ftype == 1 else "CODE"), "data": data, "size": len(data), "autorun_line": meta.get("autorun_line"), "start_addr": meta.get("start_addr")}
        else:
            write_device_bytes(dst_info, data)
        canvas_print(f"Copied '{src_info['name']}' ({len(data)} bytes) to {dst_part}")
        return

    elif src_info.get("type") == "ram":
        sname = src_info.get("name", "")
        if sname not in ram_disk:
            canvas_print(f"Source file not found on RAM Disk: '{sname}'")
            return
        finfo = ram_disk[sname]
        data = finfo.get("data", b"") if isinstance(finfo, dict) else finfo
        if dst_info.get("type") in ("plus3", "d"):
            dst_num = dst_info.get("drive_num", dst_info.get("drive", 1))
            dst_disk = get_mgt_disk(dst_num)
            if not dst_disk:
                fdi_path = os.path.join(os.getcwd(), f"drive{dst_num}.fdi")
                dst_disk = MGTDisk(fdi_path, disk_name=f"DRIVE {dst_info.get('drive', dst_num)}")
                mgt_drives[dst_num] = dst_disk
            ftype = MGTDisk.TYPE_BASIC if (isinstance(finfo, dict) and finfo.get("type") == "PROG") else MGTDisk.TYPE_CODE
            dst_disk.save_file(dst_info["name"], ftype, data, autorun_line=(finfo.get("autorun_line") if isinstance(finfo, dict) else None), start_addr=(finfo.get("start_addr") if isinstance(finfo, dict) else None))
        elif dst_info.get("type") == "ram":
            import copy
            ram_disk[dst_info["name"]] = copy.deepcopy(finfo)
        else:
            write_device_bytes(dst_info, data)
        canvas_print(f"Copied '{sname}' ({len(data)} bytes) to {dst_part}")
        return

    else:
        data = read_device_bytes(src_info)
        if not data:
            canvas_print(f"Source file not found or empty: {src_part}")
            return
        write_device_bytes(dst_info, data)
        canvas_print(f"Copied {len(data)} bytes from {src_part} to {dst_part}")


def handle_save_command(arg_str):
    if is_execution_mode() and 'program' in globals() and any('SOFTLOCK' in str(v).upper() for v in program.values()):
        return
    s = arg_str.strip()
    if s.startswith("*"):
        s = s[1:].strip()
    
    upper_s = s.upper()
    mode = "PROG"
    code_start = 16384
    code_len = 6912
    autorun_line = None
    spec_part = s
    
    data_arr_name = None
    if "SCREEN$" in upper_s:
        mode = "SCREEN$"
        idx = upper_s.index("SCREEN$")
        spec_part = s[:idx].strip()
    elif "DATA " in upper_s:
        mode = "DATA"
        idx = upper_s.index("DATA ")
        spec_part = s[:idx].strip()
        data_arg = s[idx + 5:].strip()
        m_arr = re.match(r"^(!?[A-Za-z][A-Za-z0-9]*\$?)\s*\(\s*\)", data_arg)
        if m_arr:
            data_arr_name = m_arr.group(1).upper()
    elif "CODE" in upper_s:
        mode = "CODE"
        idx = upper_s.index("CODE")
        spec_part = s[:idx].strip()
        code_args = s[idx + 4:].strip()
        if code_args:
            c_parts = split_top_level_commas(code_args)
            if len(c_parts) >= 1 and c_parts[0].strip():
                try: code_start = int(evaluate_expr(c_parts[0]))
                except: code_start = 16384
            if len(c_parts) >= 2 and c_parts[1].strip():
                try: code_len = int(evaluate_expr(c_parts[1]))
                except: code_len = 6912
    elif "LINE" in upper_s:
        idx = upper_s.index("LINE")
        spec_part = s[:idx].strip()
        line_arg = s[idx + 4:].strip()
        try: autorun_line = int(evaluate_expr(line_arg))
        except: autorun_line = None
    # Check for explicit format specifier such as ,zxb or ,tap or ,forth or ,zxf or ,rom or ,bin (case-insensitive)
    m_fmt = re.search(r'[, ]\s*(ZXB|TAP|FORTH|ZXF|ROM|BIN)\b', spec_part, flags=re.IGNORECASE)
    if m_fmt:
        mode = m_fmt.group(1).upper()
        if mode == "ZXF": mode = "FORTH"
        elif mode in ("ROM", "BIN"): mode = "ROM"
        spec_part = (spec_part[:m_fmt.start()] + spec_part[m_fmt.end():]).strip()
        if spec_part.endswith(","):
            spec_part = spec_part[:-1].strip()
    
    dev_info = parse_device_spec(spec_part)
    dev_type = dev_info["type"]
    
    if dev_type == "ram":
        fname = dev_info.get("name", "unnamed")
        if mode == "SCREEN$":
            block = bytearray(6912)
            for scr_y in range(192):
                third = scr_y // 64
                row_in_third = (scr_y % 64) // 8
                line_in_row = scr_y % 8
                y = 191 - scr_y
                for x in range(32):
                    addr = (third * 2048) + (row_in_third * 32) + (line_in_row * 256) + x
                    byte_val = 0
                    for bit in range(8):
                        px = x * 8 + bit
                        if px < 256 and gfx_bits[px][y]:
                            byte_val |= (1 << (7 - bit))
                    block[addr] = byte_val
            for r in range(24):
                for c in range(32):
                    addr = 6144 + (r * 32) + c
                    ink = attr_ink[r][c] & 7
                    paper = (attr_paper[r][c] & 7) << 3
                    bright = 64 if attr_bright[r][c] else 0
                    flash = 128 if attr_flash[r][c] else 0
                    block[addr] = ink | paper | bright | flash
            ram_disk[fname] = {"type": "SCREEN$", "data": bytes(block), "size": len(block)}
            canvas_print(f"Saved SCREEN$ '{fname}' to RAM Disk")
        elif mode == "CODE":
            block = bytes(memory[code_start : code_start + code_len])
            ram_disk[fname] = {"type": "CODE", "data": block, "start_addr": code_start, "size": len(block)}
            canvas_print(f"Saved CODE '{fname}' ({code_start}, {code_len}) to RAM Disk")
        elif mode == "ROM":
            block = bytes(memory[0x0000:0x4000])
            ram_disk[fname] = {"type": "ROM", "data": block, "start_addr": 0, "size": len(block)}
            canvas_print(f"Saved Interface 2 ROM '{fname}' (16384 bytes) to RAM Disk")
        elif mode == "DATA" and data_arr_name:
            arr_data = bytearray()
            target_dict = ram_disk_arrays if data_arr_name.startswith("!") else arrays
            if data_arr_name in string_variables:
                arr_data.extend(string_variables[data_arr_name].encode('latin-1', errors='ignore'))
            else:
                val = None
                if data_arr_name in target_dict:
                    val = target_dict[data_arr_name]
                elif data_arr_name.startswith("!") and data_arr_name[1:] in arrays:
                    val = arrays[data_arr_name[1:]]
                elif (not data_arr_name.startswith("!")) and f"!{data_arr_name}" in ram_disk_arrays:
                    val = ram_disk_arrays[f"!{data_arr_name}"]
                if val is not None:
                    import json
                    if isinstance(val, tuple) and len(val) == 2:
                        dims, arr_dict = val
                        arr_data.extend(json.dumps({"dims": dims, "data": {str(k): v for k, v in arr_dict.items()}}).encode('utf-8'))
                    else:
                        arr_data.extend(json.dumps({"data": val}).encode('utf-8'))
            ram_disk[fname] = {"type": "DATA", "arr_name": data_arr_name, "data": bytes(arr_data), "size": len(arr_data)}
            canvas_print(f"Saved DATA '{data_arr_name}' as '{fname}' to RAM Disk")
        else:
            prog_lines = []
            if autorun_line is not None:
                prog_lines.append(f"AUTORUN={autorun_line}")
            for ln in sorted(program.keys()):
                prog_lines.append(f"{ln} {program[ln]}")
            prog_bytes = ("\r\n".join(prog_lines) + "\r\n").encode('latin-1', errors='ignore')
            ram_disk[fname] = {"type": "PROG", "data": prog_bytes, "autorun_line": autorun_line, "size": len(prog_bytes)}
            canvas_print(f"Saved '{fname}' ({len(program)} lines) to RAM Disk")
        return
    elif dev_type in ("d", "plus3"):
        drive = dev_info.get("drive_num", dev_info.get("drive", mgt_default_drive))
        fname = dev_info.get("name", "unnamed")
        drv_label = f"Drive {dev_info.get('drive', drive)}:" if dev_type == "plus3" else f"Drive {drive}"
        disk = get_mgt_disk(drive)
        if disk is None:
            fdi_path = os.path.join(os.getcwd(), f"drive{drive}.fdi")
            disk = MGTDisk(fdi_path, disk_name=f"DRIVE {dev_info.get('drive', drive)}")
            mgt_drives[drive] = disk
        if mode == "SCREEN$":
            simulate_tape_loading_border("Saving SCREEN$")
            block = bytearray(6912)
            for scr_y in range(192):
                third = scr_y // 64
                row_in_third = (scr_y % 64) // 8
                line_in_row = scr_y % 8
                y = 191 - scr_y
                for x in range(32):
                    addr = (third * 2048) + (row_in_third * 32) + (line_in_row * 256) + x
                    byte_val = 0
                    for bit in range(8):
                        px = x * 8 + bit
                        if px < 256 and gfx_bits[px][y]:
                            byte_val |= (1 << (7 - bit))
                    block[addr] = byte_val
            for r in range(24):
                for c in range(32):
                    addr = 6144 + (r * 32) + c
                    ink = attr_ink[r][c] & 7
                    paper = (attr_paper[r][c] & 7) << 3
                    bright = 64 if attr_bright[r][c] else 0
                    flash = 128 if attr_flash[r][c] else 0
                    block[addr] = ink | paper | bright | flash
            try:
                disk.save_file(fname, MGTDisk.TYPE_SCREEN, bytes(block))
                canvas_print(f"Saved SCREEN$ '{fname}' to {drv_label} ({os.path.basename(disk.filepath)})")
            except Exception as e:
                canvas_print(f"Error saving SCREEN$ to {drv_label}: {e}")
        elif mode == "CODE":
            simulate_tape_loading_border("Saving CODE")
            block = memory[code_start : code_start + code_len]
            try:
                disk.save_file(fname, MGTDisk.TYPE_CODE, bytes(block), start_addr=code_start, data_length=code_len)
                canvas_print(f"Saved CODE '{fname}' ({code_start}, {code_len}) to {drv_label} ({os.path.basename(disk.filepath)})")
            except Exception as e:
                canvas_print(f"Error saving CODE to {drv_label}: {e}")
        elif mode == "DATA" and data_arr_name:
            arr_data = bytearray()
            target_dict = ram_disk_arrays if data_arr_name.startswith("!") else arrays
            try:
                if data_arr_name in string_variables:
                    val = string_variables[data_arr_name]
                    arr_data.extend(val.encode('latin-1', errors='ignore'))
                    ftype = MGTDisk.TYPE_CHAR_ARRAY
                else:
                    val = None
                    if data_arr_name in target_dict:
                        val = target_dict[data_arr_name]
                    elif data_arr_name.startswith("!") and data_arr_name[1:] in arrays:
                        val = arrays[data_arr_name[1:]]
                    elif (not data_arr_name.startswith("!")) and f"!{data_arr_name}" in ram_disk_arrays:
                        val = ram_disk_arrays[f"!{data_arr_name}"]
                    if val is not None:
                        import json
                        if isinstance(val, tuple) and len(val) == 2:
                            dims, arr_dict = val
                            arr_data.extend(json.dumps({"dims": dims, "data": {str(k): v for k, v in arr_dict.items()}}).encode('utf-8'))
                        else:
                            arr_data.extend(json.dumps({"data": val}).encode('utf-8'))
                    ftype = MGTDisk.TYPE_NUM_ARRAY
                disk.save_file(fname, ftype, bytes(arr_data))
                canvas_print(f"Saved DATA '{data_arr_name}' as '{fname}' to {drv_label} ({os.path.basename(disk.filepath)})")
            except Exception as e:
                canvas_print(f"Error saving DATA to {drv_label}: {e}")
        else:
            simulate_tape_loading_border("Saving")
            prog_lines = []
            if autorun_line is not None:
                prog_lines.append(f"AUTORUN={autorun_line}")
            for ln in sorted(program.keys()):
                prog_lines.append(f"{ln} {program[ln]}")
            prog_bytes = ("\r\n".join(prog_lines) + "\r\n").encode('latin-1', errors='ignore')
            try:
                disk.save_file(fname, MGTDisk.TYPE_BASIC, prog_bytes, autorun_line=autorun_line)
                canvas_print(f"Saved '{fname}' ({len(program)} lines) to {drv_label} ({os.path.basename(disk.filepath)})")
            except Exception as e:
                canvas_print(f"Error saving program to {drv_label}: {e}")
    elif dev_type == "m":
        d_num = dev_info["drive"]
        fname = dev_info["name"]
        if mode == "SCREEN$":
            mdr_save_screen(d_num, fname)
        elif mode == "CODE":
            mdr_save_code(d_num, fname, code_start, code_len)
        else:
            mdr_save_program(d_num, fname, autorun_line=autorun_line)
    elif dev_type in ("b", "t", "n"):
        if mode == "SCREEN$":
            block = bytearray(6912)
            for scr_y in range(192):
                third = scr_y // 64
                row_in_third = (scr_y % 64) // 8
                line_in_row = scr_y % 8
                y = 191 - scr_y
                for x in range(32):
                    addr = (third * 2048) + (row_in_third * 32) + (line_in_row * 256) + x
                    byte_val = 0
                    for bit in range(8):
                        px = x * 8 + bit
                        if px < 256 and gfx_bits[px][y]:
                            byte_val |= (1 << (7 - bit))
                    block[addr] = byte_val
            for r in range(24):
                for c in range(32):
                    addr = 6144 + (r * 32) + c
                    ink = attr_ink[r][c] & 7
                    paper = (attr_paper[r][c] & 7) << 3
                    bright = 64 if attr_bright[r][c] else 0
                    flash = 128 if attr_flash[r][c] else 0
                    block[addr] = ink | paper | bright | flash
            write_device_bytes(dev_info, bytes(block))
            canvas_print(f"Saved SCREEN$ to {dev_info.get('name')}")
        elif mode == "CODE":
            block = memory[code_start : code_start + code_len]
            write_device_bytes(dev_info, bytes(block))
            canvas_print(f"Saved CODE ({code_start}, {code_len}) to {dev_info.get('name')}")
        else:
            prog_lines = []
            if autorun_line is not None:
                prog_lines.append(f"AUTORUN={autorun_line}")
            for ln in sorted(program.keys()):
                prog_lines.append(f"{ln} {program[ln]}")
            prog_bytes = ("\r\n".join(prog_lines) + "\r\n").encode('utf-8')
            write_device_bytes(dev_info, prog_bytes)
            canvas_print(f"Saved program to {dev_info.get('name')}")
    else:
        fname = dev_info.get("name", "").replace('"', '').replace("'", '').strip(' "\',;')
        if fname.lower().endswith(".zxb"):
            mode = "ZXB"
            fname = fname[:-4]
        elif fname.lower().endswith(".tap"):
            mode = "TAP"
            fname = fname[:-4]
        elif fname.lower().endswith(".zxbcode"):
            mode = "CODE"
            fname = fname[:-8]
        elif fname.lower().endswith(".dzxdata"):
            mode = "DATA"
            fname = fname[:-8]
        elif fname.lower().endswith(".zxf"):
            mode = "FORTH"
            fname = fname[:-4]
        elif fname.lower().endswith(".rom"):
            mode = "ROM"
            fname = fname[:-4]
        elif fname.lower().endswith(".bin"):
            mode = "ROM"
            fname = fname[:-4]

        if not fname and mode != "SCREEN$":
            filepath = ask_save_filename(
                initialdir=get_zx_folder(),
                title="Save BASIC Program / ROM",
                filetypes=[
                    ("TAP Files", "*.tap"),
                    ("ZX Interface 2 Cartridge ROM", "*.rom"),
                    ("Interface 2 Binary ROM", "*.bin"),
                    ("ZXB Plain Text Files", "*.zxb"),
                    ("Sinclair Forth Machine Code", "*.zxf"),
                    ("Code Files", "*.zxbcode"),
                    ("Data Files", "*.dzxdata"),
                    ("All Files", "*.*")
                ],
                defaultextension=".rom" if mode == "ROM" else ".tap"
            )
            if filepath:
                base_name = os.path.basename(filepath)
                name_wo_ext, ext = os.path.splitext(base_name)
                fname = name_wo_ext
                if ext.lower() == ".zxb": mode = "ZXB"
                elif ext.lower() == ".zxbcode": mode = "CODE"
                elif ext.lower() == ".dzxdata": mode = "DATA"
                elif ext.lower() == ".zxf": mode = "FORTH"
                elif ext.lower() in (".rom", ".bin"): mode = "ROM"
                else: mode = "TAP"
        if fname or mode in ("SCREEN$", "DATA", "FORTH", "ROM"):
            save_program_file(fname if fname else "program", mode, code_start=code_start, code_len=code_len, data_arr_name=data_arr_name)


def handle_load_command(arg_str):
    global canvas_dirty, autorun_enabled, tape_block_index, tape_raw_index, tape_raw_blocks, tape_block_headers, tape_data_blocks, last_loaded_code_bytes, last_loaded_code_addr, last_loaded_screen_bytes
    s = arg_str.strip()
    if s.startswith("*"):
        s = s[1:].strip()
    
    upper_s = s.upper()
    if upper_s.startswith("TILEMAP"):
        handle_load_tilemap_command(s)
        return
    mode = "PROG"
    dest_addr = None
    spec_part = s
    
    data_arr_name = None
    if "SCREEN$" in upper_s:
        mode = "SCREEN$"
        idx = upper_s.index("SCREEN$")
        spec_part = s[:idx].strip()
    elif "DATA " in upper_s:
        mode = "DATA"
        idx = upper_s.index("DATA ")
        spec_part = s[:idx].strip()
        data_arg = s[idx + 5:].strip()
        m_arr = re.match(r"^(!?[A-Za-z][A-Za-z0-9]*\$?)\s*\(\s*\)", data_arg)
        if m_arr:
            data_arr_name = m_arr.group(1).upper()
    elif "CODE" in upper_s:
        mode = "CODE"
        idx = upper_s.index("CODE")
        spec_part = s[:idx].strip()
        code_args = s[idx + 4:].strip()
        if code_args:
            try: dest_addr = int(evaluate_expr(code_args))
            except: dest_addr = None
            
    # Check for explicit format specifier such as ,zxb or ,tap or ,tzx or ,z80 or ,sna or ,trd or ,scl or ,dsk or ,bas or ,forth or ,zxf or ,rom or ,bin (case-insensitive)
    m_fmt = re.search(r'[, ]\s*(ZXB|TAP|TZX|Z80|SNA|TRD|SCL|DSK|BAS|FORTH|ZXF|ROM|BIN)\b', spec_part, flags=re.IGNORECASE)
    if m_fmt:
        mode = m_fmt.group(1).upper()
        if mode == "ZXF": mode = "FORTH"
        elif mode in ("ROM", "BIN"): mode = "ROM"
        spec_part = (spec_part[:m_fmt.start()] + spec_part[m_fmt.end():]).strip()
        if spec_part.endswith(","):
            spec_part = spec_part[:-1].strip()

    dev_info = parse_device_spec(spec_part)
    dev_type = dev_info["type"]
    folder = get_zx_folder()
    
    if dev_type == "ram":
        fname = dev_info.get("name", "")
        if fname not in ram_disk:
            canvas_print(f"File not found on RAM Disk: '{fname}'")
            return
        finfo = ram_disk[fname]
        ftype = finfo.get("type", "PROG") if isinstance(finfo, dict) else "PROG"
        data = finfo.get("data", b"") if isinstance(finfo, dict) else finfo
        if mode == "SCREEN$" or ftype == "SCREEN$":
            if len(data) >= 6912:
                for scr_y in range(192):
                    third = scr_y // 64
                    row_in_third = (scr_y % 64) // 8
                    line_in_row = scr_y % 8
                    y = 191 - scr_y
                    for x in range(32):
                        addr = (third * 2048) + (row_in_third * 32) + (line_in_row * 256) + x
                        if addr < len(data):
                            byte_val = data[addr]
                            for bit in range(8):
                                px = x * 8 + bit
                                if px < 256: gfx_bits[px][y] = bool((byte_val >> (7 - bit)) & 1)
                for r in range(24):
                    for c in range(32):
                        addr = 6144 + (r * 32) + c
                        if addr < len(data):
                            attr_byte = data[addr]
                            attr_ink[r][c] = attr_byte & 7
                            attr_paper[r][c] = (attr_byte >> 3) & 7
                            attr_bright[r][c] = bool(attr_byte & 64)
                            attr_flash[r][c] = bool(attr_byte & 128)
                canvas_dirty = True
                redraw_canvas()
                update_display()
                if not is_execution_mode():
                    canvas_print(f"Loaded SCREEN$ '{fname}' from RAM Disk")
            return
        elif mode == "CODE" or ftype == "CODE":
            target = dest_addr if dest_addr is not None else (finfo.get("start_addr", 16384) if isinstance(finfo, dict) else 16384)
            target &= 0xFFFF
            for i, b in enumerate(data):
                if target + i < 65536:
                    memory[target + i] = b
            if not is_execution_mode():
                canvas_print(f"Loaded CODE '{fname}' ({len(data)} bytes) to {target} from RAM Disk")
            return
        elif mode == "ROM" or ftype == "ROM":
            swap_cartridge_rom(data, name=fname)
            canvas_print(f"Loaded Interface 2 ROM '{fname}' from RAM Disk")
            handle_system_reset()
            return
        elif mode == "DATA" or ftype == "DATA":
            arr_name = data_arr_name if data_arr_name else (finfo.get("arr_name") if isinstance(finfo, dict) else None)
            if not arr_name: arr_name = fname.upper()
            target_dict = ram_disk_arrays if arr_name.startswith("!") else arrays
            if arr_name.endswith("$") and not (b'"dims"' in data or b'{"dims"' in data):
                string_variables[arr_name] = data.decode('latin-1', errors='ignore')
            else:
                try:
                    import json
                    parsed = json.loads(data.decode('utf-8'))
                    if isinstance(parsed, dict) and "dims" in parsed and isinstance(parsed.get("data"), dict):
                        dims = parsed["dims"]
                        arr_dict = {tuple(int(x) for x in k.strip('()').split(',')): v for k, v in parsed["data"].items()}
                        target_dict[arr_name] = (dims, arr_dict)
                    elif isinstance(parsed, dict) and "data" in parsed:
                        target_dict[arr_name] = parsed["data"]
                    else:
                        target_dict[arr_name] = parsed
                except Exception:
                    pass
            if not is_execution_mode():
                canvas_print(f"Loaded DATA '{arr_name}' from RAM Disk")
            return
        else:
            text = data.decode('latin-1', errors='ignore')
            program.clear()
            variables.clear()
            string_variables.clear()
            arrays.clear()
            count = 0
            autorun_ln = finfo.get("autorun_line") if isinstance(finfo, dict) else None
            for line in text.splitlines():
                line = line.strip()
                if not line or line.startswith("TYPE="):
                    continue
                if line.startswith("AUTORUN="):
                    try: autorun_ln = int(line.split("=")[1])
                    except: pass
                    continue
                match = re.match(r'^(\d+)\s+(.+)$', line)
                if match:
                    ln = int(match.group(1))
                    program[ln] = match.group(2).strip()
                    count += 1
            if not is_execution_mode():
                canvas_print(f"Loaded '{fname}' ({count} lines) from RAM Disk")
            if autorun_enabled and autorun_ln is not None and autorun_ln in program:
                line_nums = sorted(program.keys())
                run_program(get_target_line_idx(autorun_ln, line_nums))
            return
    elif dev_type in ("d", "plus3"):
        drive = dev_info.get("drive_num", dev_info.get("drive", mgt_default_drive))
        fname = dev_info.get("name", "")
        drv_label = f"Drive {dev_info.get('drive', drive)}:" if dev_type == "plus3" else f"Drive {drive}"
        disk = get_mgt_disk(drive)
        if disk is None:
            canvas_print(f"{drv_label} No disk in drive")
            return
        try:
            ftype, data, meta = disk.load_file(fname)
        except Exception as e:
            canvas_print(f"File not found on {drv_label}: '{fname}' ({e})")
            return

        if mode == "SCREEN$" or ftype == MGTDisk.TYPE_SCREEN:
            simulate_tape_loading_border(operation_name="Loading SCREEN$", filename=fname, file_type="Bytes")
            if len(data) >= 6912:
                for scr_y in range(192):
                    third = scr_y // 64
                    row_in_third = (scr_y % 64) // 8
                    line_in_row = scr_y % 8
                    y = 191 - scr_y
                    for x in range(32):
                        addr = (third * 2048) + (row_in_third * 32) + (line_in_row * 256) + x
                        if addr < len(data):
                            byte_val = data[addr]
                            for bit in range(8):
                                px = x * 8 + bit
                                if px < 256: gfx_bits[px][y] = bool((byte_val >> (7 - bit)) & 1)
                for r in range(24):
                    for c in range(32):
                        addr = 6144 + (r * 32) + c
                        if addr < len(data):
                            attr_byte = data[addr]
                            attr_ink[r][c] = attr_byte & 7
                            attr_paper[r][c] = (attr_byte >> 3) & 7
                            attr_bright[r][c] = bool(attr_byte & 64)
                            attr_flash[r][c] = bool(attr_byte & 128)
                            attr_used[r][c] = True
                canvas_dirty = True
                if not is_execution_mode():
                    canvas_print(f"Loaded SCREEN$ '{fname}' from {drv_label}")
            else:
                canvas_print(f"Error: Invalid screen data on {drv_label}: {fname}")
        elif mode == "CODE" or ftype == MGTDisk.TYPE_CODE:
            simulate_tape_loading_border(operation_name="Loading CODE", filename=fname, file_type="Bytes")
            target = dest_addr if dest_addr is not None else meta.get("start_addr", 16384)
            target &= 0xFFFF
            memory[target : target + len(data)] = data
            if not is_execution_mode():
                canvas_print(f"Loaded CODE '{fname}' ({len(data)} bytes) to {target} from {drv_label}")
        elif mode == "DATA" or ftype in (MGTDisk.TYPE_NUM_ARRAY, MGTDisk.TYPE_CHAR_ARRAY):
            target_arr = data_arr_name if data_arr_name else fname.upper()
            target_dict = ram_disk_arrays if target_arr.startswith("!") else arrays
            try:
                if ftype == MGTDisk.TYPE_CHAR_ARRAY:
                    string_variables[target_arr] = data.decode('latin-1', errors='ignore')
                    if not is_execution_mode():
                        canvas_print(f"Loaded string DATA '{target_arr}' from {drv_label}")
                else:
                    import json
                    parsed = json.loads(data.decode('utf-8'))
                    if isinstance(parsed, dict) and "dims" in parsed and isinstance(parsed.get("data"), dict):
                        dims = parsed["dims"]
                        arr_dict = {tuple(int(x) for x in k.strip('()').split(',')): v for k, v in parsed["data"].items()}
                        target_dict[target_arr] = (dims, arr_dict)
                    elif isinstance(parsed, dict) and "data" in parsed:
                        target_dict[target_arr] = parsed["data"]
                    else:
                        target_dict[target_arr] = parsed
                    if not is_execution_mode():
                        canvas_print(f"Loaded array DATA '{target_arr}' from {drv_label}")
            except Exception:
                if not is_execution_mode():
                    canvas_print(f"Loaded DATA '{fname}' ({len(data)} bytes) from {drv_label}")
        else:
            simulate_tape_loading_border(operation_name="Loading", filename=fname, file_type="Program")
            parsed = parse_bas_file(data)
            program.clear()
            _z80_compiled_blocks.clear()
            if 'program_line_order' in globals():
                program_line_order.clear()
            count = 0
            autorun_ln = meta.get("autorun_line") if meta else None
            for ln in sorted(parsed.keys()):
                program[ln] = parsed[ln]
                if 'program_line_order' in globals():
                    program_line_order.append(ln)
                count += 1
            parse_data_lines()
            _split_cache.clear()
            if not is_execution_mode():
                canvas_print(f"Loaded '{fname}' ({count} lines) from {drv_label}")
            if autorun_enabled and autorun_ln is not None and autorun_ln in program:
                line_nums = program_line_order if ('program_line_order' in globals() and program_line_order and all(k in program for k in program_line_order)) else sorted(program.keys())
                run_program(get_target_line_idx(autorun_ln, line_nums))
    elif dev_type == "m":
        d_num = dev_info["drive"]
        fname = dev_info["name"]
        if mode == "SCREEN$":
            mdr_load_screen(d_num, fname)
        elif mode == "CODE":
            mdr_load_code(d_num, fname, dest_start=dest_addr)
        else:
            mdr_load_program(d_num, fname)
    elif dev_type in ("b", "t", "n"):
        data = read_device_bytes(dev_info)
        if not data:
            canvas_print(f"No data received from {dev_info.get('name')}")
            return
        if mode == "SCREEN$":
            if len(data) >= 6912:
                for scr_y in range(192):
                    third = scr_y // 64
                    row_in_third = (scr_y % 64) // 8
                    line_in_row = scr_y % 8
                    y = 191 - scr_y
                    for x in range(32):
                        addr = (third * 2048) + (row_in_third * 32) + (line_in_row * 256) + x
                        if addr < len(data):
                            byte_val = data[addr]
                            for bit in range(8):
                                px = x * 8 + bit
                                if px < 256: gfx_bits[px][y] = bool((byte_val >> (7 - bit)) & 1)
                for r in range(24):
                    for c in range(32):
                        addr = 6144 + (r * 32) + c
                        if addr < len(data):
                            attr_byte = data[addr]
                            attr_ink[r][c] = attr_byte & 7
                            attr_paper[r][c] = (attr_byte >> 3) & 7
                            attr_bright[r][c] = bool(attr_byte & 64)
                            attr_flash[r][c] = bool(attr_byte & 128)
                            attr_used[r][c] = True
                canvas_dirty = True
                if not is_execution_mode():
                    canvas_print(f"Loaded SCREEN$ from {dev_info.get('name')}")
            else:
                canvas_print("Invalid SCREEN$ data")
        elif mode == "CODE":
            target = dest_addr if dest_addr is not None else 16384
            memory[target : target + len(data)] = data
            if not is_execution_mode():
                canvas_print(f"Loaded CODE ({len(data)} bytes) to {target} from {dev_info.get('name')}")
        else:
            text = data.decode('latin-1', errors='ignore')
            program.clear()
            count = 0
            autorun_ln = None
            for line in text.splitlines():
                line = line.strip()
                if not line or line.startswith("AUTORUN=") or line.startswith("TYPE="):
                    continue
                match = re.match(r'^(\d+)\s+(.+)$', line)
                if match:
                    ln = int(match.group(1))
                    program[ln] = match.group(2).strip()
                    count += 1
            if not is_execution_mode():
                canvas_print(f"Loaded {count} lines from {dev_info.get('name')}")
            if autorun_enabled and autorun_ln is not None and autorun_ln in program:
                line_nums = sorted(program.keys())
                run_program(get_target_line_idx(autorun_ln, line_nums))
    else:
        fname = dev_info.get("name", "").replace('"', '').replace("'", '').strip(' "\',;')
        if fname.lower().endswith(".zxb"):
            mode = "ZXB"
            fname = fname[:-4]
        elif fname.lower().endswith(".tap"):
            mode = "TAP"
            fname = fname[:-4]
        elif fname.lower().endswith(".zxbcode"):
            mode = "CODE"
            fname = fname[:-8]
        elif fname.lower().endswith(".dzxdata"):
            mode = "DATA"
            fname = fname[:-8]
        elif fname.lower().endswith(".zxf"):
            mode = "FORTH"
            fname = fname[:-4]

        if not fname and mode != "SCREEN$":
            if is_execution_mode():
                if mode == "CODE":
                    blk_hdr_addr = None
                    if 'tape_block_headers' in globals() and 'tape_block_index' in globals() and tape_block_index < len(tape_block_headers):
                        blk_hdr_addr = tape_block_headers[tape_block_index][1]
                    target_dest = dest_addr if dest_addr is not None else (blk_hdr_addr if blk_hdr_addr is not None else (last_loaded_code_addr if 'last_loaded_code_addr' in globals() and last_loaded_code_addr else 16384))
                    target_dest &= 0xFFFF
                    if 'tape_data_blocks' in globals() and 'tape_block_index' in globals() and tape_block_index < len(tape_data_blocks):
                        raw_payload = tape_data_blocks[tape_block_index]
                        tape_block_index += 1
                        if 'tape_raw_blocks' in globals() and 'tape_raw_index' in globals():
                            while tape_raw_index < len(tape_raw_blocks):
                                rf, rp = tape_raw_blocks[tape_raw_index]
                                tape_raw_index += 1
                                if rf == 255 and rp == raw_payload:
                                    break
                        if target_dest + len(raw_payload) <= len(memory):
                            memory[target_dest : target_dest + len(raw_payload)] = raw_payload
                        last_loaded_code_bytes = bytes(raw_payload)
                        last_loaded_code_addr = target_dest
                        if target_dest == 16384 and len(raw_payload) >= 6144:
                            last_loaded_screen_bytes = bytes(raw_payload)
                            load_screen_bytes(raw_payload)
                    else:
                        if 'last_loaded_code_bytes' in globals() and last_loaded_code_bytes:
                            if target_dest + len(last_loaded_code_bytes) <= len(memory):
                                memory[target_dest : target_dest + len(last_loaded_code_bytes)] = last_loaded_code_bytes
                    simulate_tape_loading_border(operation_name="Loading", filename="CODE", file_type="Bytes", duration_sec=0.5)
                    return
                elif mode == "DATA":
                    return
                elif mode == "PROG":
                    loaded_prog = False
                    if 'tape_raw_blocks' in globals() and 'tape_raw_index' in globals():
                        prog_payload = None
                        prog_len = None
                        autorun_ln = None
                        while tape_raw_index < len(tape_raw_blocks):
                            rf, rp = tape_raw_blocks[tape_raw_index]
                            tape_raw_index += 1
                            if rf == 0 and len(rp) >= 15:
                                btype = rp[0]
