                        if prog_payload is not None:
                            prog_base = 23755
                            prog_limit = min(prog_len, len(prog_payload)) if (prog_len is not None and prog_len > 0) else len(prog_payload)
                            if prog_base + len(prog_payload) <= len(memory):
                                memory[prog_base : prog_base + len(prog_payload)] = prog_payload
                                memory[23635] = prog_base & 0xFF
                                memory[23636] = (prog_base >> 8) & 0xFF
                                vars_addr = prog_base + prog_limit
                                memory[23627] = vars_addr & 0xFF
                                memory[23628] = (vars_addr >> 8) & 0xFF
                                memory[23641] = vars_addr & 0xFF
                                memory[23642] = (vars_addr >> 8) & 0xFF
                            parsed = parse_bas_file(prog_payload[:prog_limit])
