def handle_verify_command(arg_str):
    s = arg_str.strip()
    if s.startswith("*"):
        s = s[1:].strip()
    
    upper_s = s.upper()
    if "DATA " in upper_s:
        idx = upper_s.index("DATA ")
        spec_part = s[:idx].strip()
        data_arg = s[idx + 5:].strip()
        canvas_print(f"Verified DATA {data_arg.strip()}")
        return

    dev_info = parse_device_spec(s)
    dev_type = dev_info["type"]
    if dev_type in ("d", "plus3"):
        drive = dev_info.get("drive_num", dev_info.get("drive", mgt_default_drive))
        fname = dev_info.get("name", "")
        drv_label = f"Drive {dev_info.get('drive', drive)}:" if dev_type == "plus3" else f"Drive {drive}"
        disk = get_mgt_disk(drive)
        if disk is None:
            canvas_print(f"{drv_label} No disk in drive")
            return
        entry = disk.find_file(fname)
        if entry:
            canvas_print(f"Verified '{fname}' on {drv_label} ({entry['sectors']} sectors)")
        else:
            canvas_print(f"File not found on {drv_label}: '{fname}'")
        return
    elif dev_type == "m":
        mdr_verify_program(dev_info["drive"], dev_info["name"])
    else:
        fname = dev_info.get("name", "")
        folder = get_zx_folder()
        target_path = os.path.join(folder, f"{fname}.tap")
        if not os.path.exists(target_path):
            target_path = os.path.join(folder, f"{fname}.zxb")
        if os.path.exists(target_path):
            verify_program_file(target_path)
        else:
            canvas_print("File not found for verification")


def handle_merge_command(arg_str):
    s = arg_str.strip()
    if s.startswith("*"):
        s = s[1:].strip()
    
    dev_info = parse_device_spec(s)
    dev_type = dev_info["type"]
    if dev_type == "ram":
        fname = dev_info.get("name", "")
        if fname not in ram_disk:
            canvas_print(f"File not found on RAM Disk: '{fname}'")
            return
        finfo = ram_disk[fname]
        data = finfo.get("data", b"") if isinstance(finfo, dict) else finfo
        text = data.decode('latin-1', errors='ignore')
        count = 0
        for line in text.splitlines():
            line = line.strip()
            if not line or line.startswith("AUTORUN=") or line.startswith("TYPE="):
                continue
            match = re.match(r'^(\d+)\s+(.+)$', line)
            if match:
                ln = int(match.group(1))
                program[ln] = match.group(2).strip()
                count += 1
        canvas_print(f"Merged '{fname}' ({count} lines) from RAM Disk")
        return
    elif dev_type in ("d", "plus3"):
        drive = dev_info.get("drive_num", dev_info.get("drive", mgt_default_drive))
        fname = dev_info.get("name", "")
        drv_label = f"Drive {dev_info.get('drive', drive)}:" if dev_type == "plus3" else f"Drive {drive}"
        disk = get_mgt_disk(drive)
        if disk is None:
            canvas_print(f"{drv_label} No disk in drive")
            return
        try:
            ftype, data, meta = disk.load_file(fname)
            text = data.decode('latin-1', errors='ignore')
            count = 0
            for line in text.splitlines():
                line = line.strip()
                if not line or line.startswith("AUTORUN=") or line.startswith("TYPE="):
                    continue
                match = re.match(r'^(\d+)\s+(.+)$', line)
                if match:
                    ln = int(match.group(1))
                    program[ln] = match.group(2).strip()
                    count += 1
            canvas_print(f"Merged '{fname}' ({count} lines) from {drv_label}")
        except Exception as e:
            canvas_print(f"Error merging from {drv_label}: {e}")
        return
    elif dev_type == "m":
        mdr_merge_program(dev_info["drive"], dev_info["name"])
    else:
        fname = dev_info.get("name", "")
        folder = get_zx_folder()
        target_path = os.path.join(folder, f"{fname}.tap")
        if not os.path.exists(target_path):
            target_path = os.path.join(folder, f"{fname}.zxb")
        if os.path.exists(target_path):
            merge_program_file(target_path)
        else:
            canvas_print("File not found for merge")


boriel_compiler_path = None


def find_boriel_compiler(prompt_user=True):
    """
    Locates the Boriel ZXBC / ZXC compiler executable.
    If not found in standard paths, prompts the user via a native file dialog.
    """
    global boriel_compiler_path
    if boriel_compiler_path and os.path.exists(boriel_compiler_path):
        return boriel_compiler_path

    # Check PATH first
    for name in ("zxbc", "zxbc.exe", "zxc", "zxc.exe"):
        w = shutil.which(name)
        if w and os.path.exists(w):
            boriel_compiler_path = w
            return w

    # Check repo, current working directory, and standard installation directories
    base_dir = os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else os.getcwd()
    candidates = [
        os.path.join(base_dir, "zxbasic", "zxbc.exe"),
        os.path.join(os.getcwd(), "zxbasic", "zxbc.exe"),
        os.path.join(base_dir, "zxbasic", "zxbc.py"),
        os.path.join(os.getcwd(), "zxbasic", "zxbc.py"),
        r"C:\Users\kfash\AppData\Local\Python\pythoncore-3.14-64\Scripts\zxbc.exe",
        r"C:\zx\zxbc\zxbc.exe",
        r"C:\zx\zxbc.exe",
        r"C:\zx\zxc.exe",
    ]
    for c in candidates:
        if os.path.exists(c):
            boriel_compiler_path = c
            return c

    # Prompt the user via a file dialog if not found
    if prompt_user:
        try:
            chosen = ask_open_filename(
                title="Select Boriel's ZXBC / ZXC Compiler Binary",
                filetypes=[
                    ("Boriel Compiler (*.exe, *.py, *.bat, *.cmd)", "*.exe;*.py;*.bat;*.cmd"),
                    ("Executable Files", "*.exe"),
                    ("Python Scripts", "*.py"),
                    ("All Files", "*.*")
                ]
            )
            if chosen and os.path.exists(chosen):
                boriel_compiler_path = chosen
                return chosen
        except Exception:
            pass

    return None


def transpile_single_sprite_stmt(st, active_tbl, coll_tbl, defs_tbl, base):
    m = re.match(r'^(.*?\b(?:THEN|ELSE)\s+)((?:SPRITE\b|EDSPRITES?\b|SPRITED\b|SET\s+SPRITES?\b|SETSPRITES?\b|INCLUDE\s+SPRITES?\b).*)$', st, re.IGNORECASE)
    if m:
        prefix = m.group(1)
        sprite_part = m.group(2).strip()
    elif re.match(r'^(?:SPRITE\b|EDSPRITES?\b|SPRITED\b|SET\s+SPRITES?\b|SETSPRITES?\b|INCLUDE\s+SPRITES?\b)', st.strip(), re.IGNORECASE):
        prefix = ""
        sprite_part = st.strip()
    else:
        return None

    if re.match(r"^INCLUDE\s+SPRITES?\b", sprite_part, re.IGNORECASE):
        return f"{prefix}REM INCLUDE SPRITES"

    if re.match(r"^SET\s+SPRITES?\b", sprite_part, re.IGNORECASE) or re.match(r"^SETSPRITES?\b", sprite_part, re.IGNORECASE):
        return f"{prefix}REM {sprite_part}"

    if sprite_part.upper().startswith("EDSPRITES") or sprite_part.upper().startswith("EDSPRITE") or sprite_part.upper().startswith("SPRITED"):
        return f"{prefix}REM EDSPRITES"

    cmd_tail = sprite_part[6:].strip()
    if cmd_tail.startswith(":"):
        cmd_tail = cmd_tail[1:].strip()

    if not cmd_tail or cmd_tail.upper() == "STEP":
        return f"{prefix}RANDOMIZE USR {base + 9}"
    if cmd_tail.upper().startswith("EDIT"):
        return f"{prefix}REM EDSPRITES"
    m_init = re.match(r"^INIT(?:\s+(\d+))?$", cmd_tail, re.IGNORECASE)
    if m_init:
        addr = int(m_init.group(1)) if m_init.group(1) else base
        return f"{prefix}RANDOMIZE USR {addr}"
    if cmd_tail.upper() == "CLEAR":
        return f"{prefix}RANDOMIZE USR {base + 21}"
    if cmd_tail.upper() == "UPDATE":
        return f"{prefix}RANDOMIZE USR {base + 3}"
    if cmd_tail.upper() == "DRAW":
        return f"{prefix}RANDOMIZE USR {base + 6}"
    m_on = re.match(r"^ON\s+([^,:]+)(?:,\s*([^,:]+))?(?:,\s*([^,:]+))?$", cmd_tail, re.IGNORECASE)
    if m_on:
        s_id = m_on.group(1).strip()
        anim = m_on.group(2).strip() if m_on.group(2) else "0"
        on_code = f"POKE ({active_tbl}+({s_id})*32), (1+(({anim})>0)): POKE ({active_tbl}+({s_id})*32+6), 0: POKE ({active_tbl}+({s_id})*32+10), 0"
        if m_on.group(3):
            def_id = m_on.group(3).strip()
            on_code += f": POKE ({active_tbl}+({s_id})*32+1), ({def_id})"
        return f"{prefix}{on_code}"
    # Check for slot-first syntax: SPRITE <slot> ON/OFF/POS/MOVE/AT...
    m_slot = re.match(r"^(\d+|[A-Za-z0-9_]+)\s+(ON|OFF|POS|MOVE|AT|INK|USE|SHAPE)\b(.*)$", cmd_tail, re.IGNORECASE)
    if m_slot:
        s_id = m_slot.group(1).strip()
        verb = m_slot.group(2).upper()
        rest = m_slot.group(3).strip()
        if verb == "ON":
            m_at = re.search(r'\bAT\s+([^,:]+),\s*([^,:]+)', rest, re.IGNORECASE)
            pokes = [f"POKE ({active_tbl}+({s_id})*32), 1", f"POKE ({active_tbl}+({s_id})*32+6), 0", f"POKE ({active_tbl}+({s_id})*32+10), 0"]
            if m_at:
                pokes.append(f"POKE ({active_tbl}+({s_id})*32+2), ({m_at.group(1).strip()})")
                pokes.append(f"POKE ({active_tbl}+({s_id})*32+3), ({m_at.group(2).strip()})")
            return f"{prefix}" + ": ".join(pokes)
        elif verb == "OFF":
            return f"{prefix}POKE ({active_tbl}+({s_id})*32), 0"
        elif verb in ("POS", "AT"):
            rest_clean = re.sub(r'^(?:AT\s+|,)', '', rest, flags=re.IGNORECASE).strip()
            args = split_top_level_commas(rest_clean)
            if len(args) >= 2:
                return f"{prefix}POKE ({active_tbl}+({s_id})*32+2), ({args[0].strip()}): POKE ({active_tbl}+({s_id})*32+3), ({args[1].strip()})"
        elif verb == "MOVE":
            args = split_top_level_commas(rest)
            if len(args) >= 2:
                return f"{prefix}POKE ({active_tbl}+({s_id})*32+13), ({args[0].strip()}): POKE ({active_tbl}+({s_id})*32+15), ({args[1].strip()})"
        elif verb == "INK":
            return f"{prefix}POKE ({active_tbl}+({s_id})*32+7), ({rest})"
        elif verb in ("USE", "SHAPE"):
            return f"{prefix}POKE ({active_tbl}+({s_id})*32+1), ({rest}): POKE ({active_tbl}+({s_id})*32+10), 0"
    m_use = re.match(r"^(?:USE|SHAPE)\s+([^,:]+),\s*([^,:]+)$", cmd_tail, re.IGNORECASE)
    if m_use:
        s_id = m_use.group(1).strip()
        d_id = m_use.group(2).strip()
        return f"{prefix}POKE ({active_tbl}+({s_id})*32+1), ({d_id}): POKE ({active_tbl}+({s_id})*32+10), 0"
    m_off = re.match(r"^OFF\s+([^,:]+)$", cmd_tail, re.IGNORECASE)
    if m_off:
        s_id = m_off.group(1).strip()
        return f"{prefix}POKE ({active_tbl}+({s_id})*32), 0"
    m_pos = re.match(r"^POS\s+([^,:]+),\s*([^,:]+),\s*([^,:]+)$", cmd_tail, re.IGNORECASE)
    if m_pos:
        s_id, x, y = m_pos.group(1).strip(), m_pos.group(2).strip(), m_pos.group(3).strip()
        return f"{prefix}POKE ({active_tbl}+({s_id})*32+2), ({x}): POKE ({active_tbl}+({s_id})*32+3), ({y})"
    m_move = re.match(r"^MOVE\s+([^,:]+),\s*([^,:]+),\s*([^,:]+)$", cmd_tail, re.IGNORECASE)
    if m_move:
        s_id, d, spd = m_move.group(1).strip(), m_move.group(2).strip(), m_move.group(3).strip()
        return f"{prefix}POKE ({active_tbl}+({s_id})*32+13), ({d}): POKE ({active_tbl}+({s_id})*32+15), ({spd})"
    m_path = re.match(r"^PATH\s+([^,:]+),\s*([^,:]+),\s*([^,:]+)(?:,\s*([^,:]+),\s*([^,:]+))?$", cmd_tail, re.IGNORECASE)
    if m_path:
        s_id, mode, param = m_path.group(1).strip(), m_path.group(2).strip(), m_path.group(3).strip()
        tail_code = f"POKE ({active_tbl}+({s_id})*32+14), ({mode}): POKE ({active_tbl}+({s_id})*32+18), ({param})"
        if m_path.group(4) and m_path.group(5):
            cx, cy = m_path.group(4).strip(), m_path.group(5).strip()
            tail_code += f": POKE ({active_tbl}+({s_id})*32+16), ({cx}): POKE ({active_tbl}+({s_id})*32+17), ({cy})"
        return f"{prefix}{tail_code}"
    m_ink = re.match(r"^INK\s+([^,:]+),\s*([^,:]+)$", cmd_tail, re.IGNORECASE)
    if m_ink:
        s_id, col = m_ink.group(1).strip(), m_ink.group(2).strip()
        return f"{prefix}POKE ({active_tbl}+({s_id})*32+7), ({col})"
    m_reb = re.match(r"^REBOUND\s+([^,:]+),\s*([^,:]+)$", cmd_tail, re.IGNORECASE)
    if m_reb:
        s_id, frames = m_reb.group(1).strip(), m_reb.group(2).strip()
        return f"{prefix}POKE ({active_tbl}+({s_id})*32+20), ({frames})"
    m_from = re.match(r"^DEF\s+(\d+)\s+FROM\s+(\d+)$", cmd_tail, re.IGNORECASE)
    if m_from:
        d_id = m_from.group(1)
        return f"{prefix}REM SPRITE DEF {d_id} PRELOADED IN MC"
    m_def_bytes = re.match(r"^DEF\s+([^,]+),\s*([^,]+),\s*(.+)$", cmd_tail, re.IGNORECASE)
    if m_def_bytes:
        d_id = m_def_bytes.group(1).strip()
        f_idx = m_def_bytes.group(2).strip()
        return f"{prefix}REM SPRITE DEF {d_id},{f_idx} PRELOADED IN MC"
    m_attr = re.match(r"^ATTR\s+(.+)$", cmd_tail, re.IGNORECASE)
    if m_attr:
        args = split_top_level_commas(m_attr.group(1))
        if len(args) >= 1:
            s_id = args[0].strip()
            pokes = []
            offsets = [0, 1, 2, 3, 7, 13, 14, 15, 18, 20]
            for idx, off in enumerate(offsets, 1):
                if idx < len(args) and args[idx].strip():
                    pokes.append(f"POKE ({active_tbl}+({s_id})*32+{off}), ({args[idx].strip()})")
            if pokes:
                return f"{prefix}" + ": ".join(pokes)
    return None


def transpile_sprites_for_boriel(target_prog):
    """
    Translates extended SPRITE commands and COLLISION()/SPRITE() functions into
    Sinclair BASIC POKE, PEEK, and USR calls so the program can be compiled
    directly by Boriel's ZXBC without syntax errors.
    """
    base = DEFAULT_SPRITE_ENGINE_BASE if 'DEFAULT_SPRITE_ENGINE_BASE' in globals() else 50000
    active_tbl = base + 40
    coll_tbl = base + 552
    defs_tbl = base + 3072

    uses_sprites = any(re.search(r'\b(?:SPRITE|COLLISION|EDSPRITES?|SPRITED|INCLUDE\s+SPRITES?|SET\s+SPRITES?|SETSPRITES?)\b', line, re.IGNORECASE) for line in target_prog.values())
    if not uses_sprites:
        return target_prog

    processed = {}
    for ln, line_text in sorted(target_prog.items()):
        # In Boriel compiled machine code, CLEAR is handled by the tape autoloader, not runtime MC
        line_text = re.sub(r'\bCLEAR\s+\d+\b', 'REM CLEAR', line_text, flags=re.IGNORECASE)

        sub_stmts = split_statements(line_text)
        new_subs = []
        for stmt in sub_stmts:
            st = stmt.strip()
            trans = transpile_single_sprite_stmt(st, active_tbl, coll_tbl, defs_tbl, base)
            curr_st = trans if trans is not None else st

            curr_st = re.sub(r'\bCOLLISION\s*\(\s*([^,\)]+)\s*,\s*\"?SPRITE\"?\s*\)', rf'((PEEK({coll_tbl}+\1) AND 1)>0)', curr_st, flags=re.IGNORECASE)
            curr_st = re.sub(r'\bCOLLISION\s*\(\s*([^,\)]+)\s*,\s*\"?UDG\"?\s*\)', rf'((PEEK({coll_tbl}+\1) AND 2)>0)', curr_st, flags=re.IGNORECASE)
            curr_st = re.sub(r'\bCOLLISION\s*\(\s*([^,\)]+)\s*,\s*\"?BLOCK\"?\s*\)', rf'((PEEK({coll_tbl}+\1) AND 4)>0)', curr_st, flags=re.IGNORECASE)
            curr_st = re.sub(r'\bCOLLISION\s*\(\s*([^,\)]+)\s*,\s*\"?INK\"?\s*\)', rf'((PEEK({coll_tbl}+\1) AND 8)>0)', curr_st, flags=re.IGNORECASE)
            curr_st = re.sub(r'\bCOLLISION\s*\(\s*([^,\)]+)\s*,\s*\"?PAPER\"?\s*\)', rf'((PEEK({coll_tbl}+\1) AND 16)>0)', curr_st, flags=re.IGNORECASE)
            curr_st = re.sub(r'\bCOLLISION\s*\(\s*([^,\)]+)\s*,\s*\"?TARGET\"?\s*\)', rf'((PEEK({coll_tbl}+\1) AND 32)>0)', curr_st, flags=re.IGNORECASE)
            curr_st = re.sub(r'\bCOLLISION\s*\(\s*([^,\)]+)\s*\)', rf'PEEK({coll_tbl}+\1)', curr_st, flags=re.IGNORECASE)

            curr_st = re.sub(r'\bSPRITE\s*\(\s*([^,\)]+)\s*,\s*\"?X\"?\s*\)', rf'PEEK({active_tbl}+(\1)*32+2)', curr_st, flags=re.IGNORECASE)
            curr_st = re.sub(r'\bSPRITE\s*\(\s*([^,\)]+)\s*,\s*\"?Y\"?\s*\)', rf'PEEK({active_tbl}+(\1)*32+3)', curr_st, flags=re.IGNORECASE)
            curr_st = re.sub(r'\bSPRITE\s*\(\s*([^,\)]+)\s*,\s*\"?FRAME\"?\s*\)', rf'PEEK({active_tbl}+(\1)*32+10)', curr_st, flags=re.IGNORECASE)
            curr_st = re.sub(r'\bSPRITE\s*\(\s*([^,\)]+)\s*,\s*\"?COLLISION\"?\s*\)', rf'PEEK({coll_tbl}+\1)', curr_st, flags=re.IGNORECASE)
            curr_st = re.sub(r'\bSPRITE\s*\(\s*([^,\)]+)\s*,\s*\"?INK\"?\s*\)', rf'PEEK({active_tbl}+(\1)*32+7)', curr_st, flags=re.IGNORECASE)
            curr_st = re.sub(r'\bSPRITE\s*\(\s*([^,\)]+)\s*,\s*\"?DIR\"?\s*\)', rf'PEEK({active_tbl}+(\1)*32+13)', curr_st, flags=re.IGNORECASE)
            curr_st = re.sub(r'\bSPRITE\s*\(\s*([^,\)]+)\s*,\s*\"?SPEED\"?\s*\)', rf'PEEK({active_tbl}+(\1)*32+15)', curr_st, flags=re.IGNORECASE)

            new_subs.append(curr_st)

        processed[ln] = ": ".join(new_subs)

    return processed


def extract_sprite_defs_data(target_prog, base=50000):
    """
    Scans target_prog DATA lines, inline SPRITE DEF lines, and resident sprite engine
    definitions, producing a bytearray of sprite definitions (128 bytes per definition)
    and the number of defined sprites.
    """
    raw_defs = bytearray(64 * 128)
    max_def_id = -1

    # 1. Check resident sprite engine definitions
    try:
        eng = get_sprite_engine()
        if eng and hasattr(eng, "definitions"):
            for d_id, frames in eng.definitions.items():
                if 0 <= d_id < 64:
                    for f_idx in range(min(4, len(frames))):
                        frame_bytes = frames[f_idx]
                        if any(frame_bytes):
                            dst = d_id * 128 + f_idx * 32
                            raw_defs[dst : dst + 32] = frame_bytes[:32]
                            max_def_id = max(max_def_id, d_id)
    except Exception:
        pass

    if not target_prog:
        num_defs = max(0, max_def_id + 1)
        return bytes(raw_defs[: num_defs * 128]), num_defs

    # 2. Extract DATA statements by line
    line_data_pool = {}
    for ln in sorted(target_prog.keys()):
        line_text = target_prog[ln]
        sub_stmts = split_statements(line_text)
        vals = []
        for stmt in sub_stmts:
            stmt_s = stmt.strip()
            if stmt_s.upper().startswith("DATA "):
                data_tail = stmt_s[5:].strip()
                raw_items = split_top_level_commas(data_tail)
                for item in raw_items:
                    item_s = item.strip()
                    try:
                        val = int(round(float(item_s)))
                        vals.append(val & 0xFF)
                    except Exception:
                        pass
        if vals:
            line_data_pool[ln] = vals

    # 3. Match SPRITE DEF <id> FROM <start_line>
    for ln in sorted(target_prog.keys()):
        line_text = target_prog[ln]
        for m in re.finditer(r'\bSPRITE\s+DEF\s+(\d+)\s+FROM\s+(\d+)\b', line_text, re.IGNORECASE):
            d_id = int(m.group(1))
            start_line = int(m.group(2))
            if 0 <= d_id < 64:
                collected = []
                for d_ln in sorted(line_data_pool.keys()):
                    if d_ln >= start_line:
                        collected.extend(line_data_pool[d_ln])
                        if len(collected) >= 128:
                            break
                if collected:
                    bytes_128 = bytes(collected[:128])
                    if len(bytes_128) < 128:
                        bytes_128 = bytes_128 + bytes(128 - len(bytes_128))
                    dst = d_id * 128
                    raw_defs[dst : dst + 128] = bytes_128
                    max_def_id = max(max_def_id, d_id)

    # 4. Match inline SPRITE DEF <id>, <frame>, <b0>..<b31>
    for ln in sorted(target_prog.keys()):
        line_text = target_prog[ln]
        sub_stmts = split_statements(line_text)
        for stmt in sub_stmts:
            stmt_s = stmt.strip()
            m_bytes = re.match(r'^SPRITE\s+DEF\s+(\d+)\s*,\s*(\d+)\s*,\s*(.+)$', stmt_s, re.IGNORECASE)
            if m_bytes:
                d_id = int(m_bytes.group(1))
                f_idx = int(m_bytes.group(2))
                raw_items = split_top_level_commas(m_bytes.group(3))
                vals = []
                for item in raw_items[:32]:
                    try:
                        val = int(round(float(item.strip())))
                        vals.append(val & 0xFF)
                    except Exception:
                        pass
                if 0 <= d_id < 64 and 0 <= f_idx < 4 and vals:
                    frame_bytes = bytes(vals[:32])
                    if len(frame_bytes) < 32:
                        frame_bytes = frame_bytes + bytes(32 - len(frame_bytes))
                    dst = d_id * 128 + f_idx * 32
                    raw_defs[dst : dst + 32] = frame_bytes
                    max_def_id = max(max_def_id, d_id)

    # 5. Extract sprite definitions from DATA statements when POKE (53072... or defs_tbl is present
    has_poke_defs = any(re.search(r'POKE\s*\(?\s*(?:53072|\(?50000\s*\+\s*3072|defs_tbl)', line, re.IGNORECASE) for line in target_prog.values())
    if has_poke_defs:
        all_numeric_data = []
        for ln in sorted(line_data_pool.keys()):
            if ln < 7000:
                all_numeric_data.extend(line_data_pool[ln])
        idx = 0
        while idx + 34 <= len(all_numeric_data):
            sid = all_numeric_data[idx]
            fid = all_numeric_data[idx + 1]
            if 0 <= sid < 64 and 0 <= fid < 4:
                frame_bytes = bytes(all_numeric_data[idx + 2 : idx + 34])
                dst = sid * 128 + fid * 32
                raw_defs[dst : dst + 32] = frame_bytes
                max_def_id = max(max_def_id, sid)
                idx += 34
            else:
                idx += 1

    num_defs = max(0, max_def_id + 1)
    return bytes(raw_defs[: num_defs * 128]), num_defs


def extract_tilemap_data(target_prog, tilemap_base=40000):
    """
    Extracts tilemap binary asset data from LOAD TILEMAP files or resident tilemap engine.
    """
    max_safe_bytes = max(0, 65536 - tilemap_base)
    sp_base = DEFAULT_SPRITE_ENGINE_BASE if 'DEFAULT_SPRITE_ENGINE_BASE' in globals() else 50000
    if sp_base > tilemap_base:
        max_safe_bytes = min(max_safe_bytes, sp_base - tilemap_base)

    # 1. Check if LOAD TILEMAP "file" is in program
    if target_prog:
        for ln in sorted(target_prog.keys()):
            m_load = re.search(r'\bLOAD\s+TILEMAP\s+([^\s,:]+)', target_prog[ln], re.IGNORECASE)
            if m_load:
                raw_fname = m_load.group(1).strip(' "\'')
                candidates = [
                    raw_fname if os.path.isabs(raw_fname) else None,
                    os.path.join(os.getcwd(), raw_fname),
                    os.path.join(get_zx_folder(), raw_fname)
                ]
                for c in candidates:
                    if c and os.path.exists(c) and not os.path.isdir(c):
                        try:
                            with open(c, "rb") as f:
                                data = f.read()
                            if len(data) == 6912 or c.lower().endswith((".scn", ".scr")):
                                eng = TilemapEngine(tilemap_base)
                                eng.grab_from_screen_bytes(data)
                                used = [i for i, t in enumerate(eng.tiles) if any(t)]
                                max_idx = max(used) if used else -1
                                if max_idx >= 0:
                                    num_tiles = min(192, max_idx + 1)
                                    num_tiles = min(num_tiles, max_safe_bytes // 256)
                                    raw_tiles = bytearray(num_tiles * 256)
                                    for i in range(num_tiles):
                                        raw_tiles[i * 256 : (i + 1) * 256] = eng.tiles[i][:256]
                                    return bytes(raw_tiles)
                            else:
                                max_tiles = min(192, len(data) // 256)
                                used = [i for i in range(max_tiles) if any(data[i * 256 : (i + 1) * 256])]
                                max_idx = max(used) if used else -1
                                if max_idx >= 0:
                                    num_tiles = min(192, max_idx + 1)
                                    num_tiles = min(num_tiles, max_safe_bytes // 256)
                                    return data[: num_tiles * 256]
                                return b""
                        except Exception:
                            pass

    # 2. Check resident tile engine
    try:
        eng = get_tilemap_engine()
        if eng and hasattr(eng, "tiles"):
            used = [i for i, t in enumerate(eng.tiles) if any(t)]
            max_idx = max(used) if used else -1
            if max_idx >= 0:
                num_tiles = min(192, max_idx + 1)
                num_tiles = min(num_tiles, max_safe_bytes // 256)
                raw_tiles = bytearray(num_tiles * 256)
                for i in range(num_tiles):
                    raw_tiles[i * 256 : (i + 1) * 256] = eng.tiles[i][:256]
                return bytes(raw_tiles)
    except Exception:
        pass

    return b""



def transpile_place_args_to_pokes(place_str, tile_engine_base=45000):
    items_with_sep = []
    current = []
    in_string = False
    paren_depth = 0
    at_mode = False
    comma_count_in_at = 0
    current_sep = None
    i = 0
    n = len(place_str)

    while i < n:
        char = place_str[i]
        if char in ('"', "'"):
            in_string = not in_string
            current.append(char)
        elif not in_string:
            if char == '(':
                paren_depth += 1
                current.append(char)
            elif char == ')':
                paren_depth = max(0, paren_depth - 1)
                current.append(char)
            elif paren_depth == 0:
                curr_str = "".join(current).strip().upper()
                if curr_str.startswith("AT ") or curr_str == "AT":
                    at_mode = True

                if char == ';':
                    at_mode = False
                    comma_count_in_at = 0
                    items_with_sep.append((current_sep, "".join(current).strip()))
                    current = []
                    current_sep = ';'
                elif char == ',':
                    if at_mode:
                        comma_count_in_at += 1
                        if comma_count_in_at >= 2:
                            at_mode = False
                            comma_count_in_at = 0
                            items_with_sep.append((current_sep, "".join(current).strip()))
                            current = []
                            current_sep = ','
                        else:
                            current.append(char)
                    else:
                        items_with_sep.append((current_sep, "".join(current).strip()))
                        current = []
                        current_sep = ','
                else:
                    current.append(char)
            else:
                current.append(char)
        else:
            current.append(char)
        i += 1

    if current:
        items_with_sep.append((current_sep, "".join(current).strip()))

    stmts = []
    cur_row = "0"
    cur_col = "0"
    cur_ink = "7"
    cur_paper = "0"
    cur_bright = "0"
    cur_flash = "0"
    cur_inverse = "0"
    cur_over = "0"

    for sep, item in items_with_sep:
        if not item:
            continue
        up = item.upper()
        if up.startswith("AT "):
            coords = split_top_level_commas(item[3:].strip())
            if len(coords) >= 2:
                cur_row = f"({coords[0].strip()})"
                cur_col = f"({coords[1].strip()})"
        elif up.startswith("INK "):
            cur_ink = f"(({item[4:].strip()}) bAND 7)"
        elif up.startswith("PAPER "):
            cur_paper = f"(({item[6:].strip()}) bAND 7)"
        elif up.startswith("BRIGHT "):
            cur_bright = f"(1*(({item[7:].strip()})>0))"
        elif up.startswith("FLASH "):
            cur_flash = f"(1*(({item[6:].strip()})>0))"
        elif up.startswith("INVERSE "):
            cur_inverse = f"(1*(({item[8:].strip()})>0))"
        elif up.startswith("OVER "):
            cur_over = f"(1*(({item[5:].strip()})>0))"
        else:
            tile_expr = item.strip()
            m_t = re.match(r"^TILE\s*\(\s*(.+)\s*\)$", tile_expr, re.IGNORECASE)
            if m_t:
                idx_expr = m_t.group(1).strip()
                t_arg = f"({idx_expr})"
            else:
                t_arg = f"({tile_expr})"

            attr_calc = f"(({cur_flash})*128+({cur_bright})*64+({cur_paper})*8+({cur_ink}))"
            flags_calc = f"(({cur_over})+(({cur_inverse})*2))"

            pokes = [
                f"POKE ({tile_engine_base}+6), {cur_row}",
                f"POKE ({tile_engine_base}+7), {cur_col}",
                f"POKE ({tile_engine_base}+8), (({t_arg}) - INT(({t_arg})/256)*256)",
                f"POKE ({tile_engine_base}+9), (INT(({t_arg})/256))",
                f"POKE ({tile_engine_base}+10), {attr_calc}",
                f"POKE ({tile_engine_base}+11), {flags_calc}",
                f"RANDOMIZE USR {tile_engine_base}"
            ]
            stmts.append(": ".join(pokes))
            cur_col = f"({cur_col}+2)"

    return ": ".join(stmts) if stmts else "REM PLACE NOP"


def transpile_single_tile_stmt(st, tile_engine_base=45000):
    m = re.match(r'^(.*?\b(?:THEN|ELSE)\s+)(.*)$', st, re.IGNORECASE)
    if m:
        prefix = m.group(1)
        cmd_part = m.group(2).strip()
    else:
        prefix = ""
        cmd_part = st.strip()

    cmd_upper = cmd_part.upper()

    if re.match(r"^INCLUDE\s+TILEMAPS?\b", cmd_part, re.IGNORECASE):
        return f"{prefix}REM INCLUDE TILEMAP"

    # 1. TILEMAP <addr>
    m_tm = re.match(r"^TILEMAP\s+(.+)$", cmd_part, re.IGNORECASE)
    if m_tm:
        addr_expr = m_tm.group(1).strip()
        try:
            addr_val = int(addr_expr) & 0xFFFF
            lo = addr_val & 255
            hi = (addr_val >> 8) & 255
            return f"{prefix}POKE {tile_engine_base + 12}, {lo}: POKE {tile_engine_base + 13}, {hi}"
        except Exception:
            return f"{prefix}POKE ({tile_engine_base}+12), (({addr_expr}) - INT(({addr_expr})/256)*256): POKE ({tile_engine_base}+13), (INT(({addr_expr})/256))"

    # 2. LOAD TILEMAP "file" [, addr]
    m_load = re.match(r"^LOAD\s+TILEMAP\s+(.+)$", cmd_part, re.IGNORECASE)
    if m_load:
        args = split_top_level_commas(m_load.group(1))
        f_part = args[0].strip()
        if len(args) > 1 and args[1].strip():
            a_part = args[1].strip()
            try:
                addr_val = int(a_part) & 0xFFFF
                lo = addr_val & 255
                hi = (addr_val >> 8) & 255
                return f"{prefix}POKE {tile_engine_base + 12}, {lo}: POKE {tile_engine_base + 13}, {hi}: REM LOAD TILEMAP {f_part} PRELOADED IN MC"
            except Exception:
                return f"{prefix}POKE ({tile_engine_base}+12), (({a_part}) - INT(({a_part})/256)*256): POKE ({tile_engine_base}+13), (INT(({a_part})/256)): REM LOAD TILEMAP {f_part} PRELOADED IN MC"
        else:
            return f"{prefix}REM LOAD TILEMAP {f_part} PRELOADED IN MC"

    # 3. GRAB TILES [addr] [, "file"]
    m_grab = re.match(r"^GRAB\s+(?:TILES?|TILEMAP)\b\s*(.*)$", cmd_part, re.IGNORECASE)
    if m_grab:
        tail = m_grab.group(1).strip()
        if not tail:
            return f"{prefix}REM GRAB TILES LIVE SCREEN"
        args = split_top_level_commas(tail)
        p1 = args[0].strip()
        p2 = args[1].strip() if len(args) > 1 else ""
        file_part = ""
        addr_part = ""
        if p1.startswith(('"', "'")):
            file_part = p1
            addr_part = p2
        elif p2.startswith(('"', "'")):
            file_part = p2
            addr_part = p1
        else:
            if p2:
                addr_part = p1
                file_part = p2
            else:
                addr_part = p1
        if file_part:
            tgt = f"({addr_part})" if addr_part else "16384"
            return f"{prefix}LOAD {file_part} CODE {tgt}"
        else:
            return f"{prefix}REM GRAB TILES {addr_part}"

    # 4. EDTILES
    if cmd_upper.startswith("EDTILES") or cmd_upper.startswith("EDTILE") or cmd_upper.startswith("TILED"):
        return f"{prefix}REM EDTILES"

    # 5. PLACE ...
    m_place = re.match(r"^PLACE\b\s*(.*)$", cmd_part, re.IGNORECASE)
    if m_place:
        args_str = m_place.group(1).strip()
        if not args_str:
            return f"{prefix}REM PLACE EMPTY"
        return f"{prefix}" + transpile_place_args_to_pokes(args_str, tile_engine_base)

    return None


def transpile_tiles_for_boriel(target_prog):
    """
    Translates custom tilemap commands (TILEMAP, PLACE, LOAD TILEMAP, GRAB TILES, EDTILES)
    and TILE(x) functions into Sinclair BASIC POKE, PEEK, LOAD CODE, and USR calls so
    the program can be compiled directly by Boriel's ZXBC without syntax errors.
    """
    tile_engine_base = DEFAULT_TILE_ENGINE_BASE if 'DEFAULT_TILE_ENGINE_BASE' in globals() else 45000
    uses_tilemap = any(re.search(r'\b(?:TILEMAP|PLACE|TILE\s*\(|LOAD\s+TILEMAP|GRAB\s+TILES?|EDTILES?|TILED|INCLUDE\s+TILEMAPS?)\b', line, re.IGNORECASE) for line in target_prog.values())
    if not uses_tilemap:
        return target_prog

    processed = {}
    for ln, line_text in sorted(target_prog.items()):
        sub_stmts = split_statements(line_text)
        new_subs = []
        for stmt in sub_stmts:
            st = stmt.strip()
            trans = transpile_single_tile_stmt(st, tile_engine_base)
            curr_st = trans if trans is not None else st

            # Replace TILE(x) in expressions with (base + x * 256)
            curr_st = re.sub(r'\bTILE\s*\(\s*([^,\)]+)\s*\)', rf'((PEEK({tile_engine_base}+12)+256*PEEK({tile_engine_base}+13))+(\1)*256)', curr_st, flags=re.IGNORECASE)
            new_subs.append(curr_st)

        processed[ln] = ": ".join(new_subs)

    return processed


def preprocess_sinclair_basic_for_boriel(target_prog):
    """
    Preprocesses BASIC lines for Boriel ZXBC compiler in --sinclair mode:
    Boriel conflates numeric variables/arrays (e.g. A, DIM A(3,6)) with string
    variables of the same base name (e.g. A$), causing fatal syntax/type errors:
    'error: Invalid assignment. Variable A$() is an array'
    or 'error: Invalid $ suffix (or sigil) for numeric variable'.
    
    Also transpiles extended SPRITE and TILEMAP statements into Sinclair POKE/PEEK/USR/LOAD CODE.
    """
    target_prog = transpile_sprites_for_boriel(target_prog)
    target_prog = transpile_tiles_for_boriel(target_prog)
    processed = {}
    for ln, line_text in target_prog.items():
        parts = []
        n = len(line_text)
        i = 0
        current_chunk = []
        while i < n:
            ch = line_text[i]
            if ch == '"':
                if current_chunk:
                    parts.append(("CODE", "".join(current_chunk)))
                    current_chunk = []
                str_chunk = [ch]
                i += 1
                while i < n:
                    c = line_text[i]
                    str_chunk.append(c)
                    if c == '"':
                        if i + 1 < n and line_text[i+1] == '"':
                            str_chunk.append(line_text[i+1])
                            i += 2
                            continue
                        else:
                            i += 1
                            break
                    i += 1
                parts.append(("STR", "".join(str_chunk)))
                continue

            # Check for REM keyword at word boundary
            if line_text[i:i+3].upper() == "REM" and (i == 0 or not line_text[i-1].isalnum()) and (i+3 == n or not line_text[i+3].isalnum()):
                if current_chunk:
                    parts.append(("CODE", "".join(current_chunk)))
                    current_chunk = []
                parts.append(("REM", line_text[i:]))
                break

            current_chunk.append(ch)
            i += 1

        if current_chunk:
            parts.append(("CODE", "".join(current_chunk)))

        transformed_parts = []
        builtins = {"CHR$", "INKEY$", "STR$", "SCREEN$", "ATTR$", "VAL$", "CODE$"}
        for ptype, text in parts:
            if ptype == "CODE":
                def rep_str_var(m):
                    full = m.group(0).upper()
                    if full in builtins or m.group(1).startswith("_s_"):
                        return m.group(0)
                    return f"_s_{m.group(1)}$"
                new_text = re.sub(r'(?<![A-Za-z0-9_])([A-Za-z][A-Za-z0-9_]*)\$', rep_str_var, text)
                transformed_parts.append(new_text)
            else:
                transformed_parts.append(text)

        processed[ln] = "".join(transformed_parts)
    return processed


def handle_compile_command(arg_str=""):
    """
    Compiles a program to a .tap tape image.
    Syntax:
        COMPILE                  - Compiles resident program to program.tap
        COMPILE "prog.zxb"       - Loads and compiles prog.zxb to prog.tap
        COMPILE "prog" TO "t.tap" - Compiles prog to t.tap
    """
    global program
    s = arg_str.strip()
    src_file = None
    dst_file = None

    if s.upper().startswith("TO "):
        src_file = None
        dst_file = s[3:].strip(' "\'')
    else:
        m_to = re.match(r'^(.*?)\s+TO\s+(.*)$', s, re.IGNORECASE)
        if m_to:
            src_file = m_to.group(1).strip(' "\'')
            dst_file = m_to.group(2).strip(' "\'')
        elif s:
            if s.lower().endswith(".tap") and not os.path.exists(s) and not os.path.exists(os.path.join(os.getcwd(), s)):
                src_file = None
                dst_file = s.strip(' "\'')
            else:
                src_file = s.strip(' "\'')

    target_program = {}
    prog_name = "program"
    found_path = None

    if src_file:
        candidates = [
            src_file if os.path.isabs(src_file) else None,
            os.path.join(os.getcwd(), src_file),
            os.path.join(get_zx_folder(), src_file),
            os.path.join(os.getcwd(), f"{src_file}.zxb"),
            os.path.join(get_zx_folder(), f"{src_file}.zxb"),
            os.path.join(os.getcwd(), f"{src_file}.bas"),
            os.path.join(get_zx_folder(), f"{src_file}.bas"),
        ]
        for c in candidates:
            if c and os.path.exists(c) and not os.path.isdir(c):
                found_path = c
                break

        if not found_path:
            canvas_print(f"File not found: {src_file}")
            return

        prog_name = os.path.splitext(os.path.basename(found_path))[0]
        try:
            with open(found_path, "r", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith("AUTORUN=") or line.startswith("TYPE="):
                        continue
                    parts = line.split(" ", 1)
                    if len(parts) == 2 and parts[0].isdigit():
                        target_program[int(parts[0])] = parts[1]
        except Exception as e:
            canvas_print(f"Error reading {found_path}: {e}")
            return
    else:
        if not program:
            canvas_print("No program in memory to compile")
            return
        target_program = program.copy()

    has_dest = bool(dst_file)
    default_dst_name = dst_file if has_dest else f"{prog_name}.tap"
    if not default_dst_name.lower().endswith(".tap"):
        default_dst_name += ".tap"

    clean_default_name = os.path.basename(default_dst_name)
    folder = get_zx_folder()

    import subprocess, tempfile, time
    temp_out_tap = os.path.join(tempfile.gettempdir(), f"_basinpy_comp_{os.getpid()}_{time.time_ns()}.tap")

    # Check if zxbc is available and if program has no Beta BASIC extensions
    has_beta_basic = False
    beta_tokens = ["DEF PROC", "PROC ", "END PROC", "LOCAL ", "CSIZE", "UDG 16", "DEF KEY", "DIM !", "LET !", "BOLD", "ITALIC", "UNDERLINE"]
    for code in target_program.values():
        code_up = code.upper()
        if any(tok in code_up for tok in beta_tokens):
            has_beta_basic = True
            break

    compiled_type = None
    boriel_fail_reason = None

    # Multi-pass: transpile sprites and tilemap statements into standard Sinclair BASIC equivalents
    sinclair_transpiled = transpile_tiles_for_boriel(transpile_sprites_for_boriel(target_program))

    if not has_beta_basic:
        zxbc_exe = find_boriel_compiler(prompt_user=True)
        if zxbc_exe and os.path.exists(zxbc_exe):
            tmp_bas = None
            temp_dir = None
            try:
                processed_prog = preprocess_sinclair_basic_for_boriel(target_program)
                clean_hdr_name = re.sub(r'[^A-Za-z0-9_]', '_', prog_name)[:10] or "program"
                temp_dir = tempfile.mkdtemp(prefix="_basinpy_boriel_")
                tmp_bas = os.path.join(temp_dir, f"{clean_hdr_name}.bas")
                with open(tmp_bas, "w", encoding="utf-8") as tf:
                    for ln in sorted(processed_prog.keys()):
                        tf.write(f"{ln} {processed_prog[ln]}\n")
                input_path = tmp_bas

                cmd = [sys.executable, zxbc_exe] if zxbc_exe.lower().endswith(".py") else [zxbc_exe]
                cmd_args = cmd + [
                    "-f", "tap",
                    "-B",
                    "-a",
                    "--sinclair",
                    "--array-base", "1",
                    "--string-base", "1",
                    "-S", "24500",
                    "-H", "4096",
                    "-O", "3",
                    "-o", temp_out_tap,
                    input_path
                ]
                res = subprocess.run(cmd_args, capture_output=True, text=True, timeout=180)
                if res.returncode == 0 and os.path.exists(temp_out_tap) and os.path.getsize(temp_out_tap) > 0:
                    compiled_type = "MC"
                elif res.stderr:
                    for eline in res.stderr.splitlines():
                        if "error:" in eline:
                            # Strip file path if present for clean display
                            boriel_fail_reason = eline.split("error:", 1)[1].strip()
                            break
            except subprocess.TimeoutExpired:
                boriel_fail_reason = "Compiler timed out (>180s)"
            except Exception as ex:
                boriel_fail_reason = str(ex)
            finally:
                if tmp_bas and os.path.exists(tmp_bas):
                    try:
                        os.remove(tmp_bas)
                    except Exception:
                        pass
                if temp_dir and os.path.exists(temp_dir):
                    try:
                        shutil.rmtree(temp_dir, ignore_errors=True)
                    except Exception:
                        pass

    if compiled_type != "MC":
        # Save conforming TAP container for standard 48K Sinclair ROM
        try:
            save_conforming_tap(temp_out_tap, sinclair_transpiled, prog_name, autostart_line=min(sinclair_transpiled.keys()) if sinclair_transpiled else 10)
            compiled_type = "BASIC"
        except Exception as e:
            canvas_print(f"Compile error: {e}")
            if os.path.exists(temp_out_tap):
                try:
                    os.remove(temp_out_tap)
                except Exception:
                    pass
            return

    # If program uses sprites or tilemap, bundle the relocatable machine code engines into the standalone TAP
    uses_sprites = any(re.search(r'\b(?:SPRITE|COLLISION|INCLUDE\s+SPRITES?)\b', code, re.IGNORECASE) for code in target_program.values())
    uses_tilemap = any(re.search(r'\b(?:TILEMAP|PLACE|TILE\s*\(|LOAD\s+TILEMAP|GRAB\s+TILES?|EDTILES?|TILED|INCLUDE\s+TILEMAPS?)\b', code, re.IGNORECASE) for code in target_program.values())
    if uses_sprites or uses_tilemap:
        try:
            bundle_engines_into_tap(temp_out_tap, compiled_type, prog_name, target_program)
        except Exception as e:
            canvas_print(f"Engine TAP bundle notice: {e}")

    # 1. Feedback to user on whether it compiled as machine code or compliant basic only .tap
    if compiled_type == "MC":
        canvas_print("Compiled as Machine Code .tap")
    else:
        canvas_print(f"Compiled as Compliant BASIC-only .tap ({len(target_program)} lines)")
        if boriel_fail_reason:
            canvas_print(f"MC notice: {boriel_fail_reason}")

    # 2. If no filename has been provided for destination .tap, bring up a dialog for the user to set name and location
    final_path = None
    if not has_dest:
        if os.environ.get("SDL_VIDEODRIVER") != "dummy" or os.environ.get("BASINPY_TEST_SAVE_DIALOG") == "1":
            try:
                chosen = ask_save_filename(
                    initialdir=os.getcwd(),
                    initialfile=f"{prog_name}.tap",
                    title="Set Destination .tap Name and Location",
                    filetypes=[("Spectrum TAP Files", "*.tap"), ("All Files", "*.*")],
                    defaultextension=".tap"
                )
                if chosen:
                    final_path = chosen
                else:
                    canvas_print("Save cancelled")
                    try:
                        if os.path.exists(temp_out_tap):
                            os.remove(temp_out_tap)
                    except Exception:
                        pass
                    return
            except Exception:
                pass
        if not final_path:
            final_path = os.path.join(os.getcwd(), f"{prog_name}.tap")
    else:
        final_path = default_dst_name if os.path.isabs(default_dst_name) else os.path.join(os.getcwd(), default_dst_name)

    try:
        shutil.copy2(temp_out_tap, final_path)
        zx_path = os.path.join(folder, os.path.basename(final_path))
        if os.path.abspath(final_path) != os.path.abspath(zx_path) and os.path.exists(folder):
            try:
                shutil.copy2(temp_out_tap, zx_path)
            except Exception:
                pass
        canvas_print(f"Destination: {os.path.basename(final_path)}")
    except Exception as e:
        canvas_print(f"Error saving to {final_path}: {e}")
    finally:
        if os.path.exists(temp_out_tap):
            try:
                os.remove(temp_out_tap)
            except Exception:
                pass


def handle_open_command(stmt_str):
    match = re.match(r"^OPEN\s*#?\s*(\d+)\s*,\s*(.+)$", stmt_str, re.IGNORECASE)
    if not match:
        canvas_print("Syntax: OPEN #stream, device_spec")
        return
    stream_idx = int(match.group(1))
    spec_str = match.group(2).strip()
    if 0 <= stream_idx < 16:
        if streams[stream_idx]:
            try:
                streams[stream_idx].close()
            except Exception:
                pass
            streams[stream_idx] = None
        dev_info = parse_device_spec(spec_str)
        dev_type = dev_info["type"]
        folder = get_zx_folder()
        if dev_type == "d":
            drive = dev_info.get("drive", mgt_default_drive)
            fname = dev_info.get("name", "unnamed")
            mgt_obj = MGTChannelStream(drive, fname)
            file_streams[stream_idx] = mgt_obj
            streams[stream_idx] = Channel(
                name=f"MGT{drive}:{fname}",
                write=lambda s: mgt_obj.write(s),
                readline=lambda: mgt_obj.readline(),
                readchar=lambda: mgt_obj.readchar(),
                close=lambda: mgt_obj.close()
            )
            canvas_print(f"Opened stream #{stream_idx} to Drive {drive} '{fname}'")
        elif dev_type == "m":
            drive = dev_info.get("drive", 1)
            fname = dev_info.get("name", "unnamed")
            mdr_obj = MDRChannelStream(drive, fname)
            file_streams[stream_idx] = mdr_obj
            streams[stream_idx] = Channel(
                name=f"MDV{drive}:{fname}",
                write=lambda s: mdr_obj.write(s),
                readline=lambda: mdr_obj.readline(),
                readchar=lambda: mdr_obj.readchar(),
                close=lambda: mdr_obj.close()
            )
            canvas_print(f"Opened stream #{stream_idx} to Microdrive {drive} '{fname}'")
        elif dev_type == "b":
            fname = dev_info.get("name", "serial_b.sbin")
            path = os.path.join(folder, fname)
            ser_obj = SerialBinChannel(path)
            file_streams[stream_idx] = ser_obj
            streams[stream_idx] = Channel(
                name=f"SERIAL_B:{fname}",
                write=lambda s: ser_obj.write(s),
                readline=lambda: ser_obj.readline(),
                readchar=lambda: ser_obj.readchar(),
                close=lambda: ser_obj.close()
            )
            canvas_print(f"Opened stream #{stream_idx} to RS-232 'b' ({fname})")
        elif dev_type == "t":
            fname = dev_info.get("name", "serial_t.sert")
            path = os.path.join(folder, fname)
            ser_obj = SerialTextChannel(path)
            file_streams[stream_idx] = ser_obj
            streams[stream_idx] = Channel(
                name=f"SERIAL_T:{fname}",
                write=lambda s: ser_obj.write(s),
                readline=lambda: ser_obj.readline(),
                readchar=lambda: ser_obj.readchar(),
                close=lambda: ser_obj.close()
            )
            canvas_print(f"Opened stream #{stream_idx} to RS-232 't' ({fname})")
        elif dev_type == "net_socket":
            host = dev_info["host"]
            port = dev_info["port"]
            proto = dev_info.get("proto", "tcp")
            try:
                net_sock_obj = SocketNetworkChannel(host, port, proto)
                file_streams[stream_idx] = net_sock_obj
                streams[stream_idx] = Channel(
                    name=f"NET:{proto.upper()}:{host}:{port}",
                    write=lambda s: net_sock_obj.write(s),
                    readline=lambda: net_sock_obj.readline(),
                    readchar=lambda: net_sock_obj.readchar(),
                    close=lambda: net_sock_obj.close()
                )
                canvas_print(f"Opened stream #{stream_idx} to {proto.upper()}://{host}:{port}")
            except Exception as e:
                canvas_print(f"Net stream open error: {e}")
        elif dev_type == "n":
            station = dev_info.get("station", 0)
            fname = dev_info.get("name", "net_broadcast.net")
            path = os.path.join(folder, fname)
            net_obj = NetChannel(path, station)
            file_streams[stream_idx] = net_obj
            streams[stream_idx] = Channel(
                name=f"NET:{station}:{fname}",
                write=lambda s: net_obj.write(s),
                readline=lambda: net_obj.readline(),
                readchar=lambda: net_obj.readchar(),
                close=lambda: net_obj.close()
            )
            canvas_print(f"Opened stream #{stream_idx} to Net station {station} ({fname})")
        else:
            fname = dev_info.get("name", "data.txt")
            path = os.path.join(folder, fname)
            txt_obj = SerialTextChannel(path)
            file_streams[stream_idx] = txt_obj
            streams[stream_idx] = Channel(
                name=f"FILE:{fname}",
                write=lambda s: txt_obj.write(s),
                readline=lambda: txt_obj.readline(),
                readchar=lambda: txt_obj.readchar(),
                close=lambda: txt_obj.close()
            )
            canvas_print(f"Opened stream #{stream_idx} to file {fname}")
    else:
        canvas_print("Error: Stream number must be 0-15")


def handle_close_command(stmt_str):
    match = re.match(r"^CLOSE\s*#?\s*(\d+)", stmt_str, re.IGNORECASE)
    if match:
        stream_idx = int(match.group(1))
        if 0 <= stream_idx < 16 and streams[stream_idx]:
            try:
                streams[stream_idx].close()
            except Exception as e:
                canvas_print(f"Close error: {e}")
            streams[stream_idx] = None
            if stream_idx in file_streams:
                del file_streams[stream_idx]
            if stream_idx in (0, 1, 2, 3):
                init_default_channels()


def execute_cls(win=None):
    global current_paper, current_ink, current_bright, current_flash, current_inverse, current_over
    global current_bold, current_italic, current_underline
    global print_row, print_col, canvas_lines, screen_chars, cell_bitmap, attr_ink, attr_paper, attr_bright, attr_flash, attr_used, gfx_bits, canvas_dirty, screen_bitmap_dirty
    screen_bitmap_dirty = True
    global timex_screen_mode, timex_hires_palette
    if win is None:
        win = active_window
    wx = win.get("x", 0)
    wy = win.get("y", 0)
    ww = win.get("w", 32)
    wh = win.get("h", 24)
    is_full = (wx == 0 and wy == 0 and ww == 32 and wh == 24)
    current_inverse = False
    current_over = False
    current_bold = False
    current_italic = False
    current_underline = False
    attr_byte = ((1 if current_flash else 0) << 7) | ((1 if current_bright else 0) << 6) | ((current_paper & 7) << 3) | (current_ink & 7)
    if len(memory) > 23695:
        memory[23693] = attr_byte  # ATTR_P: Flash, Bright, Paper, Ink
        memory[23695] = attr_byte  # ATTR_T
    map_c = map_color if 'map_color' in globals() else (lambda c, b: COLORS[c + (8 if b else 0)])
    fill_color = map_c(current_paper, current_bright)
    if is_full:
        for r in range(ATTR_ROWS):
            for c in range(ATTR_COLS):
                attr_ink[r][c] = current_ink
                attr_paper[r][c] = current_paper
                attr_bright[r][c] = current_bright
                attr_flash[r][c] = current_flash
                attr_used[r][c] = False
                screen_chars[r][c] = ' '
                cell_bitmap[r][c] = None
        max_clr_w = 512 if timex_screen_mode == 6 else 256
        for x in range(max_clr_w):
            for y in range(192):
                gfx_bits[x][y] = False
        canvas_lines.clear()
        print_row = 0
        print_col = 0
        if timex_screen_mode == 6:
            memory[0x4000:0x5800] = b'\x00' * 6144
            memory[0x6000:0x7800] = b'\x00' * 6144
            pal_idx = timex_hires_palette & 7
            fill_color = map_c(TIMEX_HIRES_COLORS[pal_idx][1], False)
        elif timex_screen_mode == 2:
            memory[0x4000:0x5800] = b'\x00' * 6144
            memory[0x6000:0x7800] = bytes([attr_byte]) * 6144
        elif timex_screen_mode == 1:
            memory[0x6000:0x7800] = b'\x00' * 6144
            memory[0x7800:0x7B00] = bytes([attr_byte]) * 768
        else:
            memory[0x4000:0x5800] = b'\x00' * 6144
            memory[0x5800:0x5B00] = bytes([attr_byte]) * 768
        if "canvas" in globals() and canvas:
            canvas.fill(fill_color)
    else:
        for r in range(wy, min(24, wy + wh)):
            for c in range(wx, min(32, wx + ww)):
                attr_ink[r][c] = current_ink
                attr_paper[r][c] = current_paper
                attr_bright[r][c] = current_bright
                attr_flash[r][c] = current_flash
                attr_used[r][c] = False
                screen_chars[r][c] = ' '
                cell_bitmap[r][c] = None
        max_px_w = min(512 if timex_screen_mode == 6 else 256, (wx + ww) * 8)
        for x in range(wx * 8, max_px_w):
            for y in range(max(0, 192 - (wy + wh) * 8), min(192, 192 - wy * 8)):
                gfx_bits[x][y] = False
        if "canvas" in globals() and canvas and 'pygame' in globals():
            rect = pygame.Rect(wx * 8, wy * 8, ww * 8, wh * 8)
            canvas.fill(fill_color, rect)
        print_row = 0
        print_col = 0
    canvas_dirty = True
    if "redraw_canvas" in globals():
        redraw_canvas(force=True)
    if "update_display" in globals():
        try:
            update_display()
        except Exception:
            pass


def handle_cls_stream(stream_idx):
    if stream_idx == 0:
        global print_row, print_col, screen_chars, cell_bitmap, attr_ink, attr_paper, attr_bright, attr_flash, attr_used, gfx_bits, canvas_dirty, screen_bitmap_dirty
        for r in (22, 23):
            for c in range(ATTR_COLS):
                attr_ink[r][c] = current_ink
                attr_paper[r][c] = current_paper
                attr_bright[r][c] = current_bright
                attr_flash[r][c] = current_flash
                attr_used[r][c] = False
                screen_chars[r][c] = ' '
                cell_bitmap[r][c] = None
        for x in range(256):
            for y in range(16):
                gfx_bits[x][y] = False
        print_row = 22
        print_col = 0
        canvas_dirty = True
        screen_bitmap_dirty = True
        if "update_display" in globals():
            try:
                update_display()
            except Exception:
                pass
    else:
        execute_cls()


def execute_print_stream(stream_idx, print_str):
    if not (0 <= stream_idx < 16) or streams[stream_idx] is None:
        canvas_print(f"Stream #{stream_idx} not open")
        return
    if stream_idx in (0, 1, 2):
        if stream_idx == 0:
            global print_row, print_col
            print_row = 22
            print_col = 0
        execute_print_items(print_str)
        return

    items_with_sep = []
    current = []
    in_string = False
    paren_depth = 0
    current_sep = None
    i = 0
    n = len(print_str)
    while i < n:
        char = print_str[i]
        if char in ('"', "'"):
            if char == "'" and not in_string and paren_depth == 0:
                item_text = "".join(current).strip()
                if item_text or current_sep is not None:
                    items_with_sep.append((current_sep, item_text))
                current = []
                current_sep = "'"
                i += 1
                continue
            in_string = not in_string
            current.append(char)
        elif not in_string:
            if char == '(':
                paren_depth += 1
                current.append(char)
            elif char == ')':
                paren_depth = max(0, paren_depth - 1)
                current.append(char)
            elif paren_depth == 0:
                if char in (';', ','):
                    items_with_sep.append((current_sep, "".join(current).strip()))
                    current = []
                    current_sep = char
                elif char == "'":
                    items_with_sep.append((current_sep, "".join(current).strip()))
                    current = []
                    current_sep = "'"
                else:
                    current.append(char)
            else:
                current.append(char)
        else:
            current.append(char)
        i += 1
    if current:
        items_with_sep.append((current_sep, "".join(current).strip()))

    suppress_newline = False
    stripped_str = print_str.strip()
    if stripped_str.endswith(';') or stripped_str.endswith(',') or stripped_str.endswith("'"):
        suppress_newline = True

    out_parts = []
    curr_col = 0
    for sep, item in items_with_sep:
        if sep == ",":
            needed = 16 - (curr_col % 16)
            out_parts.append(" " * needed)
            curr_col += needed
        elif sep == "'":
            out_parts.append("\n")
            curr_col = 0

        if not item:
            continue
        try:
            val = evaluate_expr(item)
            val_str = format_val(val)
        except Exception:
            val_str = str(item)
        out_parts.append(val_str)
        curr_col += len(val_str)

    if not suppress_newline:
        out_parts.append("\n")

    text_to_write = "".join(out_parts)
    streams[stream_idx].write(text_to_write)


def assign_input_variable(var_target, entered_val):
    global variables, string_variables, arrays
    var_target = var_target.strip()
    if not var_target:
        return
    match_str_slice = re.match(r"^([A-Za-z][A-Za-z0-9]*\$)\s*\((.+)\)$", var_target)
    arr_match = re.match(r"^([A-Za-z][A-Za-z0-9]*)\s*\((.+)\)$", var_target)
    if match_str_slice:
        var_name = match_str_slice.group(1).upper()
        slice_spec = match_str_slice.group(2).strip()
        set_string_value(var_name, slice_spec, entered_val)
    elif arr_match and not arr_match.group(1).upper().endswith("$"):
        arr_name = arr_match.group(1).upper()
        indices_str = arr_match.group(2)
        indices = [int(evaluate_expr(ind.strip())) for ind in split_top_level_commas(indices_str)]
        for idx in indices:
            if idx < 1:
                raise Exception("Subscript out of range")
        if arr_name not in arrays:
            arrays[arr_name] = make_nd_array(indices, 0.0)
        node = arrays[arr_name]
        for idx in indices[:-1]:
            if idx >= len(node):
                raise Exception("Subscript out of range")
            node = node[idx]
        if indices[-1] >= len(node):
            raise Exception("Subscript out of range")
        try:
            str_val = str(entered_val).strip()
            num_val = float(str_val) if "." in str_val else int(str_val)
        except ValueError:
            num_val = 0.0
        node[indices[-1]] = to_float(num_val)
    else:
        var_name = var_target.upper()
        if var_name.endswith("$"):
            string_variables[var_name] = str(entered_val)
        else:
            try:
                str_val = str(entered_val).strip()
                num_val = float(str_val) if "." in str_val else int(str_val)
                variables[var_name] = float(num_val)
            except ValueError:
                variables[var_name] = 0.0


def handle_input_statement(stmt_str):
    global current_paper, current_ink, print_row, print_col, screen_chars, cell_bitmap, attr_ink, attr_paper, attr_bright, attr_flash, attr_used, canvas_lines, variables, string_variables
    match_stream = re.match(r"^INPUT\s*#\s*(\d+)\s*[;,]\s*(.+)$", stmt_str, re.IGNORECASE)
    if match_stream:
        stream_idx = int(match_stream.group(1))
        rest_input = match_stream.group(2).strip()
        if stream_idx not in (0, 1):
            if 0 <= stream_idx < 16 and streams[stream_idx]:
                chan = streams[stream_idx]
                line_data = chan.readline()
                target_vars = rest_input
                while target_vars.startswith((';', ',')):
                    target_vars = target_vars[1:].strip()
                m_prompt = re.match(r'^("([^"\\]|\\.)*"|\'([^\'\\]|\\.)*\')\s*[;,]\s*(.+)$', target_vars)
                if m_prompt:
                    target_vars = m_prompt.group(4).strip()
                while target_vars.startswith((';', ',')):
                    target_vars = target_vars[1:].strip()

                is_line_input = False
                if target_vars.upper().startswith("LINE "):
                    is_line_input = True
                    target_vars = target_vars[5:].strip()

                if is_line_input:
                    assign_input_variable(target_vars.strip(), line_data.rstrip('\r\n'))
                else:
                    var_targets = split_top_level_commas(target_vars)
                    if len(var_targets) == 1:
                        tokens = [line_data.strip()]
                    elif "," in line_data:
                        tokens = [t.strip() for t in line_data.split(",") if t.strip()]
                    else:
                        tokens = line_data.split()
                    for idx, v_target in enumerate(var_targets):
                        v_target = v_target.strip()
                        val_str = tokens[idx] if idx < len(tokens) else ""
                        assign_input_variable(v_target, val_str)
            else:
                canvas_print(f"Stream #{stream_idx} not open for INPUT")
            return
        else:
            inp_content = rest_input
    else:
        inp_content = stmt_str[5:].strip()

    target_spec = inp_content.strip()

    # In ZX Spectrum BASIC, INPUT can contain print controls, prompts, and variable targets:
    # e.g., INPUT ;"How many players? (1-4) ";sp
    #       INPUT AT 10, 5; "Prompt"; a
    #       INPUT ; "Target Score? "; f(1,1)
    #       INPUT LINE a$
    while target_spec.startswith((';', ',')):
        target_spec = target_spec[1:].strip()

    has_prompt = False

    # Consume any leading print items (AT, TAB, color modifiers, string prompts)
    while target_spec:
        m_at = re.match(r"^AT\s+([^;,]+)\s*,\s*([^;,]+)\s*([;,]?)\s*(.*)$", target_spec, re.IGNORECASE)
        if m_at:
            execute_print_items(f"AT {m_at.group(1)}, {m_at.group(2)};")
            target_spec = m_at.group(4).strip()
            while target_spec.startswith((';', ',')):
                target_spec = target_spec[1:].strip()
            continue

        m_tab = re.match(r"^TAB\s+([^;,]+)\s*([;,]?)\s*(.*)$", target_spec, re.IGNORECASE)
        if m_tab:
            execute_print_items(f"TAB {m_tab.group(1)};")
            target_spec = m_tab.group(3).strip()
            while target_spec.startswith((';', ',')):
                target_spec = target_spec[1:].strip()
            continue

        m_col = re.match(r"^(INK|PAPER|FLASH|BRIGHT|INVERSE|OVER)\s+([^;,]+)\s*([;,]?)\s*(.*)$", target_spec, re.IGNORECASE)
        if m_col:
            execute_print_items(f"{m_col.group(1)} {m_col.group(2)};")
            target_spec = m_col.group(4).strip()
            while target_spec.startswith((';', ',')):
                target_spec = target_spec[1:].strip()
            continue

        m_str = re.match(r'^("([^"\\]|\\.)*"|\'([^\'\\]|\\.)*\')\s*([;,]?)\s*(.*)$', target_spec)
        if m_str:
            prompt_lit = m_str.group(1)
            prompt_text = prompt_lit.strip('"\'')
            execute_print_items(f"{prompt_lit};")
            has_prompt = True
            target_spec = m_str.group(5).strip()
            while target_spec.startswith((';', ',')):
                target_spec = target_spec[1:].strip()
            continue

        break

    is_line_input = False
    if target_spec.upper().startswith("LINE "):
        is_line_input = True
        target_spec = target_spec[5:].strip()

    if not has_prompt:
        execute_print_items('"? ";')

    is_menu_code_input = ("code number" in prompt_text.lower() or prompt_text.lower().startswith("please enter code"))

    waiting_input = True
    entered_chars = []
    cursor_visible = False
    last_cursor_toggle = 0
    saved_cursor_cell = None

    def restore_cursor_cell():
        nonlocal saved_cursor_cell
        if saved_cursor_cell is not None:
            cr, cc, och, obmp, oink, opap, oused = saved_cursor_cell
            if 0 <= cr < 24 and 0 <= cc < 32:
                screen_chars[cr][cc] = och
                cell_bitmap[cr][cc] = obmp
                attr_ink[cr][cc] = oink
                attr_paper[cr][cc] = opap
                attr_used[cr][cc] = oused
            saved_cursor_cell = None

    try:
        while waiting_input and running:
            now_ms = pygame.time.get_ticks()
            if now_ms - last_cursor_toggle >= 250:
                last_cursor_toggle = now_ms
                cursor_visible = not cursor_visible
                if 0 <= print_row < 24 and 0 <= print_col < 32:
                    if cursor_visible:
                        if saved_cursor_cell is None:
                            saved_cursor_cell = (
                                print_row, print_col,
                                screen_chars[print_row][print_col],
                                cell_bitmap[print_row][print_col],
                                attr_ink[print_row][print_col],
                                attr_paper[print_row][print_col],
                                attr_used[print_row][print_col]
                            )
                        screen_chars[print_row][print_col] = 'L'
                        cell_bitmap[print_row][print_col] = None
                        attr_ink[print_row][print_col] = current_paper
                        attr_paper[print_row][print_col] = current_ink
                        attr_used[print_row][print_col] = True
                    else:
                        restore_cursor_cell()
                    canvas_lines = ["".join(row) for row in screen_chars]
                    canvas_dirty = True
                    redraw_canvas()

            pygame.event.pump()
            update_display()
            keys = pygame.key.get_pressed()
            if keys[pygame.K_ESCAPE]:
                raise BASICBreak("D BREAK - CONT repeats")
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit()
                    sys.exit()
                elif is_break_event(event):
                    raise BASICBreak("D BREAK - CONT repeats")
                elif event.type == pygame.MOUSEMOTION:
                    update_amx_from_mouse(event.pos)
                elif event.type in (pygame.MOUSEBUTTONDOWN, pygame.MOUSEBUTTONUP):
                    update_amx_buttons(event)
                elif event.type == pygame.KEYDOWN:
                    if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER) or event.unicode in ('\r', '\n'):
                        restore_cursor_cell()
                        waiting_input = False
                    elif event.key == pygame.K_BACKSPACE:
                        restore_cursor_cell()
                        if len(entered_chars) > 0:
                            entered_chars.pop()
                            print_col -= 1
                            if print_col < 0:
                                print_col = 31
                                print_row = max(0, print_row - 1)
                            screen_chars[print_row][print_col] = ' '
                            cell_bitmap[print_row][print_col] = None
                            canvas_lines = ["".join(row) for row in screen_chars]
                            canvas_dirty = True
                            redraw_canvas()
                            update_display()
                    else:
                        restore_cursor_cell()
                        ch = event.unicode
                        if not ch or ord(ch) < 32 or ord(ch) > 126:
                            # Keypad and fallback mapping for numbers, numpad, and navigation keys
                            if event.key in (pygame.K_1, pygame.K_KP1, getattr(pygame, 'K_KP_1', pygame.K_KP1), pygame.K_END):
                                ch = '1'
                            elif event.key in (pygame.K_2, pygame.K_KP2, getattr(pygame, 'K_KP_2', pygame.K_KP2), pygame.K_DOWN):
                                ch = '2'
                            elif event.key in (pygame.K_3, pygame.K_KP3, getattr(pygame, 'K_KP_3', pygame.K_KP3), pygame.K_PAGEDOWN):
                                ch = '3'
                            elif event.key in (pygame.K_4, pygame.K_KP4, getattr(pygame, 'K_KP_4', pygame.K_KP4), pygame.K_LEFT):
                                ch = '4'
                            elif event.key in (pygame.K_5, pygame.K_KP5, getattr(pygame, 'K_KP_5', pygame.K_KP5), getattr(pygame, 'K_CLEAR', -1)):
                                ch = '5'
                            elif event.key in (pygame.K_6, pygame.K_KP6, getattr(pygame, 'K_KP_6', pygame.K_KP6), pygame.K_RIGHT):
                                ch = '6'
                            elif event.key in (pygame.K_7, pygame.K_KP7, getattr(pygame, 'K_KP_7', pygame.K_KP7), pygame.K_HOME):
                                ch = '7'
                            elif event.key in (pygame.K_8, pygame.K_KP8, getattr(pygame, 'K_KP_8', pygame.K_KP8), pygame.K_UP):
                                ch = '8'
                            elif event.key in (pygame.K_9, pygame.K_KP9, getattr(pygame, 'K_KP_9', pygame.K_KP9), pygame.K_PAGEUP):
                                ch = '9'
                            elif event.key in (pygame.K_0, pygame.K_KP0, getattr(pygame, 'K_KP_0', pygame.K_KP0), pygame.K_INSERT):
                                ch = '0'
                            elif pygame.K_a <= event.key <= pygame.K_z:
                                ch = chr(ord('a') + (event.key - pygame.K_a))
                            elif event.key == pygame.K_SPACE:
                                ch = ' '

                        if ch and ord(ch) >= 32 and ch not in ('\r', '\n'):
                            if currah_enabled and currah_keyvoice:
                                currah_speak(ch)
                            entered_chars.append(ch)
                            if 0 <= print_row < 24 and 0 <= print_col < 32:
                                screen_chars[print_row][print_col] = ch
                                cell_bitmap[print_row][print_col] = None
                                cell_x, cell_y = print_col, print_row
                                attr_ink[cell_y][cell_x] = current_ink
                                attr_paper[cell_y][cell_x] = current_paper
                                attr_used[cell_y][cell_x] = True
                            print_col += 1
                            if print_col >= 32:
                                print_col = 0
                                print_row += 1
                            canvas_lines = ["".join(row) for row in screen_chars]
                            canvas_dirty = True
                            redraw_canvas()
                            update_display()

                            # If menu code input and 1-5 pressed on empty buffer: auto-submit immediately
                            if is_menu_code_input and len(entered_chars) == 1 and ch in ('1', '2', '3', '4', '5'):
                                waiting_input = False
            pygame.time.delay(10)
    finally:
        restore_cursor_cell()
        canvas_dirty = True
        redraw_canvas()

    print_row += 1
    print_col = 0
    if print_row >= 24:
        print_row = 23

    entered_val = "".join(entered_chars).strip()
    if is_line_input:
        assign_input_variable(target_spec.strip(), "".join(entered_chars))
    else:
        var_targets = split_top_level_commas(target_spec)
        if len(var_targets) == 1:
            assign_input_variable(var_targets[0].strip(), entered_val)
        else:
            tokens = [t.strip() for t in entered_val.split(",") if t.strip()]
            for idx, v_target in enumerate(var_targets):
                val_str = tokens[idx] if idx < len(tokens) else ""
                assign_input_variable(v_target.strip(), val_str)


def get_target_line_idx(target_ln, line_numbers):
    if target_ln in program:
        return line_numbers.index(target_ln)
    for idx, ln in enumerate(line_numbers):
        if ln > target_ln:
            return idx
    raise Exception(f"Line {target_ln} not found")


_COLOR_LUT = (
    tuple(COLORS[i] for i in range(8)),
    tuple(BRIGHT_COLORS[i] for i in range(8))
)


def map_color(color_idx, bright_flag):
    return _COLOR_LUT[1 if bright_flag else 0][color_idx & 7]


_PRECACHED_BEEPS = {}
_LAST_BEEP_TIME = 0


def play_spectrum_beep(duration, pitch):
    global _LAST_BEEP_TIME
    if duration <= 0:
        return
    # Skip completely in headless or dummy audio mode, or if mixer is not initialized
    if os.environ.get("SDL_AUDIODRIVER") == "dummy" or not pygame.mixer.get_init():
        return

    now = pygame.time.get_ticks()
    # Rate limit rapid beeps within 10ms to prevent audio queue saturation and CPU freeze
    if duration <= 0.02 and (now - _LAST_BEEP_TIME) < 10:
        return
    _LAST_BEEP_TIME = now

    key = (round(duration, 4), round(pitch, 2))
    sound = _PRECACHED_BEEPS.get(key)
    if sound is None:
        frequency = 440.0 * (2.0 ** ((pitch - 9.0) / 12.0))
        sample_rate = 22050
        num_samples = int(sample_rate * duration)
        buffer = bytearray()
        for i in range(num_samples):
            val = int(32767 * 0.5 * (1 if ((i * frequency / sample_rate) % 1.0) < 0.5 else -1))
            buffer.extend(val.to_bytes(2, byteorder="little", signed=True))
        try:
            sound = pygame.mixer.Sound(buffer=bytes(buffer))
            if len(_PRECACHED_BEEPS) < 128:
                _PRECACHED_BEEPS[key] = sound
        except Exception:
            return

    try:
        sound.play()
    except Exception:
        pass

    if duration < 0.02:
        return
    start_time = pygame.time.get_ticks()
    ms_dur = int(duration * 1000)
    while (pygame.time.get_ticks() - start_time) < ms_dur:
        pygame.event.pump()
        keys = pygame.key.get_pressed()
        if keys[pygame.K_ESCAPE] or keys[pygame.K_END]:
            sound.stop()
            raise BASICBreak()
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            elif is_break_event(event):
                sound.stop()
                raise BASICBreak()
            elif event.type == pygame.KEYDOWN:
                k_char = None
                if event.key in (pygame.K_BACKSPACE, pygame.K_DELETE):
                    k_char = chr(12)
                elif event.key == pygame.K_RETURN:
                    k_char = '\r'
                elif event.key == pygame.K_SPACE:
                    k_char = ' '
                elif getattr(event, 'unicode', None):
                    k_char = event.unicode
                if k_char:
                    if 'last_keypress' in globals():
                        last_keypress = k_char
                    if 'key_press_buffer' in globals():
                        key_press_buffer.append(k_char)
                    if 'memory' in globals() and len(memory) > 23560:
                        memory[23560] = ord(k_char[0]) & 0xFF
                        memory[23561] = 0
        pygame.time.delay(5)


# ==============================================================================
# Sinclair ZX Spectrum Tape Loading Border Effect Simulation
# ==============================================================================

def render_tape_border_stripes(target_surf, border_rect, scale_y, phase, frame_num):
    """
    Renders authentic Sinclair ZX Spectrum tape loading stripes across border_rect.
    phase == 0: Pause / silence (solid border color)
    phase == 1: Pilot tone (Magenta/Red bars)
    phase == 2: Data block (Finer Yellow/Blue bars)
    """
    bx = border_rect.x
    by = border_rect.y
    bw = border_rect.width
    bh = border_rect.height
    if bw <= 0 or bh <= 0:
        return

    if phase == 0:
        # Phase 0: Pause (solid border)
        solid_color = map_color(current_border, False)
        pygame.draw.rect(target_surf, solid_color, border_rect)
        return
    elif phase == 1:
        # Phase 1: Pilot tone (Magenta & Red horizontal bars)
        c1 = COLORS[3]  # Magenta (215, 0, 215)
        c2 = COLORS[2]  # Red (215, 0, 0)
        bar_h = max(3, int(8 * scale_y))
        y_offset = int(frame_num * 3) % (bar_h * 2)
        y = by - y_offset
        flip = 0
        while y < by + bh:
            stripe_y = max(by, y)
            stripe_h = min(by + bh - stripe_y, bar_h - (stripe_y - y))
            if stripe_h > 0:
                color = c1 if flip % 2 == 0 else c2
                pygame.draw.rect(target_surf, color, pygame.Rect(bx, stripe_y, bw, stripe_h))
            y += bar_h
            flip += 1
    else:
        # Phase 2: Data block (Finer Yellow & Blue horizontal bars)
        c1 = COLORS[6]  # Yellow (215, 215, 0)
        c2 = COLORS[1]  # Blue (0, 0, 215)
        fine_h = max(1, int(2 * scale_y))
        # High-frequency pattern with deterministic variation per frame for jittery retro effect
        seed = (frame_num * 1664525 + 1013904223) & 0xFFFFFFFF
        y = by
        flip = (frame_num % 2)
        while y < by + bh:
            seed = (seed * 1103515245 + 12345) & 0x7FFFFFFF
            var = seed % 3
            h = fine_h if var == 0 else (fine_h * 2 if var == 1 else max(1, fine_h + 1))
            if y + h > by + bh:
                h = by + bh - y
            color = c1 if flip % 2 == 0 else c2
            pygame.draw.rect(target_surf, color, pygame.Rect(bx, y, bw, h))
            y += h
            flip += 1


_tape_pilot_sound_cache = None
_tape_data_sound_cache = None

def _generate_tape_pilot_sound(duration=5.0):
    global _tape_pilot_sound_cache
    if _tape_pilot_sound_cache is not None:
        return _tape_pilot_sound_cache
    try:
        sample_rate = 22050
        num_samples = int(sample_rate * min(duration, 5.0))
        freq = 806.0  # ZX Spectrum pilot tone ~806 Hz
        buffer = bytearray()
        amplitude = int(32767 * 0.15)  # 15% amplitude for comfortable listening
        for i in range(num_samples):
            val = amplitude if ((i * freq / sample_rate) % 1.0) < 0.5 else -amplitude
            buffer.extend(val.to_bytes(2, byteorder="little", signed=True))
        _tape_pilot_sound_cache = pygame.mixer.Sound(buffer=bytes(buffer))
        return _tape_pilot_sound_cache
    except Exception:
        return None


def _generate_tape_data_sound(duration=5.0):
    global _tape_data_sound_cache
    if _tape_data_sound_cache is not None:
        return _tape_data_sound_cache
    try:
        sample_rate = 22050
        num_samples = int(sample_rate * min(duration, 5.0))
        buffer = bytearray()
        amplitude = int(32767 * 0.15)  # 15% amplitude
        phase = 0.0
        seed = 1234567
        current_freq = 1500.0
        samples_left_in_bit = 0
        for i in range(num_samples):
            if samples_left_in_bit <= 0:
                seed = (seed * 1103515245 + 12345) & 0x7FFFFFFF
                bit = (seed >> 16) & 1
                current_freq = 2048.0 if bit == 0 else 1024.0
                samples_left_in_bit = int(sample_rate / (current_freq * 2))
            phase += current_freq / sample_rate
            if phase >= 1.0:
                phase -= 1.0
            val = amplitude if phase < 0.5 else -amplitude
            buffer.extend(val.to_bytes(2, byteorder="little", signed=True))
            samples_left_in_bit -= 1
        _tape_data_sound_cache = pygame.mixer.Sound(buffer=bytes(buffer))
        return _tape_data_sound_cache
    except Exception:
        return None


def print_loading_filename(filename, file_type="Program"):
    """
    Prints the loading filename at the top of the Spectrum output screen (row 0).
    Follows authentic Sinclair ZX Spectrum ROM behavior (e.g. 'Program: <name>' or 'Bytes: <name>').
    """
    global screen_chars, cell_bitmap, attr_ink, attr_paper, attr_bright, attr_flash, attr_used, gfx_bits, canvas_lines, canvas_dirty
    if is_execution_mode():
        return
    if not filename:
        return
    clean_name = os.path.splitext(os.path.basename(filename))[0].strip(' "\',;')
    if not clean_name:
        return
    prefix = f"{file_type}: " if file_type else ""
    display_str = f"{prefix}{clean_name}"[:ATTR_COLS]

    # Clear graphic bits in row 0 so graphic lines do not clash with text
    for x in range(256):
        for y in range(8):
            gfx_bits[x][191 - y] = False

    # Set row 0 character cells and attributes (black ink on white paper)
    for c in range(ATTR_COLS):
        ch = display_str[c] if c < len(display_str) else ' '
        screen_chars[0][c] = ch
        cell_bitmap[0][c] = None
        attr_ink[0][c] = 0      # Black
        attr_paper[0][c] = 7    # White
        attr_bright[0][c] = False
        attr_flash[0][c] = False
        attr_used[0][c] = True

    canvas_lines = ["".join(ch if (' ' <= ch <= '~') else ' ' for ch in row) for row in screen_chars]
    canvas_dirty = True


def simulate_tape_loading_border(operation_name="Loading", filename="", file_type="Program", duration_sec=10.0, fast_test=False):
    """
    Simulates authentic Sinclair ZX Spectrum tape loading border effects:
    1. Pilot tone: Magenta & Red border stripes with 806 Hz pilot tone.
    2. Header block: 'Program: <name>' printed at row 0 after magenta/red effect,
       followed straight after by 0.5s of Yellow & Blue border stripes.
    3. Pause: 0.25s pause with solid border color and silence.
    4. Data block: Normal Yellow & Blue border stripes with data chirp sound.
    Supports skipping via SPACE/RETURN or breaking via ESC/END.
    """
    global tape_simulation_active, tape_sim_phase, tape_sim_frame

    # Filename will be printed after the magenta and red border effect completes (not immediately)
    filename_printed = False

    is_headless = (os.environ.get("SDL_VIDEODRIVER") == "dummy") or fast_test

    pilot_sound = None
    data_sound = None
    active_channel = None
    try:
        if pygame.mixer.get_init() and not is_headless:
            pilot_sound = _generate_tape_pilot_sound(5.0)
            data_sound = _generate_tape_data_sound(5.0)
    except Exception:
        pass

    sound_len_ms = int(data_sound.get_length() * 1000) if (data_sound and hasattr(data_sound, "get_length")) else 1250

    if is_headless:
        total_ms = 100 if (duration_sec is None or duration_sec >= 1.0) else max(10, int(duration_sec * 1000))
        stage1_ms = int(total_ms * 0.4)
        stage2_ms = int(total_ms * 0.25)
        stage3_ms = int(total_ms * 0.15)
    else:
        req_ms = int(duration_sec * 1000) if duration_sec is not None else 10000
        if req_ms >= 3000:
            stage1_ms = 2000
            stage2_ms = 500
            stage3_ms = 250
            stage4_ms = sound_len_ms
            total_ms = stage1_ms + stage2_ms + stage3_ms + stage4_ms
        else:
            total_ms = req_ms
            stage1_ms = int(total_ms * 0.4)
            stage2_ms = int(total_ms * 0.25)
            stage3_ms = int(total_ms * 0.15)

    tape_simulation_active = True
    tape_sim_phase = 1
    tape_sim_frame = 0

    clock = pygame.time.Clock()
    start_ticks = pygame.time.get_ticks()
    audio_phase = 0
    stage4_started = False
    stage4_start_ticks = 0

    try:
        while True:
            elapsed = pygame.time.get_ticks() - start_ticks
            if elapsed >= total_ms:
                break

            if elapsed < stage1_ms:
                tape_sim_phase = 1
                if audio_phase != 1 and pilot_sound:
                    if active_channel:
                        try: active_channel.stop()
                        except Exception: pass
                    try: active_channel = pilot_sound.play()
                    except Exception: pass
                    audio_phase = 1
            elif elapsed < stage1_ms + stage2_ms:
                if not filename_printed:
                    if filename and operation_name.startswith("Loading") and not is_execution_mode():
                        print_loading_filename(filename, file_type)
                    filename_printed = True
                tape_sim_phase = 2
                if audio_phase != 2 and data_sound:
                    if active_channel:
                        try: active_channel.stop()
                        except Exception: pass
                    try: active_channel = data_sound.play()
                    except Exception: pass
                    audio_phase = 2
            elif elapsed < stage1_ms + stage2_ms + stage3_ms:
                tape_sim_phase = 0
                if audio_phase != 0:
                    if active_channel:
                        try: active_channel.stop()
                        except Exception: pass
                    active_channel = None
                    audio_phase = 0
            else:
                tape_sim_phase = 2
                if audio_phase != 4 and data_sound:
                    if active_channel:
                        try: active_channel.stop()
                        except Exception: pass
                    try: active_channel = data_sound.play()
                    except Exception: pass
                    audio_phase = 4
                    stage4_started = True
                    stage4_start_ticks = pygame.time.get_ticks()
                elif audio_phase == 4 and stage4_started:
                    # Blue and yellow data load simulation terminates as soon as sound completes
                    if (pygame.time.get_ticks() - stage4_start_ticks >= 100) and active_channel and not active_channel.get_busy():
                        break

            tape_sim_frame += 1

            # Check events: Allow break (ESC/END) or skip (SPACE/RETURN)
            should_skip = False
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit()
                    sys.exit()
                elif event.type == pygame.KEYDOWN:
                    if event.key in (pygame.K_ESCAPE, pygame.K_END):
                        if active_channel:
                            try: active_channel.stop()
                            except Exception: pass
                        tape_simulation_active = False
                        if not filename_printed and filename and operation_name.startswith("Loading"):
                            print_loading_filename(filename, file_type)
                            filename_printed = True
                        if canvas_dirty:
                            redraw_canvas()
                        render_frame()
                        pygame.display.flip()
                        raise BASICBreak()
                    elif event.key in (pygame.K_SPACE, pygame.K_RETURN):
                        should_skip = True
                        break
            if should_skip:
                break

            if canvas_dirty:
                redraw_canvas()
            render_frame()
            pygame.display.flip()
            if not is_headless:
                clock.tick(50)  # 50 Hz PAL refresh
            else:
                clock.tick(500)
    finally:
        if not filename_printed and filename and operation_name.startswith("Loading"):
            print_loading_filename(filename, file_type)
            filename_printed = True
        if active_channel:
            try: active_channel.stop()
            except Exception: pass
        tape_simulation_active = False
        tape_sim_phase = 1
        tape_sim_frame = 0
        if canvas_dirty:
            redraw_canvas()
        render_frame()
        pygame.display.flip()


# ==============================================================================
# Currah µSpeech (Microspeech) Hardware & Synthesizer Emulation
# ==============================================================================
currah_enabled = True
currah_busy_until = 0.0
currah_keyvoice = False
currah_allophone_buffer = []
currah_last_allophone_time = 0.0

_sp0256_voice = None
try:
    import win32com.client
    _sp0256_voice = win32com.client.Dispatch("SAPI.SpVoice")
except Exception:
    _sp0256_voice = None

SP0256_ALLOPHONES = {
    # 0x00 - 0x04: Pauses
    "PA1": " ", "PA2": " ", "PA3": " ", "PA4": " ", "PA5": " ",
    # 0x05 - 0x07
    "OY": "oy", "AY": "eye", "EH": "e",
    # 0x08 - 0x0F
    "KK3": "k", "PP": "p", "JH": "j", "NN1": "n",
    "IH": "i", "TT2": "t", "RR1": "r", "AX": "uh",
    # 0x10 - 0x17
    "MM": "m", "TT1": "t", "DH1": "th", "IY": "ee",
    "EY": "ay", "DD1": "d", "UW1": "oo", "AO": "aw",
    # 0x18 - 0x1F
    "AA": "ah", "YY2": "y", "AE": "a", "HH1": "h",
    "BB1": "b", "TH": "th", "UH": "oo", "AH": "uh",
    # 0x20 - 0x27
    "SH": "sh", "UX": "o", "ER1": "er", "ER2": "er",
    "OW": "oh", "DH2": "th", "SS": "s", "NN2": "n",
    # 0x28 - 0x2F
    "HH2": "h", "OR": "or", "AR": "ar", "UR": "ure",
    "GG2": "g", "EL": "el", "BB2": "b", "UK1": "oo",
    # 0x30 - 0x37
    "UK2": "you", "WW": "w", "DD2": "d", "GG1": "g",
    "VV": "v", "GG3": "g", "VV2": "v", "KK1": "k",
    # 0x38 - 0x3F
    "XK": "ch", "ZH": "zh", "KK2": "k", "ZZ": "z",
    "NG": "ng", "LL": "l", "WW2": "w", "XR": "for"
}

SP0256_ALLOPHONE_CODES = [
    # 0 - 7
    "PA1", "PA2", "PA3", "PA4", "PA5", "OY", "AY", "EH",
    # 8 - 15
    "KK3", "PP", "JH", "NN1", "IH", "TT2", "RR1", "AX",
    # 16 - 23
    "MM", "TT1", "DH1", "IY", "EY", "DD1", "UW1", "AO",
    # 24 - 31
    "AA", "YY2", "AE", "HH1", "BB1", "TH", "UH", "AH",
    # 32 - 39
    "SH", "UX", "ER1", "ER2", "OW", "DH2", "SS", "NN2",
    # 40 - 47
    "HH2", "OR", "AR", "UR", "GG2", "EL", "BB2", "UK1",
    # 48 - 55
    "UK2", "WW", "DD2", "GG1", "VV", "GG3", "VV2", "KK1",
    # 56 - 63
    "XK", "ZH", "KK2", "ZZ", "NG", "LL", "WW2", "XR"
]

CURRAH_ALLOPHONES = SP0256_ALLOPHONES
CURRAH_ALLOPHONE_CODES = SP0256_ALLOPHONE_CODES

# Known SP0256 allophone code sequences mapped to words
ORATOR_PHRASE_PATTERNS = {
    (23, 38): "hello",
    (23, 12, 38, 51): "spectrum",
    (38, 9, 7, 8, 13, 14, 15, 16): "spectrum",
    (38, 9, 7, 55, 13, 14, 15, 16): "spectrum",
    (38, 9, 7, 58, 13, 14, 15, 16): "spectrum",
    (38, 9, 7, 8, 17, 14, 15, 16): "spectrum",
    (38, 9, 7, 55, 17, 14, 15, 16): "spectrum",
    (38, 9, 7, 58, 17, 14, 15, 16): "spectrum",
    (38, 9, 7, 8, 13, 14, 31, 16): "spectrum",
    (27, 7, 45, 53): "hello",
    (27, 7, 45, 15, 53): "hello",
    (27, 7, 45, 45, 53): "hello",
    (14, 7, 21, 19): "ready",
}

currah_raw_codes = []

def currah_flush_allophones():
    global currah_allophone_buffer, currah_raw_codes
    if not currah_raw_codes and not currah_allophone_buffer:
        return
    seq = tuple(currah_raw_codes)
    if seq in ORATOR_PHRASE_PATTERNS:
        word = ORATOR_PHRASE_PATTERNS[seq]
    else:
        word = "".join(currah_allophone_buffer).strip()
    currah_allophone_buffer = []
    currah_raw_codes = []
    if word and _sp0256_voice:
        try:
            _sp0256_voice.Speak(word, 1)
        except Exception:
            pass


def currah_out_allophone(code):
    global currah_busy_until, currah_allophone_buffer, currah_raw_codes, currah_last_allophone_time
    if not currah_enabled:
        return
    code = int(code) & 0x3F
    name = SP0256_ALLOPHONE_CODES[code] if code < len(SP0256_ALLOPHONE_CODES) else "PA1"

    dur = 0.010 if code == 0 else (0.025 if code == 1 else (0.045 if code == 2 else (0.096 if code == 3 else (0.198 if code == 4 else 0.050))))
    currah_busy_until = time.time() + dur

    if code in (0, 1, 2, 3, 4):
        currah_flush_allophones()
    else:
        currah_raw_codes.append(code)
        phoneme = SP0256_ALLOPHONES.get(name, "")
        if phoneme:
            currah_allophone_buffer.append(phoneme)
            currah_last_allophone_time = time.time()


def currah_speak(text):
    global currah_busy_until
    if not currah_enabled:
        return
    text = str(text).strip()
    if not text:
        return
    currah_flush_allophones()

    def replace_allophone(m):
        cname = m.group(1).upper()
        return CURRAH_ALLOPHONES.get(cname, m.group(0))

    spoken = re.sub(r'\(([A-Za-z0-9]+)\)', replace_allophone, text)
    spoken = spoken.strip()
    if not spoken:
        return
    est_dur = max(0.35, len(spoken) * 0.075)
    currah_busy_until = time.time() + est_dur
    if _sp0256_voice:
        try:
            _sp0256_voice.Speak(spoken, 1)
        except Exception:
            pass


def currah_in_status():
    global currah_busy_until, currah_allophone_buffer, currah_raw_codes, currah_last_allophone_time
    now = time.time()
    if (currah_allophone_buffer or currah_raw_codes) and (now - currah_last_allophone_time > 0.25):
        currah_flush_allophones()
    if now < currah_busy_until:
        return 129.0
    return 0.0


# ==============================================================================
# AMX Mouse Hardware & AMX Control Emulation
# ==============================================================================
amx_enabled = True
amx_pointer_visible = False
current_mouse_mode = "AMX"
amx_x = 128
amx_y = 96
amx_btn_left = False
amx_btn_right = False
amx_btn_middle = False
amx_delta_x = 0
amx_delta_y = 0
amx_pio_ctrl_a = 0
amx_pio_ctrl_b = 0


def update_amx_from_mouse(mouse_pos):
    global amx_x, amx_y, amx_delta_x, amx_delta_y
    if scale_x <= 0 or scale_y <= 0:
        return
    mx, my = mouse_pos
    cur_w = canvas.get_width() if 'canvas' in globals() and canvas else 256
    cur_h = canvas.get_height() if 'canvas' in globals() and canvas else 192
    if 'scaled_canvas_w' in globals() and scaled_canvas_w > 0 and 'scaled_canvas_h' in globals() and scaled_canvas_h > 0:
        sx = int((mx - canvas_blit_x) / float(scaled_canvas_w) * cur_w)
        sy_top = int((my - canvas_blit_y) / float(scaled_canvas_h) * cur_h)
    else:
        sx = int((mx - canvas_blit_x) / scale_x)
        sy_top = int((my - canvas_blit_y) / scale_y)
    sx = max(0, min(cur_w - 1, sx))
    sy = max(0, min(cur_h - 1, (cur_h - 1) - sy_top))
    amx_delta_x = sx - amx_x
    amx_delta_y = sy - amx_y
    amx_x = sx
    amx_y = sy
    if 51920 < len(memory):
        memory[51915] = amx_x & 0xFF
        memory[51916] = amx_y & 0xFF
    if WIMPDesktop is not None:
        try:
            d = WIMPDesktop.get_instance()
            d.mouse_x = sx
            d.mouse_y = sy_top
        except Exception:
            pass


def update_amx_buttons(event=None):
    global amx_btn_left, amx_btn_right, amx_btn_middle
    if event is not None:
        if event.type == pygame.MOUSEBUTTONDOWN:
            if event.button == 1: amx_btn_left = True
            elif event.button == 2: amx_btn_middle = True
            elif event.button == 3: amx_btn_right = True
        elif event.type == pygame.MOUSEBUTTONUP:
            if event.button == 1: amx_btn_left = False
            elif event.button == 2: amx_btn_middle = False
            elif event.button == 3: amx_btn_right = False
    elif pygame.get_init() and pygame.mouse.get_focused():
        try:
            pressed = pygame.mouse.get_pressed()
            amx_btn_left = bool(pressed[0])
            amx_btn_middle = bool(pressed[1]) if len(pressed) > 1 else False
            amx_btn_right = bool(pressed[2]) if len(pressed) > 2 else False
        except Exception:
            pass

    if 51920 < len(memory):
        memory[51917] = 1 if amx_btn_left else 0
        memory[51918] = 1 if amx_btn_right else 0
        memory[51919] = 1 if amx_btn_middle else 0
        memory[51920] = (1 if amx_btn_left else 0) | ((1 if amx_btn_right else 0) << 1) | ((1 if amx_btn_middle else 0) << 2)

    if WIMPDesktop is not None:
        try:
            d = WIMPDesktop.get_instance()
            btn_mask = (1 if amx_btn_left else 0) | ((2 if amx_btn_right else 0)) | ((4 if amx_btn_middle else 0))
            d.mouse_btn = btn_mask
        except Exception:
            pass


def sync_amx_mouse_state():
    if pygame.get_init() and pygame.mouse.get_focused() and scale_x > 0 and scale_y > 0:
        try:
            mx, my = pygame.mouse.get_pos()
            update_amx_from_mouse((mx, my))
            update_amx_buttons()
        except Exception:
            pass


def amx_read_buttons_port():
    sync_amx_mouse_state()
    val = 0x1F
    if not amx_btn_left: val |= 0x80
    if not amx_btn_middle: val |= 0x40
    if not amx_btn_right: val |= 0x20
    return float(val)


def render_amx_pointer(target_surface, bx, by, sx, sy):
    px = bx + int(amx_x * sx)
    py = by + int((191 - amx_y) * sy)
    sc = max(1.0, sx)
    arrow_pts = [
        (px, py),
        (px, py + int(14 * sc)),
        (px + int(4 * sc), py + int(10 * sc)),
        (px + int(7 * sc), py + int(16 * sc)),
        (px + int(9 * sc), py + int(15 * sc)),
        (px + int(6 * sc), py + int(9 * sc)),
        (px + int(11 * sc), py + int(9 * sc))
    ]
    pygame.draw.polygon(target_surface, COLORS[0], arrow_pts)
    inner_pts = [
        (px + 1, py + 1),
        (px + 1, py + int(12 * sc)),
        (px + int(4 * sc), py + int(9 * sc)),
        (px + int(7 * sc), py + int(14 * sc)),
        (px + int(8 * sc), py + int(13 * sc)),
        (px + int(5 * sc), py + int(8 * sc)),
        (px + int(9 * sc), py + int(8 * sc))
    ]
    pygame.draw.polygon(target_surface, COLORS[7], inner_pts)


def handle_mousey_command(cmd_str=""):
    global current_mouse_mode, amx_enabled
    s = (cmd_str or "").strip()
    s_upper = s.upper()

    # Strip command prefix if present (e.g. "MOUSEY", "MOUSE")
    if s_upper.startswith("MOUSEY"):
        s = s[6:].strip()
    elif s_upper.startswith("MOUSE"):
        s = s[5:].strip()

    if s.startswith(":"):
        s = s[1:].strip()

    arg = s.strip().upper()
    if arg in ("/KEMP", "KEMP", "/KEMPSTON", "KEMPSTON", "/K", "K"):
        current_mouse_mode = "KEMP"
        amx_enabled = True
        canvas_print("MOUSE: KEMPSTON (Ports 64479, 65503, 64223)")
    elif arg in ("/AMX", "AMX", "/A", "A"):
        current_mouse_mode = "AMX"
        amx_enabled = True
        canvas_print("MOUSE: AMX (Port 223 / PEEK 51915-51920)")
    elif not arg or arg in ("/TOGGLE", "TOGGLE"):
        if current_mouse_mode == "KEMP":
            current_mouse_mode = "AMX"
            canvas_print("MOUSE: AMX (Port 223 / PEEK 51915-51920)")
        else:
            current_mouse_mode = "KEMP"
            canvas_print("MOUSE: KEMPSTON (Ports 64479, 65503, 64223)")
    elif arg in ("?", "/?", "HELP", "/HELP", "STATUS", "/STATUS"):
        canvas_print(f"Current Mouse: {current_mouse_mode}")
        canvas_print("Syntax: MOUSEY [/KEMP | /AMX]")
        canvas_print("  /KEMP : Kempston Mouse (Ports 64479, 65503, 64223)")
        canvas_print("  /AMX  : AMX Mouse (Port 223 / PEEK 51915-51920)")
    else:
        canvas_print(f"Unknown switch: {arg}")
        canvas_print("Syntax: MOUSEY [/KEMP | /AMX]")
    update_display()


def handle_amx_command(cmd_str, line_numbers=None):
    global amx_enabled, amx_pointer_visible, amx_x, amx_y
    cmd = cmd_str.strip()
    if cmd.startswith("*"):
        cmd = cmd[1:].strip()
    cmd_upper = cmd.upper()

    if cmd_upper.startswith("LOOP"):
        amx_enabled = True
        amx_pointer_visible = True
        waiting = True
        while waiting and running:
            pygame.event.pump()
            keys = pygame.key.get_pressed()
            if keys[pygame.K_ESCAPE] or keys[pygame.K_END]:
                raise BASICBreak()
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit()
                    sys.exit()
                elif is_break_event(event):
                    raise BASICBreak()
                elif event.type == pygame.MOUSEMOTION:
                    update_amx_from_mouse(event.pos)
                elif event.type == pygame.MOUSEBUTTONDOWN:
                    update_amx_from_mouse(event.pos)
                    update_amx_buttons(event)
                    waiting = False
                elif event.type == pygame.MOUSEBUTTONUP:
                    update_amx_from_mouse(event.pos)
                    update_amx_buttons(event)
                elif event.type == pygame.KEYDOWN:
                    waiting = False
            sync_amx_mouse_state()
            update_display()
            pygame.time.delay(10)
    elif cmd_upper.startswith("SHOWPOINTER") or cmd_upper.startswith("SHOWP.") or cmd_upper.startswith("SHOW"):
        amx_pointer_visible = True
        try:
            pygame.mouse.set_visible(False)
        except Exception:
            pass
        update_display()
    elif cmd_upper.startswith("HIDEPOINTER") or cmd_upper.startswith("HIDEP.") or cmd_upper.startswith("HIDE"):
        amx_pointer_visible = False
        try:
            pygame.mouse.set_visible(True)
        except Exception:
            pass
        update_display()
    elif cmd_upper.startswith("POINTER"):
        amx_enabled = True
        args = split_top_level_commas(cmd[7:].strip())
        if len(args) == 2:
            amx_x = max(0, min(255, int(evaluate_expr(args[0]))))
            amx_y = max(0, min(191, int(evaluate_expr(args[1]))))
            if 51920 < len(memory):
                memory[51915] = amx_x & 0xFF
                memory[51916] = amx_y & 0xFF
            update_display()
    elif cmd_upper.startswith("DESK") or cmd_upper.startswith("WINDOW") or cmd_upper.startswith("ICON"):
        amx_enabled = True


# ==============================================================================
# Fuller Master Unit (AY-3-8912 Sound & Orator SP0256-AL2 Speech Emulation)
# ==============================================================================

class FullerAYChip:
    def __init__(self, mode="SINCLAIR", sample_rate=44100):
        self.sample_rate = sample_rate
        self.regs = [0] * 16
        self.selected_reg = 0
        self.mode = mode.upper()  # "SINCLAIR" (1.773448 MHz) or "FULLER" (1.750000 MHz)
        self.stereo_mode = "ACB" if self.mode == "SINCLAIR" else "MONO"  # "MONO", "ABC", "ACB"

        # Channel phases
        self.channel_a_phase = 0.0
        self.channel_b_phase = 0.0
        self.channel_c_phase = 0.0

        # Noise generator (17-bit LFSR)
        self.noise_lfsr = 0x10000
        self.noise_phase = 0.0

        # Hardware envelope generator
        self.env_phase = 0.0
        self.env_step = 0
        self.env_holding = False

        # DC blocking filter state (AC coupling)
        self.dc_prev_x_l = 0.0
        self.dc_prev_y_l = 0.0
        self.dc_prev_x_r = 0.0
        self.dc_prev_y_r = 0.0

        self.lock = threading.Lock()
        self.running = True
        self._wake_event = threading.Event()
        self.sound_channel = None
        self._active_sounds = collections.deque(maxlen=8)

        # Standard General Instrument AY-3-8910 16-level logarithmic DAC curve (normalized to 1.0)
        self.vol_table = [
            0.0,     0.0050,  0.0072,  0.0105,
            0.0154,  0.0228,  0.0322,  0.0476,
            0.0691,  0.1039,  0.1500,  0.2232,
            0.3237,  0.4694,  0.6871,  1.0
        ]

        try:
            if pygame.mixer.get_init():
                if pygame.mixer.get_num_channels() < 8:
                    pygame.mixer.set_num_channels(8)
                self.sound_channel = pygame.mixer.Channel(1)
        except Exception:
            self.sound_channel = None

        self.thread = threading.Thread(target=self._audio_stream_loop, daemon=True)
        self.thread.start()

    def set_mode(self, mode):
        with self.lock:
            self.mode = mode.upper()
            if self.mode == "FULLER":
                self.stereo_mode = "MONO"
            elif self.mode == "SINCLAIR" and self.stereo_mode == "MONO":
                self.stereo_mode = "ACB"

    def set_stereo(self, st_mode):
        with self.lock:
            st = st_mode.upper()
            if st in ("MONO", "ABC", "ACB"):
                self.stereo_mode = st

    def get_clock(self):
        # Spectrum 128K = 3.54690 MHz / 2 = 1773447.5 Hz
        # Fuller Box = 3.50000 MHz / 2 = 1750000.0 Hz
        return 1750000.0 if self.mode == "FULLER" else 1773447.5

    def write_address(self, reg):
        with self.lock:
            self.selected_reg = int(reg) & 0x0F

    def write_data(self, val):
        with self.lock:
            reg = self.selected_reg
            v = int(val) & 0xFF
            self.regs[reg] = v
            # Writing to R13 resets envelope counter & state
            if reg == 13:
                self.env_step = 0
                self.env_phase = 0.0
                self.env_holding = False
            self._wake_event.set()

    def read_data(self):
        with self.lock:
            return self.regs[self.selected_reg]

    def reset(self):
        with self.lock:
            self.regs = [0] * 16
            self.selected_reg = 0
            self.channel_a_phase = 0.0
            self.channel_b_phase = 0.0
            self.channel_c_phase = 0.0
            self.noise_phase = 0.0
            self.noise_lfsr = 0x10000
            self.env_phase = 0.0
            self.env_step = 0
            self.env_holding = False
            self.dc_prev_x_l = 0.0
            self.dc_prev_y_l = 0.0
            self.dc_prev_x_r = 0.0
            self.dc_prev_y_r = 0.0
        self._wake_event.set()

    def _eval_envelope_step(self, shape, step):
        continue_flag  = (shape & 0x08) != 0
        attack_flag    = (shape & 0x04) != 0
        alternate_flag = (shape & 0x02) != 0
        hold_flag      = (shape & 0x01) != 0

        if not continue_flag:
            # Shapes 0..7: Single cycle, then 0 forever
            if step < 16:
                return step if attack_flag else (15 - step)
            else:
                return 0

        # Shapes 8..15 (Continue is True)
        cycle = step // 16
        pos = step % 16

        if hold_flag:
            if cycle == 0:
                return pos if attack_flag else (15 - pos)
            else:
                if alternate_flag:
                    return (15 - (15 if attack_flag else 0))
                else:
                    return 15 if attack_flag else 0
        else:
            if alternate_flag:
                is_up = attack_flag if (cycle % 2 == 0) else (not attack_flag)
                return pos if is_up else (15 - pos)
            else:
                return pos if attack_flag else (15 - pos)

    def _audio_stream_loop(self):
        while self.running:
            mix = None
            try:
                mix = pygame.mixer.get_init()
            except Exception:
                mix = None
            if not mix:
                time.sleep(0.05)
                continue
            mix_rate, mix_format, mix_channels = mix

            if not self.sound_channel:
                try:
                    if pygame.mixer.get_num_channels() < 8:
                        pygame.mixer.set_num_channels(8)
                    self.sound_channel = pygame.mixer.Channel(1)
                except Exception:
                    self.sound_channel = None
                if not self.sound_channel:
                    time.sleep(0.05)
                    continue

            with self.lock:
                r0, r1 = self.regs[0], self.regs[1] & 0x0F
                r2, r3 = self.regs[2], self.regs[3] & 0x0F
                r4, r5 = self.regs[4], self.regs[5] & 0x0F
                r6 = self.regs[6] & 0x1F
                r7 = self.regs[7]
                r8 = self.regs[8] & 0x1F
                r9 = self.regs[9] & 0x1F
                r10 = self.regs[10] & 0x1F
                r11 = self.regs[11]
                r12 = self.regs[12]
                r13 = self.regs[13] & 0x0F
                stereo = self.stereo_mode
                clock = self.get_clock()

            per_a = (r1 << 8) | r0
            per_b = (r3 << 8) | r2
            per_c = (r5 << 8) | r4
            per_env = (r12 << 8) | r11
            if per_env == 0: per_env = 1

            freq_a = (clock / (32.0 * (per_a if per_a > 0 else 1)))
            freq_b = (clock / (32.0 * (per_b if per_b > 0 else 1)))
            freq_c = (clock / (32.0 * (per_c if per_c > 0 else 1)))

            tone_a_en = (r7 & 0x01) == 0
            tone_b_en = (r7 & 0x02) == 0
            tone_c_en = (r7 & 0x04) == 0

            noise_a_en = (r7 & 0x08) == 0
            noise_b_en = (r7 & 0x10) == 0
            noise_c_en = (r7 & 0x20) == 0

            env_a_en = (r8 & 0x10) != 0
            env_b_en = (r9 & 0x10) != 0
            env_c_en = (r10 & 0x10) != 0
            any_env = env_a_en or env_b_en or env_c_en

            is_active = (
                (r8 & 0x0F) > 0 or (r9 & 0x0F) > 0 or (r10 & 0x0F) > 0 or any_env
            )

            if not is_active:
                if self.sound_channel and not self.sound_channel.get_busy():
                    self._wake_event.wait(timeout=0.1)
                    self._wake_event.clear()
                    continue

            # Zero-drop flow control: wait until queue is ready to accept next chunk
            if self.sound_channel and self.sound_channel.get_busy() and self.sound_channel.get_queue() is not None:
                time.sleep(0.002)
                continue

            # 20ms chunk (882 frames at 44.1kHz) aligns tightly with 50Hz frame timing
            chunk_frames = int(mix_rate * 0.020)
            dt = 1.0 / mix_rate
            total_samples = chunk_frames * mix_channels
            buf = array.array('h', [0] * total_samples)

            phase_a = self.channel_a_phase
            phase_b = self.channel_b_phase
            phase_c = self.channel_c_phase
            n_phase = self.noise_phase
            lfsr = self.noise_lfsr
            if lfsr == 0: lfsr = 0x10000
            e_phase = self.env_phase
            e_step = self.env_step

            # Filter state (DC blocking high-pass filter)
            px_l = self.dc_prev_x_l
            py_l = self.dc_prev_y_l
            px_r = self.dc_prev_x_r
            py_r = self.dc_prev_y_r
            R = 0.995

            env_step_rate = (clock / (16.0 * per_env)) if any_env else 0.0
            noise_step_rate = (clock / (16.0 * (r6 if r6 > 0 else 1))) if (noise_a_en or noise_b_en or noise_c_en) else 0.0

            for i in range(chunk_frames):
                # 1. Hardware Envelope Generator Step
                if env_step_rate > 0:
                    e_phase += env_step_rate * dt
                    if e_phase >= 1.0:
                        adv = int(e_phase)
                        e_phase -= adv
                        e_step += adv

                cur_env_vol = self.vol_table[self._eval_envelope_step(r13, e_step)]
                vol_a = cur_env_vol if env_a_en else self.vol_table[r8 & 0x0F]
                vol_b = cur_env_vol if env_b_en else self.vol_table[r9 & 0x0F]
                vol_c = cur_env_vol if env_c_en else self.vol_table[r10 & 0x0F]

                # 2. Authentic 17-Bit Fibonacci LFSR Noise Generator Step
                noise_bit = lfsr & 1
                if noise_step_rate > 0:
                    n_phase += noise_step_rate * dt
                    while n_phase >= 1.0:
                        n_phase -= 1.0
                        b0 = lfsr & 1
                        b3 = (lfsr >> 3) & 1
                        lfsr = ((lfsr >> 1) | ((b0 ^ b3) << 16)) & 0x1FFFF
                        if lfsr == 0: lfsr = 0x10000

                # 3. Channel Tone Generators (50% square wave with ultrasonic anti-aliasing)
                if tone_a_en:
                    if freq_a > 20000.0:
                        bit_tone_a = 1
                    else:
                        bit_tone_a = 1 if phase_a < 0.5 else 0
                        phase_a = (phase_a + freq_a * dt) % 1.0
                else:
                    bit_tone_a = 1

                if tone_b_en:
                    if freq_b > 20000.0:
                        bit_tone_b = 1
                    else:
                        bit_tone_b = 1 if phase_b < 0.5 else 0
                        phase_b = (phase_b + freq_b * dt) % 1.0
                else:
                    bit_tone_b = 1

                if tone_c_en:
                    if freq_c > 20000.0:
                        bit_tone_c = 1
                    else:
                        bit_tone_c = 1 if phase_c < 0.5 else 0
                        phase_c = (phase_c + freq_c * dt) % 1.0
                else:
                    bit_tone_c = 1

                # 4. Wire-AND Mixing & DC Sample Output
                bit_noise_a = noise_bit if noise_a_en else 1
                bit_noise_b = noise_bit if noise_b_en else 1
                bit_noise_c = noise_bit if noise_c_en else 1

                sig_a = vol_a if (bit_tone_a & bit_noise_a) else 0.0
                sig_b = vol_b if (bit_tone_b & bit_noise_b) else 0.0
                sig_c = vol_c if (bit_tone_c & bit_noise_c) else 0.0

                # 5. Panning & Output Scaling
                if mix_channels == 2:
                    if stereo == "ACB":
                        raw_l = sig_a + 0.5 * sig_c
                        raw_r = sig_b + 0.5 * sig_c
                    elif stereo == "ABC":
                        raw_l = sig_a + 0.5 * sig_b
                        raw_r = sig_c + 0.5 * sig_b
                    else:  # MONO
                        m_val = (sig_a + sig_b + sig_c) * 0.5
                        raw_l = m_val
                        raw_r = m_val

                    # AC coupling DC blocking filter
                    fl = raw_l - px_l + R * py_l
                    px_l, py_l = raw_l, fl
                    fr = raw_r - px_r + R * py_r
                    px_r, py_r = raw_r, fr

                    buf[i * 2] = int(max(-32767, min(32767, fl * 14000)))
                    buf[i * 2 + 1] = int(max(-32767, min(32767, fr * 14000)))
                else:
                    m_val = (sig_a + sig_b + sig_c) * 0.5
                    fm = m_val - px_l + R * py_l
                    px_l, py_l = m_val, fm
                    buf[i] = int(max(-32767, min(32767, fm * 14000)))

            self.channel_a_phase = phase_a
            self.channel_b_phase = phase_b
            self.channel_c_phase = phase_c
            self.noise_phase = n_phase
            self.noise_lfsr = lfsr
            self.env_phase = e_phase
            self.env_step = e_step
            self.dc_prev_x_l = px_l
            self.dc_prev_y_l = py_l
            self.dc_prev_x_r = px_r
            self.dc_prev_y_r = py_r

            try:
                sound = pygame.mixer.Sound(buffer=buf.tobytes())
                self._active_sounds.append(sound)
                if not self.sound_channel.get_busy():
                    self.sound_channel.play(sound)
                elif self.sound_channel.get_queue() is None:
                    try:
                        self.sound_channel.queue(sound)
                    except Exception:
                        pass
            except Exception:
                time.sleep(0.002)

fuller_ay_chip = FullerAYChip()

def _cleanup_fuller_ay():
    global fuller_ay_chip
    if fuller_ay_chip is not None:
        try:
            fuller_ay_chip.running = False
            if hasattr(fuller_ay_chip, 'thread') and fuller_ay_chip.thread.is_alive():
                fuller_ay_chip.thread.join(timeout=0.2)
        except Exception:
            pass

import atexit
atexit.register(_cleanup_fuller_ay)

# ==============================================================================
# Sinclair ZX Spectrum 128K & +3 Architecture, AY Sound & Memory Banking Subsystem
# ==============================================================================

current_ay_mode = "SINCLAIR"   # "SINCLAIR" (Ports 65533, 49149) or "FULLER" (Ports 63, 95)
current_sprite_mode = "ZX"     # "ZX" (48K monochrome machine-code engine) or "NEXT" (hardware Next sprites)
spectrum_mode = "128K_PLUS3"   # "48K" or "128K_PLUS3"
spectrum_128k_mode = True       # True for 128K BASIC mode, False for 48K mode
plus3_mode = True               # True for ZX Spectrum +3 hardware emulation
ram_banks = [bytearray(16384) for _ in range(8)]
for _b in (5, 7):
    ram_banks[_b][6144:6912] = b'\x38' * 768
current_ram_bank = 0
current_shadow_screen = False
paging_locked = False
last_7ffd_val = 0
last_1ffd_val = 0
plus3_special_paging = False
plus3_disk_motor = False
current_rom_bank = 0
if 'ZX_PLUS3_ROM_BANKS' in globals() and len(ZX_PLUS3_ROM_BANKS) == 4:
    rom_banks = [bytearray(ZX_PLUS3_ROM_BANKS[i]) for i in range(4)]
else:
    rom_banks = [bytearray(ZX_48K_ROM) for _ in range(4)]
for _rb in rom_banks:
    _rb[15616 : 15616 + 768] = ZX_ROM_FONT
current_slot_banks = [0, 5, 2, 0]          # Physical bank mapped to 16K slots 0..3
current_slot_is_rom = [True, False, False, False] # Slot type: True=ROM, False=RAM
ram_disk = {}                   # Virtual 128K Silicon Disc storage: {filename: dict}
ay_play_active = False
ay_play_stop = False

def sync_display_to_active_screen():
    global current_shadow_screen, memory, ram_banks, current_slot_banks, current_slot_is_rom
    if 'load_screen_bytes' not in globals():
        return
    if current_shadow_screen:
        if current_slot_banks[1] == 7 and not current_slot_is_rom[1]:
            vram = memory[16384:23296]
        elif current_slot_banks[3] == 7 and not current_slot_is_rom[3]:
            vram = memory[49152:49152 + 6912]
        else:
            vram = ram_banks[7][:6912]
    else:
        if current_slot_banks[1] == 5 and not current_slot_is_rom[1]:
            vram = memory[16384:23296]
        else:
            vram = ram_banks[5][:6912]
    
    vram_bytes = bytes(vram[:6912])
    if len(vram_bytes) >= 6912 and not any(vram_bytes[6144:6912]):
        vram_ba = bytearray(vram_bytes)
        vram_ba[6144:6912] = b'\x38' * 768
        vram_bytes = bytes(vram_ba)
    load_screen_bytes(vram_bytes)

def apply_plus3_memory_paging():
    global current_ram_bank, current_rom_bank, plus3_special_paging, plus3_disk_motor
    global current_slot_banks, current_slot_is_rom, memory, ram_banks, rom_banks
    global last_1ffd_val, last_7ffd_val

    # 1. Save currently mapped RAM slots back to ram_banks
    for slot in range(4):
        start_addr = slot * 16384
        end_addr = start_addr + 16384
        if not current_slot_is_rom[slot]:
            b_num = current_slot_banks[slot]
            if 0 <= b_num < 8:
                ram_banks[b_num][:] = memory[start_addr:end_addr]

    # 2. Check special all-RAM mode
    is_special = bool(last_1ffd_val & 0x01)
    plus3_special_paging = is_special
    plus3_disk_motor = bool(last_1ffd_val & 0x08)

    if is_special:
        cfg = (last_1ffd_val >> 1) & 0x03
        if cfg == 0:
            target_banks = [0, 1, 2, 3]
        elif cfg == 1:
            target_banks = [4, 5, 6, 7]
        elif cfg == 2:
            target_banks = [4, 5, 6, 3]
        else:
            target_banks = [4, 7, 6, 3]

        for slot in range(4):
            start_addr = slot * 16384
            end_addr = start_addr + 16384
            b = target_banks[slot]
            current_slot_banks[slot] = b
            current_slot_is_rom[slot] = False
            memory[start_addr:end_addr] = ram_banks[b]
        current_ram_bank = target_banks[3]
    else:
        # Normal Mode:
        # ROM selection:
        # On standard 128K / +2: Bit 4 of 7FFD selects 128K ROM (0) or 48K ROM (1).
        # On Spectrum +3: 1FFD bit 2 is MSB, 7FFD bit 4 is LSB.
        # However, standard 128K software (e.g. Head Over Heels) only writes to port 7FFD (1FFD=0).
        # If bit 4 is set, 128K software expects the 48K BASIC ROM (rom_banks[3]), NOT
        # the +3 Syntax Checker (rom_banks[1]) which would corrupt IM 2 interrupt vectoring at 0x0000.
        if 'spectrum_128k_mode' in globals() and not spectrum_128k_mode:
            current_rom_bank = 3
        elif (last_1ffd_val & 0x04) == 0:
            current_rom_bank = 3 if (last_7ffd_val & 0x10) else 0
        else:
            rom_idx = ((last_1ffd_val & 0x04) >> 1) | ((last_7ffd_val & 0x10) >> 4)
            current_rom_bank = rom_idx & 0x03

        # Slot 0: ROM
        current_slot_banks[0] = current_rom_bank
        current_slot_is_rom[0] = True
        memory[0:16384] = rom_banks[current_rom_bank]
        memory[15616 : 15616 + 768] = ZX_ROM_FONT

        # Slot 1: RAM 5
        current_slot_banks[1] = 5
        current_slot_is_rom[1] = False
        memory[16384:32768] = ram_banks[5]

        # Slot 2: RAM 2
        current_slot_banks[2] = 2
        current_slot_is_rom[2] = False
        memory[32768:49152] = ram_banks[2]

        # Slot 3: RAM selected by 0x7FFD bits 0..2
        target_ram = last_7ffd_val & 0x07
        current_slot_banks[3] = target_ram
        current_slot_is_rom[3] = False
        current_ram_bank = target_ram
        memory[49152:65536] = ram_banks[target_ram]

    # Update system variables
    memory[23388] = last_7ffd_val & 0xFF  # BANK_M (0x5B5C)
    memory[23399] = last_1ffd_val & 0xFF  # BANK_M3 (0x5B67)

def select_ram_bank(bank_num):
    global current_ram_bank, ram_banks, memory, last_7ffd_val
    bank_num = int(bank_num) & 0x07
    last_7ffd_val = (last_7ffd_val & ~0x07) | bank_num
    if plus3_mode:
        apply_plus3_memory_paging()
    else:
        if bank_num == current_ram_bank:
            return
        ram_banks[current_ram_bank][:] = memory[49152:65536]
        current_ram_bank = bank_num
        memory[49152:65536] = ram_banks[current_ram_bank]
        memory[23388] = last_7ffd_val & 0xFF

def handle_128k_paging_out(val):
    global paging_locked, last_7ffd_val, current_shadow_screen, current_rom_bank
    if not spectrum_128k_mode or paging_locked:
        return
    val &= 0xFF
    last_7ffd_val = val
    old_shadow = current_shadow_screen
    current_shadow_screen = bool(val & 0x08)
    if plus3_mode:
        apply_plus3_memory_paging()
    else:
        new_bank = val & 0x07
        select_ram_bank(new_bank)
        if 'rom_banks' in globals() and rom_banks and len(rom_banks) == 2:
            c_rom = 1 if (val & 0x10) else 0
        else:
            c_rom = 3 if (val & 0x10) else 0
        current_rom_bank = c_rom
        if 'rom_banks' in globals() and rom_banks and len(rom_banks) > c_rom:
            memory[0:16384] = rom_banks[c_rom]
        elif (val & 0x10):
            memory[0:16384] = basic_rom_backup if ('basic_rom_backup' in globals() and basic_rom_backup) else ZX_48K_ROM
        memory[15616 : 15616 + 768] = ZX_ROM_FONT
        memory[23388] = val
    if val & 0x20:
        paging_locked = True
    if old_shadow != current_shadow_screen:
        sync_display_to_active_screen()

def handle_plus3_paging_out(val):
    global last_1ffd_val, paging_locked
    if not spectrum_128k_mode or not plus3_mode or paging_locked:
        return
    val &= 0xFF
    last_1ffd_val = val
    apply_plus3_memory_paging()

def init_48k_sysvars():
    global memory, current_border, current_paper, current_ink
    current_paper = 7
    current_ink = 0
    current_border = 7
    init_system_variables()
    memory[23730] = 0x57  # RAMTOP = 65367 (0xFF57)
    memory[23731] = 0xFF
    memory[23732] = 0xFF  # P_RAMT = 65535 (0xFFFF)
    memory[23733] = 0xFF
    memory[23675] = 0x58  # UDG = 65368 (0xFF58)
    memory[23676] = 0xFF
    memory[23606] = 0x00  # CHARS = 15360 (0x3C00)
    memory[23607] = 0x3C
    memory[23610] = 255   # ERR_NR = 255
    memory[23624] = 0x38  # BORDCR = 56
    memory[23693] = 0x38  # ATTR_P = 56
    memory[23695] = 0x38  # ATTR_T = 56
    memory[23697] = 0     # RASP
    memory[23698] = 0     # PIP
    # Interface 1 System Variables:
    # 23734 = FLAGS3 (bit 0 = 1 indicates Interface 1 is hooked)
    # 23746 = NSPAT (network station number)
    # 23753..23754 = BAUD (RS232 baud rate)
    memory[23734] = 0x01
    memory[23746] = 1
    memory[23753] = 9600 & 0xFF
    memory[23754] = (9600 >> 8) & 0xFF

