def setup_if1_and_disciple_defaults():
    global mgt_default_drive, mgt_drives, microdrive_attachments, memory
    # 1. Interface 1:
    if 'microdrive_attachments' not in globals() or not microdrive_attachments:
        microdrive_attachments = {i: f"{i}.mdr" for i in range(1, 9)}
        microdrive_attachments[8] = "wimp.mdr"

    if len(memory) > 23734:
        memory[23734] = memory[23734] | 0x01
        memory[23746] = 1
        memory[23753] = 9600 & 0xFF
        memory[23754] = (9600 >> 8) & 0xFF

    # 2. DISCiPLE Floppy Disk System:
    mgt_default_drive = 1
    folder = get_zx_folder() if 'get_zx_folder' in globals() else os.getcwd()
    launch_folder = os.getcwd()
    boot_candidates = [
        os.path.join(launch_folder, "boot.fdi"),
        os.path.join(folder, "boot.fdi"),
        os.path.join(launch_folder, "drive1.fdi"),
        os.path.join(folder, "drive1.fdi"),
    ]
    mounted = False
    for p in boot_candidates:
        if os.path.exists(p):
            try:
                mgt_drives[1] = MGTDisk(p, disk_name="DISCiPLE 1")
                mounted = True
                break
            except Exception:
                pass
    if not mounted and mgt_drives.get(1) is None:
        target_default = os.path.join(folder, "drive1.fdi")
        try:
            mgt_drives[1] = MGTDisk(target_default, disk_name="DISCiPLE 1")
        except Exception:
            try:
                mgt_drives[1] = MGTDisk("", disk_name="DISCiPLE 1")
            except Exception:
                pass

def set_zx48_mode(reset_vars=True, attach_defaults=True):
    global spectrum_mode, spectrum_128k_mode, plus3_mode, paging_locked, current_sprite_mode
    global last_7ffd_val, last_1ffd_val, plus3_special_paging, plus3_disk_motor
    global current_shadow_screen, current_ram_bank, current_rom_bank
    global current_slot_banks, current_slot_is_rom, memory, ram_banks, rom_banks
    global z80_cpu, current_paper, current_ink, current_border, active_window
    
    spectrum_mode = "48K"
    current_sprite_mode = "ZX"
    spectrum_128k_mode = False
    plus3_mode = False
    paging_locked = True
    plus3_special_paging = False
    plus3_disk_motor = False
    current_shadow_screen = False
    last_7ffd_val = 0x30  # Bit 4 (48K ROM) + Bit 5 (Paging locked)
    last_1ffd_val = 0x00
    active_window = {"x": 0, "y": 0, "w": 32, "h": 24}
    
    global layer2_active, next_layer2_mode, next_lores_mode
    layer2_active = False
    next_layer2_mode = 0
    next_lores_mode = 0
    if 'next_sprite_manager' in globals():
        next_sprite_manager.clear_all()
    
    current_slot_banks = [0, 5, 2, 0]
    current_slot_is_rom = [True, False, False, False]
    current_rom_bank = 0
    current_ram_bank = 0
    
    if 'load_rom_file' in globals():
        _rom_48 = load_rom_file("48.rom") or load_rom_file("zx48.rom")
        if _rom_48 and len(_rom_48) == 16384:
            ZX_48K_ROM = _rom_48
            basic_rom_backup = bytearray(_rom_48)

    rom_banks = [bytearray(ZX_48K_ROM)]
    for _rb in rom_banks:
        _rb[15616 : 15616 + 768] = ZX_ROM_FONT

    memory[0:16384] = basic_rom_backup if ('basic_rom_backup' in globals() and basic_rom_backup) else ZX_48K_ROM
    memory[15616 : 15616 + 768] = ZX_ROM_FONT
    
    # Ensure VRAM buffers are valid white screen (paper 7, ink 0, border 7)
    ram_banks[5][0:6144] = b'\x00' * 6144
    ram_banks[5][6144:6912] = b'\x38' * 768
    ram_banks[7][6144:6912] = b'\x38' * 768
    
    memory[16384:32768] = ram_banks[5]
    memory[32768:49152] = ram_banks[2]
    memory[49152:65536] = ram_banks[0]
    
    current_paper = 7
    current_ink = 0
    current_border = 7
    
    if reset_vars:
        init_48k_sysvars()
        
    execute_cls()
    ram_banks[5][:6912] = memory[16384:23296]
    
    if 'z80_cpu' in globals() and z80_cpu is not None:
        z80_cpu.frame_tstates = 69888
        z80_cpu.clock_hz = 3500000
        z80_cpu.plus3_mode = False
        z80_cpu.contention_enabled = True
        
    if attach_defaults:
        setup_if1_and_disciple_defaults()

    sync_display_to_active_screen()
    if 'canvas_print' in globals():
        canvas_print("* ZX SPECTRUM 48K *")
        if attach_defaults:
            canvas_print("* Interface 1 & DISCiPLE Active *")
    print("* ZX SPECTRUM 48K *")
    if 'redraw_canvas' in globals():
        redraw_canvas(force=True)
    if 'update_display' in globals():
        try:
            update_display()
        except Exception:
            pass

