def set_zxp3_mode(reset_vars=True):
    global spectrum_mode, spectrum_128k_mode, plus3_mode, paging_locked, current_sprite_mode
    global last_7ffd_val, last_1ffd_val, plus3_special_paging, plus3_disk_motor
    global current_shadow_screen, current_ram_bank, current_rom_bank
    global current_slot_banks, current_slot_is_rom, memory, ram_banks, rom_banks
    global z80_cpu, current_paper, current_ink, current_border
    
    spectrum_mode = "PLUS3"
    current_sprite_mode = "ZX"
    spectrum_128k_mode = True
    plus3_mode = True
    paging_locked = False
    plus3_special_paging = False
    plus3_disk_motor = False
    current_shadow_screen = False
    last_7ffd_val = 0x00
    last_1ffd_val = 0x00
    
    global layer2_active, next_layer2_mode, next_lores_mode
    layer2_active = False
    next_layer2_mode = 0
    next_lores_mode = 0
    if 'next_sprite_manager' in globals():
        next_sprite_manager.clear_all()
    
    current_slot_banks = [0, 5, 2, 0]
    current_slot_is_rom = [True, False, False, False]
    current_rom_bank = 0
    current_ram_bank = 0
    
    # Load 4 banks of authentic Sinclair ZX Spectrum +3 ROM (64KB total):
    # ROM 0: +3 128K Editor / Menu
    # ROM 1: +3 128K Syntax / Tape
    # ROM 2: +3DOS
    # ROM 3: 48K BASIC
    p3_loaded = False
    if 'load_rom_file' in globals():
        _p3 = load_rom_file("plus3.rom")
        if _p3 and len(_p3) == 65536:
            rom_banks = [bytearray(_p3[i * 16384 : (i + 1) * 16384]) for i in range(4)]
            p3_loaded = True
        else:
            _b0 = load_rom_file("plus3-0.rom") or load_rom_file("spectrumplus3_0.rom")
            _b1 = load_rom_file("plus3-1.rom") or load_rom_file("spectrumplus3_1.rom")
            _b2 = load_rom_file("plus3-2.rom") or load_rom_file("spectrumplus3_2.rom")
            _b3 = load_rom_file("plus3-3.rom") or load_rom_file("spectrumplus3_3.rom")
            if _b0 and _b1 and _b2 and _b3 and all(len(b) == 16384 for b in (_b0, _b1, _b2, _b3)):
                rom_banks = [bytearray(_b0), bytearray(_b1), bytearray(_b2), bytearray(_b3)]
                p3_loaded = True
    if not p3_loaded:
        if 'ZX_PLUS3_ROM_BANKS' in globals() and len(ZX_PLUS3_ROM_BANKS) == 4:
            rom_banks = [bytearray(ZX_PLUS3_ROM_BANKS[i]) for i in range(4)]
        else:
            rom_banks = [bytearray(ZX_48K_ROM) for _ in range(4)]
    for _rb in rom_banks:
        _rb[15616 : 15616 + 768] = ZX_ROM_FONT
        
    memory[0:16384] = rom_banks[0]
    memory[15616 : 15616 + 768] = ZX_ROM_FONT
    
    # Ensure VRAM buffers are valid white screen (paper 7, ink 0, border 7)
    ram_banks[5][0:6144] = b'\x00' * 6144
    ram_banks[5][6144:6912] = b'\x38' * 768
    ram_banks[7][6144:6912] = b'\x38' * 768
    
    memory[16384:32768] = ram_banks[5]
    memory[32768:49152] = ram_banks[2]
    memory[49152:65536] = ram_banks[0]
    
    current_paper = 7
    current_ink = 0
    current_border = 7
    
    if reset_vars:
        init_plus3_sysvars()
        
    memory[0:16384] = rom_banks[0]
    memory[15616 : 15616 + 768] = ZX_ROM_FONT
    
    execute_cls()
    ram_banks[5][:6912] = memory[16384:23296]
    
    if 'z80_cpu' in globals() and z80_cpu is not None:
        z80_cpu.frame_tstates = 70930
        z80_cpu.clock_hz = 3546900
        z80_cpu.plus3_mode = True
        z80_cpu.contention_enabled = True
        
    sync_display_to_active_screen()
    if 'canvas_print' in globals():
        canvas_print("* ZX SPECTRUM +3 *")
    print("* ZX SPECTRUM +3 *")
    if 'redraw_canvas' in globals():
        redraw_canvas(force=True)
    if 'update_display' in globals():
        try:
            update_display()
        except Exception:
            pass

def init_timex_sysvars():
    global memory, last_7ffd_val, current_border, current_paper, current_ink
    global timex_screen_mode, timex_hires_palette, timex_port_f4, timex_port_255
    global timex_ay_selected_reg, timex_on_err_line, timex_on_err_active
    current_paper = 7
    current_ink = 0
    current_border = 7
    init_system_variables()
    if 'rom_banks' in globals() and rom_banks and len(rom_banks) > 0:
        c_rom = current_rom_bank if 'current_rom_bank' in globals() else 0
        if c_rom < len(rom_banks):
            memory[0:16384] = rom_banks[c_rom]
    memory[15616 : 15616 + 768] = ZX_ROM_FONT
    memory[23730] = 0x57  # RAMTOP = 65367 (0xFF57)
    memory[23731] = 0xFF
    memory[23732] = 0xFF  # P_RAMT = 65535 (0xFFFF)
    memory[23733] = 0xFF
    memory[23675] = 0x58  # UDG = 65368 (0xFF58)
    memory[23676] = 0xFF
    memory[23606] = 0x00  # CHARS = 15360 (0x3C00)
    memory[23607] = 0x3C
    memory[23610] = 255   # ERR_NR = 255
    memory[23624] = 0x38  # BORDCR = 56
    memory[23693] = 0x38  # ATTR_P = 56
    memory[23695] = 0x38  # ATTR_T = 56
    memory[23697] = 0     # RASP
    memory[23698] = 0     # PIP

    # Timex TS2068 specific system variables:
    if len(memory) > 23746:
        memory[23734] = 1 if ('timex_on_err_active' in globals() and timex_on_err_active) else 0
        l_err = timex_on_err_line if 'timex_on_err_line' in globals() else 0
        memory[23736] = l_err & 0xFF
        memory[23737] = (l_err >> 8) & 0xFF
        memory[23740] = (timex_ay_selected_reg & 0x0F) if 'timex_ay_selected_reg' in globals() else 0
        memory[23741] = (timex_screen_mode & 7) if 'timex_screen_mode' in globals() else 0
        memory[23742] = (timex_hires_palette & 7) if 'timex_hires_palette' in globals() else 0
        memory[23744] = 1
        memory[23745] = (timex_port_f4 & 0xFF) if 'timex_port_f4' in globals() else 0
        memory[23746] = (timex_port_255 & 0xFF) if 'timex_port_255' in globals() else 0

def set_timex_machine_mode(reset_vars=True):
    global spectrum_mode, spectrum_128k_mode, plus3_mode, paging_locked, current_sprite_mode
    global last_7ffd_val, last_1ffd_val, plus3_special_paging, plus3_disk_motor
    global current_shadow_screen, current_ram_bank, current_rom_bank
    global current_slot_banks, current_slot_is_rom, memory, ram_banks, rom_banks
    global z80_cpu, current_paper, current_ink, current_border
    global timex_screen_mode, timex_hires_palette, timex_port_f4, timex_dock_bank_select
    global timex_timer_interrupt_enabled, timex_current_paged_banks

    spectrum_mode = "TS2068"
    current_sprite_mode = "ZX"
    spectrum_128k_mode = False
    plus3_mode = False
    paging_locked = True
    plus3_special_paging = False
    plus3_disk_motor = False
    current_shadow_screen = False
    last_7ffd_val = 0x00
    last_1ffd_val = 0x00
    
    global layer2_active, next_layer2_mode, next_lores_mode
    layer2_active = False
    next_layer2_mode = 0
    next_lores_mode = 0
    if 'next_sprite_manager' in globals():
        next_sprite_manager.clear_all()

    # Reset MMU to all HOME banks
    timex_port_f4 = 0x00
    timex_dock_bank_select = 0
    timex_timer_interrupt_enabled = True
    timex_current_paged_banks = [0] * 8

    # Set Timex screen mode 0 default
    set_timex_mode(0, 0)

    # 24K TS2068 ROM if available, or fallback to 48K ROM with Timex font
    if 'load_rom_file' in globals():
        _r_ts = load_rom_file("ts2068.rom") or load_rom_file("tc2068.rom") or load_rom_file("2068.rom")
        if _r_ts and len(_r_ts) >= 16384:
            rom_banks = [bytearray(_r_ts[:16384])]
            if len(_r_ts) >= 24576:
                timex_exrom_memory[0:8192] = _r_ts[16384:24576]
        else:
            rom_banks = [bytearray(ZX_48K_ROM)]
    else:
        rom_banks = [bytearray(ZX_48K_ROM)]

    for _rb in rom_banks:
        _rb[15616 : 15616 + 768] = ZX_ROM_FONT

    memory[0:16384] = rom_banks[0]
    memory[15616 : 15616 + 768] = ZX_ROM_FONT

    # Ensure VRAM buffers are valid white screen (paper 7, ink 0, border 7)
    ram_banks[5][0:6144] = b'\x00' * 6144
    ram_banks[5][6144:6912] = b'\x38' * 768
    ram_banks[7][6144:6912] = b'\x38' * 768

    memory[16384:32768] = ram_banks[5]
    memory[32768:49152] = ram_banks[2]
    memory[49152:65536] = ram_banks[0]

    current_paper = 7
    current_ink = 0
    current_border = 7

    if reset_vars:
        init_timex_sysvars()

    execute_cls()
    ram_banks[5][:6912] = memory[16384:23296]

    # Z80 CPU configuration for Timex Sinclair 2068:
    # 3.528 MHz clock, 70560 t-states per frame
    if 'z80_cpu' in globals() and z80_cpu is not None:
        z80_cpu.frame_tstates = 70560
        z80_cpu.clock_hz = 3528000
        z80_cpu.plus3_mode = False
        z80_cpu.contention_enabled = True

    sync_display_to_active_screen()
    if 'canvas_print' in globals():
        canvas_print("* TIMEX SINCLAIR 2068 *")
    print("* TIMEX SINCLAIR 2068 *")
    if 'redraw_canvas' in globals():
        redraw_canvas(force=True)
    if 'update_display' in globals():
        try:
            update_display()
        except Exception:
            pass

def handle_timex_command(cmd_str=""):
    s = (cmd_str or "").strip()
    s_upper = s.upper()
    if s_upper.startswith("TIMEX"):
        s = s[5:].strip()
    elif s_upper.startswith("TS2068"):
        s = s[6:].strip()
    elif s_upper.startswith("TC2068"):
        s = s[6:].strip()
    set_timex_machine_mode()

# =========================================================================
# TIMEX SINCLAIR 2068 "SILVER SONIC" SOUND SYSTEM
# =========================================================================

silver_sonic_tempo = 120
silver_sonic_pitch = 0
silver_sonic_active_voice = 1
silver_sonic_envelope_shape = 0
silver_sonic_envelope_period = 1000

def handle_sonic_command(cmd_str="", is_ssound=False):
    global silver_sonic_active_voice, silver_sonic_tempo, silver_sonic_pitch
    s = (cmd_str or "").strip()
    s_upper = s.upper()
    if s_upper.startswith("SONIC"):
        s = s[5:].strip()
    elif s_upper.startswith("SSOUND"):
        s = s[6:].strip()
        is_ssound = True
    if s.startswith(":"): s = s[1:].strip()
    s_clean = s.strip()
    s_upper = s_clean.upper()
    if not s_clean:
        canvas_print(f"Silver Sonic Sound: Voice={silver_sonic_active_voice}, Tempo={silver_sonic_tempo}, Pitch={silver_sonic_pitch}")
        canvas_print("Syntax: SONIC voice, pitch, duration [, volume] or SONIC PLAY \"...\"")
        return
    if s_upper.startswith("PLAY"):
        tune = s_clean[4:].strip()
        handle_splay_command("SPLAY " + tune)
        return
    if s_upper in ("OFF", "STOP", "RESET"):
        for ch in range(3):
            fuller_ay_chip.write_address(8 + ch)
            fuller_ay_chip.write_data(0)
        return
    tokens = split_top_level_commas(s_clean) if 'split_top_level_commas' in globals() else [p.strip() for p in s_clean.split(',')]
    try:
        if len(tokens) >= 3:
            voice = int(evaluate_expr(tokens[0]))
            pitch = int(evaluate_expr(tokens[1]))
            dur = float(evaluate_expr(tokens[2]))
            vol = int(evaluate_expr(tokens[3])) if len(tokens) > 3 else 15
        elif len(tokens) == 2:
            voice = silver_sonic_active_voice
            pitch = int(evaluate_expr(tokens[0]))
            dur = float(evaluate_expr(tokens[1]))
            vol = 15
        else:
            canvas_print("Syntax: SONIC voice, pitch, duration [, volume]")
            return
        if voice == 0:
            ch_idx = 1 if is_ssound else 0
        else:
            voice = max(1, min(3, voice))
            ch_idx = voice - 1
        vol = max(0, min(15, vol))
        clk = fuller_ay_chip.get_clock()
        if abs(pitch) <= 48:
            freq = 440.0 * (2.0 ** ((pitch + silver_sonic_pitch) / 12.0))
        elif 48 < pitch <= 20000:
            freq = float(pitch) * (2.0 ** (silver_sonic_pitch / 12.0))
        else:
            freq = 440.0
        period = int(round(clk / (32.0 * max(1.0, freq)))) & 0x0FFF
        if period == 0:
            period = 1
        fuller_ay_chip.write_address(ch_idx * 2)
        fuller_ay_chip.write_data(period & 0xFF)
        fuller_ay_chip.write_address(ch_idx * 2 + 1)
        fuller_ay_chip.write_data((period >> 8) & 0x0F)
        fuller_ay_chip.write_address(7)
        r7 = fuller_ay_chip.regs[7] & ~(1 << ch_idx)
        fuller_ay_chip.write_data(r7)
        fuller_ay_chip.write_address(8 + ch_idx)
        fuller_ay_chip.write_data(vol)

        # In GUI mode with active audio mixer, play duration pause so user hears sound
        if dur > 0 and os.environ.get("SDL_AUDIODRIVER") != "dummy" and pygame.mixer.get_init():
            if dur > 5.0:
                dur_sec = dur / 50.0  # 50Hz video frames (e.g. 12 frames = 0.24s, 8 frames = 0.16s)
            else:
                dur_sec = dur * (60.0 / max(20, silver_sonic_tempo))
            dur_sec = max(0.04, min(2.0, dur_sec))
            end_t = time.perf_counter() + dur_sec
            while time.perf_counter() < end_t:
                time.sleep(min(0.005, max(0.0, end_t - time.perf_counter())))
                try:
                    for ev in pygame.event.get([pygame.QUIT, pygame.KEYDOWN]):
                        if ev.type == pygame.QUIT or (ev.type == pygame.KEYDOWN and ev.key == pygame.K_ESCAPE):
                            break
                except Exception:
                    pass
    except Exception as e:
        canvas_print(f"Error in SONIC command: {e}")

def handle_ssound_command(cmd_str=""):
    handle_sonic_command(cmd_str, is_ssound=True)

