def handle_envelope_command(cmd_str=""):
    global silver_sonic_envelope_shape, silver_sonic_envelope_period
    s = (cmd_str or "").strip()
    if s.upper().startswith("ENVELOPE"):
        s = s[8:].strip()
    if s.startswith(":"): s = s[1:].strip()
    tokens = split_top_level_commas(s) if 'split_top_level_commas' in globals() else [p.strip() for p in s.split(',')]
    try:
        shape = int(evaluate_expr(tokens[0])) if tokens else 0
        period = int(evaluate_expr(tokens[1])) if len(tokens) > 1 else 1000
        silver_sonic_envelope_shape = shape & 0x0F
        silver_sonic_envelope_period = period & 0xFFFF
        fuller_ay_chip.write_address(11)
        fuller_ay_chip.write_data(silver_sonic_envelope_period & 0xFF)
        fuller_ay_chip.write_address(12)
        fuller_ay_chip.write_data((silver_sonic_envelope_period >> 8) & 0xFF)
        fuller_ay_chip.write_address(13)
        fuller_ay_chip.write_data(silver_sonic_envelope_shape)
        canvas_print(f"Envelope Shape {silver_sonic_envelope_shape}, Period {silver_sonic_envelope_period}")
    except Exception as e:
        canvas_print(f"Error in ENVELOPE command: {e}")

def sonic_fn(arg_str=""):
    try:
        if arg_str and str(arg_str).strip():
            v = int(to_float(evaluate_expr(str(arg_str))))
            if 1 <= v <= 3:
                fuller_ay_chip.write_address(8 + (v - 1))
                return float(fuller_ay_chip.read_data())
        with fuller_ay_chip.lock:
            act = any(fuller_ay_chip.regs[8 + ch] > 0 for ch in range(3))
        return 1.0 if act else 0.0
    except Exception:
        return 0.0

def svoice_fn(arg_str=""):
    try:
        v = int(to_float(evaluate_expr(str(arg_str)))) if arg_str and str(arg_str).strip() else silver_sonic_active_voice
        v = max(1, min(3, v))
        fuller_ay_chip.write_address(8 + (v - 1))
        return float(fuller_ay_chip.read_data())
    except Exception:
        return 0.0

def spos_fn(arg_str=""):
    return float(ay_play_step if 'ay_play_step' in globals() else 0.0)

# =========================================================================
# TIMEX SINCLAIR 2068 "LKDOS" LARKEN DISK OPERATING SYSTEM
# =========================================================================

lkdos_current_drive = 1
lkdos_ramdisk_enabled = True
lkdos_ramdisk_size = 256 * 1024
lkdos_vfs = {1: {}, 2: {}, 3: {}, 4: {}}
lkdos_write_protected = {1: set(), 2: set(), 3: set(), 4: set()}

def lkdos_catalog(drive=None):
    d = drive if drive in (1, 2, 3, 4) else lkdos_current_drive
    files = lkdos_vfs.get(d, {})
    d_label = f"Drive {d}:" if d < 4 else f"Drive {d} (RAMDISK):"
    canvas_print(f"*** LKDOS {d_label} Catalog ({len(files)} files) ***")
    for name, data in sorted(files.items()):
        f_type = data.get("type", "B")
        f_size = len(data.get("bytes", b""))
        prot = "[P]" if name in lkdos_write_protected.get(d, set()) else "   "
        canvas_print(f"  {prot} {name:<12} {f_type}  {f_size:>6} bytes")
    free_sec = lkdos_free_sectors(d)
    canvas_print(f"  Free Sectors: {free_sec}")

def lkdos_free_sectors(d=None):
    drv = d if d in (1, 2, 3, 4) else lkdos_current_drive
    used = sum(len(f.get("bytes", b"")) for f in lkdos_vfs.get(drv, {}).values())
    total_bytes = lkdos_ramdisk_size if drv == 4 else (680 * 512)
    return max(0, (total_bytes - used) // 512)

def handle_lkdos_statement(stmt_str=""):
    global lkdos_current_drive, lkdos_vfs, lkdos_write_protected, program
    s = stmt_str.strip()
    s_upper = s.upper()

    if s_upper.startswith("PRINT #4") or s_upper.startswith("PRINT#4"):
        rem = s[8:].strip() if s_upper.startswith("PRINT #4") else s[7:].strip()
        if rem.startswith(",") or rem.startswith(";"):
            rem = rem[1:].strip()
        if (rem.startswith('"') and rem.endswith('"')) or (rem.startswith("'") and rem.endswith("'")):
            rem = rem[1:-1].strip()
        handle_lkdos_statement(rem)
        return

    if s_upper.startswith("FCAT") or s_upper.startswith("FDIR") or s_upper == "CAT #4" or s_upper == "DIR #4":
        rem = s[4:].strip() if s_upper.startswith(("FCAT", "FDIR")) else ""
        try:
            drv = int(evaluate_expr(rem)) if rem else lkdos_current_drive
        except Exception:
            drv = lkdos_current_drive
        lkdos_catalog(drv)
        return

    if s_upper.startswith("DRIVE"):
        rem = s[5:].strip()
        try:
            d = int(evaluate_expr(rem))
            if 1 <= d <= 4:
                lkdos_current_drive = d
                canvas_print(f"LKDOS default drive set to {d}")
            else:
                canvas_print("Drive number must be 1 to 4")
        except Exception as e:
            canvas_print(f"Error in DRIVE: {e}")
        return

    if s_upper.startswith("FSAVE"):
        rem = s[5:].strip()
        if (rem.startswith('"') and rem.endswith('"')) or (rem.startswith("'") and rem.endswith("'")):
            rem = rem[1:-1].strip()
        if not rem:
            canvas_print("Syntax: FSAVE \"filename\"")
            return
        prog_text = "\n".join(f"{line_num} {stmt}" for line_num, stmt in sorted(program.items()))
        lkdos_vfs[lkdos_current_drive][rem.upper()] = {
            "type": "B",
            "bytes": prog_text.encode("utf-8")
        }
        canvas_print(f"Saved {rem.upper()} to Drive {lkdos_current_drive}")
        return

    if s_upper.startswith("FLOAD"):
        rem = s[5:].strip()
        if (rem.startswith('"') and rem.endswith('"')) or (rem.startswith("'") and rem.endswith("'")):
            rem = rem[1:-1].strip()
        if not rem:
            canvas_print("Syntax: FLOAD \"filename\"")
            return
        fname = rem.upper()
        if fname in lkdos_vfs[lkdos_current_drive]:
            data = lkdos_vfs[lkdos_current_drive][fname]["bytes"].decode("utf-8", errors="ignore")
            program.clear()
            for line in data.splitlines():
                line = line.strip()
                m = re.match(r"^(\d+)\s*(.*)", line)
                if m:
                    program[int(m.group(1))] = m.group(2)
            canvas_print(f"Loaded {fname} from Drive {lkdos_current_drive}")
        else:
            canvas_print(f"File not found: {fname} on Drive {lkdos_current_drive}")
        return

    if s_upper.startswith("FVERIFY"):
        rem = s[7:].strip().strip('"').strip("'").upper()
        if rem in lkdos_vfs[lkdos_current_drive]:
            canvas_print(f"Verified {rem} OK on Drive {lkdos_current_drive}")
        else:
            canvas_print(f"Verify failed: {rem} not found")
        return

    if s_upper.startswith("FERASE") or s_upper.startswith("FDELETE"):
        rem = s[6:].strip() if s_upper.startswith("FERASE") else s[7:].strip()
        fname = rem.strip('"').strip("'").upper()
        if fname in lkdos_write_protected.get(lkdos_current_drive, set()):
            canvas_print(f"Cannot erase write-protected file: {fname}")
            return
        if fname in lkdos_vfs[lkdos_current_drive]:
            del lkdos_vfs[lkdos_current_drive][fname]
            canvas_print(f"Erased {fname} from Drive {lkdos_current_drive}")
        else:
            canvas_print(f"File not found: {fname}")
        return

    if s_upper.startswith("FRENAME") or s_upper.startswith("FREN"):
        rem = s[7:].strip() if s_upper.startswith("FRENAME") else s[4:].strip()
        parts = [p.strip().strip('"').strip("'").upper() for p in rem.split(',') if p.strip()]
        if len(parts) == 2:
            old_n, new_n = parts
            if old_n in lkdos_vfs[lkdos_current_drive]:
                lkdos_vfs[lkdos_current_drive][new_n] = lkdos_vfs[lkdos_current_drive].pop(old_n)
                canvas_print(f"Renamed {old_n} to {new_n}")
            else:
                canvas_print(f"File not found: {old_n}")
        else:
            canvas_print("Syntax: FRENAME \"old\", \"new\"")
        return

    if s_upper.startswith("DINIT") or s_upper.startswith("FORMAT"):
        rem = s[5:].strip() if s_upper.startswith("DINIT") else s[6:].strip()
        try:
            drv = int(evaluate_expr(rem)) if rem else lkdos_current_drive
        except Exception:
            drv = lkdos_current_drive
        if 1 <= drv <= 4:
            lkdos_vfs[drv].clear()
            lkdos_write_protected[drv].clear()
            canvas_print(f"Drive {drv} initialized.")
        return

    if s_upper.startswith("RAMDISK"):
        canvas_print("LKDOS RAMDISK: Drive 4 enabled (256 KB)")
        return

    if s_upper.startswith("FPROTECT"):
        fname = s[8:].strip().strip('"').strip("'").upper()
        lkdos_write_protected[lkdos_current_drive].add(fname)
        canvas_print(f"Protected {fname} on Drive {lkdos_current_drive}")
        return

    if s_upper.startswith("FUNPROTECT"):
        fname = s[10:].strip().strip('"').strip("'").upper()
        lkdos_write_protected[lkdos_current_drive].discard(fname)
        canvas_print(f"Unprotected {fname} on Drive {lkdos_current_drive}")
        return

    if s_upper.startswith("FEXEC"):
        rem = s[5:].strip()
        handle_lkdos_statement("FLOAD " + rem)
        execute_statement("RUN")
        return

def fpeek_fn(arg_str=""):
    try:
        addr = int(to_float(evaluate_expr(str(arg_str)))) & 0xFFFF
        return float(memory[addr])
    except Exception:
        return 0.0

def fstat_fn(arg_str=""):
    try:
        d = int(to_float(evaluate_expr(str(arg_str)))) if arg_str and str(arg_str).strip() else lkdos_current_drive
        return float(lkdos_free_sectors(d))
    except Exception:
        return float(lkdos_free_sectors(1))

