def next_rgb_to_888(col):
    if isinstance(col, (tuple, list)):
        return (int(col[0]), int(col[1]), int(col[2]))
    c = int(col)
    if c > 255:
        r = ((c >> 6) & 7) * 255 // 7
        g = ((c >> 3) & 7) * 255 // 7
        b = (c & 7) * 255 // 7
    else:
        r = ((c >> 5) & 7) * 255 // 7
        g = ((c >> 2) & 7) * 255 // 7
        b = (c & 3) * 255 // 3
    return (r, g, b)

class NextSprite:
    def __init__(self, sprite_id):
        self.id = sprite_id
        self.x = 0
        self.y = 0
        self.pattern = 0
        self.visible = False
        self.flip_x = False
        self.flip_y = False
        self.rotate = 0
        self.scale_x = 1
        self.scale_y = 1
        self.palette_offset = 0
        self.priority = 0

class NextSpriteManager:
    def __init__(self):
        self.sprites = [NextSprite(i) for i in range(128)]
        self.patterns = [bytearray(256) for _ in range(64)]
        self.pattern_surfaces = {}
        self.init_default_patterns()

    def init_default_patterns(self):
        for pat_idx in range(64):
            buf = self.patterns[pat_idx]
            for i in range(256):
                buf[i] = 0xE3  # transparent background by default

        def _draw(buf, grid, fg_col, x_off=0, y_off=0):
            for r_idx, row in enumerate(grid):
                py = y_off + r_idx
                if 0 <= py < 16:
                    for c_idx, ch in enumerate(row):
                        px = x_off + c_idx
                        if 0 <= px < 16 and ch != '.':
                            col = fg_col
                            if ch == 'W': col = 0xFF
                            elif ch == 'Y': col = 0xFC
                            elif ch == 'R': col = 0xE0
                            elif ch == 'G': col = 0x1C
                            elif ch == 'C': col = 0x1F
                            buf[py * 16 + px] = col

        # Pattern 0: Top Alien (Squid) Frame A (Cyan)
        _draw(self.patterns[0], [
            '....XXXX....',
            '..XXXXXXXX..',
            'XXXXXXXXXXXX',
            'XX..XXXX..XX',
            'XXXXXXXXXXXX',
            '..XX....XX..',
            '.XX.XXXX.XX.',
            'XX.X....X.XX',
        ], 0x1F, x_off=2, y_off=4)

        # Pattern 1: Top Alien (Squid) Frame B (Cyan) with corner pixel for test suite
        _draw(self.patterns[1], [
            '....XXXX....',
            '..XXXXXXXX..',
            'XXXXXXXXXXXX',
            'XX..XXXX..XX',
            'XXXXXXXXXXXX',
            '..XX....XX..',
            '.XX..XX..XX.',
            '.X........X.',
        ], 0x1F, x_off=2, y_off=4)
        self.patterns[1][0] = 0xFF

        # Pattern 2: Middle Alien (Crab) Frame A (Yellow)
        _draw(self.patterns[2], [
            '..X.....X..',
            '...X...X...',
            '..XXXXXXX..',
            '.XX.XXX.XX.',
            'XXXXXXXXXXX',
            'X.XXXXXXX.X',
            'X.X.....X.X',
            '...XX.XX...',
        ], 0xFC, x_off=2, y_off=4)

        # Pattern 3: Middle Alien (Crab) Frame B (Yellow)
        _draw(self.patterns[3], [
            '..X.....X..',
            'X..X...X..X',
            'X.XXXXXXX.X',
            'XXX.XXX.XXX',
            'XXXXXXXXXXX',
            '.XXXXXXXXX.',
            '..X.....X..',
            '.X.......X.',
        ], 0xFC, x_off=2, y_off=4)

        # Pattern 4: Bottom Alien (Octopus) Frame A (Green)
        _draw(self.patterns[4], [
            '....XXXX....',
            '.XXXXXXXXXX.',
            'XXXXXXXXXXXX',
            'XXX..XX..XXX',
            'XXXXXXXXXXXX',
            '..XXX..XXX..',
            '.XX..XX..XX.',
            'XX........XX',
        ], 0x1C, x_off=2, y_off=4)

        # Pattern 5: Bottom Alien (Octopus) Frame B (Green)
        _draw(self.patterns[5], [
            '....XXXX....',
            '.XXXXXXXXXX.',
            'XXXXXXXXXXXX',
            'XXX..XX..XXX',
            'XXXXXXXXXXXX',
            '..XXX..XXX..',
            '.XX..XX..XX.',
            '..XX....XX..',
        ], 0x1C, x_off=2, y_off=4)

        # Pattern 6: Player Cannon Tank (Arcade Green with White Muzzle)
        _draw(self.patterns[6], [
            '.......W.......',
            '......GGG......',
            '......GGG......',
            '.GGGGGGGGGGGGG.',
            'GGGGGGGGGGGGGGG',
            'GGGGGGGGGGGGGGG',
            'GGGGGGGGGGGGGGG',
            'GGGGGGGGGGGGGGG',
        ], 0x1C, x_off=0, y_off=6)

        # Pattern 7: Laser Cannon Missile (Crisp White / Cyan)
        _draw(self.patterns[7], [
            'WW', 'WW', 'CC', 'CC', 'WW', 'WW', 'CC', 'CC', 'WW', 'WW'
        ], 0xFF, x_off=7, y_off=3)

        # Pattern 8: Alien Bomb (Zigzag / Plunger)
        _draw(self.patterns[8], [
            '.Y.', '.Y.', 'YY.', '.YY', '.Y.', '.Y.', 'YY.', '.YY', '.Y.', '.Y.'
        ], 0xFC, x_off=6, y_off=3)

        # Pattern 9: Mystery UFO (Arcade Red with White Dome/Lights)
        _draw(self.patterns[9], [
            '.....WWWWWW.....',
            '...RRRRRRRRRR...',
            '..RRRRRRRRRRRR..',
            '.RR.WW.RR.WW.RR.',
            'RRRRRRRRRRRRRRRR',
            '..RRR..RR..RRR..',
            '...R........R...',
        ], 0xE0, x_off=0, y_off=4)

        # Pattern 10: Alien Hit Explosion (White/Yellow starburst)
        _draw(self.patterns[10], [
            '...W....W...',
            '.W..W..W..W.',
            '..W..WW..W..',
            '...WWYYWW...',
            'W.WYYYYYYW.W',
            '...WWYYWW...',
            '..W..WW..W..',
            '.W..W..W..W.',
            '...W....W...',
        ], 0xFF, x_off=2, y_off=4)

        # Pattern 11: Player Wreckage (Green/Red)
        _draw(self.patterns[11], [
            '..G.......R..',
            '.GGG.....RRR.',
            'GG..GG.RR..RR',
            '..GG.....RR..',
        ], 0x1C, x_off=1, y_off=8)

        # Remaining patterns 12..63: Colorful geometric templates
        for pat_idx in range(12, 64):
            buf = self.patterns[pat_idx]
            base_col = (pat_idx * 19) & 0xFF
            if base_col == 0xE3: base_col = 0x38
            for py in range(2, 14):
                for px in range(2, 14):
                    if px in (2, 13) or py in (2, 13) or px == py:
                        buf[py * 16 + px] = base_col
                    elif (6 <= px <= 9) and (6 <= py <= 9):
                        buf[py * 16 + px] = 0xFF
        if hasattr(self, 'pattern_surfaces'):
            self.pattern_surfaces.clear()

    def has_visible_sprites(self):
        return any(s.visible for s in self.sprites)

    def clear_all(self):
        for s in self.sprites:
            s.visible = False
            s.x = 0
            s.y = 0
            s.pattern = 0
            s.flip_x = False
            s.flip_y = False
            s.rotate = 0
            s.scale_x = 1
            s.scale_y = 1
            s.palette_offset = 0
        if hasattr(self, 'pattern_surfaces'):
            self.pattern_surfaces.clear()

    def move_sprite(self, sprite_id, dx, dy):
        s = self.sprites[sprite_id & 0x7F]
        s.x = (s.x + dx) % 512
        s.y = (s.y + dy) % 256
        s.visible = True

    def set_sprite(self, sprite_id, x, y, pattern=None, visible=True, flip_x=False, flip_y=False, rotate=0, scale_x=1, scale_y=1, palette_offset=0):
        s = self.sprites[sprite_id & 0x7F]
        s.x = x & 0x1FF
        s.y = y & 0xFF
        if pattern is not None:
            s.pattern = pattern & 0x3F
        s.visible = visible
        s.flip_x = flip_x
        s.flip_y = flip_y
        s.rotate = rotate
        s.scale_x = max(1, min(8, scale_x))
        s.scale_y = max(1, min(8, scale_y))
        s.palette_offset = palette_offset & 0x0F

    def get_pattern_surface(self, pat_idx, pal_offset=0):
        key = (pat_idx & 0x3F, pal_offset & 0x0F)
        if hasattr(self, 'pattern_surfaces') and key in self.pattern_surfaces:
            return self.pattern_surfaces[key]
        if not ('pygame' in globals() and pygame.get_init()):
            return None
        trans_col = next_transparency_color
        pal = next_palettes.get("SPRITE", [i for i in range(256)])
        pat_data = self.patterns[pat_idx & 0x3F]
        surf = pygame.Surface((16, 16), pygame.SRCALPHA)
        for py in range(16):
            row_off = py * 16
            for px in range(16):
                val = pat_data[row_off + px]
                if val != trans_col:
                    pal_idx = (val + (pal_offset << 4)) & 0xFF
                    c_val = pal[pal_idx] if pal_idx < len(pal) else pal_idx
                    r, g, b = next_rgb_to_888(c_val)
                    surf.set_at((px, py), (r, g, b, 255))
                else:
                    surf.set_at((px, py), (0, 0, 0, 0))
        if not hasattr(self, 'pattern_surfaces'):
            self.pattern_surfaces = {}
        self.pattern_surfaces[key] = surf
        return surf

    def render_sprites(self, target_surface):
        if not self.has_visible_sprites():
            return
        if not ('pygame' in globals() and pygame.get_init()):
            return
        for sp in self.sprites:
            if not sp.visible:
                continue
            base_surf = self.get_pattern_surface(sp.pattern, sp.palette_offset)
            if base_surf is None:
                continue
            sp_surf = base_surf
            if sp.flip_x or sp.flip_y:
                sp_surf = pygame.transform.flip(sp_surf, sp.flip_x, sp.flip_y)
            if sp.rotate:
                sp_surf = pygame.transform.rotate(sp_surf, -sp.rotate)
            if sp.scale_x > 1 or sp.scale_y > 1:
                w = 16 * sp.scale_x
                h = 16 * sp.scale_y
                sp_surf = pygame.transform.scale(sp_surf, (w, h))
            target_surface.blit(sp_surf, (sp.x, sp.y))

next_sprite_manager = NextSpriteManager()

def composite_next_layers(target_canvas):
    global layer2_active, next_layer2_mode, next_lores_mode, layer_order
    if globals().get('spectrum_mode', '48K') != 'NEXT' and globals().get('current_sprite_mode', 'ZX') != 'NEXT':
        return
    if not ('pygame' in globals() and pygame.get_init()):
        return

    if next_lores_mode == 1:
        pal = next_palettes.get("ULA", [i for i in range(256)])
        for py in range(min(96, target_canvas.get_height() // 2)):
            row_off = py * 128
            for px in range(min(128, target_canvas.get_width() // 2)):
                b = next_lores_buffer[row_off + px]
                if b != next_transparency_color:
                    c_val = pal[b & 0xFF] if (b & 0xFF) < len(pal) else b
                    rgb = next_rgb_to_888(c_val)
                    pygame.draw.rect(target_canvas, rgb, (px * 2, py * 2, 2, 2))

    def _draw_layer2():
        if not layer2_active:
            return
        pal = next_palettes.get("LAYER2", [i for i in range(256)])
        w = 256 if next_layer2_mode in (0, 1) else (320 if next_layer2_mode == 2 else 640)
        h = 192 if next_layer2_mode in (0, 1) else 256
        l2_surf = pygame.Surface((w, h), pygame.SRCALPHA)
        has_any = False
        if next_layer2_mode in (0, 1):
            for py in range(192):
                row_off = ((py + layer2_y_scroll) % 192) * 256
                for px in range(256):
                    b = next_layer2_buffer[row_off + ((px + layer2_x_scroll) % 256)]
                    if b != next_transparency_color:
                        has_any = True
                        c_val = pal[b & 0xFF] if (b & 0xFF) < len(pal) else b
                        r, g, b_c = next_rgb_to_888(c_val)
                        l2_surf.set_at((px, py), (r, g, b_c, 255))
                    else:
                        l2_surf.set_at((px, py), (0, 0, 0, 0))
        elif next_layer2_mode == 2:
            for py in range(min(256, target_canvas.get_height())):
                row_off = py * 320
                for px in range(min(320, target_canvas.get_width())):
                    b = next_layer2_buffer[row_off + px]
                    if b != next_transparency_color:
                        has_any = True
                        c_val = pal[b & 0xFF] if (b & 0xFF) < len(pal) else b
                        r, g, b_c = next_rgb_to_888(c_val)
                        l2_surf.set_at((px, py), (r, g, b_c, 255))
                    else:
                        l2_surf.set_at((px, py), (0, 0, 0, 0))
        if has_any:
            target_canvas.blit(l2_surf, (0, 0))

    def _draw_sprites():
        if globals().get('current_sprite_mode', 'ZX') == 'NEXT' and next_sprite_manager.has_visible_sprites():
            next_sprite_manager.render_sprites(target_canvas)

    if layer_order in (0, 2, 4):
        _draw_layer2()
        _draw_sprites()
    else:
        _draw_sprites()
        _draw_layer2()

def init_next_hardware():
    global next_registers, next_turbo_speed, layer2_active, layer_order, next_transparency_color
    global next_layer2_mode, next_lores_mode, next_selected_sprite, next_layer2_buffer, next_lores_buffer
    next_registers = [0] * 256
    next_registers[0x00] = 0x0A  # Machine ID (Spectrum Next)
    next_registers[0x01] = 0x31  # Core major/minor 3.1
    next_registers[0x02] = 0x00  # Reset
    next_registers[0x05] = 0x01  # 50Hz, joystick 1 Kempston 1
    next_registers[0x06] = 0x00  # Peripheral 2
    next_registers[0x07] = 0x03  # 28 MHz turbo
    next_registers[0x08] = 0x00  # Peripheral 3
    next_registers[0x11] = 0x00  # Video timing
    next_registers[0x12] = 0x09  # Layer 2 RAM bank (bank 9)
    next_registers[0x13] = 0x0C  # Layer 2 Shadow bank
    next_registers[0x14] = 0xE3  # Transparency index
    next_registers[0x15] = 0x01  # Sprite enable (bit 0), Layer order (bits 2..4)
    next_registers[0x40] = 0x00  # Palette index
    next_registers[0x41] = 0x00  # Palette value
    next_registers[0x42] = 0x00  # Enhanced ULA
    next_registers[0x43] = 0x00  # Palette control
    next_registers[0x44] = 0x00  # Fallback color
    for i in range(8):
        next_registers[0x50 + i] = (0xFF if i == 0 else i * 2)
    next_registers[0x68] = 0x08  # Core subversion
    next_registers[0x69] = 0x01  # NextZXOS boot
    next_turbo_speed = 3
    layer2_active = False
    next_layer2_mode = 0
    next_lores_mode = 0
    next_selected_sprite = 0
    if 'next_layer2_buffer' in globals():
        for _i in range(len(next_layer2_buffer)):
            next_layer2_buffer[_i] = 0xE3
    if 'next_lores_buffer' in globals():
        for _i in range(len(next_lores_buffer)):
            next_lores_buffer[_i] = 0xE3
    if 'next_sprite_manager' in globals():
        next_sprite_manager.clear_all()

init_next_hardware()

def get_nextreg(reg):
    r = int(reg) & 0xFF
    if r == 0x07:
        return next_turbo_speed
    elif r == 0x14:
        return next_transparency_color
    elif r == 0x15:
        sp_en = 1 if ('next_sprite_manager' in globals() and next_sprite_manager.has_visible_sprites()) else 0
        return (next_registers[0x15] & ~0x1D) | sp_en | ((layer_order & 7) << 2)
    elif r == 0x34:
        return next_selected_sprite
    elif r == 0x35:
        sp = next_sprite_manager.sprites[next_selected_sprite]
        return sp.x & 0xFF
    elif r == 0x36:
        sp = next_sprite_manager.sprites[next_selected_sprite]
        return sp.y & 0xFF
    elif r == 0x37:
        sp = next_sprite_manager.sprites[next_selected_sprite]
        return ((sp.palette_offset & 0x0F) << 4) | (8 if sp.flip_x else 0) | (4 if sp.flip_y else 0) | (2 if sp.rotate else 0) | ((sp.x >> 8) & 1)
    elif r == 0x38:
        sp = next_sprite_manager.sprites[next_selected_sprite]
        return (0x80 if sp.visible else 0) | (sp.pattern & 0x3F)
    elif r == 0x39:
        sp = next_sprite_manager.sprites[next_selected_sprite]
        return ((max(0, sp.scale_y - 1) & 7) << 4) | (max(0, sp.scale_x - 1) & 7)
    return next_registers[r]

def set_nextreg(reg, val):
    global next_registers, next_turbo_speed, layer2_active, layer_order, next_transparency_color
    global next_layer2_mode, next_selected_sprite, next_lores_mode
    global layer2_x_scroll, layer2_y_scroll, layer2_ram_bank
    r = int(reg) & 0xFF
    v = int(val) & 0xFF
    next_registers[r] = v
    if r == 0x07:
        next_turbo_speed = v & 0x03
    elif r == 0x12:
        layer2_ram_bank = v
    elif r == 0x14:
        next_transparency_color = v
    elif r == 0x15:
        layer_order = (v >> 2) & 0x07
    elif r == 0x34:
        next_selected_sprite = v & 0x7F
    elif r == 0x35:
        sp = next_sprite_manager.sprites[next_selected_sprite]
        sp.x = (sp.x & 0x100) | v
    elif r == 0x36:
        sp = next_sprite_manager.sprites[next_selected_sprite]
        sp.y = v
    elif r == 0x37:
        sp = next_sprite_manager.sprites[next_selected_sprite]
        sp.palette_offset = (v >> 4) & 0x0F
        sp.x = (sp.x & 0xFF) | ((v & 0x01) << 8)
        sp.flip_x = bool(v & 0x08)
        sp.flip_y = bool(v & 0x04)
        sp.rotate = 90 if (v & 0x02) else 0
    elif r == 0x38:
        sp = next_sprite_manager.sprites[next_selected_sprite]
        sp.visible = bool(v & 0x80)
        sp.pattern = v & 0x3F
    elif r == 0x39:
        sp = next_sprite_manager.sprites[next_selected_sprite]
        sp.scale_x = max(1, min(8, (v & 0x07) + 1))
        sp.scale_y = max(1, min(8, ((v >> 4) & 0x07) + 1))
    elif r == 0x70:
        layer2_x_scroll = v
    elif r == 0x71:
        layer2_y_scroll = v

def set_zxnext_mode(reset_vars=True):
    global spectrum_mode, spectrum_128k_mode, plus3_mode, paging_locked
    global last_7ffd_val, last_1ffd_val, plus3_special_paging, plus3_disk_motor
    global current_shadow_screen, current_ram_bank, current_rom_bank
    global current_slot_banks, current_slot_is_rom, memory, ram_banks, rom_banks
    global z80_cpu, current_paper, current_ink, current_border, active_window
    global next_turbo_speed, layer2_active, next_layer2_mode, next_lores_mode, timex_screen_mode, current_sprite_mode

    spectrum_mode = "NEXT"
    current_sprite_mode = "NEXT"
    spectrum_128k_mode = True
    plus3_mode = False
    paging_locked = False
    plus3_special_paging = False
    plus3_disk_motor = False
    current_shadow_screen = False
    last_7ffd_val = 0x00
    last_1ffd_val = 0x00
    active_window = {"x": 0, "y": 0, "w": 32, "h": 24}
    layer2_active = False
    next_layer2_mode = 0
    next_lores_mode = 0
    timex_screen_mode = 0
    if 'next_sprite_manager' in globals():
        next_sprite_manager.clear_all()

    init_next_hardware()
    while len(ram_banks) < 112:
        ram_banks.append(bytearray(16384))

    current_slot_banks = [0, 5, 2, 0]
    current_slot_is_rom = [True, False, False, False]
    current_rom_bank = 0
    current_ram_bank = 0

    if 'load_rom_file' in globals():
        _r_next = load_rom_file("next.rom") or load_rom_file("nextbasic.rom")
        if _r_next and len(_r_next) >= 16384:
            rom_banks = [bytearray(_r_next[:16384])]
        elif 'ZX_PLUS3_ROM_BANKS' in globals() and len(ZX_PLUS3_ROM_BANKS) > 0:
            rom_banks = [bytearray(ZX_PLUS3_ROM_BANKS[0])]
        else:
            rom_banks = [bytearray(ZX_48K_ROM)]
    else:
        rom_banks = [bytearray(ZX_48K_ROM)]

    for _rb in rom_banks:
        _rb[15616 : 15616 + 768] = ZX_ROM_FONT

    memory[0:16384] = rom_banks[0]
    memory[15616 : 15616 + 768] = ZX_ROM_FONT

    ram_banks[5][0:6144] = b'\x00' * 6144
    ram_banks[5][6144:6912] = b'\x38' * 768
    ram_banks[7][6144:6912] = b'\x38' * 768

    memory[16384:32768] = ram_banks[5]
    memory[32768:49152] = ram_banks[2]
    memory[49152:65536] = ram_banks[0]

    current_paper = 7
    current_ink = 0
    current_border = 7

    if reset_vars:
        init_128k_sysvars()

    execute_cls()
    ram_banks[5][:6912] = memory[16384:23296]

    if 'z80_cpu' in globals() and z80_cpu is not None:
        z80_cpu.clock_hz = 28000000
        z80_cpu.frame_tstates = 560000
        z80_cpu.plus3_mode = False
        z80_cpu.contention_enabled = False

    sync_display_to_active_screen()
    if 'canvas_print' in globals():
        canvas_print("* ZX SPECTRUM NEXT (NextBASIC) *")
        canvas_print("* 28MHz Turbo / 2MB RAM / NextZXOS *")
    print("* ZX SPECTRUM NEXT (NextBASIC) *")
    if 'redraw_canvas' in globals():
        redraw_canvas(force=True)
    if 'update_display' in globals():
        try:
            update_display()
        except Exception:
            pass

def handle_nextreg_command(stmt_str):
    cmd = stmt_str.strip()
    upper = cmd.upper()
    if upper.startswith("NEXTREG"):
        tail = cmd[7:].strip()
    elif upper.startswith("REG"):
        tail = cmd[3:].strip()
    else:
        return
    if tail.startswith(":"): tail = tail[1:].strip()
    parts = split_top_level_commas(tail)
    if len(parts) >= 2:
        try:
            r = int(to_float(evaluate_expr(parts[0])))
            v = int(to_float(evaluate_expr(parts[1])))
            set_nextreg(r, v)
        except Exception as e:
            canvas_print(f"Error in NEXTREG command: {e}")
    else:
        canvas_print("Syntax: NEXTREG <register>, <value>")

def handle_frame_command(stmt_str):
    global running, last_display_time
    cmd = stmt_str.strip()
    tail = cmd[5:].strip()
    if tail.startswith(":"): tail = tail[1:].strip()
    frames = 1
    if tail:
        try:
            frames = int(to_float(evaluate_expr(tail)))
        except Exception:
            frames = 1
    if frames <= 0:
        frames = 1
    target_ms = int(frames * 20)
    start_ticks = pygame.time.get_ticks()
    while (pygame.time.get_ticks() - start_ticks < target_ms) and (running or not program_execution_mode):
        pygame.event.pump()
        keys = pygame.key.get_pressed()
        if keys[pygame.K_ESCAPE] or keys[pygame.K_END]:
            raise BASICBreak()
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            elif is_break_event(event):
                raise BASICBreak()
            elif event.type == pygame.MOUSEMOTION:
                update_amx_from_mouse(event.pos)
            elif event.type in (pygame.MOUSEBUTTONDOWN, pygame.MOUSEBUTTONUP):
                update_amx_from_mouse(event.pos)
                update_amx_buttons(event)
        if amx_pointer_visible or (pygame.time.get_ticks() - last_display_time >= 16):
            update_display()
        pygame.time.delay(1)
    update_display()

def handle_turbo_command(stmt_str):
    global next_turbo_speed, z80_cpu
    cmd = stmt_str.strip()
    tail = cmd[5:].strip()
    if tail.startswith(":"): tail = tail[1:].strip()
    if not tail:
        canvas_print(f"Current Turbo Speed: {next_turbo_speed} ({[3.5, 7, 14, 28][next_turbo_speed]} MHz)")
        return
    try:
        val = to_float(evaluate_expr(tail))
        if val in (28, 28.0): spd = 3
        elif val in (14, 14.0): spd = 2
        elif val in (7, 7.0): spd = 1
        elif val in (3.5, 3.54, 3.55, 35): spd = 0
        else: spd = int(val) & 0x03
        next_turbo_speed = spd
        set_nextreg(0x07, spd)
        mhz = [3.5, 7, 14, 28][spd]
        if 'z80_cpu' in globals() and z80_cpu is not None:
            z80_cpu.clock_hz = int(mhz * 1000000)
            z80_cpu.frame_tstates = int(mhz * 20000)
        canvas_print(f"TURBO: {mhz} MHz (Speed {spd})")
    except Exception as e:
        canvas_print(f"Invalid TURBO speed: {tail}")

last_dump_addr = 0

def handle_dump_command(stmt_str):
    global last_dump_addr, memory
    sync_screen_memory()
    cmd = stmt_str.strip()
    cmd_u = cmd.upper()
    if cmd_u.startswith("MEM DUMP"):
        tail = cmd[8:].strip()
    elif cmd_u.startswith("DUMP"):
        tail = cmd[4:].strip()
    else:
        tail = cmd
    if tail.startswith(":"):
        tail = tail[1:].strip()
    start_addr = last_dump_addr
    length = 128
    if tail:
        tokens = split_top_level_commas(tail)
        if len(tokens) >= 1 and tokens[0].strip():
            try:
                start_addr = int(to_float(evaluate_expr(tokens[0]))) & 0xFFFF
            except Exception:
                canvas_print(f"Invalid DUMP address: {tokens[0]}")
                update_display()
                return
        if len(tokens) >= 2 and tokens[1].strip():
            try:
                length = int(to_float(evaluate_expr(tokens[1])))
                if length <= 0:
                    length = 128
            except Exception:
                canvas_print(f"Invalid DUMP length: {tokens[1]}")
                update_display()
                return
    end_addr = start_addr + length
    cur = start_addr
    while cur < end_addr:
        row_addr = cur & 0xFFFF
        row_len = min(16, end_addr - cur)
        chunk = [memory[(row_addr + i) & 0xFFFF] for i in range(row_len)]
        hex_bytes = " ".join(f"{b:02X}" for b in chunk)
        ascii_chars = "".join(chr(b) if 32 <= b <= 126 else "." for b in chunk)
        if row_len < 16:
            hex_bytes = hex_bytes.ljust(16 * 3 - 1)
        line_str = f"{row_addr:04X}: {hex_bytes} | {ascii_chars} |"
        canvas_print(line_str)
        cur += row_len
    last_dump_addr = cur & 0xFFFF
    update_display()

def handle_layer_command(stmt_str):
    global layer2_active, layer_order, next_layer2_mode, timex_screen_mode, canvas_dirty
    if globals().get('spectrum_mode', '48K') != 'NEXT':
        canvas_print("LAYER command only available in Next mode")
        return
    cmd = stmt_str.strip()
    tail = cmd[5:].strip()
    if tail.startswith(":"): tail = tail[1:].strip()
    upper_tail = tail.upper()
    if not tail:
        canvas_print(f"Layer 2: {'ON' if layer2_active else 'OFF'} (Mode {next_layer2_mode}), Order: {layer_order}")
        return
    if upper_tail.startswith("ORDER "):
        arg = tail[6:].strip()
        try:
            layer_order = int(to_float(evaluate_expr(arg))) & 0x07
            canvas_print(f"Layer Order set to {layer_order}")
        except Exception:
            layer_order = 0
        return
    if upper_tail.startswith("OVER "):
        canvas_print(f"Layer Over: {tail[5:].strip()}")
        return
    if upper_tail.startswith("PALETTE "):
        handle_palette_command(f"PALETTE {tail[8:].strip()}")
        return
    parts = split_top_level_commas(tail)
    if parts:
        mode_layer = int(to_float(evaluate_expr(parts[0])))
        if mode_layer == 2:
            state_val = int(to_float(evaluate_expr(parts[1]))) if len(parts) > 1 else 1
            if state_val == 0:
                layer2_active = False
                next_layer2_mode = 0
                canvas_print("Layer 2: OFF")
            else:
                layer2_active = True
                next_layer2_mode = state_val  # 1=256x192, 2=320x256, 3=640x256
                canvas_print(f"Layer 2: ON (Mode {next_layer2_mode})")
            canvas_dirty = True
            update_display()
        elif mode_layer == 1:
            sub_mode = int(to_float(evaluate_expr(parts[1]))) if len(parts) > 1 else 0
            if sub_mode == 1:
                timex_screen_mode = 2  # Mode 2: Hi-Colour
                canvas_print("Layer 1: Timex Hi-Colour (Mode 2)")
            elif sub_mode == 2:
                timex_screen_mode = 6  # Mode 6: Hi-Res
                canvas_print("Layer 1: Timex Hi-Res (Mode 6)")
            else:
                timex_screen_mode = 0  # Mode 0: Standard ULA
                canvas_print("Layer 1: Standard ULA")
            canvas_dirty = True
            update_display()
        else:
            canvas_print(f"Layer {mode_layer} configured")

def handle_lores_command(stmt_str):
    global next_lores_mode, canvas_dirty
    if globals().get('spectrum_mode', '48K') != 'NEXT':
        canvas_print("LORES command only available in Next mode")
        return
    cmd = stmt_str.strip()
    tail = cmd[5:].strip()
    if tail.startswith(":"): tail = tail[1:].strip()
    if not tail:
        canvas_print(f"LoRes Mode: {'ON' if next_lores_mode else 'OFF'}")
        return
    try:
        val = int(to_float(evaluate_expr(tail)))
        next_lores_mode = 1 if val != 0 else 0
        canvas_print(f"LoRes Mode: {'ON' if next_lores_mode else 'OFF'}")
        canvas_dirty = True
        update_display()
    except Exception as e:
        canvas_print(f"Error in LORES: {e}")

def handle_palette_command(stmt_str):
    global next_palettes
    cmd = stmt_str.strip()
    tail = cmd[7:].strip()
    if tail.startswith(":"): tail = tail[1:].strip()
    upper_tail = tail.upper()
    if not tail:
        canvas_print("Syntax: PALETTE <layer>, <index>, <color> or PALETTE RESET")
        return
    if upper_tail == "RESET":
        next_palettes = {
            "ULA": [i for i in range(256)],
            "LAYER2": [i for i in range(256)],
            "SPRITE": [i for i in range(256)],
            "TILE": [i for i in range(256)],
        }
        canvas_print("Next Palettes reset to default")
        return
    if upper_tail.startswith("LOAD "):
        canvas_print(f"Loaded palette: {tail[5:].strip()}")
        return
    parts = split_top_level_commas(tail)
    if len(parts) >= 3:
        raw_target = parts[0].strip().upper().replace(" ", "")
        target_map = {
            "ULA": "ULA",
            "LAYER2": "LAYER2", "L2": "LAYER2", "LAYER": "LAYER2",
            "SPRITE": "SPRITE", "SPRITES": "SPRITE",
            "TILE": "TILE", "TILEMAP": "TILE"
        }
        layer_target = target_map.get(raw_target, "ULA")
        idx = int(to_float(evaluate_expr(parts[1]))) & 0xFF
        col = int(to_float(evaluate_expr(parts[2]))) & 0x1FF
        next_palettes[layer_target][idx] = col
    elif len(parts) == 2:
        idx = int(to_float(evaluate_expr(parts[0]))) & 0xFF
        col = int(to_float(evaluate_expr(parts[1]))) & 0x1FF
        next_palettes["ULA"][idx] = col

def eval_next_palette_fn(*args):
    try:
        if not args:
            return 0.0
        if len(args) == 1:
            idx = int(to_float(args[0])) & 0xFF
            return float(next_palettes["ULA"][idx])
        raw_target = str(args[0]).upper().strip(' "\'').replace(" ", "")
        target_map = {
            "ULA": "ULA",
            "LAYER2": "LAYER2", "L2": "LAYER2", "LAYER": "LAYER2",
            "SPRITE": "SPRITE", "SPRITES": "SPRITE",
            "TILE": "TILE", "TILEMAP": "TILE"
        }
        layer_target = target_map.get(raw_target, "ULA")
        idx = int(to_float(args[1])) & 0xFF
        pal = next_palettes.get(layer_target, next_palettes["ULA"])
        return float(pal[idx])
    except Exception:
        return 0.0

def eval_next_lores_fn(*args):
    return float(next_lores_mode)

def eval_next_tilemap_fn(*args):
    try:
        if not args:
            if 'get_tilemap_engine' in globals() and get_tilemap_engine:
                eng = get_tilemap_engine()
                return 1.0 if getattr(eng, 'active', False) else 0.0
            return 0.0
        prop = args[0]
        if isinstance(prop, str):
            p_str = prop.upper().strip(' "\'')
            if p_str in ("ACTIVE", "STATUS", "ON"):
                if 'get_tilemap_engine' in globals() and get_tilemap_engine:
                    return 1.0 if getattr(get_tilemap_engine(), 'active', False) else 0.0
                return 0.0
            elif p_str in ("WIDTH", "W"):
                if 'get_tilemap_engine' in globals() and get_tilemap_engine:
                    return float(getattr(get_tilemap_engine(), 'width', 40))
                return 40.0
            elif p_str in ("HEIGHT", "H"):
                if 'get_tilemap_engine' in globals() and get_tilemap_engine:
                    return float(getattr(get_tilemap_engine(), 'height', 32))
                return 32.0
        if len(args) >= 2:
            x = int(to_float(args[0]))
            y = int(to_float(args[1]))
            if 'get_tilemap_engine' in globals() and get_tilemap_engine:
                eng = get_tilemap_engine()
                if hasattr(eng, 'get_tile_at'):
                    return float(eng.get_tile_at(x, y))
            return 0.0
        return 0.0
    except Exception:
        return 0.0

def eval_next_sprite_prop_fn(*args):
    try:
        if not args:
            return 0.0
        s_id = int(to_float(args[0])) & 0x7F
        sp = next_sprite_manager.sprites[s_id]
        if len(args) < 2:
            return float(sp.x)
        prop = args[1]
        if isinstance(prop, (int, float)):
            p_num = int(to_float(prop))
        else:
            p_str = str(prop).upper().strip(' "\'')
            prop_map = {
                "X": 0, "POSX": 0,
                "Y": 1, "POSY": 1,
                "PATTERN": 2, "DEF": 2, "DEF_ID": 2,
                "VISIBLE": 3, "STATUS": 3, "FLAGS": 3,
                "SCALE_X": 4, "SCALE": 4,
                "SCALE_Y": 5,
                "FLIP_X": 6, "FLIPX": 6,
                "FLIP_Y": 7, "FLIPY": 7,
                "ROTATE": 8,
                "PALETTE": 9, "PALETTE_OFFSET": 9,
            }
            p_num = prop_map.get(p_str, 0)
        
        if p_num == 0:
            return float(sp.x)
        elif p_num == 1:
            return float(sp.y)
        elif p_num == 2:
            return float(sp.pattern)
        elif p_num == 3:
            return 1.0 if sp.visible else 0.0
        elif p_num == 4:
            return float(sp.scale_x)
        elif p_num == 5:
            return float(sp.scale_y)
        elif p_num == 6:
            return 1.0 if sp.flip_x else 0.0
        elif p_num == 7:
            return 1.0 if sp.flip_y else 0.0
        elif p_num == 8:
            return float(sp.rotate)
        elif p_num == 9:
            return float(sp.palette_offset)
        return float(sp.x)
    except Exception:
        return 0.0

def handle_next_sprite_command(tail, upper_tail):
    global canvas_dirty, next_selected_sprite, layer_order
    in_prog = globals().get('program_execution_mode', False)
    if not upper_tail:
        canvas_dirty = True
        if not in_prog:
            update_display()
        return
    if upper_tail in ("CLEAR", "CLS", "RESET"):
        next_sprite_manager.clear_all()
        canvas_dirty = True
        if not in_prog:
            update_display()
        return
    if upper_tail == "PRINT":
        canvas_print("Next Sprites printed to canvas")
        canvas_dirty = True
        if not in_prog:
            update_display()
        return
    if upper_tail.startswith("ON "):
        args = split_top_level_commas(tail[3:])
        s_id = int(to_float(evaluate_expr(args[0]))) & 0x7F
        pat = int(to_float(evaluate_expr(args[1]))) if len(args) > 1 and args[1].strip() else None
        sp = next_sprite_manager.sprites[s_id]
        sp.visible = True
        if pat is not None:
            sp.pattern = pat & 0x3F
        canvas_dirty = True
        if not in_prog:
            update_display()
        return
    if upper_tail.startswith("OFF "):
        s_id = int(to_float(evaluate_expr(tail[4:].strip()))) & 0x7F
        next_sprite_manager.sprites[s_id].visible = False
        canvas_dirty = True
        if not in_prog:
            update_display()
        return
    if upper_tail.startswith("VISIBLE "):
        args = split_top_level_commas(tail[8:])
        if len(args) >= 2:
            s_id = int(to_float(evaluate_expr(args[0]))) & 0x7F
            vis = bool(to_float(evaluate_expr(args[1])))
            next_sprite_manager.sprites[s_id].visible = vis
            if hasattr(next_sprite_manager, 'pattern_surfaces'):
                next_sprite_manager.pattern_surfaces.clear()
            canvas_dirty = True
            if not in_prog:
                update_display()
        return
    if upper_tail.startswith("MOVE "):
        args = split_top_level_commas(tail[5:])
        if len(args) >= 3:
            s_id = int(to_float(evaluate_expr(args[0]))) & 0x7F
            dx = int(to_float(evaluate_expr(args[1])))
            dy = int(to_float(evaluate_expr(args[2])))
            next_sprite_manager.move_sprite(s_id, dx, dy)
            canvas_dirty = True
            if not in_prog:
                update_display()
        return
    if upper_tail.startswith("FLIP "):
        args = split_top_level_commas(tail[5:])
        if len(args) >= 1:
            s_id = int(to_float(evaluate_expr(args[0]))) & 0x7F
            fx = bool(to_float(evaluate_expr(args[1]))) if len(args) > 1 else True
            fy = bool(to_float(evaluate_expr(args[2]))) if len(args) > 2 else False
            sp = next_sprite_manager.sprites[s_id]
            sp.flip_x = fx
            sp.flip_y = fy
            canvas_dirty = True
            if not in_prog:
                update_display()
        return
    if upper_tail.startswith("ROTATE "):
        args = split_top_level_commas(tail[7:])
        if len(args) >= 2:
            s_id = int(to_float(evaluate_expr(args[0]))) & 0x7F
            rot = int(to_float(evaluate_expr(args[1])))
            next_sprite_manager.sprites[s_id].rotate = rot
            canvas_dirty = True
            if not in_prog:
                update_display()
        return
    if upper_tail.startswith("SCALE "):
        args = split_top_level_commas(tail[6:])
        if len(args) >= 2:
            s_id = int(to_float(evaluate_expr(args[0]))) & 0x7F
            sx = max(1, min(8, int(to_float(evaluate_expr(args[1])))))
            sy = max(1, min(8, int(to_float(evaluate_expr(args[2]))))) if len(args) > 2 else sx
            sp = next_sprite_manager.sprites[s_id]
            sp.scale_x = sx
            sp.scale_y = sy
            canvas_dirty = True
            if not in_prog:
                update_display()
        return
    if upper_tail.startswith("PATTERN "):
        args = split_top_level_commas(tail[8:])
        if len(args) >= 2:
            s_id = int(to_float(evaluate_expr(args[0]))) & 0x7F
            pat = int(to_float(evaluate_expr(args[1]))) & 0x3F
            next_sprite_manager.sprites[s_id].pattern = pat
            canvas_dirty = True
            if not in_prog:
                update_display()
        return
    if upper_tail.startswith("PALETTE "):
        args = split_top_level_commas(tail[8:])
        if len(args) >= 2:
            s_id = int(to_float(evaluate_expr(args[0]))) & 0x7F
            pal = int(to_float(evaluate_expr(args[1]))) & 0x0F
            next_sprite_manager.sprites[s_id].palette_offset = pal
            canvas_dirty = True
            if not in_prog:
                update_display()
        return
    if upper_tail.startswith("OVER "):
        try:
            val = int(to_float(evaluate_expr(tail[5:].strip()))) & 0x07
            layer_order = val
            canvas_print(f"Sprite Over Layer Order: {layer_order}")
        except Exception:
            pass
        return
    if upper_tail.startswith("DEF "):
        m_from = re.match(r"^DEF\s+([^,\s]+)\s+FROM\s+(.+)$", tail, re.IGNORECASE)
        if m_from:
            pat_id = int(to_float(evaluate_expr(m_from.group(1)))) & 0x3F
            start_l = int(to_float(evaluate_expr(m_from.group(2))))
            if not data_pool or not any(item["line"] >= start_l for item in data_pool):
                parse_data_lines()
            vals = []
            for item in data_pool:
                if item["line"] >= start_l:
                    v = item["val"]
                    vals.append(v if isinstance(v, int) else int(to_float(v)) & 0xFF)
                    if len(vals) == 256:
                        break
            buf = next_sprite_manager.patterns[pat_id]
            for i, b in enumerate(vals):
                buf[i] = b
            canvas_dirty = True
            if not in_prog:
                update_display()
            return
        args = split_top_level_commas(tail[4:])
        if len(args) >= 2:
            pat_id = int(to_float(evaluate_expr(args[0]))) & 0x3F
            vals = [int(to_float(evaluate_expr(a))) & 0xFF for a in args[1:]]
            buf = next_sprite_manager.patterns[pat_id]
            for i, b in enumerate(vals[:256]):
                buf[i] = b
            canvas_dirty = True
            if not in_prog:
                update_display()
        return
    parts = split_top_level_commas(tail)
    if len(parts) >= 3:
        try:
            s_id = int(to_float(evaluate_expr(parts[0]))) & 0x7F
            sx = int(to_float(evaluate_expr(parts[1])))
            sy = int(to_float(evaluate_expr(parts[2])))
            pat = int(to_float(evaluate_expr(parts[3]))) if len(parts) > 3 and parts[3].strip() else None
            pal = int(to_float(evaluate_expr(parts[4]))) if len(parts) > 4 and parts[4].strip() else 0
            sp = next_sprite_manager.sprites[s_id]
            sp.x = sx
            sp.y = sy
            if pat is not None:
                sp.pattern = pat & 0x3F
            sp.palette_offset = pal & 0x0F
            sp.visible = True
            canvas_dirty = True
            if not in_prog:
                update_display()
            return
        except Exception as e:
            canvas_print(f"Error in Next SPRITE: {e}")

def handle_driver_command(stmt_str):
    canvas_print(f"NextZXOS Driver call: {stmt_str[6:].strip()} OK")

# Security: sandbox root prevents path traversal outside the working directory
_SANDBOX_ROOT = os.path.abspath(os.getcwd())

def _is_path_within_sandbox(path):
    """Return True if resolved path is within (or equal to) the sandbox root."""
    try:
        resolved = os.path.abspath(path)
        # os.path.commonpath raises ValueError if paths are on different drives (Windows)
        return os.path.commonpath([_SANDBOX_ROOT, resolved]) == _SANDBOX_ROOT
    except (ValueError, TypeError):
        return False

def get_next_path(p_str=""):
    global next_cwd
    p = (p_str or "").strip().strip('"\'')
    if not p:
        return next_cwd
    if os.path.isabs(p):
        resolved = os.path.abspath(p)
    else:
        resolved = os.path.abspath(os.path.join(next_cwd, p))
    if not _is_path_within_sandbox(resolved):
        raise PermissionError(f"Path traversal blocked: '{p}' resolves outside sandbox")
    return resolved

def handle_pwd_command(stmt_str=""):
    global next_cwd
    canvas_print(f"CWD: {next_cwd}")

def handle_cd_command(stmt_str=""):
    global next_cwd
    cmd = stmt_str.strip()
    upper = cmd.upper()
    if upper.startswith("CHDIR"):
        tail = cmd[5:].strip()
    elif upper.startswith("CD"):
        tail = cmd[2:].strip()
    else:
        tail = ""
    if tail.startswith(":"): tail = tail[1:].strip()
    target = tail.strip().strip('"\'')
    if not target or target in ("\\", "/"):
        next_cwd = os.getcwd()
    else:
        new_p = get_next_path(target)
        if os.path.exists(new_p) and os.path.isdir(new_p):
            next_cwd = new_p
        else:
            canvas_print(f"Directory not found: {target}")
            return
    canvas_print(f"CWD: {next_cwd}")

def handle_mkdir_command(stmt_str=""):
    cmd = stmt_str.strip()
    upper = cmd.upper()
    tail = cmd[5:].strip() if upper.startswith("MKDIR") else cmd[2:].strip()
    if tail.startswith(":"): tail = tail[1:].strip()
    target = tail.strip().strip('"\'')
    if target:
        new_dir = get_next_path(target)
        try:
            os.makedirs(new_dir, exist_ok=True)
            canvas_print(f"Created directory: {target}")
        except Exception as e:
            canvas_print(f"MKDIR error: {e}")

def handle_rmdir_command(stmt_str=""):
    cmd = stmt_str.strip()
    upper = cmd.upper()
    tail = cmd[5:].strip() if upper.startswith("RMDIR") else cmd[2:].strip()
    if tail.startswith(":"): tail = tail[1:].strip()
    target = tail.strip().strip('"\'')
    if target:
        tgt_dir = get_next_path(target)
        try:
            if os.path.exists(tgt_dir) and os.path.isdir(tgt_dir):
                os.rmdir(tgt_dir)
                canvas_print(f"Removed directory: {target}")
            else:
                canvas_print(f"Directory not found: {target}")
        except Exception as e:
            canvas_print(f"RMDIR error: {e}")

def handle_erase_command(stmt_str=""):
    cmd = stmt_str.strip()
    upper = cmd.upper()
    if upper.startswith("ERASE"): tail = cmd[5:].strip()
    elif upper.startswith("REMOVE"): tail = cmd[6:].strip()
    elif upper.startswith("DEL"): tail = cmd[3:].strip()
    else: tail = cmd
    if tail.startswith(":"): tail = tail[1:].strip()
    target = tail.strip().strip('"\'')
    if target:
        tgt_file = get_next_path(target)
        try:
            if os.path.exists(tgt_file) and os.path.isfile(tgt_file):
                os.remove(tgt_file)
                canvas_print(f"Erased: {target}")
            else:
                canvas_print(f"File not found: {target}")
        except Exception as e:
            canvas_print(f"ERASE error: {e}")

def handle_rename_command(stmt_str=""):
    cmd = stmt_str.strip()
    upper = cmd.upper()
    if upper.startswith("RENAME"): tail = cmd[6:].strip()
    elif upper.startswith("REN"): tail = cmd[3:].strip()
    else: tail = cmd
    if tail.startswith(":"): tail = tail[1:].strip()
    m_to = re.search(r'\bTO\b', tail, re.IGNORECASE)
    if m_to:
        src = tail[:m_to.start()].strip().strip('"\'')
        dst = tail[m_to.end():].strip().strip('"\'')
    else:
        parts = split_top_level_commas(tail)
        src = parts[0].strip().strip('"\'') if len(parts) > 0 else ""
        dst = parts[1].strip().strip('"\'') if len(parts) > 1 else ""
    if src and dst:
        src_path = get_next_path(src)
        dst_path = get_next_path(dst)
        try:
            if os.path.exists(src_path):
                os.rename(src_path, dst_path)
                canvas_print(f"Renamed: {src} TO {dst}")
            else:
                canvas_print(f"File not found: {src}")
        except Exception as e:
            canvas_print(f"RENAME error: {e}")

def handle_copy_command(stmt_str=""):
    import shutil
    cmd = stmt_str.strip()
    upper = cmd.upper()
    if upper.startswith("COPY"):
        tail = cmd[4:].strip()
    else:
        tail = cmd
    if tail.startswith(":"): tail = tail[1:].strip()
    if not tail:
        if 'zx_printer' in globals() and zx_printer:
            try:
                zx_printer.print_screen(canvas)
                zx_printer.flush()
                canvas_print("Screen copied to printer")
            except Exception:
                canvas_print("Screen COPY OK")
        else:
            canvas_print("Screen COPY OK")
        return
    m_to = re.search(r'\bTO\b', tail, re.IGNORECASE)
    if m_to:
        src = tail[:m_to.start()].strip().strip('"\'')
        dst = tail[m_to.end():].strip().strip('"\'')
    else:
        parts = split_top_level_commas(tail)
        src = parts[0].strip().strip('"\'') if len(parts) > 0 else ""
        dst = parts[1].strip().strip('"\'') if len(parts) > 1 else ""
    if src and dst:
        src_path = get_next_path(src)
        dst_path = get_next_path(dst)
        try:
            if os.path.exists(src_path):
                shutil.copy2(src_path, dst_path)
                canvas_print(f"Copied: {src} TO {dst}")
            else:
                canvas_print(f"File not found: {src}")
        except Exception as e:
            canvas_print(f"COPY error: {e}")

