def handle_dot_command(cmd_str):
    c = cmd_str.strip()
    parts = c.split(None, 1)
    dot_cmd = parts[0].lower()
    arg = parts[1].strip() if len(parts) > 1 else ""
    if dot_cmd in (".ls", ".dir"):
        target_dir = get_next_path(arg)
        if os.path.exists(target_dir) and os.path.isdir(target_dir):
            items = sorted(os.listdir(target_dir), key=str.lower)
            canvas_print(f"--- {dot_cmd.upper()} {target_dir} ---")
            for item in items[:40]:
                canvas_print(item)
        else:
            canvas_print(f"Path not found: {arg}")
    elif dot_cmd == ".cd":
        handle_cd_command(f"CD {arg}")
    elif dot_cmd == ".pwd":
        handle_pwd_command()
    elif dot_cmd == ".mkdir":
        handle_mkdir_command(f"MKDIR {arg}")
    elif dot_cmd == ".rmdir":
        handle_rmdir_command(f"RMDIR {arg}")
    elif dot_cmd == ".cp":
        handle_copy_command(f"COPY {arg}")
    elif dot_cmd == ".mv":
        handle_move_command(f"MOVE {arg}")
    elif dot_cmd == ".rm":
        handle_erase_command(f"ERASE {arg}")
    elif dot_cmd == ".cat":
        tgt = get_next_path(arg)
        if os.path.exists(tgt) and os.path.isfile(tgt):
            with open(tgt, "r", errors="replace") as f:
                for line in f.readlines()[:24]:
                    canvas_print(line.rstrip())
        else:
            canvas_print(f"File not found: {arg}")
    elif dot_cmd == ".vstat":
        canvas_print(f"Next Video: L2={'ON' if layer2_active else 'OFF'} Order={layer_order}")
        canvas_print(f"Turbo: {[3.5, 7, 14, 28][next_turbo_speed]}MHz Core=3.1 Reg0={get_nextreg(0):02X}H")
    elif dot_cmd == ".help":
        canvas_print("NextZXOS / ESXDOS Dot Commands:")
        canvas_print(".ls, .dir, .cd, .pwd, .mkdir, .rmdir, .cp, .mv, .rm, .cat, .vstat")
    else:
        canvas_print(f"NextZXOS command: {dot_cmd} executed")

def handle_exdos_colon_command(cmd_str):
    clean = cmd_str.strip()[1:].strip()
    upper = clean.upper()
    if upper.startswith("DIR") or upper.startswith("CAT"):
        handle_dot_command(f".ls {clean[3:].strip()}")
    elif upper.startswith("CD"):
        handle_cd_command(f"CD {clean[2:].strip()}")
    elif upper.startswith("ERASE") or upper.startswith("DEL"):
        handle_erase_command(f"ERASE {clean[5:].strip()}")
    elif upper.startswith("REN"):
        handle_rename_command(f"RENAME {clean[3:].strip()}")
    elif upper.startswith("COPY"):
        handle_copy_command(f"COPY {clean[4:].strip()}")
    elif upper.startswith("TYPE"):
        handle_dot_command(f".cat {clean[4:].strip()}")
    elif upper.startswith("DISC") or upper.startswith("DISK"):
        canvas_print("EXDOS Disc mode active")
    elif upper.startswith("TAPE"):
        canvas_print("EXDOS Tape mode active")
    else:
        canvas_print(f"EXDOS command executed: :{clean}")

next_esxdos_open_files = {}

def read_null_term_string(cpu, addr):
    s = []
    while addr < 65536:
        b = cpu.memory[addr]
        if b == 0:
            break
        s.append(chr(b))
        addr += 1
    return "".join(s)

def write_null_term_string(cpu, addr, text):
    for ch in text.encode('ascii', errors='replace'):
        if addr >= 65536:
            break
        cpu.memory[addr] = ch
        addr += 1
    if addr < 65536:
        cpu.memory[addr] = 0

def handle_nextzxos_esxdos_hook(cpu, fn_code):
    global next_esxdos_open_files, next_active_drive, next_cwd
    # M_GETSETDRV: 0x89
    if fn_code == 0x89:
        if cpu.A == 0:
            cpu.A = ord(next_active_drive[0].upper()) - ord('A')
        else:
            old_drv = ord(next_active_drive[0].upper()) - ord('A')
            new_drv_ch = chr(ord('A') + (cpu.A & 0x07))
            set_next_drive(f"{new_drv_ch}:")
            cpu.A = old_drv
        cpu.F &= ~FLAG_C
        return True

    # F_OPEN: 0x9A
    elif fn_code == 0x9A:
        path = read_null_term_string(cpu, cpu.HL)
        target_file = get_next_path(path)
        mode_flag = cpu.B
        mode_str = "rb"
        if (mode_flag & 0x06) == 0x06 or (mode_flag & 0x0C) == 0x0C:
            mode_str = "wb+"
        elif mode_flag & 0x08:
            mode_str = "ab+"
        elif mode_flag & 0x02:
            mode_str = "rb+"
        try:
            d = os.path.dirname(target_file)
            if d:
                os.makedirs(d, exist_ok=True)
            f = open(target_file, mode_str)
            handle = 1
            while handle in next_esxdos_open_files:
                handle += 1
            next_esxdos_open_files[handle] = f
            cpu.A = handle
            cpu.F &= ~FLAG_C
        except Exception:
            cpu.A = 0x07  # File not found / error
            cpu.F |= FLAG_C
        return True

    # F_CLOSE: 0x9B
    elif fn_code == 0x9B:
        handle = cpu.A
        f = next_esxdos_open_files.pop(handle, None)
        if f:
            try:
                f.close()
            except Exception:
                pass
            cpu.F &= ~FLAG_C
        else:
            cpu.A = 0x08  # Invalid handle
            cpu.F |= FLAG_C
        return True

    # F_READ: 0x9D
    elif fn_code == 0x9D:
        handle = cpu.A
        dest_addr = cpu.IX
        count = cpu.BC
        f = next_esxdos_open_files.get(handle)
        if f:
            try:
                data = f.read(count)
                for i, b in enumerate(data):
                    if dest_addr + i < 65536:
                        cpu.memory[dest_addr + i] = b
                cpu.BC = len(data)
                cpu.F &= ~FLAG_C
            except Exception:
                cpu.A = 0x09
                cpu.F |= FLAG_C
        else:
            cpu.A = 0x08
            cpu.F |= FLAG_C
        return True

    # F_WRITE: 0x9E
    elif fn_code == 0x9E:
        handle = cpu.A
        src_addr = cpu.IX
        count = cpu.BC
        f = next_esxdos_open_files.get(handle)
        if f:
            try:
                data = bytes(cpu.memory[(src_addr + i) & 0xFFFF] for i in range(count))
                f.write(data)
                f.flush()
                cpu.BC = len(data)
                cpu.F &= ~FLAG_C
            except Exception:
                cpu.A = 0x0A
                cpu.F |= FLAG_C
        else:
            cpu.A = 0x08
            cpu.F |= FLAG_C
        return True

    # F_SEEK: 0x9F
    elif fn_code == 0x9F:
        handle = cpu.A
        offset = (cpu.BC << 16) | cpu.DE
        seek_mode = cpu.L  # 0: SET, 1: CUR, 2: END
        f = next_esxdos_open_files.get(handle)
        if f:
            try:
                f.seek(offset, seek_mode if seek_mode in (0, 1, 2) else 0)
                new_pos = f.tell()
                cpu.BC = (new_pos >> 16) & 0xFFFF
                cpu.DE = new_pos & 0xFFFF
                cpu.F &= ~FLAG_C
            except Exception:
                cpu.A = 0x0B
                cpu.F |= FLAG_C
        else:
            cpu.A = 0x08
            cpu.F |= FLAG_C
        return True

    # F_GETCWD: 0xA8
    elif fn_code == 0xA8:
        dest_addr = cpu.HL
        write_null_term_string(cpu, dest_addr, next_cwd)
        cpu.F &= ~FLAG_C
        return True

    # F_STAT: 0xAC
    elif fn_code == 0xAC:
        path = read_null_term_string(cpu, cpu.HL)
        target_file = get_next_path(path)
        dest_buf = cpu.IX
        if os.path.exists(target_file):
            sz = os.path.getsize(target_file)
            cpu.memory[dest_buf & 0xFFFF] = sz & 0xFF
            cpu.memory[(dest_buf + 1) & 0xFFFF] = (sz >> 8) & 0xFF
            cpu.memory[(dest_buf + 2) & 0xFFFF] = (sz >> 16) & 0xFF
            cpu.memory[(dest_buf + 3) & 0xFFFF] = (sz >> 24) & 0xFF
            cpu.F &= ~FLAG_C
        else:
            cpu.A = 0x07
            cpu.F |= FLAG_C
        return True

    else:
        cpu.F &= ~FLAG_C
        return True

def handle_bank_command(cmd_str=""):
    global current_ram_bank
    s = (cmd_str or "").strip()
    s_upper = s.upper()
    if s_upper.startswith("BANK"):
        s = s[4:].strip()
    elif s_upper.startswith("PAGE"):
        s = s[4:].strip()
    if s.startswith(":"): s = s[1:].strip()
    if not s or s == "?":
        canvas_print(f"Current RAM Bank: {current_ram_bank} (0..111)")
        canvas_print("Syntax: BANK <n>, BANK <n> COPY <src>, BANK <b1> TO <b2>")
        return
    try:
        m_copy = re.match(r'^(\d+)\s+COPY\s+(\d+)$', s, re.IGNORECASE)
        if m_copy:
            dst_b = int(m_copy.group(1))
            src_b = int(m_copy.group(2))
            while len(ram_banks) <= max(dst_b, src_b):
                ram_banks.append(bytearray(16384))
            ram_banks[dst_b][:] = ram_banks[src_b][:]
            canvas_print(f"Bank {src_b} copied to Bank {dst_b}")
            return
        m_to = re.match(r'^(\d+)\s+TO\s+(\d+)$', s, re.IGNORECASE)
        if m_to:
            b1 = int(m_to.group(1))
            b2 = int(m_to.group(2))
            while len(ram_banks) <= max(b1, b2):
                ram_banks.append(bytearray(16384))
            ram_banks[b2][:] = ram_banks[b1][:]
            canvas_print(f"Bank {b1} copied to Bank {b2}")
            return
        b = int(evaluate_expr(s))
        if 0 <= b < 224:
            while len(ram_banks) <= b:
                ram_banks.append(bytearray(16384))
            select_ram_bank(b)
            canvas_print(f"Paged RAM Bank {b} at 49152-65535 ($C000-$FFFF)")
        else:
            canvas_print("Error: Bank number must be 0 to 223")
    except Exception as e:
        canvas_print(f"Error in BANK command: {e}")

def handle_spectrum_command(cmd_str=""):
    s = (cmd_str or "").strip()
    s_upper = s.upper()
    if s_upper.startswith("SPECTRUM"):
        s = s[8:].strip()
    if s.startswith(":"): s = s[1:].strip()
    clean = s.upper()
    if not clean or clean in ("48", "48K"):
        set_zx48_mode()
    elif clean in ("128", "128K"):
        set_zx128_mode()
    elif clean in ("+3", "PLUS3", "P3", "ZXP3", "ZX+3"):
        set_zxp3_mode()
    elif clean in ("2068", "TS2068", "TC2068", "TIMEX", "2048", "TC2048"):
        set_timex_machine_mode()
    elif clean in ("NEXT", "ZXNEXT", "SPECTRUMNEXT", "NEXTBASIC", "28"):
        set_zxnext_mode()
    else:
        try:
            val = int(evaluate_expr(s))
            if val == 48:
                set_zx48_mode()
            elif val == 128:
                set_zx128_mode()
            elif val == 3:
                set_zxp3_mode()
            elif val in (2068, 2048):
                set_timex_machine_mode()
            elif val == 28:
                set_zxnext_mode()
            else:
                canvas_print("Syntax: SPECTRUM 48, SPECTRUM 128, SPECTRUM +3, SPECTRUM 2068, or SPECTRUM NEXT")
        except Exception:
            canvas_print("Syntax: SPECTRUM 48, SPECTRUM 128, SPECTRUM +3, SPECTRUM 2068, or SPECTRUM NEXT")

# Set system default to ZX48 with Interface 1 and DISCiPLE on 1st load
set_zx48_mode(reset_vars=True, attach_defaults=True)

# =========================================================================
# ZX SPECTRUM 128K MIDI SUBSYSTEM & WINDOWS DEFAULT MIDI OUTPUT DEVICE
# =========================================================================

class WindowsMidiOut:
    def __init__(self):
        self.hMidi = None
        self.opened = False
        self.enabled = True
        self.winmm = None
        self.pg_out = None
        self.device_name = "Windows Default MIDI Output"
        self.pending_raw_bytes = {}  # channel -> list of bytes

    def open(self):
        if self.opened:
            return True
        # 1. Try Windows winmm.dll via ctypes (direct MIDI_MAPPER = -1)
        try:
            import ctypes
            from ctypes import byref, c_uint
            self.winmm = ctypes.windll.winmm
            h = c_uint(0)
            res = self.winmm.midiOutOpen(byref(h), -1, 0, 0, 0)
            if res == 0:
                self.hMidi = h
                self.opened = True
                self.device_name = "Microsoft MIDI Mapper (winmm.dll)"
                return True
        except Exception:
            pass

        # 2. Fallback to pygame.midi
        try:
            import pygame.midi
            if not pygame.midi.get_init():
                pygame.midi.init()
            def_id = pygame.midi.get_default_output_id()
            if def_id != -1:
                self.pg_out = pygame.midi.Output(def_id)
                self.opened = True
                dev_info = pygame.midi.get_device_info(def_id)
                name = dev_info[1].decode('utf-8', 'ignore') if dev_info and len(dev_info) > 1 else f"Device {def_id}"
                self.device_name = f"{name} (pygame.midi)"
                return True
        except Exception:
            pass

        return False

    def send_short(self, msg):
        if not self.enabled:
            return
        if not self.opened:
            if not self.open():
                return
        if self.hMidi is not None:
            try:
                self.winmm.midiOutShortMsg(self.hMidi, msg & 0xFFFFFFFF)
            except Exception:
                pass
        elif self.pg_out:
            try:
                b1 = msg & 0xFF
                b2 = (msg >> 8) & 0xFF
                b3 = (msg >> 16) & 0xFF
                self.pg_out.write_short(b1, b2, b3)
            except Exception:
                pass

    def note_on(self, channel, note, velocity):
        ch = max(0, min(15, channel))
        n = max(0, min(127, note))
        v = max(0, min(127, velocity))
        msg = (0x90 | ch) | (n << 8) | (v << 16)
        self.send_short(msg)

    def note_off(self, channel, note):
        ch = max(0, min(15, channel))
        n = max(0, min(127, note))
        msg = (0x80 | ch) | (n << 8)
        self.send_short(msg)

    def program_change(self, channel, program):
        ch = max(0, min(15, channel))
        p = max(0, min(127, program))
        msg = (0xC0 | ch) | (p << 8)
        self.send_short(msg)

    def send_raw_byte(self, channel, byte_val):
        ch = max(0, min(15, channel))
        b = byte_val & 0xFF
        buf = self.pending_raw_bytes.get(ch, [])
        if b >= 0x80:
            buf = [b]
        else:
            buf.append(b)
        self.pending_raw_bytes[ch] = buf

        if buf:
            status = buf[0]
            st_type = status & 0xF0
            needed = 0
            if st_type in (0xC0, 0xD0):
                needed = 2
            elif st_type in (0x80, 0x90, 0xA0, 0xB0, 0xE0):
                needed = 3
            elif status >= 0xF0:
                needed = 1

            if needed > 0 and len(buf) >= needed:
                msg = buf[0]
                if needed >= 2:
                    msg |= (buf[1] << 8)
                if needed >= 3:
                    msg |= (buf[2] << 16)
                self.send_short(msg)
                self.pending_raw_bytes[ch] = []
            elif status < 0x80 and len(buf) == 1:
                self.program_change(ch, b)
                self.pending_raw_bytes[ch] = []

    def all_notes_off(self):
        self.pending_raw_bytes.clear()
        for ch in range(16):
            self.send_short((0xB0 | ch) | (120 << 8))  # All Sound Off
            self.send_short((0xB0 | ch) | (123 << 8))  # All Notes Off

    def get_status_string(self):
        state = "ENABLED" if self.enabled else "DISABLED"
        conn = "ACTIVE" if self.opened else "READY"
        return f"{state} ({conn}) -> {self.device_name}"

    def close(self):
        if self.opened:
            try:
                self.all_notes_off()
                if self.hMidi is not None:
                    self.winmm.midiOutClose(self.hMidi)
                    self.hMidi = None
                if self.pg_out:
                    self.pg_out.close()
                    self.pg_out = None
            except Exception:
                pass
            self.opened = False

windows_midi = WindowsMidiOut()

def handle_sound_command(cmd_str=""):
    global current_ay_mode
    s = (cmd_str or "").strip()
    s_upper = s.upper()
    if s_upper.startswith("SOUND"):
        s = s[5:].strip()
    if s.startswith(":"): s = s[1:].strip()
    s_clean = s.strip()
    s_upper = s_clean.upper()

    if s_upper in ("ED", "EDITOR", "FX", "SFX", "SOUNDED"):
        launch_sfx_editor(s_clean)
        return

    if "/FLR" in s_upper or s_upper in ("FLR", "FULLER", "FULLERBOX", "/FULLER"):
        current_ay_mode = "FULLER"
        fuller_ay_chip.set_mode("FULLER")
        canvas_print("AY Sound: FULLER BOX Emulation (1.75 MHz, Mono, Ports 63, 95)")
        return
    elif "/SIN" in s_upper or s_upper in ("SIN", "SINCLAIR", "128", "128K", "/SINCLAIR", "/128"):
        current_ay_mode = "SINCLAIR"
        fuller_ay_chip.set_mode("SINCLAIR")
        canvas_print("AY Sound: SINCLAIR 128K Emulation (1.7734 MHz, ACB Stereo, Ports 65533, 49149)")
        return
    elif "/STEREO" in s_upper or s_upper.startswith("STEREO"):
        if "ABC" in s_upper:
            fuller_ay_chip.set_stereo("ABC")
            canvas_print("AY Stereo Panning: ABC (A=Left, B=Center, C=Right)")
        elif "ACB" in s_upper:
            fuller_ay_chip.set_stereo("ACB")
            canvas_print("AY Stereo Panning: ACB (A=Left, B=Right, C=Center - Sinclair Standard)")
        else:
            fuller_ay_chip.set_stereo("ACB")
            canvas_print("AY Stereo Panning: ACB (Sinclair Standard)")
        return
    elif "/MONO" in s_upper or s_upper in ("MONO", "SOUND MONO"):
        fuller_ay_chip.set_stereo("MONO")
        canvas_print("AY Sound: MONO Panning")
        return
    elif s_upper.startswith("/MIDI") or s_upper.startswith("MIDI"):
        handle_play_command("PLAY " + s_clean)
        return
    elif s_upper in ("", "?", "/?", "/STATUS", "-STATUS", "STATUS", "/HELP"):
        clock_mhz = fuller_ay_chip.get_clock() / 1000000.0
        canvas_print(f"AY Sound Mode: {current_ay_mode} ({clock_mhz:.4f} MHz, Stereo: {fuller_ay_chip.stereo_mode})")
        if current_ay_mode == "SINCLAIR":
            canvas_print("  Register Select: Port 65533 (0xFFFD) / Data: Port 49149 (0xBFFD)")
        else:
            canvas_print("  Register Select: Port 63 (0x3F) / Data: Port 95 (0x5F)")
        with fuller_ay_chip.lock:
            regs = list(fuller_ay_chip.regs)
        clk = fuller_ay_chip.get_clock()
        pa = (regs[1] << 8) | regs[0]
        pb = (regs[3] << 8) | regs[2]
        pc = (regs[5] << 8) | regs[4]
        fa = clk / (32.0 * (pa if pa > 0 else 1)) if pa > 0 else 0
        fb = clk / (32.0 * (pb if pb > 0 else 1)) if pb > 0 else 0
        fc = clk / (32.0 * (pc if pc > 0 else 1)) if pc > 0 else 0
        canvas_print(f"  Tone Freqs: A={fa:.1f}Hz, B={fb:.1f}Hz, C={fc:.1f}Hz | Noise: R6={regs[6]&0x1F}")
        env_p = (regs[12] << 8) | regs[11]
        canvas_print(f"  Envelope: Period={env_p}, Shape={regs[13]&0x0F} | Mixer: R7={regs[7]:02X}h")
        canvas_print(f"MIDI Output:    {windows_midi.get_status_string()}")
        canvas_print("Syntax: SOUND [/SIN | /FLR | /STEREO ACB|ABC | /MONO] or SOUND reg, val")
        return

    # Direct register write: SOUND reg, val or compound: SOUND r1, v1; r2, v2; ... or SOUND r1, v1, r2, v2
    if ";" in s_clean or "," in s_clean:
        pairs = [p.strip() for p in s_clean.split(';') if p.strip()]
        for pair in pairs:
            parts = split_top_level_commas(pair)
            if len(parts) >= 2:
                for k in range(0, len(parts) - 1, 2):
                    try:
                        reg = int(evaluate_expr(parts[k]))
                        val = int(evaluate_expr(parts[k + 1]))
                        if 0 <= reg <= 15:
                            fuller_ay_chip.write_address(reg)
                            fuller_ay_chip.write_data(val)
                        else:
                            canvas_print("Error: AY register must be 0 to 15")
                    except Exception as e:
                        canvas_print(f"Error in SOUND command: {e}")
            else:
                canvas_print("Syntax: SOUND reg, val [; reg2, val2 ...]")
        return
    else:
        canvas_print("Syntax: SOUND [/SIN | /FLR | /STEREO ACB|ABC | /MONO] or SOUND reg, val [; reg2, val2 ...]")

def expand_play_loops(s):
    max_loops = 50
    loop_count = 0
    while '(' in s and ')' in s and loop_count < max_loops:
        loop_count += 1
        m = re.search(r'\(([^()]*)\)(\d*)', s)
        if not m:
            break
        body = m.group(1)
        count_str = m.group(2)
        count = int(count_str) if count_str else 2
        expanded = body * count
        s = s[:m.start()] + expanded + s[m.end():]
    return s

def parse_play_channel(s, default_tempo=120, default_midi_channel=0):
    s = expand_play_loops(s)
    octave = 5
    vol = 15
    dur_code = 5
    use_env = False
    mode = 1
    tempo = default_tempo
    env_shape = 0
    env_period = 1000
    noise_pitch = 0
    midi_channel = default_midi_channel
    midi_enabled = True
    dur_map = {1: 0.25, 2: 0.375, 3: 0.5, 4: 0.75, 5: 1.0, 6: 1.5, 7: 2.0, 8: 3.0, 9: 4.0}
    note_semitones = {'c': 0, 'd': 2, 'e': 4, 'f': 5, 'g': 7, 'a': 9, 'b': 11}
    events = []
    i = 0
    n = len(s)
    accidental = 0
    while i < n:
        ch = s[i]
        if ch.isspace():
            i += 1
            continue
        if ch in ('T', 't'):
            i += 1
            num_str = ''
            while i < n and s[i].isdigit():
                num_str += s[i]; i += 1
            if num_str:
                tempo = max(20, min(600, int(num_str)))
            continue
        if ch in ('O', 'o'):
            i += 1
            if i < n and s[i].isdigit():
                octave = max(0, min(8, int(s[i]))); i += 1
            continue
        if ch in ('V', 'v'):
            i += 1
            num_str = ''
            while i < n and s[i].isdigit():
                num_str += s[i]; i += 1
            if num_str:
                vol = max(0, min(15, int(num_str)))
            continue
        if ch in ('U', 'u'):
            i += 1; use_env = True; continue
        if ch in ('W', 'w'):
            i += 1
            num_str = ''
            while i < n and s[i].isdigit():
                num_str += s[i]; i += 1
            if num_str:
                env_shape = int(num_str) & 0x0F
            continue
        if ch in ('X', 'x'):
            i += 1
            num_str = ''
            while i < n and s[i].isdigit():
                num_str += s[i]; i += 1
            if num_str:
                env_period = int(num_str) & 0xFFFF
            continue
        if ch in ('M', 'm'):
            i += 1
            if i < n and s[i].isdigit():
                mode = int(s[i]); i += 1
            continue
        if ch in ('N', 'n'):
            i += 1
            num_str = ''
            while i < n and s[i].isdigit():
                num_str += s[i]; i += 1
            if num_str:
                noise_pitch = int(num_str) & 0x1F
            continue
        if ch in ('Y', 'y'):
            i += 1
            num_str = ''
            while i < n and s[i].isdigit():
                num_str += s[i]; i += 1
            if num_str:
                val = int(num_str)
                if 1 <= val <= 16:
                    midi_channel = val - 1
                    midi_enabled = True
                elif val == 0:
                    midi_enabled = False
            continue
        if ch in ('Z', 'z'):
            i += 1
            num_str = ''
            while i < n and s[i].isdigit():
                num_str += s[i]; i += 1
            if num_str:
                b_val = int(num_str) & 0xFF
                events.append({
                    'dur_sec': 0.0,
                    'period': 0,
                    'vol': 0,
                    'is_rest': True,
                    'use_env': False,
                    'mode': mode,
                    'is_midi_code': True,
                    'midi_byte': b_val,
                    'midi_channel': midi_channel,
                    'midi_enabled': midi_enabled,
                    'midi_note': 0,
                    'midi_vel': 0
                })
            continue
        if ch == '#':
            accidental = 1; i += 1; continue
        if ch == '$':
            accidental = -1; i += 1; continue
        if ch == '&':
            i += 1
            d_code = dur_code
            if i < n and s[i].isdigit() and s[i] != '0':
                d_code = int(s[i]); i += 1
            dur_sec = dur_map.get(d_code, 1.0) * (60.0 / tempo)
            events.append({
                'dur_sec': dur_sec,
                'period': 0,
                'vol': 0,
                'is_rest': True,
                'use_env': False,
                'mode': mode,
                'is_midi_code': False,
                'midi_byte': 0,
                'midi_note': 0,
                'midi_vel': 0,
                'midi_channel': midi_channel,
                'midi_enabled': midi_enabled
            })
            accidental = 0; continue
        if ch == '_':
            i += 1
            d_code = dur_code
            if i < n and s[i].isdigit() and s[i] != '0':
                d_code = int(s[i]); i += 1
            dur_sec = dur_map.get(d_code, 1.0) * (60.0 / tempo)
            if events:
                for ev in reversed(events):
                    if not ev.get('is_midi_code'):
                        ev['dur_sec'] += dur_sec
                        break
            continue
        lower_ch = ch.lower()
        if lower_ch in note_semitones:
            base_semi = note_semitones[lower_ch]
            if ch.isupper():
                base_semi += 12
            i += 1
            if i < n and s[i] == '#':
                accidental = 1; i += 1
            elif i < n and s[i] == '$':
                accidental = -1; i += 1
            d_code = dur_code
            if i < n and s[i].isdigit() and s[i] != '0':
                d_code = int(s[i]); i += 1
            semi = base_semi + accidental
            midi_note = (octave * 12) + semi
            midi_note = max(0, min(127, midi_note))
            freq = 440.0 * (2.0 ** ((midi_note - 69) / 12.0))
            period = int(round(55420.23 / freq)) if freq > 0 else 0
            period = max(1, min(4095, period))
            dur_sec = dur_map.get(d_code, 1.0) * (60.0 / tempo)
            midi_vel = max(0, min(127, vol * 8))
            events.append({
                'dur_sec': dur_sec,
                'period': period,
                'vol': vol,
                'is_rest': False,
                'use_env': use_env,
                'mode': mode,
                'is_midi_code': False,
                'midi_byte': 0,
                'midi_note': midi_note,
                'midi_vel': midi_vel,
                'midi_channel': midi_channel,
                'midi_enabled': midi_enabled
            })
            accidental = 0; continue
        if ch.isdigit() and ch != '0':
            dur_code = int(ch); i += 1; continue
        i += 1
    return events, tempo, env_shape, env_period, noise_pitch

def play_ay_music(channel_strings):
    global ay_play_active, ay_play_stop
    parsed_channels = []
    global_tempo = 120
    global_env_shape = 0
    global_env_period = 1000
    global_noise_pitch = 0

    num_to_parse = max(3, len(channel_strings[:8]))

    for ch_idx in range(num_to_parse):
        cs = channel_strings[ch_idx] if ch_idx < len(channel_strings) else ""
        def_midi_ch = ch_idx % 16
        evs, t, w, x, n = parse_play_channel(cs, default_tempo=global_tempo, default_midi_channel=def_midi_ch)
        if t != 120: global_tempo = t
        if w != 0: global_env_shape = w
        if x != 1000: global_env_period = x
        if n != 0: global_noise_pitch = n
        parsed_channels.append(evs)

    num_channels = len(parsed_channels)

    timestamps = {0.0}
    for ch in parsed_channels:
        cur = 0.0
        for ev in ch:
            ev['start_time'] = cur
            cur += ev['dur_sec']
            ev['end_time'] = cur
            timestamps.add(round(cur, 6))

    sorted_ts = sorted(timestamps)
    if len(sorted_ts) <= 1:
        return

    ay_play_active = True
    ay_play_stop = False

    if windows_midi.enabled:
        windows_midi.open()

    # Apply initial envelope & noise registers to AY chip
    fuller_ay_chip.write_address(6)
    fuller_ay_chip.write_data(global_noise_pitch & 0x1F)
    fuller_ay_chip.write_address(11)
    fuller_ay_chip.write_data(global_env_period & 0xFF)
    fuller_ay_chip.write_address(12)
    fuller_ay_chip.write_data((global_env_period >> 8) & 0xFF)
    if global_env_shape > 0:
        fuller_ay_chip.write_address(13)
        fuller_ay_chip.write_data(global_env_shape & 0x0F)

    reg_tone = [(0, 1), (2, 3), (4, 5)]
    reg_vol = [8, 9, 10]
    active_midi_notes = [None] * num_channels

    try:
        for idx in range(len(sorted_ts) - 1):
            if ay_play_stop:
                break
            t0, t1 = sorted_ts[idx], sorted_ts[idx + 1]
            dt = t1 - t0
            mid = (t0 + t1) / 2.0

            # Execute Z MIDI code events at t0
            if windows_midi.enabled:
                for ch_idx in range(num_channels):
                    for ev in parsed_channels[ch_idx]:
                        if ev.get('is_midi_code') and abs(ev['start_time'] - t0) < 0.0001:
                            windows_midi.send_raw_byte(ev['midi_channel'], ev['midi_byte'])

            r7 = 0x38  # Default all tones & noise off for AY

            for ch_idx in range(num_channels):
                ev_found = None
                for ev in parsed_channels[ch_idx]:
                    if not ev.get('is_midi_code') and ev['start_time'] <= mid < ev['end_time']:
                        ev_found = ev
                        break

                # 1. Internal AY Sound Chip (Channels 0, 1, 2)
                if ch_idx < 3:
                    r_low, r_high = reg_tone[ch_idx]
                    r_v = reg_vol[ch_idx]
                    if ev_found and not ev_found['is_rest'] and ev_found['vol'] > 0:
                        per = ev_found['period']
                        fuller_ay_chip.write_address(r_low)
                        fuller_ay_chip.write_data(per & 0xFF)
                        fuller_ay_chip.write_address(r_high)
                        fuller_ay_chip.write_data((per >> 8) & 0x0F)

                        v_val = (ev_found['vol'] & 0x0F) | (0x10 if ev_found['use_env'] else 0)
                        fuller_ay_chip.write_address(r_v)
                        fuller_ay_chip.write_data(v_val)
                        if ev_found['use_env'] and abs(ev_found['start_time'] - t0) < 0.0001 and global_env_shape > 0:
                            fuller_ay_chip.write_address(13)
                            fuller_ay_chip.write_data(global_env_shape & 0x0F)

                        m = ev_found['mode']
                        if m in (1, 3):  # Tone enabled
                            r7 &= ~(1 << ch_idx)
                        if m in (2, 3):  # Noise enabled
                            r7 &= ~(1 << (ch_idx + 3))
                    else:
                        fuller_ay_chip.write_address(r_v)
                        fuller_ay_chip.write_data(0)

                # 2. Windows Default MIDI Output (Channels 0..7)
                if windows_midi.enabled:
                    if ev_found and not ev_found['is_rest'] and ev_found.get('midi_enabled', True) and ev_found['vol'] > 0:
                        desired_note = (ev_found['midi_channel'], ev_found['midi_note'])
                        if active_midi_notes[ch_idx] != desired_note:
                            if active_midi_notes[ch_idx] is not None:
                                prev_ch, prev_n = active_midi_notes[ch_idx]
                                windows_midi.note_off(prev_ch, prev_n)
                            windows_midi.note_on(ev_found['midi_channel'], ev_found['midi_note'], ev_found['midi_vel'])
                            active_midi_notes[ch_idx] = desired_note
                    else:
                        if active_midi_notes[ch_idx] is not None:
                            prev_ch, prev_n = active_midi_notes[ch_idx]
                            windows_midi.note_off(prev_ch, prev_n)
                            active_midi_notes[ch_idx] = None

            fuller_ay_chip.write_address(7)
            fuller_ay_chip.write_data(r7)

            # Sleep dt in small chunks, checking for stop or break events
            end_t = time.perf_counter() + dt
            while time.perf_counter() < end_t and not ay_play_stop:
                time.sleep(min(0.008, max(0.0, end_t - time.perf_counter())))
                try:
                    for ev in pygame.event.get([pygame.QUIT, pygame.KEYDOWN]):
                        if ev.type == pygame.QUIT:
                            ay_play_stop = True
                            pygame.event.post(ev)
                            break
                        elif ev.type == pygame.KEYDOWN and ev.key == pygame.K_ESCAPE:
                            ay_play_stop = True
                            break
                except Exception:
                    pass
    finally:
        # Silence all AY channels
        for r_v in reg_vol:
            fuller_ay_chip.write_address(r_v)
            fuller_ay_chip.write_data(0)
        fuller_ay_chip.write_address(7)
        fuller_ay_chip.write_data(0x38)
        # Silence and reset active MIDI notes
        if windows_midi.enabled:
            for ch_idx in range(num_channels):
                if active_midi_notes[ch_idx] is not None:
                    prev_ch, prev_n = active_midi_notes[ch_idx]
                    windows_midi.note_off(prev_ch, prev_n)
                    active_midi_notes[ch_idx] = None
            windows_midi.all_notes_off()
        ay_play_active = False

def handle_play_command(cmd_str=""):
    s = (cmd_str or "").strip()
    s_upper = s.upper()
    if s_upper.startswith("PLAY"):
        s = s[4:].strip()
    if s.startswith(":"): s = s[1:].strip()
    s_clean = s.strip()
    s_upper = s_clean.upper()

    if s_upper in ("/STATUS", "?", "/?", "STATUS", "HELP", "/HELP"):
        canvas_print("ZX Spectrum 128K PLAY & MIDI Subsystem:")
        canvas_print(f"  MIDI Out:     {windows_midi.get_status_string()}")
        canvas_print("  Channels 1-3: Internal AY-3-8912 PSG + MIDI Out")
        canvas_print("  Channels 4-8: Expanded Polyphonic MIDI Out Voices")
        canvas_print("  Syntax: PLAY s1$ [, s2$ ... [, s8$]]")
        canvas_print("  Codes:  Y1..Y16 (Channel) | Z code (MIDI Byte/Patch) | V0..V15 (Velocity)")
        return
    elif s_upper in ("/MIDI", "/MIDI STATUS"):
        canvas_print(f"MIDI Output: {windows_midi.get_status_string()}")
        return
    elif s_upper in ("/MIDI ON", "MIDI ON"):
        windows_midi.enabled = True
        windows_midi.open()
        canvas_print(f"MIDI Output: ENABLED ({windows_midi.device_name})")
        return
    elif s_upper in ("/MIDI OFF", "MIDI OFF"):
        windows_midi.all_notes_off()
        windows_midi.enabled = False
        canvas_print("MIDI Output: DISABLED")
        return
    elif s_upper in ("/MIDI RESET", "MIDI RESET"):
        windows_midi.all_notes_off()
        canvas_print("MIDI Output: Reset (All Notes Off)")
        return

    if not s_clean:
        canvas_print("Syntax: PLAY ch1$ [, ch2$ ... [, ch8$]]")
        return
    parts = split_top_level_commas(s_clean)
    ch_strings = []
    for p in parts[:8]:
        p = p.strip()
        if not p:
            ch_strings.append("")
            continue
        try:
            val = evaluate_expr(p)
            ch_strings.append(str(val))
        except Exception:
            ch_strings.append(p.strip('"\''))
    play_ay_music(ch_strings)


# Fuller Orator SP0256-AL2 Speech
orator_enabled = True
orator_busy_until = 0.0
orator_allophone_buffer = []
orator_raw_codes = []
orator_last_allophone_time = 0.0

def orator_flush_allophones():
    global orator_allophone_buffer, orator_raw_codes
    if not orator_raw_codes and not orator_allophone_buffer:
        return
    seq = tuple(orator_raw_codes)
    if seq in ORATOR_PHRASE_PATTERNS:
        word = ORATOR_PHRASE_PATTERNS[seq]
    else:
        word = "".join(orator_allophone_buffer).strip()
    orator_allophone_buffer = []
    orator_raw_codes = []
    if word and _sp0256_voice:
        try:
            _sp0256_voice.Speak(word, 1)
        except Exception:
            pass

def orator_out_allophone(code):
    global orator_busy_until, orator_allophone_buffer, orator_raw_codes, orator_last_allophone_time
    if not orator_enabled:
        return
    code = int(code) & 0x3F
    dur = 0.010 if code == 0 else (0.025 if code == 1 else (0.045 if code == 2 else (0.096 if code == 3 else (0.198 if code == 4 else 0.050))))
    orator_busy_until = time.time() + dur
    name = SP0256_ALLOPHONE_CODES[code] if code < len(SP0256_ALLOPHONE_CODES) else "PA1"
    if code in (0, 1, 2, 3, 4):
        orator_flush_allophones()
    else:
        orator_raw_codes.append(code)
        phoneme = SP0256_ALLOPHONES.get(name, "")
        if phoneme:
            orator_allophone_buffer.append(phoneme)
            orator_last_allophone_time = time.time()

def orator_in_status():
    global orator_busy_until, orator_allophone_buffer, orator_raw_codes, orator_last_allophone_time
    now = time.time()
    if (orator_allophone_buffer or orator_raw_codes) and (now - orator_last_allophone_time > 0.25):
        orator_flush_allophones()
    if now < orator_busy_until:
        return 128.0
    return 0.0


# ==============================================================================
# Cheetah SpecDrum 8-Bit DAC & Drum Sequencer Emulation
# ==============================================================================
class SpecDrumSubsystem:
    def __init__(self, samples_dir=None):
        self.lock = threading.Lock()
        self.samples_dir = samples_dir or self._find_samples_dir()
        self.kits = {}          # kit_name -> list of drum dicts
        self.kit_info = {}      # kit_name -> description/title
        self.current_kit = "standard"
        self.dac_buffer = bytearray()
        self.dac_last_time = time.time()
        self.last_dac_sounds = []
        self.sound_channels = []
        self._init_channels()
        self.load_all_kits()

    def _find_samples_dir(self):
        candidates = [
            os.path.join(os.path.dirname(os.path.abspath(__file__)), "specdrum_samples"),
            os.path.join(os.getcwd(), "specdrum_samples"),
            r"c:\Users\kfash\Documents\BasinPy\specdrum_samples",
        ]
        for c in candidates:
            if os.path.isdir(c):
                return c
        d = candidates[0]
        try: os.makedirs(d, exist_ok=True)
        except Exception: pass
        return d

    def _init_channels(self):
        try:
            if pygame.mixer.get_init():
                if pygame.mixer.get_num_channels() < 12:
                    pygame.mixer.set_num_channels(12)
                self.sound_channels = [pygame.mixer.Channel(i) for i in (4, 5, 6, 7)]
        except Exception:
            self.sound_channels = []

    def _get_free_channel(self):
        if not self.sound_channels:
            self._init_channels()
        for ch in self.sound_channels:
            if ch and not ch.get_busy():
                return ch
        if self.sound_channels:
            return self.sound_channels[0]
        return None

    def _generate_synthetic_fallback(self, drum_name, drum_num):
        sample_rate = 22050
        durations = {1: 0.15, 2: 0.12, 3: 0.18, 4: 0.22, 5: 0.10, 6: 0.08, 7: 0.16, 8: 0.14}
        dur = durations.get(drum_num, 0.15)
        num_samples = int(sample_rate * dur)
        buf = bytearray(num_samples * 2)
        for i in range(num_samples):
            t = i / sample_rate
            env = max(0.0, 1.0 - t / dur)
            val = 0.0
            if drum_num in (1, 4):
                freq = max(40.0, 180.0 * (env ** 2) if drum_num == 1 else 120.0 * env)
                val = math.sin(2.0 * math.pi * freq * t) * env
            elif drum_num == 2:
                noise = random.uniform(-1.0, 1.0)
                body = math.sin(2.0 * math.pi * 180.0 * t)
                val = (0.7 * noise + 0.3 * body) * (env ** 1.5)
            elif drum_num == 3:
                freq = max(80.0, 220.0 * env)
                val = math.sin(2.0 * math.pi * freq * t) * (env ** 1.2)
            elif drum_num == 5:
                val = (0.5 * math.sin(2.0 * math.pi * 587.0 * t) + 0.5 * math.sin(2.0 * math.pi * 845.0 * t)) * env
            elif drum_num in (6, 7):
                noise = random.uniform(-1.0, 1.0)
                val = noise * (env ** 2.5 if drum_num == 6 else env)
            elif drum_num == 8:
                noise = random.uniform(-1.0, 1.0)
                b_env = env * (1.0 if t > 0.03 else 0.5)
                val = noise * b_env
            s16 = int(max(-32767, min(32767, val * 30000)))
            buf[i*2] = s16 & 0xFF
            buf[i*2+1] = (s16 >> 8) & 0xFF
        try:
            return pygame.mixer.Sound(buffer=bytes(buf))
        except Exception:
            return None

    def load_all_kits(self):
        with self.lock:
            self.kits.clear()
            self.kit_info.clear()
            if not os.path.isdir(self.samples_dir):
                return

            subdirs = [d for d in os.listdir(self.samples_dir) if os.path.isdir(os.path.join(self.samples_dir, d))]
            for d in sorted(subdirs):
                kit_path = os.path.join(self.samples_dir, d)
                kit_key = d.lower().strip()
                drumkit_file = os.path.join(kit_path, "drumkit.txt")
                info_file = os.path.join(kit_path, "info.txt")

                title = d
                if os.path.isfile(info_file):
                    try:
                        with open(info_file, "r", encoding="utf-8", errors="ignore") as inf:
                            first_line = inf.readline().strip()
                            if first_line: title = first_line
                    except Exception:
                        pass
                self.kit_info[kit_key] = title

                drums = []
                if os.path.isfile(drumkit_file):
                    try:
                        with open(drumkit_file, "r", encoding="utf-8", errors="ignore") as f:
                            lines = [ln.strip() for ln in f if ln.strip() and "=" in ln]
                        for idx, ln in enumerate(lines, 1):
                            parts = ln.split("=", 1)
                            raw_name = parts[0].strip()
                            wav_name = parts[1].strip()
                            clean_name = re.sub(r'^\[\d+\]\s*', '', raw_name).strip().upper()
                            wav_path = os.path.join(kit_path, wav_name)
                            snd = None
                            if os.path.isfile(wav_path):
                                try: snd = pygame.mixer.Sound(wav_path)
                                except Exception: pass
                            if not snd:
                                snd = self._generate_synthetic_fallback(clean_name, idx)
                            aliases = [str(idx), clean_name, clean_name.replace(" ", "")]
                            if "KICK" in clean_name or "BASS" in clean_name:
                                aliases.extend(["KICK", "BASS", "BD"])
                            elif "SNARE" in clean_name:
                                aliases.extend(["SNARE", "SD"])
                            elif "MID" in clean_name and "TOM" in clean_name:
                                aliases.extend(["MIDTOM", "MID TOM", "TOM1"])
                            elif "LO" in clean_name and "TOM" in clean_name:
                                aliases.extend(["LOWTOM", "LOW TOM", "TOM2"])
                            elif "COWBELL" in clean_name or "COW" in clean_name:
                                aliases.extend(["COWBELL", "COW", "CB"])
                            elif "HIHAT C" in clean_name or "CLOSED" in clean_name:
                                aliases.extend(["HHCLOSE", "HIHAT_C", "CHH"])
                            elif "HIHAT O" in clean_name or "OPEN" in clean_name or "CYMB" in clean_name:
                                aliases.extend(["HHOPEN", "HIHAT_O", "OHH", "CYMBAL"])
                            elif "CLAP" in clean_name:
                                aliases.extend(["CLAP", "CLAPS", "HANDCLAP"])
                            drums.append({
                                "id": idx,
                                "name": clean_name,
                                "file": wav_name,
                                "aliases": [a.upper() for a in set(aliases)],
                                "sound": snd
                            })
                    except Exception:
                        pass

                if not drums:
                    wav_files = sorted([f for f in os.listdir(kit_path) if f.lower().endswith(".wav")])
                    for idx, wf in enumerate(wav_files, 1):
                        clean_name = os.path.splitext(wf)[0].replace("_", " ").strip().upper()
                        wav_path = os.path.join(kit_path, wf)
                        snd = None
                        if os.path.isfile(wav_path):
                            try: snd = pygame.mixer.Sound(wav_path)
                            except Exception: pass
                        if not snd:
                            snd = self._generate_synthetic_fallback(clean_name, idx)
                        aliases = [str(idx), clean_name, clean_name.replace(" ", "")]
                        drums.append({
                            "id": idx,
                            "name": clean_name,
                            "file": wf,
                            "aliases": [a.upper() for a in set(aliases)],
                            "sound": snd
                        })

                if drums:
                    self.kits[kit_key] = drums

            if "standard" in self.kits:
                self.current_kit = "standard"
            elif self.kits:
                self.current_kit = list(self.kits.keys())[0]

    def set_kit(self, kit_name):
        with self.lock:
            k = kit_name.lower().strip()
            if k in self.kits:
                self.current_kit = k
                return True, k, self.kit_info.get(k, k)
            for name in self.kits:
                if k in name:
                    self.current_kit = name
                    return True, name, self.kit_info.get(name, name)
            return False, k, None

    def play_drum(self, drum_arg, volume=1.0):
        with self.lock:
            if not self.kits or self.current_kit not in self.kits:
                return False, "No SpecDrum kits loaded"
            drums = self.kits[self.current_kit]

            matched_drum = None
            if isinstance(drum_arg, (int, float)):
                d_num = int(drum_arg)
                for d in drums:
                    if d["id"] == d_num:
                        matched_drum = d
                        break
            else:
                s = str(drum_arg).strip().upper().replace('"', '').replace("'", "")
                if s.isdigit():
                    d_num = int(s)
                    for d in drums:
                        if d["id"] == d_num:
                            matched_drum = d
                            break
                if not matched_drum:
                    for d in drums:
                        if s in d["aliases"] or s == d["name"] or s == d["name"].replace(" ", ""):
                            matched_drum = d
                            break
                if not matched_drum:
                    for d in drums:
                        if any(s in a for a in d["aliases"]):
                            matched_drum = d
                            break

            if matched_drum and matched_drum["sound"]:
                try:
                    vol = max(0.0, min(1.0, float(volume)))
                    matched_drum["sound"].set_volume(vol)
                    ch = self._get_free_channel()
                    if ch:
                        ch.play(matched_drum["sound"])
                    else:
                        matched_drum["sound"].play()
                    return True, f"Playing {matched_drum['name']}"
                except Exception as e:
                    return False, f"Sound play error: {e}"
            return False, f"Unknown drum: {drum_arg}"

    def install_kit(self, source_path, kit_name=None):
        src = source_path.strip().strip('"').strip("'")
        if not os.path.exists(src):
            return False, f"Source path not found: {src}"

        if not kit_name:
            base = os.path.splitext(os.path.basename(src))[0].lower()
            kit_name = re.sub(r'[^a-z0-9_]', '_', base).strip('_')

        target_dir = os.path.join(self.samples_dir, kit_name)
        os.makedirs(target_dir, exist_ok=True)

        count = 0
        if zipfile.is_zipfile(src):
            try:
                with zipfile.ZipFile(src, 'r') as zf:
                    for member in zf.infolist():
                        if not member.is_dir() and member.filename.lower().endswith(('.wav', '.txt')):
                            fname = os.path.basename(member.filename)
                            if fname:
                                with zf.open(member) as sf, open(os.path.join(target_dir, fname), 'wb') as df:
                                    shutil.copyfileobj(sf, df)
                                    if fname.lower().endswith('.wav'): count += 1
            except Exception as e:
                return False, f"Error extracting zip: {e}"
        elif os.path.isdir(src):
            try:
                for root, _, files in os.walk(src):
                    for f in files:
                        if f.lower().endswith(('.wav', '.txt')):
                            shutil.copy2(os.path.join(root, f), os.path.join(target_dir, f))
                            if f.lower().endswith('.wav'): count += 1
            except Exception as e:
                return False, f"Error copying files: {e}"
        else:
            if src.lower().endswith('.wav'):
                try:
                    shutil.copy2(src, os.path.join(target_dir, os.path.basename(src)))
                    count += 1
                except Exception as e:
                    return False, f"Error copying file: {e}"

        if count == 0:
            return False, f"No .WAV audio samples found in {src}"

        self.load_all_kits()
        self.set_kit(kit_name)
        return True, f"Installed kit '{kit_name}' with {count} sample(s)."

    def write_dac(self, val):
        """Hardware emulation of Cheetah SpecDrum 8-bit DAC on Port 223 (0xDF)."""
        val = int(val) & 0xFF
        now = time.time()
        if 1 <= val <= 8 and (not self.dac_buffer or now - self.dac_last_time > 0.025):
            if self.dac_buffer:
                with self.lock:
                    self._flush_dac()
            self.play_drum(val)
            self.dac_last_time = now
            return
        with self.lock:
            self.dac_buffer.append(val)
            if len(self.dac_buffer) >= 256 or (self.dac_buffer and now - self.dac_last_time > 0.025):
                self._flush_dac()
            self.dac_last_time = now

    def _flush_dac(self):
        if not self.dac_buffer:
            return
        # Discard undersized buffers (< 128 samples) to prevent SDL_mixer from
        # crashing with a segmentation fault on runt audio chunks
        if len(self.dac_buffer) < 128:
            self.dac_buffer.clear()
            return
        data = bytes(self.dac_buffer)
        self.dac_buffer.clear()
        try:
            out_pcm = bytearray(len(data) * 2)
            for i, b in enumerate(data):
                s16 = int((b - 128) * 256)
                out_pcm[i*2] = s16 & 0xFF
                out_pcm[i*2+1] = (s16 >> 8) & 0xFF
            snd = pygame.mixer.Sound(buffer=bytes(out_pcm))
            self.last_dac_sounds.append(snd)
            if len(self.last_dac_sounds) > 16:
                self.last_dac_sounds.pop(0)
            ch = self.sound_channels[3] if len(self.sound_channels) > 3 else self._get_free_channel()
            if ch:
                if ch.get_busy() and ch.get_queue() is None:
                    ch.queue(snd)
                else:
                    ch.play(snd)
            else:
                snd.play()
        except Exception:
            pass

    def reset(self):
        with self.lock:
            self.dac_buffer.clear()
            self.last_dac_sounds.clear()
            for ch in self.sound_channels:
                try:
                    if ch and ch.get_busy(): ch.stop()
                except Exception: pass

specdrum_subsystem = SpecDrumSubsystem()


def handle_specdrum_command(cmd_str=""):
    global specdrum_subsystem
    s = (cmd_str or "").strip()
    s_upper = s.upper()

    if s_upper.startswith("SPECDRUM"):
        s = s[8:].strip()
    elif s_upper.startswith("DRUM"):
        s = s[4:].strip()

    if s.startswith(":"):
        s = s[1:].strip()

    s = s.strip()
    s_upper = s.upper()

    if not s or s_upper in ("?", "/?", "HELP", "/HELP", "STATUS", "/STATUS"):
        canvas_print("--- CHEETAH SPECDRUM 8-BIT DRUM SYSTEM ---")
        canvas_print(f"Active Kit: {specdrum_subsystem.current_kit.upper()} ({specdrum_subsystem.kit_info.get(specdrum_subsystem.current_kit, '')})")
        canvas_print("Commands & Switches:")
        canvas_print("  DRUM <num|name> [, vol] : Play drum sound (1-8 or name)")
        canvas_print("  SPECDRUM /KIT <name>    : Select active kit")
        canvas_print("  SPECDRUM /INSTALL <path>: Install new sample pack")
        canvas_print("  SPECDRUM /LIST          : List all kits and sounds")
        canvas_print("  OUT 223, byte           : Direct 8-bit DAC output")
        update_display()
        return

    if s_upper.startswith("/KIT") or s_upper.startswith("KIT"):
        arg = s[4:].strip() if s_upper.startswith("/KIT") else s[3:].strip()
        arg = arg.strip().strip('"').strip("'")
        ok, k_name, title = specdrum_subsystem.set_kit(arg)
        if ok:
            canvas_print(f"SPECDRUM KIT: {k_name.upper()} ({title})")
        else:
            canvas_print(f"Kit not found: {arg}")
            canvas_print(f"Available kits: {', '.join(specdrum_subsystem.kits.keys()).upper()}")
        update_display()
        return

    if s_upper.startswith("/LIST") or s_upper.startswith("LIST"):
        canvas_print("--- SPECDRUM INSTALLED KITS ---")
        for k in sorted(specdrum_subsystem.kits.keys()):
            marker = "* " if k == specdrum_subsystem.current_kit else "  "
            title = specdrum_subsystem.kit_info.get(k, k)
            canvas_print(f"{marker}{k.upper()}: {title}")
        canvas_print(f"\nActive Kit Sounds ({specdrum_subsystem.current_kit.upper()}):")
        cur_drums = specdrum_subsystem.kits.get(specdrum_subsystem.current_kit, [])
        for d in cur_drums:
            canvas_print(f"  [{d['id']}] {d['name']:<12} ({d['file']})")
        update_display()
        return

    if s_upper.startswith("/INSTALL") or s_upper.startswith("INSTALL"):
        raw_args = s[8:].strip() if s_upper.startswith("/INSTALL") else s[7:].strip()
        parts = [p.strip().strip('"').strip("'") for p in raw_args.split(",") if p.strip()]
        if not parts:
            canvas_print("Syntax: SPECDRUM /INSTALL \"source_path_or_zip\" [, \"kit_name\"]")
            update_display()
            return
        src_path = parts[0]
        k_name = parts[1] if len(parts) > 1 else None
        ok, msg = specdrum_subsystem.install_kit(src_path, k_name)
        canvas_print(msg)
        update_display()
        return

    if s_upper.startswith("/RESET") or s_upper.startswith("RESET"):
        specdrum_subsystem.set_kit("standard")
        canvas_print("SPECDRUM: Reset to Standard Kit")
        update_display()
        return

    parts = [p.strip() for p in s.split(",") if p.strip()]
    drum_target = parts[0]
    vol = 1.0
    if len(parts) > 1:
        try:
            vol = float(evaluate_expr(parts[1]))
        except Exception:
            vol = 1.0

    try:
        evaluated = evaluate_expr(drum_target)
        drum_target = evaluated
    except Exception:
        pass

    ok, msg = specdrum_subsystem.play_drum(drum_target, vol)
    if not ok:
        canvas_print(f"SpecDrum: {msg}")
        update_display()


class ZXBeeperAudio:
    """
    Cycle-accurate ZX Spectrum 48K beeper audio synthesizer (Port 254 bits 4 & 3).
    Accurately synthesizes square wave tones, pitch sweeps, white noise, and PWM /
    multi-channel music directly from Z80 T-state transitions.
    Includes authentic analog speaker RC low-pass filtering (~3.5 kHz) and DC-blocking,
    turning pulse-frequency modulation (e.g. Ark of Yesod / Odin synthesizer, Dinamic PWM)
    into smooth, rich analog synth audio without clicky digital artifacts or chunk jitter.
    Includes dynamic emulation-rate synchronization to eliminate buffer underruns.
    """
    def __init__(self, sample_rate=44100):
        self.clock = 3500000.0  # ZX Spectrum 48K CPU clock (3.5 MHz)
        self.sample_rate = sample_rate
        self.channels = 2
        self.last_cycle = 0
        self.last_amp = 0
        self.frame_events = []
        self.frame_start_cycle = 0
        self.last_frame_time = time.perf_counter()
        self.buffer = array.array('h')
        self.sound_channel = None

        # Authentic ZX Spectrum 48K analog speaker RC low-pass filter (~3.5 kHz) & DC blocker
        fc = 3500.0
        dt = 1.0 / self.sample_rate
        self.lpf_alpha = (2.0 * math.pi * fc * dt) / (1.0 + 2.0 * math.pi * fc * dt)
        self.lpf_y = 0.0
        self.dc_x_prev = 0.0
        self.dc_y_prev = 0.0
        self.dc_R = 0.995

        # 4-level DAC: (EAR=0/MIC=0, EAR=0/MIC=1, EAR=1/MIC=0, EAR=1/MIC=1)
        self.dac_levels = (0, 3000, 10000, 13000)
        self._init_channel()

    def _init_channel(self):
        try:
            if 'pygame' in globals() and pygame.mixer.get_init():
                mix = pygame.mixer.get_init()
                self.sample_rate = mix[0]
                self.channels = mix[2]
                dt = 1.0 / self.sample_rate
                self.lpf_alpha = (2.0 * math.pi * 3500.0 * dt) / (1.0 + 2.0 * math.pi * 3500.0 * dt)
                if pygame.mixer.get_num_channels() < 8:
                    pygame.mixer.set_num_channels(8)
                self.sound_channel = pygame.mixer.Channel(2)
        except Exception:
            self.sound_channel = None

    def reset(self):
        self.last_cycle = 0
        self.last_amp = 0
        self.frame_events.clear()
        self.frame_start_cycle = 0
        self.last_frame_time = time.perf_counter()
        self.buffer = array.array('h')
        self.lpf_y = 0.0
        self.dc_x_prev = 0.0
        self.dc_y_prev = 0.0
        try:
            if self.sound_channel and self.sound_channel.get_busy():
                self.sound_channel.stop()
        except Exception:
            pass

    def write_speaker(self, val, current_cycle):
        if os.environ.get("SDL_AUDIODRIVER") == "dummy":
            self.last_cycle = current_cycle
            return
        if not self.sound_channel:
            self._init_channel()
            if not self.sound_channel:
                self.last_cycle = current_cycle
                return

        ear = (val >> 4) & 1
        mic = (val >> 3) & 1
        raw_amp = self.dac_levels[(ear * 2) + mic]

        if current_cycle < self.frame_start_cycle:
            self.frame_start_cycle = current_cycle
            self.frame_events.clear()

        if raw_amp != self.last_amp:
            self.frame_events.append((current_cycle - self.frame_start_cycle, raw_amp))
            self.last_amp = raw_amp

    def flush_frame(self, current_cycle):
        if os.environ.get("SDL_AUDIODRIVER") == "dummy":
            self.last_cycle = current_cycle
            self.frame_events.clear()
            self.frame_start_cycle = current_cycle
            return
        if not self.sound_channel:
            self._init_channel()
            if not self.sound_channel:
                self.last_cycle = current_cycle
                self.frame_events.clear()
                self.frame_start_cycle = current_cycle
                return

        if current_cycle < self.frame_start_cycle:
            self.frame_start_cycle = current_cycle
            self.frame_events.clear()
            return

        now = time.perf_counter()
        dt_wall = max(0.018, min(0.090, now - self.last_frame_time))
        self.last_frame_time = now

        total_cycles = max(1, current_cycle - self.frame_start_cycle)
        self.frame_start_cycle = current_cycle

        n_samples = int(dt_wall * self.sample_rate)
        if n_samples <= 0:
            self.frame_events.clear()
            return

        events = self.frame_events
        n_evts = len(events)
        cycles_per_sample = total_cycles / float(n_samples)

        alpha = self.lpf_alpha
        lpf_y = self.lpf_y
        dc_x_prev = self.dc_x_prev
        dc_y_prev = self.dc_y_prev
        R = self.dc_R
        ch = self.channels
        buf = self.buffer

        cur_evt_idx = 0
        cur_amp = self.last_amp
        if events and events[0][0] <= 0:
            cur_amp = events[0][1]
            cur_evt_idx = 1

        for s_idx in range(n_samples):
            s_start = s_idx * cycles_per_sample
            s_end = (s_idx + 1) * cycles_per_sample

            accum = 0.0
            pos = s_start
            while cur_evt_idx < n_evts and events[cur_evt_idx][0] < s_end:
                evt_cyc, next_amp = events[cur_evt_idx]
                if evt_cyc > pos:
                    accum += (evt_cyc - pos) * cur_amp
                    pos = evt_cyc
                cur_amp = next_amp
                cur_evt_idx += 1
            accum += (s_end - pos) * cur_amp

            target_amp = accum / cycles_per_sample
            lpf_y += alpha * (target_amp - lpf_y)
            dc_y = lpf_y - dc_x_prev + R * dc_y_prev
            dc_x_prev = lpf_y
            dc_y_prev = dc_y

            s = int(dc_y * 2.5)
            if s > 32000: s = 32000
            elif s < -32000: s = -32000
            buf.append(s)
            if ch == 2:
                buf.append(s)

        self.lpf_y = lpf_y
        self.dc_x_prev = dc_x_prev
        self.dc_y_prev = dc_y_prev
        self.frame_events.clear()

        chunk_frames = int(self.sample_rate * 0.02)
        chunk_size = chunk_frames * self.channels
        if len(self.buffer) > chunk_size * 8:
            self.buffer = self.buffer[-(chunk_size * 4):]

        self._push_chunks()

    def _push_chunks(self):
        chunk_frames = int(self.sample_rate * 0.02)  # Exactly 20ms frame
        chunk_size = chunk_frames * self.channels
        while len(self.buffer) >= chunk_size:
            if self.sound_channel and self.sound_channel.get_busy() and self.sound_channel.get_queue() is not None:
                break
            chunk = self.buffer[:chunk_size]
            self.buffer = self.buffer[chunk_size:]
            if self.sound_channel:
                try:
                    snd = pygame.mixer.Sound(buffer=chunk.tobytes())
                    if not self.sound_channel.get_busy():
                        self.sound_channel.play(snd)
                    else:
                        self.sound_channel.queue(snd)
                except Exception:
                    pass


zx_beeper_audio = ZXBeeperAudio()


def handle_out_port(port, val):
    global current_border, amx_pio_ctrl_a, amx_pio_ctrl_b, timex_dock_bank_select, timex_timer_interrupt_enabled, timex_port_f4, timex_ay_selected_reg, timex_port_255
    port16 = port & 0xFFFF
    port8 = port & 0xFF
    val &= 0xFF

    # Timex Sinclair 2068 Port 255 (0xFF): Display Mode & Hi-Res Palette Control
    if port8 == 255:
        timex_dock_bank_select = 1 if (val & 0x80) else 0
        timex_timer_interrupt_enabled = bool(val & 0x40)
        set_timex_mode(val & 7, (val >> 3) & 7, raw_val=val)
        update_timex_mmu(timex_port_f4, timex_dock_bank_select)

    # Timex Sinclair 2068 Port 244 (0xF4): Memory Bank Paging (DOCK / EX-ROM)
    elif port8 == 244:
        update_timex_mmu(val, timex_dock_bank_select)

    # Timex Sinclair 2068 Port 245 (0xF5): AY-3-8912 PSG Register Select
    elif port8 == 245:
        globals()['timex_ay_selected_reg'] = val & 0x0F
        if 'fuller_ay_chip' in globals() and fuller_ay_chip:
            fuller_ay_chip.write_address(val & 0x0F)

    # Timex Sinclair 2068 Port 246 (0xF6): AY-3-8912 PSG Register Data Write
    elif port8 == 246:
        if 'fuller_ay_chip' in globals() and fuller_ay_chip:
            fuller_ay_chip.write_data(val & 0xFF)

    # WD1793 / KR1818VG93 (TR-DOS / Beta Disk)
    if 'active_disk_system' in globals() and (active_disk_system in ("TRD", "BETA") or port8 in (0x1F, 0xFF)):
        if port8 == 0x1F:
            handle_wd1793_command(val)
        elif port8 == 0x3F and not ('fuller_ay_chip' in globals() and fuller_ay_chip and getattr(fuller_ay_chip, 'current_mode', '') == 'FULLER'):
            globals()['wd1793_track'] = val & 0xFF
        elif port8 == 0x5F:
            globals()['wd1793_sector'] = max(1, val & 0x1F)
        elif port8 == 0x7F:
            handle_wd1793_data_write(val)
        elif port8 == 0xFF and ('active_disk_system' in globals() and active_disk_system in ("TRD", "BETA")):
            handle_wd1793_system_out(val)

    # WD1770 (Opus Discovery)
    if 'active_disk_system' in globals() and (active_disk_system == "OPUS" or port8 in (0x38, 0x39, 0x3A, 0x3B, 0xEE, 0xEF)):
        if port8 == 0x38:
            handle_wd1770_command(val)
        elif port8 == 0x39:
            globals()['wd1770_track'] = val & 0xFF
        elif port8 == 0x3A:
            globals()['wd1770_sector'] = max(1, val & 0x1F)
        elif port8 == 0x3B:
            globals()['wd1770_data'] = val & 0xFF
        elif port8 in (0xEE, 0xEF):
            globals()['opus_drive_ctrl'] = val & 0xFF

    if port8 == 254:
        current_border = val & 7
        memory[23624] = current_border
        if 'zx_beeper_audio' in globals() and zx_beeper_audio is not None:
            cyc = getattr(z80_cpu, 'cycles', 0) if ('z80_cpu' in globals() and z80_cpu is not None) else 0
            zx_beeper_audio.write_speaker(val, cyc)
    # Sinclair 128K AY Register Address Select: Port 65533 (0xFFFD)
    elif spectrum_128k_mode and (port16 == 65533 or (port8 == 253 and (port16 & 0xC002) == 0xC000)):
        fuller_ay_chip.write_address(val)
    # Sinclair 128K AY Register Data Write: Port 49149 (0xBFFD)
    elif spectrum_128k_mode and (port16 == 49149 or (port8 == 253 and (port16 & 0xC002) == 0x8000)):
        fuller_ay_chip.write_data(val)
    # Sinclair 128K Memory Paging Register: Port 32765 (0x7FFD)
    elif spectrum_128k_mode and (port16 == 32765 or (port8 == 253 and (port16 & 0xC002) == 0x4000)):
        handle_128k_paging_out(val)
    # Sinclair ZX Spectrum +3 Memory Paging Register: Port 8189 (0x1FFD)
    elif plus3_mode and (port16 == 8189 or (port16 & 0xF002) == 0x1000):
        handle_plus3_paging_out(val)
    # Sinclair ZX Spectrum +3 Floppy Disk Controller Data: Port 16381 (0x3FFD)
    elif plus3_mode and (port16 == 16381 or (port16 & 0xF002) == 0x3000):
        pass
    elif port8 == 63:  # Fuller Master Unit AY-3-8912 Register Address Select
        fuller_ay_chip.write_address(val)
    elif port8 == 95:  # Fuller Master Unit AY-3-8912 Register Data Write
        fuller_ay_chip.write_data(val)
        if amx_enabled:
            amx_pio_ctrl_a = val
    elif port8 == 127:  # Fuller Master Unit Orator Speech SP0256-AL2 Allophone Output
        orator_out_allophone(val & 0x3F)
        if amx_enabled:
            amx_pio_ctrl_b = val
    elif port8 == 223:  # Cheetah SpecDrum 8-Bit DAC Output
        specdrum_subsystem.write_dac(val)
    # Spectranext UART Data: Port #143B (5179)
    elif port8 == 0x3B and ((port16 >> 8) & 0xFF) == 0x14:
        if 'spectranext_subsystem' in globals() and spectranext_subsystem:
            spectranext_subsystem.write_uart_data(val)
    # Spectranext UART Control: Port #153B (5435)
    elif port8 == 0x3B and ((port16 >> 8) & 0xFF) == 0x15:
        if 'spectranext_subsystem' in globals() and spectranext_subsystem:
            spectranext_subsystem.write_uart_ctrl(val)
    # Spectranet CPLD Paging Port: Port #003B (59)
    elif port8 == 0x3B:
        if 'spectranet_subsystem' in globals() and spectranet_subsystem:
            spectranet_subsystem.handle_cpld_out(val)
        elif currah_enabled:
            currah_out_allophone(val & 0x3F)
    elif currah_enabled and (port8 in (56, 59) or port16 in (9275, 9531)):
        currah_out_allophone(val & 0x3F)
    else:
        pass


def get_floating_bus_byte():
    if 'z80_cpu' not in globals() or z80_cpu is None:
        return 0xFF
    frame_t = getattr(z80_cpu, 'frame_tstates', 69888)
    line_t = 228 if getattr(z80_cpu, 'plus3_mode', False) else 224
    cyc = getattr(z80_cpu, 'cycles', 0) % frame_t
    line = cyc // line_t
    cycle_in_line = cyc % line_t

    # Visible display scanlines 64..255, first 128 T-states of scanline
    if 64 <= line < 256 and cycle_in_line < 128:
        scr_y = line - 64
        col = cycle_in_line // 4
        sub = cycle_in_line % 4
        if spectrum_128k_mode and current_shadow_screen:
            vram = ram_banks[7]
        elif 'current_slot_banks' in globals() and current_slot_banks[1] == 5:
            vram = memory[16384:23296]
        else:
            vram = ram_banks[5]
        if sub < 2:
            # Bitmap byte
            third = scr_y // 64
            row_in_third = (scr_y % 64) // 8
            line_in_row = scr_y % 8
            offset = (third * 2048) + (row_in_third * 32) + (line_in_row * 256) + col
        else:
            # Attribute byte
            offset = 6144 + ((scr_y // 8) * 32) + col
        if 0 <= offset < len(vram):
            return vram[offset]
    return 0xFF


def read_in_port(port):
    global current_mouse_mode
    port16 = port & 0xFFFF
    port8 = port & 0xFF
    hi = (port16 >> 8) & 0xFF

    # WD1793 / KR1818VG93 (TR-DOS / Beta Disk)
    if 'active_disk_system' in globals() and (active_disk_system in ("TRD", "BETA") or port8 in (0x1F, 0x3F, 0x5F, 0x7F, 0xFF)):
        if port8 == 0x1F:
            return float(get_wd1793_status())
        elif port8 == 0x3F and not ('fuller_ay_chip' in globals() and fuller_ay_chip and getattr(fuller_ay_chip, 'current_mode', '') == 'FULLER'):
            return float(globals().get('wd1793_track', 0))
        elif port8 == 0x5F:
            return float(globals().get('wd1793_sector', 1))
        elif port8 == 0x7F:
            return float(handle_wd1793_data_read())
        elif port8 == 0xFF:
            if 'active_disk_system' in globals() and active_disk_system in ("TRD", "BETA"):
                return float(0xC0)
            return float(timex_port_255)

    # WD1770 (Opus Discovery)
    if 'active_disk_system' in globals() and (active_disk_system == "OPUS" or port8 in (0x38, 0x39, 0x3A, 0x3B, 0xEE, 0xEF)):
        if port8 == 0x38:
            return float(get_wd1770_status())
        elif port8 == 0x39:
            return float(globals().get('wd1770_track', 0))
        elif port8 == 0x3A:
            return float(globals().get('wd1770_sector', 1))
        elif port8 == 0x3B:
            return float(handle_wd1770_data_read())

    # Spectranext UART Data: Port #143B (5179)
    if port8 == 0x3B and hi == 0x14:
        if 'spectranext_subsystem' in globals() and spectranext_subsystem:
            return float(spectranext_subsystem.read_uart_data())
    # Spectranext UART Status: Port #153B (5435)
    if port8 == 0x3B and hi == 0x15:
        if 'spectranext_subsystem' in globals() and spectranext_subsystem:
            return float(spectranext_subsystem.read_uart_status())
    # Spectranet CPLD Paging Port: Port #003B (59)
    if port8 == 0x3B:
        if 'spectranet_subsystem' in globals() and spectranet_subsystem:
            return float(spectranet_subsystem.handle_cpld_in())

    # Sinclair 128K AY Register Data Read: Port 65533 (0xFFFD)
    if spectrum_128k_mode and (port16 == 65533 or (port8 == 253 and (port16 & 0xC002) == 0xC000)):
        return float(fuller_ay_chip.read_data())
    # Sinclair 128K Memory Paging Read: Port 32765 (0x7FFD)
    if spectrum_128k_mode and (port16 == 32765 or (port8 == 253 and (port16 & 0xC002) == 0x4000)):
        return float(last_7ffd_val)
    # Sinclair ZX Spectrum +3 Memory Paging Read: Port 8189 (0x1FFD)
    if plus3_mode and (port16 == 8189 or (port16 & 0xF002) == 0x1000):
        return float(last_1ffd_val)
    # Sinclair ZX Spectrum +3 Floppy Disk Controller (uPD765A) Ports:
    # Port 12285 (0x2FFD) = Main Status Register (MSR)
    if plus3_mode and (port16 == 12285 or (port16 & 0xF002) == 0x2000):
        return float(0x80 if plus3_disk_motor else 0x00)
    # Port 16381 (0x3FFD) = FDC Data Register
    if plus3_mode and (port16 == 16381 or (port16 & 0xF002) == 0x3000):
        return float(get_floating_bus_byte())

    # Kempston Mouse ports (Port #FBDF = 64479 X, Port #FFDF = 65503 Y, Port #FADF = 64223 Buttons)
    if port16 == 64479 or (current_mouse_mode == "KEMP" and port8 == 223 and hi == 0xFB):
        sync_amx_mouse_state()
        return float(amx_x & 0xFF)
    if port16 in (65503, 16351) or (current_mouse_mode == "KEMP" and port8 == 223 and hi in (0xFF, 0x3F)):
        sync_amx_mouse_state()
        return float(max(0, min(255, 191 - amx_y)))
    if port16 == 64223 or (current_mouse_mode == "KEMP" and port8 == 223 and hi == 0xFA):
        sync_amx_mouse_state()
        val = 0xFF
        if amx_btn_right: val &= ~0x01
        if amx_btn_left:  val &= ~0x02
        if amx_btn_middle: val &= ~0x04
        return float(val)

    if port8 == 63:  # Fuller Master Unit AY-3-8912 Data Read / AMX Mouse Y
        if current_mouse_mode == "AMX" and amx_enabled and amx_delta_y != 0:
            sync_amx_mouse_state()
            return float(1 if amx_delta_y < 0 else 0)
        return float(fuller_ay_chip.read_data())
    if port8 == 95:  # Fuller Master Unit AY-3-8912 Data Read
        return float(fuller_ay_chip.read_data())
    if port8 == 127:  # Fuller Master Unit: Orator Speech Status (bit 7) / Fuller Joystick
        if current_joystick_mode.upper() == "FULR":
            val = 0xFF
            if joystick:
                try:
                    s = get_joypad_state(joystick)
                    if s["up"]: val &= ~0x01     # Bit 0: Up
                    if s["down"]: val &= ~0x02   # Bit 1: Down
                    if s["left"]: val &= ~0x04   # Bit 2: Left
                    if s["right"]: val &= ~0x08  # Bit 3: Right
                    btn0 = joystick.get_button(0) if joystick.get_numbuttons() > 0 else False
                    btn1 = joystick.get_button(1) if joystick.get_numbuttons() > 1 else False
                    if btn0 or (s["fire"] and not btn1):
                        val &= ~0x80             # Bit 7: Fire 1
                    if btn1:
                        val &= ~0x20             # Bit 5: Fire 2
                except Exception:
                    pass
            return float(val)
        else:
            return orator_in_status()
    if currah_enabled and (port8 in (56, 59) or port16 in (9275, 9531)):
        return currah_in_status()
    if port8 == 223:  # Port 223: AMX or Kempston Mouse Buttons
        sync_amx_mouse_state()
        if current_mouse_mode == "KEMP":
            val = 0xFF
            if amx_btn_right: val &= ~0x01
            if amx_btn_left:  val &= ~0x02
            if amx_btn_middle: val &= ~0x04
            return float(val)
        else:
            if amx_enabled:
                return amx_read_buttons_port()
    if port8 == 31:  # Kempston Joystick Interface (Port 31 / 0x1F) & AMX Mouse X direction
        sync_amx_mouse_state()
        if current_mouse_mode == "AMX" and amx_enabled and amx_delta_x != 0:
            return float(1 if amx_delta_x > 0 else 0)
        if current_joystick_mode.upper() == "KEMP" and joystick:
            val = 0
            try:
                s = get_joypad_state(joystick)
                if s["right"]: val |= 1
                if s["left"]: val |= 2
                if s["down"]: val |= 4
                if s["up"]: val |= 8
                if s["fire"]: val |= 16
            except Exception:
                pass
            return float(val)
    elif port8 == 244:  # Timex Port 0xF4: Memory Paging Status
        return float(timex_port_f4)
    elif port8 == 245:  # Timex Port 0xF5: AY Register Select Status
        return float(timex_ay_selected_reg)
    elif port8 == 246:  # Timex Port 0xF6: AY Register Read / Joystick (Register 14)
        if timex_ay_selected_reg == 14:
            p_num = 2 if (hi & 0x02) else 1
            mask = 0xFF
            dir_val = int(evaluate_timex_stick(p_num, 1))
            fire_val = int(evaluate_timex_stick(p_num, 2))
            if dir_val & 1: mask &= ~0x01
            if dir_val & 2: mask &= ~0x02
            if dir_val & 4: mask &= ~0x04
            if dir_val & 8: mask &= ~0x08
            if fire_val & 128: mask &= ~0x80
            return float(mask)
        else:
            if 'fuller_ay_chip' in globals() and fuller_ay_chip:
                return float(fuller_ay_chip.read_data())
            return 255.0
    elif port8 == 47:   # Port 0x2F: Portuguese TC2048 / TC2068 Joystick Port 2
        val = 0
        dir_val = int(evaluate_timex_stick(2, 1))
        fire_val = int(evaluate_timex_stick(2, 2))
        if dir_val & 8: val |= 1
        if dir_val & 4: val |= 2
        if dir_val & 2: val |= 4
        if dir_val & 1: val |= 8
        if fire_val & 128: val |= 16
        return float(val)
    elif port8 == 255:
        return float(timex_port_255)
    elif port8 == 254:
        res = 255
        if 'universal_tape_player' in globals() and universal_tape_player.active and 'z80_cpu' in globals():
            ear = universal_tape_player.sample_ear(z80_cpu)
            if ear == 0:
                res &= ~0x40
        hi = (port16 >> 8) & 0xFF
        try:
            if 'pygame' in globals() and pygame.get_init():
                keys = pygame.key.get_pressed()
                if (hi & 0x01) == 0 or hi == 0:
                    if keys[pygame.K_LSHIFT] or keys[pygame.K_RSHIFT]: res &= ~0x01
                    if keys[pygame.K_z]: res &= ~0x02
                    if keys[pygame.K_x]: res &= ~0x04
                    if keys[pygame.K_c]: res &= ~0x08
                    if keys[pygame.K_v]: res &= ~0x10
                if (hi & 0x02) == 0 or hi == 0:
                    if keys[pygame.K_a]: res &= ~0x01
                    if keys[pygame.K_s]: res &= ~0x02
                    if keys[pygame.K_d]: res &= ~0x04
                    if keys[pygame.K_f]: res &= ~0x08
                    if keys[pygame.K_g]: res &= ~0x10
                if (hi & 0x04) == 0 or hi == 0:
                    if keys[pygame.K_q]: res &= ~0x01
                    if keys[pygame.K_w]: res &= ~0x02
                    if keys[pygame.K_e]: res &= ~0x04
                    if keys[pygame.K_r]: res &= ~0x08
                    if keys[pygame.K_t]: res &= ~0x10
                if (hi & 0x08) == 0 or hi == 0:
                    if keys[pygame.K_1] or keys[pygame.K_KP_1] or keys[pygame.K_END]: res &= ~0x01
                    if keys[pygame.K_2] or keys[pygame.K_KP_2]: res &= ~0x02
                    if keys[pygame.K_3] or keys[pygame.K_KP_3] or keys[pygame.K_PAGEDOWN]: res &= ~0x04
                    if keys[pygame.K_4] or keys[pygame.K_KP_4]: res &= ~0x08
                    if keys[pygame.K_5] or keys[pygame.K_KP_5] or keys[pygame.K_LEFT]: res &= ~0x10
                if (hi & 0x10) == 0 or hi == 0:
                    if keys[pygame.K_0] or keys[pygame.K_KP_0] or keys[pygame.K_INSERT]: res &= ~0x01
                    if keys[pygame.K_9] or keys[pygame.K_KP_9] or keys[pygame.K_PAGEUP]: res &= ~0x02
                    if keys[pygame.K_8] or keys[pygame.K_KP_8] or keys[pygame.K_RIGHT]: res &= ~0x04
                    if keys[pygame.K_7] or keys[pygame.K_KP_7] or keys[pygame.K_UP] or keys[pygame.K_HOME]: res &= ~0x08
                    if keys[pygame.K_6] or keys[pygame.K_KP_6] or keys[pygame.K_DOWN]: res &= ~0x10
                if (hi & 0x20) == 0 or hi == 0:
                    if keys[pygame.K_p]: res &= ~0x01
                    if keys[pygame.K_o]: res &= ~0x02
                    if keys[pygame.K_i]: res &= ~0x04
                    if keys[pygame.K_u]: res &= ~0x08
                    if keys[pygame.K_y]: res &= ~0x10
                if (hi & 0x40) == 0 or hi == 0:
                    if keys[pygame.K_RETURN] or keys[pygame.K_KP_ENTER]: res &= ~0x01
                    if keys[pygame.K_l]: res &= ~0x02
                    if keys[pygame.K_k]: res &= ~0x04
                    if keys[pygame.K_j]: res &= ~0x08
                    if keys[pygame.K_h]: res &= ~0x10
                if (hi & 0x80) == 0 or hi == 0:
                    if keys[pygame.K_SPACE]: res &= ~0x01
                    if keys[pygame.K_LCTRL] or keys[pygame.K_RCTRL] or keys[pygame.K_LALT] or keys[pygame.K_RALT]: res &= ~0x02
                    if keys[pygame.K_m]: res &= ~0x04
                    if keys[pygame.K_n]: res &= ~0x08
                    if keys[pygame.K_b]: res &= ~0x10
        except Exception:
            pass
        j_keys = get_joystick_pressed_keys()
        if j_keys:
            if (hi & 0x08) == 0 or hi == 0:
                if '1' in j_keys: res &= ~0x01
                if '2' in j_keys: res &= ~0x02
                if '3' in j_keys: res &= ~0x04
                if '4' in j_keys: res &= ~0x08
                if '5' in j_keys: res &= ~0x10
            if (hi & 0x10) == 0 or hi == 0:
                if '0' in j_keys: res &= ~0x01
                if '9' in j_keys: res &= ~0x02
                if '8' in j_keys: res &= ~0x04
                if '7' in j_keys: res &= ~0x08
                if '6' in j_keys: res &= ~0x10
        return float(res)
    else:
        return float(get_floating_bus_byte())


def ensure_cell_attributes(x, y):
    global canvas_dirty
    cell_x = max(0, min(31, x // 8))
    cell_y = max(0, min(23, (191 - y) // 8))
    eff_ink = current_paper if current_inverse else current_ink
    eff_paper = current_ink if current_inverse else current_paper
    if not attr_used[cell_y][cell_x]:
        if eff_ink == 9:
            cur_p = attr_paper[cell_y][cell_x]
            attr_ink[cell_y][cell_x] = 0 if cur_p >= 4 else 7
        elif eff_ink != 8:
            attr_ink[cell_y][cell_x] = eff_ink % 8
        if eff_paper == 9:
            cur_i = attr_ink[cell_y][cell_x]
            attr_paper[cell_y][cell_x] = 0 if cur_i >= 4 else 7
        elif eff_paper != 8:
            attr_paper[cell_y][cell_x] = eff_paper % 8
        attr_bright[cell_y][cell_x] = current_bright
        attr_flash[cell_y][cell_x] = current_flash
        attr_used[cell_y][cell_x] = True
        canvas_dirty = True
    else:
        if eff_ink == 9:
            cur_p = attr_paper[cell_y][cell_x]
            target_i = 0 if cur_p >= 4 else 7
            if attr_ink[cell_y][cell_x] != target_i:
                attr_ink[cell_y][cell_x] = target_i
                canvas_dirty = True
        elif eff_ink != 8:
            target_i = eff_ink % 8
            if attr_ink[cell_y][cell_x] != target_i:
                attr_ink[cell_y][cell_x] = target_i
                canvas_dirty = True
        if attr_bright[cell_y][cell_x] != current_bright:
            attr_bright[cell_y][cell_x] = current_bright
            canvas_dirty = True


def plot_pixel(x, y):
    global gfx_x, gfx_y, canvas_dirty, memory, screen_bitmap_dirty
    canvas_dirty = True
    screen_bitmap_dirty = True
    max_w = 512 if timex_screen_mode == 6 else 256
    x = max(0, min(max_w - 1, int(round(x))))
    y = max(0, min(191, int(round(y))))
    if timex_screen_mode != 6:
        ensure_cell_attributes(x, y)
    if current_over:
        gfx_bits[x][y] = not gfx_bits[x][y]
    else:
        gfx_bits[x][y] = True
    gfx_x = x
    gfx_y = y
    memory[23677] = gfx_x & 0xFF
    memory[23678] = gfx_y & 0xFF

    scr_y = 191 - y
    third = scr_y >> 6
    row_in_third = (scr_y >> 3) & 7
    scanline = scr_y & 7
    line_base = (third << 11) | (scanline << 8) | (row_in_third << 5)

    if timex_screen_mode == 6:
        col = x >> 3
        bit_pos = 7 - (x & 7)
        if (col & 1) == 0:
            vram_addr = 0x4000 | line_base | (col >> 1)
        else:
            vram_addr = 0x6000 | line_base | (col >> 1)
        if current_over:
            memory[vram_addr] ^= (1 << bit_pos)
        else:
            memory[vram_addr] |= (1 << bit_pos)
    elif timex_screen_mode == 2:
        col = x >> 3
        bit_pos = 7 - (x & 7)
        vram_addr = 0x4000 | line_base | col
        if current_over:
            memory[vram_addr] ^= (1 << bit_pos)
        else:
            memory[vram_addr] |= (1 << bit_pos)
        attr_addr = 0x6000 | line_base | col
        attr_b = (128 if current_flash else 0) | (64 if current_bright else 0) | ((current_paper & 7) << 3) | (current_ink & 7)
        memory[attr_addr] = attr_b
    elif timex_screen_mode == 1:
        col = x >> 3
        bit_pos = 7 - (x & 7)
        vram_addr = 0x6000 | line_base | col
        if current_over:
            memory[vram_addr] ^= (1 << bit_pos)
        else:
            memory[vram_addr] |= (1 << bit_pos)
        attr_addr = 0x7800 + (scr_y // 8) * 32 + col
        attr_b = (128 if current_flash else 0) | (64 if current_bright else 0) | ((current_paper & 7) << 3) | (current_ink & 7)
        memory[attr_addr] = attr_b
    else:
        col = x >> 3
        bit_pos = 7 - (x & 7)
        vram_addr = 0x4000 | line_base | col
        if current_over:
            memory[vram_addr] ^= (1 << bit_pos)
        else:
            memory[vram_addr] |= (1 << bit_pos)
        attr_addr = 0x5800 + (scr_y // 8) * 32 + col
        attr_b = (128 if current_flash else 0) | (64 if current_bright else 0) | ((current_paper & 7) << 3) | (current_ink & 7)
        memory[attr_addr] = attr_b

def unplot_pixel(x, y):
    global gfx_x, gfx_y, canvas_dirty, memory, screen_bitmap_dirty
    canvas_dirty = True
    screen_bitmap_dirty = True
    max_w = 512 if timex_screen_mode == 6 else 256
    x = max(0, min(max_w - 1, int(round(x))))
    y = max(0, min(191, int(round(y))))
    if timex_screen_mode != 6:
        ensure_cell_attributes(x, y)
    gfx_bits[x][y] = False
    gfx_x = x
    gfx_y = y
    memory[23677] = gfx_x & 0xFF
    memory[23678] = gfx_y & 0xFF

    scr_y = 191 - y
    third = scr_y >> 6
    row_in_third = (scr_y >> 3) & 7
    scanline = scr_y & 7
    line_base = (third << 11) | (scanline << 8) | (row_in_third << 5)

    if timex_screen_mode == 6:
        col = x >> 3
        bit_pos = 7 - (x & 7)
        if (col & 1) == 0:
            vram_addr = 0x4000 | line_base | (col >> 1)
        else:
            vram_addr = 0x6000 | line_base | (col >> 1)
        memory[vram_addr] &= ~(1 << bit_pos)
    elif timex_screen_mode == 2:
        col = x >> 3
        bit_pos = 7 - (x & 7)
        vram_addr = 0x4000 | line_base | col
        memory[vram_addr] &= ~(1 << bit_pos)
    elif timex_screen_mode == 1:
        col = x >> 3
        bit_pos = 7 - (x & 7)
        vram_addr = 0x6000 | line_base | col
        memory[vram_addr] &= ~(1 << bit_pos)
    else:
        col = x >> 3
        bit_pos = 7 - (x & 7)
        vram_addr = 0x4000 | line_base | col
        memory[vram_addr] &= ~(1 << bit_pos)


def draw_line(x0, y0, x1, y1):
    max_w = 512 if timex_screen_mode == 6 else 256
    x0 = max(0, min(max_w - 1, int(round(x0))))
    y0 = max(0, min(191, int(round(y0))))
    x1 = max(0, min(max_w - 1, int(round(x1))))
    y1 = max(0, min(191, int(round(y1))))
    sx = 1 if x0 < x1 else -1
    sy = 1 if y0 < y1 else -1
    dx_abs = abs(x1 - x0)
    dy_abs = abs(y1 - y0)
    err = dx_abs - dy_abs
    while True:
        plot_pixel(x0, y0)
        if x0 == x1 and y0 == y1:
            break
        e2 = 2 * err
        if e2 > -dy_abs:
            err -= dy_abs
            x0 += sx
        if e2 < dx_abs:
            err += dx_abs
            y0 += sy


def get_pattern_bit(px, py, pat=None):
    if pat is None:
        pat = active_pattern
    if pat == 255 or pat == 0xFF:
        return True
    if isinstance(pat, (int, float)):
        pat_int = int(to_float(pat)) & 0xFF
        bit_col = 7 - (px % 8)
        row_shift = py % 8
        val = ((pat_int >> row_shift) | (pat_int << (8 - row_shift))) & 0xFF
        return bool((val >> bit_col) & 1)
    elif isinstance(pat, (bytes, bytearray, list)):
        if len(pat) >= 8:
            row_b = pat[py % min(len(pat), 16)]
            if isinstance(row_b, str): row_b = ord(row_b)
            return bool((int(row_b) >> (7 - (px % 8))) & 1)
    elif isinstance(pat, str):
        if len(pat) >= 8:
            row_b = ord(pat[py % min(len(pat), 16)])
            return bool((row_b >> (7 - (px % 8))) & 1)
    return True


def draw_box(x, y, w, h, do_fill=False, pattern=None):
    global gfx_x, gfx_y
    x = int(x)
    y = int(y)
    w = int(w)
    h = int(h)
    draw_line(x, y, x + w, y)
    draw_line(x + w, y, x + w, y + h)
    draw_line(x + w, y + h, x, y + h)
    draw_line(x, y + h, x, y)
    if do_fill:
        pat = pattern if pattern is not None else active_pattern
        x_min, x_max = min(x, x + w), max(x, x + w)
        y_min, y_max = min(y, y + h), max(y, y + h)
        for py in range(y_min + 1, y_max):
            for px in range(x_min + 1, x_max):
                if 0 <= px < 256 and 0 <= py < 192:
                    if get_pattern_bit(px, py, pat):
                        plot_pixel(px, py)
                    else:
                        gfx_bits[px][py] = False
                        ensure_cell_attributes(px, py)
                        cell_x = max(0, min(31, px // 8))
                        cell_y = max(0, min(23, (191 - py) // 8))
                        paper_col = attr_paper[cell_y][cell_x]
                        bright_flag = attr_bright[cell_y][cell_x]
                        canvas.set_at((px, 191 - py), map_color(paper_col, bright_flag))
    gfx_x = max(0, min(255, x + w))
    gfx_y = max(0, min(191, y + h))
    update_display()


def parse_inline_attributes_and_args(arg_str):
    global current_ink, current_paper, current_bright, current_flash, current_inverse, current_over
    global current_bold, current_italic, current_underline
    saved_attrs = (current_ink, current_paper, current_bright, current_flash, current_inverse, current_over, current_bold, current_italic, current_underline)
    rem = arg_str.strip()
    while True:
        m = re.match(r'^(INK|PAPER|BRIGHT|FLASH|INVERSE|OVER|BOLD|ITALIC|UNDERLINE)\s+([^;]+?)\s*;\s*(.*)$', rem, re.IGNORECASE)
        if m:
            attr_kw = m.group(1).upper()
            val = int(to_float(evaluate_expr(m.group(2))))
            if attr_kw == "INK": current_ink = val if val in (8, 9) else (val % 8)
            elif attr_kw == "PAPER": current_paper = val if val in (8, 9) else (val % 8)
            elif attr_kw == "BRIGHT": current_bright = bool(val)
            elif attr_kw == "FLASH": current_flash = bool(val)
            elif attr_kw == "INVERSE": current_inverse = bool(val)
            elif attr_kw == "OVER": current_over = bool(val)
            elif attr_kw == "BOLD": current_bold = bool(val)
            elif attr_kw == "ITALIC": current_italic = bool(val)
            elif attr_kw == "UNDERLINE": current_underline = bool(val)
            rem = m.group(3).strip()
        else:
            break
    return rem, saved_attrs


def restore_inline_attributes(saved_attrs):
    global current_ink, current_paper, current_bright, current_flash, current_inverse, current_over
    global current_bold, current_italic, current_underline
    if len(saved_attrs) == 9:
        current_ink, current_paper, current_bright, current_flash, current_inverse, current_over, current_bold, current_italic, current_underline = saved_attrs
    else:
        current_ink, current_paper, current_bright, current_flash, current_inverse, current_over = saved_attrs[:6]


def draw_relative(dx, dy):
    global gfx_x, gfx_y
    max_w = 512 if timex_screen_mode == 6 else 256
    x2 = max(0, min(max_w - 1, gfx_x + dx))
    y2 = max(0, min(191, gfx_y + dy))
    x0, y0 = gfx_x, gfx_y
    sx = 1 if x0 < x2 else -1
    sy = 1 if y0 < y2 else -1
    dx_abs = abs(x2 - x0)
    dy_abs = abs(y2 - y0)
    err = dx_abs - dy_abs
    while True:
        plot_pixel(x0, y0)
        if x0 == x2 and y0 == y2:
            break
        e2 = 2 * err
        if e2 > -dy_abs:
            err -= dy_abs
            x0 += sx
        if e2 < dx_abs:
            err += dx_abs
            y0 += sy
    gfx_x = x2
    gfx_y = y2
    update_display()


def draw_arc(dx, dy, phi):
    global gfx_x, gfx_y
    if abs(phi) < 1e-6:
        draw_relative(dx, dy)
        return
    max_w = 512 if timex_screen_mode == 6 else 256
    x0, y0 = float(gfx_x), float(gfx_y)
    x1, y1 = float(max(0, min(max_w - 1, gfx_x + dx))), float(max(0, min(191, gfx_y + dy)))
    chord_dx = x1 - x0
    chord_dy = y1 - y0
    chord_len = math.hypot(chord_dx, chord_dy)
    if chord_len < 1e-6:
        plot_pixel(int(round(x0)), int(round(y0)))
        return
    sin_half = math.sin(phi / 2.0)
    if abs(sin_half) < 1e-6:
        draw_relative(dx, dy)
        return
    r = chord_len / (2.0 * abs(sin_half))
    mx = x0 + chord_dx / 2.0
    my = y0 + chord_dy / 2.0
    d_center = (chord_len / 2.0) / math.tan(phi / 2.0)
    cx = mx - (chord_dy / chord_len) * d_center
    cy = my + (chord_dx / chord_len) * d_center
    
    start_angle = math.atan2(y0 - cy, x0 - cx)
    steps = max(2, int(chord_len * 2))
    for step in range(steps + 1):
        frac = step / float(steps)
        angle = start_angle + frac * phi
        px = int(round(cx + r * math.cos(angle)))
        py = int(round(cy + r * math.sin(angle)))
        plot_pixel(px, py)
    gfx_x = int(round(x1))
    gfx_y = int(round(y1))
    update_display()


def draw_circle(xc, yc, r):
    x = 0
    y = r
    d = 3 - 2 * r
    def plot_circle_symmetrical(cx, cy, px, py):
        plot_pixel(cx + px, cy + py)
        plot_pixel(cx - px, cy + py)
        plot_pixel(cx + px, cy - py)
        plot_pixel(cx - px, cy - py)
        plot_circle_symmetrical_diagonal(cx, cy, px, py)
    def plot_circle_symmetrical_diagonal(cx, cy, px, py):
        plot_pixel(cx + py, cy + px)
        plot_circle_symmetrical_other(cx, cy, px, py)
    def plot_circle_symmetrical_other(cx, cy, px, py):
        plot_pixel(cx - py, cy + px)
        plot_pixel(cx + py, cy - px)
        plot_pixel(cx - py, cy - px)
    plot_circle_symmetrical(xc, yc, x, y)
    plot_circle_symmetrical_diagonal(xc, yc, x, y)
    while y >= x:
        x += 1
        if d > 0:
            y -= 1
            d = d + 4 * (x - y) + 10
        else:
            d = d + 4 * x + 6
        plot_circle_symmetrical(xc, yc, x, y)
        plot_circle_symmetrical_diagonal(xc, yc, x, y)
    update_display()


def get_point(x, y):
    max_w = 512 if timex_screen_mode == 6 else 256
    x = max(0, min(max_w - 1, int(round(x))))
    y = max(0, min(191, int(round(y))))
    return 1 if gfx_bits[x][y] else 0


def make_nd_array(dims, fill=0.0):
    if not dims:
        return fill
    if len(dims) == 1:
        return [fill] * (dims[0] + 1)
    return [make_nd_array(dims[1:], fill) for _ in range(dims[0] + 1)]


def get_array(arr_name, *indices):
    global arrays, ram_disk_arrays
    arr_name = arr_name.upper()
    target_table = arrays
    if arr_name.startswith("!"):
        target_table = ram_disk_arrays
    elif arr_name not in arrays and f"!{arr_name}" in ram_disk_arrays:
        target_table = ram_disk_arrays
        arr_name = f"!{arr_name}"

    if arr_name not in target_table:
        dims = [max(int(idx), 20) for idx in indices]
        target_table[arr_name] = make_nd_array(dims, 0.0)
    node = target_table[arr_name]
    for idx in indices:
        i = int(idx)
        if isinstance(node, list):
            if i < 0:
                raise Exception("Subscript out of range")
            while len(node) <= i:
                node.append(0.0)
            node = node[i]
        else:
            return 0.0
    return node


def redraw_canvas(force=False):
    global canvas, canvas_dirty, canvas_dirty_cells
    if not ('pygame' in globals() and pygame.get_init() and pygame.display.get_init()):
        return
    if (udg_editor_active or music_editor_active or sfx_editor_active or drum_editor_active) and not force:
        return
    if (globals().get('spectrum_mode', '48K') == 'NEXT' or globals().get('current_sprite_mode', 'ZX') == 'NEXT') and ('next_sprite_manager' in globals() and (next_sprite_manager.has_visible_sprites() or layer2_active or next_lores_mode)):
        force = True
    if not force and not canvas_dirty:
        return
    if gui_mode and WIMPDesktop:
        desktop = WIMPDesktop.get_instance()
        if canvas.get_width() != desktop.canvas.get_width() or canvas.get_height() != desktop.canvas.get_height():
            canvas = pygame.Surface((desktop.canvas.get_width(), desktop.canvas.get_height()))
        desktop.render(canvas)
        canvas_dirty = False
        return

    if timex_screen_mode == 6:
        if canvas.get_width() != 512:
            canvas = pygame.Surface((512, 192))
        px_array = pygame.PixelArray(canvas)
        pal_idx = timex_hires_palette & 7
        ink_idx, paper_idx = TIMEX_HIRES_COLORS[pal_idx]
        ink_c = map_color(ink_idx, False)
        paper_c = map_color(paper_idx, False)
        mem = memory
        for py in range(192):
            scr_y = py
            third = scr_y >> 6
            row_in_third = (scr_y >> 3) & 7
            scanline = scr_y & 7
            line_base = (third << 11) | (scanline << 8) | (row_in_third << 5)
            y_bmp = 191 - py
            for col in range(64):
                if (col & 1) == 0:
                    b = mem[0x4000 | line_base | (col >> 1)]
                else:
                    b = mem[0x6000 | line_base | (col >> 1)]
                x_base = col << 3
                for dx in range(8):
                    px = x_base + dx
                    is_set = bool((b >> (7 - dx)) & 1) or gfx_bits[px][y_bmp]
                    px_array[px, py] = ink_c if is_set else paper_c
        del px_array
        if globals().get('spectrum_mode', '48K') == 'NEXT':
            composite_next_layers(canvas)
        canvas_dirty = False
        canvas_dirty_cells.clear()
        return
    elif timex_screen_mode == 2:
        global canvas_base, screen_bitmap_dirty
        if canvas.get_width() != 256:
            canvas = pygame.Surface((256, 192))
        if 'canvas_base' not in globals() or canvas_base is None or canvas_base.get_size() != (256, 192):
            canvas_base = pygame.Surface((256, 192))
            screen_bitmap_dirty = True
        if 'screen_bitmap_dirty' not in globals():
            screen_bitmap_dirty = True
        if screen_bitmap_dirty:
            px_array = pygame.PixelArray(canvas_base)
            phase = flash_phase
            mem = memory
            for py in range(192):
                scr_y = py
                third = scr_y >> 6
                row_in_third = (scr_y >> 3) & 7
                scanline = scr_y & 7
                line_base = (third << 11) | (scanline << 8) | (row_in_third << 5)
                y_bmp = 191 - py
                for col in range(32):
                    b = mem[0x4000 | line_base | col]
                    attr = mem[0x6000 | line_base | col]
                    ink_col = attr & 7
                    paper_col = (attr >> 3) & 7
                    bright_flag = bool((attr >> 6) & 1)
                    is_flashing = bool((attr >> 7) & 1) and phase
                    active_ink = paper_col if is_flashing else ink_col
                    active_paper = ink_col if is_flashing else paper_col
                    ink_c = map_color(active_ink, bright_flag)
                    paper_c = map_color(active_paper, bright_flag)
                    x_base = col << 3
                    for dx in range(8):
                        px = x_base + dx
                        is_set = bool((b >> (7 - dx)) & 1) or gfx_bits[px][y_bmp]
                        px_array[px, py] = ink_c if is_set else paper_c
            del px_array
            screen_bitmap_dirty = False
            canvas_dirty_cells.clear()
        canvas.blit(canvas_base, (0, 0))
        if globals().get('spectrum_mode', '48K') == 'NEXT' or globals().get('current_sprite_mode', 'ZX') == 'NEXT':
            composite_next_layers(canvas)
        canvas_dirty = False
        return
    elif timex_screen_mode == 1:
        if canvas.get_width() != 256:
            canvas = pygame.Surface((256, 192))
        px_array = pygame.PixelArray(canvas)
        phase = flash_phase
        mem = memory
        for cy in range(24):
            y_top = cy * 8
            for cx in range(32):
                x_left = cx * 8
                attr = mem[0x7800 + cy * 32 + cx]
                ink_col = attr & 7
                paper_col = (attr >> 3) & 7
                bright_flag = bool((attr >> 6) & 1)
                is_flashing = bool((attr >> 7) & 1) and phase
                active_ink = paper_col if is_flashing else ink_col
                active_paper = ink_col if is_flashing else paper_col
                ink_c = map_color(active_ink, bright_flag)
                paper_c = map_color(active_paper, bright_flag)
                for dy in range(8):
                    py = y_top + dy
                    scr_y = py
                    third = scr_y >> 6
                    row_in_third = (scr_y >> 3) & 7
                    scanline = scr_y & 7
                    line_base = (third << 11) | (scanline << 8) | (row_in_third << 5)
                    b = mem[0x6000 | line_base | cx]
                    y_bmp = 191 - py
                    for dx in range(8):
                        px = x_left + dx
                        is_set = bool((b >> (7 - dx)) & 1) or gfx_bits[px][y_bmp]
                        px_array[px, py] = ink_c if is_set else paper_c
        del px_array
        if globals().get('spectrum_mode', '48K') == 'NEXT' or globals().get('current_sprite_mode', 'ZX') == 'NEXT':
            composite_next_layers(canvas)
        canvas_dirty = False
        canvas_dirty_cells.clear()
        return
    else:
        if canvas.get_width() != 256:
            canvas = pygame.Surface((256, 192))

    cpu = get_z80_cpu() if 'get_z80_cpu' in globals() else globals().get('z80_cpu', None)
    is_mc_running = (cpu is not None and (getattr(cpu, 'is_running', False) or getattr(cpu, 'screen_dirty', False)))
    if is_mc_running and not ('current_shadow_screen' in globals() and current_shadow_screen):
        surf8 = _get_fast_vram_surf()
        if surf8:
            mem = cpu.memory if (cpu is not None and hasattr(cpu, 'memory')) else memory
            tbl = _VRAM_PIXEL_TABLE_FLASH if ('flash_phase' in globals() and flash_phase) else _VRAM_PIXEL_TABLE
            offsets = _VRAM_SCANLINE_OFFSETS
            buf = _vram_raw_buf
            for vram_base, attr_base, dest_base in offsets:
                for col in range(32):
                    attr = mem[attr_base + col]
                    b = mem[vram_base + col]
                    buf[dest_base + (col << 3) : dest_base + (col << 3) + 8] = tbl[(attr << 8) | b]
            buf_proxy = surf8.get_buffer()
            buf_proxy.write(bytes(buf))
            del buf_proxy
            canvas.blit(surf8, (0, 0))
            canvas_dirty = False
            canvas_dirty_cells.clear()
            return
    px_array = pygame.PixelArray(canvas)
    gfx = gfx_bits
    map_c = map_color
    phase = flash_phase

    # Incremental update if we have a moderate set of dirty cells
    if not force and canvas_dirty_cells and len(canvas_dirty_cells) < 768:
        cells_to_draw = list(canvas_dirty_cells)
        canvas_dirty_cells.clear()
        for cy, cx in cells_to_draw:
            if not (0 <= cy < 24 and 0 <= cx < 32):
                continue
            y_top = cy * 8
            x_left = cx * 8
            ink_col = attr_ink[cy][cx]
            paper_col = attr_paper[cy][cx]
            bright_flag = attr_bright[cy][cx]
            is_flashing = attr_flash[cy][cx] and phase
            active_ink = paper_col if is_flashing else ink_col
            active_paper = ink_col if is_flashing else paper_col

            ink_c = map_c(active_ink, bright_flag)
            paper_c = map_c(active_paper, bright_flag)

            for dy in range(8):
                py = y_top + dy
                y_bmp = 191 - py
                for dx in range(8):
                    px = x_left + dx
                    px_array[px, py] = ink_c if gfx[px][y_bmp] else paper_c
        del px_array
        if globals().get('spectrum_mode', '48K') == 'NEXT':
            composite_next_layers(canvas)
        canvas_dirty = False
        return

    canvas_dirty_cells.clear()
    for cy in range(24):
        y_top = cy * 8
        for cx in range(32):
            x_left = cx * 8
            ink_col = attr_ink[cy][cx]
            paper_col = attr_paper[cy][cx]
            bright_flag = attr_bright[cy][cx]
            is_flashing = attr_flash[cy][cx] and phase
            active_ink = paper_col if is_flashing else ink_col
            active_paper = ink_col if is_flashing else paper_col

            ink_c = map_c(active_ink, bright_flag)
            paper_c = map_c(active_paper, bright_flag)

            # Check if any gfx pixel is set in this 8x8 cell
            has_gfx = False
            for dx in range(8):
                px = x_left + dx
                col_bits = gfx[px]
                for dy in range(8):
                    if col_bits[191 - (y_top + dy)]:
                        has_gfx = True
                        break
                if has_gfx:
                    break

            if not has_gfx:
                px_array[x_left:x_left + 8, y_top:y_top + 8] = paper_c
            else:
                for dy in range(8):
                    py = y_top + dy
                    y_bmp = 191 - py
                    for dx in range(8):
                        px = x_left + dx
                        px_array[px, py] = ink_c if gfx[px][y_bmp] else paper_c
    del px_array
    if globals().get('spectrum_mode', '48K') == 'NEXT' or globals().get('current_sprite_mode', 'ZX') == 'NEXT':
        composite_next_layers(canvas)
    canvas_dirty = False


if canvas_dirty:
    redraw_canvas(force=True)


def get_char_bitmap(ch):
    if not ch or ch == ' ' or ch == '\x00':
        return bytearray(8)
    code = ord(ch) if isinstance(ch, str) else int(ch)
    if 144 <= code <= 164:
        udg_base = memory[23675] + (memory[23676] * 256)
        offset = code - 144
        addr = udg_base + offset * 8
        if 0 <= addr + 8 <= len(memory):
            bmp = memory[addr : addr + 8]
            if any(bmp):
                return bytearray(bmp)
        def_bank = globals().get('DEFAULT_UDG_BANK')
        if def_bank and 0 <= offset < len(def_bank):
            return bytearray(def_bank[offset])
        return bytearray(8)
    elif 128 <= code <= 143:
        bg_val = code - 128
        bl = bool(bg_val & 1)
        br = bool(bg_val & 2)
        tr = bool(bg_val & 4)
        tl = bool(bg_val & 8)
        top_b = (0xF0 if tl else 0) | (0x0F if tr else 0)
        bot_b = (0xF0 if bl else 0) | (0x0F if br else 0)
        return bytearray([top_b] * 4 + [bot_b] * 4)
    elif 32 <= code <= 127:
        chars_base = memory[23606] + (memory[23607] * 256)
        if chars_base != 15360 and 0 <= chars_base + code * 8 + 8 <= len(memory):
            return bytearray(memory[chars_base + code * 8 : chars_base + code * 8 + 8])
        offset = (code - 32) * 8
        return bytearray(ZX_ROM_FONT[offset : offset + 8])
    else:
        chars_base = memory[23606] + (memory[23607] * 256)
        addr = chars_base + code * 8
        if 0 <= addr + 8 <= len(memory):
            return bytearray(memory[addr : addr + 8])
        return bytearray(8)


def parse_basin_control_to_zx_bytes(code_str):
    out = []
    i = 0
    code = code_str.lower().strip()
    while i < len(code):
        c = code[i]
        if c == 'i' and i + 1 < len(code) and code[i+1].isdigit():
            out.append(f"\x10{chr(int(code[i+1]))}")
            i += 2
        elif c == 'p' and i + 1 < len(code) and code[i+1].isdigit():
            out.append(f"\x11{chr(int(code[i+1]))}")
            i += 2
        elif c == 'f' and i + 1 < len(code) and code[i+1].isdigit():
            out.append(f"\x12{chr(int(code[i+1]))}")
            i += 2
        elif c == 'b' and i + 1 < len(code) and code[i+1].isdigit():
            out.append(f"\x13{chr(int(code[i+1]))}")
            i += 2
        elif c == 'v':
            if i + 1 < len(code) and code[i+1] == 'n':
                out.append("\x14\x00")
                i += 2
            elif i + 1 < len(code) and code[i+1].isdigit():
                out.append(f"\x14{chr(int(code[i+1]))}")
                i += 2
            else:
                out.append("\x14\x01")
                i += 1
        elif c == 'o' and i + 1 < len(code) and code[i+1].isdigit():
            out.append(f"\x15{chr(int(code[i+1]))}")
            i += 2
        else:
            i += 1
    return "".join(out)


def apply_basin_escapes(code):
    global current_ink, current_paper, current_flash, current_bright, current_inverse, current_over
    i = 0
    code = code.lower().strip()
    while i < len(code):
        c = code[i]
        if c == 'i' and i + 1 < len(code) and code[i+1].isdigit():
            current_ink = int(code[i+1])
            i += 2
        elif c == 'p' and i + 1 < len(code) and code[i+1].isdigit():
            current_paper = int(code[i+1])
            i += 2
        elif c == 'f' and i + 1 < len(code) and code[i+1].isdigit():
            current_flash = bool(int(code[i+1]))
            i += 2
        elif c == 'b' and i + 1 < len(code) and code[i+1].isdigit():
            current_bright = bool(int(code[i+1]))
            i += 2
        elif c == 'v':
            if i + 1 < len(code) and code[i+1] == 'n':
                current_inverse = False
                i += 2
            elif i + 1 < len(code) and code[i+1].isdigit():
                current_inverse = bool(int(code[i+1]))
                i += 2
            else:
                current_inverse = True
                i += 1
        elif c == 'o' and i + 1 < len(code) and code[i+1].isdigit():
            current_over = bool(int(code[i+1]))
            i += 2
        else:
            i += 1


def decode_zx_string(s):
    if not isinstance(s, str) or '\\' not in s:
        return s
    out = []
    i = 0
    n = len(s)
    block_symbols = {' ', ':', '.', "'", ',', '_'}
    while i < n:
        if s[i] == '\\' and i + 1 < n:
            if s[i+1] == '\\':
                out.append('\\')
                i += 2
                continue
            if s[i+1] == '{':
                close_brace = s.find('}', i + 2)
                if close_brace != -1:
                    code_content = s[i+2:close_brace]
                    out.append(parse_basin_control_to_zx_bytes(code_content))
                    i = close_brace + 1
                    continue
            if i + 2 < n and s[i+1] in block_symbols and s[i+2] in block_symbols:
                c1, c2 = s[i+1], s[i+2]
                tl = c1 in (':', '.', "'")
                bl = c1 in (':', ',', '_')
                tr = c2 in (':', '.', "'")
                br = c2 in (':', ',', '_')
                val = (8 if tl else 0) | (4 if tr else 0) | (2 if br else 0) | (1 if bl else 0)
                out.append(chr(128 + val))
                i += 3
                continue
            ch = s[i+1]
            if ('a' <= ch <= 'u') or ('A' <= ch <= 'U'):
                code = 144 + (ord(ch.upper()) - ord('A'))
                out.append(chr(code))
                i += 2
                continue
            out.append(s[i])
            i += 1
        else:
            out.append(s[i])
            i += 1
    return "".join(out)


_glyph_cache = {}
_font_cache = {}


class ZXPrinterPDF:
    def __init__(self, output_path="printout.pdf", page_width=595.28, page_height=842.0):
        self.output_path = output_path
        self.page_width = page_width
        self.page_height = page_height
        
        # Scale: 256 Spectrum pixels -> 512 pt (2.0 scale)
        self.scale = 2.0
        self.content_width = 256
        self.content_width_pt = self.content_width * self.scale  # 512 pt
        self.margin_x_pt = (self.page_width - self.content_width_pt) / 2.0  # 41.64 pt
        self.margin_y_top_pt = 40.0
        self.margin_y_bottom_pt = 40.0
        self.usable_height_pt = self.page_height - self.margin_y_top_pt - self.margin_y_bottom_pt  # 762 pt
        self.max_page_pixels_y = int(self.usable_height_pt / self.scale)  # ~381 scanlines
        
        # Current print position in text columns (0..31)
        self.current_col = 0
        # Line raster buffer: 256 pixels wide x 8 pixels high (RGB bytes: 256*8*3)
        self.line_buffer = bytearray(256 * 8 * 3)
        self._clear_line_buffer()
        self.line_buffer_dirty = False
        
        # Current page raster: width 256, list of scanline rows (each row is 256 * 3 bytes)
        self.pages = []  # List of bytearrays, each is (width * height * 3)
        self.page_heights = []  # Height in scanlines of each page
        self.current_page_scanlines = []  # List of 256*3 bytearrays
        
    def _clear_line_buffer(self):
        # Fill line buffer with white paper (255, 255, 255)
        for i in range(256 * 8):
            idx = i * 3
            self.line_buffer[idx] = 255
            self.line_buffer[idx + 1] = 255
            self.line_buffer[idx + 2] = 255
        self.current_col = 0
        self.line_buffer_dirty = False

    def _flush_line(self):
        if not self.line_buffer_dirty and self.current_col == 0:
            blank_row = bytearray(b'\xff' * (256 * 3))
            rows = [blank_row for _ in range(8)]
        else:
            rows = []
            for y in range(8):
                row = self.line_buffer[y * 256 * 3 : (y + 1) * 256 * 3]
                rows.append(bytearray(row))
        self._clear_line_buffer()
        
        if len(self.current_page_scanlines) + 8 > self.max_page_pixels_y:
            self.new_page()
            
        self.current_page_scanlines.extend(rows)

    def new_page(self):
        if self.line_buffer_dirty:
            for y in range(8):
                self.current_page_scanlines.append(bytearray(self.line_buffer[y * 256 * 3 : (y + 1) * 256 * 3]))
            self._clear_line_buffer()
        if self.current_page_scanlines:
            h = len(self.current_page_scanlines)
            flat = bytearray()
            for r in self.current_page_scanlines:
                flat.extend(r)
            self.pages.append(flat)
            self.page_heights.append(h)
            self.current_page_scanlines = []
        self._clear_line_buffer()

    def print_char(self, ch, ink=(0, 0, 0), paper=(255, 255, 255)):
        if ch == '\n':
            self._flush_line()
            return
        if ch == '\r':
            self.current_col = 0
            return
        if ch == '\t':
            # Tab to next 16-column boundary
            self.current_col = 16 if self.current_col < 16 else 0
            if self.current_col == 0:
                self._flush_line()
            return
        if ch == '\x0c':  # Form feed
            self.new_page()
            return
            
        if self.current_col >= 32:
            self._flush_line()
            
        bmp = get_char_bitmap(ch)
        start_x = self.current_col * 8
        
        for dy in range(8):
            b = bmp[dy]
            for dx in range(8):
                px = start_x + dx
                bit = (b >> (7 - dx)) & 1
                color = ink if bit else paper
                idx = (dy * 256 + px) * 3
                self.line_buffer[idx] = color[0]
                self.line_buffer[idx + 1] = color[1]
                self.line_buffer[idx + 2] = color[2]
                
        self.line_buffer_dirty = True
        self.current_col += 1

    def print_text(self, text, newline=True):
        decoded = decode_zx_string(str(text))
        for ch in decoded:
            self.print_char(ch)
        if newline:
            self._flush_line()

    def print_text_stream(self, s):
        decoded = decode_zx_string(str(s))
        for ch in decoded:
            self.print_char(ch)
        if s.endswith('\n'):
            self.save()

    def print_screen(self, scr_surface=None, scr_bytes=None):
        if self.line_buffer_dirty:
            self._flush_line()
            
        # Check if 192 scanlines fit on current page
        if len(self.current_page_scanlines) + 192 > self.max_page_pixels_y:
            self.new_page()
            
        if scr_bytes is not None and len(scr_bytes) >= 6912:
            # Decode Spectrum 6912 byte SCREEN$
            screen_rows = self._decode_scr_bytes(scr_bytes)
        elif scr_surface is not None:
            # Read from pygame Surface (256x192)
            screen_rows = []
            for y in range(192):
                row = bytearray(256 * 3)
                for x in range(256):
                    c = scr_surface.get_at((x, y))
                    idx = x * 3
                    row[idx] = c[0]
                    row[idx + 1] = c[1]
                    row[idx + 2] = c[2]
                screen_rows.append(row)
        else:
            # Full composite screen dump: canvas + screen_chars
            redraw_canvas(force=True)
            comp_surf = pygame.Surface((256, 192))
            comp_surf.blit(canvas, (0, 0))
            if 'screen_chars' in globals():
                for r in range(min(24, len(screen_chars))):
                    for c in range(min(32, len(screen_chars[r]))):
                        ch = screen_chars[r][c]
                        if ch and ch != ' ' and ch != '\x00':
                            render_spectrum_cell(r, c, ch, c * 8, r * 8, 1.0, 1.0, target_screen=comp_surf)
            screen_rows = []
            for y in range(192):
                row = bytearray(256 * 3)
                for x in range(256):
                    c = comp_surf.get_at((x, y))
                    idx = x * 3
                    row[idx] = c[0]
                    row[idx + 1] = c[1]
                    row[idx + 2] = c[2]
                screen_rows.append(row)

        self.current_page_scanlines.extend(screen_rows)
        # Add 8 blank scanlines of spacing after screen dump
        blank_row = bytearray(b'\xff' * (256 * 3))
        for _ in range(8):
            if len(self.current_page_scanlines) < self.max_page_pixels_y:
                self.current_page_scanlines.append(blank_row)

    def _decode_scr_bytes(self, scr_bytes):
        # Decodes 6912 bytes into 192 rows of 256*3 RGB bytes
        rows = []
        map_c = map_color
        for y in range(192):
            third = y // 64
            row_in_third = (y % 64) // 8
            line_in_row = y % 8
            cy = y // 8
            row = bytearray(256 * 3)
            for cx in range(32):
                bmp_addr = (third * 2048) + (row_in_third * 32) + (line_in_row * 256) + cx
                attr_addr = 6144 + cy * 32 + cx
                byte_val = scr_bytes[bmp_addr]
                attr = scr_bytes[attr_addr]
                ink = attr & 7
                paper = (attr >> 3) & 7
                bright = bool(attr & 64)
                ink_c = map_c(ink, bright)
                paper_c = map_c(paper, bright)
                for bit in range(8):
                    px = cx * 8 + bit
                    is_set = (byte_val >> (7 - bit)) & 1
                    c = ink_c if is_set else paper_c
                    idx = px * 3
                    row[idx] = c[0]
                    row[idx + 1] = c[1]
                    row[idx + 2] = c[2]
            rows.append(row)
        return rows

    def flush(self):
        if self.line_buffer_dirty:
            self._flush_line()
        self.save()

    def reset(self):
        self.pages = []
        self.page_heights = []
        self.current_page_scanlines = []
        self._clear_line_buffer()

    def save(self, filepath=None):
        if filepath:
            self.output_path = filepath
        
        pages_to_save = list(self.pages)
        heights_to_save = list(self.page_heights)
        
        cur_scanlines = list(self.current_page_scanlines)
        if self.line_buffer_dirty:
            for y in range(8):
                cur_scanlines.append(bytearray(self.line_buffer[y * 256 * 3 : (y + 1) * 256 * 3]))
                
        if cur_scanlines:
            flat = bytearray()
            for r in cur_scanlines:
                flat.extend(r)
            pages_to_save.append(flat)
            heights_to_save.append(len(cur_scanlines))
            
        if not pages_to_save:
            blank_page = bytearray(b'\xff' * (256 * 8 * 3))
            pages_to_save.append(blank_page)
            heights_to_save.append(8)
            
        num_pages = len(pages_to_save)
        objects = []
        
        def add_obj(data):
            objects.append(data)
            return len(objects)

        # 1: Catalog
        add_obj(b'<< /Type /Catalog /Pages 2 0 R >>')
        # 2: Pages (placeholder)
        add_obj(None)
        
        page_obj_ids = []
        for p_idx in range(num_pages):
            raw_rgb = pages_to_save[p_idx]
            h = heights_to_save[p_idx]
            comp_rgb = zlib.compress(bytes(raw_rgb), 9)
            
            w_pt = self.content_width_pt  # 512 pt
            h_pt = h * self.scale
            x_pt = self.margin_x_pt
            y_pt = self.page_height - self.margin_y_top_pt - h_pt
            
            img_obj_num = len(objects) + 3
            content_obj_num = len(objects) + 2
            page_obj_num = len(objects) + 1
            
            page_dict = (
                f'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 {self.page_width:.2f} {self.page_height:.2f}] '
                f'/Contents {content_obj_num} 0 R /Resources << /XObject << /Im{p_idx} {img_obj_num} 0 R >> >> >>'
            ).encode('latin-1')
            add_obj(page_dict)
            page_obj_ids.append(page_obj_num)
            
            stream_body = f'q\n{w_pt:.2f} 0 0 {h_pt:.2f} {x_pt:.2f} {y_pt:.2f} cm\n/Im{p_idx} Do\nQ\n'.encode('latin-1')
            add_obj(f'<< /Length {len(stream_body)} >>\nstream\n'.encode('latin-1') + stream_body + b'\nendstream')
            
            img_dict = (
                f'<< /Type /XObject /Subtype /Image /Width {self.content_width} /Height {h} '
                f'/ColorSpace /DeviceRGB /BitsPerComponent 8 /Interpolate false '
                f'/Filter /FlateDecode /Length {len(comp_rgb)} >>\nstream\n'
            ).encode('latin-1') + comp_rgb + b'\nendstream'
            add_obj(img_dict)

        kids_str = " ".join(f"{oid} 0 R" for oid in page_obj_ids)
        objects[1] = f'<< /Type /Pages /Kids [{kids_str}] /Count {num_pages} >>'.encode('latin-1')
        
        out = bytearray(b'%PDF-1.4\n%\xe2\xe3\xcf\xd3\n')
        xref = [0]
        for i, obj in enumerate(objects, 1):
            xref.append(len(out))
            out.extend(f'{i} 0 obj\n'.encode('latin-1'))
            out.extend(obj)
            out.extend(b'\nendobj\n')
            
        xref_offset = len(out)
        out.extend(f'xref\n0 {len(objects)+1}\n0000000000 65535 f \n'.encode('latin-1'))
        for offset in xref[1:]:
            out.extend(f'{offset:010d} 00000 n \n'.encode('latin-1'))
        out.extend(f'trailer\n<< /Size {len(objects)+1} /Root 1 0 R >>\nstartxref\n{xref_offset}\n%%EOF\n'.encode('latin-1'))
        
        try:
            with open(self.output_path, 'wb') as f:
                f.write(out)
        except Exception:
            pass
        return len(out)


zx_printer = ZXPrinterPDF()

