def execute_udg_command(args_str):
    global current_udg_bank, canvas_dirty, _glyph_cache
    args_str = args_str.strip()
    if not args_str or args_str.upper() in ("?", "LIST", "HELP"):
        canvas_print("UDG Banks (0-17):")
        canvas_print(" 1. Space Invaders   2. Pac-Man / Maze")
        canvas_print(" 3. Donkey Kong      4. Super Mario")
        canvas_print(" 5. Sonic Hedgehog   6. Cards & Dice")
        canvas_print(" 7. Common Emoji     8. Sci-Fi Based")
        canvas_print(" 9. Jet Set Willy   10. Chuckie Egg")
        canvas_print("11. Lode / Robotron 12. Scramble")
        canvas_print("13. Snake Games     14. Battle / War")
        canvas_print("15. Psion Horace    16. Word / Excel")
        canvas_print("17. Frogger (1983)   0. Default Outline")
        canvas_print(f"Current bank: {current_udg_bank if current_udg_bank else 'Default'}")
        update_display()
        return

    val = evaluate_expr(args_str)
    bank_num = int(to_float(val))
    if bank_num < 0 or bank_num > 17:
        raise Exception("Integer out of range")

    udg_base = memory[23675] + (memory[23676] * 256)
    bank_data = UDG_PRESET_BANKS[bank_num]
    flat_bytes = []
    for char_bytes in bank_data:
        flat_bytes.extend(char_bytes)

    for i, b in enumerate(flat_bytes):
        if udg_base + i < len(memory):
            memory[udg_base + i] = b

    current_udg_bank = bank_num
    _glyph_cache.clear()
    canvas_dirty = True
    update_display()


def is_frogger_program():
    if 'program' in globals() and program:
        text = " ".join(str(v) for v in program.values()).upper()
        if "FROGGER" in text:
            return True
        if "\\D\\R\\E" in text and "\\G\\F" in text:
            return True
    return False


def load_frogger_udgs():
    global memory, canvas_dirty, _glyph_cache
    udg_base = memory[23675] + (memory[23676] * 256) if 'memory' in globals() and len(memory) > 23676 else 65368
    if not (0 <= udg_base <= len(memory) - 168):
        udg_base = 65368
    for idx, char_bytes in enumerate(FROGGER_UDG_BANK):
        for row_idx, b in enumerate(char_bytes):
            if udg_base + idx * 8 + row_idx < len(memory):
                memory[udg_base + idx * 8 + row_idx] = b
    if '_glyph_cache' in globals():
        _glyph_cache.clear()
    canvas_dirty = True


