# ZX Spectrum Paint Studio (Amiga Deluxe Paint / The Artist ZX Style)
# ==============================================================================

class ZXPaintStudio:
    BRUSH_SHAPES = {
        "1x1": [(0, 0)],
        "2x2": [(0, 0), (1, 0), (0, 1), (1, 1)],
        "3x3": [(dx, dy) for dx in (-1, 0, 1) for dy in (-1, 0, 1)],
        "5x5": [(dx, dy) for dx in range(-2, 3) for dy in range(-2, 3) if abs(dx) + abs(dy) <= 3],
        "CROSS": [(0, 0), (-1, 0), (1, 0), (0, -1), (0, 1), (-2, 0), (2, 0), (0, -2), (0, 2)],
        "SLASH": [(-2, 2), (-1, 1), (0, 0), (1, -1), (2, -2)],
        "BSLASH": [(-2, -2), (-1, -1), (0, 0), (1, 1), (2, 2)],
        "VBAR": [(0, dy) for dy in range(-2, 3)],
        "HBAR": [(dx, 0) for dx in range(-2, 3)],
        "DITHER": [(dx, dy) for dx in range(-2, 3) for dy in range(-2, 3) if (dx + dy) % 2 == 0]
    }

    TOOLS = [
        ("PENCIL", "Pencil"),
        ("BRUSH", "Brush"),
        ("LINE", "Line"),
        ("RAY", "Ray"),
        ("RECT", "Rect"),
        ("FILLBOX", "FillBox"),
        ("CIRCLE", "Circle"),
        ("FILLCIR", "FillCir"),
        ("ELLIPSE", "Ellipse"),
        ("BUCKET", "Bucket"),
        ("SPRAY", "Spray"),
        ("TEXT", "Text"),
        ("ERASER", "Eraser"),
        ("COLOR", "Color"),
        ("PICK", "Pick"),
        ("CLEAR", "Clear")
    ]

    INPUT_MODES = ["AMX", "KEMP", "JOY", "KEYS"]
    JOY_MODES = ["KEMP", "CURS", "SINC1", "SINC2"]
    ATTR_MODES = ["AUTO", "PIXEL_ONLY", "COLOR_ONLY"]
    DEV_TARGETS = ["HOST", "TAPE", "MDRIVE", "RAMDISK", "FLOPPY"]

    def __init__(self):
        self.running = True
        self.tool = "PENCIL"
        self.brush_shape = "1x1"
        self.input_device = "AMX"
        self.joystick_mode = "KEMP"
        self.attr_mode = "AUTO"
        self.dev_target = "HOST"

        # Attribute & color states
        self.current_ink = 0      # 0..7 (Black)
        self.current_paper = 7    # 0..7 (White)
        self.current_bright = False
        self.current_flash = False
        self.draw_color = 1       # 1 = INK, 0 = PAPER

        # Canvas cursor (screen top-down pixels 0..255, 0..191)
        self.cursor_x = 128
        self.cursor_y = 96

        # Drag/drawing state
        self.is_drawing = False
        self.start_x = None
        self.start_y = None
        self.last_ray_x = None
        self.last_ray_y = None
        self.cursor_blink = 0

        # Undo / Redo
        self.undo_stack = []
        self.redo_stack = []
        self.max_undo = 16

        # Modal dialog state
        self.modal_active = False
        self.modal_type = None  # "ESC_PROMPT", "SAVE_PROMPT", "LOAD_PROMPT", "JPG_PROMPT"
        self.modal_text = ""
        self.modal_input = ""
        self.modal_cursor_blink = 0

        # Status
        self.status_message = "Ready. Press ESC to return to BASIC."
        self.status_timer = 0

        # UI Click bounds cache
        self.tool_rects = {}
        self.brush_rects = {}
        self.ink_swatch_rects = []
        self.paper_swatch_rects = []
        self.action_rects = {}

    def set_status(self, msg, duration=180):
        self.status_message = msg
        self.status_timer = duration

    def cycle_tool(self, forward=True):
        names = [t[0] for t in self.TOOLS]
        if self.tool in names:
            idx = names.index(self.tool)
            idx = (idx + (1 if forward else -1)) % len(names)
            self.tool = names[idx]
        else:
            self.tool = names[0]
        self.set_status(f"Tool: {self.tool}")

    def cycle_brush(self):
        shapes = list(self.BRUSH_SHAPES.keys())
        if self.brush_shape in shapes:
            idx = (shapes.index(self.brush_shape) + 1) % len(shapes)
            self.brush_shape = shapes[idx]
        else:
            self.brush_shape = shapes[0]
        self.set_status(f"Brush: {self.brush_shape}")

    def cycle_input(self):
        idx = (self.INPUT_MODES.index(self.input_device) + 1) % len(self.INPUT_MODES)
        self.input_device = self.INPUT_MODES[idx]
        self.set_status(f"Input: {self.input_device}")

    def cycle_joy_mode(self):
        idx = (self.JOY_MODES.index(self.joystick_mode) + 1) % len(self.JOY_MODES)
        self.joystick_mode = self.JOY_MODES[idx]
        self.set_status(f"Joystick: {self.joystick_mode}")

    def cycle_attr_mode(self):
        idx = (self.ATTR_MODES.index(self.attr_mode) + 1) % len(self.ATTR_MODES)
        self.attr_mode = self.ATTR_MODES[idx]
        self.set_status(f"Attribute Mode: {self.attr_mode}")

    def cycle_dev_target(self):
        idx = (self.DEV_TARGETS.index(self.dev_target) + 1) % len(self.DEV_TARGETS)
        self.dev_target = self.DEV_TARGETS[idx]
        self.set_status(f"Device: {self.dev_target}")

    def swap_colors(self):
        self.current_ink, self.current_paper = self.current_paper, self.current_ink
        self.set_status(f"Swapped: INK={self.current_ink}, PAP={self.current_paper}")

    def toggle_bright(self):
        self.current_bright = not self.current_bright
        self.set_status(f"BRIGHT: {'ON' if self.current_bright else 'OFF'}")

    def toggle_flash(self):
        self.current_flash = not self.current_flash
        self.set_status(f"FLASH: {'ON' if self.current_flash else 'OFF'}")

    def save_undo(self):
        snapshot = (
            [col[:] for col in gfx_bits],
            [row[:] for row in attr_ink],
            [row[:] for row in attr_paper],
            [row[:] for row in attr_bright],
            [row[:] for row in attr_flash]
        )
        self.undo_stack.append(snapshot)
        if len(self.undo_stack) > self.max_undo:
            self.undo_stack.pop(0)
        self.redo_stack.clear()

    def undo(self):
        if not self.undo_stack:
            self.set_status("Nothing to undo.")
            return
        cur_state = (
            [col[:] for col in gfx_bits],
            [row[:] for row in attr_ink],
            [row[:] for row in attr_paper],
            [row[:] for row in attr_bright],
            [row[:] for row in attr_flash]
        )
        self.redo_stack.append(cur_state)
        prev = self.undo_stack.pop()
        self._restore_state(prev)
        self.set_status("Undo performed.")

    def redo(self):
        if not self.redo_stack:
            self.set_status("Nothing to redo.")
            return
        cur_state = (
            [col[:] for col in gfx_bits],
            [row[:] for row in attr_ink],
            [row[:] for row in attr_paper],
            [row[:] for row in attr_bright],
            [row[:] for row in attr_flash]
        )
        self.undo_stack.append(cur_state)
        nxt = self.redo_stack.pop()
        self._restore_state(nxt)
        self.set_status("Redo performed.")

    def _restore_state(self, state):
        global canvas_dirty
        g, ai, ap, ab, af = state
        for x in range(256):
            gfx_bits[x][:] = g[x]
        for r in range(24):
            attr_ink[r][:] = ai[r]
            attr_paper[r][:] = ap[r]
            attr_bright[r][:] = ab[r]
            attr_flash[r][:] = af[r]
        canvas_dirty = True

    def plot_pixel(self, x, y, value=True, update_attr=True):
        if not (0 <= x < 256 and 0 <= y < 192):
            return
        global canvas_dirty
        internal_y = 191 - y
        if self.attr_mode != "COLOR_ONLY":
            gfx_bits[x][internal_y] = value
        if self.attr_mode != "PIXEL_ONLY" and update_attr:
            r = y // 8
            c = x // 8
            if 0 <= r < 24 and 0 <= c < 32:
                attr_ink[r][c] = self.current_ink
                attr_paper[r][c] = self.current_paper
                attr_bright[r][c] = self.current_bright
                attr_flash[r][c] = self.current_flash
                attr_used[r][c] = True
        canvas_dirty = True

    def wash_cell(self, cx, cy):
        if not (0 <= cx < 32 and 0 <= cy < 24):
            return
        global canvas_dirty
        attr_ink[cy][cx] = self.current_ink
        attr_paper[cy][cx] = self.current_paper
        attr_bright[cy][cx] = self.current_bright
        attr_flash[cy][cx] = self.current_flash
        attr_used[cy][cx] = True
        canvas_dirty = True

    def pick_cell(self, cx, cy):
        if not (0 <= cx < 32 and 0 <= cy < 24):
            return
        self.current_ink = attr_ink[cy][cx] & 7
        self.current_paper = attr_paper[cy][cx] & 7
        self.current_bright = bool(attr_bright[cy][cx])
        self.current_flash = bool(attr_flash[cy][cx])
        self.set_status(f"Picked C:{cx} R:{cy} | INK:{self.current_ink} PAP:{self.current_paper} BRT:{int(self.current_bright)}")

    def clear_screen(self):
        global canvas_dirty
        self.save_undo()
        for x in range(256):
            for y in range(192):
                gfx_bits[x][y] = False
        for r in range(24):
            for c in range(32):
                attr_ink[r][c] = self.current_ink
                attr_paper[r][c] = self.current_paper
                attr_bright[r][c] = self.current_bright
                attr_flash[r][c] = self.current_flash
                attr_used[r][c] = True
        canvas_dirty = True
        self.set_status("Screen cleared.")

    def invert_screen(self):
        global canvas_dirty
        self.save_undo()
        for x in range(256):
            for y in range(192):
                gfx_bits[x][y] = not gfx_bits[x][y]
        canvas_dirty = True
        self.set_status("Screen inverted.")

    def apply_brush(self, cx, cy, is_erase=False):
        offsets = self.BRUSH_SHAPES.get(self.brush_shape, [(0, 0)])
        val = False if is_erase else (self.draw_color == 1)
        for dx, dy in offsets:
            px = cx + dx
            py = cy + dy
            if 0 <= px < 256 and 0 <= py < 192:
                self.plot_pixel(px, py, value=val)

    def apply_spray(self, cx, cy):
        import random
        val = (self.draw_color == 1)
        for _ in range(8):
            dx = random.randint(-4, 4)
            dy = random.randint(-4, 4)
            if dx * dx + dy * dy <= 16:
                px = cx + dx
                py = cy + dy
                if 0 <= px < 256 and 0 <= py < 192:
                    self.plot_pixel(px, py, value=val)

    def stamp_char(self, ch):
        bmp = get_char_bitmap(ch)
        self.save_undo()
        val = (self.draw_color == 1)
        for dy in range(8):
            py = self.cursor_y + dy
            if 0 <= py < 192:
                byte_val = bmp[dy] if dy < len(bmp) else 0
                for dx in range(8):
                    px = self.cursor_x + dx
                    if 0 <= px < 256:
                        is_set = bool((byte_val >> (7 - dx)) & 1)
                        if is_set:
                            self.plot_pixel(px, py, value=val)
        self.cursor_x += 8
        if self.cursor_x > 248:
            self.cursor_x = 0
            self.cursor_y = min(184, self.cursor_y + 8)
        self.set_status(f"Stamped '{ch}' at ({self.cursor_x}, {self.cursor_y})")

    def bresenham_line(self, x0, y0, x1, y1):
        points = []
        dx = abs(x1 - x0)
        dy = abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx - dy
        curr_x, curr_y = x0, y0
        while True:
            points.append((curr_x, curr_y))
            if curr_x == x1 and curr_y == y1:
                break
            e2 = 2 * err
            if e2 > -dy:
                err -= dy
                curr_x += sx
            if e2 < dx:
                err += dx
                curr_y += sy
        return points

    def bresenham_circle(self, xc, yc, r):
        points = set()
        x = 0
        y = r
        d = 3 - 2 * r
        def add_pts(cx, cy, px, py):
            for sx, sy in ((cx + px, cy + py), (cx - px, cy + py), (cx + px, cy - py), (cx - px, cy - py),
                           (cx + py, cy + px), (cx - py, cy + px), (cx + py, cy - px), (cx - py, cy - px)):
                if 0 <= sx < 256 and 0 <= sy < 192:
                    points.add((sx, sy))
        add_pts(xc, yc, x, y)
        while y >= x:
            x += 1
            if d > 0:
                y -= 1
                d = d + 4 * (x - y) + 10
            else:
                d = d + 4 * x + 6
            add_pts(xc, yc, x, y)
        return list(points)

    def filled_circle(self, xc, yc, r):
        points = []
        r2 = r * r
        for y in range(max(0, yc - r), min(192, yc + r + 1)):
            dy = y - yc
            dx_max = int(math.isqrt(max(0, r2 - dy * dy)))
            for x in range(max(0, xc - dx_max), min(256, xc + dx_max + 1)):
                points.append((x, y))
        return points

    def bresenham_ellipse(self, x0, y0, x1, y1):
        points = set()
        rx = abs(x1 - x0) // 2
        ry = abs(y1 - y0) // 2
        if rx == 0 and ry == 0:
            return [(x0, y0)]
        if rx == 0:
            return [(x0, y) for y in range(min(y0, y1), max(y0, y1) + 1)]
        if ry == 0:
            return [(x, y0) for x in range(min(x0, x1), max(x0, x1) + 1)]
        xc = (x0 + x1) // 2
        yc = (y0 + y1) // 2
        x = 0
        y = ry
        d1 = (ry * ry) - (rx * rx * ry) + (0.25 * rx * rx)
        dx = 2 * ry * ry * x
        dy = 2 * rx * rx * y
        def add_quad(cx, cy, px, py):
            for sx, sy in ((cx + px, cy + py), (cx - px, cy + py), (cx + px, cy - py), (cx - px, cy - py)):
                if 0 <= sx < 256 and 0 <= sy < 192:
                    points.add((sx, sy))
        add_quad(xc, yc, x, y)
        while dx < dy:
            x += 1
            dx += 2 * ry * ry
            if d1 < 0:
                d1 += dx + (ry * ry)
            else:
                y -= 1
                dy -= 2 * rx * rx
                d1 += dx - dy + (ry * ry)
            add_quad(xc, yc, x, y)
        d2 = ((ry * ry) * ((x + 0.5) ** 2)) + ((rx * rx) * ((y - 1) ** 2)) - (rx * rx * ry * ry)
        while y >= 0:
            y -= 1
            dy -= 2 * rx * rx
            if d2 > 0:
                d2 += (rx * rx) - dy
            else:
                x += 1
                dx += 2 * ry * ry
                d2 += (rx * rx) - dy + dx
            add_quad(xc, yc, x, y)
        return list(points)

    def flood_fill(self, start_x, start_y):
        if not (0 <= start_x < 256 and 0 <= start_y < 192):
            return
        self.save_undo()
        start_internal_y = 191 - start_y
        target_val = bool(gfx_bits[start_x][start_internal_y])
        fill_val = True if (self.tool != "ERASER" and self.draw_color == 1) else False

        same_pixel = (target_val == fill_val)
        if same_pixel and self.attr_mode == "PIXEL_ONLY":
            return

        queue = collections.deque([(start_x, start_y)])
        visited = set([(start_x, start_y)])

        while queue:
            cx, cy = queue.popleft()
            internal_y = 191 - cy
            if not same_pixel:
                gfx_bits[cx][internal_y] = fill_val
            if self.attr_mode in ("AUTO", "COLOR_ONLY"):
                r = cy // 8
                c = cx // 8
                if 0 <= r < 24 and 0 <= c < 32:
                    attr_ink[r][c] = self.current_ink
                    attr_paper[r][c] = self.current_paper
                    attr_bright[r][c] = self.current_bright
                    attr_flash[r][c] = self.current_flash
                    attr_used[r][c] = True

            for nx, ny in ((cx + 1, cy), (cx - 1, cy), (cx, cy + 1), (cx, cy - 1)):
                if 0 <= nx < 256 and 0 <= ny < 192:
                    if (nx, ny) not in visited:
                        if bool(gfx_bits[nx][191 - ny]) == target_val:
                            visited.add((nx, ny))
                            queue.append((nx, ny))
        global canvas_dirty
        canvas_dirty = True
        self.set_status("Flood fill completed.")

    def get_shape_points(self, tool, x0, y0, x1, y1):
        if tool == "LINE":
            return self.bresenham_line(x0, y0, x1, y1)
        elif tool == "RECT":
            pts = set()
            min_x, max_x = min(x0, x1), max(x0, x1)
            min_y, max_y = min(y0, y1), max(y0, y1)
            for x in range(min_x, max_x + 1):
                pts.add((x, min_y))
                pts.add((x, max_y))
            for y in range(min_y, max_y + 1):
                pts.add((min_x, y))
                pts.add((max_x, y))
            return list(pts)
        elif tool == "FILLBOX":
            pts = []
            min_x, max_x = min(x0, x1), max(x0, x1)
            min_y, max_y = min(y0, y1), max(y0, y1)
            for y in range(min_y, max_y + 1):
                for x in range(min_x, max_x + 1):
                    pts.append((x, y))
            return pts
        elif tool == "CIRCLE":
            r = int(math.hypot(x1 - x0, y1 - y0))
            return self.bresenham_circle(x0, y0, r)
        elif tool == "FILLCIR":
            r = int(math.hypot(x1 - x0, y1 - y0))
            return self.filled_circle(x0, y0, r)
        elif tool == "ELLIPSE":
            return self.bresenham_ellipse(x0, y0, x1, y1)
        return []

    def handle_canvas_press(self, cx, cy, button=1):
        self.cursor_x = cx
        self.cursor_y = cy
        self.draw_color = 0 if button == 3 else 1

        if self.tool == "PICK":
            self.pick_cell(cx // 8, cy // 8)
            return
        if self.tool == "COLOR":
            self.save_undo()
            self.wash_cell(cx // 8, cy // 8)
            self.is_drawing = True
            return
        if self.tool == "BUCKET":
            self.flood_fill(cx, cy)
            return
        if self.tool == "TEXT":
            return
        if self.tool == "RAY":
            if self.last_ray_x is None:
                self.last_ray_x = cx
                self.last_ray_y = cy
                self.set_status(f"Ray started at ({cx}, {cy}). Click next point.")
            else:
                self.save_undo()
                for px, py in self.bresenham_line(self.last_ray_x, self.last_ray_y, cx, cy):
                    self.plot_pixel(px, py, value=(self.draw_color == 1))
                self.last_ray_x = cx
                self.last_ray_y = cy
            return
        if self.tool == "PENCIL":
            self.save_undo()
            self.is_drawing = True
            self.plot_pixel(cx, cy, value=(self.draw_color == 1))
            return
        if self.tool == "BRUSH":
            self.save_undo()
            self.is_drawing = True
            self.apply_brush(cx, cy, is_erase=False)
            return
        if self.tool == "ERASER":
            self.save_undo()
            self.is_drawing = True
            self.apply_brush(cx, cy, is_erase=True)
            return
        if self.tool == "SPRAY":
            self.save_undo()
            self.is_drawing = True
            self.apply_spray(cx, cy)
            return
        if self.tool in ("LINE", "RECT", "FILLBOX", "CIRCLE", "FILLCIR", "ELLIPSE"):
            self.is_drawing = True
            self.start_x = cx
            self.start_y = cy

    def handle_canvas_drag(self, cx, cy):
        self.cursor_x = cx
        self.cursor_y = cy
        if not self.is_drawing:
            return
        if self.tool == "PENCIL":
            self.plot_pixel(cx, cy, value=(self.draw_color == 1))
        elif self.tool == "BRUSH":
            self.apply_brush(cx, cy, is_erase=False)
        elif self.tool == "ERASER":
            self.apply_brush(cx, cy, is_erase=True)
        elif self.tool == "SPRAY":
            self.apply_spray(cx, cy)
        elif self.tool == "COLOR":
            self.wash_cell(cx // 8, cy // 8)

    def handle_canvas_release(self, cx, cy):
        if not self.is_drawing:
            return
        self.is_drawing = False
        if self.tool in ("LINE", "RECT", "FILLBOX", "CIRCLE", "FILLCIR", "ELLIPSE"):
            if self.start_x is not None and self.start_y is not None:
                self.save_undo()
                pts = self.get_shape_points(self.tool, self.start_x, self.start_y, cx, cy)
                val = (self.draw_color == 1)
                for px, py in pts:
                    self.plot_pixel(px, py, value=val)
                self.start_x = None
                self.start_y = None
                self.set_status(f"{self.tool} completed.")

    def prompt_save_modal(self):
        self.modal_active = True
        self.modal_type = "SAVE_PROMPT"
        self.modal_text = "Enter Save Filename:"
        self.modal_input = "screen"

    def prompt_load_modal(self):
        self.modal_active = True
        self.modal_type = "LOAD_PROMPT"
        self.modal_text = "Enter Load Filename:"
        self.modal_input = "screen"

    def prompt_jpg_modal(self):
        self.modal_active = True
        self.modal_type = "JPG_PROMPT"
        self.modal_text = "Enter JPG Filename to Import:"
        self.modal_input = ""

    def prompt_exit_modal(self):
        self.modal_active = True
        self.modal_type = "ESC_PROMPT"
        self.modal_text = "Save screen before returning to BASIC?"
        self.modal_input = ""

    def save_screen(self, filename):
        clean = filename.strip().strip('"').strip("'").strip()
        if not clean: clean = "screen"
        dev = self.dev_target.upper()
        try:
            if dev == "HOST":
                save_screen_file(clean)
                self.set_status(f"Saved {clean}.scr (Host).")
            elif dev == "TAPE":
                handle_save_command(f'"{clean}" SCREEN$')
                self.set_status(f"Saved '{clean}' SCREEN$ to Tape.")
            elif dev == "MDRIVE":
                handle_save_command(f'*"m";1;"{clean}" SCREEN$')
                self.set_status(f"Saved '{clean}' SCREEN$ to Microdrive 1.")
            elif dev == "RAMDISK":
                handle_save_command(f'!"{clean}" SCREEN$')
                self.set_status(f"Saved '{clean}' SCREEN$ to RAM disk.")
            elif dev == "FLOPPY":
                handle_save_command(f'"d1:{clean}" SCREEN$')
                self.set_status(f"Saved '{clean}' SCREEN$ to Disk 1.")
            return True
        except Exception as e:
            self.set_status(f"Save error: {e}")
            return False

    def load_screen(self, filename):
        clean = filename.strip().strip('"').strip("'").strip()
        if not clean: clean = "screen"
        dev = self.dev_target.upper()
        try:
            self.save_undo()
            if dev == "HOST":
                candidates = [
                    clean,
                    clean + ".scr",
                    os.path.join(get_zx_folder(), clean),
                    os.path.join(get_zx_folder(), clean + ".scr"),
                    os.path.join(os.getcwd(), clean),
                    os.path.join(os.getcwd(), clean + ".scr")
                ]
                found = None
                for c in candidates:
                    if os.path.exists(c) and os.path.isfile(c):
                        found = c
                        break
                if found:
                    load_screen_file(found)
                    self.set_status(f"Loaded {os.path.basename(found)}.")
                else:
                    self.set_status(f"File '{clean}' not found.")
                    return False
            elif dev == "TAPE":
                handle_load_command(f'"{clean}" SCREEN$')
                self.set_status(f"Loaded '{clean}' SCREEN$ from Tape.")
            elif dev == "MDRIVE":
                handle_load_command(f'*"m";1;"{clean}" SCREEN$')
                self.set_status(f"Loaded '{clean}' SCREEN$ from Microdrive 1.")
            elif dev == "RAMDISK":
                handle_load_command(f'!"{clean}" SCREEN$')
                self.set_status(f"Loaded '{clean}' SCREEN$ from RAM disk.")
            elif dev == "FLOPPY":
                handle_load_command(f'"d1:{clean}" SCREEN$')
                self.set_status(f"Loaded '{clean}' SCREEN$ from Disk 1.")
            global canvas_dirty
            canvas_dirty = True
            return True
        except Exception as e:
            self.set_status(f"Load error: {e}")
            return False

    def import_jpg(self, filename):
        target = filename.strip().strip('"').strip("'").strip()
        if not target:
            self.set_status("No filename given.")
            return False
        candidates = [
            target,
            os.path.join(os.getcwd(), target),
            os.path.join(get_zx_folder(), target)
        ]
        if not (target.lower().endswith(".jpg") or target.lower().endswith(".jpeg")):
            candidates.extend([
                target + ".jpg",
                os.path.join(os.getcwd(), target + ".jpg"),
                os.path.join(get_zx_folder(), target + ".jpg"),
                target + ".jpeg",
                os.path.join(os.getcwd(), target + ".jpeg"),
                os.path.join(get_zx_folder(), target + ".jpeg")
            ])
        found = None
        for c in candidates:
            if os.path.exists(c) and os.path.isfile(c):
                found = c
                break
        if not found:
            self.set_status(f"JPG file '{target}' not found.")
            return False
        try:
            self.save_undo()
            block = convert_image_to_spectrum_screen(found)
            load_screen_bytes(block)
            self.set_status(f"Imported JPG: {os.path.basename(found)}")
            global canvas_dirty
            canvas_dirty = True
            return True
        except Exception as e:
            self.set_status(f"JPG Import error: {e}")
            return False

    def handle_toolbox_click(self, pos, button=1):
        if self.modal_active:
            if self.modal_type == "ESC_PROMPT":
                if self.action_rects.get("MODAL_YES") and self.action_rects["MODAL_YES"].collidepoint(pos):
                    self.save_screen("screen")
                    self.running = False
                    return
                elif self.action_rects.get("MODAL_NO") and self.action_rects["MODAL_NO"].collidepoint(pos):
                    self.running = False
                    return
                elif self.action_rects.get("MODAL_CANCEL") and self.action_rects["MODAL_CANCEL"].collidepoint(pos):
                    self.modal_active = False
                    self.modal_type = None
                    return
            elif self.modal_type in ("SAVE_PROMPT", "LOAD_PROMPT", "JPG_PROMPT"):
                if self.action_rects.get("MODAL_OK") and self.action_rects["MODAL_OK"].collidepoint(pos):
                    self.confirm_modal()
                    return
                elif self.action_rects.get("MODAL_CANCEL") and self.action_rects["MODAL_CANCEL"].collidepoint(pos):
                    self.modal_active = False
                    self.modal_type = None
                    return
            return

        for t_name, r in self.tool_rects.items():
            if r.collidepoint(pos):
                if t_name == "CLEAR":
                    self.clear_screen()
                else:
                    self.tool = t_name
                    if t_name == "RAY":
                        self.last_ray_x = None
                        self.last_ray_y = None
                    self.set_status(f"Selected Tool: {t_name}")
                return

        for idx, r in enumerate(self.ink_swatch_rects):
            if r.collidepoint(pos):
                self.current_ink = idx
                self.set_status(f"Selected INK: {idx}")
                return

        for idx, r in enumerate(self.paper_swatch_rects):
            if r.collidepoint(pos):
                self.current_paper = idx
                self.set_status(f"Selected PAPER: {idx}")
                return

        for b_name, r in self.brush_rects.items():
            if r.collidepoint(pos):
                self.brush_shape = b_name
                self.set_status(f"Selected Brush: {b_name}")
                return

        for act, r in self.action_rects.items():
            if r.collidepoint(pos):
                if act == "SWAP": self.swap_colors()
                elif act == "BRIGHT": self.toggle_bright()
                elif act == "FLASH": self.toggle_flash()
                elif act == "MODE": self.cycle_attr_mode()
                elif act == "INPUT": self.cycle_input()
                elif act == "JOY": self.cycle_joy_mode()
                elif act == "SAVE": self.prompt_save_modal()
                elif act == "LOAD": self.prompt_load_modal()
                elif act == "JPG": self.prompt_jpg_modal()
                elif act == "DEV": self.cycle_dev_target()
                elif act == "UNDO": self.undo()
                elif act == "REDO": self.redo()
                elif act == "INV": self.invert_screen()
                elif act == "EXIT": self.prompt_exit_modal()
                return

    def confirm_modal(self):
        if not self.modal_active:
            return
        m_type = self.modal_type
        text = self.modal_input.strip()
        self.modal_active = False
        self.modal_type = None
        if m_type == "SAVE_PROMPT":
            self.save_screen(text if text else "screen")
        elif m_type == "LOAD_PROMPT":
            self.load_screen(text if text else "screen")
        elif m_type == "JPG_PROMPT":
            self.import_jpg(text)

    def handle_event(self, event):
        global scale_x, scale_y, canvas_blit_x, canvas_blit_y, scaled_canvas_w, scaled_canvas_h

        if event.type == pygame.MOUSEBUTTONDOWN:
            if listing_rect and listing_rect.collidepoint(event.pos):
                self.handle_toolbox_click(event.pos, event.button)
            elif scale_x > 0 and scale_y > 0:
                mx, my = event.pos
                if canvas_blit_x <= mx < canvas_blit_x + scaled_canvas_w and canvas_blit_y <= my < canvas_blit_y + scaled_canvas_h:
                    cx = int((mx - canvas_blit_x) / scale_x)
                    cy = int((my - canvas_blit_y) / scale_y)
                    cx = max(0, min(255, cx))
                    cy = max(0, min(191, cy))
                    self.handle_canvas_press(cx, cy, event.button)

        elif event.type == pygame.MOUSEBUTTONUP:
            if self.is_drawing:
                self.handle_canvas_release(self.cursor_x, self.cursor_y)

        elif event.type == pygame.MOUSEMOTION:
            if scale_x > 0 and scale_y > 0:
                mx, my = event.pos
                if canvas_blit_x <= mx < canvas_blit_x + scaled_canvas_w and canvas_blit_y <= my < canvas_blit_y + scaled_canvas_h:
                    cx = int((mx - canvas_blit_x) / scale_x)
                    cy = int((my - canvas_blit_y) / scale_y)
                    cx = max(0, min(255, cx))
                    cy = max(0, min(191, cy))
                    if self.input_device == "AMX":
                        update_amx_from_mouse(event.pos)
                    self.handle_canvas_drag(cx, cy)

        elif event.type == pygame.KEYDOWN:
            self.handle_key(event)

    def handle_key(self, event):
        if self.modal_active:
            if self.modal_type == "ESC_PROMPT":
                if event.key in (pygame.K_y, pygame.K_RETURN):
                    self.save_screen("screen")
                    self.running = False
                elif event.key == pygame.K_n:
                    self.running = False
                elif event.key in (pygame.K_c, pygame.K_ESCAPE):
                    self.modal_active = False
                    self.modal_type = None
                return
            elif self.modal_type in ("SAVE_PROMPT", "LOAD_PROMPT", "JPG_PROMPT"):
                if event.key == pygame.K_RETURN:
                    self.confirm_modal()
                elif event.key == pygame.K_ESCAPE:
                    self.modal_active = False
                    self.modal_type = None
                elif event.key == pygame.K_BACKSPACE:
                    self.modal_input = self.modal_input[:-1]
                elif event.unicode and event.unicode.isprintable():
                    self.modal_input += event.unicode
                return

        if self.tool == "TEXT":
            if event.key == pygame.K_ESCAPE:
                self.prompt_exit_modal()
            elif event.key == pygame.K_BACKSPACE:
                self.cursor_x = max(0, self.cursor_x - 8)
            elif event.unicode and event.unicode.isprintable():
                self.stamp_char(event.unicode)
            elif event.key == pygame.K_RETURN:
                self.cursor_x = 0
                self.cursor_y = min(184, self.cursor_y + 8)
            return

        mods = pygame.key.get_mods()
        shift = bool(mods & pygame.KMOD_SHIFT)

        if pygame.K_1 <= event.key <= pygame.K_8:
            num = event.key - pygame.K_1
            if shift:
                self.current_paper = num
                self.set_status(f"PAPER: {num}")
            else:
                self.current_ink = num
                self.set_status(f"INK: {num}")
            return

        if event.key == pygame.K_ESCAPE:
            self.prompt_exit_modal()
        elif event.key == pygame.K_b:
            self.toggle_bright()
        elif event.key == pygame.K_f:
            self.toggle_flash()
        elif event.key == pygame.K_x:
            self.swap_colors()
        elif event.key == pygame.K_m:
            self.cycle_input()
        elif event.key == pygame.K_j:
            self.cycle_joy_mode()
        elif event.key == pygame.K_a:
            self.cycle_attr_mode()
        elif event.key == pygame.K_t:
            self.cycle_tool()
        elif event.key == pygame.K_u:
            self.undo()
        elif event.key == pygame.K_r:
            self.redo()
        elif event.key == pygame.K_c:
            self.clear_screen()
        elif event.key == pygame.K_i:
            self.invert_screen()
        elif event.key == pygame.K_s:
            self.prompt_save_modal()
        elif event.key == pygame.K_l:
            self.prompt_load_modal()
        elif event.key == pygame.K_SPACE:
            if not self.is_drawing:
                self.handle_canvas_press(self.cursor_x, self.cursor_y, button=1)
            else:
                self.handle_canvas_release(self.cursor_x, self.cursor_y)

    def step_continuous_input(self, dt):
        if self.status_timer > 0:
            self.status_timer -= 1
        self.cursor_blink = (self.cursor_blink + 1) % 60
        self.modal_cursor_blink = (self.modal_cursor_blink + 1) % 60

        if self.modal_active:
            return

        keys = pygame.key.get_pressed()
        mods = pygame.key.get_mods()
        step = 4 if (mods & pygame.KMOD_SHIFT) else 1

        dx = 0
        dy = 0
        if keys[pygame.K_LEFT] or keys[pygame.K_o]: dx -= step
        if keys[pygame.K_RIGHT] or keys[pygame.K_p]: dx += step
        if keys[pygame.K_UP] or keys[pygame.K_q]: dy -= step
        if keys[pygame.K_DOWN] or keys[pygame.K_a]: dy += step

        if self.input_device == "JOY":
            global joystick
            j_state = get_joypad_state(joystick)
            if j_state["left"]: dx -= step
            if j_state["right"]: dx += step
            if j_state["up"]: dy -= step
            if j_state["down"]: dy += step
            if j_state["fire"]:
                if not self.is_drawing:
                    self.handle_canvas_press(self.cursor_x, self.cursor_y, button=1)
                else:
                    self.handle_canvas_drag(self.cursor_x, self.cursor_y)
            elif self.is_drawing and not keys[pygame.K_SPACE]:
                self.handle_canvas_release(self.cursor_x, self.cursor_y)

        if dx != 0 or dy != 0:
            self.cursor_x = max(0, min(255, self.cursor_x + dx))
            self.cursor_y = max(0, min(191, self.cursor_y + dy))
            if self.is_drawing:
                self.handle_canvas_drag(self.cursor_x, self.cursor_y)

    def render_toolbox(self, screen, rect):
        pygame.draw.rect(screen, (238, 238, 242), rect)
        pygame.draw.rect(screen, COLORS[1], rect, 2)

        cur_y = rect.y + 3
        pad_x = rect.x + 6
        avail_w = rect.width - 12

        banner_h = 24
        banner_rect = pygame.Rect(pad_x, cur_y, avail_w, banner_h)
        pygame.draw.rect(screen, COLORS[0], banner_rect)
        stripe_colors = [COLORS[2], COLORS[6], COLORS[4], COLORS[5]]
        stripe_w = 6
        for i, col in enumerate(stripe_colors):
            s_rect = pygame.Rect(banner_rect.right - 28 + (i * stripe_w), banner_rect.y, stripe_w, banner_h)
            pygame.draw.rect(screen, col, s_rect)

        title_surf = legend_font.render("ZX PAINT STUDIO  (Deluxe Paint / The Artist)", True, COLORS[7])
        screen.blit(title_surf, (banner_rect.x + 6, banner_rect.y + 4))
        cur_y += banner_h + 4

        btn_cols = 4
        btn_rows = 4
        btn_w = (avail_w - (btn_cols - 1) * 3) // btn_cols
        btn_h = 18

        self.tool_rects.clear()
        for idx, (t_name, label) in enumerate(self.TOOLS):
            col = idx % btn_cols
            row = idx // btn_cols
            bx = pad_x + col * (btn_w + 3)
            by = cur_y + row * (btn_h + 3)
            b_rect = pygame.Rect(bx, by, btn_w, btn_h)
            self.tool_rects[t_name] = b_rect

            is_active = (self.tool == t_name)
            bg_col = map_color(6, True) if is_active else COLORS[7]
            border_col = COLORS[2] if is_active else (140, 140, 160)
            text_col = COLORS[0] if is_active else COLORS[1]

            pygame.draw.rect(screen, bg_col, b_rect)
            pygame.draw.rect(screen, border_col, b_rect, 2 if is_active else 1)
            t_surf = legend_font.render(label[:7], True, text_col)
            screen.blit(t_surf, (b_rect.centerx - t_surf.get_width() // 2, b_rect.centery - t_surf.get_height() // 2))

        cur_y += btn_rows * (btn_h + 3) + 3

        swatch_w = (avail_w - 55) // 8
        swatch_h = 14

        ink_lbl = legend_font.render("INK:", True, COLORS[0])
        screen.blit(ink_lbl, (pad_x, cur_y + 1))
        self.ink_swatch_rects.clear()
        for c_idx in range(8):
            sx = pad_x + 36 + c_idx * (swatch_w + 2)
            s_rect = pygame.Rect(sx, cur_y, swatch_w, swatch_h)
            self.ink_swatch_rects.append(s_rect)
            c_rgb = map_color(c_idx, self.current_bright)
            pygame.draw.rect(screen, c_rgb, s_rect)
            if self.current_ink == c_idx:
                pygame.draw.rect(screen, COLORS[0], s_rect, 2)
                pygame.draw.rect(screen, COLORS[7], pygame.Rect(s_rect.centerx - 2, s_rect.centery - 2, 4, 4))
            else:
                pygame.draw.rect(screen, (100, 100, 120), s_rect, 1)

        cur_y += swatch_h + 3

        pap_lbl = legend_font.render("PAP:", True, COLORS[0])
        screen.blit(pap_lbl, (pad_x, cur_y + 1))
        self.paper_swatch_rects.clear()
        for c_idx in range(8):
            sx = pad_x + 36 + c_idx * (swatch_w + 2)
            s_rect = pygame.Rect(sx, cur_y, swatch_w, swatch_h)
            self.paper_swatch_rects.append(s_rect)
            c_rgb = map_color(c_idx, self.current_bright)
            pygame.draw.rect(screen, c_rgb, s_rect)
            if self.current_paper == c_idx:
                pygame.draw.rect(screen, COLORS[0], s_rect, 2)
                pygame.draw.rect(screen, COLORS[7], pygame.Rect(s_rect.centerx - 2, s_rect.centery - 2, 4, 4))
            else:
                pygame.draw.rect(screen, (100, 100, 120), s_rect, 1)

        cur_y += swatch_h + 4

        self.action_rects.clear()
        ctrl_w = (avail_w - 9) // 4
        ctrl_h = 16

        ctrls = [
            ("SWAP", "SWAP", COLORS[7], COLORS[0]),
            ("BRIGHT", f"BRT:{'1' if self.current_bright else '0'}", map_color(6, True) if self.current_bright else COLORS[7], COLORS[0]),
            ("FLASH", f"FLS:{'1' if self.current_flash else '0'}", map_color(2, True) if self.current_flash else COLORS[7], COLORS[0]),
            ("MODE", f"M:{self.attr_mode[:4]}", map_color(5, True) if self.attr_mode == "AUTO" else COLORS[7], COLORS[0])
        ]
        for c_i, (c_id, c_label, c_bg, c_fg) in enumerate(ctrls):
            cx = pad_x + c_i * (ctrl_w + 3)
            c_rect = pygame.Rect(cx, cur_y, ctrl_w, ctrl_h)
            self.action_rects[c_id] = c_rect
            pygame.draw.rect(screen, c_bg, c_rect)
            pygame.draw.rect(screen, (120, 120, 140), c_rect, 1)
            cs = legend_font.render(c_label, True, c_fg)
            screen.blit(cs, (c_rect.centerx - cs.get_width() // 2, c_rect.centery - cs.get_height() // 2))

        cur_y += ctrl_h + 4

        self.brush_rects.clear()
        b_lbl = legend_font.render("BRUSH:", True, COLORS[0])
        screen.blit(b_lbl, (pad_x, cur_y + 1))
        b_names = list(self.BRUSH_SHAPES.keys())
        bw = (avail_w - 50 - (len(b_names) - 1) * 2) // len(b_names)
        bw = max(18, bw)
        for b_i, b_name in enumerate(b_names):
            bx = pad_x + 48 + b_i * (bw + 2)
            b_rect = pygame.Rect(bx, cur_y, bw, ctrl_h)
            self.brush_rects[b_name] = b_rect
            is_b_act = (self.brush_shape == b_name)
            bg = map_color(6, True) if is_b_act else COLORS[7]
            pygame.draw.rect(screen, bg, b_rect)
            pygame.draw.rect(screen, COLORS[2] if is_b_act else (140, 140, 160), b_rect, 1)
            b_surf = legend_font.render(b_name[:3], True, COLORS[0])
            screen.blit(b_surf, (b_rect.centerx - b_surf.get_width() // 2, b_rect.centery - b_surf.get_height() // 2))

        cur_y += ctrl_h + 4

        in_lbl = legend_font.render("INPUT:", True, COLORS[0])
        screen.blit(in_lbl, (pad_x, cur_y + 1))
        in_w = (avail_w - 48 - 6) // 3
        in_btn = pygame.Rect(pad_x + 46, cur_y, in_w * 2, ctrl_h)
        self.action_rects["INPUT"] = in_btn
        pygame.draw.rect(screen, map_color(5, True), in_btn)
        pygame.draw.rect(screen, (100, 100, 140), in_btn, 1)
        in_txt = f"{self.input_device} {'MOUSE' if 'M' in self.input_device else ''}"
        in_s = legend_font.render(in_txt.strip(), True, COLORS[0])
        screen.blit(in_s, (in_btn.centerx - in_s.get_width() // 2, in_btn.centery - in_s.get_height() // 2))

        joy_btn = pygame.Rect(in_btn.right + 4, cur_y, in_w, ctrl_h)
        self.action_rects["JOY"] = joy_btn
        pygame.draw.rect(screen, COLORS[7], joy_btn)
        pygame.draw.rect(screen, (100, 100, 140), joy_btn, 1)
        j_s = legend_font.render(f"J:{self.joystick_mode}", True, COLORS[0])
        screen.blit(j_s, (joy_btn.centerx - j_s.get_width() // 2, joy_btn.centery - j_s.get_height() // 2))

        cur_y += ctrl_h + 4

        stor_w = (avail_w - 9) // 4
        s_btns = [
            ("SAVE", "SAVE.SCR", COLORS[7], COLORS[1]),
            ("LOAD", "LOAD.SCR", COLORS[7], COLORS[1]),
            ("JPG", "IMPORT JPG", COLORS[7], (140, 40, 0)),
            ("DEV", f"[{self.dev_target[:5]}]", (220, 225, 245), COLORS[0]),
            ("UNDO", "UNDO (U)", COLORS[7], COLORS[0]),
            ("REDO", "REDO (R)", COLORS[7], COLORS[0]),
            ("INV", "INVERT", COLORS[7], COLORS[0]),
            ("EXIT", "EXIT (ESC)", (255, 220, 220), COLORS[2])
        ]
        for s_i, (s_id, s_lbl, s_bg, s_fg) in enumerate(s_btns):
            row_idx = s_i // 4
            col_idx = s_i % 4
            sx = pad_x + col_idx * (stor_w + 3)
            sy = cur_y + row_idx * (ctrl_h + 3)
            s_rect = pygame.Rect(sx, sy, stor_w, ctrl_h)
            self.action_rects[s_id] = s_rect
            pygame.draw.rect(screen, s_bg, s_rect)
            pygame.draw.rect(screen, (120, 120, 150), s_rect, 1)
            ss = legend_font.render(s_lbl, True, s_fg)
            screen.blit(ss, (s_rect.centerx - ss.get_width() // 2, s_rect.centery - ss.get_height() // 2))

        cur_y += 2 * (ctrl_h + 3) + 3

        if self.modal_active:
            m_h = 70
            m_rect = pygame.Rect(pad_x + 4, cur_y, avail_w - 8, m_h)
            pygame.draw.rect(screen, (255, 255, 230), m_rect)
            pygame.draw.rect(screen, COLORS[2], m_rect, 2)

            m_surf = legend_font.render(self.modal_text, True, COLORS[0])
            screen.blit(m_surf, (m_rect.x + 8, m_rect.y + 6))

            if self.modal_type == "ESC_PROMPT":
                bw3 = (m_rect.width - 24) // 3
                y_rect = pygame.Rect(m_rect.x + 6, m_rect.y + 34, bw3, 24)
                n_rect = pygame.Rect(y_rect.right + 6, m_rect.y + 34, bw3, 24)
                c_rect = pygame.Rect(n_rect.right + 6, m_rect.y + 34, bw3, 24)
                self.action_rects["MODAL_YES"] = y_rect
                self.action_rects["MODAL_NO"] = n_rect
                self.action_rects["MODAL_CANCEL"] = c_rect

                for br, btxt, bgc, fgc in ((y_rect, "YES (Y)", map_color(4, True), COLORS[0]),
                                           (n_rect, "NO (N)", map_color(6, True), COLORS[0]),
                                           (c_rect, "CANCEL (C)", COLORS[7], COLORS[2])):
                    pygame.draw.rect(screen, bgc, br)
                    pygame.draw.rect(screen, COLORS[0], br, 1)
                    bs = legend_font.render(btxt, True, fgc)
                    screen.blit(bs, (br.centerx - bs.get_width() // 2, br.centery - bs.get_height() // 2))
            else:
                in_box = pygame.Rect(m_rect.x + 6, m_rect.y + 26, m_rect.width - 90, 20)
                pygame.draw.rect(screen, COLORS[7], in_box)
                pygame.draw.rect(screen, COLORS[0], in_box, 1)
                cursor_char = "_" if (self.modal_cursor_blink < 30) else ""
                disp_inp = self.modal_input + cursor_char
                in_surf = legend_font.render(disp_inp, True, COLORS[0])
                screen.blit(in_surf, (in_box.x + 4, in_box.y + 3))

                ok_r = pygame.Rect(in_box.right + 4, in_box.y, 38, 20)
                cc_r = pygame.Rect(ok_r.right + 3, in_box.y, 38, 20)
                self.action_rects["MODAL_OK"] = ok_r
                self.action_rects["MODAL_CANCEL"] = cc_r
                pygame.draw.rect(screen, map_color(4, True), ok_r)
                pygame.draw.rect(screen, COLORS[0], ok_r, 1)
                ok_s = legend_font.render("OK", True, COLORS[0])
                screen.blit(ok_s, (ok_r.centerx - ok_s.get_width() // 2, ok_r.centery - ok_s.get_height() // 2))

                pygame.draw.rect(screen, COLORS[7], cc_r)
                pygame.draw.rect(screen, COLORS[0], cc_r, 1)
                cc_s = legend_font.render("CAN", True, COLORS[2])
                screen.blit(cc_s, (cc_r.centerx - cc_s.get_width() // 2, cc_r.centery - cc_s.get_height() // 2))

        stat_h = 44
        stat_rect = pygame.Rect(pad_x, rect.bottom - stat_h - 4, avail_w, stat_h)
        pygame.draw.rect(screen, (25, 25, 45), stat_rect)
        pygame.draw.rect(screen, COLORS[1], stat_rect, 1)

        cell_c = self.cursor_x // 8
        cell_r = self.cursor_y // 8
        cell_ink = attr_ink[cell_r][cell_c] if (0 <= cell_r < 24 and 0 <= cell_c < 32) else 0
        cell_pap = attr_paper[cell_r][cell_c] if (0 <= cell_r < 24 and 0 <= cell_c < 32) else 7
        cell_brt = int(attr_bright[cell_r][cell_c]) if (0 <= cell_r < 24 and 0 <= cell_c < 32) else 0

        coords_str = f"X:{self.cursor_x:03d} Y:{self.cursor_y:03d} [C:{cell_c:02d} R:{cell_r:02d}]  INK:{cell_ink} PAP:{cell_pap} B:{cell_brt}"
        coord_s = legend_font.render(coords_str, True, map_color(6, True))
        screen.blit(coord_s, (stat_rect.x + 6, stat_rect.y + 4))

        stat_s = legend_font.render(self.status_message, True, COLORS[7])
        screen.blit(stat_s, (stat_rect.x + 6, stat_rect.y + 22))

    def render_canvas_cursor(self, screen, canvas_blit_x, canvas_blit_y, scale_x, scale_y):
        if scale_x <= 0 or scale_y <= 0:
            return

        if self.is_drawing and self.start_x is not None and self.start_y is not None:
            preview_pts = self.get_shape_points(self.tool, self.start_x, self.start_y, self.cursor_x, self.cursor_y)
            prev_col = map_color(self.current_ink, self.current_bright) if (self.draw_color == 1) else map_color(self.current_paper, self.current_bright)
            pw = max(1, int(scale_x))
            ph = max(1, int(scale_y))
            for px, py in preview_pts:
                sx = canvas_blit_x + int(px * scale_x)
                sy = canvas_blit_y + int(py * scale_y)
                pygame.draw.rect(screen, prev_col, pygame.Rect(sx, sy, pw, ph))

        if self.tool == "TEXT":
            bx = canvas_blit_x + int(self.cursor_x * scale_x)
            by = canvas_blit_y + int(self.cursor_y * scale_y)
            bw = int(8 * scale_x)
            bh = int(8 * scale_y)
            pygame.draw.rect(screen, map_color(2, True), pygame.Rect(bx, by, bw, bh), 1)

        cx = canvas_blit_x + int(self.cursor_x * scale_x)
        cy = canvas_blit_y + int(self.cursor_y * scale_y)

        if self.input_device in ("AMX", "KEMP"):
            render_amx_pointer(screen, canvas_blit_x, canvas_blit_y, scale_x, scale_y)
        else:
            cross_color = map_color(6, True) if (self.cursor_blink < 30) else map_color(2, True)
            ch_len = int(5 * max(1.0, scale_x))
            pygame.draw.line(screen, COLORS[0], (cx - ch_len - 1, cy), (cx + ch_len + 1, cy), 2)
            pygame.draw.line(screen, COLORS[0], (cx, cy - ch_len - 1), (cx, cy + ch_len + 1), 2)
            pygame.draw.line(screen, cross_color, (cx - ch_len, cy), (cx + ch_len, cy), 1)
            pygame.draw.line(screen, cross_color, (cx, cy - ch_len), (cx, cy + ch_len), 1)

        if self.tool in ("BRUSH", "ERASER"):
            offsets = self.BRUSH_SHAPES.get(self.brush_shape, [(0, 0)])
            pw = max(1, int(scale_x))
            ph = max(1, int(scale_y))
            for dx, dy in offsets:
                px = self.cursor_x + dx
                py = self.cursor_y + dy
                if 0 <= px < 256 and 0 <= py < 192:
                    bsx = canvas_blit_x + int(px * scale_x)
                    bsy = canvas_blit_y + int(py * scale_y)
                    pygame.draw.rect(screen, map_color(6, True), pygame.Rect(bsx, bsy, pw, ph), 1)


def launch_paint_studio(args=""):
    global paint_editor_active, active_paint_studio, canvas_dirty, screen, canvas, clock
    studio = ZXPaintStudio()
    active_paint_studio = studio

    clean_args = args.strip().strip('"').strip("'").strip()
    if clean_args:
        if clean_args.lower().endswith(".jpg") or clean_args.lower().endswith(".jpeg"):
            studio.import_jpg(clean_args)
        else:
            studio.load_screen(clean_args)

    if os.environ.get("SDL_VIDEODRIVER") == "dummy":
        paint_editor_active = True
        return studio

    paint_editor_active = True
    studio.running = True
    clock = pygame.time.Clock()

    try:
        while studio.running:
            dt = clock.tick(60)
            studio.step_continuous_input(dt)

            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    studio.running = False
                    pygame.quit()
                    sys.exit(0)
                elif event.type == pygame.VIDEORESIZE:
                    screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
                else:
                    studio.handle_event(event)

            if canvas_dirty:
                redraw_canvas(force=True)
            render_frame()
            try:
                pygame.display.flip()
            except Exception:
                pass
    finally:
        paint_editor_active = False
        active_paint_studio = None
        if 'pygame' in globals() and pygame.get_init() and pygame.display.get_init():
            canvas_dirty = True
            try:
                redraw_canvas(force=True)
                render_frame()
                pygame.display.flip()
            except Exception:
                pass
            canvas_print("Returned from ZX Paint Studio.")
            try:
                update_display()
            except Exception:
                pass


def get_status_bar_info():
    """Returns (status_text, status_type, mode_text, line_text, info_text) for the input area status bar."""
    # 1. Operational Status
    cpu = globals().get('z80_cpu', None)
    if 'get_z80_cpu' in globals():
        try: cpu = get_z80_cpu()
        except Exception: pass
    is_mc_running = (cpu is not None and getattr(cpu, 'is_running', False))

    if globals().get('program_execution_mode', False) or is_mc_running:
        st_text = "RUNNING"
        st_type = "RUNNING"
    elif globals().get('listing_edit_active', False):
        st_text = "EDITING"
        st_type = "EDITING"
    elif globals().get('find_prompt_active', False):
        st_text = "FIND"
        st_type = "FIND"
    elif globals().get('listing_monitor_active', False) or globals().get('z80_monitor_mode', False):
        mon = get_crystal_monitor() if 'get_crystal_monitor' in globals() else None
        st_stat = mon.last_status if mon and hasattr(mon, 'last_status') else "OK"
        st_text = f"Z80 MON [{st_stat}]"
        st_type = "MONITOR"
    elif globals().get('listing_vars_active', False):
        st_text = "VARS"
        st_type = "VARS"
    elif globals().get('listing_code_active', False):
        st_text = "LIST CODE"
        st_type = "CODE"
    elif globals().get('zxdb_browser_active', False):
        st_text = "ZXDB ARCHIVE"
        st_type = "ARCHIVE"
    elif globals().get('cpm_mode_active', False):
        st_text = "CP/M 3.0"
        st_type = "CPM"
    elif globals().get('z80_interactive_mode', False):
        st_text = "ZEUS Z80"
        st_type = "ZEUS"
    elif globals().get('prolog_interactive_mode', False):
        st_text = "MICRO-PROLOG"
        st_type = "PROLOG"
    elif globals().get('logo_interactive_mode', False):
        st_text = "LOGO"
        st_type = "LOGO"
    elif globals().get('forth_interactive_mode', False):
        st_text = "FORTH"
        st_type = "FORTH"
    elif globals().get('spectrum_mode', '48K') == "NEXT":
        st_text = "NEXT"
        st_type = "NEXT"
    else:
        st_text = "READY"
        st_type = "READY"

    # 2. Mode of Operation & Input Mode Letter
    if globals().get('cpm_mode_active', False):
        mode_text = "+3 CP/M PLUS"
    elif globals().get('z80_interactive_mode', False):
        mode_text = "ZEUS ASSEMBLER"
    elif globals().get('forth_interactive_mode', False):
        mode_text = "FORTH-79"
    elif globals().get('prolog_interactive_mode', False):
        mode_text = "MICRO-PROLOG"
    elif globals().get('logo_interactive_mode', False):
        mode_text = "ZX LOGO"
    else:
        sp_mode = globals().get('spectrum_mode', '48K')
        if sp_mode == "NEXT":
            hw_str = "ZX NEXT"
        elif sp_mode == "TS2068":
            hw_str = "TS2068"
        elif globals().get('plus3_mode', False) or sp_mode in ("PLUS3", "128K_PLUS3"):
            hw_str = "ZX +3"
        elif globals().get('spectrum_128k_mode', False) or sp_mode == "128K":
            hw_str = "ZX 128K"
        else:
            hw_str = "ZX 48K"

        m_let = "C" if globals().get('cpm_mode_active', False) else ("Z" if globals().get('z80_interactive_mode', False) else ("M" if (globals().get('z80_monitor_mode', False) or globals().get('listing_monitor_active', False)) else ("P" if globals().get('prolog_interactive_mode', False) else ("L" if globals().get('logo_interactive_mode', False) else ("F" if globals().get('forth_interactive_mode', False) else ("E" if globals().get('listing_edit_active', False) else ("?" if globals().get('find_prompt_active', False) else "K")))))))
        mode_text = f"{hw_str} BASIC [{m_let}]"

    # 3. Line Number (if BASIC etc.)
    prog = globals().get('program', {})
    if globals().get('program_execution_mode', False):
        c_ln = globals().get('current_running_line') or globals().get('current_trace_line')
        line_text = f"Line {c_ln}" if c_ln is not None else "Line: RUN"
    elif globals().get('listing_edit_active', False):
        e_ln = globals().get('listing_edit_ln', None)
        line_text = f"Line {e_ln}" if e_ln is not None else "Line: (New)"
    elif globals().get('find_prompt_active', False):
        line_text = "Find"
    elif globals().get('cpm_mode_active', False):
        line_text = "Drive A:"
    elif globals().get('z80_interactive_mode', False):
        pc = globals().get('z80_pc', 0x8000)
        line_text = f"PC: {hex(pc)[2:].upper()}H"
    elif globals().get('forth_interactive_mode', False):
        stk = globals().get('forth_data_stack', [])
        line_text = f"Stack [{len(stk)}]"
    else:
        inp = globals().get('input_text', '').strip()
        m_num = re.match(r'^(\d+)', inp)
        if m_num:
            line_text = f"Line {m_num.group(1)}"
        elif prog:
            sorted_lns = sorted(prog.keys())
            sc_idx = globals().get('listing_scroll_index', 0)
            if 0 <= sc_idx < len(sorted_lns):
                cur_ln = sorted_lns[sc_idx]
                line_text = f"Line {cur_ln} ({len(prog)})"
            else:
                line_text = f"Lines: {len(prog)}"
        else:
            line_text = "Line: --"

    # 4. Cursor / Free RAM Information
    cur_pos = globals().get('input_cursor_pos', 0)
    sp_mode = globals().get('spectrum_mode', '48K')
    if sp_mode == "NEXT":
        turbo_spd = globals().get('next_turbo_speed', 3)
        mhz_val = [3.5, 7, 14, 28][turbo_spd] if 0 <= turbo_spd <= 3 else 28
        mhz_str = f"{int(mhz_val)}MHz" if isinstance(mhz_val, int) or mhz_val.is_integer() else f"{mhz_val}MHz"
        info_text = f"Col {cur_pos + 1} | {mhz_str} | 1.8M Free"
    else:
        free_mem = int(get_free_memory()) if 'get_free_memory' in globals() else 41000
        if free_mem >= 1024:
            mem_str = f"{free_mem / 1024.0:.1f}K Free"
        else:
            mem_str = f"{free_mem}B Free"
        info_text = f"Col {cur_pos + 1} | {mem_str}"

    return st_text, st_type, mode_text, line_text, info_text


def render_frame():
    global listing_scroll_index, flash_phase, input_text, input_cursor_pos, listing_rect, prompt_rect
    global listing_edit_active, listing_edit_ln, listing_edit_text, listing_edit_cursor, listing_cursor_blink
    global canvas_blit_x, canvas_blit_y, scale_x, scale_y, scaled_canvas_w, scaled_canvas_h
    if not ('pygame' in globals() and pygame.get_init() and pygame.display.get_init() and 'screen' in globals() and screen):
        return
    if canvas_dirty:
        redraw_canvas()
    win_w, win_h = screen.get_size()
    screen.fill(COLORS[0])

    if fullscreen_mode:
        # Fullscreen Spectrum Output Window: preserve proportions, hide rest of UI
        if win_w / float(win_h) > ASPECT_RATIO:
            spectrum_h = win_h
            spectrum_w = int(spectrum_h * ASPECT_RATIO)
            spectrum_x = (win_w - spectrum_w) // 2
            spectrum_y = 0
        else:
            spectrum_w = win_w
            spectrum_h = int(spectrum_w / float(ASPECT_RATIO))
            spectrum_x = 0
            spectrum_y = (win_h - spectrum_h) // 2

        border_rect = pygame.Rect(spectrum_x, spectrum_y, spectrum_w, spectrum_h)
        if tape_simulation_active:
            render_tape_border_stripes(screen, border_rect, scale_y, tape_sim_phase, tape_sim_frame)
        else:
            screen.fill(map_color(current_border, False), border_rect)

        scale_x = spectrum_w / float(EMULATED_TOTAL_W)
        scale_y = spectrum_h / float(EMULATED_TOTAL_H)
        scaled_canvas_w = int(CANVAS_W * scale_x)
        scaled_canvas_h = int(CANVAS_H * scale_y)

        scaled_canvas = pygame.transform.scale(canvas, (scaled_canvas_w, scaled_canvas_h))
        canvas_blit_x = spectrum_x + int(BORDER_PX * scale_x)
        canvas_blit_y = spectrum_y + int(BORDER_PX * scale_y)
        screen.blit(scaled_canvas, (canvas_blit_x, canvas_blit_y))

        # Render character screen grid (32 cols x 24 rows) at precise cell coordinates
        text_scale_font = get_scale_font(max(10, int(11 * scale_y)))
        max_right_x = canvas_blit_x + scaled_canvas_w

        cpu = get_z80_cpu() if 'get_z80_cpu' in globals() else globals().get('z80_cpu', None)
        is_mc_running = (cpu is not None and getattr(cpu, 'is_running', False))
        if not cpm_mode_active and not udg_editor_active and not music_editor_active and not sfx_editor_active and not drum_editor_active and not paint_editor_active and not is_mc_running and not gui_mode and timex_screen_mode not in (2, 6):
            for r, row_chars in enumerate(screen_chars):
                if r >= 24:
                    break
                text_y = canvas_blit_y + int(r * 8 * scale_y)
                for c, ch in enumerate(row_chars):
                    if c >= 32:
                        break
                    text_x = canvas_blit_x + int(c * 8 * scale_x)
                    if text_x >= max_right_x:
                        break
                    render_spectrum_cell(r, c, ch, text_x, text_y, scale_x, scale_y, text_scale_font, screen)

        if amx_pointer_visible:
            render_amx_pointer(screen, canvas_blit_x, canvas_blit_y, scale_x, scale_y)
        render_logo_turtle(screen, canvas_blit_x, canvas_blit_y, scale_x, scale_y)
        if paint_editor_active and active_paint_studio:
            active_paint_studio.render_canvas_cursor(screen, canvas_blit_x, canvas_blit_y, scale_x, scale_y)

        if trace_on and current_trace_line is not None:
            trace_font = get_scale_font(max(10, int(12 * scale_y)))
            trace_text = f" {current_trace_line} "
            trace_surf = trace_font.render(trace_text, True, COLORS[0])
            trace_bg_rect = trace_surf.get_rect()
            padding = int(8 * scale_x)
            trace_bg_rect.right = border_rect.right - padding
            trace_bg_rect.bottom = border_rect.bottom - padding
            pygame.draw.rect(screen, COLORS[7], trace_bg_rect)
            screen.blit(trace_surf, trace_bg_rect.topleft)

        if clock_display_active:
            clk_font = get_scale_font(max(10, int(11 * scale_y)))
            clk_surf = clk_font.render(time.strftime("%H:%M:%S"), True, COLORS[0], COLORS[7])
            screen.blit(clk_surf, (border_rect.right - clk_surf.get_width() - int(4 * scale_x), border_rect.top + int(4 * scale_y)))

        listing_rect = pygame.Rect(-1000, -1000, 0, 0)
        prompt_rect = pygame.Rect(-1000, -1000, 0, 0)
        return

    prompt_h = 36
    content_h = win_h - (MARGIN * 3) - prompt_h
    content_h = max(200, content_h)

    spectrum_h = content_h
    spectrum_w = int(spectrum_h * ASPECT_RATIO)

    listing_w = win_w - spectrum_w - (MARGIN * 3)
    if listing_w < 350:
        listing_w = 350
        spectrum_w = win_w - listing_w - (MARGIN * 3)
        spectrum_h = int(spectrum_w / ASPECT_RATIO)

    # Left Panel: Code Listing with Scrolling Support
    listing_rect = pygame.Rect(MARGIN, MARGIN, listing_w, spectrum_h)
    pygame.draw.rect(screen, COLORS[7], listing_rect)
    pygame.draw.rect(screen, COLORS[1], listing_rect, 2)

    list_y = listing_rect.y + 6
    if listing_monitor_active:
        title_surf = font.render("Crystal Computing Z80 Monitor & Disassembler", True, (0, 70, 180))
    elif listing_vars_active:
        title_surf = font.render("Defined Variables [VARS] (Type LIST to return)", True, COLORS[1])
    elif listing_code_active:
        title_surf = font.render("Compiled Code Blocks [LIST CODE] (Type LIST to return)", True, (160, 40, 0))
    elif listing_edit_active:
        title_surf = font.render("Program Code Listing [EDITING - Enter:save, Esc:exit]", True, COLORS[2])
    else:
        title_surf = font.render("Program Code Listing (Click line to edit)", True, COLORS[1])
    screen.blit(title_surf, (listing_rect.x + 10, list_y))
    list_y += 18

    # Visual Compliance Legend Bar (or Monitor Command Guide if monitor active)
    if listing_monitor_active:
        cmd_guide = "[D]is [M]em [R]eg [B]rk [S]tep [O]ver [G]o [A]sm [?]Help [X]Exit"
        g_surf = legend_font.render(cmd_guide, True, (80, 80, 80))
        screen.blit(g_surf, (listing_rect.x + 10, list_y))
    elif listing_code_active:
        cmd_guide = "[TYPE] Line/Origin  Address (Hex)  Length (Bytes)"
        g_surf = legend_font.render(cmd_guide, True, (60, 60, 90))
        screen.blit(g_surf, (listing_rect.x + 10, list_y))
    else:
        legend_tags = [
            ("48K", COMPLIANCE_COLORS["48K"]),
            ("128K", COMPLIANCE_COLORS["128K"]),
            ("BB3", COMPLIANCE_COLORS["BB3"]),
            ("BB4", COMPLIANCE_COLORS["BB4"]),
            ("BORIEL", COMPLIANCE_COLORS["BORIEL"]),
            ("TS2068", COMPLIANCE_COLORS["TS2068"]),
            ("NEXT", COMPLIANCE_COLORS["NEXT"]),
            ("PERIPH", COMPLIANCE_COLORS["PERIPH"]),
            ("SYSTEM", COMPLIANCE_COLORS["SYSTEM"]),
        ]
        cur_tag_x = listing_rect.x + 10
        for label, col in legend_tags:
            t_surf = legend_font.render(f"[{label}]", True, col)
            screen.blit(t_surf, (cur_tag_x, list_y))
            cur_tag_x += t_surf.get_width() + 6

    list_y += 18

    if listing_monitor_active:
        mon = get_crystal_monitor()
        reg_lines = mon.get_register_lines()
        reg_box_h = len(reg_lines) * 16 + 6
        reg_rect = pygame.Rect(listing_rect.x + 6, list_y, listing_rect.width - 12, reg_box_h)
        pygame.draw.rect(screen, (242, 246, 252), reg_rect)
        pygame.draw.rect(screen, (160, 185, 220), reg_rect, 1)

        for r_idx, r_text in enumerate(reg_lines):
            r_surf = legend_font.render(r_text, True, (20, 30, 80))
            screen.blit(r_surf, (reg_rect.x + 6, list_y + 3 + r_idx * 16))

        list_y += reg_box_h + 6

        mon_lines = mon.history
        max_visible_lines = max(1, (listing_rect.height - (list_y - listing_rect.y) - 24) // 16)
        total_items = len(mon_lines)
        listing_scroll_index = max(0, min(listing_scroll_index, max(0, total_items - max_visible_lines)))

        clip_rect = pygame.Rect(listing_rect.x + 2, list_y, listing_rect.width - 4, listing_rect.height - (list_y - listing_rect.y) - 22)
        screen.set_clip(clip_rect)
        for visible_row in range(max_visible_lines):
            item_idx = listing_scroll_index + visible_row
            row_y = list_y + (visible_row * 16)
            if item_idx >= total_items:
                break
            m_line = mon_lines[item_idx]
            row_rect = pygame.Rect(listing_rect.x + 4, row_y, listing_rect.width - 8, 16)
            if m_line.startswith(">"):
                pygame.draw.rect(screen, (255, 252, 204), row_rect)
                pygame.draw.rect(screen, (230, 195, 40), row_rect, 1)
                l_col = (180, 30, 0)
            elif m_line.startswith("*"):
                pygame.draw.rect(screen, (255, 235, 235), row_rect)
                l_col = (200, 0, 0)
            elif m_line.startswith("***"):
                pygame.draw.rect(screen, (255, 225, 225), row_rect)
                l_col = (190, 0, 0)
            elif m_line.startswith(";") or m_line.startswith("-"):
                l_col = (110, 110, 110)
            else:
                l_col = (20, 20, 40)
            l_surf = legend_font.render(m_line, True, l_col)
            screen.blit(l_surf, (listing_rect.x + 8, row_y + 1))
        screen.set_clip(None)
    elif listing_vars_active:
        var_lines = get_vars_listing_lines()
        max_visible_lines = max(1, (listing_rect.height - (list_y - listing_rect.y) - 6) // 18)
        total_items = len(var_lines)
        listing_scroll_index = max(0, min(listing_scroll_index, max(0, total_items - max_visible_lines)))

        clip_rect = pygame.Rect(listing_rect.x + 2, listing_rect.y + 2, listing_rect.width - 4, listing_rect.height - 4)
        screen.set_clip(clip_rect)
        text_start_x = listing_rect.x + 10
        for visible_row in range(max_visible_lines):
            item_idx = listing_scroll_index + visible_row
            row_y = list_y + (visible_row * 18)
            if item_idx >= total_items:
                break
            v_line = var_lines[item_idx]
            v_surf = font.render(v_line, True, COLORS[1])
            screen.blit(v_surf, (text_start_x, row_y))
        screen.set_clip(None)
    elif listing_code_active:
        code_lines = get_code_listing_lines()
        max_visible_lines = max(1, (listing_rect.height - (list_y - listing_rect.y) - 6) // 18)
        total_items = len(code_lines)
        listing_scroll_index = max(0, min(listing_scroll_index, max(0, total_items - max_visible_lines)))

        clip_rect = pygame.Rect(listing_rect.x + 2, listing_rect.y + 2, listing_rect.width - 4, listing_rect.height - 4)
        screen.set_clip(clip_rect)
        text_start_x = listing_rect.x + 10
        for visible_row in range(max_visible_lines):
            item_idx = listing_scroll_index + visible_row
            row_y = list_y + (visible_row * 18)
            if item_idx >= total_items:
                break
            entry = code_lines[item_idx]
            c_text, c_col = entry if isinstance(entry, tuple) else (entry, COLORS[1])
            c_surf = font.render(c_text, True, c_col)
            screen.blit(c_surf, (text_start_x, row_y))
        screen.set_clip(None)
    else:
        cur_prog = zeus_source if z80_interactive_mode else program
        line_nums = sorted(cur_prog.keys())
        max_visible_lines = max(1, (listing_rect.height - (list_y - listing_rect.y) - 6) // 18)
        total_items = len(line_nums) + (1 if (listing_edit_active and listing_edit_ln is None) else 0)
        listing_scroll_index = max(0, min(listing_scroll_index, max(0, total_items - max_visible_lines)))

