last_display_time = 0


def update_display():
    global last_display_time
    if not ('pygame' in globals() and pygame.get_init() and pygame.display.get_init()):
        return
    try:
        last_display_time = pygame.time.get_ticks()
        pygame.event.pump()
        if canvas_dirty:
            redraw_canvas()
        render_frame()
        pygame.display.flip()
        if 'clock' in globals() and clock:
            clock.tick(60)
        last_display_time = pygame.time.get_ticks()
    except Exception:
        pass


def canvas_print(text):
    global canvas_lines, canvas_dirty, print_row, print_col, screen_chars, screen_bitmap_dirty
    for raw_line in str(text).split('\n'):
        sub_lines = [raw_line[j:j+32] for j in range(0, max(1, len(raw_line)), 32)] if raw_line else [""]
        for line in sub_lines:
            canvas_lines.append(line)
            if len(canvas_lines) > 50:
                canvas_lines.pop(0)
            try:
                if 'screen_chars' in globals() and screen_chars:
                    if 0 <= print_row < 24:
                        for i, ch in enumerate(line[:32]):
                            screen_chars[print_row][i] = ch
                        for i in range(len(line[:32]), 32):
                            screen_chars[print_row][i] = ' '
                        print_row += 1
                        if print_row >= 24:
                            print_row = 23
                            if 'scroll_screen' in globals():
                                scroll_screen()
                        canvas_dirty = True
                        screen_bitmap_dirty = True
            except Exception:
                pass


def find_matching_paren(s, open_idx):
    depth = 0
    in_q = False
    for i in range(open_idx, len(s)):
        ch = s[i]
        if ch == '"':
            in_q = not in_q
        elif not in_q:
            if ch == '(':
                depth += 1
            elif ch == ')':
                depth -= 1
                if depth == 0:
                    return i
    return -1


def is_single_quoted_string(s):
    s = s.strip()
    if len(s) >= 2 and (s[0] in ('"', "'")) and s[-1] == s[0]:
        q = s[0]
        i = 1
        while i < len(s) - 1:
            if s[i] == q:
                if i + 1 < len(s) - 1 and s[i+1] == q:
                    i += 2
                    continue
                return False
            i += 1
        return True
    return False


def split_top_level_commas(s):
    parts = []
    curr = []
    depth = 0
    in_q = False
    for ch in s:
        if ch == '"':
            in_q = not in_q
            curr.append(ch)
        elif not in_q:
            if ch == '(':
                depth += 1
                curr.append(ch)
            elif ch == ')':
                depth = max(0, depth - 1)
                curr.append(ch)
            elif ch == ',' and depth == 0:
                parts.append("".join(curr).strip())
                curr = []
            else:
                curr.append(ch)
        else:
            curr.append(ch)
    if curr:
        parts.append("".join(curr).strip())
    return parts


def parse_slice_indices(s_len, spec):
    spec = spec.strip()
    if not spec:
        return 1, s_len

    upper_spec = spec.upper()
    to_idx = -1
    depth = 0
    in_q = False

    i = 0
    while i < len(spec):
        ch = spec[i]
        if ch == '"':
            in_q = not in_q
        elif not in_q:
            if ch == '(':
                depth += 1
            elif ch == ')':
                depth = max(0, depth - 1)
            elif depth == 0:
                if upper_spec[i:i+2] == "TO":
                    before_ok = (i == 0 or not spec[i-1].isalnum())
                    after_ok = (i + 2 == len(spec) or not spec[i+2].isalnum())
                    if before_ok and after_ok:
                        to_idx = i
                        break
        i += 1

    if to_idx != -1:
        start_part = spec[:to_idx].strip()
        end_part = spec[to_idx+2:].strip()
        try: start = int(float(evaluate_expr(start_part))) if start_part else 1
        except (ValueError, TypeError): start = 1
        try: end = int(float(evaluate_expr(end_part))) if end_part else s_len
        except (ValueError, TypeError): end = s_len
    else:
        try: idx = int(float(evaluate_expr(spec)))
        except (ValueError, TypeError): idx = 1
        start = idx
        end = idx

    return start, end


def slice_string(s, spec):
    s = str(s)
    start, end = parse_slice_indices(len(s), spec)
    if start == end + 1 and 1 <= start <= len(s) + 1:
        return ""
    if start < 1 or start > len(s) + 1 or end < start - 1 or end > len(s):
        raise Exception("Subscript out of range")
    return s[start - 1 : end]


def assign_string_slice(curr_str, spec, repl_val):
    curr_str = str(curr_str)
    repl_val = str(repl_val)
    start, end = parse_slice_indices(len(curr_str), spec)
    if start == end + 1 and 1 <= start <= len(curr_str) + 1:
        return curr_str
    if start < 1 or start > len(curr_str) or end < start or end > len(curr_str):
        raise Exception("Subscript out of range")
    slice_len = end - start + 1
    if len(repl_val) < slice_len:
        repl_fitted = repl_val.ljust(slice_len, ' ')
    else:
        repl_fitted = repl_val[:slice_len]
    return curr_str[:start-1] + repl_fitted + curr_str[end:]


def get_string_value(var_name, spec):
    global arrays, ram_disk_arrays, string_variables
    var_name = var_name.upper()
    target_arr = arrays if var_name in arrays else (ram_disk_arrays if var_name in ram_disk_arrays else (ram_disk_arrays if f"!{var_name}" in ram_disk_arrays else None))
    actual_name = var_name if target_arr is not ram_disk_arrays or var_name in ram_disk_arrays else f"!{var_name}"

    if target_arr is not None:
        args = split_top_level_commas(spec)
        try:
            row = int(float(evaluate_expr(args[0])))
        except (ValueError, TypeError):
            row = 0
        if row < 0 or row >= len(target_arr[actual_name]):
            raise Exception("Subscript out of range")
        row_str = target_arr[actual_name][row]
        if len(args) == 1:
            return row_str
        elif len(args) == 2:
            return slice_string(row_str, args[1])
        else:
            raise Exception("Subscript out of range")
    else:
        s = string_variables.get(var_name, "")
        return slice_string(s, spec)


def set_string_value(var_name, spec, val):
    global arrays, ram_disk_arrays, string_variables
    var_name = var_name.upper()
    val_str = str(val)
    target_arr = arrays if var_name in arrays else (ram_disk_arrays if var_name in ram_disk_arrays else (ram_disk_arrays if f"!{var_name}" in ram_disk_arrays else None))
    actual_name = var_name if target_arr is not ram_disk_arrays or var_name in ram_disk_arrays else f"!{var_name}"

    if target_arr is not None:
        args = split_top_level_commas(spec)
        try:
            row = int(float(evaluate_expr(args[0])))
        except (ValueError, TypeError):
            row = 0
        if row < 0 or row >= len(target_arr[actual_name]):
            raise Exception("Subscript out of range")
        row_str = target_arr[actual_name][row]
        str_len = len(row_str)
        if len(args) == 1:
            target_arr[actual_name][row] = val_str.ljust(str_len, ' ')[:str_len]
        elif len(args) == 2:
            target_arr[actual_name][row] = assign_string_slice(row_str, args[1], val_str)
        else:
            raise Exception("Subscript out of range")
    else:
        if var_name not in string_variables:
            raise Exception("Subscript out of range")
        string_variables[var_name] = assign_string_slice(string_variables[var_name], spec, val_str)


def resolve_strings_and_slices(expr):
    out = []
    i = 0
    n = len(expr)
    builtins = {
        "CHR$", "STR$", "SCREEN$", "VAL$", "INKEY$", "JOYSTICK$",
        "UPPER$", "LOWER$", "STRING$", "HEX$", "BIN$", "PEEK$", "DEC$",
        "EXP$", "DSK$", "GET$", "TIME$", "DATE$", "DATED$", "MEM$", "MEMORY$", "USING$"
    }

    while i < n:
        ch = expr[i]
        if ch == '"':
            q = ch
            start_q = i
            i += 1
            while i < n and expr[i] != q:
                i += 1
            if i < n:
                i += 1
            literal = expr[start_q:i]
            decoded_literal = decode_zx_string(literal[1:-1])

            rem = expr[i:].lstrip()
            if rem.startswith('('):
                ws_len = len(expr[i:]) - len(rem)
                open_p = i + ws_len
                close_p = find_matching_paren(expr, open_p)
                if close_p != -1:
                    slice_spec = expr[open_p + 1 : close_p]
                    sliced = slice_string(decoded_literal, slice_spec)
                    i = close_p + 1
                    while True:
                        rem2 = expr[i:].lstrip()
                        if rem2.startswith('('):
                            open_p2 = i + (len(expr[i:]) - len(rem2))
                            close_p2 = find_matching_paren(expr, open_p2)
                            if close_p2 != -1:
                                slice_spec2 = expr[open_p2 + 1 : close_p2]
                                sliced = slice_string(sliced, slice_spec2)
                                i = close_p2 + 1
                                continue
                        break
                    out.append(repr(sliced))
                    continue
            out.append(repr(decoded_literal))
        else:
            match = re.match(r'^!?([A-Za-z][A-Za-z0-9_]*\$)', expr[i:])
            if match:
                var_name = match.group(0).upper()
                after_var = i + len(match.group(0))

                if var_name in builtins:
                    if var_name == "INKEY$":
                        rem_inkey = expr[after_var:].lstrip()
                        if rem_inkey.startswith('#'):
                            ws_len = len(expr[after_var:]) - len(rem_inkey)
                            hash_pos = after_var + ws_len
                            after_hash = hash_pos + 1
                            rem_after = expr[after_hash:].lstrip()
                            m_stream = re.match(r'^(\d+|\([^\)]+\)|[A-Za-z][A-Za-z0-9]*)', rem_after)
                            if m_stream:
                                s_expr = m_stream.group(1)
                                end_pos = after_hash + (len(expr[after_hash:]) - len(rem_after)) + len(s_expr)
                                clean_s = s_expr[1:-1] if s_expr.startswith('(') and s_expr.endswith(')') else s_expr
                                try:
                                    s_idx = int(evaluate_expr(clean_s))
                                except:
                                    s_idx = 0
                                ch_val = zx_inkey_stream(s_idx)
                                out.append(repr(ch_val))
                                i = end_pos
                                continue
                        else:
                            ink_val = get_next_inkey()
                            out.append(repr(ink_val))
                            i = after_var
                            continue
                    elif var_name == "JOYSTICK$":
                        out.append(repr(current_joystick_mode))
                        i = after_var
                        continue
                    out.append(expr[i:after_var])
                    i = after_var
                    continue

                rem = expr[after_var:].lstrip()
                if rem.startswith('('):
                    ws_len = len(expr[after_var:]) - len(rem)
                    open_p = after_var + ws_len
                    close_p = find_matching_paren(expr, open_p)
                    if close_p != -1:
                        slice_spec = expr[open_p + 1 : close_p]
                        sliced = get_string_value(var_name, slice_spec)
                        i = close_p + 1
                        while True:
                            rem2 = expr[i:].lstrip()
                            if rem2.startswith('('):
                                open_p2 = i + (len(expr[i:]) - len(rem2))
                                close_p2 = find_matching_paren(expr, open_p2)
                                if close_p2 != -1:
                                    slice_spec2 = expr[open_p2 + 1 : close_p2]
                                    sliced = slice_string(sliced, slice_spec2)
                                    i = close_p2 + 1
                                    continue
                            break
                        out.append(repr(sliced))
                        continue

                curr_str = string_variables.get(var_name, "")
                out.append(repr(curr_str))
                i = after_var
            else:
                out.append(ch)
                i += 1

    return "".join(out)


def zx_sgn(x):
    val = to_float(x)
    return -1.0 if val < 0 else (1.0 if val > 0 else 0.0)


def zx_str(x):
    return format_val(x)


def zx_code(s):
    s = str(s)
    return float(ord(s[0])) if len(s) > 0 else 0.0


def zx_chr(x):
    return chr(max(0, min(255, int(to_float(x)))))


def zx_peek(addr):
    global memory, gfx_bits, attr_ink, attr_paper, attr_bright, attr_flash
    a = int(to_float(addr)) & 0xFFFF
    if currah_enabled and a == 4096:
        return currah_in_status()
    if amx_enabled and 51915 <= a <= 51920:
        sync_amx_mouse_state()
        if a == 51915: return float(amx_x)
        if a == 51916: return float(amx_y)
        if a == 51917: return 1.0 if amx_btn_left else 0.0
        if a == 51918: return 1.0 if amx_btn_right else 0.0
        if a == 51919: return 1.0 if amx_btn_middle else 0.0
        if a == 51920:
            return float((1 if amx_btn_left else 0) | ((1 if amx_btn_right else 0) << 1) | ((1 if amx_btn_middle else 0) << 2))
    # Screen bitmap 16384..22527 (6144 bytes)
    if 16384 <= a < 22528:
        if globals().get('screen_bitmap_dirty', False):
            bx, by, _, _ = _VRAM_MAP[a - 16384]
            col0 = gfx_bits[bx]
            col1 = gfx_bits[bx+1]
            col2 = gfx_bits[bx+2]
            col3 = gfx_bits[bx+3]
            col4 = gfx_bits[bx+4]
            col5 = gfx_bits[bx+5]
            col6 = gfx_bits[bx+6]
            col7 = gfx_bits[bx+7]
            val = ((128 if col0[by] else 0) | (64 if col1[by] else 0) |
                   (32 if col2[by] else 0) | (16 if col3[by] else 0) |
                   (8 if col4[by] else 0) | (4 if col5[by] else 0) |
                   (2 if col6[by] else 0) | (1 if col7[by] else 0))
            memory[a] = val
            return float(val)
        return float(memory[a])
    # Attribute block 22528..23295 (768 bytes)
    elif 22528 <= a < 23296:
        if globals().get('screen_bitmap_dirty', False):
            offset = a - 22528
            r = offset >> 5
            c = offset & 31
            val = (128 if attr_flash[r][c] else 0) | (64 if attr_bright[r][c] else 0) | ((attr_paper[r][c] & 7) << 3) | (attr_ink[r][c] & 7)
            memory[a] = val
            return float(val)
        return float(memory[a])
    elif a in (23672, 23673, 23674):  # FRAMES
        tf = int(pygame.time.get_ticks() * 50 / 1000)
        return float((tf >> ((a - 23672) * 8)) & 0xFF)
    elif a == 23624:  # BORDCR
        return float((current_border & 7) | ((current_paper & 7) << 3))
    elif a == 23693:  # ATTR_P
        return float((current_ink & 7) | ((current_paper & 7) << 3) | (64 if current_bright else 0) | (128 if current_flash else 0))
    elif a == 23695:  # ATTR_T
        return float((current_ink & 7) | ((current_paper & 7) << 3))
    elif a == 23677:  # COORDS x
        return float(gfx_x & 0xFF)
    elif a == 23678:  # COORDS y
        return float(gfx_y & 0xFF)
    elif a == 23606:  # CHARS low
        return float((15616 - 256) & 0xFF)
    elif a == 23607:  # CHARS high
        return float(((15616 - 256) >> 8) & 0xFF)
    elif a == 23675:  # UDG low
        return float(65368 & 0xFF)
    elif a == 23676:  # UDG high
        return float((65368 >> 8) & 0xFF)
    elif a == 23688:  # S_POSN col
        return float(print_col & 0xFF)
    elif a == 23689:  # S_POSN line
        return float((24 - print_row) & 0xFF)
    if a == 23560:  # LAST_K
        if last_keypress:
            return float(ord(last_keypress[0]))
        j_k = get_joystick_inkey()
        return float(ord(j_k)) if j_k else 0.0
    return float(memory[a])


def zx_poke(addr, val):
    global memory, gfx_bits, attr_ink, attr_paper, attr_bright, attr_flash, attr_used, cell_bitmap
    global canvas_dirty, canvas_dirty_cells, screen_bitmap_dirty
    global current_border, current_ink, current_paper, current_bright, current_flash, last_keypress, gfx_x, gfx_y
    a = int(to_float(addr)) & 0xFFFF
    v = int(to_float(val)) & 0xFF
    if currah_enabled and a == 4096:
        currah_out_allophone(v & 0x3F)
    memory[a] = v
    if (0x4000 <= a < 0x5B00) or (0x6000 <= a < 0x7B00):
        handle_poke_vram(a, v)
    elif a == 23624:  # BORDCR
        current_border = v & 7
        update_display()
    elif a == 23693:  # ATTR_P
        current_ink = v & 7
        current_paper = (v >> 3) & 7
        current_bright = bool((v >> 6) & 1)
        current_flash = bool((v >> 7) & 1)
    elif a == 23695:  # ATTR_T
        current_ink = v & 7
        current_paper = (v >> 3) & 7
    elif a == 23677:  # COORDS x
        gfx_x = v
    elif a == 23678:  # COORDS y
        gfx_y = v
    elif a == 23560:  # LAST_K
        last_keypress = chr(v) if v > 0 else ""


def zx_attr(r, c):
    r = int(to_float(r))
    c = int(to_float(c))
    if 0 <= r < 24 and 0 <= c < 32:
        ink = attr_ink[r][c] & 7
        paper = attr_paper[r][c] & 7
        bright = 64 if attr_bright[r][c] else 0
        flash = 128 if attr_flash[r][c] else 0
        return float(flash + bright + (paper << 3) + ink)
    return 0.0


def zx_screen(r, c):
    r = int(to_float(r))
    c = int(to_float(c))
    if 0 <= r < 24 and 0 <= c < 32:
        ch = screen_chars[r][c]
        return ch if ch != '\x00' else " "
    return " "


def zx_point(x, y):
    return float(get_point(int(to_float(x)), int(to_float(y))))


def zx_bin(s):
    s = str(s).strip(' "\'')
    return float(int(s, 2))


def zx_usr(arg):
    if isinstance(arg, str):
        char_code = arg.strip().upper()
        if len(char_code) > 0:
            udg_base = memory[23675] + (memory[23676] * 256)
            ch = char_code[0]
            if 'A' <= ch <= 'U':
                offset = ord(ch) - ord('A')
                return float(udg_base + offset * 8)
            else:
                return float(udg_base + max(0, min(20, ord(ch))) * 8)
        return 0.0
    val = float(to_float(arg))
    if int(val) == 51912:
        global amx_enabled, amx_pointer_visible
        amx_enabled = True
        amx_pointer_visible = True
        try:
            pygame.mouse.set_visible(False)
        except Exception:
            pass
        if 51920 < len(memory):
            memory[51915] = amx_x & 0xFF
            memory[51916] = amx_y & 0xFF
        return val
    addr = int(val) & 0xFFFF
    try:
        eng = get_sprite_engine(memory_ref=memory)
        if eng.base <= addr < eng.base + 24:
            offset = addr - eng.base
            if offset == 0:
                eng.init_engine(memory_ref=memory)
                return 0.0
            elif offset == 3:
                eng.update_all()
                return 0.0
            elif offset == 6:
                eng.draw_all()
                return 0.0
            elif offset == 9:
                eng.step()
                return 0.0
            elif offset == 12:
                eng.set_attr_from_params()
                return 0.0
            elif offset == 15:
                eng.get_attr_to_params()
                return 0.0
            elif offset == 18:
                eng.def_sprite_from_params()
                return 0.0
            elif offset == 21:
                eng.clear_all()
                return 0.0
    except Exception:
        pass
    try:
        sync_screen_memory()
        cpu = get_z80_cpu()
        cpu.run_from(addr)
        sync_from_screen_memory()
        if getattr(cpu, 'suspended_by_break', False):
            global can_continue_mc, suspended_mc_cpu
            can_continue_mc = True
            suspended_mc_cpu = cpu
            raise BASICBreak(f"L BREAK into program at PC #{cpu.PC:04X}")
        return float(cpu.BC)
    except BASICBreak:
        raise
    except Exception:
        return val


def zx_val(s):
    res = evaluate_expr(str(s))
    return to_float(res)


def zx_val_str(s):
    res = evaluate_expr(str(s))
    return str(res)


def zx_using(fmt_str, val):
    fmt = str(fmt_str)
    if isinstance(val, (int, float)):
        num = float(val)
        if '#' in fmt or '.' in fmt:
            if '.' in fmt:
                dec_part = fmt.split('.', 1)[1]
                dec_places = len(re.findall(r'#', dec_part))
                formatted_num = f"{num:.{dec_places}f}"
            else:
                formatted_num = f"{int(round(num))}"
            out_chars = []
            num_idx = len(formatted_num) - 1
            for ch in reversed(fmt):
                if ch == '#':
                    if num_idx >= 0:
                        out_chars.append(formatted_num[num_idx])
                        num_idx -= 1
                    else:
                        out_chars.append(' ')
                elif ch == '.':
                    out_chars.append('.')
                    if num_idx >= 0 and formatted_num[num_idx] == '.':
                        num_idx -= 1
                else:
                    out_chars.append(ch)
            while num_idx >= 0:
                out_chars.append(formatted_num[num_idx])
                num_idx -= 1
            return "".join(reversed(out_chars))
        return format_val(val)
    else:
        val_str = str(val)
        width = len(fmt)
        return val_str[:width].ljust(width)


def eval_inarray_fn(arr_name, val, st=1):
    name = str(arr_name).strip().upper()
    arr_entry = arrays.get(name, ram_disk_arrays.get(name, ram_disk_arrays.get(f"!{name}", None)))
    if arr_entry is None and name.startswith("!"):
        arr_entry = arrays.get(name[1:], None)
    if arr_entry is None and not name.startswith("!"):
        arr_entry = ram_disk_arrays.get(f"!{name}", None)
    if arr_entry is None:
        return 0.0
    start_idx = max(1, int(to_float(st))) if st is not None else 1
    if isinstance(arr_entry, tuple):
        dims, data_dict = arr_entry
        if len(dims) == 1:
            for i in range(start_idx, dims[0] + 1):
                cur = data_dict.get((i,), None)
                if cur == val or (isinstance(val, (int, float)) and cur == to_float(val)) or (isinstance(val, str) and cur is not None and str(val) in str(cur)):
                    return float(i)
        elif len(dims) == 2:
            for r in range(start_idx, dims[0] + 1):
                row_str = "".join(str(data_dict.get((r, c), " ")) for c in range(1, dims[1] + 1))
                if str(val) in row_str:
                    return float(r)
    elif isinstance(arr_entry, list):
        for i in range(start_idx, len(arr_entry)):
            cur = arr_entry[i]
            if cur == val or (isinstance(val, (int, float)) and cur == to_float(val)) or (isinstance(val, str) and str(val) in str(cur)):
                return float(i)
            elif isinstance(cur, list):
                for c_val in cur[1:]:
                    if c_val == val or (isinstance(val, (int, float)) and c_val == to_float(val)):
                        return float(i)
    return 0.0


def zx_cast(tgt_type, val):
    t_str = str(tgt_type).strip(' "\'').upper()
    if t_str == "STRING":
        return str(val)
    v_num = to_float(val)
    if t_str == "UBYTE":
        return float(int(v_num) & 0xFF)
    elif t_str == "BYTE":
        b = int(v_num) & 0xFF
        return float(b - 256 if b >= 128 else b)
    elif t_str == "UINTEGER":
        return float(int(v_num) & 0xFFFF)
    elif t_str == "INTEGER":
        w = int(v_num) & 0xFFFF
        return float(w - 65536 if w >= 32768 else w)
    elif t_str == "ULONG":
        return float(int(v_num) & 0xFFFFFFFF)
    elif t_str == "LONG":
        dw = int(v_num) & 0xFFFFFFFF
        return float(dw - 4294967296 if dw >= 2147483648 else dw)
    elif t_str in ("FLOAT", "FIXED"):
        return float(v_num)
    return float(v_num)


def zx_sizeof(arg):
    s = str(arg).strip(' "\'').upper()
    type_sizes = {
        "UBYTE": 1.0, "BYTE": 1.0,
        "UINTEGER": 2.0, "INTEGER": 2.0,
        "ULONG": 4.0, "LONG": 4.0,
        "FLOAT": 5.0, "FIXED": 5.0,
        "STRING": 2.0
    }
    if s in type_sizes:
        return type_sizes[s]
    if s in arrays:
        return float(len(arrays[s]) * 5)
    if s in ram_disk_arrays:
        return float(len(ram_disk_arrays[s]) * 5)
    if s in string_variables:
        return float(len(string_variables[s]))
    return 2.0


def eval_collision_fn(*args):
    try:
        eng = get_sprite_engine(memory_ref=memory)
        if not args:
            return 0.0
        slot_id = int(to_float(args[0])) & 0x0F
        coll_val = 0
        if eng.memory is not None and eng.collision_table_addr + slot_id < len(eng.memory):
            coll_val = eng.memory[eng.collision_table_addr + slot_id]
        else:
            coll_val = eng._read_slot_byte(slot_id, 23)

        if len(args) > 1:
            arg2 = args[1]
            if isinstance(arg2, str):
                name_map = {
                    "SPRITE": 1, "UDG": 2, "BLOCK": 4, "INK": 8, "PAPER": 16, "TARGET": 32
                }
                mask = name_map.get(arg2.upper().strip(' "\''), 1)
            else:
                mask = int(to_float(arg2))
            return 1.0 if (coll_val & mask) else 0.0
        return float(coll_val)
    except Exception:
        return 0.0


def eval_sprite_prop_fn(*args):
    if globals().get('spectrum_mode', '48K') == 'NEXT':
        return eval_next_sprite_prop_fn(*args)
    try:
        eng = get_sprite_engine(memory_ref=memory)
        if not args:
            return 0.0
        slot_id = int(to_float(args[0])) & 0x0F
        if len(args) < 2:
            return float(eng._read_slot_byte(slot_id, 0))
        prop = args[1]
        if isinstance(prop, str):
            prop_map = {
                "STATUS": 0, "DEF": 1, "DEF_ID": 1, "X": 2, "Y": 3,
                "OLD_X": 4, "OLD_Y": 5, "INK": 7, "BRIGHT": 8,
                "FRAME_COUNT": 9, "FRAME": 10, "CUR_FRAME": 10,
                "ANIM_SPEED": 11, "DIR": 13, "PATH": 14, "PATH_MODE": 14,
                "SPEED": 15, "ORIGIN_X": 16, "ORIGIN_Y": 17,
                "COLLISION": 23, "OTHER": 24
            }
            offset = prop_map.get(prop.upper().strip(' "\''), 0)
        else:
            offset = int(to_float(prop))
        return float(eng._read_slot_byte(slot_id, offset))
    except Exception:
        return 0.0


def eval_tile_fn(*args):
    try:
        if not args:
            return 0.0
        t_id = int(to_float(args[0]))
        if get_tilemap_engine:
            eng = get_tilemap_engine()
            return float(eng.get_tile_address(t_id))
        return float(32768 + t_id * 256)
    except Exception:
        return 0.0


def zx_call_builtin(fname, arg_str):
    upper_fn = fname.upper()
    if upper_fn == "STICK":
        parts = split_top_level_commas(arg_str)
        p = int(to_float(evaluate_expr(parts[0]))) if parts and parts[0].strip() else 1
        t = int(to_float(evaluate_expr(parts[1]))) if len(parts) > 1 and parts[1].strip() else 1
        return evaluate_timex_stick(p, t)
    if upper_fn == "FREE":
        return float(get_free_memory())
    if upper_fn == "MODE":
        return float(timex_screen_mode)
    if upper_fn == "TILE":
        parts = split_top_level_commas(arg_str)
        args_eval = [evaluate_expr(p) for p in parts if p.strip()]
        return eval_tile_fn(*args_eval)
    if upper_fn == "COLLISION":
        parts = split_top_level_commas(arg_str)
        args_eval = [evaluate_expr(p) for p in parts if p.strip()]
        return eval_collision_fn(*args_eval)
    if upper_fn == "SPRITE":
        parts = split_top_level_commas(arg_str)
        args_eval = [evaluate_expr(p) for p in parts if p.strip()]
        return eval_sprite_prop_fn(*args_eval)
    if upper_fn == "SIN": return math.sin(to_float(evaluate_expr(arg_str)))
    if upper_fn == "COS": return math.cos(to_float(evaluate_expr(arg_str)))
    if upper_fn == "TAN": return math.tan(to_float(evaluate_expr(arg_str)))
    if upper_fn == "ASN": return math.asin(to_float(evaluate_expr(arg_str)))
    if upper_fn == "ACS": return math.acos(to_float(evaluate_expr(arg_str)))
    if upper_fn == "ATN": return math.atan(to_float(evaluate_expr(arg_str)))
    if upper_fn == "EXP": return math.exp(to_float(evaluate_expr(arg_str)))
    if upper_fn == "LN": return math.log(to_float(evaluate_expr(arg_str)))
    if upper_fn == "ABS": return abs(to_float(evaluate_expr(arg_str)))
    if upper_fn == "INT": return math.floor(to_float(evaluate_expr(arg_str)))
    if upper_fn == "SQR": return math.sqrt(to_float(evaluate_expr(arg_str)))
    if upper_fn == "LEN": return float(len(str(evaluate_expr(arg_str))))
    if upper_fn == "SGN": return zx_sgn(evaluate_expr(arg_str))
    if upper_fn == "CODE": return zx_code(evaluate_expr(arg_str))
    if upper_fn == "CHR$": return zx_chr(evaluate_expr(arg_str))
    if upper_fn == "STR$": return zx_str(evaluate_expr(arg_str))
    if upper_fn == "PEEK": return zx_peek(evaluate_expr(arg_str))
    if upper_fn == "VAL": return zx_val(evaluate_expr(arg_str))
    if upper_fn == "VAL$": return zx_val_str(evaluate_expr(arg_str))
    if upper_fn == "USR": return zx_usr(evaluate_expr(arg_str))
    if upper_fn == "BIN": return zx_bin(arg_str)
    if upper_fn == "IN": return float(read_in_port(int(to_float(evaluate_expr(arg_str)))))
    if upper_fn == "MOUSEX":
        sync_amx_mouse_state()
        return float(amx_x)
    if upper_fn == "MOUSEY":
        sync_amx_mouse_state()
        return float(amx_y)
    if upper_fn == "MOUSEB":
        sync_amx_mouse_state()
        return float((1 if amx_btn_left else 0) | ((1 if amx_btn_right else 0) << 1) | ((1 if amx_btn_middle else 0) << 2))
    if upper_fn in ("DRUM", "SPECDRUM"):
        parts = split_top_level_commas(arg_str)
        drum_tgt = evaluate_expr(parts[0]) if parts and parts[0].strip() else 1
        vol = float(evaluate_expr(parts[1])) if len(parts) > 1 and parts[1].strip() else 1.0
        specdrum_subsystem.play_drum(drum_tgt, vol)
        return 1.0
    if upper_fn == "ATTR":
        parts = split_top_level_commas(arg_str)
        if len(parts) == 2:
            return zx_attr(evaluate_expr(parts[0]), evaluate_expr(parts[1]))
        return 0.0
    if upper_fn == "SCREEN$":
        parts = split_top_level_commas(arg_str)
        if len(parts) == 2:
            return zx_screen(evaluate_expr(parts[0]), evaluate_expr(parts[1]))
        return " "
    if upper_fn == "POINT":
        parts = split_top_level_commas(arg_str)
        if len(parts) == 2:
            return zx_point(evaluate_expr(parts[0]), evaluate_expr(parts[1]))
        return 0.0
    if upper_fn in ("SOUND", "AY"):
        reg = int(to_float(evaluate_expr(arg_str))) if arg_str.strip() else fuller_ay_chip.selected_reg
        if 0 <= reg <= 15:
            fuller_ay_chip.write_address(reg)
            return float(fuller_ay_chip.read_data())
        return 0.0
    if upper_fn in ("BANK", "PAGE"):
        return float(current_ram_bank)
    if upper_fn == "SPECTRUM":
        if spectrum_mode == "NEXT": return 28.0
        elif spectrum_mode == "TS2068": return 2068.0
        elif plus3_mode: return 3.0
        return 128.0 if spectrum_128k_mode else 48.0
    if upper_fn in ("TIMEX", "TS2068", "TC2068"):
        return 2068.0 if spectrum_mode == "TS2068" else 0.0
    if upper_fn in ("NEXT", "ZXNEXT", "SPECTRUMNEXT", "NEXTBASIC"):
        return 28.0 if spectrum_mode == "NEXT" else 0.0
    if upper_fn in ("REG", "NEXTREG"):
        reg = int(to_float(evaluate_expr(arg_str))) if arg_str.strip() else 0
        return float(get_nextreg(reg))
    if upper_fn == "PEEK$":
        parts = split_top_level_commas(arg_str)
        addr = int(to_float(evaluate_expr(parts[0]))) & 0xFFFF
        l_cnt = int(to_float(evaluate_expr(parts[1]))) if len(parts) > 1 else 1
        if globals().get('screen_bitmap_dirty', False) and (16384 <= addr < 23296 or 16384 <= addr + l_cnt <= 23296 or (addr < 16384 and addr + l_cnt > 16384)):
            sync_screen_memory()
        return "".join(chr(memory[(addr + k) & 0xFFFF]) for k in range(max(0, l_cnt)))
    if upper_fn == "DEC$":
        parts = split_top_level_commas(arg_str)
        v = int(to_float(evaluate_expr(parts[0])))
        s_val = str(v)
        if len(parts) > 1:
            w = int(to_float(evaluate_expr(parts[1])))
            s_val = s_val.zfill(w)
        return s_val
    if upper_fn == "EXP$":
        val = evaluate_expr(arg_str)
        if isinstance(val, str):
            try:
                return str(evaluate_expr(val))
            except Exception:
                return val
        return str(val)
    if upper_fn == "GET$":
        parts = split_top_level_commas(arg_str)
        if not parts or not parts[0].strip():
            return get_next_inkey()
        l_cnt = int(to_float(evaluate_expr(parts[1]))) if len(parts) > 1 else int(to_float(evaluate_expr(parts[0])))
        return " " * max(0, min(l_cnt, 255))
    if upper_fn == "DRIVER":
        return 0.0
    if upper_fn == "DSK$":
        return f"{next_active_drive} 1.8M Free"
    if upper_fn in ("LAYER2", "LAYER 2"):
        return 1.0 if layer2_active else 0.0
    if upper_fn == "LORES":
        return float(next_lores_mode)
    if upper_fn == "PALETTE":
        parts = split_top_level_commas(arg_str)
        args_eval = []
        for i, p in enumerate(parts):
            p_str = p.strip()
            if not p_str:
                continue
            p_upper = p_str.upper().replace(" ", "")
            if i == 0 and p_upper in ("ULA", "LAYER2", "LAYER", "L2", "SPRITE", "SPRITES", "TILE", "TILEMAP"):
                args_eval.append(p_upper)
            else:
                args_eval.append(evaluate_expr(p_str))
        return eval_next_palette_fn(*args_eval)
    if upper_fn == "TILEMAP":
        parts = split_top_level_commas(arg_str)
        args_eval = [evaluate_expr(p) for p in parts if p.strip()]
        return eval_next_tilemap_fn(*args_eval)
    if upper_fn == "LAYER":
        parts = split_top_level_commas(arg_str)
        l_num = int(to_float(evaluate_expr(parts[0]))) if parts and parts[0].strip() else 2
        return 1.0 if (l_num == 2 and layer2_active) else 0.0
    if upper_fn == "TURBO":
        return float(next_turbo_speed)
    if upper_fn == "PLAY":
        return 1.0 if ay_play_active else 0.0
    if upper_fn == "SONIC":
        return sonic_fn(arg_str)
    if upper_fn == "SVOICE":
        return svoice_fn(arg_str)
    if upper_fn == "SPOS":
        return spos_fn(arg_str)
    if upper_fn == "FPEEK":
        return fpeek_fn(arg_str)
    if upper_fn == "FSTAT":
        return fstat_fn(arg_str)
    # Beta BASIC v3 functions
    if upper_fn == "UPPER$":
        return str(evaluate_expr(arg_str)).upper()
    if upper_fn == "LOWER$":
        return str(evaluate_expr(arg_str)).lower()
    if upper_fn == "DPEEK":
        addr = int(to_float(evaluate_expr(arg_str))) & 0xFFFF
        if globals().get('screen_bitmap_dirty', False) and (16384 <= addr < 23296 or addr == 16383):
            sync_screen_memory()
        return float(memory[addr] | (memory[(addr + 1) & 0xFFFF] << 8))
    if upper_fn == "HEX$":
        parts = split_top_level_commas(arg_str)
        n = int(to_float(evaluate_expr(parts[0])))
        h = hex(n & 0xFFFFFFFF)[2:].upper() if n < 0 else hex(n)[2:].upper()
        if len(parts) > 1:
            w = int(to_float(evaluate_expr(parts[1])))
            h = h.zfill(w)
        return h
    if upper_fn == "BIN$":
        parts = split_top_level_commas(arg_str)
        n = int(to_float(evaluate_expr(parts[0])))
        b = bin(n & 0xFFFFFFFF)[2:] if n < 0 else bin(n)[2:]
        if len(parts) > 1:
            w = int(to_float(evaluate_expr(parts[1])))
            b = b.zfill(w)
        return b
    if upper_fn == "DEC":
        s = str(evaluate_expr(arg_str)).strip(' "\'')
        if s.startswith("$") or s.startswith("&H") or s.startswith("&h"):
            s = s[1:] if s.startswith("$") else s[2:]
        return float(int(s, 16))
    if upper_fn == "STRING$":
        parts = split_top_level_commas(arg_str)
        if len(parts) >= 2:
            cnt = max(0, int(to_float(evaluate_expr(parts[0]))))
            item = evaluate_expr(parts[1])
            ch = chr(int(to_float(item))) if isinstance(item, (int, float)) else str(item)
            return ch * cnt
        return ""
    if upper_fn in ("INSTR", "INSTRING"):
        parts = split_top_level_commas(arg_str)
        if len(parts) == 2:
            s = str(evaluate_expr(parts[0]))
            sub = str(evaluate_expr(parts[1]))
            idx = s.find(sub)
            return float(idx + 1 if idx != -1 else 0)
        elif len(parts) >= 3:
            st = max(1, int(to_float(evaluate_expr(parts[0]))))
            s = str(evaluate_expr(parts[1]))
            sub = str(evaluate_expr(parts[2]))
            idx = s.find(sub, st - 1)
            return float(idx + 1 if idx != -1 else 0)
        return 0.0
    if upper_fn == "TIME$":
        return time.strftime("%H:%M:%S")
    if upper_fn == "TIME":
        return float(int(time.time()) % 86400)
    if upper_fn in ("DATED$", "DATE$"):
        return time.strftime("%d/%m/%y")
    if upper_fn == "RNDM":
        n = int(to_float(evaluate_expr(arg_str)))
        return float(random.randint(0, max(0, n - 1)) if n > 0 else 0)
    if upper_fn == "MIN":
        parts = split_top_level_commas(arg_str)
        return float(min(to_float(evaluate_expr(p)) for p in parts))
    if upper_fn == "MAX":
        parts = split_top_level_commas(arg_str)
        return float(max(to_float(evaluate_expr(p)) for p in parts))
    if upper_fn == "ITEM":
        parts = split_top_level_commas(arg_str)
        if len(parts) >= 2:
            idx = int(to_float(evaluate_expr(parts[0])))
            s = str(evaluate_expr(parts[1]))
            delim = str(evaluate_expr(parts[2])) if len(parts) > 2 else ","
            tokens = s.split(delim)
            if 1 <= idx <= len(tokens):
                return tokens[idx - 1]
        return ""
    if upper_fn == "INARRAY":
        parts = split_top_level_commas(arg_str)
        if len(parts) >= 2:
            arr_n = parts[0].strip()
            val = evaluate_expr(parts[1])
            st = evaluate_expr(parts[2]) if len(parts) >= 3 else 1
            return eval_inarray_fn(arr_n, val, st)
        return 0.0
    if upper_fn == "BAND":
        parts = split_top_level_commas(arg_str)
        if len(parts) >= 2:
            return float(int(to_float(evaluate_expr(parts[0]))) & int(to_float(evaluate_expr(parts[1]))))
        return 0.0
    if upper_fn == "BOR":
        parts = split_top_level_commas(arg_str)
        if len(parts) >= 2:
            return float(int(to_float(evaluate_expr(parts[0]))) | int(to_float(evaluate_expr(parts[1]))))
        return 0.0
    if upper_fn == "BXOR":
        parts = split_top_level_commas(arg_str)
        if len(parts) >= 2:
            return float(int(to_float(evaluate_expr(parts[0]))) ^ int(to_float(evaluate_expr(parts[1]))))
        return 0.0
    if upper_fn == "BNOT":
        return float(~int(to_float(evaluate_expr(arg_str))) & 0xFFFF)
    if upper_fn == "LENGTH":
        arg = arg_str.strip().upper()
        if arg in string_variables:
            return float(len(string_variables[arg]))
        if arg in arrays:
            return float(len(arrays[arg]) - 1)
        v = evaluate_expr(arg_str)
        return float(len(str(v)))
    if upper_fn in ("MEM$", "MEMORY$"):
        parts = split_top_level_commas(arg_str)
        if len(parts) >= 2:
            addr = int(to_float(evaluate_expr(parts[0]))) & 0xFFFF
            length = max(0, int(to_float(evaluate_expr(parts[1]))))
            if globals().get('screen_bitmap_dirty', False) and (16384 <= addr < 23296 or 16384 <= addr + length <= 23296 or (addr < 16384 and addr + length > 16384)):
                sync_screen_memory()
            return "".join(chr(memory[(addr + i) & 0xFFFF]) for i in range(length))
        return ""
    if upper_fn == "USING$":
        parts = split_top_level_commas(arg_str)
        if len(parts) >= 2:
            fmt = str(evaluate_expr(parts[0]))
            val = evaluate_expr(parts[1])
            return zx_using(fmt, val)
        return ""
    if upper_fn == "MOD":
        parts = split_top_level_commas(arg_str)
        if len(parts) >= 2:
            a = int(to_float(evaluate_expr(parts[0])))
            b = int(to_float(evaluate_expr(parts[1])))
            return float(a % b if b != 0 else 0)
        return 0.0
    if upper_fn == "XOR":
        parts = split_top_level_commas(arg_str)
        if len(parts) >= 2:
            a = int(to_float(evaluate_expr(parts[0])))
            b = int(to_float(evaluate_expr(parts[1])))
            return float(a ^ b)
        return 0.0
    # Boriel ZX Basic built-in functions
    if upper_fn == "CAST":
        parts = split_top_level_commas(arg_str)
        if len(parts) >= 2:
            return zx_cast(parts[0], evaluate_expr(parts[1]))
        return 0.0
    if upper_fn == "SIZEOF":
        return zx_sizeof(arg_str)
    if upper_fn == "LBOUND":
        return 0.0
    if upper_fn == "UBOUND":
        parts = split_top_level_commas(arg_str)
        arr_n = parts[0].strip().upper()
        if arr_n in arrays:
            return float(len(arrays[arr_n]) - 1)
        elif arr_n in ram_disk_arrays or f"!{arr_n}" in ram_disk_arrays:
            t = ram_disk_arrays.get(arr_n, ram_disk_arrays.get(f"!{arr_n}"))
            return float(len(t) - 1)
        return 0.0
    if upper_fn == "SHL":
        parts = split_top_level_commas(arg_str)
        if len(parts) >= 2:
            a = int(to_float(evaluate_expr(parts[0])))
            b = int(to_float(evaluate_expr(parts[1])))
            return float((a << b) & 0xFFFF)
        return 0.0
    if upper_fn == "SHR":
        parts = split_top_level_commas(arg_str)
        if len(parts) >= 2:
            a = int(to_float(evaluate_expr(parts[0])))
            b = int(to_float(evaluate_expr(parts[1])))
            return float((a >> b) & 0xFFFF)
        return 0.0
    if upper_fn == "CHR":
        return zx_chr(evaluate_expr(arg_str))
    if upper_fn == "STR":
        return zx_str(evaluate_expr(arg_str))
    if upper_fn == "INKEY":
        return get_next_inkey()
    return 0.0


def call_user_function(fn_name, *args):
    fn_name = fn_name.upper()
    if fn_name not in user_functions:
        raise Exception(f"Undefined function FN {fn_name}")
    fn = user_functions[fn_name]
    fn_args = fn.get("args", [])
    saved_vals = {}
    for param, val in zip(fn_args, args):
        if param.endswith("$"):
            saved_vals[param] = string_variables.get(param, None)
            string_variables[param] = str(val)
        else:
            saved_vals[param] = variables.get(param, None)
            variables[param] = to_float(val)
    try:
        return evaluate_expr(fn["body"])
    finally:
        for param in fn_args:
            if param in saved_vals:
                if saved_vals[param] is not None:
                    if param.endswith("$"): string_variables[param] = saved_vals[param]
                    else: variables[param] = saved_vals[param]
                else:
                    if param.endswith("$"): string_variables.pop(param, None)
                    else: variables.pop(param, None)


def zx_in(port):
    return float(read_in_port(int(to_float(port))))



