                eval_str = re.sub(r'\bATTR\s*\(', 'attr(', eval_str, flags=re.IGNORECASE)
                eval_str = re.sub(r'\bSCREEN\$\s*\(', 'screen_str(', eval_str, flags=re.IGNORECASE)
