                eval_str = re.sub(r'\bLEN\s*\(', 'len_fn(', eval_str, flags=re.IGNORECASE)
                eval_str = re.sub(r'\bSIN\s*\(', 'sin_fn(', eval_str, flags=re.IGNORECASE)
