                eval_str = re.sub(r'\bDPEEK\s*\(', 'dpeek_fn(', eval_str, flags=re.IGNORECASE)
                eval_str = re.sub(r'\bHEX\$\s*\(', 'hex_fn(', eval_str, flags=re.IGNORECASE)
