                eval_str = re.sub(r'\bSTRING\$\s*\(', 'string_fn(', eval_str, flags=re.IGNORECASE)
                eval_str = re.sub(r'\b(?:INSTR|INSTRING)\s*\(', 'instr_fn(', eval_str, flags=re.IGNORECASE)
                eval_str = re.sub(r'\bRNDM\s*\(', 'rndm_fn(', eval_str, flags=re.IGNORECASE)
                eval_str = re.sub(r'\bMIN\s*\(', 'min_fn(', eval_str, flags=re.IGNORECASE)
