        while curr_s < len(sub_stmts):
            sub = sub_stmts[curr_s].strip().upper()
            if sub.startswith("CASE ") or sub == "CASE":
                depth += 1
            elif sub.startswith("ENDCASE") or sub == "ENDCASE":
                depth -= 1
                if depth == 0:
                    return curr_l, curr_s
            curr_s += 1
