def find_next_case_branch(start_l_idx, start_s_idx, line_numbers):
    depth = 0
    curr_l = start_l_idx
    curr_s = start_s_idx
    while curr_l < len(line_numbers):
        ln = line_numbers[curr_l]
        sub_stmts = split_statements(program.get(ln, ""))
        while curr_s < len(sub_stmts):
            sub = sub_stmts[curr_s].strip().upper()
            if sub.startswith("CASE ") or sub == "CASE":
                depth += 1
            elif sub.startswith("ENDCASE") or sub == "ENDCASE":
                if depth == 0:
                    return curr_l, curr_s
                depth -= 1
            elif depth == 0 and (sub.startswith("WHEN ") or sub == "WHEN" or sub.startswith("OTHERWISE") or sub == "OTHERWISE"):
                return curr_l, curr_s
            curr_s += 1
        curr_s = 0
        curr_l += 1
    return len(line_numbers), 0


def handle_swap_statement(stmt_str):
    global variables, string_variables
    parts = split_top_level_commas(stmt_str[4:].strip())
    if len(parts) == 2:
        v1 = parts[0].strip().upper()
        v2 = parts[1].strip().upper()
        if v1.endswith("$") and v2.endswith("$"):
            val1 = string_variables.get(v1, "")
            val2 = string_variables.get(v2, "")
            string_variables[v1], string_variables[v2] = val2, val1
        elif not v1.endswith("$") and not v2.endswith("$"):
            val1 = variables.get(v1, 0.0)
            val2 = variables.get(v2, 0.0)
            variables[v1], variables[v2] = val2, val1
        else:
            raise Exception("Type mismatch in SWAP")


def handle_locate_statement(stmt_str):
    global print_row, print_col
    parts = split_top_level_commas(stmt_str[6:].strip())
    if len(parts) == 2:
        r = int(to_float(evaluate_expr(parts[0])))
        c = int(to_float(evaluate_expr(parts[1])))
        wx = active_window.get("x", 0)
        wy = active_window.get("y", 0)
        ww = active_window.get("w", 32)
        wh = active_window.get("h", 24)
        if 0 <= r < wh and 0 <= c < ww:
            print_row = wy + r
            print_col = wx + c
        else:
            print_row = max(0, min(23, r))
            print_col = max(0, min(31, c))


def scan_proc_definitions():
    global proc_definitions
    proc_definitions.clear()
    line_numbers = sorted(program.keys())
    for l_idx, ln in enumerate(line_numbers):
        stmt_line = program.get(ln, "")
        sub_stmts = split_statements(stmt_line)
        for s_idx, sub in enumerate(sub_stmts):
            sub_s = sub.strip()
            sub_u = sub_s.upper()
            is_def_proc = sub_u.startswith("DEF PROC")
            is_sub = sub_u.startswith("SUB ") or sub_u == "SUB"
            is_func = sub_u.startswith("FUNCTION ") or sub_u == "FUNCTION"
            if is_def_proc or is_sub or is_func:
                if is_def_proc:
                    raw_tail = sub_s[8:].strip()
                    is_function = False
                elif is_sub:
                    raw_tail = sub_s[3:].strip()
                    is_function = False
                else:
                    raw_tail = sub_s[8:].strip()
                    is_function = True

                # Strip FASTCALL or STDCALL
                raw_tail = re.sub(r'^(?:FASTCALL|STDCALL)\s+', '', raw_tail, flags=re.IGNORECASE).strip()
                
                # For FUNCTION, strip trailing " AS <type>"
                ret_type = None
                m_ret = re.search(r'\s+AS\s+([A-Za-z0-9_]+)$', raw_tail, flags=re.IGNORECASE)
                if m_ret:
                    ret_type = m_ret.group(1).upper()
                    raw_tail = raw_tail[:m_ret.start()].strip()

                m = re.match(r"^([A-Za-z][A-Za-z0-9_]*\$?)(?:\s*\((.*?)\)|\s+(.*))?$", raw_tail)
                if m:
                    p_name = m.group(1).upper()
                    raw_params = m.group(2) or m.group(3) or ""
                    raw_param_list = [p.strip() for p in split_top_level_commas(raw_params) if p.strip()]
                    clean_params = []
                    for p in raw_param_list:
                        p_up = p.upper()
                        is_ref = False
                        if p_up.startswith("BYREF "):
                            is_ref = True
                            p = p[6:].strip()
                        elif p_up.startswith("REF "):
                            is_ref = True
                            p = p[4:].strip()
                        elif p_up.startswith("BYVAL "):
                            p = p[6:].strip()
                        # Strip "AS <type>"
                        p = re.sub(r'\s+AS\s+[A-Za-z0-9_]+', '', p, flags=re.IGNORECASE).strip()
                        clean_name = p.upper()
                        if is_ref:
                            clean_params.append(f"REF {clean_name}")
                        else:
                            clean_params.append(clean_name)
                    proc_definitions[p_name] = {
                        "line_idx": l_idx,
                        "sub_idx": s_idx,
                        "params": clean_params,
                        "is_function": is_function,
                        "return_type": ret_type
                    }


def execute_proc_until_return(func_name, actual_args):
    global proc_stack, variables, string_variables
    proc_name = func_name.upper()
    if proc_name not in proc_definitions:
        scan_proc_definitions()
    if proc_name not in proc_definitions:
        raise Exception(f"Undefined FUNCTION {proc_name}")
    proc_def = proc_definitions[proc_name]
    formal_params = proc_def["params"]
    saved_locals = {}
    ref_map = {}

    for idx, formal in enumerate(formal_params):
        is_ref = formal.startswith("REF ")
        clean_name = formal[4:].strip().upper() if is_ref else formal.strip().upper()
        if idx < len(actual_args):
            arg_expr = actual_args[idx]
            if is_ref:
                ref_map[clean_name] = arg_expr.upper() if isinstance(arg_expr, str) else str(arg_expr)
            if clean_name.endswith("$"):
                saved_locals[clean_name] = string_variables.get(clean_name, None)
                string_variables[clean_name] = str(evaluate_expr(str(arg_expr)))
            else:
                saved_locals[clean_name] = variables.get(clean_name, None)
                variables[clean_name] = to_float(evaluate_expr(str(arg_expr)))
        else:
            if clean_name.endswith("$"):
                saved_locals[clean_name] = string_variables.get(clean_name, None)
                string_variables[clean_name] = ""
            else:
                saved_locals[clean_name] = variables.get(clean_name, None)
                variables[clean_name] = 0.0

    return_box = ["" if proc_def.get("return_type") == "STRING" else 0.0]

    frame = {
        "name": proc_name,
        "is_function": True,
        "ret_line_idx": -1,
        "ret_sub_idx": -1,
        "saved_locals": saved_locals,
        "ref_map": ref_map,
        "params": [f.replace("REF ", "").strip().upper() for f in formal_params],
        "return_box": return_box
    }
    proc_stack.append(frame)

    line_numbers = sorted(program.keys())
    curr_l = proc_def["line_idx"]
    curr_s = proc_def["sub_idx"] + 1

    try:
        while curr_l < len(line_numbers):
            stmt_line = program.get(line_numbers[curr_l], "")
            sub_stmts = split_statements(stmt_line)
            if curr_s >= len(sub_stmts):
                curr_l += 1
                curr_s = 0
                continue

            sub_stmt = sub_stmts[curr_s]
            sub_u = sub_stmt.strip().upper()
            next_l = curr_l
            next_s = curr_s + 1
            if next_s >= len(sub_stmts):
                next_l = curr_l + 1
                next_s = 0

            # RETURN [expr]
            if sub_u == "RETURN" or sub_u.startswith("RETURN "):
                if sub_u.startswith("RETURN "):
                    ret_expr = sub_stmt[7:].strip()
                    val = evaluate_expr(ret_expr)
                    return_box[0] = val
                break

            # END FUNCTION / EXIT FUNCTION / END SUB / END PROC
            if sub_u in ("END FUNCTION", "EXIT FUNCTION", "ENDFUNCTION", "END PROC", "END SUB", "EXIT SUB", "ENDSUB") or sub_u.startswith(("END FUNCTION ", "EXIT FUNCTION ", "END SUB ", "EXIT SUB ")):
                break

            # Assignment to function name: e.g. Add = a + b
            m_fn_assign = re.match(r"^" + re.escape(proc_name) + r"\s*=\s*(.+)$", sub_stmt.strip(), re.IGNORECASE)
            if m_fn_assign:
                val = evaluate_expr(m_fn_assign.group(1))
                return_box[0] = val
                curr_l = next_l
                curr_s = next_s
                continue

            # Nested definitions: skip
            if sub_u.startswith("DEF PROC") or sub_u.startswith("SUB ") or sub_u.startswith("FUNCTION "):
                skip_l, skip_s = find_matching_end_proc(curr_l, curr_s + 1, line_numbers)
                stmt_l = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                s_stmts = split_statements(stmt_l)
                if skip_s + 1 < len(s_stmts):
                    curr_l = skip_l
                    curr_s = skip_s + 1
                else:
                    curr_l = skip_l + 1
                    curr_s = 0
                continue

            # IF THEN RETURN
            if sub_u.startswith("IF "):
                m_if = re.match(r"^IF\s+(.+?)\s+THEN\s+(.+)$", sub_stmt, re.IGNORECASE)
                if m_if:
                    cond = evaluate_expr(m_if.group(1))
                    t_part, e_part = split_then_else(m_if.group(2))
                    tgt = t_part if cond else e_part
                    if tgt:
                        tgt_u = tgt.strip().upper()
                        if tgt_u == "RETURN" or tgt_u.startswith("RETURN "):
                            if tgt_u.startswith("RETURN "):
                                return_box[0] = evaluate_expr(tgt.strip()[7:])
                            break
                        elif tgt_u in ("EXIT FUNCTION", "END FUNCTION", "EXIT SUB", "END SUB"):
                            break
                        else:
                            execute_statement(tgt.strip(), line_numbers)
                    curr_l = next_l
                    curr_s = next_s
                    continue

            execute_statement(sub_stmt, line_numbers)
            curr_l = next_l
            curr_s = next_s

    finally:
        if proc_stack and proc_stack[-1] is frame:
            proc_stack.pop()
        for formal, caller_var in ref_map.items():
            if formal.endswith("$") and caller_var.endswith("$"):
                string_variables[caller_var] = string_variables.get(formal, "")
            elif not formal.endswith("$") and not caller_var.endswith("$"):
                variables[caller_var] = variables.get(formal, 0.0)
        for var_name, old_val in saved_locals.items():
            if var_name.endswith("$"):
                if old_val is not None: string_variables[var_name] = old_val
                else: string_variables.pop(var_name, None)
            else:
                if old_val is not None: variables[var_name] = old_val
                else: variables.pop(var_name, None)

    return return_box[0]


def execute_proc_call(call_str, curr_l, curr_s, next_l, next_s, line_numbers):
    global proc_stack, variables, string_variables
    cleaned = call_str.strip()
    if cleaned.upper().startswith("PROC"):
        cleaned = cleaned[4:].strip()
    elif cleaned.upper().startswith("CALL"):
        cleaned = cleaned[4:].strip()
    m = re.match(r"^([A-Za-z][A-Za-z0-9_]*)(?:\s*\((.*?)\)|\s+(.*))?$", cleaned)
    if not m:
        raise Exception(f"Invalid PROC call: {call_str}")
    proc_name = m.group(1).upper()
    if proc_name not in proc_definitions:
        scan_proc_definitions()
    if proc_name not in proc_definitions:
        raise Exception(f"Undefined PROC {proc_name}")
    raw_args = m.group(2) or m.group(3) or ""
    actual_args = [a.strip() for a in split_top_level_commas(raw_args) if a.strip()]

    proc_def = proc_definitions[proc_name]
    formal_params = proc_def["params"]
    saved_locals = {}
    ref_map = {}

    for idx, formal in enumerate(formal_params):
        is_ref = formal.startswith("REF ")
        clean_name = formal[4:].strip().upper() if is_ref else formal.strip().upper()
        if idx < len(actual_args):
            arg_expr = actual_args[idx]
            if is_ref:
                ref_map[clean_name] = arg_expr.upper()
            if clean_name.endswith("$"):
                saved_locals[clean_name] = string_variables.get(clean_name, None)
                string_variables[clean_name] = str(evaluate_expr(arg_expr))
            else:
                saved_locals[clean_name] = variables.get(clean_name, None)
                variables[clean_name] = to_float(evaluate_expr(arg_expr))
        else:
            if clean_name.endswith("$"):
                saved_locals[clean_name] = string_variables.get(clean_name, None)
                string_variables[clean_name] = ""
            else:
                saved_locals[clean_name] = variables.get(clean_name, None)
                variables[clean_name] = 0.0

    proc_stack.append({
        "name": proc_name,
        "is_function": proc_def.get("is_function", False),
        "ret_line_idx": next_l,
        "ret_sub_idx": next_s,
        "saved_locals": saved_locals,
        "ref_map": ref_map,
        "params": [f.replace("REF ", "").strip().upper() for f in formal_params],
        "return_box": [0.0]
    })

    target_l = proc_def["line_idx"]
    target_s = proc_def["sub_idx"] + 1
    stmt_line = program.get(line_numbers[target_l], "")
    sub_stmts = split_statements(stmt_line)
    if target_s >= len(sub_stmts):
        target_l += 1
        target_s = 0
    return target_l, target_s


class ForthWord:
    def __init__(self, name, is_primitive=True, func=None, is_immediate=False, compiled_body=None):
        self.name = name.upper()
        self.is_primitive = is_primitive
        self.func = func
        self.is_immediate = is_immediate
        self.compiled_body = compiled_body or []

    def __call__(self, engine):
        if self.func:
            return self.func(engine)



class ForthEngine:
    """Complete Abersoft fig-FORTH 1.1 interpreter for the Sinclair ZX Spectrum 48K.
    Provides complete isolation from Sinclair BASIC, intercepts screen memory
    and system variables, and supports mass storage across local files, .mdr, and .fdi.
    """
    BUFFER_BASE = 49152  # 12KB RAM space for 12 block buffers of 1024 bytes (49152..61439)

    def __init__(self):
        self.ds = []  # Data stack (16-bit signed: -32768..32767)
        self.rs = []  # Return stack
        self.state = 0  # 0 = interpreting, 1 = compiling
        self.base = 10  # Radix
        self.dp = 32768  # Dictionary pointer / HERE
        self.scr = 1  # Screen variable
        self.current_media = "local"  # "local", "mdr", "fdi"
        self.current_drive = 0
        self.screen_file_path = os.path.join(os.getcwd(), "screens.fth")
        self.block_buffers = {}  # blk_num -> {"data": bytearray(1024), "dirty": bool, "addr": int}
        self.last_accessed_blk = 1
        self.output_buffer = []
        self.compiling_word = None
        self.compiling_body = []
        self.control_stack = []
        self.dictionary = {}
        self.words = self.dictionary
        self.init_dictionary()

    @property
    def stack(self):
        return self.ds

    def push(self, val):
        if isinstance(val, float):
            self.ds.append(val)
            return
        val = int(val)
        val = ((val + 32768) % 65536) - 32768
        self.ds.append(val)

    def pop(self):
        if not self.ds:
            raise Exception("Forth: Stack underflow")
        return self.ds.pop()

    def tos(self):
        if not self.ds:
            raise Exception("Forth: Stack underflow")
        return self.ds[-1]

    def push_d(self, dval):
        dval = int(dval) & 0xFFFFFFFF
        low = dval & 0xFFFF
        high = (dval >> 16) & 0xFFFF
        self.push(((low + 32768) % 65536) - 32768)
        self.push(((high + 32768) % 65536) - 32768)

    def pop_d(self):
        high = self.pop() & 0xFFFF
        low = self.pop() & 0xFFFF
        dval = (high << 16) | low
        if dval >= 0x80000000:
            dval -= 0x100000000
        return dval

    def peek_byte(self, addr):
        return int(zx_peek(addr))

    def poke_byte(self, addr, val):
        zx_poke(addr, val)

    def peek_word(self, addr):
        low = self.peek_byte(addr)
        high = self.peek_byte(addr + 1)
        val = low | (high << 8)
        return ((val + 32768) % 65536) - 32768

    def poke_word(self, addr, val):
        val = int(val) & 0xFFFF
        self.poke_byte(addr, val & 0xFF)
        self.poke_byte(addr + 1, (val >> 8) & 0xFF)

    def print_text(self, text):
        self.output_buffer.append(str(text))

    def emit(self, ch):
        self.output_buffer.append(chr(ch & 0xFF))

    def cr(self):
        line = "".join(self.output_buffer)
        self.output_buffer.clear()
        canvas_print(line)

    def flush_output(self):
        if self.output_buffer:
            line = "".join(self.output_buffer)
            self.output_buffer.clear()
            canvas_print(line)

    # ------------------ Mass Storage System ------------------
    def get_block_buffer(self, blk):
        global microdrive_attachments
        blk = int(blk)
        self.last_accessed_blk = blk
        self.scr = blk
        if blk in self.block_buffers:
            return self.block_buffers[blk]

        buf_addr = self.BUFFER_BASE + ((blk % 12) * 1024)
        data = bytearray(1024)

        if self.current_media == "local":
            if os.path.exists(self.screen_file_path):
                with open(self.screen_file_path, "rb") as f:
                    f.seek(blk * 1024)
                    chunk = f.read(1024)
                    if chunk:
                        data[:len(chunk)] = chunk
        elif self.current_media == "mdr":
            d_num = max(1, min(8, self.current_drive or 1))
            mdr_fname = microdrive_attachments.get(d_num, f"{d_num}.mdr")
            if os.path.exists(mdr_fname):
                with open(mdr_fname, "rb") as f:
                    f.seek((blk - 1) * 1024 if blk > 0 else 0)
                    chunk = f.read(1024)
                    if chunk:
                        data[:len(chunk)] = chunk
        elif self.current_media == "fdi":
            d_num = max(1, min(2, self.current_drive or 1))
            disk = get_mgt_disk(d_num)
            if disk:
                raw_off = (4 * disk.BYTES_PER_TRACK) + (blk * 1024)
                if raw_off + 1024 <= len(disk.raw_data):
                    data[:] = disk.raw_data[raw_off : raw_off + 1024]

        entry = {"data": data, "dirty": False, "addr": buf_addr}
        self.block_buffers[blk] = entry
        for i in range(1024):
            self.poke_byte(buf_addr + i, data[i])
        return entry

    def mark_update(self):
        buf = self.get_block_buffer(self.last_accessed_blk)
        buf["dirty"] = True

    def flush_buffers(self):
        global microdrive_attachments
        for blk, entry in list(self.block_buffers.items()):
            if entry["dirty"]:
                buf_addr = entry["addr"]
                for i in range(1024):
                    entry["data"][i] = self.peek_byte(buf_addr + i)

                if self.current_media == "local":
                    mode = "r+b" if os.path.exists(self.screen_file_path) else "wb"
                    with open(self.screen_file_path, mode) as f:
                        f.seek(blk * 1024)
                        f.write(entry["data"])
                elif self.current_media == "mdr":
                    d_num = max(1, min(8, self.current_drive or 1))
                    mdr_fname = microdrive_attachments.get(d_num, f"{d_num}.mdr")
                    mode = "r+b" if os.path.exists(mdr_fname) else "wb"
                    with open(mdr_fname, mode) as f:
                        f.seek((blk - 1) * 1024 if blk > 0 else 0)
                        f.write(entry["data"])
                elif self.current_media == "fdi":
                    d_num = max(1, min(2, self.current_drive or 1))
                    disk = get_mgt_disk(d_num)
                    if disk:
                        raw_off = (4 * disk.BYTES_PER_TRACK) + (blk * 1024)
                        if raw_off + 1024 <= len(disk.raw_data):
                            disk.raw_data[raw_off : raw_off + 1024] = entry["data"]
                            disk.save_fdi()
                entry["dirty"] = False

    def select_drive(self, n):
        n = int(n)
        self.current_drive = n
        if n == 0:
            self.current_media = "local"
        else:
            if self.current_media not in ("mdr", "fdi"):
                self.current_media = "local"

    def use_media(self, name):
        name = name.strip().strip('"').strip("'")
        if name.lower().endswith(".mdr") or re.match(r'^(?:m|mdr)\s*(\d+)$', name, re.IGNORECASE):
            m = re.search(r'(\d+)', name)
            d = int(m.group(1)) if m else 1
            self.current_media = "mdr"
            self.current_drive = max(1, min(8, d))
            canvas_print(f"Forth screens set to Microdrive {self.current_drive}")
        elif name.lower().endswith(".fdi") or re.match(r'^(?:d|fdi)\s*(\d+)$', name, re.IGNORECASE):
            m = re.search(r'(\d+)', name)
            d = int(m.group(1)) if m else 1
            self.current_media = "fdi"
            self.current_drive = max(1, min(2, d))
            canvas_print(f"Forth screens set to FDI Floppy Drive {self.current_drive}")
        else:
            self.current_media = "local"
            self.screen_file_path = os.path.abspath(name)
            canvas_print(f"Forth screens set to local file '{name}'")
        self.block_buffers.clear()

    def catalog_media(self):
        if self.current_media == "local":
            files = [f for f in os.listdir(".") if f.endswith((".fth", ".scr", ".tap", ".zxb", ".mdr", ".fdi"))]
            canvas_print(f"--- LOCAL FORTH FILES ({len(files)}) ---")
            for f in files[:10]:
                canvas_print(f"  {f}")
        elif self.current_media == "mdr":
            mdr_cat(self.current_drive or 1)
        elif self.current_media == "fdi":
            mgt_cat(self.current_drive or 1)

    def list_screen(self, blk):
        entry = self.get_block_buffer(blk)
        data = entry["data"]
        canvas_print(f"SCR # {blk}")
        for r in range(16):
            line_bytes = data[r * 64 : (r + 1) * 64]
            line_str = "".join(chr(b) if 32 <= b <= 126 else " " for b in line_bytes).rstrip()
            canvas_print(f"{r:2} {line_str}")

    def index_screens(self, from_s, to_s):
        for s in range(from_s, to_s + 1):
            entry = self.get_block_buffer(s)
            line0 = "".join(chr(b) if 32 <= b <= 126 else " " for b in entry["data"][:64]).rstrip()
            canvas_print(f"{s:3} {line0}")

    def load_screen(self, blk):
        entry = self.get_block_buffer(blk)
        text = "".join(chr(b) if 32 <= b <= 126 or b in (10, 13) else " " for b in entry["data"])
        self.interpret(text)

    def rw_block(self, addr, blk, flag):
        entry = self.get_block_buffer(blk)
        if flag == 1:
            for i in range(1024):
                self.poke_byte(addr + i, entry["data"][i])
        else:
            for i in range(1024):
                entry["data"][i] = self.peek_byte(addr + i)
            entry["dirty"] = True

    # ------------------ Dictionary Initialization ------------------
    def add_word(self, name, func, is_immediate=False):
        self.dictionary[name.upper()] = ForthWord(name, is_primitive=True, func=func, is_immediate=is_immediate)

    def init_dictionary(self):
        # Stack Manipulation
        self.add_word("DUP", lambda e: e.push(e.tos()))
        self.add_word("DROP", lambda e: e.pop())
        self.add_word("SWAP", lambda e: (lambda b, a: (e.push(b), e.push(a)))(e.pop(), e.pop()))
        self.add_word("OVER", lambda e: (lambda b, a: (e.push(a), e.push(b), e.push(a)))(e.pop(), e.pop()))
        self.add_word("ROT", lambda e: (lambda c, b, a: (e.push(b), e.push(c), e.push(a)))(e.pop(), e.pop(), e.pop()))
        self.add_word("-ROT", lambda e: (lambda c, b, a: (e.push(c), e.push(a), e.push(b)))(e.pop(), e.pop(), e.pop()))
        self.add_word("?DUP", lambda e: e.push(e.tos()) if e.tos() != 0 else None)
        self.add_word("DEPTH", lambda e: e.push(len(e.ds)))
        self.add_word("PICK", lambda e: (lambda n: e.push(e.ds[-1 - n]))(e.pop()))
        self.add_word("ROLL", lambda e: (lambda n: e.push(e.ds.pop(-1 - n)))(e.pop()))
        self.add_word("2DUP", lambda e: (e.push(e.ds[-2]), e.push(e.ds[-2])))
        self.add_word("2DROP", lambda e: (e.pop(), e.pop()))
        self.add_word("2SWAP", lambda e: (lambda d, c, b, a: (e.push(c), e.push(d), e.push(a), e.push(b)))(e.pop(), e.pop(), e.pop(), e.pop()))
        self.add_word("2OVER", lambda e: (e.push(e.ds[-4]), e.push(e.ds[-4])))
        self.add_word(">R", lambda e: e.rs.append(e.pop()))
        self.add_word("R>", lambda e: e.push(e.rs.pop()))
        self.add_word("R@", lambda e: e.push(e.rs[-1]))
        self.add_word("2>R", lambda e: (lambda b, a: (e.rs.append(a), e.rs.append(b)))(e.pop(), e.pop()))
        self.add_word("2R>", lambda e: (lambda b, a: (e.push(a), e.push(b)))(e.rs.pop(), e.rs.pop()))
        self.add_word("2R@", lambda e: (e.push(e.rs[-2]), e.push(e.rs[-1])))
        self.add_word("SP@", lambda e: e.push(len(e.ds)))
        self.add_word("SP!", lambda e: e.ds.clear())
        self.add_word("RP@", lambda e: e.push(len(e.rs)))
        self.add_word("RP!", lambda e: e.rs.clear())

        # Arithmetic & Logic
        self.add_word("+", lambda e: (lambda b, a: e.push(a + b))(e.pop(), e.pop()))
        self.add_word("-", lambda e: (lambda b, a: e.push(a - b))(e.pop(), e.pop()))
        self.add_word("*", lambda e: (lambda b, a: e.push(a * b))(e.pop(), e.pop()))
        self.add_word("/", lambda e: (lambda b, a: e.push(int(a / b)))(e.pop(), e.pop()))
        self.add_word("MOD", lambda e: (lambda b, a: e.push(a % b))(e.pop(), e.pop()))
        self.add_word("/MOD", lambda e: (lambda b, a: (e.push(a % b), e.push(int(a / b))))(e.pop(), e.pop()))
        self.add_word("*/", lambda e: (lambda c, b, a: e.push(int((a * b) / c)))(e.pop(), e.pop(), e.pop()))
        self.add_word("*/MOD", lambda e: (lambda c, b, a: (e.push((a * b) % c), e.push(int((a * b) / c))))(e.pop(), e.pop(), e.pop()))
        self.add_word("1+", lambda e: e.push(e.pop() + 1))
        self.add_word("2+", lambda e: e.push(e.pop() + 2))
        self.add_word("1-", lambda e: e.push(e.pop() - 1))
        self.add_word("2-", lambda e: e.push(e.pop() - 2))
        self.add_word("2*", lambda e: e.push(e.pop() << 1))
        self.add_word("2/", lambda e: e.push(e.pop() >> 1))
        self.add_word("ABS", lambda e: e.push(abs(e.pop())))
        self.add_word("NEGATE", lambda e: e.push(-e.pop()))
        self.add_word("MIN", lambda e: (lambda b, a: e.push(min(a, b)))(e.pop(), e.pop()))
        self.add_word("MAX", lambda e: (lambda b, a: e.push(max(a, b)))(e.pop(), e.pop()))
        self.add_word("AND", lambda e: (lambda b, a: e.push(a & b))(e.pop(), e.pop()))
        self.add_word("OR", lambda e: (lambda b, a: e.push(a | b))(e.pop(), e.pop()))
        self.add_word("XOR", lambda e: (lambda b, a: e.push(a ^ b))(e.pop(), e.pop()))
        self.add_word("NOT", lambda e: e.push(1 if e.pop() == 0 else 0))
        self.add_word("0=", lambda e: e.push(1 if e.pop() == 0 else 0))
        self.add_word("0<", lambda e: e.push(1 if e.pop() < 0 else 0))
        self.add_word("0>", lambda e: e.push(1 if e.pop() > 0 else 0))
        self.add_word("=", lambda e: (lambda b, a: e.push(1 if a == b else 0))(e.pop(), e.pop()))
        self.add_word("<", lambda e: (lambda b, a: e.push(1 if a < b else 0))(e.pop(), e.pop()))
        self.add_word(">", lambda e: (lambda b, a: e.push(1 if a > b else 0))(e.pop(), e.pop()))
        self.add_word("<>", lambda e: (lambda b, a: e.push(1 if a != b else 0))(e.pop(), e.pop()))
        self.add_word("U<", lambda e: (lambda b, a: e.push(1 if (a & 0xFFFF) < (b & 0xFFFF) else 0))(e.pop(), e.pop()))
        self.add_word("U>", lambda e: (lambda b, a: e.push(1 if (a & 0xFFFF) > (b & 0xFFFF) else 0))(e.pop(), e.pop()))

        # Double numbers
        self.add_word("D+", lambda e: e.push_d(e.pop_d() + e.pop_d()))
        self.add_word("D-", lambda e: (lambda d2, d1: e.push_d(d1 - d2))(e.pop_d(), e.pop_d()))
        self.add_word("DABS", lambda e: e.push_d(abs(e.pop_d())))
        self.add_word("DNEGATE", lambda e: e.push_d(-e.pop_d()))

        # Memory Interception
        self.add_word("@", lambda e: e.push(e.peek_word(e.pop())))
        self.add_word("!", lambda e: (lambda addr, val: e.poke_word(addr, val))(e.pop(), e.pop()))
        self.add_word("C@", lambda e: e.push(e.peek_byte(e.pop())))
        self.add_word("C!", lambda e: (lambda addr, val: e.poke_byte(addr, val))(e.pop(), e.pop()))
        self.add_word("+!", lambda e: (lambda addr, n: e.poke_word(addr, e.peek_word(addr) + n))(e.pop(), e.pop()))
        self.add_word("2@", lambda e: (lambda addr: (e.push(e.peek_word(addr)), e.push(e.peek_word(addr + 2))))(e.pop()))
        self.add_word("2!", lambda e: (lambda addr, high, low: (e.poke_word(addr, low), e.poke_word(addr + 2, high)))(e.pop(), e.pop(), e.pop()))
        self.add_word("MOVE", lambda e: (lambda u, dst, src: [e.poke_byte(dst + i, e.peek_byte(src + i)) for i in range(u)])(e.pop(), e.pop(), e.pop()))
        self.add_word("CMOVE", lambda e: (lambda u, dst, src: [e.poke_byte(dst + i, e.peek_byte(src + i)) for i in range(u)])(e.pop(), e.pop(), e.pop()))
        self.add_word("CMOVE>", lambda e: (lambda u, dst, src: [e.poke_byte(dst + i, e.peek_byte(src + i)) for i in range(u - 1, -1, -1)])(e.pop(), e.pop(), e.pop()))
        self.add_word("FILL", lambda e: (lambda b, u, addr: [e.poke_byte(addr + i, b) for i in range(u)])(e.pop(), e.pop(), e.pop()))
        self.add_word("ERASE", lambda e: (lambda u, addr: [e.poke_byte(addr + i, 0) for i in range(u)])(e.pop(), e.pop()))
        self.add_word("BLANKS", lambda e: (lambda u, addr: [e.poke_byte(addr + i, 32) for i in range(u)])(e.pop(), e.pop()))

        # Compilation & Dictionary words
        self.add_word("HERE", lambda e: e.push(e.dp))
        self.add_word("PAD", lambda e: e.push(e.dp + 68))
        self.add_word("DP", lambda e: e.push(23800))
        self.add_word("SCR", lambda e: e.push(23802))
        self.add_word("BASE", lambda e: e.push(23804))
        self.add_word("DECIMAL", lambda e: setattr(e, "base", 10))
        self.add_word("HEX", lambda e: setattr(e, "base", 16))
        self.add_word("OCTAL", lambda e: setattr(e, "base", 8))
        self.add_word("BINARY", lambda e: setattr(e, "base", 2))
        self.add_word("ALLOT", lambda e: setattr(e, "dp", e.dp + e.pop()))
        self.add_word(",", lambda e: (lambda val: (e.poke_word(e.dp, val), setattr(e, "dp", e.dp + 2)))(e.pop()))
        self.add_word("C,", lambda e: (lambda val: (e.poke_byte(e.dp, val), setattr(e, "dp", e.dp + 1)))(e.pop()))
        self.add_word("EXECUTE", lambda e: e.execute_token(e.pop()))

        self.poke_word(23804, 10)  # BASE
        self.poke_word(23802, 1)   # SCR

        # I/O & Output
        self.add_word(".", lambda e: e.print_text(f"{e.pop()} "))
        self.add_word("U.", lambda e: e.print_text(f"{e.pop() & 0xFFFF} "))
        self.add_word(".R", lambda e: (lambda w, n: e.print_text(f"{n:>{w}}"))(e.pop(), e.pop()))
        self.add_word("U.R", lambda e: (lambda w, u: e.print_text(f"{u & 0xFFFF:>{w}}"))(e.pop(), e.pop()))
        self.add_word("D.", lambda e: e.print_text(f"{e.pop_d()} "))
        self.add_word("?", lambda e: e.print_text(f"{e.peek_word(e.pop())} "))
        self.add_word("CR", lambda e: e.cr())
        self.add_word("SPACE", lambda e: e.print_text(" "))
        self.add_word("SPACES", lambda e: e.print_text(" " * max(0, e.pop())))
        self.add_word("EMIT", lambda e: e.emit(e.pop()))
        self.add_word("KEY", lambda e: (lambda k: e.push(ord(k[0]) if k else 32))(last_keypress or get_joystick_inkey()))
        self.add_word("KEY?", lambda e: e.push(1 if (last_keypress or get_joystick_inkey()) else 0))
        self.add_word("?KEY", lambda e: e.push(1 if (last_keypress or get_joystick_inkey()) else 0))
        self.add_word("COUNT", lambda e: (lambda addr: (e.push(addr + 1), e.push(e.peek_byte(addr))))(e.pop()))
        self.add_word("TYPE", lambda e: (lambda u, addr: e.print_text("".join(chr(e.peek_byte(addr + i)) for i in range(u))))(e.pop(), e.pop()))

        # Abersoft Spectrum Graphics
        self.add_word("PLOT", lambda e: (lambda y, x: (plot_pixel(x, y), update_display()))(e.pop(), e.pop()))
        self.add_word("UNPLOT", lambda e: (lambda y, x: (unplot_pixel(x, y), update_display()))(e.pop(), e.pop()))
        self.add_word("POINT", lambda e: (lambda y, x: e.push(1 if (0 <= x < (512 if timex_screen_mode == 6 else 256) and 0 <= y < 192 and gfx_bits[x][y]) else 0))(e.pop(), e.pop()))
        self.add_word("DRAW", lambda e: (lambda dy, dx: (draw_relative(dx, dy), update_display()))(e.pop(), e.pop()))
        self.add_word("LINE", lambda e: (lambda y2, x2, y1, x1: (draw_line(x1, y1, x2, y2), update_display()))(e.pop(), e.pop(), e.pop(), e.pop()))
        self.add_word("CIRCLE", lambda e: (lambda r, y, x: (draw_circle(x, y, r), update_display()))(e.pop(), e.pop(), e.pop()))
        self.add_word("ARC", lambda e: (lambda phi, dy, dx: (draw_arc(dx, dy, phi), update_display()))(e.pop(), e.pop(), e.pop()))
        self.add_word("BOX", lambda e: (lambda h, w, y, x: (draw_box(x, y, w, h), update_display()))(e.pop(), e.pop(), e.pop(), e.pop()))
        self.add_word("FILL", lambda e: (lambda y, x: (canvas_fill(x, y), update_display()))(e.pop(), e.pop()))
        self.add_word("CLS", lambda e: execute_cls())
        self.add_word("PAGE", lambda e: execute_cls())
        self.add_word("AT", lambda e: (lambda c, l: (globals().__setitem__("print_row", max(0, min(23, l))), globals().__setitem__("print_col", max(0, min(31, c)))))(e.pop(), e.pop()))
        self.add_word("INK", lambda e: globals().__setitem__("current_ink", e.pop() & 7))
        self.add_word("PAPER", lambda e: globals().__setitem__("current_paper", e.pop() & 7))
        self.add_word("FLASH", lambda e: globals().__setitem__("current_flash", bool(e.pop())))
        self.add_word("BRIGHT", lambda e: globals().__setitem__("current_bright", bool(e.pop())))
        self.add_word("INVERSE", lambda e: globals().__setitem__("current_inverse", bool(e.pop())))
        self.add_word("SET-OVER", lambda e: globals().__setitem__("current_over", bool(e.pop())))
        self.add_word("OVER-MODE", lambda e: globals().__setitem__("current_over", bool(e.pop())))
        self.add_word("BORDER", lambda e: (globals().__setitem__("current_border", e.pop() & 7), update_display()))
        self.add_word("ATTR", lambda e: (lambda c, l: e.push(e.peek_byte(22528 + (l * 32) + c)))(e.pop(), e.pop()))
        # Timex Sinclair 2068 Forth Words
        self.add_word("MODE", lambda e: set_timex_mode(e.pop()))
        self.add_word("MODE0", lambda e: set_timex_mode(0))
        self.add_word("MODE1", lambda e: set_timex_mode(1))
        self.add_word("MODE2", lambda e: set_timex_mode(2))
        self.add_word("MODE6", lambda e: set_timex_mode(6))
        self.add_word("OUT255", lambda e: handle_out_port(255, e.pop()))
        self.add_word("PORT!", lambda e: (lambda port, val: handle_out_port(port, val))(e.pop(), e.pop()))
        self.add_word("PORT@", lambda e: e.push(int(read_in_port(e.pop()))))

        # Abersoft Sound
        self.add_word("BEEP", lambda e: (lambda pitch, dur: play_spectrum_beep(dur / 1000.0 if dur > 20 else dur, pitch))(e.pop(), e.pop()))
        self.add_word("BLEEP", lambda e: (lambda pitch, dur: play_spectrum_beep(dur / 1000.0 if dur > 20 else dur, pitch))(e.pop(), e.pop()))

        self.add_word("UDG", lambda e: execute_udg_command(str(e.pop())))
        self.add_word("UDGED", lambda e: launch_udg_editor())
        self.add_word("EDSPRITES", lambda e: launch_sprite_editor())
        self.add_word("EDTILES", lambda e: launch_tile_editor() if launch_tile_editor else None)
        self.add_word("GUI", lambda e: launch_wimp_desktop() if launch_wimp_desktop else None)
        self.add_word("ICONED", lambda e: launch_icon_editor() if launch_icon_editor else None)
        self.add_word("MENU", lambda e: handle_wimp_menu_command(str(e.pop())) if handle_wimp_menu_command and e.stack else None)
        self.add_word("ICON", lambda e: handle_wimp_icon_command(str(e.pop())) if handle_wimp_icon_command and e.stack else None)
        self.add_word("WINDOW", lambda e: handle_wimp_window_command(str(e.pop())) if handle_wimp_window_command and e.stack else None)
        self.add_word("MOUSE", lambda e: (lambda d: (lambda x, y, b, c: (e.push(x), e.push(y), e.push(b)))(*d.query_mouse_state()))(WIMPDesktop.get_instance()) if WIMPDesktop else None)
        self.add_word("MUSIC", lambda e: launch_music_editor())

        self.add_word("SET-DRIVE", lambda e: handle_set_drive_command(str(e.pop()) if e.stack else ""))
        self.add_word("SET-MDR", lambda e: handle_set_mdr_command(str(e.pop()) if e.stack else ""))
        self.add_word("SET DRIVE", lambda e: handle_set_drive_command(str(e.pop()) if e.stack else ""))
        self.add_word("SET MDR", lambda e: handle_set_mdr_command(str(e.pop()) if e.stack else ""))
        self.add_word("SET-SPRITES", lambda e: handle_set_sprites_command(str(e.pop()) if e.stack else ""))
        self.add_word("SET SPRITES", lambda e: handle_set_sprites_command(str(e.pop()) if e.stack else ""))
        self.add_word("ATTACH", lambda e: handle_unified_attach(str(e.pop()) if e.stack else ""))
        self.add_word("ADD-DRIVE", lambda e: handle_unified_attach(str(e.pop()) if e.stack else ""))
        self.add_word("ADD DRIVE", lambda e: handle_unified_attach(str(e.pop()) if e.stack else ""))
        self.add_word("DRUMS", lambda e: launch_drum_editor())
        self.add_word("SFX", lambda e: launch_sfx_editor())
        self.add_word("JPG", lambda e: execute_jpg_command(""))
        self.add_word("JOYSTICK", lambda e: execute_joystick_command(str(e.pop())))
        self.add_word("JOYSTICK-KEMP", lambda e: execute_joystick_command("KEMP"))
        self.add_word("JOYSTICK-CURS", lambda e: execute_joystick_command("CURS"))
        self.add_word("JOYSTICK-SINC1", lambda e: execute_joystick_command("SINC1"))
        self.add_word("JOYSTICK-SINC2", lambda e: execute_joystick_command("SINC2"))
        self.add_word("JOYSTICK-INF2", lambda e: execute_joystick_command("INF2"))
        self.add_word("JOYSTICK-FULR", lambda e: execute_joystick_command("FULR"))
        self.add_word("DRUM", lambda e: specdrum_subsystem.play_drum(e.pop()))
        self.add_word("SPECDRUM", lambda e: specdrum_subsystem.play_drum(e.pop()))

        # Block Mass Storage Words
        self.add_word("BLOCK", lambda e: e.push(e.get_block_buffer(e.pop())["addr"]))
        self.add_word("BUFFER", lambda e: (lambda blk: e.push(e.get_block_buffer(blk)["addr"]))(e.pop()))
        self.add_word("UPDATE", lambda e: e.mark_update())
        self.add_word("FLUSH", lambda e: e.flush_buffers())
        self.add_word("SAVE-BUFFERS", lambda e: e.flush_buffers())
        self.add_word("EMPTY-BUFFERS", lambda e: e.block_buffers.clear())
        self.add_word("LIST", lambda e: e.list_screen(e.pop()))
        self.add_word("INDEX", lambda e: (lambda to_s, from_s: e.index_screens(from_s, to_s))(e.pop(), e.pop()))
        self.add_word("TRIAD", lambda e: (lambda n: [e.list_screen((n // 3) * 3 + i) for i in range(3)])(e.pop()))
        self.add_word("LOAD", lambda e: e.load_screen(e.pop()))
        self.add_word("R/W", lambda e: (lambda flag, blk, addr: e.rw_block(addr, blk, flag))(e.pop(), e.pop(), e.pop()))

        # Drive & Multi-Media Selection
        self.add_word("DRIVE", lambda e: e.select_drive(e.pop()))
        self.add_word("DR0", lambda e: e.select_drive(0))
        self.add_word("DR1", lambda e: e.select_drive(1))
        self.add_word("DR2", lambda e: e.select_drive(2))
        self.add_word("DR3", lambda e: e.select_drive(3))
        self.add_word("DR4", lambda e: e.select_drive(4))
        self.add_word("DR5", lambda e: e.select_drive(5))
        self.add_word("DR6", lambda e: e.select_drive(6))
        self.add_word("DR7", lambda e: e.select_drive(7))
        self.add_word("DR8", lambda e: e.select_drive(8))
        self.add_word("MDR", lambda e: setattr(e, "current_media", "mdr"))
        self.add_word("FDI", lambda e: setattr(e, "current_media", "fdi"))
        self.add_word("MDR-DRIVE", lambda e: (setattr(e, "current_media", "mdr"), setattr(e, "current_drive", max(1, min(8, e.pop())))))
        self.add_word("FDI-DRIVE", lambda e: (setattr(e, "current_media", "fdi"), setattr(e, "current_drive", max(1, min(2, e.pop())))))
        self.add_word("MDR-CAT", lambda e: mdr_cat(e.current_drive or 1))
        self.add_word("FDI-CAT", lambda e: mgt_cat(e.current_drive or 1))
        self.add_word("CAT", lambda e: e.catalog_media())
        self.add_word("CATALOG", lambda e: e.catalog_media())
        self.add_word("BOOT", lambda e: handle_boot_command(str(e.pop()) if len(e.ds) > 0 else ""))

        # Immediate Control Words
        self.add_word("IMMEDIATE", lambda e: setattr(e.get_latest_word(), "is_immediate", True))
        self.add_word(":", lambda e: None, is_immediate=True)
        self.add_word(";", lambda e: None, is_immediate=True)
        self.add_word("IF", lambda e: None, is_immediate=True)
        self.add_word("ELSE", lambda e: None, is_immediate=True)
        self.add_word("THEN", lambda e: None, is_immediate=True)
        self.add_word("DO", lambda e: None, is_immediate=True)
        self.add_word("LOOP", lambda e: None, is_immediate=True)
        self.add_word("+LOOP", lambda e: None, is_immediate=True)
        self.add_word("LEAVE", lambda e: None, is_immediate=True)
        self.add_word("I", lambda e: e.push(e.rs[-1]))
        self.add_word("J", lambda e: e.push(e.rs[-3]))
        self.add_word("BEGIN", lambda e: None, is_immediate=True)
        self.add_word("UNTIL", lambda e: None, is_immediate=True)
        self.add_word("WHILE", lambda e: None, is_immediate=True)
        self.add_word("REPEAT", lambda e: None, is_immediate=True)
        self.add_word("AGAIN", lambda e: None, is_immediate=True)
        self.add_word("CASE", lambda e: None, is_immediate=True)
        self.add_word("OF", lambda e: None, is_immediate=True)
        self.add_word("ENDOF", lambda e: None, is_immediate=True)
        self.add_word("ENDCASE", lambda e: None, is_immediate=True)

    def get_latest_word(self):
        if not self.dictionary:
            return None
        return list(self.dictionary.values())[-1]

    # ------------------ Interpreter & Compiler ------------------
    def eval(self, code_str):
        return self.interpret(code_str)

    def interpret(self, code_str):
        tokens = []
        i = 0
        n = len(code_str)
        while i < n:
            ch = code_str[i]
            if ch.isspace():
                i += 1
                continue

            if ch == '\\' and (i + 1 == n or code_str[i+1].isspace()):
                while i < n and code_str[i] != '\n':
                    i += 1
                continue

            if ch == '(' and (i + 1 < n and code_str[i+1].isspace()):
                end_p = code_str.find(')', i)
                if end_p != -1:
                    i = end_p + 1
                    continue
                else:
                    break

            if code_str[i:i+3] == '."' and (i + 2 == n or code_str[i+2].isspace() or code_str[i+2] == '"'):
                i += 2
                while i < n and code_str[i].isspace(): i += 1
                end_q = code_str.find('"', i)
                if end_q != -1:
                    tokens.append(('DOT_QUOTE', code_str[i:end_q]))
                    i = end_q + 1
                    continue

            if code_str[i:i+3] == '.(' and (i + 2 == n or code_str[i+2].isspace()):
                i += 2
                while i < n and code_str[i].isspace(): i += 1
                end_p = code_str.find(')', i)
                if end_p != -1:
                    tokens.append(('DOT_PAREN', code_str[i:end_p]))
                    i = end_p + 1
                    continue

            start = i
            while i < n and not code_str[i].isspace():
                i += 1
            word_str = code_str[start:i]
            tokens.append(('WORD', word_str))

        token_idx = 0
        while token_idx < len(tokens):
            t_type, t_val = tokens[token_idx]
            token_idx += 1

            if t_type == 'DOT_QUOTE':
                if self.state == 1:
                    self.compiling_body.append(('DOT_QUOTE', t_val))
                else:
                    self.print_text(t_val)
                continue
            elif t_type == 'DOT_PAREN':
                self.print_text(t_val)
                continue

            w_upper = t_val.upper()

            # End Forth marker inside Forth code
            if w_upper in ("END_FORTH", "END") and token_idx < len(tokens) and tokens[token_idx][1].upper() == "FORTH":
                token_idx += 1
                break
            if w_upper == "END_FORTH":
                break

            # Colon definition start
            if w_upper == ':':
                if token_idx < len(tokens):
                    _, name = tokens[token_idx]
                    token_idx += 1
                    self.state = 1
                    self.compiling_word = name.upper()
                    self.compiling_body = []
                    self.control_stack.clear()
                continue

            # Colon definition end
            if w_upper == ';':
                if self.state == 1:
                    self.compiling_body.append(('EXIT', None))
                    new_word = ForthWord(self.compiling_word, is_primitive=False, compiled_body=list(self.compiling_body))
                    self.dictionary[self.compiling_word] = new_word
                    self.state = 0
                    self.compiling_word = None
                    self.compiling_body.clear()
                continue

            # Compile-time control structures
            if self.state == 1:
                if w_upper == 'IF':
                    idx = len(self.compiling_body)
                    self.compiling_body.append(('0BRANCH', None))
                    self.control_stack.append(('IF', idx))
                    continue
                elif w_upper == 'ELSE':
                    idx = len(self.compiling_body)
                    self.compiling_body.append(('BRANCH', None))
                    if self.control_stack and self.control_stack[-1][0] == 'IF':
                        _, if_idx = self.control_stack.pop()
                        self.compiling_body[if_idx] = ('0BRANCH', idx + 1)
                    self.control_stack.append(('ELSE', idx))
                    continue
                elif w_upper == 'THEN':
                    if self.control_stack:
                        tag, j_idx = self.control_stack.pop()
                        curr_len = len(self.compiling_body)
                        if tag == 'IF':
                            self.compiling_body[j_idx] = ('0BRANCH', curr_len)
                        elif tag == 'ELSE':
                            self.compiling_body[j_idx] = ('BRANCH', curr_len)
                    continue
                elif w_upper == 'DO':
                    idx = len(self.compiling_body)
                    self.compiling_body.append(('DO', None))
                    self.control_stack.append(('DO', idx))
                    continue
                elif w_upper == 'LOOP':
                    if self.control_stack and self.control_stack[-1][0] == 'DO':
                        _, do_idx = self.control_stack.pop()
                        self.compiling_body.append(('LOOP', do_idx + 1))
                    continue
                elif w_upper == '+LOOP':
                    if self.control_stack and self.control_stack[-1][0] == 'DO':
                        _, do_idx = self.control_stack.pop()
                        self.compiling_body.append(('+LOOP', do_idx + 1))
                    continue
                elif w_upper == 'LEAVE':
                    self.compiling_body.append(('LEAVE', None))
                    continue
                elif w_upper == 'BEGIN':
                    idx = len(self.compiling_body)
                    self.control_stack.append(('BEGIN', idx))
                    continue
                elif w_upper == 'UNTIL':
                    if self.control_stack and self.control_stack[-1][0] == 'BEGIN':
                        _, begin_idx = self.control_stack.pop()
                        self.compiling_body.append(('0BRANCH', begin_idx))
                    continue
                elif w_upper == 'AGAIN':
                    if self.control_stack and self.control_stack[-1][0] == 'BEGIN':
                        _, begin_idx = self.control_stack.pop()
                        self.compiling_body.append(('BRANCH', begin_idx))
                    continue
                elif w_upper == 'WHILE':
                    idx = len(self.compiling_body)
                    self.compiling_body.append(('0BRANCH', None))
                    self.control_stack.append(('WHILE', idx))
                    continue
                elif w_upper == 'REPEAT':
                    if len(self.control_stack) >= 2 and self.control_stack[-1][0] == 'WHILE' and self.control_stack[-2][0] == 'BEGIN':
                        _, while_idx = self.control_stack.pop()
                        _, begin_idx = self.control_stack.pop()
                        self.compiling_body.append(('BRANCH', begin_idx))
                        self.compiling_body[while_idx] = ('0BRANCH', len(self.compiling_body))
                    continue
                elif w_upper == 'CASE':
                    self.control_stack.append(('CASE', []))
                    continue
                elif w_upper == 'OF':
                    idx = len(self.compiling_body)
                    self.compiling_body.append(('OF', None))
                    self.control_stack.append(('OF', idx))
                    continue
                elif w_upper == 'ENDOF':
                    if self.control_stack and self.control_stack[-1][0] == 'OF':
                        _, of_idx = self.control_stack.pop()
                        idx = len(self.compiling_body)
                        self.compiling_body.append(('BRANCH', None))
                        self.compiling_body[of_idx] = ('OF', len(self.compiling_body))
                        if self.control_stack and self.control_stack[-1][0] == 'CASE':
                            self.control_stack[-1][1].append(idx)
                    continue
                elif w_upper == 'ENDCASE':
                    if self.control_stack and self.control_stack[-1][0] == 'CASE':
                        _, exit_jumps = self.control_stack.pop()
                        self.compiling_body.append(('DROP', None))
                        for ej in exit_jumps:
                            self.compiling_body[ej] = ('BRANCH', len(self.compiling_body))
                    continue
                elif w_upper in ('RECURSE', 'MYSELF'):
                    self.compiling_body.append(('RECURSE', None))
                    continue

                if w_upper in self.dictionary:
                    w_obj = self.dictionary[w_upper]
                    if w_obj.is_immediate:
                        w_obj.func(self)
                        continue
                    else:
                        self.compiling_body.append(('EXEC', w_obj))
                        continue

            # Defining words when interpreting
            if self.state == 0:
                if w_upper == 'VARIABLE':
                    if token_idx < len(tokens):
                        _, vname = tokens[token_idx]
                        token_idx += 1
                        var_addr = self.dp
                        self.dp += 2
                        self.poke_word(var_addr, 0)
                        self.add_word(vname, lambda e, a=var_addr: e.push(a))
                    continue
                elif w_upper == 'CONSTANT':
                    if token_idx < len(tokens):
                        _, cname = tokens[token_idx]
                        token_idx += 1
                        cval = self.pop()
                        self.add_word(cname, lambda e, v=cval: e.push(v))
                    continue
                elif w_upper == 'VALUE':
                    if token_idx < len(tokens):
                        _, vname = tokens[token_idx]
                        token_idx += 1
                        val = self.pop()
                        val_cell = [val]
                        self.add_word(vname, lambda e, cell=val_cell: e.push(cell[0]))
                        self.add_word(f"TO_{vname}", lambda e, cell=val_cell: cell.__setitem__(0, e.pop()))
                    continue
                elif w_upper == 'TO':
                    if token_idx < len(tokens):
                        _, vname = tokens[token_idx]
                        token_idx += 1
                        to_key = f"TO_{vname.upper()}"
                        if to_key in self.dictionary:
                            self.dictionary[to_key].func(self)
                    continue
                elif w_upper == 'USE':
                    if token_idx < len(tokens):
                        _, media_arg = tokens[token_idx]
                        token_idx += 1
                        self.use_media(media_arg)
                    continue
                elif w_upper in ('INCLUDE', 'LOAD-FILE'):
                    if token_idx < len(tokens):
                        _, file_arg = tokens[token_idx]
                        token_idx += 1
                        clean_fname = file_arg.strip().strip('"').strip("'")
                        if os.path.exists(clean_fname):
                            with open(clean_fname, "r", encoding="utf-8", errors="ignore") as ff:
                                self.interpret(ff.read())
                    continue
                elif w_upper == 'MDR-SAVE':
                    if token_idx < len(tokens):
                        _, fname_arg = tokens[token_idx]
                        token_idx += 1
                        clean_fn = fname_arg.strip().strip('"').strip("'")
                        buf = self.get_block_buffer(self.scr)["data"]
                        mdr_write_file_bytes(self.current_drive or 1, clean_fn, bytes(buf), file_type="C")
                    continue
                elif w_upper == 'MDR-LOAD':
                    if token_idx < len(tokens):
                        _, fname_arg = tokens[token_idx]
                        token_idx += 1
                        clean_fn = fname_arg.strip().strip('"').strip("'")
                        data = mdr_read_file_bytes(self.current_drive or 1, clean_fn)
                        if data:
                            buf = self.get_block_buffer(self.scr)
                            buf["data"][:len(data)] = data[:1024]
                            buf["dirty"] = True
                    continue
                elif w_upper == 'FDI-SAVE':
                    if token_idx < len(tokens):
                        _, fname_arg = tokens[token_idx]
                        token_idx += 1
                        clean_fn = fname_arg.strip().strip('"').strip("'")
                        disk = get_mgt_disk(self.current_drive or 1)
                        if disk:
                            buf = self.get_block_buffer(self.scr)["data"]
                            disk.save_file(clean_fn, MGTDisk.TYPE_CODE, bytes(buf))
                    continue
                elif w_upper == 'FDI-LOAD':
                    if token_idx < len(tokens):
                        _, fname_arg = tokens[token_idx]
                        token_idx += 1
                        clean_fn = fname_arg.strip().strip('"').strip("'")
                        disk = get_mgt_disk(self.current_drive or 1)
                        if disk:
                            data = disk.load_file(clean_fn)
                            if data:
                                buf = self.get_block_buffer(self.scr)
                                buf["data"][:len(data)] = data[:1024]
                                buf["dirty"] = True
                    continue

            # Dictionary lookup
            if w_upper in self.dictionary:
                w_obj = self.dictionary[w_upper]
                if self.state == 1 and not w_obj.is_immediate:
                    self.compiling_body.append(('EXEC', w_obj))
                else:
                    self.execute_word(w_obj)
                continue

            num = self.parse_number(t_val)
            if num is not None:
                if self.state == 1:
                    self.compiling_body.append(('LIT', num))
                else:
                    self.push(num)
                continue

            raise Exception(f"Forth: Unknown word '{t_val}'")

        self.flush_output()

    def parse_number(self, s):
        radix = self.base
        s = s.strip()
        if not s:
            return None
        if s.startswith('$'):
            radix = 16
            s = s[1:]
        elif s.startswith('%'):
            radix = 2
            s = s[1:]
        elif s.startswith('#'):
            radix = 10
            s = s[1:]

        is_double = False
        if len(s) > 1 and s.endswith('.'):
            is_double = True
            s = s[:-1]

        try:
            if radix == 10 and '.' in s and not s.endswith('.'):
                return float(s)
            val = int(s, radix)
            if is_double:
                self.push_d(val)
                return None
            return val
        except ValueError:
            return None

    def execute_word(self, word_obj):
        if word_obj.is_primitive:
            word_obj.func(self)
        else:
            self.run_compiled(word_obj.compiled_body)

    def execute_token(self, xt):
        if isinstance(xt, ForthWord):
            self.execute_word(xt)

    def run_compiled(self, body):
        ip = 0
        n = len(body)
        while ip < n:
            op, arg = body[ip]
            if op == 'LIT':
                self.push(arg)
                ip += 1
            elif op == 'EXEC':
                self.execute_word(arg)
                ip += 1
            elif op == 'BRANCH':
                ip = arg
            elif op == '0BRANCH':
                cond = self.pop()
                if cond == 0:
                    ip = arg
                else:
                    ip += 1
            elif op == 'DO':
                init = self.pop()
                limit = self.pop()
                self.rs.append(limit)
                self.rs.append(init)
                ip += 1
            elif op == 'LOOP':
                init = self.rs.pop() + 1
                limit = self.rs[-1]
                if init < limit:
                    self.rs.append(init)
                    ip = arg
                else:
                    self.rs.pop()
                    ip += 1
            elif op == '+LOOP':
                step = self.pop()
                init = self.rs.pop() + step
                limit = self.rs[-1]
                if (step > 0 and init < limit) or (step < 0 and init > limit) or step == 0:
                    self.rs.append(init)
                    ip = arg
                else:
                    self.rs.pop()
                    ip += 1
            elif op == 'LEAVE':
                if len(self.rs) >= 2:
                    self.rs[-1] = self.rs[-2]
                ip += 1
            elif op == 'OF':
                test_val = self.pop()
                selector = self.tos()
                if selector == test_val:
                    self.pop()
                    ip += 1
                else:
                    ip = arg
            elif op == 'DROP':
                if self.ds:
                    self.pop()
                ip += 1
            elif op == 'DOT_QUOTE':
                self.print_text(arg)
                ip += 1
            elif op == 'EXIT':
                break
            elif op == 'RECURSE':
                self.run_compiled(body)
                ip += 1


def get_forth_engine():
    global forth_engine
    if forth_engine is None:
        forth_engine = ForthEngine()
    return forth_engine


# =========================================================================
# Sinclair ZX Spectrum LOGO Subsystem Implementation
# Authentic 1983 Sinclair Research / Logotron / LCSI 48K/128K Logo Engine
# =========================================================================

class LogoStop(Exception):
    pass

class LogoOutput(Exception):
    def __init__(self, value):
        self.value = value

class SinclairLogoEngine:
    def __init__(self):
        self.reset()

    def reset(self):
        # Turtle coordinates: (0, 0) is centered at screen (128, 96)
        self.x = 0.0
        self.y = 0.0
        self.heading = 0.0  # 0 = North (Up, +Y in Spectrum coordinates)
        self.pen_down = True
        self.pen_mode = "PAINT"  # PAINT, ERASE, REVERSE
        self.turtle_visible = True
        self.wrap_mode = "WINDOW"  # WINDOW, WRAP, FENCE
        self.ink = current_ink if 'current_ink' in globals() else 0
        self.paper = current_paper if 'current_paper' in globals() else 7
        self.border = current_border if 'current_border' in globals() else 7
        self.bright = current_bright if 'current_bright' in globals() else 0
        self.flash = current_flash if 'current_flash' in globals() else 0
        self.globals = {}
        self.procedures = {}
        self.local_stack = []
        self.repcount_stack = []
        self.last_test = None
        self.call_depth = 0
        self.max_call_depth = 500

    def home(self):
        old_x, old_y = self.x, self.y
        self.x = 0.0
        self.y = 0.0
        self.heading = 0.0
        if self.pen_down:
            self.draw_turtle_line(old_x, old_y, self.x, self.y)

    def clear_screen(self):
        global gfx_bits, canvas_dirty, timex_screen_mode
        self.x = 0.0
        self.y = 0.0
        self.heading = 0.0
        max_w = 512 if timex_screen_mode == 6 else 256
        for px in range(max_w):
            for py in range(192):
                gfx_bits[px][py] = False
        execute_cls()
        canvas_dirty = True
        if "redraw_canvas" in globals():
            redraw_canvas(force=True)

    def clear_text(self):
        global canvas_lines, canvas_dirty
        canvas_lines.clear()
        canvas_dirty = True

    def set_xy(self, new_x, new_y):
        old_x, old_y = self.x, self.y
        self.x = float(new_x)
        self.y = float(new_y)
        max_w = 512.0 if timex_screen_mode == 6 else 256.0
        half_w = max_w / 2.0
        if self.wrap_mode == "WRAP":
            self.x = ((self.x + half_w) % max_w) - half_w
            self.y = ((self.y + 96.0) % 192.0) - 96.0
        if self.pen_down:
            self.draw_turtle_line(old_x, old_y, self.x, self.y)

    def forward(self, dist):
        rad = math.radians(self.heading)
        dx = dist * math.sin(rad)
        dy = dist * math.cos(rad)
        self.set_xy(self.x + dx, self.y + dy)

    def back(self, dist):
        self.forward(-dist)

    def right(self, angle):
        self.heading = (self.heading + angle) % 360.0

    def left(self, angle):
        self.right(-angle)

    def set_heading(self, angle):
        self.heading = float(angle) % 360.0

    def draw_turtle_line(self, lx0, ly0, lx1, ly1):
        global gfx_bits, canvas_dirty, timex_screen_mode
        cx = 256.0 if timex_screen_mode == 6 else 128.0
        cy = 96.0
        sx0 = cx + lx0
        sy0 = cy + ly0
        sx1 = cx + lx1
        sy1 = cy + ly1

        x0 = int(round(sx0))
        y0 = int(round(sy0))
        x1 = int(round(sx1))
        y1 = int(round(sy1))

        dx_abs = abs(x1 - x0)
        dy_abs = abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx_abs - dy_abs
        max_w = 512 if timex_screen_mode == 6 else 256

        while True:
            if 0 <= x0 < max_w and 0 <= y0 < 192:
                if self.pen_mode == "PAINT":
                    plot_pixel(x0, y0)
                elif self.pen_mode == "ERASE":
                    unplot_pixel(x0, y0)
                elif self.pen_mode == "REVERSE":
                    if gfx_bits[x0][y0]:
                        unplot_pixel(x0, y0)
                    else:
                        plot_pixel(x0, y0)

            if x0 == x1 and y0 == y1:
                break
            e2 = 2 * err
            if e2 > -dy_abs:
                err -= dy_abs
                x0 += sx
            if e2 < dx_abs:
                err += dx_abs
                y0 += sy

        canvas_dirty = True
        memory[23677] = int(max(0, min(255, round(sx1)))) & 0xFF
        memory[23678] = int(max(0, min(191, round(sy1)))) & 0xFF

    def draw_turtle_dot(self, lx, ly):
        global gfx_bits, canvas_dirty, timex_screen_mode
        cx = 256.0 if timex_screen_mode == 6 else 128.0
        sx = int(round(cx + lx))
        sy = int(round(96.0 + ly))
        max_w = 512 if timex_screen_mode == 6 else 256
        if 0 <= sx < max_w and 0 <= sy < 192:
            if self.pen_mode == "PAINT":
                plot_pixel(sx, sy)
            elif self.pen_mode == "ERASE":
                unplot_pixel(sx, sy)
            elif self.pen_mode == "REVERSE":
                if gfx_bits[sx][sy]:
                    unplot_pixel(sx, sy)
                else:
                    plot_pixel(sx, sy)
            canvas_dirty = True

    def draw_turtle_circle(self, radius):
        global timex_screen_mode
        cx = 256.0 if timex_screen_mode == 6 else 128.0
        sx = int(round(cx + self.x))
        sy = int(round(96.0 + self.y))
        r = int(round(abs(radius)))
        if "draw_circle" in globals() and r > 0:
            draw_circle(sx, sy, r)
        else:
            step_len = (2.0 * math.pi * r) / 36.0
            for _ in range(36):
                self.forward(step_len)
                self.right(10)

    def get_var(self, name):
        name = name.upper()
        for scope in reversed(self.local_stack):
            if name in scope:
                return scope[name]
        if name in self.globals:
            return self.globals[name]
        return 0

    def set_var(self, name, val):
        name = name.upper()
        for scope in reversed(self.local_stack):
            if name in scope:
                scope[name] = val
                return
        self.globals[name] = val

    def declare_local(self, name):
        name = name.upper()
        if self.local_stack:
            self.local_stack[-1][name] = 0
        else:
            self.globals[name] = 0

    def tokenize(self, code):
        tokens = []
        i = 0
        n = len(code)
        while i < n:
            c = code[i]
            if c.isspace():
                i += 1
                continue
            if c == ';' or (code[i:i+4].upper() == 'REM ' and (i == 0 or code[i-1].isspace() or code[i-1] == ':')):
                nl = code.find('\n', i)
                if nl == -1: break
                i = nl + 1
                continue
            if c == '[':
                tokens.append(('LBRACKET', '['))
                i += 1
            elif c == ']':
                tokens.append(('RBRACKET', ']'))
                i += 1
            elif c == '(':
                tokens.append(('LPAREN', '('))
                i += 1
            elif c == ')':
                tokens.append(('RPAREN', ')'))
                i += 1
            elif c == '"':
                start = i + 1
                i += 1
                while i < n and not code[i].isspace() and code[i] not in '[]()':
                    if code[i] == '"':
                        i += 1
                        break
                    i += 1
                word_val = code[start:i].rstrip('"')
                tokens.append(('WORD', word_val))
            elif c == ':' and i + 1 < n and (code[i+1].isalpha() or code[i+1] == '_'):
                start = i + 1
                i += 1
                while i < n and (code[i].isalnum() or code[i] in '_$'):
                    i += 1
                var_name = code[start:i].upper()
                tokens.append(('VAR', var_name))
            elif c == ':':
                tokens.append(('SEP', ':'))
                i += 1
            elif c in '+-*/%^':
                if c == '-' and i + 1 < n and (code[i+1].isdigit() or code[i+1] == '.'):
                    prev_is_val = tokens and tokens[-1][0] in ('NUMBER', 'WORD', 'VAR', 'RBRACKET', 'RPAREN')
                    if not prev_is_val:
                        start = i
                        i += 1
                        while i < n and (code[i].isdigit() or code[i] == '.'):
                            i += 1
                        num_str = code[start:i]
                        val = float(num_str) if '.' in num_str else int(num_str)
                        tokens.append(('NUMBER', val))
                        continue
                tokens.append(('OPERATOR', c))
                i += 1
            elif c in '<>=':
                if code[i:i+2] in ('<=', '>=', '<>'):
                    tokens.append(('OPERATOR', code[i:i+2]))
                    i += 2
                else:
                    tokens.append(('OPERATOR', c))
                    i += 1
            elif c.isdigit() or (c == '.' and i + 1 < n and code[i+1].isdigit()):
                start = i
                while i < n and (code[i].isdigit() or code[i] == '.'):
                    i += 1
                num_str = code[start:i]
                val = float(num_str) if '.' in num_str else int(num_str)
                tokens.append(('NUMBER', val))
            elif c.isalpha() or c == '_' or c == '?' or c == '$':
                start = i
                while i < n and (code[i].isalnum() or code[i] in '_?$'):
                    i += 1
                ident = code[start:i].upper()
                tokens.append(('IDENT', ident))
            else:
                tokens.append(('SYMBOL', c))
                i += 1
        return tokens

    def group_brackets(self, tokens):
        stack = [[]]
        for tok in tokens:
            t_type, t_val = tok
            if t_type == 'LBRACKET':
                new_list = []
                stack[-1].append(('LIST', new_list))
                stack.append(new_list)
            elif t_type == 'RBRACKET':
                if len(stack) > 1:
                    stack.pop()
            elif t_type == 'SEP':
                continue
            else:
                stack[-1].append(tok)
        return stack[0]

    def eval(self, code_str):
        return self.interpret(code_str)

    def interpret(self, code_str):
        raw_tokens = self.tokenize(code_str)
        grouped = self.group_brackets(raw_tokens)
        self.execute_tokens(grouped)

    def execute_tokens(self, tokens):
        idx = 0
        n = len(tokens)

        def eval_primary():
            nonlocal idx
            if idx >= n:
                return 0
            t_type, t_val = tokens[idx]
            idx += 1
            if t_type == 'NUMBER':
                return t_val
            elif t_type == 'WORD':
                return t_val
            elif t_type == 'VAR':
                return self.get_var(t_val)
            elif t_type == 'LIST':
                return t_val
            elif t_type == 'LPAREN':
                val = eval_expr()
                if idx < n and tokens[idx][0] == 'RPAREN':
                    idx += 1
                return val
            elif t_type == 'IDENT':
                fn = t_val
                if fn == 'XCOR': return self.x
                elif fn == 'YCOR': return self.y
                elif fn == 'HEADING': return self.heading
                elif fn == 'POS': return [self.x, self.y]
                elif fn in ('PENDOWN?', 'PENDOWNP'): return self.pen_down
                elif fn in ('SHOWN?', 'SHOWNP'): return self.turtle_visible
                elif fn == 'REPCOUNT':
                    return self.repcount_stack[-1] if self.repcount_stack else 1
                elif fn == 'RANDOM':
                    max_v = int(eval_primary())
                    import random
                    return random.randint(0, max(0, max_v - 1)) if max_v > 0 else 0
                elif fn == 'ROUND': return round(float(eval_primary()))
                elif fn == 'INT': return int(float(eval_primary()))
                elif fn == 'ABS': return abs(float(eval_primary()))
                elif fn == 'SQRT': return math.sqrt(max(0.0, float(eval_primary())))
                elif fn == 'SIN': return math.sin(math.radians(float(eval_primary())))
                elif fn == 'COS': return math.cos(math.radians(float(eval_primary())))
                elif fn == 'TAN': return math.tan(math.radians(float(eval_primary())))
                elif fn == 'SUM': return eval_primary() + eval_primary()
                elif fn == 'DIFFERENCE': return eval_primary() - eval_primary()
                elif fn == 'PRODUCT': return eval_primary() * eval_primary()
                elif fn == 'QUOTIENT':
                    d = eval_primary(); return eval_primary() / (d if d != 0 else 1e-9)
                elif fn in ('REMAINDER', 'MOD'):
                    m = eval_primary(); return eval_primary() % (m if m != 0 else 1)
                elif fn == 'FIRST':
                    arg = eval_primary()
                    return arg[0] if isinstance(arg, (list, str)) and len(arg) > 0 else ""
                elif fn in ('BUTFIRST', 'BF'):
                    arg = eval_primary()
                    return arg[1:] if isinstance(arg, (list, str)) and len(arg) > 1 else ([] if isinstance(arg, list) else "")
                elif fn == 'LAST':
                    arg = eval_primary()
                    return arg[-1] if isinstance(arg, (list, str)) and len(arg) > 0 else ""
                elif fn in ('BUTLAST', 'BL'):
                    arg = eval_primary()
                    return arg[:-1] if isinstance(arg, (list, str)) and len(arg) > 1 else ([] if isinstance(arg, list) else "")
                elif fn == 'COUNT':
                    arg = eval_primary()
                    return len(arg) if isinstance(arg, (list, str)) else 0
                elif fn in ('EMPTY?', 'EMPTYP'):
                    arg = eval_primary()
                    return len(arg) == 0 if isinstance(arg, (list, str)) else False
                elif fn == 'ITEM':
                    it_idx = int(eval_primary())
                    coll = eval_primary()
                    if isinstance(coll, (list, str)) and 1 <= it_idx <= len(coll):
                        return coll[it_idx - 1]
                    return ""
                elif fn in ('WORD', 'SENTENCE', 'SE', 'LIST'):
                    a = eval_primary()
                    b = eval_primary()
                    if fn == 'WORD': return str(a) + str(b)
                    return [a, b]
                elif fn in self.procedures:
                    return self.call_procedure(fn, eval_expr)
                else:
                    return self.get_var(fn)
            return 0

        PRECEDENCE = {
            'OR': 1, 'AND': 2,
            '=': 3, '<>': 3, '<': 3, '>': 3, '<=': 3, '>=': 3,
            '+': 4, '-': 4,
            '*': 5, '/': 5, '%': 5,
            '^': 6
        }

        def eval_expr(min_prec=0):
            nonlocal idx
            left = eval_primary()
            while idx < n:
                t_type, t_val = tokens[idx]
                op = t_val.upper() if t_type in ('OPERATOR', 'IDENT') else None
                if op not in PRECEDENCE or PRECEDENCE[op] < min_prec:
                    break
                idx += 1
                next_min_prec = PRECEDENCE[op] + 1
                right = eval_expr(next_min_prec)
                if op == '+': left = left + right
                elif op == '-': left = left - right
                elif op == '*': left = left * right
                elif op == '/': left = left / right if right != 0 else 0
                elif op == '%': left = left % right if right != 0 else 0
                elif op == '^': left = left ** right
                elif op == '=': left = (left == right)
                elif op == '<>': left = (left != right)
                elif op == '<': left = (left < right)
                elif op == '>': left = (left > right)
                elif op == '<=': left = (left <= right)
                elif op == '>=': left = (left >= right)
                elif op == 'AND': left = bool(left and right)
                elif op == 'OR': left = bool(left or right)
            return left

        def fetch_list_block():
            nonlocal idx
            if idx < n:
                t_type, t_val = tokens[idx]
                if t_type == 'LIST':
                    idx += 1
                    return t_val
            return []

        def fetch_word_or_var():
            nonlocal idx
            if idx < n:
                t_type, t_val = tokens[idx]
                idx += 1
                return t_val
            return ""

        while idx < n:
            t_type, t_val = tokens[idx]
            idx += 1

            if t_type != 'IDENT':
                continue

            cmd = t_val

            if cmd == 'TO':
                if idx < n and tokens[idx][0] == 'IDENT':
                    proc_name = tokens[idx][1].upper()
                    idx += 1
                    params = []
                    while idx < n and tokens[idx][0] == 'VAR':
                        params.append(tokens[idx][1])
                        idx += 1
                    body = []
                    while idx < n:
                        if tokens[idx][0] == 'IDENT' and tokens[idx][1] == 'END':
                            idx += 1
                            break
                        body.append(tokens[idx])
                        idx += 1
                    self.procedures[proc_name] = {'params': params, 'body': body}
                continue

            elif cmd in ('END', 'END_LOGO', 'ENDLOGO', 'BYE'):
                return

            elif cmd in ('MODE', 'SETMODE'):
                m = int(eval_expr())
                pal = None
                set_timex_mode(m, pal)

            elif cmd in ('FORWARD', 'FD'):
                dist = eval_expr()
                self.forward(dist)

            elif cmd in ('BACK', 'BK'):
                dist = eval_expr()
                self.back(dist)

            elif cmd in ('RIGHT', 'RT'):
                ang = eval_expr()
                self.right(ang)

            elif cmd in ('LEFT', 'LT'):
                ang = eval_expr()
                self.left(ang)

            elif cmd == 'HOME':
                self.home()

            elif cmd == 'SETXY':
                nx = eval_expr()
                ny = eval_expr()
                self.set_xy(nx, ny)

            elif cmd == 'SETPOS':
                pos = eval_primary()
                if isinstance(pos, list) and len(pos) >= 2:
                    p0 = pos[0][1] if isinstance(pos[0], tuple) else pos[0]
                    p1 = pos[1][1] if isinstance(pos[1], tuple) else pos[1]
                    self.set_xy(p0, p1)

            elif cmd == 'SETX':
                nx = eval_expr()
                self.set_xy(nx, self.y)

            elif cmd == 'SETY':
                ny = eval_expr()
                self.set_xy(self.x, ny)

            elif cmd in ('SETHEADING', 'SETH'):
                ang = eval_expr()
                self.set_heading(ang)

            elif cmd == 'TOWARDS':
                tx = eval_expr()
                ty = eval_expr()
                dx = tx - self.x
                dy = ty - self.y
                self.heading = math.degrees(math.atan2(dx, dy)) % 360.0

            elif cmd in ('CLEARSCREEN', 'CS'):
                self.clear_screen()

            elif cmd in ('CLEARTEXT', 'CT'):
                self.clear_text()

            elif cmd == 'RESET':
                self.clear_screen()
                self.pen_down = True
                self.pen_mode = "PAINT"
                self.turtle_visible = True

            elif cmd in ('PENDOWN', 'PD'):
                self.pen_down = True
                self.pen_mode = "PAINT"

            elif cmd in ('PENUP', 'PU'):
                self.pen_down = False

            elif cmd in ('PENERASE', 'PE'):
                self.pen_down = True
                self.pen_mode = "ERASE"

            elif cmd in ('PENREVERSE', 'PX'):
                self.pen_down = True
                self.pen_mode = "REVERSE"

            elif cmd in ('SHOWTURTLE', 'ST'):
                self.turtle_visible = True

            elif cmd in ('HIDETURTLE', 'HT'):
                self.turtle_visible = False

            elif cmd == 'WRAP':
                self.wrap_mode = "WRAP"

            elif cmd == 'WINDOW':
                self.wrap_mode = "WINDOW"

            elif cmd == 'FENCE':
                self.wrap_mode = "FENCE"

            elif cmd == 'DOT':
                dx = eval_expr()
                dy = eval_expr()
                self.draw_turtle_dot(dx, dy)

            elif cmd == 'CIRCLE':
                cr = eval_expr()
                self.draw_turtle_circle(cr)

            elif cmd == 'ARC':
                arc_ang = eval_expr()
                arc_r = eval_expr()
                steps = max(4, int(abs(arc_ang) / 5))
                step_len = (2.0 * math.pi * arc_r * (arc_ang / 360.0)) / float(steps)
                step_turn = float(arc_ang) / float(steps)
                for _ in range(steps):
                    self.forward(step_len)
                    self.right(step_turn)

            elif cmd in ('INK', 'SETINK', 'SETPC', 'PC'):
                self.ink = int(eval_expr()) % 8

            elif cmd in ('PAPER', 'SETPAPER', 'SETBG', 'BG'):
                self.paper = int(eval_expr()) % 8
                if 'current_paper' in globals():
                    current_paper = self.paper

            elif cmd in ('BORDER', 'SETBORDER'):
                self.border = int(eval_expr()) % 8
                if 'current_border' in globals():
                    current_border = self.border

            elif cmd in ('BRIGHT', 'SETBRIGHT'):
                self.bright = int(eval_expr()) & 1

            elif cmd in ('FLASH', 'SETFLASH'):
                self.flash = int(eval_expr()) & 1

            elif cmd == 'REPEAT':
                count = int(eval_expr())
                body = fetch_list_block()
                for c in range(1, count + 1):
                    self.repcount_stack.append(c)
                    try:
                        self.execute_tokens(body)
                    except LogoStop:
                        self.repcount_stack.pop()
                        break
                    self.repcount_stack.pop()

            elif cmd == 'IF':
                cond = eval_expr()
                if idx < n and tokens[idx][0] == 'IDENT' and tokens[idx][1] == 'THEN':
                    idx += 1
                body = fetch_list_block()
                if cond:
                    self.execute_tokens(body)

            elif cmd == 'IFELSE':
                cond = eval_expr()
                then_b = fetch_list_block()
                else_b = fetch_list_block()
                if cond:
                    self.execute_tokens(then_b)
                else:
                    self.execute_tokens(else_b)

            elif cmd == 'TEST':
                self.last_test = bool(eval_expr())

            elif cmd in ('IFTRUE', 'IFT'):
                body = fetch_list_block()
                if self.last_test:
                    self.execute_tokens(body)

            elif cmd in ('IFFALSE', 'IFF'):
                body = fetch_list_block()
                if not self.last_test:
                    self.execute_tokens(body)

            elif cmd == 'MAKE':
                vname = fetch_word_or_var()
                val = eval_expr()
                self.set_var(vname, val)

            elif cmd == 'LOCAL':
                vname = fetch_word_or_var()
                self.declare_local(vname)

            elif cmd == 'STOP':
                raise LogoStop()

            elif cmd in ('OUTPUT', 'OP'):
                val = eval_expr()
                raise LogoOutput(val)

            elif cmd in ('PRINT', 'PR'):
                val = eval_expr()
                canvas_print(str(val))

            elif cmd == 'TYPE':
                val = eval_expr()
                if canvas_lines:
                    canvas_lines[-1] += str(val)
                else:
                    canvas_lines.append(str(val))
                canvas_dirty = True

            elif cmd == 'BEEP':
                pitch = eval_expr()
                dur = eval_expr()
                if 'play_spectrum_beep' in globals():
                    play_spectrum_beep(float(dur), float(pitch))

            elif cmd in ('WAIT', 'PAUSE'):
                dur = eval_expr()
                pygame.time.delay(int(dur * 20))

            elif cmd == 'MODE':
                m_val = int(eval_expr())
                if 'set_timex_mode' in globals():
                    set_timex_mode(m_val)

            elif cmd in self.procedures:
                self.call_procedure(cmd, eval_expr)

    def call_procedure(self, name, eval_arg_fn):
        proc = self.procedures[name]
        params = proc['params']
        args = {}
        for p in params:
            args[p] = eval_arg_fn()
        
        if self.call_depth >= self.max_call_depth:
            raise RecursionError(f"Logo maximum recursion depth ({self.max_call_depth}) exceeded")
        
        self.call_depth += 1
        self.local_stack.append(args)
        try:
            self.execute_tokens(proc['body'])
            return 0
        except LogoStop:
            return 0
        except LogoOutput as lo:
            return lo.value
        finally:
            self.local_stack.pop()
            self.call_depth -= 1


def get_logo_engine():
    global logo_engine
    if logo_engine is None:
        logo_engine = SinclairLogoEngine()
    return logo_engine


def render_logo_turtle(target_surface, blit_x, blit_y, scale_x, scale_y):
    if not logo_interactive_mode and (logo_engine is None or not logo_engine.turtle_visible):
        return
    eng = get_logo_engine()
    if not eng.turtle_visible:
        return
    cx_base = 256.0 if timex_screen_mode == 6 else 128.0
    cx = blit_x + int((cx_base + eng.x) * scale_x)
    cy = blit_y + int((191.0 - (96.0 + eng.y)) * scale_y)
    rad = math.radians(eng.heading)
    size = max(5, int(7 * scale_x))
    tip_x = cx + int(size * math.sin(rad))
    tip_y = cy - int(size * math.cos(rad))
    lb_rad = rad + math.radians(140)
    lb_x = cx + int(size * 0.8 * math.sin(lb_rad))
    lb_y = cy - int(size * 0.8 * math.cos(lb_rad))
    rb_rad = rad - math.radians(140)
    rb_x = cx + int(size * 0.8 * math.sin(rb_rad))
    rb_y = cy - int(size * 0.8 * math.cos(rb_rad))
    pts = [(tip_x, tip_y), (lb_x, lb_y), (cx, cy), (rb_x, rb_y)]
    try:
        pygame.draw.polygon(target_surface, (0, 230, 0), pts)
        pygame.draw.polygon(target_surface, (0, 80, 0), pts, 1)
    except Exception:
        pass

# ==============================================================================
# Sinclair micro-PROLOG Inference Engine (ZX Spectrum 48K/128K)
# Supports both Edinburgh/ISO Horn clauses and micro-PROLOG list syntax
# ==============================================================================

class PrologVariable:
    def __init__(self, name):
        self.name = name
    def __repr__(self):
        return self.name
    def __eq__(self, other):
        return isinstance(other, PrologVariable) and self.name == other.name
    def __hash__(self):
        return hash(self.name)

class PrologStruct:
    def __init__(self, functor, args):
        self.functor = str(functor)
        self.args = list(args)
    def __repr__(self):
        return prolog_term_to_str(self)
    def __eq__(self, other):
        return isinstance(other, PrologStruct) and self.functor == other.functor and self.args == other.args
    def __hash__(self):
        return hash((self.functor, tuple(self.args)))

PROLOG_RESERVED_WORDS = {'LIST', 'LISTING', 'KILL', 'CLEAR', 'END', 'BYE', 'QUIT', 'CAT', 'PROLOG', 'IS', 'NOT', 'MOD'}

def is_prolog_var_name(s):
    if not s: return False
    if s.upper() in PROLOG_RESERVED_WORDS: return False
    if s.startswith('_'): return True
    if s[0].isupper(): return True
    if s.lower() in ('x', 'y', 'z', 'x1', 'y1', 'z1', 'x2', 'y2', 'z2', 'who', 'what', 'which'):
        return True
    return False

def prolog_term_to_str(t):
    if isinstance(t, PrologVariable):
        return t.name
    if isinstance(t, (int, float)):
        return str(t)
    if isinstance(t, str):
        return t
    if isinstance(t, PrologStruct):
        if t.functor == '.' and len(t.args) == 2:
            items = []
            curr = t
            while isinstance(curr, PrologStruct) and curr.functor == '.' and len(curr.args) == 2:
                items.append(prolog_term_to_str(curr.args[0]))
                curr = curr.args[1]
            if curr == '[]':
                return '[' + ', '.join(items) + ']'
            return '[' + ', '.join(items) + ' | ' + prolog_term_to_str(curr) + ']'
        if not t.args:
            return t.functor
        return f"{t.functor}(" + ", ".join(prolog_term_to_str(a) for a in t.args) + ")"
    return str(t)

def prolog_to_term(x):
    if isinstance(x, (PrologVariable, PrologStruct, int, float)):
        return x
    if isinstance(x, str):
        if is_prolog_var_name(x):
            return PrologVariable(x)
        return x
    if isinstance(x, list):
        res = '[]'
        for item in reversed(x):
            res = PrologStruct('.', [prolog_to_term(item), res])
        return res
    return x

def prolog_substitute(term, subst):
    if isinstance(term, PrologVariable):
        if term.name in subst:
            return prolog_substitute(subst[term.name], subst)
        return term
    elif isinstance(term, PrologStruct):
        return PrologStruct(term.functor, [prolog_substitute(a, subst) for a in term.args])
    return term

def prolog_unify(t1, t2, subst):
    if subst is None:
        return None
    t1 = prolog_substitute(t1, subst)
    t2 = prolog_substitute(t2, subst)
    if t1 == t2:
        return subst
    if isinstance(t1, PrologVariable):
        new_sub = dict(subst)
        new_sub[t1.name] = t2
        return new_sub
    if isinstance(t2, PrologVariable):
        new_sub = dict(subst)
        new_sub[t2.name] = t1
        return new_sub
    if isinstance(t1, PrologStruct) and isinstance(t2, PrologStruct):
        if t1.functor != t2.functor or len(t1.args) != len(t2.args):
            return None
        cur = subst
        for a1, a2 in zip(t1.args, t2.args):
            cur = prolog_unify(a1, a2, cur)
            if cur is None:
                return None
        return cur
    return None

def get_prolog_term_vars(term):
    vars_set = []
    def _collect(t):
        if isinstance(t, PrologVariable):
            if t.name not in vars_set:
                vars_set.append(t.name)
        elif isinstance(t, PrologStruct):
            for a in t.args:
                _collect(a)
    _collect(term)
    return vars_set

def tokenize_prolog(code):
    tokens = []
    i = 0
    n = len(code)
    while i < n:
        c = code[i]
        if c.isspace():
            i += 1
            continue
        if c == '%' or (code[i:i+4].upper() == 'REM ' and (i == 0 or code[i-1].isspace() or code[i-1] == ':')):
            nl = code.find('\n', i)
            if nl == -1: break
            i = nl + 1
            continue
        if c == '/' and i + 1 < n and code[i+1] == '*':
            end_c = code.find('*/', i + 2)
            if end_c == -1: break
            i = end_c + 2
            continue
        if code[i:i+2] == ':-':
            tokens.append(('IF', ':-'))
            i += 2
            continue
        if code[i:i+2] == '?-':
            tokens.append(('QUERY_PROMPT', '?-'))
            i += 2
            continue
        if code[i:i+2] in ('<=', '>=', ':=', '\\=', '<>'):
            tokens.append(('OP', code[i:i+2]))
            i += 2
            continue
        if c in '()[]|,':
            tokens.append(('PUNCT', c))
            i += 1
            continue
        if c in '+-*/=<>!':
            tokens.append(('OP', c))
            i += 1
            continue
        if c == '.':
            if i + 1 < n and code[i+1].isdigit():
                start = i
                i += 1
                while i < n and code[i].isdigit(): i += 1
                tokens.append(('NUMBER', float(code[start:i])))
            else:
                tokens.append(('DOT', '.'))
                i += 1
            continue
        if c == '?':
            tokens.append(('QUERY', '?'))
            i += 1
            continue
        if c in '\'\"':
            quote = c
            start = i + 1
            i += 1
            while i < n and code[i] != quote:
                if code[i] == '\\' and i + 1 < n:
                    i += 2
                else:
                    i += 1
            val = code[start:i]
            if i < n and code[i] == quote: i += 1
            tokens.append(('ATOM', val))
            continue
        if c.isdigit():
            start = i
            while i < n and (code[i].isdigit() or code[i] == '.'):
                i += 1
            num_str = code[start:i]
            val = float(num_str) if '.' in num_str else int(num_str)
            tokens.append(('NUMBER', val))
            continue
        if c.isalnum() or c in '_-':
            start = i
            while i < n and (code[i].isalnum() or code[i] in '_-'):
                i += 1
            ident = code[start:i]
            if is_prolog_var_name(ident):
                tokens.append(('VAR', ident.upper() if len(ident) <= 2 else ident))
            else:
                tokens.append(('ATOM', ident))
            continue
        tokens.append(('SYMBOL', c))
        i += 1
    return tokens

def parse_prolog_term(tokens, idx):
    if idx >= len(tokens):
        return None, idx
    t_type, t_val = tokens[idx]
    
    if t_type == 'VAR':
        return PrologVariable(t_val), idx + 1
    
    if t_type == 'NUMBER':
        return t_val, idx + 1

    if t_type == 'PUNCT' and t_val == '[':
        idx += 1
        items = []
        tail = '[]'
        if idx < len(tokens) and tokens[idx] == ('PUNCT', ']'):
            return '[]', idx + 1
        while idx < len(tokens):
            item, idx = parse_prolog_expr(tokens, idx)
            items.append(item)
            if idx < len(tokens) and tokens[idx] == ('PUNCT', ','):
                idx += 1
            elif idx < len(tokens) and tokens[idx] == ('PUNCT', '|'):
                idx += 1
                tail, idx = parse_prolog_expr(tokens, idx)
                if idx < len(tokens) and tokens[idx] == ('PUNCT', ']'):
                    idx += 1
                break
            elif idx < len(tokens) and tokens[idx] == ('PUNCT', ']'):
                idx += 1
                break
            else:
                break
        res = tail
        for it in reversed(items):
            res = PrologStruct('.', [it, res])
        return res, idx

    if t_type == 'PUNCT' and t_val == '(':
        idx += 1
        elements = []
        while idx < len(tokens) and tokens[idx] != ('PUNCT', ')'):
            el, idx = parse_prolog_expr(tokens, idx)
            elements.append(el)
            if idx < len(tokens) and tokens[idx] == ('PUNCT', ','):
                idx += 1
        if idx < len(tokens) and tokens[idx] == ('PUNCT', ')'):
            idx += 1
        if not elements:
            return '()', idx
        if len(elements) == 1:
            return elements[0], idx
        first = elements[0]
        if isinstance(first, str):
            return PrologStruct(first, elements[1:]), idx
        return elements, idx

    if t_type in ('ATOM', 'OP'):
        functor = t_val
        idx += 1
        if idx < len(tokens) and tokens[idx] == ('PUNCT', '('):
            idx += 1
            args = []
            if idx < len(tokens) and tokens[idx] == ('PUNCT', ')'):
                idx += 1
                return PrologStruct(functor, []), idx
            while idx < len(tokens):
                arg, idx = parse_prolog_expr(tokens, idx)
                args.append(arg)
                if idx < len(tokens) and tokens[idx] == ('PUNCT', ','):
                    idx += 1
                elif idx < len(tokens) and tokens[idx] == ('PUNCT', ')'):
                    idx += 1
                    break
                else:
                    break
            return PrologStruct(functor, args), idx
        return functor, idx

    return t_val, idx + 1

PROLOG_INFIX_OPS = {
    ':=': 10,
    'is': 10,
    '=': 10,
    '\\=': 10,
    '<>': 10,
    '<': 10,
    '>': 10,
    '<=': 10,
    '=<': 10,
    '>=': 10,
    '+': 20,
    '-': 20,
    '*': 30,
    '/': 30,
    'mod': 30,
}

def parse_prolog_expr(tokens, idx, min_prec=0):
    left, idx = parse_prolog_term(tokens, idx)
    if left is None:
        return None, idx
    while idx < len(tokens):
        t_type, t_val = tokens[idx]
        op = str(t_val)
        op_lower = op.lower()
        prec = PROLOG_INFIX_OPS.get(op) or PROLOG_INFIX_OPS.get(op_lower)
        if prec is None or prec < min_prec:
            break
        idx += 1
        right, idx = parse_prolog_expr(tokens, idx, prec + 1)
        left = PrologStruct(op_lower if op_lower in ('is', 'mod') else op, [left, right])
    return left, idx

def parse_prolog_sentences(tokens):
    sentences = []
    idx = 0
    n = len(tokens)
    while idx < n:
        if tokens[idx] == ('DOT', '.'):
            idx += 1
            continue

        if tokens[idx] in (('QUERY_PROMPT', '?-'), ('QUERY', '?')):
            idx += 1
            goals = []
            while idx < n and tokens[idx] != ('DOT', '.'):
                term, idx = parse_prolog_expr(tokens, idx)
                if isinstance(term, PrologStruct):
                    goals.append(term)
                elif isinstance(term, list):
                    for g in term:
                        goals.append(g if isinstance(g, PrologStruct) else PrologStruct(g[0], g[1:]))
                elif term:
                    goals.append(term)
                if idx < n and tokens[idx] == ('PUNCT', ','):
                    idx += 1
                else:
                    break
            if idx < n and tokens[idx] == ('DOT', '.'):
                idx += 1
            sentences.append(('QUERY', goals))
            continue

        if tokens[idx] == ('PUNCT', '(') and idx + 1 < n and tokens[idx+1] == ('PUNCT', '('):
            term, idx = parse_prolog_expr(tokens, idx)
            if isinstance(term, PrologStruct):
                sentences.append(('CLAUSE', term, []))
                continue
            elif isinstance(term, list) and len(term) > 0:
                head = term[0] if isinstance(term[0], PrologStruct) else PrologStruct(term[0][0], term[0][1:])
                body = [b if isinstance(b, PrologStruct) else PrologStruct(b[0], b[1:]) for b in term[1:]]
                sentences.append(('CLAUSE', head, body))
                continue

        t_type, t_val = tokens[idx]
        cmd_upper = str(t_val).upper()
        if cmd_upper in ('LIST', 'LISTING', 'CAT'):
            sentences.append(('COMMAND', 'LIST'))
            idx += 1
            if idx < n and tokens[idx] == ('DOT', '.'): idx += 1
            continue
        elif cmd_upper in ('KILL', 'CLEAR'):
            sentences.append(('COMMAND', 'KILL'))
            idx += 1
            if idx < n and tokens[idx] == ('DOT', '.'): idx += 1
            continue
        elif cmd_upper in ('END', 'BYE', 'QUIT') or (cmd_upper == 'END' and idx + 1 < n and str(tokens[idx+1][1]).upper() == 'PROLOG'):
            sentences.append(('COMMAND', 'END'))
            idx += 1
            if idx < n and str(tokens[idx][1]).upper() == 'PROLOG': idx += 1
            if idx < n and tokens[idx] == ('DOT', '.'): idx += 1
            continue

        head, idx = parse_prolog_expr(tokens, idx)
        if head is None:
            break

        body = []
        if idx < n and tokens[idx] == ('IF', ':-'):
            idx += 1
            while idx < n and tokens[idx] != ('DOT', '.'):
                b_term, idx = parse_prolog_expr(tokens, idx)
                if b_term:
                    body.append(b_term)
                if idx < n and tokens[idx] == ('PUNCT', ','):
                    idx += 1
                else:
                    break
        elif idx < n and tokens[idx] == ('QUERY', '?'):
            idx += 1
            sentences.append(('QUERY', [head]))
            continue

        if idx < n and tokens[idx] == ('DOT', '.'):
            idx += 1

        sentences.append(('CLAUSE', head, body))

    return sentences

class SinclairPrologEngine:
    def __init__(self):
        self.clauses = []
        self.var_counter = 0
        self.output_lines = []
        self._print_fn = None

    def clear(self):
        self.clauses.clear()
        self.output_lines.clear()

    def add_clause(self, head, body=None):
        head_term = prolog_to_term(head)
        body_terms = [prolog_to_term(b) for b in (body or [])]
        self.clauses.append((head_term, body_terms))

    def rename_vars(self, term, suffix):
        if isinstance(term, PrologVariable):
            return PrologVariable(f"{term.name}_{suffix}")
        if isinstance(term, PrologStruct):
            return PrologStruct(term.functor, [self.rename_vars(a, suffix) for a in term.args])
        return term

    def solve(self, goals):
        goals = [prolog_to_term(g) for g in goals]
        yield from self._solve_goals(goals, {})

    def _solve_goals(self, goals, subst):
        if not goals:
            yield subst
            return

        g = prolog_substitute(goals[0], subst)
        rest = goals[1:]

        if isinstance(g, PrologStruct):
            if g.functor == '=' and len(g.args) == 2:
                s = prolog_unify(g.args[0], g.args[1], subst)
                if s is not None:
                    yield from self._solve_goals(rest, s)
                return

            if g.functor in ('\\=', '<>') and len(g.args) == 2:
                s = prolog_unify(g.args[0], g.args[1], subst)
                if s is None:
                    yield from self._solve_goals(rest, subst)
                return

            if g.functor == 'true':
                yield from self._solve_goals(rest, subst)
                return

            if g.functor == 'fail':
                return

            if g.functor in ('write', 'print', 'pr') and len(g.args) == 1:
                val = prolog_substitute(g.args[0], subst)
                out = prolog_term_to_str(val)
                self.output_lines.append(out)
                if self._print_fn: self._print_fn(out)
                yield from self._solve_goals(rest, subst)
                return

            if g.functor == 'nl':
                self.output_lines.append("")
                if self._print_fn: self._print_fn("")
                yield from self._solve_goals(rest, subst)
                return

            if g.functor == 'is' and len(g.args) == 2:
                var_target = g.args[0]
                expr = prolog_substitute(g.args[1], subst)
                eval_val = self.eval_math(expr)
                s = prolog_unify(var_target, eval_val, subst)
                if s is not None:
                    yield from self._solve_goals(rest, s)
                return

            if g.functor in ('<', '>', '=<', '<=', '>=') and len(g.args) == 2:
                v1 = self.eval_math(prolog_substitute(g.args[0], subst))
                v2 = self.eval_math(prolog_substitute(g.args[1], subst))
                op = g.functor
                ok = False
                if op == '<': ok = (v1 < v2)
                elif op == '>': ok = (v1 > v2)
                elif op in ('=<', '<='): ok = (v1 <= v2)
                elif op == '>=': ok = (v1 >= v2)
                if ok:
                    yield from self._solve_goals(rest, subst)
                return

            if g.functor in ('not', '\\+') and len(g.args) == 1:
                inner_goals = [g.args[0]]
                has_sol = False
                for _ in self._solve_goals(inner_goals, subst):
                    has_sol = True
                    break
                if not has_sol:
                    yield from self._solve_goals(rest, subst)
                return

        # User clauses
        self.var_counter += 1
        suffix = self.var_counter
        for head, body in self.clauses:
            r_head = self.rename_vars(head, suffix)
            r_body = [self.rename_vars(b, suffix) for b in body]
            s = prolog_unify(g, r_head, subst)
            if s is not None:
                yield from self._solve_goals(r_body + rest, s)

    def eval_math(self, term):
        if isinstance(term, (int, float)):
            return term
        if isinstance(term, PrologStruct):
            if term.functor == '+' and len(term.args) == 2:
                return self.eval_math(term.args[0]) + self.eval_math(term.args[1])
            elif term.functor == '-' and len(term.args) == 2:
                return self.eval_math(term.args[0]) - self.eval_math(term.args[1])
            elif term.functor == '*' and len(term.args) == 2:
                return self.eval_math(term.args[0]) * self.eval_math(term.args[1])
            elif term.functor == '/' and len(term.args) == 2:
                d = self.eval_math(term.args[1])
                return self.eval_math(term.args[0]) / (d if d != 0 else 1e-9)
            elif term.functor == 'mod' and len(term.args) == 2:
                return self.eval_math(term.args[0]) % self.eval_math(term.args[1])
        return 0

    def interpret(self, code_str, print_fn=None):
        self._print_fn = print_fn
        def _emit(text):
            self.output_lines.append(text)
            if print_fn:
                print_fn(text)

        tokens = tokenize_prolog(code_str)
        sentences = parse_prolog_sentences(tokens)
        for s in sentences:
            stype = s[0]
            if stype == 'COMMAND':
                cmd = s[1]
                if cmd == 'LIST':
                    if not self.clauses:
                        _emit("No clauses.")
                    else:
                        for h, b in self.clauses:
                            if b:
                                _emit(f"{prolog_term_to_str(h)} :- " + ", ".join(prolog_term_to_str(x) for x in b) + ".")
                            else:
                                _emit(f"{prolog_term_to_str(h)}.")
                elif cmd == 'KILL':
                    self.clauses.clear()
                    _emit("All clauses killed.")
            elif stype == 'CLAUSE':
                head = s[1]
                body = s[2]
                self.add_clause(head, body)
            elif stype == 'QUERY':
                goals = s[1]
                q_vars = []
                for g in goals:
                    for v in get_prolog_term_vars(g):
                        if v not in q_vars:
                            q_vars.append(v)
                solutions = []
                for sol in self.solve(goals):
                    solutions.append(sol)
                    if len(solutions) >= 50:
                        break
                if solutions:
                    if q_vars:
                        for sol in solutions:
                            parts = [f"{v} = {prolog_term_to_str(prolog_substitute(PrologVariable(v), sol))}" for v in q_vars]
                            _emit(", ".join(parts))
                    _emit("YES")
                else:
                    _emit("NO")

def get_prolog_engine():
    global prolog_engine
    if prolog_engine is None:
        prolog_engine = SinclairPrologEngine()
    return prolog_engine


