# ==============================================================================
# Sinclair ZEUS Z80 Assembler Prototype
# ==============================================================================

REG8 = {"B": 0, "C": 1, "D": 2, "E": 3, "H": 4, "L": 5, "(HL)": 6, "A": 7}
REG16_SP = {"BC": 0, "DE": 1, "HL": 2, "SP": 3}
REG16_AF = {"BC": 0, "DE": 1, "HL": 2, "AF": 3}
COND_CC = {"NZ": 0, "Z": 1, "NC": 2, "C": 3, "PO": 4, "PE": 5, "P": 6, "M": 7}
COND_JR = {"NZ": 0, "Z": 1, "NC": 2, "C": 3}
RST_VECTORS = {0: 0x00, 0x08: 0x08, 8: 0x08, 0x10: 0x10, 16: 0x10, 0x18: 0x18, 24: 0x18,
               0x20: 0x20, 32: 0x20, 0x28: 0x28, 40: 0x28, 0x30: 0x30, 48: 0x30, 0x38: 0x38, 56: 0x38}

class AssemblerError(Exception):
    pass

class SinclairZeusAssembler:
    def __init__(self):
        self.symbols = {}
        self.code_bytes = bytearray()
        self.org_address = 0x8000
        self.current_pc = 0x8000
        self.listing = [] # list of (addr, bytes, source_line)
        self.errors = []

    def eval_expr(self, expr, pass_num=1):
        expr = expr.strip()
        if not expr:
            return 0
        if expr == "$":
            return self.current_pc
        # Number formats:
        # Hex: #8000, 0x8000, $8000, &H8000, 8000H
        if expr.startswith("#"):
            try: return int(expr[1:], 16)
            except ValueError: pass
        if expr.startswith("$") and len(expr) > 1:
            try: return int(expr[1:], 16)
            except ValueError: pass
        if expr.upper().startswith("&H"):
            try: return int(expr[2:], 16)
            except ValueError: pass
        if expr.lower().startswith("0x"):
            try: return int(expr[2:], 16)
            except ValueError: pass
        if expr.upper().endswith("H") and len(expr) > 1 and expr[0].isdigit():
            try: return int(expr[:-1], 16)
            except ValueError: pass
        # Binary: %1010, 1010B
        if expr.startswith("%"):
            try: return int(expr[1:], 2)
            except ValueError: pass
        if expr.upper().endswith("B") and len(expr) > 1 and all(c in '01' for c in expr[:-1]):
            try: return int(expr[:-1], 2)
            except ValueError: pass
        # Character literal: 'A' or "A"
        if (expr.startswith("'") and expr.endswith("'")) or (expr.startswith('"') and expr.endswith('"')):
            inner = expr[1:-1]
            if len(inner) == 1:
                return ord(inner)
        # Decimal
        if re.match(r"^-?\d+$", expr):
            return int(expr)
        # Check symbol
        sym_upper = expr.upper()
        if sym_upper in self.symbols:
            return self.symbols[sym_upper]
        
        # Arithmetic expression (e.g. label + 5, label - 2, $ + 4)
        m_op = re.search(r"[\+\-\*\/]", expr)
        if m_op:
            op = m_op.group(0)
            parts = expr.split(op, 1)
            left = self.eval_expr(parts[0], pass_num)
            right = self.eval_expr(parts[1], pass_num)
            if op == '+': return left + right
            elif op == '-': return left - right
            elif op == '*': return left * right
            elif op == '/': return left // (right if right != 0 else 1)

        if pass_num == 1:
            return 0  # placeholder during pass 1 for forward references
        raise AssemblerError(f"Undefined symbol or invalid expression: '{expr}'")

    def parse_line(self, line):
        # Strip comments
        sem_idx = line.find(";")
        if sem_idx != -1:
            line = line[:sem_idx]
        line = line.strip()
        if not line:
            return None, None, []

        # Check for leading Zeus line number (e.g. "10 LD A, 2")
        m_ln = re.match(r"^(\d+)\s+(.*)$", line)
        if m_ln:
            line = m_ln.group(2).strip()

        label = None
        instruction = None
        operands = []

        # Check if line starts with label (ending with : or whitespace)
        tokens = line.split(None, 1)
        first = tokens[0]
        first_upper = first.upper()

        KNOWN_MNEMONICS = {
            "ORG", "ADDRESS", "EQU", "DEFB", "DB", "DEFW", "DW", "DEFS", "DS", "DEFM", "DM", "ENT", "END", "INCLUDE",
            "LD", "PUSH", "POP", "EX", "EXX", "ADD", "ADC", "SUB", "SBC", "AND", "XOR", "OR", "CP",
            "INC", "DEC", "DAA", "CPL", "NEG", "CCF", "SCF", "NOP", "HALT", "DI", "EI", "IM",
            "RLCA", "RRCA", "RLA", "RRA", "RLC", "RRC", "RL", "RR", "SLA", "SRA", "SRL", "RLD", "RRD",
            "BIT", "SET", "RES", "JP", "JR", "CALL", "RET", "RETI", "RETN", "RST", "IN", "OUT",
            "LDI", "LDIR", "CPI", "CPIR", "INI", "INIR", "OUTI", "OTIR", "DJNZ"
        }

        if first.endswith(":"):
            label = first[:-1]
            rest = tokens[1].strip() if len(tokens) > 1 else ""
        elif first_upper not in KNOWN_MNEMONICS:
            # If not a known mnemonic, treat as label
            label = first
            rest = tokens[1].strip() if len(tokens) > 1 else ""
        else:
            rest = line

        if rest:
            parts = rest.split(None, 1)
            instruction = parts[0].upper()
            if len(parts) > 1:
                # Split operands by comma (preserving commas inside quotes or parens)
                raw_ops = parts[1].strip()
                ops = []
                cur = []
                in_q = False
                q_char = None
                p_level = 0
                for ch in raw_ops:
                    if ch in ('"', "'"):
                        if in_q and ch == q_char: in_q = False
                        elif not in_q: in_q = True; q_char = ch
                        cur.append(ch)
                    elif not in_q:
                        if ch == '(': p_level += 1
                        elif ch == ')': p_level -= 1
                        if ch == ',' and p_level == 0:
                            ops.append("".join(cur).strip())
                            cur = []
                            continue
                        cur.append(ch)
                    else:
                        cur.append(ch)
                if cur:
                    ops.append("".join(cur).strip())
                operands = ops

        return label, instruction, operands

    def assemble(self, source_text, target_memory=None):
        raw_lines = source_text.splitlines()
        lines = []
        for rl in raw_lines:
            parts = []
            curr = []
            in_q = False
            q_char = None
            for ch in rl:
                if ch in ('"', "'"):
                    if not in_q:
                        in_q = True
                        q_char = ch
                    elif ch == q_char:
                        in_q = False
                    curr.append(ch)
                elif ch == ':' and not in_q:
                    parts.append("".join(curr).strip())
                    curr = []
                else:
                    curr.append(ch)
            if curr:
                parts.append("".join(curr).strip())
            for p in parts:
                if p:
                    lines.append(p)

        self.symbols.clear()
        self.errors.clear()
        self.listing.clear()
        self.org_address = 0x8000
        self.includes_sprites = False
        self.includes_tilemap = False

        # Pass 1: Gather labels and compute addresses
        self.current_pc = self.org_address
        for line in lines:
            label, instr, ops = self.parse_line(line)
            if instr in ("ORG", "ADDRESS") and ops:
                self.org_address = self.eval_expr(ops[0], pass_num=1)
                self.current_pc = self.org_address
            if instr == "INCLUDE" and ops:
                for op in ops:
                    op_u = op.upper().strip('"\' ')
                    if "SPRITE" in op_u:
                        self.includes_sprites = True
                        sp_base = DEFAULT_SPRITE_ENGINE_BASE if 'DEFAULT_SPRITE_ENGINE_BASE' in globals() else 50000
                        self.symbols["SP_BASE"] = sp_base
                        self.symbols["SP_INIT"] = sp_base + 0
                        self.symbols["SP_UPDATE"] = sp_base + 3
                        self.symbols["SP_DRAW"] = sp_base + 6
                        self.symbols["SP_STEP"] = sp_base + 9
                        self.symbols["SP_SET_ATTR"] = sp_base + 12
                        self.symbols["SP_GET_ATTR"] = sp_base + 15
                        self.symbols["SP_DEF_SPRITE"] = sp_base + 18
                        self.symbols["SP_CLEAR_ALL"] = sp_base + 21
                        self.symbols["SP_ACTIVE_TABLE"] = sp_base + 40
                        self.symbols["SP_COLLISION_TABLE"] = sp_base + 552
                        self.symbols["SP_PARAM_BLOCK"] = sp_base + 568
                        self.symbols["SP_RESTORE_BUFFERS"] = sp_base + 600
                        self.symbols["SP_DEFS"] = sp_base + 3072
                        self.symbols["SLOT_SIZE"] = 32
                        self.symbols["SLOT_STATUS"] = 0
                        self.symbols["SLOT_DEF_ID"] = 1
                        self.symbols["SLOT_X"] = 2
                        self.symbols["SLOT_Y"] = 3
                        self.symbols["SLOT_INK"] = 7
                        self.symbols["SLOT_FRAME"] = 10
                        self.symbols["SLOT_DIR"] = 13
                        self.symbols["SLOT_PATH_MODE"] = 14
                        self.symbols["SLOT_SPEED"] = 15
                        self.symbols["SLOT_PATH_PARAM"] = 18
                        self.symbols["SLOT_REBOUND"] = 20
                        self.symbols["SLOT_COLLISION"] = 23
                    if "TILE" in op_u:
                        self.includes_tilemap = True
                        tl_base = DEFAULT_TILE_ENGINE_BASE if 'DEFAULT_TILE_ENGINE_BASE' in globals() else 45000
                        self.symbols["TL_BASE"] = tl_base
                        self.symbols["TL_PLACE"] = tl_base + 0
                        self.symbols["TL_CLEAR"] = tl_base + 3
                        self.symbols["TL_ROW"] = tl_base + 6
                        self.symbols["TL_COL"] = tl_base + 7
                        self.symbols["TL_TILE_ADDR"] = tl_base + 8
                        self.symbols["TL_ATTR"] = tl_base + 10
                        self.symbols["TL_FLAGS"] = tl_base + 11
                        self.symbols["TL_TILEMAP_BASE"] = tl_base + 12
                        self.symbols["TL_NUM_TILES"] = tl_base + 14
                        self.symbols["TL_MAP_DATA"] = 40000
                        self.symbols["TL_FLAG_OVER"] = 1
                        self.symbols["TL_FLAG_INVERSE"] = 2
                        self.symbols["TL_FLAG_NO_ATTR"] = 4
                        self.symbols["TL_FLAG_PACKED"] = 8
            if label:
                if instr == "EQU" and ops:
                    val = self.eval_expr(ops[0], pass_num=1)
                    self.symbols[label.upper()] = val
                    continue
                else:
                    self.symbols[label.upper()] = self.current_pc

            if instr and instr not in ("EQU", "ORG", "ADDRESS", "INCLUDE"):
                try:
                    b = self.encode_instruction(instr, ops, pass_num=1)
                    self.current_pc += len(b)
                except Exception as e:
                    self.current_pc += 1  # estimate

        # Pass 2: Generate code bytes
        self.current_pc = self.org_address
        self.code_bytes = bytearray()
        for raw_line in lines:
            label, instr, ops = self.parse_line(raw_line)
            line_pc = self.current_pc
            instr_bytes = bytearray()

            if instr in ("ORG", "ADDRESS") and ops:
                self.org_address = self.eval_expr(ops[0], pass_num=2)
                self.current_pc = self.org_address
                line_pc = self.current_pc

            if instr and instr not in ("EQU", "ORG", "ADDRESS", "INCLUDE"):
                try:
                    instr_bytes = self.encode_instruction(instr, ops, pass_num=2)
                    self.code_bytes.extend(instr_bytes)
                    self.current_pc += len(instr_bytes)
                except Exception as e:
                    self.errors.append((raw_line, str(e)))

            self.listing.append((line_pc, bytes(instr_bytes), raw_line))

        if target_memory is not None:
            for i, b in enumerate(self.code_bytes):
                target_memory[(self.org_address + i) & 0xFFFF] = b

        return bytes(self.code_bytes)

    def encode_instruction(self, mnem, ops, pass_num):
        # 1. Directives
        if mnem in ("DEFB", "DB"):
            res = bytearray()
            for op in ops:
                if (op.startswith('"') and op.endswith('"')) or (op.startswith("'") and op.endswith("'")):
                    res.extend(op[1:-1].encode('ascii', errors='replace'))
                else:
                    val = self.eval_expr(op, pass_num) & 0xFF
                    res.append(val)
            return bytes(res)

        if mnem in ("DEFW", "DW"):
            res = bytearray()
            for op in ops:
                val = self.eval_expr(op, pass_num) & 0xFFFF
                res.extend(struct.pack("<H", val))
            return bytes(res)

        if mnem in ("DEFS", "DS"):
            count = self.eval_expr(ops[0], pass_num) if ops else 0
            val = self.eval_expr(ops[1], pass_num) & 0xFF if len(ops) > 1 else 0
            return bytes([val] * count)

        if mnem in ("DEFM", "DM"):
            res = bytearray()
            for op in ops:
                if (op.startswith('"') and op.endswith('"')) or (op.startswith("'") and op.endswith("'")):
                    res.extend(op[1:-1].encode('ascii', errors='replace'))
                else:
                    res.extend(op.encode('ascii', errors='replace'))
            return bytes(res)

        if mnem in ("ENT", "END", "ORG", "ADDRESS", "EQU", "INCLUDE"):
            return b""

        # 2. Simple 1-byte opcodes
        SIMPLE = {
            "NOP": 0x00, "RLCA": 0x07, "RRCA": 0x0F, "RLA": 0x17, "RRA": 0x1F,
            "DAA": 0x27, "CPL": 0x2F, "SCF": 0x37, "CCF": 0x3F, "HALT": 0x76,
            "EXX": 0xD9, "DI": 0xF3, "EI": 0xFB
        }
        if mnem in SIMPLE:
            return bytes([SIMPLE[mnem]])

        # 3. Simple 2-byte ED opcodes
        SIMPLE_ED = {
            "NEG": 0x44, "RETN": 0x45, "RETI": 0x4D, "RRD": 0x67, "RLD": 0x6F,
            "LDI": 0xA0, "CPI": 0xA1, "INI": 0xA2, "OUTI": 0xA3,
            "LDD": 0xA8, "CPD": 0xA9, "IND": 0xAA, "OUTD": 0xAB,
            "LDIR": 0xB0, "CPIR": 0xB1, "INIR": 0xB2, "OTIR": 0xB3,
            "LDDR": 0xB8, "CPDR": 0xB9, "INDR": 0xBA, "OTDR": 0xBB
        }
        if mnem in SIMPLE_ED:
            return bytes([0xED, SIMPLE_ED[mnem]])

        # 4. RET
        if mnem == "RET":
            if not ops:
                return b"\xC9"
            cc = ops[0].upper()
            if cc in COND_CC:
                return bytes([0xC0 | (COND_CC[cc] << 3)])
            raise AssemblerError(f"Invalid condition for RET: {cc}")

        # 5. RST
        if mnem == "RST":
            p = self.eval_expr(ops[0], pass_num)
            if p in RST_VECTORS:
                vec = RST_VECTORS[p]
                return bytes([0xC7 | vec])
            raise AssemblerError(f"Invalid restart vector for RST: {p}")

        # 6. IM
        if mnem == "IM":
            m = self.eval_expr(ops[0], pass_num)
            if m == 0: return b"\xED\x46"
            if m == 1: return b"\xED\x56"
            if m == 2: return b"\xED\x5E"
            raise AssemblerError(f"Invalid interrupt mode for IM: {m}")

        # 7. DJNZ and JR
        if mnem == "DJNZ":
            target = self.eval_expr(ops[0], pass_num)
            disp = target - (self.current_pc + 2)
            if pass_num == 2 and not (-128 <= disp <= 127):
                raise AssemblerError(f"DJNZ displacement out of range: {disp}")
            return bytes([0x10, disp & 0xFF])

        if mnem == "JR":
            if len(ops) == 1:
                target = self.eval_expr(ops[0], pass_num)
                disp = target - (self.current_pc + 2)
                if pass_num == 2 and not (-128 <= disp <= 127):
                    raise AssemblerError(f"JR displacement out of range: {disp}")
                return bytes([0x18, disp & 0xFF])
            elif len(ops) == 2:
                cc = ops[0].upper()
                target = self.eval_expr(ops[1], pass_num)
                disp = target - (self.current_pc + 2)
                if cc in COND_JR:
                    if pass_num == 2 and not (-128 <= disp <= 127):
                        raise AssemblerError(f"JR {cc} displacement out of range: {disp}")
                    return bytes([0x20 | (COND_JR[cc] << 3), disp & 0xFF])
                raise AssemblerError(f"Invalid condition for JR: {cc}")

        # 8. JP
        if mnem == "JP":
            if len(ops) == 1:
                op0 = ops[0].upper()
                if op0 == "(HL)": return b"\xE9"
                if op0 == "(IX)": return b"\xDD\xE9"
                if op0 == "(IY)": return b"\xFD\xE9"
                target = self.eval_expr(ops[0], pass_num) & 0xFFFF
                return bytes([0xC3, target & 0xFF, (target >> 8) & 0xFF])
            elif len(ops) == 2:
                cc = ops[0].upper()
                target = self.eval_expr(ops[1], pass_num) & 0xFFFF
                if cc in COND_CC:
                    return bytes([0xC2 | (COND_CC[cc] << 3), target & 0xFF, (target >> 8) & 0xFF])
                raise AssemblerError(f"Invalid condition for JP: {cc}")

        # 9. CALL
        if mnem == "CALL":
            if len(ops) == 1:
                target = self.eval_expr(ops[0], pass_num) & 0xFFFF
                return bytes([0xCD, target & 0xFF, (target >> 8) & 0xFF])
            elif len(ops) == 2:
                cc = ops[0].upper()
                target = self.eval_expr(ops[1], pass_num) & 0xFFFF
                if cc in COND_CC:
                    return bytes([0xC4 | (COND_CC[cc] << 3), target & 0xFF, (target >> 8) & 0xFF])
                raise AssemblerError(f"Invalid condition for CALL: {cc}")

        # 10. PUSH / POP
        if mnem == "PUSH":
            r = ops[0].upper()
            if r == "IX": return b"\xDD\xE5"
            if r == "IY": return b"\xFD\xE5"
            if r in REG16_AF:
                return bytes([0xC5 | (REG16_AF[r] << 4)])
            raise AssemblerError(f"Invalid register for PUSH: {r}")

        if mnem == "POP":
            r = ops[0].upper()
            if r == "IX": return b"\xDD\xE1"
            if r == "IY": return b"\xFD\xE1"
            if r in REG16_AF:
                return bytes([0xC1 | (REG16_AF[r] << 4)])
            raise AssemblerError(f"Invalid register for POP: {r}")

        # 11. EX
        if mnem == "EX":
            op0 = ops[0].upper()
            op1 = ops[1].upper()
            if op0 == "DE" and op1 == "HL": return b"\xEB"
            if op0 == "AF" and op1 in ("AF'", "AF`"): return b"\x08"
            if op0 == "(SP)":
                if op1 == "HL": return b"\xE3"
                if op1 == "IX": return b"\xDD\xE3"
                if op1 == "IY": return b"\xFD\xE3"
            raise AssemblerError(f"Invalid operands for EX: {op0}, {op1}")

        # 12. INC / DEC
        if mnem in ("INC", "DEC"):
            is_dec = (mnem == "DEC")
            op = ops[0].upper()
            # 8-bit reg
            if op in REG8:
                base = 0x05 if is_dec else 0x04
                return bytes([base | (REG8[op] << 3)])
            # 16-bit reg
            if op in REG16_SP:
                base = 0x0B if is_dec else 0x03
                return bytes([base | (REG16_SP[op] << 4)])
            if op == "IX": return bytes([0xDD, 0x2B if is_dec else 0x23])
            if op == "IY": return bytes([0xFD, 0x2B if is_dec else 0x23])
            # (IX+d), (IY+d)
            m_ix = self.parse_indexed(op, pass_num)
            if m_ix:
                prefix, disp = m_ix
                return bytes([prefix, 0x35 if is_dec else 0x34, disp])
            raise AssemblerError(f"Invalid operand for {mnem}: {op}")

        # 13. ADD / ADC / SBC
        if mnem in ("ADD", "ADC", "SBC"):
            op0 = ops[0].upper() if len(ops) > 1 else "A"
            op1 = ops[1] if len(ops) > 1 else ops[0]
            op1_upper = op1.upper()
            # 16-bit ADD HL, rr
            if mnem == "ADD" and op0 == "HL" and op1_upper in REG16_SP:
                return bytes([0x09 | (REG16_SP[op1_upper] << 4)])
            if mnem == "ADD" and op0 == "IX" and op1_upper in ("BC", "DE", "IX", "SP"):
                code = {"BC": 0x09, "DE": 0x19, "IX": 0x29, "SP": 0x39}[op1_upper]
                return bytes([0xDD, code])
            if mnem == "ADD" and op0 == "IY" and op1_upper in ("BC", "DE", "IY", "SP"):
                code = {"BC": 0x09, "DE": 0x19, "IY": 0x29, "SP": 0x39}[op1_upper]
                return bytes([0xFD, code])
            # 16-bit ADC HL, rr / SBC HL, rr
            if mnem in ("ADC", "SBC") and op0 == "HL" and op1_upper in REG16_SP:
                base = 0x4A if mnem == "ADC" else 0x42
                return bytes([0xED, base | (REG16_SP[op1_upper] << 4)])
            # 8-bit ALU operations on A
            alu_code = {"ADD": 0, "ADC": 1, "SBC": 3}[mnem]
            if op0 == "A":
                if op1_upper in REG8:
                    return bytes([0x80 | (alu_code << 3) | REG8[op1_upper]])
                m_ix = self.parse_indexed(op1_upper, pass_num)
                if m_ix:
                    prefix, disp = m_ix
                    return bytes([prefix, 0x80 | (alu_code << 3) | 6, disp])
                # Immediate
                val = self.eval_expr(op1, pass_num) & 0xFF
                return bytes([0xC6 | (alu_code << 3), val])

        # 14. SUB / AND / XOR / OR / CP
        if mnem in ("SUB", "AND", "XOR", "OR", "CP"):
            alu_code = {"SUB": 2, "AND": 4, "XOR": 5, "OR": 6, "CP": 7}[mnem]
            # operand might be (A, r) or just r
            op_str = ops[1] if len(ops) > 1 and ops[0].upper() == "A" else ops[0]
            op_upper = op_str.upper()
            if op_upper in REG8:
                return bytes([0x80 | (alu_code << 3) | REG8[op_upper]])
            m_ix = self.parse_indexed(op_upper, pass_num)
            if m_ix:
                prefix, disp = m_ix
                return bytes([prefix, 0x80 | (alu_code << 3) | 6, disp])
            # Immediate
            val = self.eval_expr(op_str, pass_num) & 0xFF
            return bytes([0xC6 | (alu_code << 3), val])

        # 15. BIT / SET / RES
        if mnem in ("BIT", "SET", "RES"):
            bit_val = self.eval_expr(ops[0], pass_num)
            if not (0 <= bit_val <= 7):
                raise AssemblerError(f"Bit index must be 0-7: {bit_val}")
            op1_upper = ops[1].upper()
            base_code = {"BIT": 0x40, "RES": 0x80, "SET": 0xC0}[mnem]
            if op1_upper in REG8:
                return bytes([0xCB, base_code | (bit_val << 3) | REG8[op1_upper]])
            m_ix = self.parse_indexed(op1_upper, pass_num)
            if m_ix:
                prefix, disp = m_ix
                return bytes([prefix, 0xCB, disp, base_code | (bit_val << 3) | 6])
            raise AssemblerError(f"Invalid operand for {mnem}: {op1_upper}")

        # 16. Shifts / Rotates (CB prefix)
        CB_SHIFTS = {
            "RLC": 0x00, "RRC": 0x08, "RL": 0x10, "RR": 0x18,
            "SLA": 0x20, "SRA": 0x28, "SRL": 0x38
        }
        if mnem in CB_SHIFTS:
            op_upper = ops[0].upper()
            base = CB_SHIFTS[mnem]
            if op_upper in REG8:
                return bytes([0xCB, base | REG8[op_upper]])
            m_ix = self.parse_indexed(op_upper, pass_num)
            if m_ix:
                prefix, disp = m_ix
                return bytes([prefix, 0xCB, disp, base | 6])
            raise AssemblerError(f"Invalid operand for {mnem}: {op_upper}")

        # 17. IN / OUT
        if mnem == "IN":
            op0 = ops[0].upper()
            op1 = ops[1].upper()
            if op0 == "A" and op1.startswith("(") and op1.endswith(")"):
                inner = op1[1:-1].strip()
                if inner != "C":
                    port = self.eval_expr(inner, pass_num) & 0xFF
                    return bytes([0xDB, port])
            if op1 == "(C)" and op0 in REG8:
                return bytes([0xED, 0x40 | (REG8[op0] << 3)])
            raise AssemblerError(f"Invalid operands for IN: {ops}")

        if mnem == "OUT":
            op0 = ops[0].upper()
            op1 = ops[1].upper()
            if op0.startswith("(") and op0.endswith(")"):
                inner = op0[1:-1].strip()
                if inner != "C" and op1 == "A":
                    port = self.eval_expr(inner, pass_num) & 0xFF
                    return bytes([0xD3, port])
                elif inner == "C" and op1 in REG8:
                    return bytes([0xED, 0x41 | (REG8[op1] << 3)])
            raise AssemblerError(f"Invalid operands for OUT: {ops}")

        # 18. LD (Largest group)
        if mnem == "LD":
            return self.encode_ld(ops[0], ops[1], pass_num)

        raise AssemblerError(f"Unrecognized instruction: {mnem}")

    def encode_ld(self, dst_str, src_str, pass_num):
        dst_u = dst_str.upper()
        src_u = src_str.upper()

        # Special LD A, I / LD A, R / LD I, A / LD R, A
        if dst_u == "A" and src_u == "I": return b"\xED\x57"
        if dst_u == "A" and src_u == "R": return b"\xED\x5F"
        if dst_u == "I" and src_u == "A": return b"\xED\x47"
        if dst_u == "R" and src_u == "A": return b"\xED\x4F"

        # 16-bit register loads
        # LD rr, nn
        if dst_u in REG16_SP and not src_u.startswith("("):
            val = self.eval_expr(src_str, pass_num) & 0xFFFF
            return bytes([0x01 | (REG16_SP[dst_u] << 4), val & 0xFF, (val >> 8) & 0xFF])
        if dst_u == "IX" and not src_u.startswith("("):
            val = self.eval_expr(src_str, pass_num) & 0xFFFF
            return bytes([0xDD, 0x21, val & 0xFF, (val >> 8) & 0xFF])
        if dst_u == "IY" and not src_u.startswith("("):
            val = self.eval_expr(src_str, pass_num) & 0xFFFF
            return bytes([0xFD, 0x21, val & 0xFF, (val >> 8) & 0xFF])

        # LD SP, HL / LD SP, IX / LD SP, IY
        if dst_u == "SP":
            if src_u == "HL": return b"\xF9"
            if src_u == "IX": return b"\xDD\xF9"
            if src_u == "IY": return b"\xFD\xF9"

        # LD (nn), HL / LD HL, (nn)
        if dst_u.startswith("(") and dst_u.endswith(")") and src_u == "HL":
            addr = self.eval_expr(dst_str[1:-1], pass_num) & 0xFFFF
            return bytes([0x22, addr & 0xFF, (addr >> 8) & 0xFF])
        if dst_u == "HL" and src_u.startswith("(") and src_u.endswith(")"):
            addr = self.eval_expr(src_str[1:-1], pass_num) & 0xFFFF
            return bytes([0x2A, addr & 0xFF, (addr >> 8) & 0xFF])

        # LD (nn), IX/IY / LD IX/IY, (nn)
        if dst_u.startswith("(") and dst_u.endswith(")") and src_u == "IX":
            addr = self.eval_expr(dst_str[1:-1], pass_num) & 0xFFFF
            return bytes([0xDD, 0x22, addr & 0xFF, (addr >> 8) & 0xFF])
        if dst_u == "IX" and src_u.startswith("(") and src_u.endswith(")"):
            addr = self.eval_expr(src_str[1:-1], pass_num) & 0xFFFF
            return bytes([0xDD, 0x2A, addr & 0xFF, (addr >> 8) & 0xFF])
        if dst_u.startswith("(") and dst_u.endswith(")") and src_u == "IY":
            addr = self.eval_expr(dst_str[1:-1], pass_num) & 0xFFFF
            return bytes([0xFD, 0x22, addr & 0xFF, (addr >> 8) & 0xFF])
        if dst_u == "IY" and src_u.startswith("(") and src_u.endswith(")"):
            addr = self.eval_expr(src_str[1:-1], pass_num) & 0xFFFF
            return bytes([0xFD, 0x2A, addr & 0xFF, (addr >> 8) & 0xFF])

        # LD (nn), rr / LD rr, (nn) (ED prefix)
        if dst_u.startswith("(") and dst_u.endswith(")") and src_u in REG16_SP:
            addr = self.eval_expr(dst_str[1:-1], pass_num) & 0xFFFF
            return bytes([0xED, 0x43 | (REG16_SP[src_u] << 4), addr & 0xFF, (addr >> 8) & 0xFF])
        if dst_u in REG16_SP and src_u.startswith("(") and src_u.endswith(")"):
            addr = self.eval_expr(src_str[1:-1], pass_num) & 0xFFFF
            return bytes([0xED, 0x4B | (REG16_SP[dst_u] << 4), addr & 0xFF, (addr >> 8) & 0xFF])

        # LD A, (BC) / LD A, (DE) / LD (BC), A / LD (DE), A
        if dst_u == "A" and src_u == "(BC)": return b"\x0A"
        if dst_u == "A" and src_u == "(DE)": return b"\x1A"
        if dst_u == "(BC)" and src_u == "A": return b"\x02"
        if dst_u == "(DE)" and src_u == "A": return b"\x12"

        # LD A, (nn) / LD (nn), A
        if dst_u == "A" and src_u.startswith("(") and src_u.endswith(")"):
            m_ix = self.parse_indexed(src_u, pass_num)
            if not m_ix and src_u not in ("(BC)", "(DE)", "(HL)"):
                addr = self.eval_expr(src_str[1:-1], pass_num) & 0xFFFF
                return bytes([0x3A, addr & 0xFF, (addr >> 8) & 0xFF])
        if dst_u.startswith("(") and dst_u.endswith(")") and src_u == "A":
            m_ix = self.parse_indexed(dst_u, pass_num)
            if not m_ix and dst_u not in ("(BC)", "(DE)", "(HL)"):
                addr = self.eval_expr(dst_str[1:-1], pass_num) & 0xFFFF
                return bytes([0x32, addr & 0xFF, (addr >> 8) & 0xFF])

        # Indexed (IX+d), (IY+d) loads
        m_ix_dst = self.parse_indexed(dst_u, pass_num)
        m_ix_src = self.parse_indexed(src_u, pass_num)

        if m_ix_dst:
            prefix, disp = m_ix_dst
            if src_u in REG8 and src_u != "(HL)":
                return bytes([prefix, 0x70 | REG8[src_u], disp])
            # LD (IX+d), n
            val = self.eval_expr(src_str, pass_num) & 0xFF
            return bytes([prefix, 0x36, disp, val])

        if m_ix_src:
            prefix, disp = m_ix_src
            if dst_u in REG8 and dst_u != "(HL)":
                return bytes([prefix, 0x46 | (REG8[dst_u] << 3), disp])

        # 8-bit register-to-register / (HL)
        if dst_u in REG8 and src_u in REG8:
            if dst_u == "(HL)" and src_u == "(HL)":
                raise AssemblerError("LD (HL), (HL) does not exist (HALT is 0x76)")
            return bytes([0x40 | (REG8[dst_u] << 3) | REG8[src_u]])

        # LD r, n / LD (HL), n
        if dst_u in REG8:
            val = self.eval_expr(src_str, pass_num) & 0xFF
            return bytes([0x06 | (REG8[dst_u] << 3), val])

        raise AssemblerError(f"Unsupported LD combination: LD {dst_str}, {src_str}")

    def parse_indexed(self, s, pass_num):
        s = s.strip().upper()
        # Matches (IX), (IX+5), (IX-3), (IY), (IY+10), etc.
        m = re.match(r"^\((IX|IY)(?:([\+\-])(.+))?\)$", s)
        if m:
            reg = m.group(1)
            sign = m.group(2)
            expr = m.group(3)
            prefix = 0xDD if reg == "IX" else 0xFD
            disp = 0
            if expr:
                val = self.eval_expr(expr, pass_num)
                disp = (-val if sign == '-' else val) & 0xFF
            return prefix, disp
        return None

# ==============================================================================
# SinclairZ80CPU Emulator Prototype
# ==============================================================================

FLAG_S = 0x80
FLAG_Z = 0x40
FLAG_Y = 0x20
FLAG_H = 0x10
FLAG_X = 0x08
FLAG_PV = 0x04
FLAG_N = 0x02
FLAG_C = 0x01

# Parity table for 8-bit values
PARITY_TABLE = [0] * 256
for i in range(256):
    p = 1
    v = i
    while v:
        p ^= (v & 1)
        v >>= 1
    PARITY_TABLE[i] = FLAG_PV if p else 0


def float_to_spectrum_5byte(val):
    val = float(val)
    if val == 0.0:
        return bytes(5)
    sign = 1 if val < 0 else 0
    val = abs(val)
    exp = int(math.floor(math.log2(val))) + 1
    mant = val / (2.0 ** exp)
    mant_int = int(round(mant * (2 ** 32)))
    if mant_int >= (1 << 32):
        mant_int = (1 << 32) - 1
    b0 = (exp + 128) & 0xFF
    b1 = ((mant_int >> 24) & 0x7F) | (0x80 if sign else 0x00)
    b2 = (mant_int >> 16) & 0xFF
    b3 = (mant_int >> 8) & 0xFF
    b4 = mant_int & 0xFF
    return bytes([b0, b1, b2, b3, b4])

def spectrum_5byte_to_float(b):
    if len(b) < 5:
        return 0.0
    b0, b1, b2, b3, b4 = b[:5]
    if b0 == 0:
        sign = -1 if b1 == 0xFF else 1
        return float(sign * (b2 | (b3 << 8)))
    exp = b0 - 128
    sign = -1.0 if (b1 & 0x80) else 1.0
    mant_int = ((b1 & 0x7F) | 0x80) << 24 | (b2 << 16) | (b3 << 8) | b4
    mant = mant_int / (2.0 ** 32)
    return sign * mant * (2.0 ** exp)

class SinclairZ80CPU:
    def __init__(self, memory=None):
        self.memory = memory if memory is not None else bytearray(65536)
        self.plus3_mode = ('plus3_mode' in globals() and plus3_mode)
        if self.plus3_mode:
            self.frame_tstates = 70930
            self.clock_hz = 3546900
        elif 'spectrum_128k_mode' in globals() and spectrum_128k_mode:
            self.frame_tstates = 70908
            self.clock_hz = 3546900
        else:
            self.frame_tstates = 69888
            self.clock_hz = 3500000
        self.contention_enabled = False
        self.reset()
        # Hooks for ZX Spectrum hardware integration
        self.hook_print_char = None
        self.hook_cls = None
        self.hook_beeper = None
        self.hook_plot = None
        self.hook_draw = None
        self.hook_port_out = None
        self.hook_port_in = None
        self.screen_dirty = False
        self.is_running = False
        self.captured_output = []
        self.calc_stack = []
        self.breakpoints = set()
        self.breakpoint_hit = None
        self.suspended_by_break = False
        self.user_quit = False
        self.rom_traps_enabled = True
        self.hook_cpm_trap = None
        self.cpm_mode = False
        self.spectranet_subsystem = globals().get('spectranet_subsystem', None)

    def trigger_break(self):
        self.suspended_by_break = True

    def reset(self):
        self.A = 0x00
        self.F = 0x40  # Zero flag set initially
        self.B = 0x00
        self.C = 0x00
        self.D = 0x00
        self.E = 0x00
        self.H = 0x00
        self.L = 0x00

        self.A_prime = 0x00
        self.F_prime = 0x00
        self.B_prime = 0x00
        self.C_prime = 0x00
        self.D_prime = 0x00
        self.E_prime = 0x00
        self.H_prime = 0x00
        self.L_prime = 0x00

        self.IX = 0x0000
        self.IY = 0x0000
        self.SP = 0xFFFE
        self.PC = 0x0000
        self.I = 0x00
        self.R = 0x00
        self.IFF1 = False
        self.IFF2 = False
        self.IM = 1
        self.halted = False
        self.suspended_by_break = False
        self.user_quit = False
        self.cycles = 0
        self.frame_tstates = 70930 if getattr(self, 'plus3_mode', False) else 69888
        self.clock_hz = 3546900 if getattr(self, 'plus3_mode', False) else 3500000
        if 'zx_beeper_audio' in globals() and zx_beeper_audio is not None:
            zx_beeper_audio.reset()
        if hasattr(self, 'calc_stack'):
            self.calc_stack.clear()
        self.breakpoint_hit = None

    # 16-bit register pairs
    @property
    def BC(self): return (self.B << 8) | self.C
    @BC.setter
    def BC(self, val): self.B = (val >> 8) & 0xFF; self.C = val & 0xFF

    @property
    def DE(self): return (self.D << 8) | self.E
    @DE.setter
    def DE(self, val): self.D = (val >> 8) & 0xFF; self.E = val & 0xFF

    @property
    def HL(self): return (self.H << 8) | self.L
    @HL.setter
    def HL(self, val): self.H = (val >> 8) & 0xFF; self.L = val & 0xFF

    @property
    def AF(self): return (self.A << 8) | self.F
    @AF.setter
    def AF(self, val): self.A = (val >> 8) & 0xFF; self.F = val & 0xFF

    def contend_memory(self, addr, tstates=0):
        if not self.contention_enabled:
            return 0
        addr &= 0xFFFF
        is_contended = False
        if not getattr(self, 'plus3_mode', False):
            if 0x4000 <= addr < 0x8000:
                is_contended = True
        else:
            slot = addr >> 14
            bank = current_slot_banks[slot] if 'current_slot_banks' in globals() else 5
            if bank in (4, 5, 6, 7):
                is_contended = True
        if not is_contended:
            return 0
        line_t = 228 if getattr(self, 'plus3_mode', False) else 224
        frame_t = getattr(self, 'frame_tstates', 69888)
        cyc = (self.cycles + tstates) % frame_t
        line = cyc // line_t
        c_in_line = cyc % line_t
        if 64 <= line < 256 and c_in_line < 128:
            return [6, 5, 4, 3, 2, 1, 0, 0][c_in_line % 8]
        return 0

    def read_byte(self, addr):
        a = addr & 0xFFFF
        sub = self.spectranet_subsystem
        if sub is not None:
            if sub.page_a_enabled and 0x1000 <= a < 0x2000:
                return sub.read_w5100(a - 0x1000)
            if sub.page_b_enabled and 0x2000 <= a < 0x3000:
                return sub.read_ram(a - 0x2000)
        return self.memory[a]

    def write_byte(self, addr, val):
        global gfx_bits, attr_ink, attr_paper, attr_bright, attr_flash, canvas_dirty, canvas_dirty_cells
        addr &= 0xFFFF
        val &= 0xFF
        sub = self.spectranet_subsystem
        if sub is not None:
            if sub.page_a_enabled and 0x1000 <= addr < 0x2000:
                sub.write_w5100(addr - 0x1000, val)
                return
            if sub.page_b_enabled and 0x2000 <= addr < 0x3000:
                sub.write_ram(addr - 0x2000, val)
                return
        if addr < 0x4000:
            if getattr(self, 'cpm_mode', False) or getattr(self, 'hook_cpm_trap', None) is not None or ('plus3_special_paging' in globals() and plus3_special_paging):
                self.memory[addr] = val
            return
        mem = self.memory
        if 0x6000 <= addr < 0x7B00:
            if mem[addr] != val:
                mem[addr] = val
                handle_poke_vram(addr, val)
                self.screen_dirty = True
                canvas_dirty = True
            return
        if addr >= 0x5B00 and not (current_shadow_screen and 'current_slot_banks' in globals() and current_slot_banks[3] == 7 and 0xC000 <= addr < 0xDB00):
            if mem[addr] == val:
                return
            mem[addr] = val
            return
        mem[addr] = val
        if 0x4000 <= addr < 0x5800:
            if not current_shadow_screen or ('current_slot_banks' in globals() and current_slot_banks[1] == 7):
                self.screen_dirty = True
                canvas_dirty = True
                handle_poke_vram(addr, val)
                base_x, basin_y, cell_y, col = _VRAM_MAP[addr - 0x4000]
                if 'screen_chars' in globals() and screen_chars:
                    if 0 <= cell_y < 24 and 0 <= col < 32:
                        screen_chars[cell_y][col] = ' '
                bits = _BYTE_BITS[val]
                gfx = gfx_bits
                gfx[base_x][basin_y] = bits[0]
                gfx[base_x + 1][basin_y] = bits[1]
                gfx[base_x + 2][basin_y] = bits[2]
                gfx[base_x + 3][basin_y] = bits[3]
                gfx[base_x + 4][basin_y] = bits[4]
                gfx[base_x + 5][basin_y] = bits[5]
                gfx[base_x + 6][basin_y] = bits[6]
                gfx[base_x + 7][basin_y] = bits[7]
                canvas_dirty_cells.add((cell_y, col))
        elif 0x5800 <= addr < 0x5B00:
            if not current_shadow_screen or ('current_slot_banks' in globals() and current_slot_banks[1] == 7):
                self.screen_dirty = True
                canvas_dirty = True
                offset = addr - 0x5800
                row = offset >> 5
                col = offset & 31
                if 0 <= row < 24 and 0 <= col < 32:
                    attr_ink[row][col] = val & 0x07
                    attr_paper[row][col] = (val >> 3) & 0x07
                    attr_bright[row][col] = (val >> 6) & 0x01
                    attr_flash[row][col] = (val >> 7) & 0x01
                    canvas_dirty_cells.add((row, col))
        elif current_shadow_screen and 'current_slot_banks' in globals() and current_slot_banks[3] == 7 and 0xC000 <= addr < 0xD800:
            self.screen_dirty = True
            canvas_dirty = True
            base_x, basin_y, cell_y, col = _VRAM_MAP[addr - 0xC000]
            if 'screen_chars' in globals() and screen_chars:
                if 0 <= cell_y < 24 and 0 <= col < 32:
                    screen_chars[cell_y][col] = ' '
            bits = _BYTE_BITS[val]
            gfx = gfx_bits
            gfx[base_x][basin_y] = bits[0]
            gfx[base_x + 1][basin_y] = bits[1]
            gfx[base_x + 2][basin_y] = bits[2]
            gfx[base_x + 3][basin_y] = bits[3]
            gfx[base_x + 4][basin_y] = bits[4]
            gfx[base_x + 5][basin_y] = bits[5]
            gfx[base_x + 6][basin_y] = bits[6]
            gfx[base_x + 7][basin_y] = bits[7]
            canvas_dirty_cells.add((cell_y, col))
        elif current_shadow_screen and 'current_slot_banks' in globals() and current_slot_banks[3] == 7 and 0xD800 <= addr < 0xDB00:
            self.screen_dirty = True
            canvas_dirty = True
            offset = addr - 0xD800
            row = offset >> 5
            col = offset & 31
            if 0 <= row < 24 and 0 <= col < 32:
                attr_ink[row][col] = val & 0x07
                attr_paper[row][col] = (val >> 3) & 0x07
                attr_bright[row][col] = (val >> 6) & 0x01
                attr_flash[row][col] = (val >> 7) & 0x01
                canvas_dirty_cells.add((row, col))

    def read_word(self, addr):
        addr &= 0xFFFF
        mem = self.memory
        return mem[addr] | (mem[(addr + 1) & 0xFFFF] << 8)

    def write_word(self, addr, val):
        a = addr & 0xFFFF
        if a >= 0x5B00 and a < 0xFFFF:
            self.memory[a] = val & 0xFF
            self.memory[a + 1] = (val >> 8) & 0xFF
            return
        self.write_byte(a, val & 0xFF)
        self.write_byte(a + 1, (val >> 8) & 0xFF)

    def push_word(self, val):
        sp = (self.SP - 2) & 0xFFFF
        self.SP = sp
        if sp >= 0x5B00 and sp < 0xFFFF:
            self.memory[sp] = val & 0xFF
            self.memory[sp + 1] = (val >> 8) & 0xFF
        else:
            self.write_byte(sp, val & 0xFF)
            self.write_byte(sp + 1, (val >> 8) & 0xFF)

    def pop_word(self):
        sp = self.SP
        mem = self.memory
        val = mem[sp] | (mem[(sp + 1) & 0xFFFF] << 8)
        self.SP = (sp + 2) & 0xFFFF
        return val

    def fetch_byte(self):
        pc = self.PC
        b = self.memory[pc]
        self.PC = (pc + 1) & 0xFFFF
        return b

    def fetch_word(self):
        pc = self.PC
        mem = self.memory
        w = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8)
        self.PC = (pc + 2) & 0xFFFF
        return w

    # Condition checks
    def test_cond(self, cc):
        # 0: NZ, 1: Z, 2: NC, 3: C, 4: PO, 5: PE, 6: P, 7: M
        if cc == 0: return not (self.F & FLAG_Z)
        if cc == 1: return bool(self.F & FLAG_Z)
        if cc == 2: return not (self.F & FLAG_C)
        if cc == 3: return bool(self.F & FLAG_C)
        if cc == 4: return not (self.F & FLAG_PV)
        if cc == 5: return bool(self.F & FLAG_PV)
        if cc == 6: return not (self.F & FLAG_S)
        if cc == 7: return bool(self.F & FLAG_S)
        return False

    # Arithmetic helpers
    def set_flags_add8(self, a, b, carry=0):
        res = a + b + carry
        flags = 0
        if res & 0x80: flags |= FLAG_S
        if (res & 0xFF) == 0: flags |= FLAG_Z
        if (a & 0x0F) + (b & 0x0F) + carry > 0x0F: flags |= FLAG_H
        if ((a ^ res) & (b ^ res) & 0x80): flags |= FLAG_PV
        if res > 0xFF: flags |= FLAG_C
        self.F = flags
        return res & 0xFF

    def set_flags_sub8(self, a, b, carry=0):
        res = a - b - carry
        flags = FLAG_N
        if res & 0x80: flags |= FLAG_S
        if (res & 0xFF) == 0: flags |= FLAG_Z
        if (a & 0x0F) - (b & 0x0F) - carry < 0: flags |= FLAG_H
        if ((a ^ b) & (a ^ res) & 0x80): flags |= FLAG_PV
        if res < 0: flags |= FLAG_C
        self.F = flags
        return res & 0xFF

    def set_flags_logic8(self, res, is_and=False):
        res &= 0xFF
        flags = FLAG_H if is_and else 0
        if res & 0x80: flags |= FLAG_S
        if res == 0: flags |= FLAG_Z
        flags |= PARITY_TABLE[res]
        self.F = flags
        return res

    def set_flags_inc8(self, val):
        res = (val + 1) & 0xFF
        c = self.F & FLAG_C
        flags = c
        if res & 0x80: flags |= FLAG_S
        if res == 0: flags |= FLAG_Z
        if (val & 0x0F) == 0x0F: flags |= FLAG_H
        if val == 0x7F: flags |= FLAG_PV
        self.F = flags
        return res

    def set_flags_dec8(self, val):
        res = (val - 1) & 0xFF
        c = self.F & FLAG_C
        flags = FLAG_N | c
        if res & 0x80: flags |= FLAG_S
        if res == 0: flags |= FLAG_Z
        if (val & 0x0F) == 0: flags |= FLAG_H
        if val == 0x80: flags |= FLAG_PV
        self.F = flags
        return res

    # 8-bit register get/set
    def get_reg8(self, r):
        if r == 7: return self.A
        if r == 0: return self.B
        if r == 1: return self.C
        if r == 2: return self.D
        if r == 3: return self.E
        if r == 4: return self.H
        if r == 5: return self.L
        if r == 6: return self.read_byte((self.H << 8) | self.L)
        return 0

    def set_reg8(self, r, val):
        val &= 0xFF
        if r == 7: self.A = val
        elif r == 0: self.B = val
        elif r == 1: self.C = val
        elif r == 2: self.D = val
        elif r == 3: self.E = val
        elif r == 4: self.H = val
        elif r == 5: self.L = val
        elif r == 6: self.write_byte((self.H << 8) | self.L, val)

    # 16-bit register get/set
    def get_reg16(self, rr):
        if rr == 0: return (self.B << 8) | self.C
        if rr == 1: return (self.D << 8) | self.E
        if rr == 2: return (self.H << 8) | self.L
        if rr == 3: return self.SP
        return 0

    def set_reg16(self, rr, val):
        val &= 0xFFFF
        if rr == 0:
            self.B = (val >> 8) & 0xFF
            self.C = val & 0xFF
        elif rr == 1:
            self.D = (val >> 8) & 0xFF
            self.E = val & 0xFF
        elif rr == 2:
            self.H = (val >> 8) & 0xFF
            self.L = val & 0xFF
        elif rr == 3:
            self.SP = val

    # Sinclair Calculator Stack Operations
    def sync_calc_stack_from_memory(self):
        stkend = self.memory[23653] | (self.memory[23654] << 8)
        stkbot = self.memory[23651] | (self.memory[23652] << 8)
        min_addr = stkbot if (0x5C00 <= stkbot <= 0xFFF0) else 0x5C92
        items = []
        if min_addr <= stkend <= min_addr + 1000:
            for addr in range(min_addr, stkend, 5):
                b = bytes([self.memory[(addr + i) & 0xFFFF] for i in range(5)])
                items.append(spectrum_5byte_to_float(b))
        self.calc_stack = items

    def calc_push(self, val):
        stkend = self.memory[23653] | (self.memory[23654] << 8)
        if stkend < 0x5CB0 or stkend > 0xFFF0:
            stkend = 0x5CB0
        b = float_to_spectrum_5byte(val)
        for i in range(5):
            self.memory[(stkend + i) & 0xFFFF] = b[i]
        stkend = (stkend + 5) & 0xFFFF
        self.memory[23653] = stkend & 0xFF
        self.memory[23654] = (stkend >> 8) & 0xFF
        self.calc_stack.append(float(val))

    def calc_pop(self):
        stkend = self.memory[23653] | (self.memory[23654] << 8)
        stkbot = self.memory[23651] | (self.memory[23652] << 8)
        min_addr = stkbot if (0x5C00 <= stkbot <= 0xFFF0) else 0x5CB0
        val = 0.0
        if stkend >= min_addr + 5:
            b = bytes([self.memory[(stkend - 5 + i) & 0xFFFF] for i in range(5)])
            stkend = (stkend - 5) & 0xFFFF
            self.memory[23653] = stkend & 0xFF
            self.memory[23654] = (stkend >> 8) & 0xFF
            val = spectrum_5byte_to_float(b)
        elif stkend >= 5:
            b = bytes([self.memory[(stkend - 5 + i) & 0xFFFF] for i in range(5)])
            stkend = (stkend - 5) & 0xFFFF
            self.memory[23653] = stkend & 0xFF
            self.memory[23654] = (stkend >> 8) & 0xFF
            val = spectrum_5byte_to_float(b)
        if self.calc_stack:
            self.calc_stack.pop()
        return val

    def execute_fp_calc(self):
        self.sync_calc_stack_from_memory()
        while True:
            calc_op = self.fetch_byte()
            if calc_op == 0x38:  # end-calc
                self.sync_calc_stack_from_memory()
                break
            elif calc_op == 0x00:  # jump-true
                disp_raw = self.fetch_byte()
                disp = disp_raw if disp_raw < 128 else disp_raw - 256
                cond = self.calc_pop()
                if cond != 0.0:
                    self.PC = (self.PC + disp) & 0xFFFF
            elif calc_op == 0x33:  # jump
                disp_raw = self.fetch_byte()
                disp = disp_raw if disp_raw < 128 else disp_raw - 256
                self.PC = (self.PC + disp) & 0xFFFF
            elif calc_op == 0x01:  # exchange
                stkend = self.memory[23653] | (self.memory[23654] << 8)
                stkbot = self.memory[23651] | (self.memory[23652] << 8)
                min_addr = stkbot if (0x5C00 <= stkbot <= 0xFFF0) else 0x5C92
                if stkend >= min_addr + 10:
                    y = self.calc_pop()
                    x = self.calc_pop()
                    self.calc_push(y)
                    self.calc_push(x)
            elif calc_op == 0x02:  # delete
                self.calc_pop()
            elif calc_op == 0x03:  # subtract
                y = self.calc_pop()
                x = self.calc_pop()
                self.calc_push(x - y)
            elif calc_op == 0x04:  # multiply
                y = self.calc_pop()
                x = self.calc_pop()
                self.calc_push(x * y)
            elif calc_op == 0x05:  # division
                y = self.calc_pop()
                x = self.calc_pop()
                self.calc_push(x / (y if y != 0 else 1e-9))
            elif calc_op == 0x06:  # to-power
                y = self.calc_pop()
                x = self.calc_pop()
                try:
                    self.calc_push(x ** y)
                except Exception:
                    self.calc_push(0.0)
            elif calc_op == 0x07:  # or
                y = self.calc_pop()
                x = self.calc_pop()
                self.calc_push(1.0 if (x != 0.0 or y != 0.0) else 0.0)
            elif calc_op == 0x08:  # no-&-no (and)
                y = self.calc_pop()
                x = self.calc_pop()
                self.calc_push(1.0 if (x != 0.0 and y != 0.0) else 0.0)
            elif calc_op == 0x09:  # <=
                y = self.calc_pop()
                x = self.calc_pop()
                self.calc_push(1.0 if x <= y else 0.0)
            elif calc_op == 0x0A:  # >=
                y = self.calc_pop()
                x = self.calc_pop()
                self.calc_push(1.0 if x >= y else 0.0)
            elif calc_op == 0x0B:  # <>
                y = self.calc_pop()
                x = self.calc_pop()
                self.calc_push(1.0 if x != y else 0.0)
            elif calc_op == 0x0C:  # >
                y = self.calc_pop()
                x = self.calc_pop()
                self.calc_push(1.0 if x > y else 0.0)
            elif calc_op == 0x0D:  # <
                y = self.calc_pop()
                x = self.calc_pop()
                self.calc_push(1.0 if x < y else 0.0)
            elif calc_op == 0x0E:  # =
                y = self.calc_pop()
                x = self.calc_pop()
                self.calc_push(1.0 if x == y else 0.0)
            elif calc_op == 0x0F:  # addition
                y = self.calc_pop()
                x = self.calc_pop()
                self.calc_push(x + y)
            elif calc_op == 0x1B:  # negate
                self.calc_push(-self.calc_pop())
            elif calc_op == 0x1F:  # sin
                self.calc_push(math.sin(self.calc_pop()))
            elif calc_op == 0x20:  # cos
                self.calc_push(math.cos(self.calc_pop()))
            elif calc_op == 0x21:  # tan
                self.calc_push(math.tan(self.calc_pop()))
            elif calc_op == 0x22:  # asn
                self.calc_push(math.asin(max(-1.0, min(1.0, self.calc_pop()))))
            elif calc_op == 0x23:  # acs
                self.calc_push(math.acos(max(-1.0, min(1.0, self.calc_pop()))))
            elif calc_op == 0x24:  # atn
                self.calc_push(math.atan(self.calc_pop()))
            elif calc_op == 0x25:  # ln
                v = self.calc_pop()
                self.calc_push(math.log(max(1e-9, v)))
            elif calc_op == 0x26:  # exp
                v = self.calc_pop()
                self.calc_push(math.exp(min(88.0, v)))
            elif calc_op == 0x27:  # int
                self.calc_push(math.floor(self.calc_pop()))
            elif calc_op == 0x28:  # sqr
                self.calc_push(math.sqrt(max(0.0, self.calc_pop())))
            elif calc_op == 0x29:  # sgn
                v = self.calc_pop()
                self.calc_push(1.0 if v > 0 else (-1.0 if v < 0 else 0.0))
            elif calc_op == 0x2A:  # abs
                self.calc_push(abs(self.calc_pop()))
            elif calc_op in (0x2D, 0x31):  # duplicate
                v = self.calc_pop()
                self.calc_push(v)
                self.calc_push(v)
            elif calc_op == 0x2E:  # strs (STR$)
                val = self.calc_pop()
                s = str(int(val)) if int(val) == val else f"{val:g}"
                s_bytes = s.encode("latin1", errors="ignore")
                str_len = len(s_bytes)
                str_addr = 0x5C92
                for idx, sb in enumerate(s_bytes):
                    self.memory[(str_addr + idx) & 0xFFFF] = sb
                end_addr = str_addr + str_len
                self.memory[23649] = end_addr & 0xFF
                self.memory[23650] = (end_addr >> 8) & 0xFF
                self.memory[23651] = end_addr & 0xFF
                self.memory[23652] = (end_addr >> 8) & 0xFF
                desc = [
                    0x00,
                    str_addr & 0xFF,
                    (str_addr >> 8) & 0xFF,
                    str_len & 0xFF,
                    (str_len >> 8) & 0xFF,
                ]
                for i in range(5):
                    self.memory[(end_addr + i) & 0xFFFF] = desc[i]
                stkend = end_addr + 5
                self.memory[23653] = stkend & 0xFF
                self.memory[23654] = (stkend >> 8) & 0xFF
            elif calc_op == 0x32:  # n-mod-m
                y = self.calc_pop()
                x = self.calc_pop()
                self.calc_push(x % y if y != 0 else 0.0)
            elif calc_op == 0x34:  # stk-data
                b = bytes([self.fetch_byte() for _ in range(5)])
                self.calc_push(spectrum_5byte_to_float(b))
            elif calc_op in (0x35, 0xA2):  # stk-half / const 0.5
                self.calc_push(0.5)
            elif calc_op in (0x36, 0xA1):  # stk-one / const 1.0
                self.calc_push(1.0)
            elif calc_op in (0x37, 0xA0):  # stk-zero / const 0.0
                self.calc_push(0.0)
            elif calc_op == 0x3B:  # fp-to-bc
                self.BC = int(round(self.calc_pop())) & 0xFFFF
            elif calc_op == 0x3C:  # bc-to-fp
                self.calc_push(float(self.BC))
            elif calc_op == 0xA3:  # const pi/2
                self.calc_push(math.pi / 2.0)
            elif calc_op == 0xA4:  # const 10.0
                self.calc_push(10.0)
            else:
                break

    # Check ROM interception
    def check_rom_hook(self):
        global tape_block_index, tape_raw_index, tape_raw_blocks, last_loaded_screen_bytes, last_loaded_code_bytes, last_loaded_code_addr, entire_group_stream, entire_group_ptr
        global tape_pure_data_blocks, tape_turbo_blocks, tape_turbo_index, speedlock_call_count, ram_banks, select_ram_bank, current_ram_bank
        # CP/M BDOS & BIOS Interception Hook
        hook_cpm = getattr(self, 'hook_cpm_trap', None)
        if hook_cpm is not None:
            if self.PC in (0x0000, 0x0005) or self.PC == getattr(self, 'bdos_entry', 0xFDF0) or (0xFE00 <= self.PC <= 0xFE33):
                return hook_cpm(self)

        pc = self.PC
        if pc >= 0x4000 and pc not in (0x5D06, 0x5D51, 0x5D88, 0x81F6, 0x9C4C, 0xFCF7):
            return False

        # TR-DOS / Beta Disk ROM Hook (0x3D13 / 15619)
        if pc == 0x3D13:
            return handle_trdos_rom_hook(self)

        # Spectranet CPLD CALL 0x3FF8..0x3FFF Trap
        if 'spectranet_subsystem' in globals() and spectranet_subsystem:
            if spectranet_subsystem.traps_enabled and 0x3FF8 <= pc <= 0x3FFF:
                return spectranet_subsystem.handle_trap_call(self)

        if 'cartridge_inserted' in globals() and cartridge_inserted:
            return False

        if not getattr(self, 'rom_traps_enabled', True):
            return False

        # RST 0 / 0x0000: START / Reset
        if pc == 0x0000:
            init_system_variables()
            self.reset()
            self.halted = True
            return True

        # RST 8 / 0x0008: NextZXOS / ESXDOS API Hook (in NEXT mode) or ERROR-1 (in Sinclair mode)
        if pc == 0x0008:
            ret_addr = self.pop_word()
            fn_code = self.read_byte(ret_addr)
            if globals().get('spectrum_mode', '48K') == 'NEXT' and fn_code >= 0x80:
                self.PC = (ret_addr + 1) & 0xFFFF
                handle_nextzxos_esxdos_hook(self, fn_code)
                return True
            err_code = fn_code
            self.memory[23610] = (err_code - 1) & 0xFF
            self.captured_output.append(f"[ERROR {err_code}]")
            self.PC = (ret_addr + 1) & 0xFFFF
            return True

        # RST 16 / 0x0010: PRINT-A-1
        if pc == 0x0010:
            curchl = self.memory[23633] | (self.memory[23634] << 8)
            if curchl < 0x10000 - 1:
                out_routine = self.memory[curchl] | (self.memory[curchl + 1] << 8)
                if out_routine >= 0x4000:
                    return False
            ch = chr(self.A) if 32 <= self.A <= 126 or self.A in (10, 13) else f"<{self.A}>"
            self.captured_output.append(ch)
            if self.hook_print_char:
                self.hook_print_char(self.A)
            self.PC = self.pop_word()
            return True

        # RST 24 / 0x0018: GET-CHAR (scan current char, skip spaces)
        if pc == 0x0018:
            ch_add = self.memory[23645] | (self.memory[23646] << 8)
            ch = self.read_byte(ch_add)
            while ch == 32:
                ch_add = (ch_add + 1) & 0xFFFF
                ch = self.read_byte(ch_add)
            self.memory[23645] = ch_add & 0xFF
            self.memory[23646] = (ch_add >> 8) & 0xFF
            self.A = ch
            self.F &= ~(FLAG_Z | FLAG_C)
            if ch in (13, ord(':')): self.F |= FLAG_Z
            if 48 <= ch <= 57: self.F |= FLAG_C
            self.PC = self.pop_word()
            return True

        # RST 32 / 0x0020: NEXT-CHAR (advance CH_ADD, then scan)
        if pc == 0x0020:
            ch_add = ((self.memory[23645] | (self.memory[23646] << 8)) + 1) & 0xFFFF
            ch = self.read_byte(ch_add)
            while ch == 32:
                ch_add = (ch_add + 1) & 0xFFFF
                ch = self.read_byte(ch_add)
            self.memory[23645] = ch_add & 0xFF
            self.memory[23646] = (ch_add >> 8) & 0xFF
            self.A = ch
            self.F &= ~(FLAG_Z | FLAG_C)
            if ch in (13, ord(':')): self.F |= FLAG_Z
            if 48 <= ch <= 57: self.F |= FLAG_C
            self.PC = self.pop_word()
            return True

        # RST 40 / 0x0028 and 0x335B: Floating-Point Calculator
        if pc in (0x0028, 0x335B):
            self.PC = self.pop_word()
            self.execute_fp_calc()
            return True

        # RST 48 / 0x0030: BC-ADD (DE = HL + BC)
        if pc == 0x0030:
            self.DE = (self.HL + self.BC) & 0xFFFF
            self.PC = self.pop_word()
            return True

        # RST 56 / 0x0038: MASK-INT (Frame Counter)
        if pc == 0x0038:
            frames = self.memory[23672] | (self.memory[23673] << 8) | (self.memory[23674] << 16)
            frames = (frames + 1) & 0xFFFFFF
            self.memory[23672] = frames & 0xFF
            self.memory[23673] = (frames >> 8) & 0xFF
            self.memory[23674] = (frames >> 16) & 0xFF
            self.IFF1 = True
            self.IFF2 = True
            self.PC = self.pop_word()
            return True

        # 0x02BF: KEY-SCAN
        if pc == 0x02BF:
            key = get_next_inkey() if 'get_next_inkey' in globals() else ""
            self.A = ord(key[0]) if key else 0
            self.PC = self.pop_word()
            return True

        # 0x03B5: BEEPER (duration DE, pitch HL)
        if pc == 0x03B5:
            if self.hook_beeper:
                self.hook_beeper(self.DE, self.HL)
            self.IFF1 = True
            self.IFF2 = True
            self.PC = self.pop_word()
            return True

        # 0x03F8: BEEP (calc_stack: duration, pitch)
        if pc == 0x03F8:
            try:
                pitch = self.calc_pop()
                dur = self.calc_pop()
                if 'play_spectrum_beep' in globals():
                    play_spectrum_beep(dur, pitch)
            except Exception:
                pass
            self.IFF1 = True
            self.IFF2 = True
            self.PC = self.pop_word()
            return True

        # 0x04C2 / 0x0556 / 0x0562: SA-BYTES / LD-BYTES
        if pc in (0x04C2, 0x0556, 0x0562):
            if 'tape_raw_blocks' in globals() and tape_raw_blocks and 'tape_raw_index' in globals() and tape_raw_index < len(tape_raw_blocks):
                flg, payload = tape_raw_blocks[tape_raw_index]
                tape_raw_index += 1
                ix = self.IX & 0xFFFF
                de = self.DE & 0xFFFF
                copy_len = min(len(payload), de) if de > 0 else len(payload)
                if ix + copy_len <= len(self.memory):
                    self.memory[ix : ix + copy_len] = payload[:copy_len]
                if (ix == 0x4000 or (0x4000 <= ix < 0x5800)) and len(payload) >= 6144:
                    last_loaded_screen_bytes = bytes(payload)
                    if 'load_screen_bytes' in globals():
                        load_screen_bytes(payload)
                elif len(payload) > 100:
                    last_loaded_code_bytes = bytes(payload)
                    last_loaded_code_addr = ix
            elif 'tape_data_blocks' in globals() and tape_data_blocks and 'tape_block_index' in globals() and tape_block_index < len(tape_data_blocks):
                payload = tape_data_blocks[tape_block_index]
                tape_block_index += 1
                ix = self.IX & 0xFFFF
                de = self.DE & 0xFFFF
                copy_len = min(len(payload), de) if de > 0 else len(payload)
                if ix + copy_len <= len(self.memory):
                    self.memory[ix : ix + copy_len] = payload[:copy_len]
                if (ix == 0x4000 or (0x4000 <= ix < 0x5800)) and len(payload) >= 6144:
                    last_loaded_screen_bytes = bytes(payload)
                    if 'load_screen_bytes' in globals():
                        load_screen_bytes(payload)
                elif len(payload) > 100:
                    last_loaded_code_bytes = bytes(payload)
                    last_loaded_code_addr = ix
            self.F |= FLAG_C
            self.PC = self.pop_word()
            return True

        # Entire Group custom tape loader hook (0x5D51 / 0x5D88, used by Removal and other Entire Group releases)
        if pc == 0x5D51 and self.read_byte(0x5D51) == 0xCD:
            prog_base = 23755
            sync_off = prog_base + 272 + 34
            if sync_off + 12 <= len(self.memory) and bytes(self.memory[sync_off : sync_off + 12]) == b'Entire Group':
                stream_start = prog_base + 272 + 47
                entire_group_stream = bytes(self.memory[stream_start:])
                entire_group_ptr = 0
            elif 'tape_raw_blocks' in globals() and tape_raw_blocks and 'tape_raw_index' in globals() and tape_raw_index < len(tape_raw_blocks):
                flg, payload = tape_raw_blocks[tape_raw_index]
                tape_raw_index += 1
                entire_group_stream = payload
                entire_group_ptr = 0
            self.F |= FLAG_C
            self.PC = self.pop_word()
            return True

        if pc == 0x5D88 and self.read_byte(0x5D88) == 0xD5 and self.read_byte(0x5D89) == 0xC5:
            if 'entire_group_stream' in globals() and entire_group_stream and 'entire_group_ptr' in globals():
                if entire_group_ptr < len(entire_group_stream):
                    self.A = entire_group_stream[entire_group_ptr]
                    entire_group_ptr += 1
                    self.F |= FLAG_C
                else:
                    self.F &= ~FLAG_C
                self.PC = self.pop_word()
                return True
        # Speedlock 7 Entry Fast-Forward hook (0x5D06)
        if pc == 0x5D06 and 'tape_pure_data_blocks' in globals() and tape_pure_data_blocks and len(tape_pure_data_blocks) > 23:
            b = tape_pure_data_blocks
            if len(b[1]) == 233 and len(b[3]) == 6144:
                # 1. Screen bitmap (Block 3, 6144 bytes) to 16384
                scr_bitmap = bytearray([((0xC1 ^ x) + 0x11) & 0xFF for x in b[3]])
                self.memory[16384 : 16384 + len(scr_bitmap)] = scr_bitmap

                # Screen attributes (Block 5, 768 bytes) to 22528 and 32768
                scr_attr = bytearray([((0xC1 ^ x) + 0x11) & 0xFF for x in b[5]])
                self.memory[22528 : 22528 + len(scr_attr)] = scr_attr
                if 32768 + len(scr_attr) <= len(self.memory):
                    self.memory[32768 : 32768 + len(scr_attr)] = scr_attr
                if 'load_screen_bytes' in globals():
                    load_screen_bytes(self.memory[16384:23296])
                if 'update_display' in globals():
                    update_display()
                self.screen_dirty = True

                # 2. Decrypt game code blocks
                self.memory[0x7FFF : 0x7FFF + len(b[15])] = bytearray([((0x86 ^ x) + 0x11) & 0xFF for x in b[15]])
                self.memory[0x93FF : 0x93FF + len(b[7])] = bytearray([((0xC1 ^ x) + 0x11) & 0xFF for b_i in [b[7]] for x in b_i])
                self.memory[0xACFF : 0xACFF + len(b[17])] = bytearray([((0x86 ^ x) + 0x11) & 0xFF for x in b[17]])
                self.memory[0xFE41 : 0xFE41 + len(b[19])] = bytearray([((0x86 ^ x) + 0x11) & 0xFF for x in b[19]])
                self.memory[0xFEFD : 0xFEFD + len(b[21])] = bytearray([((0x86 ^ x) + 0x11) & 0xFF for x in b[21]])
                self.memory[0x6000 : 0x6000 + len(b[23])] = bytearray([((0x86 ^ x) + 0x11) & 0xFF for x in b[23]])

                # 3. Apply 0xE3 XOR decryption on 14000 bytes starting at 0x7FFF
                for i in range(14000):
                    self.memory[0x7FFF + i] ^= 0xE3

                if 0xFEB4 < len(self.memory):
                    self.memory[0xFEB4] = 0

                if 'ram_banks' in globals():
                    ram_banks[0][:] = self.memory[0xC000 : 0x10000]

                self.PC = 0x6000
                self.SP = 0x5FFF
                return True

        # Robocop 128K Inter-Bank Memory Copy hook (0x9C4C)
        if pc == 0x9C4C and self.read_byte(0x9C50) == 0xED and self.read_byte(0x9C51) == 0x69:
            de = self.DE & 0xFFFF
            src_bank = self.L & 0x07
            dst_bank = self.H & 0x07
            iy = self.IY & 0xFFFF
            ix = self.IX & 0xFFFF
            def advance_bank(bk):
                if bk == 7: return 1
                if bk == 4: return 6
                nb = (bk + 1) & 7
                return 6 if nb == 5 else nb

            while de > 0:
                val = ram_banks[src_bank][iy - 0xC000] if iy >= 0xC000 else self.memory[iy]
                if ix >= 0xC000:
                    ram_banks[dst_bank][ix - 0xC000] = val
                else:
                    self.memory[ix] = val
                iy += 1
                if iy > 0xFFFF:
                    iy = 0xC000
                    src_bank = advance_bank(src_bank)
                ix += 1
                if ix > 0xFFFF:
                    ix = 0xC000
                    dst_bank = advance_bank(dst_bank)
                de -= 1
            self.DE = 0
            self.IY = iy & 0xFFFF
            self.IX = ix & 0xFFFF
            self.L = src_bank
            self.H = dst_bank
            if 'current_ram_bank' in globals():
                current_ram_bank = 0
            if 'ram_banks' in globals():
                self.memory[0xC000 : 0x10000] = ram_banks[0][:]
            if 'select_ram_bank' in globals():
                select_ram_bank(0)
            self.PC = 0x66EF
            return True

        # Speedlock 7 Tape Loader hook (0xFCF7)
        if pc == 0xFCF7 and 'tape_pure_data_blocks' in globals() and tape_pure_data_blocks:
            if 'speedlock_call_count' not in globals():
                speedlock_call_count = 0
            speedlock_call_count += 1
            if speedlock_call_count == 1:
                # Load Block 1 (pure data block index 1, 233 bytes) into 0xFEE9
                if len(tape_pure_data_blocks) > 1:
                    blk = tape_pure_data_blocks[1]
                    dec = bytearray([((0xC1 ^ b) + 0x11) & 0xFF for b in blk])
                    copy_len = min(len(dec), len(self.memory) - 0xFEE9)
                    self.memory[0xFEE9 : 0xFEE9 + copy_len] = dec[:copy_len]
                if 0xFEB4 < len(self.memory):
                    self.memory[0xFEB4] = 0
                self.pop_word()  # pop return address 0xFE44
                self.PC = 0xFEE9
                return True
            elif speedlock_call_count == 2:
                # Screen bitmap (Block 3, 6144 bytes) to 16384
                if len(tape_pure_data_blocks) > 3:
                    scr_bitmap = bytearray([((0xC1 ^ b) + 0x11) & 0xFF for b in tape_pure_data_blocks[3]])
                    self.memory[16384 : 16384 + len(scr_bitmap)] = scr_bitmap

                # Screen attributes (Block 5, 768 bytes) to 22528 and 32768
                if len(tape_pure_data_blocks) > 5:
                    scr_attr = bytearray([((0xC1 ^ b) + 0x11) & 0xFF for b in tape_pure_data_blocks[5]])
                    self.memory[22528 : 22528 + len(scr_attr)] = scr_attr
                    if 32768 + len(scr_attr) <= len(self.memory):
                        self.memory[32768 : 32768 + len(scr_attr)] = scr_attr
                if 'load_screen_bytes' in globals():
                    load_screen_bytes(self.memory[16384:23296])
                if 'update_display' in globals():
                    update_display()
                self.screen_dirty = True

                # Block 7 (6400 bytes, key 0xC1) to 0x93FF
                if len(tape_pure_data_blocks) > 7:
                    b7 = bytearray([((0xC1 ^ b) + 0x11) & 0xFF for b in tape_pure_data_blocks[7]])
                    self.memory[0x93FF : 0x93FF + len(b7)] = b7

                # Block 9 (2 bytes, key 0xC1) to 0xFD80
                if len(tape_pure_data_blocks) > 9:
                    b9 = bytearray([((0xC1 ^ b) + 0x11) & 0xFF for b in tape_pure_data_blocks[9]])
                    self.memory[0xFD80 : 0xFD80 + len(b9)] = b9

                # Block 11 (4 bytes, key 0x86) to 0xFDB4
                if len(tape_pure_data_blocks) > 11:
                    b11 = bytearray([((0x86 ^ b) + 0x11) & 0xFF for b in tape_pure_data_blocks[11]])
                    self.memory[0xFDB4 : 0xFDB4 + len(b11)] = b11

                # Block 13 (55 bytes, key 0x86) to 0xFF4A
                if len(tape_pure_data_blocks) > 13:
                    b13 = bytearray([((0x86 ^ b) + 0x11) & 0xFF for b in tape_pure_data_blocks[13]])
                    self.memory[0xFF4A : 0xFF4A + len(b13)] = b13

                # Block 15 (5120 bytes, key 0x86) to 0x7FFF
                if len(tape_pure_data_blocks) > 15:
                    b15 = bytearray([((0x86 ^ b) + 0x11) & 0xFF for b in tape_pure_data_blocks[15]])
                    self.memory[0x7FFF : 0x7FFF + len(b15)] = b15

                # Block 17 (2480 bytes, key 0x86) to 0xACFF
                if len(tape_pure_data_blocks) > 17:
                    b17 = bytearray([((0x86 ^ b) + 0x11) & 0xFF for b in tape_pure_data_blocks[17]])
                    self.memory[0xACFF : 0xACFF + len(b17)] = b17

                # Block 19 (115 bytes, key 0x86) to 0xFE41
                if len(tape_pure_data_blocks) > 19:
                    b19 = bytearray([((0x86 ^ b) + 0x11) & 0xFF for b in tape_pure_data_blocks[19]])
                    self.memory[0xFE41 : 0xFE41 + len(b19)] = b19

                # Block 21 (49 bytes, key 0x86) to 0xFEFD
                if len(tape_pure_data_blocks) > 21:
                    b21 = bytearray([((0x86 ^ b) + 0x11) & 0xFF for b in tape_pure_data_blocks[21]])
                    self.memory[0xFEFD : 0xFEFD + len(b21)] = b21

                # Block 23 (22 bytes, key 0x86) to 0x6000
                if len(tape_pure_data_blocks) > 23:
                    b23 = bytearray([((0x86 ^ b) + 0x11) & 0xFF for b in tape_pure_data_blocks[23]])
                    self.memory[0x6000 : 0x6000 + len(b23)] = b23

                if 0xFEB4 < len(self.memory):
                    self.memory[0xFEB4] = 0
                self.PC = self.pop_word()
                return True

        # Robocop Level Loader hook (0x81F6)
        if pc == 0x81F6 and 'tape_turbo_blocks' in globals() and tape_turbo_blocks:
            if 'tape_turbo_index' not in globals():
                tape_turbo_index = 0
            if tape_turbo_index < len(tape_turbo_blocks):
                tb = tape_turbo_blocks[tape_turbo_index]
                tape_turbo_index += 1
                payload = tb[1:] if len(tb) > 0 and tb[0] == 0x88 else tb
                dest = self.IX & 0xFFFF
                de = self.DE & 0xFFFF
                copy_len = min(len(payload), de) if de > 0 else len(payload)
                if dest + copy_len <= len(self.memory):
                    self.memory[dest : dest + copy_len] = payload[:copy_len]
                    if dest + copy_len > 0xC000 and 'ram_banks' in globals() and 'current_ram_bank' in globals():
                        start_c0 = max(0, 0xC000 - dest)
                        ram_offset = max(0, dest - 0xC000)
                        ram_len = copy_len - start_c0
                        ram_banks[current_ram_bank][ram_offset : ram_offset + ram_len] = payload[start_c0 : start_c0 + ram_len]
                self.F |= FLAG_C
                self.PC = self.pop_word()
                return True

        # 0x0D6B: CLS
        if pc == 0x0D6B:
            if self.hook_cls:
                self.hook_cls()
            self.PC = self.pop_word()
            return True

        # 0x0D6E: CLS-LOWER (clear lines 22-23)
        if pc == 0x0D6E:
            global print_row, print_col, canvas_dirty, screen_chars
            if 'screen_chars' in globals() and screen_chars:
                for r in (22, 23):
                    for c in range(32):
                        screen_chars[r][c] = ' '
            print_row = 22
            print_col = 0
            canvas_dirty = True
            self.PC = self.pop_word()
            return True

        # 0x0DAF: TEMPS (copy ATTR_P/MASK_P to ATTR_T/MASK_T)
        if pc == 0x0DAF:
            self.memory[23695] = self.memory[23693]
            self.memory[23696] = self.memory[23694]
            self.PC = self.pop_word()
            return True

        # 0x0E9B, 0x1601, 0x1605, 0x1655, 0x12A9: Channel/Stream open
        if pc in (0x0E9B, 0x1601, 0x1605, 0x1655, 0x12A9):
            if pc == 0x12A9: self.F |= FLAG_C
            self.PC = self.pop_word()
            return True

        # 0x0F2C, 0x203C: PR-STRING (DE=addr, BC=length or 0-terminated)
        if pc in (0x0F2C, 0x203C):
            if self.BC > 0:
                text = "".join(chr(self.read_byte(self.DE + i)) for i in range(self.BC))
            else:
                chars = []
                for i in range(256):
                    c = self.read_byte(self.DE + i)
                    if c in (0, 0xFF): break
                    chars.append(chr(c))
                text = "".join(chars)
            self.captured_output.append(text)
            if self.hook_print_char:
                for c in text:
                    self.hook_print_char(ord(c))
            self.PC = self.pop_word()
            return True

        # 0x10A8 / 0x15D4: KEY-INPUT / WAIT-KEY
        if pc in (0x10A8, 0x15D4):
            key = get_next_inkey() if 'get_next_inkey' in globals() else ""
            self.A = ord(key[0]) if key else 0
            self.PC = self.pop_word()
            return True

        # 0x1A1B / 0x1A24: OUT-NUM-1 / OUT-NUM-2 (print 16-bit integer in BC)
        if pc in (0x1A1B, 0x1A24):
            num_str = str(self.BC)
            self.captured_output.append(num_str)
            if self.hook_print_char:
                for ch in num_str:
                    self.hook_print_char(ord(ch))
            self.PC = self.pop_word()
            return True

        # 0x1E99: FIND-INT1 (convert top of calc stack to 8-bit integer in A)
        if pc == 0x1E99:
            self.A = int(round(self.calc_pop())) & 0xFF
            self.PC = self.pop_word()
            return True

        # 0x1F3A / 0x1F3D: PAUSE statement
        if pc in (0x1F3A, 0x1F3D):
            frames = self.memory[23672] | (self.memory[23673] << 8) | (self.memory[23674] << 16)
            frames = (frames + max(1, self.BC)) & 0xFFFFFF
            self.memory[23672] = frames & 0xFF
            self.memory[23673] = (frames >> 8) & 0xFF
            self.memory[23674] = (frames >> 16) & 0xFF
            iy = self.IY
            self.memory[(iy + 1) & 0xFFFF] &= ~0x20
            self.BC = 0
            self.PC = self.pop_word()
            return True

        # 0x22AA: PLOT (B=x, C=y)
        if pc == 0x22AA:
            if self.hook_plot:
                self.hook_plot(self.B, self.C)
            self.memory[23677] = self.B & 0xFF
            self.memory[23678] = self.C & 0xFF
            self.PC = self.pop_word()
            return True

        # 0x22DC: POINT (B=x, C=y -> A=1 if set, 0 if reset, Z flag)
        if pc == 0x22DC:
            px = self.B & 0xFF
            py = self.C & 0xFF
            basin_y = max(0, min(191, py))
            global gfx_bits
            is_set = gfx_bits[px][basin_y] if ('gfx_bits' in globals() and 0 <= px < 256) else False
            self.A = 1 if is_set else 0
            self.F &= ~(FLAG_Z | FLAG_S | FLAG_C)
            if not is_set: self.F |= FLAG_Z
            self.PC = self.pop_word()
            return True

        # 0x247D: DRAW (relative dx=B, dy=C)
        if pc == 0x247D:
            if self.hook_draw:
                self.hook_draw(self.B, self.C)
            self.PC = self.pop_word()
            return True

        # 0x24B7: DRAW-TO (absolute x=B, y=C)
        if pc == 0x24B7:
            x0 = self.memory[23677]
            y0 = self.memory[23678]
            if 'draw_line' in globals():
                draw_line(x0, y0, self.B & 0xFF, self.C & 0xFF)
            self.memory[23677] = self.B & 0xFF
            self.memory[23678] = self.C & 0xFF
            self.PC = self.pop_word()
            return True

        # 0x2D28: STACK-A (push 8-bit integer in A to calc stack)
        if pc == 0x2D28:
            self.calc_push(float(self.A))
            self.PC = self.pop_word()
            return True

        # 0x33B4: STACK-NUM (read 5-byte float at (HL) into calc stack, HL += 5)
        if pc == 0x33B4:
            b = bytes([self.read_byte(self.HL + i) for i in range(5)])
            val = spectrum_5byte_to_float(b)
            self.calc_push(val)
            self.HL = (self.HL + 5) & 0xFFFF
            self.PC = self.pop_word()
            return True

        # 0x2D4F: BC-TO-FP (push 16-bit integer in BC to calc stack)
        if pc == 0x2D4F:
            self.calc_push(float(self.BC))
            self.PC = self.pop_word()
            return True

        # 0x2DA2: FP-TO-BC (pop calc stack into BC)
        if pc == 0x2DA2:
            self.BC = int(round(self.calc_pop())) & 0xFFFF
            self.PC = self.pop_word()
            return True

        # 0x2DE3: PRINT-FP (print float on top of calc stack)
        if pc == 0x2DE3:
            val = self.calc_pop()
            val_str = str(int(val)) if val == int(val) else f"{val:.6g}"
            self.captured_output.append(val_str)
            if self.hook_print_char:
                for ch in val_str:
                    self.hook_print_char(ord(ch))
            self.PC = self.pop_word()
            return True

        return False

    def step(self):
        if self.halted:
            return 4

        # Check ROM hooks / CP/M traps before fetching
        if self.rom_traps_enabled or getattr(self, 'cpm_mode', False) or getattr(self, 'hook_cpm_trap', None) is not None:
            pc = self.PC
            if pc < 0x4000 or (0xFD00 <= pc <= 0xFE33) or pc in (0x5D06, 0x5D51, 0x5D88, 0x81F6, 0x9C4C, 0xFCF7):
                if self.check_rom_hook():
                    return 11

        pc = self.PC
        mem = self.memory
        op = mem[pc]
        self.PC = (pc + 1) & 0xFFFF
        self.R = (self.R & 0x80) | ((self.R + 1) & 0x7F)

        cat = op >> 6

        # Quadrant 1: LD r, r' and HALT
        if cat == 1:
            if op == 0x76:
                self.halted = True
                return 4
            r_dst = (op >> 3) & 7
            r_src = op & 7
            self.set_reg8(r_dst, self.get_reg8(r_src))
            return 7 if (r_dst == 6 or r_src == 6) else 4

        # Quadrant 2: ALU A, r
        if cat == 2:
            alu_op = (op >> 3) & 7
            r_val = self.get_reg8(op & 7)
            self.execute_alu(alu_op, r_val)
            return 7 if (op & 7) == 6 else 4

        # Quadrant 0: Misc, loads, 16-bit ALU, INC/DEC, rotates, jumps
        if cat == 0:
            # NOP
            if op == 0x00:
                return 4

            # LD rr, nn
            if (op & 0xCF) == 0x01:
                rr = (op >> 4) & 3
                val = self.fetch_word()
                self.set_reg16(rr, val)
                return 10

            # LD (BC), A / LD (DE), A
            if op == 0x02: self.write_byte(self.BC, self.A); return 7
            if op == 0x12: self.write_byte(self.DE, self.A); return 7
            # LD A, (BC) / LD A, (DE)
            if op == 0x0A: self.A = self.read_byte(self.BC); return 7
            if op == 0x1A: self.A = self.read_byte(self.DE); return 7

            # LD (nn), HL / LD HL, (nn)
            if op == 0x22: addr = self.fetch_word(); self.write_word(addr, self.HL); return 16
            if op == 0x2A: addr = self.fetch_word(); self.HL = self.read_word(addr); return 16

            # LD (nn), A / LD A, (nn)
            if op == 0x32: addr = self.fetch_word(); self.write_byte(addr, self.A); return 13
            if op == 0x3A: addr = self.fetch_word(); self.A = self.read_byte(addr); return 13

            # INC rr / DEC rr
            if (op & 0xCF) == 0x03:
                rr = (op >> 4) & 3
                self.set_reg16(rr, (self.get_reg16(rr) + 1) & 0xFFFF)
                return 6
            if (op & 0xCF) == 0x0B:
                rr = (op >> 4) & 3
                if rr < 3:
                    cur_pc = self.PC
                    b0 = mem[cur_pc]
                    b1 = mem[(cur_pc + 1) & 0xFFFF]
                    b2 = mem[(cur_pc + 2) & 0xFFFF]
                    b3 = mem[(cur_pc + 3) & 0xFFFF]
                    if b2 == 0x20 and b3 == 0xFB:
                        shift = (op >> 4) * 2
                        if (b0 == 0x78 + shift and b1 == 0xB1 + shift) or (b0 == 0x79 + shift and b1 == 0xB0 + shift):
                            val = self.get_reg16(rr)
                            count = val if val != 0 else 65536
                            if count >= 4:
                                rem_cycles = self.frame_tstates - (self.cycles % self.frame_tstates)
                                max_iters = rem_cycles // 26
                                iters = min(count, max_iters)
                                if iters >= count:
                                    self.set_reg16(rr, 0)
                                    self.A = 0
                                    self.F = 0x44
                                    self.R = (self.R & 0x80) | ((self.R + count * 4) & 0x7F)
                                    self.PC = (cur_pc + 4) & 0xFFFF
                                    return 26 * count - 5
                                elif iters > 0:
                                    rem_val = (count - iters) & 0xFFFF
                                    self.set_reg16(rr, rem_val)
                                    hi = (rem_val >> 8) & 0xFF
                                    lo = rem_val & 0xFF
                                    self.A = hi | lo
                                    res = self.A
                                    self.F = (FLAG_S if res & 0x80 else 0) | PARITY_TABLE[res]
                                    self.R = (self.R & 0x80) | ((self.R + iters * 4) & 0x7F)
                                    self.PC = (cur_pc - 1) & 0xFFFF
                                    return 26 * iters
                self.set_reg16(rr, (self.get_reg16(rr) - 1) & 0xFFFF)
                return 6

            # INC r / DEC r
            if (op & 0xC7) == 0x04:
                r = (op >> 3) & 7
                self.set_reg8(r, self.set_flags_inc8(self.get_reg8(r)))
                return 11 if r == 6 else 4
            if (op & 0xC7) == 0x05:
                r = (op >> 3) & 7
                if op == 0x3D:
                    cur_pc = self.PC
                    if mem[cur_pc & 0xFFFF] == 0x20 and mem[(cur_pc + 1) & 0xFFFF] == 0xFD:
                        a = self.A if self.A != 0 else 256
                        if a >= 4:
                            rem_cycles = self.frame_tstates - (self.cycles % self.frame_tstates)
                            max_iters = rem_cycles // 16
                            iters = min(a, max_iters)
                            if iters >= a:
                                self.A = 0
                                self.F = 0x42 | (self.F & 1)
                                self.R = (self.R & 0x80) | ((self.R + a * 2) & 0x7F)
                                self.PC = (cur_pc + 2) & 0xFFFF
                                return 16 * a - 5
                            elif iters > 0:
                                self.A = (a - iters) & 0xFF
                                self.F = self.set_flags_dec8(self.A + 1)
                                self.R = (self.R & 0x80) | ((self.R + iters * 2) & 0x7F)
                                self.PC = (cur_pc - 1) & 0xFFFF
                                return 16 * iters
                self.set_reg8(r, self.set_flags_dec8(self.get_reg8(r)))
                return 11 if r == 6 else 4

            # LD r, n
            if (op & 0xC7) == 0x06:
                r = (op >> 3) & 7
                val = self.fetch_byte()
                self.set_reg8(r, val)
                return 10 if r == 6 else 7

            # RLCA, RRCA, RLA, RRA
            if op == 0x07: # RLCA
                c = (self.A >> 7) & 1
                self.A = ((self.A << 1) | c) & 0xFF
                self.F = (self.F & ~(FLAG_H | FLAG_N | FLAG_C)) | c
                return 4
            if op == 0x0F: # RRCA
                c = self.A & 1
                self.A = ((self.A >> 1) | (c << 7)) & 0xFF
                self.F = (self.F & ~(FLAG_H | FLAG_N | FLAG_C)) | c
                return 4
            if op == 0x17: # RLA
                old_c = self.F & FLAG_C
                new_c = (self.A >> 7) & 1
                self.A = ((self.A << 1) | old_c) & 0xFF
                self.F = (self.F & ~(FLAG_H | FLAG_N | FLAG_C)) | new_c
                return 4
            if op == 0x1F: # RRA
                old_c = (self.F & FLAG_C) << 7
                new_c = self.A & 1
                self.A = ((self.A >> 1) | old_c) & 0xFF
                self.F = (self.F & ~(FLAG_H | FLAG_N | FLAG_C)) | new_c
                return 4

            # EX AF, AF'
            if op == 0x08:
                self.A, self.A_prime = self.A_prime, self.A
                self.F, self.F_prime = self.F_prime, self.F
                return 4

            # ADD HL, rr
            if (op & 0xCF) == 0x09:
                rr = (op >> 4) & 3
                v1 = self.HL
                v2 = self.get_reg16(rr)
                res = v1 + v2
                flags = self.F & (FLAG_S | FLAG_Z | FLAG_PV)
                if (v1 & 0x0FFF) + (v2 & 0x0FFF) > 0x0FFF: flags |= FLAG_H
                if res > 0xFFFF: flags |= FLAG_C
                self.F = flags
                self.HL = res & 0xFFFF
                return 11

            # JR e
            if op == 0x18:
                offset = self.fetch_byte()
                disp = offset if offset < 128 else offset - 256
                self.PC = (self.PC + disp) & 0xFFFF
                return 12

            # JR cc, e
            if (op & 0xE7) == 0x20:
                cc = (op >> 3) & 3
                offset = self.fetch_byte()
                disp = offset if offset < 128 else offset - 256
                if self.test_cond(cc):
                    self.PC = (self.PC + disp) & 0xFFFF
                    return 12
                return 7

            # DJNZ e
            if op == 0x10:
                cur_pc = self.PC
                offset = mem[cur_pc]
                if offset == 0xFE:
                    b = self.B if self.B != 0 else 256
                    if b >= 4:
                        rem_cycles = self.frame_tstates - (self.cycles % self.frame_tstates)
                        max_iters = rem_cycles // 13
                        iters = min(b, max_iters)
                        if iters >= b:
                            self.B = 0
                            self.R = (self.R & 0x80) | ((self.R + b) & 0x7F)
                            self.PC = (cur_pc + 1) & 0xFFFF
                            return 13 * b - 5
                        elif iters > 0:
                            self.B = (b - iters) & 0xFF
                            self.R = (self.R & 0x80) | ((self.R + iters) & 0x7F)
                            self.PC = (cur_pc - 1) & 0xFFFF
                            return 13 * iters
                self.PC = (cur_pc + 1) & 0xFFFF
                disp = offset if offset < 128 else offset - 256
                self.B = (self.B - 1) & 0xFF
                if self.B != 0:
                    self.PC = (self.PC + disp) & 0xFFFF
                    return 13
                return 8

            # DAA, CPL, SCF, CCF
            if op == 0x27: # DAA
                a = self.A
                correction = 0
                carry = self.F & FLAG_C
                h = self.F & FLAG_H
                n = self.F & FLAG_N
                if h or (not n and (a & 0x0F) > 9): correction |= 0x06
                if carry or (not n and a > 0x99):
                    correction |= 0x60
                    carry = FLAG_C
                a = (a - correction) & 0xFF if n else (a + correction) & 0xFF
                flags = n | carry
                if a & 0x80: flags |= FLAG_S
                if a == 0: flags |= FLAG_Z
                flags |= PARITY_TABLE[a]
                self.A = a
                self.F = flags
                return 4
            if op == 0x2F: # CPL
                self.A ^= 0xFF
                self.F |= (FLAG_H | FLAG_N)
                return 4
            if op == 0x37: # SCF
                self.F = (self.F & ~(FLAG_H | FLAG_N)) | FLAG_C
                return 4
            if op == 0x3F: # CCF
                old_c = self.F & FLAG_C
                h = FLAG_H if old_c else 0
                self.F = (self.F & ~(FLAG_H | FLAG_N | FLAG_C)) | h | (FLAG_C if not old_c else 0)
                return 4

        # Quadrant 3: RET, CALL, JP, RST, PUSH, POP, Prefixes

        # RET cc
        if (op & 0xC7) == 0xC0:
            cc = (op >> 3) & 7
            if self.test_cond(cc):
                self.PC = self.pop_word()
                return 11
            return 5

        # POP rr
        if (op & 0xCF) == 0xC1:
            rr = (op >> 4) & 3
            val = self.pop_word()
            if rr == 0: self.BC = val
            elif rr == 1: self.DE = val
            elif rr == 2: self.HL = val
            elif rr == 3: self.AF = val
            return 10

        # JP cc, nn
        if (op & 0xC7) == 0xC2:
            cc = (op >> 3) & 7
            target = self.fetch_word()
            if self.test_cond(cc):
                self.PC = target
            return 10

        # JP nn
        if op == 0xC3:
            self.PC = self.fetch_word()
            return 10

        # CALL cc, nn
        if (op & 0xC7) == 0xC4:
            cc = (op >> 3) & 7
            target = self.fetch_word()
            if self.test_cond(cc):
                self.push_word(self.PC)
                self.PC = target
                return 17
            return 10

        # PUSH rr
        if (op & 0xCF) == 0xC5:
            rr = (op >> 4) & 3
            if rr == 0: val = self.BC
            elif rr == 1: val = self.DE
            elif rr == 2: val = self.HL
            elif rr == 3: val = self.AF
            self.push_word(val)
            return 11

        # ALU A, n (immediate)
        if (op & 0xC7) == 0xC6:
            alu_op = (op >> 3) & 7
            val = self.fetch_byte()
            self.execute_alu(alu_op, val)
            return 7

        # RST p
        if (op & 0xC7) == 0xC7:
            p = op & 0x38
            if p == 0x08 and globals().get('spectrum_mode', '48K') == 'NEXT':
                fn_code = self.fetch_byte()
                if fn_code >= 0x80:
                    handle_nextzxos_esxdos_hook(self, fn_code)
                    return 11
                else:
                    self.PC = (self.PC - 1) & 0xFFFF
            self.push_word(self.PC)
            self.PC = p
            return 11

        # RET
        if op == 0xC9:
            self.PC = self.pop_word()
            return 10

        # CALL nn
        if op == 0xCD:
            target = self.fetch_word()
            self.push_word(self.PC)
            self.PC = target
            return 17

        # EXX
        if op == 0xD9:
            self.B, self.B_prime = self.B_prime, self.B
            self.C, self.C_prime = self.C_prime, self.C
            self.D, self.D_prime = self.D_prime, self.D
            self.E, self.E_prime = self.E_prime, self.E
            self.H, self.H_prime = self.H_prime, self.H
            self.L, self.L_prime = self.L_prime, self.L
            return 4

        # JP (HL)
        if op == 0xE9:
            self.PC = self.HL
            return 4

        # EX (SP), HL
        if op == 0xE3:
            val = self.read_word(self.SP)
            self.write_word(self.SP, self.HL)
            self.HL = val
            return 19

        # EX DE, HL
        if op == 0xEB:
            self.D, self.H = self.H, self.D
            self.E, self.L = self.L, self.E
            return 4

        # DI / EI
        if op == 0xF3: self.IFF1 = False; self.IFF2 = False; return 4
        if op == 0xFB: self.IFF1 = True; self.IFF2 = True; return 4

        # LD SP, HL
        if op == 0xF9:
            self.SP = self.HL
            return 6

        # IN A, (n) / OUT (n), A
        if op == 0xDB:
            port = self.fetch_byte()
            self.A = int(self.in_port(port | (self.A << 8))) & 0xFF
            return 11
        if op == 0xD3:
            port = self.fetch_byte()
            self.out_port(port | (self.A << 8), self.A)
            return 11

        # Prefixes: CB, ED, DD, FD
        if op == 0xCB:
            return self.step_cb()
        if op == 0xED:
            return self.step_ed()
        if op == 0xDD:
            return self.step_indexed("IX")
        if op == 0xFD:
            return self.step_indexed("IY")

        return 4

    def execute_alu(self, alu_op, val):
        if alu_op == 0: self.A = self.set_flags_add8(self.A, val)
        elif alu_op == 1: self.A = self.set_flags_add8(self.A, val, self.F & FLAG_C)
        elif alu_op == 2: self.A = self.set_flags_sub8(self.A, val)
        elif alu_op == 3: self.A = self.set_flags_sub8(self.A, val, self.F & FLAG_C)
        elif alu_op == 4: self.A = self.set_flags_logic8(self.A & val, is_and=True)
        elif alu_op == 5: self.A = self.set_flags_logic8(self.A ^ val)
        elif alu_op == 6: self.A = self.set_flags_logic8(self.A | val)
        elif alu_op == 7: self.set_flags_sub8(self.A, val) # CP

    # CB prefix instructions
    def step_cb(self):
        op = self.fetch_byte()
        self.R = (self.R & 0x80) | ((self.R + 1) & 0x7F)
        r = op & 7
        val = self.get_reg8(r)
        cat = (op >> 6) & 3
        bit_idx = (op >> 3) & 7

        if cat == 0: # Rotates & Shifts
            sub_op = (op >> 3) & 7
            if sub_op == 0: # RLC
                c = (val >> 7) & 1
                res = ((val << 1) | c) & 0xFF
                flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
            elif sub_op == 1: # RRC
                c = val & 1
                res = ((val >> 1) | (c << 7)) & 0xFF
                flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
            elif sub_op == 2: # RL
                old_c = self.F & FLAG_C
                c = (val >> 7) & 1
                res = ((val << 1) | old_c) & 0xFF
                flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
            elif sub_op == 3: # RR
                old_c = (self.F & FLAG_C) << 7
                c = val & 1
                res = ((val >> 1) | old_c) & 0xFF
                flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
            elif sub_op == 4: # SLA
                c = (val >> 7) & 1
                res = (val << 1) & 0xFF
                flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
            elif sub_op == 5: # SRA
                c = val & 1
                res = ((val >> 1) | (val & 0x80)) & 0xFF
                flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
            elif sub_op == 6: # SLL
                c = (val >> 7) & 1
                res = ((val << 1) | 1) & 0xFF
                flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
            elif sub_op == 7: # SRL
                c = val & 1
                res = (val >> 1) & 0xFF
                flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
            self.F = flags
            self.set_reg8(r, res)
            return 15 if r == 6 else 8

        elif cat == 1: # BIT
            bit_val = (val >> bit_idx) & 1
            flags = (self.F & FLAG_C) | FLAG_H
            if bit_val == 0: flags |= (FLAG_Z | FLAG_PV)
            if bit_idx == 7 and bit_val: flags |= FLAG_S
            self.F = flags
            return 12 if r == 6 else 8

        elif cat == 2: # RES
            res = val & ~(1 << bit_idx)
            self.set_reg8(r, res)
            return 15 if r == 6 else 8

        elif cat == 3: # SET
            res = val | (1 << bit_idx)
            self.set_reg8(r, res)
            return 15 if r == 6 else 8

        return 8

    # ED prefix instructions
    def step_ed(self):
        op = self.fetch_byte()
        self.R = (self.R & 0x80) | ((self.R + 1) & 0x7F)

        # IN r, (C)
        if (op & 0xC7) == 0x40:
            r = (op >> 3) & 7
            val = int(self.in_port(self.BC)) & 0xFF
            if r != 6:
                self.set_reg8(r, val)
            flags = (self.F & FLAG_C)
            if val & 0x80: flags |= FLAG_S
            if val == 0: flags |= FLAG_Z
            flags |= PARITY_TABLE[val]
            self.F = flags
            return 12

        # OUT (C), r
        if (op & 0xC7) == 0x41:
            r = (op >> 3) & 7
            val = 0 if r == 6 else self.get_reg8(r)
            self.out_port(self.BC, val)
            return 12

        # Block instructions
        if op == 0xB0: # LDIR
            hl = self.HL
            de = self.DE
            bc = self.BC
            cyc = 0
            iters = 0
            while bc > 0:
                val = self.read_byte(hl)
                self.write_byte(de, val)
                hl = (hl + 1) & 0xFFFF
                de = (de + 1) & 0xFFFF
                bc = (bc - 1) & 0xFFFF
                cyc += 21
                iters += 1
                if cyc >= 4200:
                    break
            self.HL = hl
            self.DE = de
            self.BC = bc
            if iters > 1:
                self.R = (self.R & 0x80) | ((self.R + (iters - 1) * 2) & 0x7F)
            self.F &= ~(FLAG_H | FLAG_PV | FLAG_N)
            if bc != 0:
                self.F |= FLAG_PV
                self.PC = (self.PC - 2) & 0xFFFF # repeat
                return cyc
            return cyc - 5

        if op == 0xA0: # LDI
            val = self.read_byte(self.HL)
            self.write_byte(self.DE, val)
            self.HL = (self.HL + 1) & 0xFFFF
            self.DE = (self.DE + 1) & 0xFFFF
            self.BC = (self.BC - 1) & 0xFFFF
            self.F &= ~(FLAG_H | FLAG_PV | FLAG_N)
            if self.BC != 0: self.F |= FLAG_PV
            return 16

        if op == 0xA8: # LDD
            val = self.read_byte(self.HL)
            self.write_byte(self.DE, val)
            self.HL = (self.HL - 1) & 0xFFFF
            self.DE = (self.DE - 1) & 0xFFFF
            self.BC = (self.BC - 1) & 0xFFFF
            self.F &= ~(FLAG_H | FLAG_PV | FLAG_N)
            if self.BC != 0: self.F |= FLAG_PV
            return 16

        if op == 0xB8: # LDDR
            hl = self.HL
            de = self.DE
            bc = self.BC
            cyc = 0
            iters = 0
            while bc > 0:
                val = self.read_byte(hl)
                self.write_byte(de, val)
                hl = (hl - 1) & 0xFFFF
                de = (de - 1) & 0xFFFF
                bc = (bc - 1) & 0xFFFF
                cyc += 21
                iters += 1
                if cyc >= 4200:
                    break
            self.HL = hl
            self.DE = de
            self.BC = bc
            if iters > 1:
                self.R = (self.R & 0x80) | ((self.R + (iters - 1) * 2) & 0x7F)
            self.F &= ~(FLAG_H | FLAG_PV | FLAG_N)
            if bc != 0:
                self.F |= FLAG_PV
                self.PC = (self.PC - 2) & 0xFFFF # repeat
                return cyc
            return cyc - 5

        if op == 0xA1: # CPI
            val = self.read_byte(self.HL)
            res = (self.A - val) & 0xFF
            flags = (self.F & FLAG_C) | FLAG_N
            if res == 0: flags |= FLAG_Z
            if res & 0x80: flags |= FLAG_S
            if (self.A & 0x0F) < (val & 0x0F): flags |= FLAG_H
            self.HL = (self.HL + 1) & 0xFFFF
            self.BC = (self.BC - 1) & 0xFFFF
            if self.BC != 0: flags |= FLAG_PV
            self.F = flags
            return 16

        if op == 0xB1: # CPIR
            val = self.read_byte(self.HL)
            res = (self.A - val) & 0xFF
            flags = (self.F & FLAG_C) | FLAG_N
            if res == 0: flags |= FLAG_Z
            if res & 0x80: flags |= FLAG_S
            if (self.A & 0x0F) < (val & 0x0F): flags |= FLAG_H
            self.HL = (self.HL + 1) & 0xFFFF
            self.BC = (self.BC - 1) & 0xFFFF
            if self.BC != 0: flags |= FLAG_PV
            self.F = flags
            if self.BC != 0 and res != 0:
                self.PC = (self.PC - 2) & 0xFFFF # repeat
                return 21
            return 16

        if op == 0xA9: # CPD
            val = self.read_byte(self.HL)
            res = (self.A - val) & 0xFF
            flags = (self.F & FLAG_C) | FLAG_N
            if res == 0: flags |= FLAG_Z
            if res & 0x80: flags |= FLAG_S
            if (self.A & 0x0F) < (val & 0x0F): flags |= FLAG_H
            self.HL = (self.HL - 1) & 0xFFFF
            self.BC = (self.BC - 1) & 0xFFFF
            if self.BC != 0: flags |= FLAG_PV
            self.F = flags
            return 16

        if op == 0xB9: # CPDR
            val = self.read_byte(self.HL)
            res = (self.A - val) & 0xFF
            flags = (self.F & FLAG_C) | FLAG_N
            if res == 0: flags |= FLAG_Z
            if res & 0x80: flags |= FLAG_S
            if (self.A & 0x0F) < (val & 0x0F): flags |= FLAG_H
            self.HL = (self.HL - 1) & 0xFFFF
            self.BC = (self.BC - 1) & 0xFFFF
            if self.BC != 0: flags |= FLAG_PV
            self.F = flags
            if self.BC != 0 and res != 0:
                self.PC = (self.PC - 2) & 0xFFFF # repeat
                return 21
            return 16

        # LD (nn), rr / LD rr, (nn)
        if (op & 0xCF) == 0x43:
            rr = (op >> 4) & 3
            addr = self.fetch_word()
            self.write_word(addr, self.get_reg16(rr))
            return 20
        if (op & 0xCF) == 0x4B:
            rr = (op >> 4) & 3
            addr = self.fetch_word()
            self.set_reg16(rr, self.read_word(addr))
            return 20

        # RRD / RLD (BCD digit rotate)
        if op == 0x67: # RRD
            val = self.read_byte(self.HL)
            new_hl = ((self.A & 0x0F) << 4) | ((val >> 4) & 0x0F)
            self.write_byte(self.HL, new_hl)
            self.A = (self.A & 0xF0) | (val & 0x0F)
            flags = (self.F & FLAG_C)
            if self.A & 0x80: flags |= FLAG_S
            if self.A == 0: flags |= FLAG_Z
            flags |= PARITY_TABLE[self.A]
            self.F = flags
            return 18

        if op == 0x6F: # RLD
            val = self.read_byte(self.HL)
            new_hl = ((val << 4) & 0xF0) | (self.A & 0x0F)
            self.write_byte(self.HL, new_hl)
            self.A = (self.A & 0xF0) | ((val >> 4) & 0x0F)
            flags = (self.F & FLAG_C)
            if self.A & 0x80: flags |= FLAG_S
            if self.A == 0: flags |= FLAG_Z
            flags |= PARITY_TABLE[self.A]
            self.F = flags
            return 18

        # Block I/O: INI, INIR, IND, INDR
        if op == 0xA2: # INI
            val = int(self.in_port(self.BC)) & 0xFF
            self.write_byte(self.HL, val)
            self.HL = (self.HL + 1) & 0xFFFF
            self.B = (self.B - 1) & 0xFF
            flags = (self.F & FLAG_C) | FLAG_N
            if self.B == 0: flags |= FLAG_Z
            if self.B & 0x80: flags |= FLAG_S
            self.F = flags
            return 16

        if op == 0xB2: # INIR
            val = int(self.in_port(self.BC)) & 0xFF
            self.write_byte(self.HL, val)
            self.HL = (self.HL + 1) & 0xFFFF
            self.B = (self.B - 1) & 0xFF
            flags = (self.F & FLAG_C) | FLAG_N
            if self.B == 0: flags |= FLAG_Z
            if self.B & 0x80: flags |= FLAG_S
            self.F = flags
            if self.B != 0:
                self.PC = (self.PC - 2) & 0xFFFF
                return 21
            return 16

        if op == 0xAA: # IND
            val = int(self.in_port(self.BC)) & 0xFF
            self.write_byte(self.HL, val)
            self.HL = (self.HL - 1) & 0xFFFF
            self.B = (self.B - 1) & 0xFF
            flags = (self.F & FLAG_C) | FLAG_N
            if self.B == 0: flags |= FLAG_Z
            if self.B & 0x80: flags |= FLAG_S
            self.F = flags
            return 16

        if op == 0xBA: # INDR
            val = int(self.in_port(self.BC)) & 0xFF
            self.write_byte(self.HL, val)
            self.HL = (self.HL - 1) & 0xFFFF
            self.B = (self.B - 1) & 0xFF
            flags = (self.F & FLAG_C) | FLAG_N
            if self.B == 0: flags |= FLAG_Z
            if self.B & 0x80: flags |= FLAG_S
            self.F = flags
            if self.B != 0:
                self.PC = (self.PC - 2) & 0xFFFF
                return 21
            return 16

        # Block I/O: OUTI, OTIR, OUTD, OTDR
        if op == 0xA3: # OUTI
            val = self.read_byte(self.HL)
            self.B = (self.B - 1) & 0xFF
            self.out_port(self.BC, val)
            self.HL = (self.HL + 1) & 0xFFFF
            flags = (self.F & FLAG_C) | FLAG_N
            if self.B == 0: flags |= FLAG_Z
            if self.B & 0x80: flags |= FLAG_S
            self.F = flags
            return 16

        if op == 0xB3: # OTIR
            val = self.read_byte(self.HL)
            self.B = (self.B - 1) & 0xFF
            self.out_port(self.BC, val)
            self.HL = (self.HL + 1) & 0xFFFF
            flags = (self.F & FLAG_C) | FLAG_N
            if self.B == 0: flags |= FLAG_Z
            if self.B & 0x80: flags |= FLAG_S
            self.F = flags
            if self.B != 0:
                self.PC = (self.PC - 2) & 0xFFFF
                return 21
            return 16

        if op == 0xAB: # OUTD
            val = self.read_byte(self.HL)
            self.B = (self.B - 1) & 0xFF
            self.out_port(self.BC, val)
            self.HL = (self.HL - 1) & 0xFFFF
            flags = (self.F & FLAG_C) | FLAG_N
            if self.B == 0: flags |= FLAG_Z
            if self.B & 0x80: flags |= FLAG_S
            self.F = flags
            return 16

        if op == 0xBB: # OTDR
            val = self.read_byte(self.HL)
            self.B = (self.B - 1) & 0xFF
            self.out_port(self.BC, val)
            self.HL = (self.HL - 1) & 0xFFFF
            flags = (self.F & FLAG_C) | FLAG_N
            if self.B == 0: flags |= FLAG_Z
            if self.B & 0x80: flags |= FLAG_S
            self.F = flags
            if self.B != 0:
                self.PC = (self.PC - 2) & 0xFFFF
                return 21
            return 16

        # NEG (with standard silicon aliases)
        if op in (0x44, 0x4C, 0x54, 0x5C, 0x64, 0x6C, 0x74, 0x7C):
            self.A = self.set_flags_sub8(0, self.A)
            return 8

        # RETI / RETN (with silicon aliases)
        if op in (0x45, 0x4D, 0x55, 0x5D, 0x65, 0x6D, 0x75, 0x7D):
            self.IFF1 = self.IFF2
            self.PC = self.pop_word()
            return 14

        # IM 0/1/2 (with silicon aliases)
        if op in (0x46, 0x66, 0x4E, 0x6E): self.IM = 0; return 8
        if op in (0x56, 0x76): self.IM = 1; return 8
        if op in (0x5E, 0x7E): self.IM = 2; return 8

        # LD A, I / LD A, R (sets S, Z, H=0, P/V=IFF2, N=0, preserves C)
        if op == 0x57:
            self.A = self.I
            flags = (self.F & FLAG_C)
            if self.A & 0x80: flags |= FLAG_S
            if self.A == 0: flags |= FLAG_Z
            if self.IFF2: flags |= FLAG_PV
            self.F = flags
            return 9
        if op == 0x5F:
            self.A = self.R
            flags = (self.F & FLAG_C)
            if self.A & 0x80: flags |= FLAG_S
            if self.A == 0: flags |= FLAG_Z
            if self.IFF2: flags |= FLAG_PV
            self.F = flags
            return 9
        if op == 0x47: self.I = self.A; return 9
        if op == 0x4F: self.R = self.A; return 9

        # ADC HL, rr / SBC HL, rr
        if (op & 0xCF) == 0x4A: # ADC HL, rr
            rr = (op >> 4) & 3
            v1 = self.HL
            v2 = self.get_reg16(rr)
            c = self.F & FLAG_C
            res = v1 + v2 + c
            flags = 0
            if res & 0x8000: flags |= FLAG_S
            if (res & 0xFFFF) == 0: flags |= FLAG_Z
            if (v1 & 0x0FFF) + (v2 & 0x0FFF) + c > 0x0FFF: flags |= FLAG_H
            if ((v1 ^ res) & (v2 ^ res) & 0x8000): flags |= FLAG_PV
            if res > 0xFFFF: flags |= FLAG_C
            self.F = flags
            self.HL = res & 0xFFFF
            return 15

        if (op & 0xCF) == 0x42: # SBC HL, rr
            rr = (op >> 4) & 3
            v1 = self.HL
            v2 = self.get_reg16(rr)
            c = self.F & FLAG_C
            res = v1 - v2 - c
            flags = FLAG_N
            if res & 0x8000: flags |= FLAG_S
            if (res & 0xFFFF) == 0: flags |= FLAG_Z
            if (v1 & 0x0FFF) - (v2 & 0x0FFF) - c < 0: flags |= FLAG_H
            if ((v1 ^ v2) & (v1 ^ res) & 0x8000): flags |= FLAG_PV
            if res < 0: flags |= FLAG_C
            self.F = flags
            self.HL = res & 0xFFFF
            return 15

        return 8

    # Indexed DD / FD instructions
    def step_indexed(self, reg_name):
        reg_val = self.IX if reg_name == "IX" else self.IY
        op = self.fetch_byte()
        self.R = (self.R & 0x80) | ((self.R + 1) & 0x7F)

        # DDCB / FDCB: Bit / Shift instructions
        if op == 0xCB:
            self.R = (self.R & 0x80) | ((self.R + 1) & 0x7F)
            d_raw = self.fetch_byte()
            disp = d_raw if d_raw < 128 else d_raw - 256
            target_addr = (reg_val + disp) & 0xFFFF
            cb_op = self.fetch_byte()

            val = self.read_byte(target_addr)
            cat = (cb_op >> 6) & 3
            bit_idx = (cb_op >> 3) & 7
            r = cb_op & 7

            if cat == 0:  # Rotates & Shifts
                sub_op = (cb_op >> 3) & 7
                if sub_op == 0:  # RLC
                    c = (val >> 7) & 1
                    res = ((val << 1) | c) & 0xFF
                    flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
                elif sub_op == 1:  # RRC
                    c = val & 1
                    res = ((val >> 1) | (c << 7)) & 0xFF
                    flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
                elif sub_op == 2:  # RL
                    old_c = self.F & FLAG_C
                    c = (val >> 7) & 1
                    res = ((val << 1) | old_c) & 0xFF
                    flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
                elif sub_op == 3:  # RR
                    old_c = (self.F & FLAG_C) << 7
                    c = val & 1
                    res = ((val >> 1) | old_c) & 0xFF
                    flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
                elif sub_op == 4:  # SLA
                    c = (val >> 7) & 1
                    res = (val << 1) & 0xFF
                    flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
                elif sub_op == 5:  # SRA
                    c = val & 1
                    res = ((val >> 1) | (val & 0x80)) & 0xFF
                    flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
                elif sub_op == 6:  # SLL
                    c = (val >> 7) & 1
                    res = ((val << 1) | 1) & 0xFF
                    flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
                elif sub_op == 7:  # SRL
                    c = val & 1
                    res = (val >> 1) & 0xFF
                    flags = c | (FLAG_S if res & 0x80 else 0) | (FLAG_Z if res == 0 else 0) | PARITY_TABLE[res]
                self.F = flags
                self.write_byte(target_addr, res)
                if r != 6:
                    self.set_reg8(r, res)
                return 23

            elif cat == 1:  # BIT
                bit_val = (val >> bit_idx) & 1
                flags = (self.F & FLAG_C) | FLAG_H
                if bit_val == 0: flags |= (FLAG_Z | FLAG_PV)
                if bit_idx == 7 and bit_val: flags |= FLAG_S
                self.F = flags
                return 20

            elif cat == 2:  # RES
                res = val & ~(1 << bit_idx)
                self.write_byte(target_addr, res)
                if r != 6:
                    self.set_reg8(r, res)
                return 23

            elif cat == 3:  # SET
                res = val | (1 << bit_idx)
                self.write_byte(target_addr, res)
                if r != 6:
                    self.set_reg8(r, res)
                return 23

        # ADD IX/IY, rr
        if (op & 0xCF) == 0x09:
            rr = (op >> 4) & 3
            v1 = reg_val
            v2 = self.BC if rr == 0 else self.DE if rr == 1 else reg_val if rr == 2 else self.SP
            res = v1 + v2
            flags = self.F & (FLAG_S | FLAG_Z | FLAG_PV)
            if (v1 & 0x0FFF) + (v2 & 0x0FFF) > 0x0FFF: flags |= FLAG_H
            if res > 0xFFFF: flags |= FLAG_C
            self.F = flags
            res &= 0xFFFF
            if reg_name == "IX": self.IX = res
            else: self.IY = res
            return 15

        # LD IX/IY, nn
        if op == 0x21:
            val = self.fetch_word()
            if reg_name == "IX": self.IX = val
            else: self.IY = val
            return 14

        # LD (nn), IX/IY
        if op == 0x22:
            addr = self.fetch_word()
            self.write_word(addr, reg_val)
            return 20

        # LD IX/IY, (nn)
        if op == 0x2A:
            addr = self.fetch_word()
            val = self.read_word(addr)
            if reg_name == "IX": self.IX = val
            else: self.IY = val
            return 20

        # INC IX/IY / DEC IX/IY
        if op == 0x23:
            if reg_name == "IX": self.IX = (self.IX + 1) & 0xFFFF
            else: self.IY = (self.IY + 1) & 0xFFFF
            return 10
        if op == 0x2B:
            if reg_name == "IX": self.IX = (self.IX - 1) & 0xFFFF
            else: self.IY = (self.IY - 1) & 0xFFFF
            return 10

        # PUSH IX/IY / POP IX/IY
        if op == 0xE5: self.push_word(reg_val); return 15
        if op == 0xE1:
            val = self.pop_word()
            if reg_name == "IX": self.IX = val
            else: self.IY = val
            return 14

        # JP (IX) / JP (IY)
        if op == 0xE9:
            self.PC = reg_val
            return 8

        # EX (SP), IX/IY
        if op == 0xE3:
            val = self.read_word(self.SP)
            self.write_word(self.SP, reg_val)
            if reg_name == "IX": self.IX = val
            else: self.IY = val
            return 23

        # LD SP, IX/IY
        if op == 0xF9:
            self.SP = reg_val
            return 10

        # Displaced operations (IX+d) / (IY+d)
        is_displaced = (
            op in (0x34, 0x35, 0x36) or
            ((op & 0xC7) == 0x46 and op != 0x76) or
            ((op & 0xF8) == 0x70) or
            ((op & 0xC7) == 0x86)
        )
        if is_displaced:
            d_raw = self.fetch_byte()
            disp = d_raw if d_raw < 128 else d_raw - 256
            target_addr = (reg_val + disp) & 0xFFFF

            # LD (IX+d), n
            if op == 0x36:
                n = self.fetch_byte()
                self.write_byte(target_addr, n)
                return 19

            # LD r, (IX+d)
            if (op & 0xC7) == 0x46:
                r = (op >> 3) & 7
                self.set_reg8(r, self.read_byte(target_addr))
                return 19

            # LD (IX+d), r
            if (op & 0xF8) == 0x70:
                r = op & 7
                self.write_byte(target_addr, self.get_reg8(r))
                return 19

            # INC (IX+d) / DEC (IX+d)
            if op == 0x34:
                v = self.read_byte(target_addr)
                self.write_byte(target_addr, self.set_flags_inc8(v))
                return 23
            if op == 0x35:
                v = self.read_byte(target_addr)
                self.write_byte(target_addr, self.set_flags_dec8(v))
                return 23

            # ALU A, (IX+d)
            if (op & 0xC7) == 0x86:
                alu_op = (op >> 3) & 7
                v = self.read_byte(target_addr)
                self.execute_alu(alu_op, v)
                return 19

        # Half-registers: IXH, IXL, IYH, IYL
        def get_idx_half(r):
            cur = self.IX if reg_name == "IX" else self.IY
            if r == 4: return (cur >> 8) & 0xFF
            if r == 5: return cur & 0xFF
            return self.get_reg8(r)

        def set_idx_half(r, val):
            val &= 0xFF
            cur = self.IX if reg_name == "IX" else self.IY
            if r == 4:
                res = (val << 8) | (cur & 0xFF)
            elif r == 5:
                res = (cur & 0xFF00) | val
            else:
                self.set_reg8(r, val)
                return
            if reg_name == "IX": self.IX = res
            else: self.IY = res

        # INC / DEC half-registers (0x24, 0x25, 0x2C, 0x2D)
        if op == 0x24: set_idx_half(4, self.set_flags_inc8(get_idx_half(4))); return 8
        if op == 0x25: set_idx_half(4, self.set_flags_dec8(get_idx_half(4))); return 8
        if op == 0x2C: set_idx_half(5, self.set_flags_inc8(get_idx_half(5))); return 8
        if op == 0x2D: set_idx_half(5, self.set_flags_dec8(get_idx_half(5))); return 8

        # LD half-register immediate (0x26, 0x2E)
        if op == 0x26: set_idx_half(4, self.fetch_byte()); return 11
        if op == 0x2E: set_idx_half(5, self.fetch_byte()); return 11

        # LD r, r' where r or r' is IXH/IXL (0x40..0x7F, not HALT 0x76, not displaced r=6 or r'=6)
        if (op & 0xC0) == 0x40 and op != 0x76:
            r_dst = (op >> 3) & 7
            r_src = op & 7
            if r_dst != 6 and r_src != 6 and (r_dst in (4, 5) or r_src in (4, 5)):
                set_idx_half(r_dst, get_idx_half(r_src))
                return 8

        # ALU A, r where r is IXH/IXL (0x80..0xBF, not displaced r=6)
        if (op & 0xC0) == 0x80:
            alu_op = (op >> 3) & 7
            r_src = op & 7
            if r_src in (4, 5):
                self.execute_alu(alu_op, get_idx_half(r_src))
                return 8

        # Fallback for opcodes that do not use index registers under DD/FD prefix
        self.PC = (self.PC - 1) & 0xFFFF
        return 4 + self.step()

    # Interrupt handling
    def interrupt(self, data=0xFF):
        if not self.IFF1:
            return False
        is_bb = (getattr(self, 'memory', None) is not None and len(self.memory) > 0xA205 and self.memory[0xA200:0xA205] == b'\xf6@\x12\x18\x17')
        is_dinamic_blit = (getattr(self, 'memory', None) is not None and len(self.memory) > 0x7FE3 and self.memory[0x7FE0:0x7FE3] == b'\xE3\x7F\xC9' and 0x7FE0 <= self.PC <= 0x8045)
        if is_bb and getattr(self, 'IM', 1) == 2:
            is_safe_stack = (0x9600 <= self.SP <= 0x9700)
            if not is_safe_stack or (0xA3A0 <= self.PC <= 0xA835) or (0xB9E0 <= self.PC <= 0xC000):
                return False
        if is_dinamic_blit:
            return False
        if self.halted:
            self.halted = False
        self.IFF1 = False
        self.IFF2 = False
        self.push_word(self.PC)
        if self.IM in (0, 1):
            self.PC = 0x0038
        elif self.IM == 2:
            vec_addr = ((self.I << 8) | (data & 0xFF)) & 0xFFFF
            self.PC = self.read_word(vec_addr)
        return True

    def nmi(self):
        self.IFF1 = False
        if self.halted:
            self.halted = False
        self.push_word(self.PC)
        self.PC = 0x0066
        return True

    # I/O handling
    def in_port(self, port):
        if self.hook_port_in:
            return int(self.hook_port_in(port)) & 0xFF
        # Port 0xFE keyboard matrix emulation
        # Active low: 0xFF if no key pressed
        return 0xFF

    def out_port(self, port, val):
        if self.hook_port_out:
            self.hook_port_out(port, val)

    def write_port(self, port, val):
        self.out_port(port, val)

    def read_port(self, port):
        return self.in_port(port)

    def run(self, max_instructions=None, stop_on_ret=True):
        global current_running_engine
        self.is_running = True
        prev_engine = current_running_engine if 'current_running_engine' in globals() else "NORMAL"
        current_running_engine = "Z80"
        try:
            return self._run_internal(max_instructions=max_instructions, stop_on_ret=stop_on_ret)
        finally:
            self.is_running = False
            current_running_engine = prev_engine

    def _run_internal(self, max_instructions=None, stop_on_ret=True):
        global canvas_dirty, screen_bitmap_dirty
        count = 0
        init_sp = self.SP
        is_headless = os.environ.get("SDL_VIDEODRIVER") == "dummy"
        safety_limit = 1000000 if is_headless and max_instructions is None else max_instructions
        last_frame_ticks = pygame.time.get_ticks() if ('pygame' in globals() and pygame.get_init()) else 0
        frame_tstates = getattr(self, 'frame_tstates', 70930 if getattr(self, 'plus3_mode', False) else 69888)
        cycles_since_int = 0
        while (safety_limit is None or count < safety_limit):
            if getattr(self, 'suspended_by_break', False):
                break
            if self.halted:
                if self.IFF1:
                    rem = frame_tstates - cycles_since_int
                    if rem > 0:
                        self.cycles += rem
                        cycles_since_int += rem
                    else:
                        cycles_since_int += 4
                        self.cycles += 4
                    count += 1
                else:
                    break
            if count > 0 and self.PC in self.breakpoints:
                self.breakpoint_hit = self.PC
                if 'get_crystal_monitor' in globals():
                    try:
                        get_crystal_monitor().on_breakpoint(self.breakpoint_hit)
                    except Exception:
                        pass
                break
            # Dinamic loader wait-for-key loop at 0xFDA9 (Army Moves, Game Over, Phantis, etc.)
            # 0xFDA9: CALL 0x028E; INC E; JR Z, 0xFDA9; JP 0xFF7A
            if self.PC == 0xFDA9 and self.read_byte(0xFDA9) == 0xCD and self.read_word(0xFDAA) == 0x028E:
                self._at_dinamic_wait = True
            elif self.PC in (0xFDAF, 0xFF7A, 0x5B00, 0xCD14):
                self._at_dinamic_wait = False
                self._dinamic_wait_frames = 0

            if stop_on_ret:
                op = self.read_byte(self.PC)
                if op == 0xC9 and self.SP >= init_sp:
                    if self.read_word(self.SP) == 0:
                        cyc = self.step()
                        self.cycles += cyc
                        count += 1
                        break
                elif (op & 0xC7) == 0xC0 and self.SP >= init_sp:
                    cc = (op >> 3) & 7
                    if self.test_cond(cc):
                        if self.read_word(self.SP) == 0:
                            cyc = self.step()
                            self.cycles += cyc
                            count += 1
                            break
            cyc = self.step()
            if self.contention_enabled:
                cyc += self.contend_memory(self.PC)
            self.cycles += cyc
            cycles_since_int += cyc
            count += 1

            while cycles_since_int >= frame_tstates:
                is_bb = (getattr(self, 'memory', None) is not None and len(self.memory) > 0xA205 and self.memory[0xA200:0xA205] == b'\xf6@\x12\x18\x17')
                is_dinamic_blit = (getattr(self, 'memory', None) is not None and len(self.memory) > 0x7FE3 and self.memory[0x7FE0:0x7FE3] == b'\xE3\x7F\xC9' and 0x7FE0 <= self.PC <= 0x8045)
                is_bb_mid_blit = is_bb and getattr(self, 'IM', 1) == 2 and (0xA3A0 <= self.PC <= 0xA835 or 0xB9E0 <= self.PC <= 0xC000 or not (0x9600 <= self.SP <= 0x9700))
                if is_bb_mid_blit or is_dinamic_blit:
                    # Defer the interrupt while the blitter is actively using hijacked SP
                    # so the CPU can complete the blit loop and restore SP to 0x9600..0x9700.
                    if getattr(self, '_blit_defer_count', 0) < 50:
                        self._blit_defer_count = getattr(self, '_blit_defer_count', 0) + 1
                        break
                    else:
                        self._blit_defer_count = 0
                else:
                    self._blit_defer_count = 0

                cycles_since_int -= frame_tstates
                if getattr(self, '_at_dinamic_wait', False):
                    wait_f = getattr(self, '_dinamic_wait_frames', 0) + 1
                    self._dinamic_wait_frames = wait_f
                    if wait_f >= 50:  # ~1.0 second on loading screen before auto-starting
                        self.E = 0
                        self.PC = 0xFDAC
                        self._dinamic_wait_frames = 0
                        self._at_dinamic_wait = False
                pre_int_pc = self.PC
                if self.IFF1:
                    if not self.interrupt(0xFF):
                        cycles_since_int += frame_tstates
                        break

                if 'zx_beeper_audio' in globals() and zx_beeper_audio is not None:
                    zx_beeper_audio.flush_frame(self.cycles)
                if 'pygame' in globals() and pygame.get_init():
                    try:
                        pygame.event.pump()
                        for event in pygame.event.get():
                            if event.type == pygame.QUIT:
                                self.user_quit = True
                                break
                            elif 'is_break_event' in globals() and is_break_event(event):
                                self.suspended_by_break = True
                                break
                            elif event.type == pygame.KEYDOWN:
                                k_char = None
                                if event.key in (pygame.K_BACKSPACE, pygame.K_DELETE):
                                    k_char = chr(12)
                                elif event.key == pygame.K_RETURN:
                                    k_char = '\r'
                                elif event.key == pygame.K_SPACE:
                                    k_char = ' '
                                elif getattr(event, 'unicode', None):
                                    k_char = event.unicode
                                if k_char:
                                    if 'last_keypress' in globals():
                                        global last_keypress
                                        last_keypress = k_char
                                    if 'key_press_buffer' in globals():
                                        key_press_buffer.append(k_char)
                        if getattr(self, 'user_quit', False) or getattr(self, 'suspended_by_break', False):
                            break
                        keys = pygame.key.get_pressed()
                        if keys[pygame.K_ESCAPE]:
                            self.suspended_by_break = True
                            break
                    except Exception:
                        pass

                    is_dinamic_blit = (getattr(self, 'memory', None) is not None and len(self.memory) > 0x7FE3 and self.memory[0x7FE0:0x7FE3] == b'\xE3\x7F\xC9' and 0x7FE0 <= pre_int_pc <= 0x8045)
                    is_bb_mid_blit = is_bb and getattr(self, 'IM', 1) == 2 and (0xA3A0 <= pre_int_pc <= 0xA835 or 0xB9E0 <= pre_int_pc <= 0xC000 or not (0x9600 <= self.SP <= 0x9700))
                    is_mid_blit = is_dinamic_blit or is_bb_mid_blit
                    if not is_mid_blit and (self.screen_dirty or canvas_dirty):
                        canvas_dirty = True
                        screen_bitmap_dirty = True
                        if 'redraw_canvas' in globals():
                            redraw_canvas(force=True)
                        if 'render_frame' in globals():
                            render_frame()
                        if pygame.display.get_init():
                            pygame.display.flip()
                        self.screen_dirty = False
                    if 'clock' in globals() and not is_headless:
                        clock.tick(50)
        if getattr(self, 'suspended_by_break', False):
            global can_continue_mc, suspended_mc_cpu
            can_continue_mc = True
            suspended_mc_cpu = self
        return count

    def run_from(self, addr, max_instructions=None):
        self.reset()
        self.PC = addr & 0xFFFF
        self.SP = 0xFFFE
        if len(self.memory) >= 0x10000:
            self.memory[0xFFFE] = 0x00
            self.memory[0xFFFF] = 0x00
        return self.run(max_instructions=max_instructions, stop_on_ret=True)

    def step_over(self):
        if self.halted:
            return 4
        pc = self.PC
        instr_len = 1
        mnem_u = ""
        try:
            if 'decompile_instruction' in globals():
                next_pc, mnem = decompile_instruction(self.memory, pc)
                instr_len = max(1, (next_pc - pc) & 0xFFFF)
                mnem_u = mnem.upper().strip()
        except Exception:
            pass

        is_call_or_block = (
            mnem_u.startswith("CALL") or 
            mnem_u.startswith("RST") or 
            mnem_u in ("LDIR", "LDDR", "CPIR", "CPDR", "INIR", "INDR", "OTIR", "OTDR")
        )
        if is_call_or_block:
            target_pc = (pc + instr_len) & 0xFFFF
            already_bp = target_pc in self.breakpoints
            self.breakpoints.add(target_pc)
            total_cyc = 0
            try:
                cyc = self.step()
                self.cycles += cyc
                total_cyc += cyc
                while not self.halted and self.PC != target_pc:
                    if self.PC in self.breakpoints and self.PC != target_pc:
                        self.breakpoint_hit = self.PC
                        if 'get_crystal_monitor' in globals():
                            try:
                                get_crystal_monitor().on_breakpoint(self.breakpoint_hit)
                            except Exception:
                                pass
                        break
                    cyc = self.step()
                    self.cycles += cyc
                    total_cyc += cyc
            finally:
                if not already_bp and target_pc in self.breakpoints:
                    self.breakpoints.remove(target_pc)
            return total_cyc
        else:
            cyc = self.step()
            self.cycles += cyc
            return cyc


# ==============================================================================
# Sinclair Hardware Bridge Routines for Z80 ROM Calls
# ==============================================================================

def z80_print_char(code):
    global print_row, print_col, screen_chars, canvas_dirty
    if code in (10, 13):
        print_col = 0
        print_row += 1
        if print_row >= 24:
            print_row = 23
            if 'scroll_screen' in globals():
                scroll_screen()
        canvas_dirty = True
        return
    ch = chr(code) if 32 <= code <= 126 else ' '
    try:
        if 'screen_chars' in globals() and screen_chars:
            if 0 <= print_row < 24 and 0 <= print_col < 32:
                screen_chars[print_row][print_col] = ch
                canvas_dirty = True
            print_col += 1
            if print_col >= 32:
                print_col = 0
                print_row += 1
                if print_row >= 24:
                    print_row = 23
                    if 'scroll_screen' in globals():
                        scroll_screen()
    except Exception:
        pass

def z80_cls():
    global gfx_bits, canvas_dirty, print_row, print_col, screen_chars, attr_ink, attr_paper, attr_bright, attr_flash, memory
    for x in range(256):
        for y in range(192):
            gfx_bits[x][y] = 0
    if 'screen_chars' in globals() and screen_chars:
        for r in range(24):
            for c in range(32):
                screen_chars[r][c] = ' '
    for r in range(24):
        for c in range(32):
            attr_ink[r][c] = current_ink
            attr_paper[r][c] = current_paper
            attr_bright[r][c] = 1 if current_bright else 0
            attr_flash[r][c] = 1 if current_flash else 0
    print_row = 0
    print_col = 0
    canvas_dirty = True
    memory[0x4000:0x5800] = b'\x00' * 6144
    attr_byte = (128 if current_flash else 0) | (64 if current_bright else 0) | ((current_paper & 7) << 3) | (current_ink & 7)
    memory[0x5800:0x5B00] = bytes([attr_byte]) * 768

def z80_beeper(de, hl):
    try:
        if hl <= 0: hl = 1
        freq = 437500.0 / (hl + 30.0)
        semitone = 12.0 * math.log2(max(20.0, min(10000.0, freq)) / 440.0) + 9.0
        dur_sec = max(0.01, min(1.0, (de * (hl + 30.0)) / 3500000.0))
        play_spectrum_beep(dur_sec, semitone)
    except Exception:
        pass

def z80_plot(b, c):
    try:
        plot_pixel(b & 0xFF, c & 0xFF)
    except Exception:
        pass

def z80_draw(b, c):
    try:
        dx = b if b < 128 else b - 256
        dy = c if c < 128 else c - 256
        draw_relative(dx, dy)
    except Exception:
        pass

def get_zeus_assembler():
    global zeus_assembler
    if zeus_assembler is None:
        zeus_assembler = SinclairZeusAssembler()
    return zeus_assembler

def get_z80_cpu():
    global z80_cpu, memory
    if z80_cpu is None:
        z80_cpu = SinclairZ80CPU(memory)
        z80_cpu.hook_print_char = z80_print_char
        z80_cpu.hook_cls = z80_cls
        z80_cpu.hook_beeper = z80_beeper
        z80_cpu.hook_plot = z80_plot
        z80_cpu.hook_draw = z80_draw
        z80_cpu.hook_port_out = handle_out_port
        z80_cpu.hook_port_in = read_in_port
    return z80_cpu

def export_zeus_asm(filepath, assembler=None):
    if assembler is None:
        assembler = get_zeus_assembler()
    lines_out = []
    lines_out.append("; ========================================================")
    lines_out.append("; Sinclair ZEUS Z80 Assembler Export")
    lines_out.append(f"; Origin: {assembler.org_address} (0x{assembler.org_address:04X})")
    lines_out.append(f"; Total bytes: {len(assembler.code_bytes)}")
    lines_out.append("; ========================================================\n")
    for addr, code_b, src in assembler.listing:
        if code_b:
            hex_str = " ".join(f"{b:02X}" for b in code_b)
            lines_out.append(f"{addr:04X}  {hex_str:<14}  {src}")
        else:
            lines_out.append(f"                        {src}")
    content = "\n".join(lines_out)
    with open(filepath, "w", encoding="utf-8") as f:
        f.write(content)
    return content

def export_zeus_tap(filepath, prog_name="Code", org_addr=None, code_bytes=None, includes_sprites=None, includes_tilemap=None):
    asm = get_zeus_assembler()
    if org_addr is None:
        org_addr = asm.org_address
    if code_bytes is None:
        code_bytes = asm.code_bytes
    if includes_sprites is None:
        includes_sprites = getattr(asm, "includes_sprites", False)
    if includes_tilemap is None:
        includes_tilemap = getattr(asm, "includes_tilemap", False)

    clean_name = (prog_name[:10]).strip() or "Code"

    if not includes_sprites and not includes_tilemap:
        clear_addr = org_addr - 1 if org_addr > 0 else 0
        basic_lines = [
            (10, f"CLEAR {clear_addr}"),
            (20, 'LOAD "" CODE'),
            (30, f"RANDOMIZE USR {org_addr}")
        ]
        basic_payload = bytearray()
        for ln, text in basic_lines:
            line_bytes = tokenize_sinclair_line(ln, text)
            basic_payload.extend(line_bytes)

        name_bytes = clean_name.ljust(10).encode('ascii', errors='replace')[:10]
        b_header = bytearray([0x00])
        b_header.extend(name_bytes)
        b_data_len = len(basic_payload)
        b_header.extend(struct.pack("<H", b_data_len))
        b_header.extend(struct.pack("<H", 10))
        b_header.extend(struct.pack("<H", b_data_len))

        basic_header_block = create_tap_block(0x00, b_header)
        basic_data_block = create_tap_block(0xFF, basic_payload)

        c_header = bytearray([0x03])
        c_header.extend(clean_name.ljust(10).encode('ascii', errors='replace')[:10])
        c_len = len(code_bytes)
        c_header.extend(struct.pack("<H", c_len))
        c_header.extend(struct.pack("<H", org_addr))
        c_header.extend(struct.pack("<H", 0x8000))

        code_header_block = create_tap_block(0x00, c_header)
        code_data_block = create_tap_block(0xFF, code_bytes)

        with open(filepath, "wb") as f:
            f.write(basic_header_block)
            f.write(basic_data_block)
            f.write(code_header_block)
            f.write(code_data_block)
        return

    sp_base = DEFAULT_SPRITE_ENGINE_BASE if 'DEFAULT_SPRITE_ENGINE_BASE' in globals() else 50000
    tile_base = DEFAULT_TILE_ENGINE_BASE if 'DEFAULT_TILE_ENGINE_BASE' in globals() else 45000
    tilemap_base = 40000

    sp_engine_bytes = b""
    sp_data_bytes = b""
    num_defs = 0
    if includes_sprites:
        sp_bytes = generate_sprite_engine_binary(sp_base)
        sp_engine_bytes = sp_bytes[:3072]
        sp_data_bytes, num_defs = extract_sprite_defs_data(None, base=sp_base)

    tl_bytes = b""
    tl_data_bytes = b""
    if includes_tilemap:
        tl_bytes = generate_tile_engine_binary(base=tile_base, tilemap_base=tilemap_base)
        tl_data_bytes = extract_tilemap_data(None, tilemap_base=tilemap_base)

    start_base = org_addr
    if includes_sprites:
        start_base = min(start_base, sp_base)
    if includes_tilemap:
        start_base = min(start_base, tile_base, tilemap_base if tl_data_bytes else tile_base)

    max_addr = org_addr + len(code_bytes)
    if includes_sprites:
        max_addr = max(max_addr, sp_base + len(sp_engine_bytes))
        if sp_data_bytes and num_defs > 0:
            max_addr = max(max_addr, sp_base + 3072 + len(sp_data_bytes))
    if includes_tilemap:
        max_addr = max(max_addr, tile_base + len(tl_bytes))
        if tl_data_bytes:
            max_addr = max(max_addr, tilemap_base + len(tl_data_bytes))

    mono_payload = bytearray(max_addr - start_base)
    mono_payload[org_addr - start_base : org_addr - start_base + len(code_bytes)] = code_bytes
    if includes_tilemap and tl_data_bytes:
        mono_payload[tilemap_base - start_base : tilemap_base - start_base + len(tl_data_bytes)] = tl_data_bytes
    if includes_tilemap:
        mono_payload[tile_base - start_base : tile_base - start_base + len(tl_bytes)] = tl_bytes
    if includes_sprites:
        mono_payload[sp_base - start_base : sp_base - start_base + len(sp_engine_bytes)] = sp_engine_bytes
        if sp_data_bytes and num_defs > 0:
            mono_payload[sp_base + 3072 - start_base : sp_base + 3072 - start_base + len(sp_data_bytes)] = sp_data_bytes

    loader_code = f'10 CLEAR {start_base - 1}: 20 LOAD "" CODE: 30 RANDOMIZE USR {org_addr}'
    loader_blocks = create_tap_loader_blocks(loader_code, filename_str="loader", autostart_line=1)
    code_blocks = create_tap_code_blocks(clean_name, bytes(mono_payload), start_addr=start_base)

    final_tap = loader_blocks + code_blocks
    with open(filepath, "wb") as f:
        f.write(final_tap)


# ==============================================================================
# Sinclair ZEUS Z80 Compiler Caching, Decompiler, and ZLOAD Subsystem
# ==============================================================================

_z80_compiled_blocks = {}

def execute_z80_inline_block(code_str, block_key=None):
    """
    Executes an inline Z80 assembly block.
    Compiles on 1st run and places machine code in memory at ADDRESS / ORG.
    Sets flag compiled=True so on subsequent runs the code directly executes
    from the pre-assembled code in memory without re-assembling (as if USR address was used).
    """
    global _z80_compiled_blocks, memory
    clean_code = code_str.strip()
    if not clean_code:
        return None
    code_hash = hash(clean_code)

    cached = _z80_compiled_blocks.get(block_key) if block_key is not None else None
    if cached is None or cached.get("code_hash") != code_hash or not cached.get("compiled"):
        asm = get_zeus_assembler()
        cbytes = asm.assemble(clean_code, target_memory=memory)
        target_addr = asm.org_address
        if getattr(asm, "includes_sprites", False):
            sp_base = DEFAULT_SPRITE_ENGINE_BASE if 'DEFAULT_SPRITE_ENGINE_BASE' in globals() else 50000
            if memory[sp_base] != 0xC3:
                sp_bin = generate_sprite_engine_binary(sp_base)
                for i, b in enumerate(sp_bin[:3072]):
                    memory[sp_base + i] = b
        if getattr(asm, "includes_tilemap", False):
            tl_base = DEFAULT_TILE_ENGINE_BASE if 'DEFAULT_TILE_ENGINE_BASE' in globals() else 45000
            if memory[tl_base] != 0xC3:
                tl_bin = generate_tile_engine_binary(base=tl_base, tilemap_base=40000)
                for i, b in enumerate(tl_bin):
                    memory[tl_base + i] = b
        has_code = any(
            instr not in ("ORG", "ADDRESS", "EQU", "DEFB", "DB", "DEFW", "DW", "DEFS", "DS", "DEFM", "DM", "ENT", "END", "INCLUDE")
            for _, instr, _ in [asm.parse_line(l) for l in clean_code.splitlines()]
            if instr
        )
        cached = {
            "compiled": True,
            "address": target_addr,
            "code_hash": code_hash,
            "length": len(cbytes),
            "has_code": has_code
        }
        if block_key is not None:
            _z80_compiled_blocks[block_key] = cached

    # Run from pre-assembled code as if USR address was used
    if cached.get("has_code", True):
        cpu = get_z80_cpu()
        cpu.run_from(cached["address"])
    return cached


# ==============================================================================
# Sinclair FORTH Native Z80 Compiler and Execution Subsystem
# ==============================================================================

_forth_compiled_blocks = {}
_last_compiled_forth = None

class SinclairForthCompiler:
    """
    Subroutine-threaded Sinclair Forth compiler targeting native Z80 machine code.
    Uses IX as the Forth parameter stack (starting at 0xFF00), hardware SP as the
    return stack, and standard ZX Spectrum ROM / system variables for I/O:
      - RST 16 for character output
      - 0x0DAF for CLS
      - 23560 (LAST_K) for keyboard input
      - Port 0xFE and 23624 (BORDCR) for border color
    All jumps and calls use fixed 3-byte opcodes (JP, CALL) to ensure identical
    pass 1 and pass 2 symbol resolution in the Zeus assembler.
    """
    def __init__(self, org=0x8000):
        self.org = org
        self.words = {}      # name_upper -> label
        self.vars = {}       # name_upper -> label
        self.consts = {}     # name_upper -> value
        self.label_seq = 0

    def new_label(self, prefix="lbl"):
        self.label_seq += 1
        return f"__{prefix}_{self.label_seq}"

    def parse_tokens(self, code_str):
        tokens = []
        i = 0
        n = len(code_str)
        while i < n:
            while i < n and code_str[i].isspace():
                i += 1
            if i >= n:
                break
            # Line comment: \
            if code_str[i] == '\\' and (i + 1 == n or code_str[i+1].isspace()):
                while i < n and code_str[i] not in ('\r', '\n'):
                    i += 1
                continue
            # Parenthesized comment: ( ... )
            if code_str[i] == '(' and (i + 1 == n or code_str[i+1].isspace()):
                i += 1
                while i < n and code_str[i] != ')':
                    i += 1
                if i < n and code_str[i] == ')':
                    i += 1
                continue
            # String literal: ." ... "
            if code_str[i:i+2] == '."' and (i + 2 == n or code_str[i+2].isspace()):
                i += 2
                if i < n and code_str[i].isspace():
                    i += 1
                start_s = i
                while i < n and code_str[i] != '"':
                    i += 1
                s_val = code_str[start_s:i]
                if i < n and code_str[i] == '"':
                    i += 1
                tokens.append(('DOT_QUOTE', s_val))
                continue
            # General word / literal
            start_w = i
            while i < n and not code_str[i].isspace():
                i += 1
            w = code_str[start_w:i]
            tokens.append(('WORD', w))
        return tokens

    def parse_number(self, s):
        s = s.strip()
        if not s: return None
        if s.startswith("$") or s.startswith("#") or s.lower().startswith("0x"):
            prefix_len = 2 if s.lower().startswith("0x") else 1
            try: return int(s[prefix_len:], 16)
            except: pass
        if s.upper().endswith("H") and len(s) > 1 and s[0].isdigit():
            try: return int(s[:-1], 16)
            except: pass
        if s.startswith("%"):
            try: return int(s[1:], 2)
            except: pass
        try:
            val = int(s)
            return ((val + 32768) % 65536) - 32768
        except:
            return None

    def compile(self, forth_code):
        tokens = self.parse_tokens(forth_code)
        
        # Check for ORG / ADDRESS directive
        idx = 0
        while idx < len(tokens):
            t_type, t_val = tokens[idx]
            if t_type == 'WORD' and t_val.upper() in ("ORG", "ADDRESS") and idx + 1 < len(tokens):
                num = self.parse_number(tokens[idx+1][1])
                if num is not None:
                    self.org = num & 0xFFFF
                    del tokens[idx:idx+2]
                    continue
            idx += 1

        top_lines = []
        word_lines = []
        cur_lines = top_lines
        ctrl_stack = []
        in_colon = False
        cur_word_name = None
        var_decls = []

        i = 0
        while i < len(tokens):
            t_type, t_val = tokens[i]
            i += 1

            if t_type == 'DOT_QUOTE':
                cur_lines.append("    call __print_str")
                s_bytes = t_val.encode('ascii', errors='replace')
                cur_lines.append(f"    db {len(s_bytes)}")
                clean_s = t_val.replace('"', '""')
                cur_lines.append(f'    db "{clean_s}"')
                continue

            w_upper = t_val.upper()

            if w_upper in ("END_FORTH", "ENDFORTH", "END") and i < len(tokens) and tokens[i][1].upper() == "FORTH":
                i += 1
                break
            if w_upper in ("END_FORTH", "ENDFORTH"):
                break

            # Colon definitions: : <name> ... ;
            if w_upper == ':':
                if i < len(tokens):
                    _, name = tokens[i]
                    i += 1
                    cur_word_name = name.upper()
                    clean_lbl = re.sub(r'[^A-Za-z0-9_]', '_', cur_word_name)
                    lbl = f"__usr_{clean_lbl}_{self.new_label('w')}"
                    self.words[cur_word_name] = lbl
                    in_colon = True
                    cur_lines = word_lines
                    cur_lines.append(f"{lbl}:")
                continue

            if w_upper == ';':
                if in_colon:
                    cur_lines.append("    ret")
                    in_colon = False
                    cur_lines = top_lines
                    cur_word_name = None
                continue

            # Control Structures
            if w_upper == 'IF':
                false_lbl = self.new_label("if_false")
                end_lbl = self.new_label("if_end")
                cur_lines.append("    call __pop_hl")
                cur_lines.append("    ld a, l")
                cur_lines.append("    or h")
                cur_lines.append(f"    jp z, {false_lbl}")
                ctrl_stack.append(('IF', false_lbl, end_lbl, False))
                continue

            if w_upper == 'ELSE':
                if ctrl_stack and ctrl_stack[-1][0] == 'IF':
                    tag, false_lbl, end_lbl, _ = ctrl_stack.pop()
                    cur_lines.append(f"    jp {end_lbl}")
                    cur_lines.append(f"{false_lbl}:")
                    ctrl_stack.append(('IF', false_lbl, end_lbl, True))
                continue

            if w_upper == 'THEN':
                if ctrl_stack and ctrl_stack[-1][0] == 'IF':
                    tag, false_lbl, end_lbl, has_else = ctrl_stack.pop()
                    if not has_else:
                        cur_lines.append(f"{false_lbl}:")
                    cur_lines.append(f"{end_lbl}:")
                continue

            if w_upper == 'BEGIN':
                begin_lbl = self.new_label("begin")
                cur_lines.append(f"{begin_lbl}:")
                ctrl_stack.append(('BEGIN', begin_lbl))
                continue

            if w_upper == 'UNTIL':
                if ctrl_stack and ctrl_stack[-1][0] == 'BEGIN':
                    _, begin_lbl = ctrl_stack.pop()
                    cur_lines.append("    call __pop_hl")
                    cur_lines.append("    ld a, l")
                    cur_lines.append("    or h")
                    cur_lines.append(f"    jp z, {begin_lbl}")
                continue

            if w_upper == 'AGAIN':
                if ctrl_stack and ctrl_stack[-1][0] == 'BEGIN':
                    _, begin_lbl = ctrl_stack.pop()
                    cur_lines.append(f"    jp {begin_lbl}")
                continue

            if w_upper == 'WHILE':
                exit_lbl = self.new_label("while_exit")
                cur_lines.append("    call __pop_hl")
                cur_lines.append("    ld a, l")
                cur_lines.append("    or h")
                cur_lines.append(f"    jp z, {exit_lbl}")
                ctrl_stack.append(('WHILE', exit_lbl))
                continue

            if w_upper == 'REPEAT':
                if len(ctrl_stack) >= 2 and ctrl_stack[-1][0] == 'WHILE' and ctrl_stack[-2][0] == 'BEGIN':
                    _, exit_lbl = ctrl_stack.pop()
                    _, begin_lbl = ctrl_stack.pop()
                    cur_lines.append(f"    jp {begin_lbl}")
                    cur_lines.append(f"{exit_lbl}:")
                continue

            if w_upper == 'DO':
                loop_start = self.new_label("do_start")
                loop_exit = self.new_label("do_exit")
                cur_lines.append("    call __pop_de") # initial index
                cur_lines.append("    call __pop_hl") # limit
                cur_lines.append("    push hl")       # limit to return stack
                cur_lines.append("    push de")       # index to return stack
                cur_lines.append(f"{loop_start}:")
                ctrl_stack.append(('DO', loop_start, loop_exit))
                continue

            if w_upper == 'I':
                cur_lines.append("    call __f_i")
                continue

            if w_upper == 'LEAVE':
                if ctrl_stack and ctrl_stack[-1][0] == 'DO':
                    _, _, loop_exit = ctrl_stack[-1]
                    cur_lines.append(f"    jp {loop_exit}")
                continue

            if w_upper == 'LOOP':
                if ctrl_stack and ctrl_stack[-1][0] == 'DO':
                    _, loop_start, loop_exit = ctrl_stack.pop()
                    cont_lbl = self.new_label("loop_cont")
                    cur_lines.append("    pop hl")  # index
                    cur_lines.append("    pop de")  # limit
                    cur_lines.append("    inc hl")
                    cur_lines.append("    ld a, h")
                    cur_lines.append("    cp d")
                    cur_lines.append(f"    jp nz, {cont_lbl}")
                    cur_lines.append("    ld a, l")
                    cur_lines.append("    cp e")
                    cur_lines.append(f"    jp nz, {cont_lbl}")
                    cur_lines.append(f"    jp {loop_exit}")
                    cur_lines.append(f"{cont_lbl}:")
                    cur_lines.append("    push de")
                    cur_lines.append("    push hl")
                    cur_lines.append(f"    jp {loop_start}")
                    cur_lines.append(f"{loop_exit}:")
                continue

            # Defining words: VARIABLE and CONSTANT
            if w_upper == 'VARIABLE':
                if i < len(tokens):
                    _, vname = tokens[i]
                    i += 1
                    vname_u = vname.upper()
                    clean_v = re.sub(r'[^A-Za-z0-9_]', '_', vname_u)
                    vlbl = f"__var_{clean_v}_{self.new_label('v')}"
                    self.vars[vname_u] = vlbl
                    var_decls.append(f"{vlbl}: dw 0")
                continue

            if w_upper == 'CONSTANT':
                if i < len(tokens):
                    _, cname = tokens[i]
                    i += 1
                    cval = 0
                    if cur_lines and cur_lines[-1] == "    call __push_hl" and len(cur_lines) >= 2:
                        prev = cur_lines[-2].strip()
                        if prev.startswith("ld hl,"):
                            try: cval = int(prev[7:].strip())
                            except: pass
                            cur_lines.pop()
                            cur_lines.pop()
                    self.consts[cname.upper()] = cval
                continue

            if w_upper in self.vars:
                cur_lines.append(f"    ld hl, {self.vars[w_upper]}")
                cur_lines.append("    call __push_hl")
                continue

            if w_upper in self.consts:
                cur_lines.append(f"    ld hl, {self.consts[w_upper]}")
                cur_lines.append("    call __push_hl")
                continue

            if w_upper in self.words:
                cur_lines.append(f"    call {self.words[w_upper]}")
                continue

            # Standard Forth primitives map
            PRIM_MAP = {
                "DUP": "call __f_dup",
                "DROP": "call __f_drop",
                "SWAP": "call __f_swap",
                "OVER": "call __f_over",
                "ROT": "call __f_rot",
                "-ROT": "call __f_mrot",
                "?DUP": "call __f_qdup",
                "2DUP": "call __f_2dup",
                "2DROP": "call __f_2drop",
                "2SWAP": "call __f_2swap",
                "NIP": "call __f_nip",
                "TUCK": "call __f_tuck",
                "DEPTH": "call __f_depth",
                ">R": "call __f_tor",
                "R>": "call __f_rfrom",
                "R@": "call __f_rat",
                "+": "call __f_add",
                "-": "call __f_sub",
                "1+": "call __f_1plus",
                "1-": "call __f_1minus",
                "2+": "call __f_2plus",
                "2-": "call __f_2minus",
                "2*": "call __f_2star",
                "2/": "call __f_2slash",
                "NEGATE": "call __f_negate",
                "ABS": "call __f_abs",
                "*": "call __f_mul",
                "/": "call __f_div",
                "MOD": "call __f_mod",
                "/MOD": "call __f_slashmod",
                "MIN": "call __f_min",
                "MAX": "call __f_max",
                "AND": "call __f_and",
                "OR": "call __f_or",
                "XOR": "call __f_xor",
                "NOT": "call __f_zero_eq",
                "INVERT": "call __f_invert",
                "0=": "call __f_zero_eq",
                "0<": "call __f_zero_lt",
                "0>": "call __f_zero_gt",
                "=": "call __f_eq",
                "<>": "call __f_ne",
                "<": "call __f_lt",
                ">": "call __f_gt",
                "<=": "call __f_le",
                ">=": "call __f_ge",
                "@": "call __f_fetch",
                "!": "call __f_store",
                "C@": "call __f_cfetch",
                "C!": "call __f_cstore",
                "+!": "call __f_plusstore",
                ".": "call __f_dot",
                "U.": "call __f_udot",
                "EMIT": "call __f_emit",
                "CR": "call __f_cr",
                "SPACE": "call __f_space",
                "SPACES": "call __f_spaces",
                "CLS": "call __f_cls",
                "BORDER": "call __f_border",
                "KEY": "call __f_key",
                "?KEY": "call __f_qkey",
                "KEY?": "call __f_qkey",
            }

            if w_upper in PRIM_MAP:
                cur_lines.append(f"    {PRIM_MAP[w_upper]}")
                continue

            # Number literal
            num = self.parse_number(t_val)
            if num is not None:
                cur_lines.append(f"    ld hl, {num}")
                cur_lines.append("    call __push_hl")
                continue

            raise Exception(f"Unknown Forth word: '{t_val}'")

        # Assemble full source
        asm_parts = [f"ORG {self.org}"]
        asm_parts.append("""
__forth_entry:
    push bc
    push de
    push hl
    push iy
    ld ix, 0xFF00
    call __forth_main
    pop iy
    pop hl
    pop de
    pop bc
    ret
""")
        # Library of primitives
        asm_parts.append("""
__push_hl:
    dec ix
    dec ix
    ld (ix+0), l
    ld (ix+1), h
    ret

__pop_hl:
    ld l, (ix+0)
    ld h, (ix+1)
    inc ix
    inc ix
    ret

__pop_de:
    ld e, (ix+0)
    ld d, (ix+1)
    inc ix
    inc ix
    ret

__f_dup:
    ld l, (ix+0)
    ld h, (ix+1)
    dec ix
    dec ix
    ld (ix+0), l
    ld (ix+1), h
    ret

__f_drop:
    inc ix
    inc ix
    ret

__f_swap:
    ld l, (ix+0)
    ld h, (ix+1)
    ld e, (ix+2)
    ld d, (ix+3)
    ld (ix+0), e
    ld (ix+1), d
    ld (ix+2), l
    ld (ix+3), h
    ret

__f_over:
    ld l, (ix+2)
    ld h, (ix+3)
    jp __push_hl

__f_rot:
    ld l, (ix+0)
    ld h, (ix+1)
    ld e, (ix+2)
    ld d, (ix+3)
    ld c, (ix+4)
    ld b, (ix+5)
    ld (ix+0), c
    ld (ix+1), b
    ld (ix+2), l
    ld (ix+3), h
    ld (ix+4), e
    ld (ix+5), d
    ret

__f_mrot:
    ld l, (ix+0)
    ld h, (ix+1)
    ld e, (ix+2)
    ld d, (ix+3)
    ld c, (ix+4)
    ld b, (ix+5)
    ld (ix+0), e
    ld (ix+1), d
    ld (ix+2), c
    ld (ix+3), b
    ld (ix+4), l
    ld (ix+5), h
    ret

__f_qdup:
    ld a, (ix+0)
    or (ix+1)
    ret z
    jp __f_dup

__f_2dup:
    ld l, (ix+2)
    ld h, (ix+3)
    call __push_hl
    ld l, (ix+2)
    ld h, (ix+3)
    jp __push_hl

__f_2drop:
    inc ix
    inc ix
    inc ix
    inc ix
    ret

__f_2swap:
    ld l, (ix+0)
    ld h, (ix+1)
    ld e, (ix+4)
    ld d, (ix+5)
    ld (ix+0), e
    ld (ix+1), d
    ld (ix+4), l
    ld (ix+5), h
    ld l, (ix+2)
    ld h, (ix+3)
    ld e, (ix+6)
    ld d, (ix+7)
    ld (ix+2), e
    ld (ix+3), d
    ld (ix+6), l
    ld (ix+7), h
    ret

__f_nip:
    ld l, (ix+0)
    ld h, (ix+1)
    inc ix
    inc ix
    ld (ix+0), l
    ld (ix+1), h
    ret

__f_tuck:
    call __f_swap
    jp __f_over

__f_depth:
    ld de, 0xFF00
    push ix
    pop hl
    or a
    ex de, hl
    sbc hl, de
    sra h
    rr l
    jp __push_hl

__f_tor:
    call __pop_hl
    pop bc
    push hl
    push bc
    ret

__f_rfrom:
    pop bc
    pop hl
    push bc
    jp __push_hl

__f_rat:
    pop bc
    pop hl
    push hl
    push bc
    jp __push_hl

__f_i:
    pop bc
    pop hl
    push hl
    push bc
    jp __push_hl

__f_add:
    call __pop_de
    ld l, (ix+0)
    ld h, (ix+1)
    add hl, de
    ld (ix+0), l
    ld (ix+1), h
    ret

__f_sub:
    call __pop_de
    ld l, (ix+0)
    ld h, (ix+1)
    or a
    sbc hl, de
    ld (ix+0), l
    ld (ix+1), h
    ret

__f_1plus:
    inc (ix+0)
    ret nz
    inc (ix+1)
    ret

__f_1minus:
    ld a, (ix+0)
    sub 1
    ld (ix+0), a
    ret nc
    dec (ix+1)
    ret

__f_2plus:
    call __f_1plus
    jp __f_1plus

__f_2minus:
    call __f_1minus
    jp __f_1minus

__f_2star:
    sla (ix+0)
    rl (ix+1)
    ret

__f_2slash:
    sra (ix+1)
    rr (ix+0)
    ret

__f_negate:
    ld l, (ix+0)
    ld h, (ix+1)
    ld a, 0
    sub l
    ld (ix+0), a
    ld a, 0
    sbc a, h
    ld (ix+1), a
    ret

__f_abs:
    bit 7, (ix+1)
    ret z
    jp __f_negate

__f_mul:
    call __pop_de
    call __pop_hl
    ld b, h
    ld c, l
    ld hl, 0
    ld a, 16
__f_mul_l:
    srl b
    rr c
    jp nc, __f_mul_s
    add hl, de
__f_mul_s:
    sla e
    rl d
    dec a
    jp nz, __f_mul_l
    jp __push_hl

__f_div:
    call __pop_de
    call __pop_hl
    ld a, d
    or e
    jp nz, __f_div_ok
    ld hl, 0
    jp __push_hl
__f_div_ok:
    ld c, 0
    bit 7, h
    jp z, __f_div_cde
    inc c
    ld a, 0
    sub l
    ld l, a
    ld a, 0
    sbc a, h
    ld h, a
__f_div_cde:
    bit 7, d
    jp z, __f_div_u
    inc c
    ld a, 0
    sub e
    ld e, a
    ld a, 0
    sbc a, d
    ld d, a
__f_div_u:
    push bc
    ld bc, 0
    ld b, 16
    ld a, 0
__f_udiv_l:
    add hl, hl
    rla
    cp e
    jp c, __f_udiv_s
    sub e
    inc l
__f_udiv_s:
    djnz __f_udiv_l
    pop bc
    bit 0, c
    jp z, __f_div_dn
    ld a, 0
    sub l
    ld l, a
    ld a, 0
    sbc a, h
    ld h, a
__f_div_dn:
    jp __push_hl

__f_mod:
    call __f_over
    call __f_over
    call __f_div
    call __f_mul
    jp __f_sub

__f_slashmod:
    call __f_over
    call __f_over
    call __f_mod
    call __pop_de
    call __f_div
    ld l, e
    ld h, d
    call __push_hl
    jp __f_swap

__f_min:
    call __f_2dup
    call __f_lt
    call __pop_hl
    ld a, l
    or h
    jp nz, __f_min_l
    call __f_swap
__f_min_l:
    jp __f_drop

__f_max:
    call __f_2dup
    call __f_gt
    call __pop_hl
    ld a, l
    or h
    jp nz, __f_max_l
    call __f_swap
__f_max_l:
    jp __f_drop

__f_and:
    call __pop_de
    ld a, (ix+0)
    and e
    ld (ix+0), a
    ld a, (ix+1)
    and d
    ld (ix+1), a
    ret

__f_or:
    call __pop_de
    ld a, (ix+0)
    or e
    ld (ix+0), a
    ld a, (ix+1)
    or d
    ld (ix+1), a
    ret

__f_xor:
    call __pop_de
    ld a, (ix+0)
    xor e
    ld (ix+0), a
    ld a, (ix+1)
    xor d
    ld (ix+1), a
    ret

__f_invert:
    ld a, (ix+0)
    cpl
    ld (ix+0), a
    ld a, (ix+1)
    cpl
    ld (ix+1), a
    ret

__f_zero_eq:
    ld a, (ix+0)
    or (ix+1)
    jp z, __set_one
    jp __set_zero

__f_zero_lt:
    bit 7, (ix+1)
    jp nz, __set_one
    jp __set_zero

__f_zero_gt:
    bit 7, (ix+1)
    jp nz, __set_zero
    ld a, (ix+0)
    or (ix+1)
    jp nz, __set_one
    jp __set_zero

__f_eq:
    call __pop_de
    ld l, (ix+0)
    ld h, (ix+1)
    or a
    sbc hl, de
    jp z, __set_one
    jp __set_zero

__f_ne:
    call __pop_de
    ld l, (ix+0)
    ld h, (ix+1)
    or a
    sbc hl, de
    jp nz, __set_one
    jp __set_zero

__f_lt:
    call __pop_de
    call __pop_hl
    or a
    sbc hl, de
    jp m, __f_lt_chk
    jp pe, __f_lt_true
    jp __f_lt_false
__f_lt_chk:
    jp po, __f_lt_true
__f_lt_false:
    ld hl, 0
    jp __push_hl
__f_lt_true:
    ld hl, 1
    jp __push_hl

__f_gt:
    call __f_swap
    jp __f_lt

__f_le:
    call __f_gt
    jp __f_zero_eq

__f_ge:
    call __f_lt
    jp __f_zero_eq

__set_one:
    ld (ix+0), 1
    ld (ix+1), 0
    ret

__set_zero:
    ld (ix+0), 0
    ld (ix+1), 0
    ret

__f_fetch:
    call __pop_hl
    ld e, (hl)
    inc hl
    ld d, (hl)
    ld l, e
    ld h, d
    jp __push_hl

__f_store:
    call __pop_hl
    call __pop_de
    ld (hl), e
    inc hl
    ld (hl), d
    ret

__f_cfetch:
    call __pop_hl
    ld l, (hl)
    ld h, 0
    jp __push_hl

__f_cstore:
    call __pop_hl
    call __pop_de
    ld (hl), e
    ret

__f_plusstore:
    call __pop_hl
    call __pop_de
    ld a, (hl)
    add a, e
    ld (hl), a
    inc hl
    ld a, (hl)
    adc a, d
    ld (hl), a
    ret

__f_emit:
    call __pop_hl
    ld a, l
    rst 16
    ret

__f_cr:
    ld a, 13
    rst 16
    ret

__f_space:
    ld a, 32
    rst 16
    ret

__f_spaces:
    call __pop_hl
    ld b, l
    ld a, b
    or a
    ret z
__f_sp_l:
    ld a, 32
    rst 16
    djnz __f_sp_l
    ret

__f_dot:
    call __pop_hl
    bit 7, h
    jp z, __f_dot_pos
    push hl
    ld a, 45
    rst 16
    pop hl
    ld a, 0
    sub l
    ld l, a
    ld a, 0
    sbc a, h
    ld h, a
__f_dot_pos:
    ld bc, 0
__f_dot_l1:
    push bc
    ld c, 0
    ld b, 16
    ld a, 0
__f_dot_d16:
    add hl, hl
    rla
    cp 10
    jp c, __f_dot_sk
    sub 10
    inc l
__f_dot_sk:
    djnz __f_dot_d16
    pop bc
    push af
    inc bc
    ld a, h
    or l
    jp nz, __f_dot_l1
__f_dot_p:
    pop af
    add a, 48
    rst 16
    dec bc
    ld a, b
    or c
    jp nz, __f_dot_p
    ld a, 32
    rst 16
    ret

__f_udot:
    call __pop_hl
    jp __f_dot_pos

__f_cls:
    call 0x0DAF
    ret

__f_border:
    call __pop_hl
    ld a, l
    and 7
    out (0xFE), a
    rlca
    rlca
    rlca
    ld (23624), a
    ret

__f_key:
__f_key_w:
    ld a, (23560)
    or a
    jp z, __f_key_w
    ld l, a
    ld h, 0
    ld a, 0
    ld (23560), a
    jp __push_hl

__f_qkey:
    ld a, (23560)
    or a
    jp nz, __f_qkey_y
    ld hl, 0
    jp __push_hl
__f_qkey_y:
    ld hl, 1
    jp __push_hl

__print_str:
    pop hl
    ld a, (hl)
    inc hl
    ld b, a
    or a
    jp z, __ps_end
__ps_loop:
    ld a, (hl)
    inc hl
    rst 16
    djnz __ps_loop
__ps_end:
    jp (hl)
""")

        if word_lines:
            asm_parts.extend(word_lines)

        asm_parts.append("__forth_main:")
        if top_lines:
            asm_parts.extend(top_lines)
        asm_parts.append("    ret\n")

        if var_decls:
            asm_parts.extend(var_decls)

        full_asm = "\n".join(asm_parts)
        return full_asm


def execute_forth_inline_block(code_str, block_key=None, org_address=0x8000):
    """
    Executes an inline Sinclair Forth block by compiling it to native Z80 machine code.
    Compiles on 1st run and places machine code in memory at ADDRESS / ORG (default 0x8000 / 32768).
    Sets flag compiled=True so on subsequent runs the code directly executes
    from the pre-compiled code in memory without re-compiling (as if USR address was used).
    """
    global _forth_compiled_blocks, _last_compiled_forth, memory
    clean_code = code_str.strip()
    if not clean_code:
        return None
    code_hash = hash(clean_code)

    cached = _forth_compiled_blocks.get(block_key) if block_key is not None else None
    if cached is None or cached.get("code_hash") != code_hash or not cached.get("compiled"):
        compiler = SinclairForthCompiler(org=org_address)
        asm_code = compiler.compile(clean_code)
        asm = get_zeus_assembler()
        cbytes = asm.assemble(asm_code, target_memory=memory)
        target_addr = compiler.org
        cached = {
            "compiled": True,
            "address": target_addr,
            "code_hash": code_hash,
            "length": len(cbytes),
            "code_bytes": bytes(cbytes),
            "source": clean_code
        }
        if block_key is not None:
            _forth_compiled_blocks[block_key] = cached
        _last_compiled_forth = cached

    cpu = get_z80_cpu()
    cpu.run_from(cached["address"])
    return cached

_Z80_DEC_REGS8 = ["B", "C", "D", "E", "H", "L", "(HL)", "A"]
_Z80_DEC_REGS16 = ["BC", "DE", "HL", "SP"]
_Z80_DEC_REGS16_AF = ["BC", "DE", "HL", "AF"]
_Z80_DEC_CONDS = ["NZ", "Z", "NC", "C", "PO", "PE", "P", "M"]
_Z80_DEC_ALU_OPS = ["ADD A,", "ADC A,", "SUB", "SBC A,", "AND", "XOR", "OR", "CP"]

def decompile_instruction(mem, pc):
    op = mem[pc & 0xFFFF]
    pc = (pc + 1) & 0xFFFF

    # Simple 1-byte instructions
    if op == 0x00: return pc, "NOP"
    if op == 0x08: return pc, "EX AF, AF'"
    if op == 0x76: return pc, "HALT"
    if op == 0xC9: return pc, "RET"
    if op == 0xD9: return pc, "EXX"
    if op == 0xEB: return pc, "EX DE, HL"
    if op == 0xE3: return pc, "EX (SP), HL"
    if op == 0xE9: return pc, "JP (HL)"
    if op == 0xF9: return pc, "LD SP, HL"
    if op == 0xF3: return pc, "DI"
    if op == 0xFB: return pc, "EI"
    if op == 0x27: return pc, "DAA"
    if op == 0x2F: return pc, "CPL"
    if op == 0x37: return pc, "SCF"
    if op == 0x3F: return pc, "CCF"
    if op == 0x07: return pc, "RLCA"
    if op == 0x0F: return pc, "RRCA"
    if op == 0x17: return pc, "RLA"
    if op == 0x1F: return pc, "RRA"

    # LD rr, nn
    if (op & 0xCF) == 0x01:
        rr = _Z80_DEC_REGS16[(op >> 4) & 3]
        nn = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8); pc = (pc + 2) & 0xFFFF
        return pc, f"LD {rr}, {nn}"

    # LD (BC), A / LD (DE), A / LD A, (BC) / LD A, (DE)
    if op == 0x02: return pc, "LD (BC), A"
    if op == 0x12: return pc, "LD (DE), A"
    if op == 0x0A: return pc, "LD A, (BC)"
    if op == 0x1A: return pc, "LD A, (DE)"

    # LD (nn), HL / LD HL, (nn)
    if op == 0x22:
        nn = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8); pc = (pc + 2) & 0xFFFF
        return pc, f"LD ({nn}), HL"
    if op == 0x2A:
        nn = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8); pc = (pc + 2) & 0xFFFF
        return pc, f"LD HL, ({nn})"

    # LD (nn), A / LD A, (nn)
    if op == 0x32:
        nn = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8); pc = (pc + 2) & 0xFFFF
        return pc, f"LD ({nn}), A"
    if op == 0x3A:
        nn = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8); pc = (pc + 2) & 0xFFFF
        return pc, f"LD A, ({nn})"

    # INC / DEC rr
    if (op & 0xCF) == 0x03:
        return pc, f"INC {_Z80_DEC_REGS16[(op >> 4) & 3]}"
    if (op & 0xCF) == 0x0B:
        return pc, f"DEC {_Z80_DEC_REGS16[(op >> 4) & 3]}"

    # ADD HL, rr
    if (op & 0xCF) == 0x09:
        return pc, f"ADD HL, {_Z80_DEC_REGS16[(op >> 4) & 3]}"

    # INC / DEC r
    if (op & 0xC7) == 0x04:
        return pc, f"INC {_Z80_DEC_REGS8[(op >> 3) & 7]}"
    if (op & 0xC7) == 0x05:
        return pc, f"DEC {_Z80_DEC_REGS8[(op >> 3) & 7]}"

    # LD r, n
    if (op & 0xC7) == 0x06:
        r = _Z80_DEC_REGS8[(op >> 3) & 7]
        n = mem[pc]; pc = (pc + 1) & 0xFFFF
        return pc, f"LD {r}, {n}"

    # Relative jumps: JR e, JR cc, e, DJNZ e
    if op == 0x10:
        disp_b = mem[pc]; pc = (pc + 1) & 0xFFFF
        disp = disp_b if disp_b < 128 else disp_b - 256
        target = (pc + disp) & 0xFFFF
        return pc, f"DJNZ {target}"
    if op == 0x18:
        disp_b = mem[pc]; pc = (pc + 1) & 0xFFFF
        disp = disp_b if disp_b < 128 else disp_b - 256
        target = (pc + disp) & 0xFFFF
        return pc, f"JR {target}"
    if (op & 0xE7) == 0x20:
        cc = _Z80_DEC_CONDS[(op >> 3) & 3]
        disp_b = mem[pc]; pc = (pc + 1) & 0xFFFF
        disp = disp_b if disp_b < 128 else disp_b - 256
        target = (pc + disp) & 0xFFFF
        return pc, f"JR {cc}, {target}"

    # LD r, r' (0x40 - 0x7F except 0x76 HALT)
    if 0x40 <= op <= 0x7F:
        dst = _Z80_DEC_REGS8[(op >> 3) & 7]
        src = _Z80_DEC_REGS8[op & 7]
        return pc, f"LD {dst}, {src}"

    # ALU r (0x80 - 0xBF)
    if 0x80 <= op <= 0xBF:
        alu = _Z80_DEC_ALU_OPS[(op >> 3) & 7]
        src = _Z80_DEC_REGS8[op & 7]
        return pc, f"{alu} {src}"

    # RET cc
    if (op & 0xC7) == 0xC0:
        return pc, f"RET {_Z80_DEC_CONDS[(op >> 3) & 7]}"

    # POP / PUSH rr
    if (op & 0xCF) == 0xC1:
        return pc, f"POP {_Z80_DEC_REGS16_AF[(op >> 4) & 3]}"
    if (op & 0xCF) == 0xC5:
        return pc, f"PUSH {_Z80_DEC_REGS16_AF[(op >> 4) & 3]}"

    # JP cc, nn / JP nn
    if (op & 0xC7) == 0xC2:
        cc = _Z80_DEC_CONDS[(op >> 3) & 7]
        nn = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8); pc = (pc + 2) & 0xFFFF
        return pc, f"JP {cc}, {nn}"
    if op == 0xC3:
        nn = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8); pc = (pc + 2) & 0xFFFF
        return pc, f"JP {nn}"

    # CALL cc, nn / CALL nn
    if (op & 0xC7) == 0xC4:
        cc = _Z80_DEC_CONDS[(op >> 3) & 7]
        nn = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8); pc = (pc + 2) & 0xFFFF
        return pc, f"CALL {cc}, {nn}"
    if op == 0xCD:
        nn = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8); pc = (pc + 2) & 0xFFFF
        return pc, f"CALL {nn}"

    # ALU n (0xC6, 0xCE, 0xD6, 0xDE, 0xE6, 0xEE, 0xF6, 0xFE)
    if (op & 0xC7) == 0xC6:
        alu = _Z80_DEC_ALU_OPS[(op >> 3) & 7]
        n = mem[pc]; pc = (pc + 1) & 0xFFFF
        return pc, f"{alu} {n}"

    # RST p
    if (op & 0xC7) == 0xC7:
        p = op & 0x38
        return pc, f"RST {p}"

    # IN / OUT (n)
    if op == 0xDB:
        n = mem[pc]; pc = (pc + 1) & 0xFFFF
        return pc, f"IN A, ({n})"
    if op == 0xD3:
        n = mem[pc]; pc = (pc + 1) & 0xFFFF
        return pc, f"OUT ({n}), A"

    # CB prefix (Bit operations)
    if op == 0xCB:
        cb_op = mem[pc]; pc = (pc + 1) & 0xFFFF
        r = _Z80_DEC_REGS8[cb_op & 7]
        b = (cb_op >> 3) & 7
        if cb_op < 0x40:
            rot_ops = ["RLC", "RRC", "RL", "RR", "SLA", "SRA", "SRL"]
            rot_idx = (cb_op >> 3) & 7
            if rot_idx < len(rot_ops):
                return pc, f"{rot_ops[rot_idx]} {r}"
        elif cb_op < 0x80:
            return pc, f"BIT {b}, {r}"
        elif cb_op < 0xC0:
            return pc, f"RES {b}, {r}"
        else:
            return pc, f"SET {b}, {r}"

    # ED prefix (Extended)
    if op == 0xED:
        ed_op = mem[pc]; pc = (pc + 1) & 0xFFFF
        ED_BLOCK = {
            0xB0: "LDIR", 0xB8: "LDDR", 0xA0: "LDI", 0xA8: "LDD",
            0xB1: "CPIR", 0xB9: "CPDR", 0xA1: "CPI", 0xA9: "CPD",
            0xB2: "INIR", 0xBA: "INDR", 0xA2: "INI", 0xAA: "IND",
            0xB3: "OTIR", 0xBB: "OTDR", 0xA3: "OUTI", 0xAB: "OUTD",
            0x4D: "RETI", 0x45: "RETN", 0x44: "NEG",
            0x47: "LD I, A", 0x4F: "LD R, A", 0x57: "LD A, I", 0x5F: "LD A, R",
            0x67: "RRD", 0x6F: "RLD",
            0x46: "IM 0", 0x56: "IM 1", 0x5E: "IM 2"
        }
        if ed_op in ED_BLOCK:
            return pc, ED_BLOCK[ed_op]
        # IN r, (C) / OUT (C), r
        if (ed_op & 0xC7) == 0x40:
            r = _Z80_DEC_REGS8[(ed_op >> 3) & 7]
            return pc, f"IN {r}, (C)"
        if (ed_op & 0xC7) == 0x41:
            r = _Z80_DEC_REGS8[(ed_op >> 3) & 7]
            return pc, f"OUT (C), {r}"
        # SBC / ADC HL, rr
        if (ed_op & 0xCF) == 0x42:
            return pc, f"SBC HL, {_Z80_DEC_REGS16[(ed_op >> 4) & 3]}"
        if (ed_op & 0xCF) == 0x4A:
            return pc, f"ADC HL, {_Z80_DEC_REGS16[(ed_op >> 4) & 3]}"
        # LD (nn), rr / LD rr, (nn)
        if (ed_op & 0xCF) == 0x43:
            rr = _Z80_DEC_REGS16[(ed_op >> 4) & 3]
            nn = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8); pc = (pc + 2) & 0xFFFF
            return pc, f"LD ({nn}), {rr}"
        if (ed_op & 0xCF) == 0x4B:
            rr = _Z80_DEC_REGS16[(ed_op >> 4) & 3]
            nn = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8); pc = (pc + 2) & 0xFFFF
            return pc, f"LD {rr}, ({nn})"

    # DD / FD prefix (IX / IY)
    if op in (0xDD, 0xFD):
        reg_name = "IX" if op == 0xDD else "IY"
        sub_op = mem[pc]; pc = (pc + 1) & 0xFFFF
        if sub_op == 0x21:
            nn = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8); pc = (pc + 2) & 0xFFFF
            return pc, f"LD {reg_name}, {nn}"
        if sub_op == 0x22:
            nn = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8); pc = (pc + 2) & 0xFFFF
            return pc, f"LD ({nn}), {reg_name}"
        if sub_op == 0x2A:
            nn = mem[pc] | (mem[(pc + 1) & 0xFFFF] << 8); pc = (pc + 2) & 0xFFFF
            return pc, f"LD {reg_name}, ({nn})"
        if sub_op == 0x23: return pc, f"INC {reg_name}"
        if sub_op == 0x2B: return pc, f"DEC {reg_name}"
        if (sub_op & 0xCF) == 0x09:
            return pc, f"ADD {reg_name}, {_Z80_DEC_REGS16[(sub_op >> 4) & 3]}"
        if sub_op == 0xE1: return pc, f"POP {reg_name}"
        if sub_op == 0xE5: return pc, f"PUSH {reg_name}"
        if sub_op == 0xE9: return pc, f"JP ({reg_name})"
        if sub_op == 0xF9: return pc, f"LD SP, {reg_name}"
        if sub_op == 0xE3: return pc, f"EX (SP), {reg_name}"
        # Displaced operations (IX+d)
        d_raw = mem[pc]; pc = (pc + 1) & 0xFFFF
        disp = f"+{d_raw}" if d_raw < 128 else f"-{256 - d_raw}"
        ind = f"({reg_name}{disp})"
        if (sub_op & 0xC7) == 0x06:
            r = _Z80_DEC_REGS8[(sub_op >> 3) & 7]
            n = mem[pc]; pc = (pc + 1) & 0xFFFF
            return pc, f"LD {ind}, {n}"
        if (sub_op & 0xC7) == 0x04: return pc, f"INC {ind}"
        if (sub_op & 0xC7) == 0x05: return pc, f"DEC {ind}"
        if 0x40 <= sub_op <= 0x7F and (sub_op & 7) == 6:
            r = _Z80_DEC_REGS8[(sub_op >> 3) & 7]
            return pc, f"LD {r}, {ind}"
        if 0x70 <= sub_op <= 0x77:
            r = _Z80_DEC_REGS8[sub_op & 7]
            return pc, f"LD {ind}, {r}"
        if 0x80 <= sub_op <= 0xBF and (sub_op & 7) == 6:
            alu = _Z80_DEC_ALU_OPS[(sub_op >> 3) & 7]
            return pc, f"{alu} {ind}"

    # Fallback to DEFB
    return pc, f"DEFB {op}"

def decompile_z80(mem, start_addr, max_bytes=512, stop_on_ret=True):
    """
    Decompiles memory into a plain text Z80 opcode listing.
    Starts with ADDRESS <start_addr>, followed by decoded instructions.
    """
    lines = [f"ADDRESS {start_addr}"]
    pc = start_addr & 0xFFFF
    count = 0
    while count < max_bytes and pc < 65536:
        next_pc, mnem = decompile_instruction(mem, pc)
        lines.append(mnem)
        instr_len = (next_pc - pc) & 0xFFFF
        if instr_len == 0:
            instr_len = 1
            next_pc = (pc + 1) & 0xFFFF
        count += instr_len
        pc = next_pc
        if stop_on_ret and mnem in ("RET", "RETI", "RETN"):
            break
        if stop_on_ret and mnem.startswith("JP ") and not mnem.startswith("JP (") and "," not in mnem:
            break
    return "\n".join(lines)

def execute_decompile_command(args_str):
    global memory
    parts = []
    curr = []
    in_q = False
    q_char = None
    for ch in args_str.strip():
        if ch in ('"', "'"):
            if not in_q: in_q = True; q_char = ch
            elif ch == q_char: in_q = False
            curr.append(ch)
        elif ch == ',' and not in_q:
            parts.append("".join(curr).strip())
            curr = []
        else:
            curr.append(ch)
    if curr:
        parts.append("".join(curr).strip())

    if len(parts) < 2:
        canvas_print('Syntax: DECOMPILE address, "filename"')
        update_display()
        return

    addr_expr = parts[0].strip()
    try:
        addr = int(evaluate_expr(addr_expr))
    except Exception:
        try:
            addr = get_zeus_assembler().eval_expr(addr_expr)
        except Exception:
            canvas_print(f"Invalid DECOMPILE address: {addr_expr}")
            update_display()
            return

    max_bytes = 512
    if len(parts) >= 3:
        try:
            max_bytes = int(evaluate_expr(parts[1].strip()))
            fname_arg = parts[2].strip()
        except Exception:
            fname_arg = parts[1].strip()
    else:
        fname_arg = parts[1].strip()

    fname = fname_arg.strip('\"\'')
    if not fname.lower().endswith(".z8c"):
        fname += ".z8c"

    listing_text = decompile_z80(memory, addr, max_bytes=max_bytes, stop_on_ret=True)
    try:
        with open(fname, "w", encoding="utf-8") as f:
            f.write(listing_text + "\n")
        canvas_print(f"Decompiled address {addr} to '{fname}'")
    except Exception as e:
        canvas_print(f"Error saving '{fname}': {e}")
    update_display()

def execute_zload_command(args_str):
    global program, canvas_dirty, _z80_compiled_blocks
    parts = []
    curr = []
    in_q = False
    q_char = None
    for ch in args_str.strip():
        if ch in ('"', "'"):
            if not in_q: in_q = True; q_char = ch
            elif ch == q_char: in_q = False
            curr.append(ch)
        elif ch == ',' and not in_q:
            parts.append("".join(curr).strip())
            curr = []
        else:
            curr.append(ch)
    if curr:
        parts.append("".join(curr).strip())

    if len(parts) < 2:
        canvas_print('Syntax: ZLOAD "filename", line_number')
        update_display()
        return

    fname = parts[0].strip().strip('\"\'')
    if not fname.lower().endswith(".z8c"):
        fname += ".z8c"

    try:
        target_line = int(evaluate_expr(parts[1].strip()))
    except Exception:
        canvas_print(f"Invalid line number: {parts[1]}")
        update_display()
        return

    target_path = fname
    if not os.path.exists(target_path):
        cur_dir_candidate = os.path.join(os.getcwd(), fname)
        if os.path.exists(cur_dir_candidate):
            target_path = cur_dir_candidate
        else:
            basinpy_dir = r"c:\Users\kfash\Documents\BasinPy"
            bp_candidate = os.path.join(basinpy_dir, fname)
            if os.path.exists(bp_candidate):
                target_path = bp_candidate
            else:
                canvas_print(f"File not found: {fname}")
                update_display()
                return

    try:
        with open(target_path, "r", encoding="utf-8", errors="ignore") as f:
            raw_lines = [l.strip() for l in f.readlines() if l.strip() and not l.strip().startswith(";")]
    except Exception as e:
        canvas_print(f"Error reading '{fname}': {e}")
        update_display()
        return

    # Strip existing outer Z80 / END Z80 if present
    if raw_lines and raw_lines[0].upper() == "Z80":
        raw_lines = raw_lines[1:]
    if raw_lines and raw_lines[-1].upper() in ("END Z80", "ENDZ80", "END_Z80"):
        raw_lines = raw_lines[:-1]

    block_lines = ["Z80"] + raw_lines + ["END Z80"]

    curr_ln = target_line
    for bline in block_lines:
        program[curr_ln] = bline
        curr_ln += 10

    _z80_compiled_blocks.clear()
    canvas_dirty = True
    canvas_print(f"Loaded '{fname}' into program at line {target_line}")
    update_display()


# ==============================================================================
# Crystal Computing Z80 Machine Code Monitor & Disassembler Subsystem
# ==============================================================================

def parse_monitor_val(expr, symbols=None, default=None):
    if expr is None:
        return default
    s = str(expr).strip()
    if not s:
        return default
    # Quoted character
    if (s.startswith("'") and s.endswith("'") and len(s) == 3) or \
       (s.startswith('"') and s.endswith('"') and len(s) == 3):
        return ord(s[1])
    # Symbol lookup
    if symbols and s.upper() in symbols:
        return symbols[s.upper()]
    try:
        if 'get_zeus_assembler' in globals():
            asm = get_zeus_assembler()
            if asm and s.upper() in asm.symbols:
                return asm.symbols[s.upper()]
    except Exception:
        pass
    # Arithmetic: e.g. START + 4 or #8000 + 10
    for op in ('+', '-'):
        if op in s and not s.startswith(op):
            parts = s.split(op, 1)
            v1 = parse_monitor_val(parts[0], symbols)
            v2 = parse_monitor_val(parts[1], symbols)
            if v1 is not None and v2 is not None:
                return (v1 + v2) & 0xFFFF if op == '+' else (v1 - v2) & 0xFFFF
    # Hex with prefix (#, $, 0x, &H)
    if s.startswith("#"):
        try: return int(s[1:], 16)
        except ValueError: pass
    if s.startswith("$") and len(s) > 1:
        try: return int(s[1:], 16)
        except ValueError: pass
    if s.lower().startswith("0x"):
        try: return int(s[2:], 16)
        except ValueError: pass
    if s.upper().startswith("&H"):
        try: return int(s[2:], 16)
        except ValueError: pass
    # Hex with suffix H (e.g. 8000H, FAH, 0AH)
    if s.upper().endswith("H") and len(s) > 1:
        try: return int(s[:-1], 16)
        except ValueError: pass
    # Binary with prefix (%) or (0b) or suffix (B)
    if s.startswith("%"):
        try: return int(s[1:], 2)
        except ValueError: pass
    if s.lower().startswith("0b"):
        try: return int(s[2:], 2)
        except ValueError: pass
    if s.upper().endswith("B") and len(s) > 1 and all(c in '01' for c in s[:-1]):
        try: return int(s[:-1], 2)
        except ValueError: pass
    # Decimal
    if re.match(r"^-?\d+$", s):
        try: return int(s, 10)
        except ValueError: pass
    # Bare hex
    if re.match(r"^[0-9a-fA-F]+$", s):
        try: return int(s, 16)
        except ValueError: pass
    return default


class CrystalZ80Monitor:
    def __init__(self, cpu=None, memory=None):
        self._cpu = cpu
        self._memory = memory
        self.disasm_addr = 0x8000
        self.mem_addr = 0x8000
        self.history = []
        self.scroll_index = 0
        self.active = False
        self.origin = "BASIC"
        self.assemble_addr = None
        self.last_status = "READY"

    @property
    def memory(self):
        if self._memory is not None:
            return self._memory
        global memory
        return memory

    @property
    def cpu(self):
        if self._cpu is not None:
            return self._cpu
        return get_z80_cpu()

    def log(self, text):
        for line in str(text).splitlines():
            self.history.append(line)
        if len(self.history) > 500:
            self.history = self.history[-500:]

    def open(self, addr=None, origin="BASIC"):
        global listing_monitor_active, z80_monitor_mode, listing_vars_active, listing_code_active, listing_edit_active
        self.active = True
        self.origin = origin
        listing_monitor_active = True
        z80_monitor_mode = True
        listing_vars_active = False
        listing_code_active = False
        if "cancel_listing_edit" in globals():
            cancel_listing_edit()
        else:
            listing_edit_active = False

        cpu = self.cpu
        if addr is not None:
            cpu.PC = addr & 0xFFFF
            self.disasm_addr = cpu.PC
            self.mem_addr = cpu.PC
        else:
            self.disasm_addr = cpu.PC
            self.mem_addr = cpu.PC
        self.last_status = "ACTIVE"
        self.log(f"--- Crystal Computing Z80 Monitor ---")
        self.disassemble_block(self.disasm_addr, count=12)

    def close(self):
        global listing_monitor_active, z80_monitor_mode, z80_interactive_mode
        self.active = False
        self.assemble_addr = None
        self.last_status = "CLOSED"
        listing_monitor_active = False
        z80_monitor_mode = False
        if self.origin == "ZEUS":
            z80_interactive_mode = True

    def on_breakpoint(self, addr):
        global listing_monitor_active, z80_monitor_mode, listing_vars_active, listing_code_active
        self.active = True
        listing_monitor_active = True
        z80_monitor_mode = True
        listing_vars_active = False
        listing_code_active = False
        self.last_status = f"BP HIT #{addr:04X}"
        self.disasm_addr = addr & 0xFFFF
        self.log(f"*** BREAKPOINT AT #{addr:04X} ({addr}) ***")
        self.disassemble_block(addr, count=8)

    def get_register_lines(self):
        cpu = self.cpu
        f = cpu.F
        s = 1 if (f & 0x80) else 0
        z = 1 if (f & 0x40) else 0
        h = 1 if (f & 0x10) else 0
        pv = 1 if (f & 0x04) else 0
        n = 1 if (f & 0x02) else 0
        c = 1 if (f & 0x01) else 0

        line1 = f"AF:{cpu.A:02X}{cpu.F:02X}  BC:{cpu.BC:04X}  DE:{cpu.DE:04X}  HL:{cpu.HL:04X}  SP:{cpu.SP:04X}  PC:{cpu.PC:04X}"
        line2 = f"AF':{cpu.A_prime:02X}{cpu.F_prime:02X} BC':{cpu.BC:04X} DE':{cpu.DE:04X} HL':{cpu.HL:04X} IX:{cpu.IX:04X} IY:{cpu.IY:04X}"
        line3 = f"Flags:[S:{s} Z:{z} H:{h} PV:{pv} N:{n} C:{c}]  I:{cpu.I:02X} R:{cpu.R:02X} IM:{cpu.IM} IFF:{1 if cpu.IFF1 else 0}"
        return [line1, line2, line3]

    def disassemble_block(self, start_addr=None, count=16):
        if start_addr is None:
            start_addr = self.disasm_addr
        pc = start_addr & 0xFFFF
        cpu = self.cpu
        mem = self.memory
        self.log(f"Disassembly at #{pc:04X} ({pc}):")
        for _ in range(count):
            cur_pc = pc
            next_pc, mnem = decompile_instruction(mem, cur_pc)
            instr_len = max(1, (next_pc - cur_pc) & 0xFFFF)
            hex_bytes = " ".join(f"{mem[(cur_pc + i) & 0xFFFF]:02X}" for i in range(instr_len))
            pc_mark = ">" if cur_pc == cpu.PC else " "
            bp_mark = "*" if cur_pc in cpu.breakpoints else " "
            self.log(f"{pc_mark}{bp_mark} #{cur_pc:04X}  {hex_bytes:<12}  {mnem}")
            pc = next_pc
        self.disasm_addr = pc

    def dump_memory(self, start_addr=None, num_bytes=64):
        if start_addr is None:
            start_addr = self.mem_addr
        addr = start_addr & 0xFFFF
        mem = self.memory
        self.log(f"Memory dump at #{addr:04X} ({addr}):")
        for row in range(0, num_bytes, 8):
            row_addr = (addr + row) & 0xFFFF
            b_list = [mem[(row_addr + i) & 0xFFFF] for i in range(8)]
            hex_str = " ".join(f"{b:02X}" for b in b_list)
            ascii_str = "".join(chr(b) if 32 <= b <= 126 else "." for b in b_list)
            self.log(f"#{row_addr:04X}:  {hex_str:<23}  {ascii_str}")
        self.mem_addr = (addr + num_bytes) & 0xFFFF

    def handle_command(self, line):
        line = line.strip()
        if not line:
            if self.assemble_addr is not None:
                self.log(f"Exited assemble mode. Next PC is #{self.assemble_addr:04X}.")
                self.assemble_addr = None
                self.last_status = "READY"
            return

        # If currently in interactive assemble mode:
        if self.assemble_addr is not None:
            if line.upper() in (".", "EXIT", "QUIT", "Q", "END"):
                self.log(f"Exited assemble mode. Next PC is #{self.assemble_addr:04X}.")
                self.assemble_addr = None
                self.last_status = "READY"
                return
            asm = get_zeus_assembler()
            try:
                cbytes = asm.assemble(f"ORG {self.assemble_addr}\n{line}\n", target_memory=self.memory)
                if asm.errors:
                    self.log(f"Assembly error: {asm.errors[0]}")
                else:
                    hex_b = " ".join(f"{b:02X}" for b in cbytes)
                    self.log(f"#{self.assemble_addr:04X}  {hex_b:<10}  {line}")
                    self.assemble_addr = (self.assemble_addr + len(cbytes)) & 0xFFFF
                    self.disasm_addr = self.assemble_addr
                    self.last_status = f"ASM #{self.assemble_addr:04X}"
            except Exception as e:
                self.log(f"Error: {e}")
            return

        # Split command and arguments
        parts = line.split(None, 1)
        cmd = parts[0].upper()
        args = parts[1].strip() if len(parts) > 1 else ""

        # Check '=' for register assignment (e.g. PC=8000, A=FF, CF=1, C=5)
        if "=" in line:
            eq_parts = line.split("=", 1)
            candidate_reg = eq_parts[0].strip().upper()
            if candidate_reg not in ("FILL", "COPY", "FIND"):
                val_str = eq_parts[1].strip()
                self._set_register(candidate_reg, val_str)
                return

        if cmd in ("D", "DIS", "DISASM"):
            addr = parse_monitor_val(args) if args else None
            self.disassemble_block(addr)
        elif cmd in ("M", "MEM", "DUMP"):
            arg_tokens = args.split()
            if not arg_tokens:
                self.dump_memory()
            elif len(arg_tokens) == 1:
                addr = parse_monitor_val(arg_tokens[0])
                if addr is not None:
                    self.dump_memory(addr)
                else:
                    self.log(f"Invalid address: {arg_tokens[0]}")
            else:
                # Memory deposit: M <addr> <val1> [val2 ...]
                addr = parse_monitor_val(arg_tokens[0])
                if addr is None:
                    self.log(f"Invalid address: {arg_tokens[0]}")
                    return
                deposit_bytes = []
                for tok in arg_tokens[1:]:
                    val = parse_monitor_val(tok)
                    if val is None:
                        self.log(f"Invalid value: {tok}")
                        return
                    deposit_bytes.append(val & 0xFF)
                cur = addr
                for b in deposit_bytes:
                    self.cpu.write_byte(cur, b)
                    cur = (cur + 1) & 0xFFFF
                self.log(f"Deposited {len(deposit_bytes)} bytes at #{addr:04X}.")
                self.mem_addr = cur
        elif cmd == "R":
            if not args:
                for r_line in self.get_register_lines():
                    self.log(r_line)
            else:
                r_parts = args.split(None, 1)
                if len(r_parts) == 1:
                    r_name = r_parts[0].upper()
                    self._show_single_register(r_name)
                else:
                    r_name = r_parts[0].upper()
                    self._set_register(r_name, r_parts[1])
        elif cmd == "B":
            if not args:
                self.log("Syntax: B <addr>")
            else:
                addr = parse_monitor_val(args)
                if addr is not None:
                    self.cpu.breakpoints.add(addr & 0xFFFF)
                    self.log(f"Breakpoint set at #{addr:04X} ({addr}).")
                else:
                    self.log(f"Invalid address: {args}")
        elif cmd == "BC":
            if not args or args in ("*", "ALL"):
                self.cpu.breakpoints.clear()
                self.log("All breakpoints cleared.")
            else:
                addr = parse_monitor_val(args)
                if addr is not None:
                    self.cpu.breakpoints.discard(addr & 0xFFFF)
                    self.log(f"Breakpoint cleared at #{addr:04X}.")
                else:
                    self.log(f"Invalid address: {args}")
        elif cmd == "BL":
            if not self.cpu.breakpoints:
                self.log("No breakpoints set.")
            else:
                bps_str = ", ".join(f"#{bp:04X} ({bp})" for bp in sorted(self.cpu.breakpoints))
                self.log(f"Breakpoints ({len(self.cpu.breakpoints)}): {bps_str}")
        elif cmd in ("S", "STEP", "T", "TRACE"):
            count = 1
            if args:
                cnt_val = parse_monitor_val(args)
                if cnt_val and cnt_val > 0:
                    count = min(cnt_val, 1000)
            for _ in range(count):
                pc = self.cpu.PC
                _, mnem = decompile_instruction(self.memory, pc)
                self.log(f"Trace #{pc:04X}:  {mnem}")
                self.cpu.step()
                if self.cpu.PC in self.cpu.breakpoints:
                    self.cpu.breakpoint_hit = self.cpu.PC
                    self.on_breakpoint(self.cpu.PC)
                    break
            self.disasm_addr = self.cpu.PC
            self.log(f"PC=#{self.cpu.PC:04X} AF=#{self.cpu.AF:04X} BC=#{self.cpu.BC:04X} HL=#{self.cpu.HL:04X}")
        elif cmd in ("O", "OVER"):
            pc = self.cpu.PC
            _, mnem = decompile_instruction(self.memory, pc)
            self.log(f"Step over #{pc:04X}:  {mnem}")
            self.cpu.step_over()
            self.disasm_addr = self.cpu.PC
            self.log(f"Next PC=#{self.cpu.PC:04X} AF=#{self.cpu.AF:04X} BC=#{self.cpu.BC:04X} HL=#{self.cpu.HL:04X}")
        elif cmd in ("G", "GO", "RUN"):
            if args:
                addr = parse_monitor_val(args)
                if addr is not None:
                    self.cpu.PC = addr & 0xFFFF
            self.log(f"Running machine code from #{self.cpu.PC:04X}...")
            self.last_status = "RUNNING"
            steps = self.cpu.run(stop_on_ret=True)
            if self.cpu.breakpoint_hit is not None:
                self.on_breakpoint(self.cpu.breakpoint_hit)
            else:
                self.last_status = "HALTED" if self.cpu.halted else "STOPPED"
                self.log(f"Execution finished in {steps} steps. PC=#{self.cpu.PC:04X}")
                self.disassemble_block(self.cpu.PC, count=8)
        elif cmd in ("A", "ASM", "ASSEMBLE"):
            arg_tokens = args.split(None, 1)
            if not arg_tokens:
                self.log("Syntax: A <addr> [opcode]")
                return
            addr = parse_monitor_val(arg_tokens[0])
            if addr is None:
                self.log(f"Invalid address: {arg_tokens[0]}")
                return
            if len(arg_tokens) > 1:
                # Direct assembly: A <addr> <opcode>
                opcode_str = arg_tokens[1].strip()
                asm = get_zeus_assembler()
                try:
                    cbytes = asm.assemble(f"ORG {addr}\n{opcode_str}\n", target_memory=self.memory)
                    if asm.errors:
                        self.log(f"Assembly error: {asm.errors[0]}")
                    else:
                        hex_b = " ".join(f"{b:02X}" for b in cbytes)
                        self.log(f"#{addr:04X}  {hex_b:<10}  {opcode_str}")
                        self.disasm_addr = (addr + len(cbytes)) & 0xFFFF
                except Exception as e:
                    self.log(f"Error: {e}")
            else:
                # Interactive assemble mode: A <addr>
                self.assemble_addr = addr & 0xFFFF
                self.last_status = f"ASM #{self.assemble_addr:04X}"
                self.log(f"Enter opcodes at #{self.assemble_addr:04X} (empty line to exit):")
        elif cmd in ("F", "FILL"):
            f_tokens = args.split()
            if len(f_tokens) < 3:
                self.log("Syntax: F <start> <end> <val>")
                return
            start = parse_monitor_val(f_tokens[0])
            end = parse_monitor_val(f_tokens[1])
            val = parse_monitor_val(f_tokens[2])
            if start is None or end is None or val is None:
                self.log("Invalid arguments to FILL.")
                return
            for a in range(start, end + 1):
                self.cpu.write_byte(a, val & 0xFF)
            self.log(f"Filled {end - start + 1} bytes (#{start:04X}-#{end:04X}) with #{val & 0xFF:02X}.")
        elif cmd in ("C", "COPY"):
            c_tokens = args.split()
            if len(c_tokens) < 3:
                self.log("Syntax: C <src> <dest> <len>")
                return
            src = parse_monitor_val(c_tokens[0])
            dest = parse_monitor_val(c_tokens[1])
            length = parse_monitor_val(c_tokens[2])
            if src is None or dest is None or length is None:
                self.log("Invalid arguments to COPY.")
                return
            # Overlap-safe copy
            if dest > src:
                for i in range(length - 1, -1, -1):
                    b = self.memory[(src + i) & 0xFFFF]
                    self.cpu.write_byte((dest + i) & 0xFFFF, b)
            else:
                for i in range(length):
                    b = self.memory[(src + i) & 0xFFFF]
                    self.cpu.write_byte((dest + i) & 0xFFFF, b)
            self.log(f"Copied {length} bytes from #{src:04X} to #{dest:04X}.")
        elif cmd == "FIND":
            find_tokens = args.split()
            if len(find_tokens) < 3:
                self.log("Syntax: FIND <start> <end> <val1> [val2...]")
                return
            start = parse_monitor_val(find_tokens[0])
            end = parse_monitor_val(find_tokens[1])
            pattern = [parse_monitor_val(t) & 0xFF for t in find_tokens[2:]]
            if start is None or end is None or None in pattern or not pattern:
                self.log("Invalid arguments to FIND.")
                return
            matches = []
            pat_len = len(pattern)
            for a in range(start, end - pat_len + 2):
                if all(self.memory[(a + i) & 0xFFFF] == pattern[i] for i in range(pat_len)):
                    matches.append(a)
            if matches:
                self.log(f"Found {len(matches)} match(es): " + ", ".join(f"#{m:04X}" for m in matches[:16]))
            else:
                self.log("Pattern not found.")
        elif cmd in ("X", "Q", "EXIT", "QUIT", "BYE", "BASIC"):
            if cmd == "BASIC":
                self.origin = "BASIC"
            self.close()
            self.log("Exited monitor.")
        elif cmd in ("ZEUS", "Z"):
            self.close()
            global z80_interactive_mode
            z80_interactive_mode = True
            self.log("Returning to Zeus Assembler.")
        elif cmd in ("CLS", "CLEAR"):
            self.history.clear()
            self.scroll_index = 0
        elif cmd in ("H", "HELP", "?"):
            self.log("--- Monitor Commands ---")
            self.log("  D [addr]             Disassemble 16 lines")
            self.log("  M [addr] [bytes...]  Memory dump / deposit")
            self.log("  R [reg] [val]        View / edit registers")
            self.log("  B <addr>             Set breakpoint")
            self.log("  BC [addr|*]          Clear breakpoint(s)")
            self.log("  BL                   List breakpoints")
            self.log("  S [count] / T [cnt]  Step / trace instructions")
            self.log("  O                    Step over subroutine/loop")
            self.log("  G [addr]             Run from address")
            self.log("  A <addr> [opcode]    Assemble opcode at address")
            self.log("  F <s> <e> <val>      Fill memory block")
            self.log("  C <s> <d> <len>      Copy memory block")
            self.log("  FIND <s> <e> <vals>  Find byte pattern in memory")
            self.log("  ZEUS                 Return to Zeus Assembler")
            self.log("  X / Q / EXIT         Exit monitor to BASIC")
        else:
            self.log(f"Unknown command: '{cmd}'. Type H for help.")

    def _show_single_register(self, reg):
        cpu = self.cpu
        val = None
        if reg == "A": val = cpu.A
        elif reg == "F": val = cpu.F
        elif reg == "B": val = cpu.B
        elif reg == "C": val = cpu.C
        elif reg == "D": val = cpu.D
        elif reg == "E": val = cpu.E
        elif reg == "H": val = cpu.H
        elif reg == "L": val = cpu.L
        elif reg == "AF": val = cpu.AF
        elif reg == "BC": val = cpu.BC
        elif reg == "DE": val = cpu.DE
        elif reg == "HL": val = cpu.HL
        elif reg == "IX": val = cpu.IX
        elif reg == "IY": val = cpu.IY
        elif reg == "SP": val = cpu.SP
        elif reg == "PC": val = cpu.PC
        elif reg == "I": val = cpu.I
        elif reg == "R": val = cpu.R
        elif reg == "IM": val = cpu.IM
        if val is not None:
            self.log(f"{reg} = #{val:04X} ({val})" if val > 255 else f"{reg} = #{val:02X} ({val})")
        else:
            self.log(f"Unknown register: {reg}")

    def _set_register(self, reg, val_str):
        cpu = self.cpu
        val = parse_monitor_val(val_str)
        if val is None:
            self.log(f"Invalid value: {val_str}")
            return
        reg = reg.upper().strip()
        if reg == "A": cpu.A = val & 0xFF
        elif reg == "F": cpu.F = val & 0xFF
        elif reg == "B": cpu.B = val & 0xFF
        elif reg == "C": cpu.C = val & 0xFF
        elif reg == "D": cpu.D = val & 0xFF
        elif reg == "E": cpu.E = val & 0xFF
        elif reg == "H": cpu.H = val & 0xFF
        elif reg == "L": cpu.L = val & 0xFF
        elif reg == "AF": cpu.AF = val & 0xFFFF
        elif reg == "BC": cpu.BC = val & 0xFFFF
        elif reg == "DE": cpu.DE = val & 0xFFFF
        elif reg == "HL": cpu.HL = val & 0xFFFF
        elif reg == "IX": cpu.IX = val & 0xFFFF
        elif reg == "IY": cpu.IY = val & 0xFFFF
        elif reg == "SP": cpu.SP = val & 0xFFFF
        elif reg == "PC": cpu.PC = val & 0xFFFF; self.disasm_addr = cpu.PC
        elif reg == "A'": cpu.A_prime = val & 0xFF
        elif reg == "F'": cpu.F_prime = val & 0xFF
        elif reg == "B'": cpu.B_prime = val & 0xFF
        elif reg == "C'": cpu.C_prime = val & 0xFF
        elif reg == "D'": cpu.D_prime = val & 0xFF
        elif reg == "E'": cpu.E_prime = val & 0xFF
        elif reg == "H'": cpu.H_prime = val & 0xFF
        elif reg == "L'": cpu.L_prime = val & 0xFF
        elif reg == "I": cpu.I = val & 0xFF
        elif reg == "R": cpu.R = val & 0xFF
        elif reg == "IM": cpu.IM = max(0, min(2, val))
        elif reg in ("IFF", "IFF1"): cpu.IFF1 = bool(val); cpu.IFF2 = bool(val)
        # Flags
        elif reg in ("ZF", "Z"): cpu.F = (cpu.F | 0x40) if val else (cpu.F & ~0x40)
        elif reg == "NZ": cpu.F = (cpu.F & ~0x40) if val else (cpu.F | 0x40)
        elif reg in ("CF", "CY"): cpu.F = (cpu.F | 0x01) if val else (cpu.F & ~0x01)
        elif reg == "NC": cpu.F = (cpu.F & ~0x01) if val else (cpu.F | 0x01)
        elif reg in ("SF", "S"): cpu.F = (cpu.F | 0x80) if val else (cpu.F & ~0x80)
        elif reg in ("HF", "HC"): cpu.F = (cpu.F | 0x10) if val else (cpu.F & ~0x10)
        elif reg in ("PV", "PE", "PF"): cpu.F = (cpu.F | 0x04) if val else (cpu.F & ~0x04)
        elif reg == "PO": cpu.F = (cpu.F & ~0x04) if val else (cpu.F | 0x04)
        elif reg in ("NF", "N"): cpu.F = (cpu.F | 0x02) if val else (cpu.F & ~0x02)
        else:
            self.log(f"Unknown register: {reg}")
            return
        self.log(f"Set {reg} = #{val:04X} ({val})" if val > 255 else f"Set {reg} = #{val:02X} ({val})")

def get_crystal_monitor():
    global crystal_monitor
    if crystal_monitor is None:
        crystal_monitor = CrystalZ80Monitor()
    return crystal_monitor




# -*- coding: utf-8 -*-
"""
Sinclair ZX Spectrum +3 CP/M Plus 2.2 Subsystem Implementation for BasinPy.
Includes:
- 5x8 Font Bitmap and 51-column x 24-row CPMScreen bitmap text display
- .DSK Disk Image parser (CP/M format)
- Full Locomotive Mallard-80 BASIC interpreter (interactive & batch execution)
- Digital Research DDT (Dynamic Debugging Tool) disassembler and memory editor
- Digital Research ED context line editor
- Digital Research PIP Peripheral Interchange Program
- Sinclair Bundled Utilities (STAT, DUMP, SUBMIT, HELP, DISCKIT, SETKEYS)
- Resident CP/M commands (DIR, TYPE, ERA, REN, USER, SAVE, MOUNT, SPEC)
"""
import re
import os
import sys
import math
import struct

# 5x8 font bitmaps for ASCII 32 to 126
# Width: 5 pixels, Height: 8 pixels
CPM_5X8_FONT = {
    ' ': (0, 0, 0, 0, 0, 0, 0, 0),
    '!': (4, 4, 4, 4, 4, 0, 4, 0),
    '"': (10, 10, 10, 0, 0, 0, 0, 0),
    '#': (10, 10, 31, 10, 31, 10, 10, 0),
    '$': (4, 15, 20, 14, 5, 30, 4, 0),
    '%': (18, 19, 8, 4, 2, 25, 9, 0),
    '&': (12, 18, 18, 12, 21, 18, 13, 0),
    "'": (12, 4, 8, 0, 0, 0, 0, 0),
    '(': (2, 4, 8, 8, 8, 4, 2, 0),
    ')': (8, 4, 2, 2, 2, 4, 8, 0),
    '*': (0, 10, 4, 31, 4, 10, 0, 0),
    '+': (0, 4, 4, 31, 4, 4, 0, 0),
    ',': (0, 0, 0, 0, 0, 6, 4, 8),
    '-': (0, 0, 0, 31, 0, 0, 0, 0),
    '.': (0, 0, 0, 0, 0, 6, 6, 0),
    '/': (0, 1, 2, 4, 8, 16, 0, 0),
    '0': (14, 17, 19, 21, 25, 17, 14, 0),
    '1': (4, 12, 4, 4, 4, 4, 14, 0),
    '2': (14, 17, 1, 6, 8, 16, 31, 0),
    '3': (31, 2, 4, 6, 1, 17, 14, 0),
    '4': (2, 6, 10, 18, 31, 2, 2, 0),
    '5': (31, 16, 30, 1, 1, 17, 14, 0),
    '6': (6, 8, 16, 30, 17, 17, 14, 0),
    '7': (31, 1, 2, 4, 8, 8, 8, 0),
    '8': (14, 17, 17, 14, 17, 17, 14, 0),
    '9': (14, 17, 17, 15, 1, 2, 12, 0),
    ':': (0, 6, 6, 0, 6, 6, 0, 0),
    ';': (0, 6, 6, 0, 6, 4, 8, 0),
    '<': (1, 2, 4, 8, 4, 2, 1, 0),
    '=': (0, 31, 0, 0, 31, 0, 0, 0),
    '>': (16, 8, 4, 2, 4, 8, 16, 0),
    '?': (14, 17, 1, 2, 4, 0, 4, 0),
    '@': (14, 17, 1, 13, 21, 21, 14, 0),
    'A': (14, 17, 17, 31, 17, 17, 17, 0),
    'B': (30, 17, 17, 30, 17, 17, 30, 0),
    'C': (14, 17, 16, 16, 16, 17, 14, 0),
    'D': (28, 18, 17, 17, 17, 18, 28, 0),
    'E': (31, 16, 16, 30, 16, 16, 31, 0),
    'F': (31, 16, 16, 30, 16, 16, 16, 0),
    'G': (14, 17, 16, 23, 17, 17, 14, 0),
    'H': (17, 17, 17, 31, 17, 17, 17, 0),
    'I': (14, 4, 4, 4, 4, 4, 14, 0),
    'J': (1, 1, 1, 1, 1, 17, 14, 0),
    'K': (17, 18, 20, 24, 20, 18, 17, 0),
    'L': (16, 16, 16, 16, 16, 16, 31, 0),
    'M': (17, 27, 21, 21, 17, 17, 17, 0),
    'N': (17, 25, 21, 19, 17, 17, 17, 0),
    'O': (14, 17, 17, 17, 17, 17, 14, 0),
    'P': (30, 17, 17, 30, 16, 16, 16, 0),
    'Q': (14, 17, 17, 17, 21, 18, 13, 0),
    'R': (30, 17, 17, 30, 20, 18, 17, 0),
    'S': (14, 17, 16, 14, 1, 17, 14, 0),
    'T': (31, 4, 4, 4, 4, 4, 4, 0),
    'U': (17, 17, 17, 17, 17, 17, 14, 0),
    'V': (17, 17, 17, 17, 17, 10, 4, 0),
    'W': (17, 17, 17, 21, 21, 27, 17, 0),
    'X': (17, 17, 10, 4, 10, 17, 17, 0),
    'Y': (17, 17, 10, 4, 4, 4, 4, 0),
    'Z': (31, 1, 2, 4, 8, 16, 31, 0),
    '[': (14, 8, 8, 8, 8, 8, 14, 0),
    '\\': (0, 16, 8, 4, 2, 1, 0, 0),
    ']': (14, 2, 2, 2, 2, 2, 14, 0),
    '^': (4, 10, 17, 0, 0, 0, 0, 0),
    '_': (0, 0, 0, 0, 0, 0, 31, 0),
    '`': (8, 4, 2, 0, 0, 0, 0, 0),
    'a': (0, 0, 14, 1, 15, 17, 15, 0),
    'b': (16, 16, 22, 25, 17, 17, 30, 0),
    'c': (0, 0, 14, 16, 16, 17, 14, 0),
    'd': (1, 1, 13, 19, 17, 17, 15, 0),
    'e': (0, 0, 14, 17, 31, 16, 14, 0),
    'f': (6, 9, 8, 28, 8, 8, 8, 0),
    'g': (0, 0, 15, 17, 17, 15, 1, 14),
    'h': (16, 16, 22, 25, 17, 17, 17, 0),
    'i': (4, 0, 12, 4, 4, 4, 14, 0),
    'j': (2, 0, 6, 2, 2, 2, 18, 12),
    'k': (16, 16, 18, 20, 24, 20, 18, 0),
    'l': (12, 4, 4, 4, 4, 4, 14, 0),
    'm': (0, 0, 26, 21, 21, 17, 17, 0),
    'n': (0, 0, 22, 25, 17, 17, 17, 0),
    'o': (0, 0, 14, 17, 17, 17, 14, 0),
    'p': (0, 0, 30, 17, 17, 30, 16, 16),
    'q': (0, 0, 15, 17, 17, 15, 1, 1),
    'r': (0, 0, 22, 25, 16, 16, 16, 0),
    's': (0, 0, 15, 16, 14, 1, 30, 0),
    't': (8, 8, 28, 8, 8, 9, 6, 0),
    'u': (0, 0, 17, 17, 17, 19, 13, 0),
    'v': (0, 0, 17, 17, 17, 10, 4, 0),
    'w': (0, 0, 17, 17, 21, 21, 10, 0),
    'x': (0, 0, 17, 10, 4, 10, 17, 0),
    'y': (0, 0, 17, 17, 17, 15, 1, 14),
    'z': (0, 0, 31, 2, 4, 8, 31, 0),
    '{': (2, 4, 4, 8, 4, 4, 2, 0),
    '|': (4, 4, 4, 4, 4, 4, 4, 0),
    '}': (8, 4, 4, 2, 4, 4, 8, 0),
    '~': (0, 13, 22, 0, 0, 0, 0, 0),
}


# CPMDiskImage is defined earlier with Plus3Disk

def parse_cpm_dsk(data):
    """Parses Spectrum +3 / Amstrad CPC DSK (.dsk) or raw floppy images, returning {filename: bytes}."""
    return CPMDiskImage.from_data(data).get_files()

class VT100Terminal:
    """
    DEC VT100 ANSI Terminal Emulation for Sinclair ZX Spectrum +3 CP/M Plus.
    Mapped to ZX Interface 1 RS-232 serial channel ('b').
    Opens a dedicated OS / Pygame window with 80 columns x 24 rows,
    black paper (#000000) and classic green phosphor text (#22DC22 / #44FF44).
    """
    active_instance = None

    def __init__(self, cpm_system=None):
        self.cols = 80
        self.rows = 24
        self.cpm_system = cpm_system
        if self.cpm_system is None and 'cpm_system' in globals():
            self.cpm_system = globals().get('cpm_system')
        self.cursor_col = 0
        self.cursor_row = 0
        self.saved_cursor = (0, 0)
        self.cursor_visible = True
        self.cursor_blink_on = True
        self.cursor_timer = 0
        self.auto_wrap = True
        self.top_margin = 0
        self.bottom_margin = 23
        self.text_grid = [[' ' for _ in range(80)] for _ in range(24)]
        self.attr_grid = [[{'bold': False, 'dim': False, 'inverse': False, 'underline': False} for _ in range(80)] for _ in range(24)]
        self.cur_attr = {'bold': False, 'dim': False, 'inverse': False, 'underline': False}
        self.esc_state = 0 # 0: normal, 1: ESC, 2: CSI '[', 3: VT52 row, 4: VT52 col
        self.param_buf = ''
        self.win = None
        self.win_surf = None
        self.font = None
        self.font_bold = None
        self.cell_w = 8
        self.cell_h = 16
        self.margin_x = 16
        self.margin_y = 16
        self.win_width = 80 * 8 + 32 # 672
        self.win_height = 24 * 16 + 32 # 416
        self.title = "ZX Spectrum +3 CP/M Plus - VT100 Terminal (RS-232 / Interface 1)"
        self.active = False

        # Monochrome Green Phosphor Palette
        self.COLOR_BG = (0, 0, 0)
        self.COLOR_GREEN = (34, 220, 34)
        self.COLOR_BRIGHT_GREEN = (68, 255, 68)
        self.COLOR_DIM_GREEN = (18, 128, 18)
        self.COLOR_CURSOR = (50, 255, 50)

    @property
    def lines(self):
        return ["".join(row) for row in self.text_grid]

    def open_window(self):
        VT100Terminal.active_instance = self
        if self.win is not None:
            self.active = True
            return
        try:
            import pygame
            if pygame.get_init():
                if hasattr(pygame, 'Window') and os.environ.get("SDL_VIDEODRIVER") != "dummy":
                    try:
                        self.win = pygame.Window(title=self.title, size=(self.win_width, self.win_height))
                        self.win_surf = self.win.get_surface()
                    except Exception:
                        self.win = None
                        self.win_surf = pygame.Surface((self.win_width, self.win_height))
                else:
                    self.win_surf = pygame.Surface((self.win_width, self.win_height))

                try:
                    self.font = pygame.font.SysFont("Consolas", 14)
                    self.font_bold = pygame.font.SysFont("Consolas", 14, bold=True)
                except Exception:
                    self.font = pygame.font.Font(None, 16)
                    self.font_bold = self.font

                if self.font:
                    fw, fh = self.font.size("W")
                    self.cell_w = max(7, fw)
                    self.cell_h = max(14, self.font.get_linesize())
                    self.win_width = self.cols * self.cell_w + self.margin_x * 2
                    self.win_height = self.rows * self.cell_h + self.margin_y * 2
                    if self.win and hasattr(self.win, 'size'):
                        try:
                            self.win.size = (self.win_width, self.win_height)
                            self.win_surf = self.win.get_surface()
                        except Exception:
                            pass
        except Exception:
            pass
        self.active = True
        self.render()

    def close_window(self):
        if VT100Terminal.active_instance is self:
            VT100Terminal.active_instance = None
        if self.win is not None:
            try:
                self.win.destroy()
            except Exception:
                pass
            self.win = None
            self.win_surf = None
        self.active = False

    def cls(self):
        self.text_grid = [[' ' for _ in range(80)] for _ in range(24)]
        self.attr_grid = [[{'bold': False, 'dim': False, 'inverse': False, 'underline': False} for _ in range(80)] for _ in range(24)]
        self.cursor_col = 0
        self.cursor_row = 0
        self.esc_state = 0
        self.param_buf = ''
        self.render()

    def scroll_up(self):
        top = self.top_margin
        bottom = self.bottom_margin
        if 0 <= top < bottom < 24:
            for r in range(top, bottom):
                self.text_grid[r] = list(self.text_grid[r + 1])
                self.attr_grid[r] = [dict(a) for a in self.attr_grid[r + 1]]
            self.text_grid[bottom] = [' '] * 80
            self.attr_grid[bottom] = [{'bold': False, 'dim': False, 'inverse': False, 'underline': False} for _ in range(80)]

    def write_char(self, ch):
        if self.esc_state == 1: # Got ESC (\x1b)
            if ch == '[': # CSI prefix
                self.esc_state = 2
                self.param_buf = ''
                return
            elif ch == 'Y': # VT52 cursor prefix
                self.esc_state = 3
                return
            elif ch == 'A': # Cursor up
                self.cursor_row = max(self.top_margin, self.cursor_row - 1)
                self.esc_state = 0
                return
            elif ch == 'B': # Cursor down
                self.cursor_row = min(self.bottom_margin, self.cursor_row + 1)
                self.esc_state = 0
                return
            elif ch == 'C': # Cursor forward
                self.cursor_col = min(79, self.cursor_col + 1)
                self.esc_state = 0
                return
            elif ch == 'D': # Index / cursor down
                self.cursor_row += 1
                if self.cursor_row > self.bottom_margin:
                    self.scroll_up()
                    self.cursor_row = self.bottom_margin
                self.esc_state = 0
                return
            elif ch == 'M': # Reverse Index / cursor up
                if self.cursor_row == self.top_margin:
                    for r in range(self.bottom_margin, self.top_margin, -1):
                        self.text_grid[r] = list(self.text_grid[r - 1])
                        self.attr_grid[r] = [dict(a) for a in self.attr_grid[r - 1]]
                    self.text_grid[self.top_margin] = [' '] * 80
                    self.attr_grid[self.top_margin] = [{'bold': False, 'dim': False, 'inverse': False, 'underline': False} for _ in range(80)]
                else:
                    self.cursor_row = max(self.top_margin, self.cursor_row - 1)
                self.esc_state = 0
                return
            elif ch == 'E': # Next line
                self.cursor_col = 0
                self.cursor_row += 1
                if self.cursor_row > self.bottom_margin:
                    self.scroll_up()
                    self.cursor_row = self.bottom_margin
                self.esc_state = 0
                return
            elif ch == 'H': # Cursor home
                self.cursor_col = 0
                self.cursor_row = 0
                self.esc_state = 0
                return
            elif ch == 'J': # Clear to end of screen
                for r in range(self.cursor_row, 24):
                    sc = self.cursor_col if r == self.cursor_row else 0
                    for c in range(sc, 80):
                        self.text_grid[r][c] = ' '
                        self.attr_grid[r][c] = {'bold': False, 'dim': False, 'inverse': False, 'underline': False}
                self.esc_state = 0
                return
            elif ch == 'K': # Clear to end of line
                for c in range(self.cursor_col, 80):
                    self.text_grid[self.cursor_row][c] = ' '
                    self.attr_grid[self.cursor_row][c] = {'bold': False, 'dim': False, 'inverse': False, 'underline': False}
                self.esc_state = 0
                return
            elif ch == '7': # Save cursor
                self.saved_cursor = (self.cursor_col, self.cursor_row)
                self.esc_state = 0
                return
            elif ch == '8': # Restore cursor
                self.cursor_col, self.cursor_row = self.saved_cursor
                self.esc_state = 0
                return
            elif ch == 'c': # Reset terminal
                self.cls()
                self.esc_state = 0
                return
            else:
                self.esc_state = 0
                return

        elif self.esc_state == 2: # CSI parameter parsing
            if ch in '0123456789;?':
                self.param_buf += ch
                return
            else:
                raw_params = self.param_buf.lstrip('?').split(';')
                params = [int(p) if p.isdigit() else 0 for p in raw_params] if self.param_buf else []
                is_priv = self.param_buf.startswith('?')
                cmd = ch
                self.esc_state = 0

                if cmd in ('H', 'f'):
                    r = (params[0] - 1) if len(params) > 0 and params[0] > 0 else 0
                    c = (params[1] - 1) if len(params) > 1 and params[1] > 0 else 0
                    self.cursor_row = max(0, min(23, r))
                    self.cursor_col = max(0, min(79, c))
                elif cmd == 'A':
                    cnt = params[0] if params and params[0] > 0 else 1
                    self.cursor_row = max(self.top_margin, self.cursor_row - cnt)
                elif cmd == 'B':
                    cnt = params[0] if params and params[0] > 0 else 1
                    self.cursor_row = min(self.bottom_margin, self.cursor_row + cnt)
                elif cmd == 'C':
                    cnt = params[0] if params and params[0] > 0 else 1
                    self.cursor_col = min(79, self.cursor_col + cnt)
                elif cmd == 'D':
                    cnt = params[0] if params and params[0] > 0 else 1
                    self.cursor_col = max(0, self.cursor_col - cnt)
                elif cmd == 'G':
                    c = (params[0] - 1) if params and params[0] > 0 else 0
                    self.cursor_col = max(0, min(79, c))
                elif cmd == 'd':
                    r = (params[0] - 1) if params and params[0] > 0 else 0
                    self.cursor_row = max(0, min(23, r))
                elif cmd == 'J':
                    code = params[0] if params else 0
                    if code == 2:
                        self.cls()
                    elif code == 0:
                        for r in range(self.cursor_row, 24):
                            sc = self.cursor_col if r == self.cursor_row else 0
                            for c in range(sc, 80):
                                self.text_grid[r][c] = ' '
                                self.attr_grid[r][c] = {'bold': False, 'dim': False, 'inverse': False, 'underline': False}
                    elif code == 1:
                        for r in range(0, self.cursor_row + 1):
                            ec = self.cursor_col if r == self.cursor_row else 79
                            for c in range(0, ec + 1):
                                self.text_grid[r][c] = ' '
                                self.attr_grid[r][c] = {'bold': False, 'dim': False, 'inverse': False, 'underline': False}
                elif cmd == 'K':
                    code = params[0] if params else 0
                    if code == 0:
                        for c in range(self.cursor_col, 80):
                            self.text_grid[self.cursor_row][c] = ' '
                            self.attr_grid[self.cursor_row][c] = {'bold': False, 'dim': False, 'inverse': False, 'underline': False}
                    elif code == 1:
                        for c in range(0, self.cursor_col + 1):
                            self.text_grid[self.cursor_row][c] = ' '
                            self.attr_grid[self.cursor_row][c] = {'bold': False, 'dim': False, 'inverse': False, 'underline': False}
                    elif code == 2:
                        self.text_grid[self.cursor_row] = [' '] * 80
                        self.attr_grid[self.cursor_row] = [{'bold': False, 'dim': False, 'inverse': False, 'underline': False} for _ in range(80)]
                elif cmd == 'm':
                    if not params:
                        params = [0]
                    for p in params:
                        if p == 0:
                            self.cur_attr = {'bold': False, 'dim': False, 'inverse': False, 'underline': False}
                        elif p == 1:
                            self.cur_attr['bold'] = True
                        elif p == 2:
                            self.cur_attr['dim'] = True
                        elif p == 4:
                            self.cur_attr['underline'] = True
                        elif p == 7:
                            self.cur_attr['inverse'] = True
                        elif p == 22:
                            self.cur_attr['bold'] = False
                            self.cur_attr['dim'] = False
                        elif p == 24:
                            self.cur_attr['underline'] = False
                        elif p == 27:
                            self.cur_attr['inverse'] = False
                elif cmd == 'r':
                    t = (params[0] - 1) if len(params) > 0 and params[0] > 0 else 0
                    b = (params[1] - 1) if len(params) > 1 and params[1] > 0 else 23
                    self.top_margin = max(0, min(22, t))
                    self.bottom_margin = max(self.top_margin + 1, min(23, b))
                    self.cursor_col = 0
                    self.cursor_row = self.top_margin
                elif cmd == 's':
                    self.saved_cursor = (self.cursor_col, self.cursor_row)
                elif cmd == 'u':
                    self.cursor_col, self.cursor_row = self.saved_cursor
                elif cmd == 'h':
                    if is_priv and 25 in params:
                        self.cursor_visible = True
                    elif is_priv and 7 in params:
                        self.auto_wrap = True
                elif cmd == 'l':
                    if is_priv and 25 in params:
                        self.cursor_visible = False
                    elif is_priv and 7 in params:
                        self.auto_wrap = False
                elif cmd == 'n':
                    if 6 in params and self.cpm_system:
                        resp = f"\x1b[{self.cursor_row + 1};{self.cursor_col + 1}R"
                        self.cpm_system.key_queue.extend([ord(x) for x in resp])
                elif cmd == 'c':
                    if self.cpm_system:
                        resp = "\x1b[?1;2c"
                        self.cpm_system.key_queue.extend([ord(x) for x in resp])
                return

        elif self.esc_state == 3: # VT52 row
            self.cursor_row = max(0, min(23, ord(ch) - 32))
            self.esc_state = 4
            return
        elif self.esc_state == 4: # VT52 col
            self.cursor_col = max(0, min(79, ord(ch) - 32))
            self.esc_state = 0
            return

        # Normal character processing
        if ch == '\x1b':
            self.esc_state = 1
            return
        elif ch == '\r':
            self.cursor_col = 0
        elif ch == '\n':
            self.cursor_row += 1
            if self.cursor_row > self.bottom_margin:
                self.scroll_up()
                self.cursor_row = self.bottom_margin
        elif ch in ('\b', '\x7f'):
            if self.cursor_col > 0:
                self.cursor_col -= 1
                self.text_grid[self.cursor_row][self.cursor_col] = ' '
                self.attr_grid[self.cursor_row][self.cursor_col] = dict(self.cur_attr)
        elif ch == '\t':
            next_tab = min(79, ((self.cursor_col // 8) + 1) * 8)
            while self.cursor_col < next_tab:
                self.text_grid[self.cursor_row][self.cursor_col] = ' '
                self.attr_grid[self.cursor_row][self.cursor_col] = dict(self.cur_attr)
                self.cursor_col += 1
        elif ch == '\x0c':
            self.cls()
        elif ord(ch) >= 32:
            self.text_grid[self.cursor_row][self.cursor_col] = ch
            self.attr_grid[self.cursor_row][self.cursor_col] = dict(self.cur_attr)
            self.cursor_col += 1
            if self.cursor_col >= 80:
                if self.auto_wrap:
                    self.cursor_col = 0
                    self.cursor_row += 1
                    if self.cursor_row > self.bottom_margin:
                        self.scroll_up()
                        self.cursor_row = self.bottom_margin
                else:
                    self.cursor_col = 79

    def write(self, s):
        for ch in s:
            self.write_char(ch)
        self.render()

    def write_string(self, s):
        self.write(s)

    def render(self):
        if not self.active or self.win_surf is None:
            return
        surf = self.win_surf
        surf.fill(self.COLOR_BG)
        f_norm = self.font
        f_bold = self.font_bold or self.font

        for r in range(24):
            row_y = self.margin_y + r * self.cell_h
            for c in range(80):
                ch = self.text_grid[r][c]
                attrs = self.attr_grid[r][c]
                is_bold = attrs.get('bold', False)
                is_dim = attrs.get('dim', False)
                is_inv = attrs.get('inverse', False)
                is_und = attrs.get('underline', False)

                if is_bold:
                    fg = self.COLOR_BRIGHT_GREEN
                    use_font = f_bold
                elif is_dim:
                    fg = self.COLOR_DIM_GREEN
                    use_font = f_norm
                else:
                    fg = self.COLOR_GREEN
                    use_font = f_norm
                bg = self.COLOR_BG

                if is_inv:
                    fg, bg = bg, fg

                cell_x = self.margin_x + c * self.cell_w
                rect = (cell_x, row_y, self.cell_w, self.cell_h)
                if bg != self.COLOR_BG:
                    surf.fill(bg, rect)

                if ch != ' ':
                    try:
                        ts = use_font.render(ch, True, fg)
                        surf.blit(ts, (cell_x, row_y))
                    except Exception:
                        pass

                if is_und:
                    try:
                        import pygame
                        pygame.draw.line(surf, fg, (cell_x, row_y + self.cell_h - 2), (cell_x + self.cell_w - 1, row_y + self.cell_h - 2), 1)
                    except Exception:
                        pass

        # Draw Cursor
        if self.cursor_visible and self.cursor_blink_on:
            cur_x = self.margin_x + self.cursor_col * self.cell_w
            cur_y = self.margin_y + self.cursor_row * self.cell_h
            try:
                import pygame
                pygame.draw.rect(surf, self.COLOR_CURSOR, (cur_x, cur_y, self.cell_w, self.cell_h), 2)
            except Exception:
                pass

        if self.win and hasattr(self.win, 'flip'):
            try:
                self.win.flip()
            except Exception:
                pass


class CPMScreen:
    """
    Simulates Sinclair ZX Spectrum +3 CP/M display.
    Supports:
      - Mode 32: Standard 32x24 Sinclair Spectrum ROM font (8x8 pixels)
      - Mode 51: Standard +3 CP/M 51x24 narrow font (5x8 pixels)
      - Mode 80: DEC VT100 ANSI terminal window (80x24 green phosphor on black)
    """
    def __init__(self):
        self.display_mode = 51 # 32, 51, 80
        self.cols = 51
        self.rows = 24
        self.cursor_col = 0
        self.cursor_row = 0
        self.text_grid = [[' ' for _ in range(51)] for _ in range(24)]
        self.attr_grid = [[0 for _ in range(51)] for _ in range(24)]
        self.fg_color = 7 # White text on Black background
        self.bg_color = 0
        self.esc_state = 0
        self.esc_param_str = ''
        self.esc_row = 0
        self.esc_col = 0
        self.inverse_mode = False
        self.vt100 = None

    def set_display_mode(self, mode):
        global csize_w, csize_h, canvas_dirty
        mode = int(mode)
        if mode not in (32, 51, 80):
            return
        self.display_mode = mode
        if mode == 32:
            self.cols = 32
            self.rows = 24
            csize_w = 8
            csize_h = 8
            if self.vt100 and self.vt100.active:
                self.vt100.close_window()
            self.cls()
        elif mode == 51:
            self.cols = 51
            self.rows = 24
            csize_w = 5
            csize_h = 8
            if self.vt100 and self.vt100.active:
                self.vt100.close_window()
            self.cls()
        elif mode == 80:
            self.cols = 80
            self.rows = 24
            if not self.vt100:
                self.vt100 = VT100Terminal(cpm_system=globals().get('cpm_system'))
            self.vt100.open_window()
            self.draw_redirect_banner()

    def set_phosphor(self, color_idx):
        global attr_ink, canvas_dirty
        self.fg_color = color_idx
        if 'attr_ink' in globals() and attr_ink:
            for r in range(24):
                for c in range(32):
                    attr_ink[r][c] = color_idx
        canvas_dirty = True
        try:
            redraw_canvas(force=True)
            update_display()
        except Exception:
            pass

    def cls(self):
        global gfx_bits, canvas_dirty, current_paper, current_ink, current_bright, current_border
        global attr_paper, attr_ink, attr_bright, attr_flash
        global screen_chars, cell_bitmap, attr_used, canvas, canvas_lines
        global csize_w, csize_h, cpm_mode_active
        self.esc_state = 0
        self.esc_param_str = ''
        self.inverse_mode = False
        cpm_mode_active = True
        if self.display_mode == 32:
            csize_w = 8
            csize_h = 8
            self.cols = 32
        elif self.display_mode == 80:
            self.cols = 80
            if self.vt100:
                self.vt100.cls()
        else:
            csize_w = 5
            csize_h = 8
            self.cols = 51
        self.rows = 24
        current_border = 0
        if 'gfx_bits' in globals() and gfx_bits:
            for x in range(256):
                col = gfx_bits[x]
                for y in range(192):
                    col[y] = 0
        self.text_grid = [[' ' for _ in range(self.cols)] for _ in range(24)]
        self.attr_grid = [[0 for _ in range(self.cols)] for _ in range(24)]
        self.fg_color = 7
        self.bg_color = 0
        current_paper = 0
        current_ink = 7
        current_bright = 1
        if 'attr_paper' in globals() and attr_paper:
            for r in range(24):
                for c in range(32):
                    attr_paper[r][c] = 0
                    attr_ink[r][c] = 7
                    attr_bright[r][c] = 1
                    attr_flash[r][c] = 0
                    if 'screen_chars' in globals() and screen_chars:
                        screen_chars[r][c] = ' '
                    if 'cell_bitmap' in globals() and cell_bitmap:
                        cell_bitmap[r][c] = None
                    if 'attr_used' in globals() and attr_used:
                        attr_used[r][c] = False
        if 'canvas_lines' in globals() and canvas_lines is not None:
            canvas_lines.clear()
        if 'canvas' in globals() and canvas:
            canvas.fill(COLORS[0])
        if 'ram_banks' in globals() and len(ram_banks) > 5:
            ram_banks[5][0:6144] = b'\x00' * 6144
            ram_banks[5][6144:6912] = b'\x47' * 768
        if 'memory' in globals() and len(memory) >= 23296 and 'ram_banks' in globals() and len(ram_banks) > 5:
            memory[16384:23296] = ram_banks[5][:6912]
        if 'z80_cpu' in globals() and z80_cpu is not None:
            z80_cpu.screen_dirty = False
        self.cursor_col = 0
        self.cursor_row = 0
        canvas_dirty = True
        try:
            redraw_canvas(force=True)
            update_display()
        except Exception:
            pass

    def draw_redirect_banner(self):
        global canvas_dirty
        self.cls()
        banner_lines = [
            "========================================",
            " SINCLAIR ZX SPECTRUM +3 CP/M PLUS v3.0 ",
            "========================================",
            "VT100 SERIAL TERMINAL REDIRECTION ACTIVE",
            "Port: ZX Interface 1 RS-232 Channel 'b'",
            "Format: 80 Columns x 24 Rows Monochrome",
            "Screen: Green Phosphor CRT Terminal     ",
            "Status: All BDOS/BIOS Output Redirected ",
            "",
            "The CP/M Console is running inside the  ",
            "dedicated VT100 Terminal Window.        ",
            "",
            "To return console output to this screen:",
            "  Type: DISPLAY 32  (Standard Spectrum) ",
            "  Type: DISPLAY 51  (+3 CP/M 51-column) ",
            "========================================"
        ]
        old_cols = self.cols
        self.cols = 51
        for r, line in enumerate(banner_lines):
            for c, ch in enumerate(line[:51]):
                self.draw_char(c + 5, r + 4, ch)
        self.cols = old_cols
        canvas_dirty = True
        try:
            redraw_canvas(force=True)
            update_display()
        except Exception:
            pass

    def draw_char(self, col, row, ch, inverse=False):
        global gfx_bits, canvas_dirty
        if self.display_mode == 80:
            return
        if 0 <= col < self.cols and 0 <= row < self.rows:
            self.text_grid[row][col] = ch
            self.attr_grid[row][col] = 1 if inverse else 0
            if 'gfx_bits' in globals() and gfx_bits:
                if self.cols == 32:
                    px_base = col * 8
                    py_base = row * 8
                    code = ord(ch)
                    if 32 <= code <= 127 and 'ZX_ROM_FONT' in globals() and len(ZX_ROM_FONT) >= 768:
                        off = (code - 32) * 8
                        glyph = ZX_ROM_FONT[off : off + 8]
                    else:
                        glyph = (0, 0, 0, 0, 0, 0, 0, 0)
                    for dy in range(8):
                        row_bits = glyph[dy]
                        y_bmp = 191 - (py_base + dy)
                        for dx in range(8):
                            bit = (row_bits >> (7 - dx)) & 1
                            if inverse:
                                bit = 1 - bit
                            gfx_bits[px_base + dx][y_bmp] = bit
                    canvas_dirty = True
                else: # 51 columns
                    px_base = col * 5
                    py_base = row * 8
                    glyph = CPM_5X8_FONT.get(ch, CPM_5X8_FONT.get('?', (0, 0, 0, 0, 0, 0, 0, 0)))
                    for dy in range(8):
                        row_bits = glyph[dy]
                        y_bmp = 191 - (py_base + dy)
                        for dx in range(5):
                            bit = (row_bits >> (4 - dx)) & 1
                            if inverse:
                                bit = 1 - bit
                            gfx_bits[px_base + dx][y_bmp] = bit
                    canvas_dirty = True

    def draw_cursor(self, visible):
        if self.display_mode == 80:
            if self.vt100 and self.vt100.active:
                self.vt100.cursor_blink_on = visible
                self.vt100.render()
            return
        if 0 <= self.cursor_col < self.cols and 0 <= self.cursor_row < self.rows:
            ch = self.text_grid[self.cursor_row][self.cursor_col]
            self.draw_char(self.cursor_col, self.cursor_row, ch, inverse=visible)

    def scroll_up(self):
        global gfx_bits, canvas_dirty
        if self.display_mode == 80:
            return
        self.text_grid.pop(0)
        self.text_grid.append([' '] * self.cols)
        self.attr_grid.pop(0)
        self.attr_grid.append([0] * self.cols)
        if 'gfx_bits' in globals() and gfx_bits:
            for x in range(256):
                col_bits = gfx_bits[x]
                for y in range(184):
                    col_bits[191 - y] = col_bits[191 - (y + 8)]
                for y in range(184, 192):
                    col_bits[191 - y] = 0
            canvas_dirty = True

    def putc(self, ch):
        if self.display_mode == 80:
            if not self.vt100 or not self.vt100.active:
                self.set_display_mode(80)
            self.vt100.write_char(ch)
            return

        # Escape sequence state machine
        if self.esc_state == 1: # Got ESC (\x1b)
            if ch == '[': # ANSI prefix
                self.esc_state = 2
                self.esc_param_str = ''
                return
            elif ch in ('Y', '='): # VT52 / ADM-3A cursor addressing prefix
                self.esc_state = 3
                return
            elif ch == 'A': # Cursor up
                self.cursor_row = max(0, self.cursor_row - 1)
                self.esc_state = 0
                return
            elif ch == 'B': # Cursor down
                self.cursor_row = min(self.rows - 1, self.cursor_row + 1)
                self.esc_state = 0
                return
            elif ch == 'C': # Cursor right
                self.cursor_col = min(self.cols - 1, self.cursor_col + 1)
                self.esc_state = 0
                return
            elif ch == 'D': # Cursor left
                self.cursor_col = max(0, self.cursor_col - 1)
                self.esc_state = 0
                return
            elif ch == 'H': # Cursor home
                self.cursor_row = 0
                self.cursor_col = 0
                self.esc_state = 0
                return
            elif ch == 'J': # Clear to end of screen
                for r in range(self.cursor_row, self.rows):
                    start_c = self.cursor_col if r == self.cursor_row else 0
                    for c in range(start_c, self.cols):
                        self.draw_char(c, r, ' ')
                self.esc_state = 0
                return
            elif ch == 'K': # Clear to end of line
                for c in range(self.cursor_col, self.cols):
                    self.draw_char(c, self.cursor_row, ' ')
                self.esc_state = 0
                return
            else:
                self.esc_state = 0
                return

        elif self.esc_state == 2: # ANSI parameter parsing
            if ch in '0123456789;?':
                self.esc_param_str += ch
                return
            else:
                cmd = ch
                raw_params = self.esc_param_str.lstrip('?').split(';')
                params = [int(p) if p.isdigit() else 0 for p in raw_params] if self.esc_param_str else []
                if cmd in ('H', 'f'): # Cursor position
                    r = (params[0] - 1) if len(params) > 0 and params[0] > 0 else 0
                    c = (params[1] - 1) if len(params) > 1 and params[1] > 0 else 0
                    self.cursor_row = max(0, min(self.rows - 1, r))
                    self.cursor_col = max(0, min(self.cols - 1, c))
                elif cmd == 'J':
                    code = params[0] if params else 0
                    if code == 2: self.cls()
                    elif code == 0:
                        for r in range(self.cursor_row, self.rows):
                            start_c = self.cursor_col if r == self.cursor_row else 0
                            for c in range(start_c, self.cols): self.draw_char(c, r, ' ')
                elif cmd == 'K':
                    for c in range(self.cursor_col, self.cols):
                        self.draw_char(c, self.cursor_row, ' ')
                elif cmd == 'm': # Graphic rendition
                    if not params or 0 in params:
                        self.inverse_mode = False
                    if 7 in params:
                        self.inverse_mode = True
                elif cmd == 'A': # Up
                    cnt = params[0] if params and params[0] > 0 else 1
                    self.cursor_row = max(0, self.cursor_row - cnt)
                elif cmd == 'B': # Down
                    cnt = params[0] if params and params[0] > 0 else 1
                    self.cursor_row = min(self.rows - 1, self.cursor_row + cnt)
                elif cmd == 'C': # Forward
                    cnt = params[0] if params and params[0] > 0 else 1
                    self.cursor_col = min(self.cols - 1, self.cursor_col + cnt)
                elif cmd == 'D': # Backward
                    cnt = params[0] if params and params[0] > 0 else 1
                    self.cursor_col = max(0, self.cursor_col - cnt)
                self.esc_state = 0
                return

        elif self.esc_state == 3: # VT52 / ADM-3A Row
            self.esc_row = ord(ch) - 32
            self.esc_state = 4
            return

        elif self.esc_state == 4: # VT52 / ADM-3A Col
            self.esc_col = ord(ch) - 32
            self.cursor_row = max(0, min(self.rows - 1, self.esc_row))
            self.cursor_col = max(0, min(self.cols - 1, self.esc_col))
            self.esc_state = 0
            return

        if ch == '\x1b': # ESC
            self.esc_state = 1
            return
        elif ch == '\x1a': # ADM-3A / Kaypro cls
            self.cls()
            return
        elif ch == '\x1e': # ADM-3A cursor home
            self.cursor_row = 0
            self.cursor_col = 0
            return
        elif ch == '\r':
            self.cursor_col = 0
        elif ch == '\n':
            self.cursor_row += 1
            if self.cursor_row >= self.rows:
                self.scroll_up()
                self.cursor_row = self.rows - 1
        elif ch in ('\b', '\x7f'):
            if self.cursor_col > 0:
                self.cursor_col -= 1
                self.draw_char(self.cursor_col, self.cursor_row, ' ')
        elif ch == '\t':
            next_tab = ((self.cursor_col // 8) + 1) * 8
            while self.cursor_col < next_tab and self.cursor_col < self.cols:
                self.putc(' ')
        elif ch == '\x0c':
            self.cls()
        elif ord(ch) >= 32:
            self.draw_char(self.cursor_col, self.cursor_row, ch, inverse=self.inverse_mode)
            self.cursor_col += 1
            if self.cursor_col >= self.cols:
                self.cursor_col = 0
                self.cursor_row += 1
                if self.cursor_row >= self.rows:
                    self.scroll_up()
                    self.cursor_row = self.rows - 1

    def puts(self, s):
        if self.display_mode == 80:
            if not self.vt100 or not self.vt100.active:
                self.set_display_mode(80)
            self.vt100.write(s)
            return
        global canvas_dirty
        for ch in s:
            self.putc(ch)
        canvas_dirty = True
        try:
            redraw_canvas(force=True)
            update_display()
        except Exception:
            pass


class JumpTarget(Exception):
    def __init__(self, l_idx, s_idx):
        self.l_idx = l_idx
        self.s_idx = s_idx

class EndProgram(Exception): pass
class StopProgram(Exception):
    def __init__(self, line_num, l_idx, s_idx):
        self.line_num = line_num
        self.l_idx = l_idx
        self.s_idx = s_idx

class ErrorTrapped(Exception):
    def __init__(self, code, line_num):
        self.code = code
        self.line_num = line_num


def format_using(fmt, values):
    """
    Locomotive Mallard-80 BASIC PRINT USING implementation.
    Handles numeric masks (#, ., ,, +, -, $$, **, **$, ^^^^) and
    string masks (!, \\ \\, &).
    """
    result = []
    val_idx = 0
    fmt_idx = 0
    flen = len(fmt)

    while fmt_idx < flen and val_idx < len(values):
        ch = fmt[fmt_idx]

        # String formatting: ! (first char), & (all), \  \ (fixed width)
        if ch == '!':
            val = str(values[val_idx])
            result.append(val[:1] if val else " ")
            val_idx += 1
            fmt_idx += 1
            continue
        elif ch == '&':
            result.append(str(values[val_idx]))
            val_idx += 1
            fmt_idx += 1
            continue
        elif ch == '\\':
            end_slash = fmt.find('\\', fmt_idx + 1)
            if end_slash != -1:
                width = end_slash - fmt_idx + 1
                val = str(values[val_idx])
                result.append(val[:width].ljust(width))
                val_idx += 1
                fmt_idx = end_slash + 1
                continue

        # Numeric formatting
        m_num = re.match(r'(\*{2}\$|\*{2}|\${2}|[+\-]?)(#+)(?:(\.)(#*))?(\^{4})?([+\-]?)', fmt[fmt_idx:])
        if m_num and (m_num.group(2) or m_num.group(1)):
            full_match = m_num.group(0)
            prefix = m_num.group(1)
            int_hashes = m_num.group(2) or ""
            dec_point = m_num.group(3) or ""
            dec_hashes = m_num.group(4) or ""
            expo = m_num.group(5)
            suffix_sign = m_num.group(6)

            val = values[val_idx]
            val_idx += 1
            fmt_idx += len(full_match)

            try:
                num = float(val)
            except Exception:
                num = 0.0

            dec_places = len(dec_hashes)
            is_neg = num < 0
            abs_num = abs(num)

            if expo:
                # Exponential notation
                formatted = f"{abs_num:.{dec_places}e}".upper()
            else:
                formatted = f"{abs_num:.{dec_places}f}"

            parts = formatted.split('.')
            int_part = parts[0]
            dec_part = ("." + parts[1]) if len(parts) > 1 else ""

            # Check for comma grouping in hashes
            if ',' in int_hashes:
                int_part = f"{int(int_part):,}"

            body = int_part + dec_part
            req_width = len(int_hashes) + (1 + len(dec_hashes) if dec_point else 0)

            # Prefixes: **, $$, **$
            dollar = ""
            fill_char = " "
            if prefix == "**$":
                dollar = "$"
                fill_char = "*"
                req_width += 3
            elif prefix == "$$":
                dollar = "$"
                req_width += 2
            elif prefix == "**":
                fill_char = "*"
                req_width += 2

            sign_str = ""
            if prefix == "+" or suffix_sign == "+":
                sign_str = "+" if not is_neg else "-"
            elif is_neg:
                sign_str = "-"

            if len(body) + len(dollar) > req_width:
                # Overflow flag in BASIC is '%'
                res_item = "%" + (dollar if dollar else "") + body
            else:
                pad_len = max(0, req_width - len(body) - len(dollar))
                padded = (fill_char * pad_len) + dollar + body
                if suffix_sign and sign_str:
                    res_item = padded + sign_str
                elif sign_str:
                    res_item = sign_str + padded
                else:
                    res_item = padded

            result.append(res_item)
            continue

        # Literal character
        if ch == '_':
            fmt_idx += 1
            if fmt_idx < flen:
                result.append(fmt[fmt_idx])
                fmt_idx += 1
        else:
            result.append(ch)
            fmt_idx += 1

    # Remaining format characters
    if fmt_idx < flen:
        result.append(fmt[fmt_idx:])

    return "".join(result)


class MallardBASIC:
    """
    Complete Locomotive Mallard-80 BASIC interpreter for Sinclair ZX Spectrum +3 CP/M.
    Supports complete grammar, commands, statements, functions, operators, sequential
    and random-access file handling, and error handling with full isolation from Spectrum mode.
    """
    SPECTRUM_ONLY_KEYWORDS = {
        "BEEP", "BORDER", "INK", "PAPER", "FLASH", "BRIGHT", "INVERSE", "OVER",
        "PLOT", "DRAW", "CIRCLE", "CAT", "VERIFY", "MERGE_SPEC", "FORMAT_SPEC"
    }

    def __init__(self, cpm_system):
        self.cpm = cpm_system
        self.program = {}      # {line_num: line_code}
        self.vars = {}         # {name: value}
        self.arrays = {}       # {name: array_data}
        self.user_fns = {}     # {name: (arg_names, expr_str)}
        self.default_types = {} # {letter: type_code ('I', 'S', 'D', 'S')}
        self.usr_addrs = {}    # {n: address}
        self.open_files = {}   # {stream_num: file_dict}
        self.field_defs = {}   # {stream_num: [(length, var_name)]}
        self.rec_buffers = {}  # {stream_num: bytearray}

        self.running = False
        self.active = False
        self.gosub_stack = []
        self.for_stack = []
        self.while_stack = []
        self.data_items = []
        self.data_ptr = 0
        self.trace_active = False

        # Error handling
        self.error_handler_line = 0
        self.last_err_code = 0
        self.last_err_line = 0
        self.break_target = None
        self.common_vars = set()

    def banner(self):
        self.cpm.screen.puts("Mallard-80 BASIC with Jet Version 1.29\r\n")
        self.cpm.screen.puts("(c) 1987 Locomotive Software Ltd\r\n")
        self.cpm.screen.puts("43285 Bytes free\r\n")
        self.cpm.screen.puts("Ok\r\n")

    def execute_line(self, line):
        line = line.strip()
        if not line:
            return

        # Check for line number entry / edit
        m_ln = re.match(r'^(\d+)\s*(.*)', line)
        if m_ln:
            ln = int(m_ln.group(1))
            code = m_ln.group(2).strip()
            if code:
                self.program[ln] = code
            elif ln in self.program:
                del self.program[ln]
            return

        cmd_upper = line.upper()

        # Check for Spectrum command crossover attempt
        first_token = cmd_upper.split()[0].rstrip(':')
        if first_token in self.SPECTRUM_ONLY_KEYWORDS:
            self.cpm.screen.puts(f"Syntax error (Spectrum keyword '{first_token}' not valid in CP/M Mallard BASIC)\r\n")
            self.cpm.screen.puts("Ok\r\n")
            return

        # Direct commands
        if cmd_upper == "SYSTEM":
            self.active = False
            self.cpm.active_app = None
            return
        elif cmd_upper == "NEW":
            self.cmd_new()
            self.cpm.screen.puts("Ok\r\n")
        elif cmd_upper == "RESET":
            self.cmd_close("")
            self.cpm.screen.puts("Ok\r\n")
        elif cmd_upper == "RUN" or cmd_upper.startswith("RUN "):
            start_ln = 0
            if len(line) > 4:
                try: start_ln = int(line[4:].strip())
                except: start_ln = 0
            self.run_program(start_ln)
        elif cmd_upper == "CONT":
            self.cmd_cont()
        elif cmd_upper == "LIST" or cmd_upper.startswith("LIST "):
            self.list_program(line[5:].strip())
            self.cpm.screen.puts("Ok\r\n")
        elif cmd_upper == "LLIST" or cmd_upper.startswith("LLIST "):
            pdf_path = prompt_save_pdf_filename(default_name="program.pdf", title="Save CP/M Program Listing PDF")
            if not pdf_path:
                self.cpm.screen.puts("Print listing cancelled\r\n")
            else:
                self.list_program(line[6:].strip(), printer=True, pdf_path=pdf_path)
                self.cpm.screen.puts("Ok\r\n")
        elif cmd_upper == "TRON":
            self.trace_active = True
            self.cpm.screen.puts("Ok\r\n")
        elif cmd_upper == "TROFF":
            self.trace_active = False
            self.cpm.screen.puts("Ok\r\n")
        elif cmd_upper.startswith("DELETE") or cmd_upper.startswith("DELETE "):
            self.cmd_delete(line[6:].strip())
            self.cpm.screen.puts("Ok\r\n")
        elif cmd_upper.startswith("RENUM") or cmd_upper.startswith("RENUM "):
            self.cmd_renum(line[5:].strip())
            self.cpm.screen.puts("Ok\r\n")
        elif cmd_upper.startswith("AUTO") or cmd_upper.startswith("AUTO "):
            self.cmd_auto(line[4:].strip())
        elif cmd_upper.startswith("LOAD ") or cmd_upper.startswith("LOAD\""):
            arg = line[4:].strip().strip('"').strip("'")
            self.load_file(arg)
            self.cpm.screen.puts("Ok\r\n")
        elif cmd_upper.startswith("SAVE ") or cmd_upper.startswith("SAVE\""):
            arg = line[4:].strip().strip('"').strip("'")
            self.save_file(arg)
            self.cpm.screen.puts("Ok\r\n")
        elif cmd_upper.startswith("MERGE ") or cmd_upper.startswith("MERGE\""):
            arg = line[5:].strip().strip('"').strip("'")
            self.merge_file(arg)
            self.cpm.screen.puts("Ok\r\n")
        elif cmd_upper in ("FILES", "DIR") or cmd_upper.startswith("FILES ") or cmd_upper.startswith("DIR "):
            p = line.split(None, 1)
            pat = p[1].strip().strip('"').strip("'") if len(p) > 1 else ""
            self.cpm.cmd_dir(pat)
            self.cpm.screen.puts("Ok\r\n")
        elif cmd_upper.startswith("KILL ") or cmd_upper.startswith("KILL\""):
            arg = line[4:].strip().strip('"').strip("'")
            drv, fn = self.cpm.parse_filespec(arg)
            self.cpm.delete_file(drv, fn, self.cpm.current_user)
            self.cpm.screen.puts("Ok\r\n")
        elif cmd_upper.startswith("NAME "):
            # NAME old$ AS new$
            m_name = re.match(r'(?i)^NAME\s+(.*?)\s+AS\s+(.*)$', line)
            if m_name:
                self.cpm.cmd_ren(f"{m_name.group(2).strip()}={m_name.group(1).strip()}")
            self.cpm.screen.puts("Ok\r\n")
        else:
            # Direct statement execution
            try:
                stmts = self.split_statements(line)
                for s in stmts:
                    self.exec_single_statement(s, 0, 0, [(0, stmts)])
            except StopProgram as sp:
                self.cpm.screen.puts(f"Break in {sp.line_num}\r\n")
            except Exception as e:
                self.cpm.screen.puts(f"Error: {e}\r\n")
            self.cpm.screen.puts("Ok\r\n")

    def cmd_new(self):
        self.program.clear()
        self.vars.clear()
        self.arrays.clear()
        self.user_fns.clear()
        self.default_types.clear()
        self.cmd_close("")
        self.break_target = None
        self.error_handler_line = 0

    def cmd_delete(self, arg):
        if not arg:
            return
        if '-' in arg:
            p = arg.split('-')
            start = int(p[0]) if p[0].strip() else 0
            end = int(p[1]) if p[1].strip() else 65535
            for ln in list(self.program.keys()):
                if start <= ln <= end:
                    del self.program[ln]
        else:
            try:
                ln = int(arg)
                if ln in self.program:
                    del self.program[ln]
            except:
                pass

    def cmd_renum(self, arg):
        # RENUM [new_start][,[old_start][,inc]]
        new_start = 10
        old_start = 0
        inc = 10
        if arg:
            parts = [p.strip() for p in arg.split(',')]
            if len(parts) > 0 and parts[0]:
                try: new_start = int(parts[0])
                except: pass
            if len(parts) > 1 and parts[1]:
                try: old_start = int(parts[1])
                except: pass
            if len(parts) > 2 and parts[2]:
                try: inc = int(parts[2])
                except: pass

        old_lines = sorted(self.program.keys())
        line_map = {}
        cur = new_start
        for ln in old_lines:
            if ln >= old_start:
                line_map[ln] = cur
                cur += inc
            else:
                line_map[ln] = ln

        # Re-map line references in code
        new_prog = {}
        for ln in old_lines:
            code = self.program[ln]
            # Replace GOTO/GOSUB/THEN/ELSE/RESTORE targets
            def repl_target(m):
                kw = m.group(1)
                tgt = int(m.group(2))
                new_tgt = line_map.get(tgt, tgt)
                return f"{kw} {new_tgt}"

            code = re.sub(r'(?i)\b(GOTO|GO\s+TO|GOSUB|GO\s+SUB|THEN|ELSE|RESTORE|RESUME)\s+(\d+)', repl_target, code)
            new_prog[line_map[ln]] = code

        self.program = new_prog

    def cmd_auto(self, arg):
        self.cpm.screen.puts("AUTO line numbering active. Press Enter on empty line to exit.\r\n")

    def cmd_cont(self):
        if self.break_target:
            l_idx, s_idx, lines = self.break_target
            self.break_target = None
            self.resume_execution(l_idx, s_idx, lines)
        else:
            self.cpm.screen.puts("Can't continue\r\n")
            self.cpm.screen.puts("Ok\r\n")

    def split_statements(self, line):
        stmts = []
        cur = []
        in_q = False
        for ch in line:
            if ch == '"':
                in_q = not in_q
                cur.append(ch)
            elif ch == ':' and not in_q:
                stmts.append("".join(cur).strip())
                cur = []
            else:
                cur.append(ch)
        if cur:
            stmts.append("".join(cur).strip())
        return stmts

    def list_program(self, range_arg="", printer=False, pdf_path=None):
        if not self.program:
            return
        start_ln = 0
        end_ln = 65535
        if range_arg:
            if '-' in range_arg:
                p = range_arg.split('-')
                if p[0].strip(): start_ln = int(p[0])
                if p[1].strip(): end_ln = int(p[1])
            else:
                try:
                    start_ln = int(range_arg)
                    end_ln = start_ln
                except:
                    pass
        llist_printer = ZXPrinterPDF(output_path=pdf_path) if (printer and pdf_path) else zx_printer
        for ln in sorted(self.program.keys()):
            if start_ln <= ln <= end_ln:
                out_line = f"{ln} {self.program[ln]}\r\n"
                if printer and llist_printer:
                    llist_printer.print_text(f"{ln} {self.program[ln]}")
                self.cpm.screen.puts(out_line)
        if printer and llist_printer:
            llist_printer.flush()

    def load_file(self, filename, run_after=False):
        drv, fn = self.cpm.parse_filespec(filename)
        if not fn.upper().endswith(".BAS"):
            fn += ".BAS"
        f = self.cpm.get_file(drv, fn, self.cpm.current_user)
        if not f:
            self.cpm.screen.puts("File not found\r\n")
            return False
        self.cmd_new()
        text = f['data'].decode('ascii', errors='replace')
        for l in text.splitlines():
            l = l.strip()
            if not l: continue
            m = re.match(r'^(\d+)\s*(.*)', l)
            if m:
                self.program[int(m.group(1))] = m.group(2).strip()
        if run_after:
            self.run_program()
        return True

    def save_file(self, filename, ascii_format=True):
        drv, fn = self.cpm.parse_filespec(filename)
        if not fn.upper().endswith(".BAS"):
            fn += ".BAS"
        out_lines = []
        for ln in sorted(self.program.keys()):
            out_lines.append(f"{ln} {self.program[ln]}")
        data = ("\r\n".join(out_lines) + "\r\n").encode('ascii')
        self.cpm.put_file(drv, fn, data, self.cpm.current_user)

    def merge_file(self, filename):
        drv, fn = self.cpm.parse_filespec(filename)
        if not fn.upper().endswith(".BAS"):
            fn += ".BAS"
        f = self.cpm.get_file(drv, fn, self.cpm.current_user)
        if not f:
            self.cpm.screen.puts(f"File not found: {filename}\r\n")
            return False
        raw_bytes = f['data'] if isinstance(f, dict) else f
        data = raw_bytes.decode('latin-1', errors='replace')
        text = data
        for l in text.splitlines():
            l = l.strip()
            if not l: continue
            m = re.match(r'^(\d+)\s*(.*)', l)
            if m:
                self.program[int(m.group(1))] = m.group(2).strip()
        return True

    def eval_expr(self, expr):
        expr = expr.strip()
        if not expr:
            return 0
        if expr.startswith('"') and expr.endswith('"') and expr.count('"') == 2:
            return expr[1:-1]

        # Power operator ^ to **
        clean_expr = expr
        clean_expr = clean_expr.replace('^', '**')

        # Relational & Logical replacements
        clean_expr = re.sub(r'<>', '!=', clean_expr)
        clean_expr = re.sub(r'(?<![<>=!])=(?![=])', '==', clean_expr)
        clean_expr = re.sub(r'\\', '//', clean_expr) # Integer division
        clean_expr = re.sub(r'(?i)\bMOD\b', '%', clean_expr)
        clean_expr = re.sub(r'(?i)\bAND\b', ' and ', clean_expr)
        clean_expr = re.sub(r'(?i)\bOR\b', ' or ', clean_expr)
        clean_expr = re.sub(r'(?i)\bNOT\b', ' not ', clean_expr)
        clean_expr = re.sub(r'(?i)\bXOR\b', ' ^ ', clean_expr)
        clean_expr = re.sub(r'(?i)\bEQV\b', ' == ', clean_expr)

        # Built-in math functions
        clean_expr = re.sub(r'(?i)\bSQR\b', 'math.sqrt', clean_expr)
        clean_expr = re.sub(r'(?i)\bINT\b', 'int', clean_expr)
        clean_expr = re.sub(r'(?i)\bFIX\b', 'math.trunc', clean_expr)
        clean_expr = re.sub(r'(?i)\bABS\b', 'abs', clean_expr)
        clean_expr = re.sub(r'(?i)\bSGN\b', 'self._fn_sgn', clean_expr)
        clean_expr = re.sub(r'(?i)\bSIN\b', 'math.sin', clean_expr)
        clean_expr = re.sub(r'(?i)\bCOS\b', 'math.cos', clean_expr)
        clean_expr = re.sub(r'(?i)\bTAN\b', 'math.tan', clean_expr)
        clean_expr = re.sub(r'(?i)\bATN\b', 'math.atan', clean_expr)
        clean_expr = re.sub(r'(?i)\bLOG\b', 'math.log', clean_expr)
        clean_expr = re.sub(r'(?i)\bEXP\b', 'math.exp', clean_expr)
        clean_expr = re.sub(r'(?i)\bRND\b', 'self._fn_rnd', clean_expr)
        clean_expr = re.sub(r'(?i)\bCINT\b', 'int', clean_expr)
        clean_expr = re.sub(r'(?i)\bCSNG\b', 'float', clean_expr)
        clean_expr = re.sub(r'(?i)\bCDBL\b', 'float', clean_expr)

        # Built-in string functions
        clean_expr = re.sub(r'(?i)\bLEN\b', 'len', clean_expr)
        clean_expr = re.sub(r'(?i)\bCHR\$', 'chr', clean_expr)
        clean_expr = re.sub(r'(?i)\bASC\b', 'ord', clean_expr)
        clean_expr = re.sub(r'(?i)\bSTR\$', 'self._fn_str', clean_expr)
        clean_expr = re.sub(r'(?i)\bVAL\b', 'self._fn_val', clean_expr)
        clean_expr = re.sub(r'(?i)\bLEFT\$', 'self._fn_left', clean_expr)
        clean_expr = re.sub(r'(?i)\bRIGHT\$', 'self._fn_right', clean_expr)
        clean_expr = re.sub(r'(?i)\bMID\$', 'self._fn_mid', clean_expr)
        clean_expr = re.sub(r'(?i)\bINSTR\b', 'self._fn_instr', clean_expr)
        clean_expr = re.sub(r'(?i)\bSTRING\$', 'self._fn_string', clean_expr)
        clean_expr = re.sub(r'(?i)\bSPACE\$', 'self._fn_space', clean_expr)
        clean_expr = re.sub(r'(?i)\bHEX\$', 'self._fn_hex', clean_expr)
        clean_expr = re.sub(r'(?i)\bOCT\$', 'self._fn_oct', clean_expr)

        # Binary pack/unpack functions
        clean_expr = re.sub(r'(?i)\bMKI\$', 'self._fn_mki', clean_expr)
        clean_expr = re.sub(r'(?i)\bCVI\b', 'self._fn_cvi', clean_expr)
        clean_expr = re.sub(r'(?i)\bMKS\$', 'self._fn_mks', clean_expr)
        clean_expr = re.sub(r'(?i)\bCVS\b', 'self._fn_cvs', clean_expr)
        clean_expr = re.sub(r'(?i)\bMKD\$', 'self._fn_mkd', clean_expr)
        clean_expr = re.sub(r'(?i)\bCVD\b', 'self._fn_cvd', clean_expr)

        # Hardware & Environment
        clean_expr = re.sub(r'(?i)\bPEEK\b', 'self._fn_peek', clean_expr)
        clean_expr = re.sub(r'(?i)\bINP\b', 'self._fn_inp', clean_expr)
        clean_expr = re.sub(r'(?i)\bPOS\(.*?\)', 'self.cpm.screen.cursor_col', clean_expr)
        clean_expr = re.sub(r'(?i)\bFRE\(.*?\)', '43285', clean_expr)
        clean_expr = re.sub(r'(?i)\bEOF\b', 'self._fn_eof', clean_expr)
        clean_expr = re.sub(r'(?i)\bLOF\b', 'self._fn_lof', clean_expr)
        clean_expr = re.sub(r'(?i)\bLOC\b', 'self._fn_loc', clean_expr)
        clean_expr = re.sub(r'(?i)\bERR\b', 'self.last_err_code', clean_expr)
        clean_expr = re.sub(r'(?i)\bERL\b', 'self.last_err_line', clean_expr)

        # Mangle remaining variable identifiers ending in $, %, !, #
        clean_expr = re.sub(r'\b([A-Za-z][A-Za-z0-9]*)\$', r'\1_str', clean_expr)
        clean_expr = re.sub(r'\b([A-Za-z][A-Za-z0-9]*)%', r'\1_int', clean_expr)
        clean_expr = re.sub(r'\b([A-Za-z][A-Za-z0-9]*)!', r'\1_sng', clean_expr)
        clean_expr = re.sub(r'\b([A-Za-z][A-Za-z0-9]*)#', r'\1_dbl', clean_expr)

        # Evaluation context
        ctx = {
            "math": math, "len": len, "chr": chr, "ord": ord, "str": str,
            "float": float, "int": int, "abs": abs, "self": self
        }
        for k, v in self.vars.items():
            clean_k = k
            if clean_k.endswith('$'): clean_k = clean_k[:-1] + "_str"
            elif clean_k.endswith('%'): clean_k = clean_k[:-1] + "_int"
            elif clean_k.endswith('!'): clean_k = clean_k[:-1] + "_sng"
            elif clean_k.endswith('#'): clean_k = clean_k[:-1] + "_dbl"
            ctx[clean_k] = v
            ctx[k] = v

        try:
            tree = ast.parse(clean_expr, mode='eval')
            # Reject any attribute access, function calls to non-whitelisted names,
            # imports, or other dangerous AST nodes
            for node in ast.walk(tree):
                if isinstance(node, (ast.Attribute, ast.Import, ast.ImportFrom)):
                    raise ValueError(f"Disallowed expression node: {type(node).__name__}")
            code_obj = compile(tree, '<mbasic_expr>', 'eval')
            return eval(code_obj, {"__builtins__": {}}, ctx)
        except Exception:
            up = expr.upper()
            if up in self.vars:
                return self.vars[up]
            return expr

    # Helper built-ins
    def _fn_sgn(self, x): return -1 if x < 0 else (1 if x > 0 else 0)
    def _fn_rnd(self, x=1): return random.random()
    def _fn_str(self, x): return f" {x}" if x >= 0 else str(x)
    def _fn_val(self, s):
        try: return float(s) if '.' in str(s) else int(s)
        except: return 0
    def _fn_left(self, s, n): return str(s)[:int(n)]
    def _fn_right(self, s, n): n = int(n); return str(s)[-n:] if n > 0 else ""
    def _fn_mid(self, s, start, length=None):
        st = int(start) - 1
        s_str = str(s)
        if length is None: return s_str[st:]
        return s_str[st : st + int(length)]
    def _fn_instr(self, *args):
        if len(args) == 2:
            s1, s2 = str(args[0]), str(args[1])
            pos = s1.find(s2)
            return pos + 1 if pos != -1 else 0
        elif len(args) == 3:
            start = max(1, int(args[0]))
            s1, s2 = str(args[1]), str(args[2])
            pos = s1.find(s2, start - 1)
            return pos + 1 if pos != -1 else 0
        return 0
    def _fn_string(self, n, c):
        ch = c[0] if isinstance(c, str) and c else chr(int(c))
        return ch * int(n)
    def _fn_space(self, n): return " " * int(n)
    def _fn_hex(self, x): return f"{int(x):X}"
    def _fn_oct(self, x): return f"{int(x):o}"
    def _fn_mki(self, val): return struct.pack("<h", int(val) & 0xFFFF).decode('latin1')
    def _fn_cvi(self, s): return struct.unpack("<h", s[:2].encode('latin1'))[0]
    def _fn_mks(self, val): return struct.pack("<f", float(val)).decode('latin1')
    def _fn_cvs(self, s): return struct.unpack("<f", s[:4].encode('latin1'))[0]
    def _fn_mkd(self, val): return struct.pack("<d", float(val)).decode('latin1')
    def _fn_cvd(self, s): return struct.unpack("<d", s[:8].encode('latin1'))[0]
    def _fn_peek(self, addr): return self.cpm.tpa_memory[int(addr) & 0xFFFF]
    def _fn_inp(self, port): return 0
    def _fn_eof(self, stream_num):
        f = self.open_files.get(stream_num)
        if not f: return -1
        return -1 if f['ptr'] >= len(f['data']) else 0
    def _fn_lof(self, stream_num):
        f = self.open_files.get(stream_num)
        return len(f['data']) if f else 0
    def _fn_loc(self, stream_num):
        f = self.open_files.get(stream_num)
        return (f['ptr'] // 128) + 1 if f else 0

    def exec_single_statement(self, stmt, l_idx, s_idx, lines):
        stmt = stmt.strip()
        if not stmt:
            return
        stmt_u = stmt.upper()
        if stmt_u.startswith("REM"):
            raise JumpTarget(l_idx + 1, 0)
        elif stmt_u == "CLS":
            self.cpm.screen.cls()
        elif stmt_u.startswith("PRINT USING") or stmt_u.startswith("? USING"):
            p_arg = stmt[11:].strip() if stmt_u.startswith("PRINT USING") else stmt[7:].strip()
            self.exec_print_using(p_arg)
        elif stmt_u.startswith("PRINT#") or stmt_u.startswith("PRINT #"):
            self.exec_print_file(stmt)
        elif stmt_u.startswith("PRINT") or stmt_u.startswith("?"):
            p_arg = stmt[5:].strip() if stmt_u.startswith("PRINT") else stmt[1:].strip()
            self.exec_print(p_arg)
        elif stmt_u.startswith("LPRINT USING"):
            self.exec_print_using(stmt[12:].strip(), to_printer=True)
        elif stmt_u.startswith("LPRINT"):
            self.exec_print(stmt[6:].strip(), to_printer=True)
        elif stmt_u.startswith("LET "):
            self.exec_let(stmt[4:].strip())
        elif stmt_u.startswith("MID$(") and "=" in stmt:
            self.exec_mid_stmt(stmt)
        elif stmt_u.startswith("SWAP "):
            self.exec_swap(stmt[5:].strip())
        elif stmt_u.startswith("FOR "):
            self.exec_for(stmt[4:].strip(), l_idx, s_idx, lines)
        elif stmt_u.startswith("NEXT"):
            self.exec_next(stmt[4:].strip())
        elif stmt_u.startswith("WHILE "):
            self.exec_while(stmt[6:].strip(), l_idx, s_idx, lines)
        elif stmt_u == "WEND":
            self.exec_wend()
        elif stmt_u.startswith("IF "):
            self.exec_if(stmt[3:].strip(), l_idx, s_idx, lines)
        elif stmt_u.startswith("GOTO ") or stmt_u.startswith("GO TO "):
            arg = stmt[6:].strip() if stmt_u.startswith("GO TO ") else stmt[5:].strip()
            tgt_l = self.find_line_index(int(arg), lines)
            raise JumpTarget(tgt_l, 0)
        elif stmt_u.startswith("GOSUB ") or stmt_u.startswith("GO SUB "):
            arg = stmt[7:].strip() if stmt_u.startswith("GO SUB ") else stmt[6:].strip()
            tgt_l = self.find_line_index(int(arg), lines)
            self.gosub_stack.append((l_idx, s_idx + 1))
            raise JumpTarget(tgt_l, 0)
        elif stmt_u == "RETURN":
            if self.gosub_stack:
                ret_l, ret_s = self.gosub_stack.pop()
                raise JumpTarget(ret_l, ret_s)
            else:
                raise Exception("RETURN without GOSUB")
        elif stmt_u.startswith("ON "):
            self.exec_on(stmt[3:].strip(), l_idx, s_idx, lines)
        elif stmt_u.startswith("RESUME"):
            self.exec_resume(stmt[6:].strip(), lines)
        elif stmt_u.startswith("STOP"):
            cur_ln = lines[l_idx][0] if l_idx < len(lines) else 0
            raise StopProgram(cur_ln, l_idx, s_idx + 1)
        elif stmt_u in ("END", "SYSTEM"):
            if stmt_u == "SYSTEM":
                self.active = False
                self.cpm.active_app = None
            raise EndProgram()
        elif stmt_u.startswith("TRON"):
            self.trace_active = True
        elif stmt_u.startswith("TROFF"):
            self.trace_active = False
        elif stmt_u.startswith("INPUT#") or stmt_u.startswith("INPUT #"):
            self.exec_input_file(stmt)
        elif stmt_u.startswith("LINE INPUT#") or stmt_u.startswith("LINE INPUT #"):
            self.exec_line_input_file(stmt)
        elif stmt_u.startswith("LINE INPUT"):
            self.exec_line_input(stmt[10:].strip())
        elif stmt_u.startswith("INPUT"):
            self.exec_input(stmt[5:].strip())
        elif stmt_u.startswith("WRITE#") or stmt_u.startswith("WRITE #"):
            self.exec_write_file(stmt)
        elif stmt_u.startswith("WRITE"):
            self.exec_write(stmt[5:].strip())
        elif stmt_u.startswith("READ "):
            self.exec_read(stmt[5:].strip())
        elif stmt_u.startswith("RESTORE"):
            arg = stmt[7:].strip()
            self.data_ptr = 0
        elif stmt_u.startswith("DIM "):
            self.exec_dim(stmt[4:].strip())
        elif stmt_u.startswith("ERASE "):
            self.exec_erase(stmt[6:].strip())
        elif stmt_u.startswith("CLEAR"):
            self.vars.clear()
            self.arrays.clear()
        elif stmt_u.startswith("DEF FN"):
            self.exec_def_fn(stmt[6:].strip())
        elif stmt_u.startswith("DEFINT "):
            self.exec_def_type('I', stmt[7:].strip())
        elif stmt_u.startswith("DEFSNG "):
            self.exec_def_type('S', stmt[7:].strip())
        elif stmt_u.startswith("DEFDBL "):
            self.exec_def_type('D', stmt[7:].strip())
        elif stmt_u.startswith("DEFSTR "):
            self.exec_def_type('$', stmt[7:].strip())
        elif stmt_u.startswith("RANDOMIZE"):
            arg = stmt[9:].strip()
            if arg: random.seed(int(self.eval_expr(arg)))
            else: random.seed()
        elif stmt_u.startswith("WIDTH"):
            pass
        elif stmt_u.startswith("POKE "):
            self.exec_poke(stmt[5:].strip())
        elif stmt_u.startswith("OUT "):
            pass
        elif stmt_u.startswith("WAIT "):
            pass
        elif stmt_u.startswith("OPEN "):
            self.cmd_open(stmt[5:].strip())
        elif stmt_u.startswith("CLOSE"):
            self.cmd_close(stmt[5:].strip())
        elif stmt_u.startswith("FIELD "):
            self.cmd_field(stmt[6:].strip())
        elif stmt_u.startswith("GET "):
            self.cmd_get(stmt[4:].strip())
        elif stmt_u.startswith("PUT "):
            self.cmd_put(stmt[4:].strip())
        elif stmt_u.startswith("LSET "):
            self.cmd_lset(stmt[5:].strip())
        elif stmt_u.startswith("RSET "):
            self.cmd_rset(stmt[5:].strip())
        elif stmt_u.startswith("COMMON "):
            for var in stmt[7:].split(','):
                self.common_vars.add(var.strip().upper())
        elif stmt_u.startswith("CHAIN "):
            self.cmd_chain(stmt[6:].strip())
        elif "=" in stmt:
            self.exec_let(stmt)
        else:
            # Unrecognized statement
            first_tok = stmt_u.split()[0]
            if first_tok in self.SPECTRUM_ONLY_KEYWORDS:
                raise Exception(f"Spectrum keyword '{first_tok}' not valid in CP/M Mallard BASIC")
            raise Exception(f"Syntax error: {stmt}")

    def find_line_index(self, ln, lines):
        for i, (line_num, _) in enumerate(lines):
            if line_num == ln:
                return i
        raise Exception(f"Undefined line number {ln}")

    def exec_print(self, arg, to_printer=False):
        if not arg:
            if to_printer and zx_printer:
                zx_printer.print_text("")
                zx_printer.flush()
            else:
                self.cpm.screen.puts("\r\n")
            return
        items = []
        cur = []
        in_q = False
        paren_depth = 0
        for ch in arg:
            if ch == '"':
                in_q = not in_q
                cur.append(ch)
            elif ch in ('(', '[') and not in_q:
                paren_depth += 1
                cur.append(ch)
            elif ch in (')', ']') and not in_q:
                if paren_depth > 0: paren_depth -= 1
                cur.append(ch)
            elif ch in (';', ',') and not in_q and paren_depth == 0:
                items.append(("".join(cur).strip(), ch))
                cur = []
            else:
                cur.append(ch)
        if cur:
            items.append(("".join(cur).strip(), ''))

        out_str = ""
        trailing_sep = False
        for itm, sep in items:
            if itm:
                m_tab = re.match(r'(?i)^TAB\s*\(\s*(.*?)\s*\)$', itm)
                m_spc = re.match(r'(?i)^SPC\s*\(\s*(.*?)\s*\)$', itm)
                if m_tab:
                    tgt_col = int(self.eval_expr(m_tab.group(1)))
                    curr_col = len(out_str)
                    if tgt_col > curr_col:
                        out_str += " " * (tgt_col - curr_col)
                elif m_spc:
                    n_spaces = int(self.eval_expr(m_spc.group(1)))
                    out_str += " " * n_spaces
                else:
                    val = self.eval_expr(itm)
                    if isinstance(val, (int, float)):
                        val_str = f" {val} " if val >= 0 else f"{val} "
                    else:
                        val_str = str(val)
                    out_str += val_str
            if sep == ',':
                out_str += " " * max(1, 14 - (len(out_str) % 14))
                trailing_sep = True
            elif sep == ';':
                trailing_sep = True
            else:
                trailing_sep = False

        if not trailing_sep:
            out_str += "\r\n"
        if to_printer and zx_printer:
            zx_printer.print_text(out_str, newline=False)
            if not trailing_sep:
                zx_printer.flush()
        else:
            self.cpm.screen.puts(out_str)

    def exec_print_using(self, arg, to_printer=False):
        # Format: format_expr; value1, value2...
        m = re.match(r'^(.*?)\s*;\s*(.*)$', arg)
        if not m:
            return
        fmt_expr = m.group(1).strip()
        val_part = m.group(2).strip()
        fmt_str = str(self.eval_expr(fmt_expr))
        vals = []
        cur = []
        in_q = False
        paren_depth = 0
        for ch in val_part:
            if ch == '"':
                in_q = not in_q
                cur.append(ch)
            elif ch in ('(', '[') and not in_q:
                paren_depth += 1
                cur.append(ch)
            elif ch in (')', ']') and not in_q:
                if paren_depth > 0: paren_depth -= 1
                cur.append(ch)
            elif ch in (',', ';') and not in_q and paren_depth == 0:
                vals.append(self.eval_expr("".join(cur).strip()))
                cur = []
            else:
                cur.append(ch)
        if cur:
            vals.append(self.eval_expr("".join(cur).strip()))

        out_text = format_using(fmt_str, vals)
        if to_printer and zx_printer:
            zx_printer.print_text(out_text, newline=True)
            zx_printer.flush()
        else:
            self.cpm.screen.puts(out_text + "\r\n")

    def exec_write(self, arg):
        # Outputs items delimited by comma, strings quoted
        items = [x.strip() for x in arg.split(',') if x.strip()]
        out_items = []
        for itm in items:
            val = self.eval_expr(itm)
            if isinstance(val, str):
                out_items.append(f'"{val}"')
            else:
                out_items.append(str(val))
        self.cpm.screen.puts(",".join(out_items) + "\r\n")

    def exec_let(self, arg):
        if '=' in arg:
            lhs, rhs = arg.split('=', 1)
            var_name = lhs.strip().upper()
            val = self.eval_expr(rhs.strip())
            self.vars[var_name] = val

    def exec_mid_stmt(self, stmt):
        # MID$(A$, 2, 3) = "XYZ"
        m = re.match(r'(?i)^MID\$\s*\(\s*([A-Z0-9$]+)\s*,\s*(.*?)(?:,\s*(.*?))?\)\s*=\s*(.*)$', stmt)
        if not m:
            return
        var_name = m.group(1).upper()
        start = int(self.eval_expr(m.group(2))) - 1
        length = int(self.eval_expr(m.group(3))) if m.group(3) else None
        repl = str(self.eval_expr(m.group(4)))
        curr = str(self.vars.get(var_name, ""))
        if length is not None:
            repl = repl[:length]
        new_val = curr[:start] + repl + curr[start + len(repl):]
        self.vars[var_name] = new_val

    def exec_swap(self, arg):
        parts = [p.strip().upper() for p in arg.split(',')]
        if len(parts) == 2:
            v1, v2 = parts[0], parts[1]
            self.vars[v1], self.vars[v2] = self.vars.get(v2, 0), self.vars.get(v1, 0)

    def exec_for(self, arg, l_idx, s_idx, lines):
        m = re.match(r'(?i)^([A-Z][A-Z0-9]*)\s*=\s*(.*?)\s+TO\s+(.*?)(?:\s+STEP\s+(.*?))?$', arg)
        if not m:
            return
        var_name = m.group(1).upper()
        start_val = self.eval_expr(m.group(2))
        end_val = self.eval_expr(m.group(3))
        step_val = self.eval_expr(m.group(4)) if m.group(4) else 1
        self.vars[var_name] = start_val

        target = (l_idx, s_idx + 1) if s_idx + 1 < len(lines[l_idx][1]) else (l_idx + 1, 0)
        self.for_stack.append({
            "var": var_name,
            "end": end_val,
            "step": step_val,
            "target": target
        })

    def exec_next(self, arg):
        if not self.for_stack:
            return
        var_names = [v.strip().upper() for v in arg.split(',') if v.strip()] if arg.strip() else [self.for_stack[-1]["var"]]
        for var_name in var_names:
            loop = self.for_stack[-1]
            if loop["var"] != var_name and len(self.for_stack) > 1:
                for i in range(len(self.for_stack)-1, -1, -1):
                    if self.for_stack[i]["var"] == var_name:
                        loop = self.for_stack[i]
                        break

            var = loop["var"]
            curr = self.vars.get(var, 0) + loop["step"]
            self.vars[var] = curr
            step = loop["step"]
            if (step > 0 and curr <= loop["end"]) or (step < 0 and curr >= loop["end"]):
                raise JumpTarget(loop["target"][0], loop["target"][1])
            else:
                if loop in self.for_stack:
                    self.for_stack.remove(loop)

    def exec_while(self, cond_str, l_idx, s_idx, lines):
        val = self.eval_expr(cond_str)
        if not val:
            depth = 1
            cur_l = l_idx
            cur_s = s_idx + 1
            while cur_l < len(lines):
                stmts = lines[cur_l][1]
                while cur_s < len(stmts):
                    st = stmts[cur_s].strip().upper()
                    if st.startswith("WHILE "): depth += 1
                    elif st == "WEND":
                        depth -= 1
                        if depth == 0:
                            raise JumpTarget(cur_l, cur_s + 1)
                    cur_s += 1
                cur_l += 1
                cur_s = 0
            raise Exception("WHILE without WEND")
        else:
            self.while_stack.append({
                "cond": cond_str,
                "target": (l_idx, s_idx + 1)
            })

    def exec_wend(self):
        if not self.while_stack:
            raise Exception("WEND without WHILE")
        entry = self.while_stack[-1]
        val = self.eval_expr(entry["cond"])
        if val:
            raise JumpTarget(entry["target"][0], entry["target"][1])
        else:
            self.while_stack.pop()

    def exec_if(self, arg, l_idx, s_idx, lines):
        m_then = re.search(r'(?i)\bTHEN\b', arg)
        m_goto = re.search(r'(?i)\bGOTO\b', arg)
        if m_then:
            cond_str = arg[:m_then.start()].strip()
            rest = arg[m_then.end():].strip()
        elif m_goto:
            cond_str = arg[:m_goto.start()].strip()
            rest = "GOTO " + arg[m_goto.end():].strip()
        else:
            return

        m_else = re.search(r'(?i)\bELSE\b', rest)
        if m_else:
            then_part = rest[:m_else.start()].strip()
            else_part = rest[m_else.end():].strip()
        else:
            then_part = rest
            else_part = None

        cond_val = self.eval_expr(cond_str)
        exec_branch = then_part if cond_val else else_part
        if exec_branch:
            if exec_branch.isdigit():
                tgt_l = self.find_line_index(int(exec_branch), lines)
                raise JumpTarget(tgt_l, 0)
            branch_stmts = self.split_statements(exec_branch)
            for s in branch_stmts:
                self.exec_single_statement(s, l_idx, s_idx, lines)
        elif not cond_val and else_part is None:
            raise JumpTarget(l_idx + 1, 0)

    def exec_on(self, arg, l_idx, s_idx, lines):
        # ON ERROR GOTO line / ON expr GOTO l1, l2 / ON expr GOSUB l1, l2
        if arg.upper().startswith("ERROR GOTO"):
            tgt = int(arg[10:].strip())
            self.error_handler_line = tgt
            return

        m = re.match(r'(?i)^(.*?)\s+(GOTO|GOSUB)\s+(.*)$', arg)
        if not m:
            return
        idx = int(self.eval_expr(m.group(1)))
        action = m.group(2).upper()
        dest_lines = [int(x.strip()) for x in m.group(3).split(',') if x.strip()]
        if 1 <= idx <= len(dest_lines):
            tgt_ln = dest_lines[idx - 1]
            tgt_l = self.find_line_index(tgt_ln, lines)
            if action == "GOSUB":
                self.gosub_stack.append((l_idx, s_idx + 1))
            raise JumpTarget(tgt_l, 0)

    def exec_resume(self, arg, lines):
        arg_u = arg.upper().strip()
        if arg_u == "NEXT":
            tgt_l = self.find_line_index(self.last_err_line, lines)
            raise JumpTarget(tgt_l + 1, 0)
        elif arg_u and arg_u != "0":
            tgt_l = self.find_line_index(int(arg_u), lines)
            raise JumpTarget(tgt_l, 0)
        else:
            # Resume at faulting line
            tgt_l = self.find_line_index(self.last_err_line, lines)
            raise JumpTarget(tgt_l, 0)

    def exec_input(self, arg):
        prompt = "? "
        m = re.match(r'^(".*?")\s*([;,])\s*(.*)$', arg)
        if m:
            prompt = m.group(1).strip('"')
            vars_part = m.group(3)
        else:
            vars_part = arg
        self.cpm.screen.puts(prompt)
        vars_to_read = [v.strip().upper() for v in vars_part.split(',') if v.strip()]
        # Read from keyboard or mock
        user_line = self.read_console_input()
        input_vals = [v.strip() for v in user_line.split(',')]
        for i, v in enumerate(vars_to_read):
            val_str = input_vals[i] if i < len(input_vals) else ""
            if v.endswith('$'):
                self.vars[v] = val_str
            else:
                try: self.vars[v] = float(val_str) if '.' in val_str else int(val_str)
                except: self.vars[v] = 0

    def exec_line_input(self, arg):
        prompt = ""
        m = re.match(r'^(".*?")\s*([;,])\s*(.*)$', arg)
        if m:
            prompt = m.group(1).strip('"')
            var_name = m.group(3).strip().upper()
        else:
            var_name = arg.strip().upper()
        if prompt:
            self.cpm.screen.puts(prompt)
        line = self.read_console_input()
        self.vars[var_name] = line

    def read_console_input(self):
        try:
            import pygame
            if pygame.get_init() and pygame.display.get_init():
                cur = []
                while True:
                    for ev in pygame.event.get():
                        if ev.type == pygame.KEYDOWN:
                            if ev.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                                self.cpm.screen.puts("\r\n")
                                return "".join(cur)
                            elif ev.key == pygame.K_BACKSPACE and cur:
                                cur.pop()
                                self.cpm.screen.putc('\b')
                        elif ev.type == pygame.TEXTINPUT:
                            for ch in ev.text:
                                if ch not in ('\r', '\n'):
                                    cur.append(ch)
                                    self.cpm.screen.putc(ch)
                    pygame.time.delay(10)
        except:
            pass
        return ""

    def exec_read(self, arg):
        vars_to_read = [v.strip().upper() for v in arg.split(',') if v.strip()]
        for v in vars_to_read:
            if self.data_ptr < len(self.data_items):
                val = self.data_items[self.data_ptr]
                self.data_ptr += 1
                try:
                    if '.' in val: self.vars[v] = float(val)
                    else: self.vars[v] = int(val)
                except ValueError:
                    self.vars[v] = val.strip('"')
            else:
                raise Exception("Out of DATA")

    def collect_data_items(self):
        self.data_items = []
        self.data_ptr = 0
        for ln in sorted(self.program.keys()):
            code = self.program[ln]
            for m in re.finditer(r'(?i)\bDATA\b\s*(.*)', code):
                items_str = m.group(1).strip()
                for item in items_str.split(','):
                    self.data_items.append(item.strip())

    def exec_dim(self, arg):
        # DIM A(10), B$(5, 5)
        for part in arg.split(','):
            m = re.match(r'^([A-Z0-9$]+)\s*\((.*?)\)$', part.strip().upper())
            if m:
                arr_name = m.group(1)
                dims = [int(self.eval_expr(d)) for d in m.group(2).split(',')]
                self.arrays[arr_name] = {"dims": dims, "data": {}}

    def exec_erase(self, arg):
        for part in arg.split(','):
            arr_name = part.strip().upper()
            if arr_name in self.arrays:
                del self.arrays[arr_name]

    def exec_def_fn(self, arg):
        # DEF FNA(X) = X * X
        m = re.match(r'^([A-Z0-9$]+)\s*(?:\((.*?)\))?\s*=\s*(.*)$', arg.strip().upper())
        if m:
            fn_name = m.group(1)
            arg_names = [a.strip() for a in m.group(2).split(',')] if m.group(2) else []
            body = m.group(3).strip()
            self.user_fns[fn_name] = (arg_names, body)

    def exec_def_type(self, type_code, arg):
        # DEFINT A-Z, C
        for part in arg.split(','):
            p = part.strip().upper()
            if '-' in p:
                start, end = p.split('-')
                for c in range(ord(start.strip()[0]), ord(end.strip()[0]) + 1):
                    self.default_types[chr(c)] = type_code
            elif p:
                self.default_types[p[0]] = type_code

    def exec_poke(self, arg):
        p = [x.strip() for x in arg.split(',')]
        if len(p) == 2:
            addr = int(self.eval_expr(p[0])) & 0xFFFF
            val = int(self.eval_expr(p[1])) & 0xFF
            self.cpm.tpa_memory[addr] = val

    # Sequential & Random File Commands
    def cmd_open(self, arg):
        # Syntax 1: OPEN "O", #1, "FILENAME"
        # Syntax 2: OPEN "FILENAME" [FOR mode] AS [#]stream [LEN=rec_len]
        m1 = re.match(r'^(".*?")\s*,\s*(?:#)?(\d+)\s*,\s*(.*)$', arg)
        if m1:
            mode = m1.group(1).strip('"').upper()
            stream = int(m1.group(2))
            fn_raw = m1.group(3).strip().strip('"').strip("'")
            rec_len = 128
        else:
            m2 = re.match(r'(?i)^(.*?)\s+FOR\s+(.*?)\s+AS\s+(?:#)?(\d+)(?:\s+LEN\s*=\s*(\d+))?$', arg)
            if m2:
                fn_raw = m2.group(1).strip().strip('"').strip("'")
                mode = m2.group(2).strip().upper()[0]
                stream = int(m2.group(3))
                rec_len = int(m2.group(4)) if m2.group(4) else 128
            else:
                return

        drv, fn = self.cpm.parse_filespec(fn_raw)
        f = self.cpm.get_file(drv, fn, self.cpm.current_user)
        existing_data = (f['data'] if isinstance(f, dict) else f) if f else b""

        self.open_files[stream] = {
            "drv": drv,
            "name": fn,
            "mode": mode,
            "data": bytearray(existing_data),
            "ptr": len(existing_data) if mode == "A" else 0,
            "rec_len": rec_len
        }
        if mode == "R":
            self.rec_buffers[stream] = bytearray(rec_len)

    def cmd_close(self, arg):
        streams = [int(s.strip().lstrip('#')) for s in arg.split(',') if s.strip()] if arg.strip() else list(self.open_files.keys())
        for s in streams:
            if s in self.open_files:
                f_info = self.open_files[s]
                self.cpm.put_file(f_info['drv'], f_info['name'], bytes(f_info['data']), self.cpm.current_user)
                del self.open_files[s]

    def exec_print_file(self, stmt):
        # PRINT #1, "Hello"
        m = re.match(r'(?i)^PRINT\s*#\s*(\d+)\s*,\s*(.*)$', stmt)
        if not m: return
        stream = int(m.group(1))
        val = str(self.eval_expr(m.group(2)))
        f = self.open_files.get(stream)
        if f: f['data'].extend((val + "\r\n").encode('ascii'))

    def exec_write_file(self, stmt):
        # WRITE #1, A$, B
        m = re.match(r'(?i)^WRITE\s*#\s*(\d+)\s*,\s*(.*)$', stmt)
        if not m: return
        stream = int(m.group(1))
        items = [x.strip() for x in m.group(2).split(',')]
        out_items = []
        for itm in items:
            v = self.eval_expr(itm)
            out_items.append(f'"{v}"' if isinstance(v, str) else str(v))
        f = self.open_files.get(stream)
        if f: f['data'].extend((",".join(out_items) + "\r\n").encode('ascii'))

    def exec_input_file(self, stmt):
        m = re.match(r'(?i)^INPUT\s*#\s*(\d+)\s*,\s*(.*)$', stmt)
        if not m: return
        stream = int(m.group(1))
        var_names = [v.strip().upper() for v in m.group(2).split(',')]
        f = self.open_files.get(stream)
        if not f: return
        text = f['data'][f['ptr']:].decode('ascii', errors='replace')
        lines = text.splitlines()
        if lines:
            line_vals = [x.strip().strip('"') for x in lines[0].split(',')]
            f['ptr'] += len(lines[0]) + 2
            for i, v in enumerate(var_names):
                val_str = line_vals[i] if i < len(line_vals) else ""
                self.vars[v] = val_str if v.endswith('$') else self._fn_val(val_str)

    def exec_line_input_file(self, stmt):
        m = re.match(r'(?i)^LINE\s+INPUT\s*#\s*(\d+)\s*,\s*(.*)$', stmt)
        if not m: return
        stream = int(m.group(1))
        var_name = m.group(2).strip().upper()
        f = self.open_files.get(stream)
        if not f: return
        text = f['data'][f['ptr']:].decode('ascii', errors='replace')
        lines = text.splitlines()
        if lines:
            f['ptr'] += len(lines[0]) + 2
            self.vars[var_name] = lines[0]

    def cmd_field(self, arg):
        # FIELD #1, 20 AS N$, 4 AS P$
        m = re.match(r'^(?:#)?(\d+)\s*,\s*(.*)$', arg)
        if not m: return
        stream = int(m.group(1))
        field_specs = []
        for pair in m.group(2).split(','):
            pm = re.match(r'(?i)^(\d+)\s+AS\s+([A-Z0-9$]+)$', pair.strip())
            if pm: field_specs.append((int(pm.group(1)), pm.group(2).upper()))
        self.field_defs[stream] = field_specs

    def cmd_get(self, arg):
        # GET [#]stream[, rec_num]
        parts = [p.strip().lstrip('#') for p in arg.split(',')]
        stream = int(parts[0])
        rec = int(parts[1]) if len(parts) > 1 else 1
        f = self.open_files.get(stream)
        if not f: return
        rec_len = f['rec_len']
        offset = (rec - 1) * rec_len
        buf = f['data'][offset : offset + rec_len]
        if len(buf) < rec_len:
            buf = buf.ljust(rec_len, b' ')
        self.rec_buffers[stream] = bytearray(buf)
        # Populate FIELD variables
        if stream in self.field_defs:
            boff = 0
            for flen, fvar in self.field_defs[stream]:
                self.vars[fvar] = self.rec_buffers[stream][boff : boff + flen].decode('latin1')
                boff += flen

    def cmd_put(self, arg):
        # PUT [#]stream[, rec_num]
        parts = [p.strip().lstrip('#') for p in arg.split(',')]
        stream = int(parts[0])
        rec = int(parts[1]) if len(parts) > 1 else 1
        f = self.open_files.get(stream)
        if not f: return
        rec_len = f['rec_len']
        offset = (rec - 1) * rec_len
        buf = self.rec_buffers.get(stream, bytearray(rec_len))
        while len(f['data']) < offset:
            f['data'].extend(b' ' * (offset - len(f['data'])))
        f['data'][offset : offset + rec_len] = buf

    def cmd_lset(self, arg):
        # LSET field_var$ = expr$
        if '=' in arg:
            lhs, rhs = arg.split('=', 1)
            var_name = lhs.strip().upper()
            val = str(self.eval_expr(rhs.strip()))
            old_val = str(self.vars.get(var_name, ""))
            length = len(old_val) if old_val else len(val)
            self.vars[var_name] = val[:length].ljust(length)
            # Sync to rec_buffer
            for s, fdefs in self.field_defs.items():
                boff = 0
                for flen, fvar in fdefs:
                    if fvar == var_name:
                        self.rec_buffers[s][boff : boff + flen] = self.vars[var_name].encode('latin1')
                    boff += flen

    def cmd_rset(self, arg):
        # RSET field_var$ = expr$
        if '=' in arg:
            lhs, rhs = arg.split('=', 1)
            var_name = lhs.strip().upper()
            val = str(self.eval_expr(rhs.strip()))
            old_val = str(self.vars.get(var_name, ""))
            length = len(old_val) if old_val else len(val)
            self.vars[var_name] = val[-length:].rjust(length)
            for s, fdefs in self.field_defs.items():
                boff = 0
                for flen, fvar in fdefs:
                    if fvar == var_name:
                        self.rec_buffers[s][boff : boff + flen] = self.vars[var_name].encode('latin1')
                    boff += flen

    def cmd_chain(self, arg):
        # CHAIN [MERGE] filename [, [line][, ALL]]
        is_merge = False
        if arg.upper().startswith("MERGE "):
            is_merge = True
            arg = arg[6:].strip()
        parts = [p.strip() for p in arg.split(',')]
        fn = parts[0].strip('"').strip("'")
        # Preserve COMMON variables
        preserved = {k: v for k, v in self.vars.items() if k in self.common_vars}
        if is_merge:
            self.merge_file(fn)
        else:
            self.load_file(fn)
        self.vars.update(preserved)
        self.run_program()

    def run_program(self, start_ln=0):
        sorted_lns = sorted(self.program.keys())
        if not sorted_lns:
            self.cpm.screen.puts("Ok\r\n")
            return
        lines = []
        for ln in sorted_lns:
            stmts = self.split_statements(self.program[ln])
            lines.append((ln, stmts))

        # Preserve common variables if chaining, else clear
        preserved = {k: v for k, v in self.vars.items() if k in self.common_vars}
        self.vars = preserved
        self.gosub_stack.clear()
        self.for_stack.clear()
        self.while_stack.clear()
        self.collect_data_items()
        self.break_target = None

        l_idx = 0
        s_idx = 0
        if start_ln > 0:
            l_idx = self.find_line_index(start_ln, lines)

        self.resume_execution(l_idx, s_idx, lines)

    def resume_execution(self, l_idx, s_idx, lines):
        while l_idx < len(lines):
            ln, stmts = lines[l_idx]
            if self.trace_active and s_idx == 0:
                self.cpm.screen.puts(f"[{ln}]")
            while s_idx < len(stmts):
                stmt = stmts[s_idx]
                try:
                    self.exec_single_statement(stmt, l_idx, s_idx, lines)
                    s_idx += 1
                except JumpTarget as jt:
                    l_idx = jt.l_idx
                    s_idx = jt.s_idx
                    break
                except StopProgram as sp:
                    self.cpm.screen.puts(f"Break in {sp.line_num}\r\n")
                    self.break_target = (sp.l_idx, sp.s_idx, lines)
                    return
                except EndProgram:
                    l_idx = len(lines)
                    s_idx = 0
                    break
                except Exception as e:
                    if self.error_handler_line > 0:
                        self.last_err_code = 1
                        self.last_err_line = ln
                        tgt_l = self.find_line_index(self.error_handler_line, lines)
                        l_idx = tgt_l
                        s_idx = 0
                        break
                    else:
                        self.cpm.screen.puts(f"Error in line {ln}: {e}\r\n")
                        l_idx = len(lines)
                        break
            else:
                l_idx += 1
                s_idx = 0

        self.cpm.screen.puts("Ok\r\n")


class DDT:
    """
    CP/M Dynamic Debugging Tool (DDT v2.2).
    Prompts with '-', supports D (dump), L (disassemble), X (examine registers),
    M (move), F (fill), G (go), and Q (quit to CP/M).
    """
    def __init__(self, cpm_system):
        self.cpm = cpm_system
        self.active = False
        self.dump_addr = 0x0100
        self.list_addr = 0x0100
        self.regs = {
            "C": 0, "Z": 1, "M": 0, "E": 0, "I": 0,
            "A": 0x00, "B": 0x0000, "D": 0x0000, "H": 0x0000,
            "S": 0x0100, "P": 0x0100
        }

    def banner(self, filename=""):
        self.cpm.screen.puts("DDT No. 2.2\r\n")
        self.active = True
        self.cpm.active_app = "DDT"
        if filename:
            drv, fn = self.cpm.parse_filespec(filename)
            f = self.cpm.get_file(drv, fn, self.cpm.current_user)
            if f:
                data = f['data']
                self.cpm.tpa_memory[0x0100 : 0x0100 + len(data)] = data
                next_addr = 0x0100 + len(data)
                self.cpm.screen.puts(f"NEXT  PC\r\n{next_addr:04X} 0100\r\n")
                self.dump_addr = 0x0100
                self.list_addr = 0x0100
            else:
                self.cpm.screen.puts("File not found\r\n")

    def execute_line(self, line):
        cmd = line.strip()
        if not cmd:
            return
        verb = cmd[0].upper()
        arg = cmd[1:].strip()

        if verb == 'Q':
            self.active = False
            self.cpm.active_app = None
            return
        elif verb == 'D':
            self.cmd_dump(arg)
        elif verb == 'L':
            self.cmd_list(arg)
        elif verb == 'X':
            self.cmd_examine(arg)
        elif verb == 'F':
            self.cmd_fill(arg)
        elif verb == 'M':
            self.cmd_move(arg)
        elif verb == 'G':
            self.cpm.screen.puts("*0100\r\n")
        else:
            self.cpm.screen.puts("?\r\n")

    def cmd_dump(self, arg):
        start = self.dump_addr
        end = start + 191
        if arg:
            if ',' in arg:
                p = arg.split(',', 1)
                try: start = int(p[0].strip(), 16)
                except: pass
                try: end = int(p[1].strip(), 16)
                except: pass
            else:
                try: start = int(arg, 16); end = start + 191
                except: pass

        addr = start & ~15
        mem = self.cpm.tpa_memory
        while addr <= end and addr < 65536:
            chunk = mem[addr : addr + 16]
            hex_part = " ".join(f"{b:02X}" for b in chunk)
            asc_part = "".join(chr(b) if 32 <= b <= 126 else "." for b in chunk)
            self.cpm.screen.puts(f"{addr:04X} {hex_part:<48} {asc_part}\r\n")
            addr += 16
        self.dump_addr = addr

    def cmd_list(self, arg):
        start = self.list_addr
        end = start + 31
        if arg:
            if ',' in arg:
                p = arg.split(',', 1)
                try: start = int(p[0].strip(), 16)
                except: pass
                try: end = int(p[1].strip(), 16)
                except: pass
            else:
                try: start = int(arg, 16); end = start + 31
                except: pass

        addr = start
        mem = self.cpm.tpa_memory
        while addr <= end and addr < 65536:
            b0 = mem[addr]
            if b0 == 0x00:
                self.cpm.screen.puts(f"{addr:04X}  NOP\r\n"); addr += 1
            elif b0 == 0xC9:
                self.cpm.screen.puts(f"{addr:04X}  RET\r\n"); addr += 1
            elif b0 == 0x3E:
                b1 = mem[addr+1] if addr+1 < 65536 else 0
                self.cpm.screen.puts(f"{addr:04X}  MVI A,{b1:02X}\r\n"); addr += 2
            elif b0 == 0xCD:
                w = mem[addr+1] | (mem[addr+2] << 8) if addr+2 < 65536 else 0
                self.cpm.screen.puts(f"{addr:04X}  CALL {w:04X}\r\n"); addr += 3
            else:
                self.cpm.screen.puts(f"{addr:04X}  DB {b0:02X}\r\n"); addr += 1
        self.list_addr = addr

    def cmd_examine(self, arg):
        r = self.regs
        flags = f"C{r['C']}Z{r['Z']}M{r['M']}E{r['E']}I{r['I']}"
        self.cpm.screen.puts(f"{flags} A={r['A']:02X} B={r['B']:04X} D={r['D']:04X} H={r['H']:04X} S={r['S']:04X} P={r['P']:04X}\r\n")

    def cmd_fill(self, arg):
        try:
            p = [x.strip() for x in arg.split(',')]
            start = int(p[0], 16)
            end = int(p[1], 16)
            val = int(p[2], 16) & 0xFF
            for a in range(start, min(end+1, 65536)):
                self.cpm.tpa_memory[a] = val
        except Exception:
            self.cpm.screen.puts("?\r\n")

    def cmd_move(self, arg):
        try:
            p = [x.strip() for x in arg.split(',')]
            start = int(p[0], 16)
            end = int(p[1], 16)
            dest = int(p[2], 16)
            length = end - start + 1
            src_bytes = self.cpm.tpa_memory[start : start + length]
            self.cpm.tpa_memory[dest : dest + length] = src_bytes
        except Exception:
            self.cpm.screen.puts("?\r\n")


class ED:
    """
    CP/M Context Editor (ED v2.2).
    Prompts with '*', supports #A (append), I (insert text), T (type lines),
    0L/B (move to start), -B (move to end), D (delete line), E (end & save), Q (quit).
    """
    def __init__(self, cpm_system):
        self.cpm = cpm_system
        self.active = False
        self.filename = ""
        self.buffer = []
        self.insert_mode = False
        self.line_ptr = 0

    def start(self, filename):
        if not filename:
            self.cpm.screen.puts("Syntax: ED filename\r\n")
            return
        self.filename = filename
        self.buffer = []
        self.insert_mode = False
        self.line_ptr = 0
        drv, fn = self.cpm.parse_filespec(filename)
        self.cpm.screen.puts(f"ED v2.2 Context Editor: {drv}:{fn}\r\n")
        f = self.cpm.get_file(drv, fn, self.cpm.current_user)
        if f:
            text = f['data'].decode('ascii', errors='replace')
            self.buffer = text.splitlines()
            self.cpm.screen.puts(f"Read {len(self.buffer)} lines into memory buffer.\r\n")
        else:
            self.cpm.screen.puts("New file.\r\n")
        self.active = True
        self.cpm.active_app = "ED"

    def execute_line(self, line):
        if self.insert_mode:
            if line == "." or line == "\x1a":
                self.insert_mode = False
                return
            self.buffer.insert(self.line_ptr, line)
            self.line_ptr += 1
            return

        cmd = line.strip().upper()
        if not cmd:
            return

        if cmd == 'Q':
            self.active = False
            self.cpm.active_app = None
            return
        elif cmd == 'E':
            drv, fn = self.cpm.parse_filespec(self.filename)
            out_data = ("\r\n".join(self.buffer) + "\r\n").encode('ascii')
            self.cpm.put_file(drv, fn, out_data, self.cpm.current_user)
            self.active = False
            self.cpm.active_app = None
            return
        elif cmd == 'I':
            self.insert_mode = True
        elif cmd in ('T', '#T', 'B#T'):
            for l in self.buffer:
                self.cpm.screen.puts(l + "\r\n")
        elif cmd in ('B', '0L'):
            self.line_ptr = 0
        elif cmd == '-B':
            self.line_ptr = len(self.buffer)
        elif cmd == 'D':
            if 0 <= self.line_ptr < len(self.buffer):
                del self.buffer[self.line_ptr]
        elif cmd == '#A':
            self.cpm.screen.puts(f"{len(self.buffer)} lines in buffer\r\n")
        else:
            self.cpm.screen.puts("?\r\n")


class WordStar:
    """
    MicroPro WordStar 2 Compatible Word Processing System for CP/M.
    Authentic 51x24 CRT display word processor featuring:
    - Opening Menu (No-File Menu) with D, N, L, F, P, E, O, Y, H, X commands.
    - Full-screen editing with Status Line, Ruler Line, 21-line Viewport, and Menu/Help line.
    - WordStar Diamond cursor navigation (^E, ^X, ^S, ^D, ^A, ^F, ^R, ^C, ^W, ^Z).
    - Quick cursor & search commands (^QS, ^QD, ^QR, ^QC, ^QF, ^QA, ^QY).
    - Block commands (^KB, ^KK, ^KC, ^KV, ^KY, ^KW, ^KR).
    - Formatting commands (^OC center, ^OW wrap toggle, ^OL/^OR margins, ^B paragraph reform).
    - File & exit commands (^KD save & menu, ^KS save & stay, ^KX save & exit to CP/M, ^KQ abandon).
    - Dot commands (.he header, .fo footer, .pa page break, .op omit page numbers, .lm, .rm).
    - WordStar CP/M 8th-bit soft-space/hyphen document file compatibility.
    """
    def __init__(self, cpm_system):
        self.cpm = cpm_system
        self.active = False
        self.mode = "MENU"        # "MENU", "EDIT", "PROMPT"
        self.is_document = True   # True=Document, False=Non-Document
        self.filename = ""
        self.logged_drive = 'A'
        self.lines = [""]
        self.cursor_row = 0
        self.cursor_col = 0
        self.top_line = 0
        self.left_col = 0
        self.insert_mode = True
        self.word_wrap = True
        self.justify = False
        self.left_margin = 1
        self.right_margin = 50
        self.tab_size = 4
        self.modified = False
        self.block_begin = None   # (row, col)
        self.block_end = None     # (row, col)
        self.find_str = ""
        self.replace_str = ""
        self.prefix_key = None    # None, '^K', '^O', '^Q', '^J'
        self.status_msg = ""
        self.prompt_text = ""
        self.prompt_buffer = []
        self.prompt_callback = None
        self.prompt_prev_mode = "MENU"
        self.help_level = 2
        self.show_directory = True

    def start(self, args=""):
        self.active = True
        self.cpm.active_app = "WORDSTAR"
        self.logged_drive = self.cpm.current_drive
        arg = args.strip()
        if arg:
            drv, fn = self.cpm.parse_filespec(arg)
            self.logged_drive = drv
            self.open_file(fn, is_doc=True)
        else:
            self.open_menu()

    def open_menu(self):
        self.mode = "MENU"
        self.prefix_key = None
        self.status_msg = ""
        self.render_screen()

    def ask_prompt(self, prompt_text, callback):
        self.prompt_prev_mode = self.mode
        self.mode = "PROMPT"
        self.prompt_text = prompt_text
        self.prompt_buffer = []
        self.prompt_callback = callback
        self.render_screen()

    def render_screen(self):
        if not hasattr(self.cpm, 'screen') or self.cpm.screen is None:
            return
        if self.mode == "MENU":
            self.render_opening_menu()
        elif self.mode == "EDIT":
            self.render_edit_screen()
        elif self.mode == "PROMPT":
            self.render_prompt()

    def render_opening_menu(self):
        lines_menu = [
            "<<<        O P E N I N G   M E N U        >>>".center(51),
            "---Preliminary Commands---  --Commands to open a file--",
            " L  Change logged drive      D  Open a document file    ",
            " F  File directory on/off    N  Open a non-document file",
            " H  Set help level                                      ",
            "---File Commands----------  --System Commands---------  ",
            " P  Print a file             R  Run a CP/M program      ",
            " E  Rename a file            X  EXIT to CP/M            ",
            " O  Copy a file                                         ",
            " Y  Delete a file                                       ",
            "-" * 51,
        ]
        if self.show_directory:
            lines_menu.append(f"Directory of Drive {self.logged_drive}: (Logged: {self.logged_drive}:)"[:51])
            files = sorted(self.cpm.drives.get(self.logged_drive, {}).keys())
            file_rows = []
            cur_row = []
            for fn in files:
                cur_row.append(f"{fn:<12}")
                if len(cur_row) == 4:
                    file_rows.append("".join(cur_row)[:51])
                    cur_row = []
            if cur_row:
                file_rows.append("".join(cur_row)[:51])
            for fr in file_rows[:9]:
                lines_menu.append(fr)
            while len(lines_menu) < 22:
                lines_menu.append(" " * 51)
        else:
            lines_menu.append("File directory display is OFF.")
            while len(lines_menu) < 22:
                lines_menu.append(" " * 51)

        lines_menu.append("-" * 51)
        prompt_line = self.status_msg if self.status_msg else "Command? (D, N, L, F, P, E, O, Y, X): "
        lines_menu.append(prompt_line[:51].ljust(51))

        for r in range(24):
            line_str = lines_menu[r] if r < len(lines_menu) else (" " * 51)
            line_str = line_str[:51].ljust(51)
            inv = (r == 0)
            for c in range(51):
                self.cpm.screen.draw_char(c, r, line_str[c], inverse=inv)

        self.cpm.screen.cursor_row = 23
        self.cpm.screen.cursor_col = min(50, len(prompt_line))
        self.cpm.screen.draw_cursor(True)

    def render_edit_screen(self):
        # 1. Status line (Row 0)
        doc_type = "DOCUMENT" if self.is_document else "NON-DOC"
        ins_str = "INSERT ON" if self.insert_mode else "INSERT OFF"
        pos_str = f"PAGE {self.cursor_row // 55 + 1} LINE {self.cursor_row + 1} COL {self.cursor_col + 1}"
        file_str = f"{self.logged_drive}:{self.filename}"
        status_line = f"{file_str:<16} {pos_str:<21} {ins_str:>12}"[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 0, status_line[c], inverse=True)

        # 2. Ruler line (Row 1)
        ruler = list("-" * 51)
        if 0 <= self.left_margin - 1 < 51:
            ruler[self.left_margin - 1] = 'L'
        if 0 <= self.right_margin - 1 < 51:
            ruler[self.right_margin - 1] = 'R'
        for c in range(4, 50, 4):
            if ruler[c] == '-':
                ruler[c] = '!'
        ruler_line = "".join(ruler)[:51]
        for c in range(51):
            self.cpm.screen.draw_char(c, 1, ruler_line[c], inverse=False)

        # 3. Text area (Rows 2 to 22, 21 rows)
        for vr in range(21):
            row_idx = 2 + vr
            doc_line_idx = self.top_line + vr
            if doc_line_idx < len(self.lines):
                line_str = self.lines[doc_line_idx]
                flag = ' '
                if line_str.startswith('.'):
                    flag = '.'
                text_slice = line_str[self.left_col : self.left_col + 50]
                row_str = f"{text_slice:<50}{flag}"[:51]
            else:
                row_str = " " * 51
            for c in range(51):
                self.cpm.screen.draw_char(c, row_idx, row_str[c], inverse=False)

        # 4. Bottom Menu / Prompt line (Row 23)
        if self.prefix_key == '^K':
            bottom_str = "^K: D-Done S-Save X-Exit Q-Quit B-Beg K-End C-Copy V-Move"
        elif self.prefix_key == '^O':
            bottom_str = "^O: C-Center L-LeftMar R-RightMar W-Wrap J-Just S-Space"
        elif self.prefix_key == '^Q':
            bottom_str = "^Q: S-LineBeg D-LineEnd R-Top C-End F-Find A-Repl Y-DelEOL"
        elif self.prefix_key == '^J':
            bottom_str = "^J: ^E-Up ^X-Down ^S-Left ^D-Right ^A-WdLeft ^F-WdRight ^B-Ref"
        elif self.status_msg:
            bottom_str = self.status_msg
        else:
            bottom_str = "^KD=Done ^KS=Save ^KX=Exit ^KQ=Quit ^J=Help"
        bottom_str = bottom_str[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 23, bottom_str[c], inverse=False)

        # Position cursor on screen
        cur_scr_row = 2 + (self.cursor_row - self.top_line)
        cur_scr_col = self.cursor_col - self.left_col
        if 2 <= cur_scr_row <= 22 and 0 <= cur_scr_col < 50:
            self.cpm.screen.cursor_row = cur_scr_row
            self.cpm.screen.cursor_col = cur_scr_col
            self.cpm.screen.draw_cursor(True)
        else:
            self.cpm.screen.draw_cursor(False)

    def render_prompt(self):
        prompt_str = (self.prompt_text + "".join(self.prompt_buffer))[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 23, prompt_str[c], inverse=False)
        self.cpm.screen.cursor_row = 23
        self.cpm.screen.cursor_col = min(50, len(self.prompt_text) + len(self.prompt_buffer))
        self.cpm.screen.draw_cursor(True)

    def open_file(self, filename, is_doc=True):
        if not filename:
            self.status_msg = "File not specified"
            self.render_screen()
            return
        drv, fn = self.cpm.parse_filespec(filename)
        self.logged_drive = drv
        self.filename = fn.upper()
        self.is_document = is_doc
        self.word_wrap = is_doc
        self.lines = [""]
        self.cursor_row = 0
        self.cursor_col = 0
        self.top_line = 0
        self.left_col = 0
        self.modified = False
        self.block_begin = None
        self.block_end = None
        self.prefix_key = None

        f = self.cpm.get_file(drv, fn, self.cpm.current_user)
        if f:
            raw = f['data']
            eof = raw.find(b'\x1a')
            if eof != -1:
                raw = raw[:eof]
            chars = []
            for b in raw:
                cb = b & 0x7F
                if cb in (10, 13) or 32 <= cb <= 126 or cb == 9:
                    chars.append(chr(cb))
            decoded = "".join(chars)
            lines = decoded.replace('\r\n', '\n').replace('\r', '\n').split('\n')
            self.lines = lines if lines else [""]
            self.status_msg = f"Read {len(self.lines)} lines from {drv}:{fn}"
        else:
            self.lines = [""]
            self.status_msg = f"New file: {drv}:{fn}"

        self.mode = "EDIT"
        self.render_screen()

    def save_file(self, filename=None):
        target_fn = filename if filename else self.filename
        if not target_fn:
            self.status_msg = "No filename specified"
            self.render_screen()
            return False
        drv, fn = self.cpm.parse_filespec(target_fn)
        out_text = "\r\n".join(self.lines) + "\r\n"
        out_data = out_text.encode('ascii', errors='replace') + b"\x1a"
        self.cpm.put_file(drv, fn, out_data, user=self.cpm.current_user)
        self.modified = False
        self.status_msg = f"Saved {drv}:{fn} ({len(out_data)} bytes)"
        self.render_screen()
        return True

    def done(self):
        if self.mode == "EDIT":
            self.save_file()
        self.open_menu()

    def exit_to_cpm(self):
        if self.mode == "EDIT" and self.modified:
            self.save_file()
        self.active = False
        self.cpm.active_app = None
        self.cpm.screen.cls()
        self.cpm.print_banner()
        self.cpm.prompt()
        self.cpm.screen.draw_cursor(True)

    def abandon(self):
        self.modified = False
        self.open_menu()

    def print_file(self, filename=None):
        lines_to_print = self.lines
        target_name = self.filename
        if filename:
            drv, fn = self.cpm.parse_filespec(filename)
            target_name = fn
            f = self.cpm.get_file(drv, fn, self.cpm.current_user)
            if f:
                raw = f['data']
                eof = raw.find(b'\x1a')
                if eof != -1: raw = raw[:eof]
                cleaned = "".join(chr(b & 0x7F) for b in raw if (b & 0x7F) in (10, 13) or 32 <= (b & 0x7F) <= 126)
                lines_to_print = cleaned.replace('\r\n', '\n').replace('\r', '\n').split('\n')

        header = ""
        footer = ""
        omit_page = False
        page_num = 1
        self.cpm.screen.cls()
        self.cpm.screen.puts(f"--- Printing: {target_name} ---\r\n")

        for line in lines_to_print:
            s = line.strip()
            if s.startswith('.'):
                dot_cmd = s[1:3].lower()
                arg = s[3:].strip()
                if dot_cmd == "he": header = arg
                elif dot_cmd == "fo": footer = arg
                elif dot_cmd == "op": omit_page = True
                elif dot_cmd == "pa":
                    self.cpm.screen.puts(f"\r\n[PAGE {page_num} BREAK]\r\n")
                    page_num += 1
                continue
            self.cpm.screen.puts(line + "\r\n")

        if footer:
            foot_str = footer.replace('#', str(page_num))
            self.cpm.screen.puts(f"\r\n{foot_str}\r\n")
        self.status_msg = "Print complete"
        if self.mode != "MENU":
            self.render_screen()

    # Editing operations
    def insert_char(self, ch):
        cur_line = self.lines[self.cursor_row]
        if self.insert_mode:
            self.lines[self.cursor_row] = cur_line[:self.cursor_col] + ch + cur_line[self.cursor_col:]
        else:
            if self.cursor_col < len(cur_line):
                self.lines[self.cursor_row] = cur_line[:self.cursor_col] + ch + cur_line[self.cursor_col+1:]
            else:
                self.lines[self.cursor_row] = cur_line + ch
        self.cursor_col += 1
        self.modified = True

        # Word wrap check
        if self.word_wrap and self.cursor_col >= self.right_margin:
            line = self.lines[self.cursor_row]
            last_sp = line.rfind(' ', self.left_margin - 1, self.cursor_col)
            if last_sp != -1 and last_sp > self.left_margin:
                wrapped_word = line[last_sp + 1:]
                self.lines[self.cursor_row] = line[:last_sp]
                indent = " " * (self.left_margin - 1)
                self.lines.insert(self.cursor_row + 1, indent + wrapped_word)
                self.cursor_row += 1
                self.cursor_col = len(indent) + len(wrapped_word)

    def newline(self):
        line = self.lines[self.cursor_row]
        tail = line[self.cursor_col:]
        self.lines[self.cursor_row] = line[:self.cursor_col]
        indent = " " * (self.left_margin - 1)
        self.lines.insert(self.cursor_row + 1, indent + tail)
        self.cursor_row += 1
        self.cursor_col = len(indent)
        self.modified = True

    def backspace(self):
        if self.cursor_col > 0:
            line = self.lines[self.cursor_row]
            self.lines[self.cursor_row] = line[:self.cursor_col - 1] + line[self.cursor_col:]
            self.cursor_col -= 1
            self.modified = True
        elif self.cursor_row > 0:
            prev_len = len(self.lines[self.cursor_row - 1])
            self.lines[self.cursor_row - 1] += self.lines[self.cursor_row]
            del self.lines[self.cursor_row]
            self.cursor_row -= 1
            self.cursor_col = prev_len
            self.modified = True

    def delete_char(self):
        line = self.lines[self.cursor_row]
        if self.cursor_col < len(line):
            self.lines[self.cursor_row] = line[:self.cursor_col + 1]
            self.lines[self.cursor_row] = line[:self.cursor_col] + line[self.cursor_col + 1:]
            self.modified = True
        elif self.cursor_row < len(self.lines) - 1:
            self.lines[self.cursor_row] += self.lines[self.cursor_row + 1]
            del self.lines[self.cursor_row + 1]
            self.modified = True

    def delete_line(self):
        if len(self.lines) > 1:
            del self.lines[self.cursor_row]
            if self.cursor_row >= len(self.lines):
                self.cursor_row = len(self.lines) - 1
        else:
            self.lines[0] = ""
        self.cursor_col = min(self.cursor_col, len(self.lines[self.cursor_row]))
        self.modified = True

    def delete_word(self):
        line = self.lines[self.cursor_row]
        if self.cursor_col >= len(line):
            self.delete_char()
            return
        idx = self.cursor_col
        while idx < len(line) and line[idx] != ' ':
            idx += 1
        while idx < len(line) and line[idx] == ' ':
            idx += 1
        self.lines[self.cursor_row] = line[:self.cursor_col] + line[idx:]
        self.modified = True

    def delete_to_eol(self):
        self.lines[self.cursor_row] = self.lines[self.cursor_row][:self.cursor_col]
        self.modified = True

    def cursor_left(self):
        if self.cursor_col > 0:
            self.cursor_col -= 1
        elif self.cursor_row > 0:
            self.cursor_row -= 1
            self.cursor_col = len(self.lines[self.cursor_row])

    def cursor_right(self):
        if self.cursor_col < len(self.lines[self.cursor_row]):
            self.cursor_col += 1
        elif self.cursor_row < len(self.lines) - 1:
            self.cursor_row += 1
            self.cursor_col = 0

    def cursor_up(self):
        if self.cursor_row > 0:
            self.cursor_row -= 1
            self.cursor_col = min(self.cursor_col, len(self.lines[self.cursor_row]))

    def cursor_down(self):
        if self.cursor_row < len(self.lines) - 1:
            self.cursor_row += 1
            self.cursor_col = min(self.cursor_col, len(self.lines[self.cursor_row]))

    def word_left(self):
        if self.cursor_col == 0 and self.cursor_row > 0:
            self.cursor_row -= 1
            self.cursor_col = len(self.lines[self.cursor_row])
        line = self.lines[self.cursor_row]
        idx = self.cursor_col
        while idx > 0 and line[idx - 1] == ' ':
            idx -= 1
        while idx > 0 and line[idx - 1] != ' ':
            idx -= 1
        self.cursor_col = idx

    def word_right(self):
        line = self.lines[self.cursor_row]
        if self.cursor_col >= len(line) and self.cursor_row < len(self.lines) - 1:
            self.cursor_row += 1
            self.cursor_col = 0
            return
        idx = self.cursor_col
        while idx < len(line) and line[idx] != ' ':
            idx += 1
        while idx < len(line) and line[idx] == ' ':
            idx += 1
        self.cursor_col = idx

    def page_up(self):
        self.cursor_row = max(0, self.cursor_row - 18)
        self.cursor_col = min(self.cursor_col, len(self.lines[self.cursor_row]))

    def page_down(self):
        self.cursor_row = min(len(self.lines) - 1, self.cursor_row + 18)
        self.cursor_col = min(self.cursor_col, len(self.lines[self.cursor_row]))

    def scroll_up_line(self):
        if self.top_line > 0:
            self.top_line -= 1

    def scroll_down_line(self):
        if self.top_line < len(self.lines) - 1:
            self.top_line += 1

    def tab_indent(self):
        next_tab = ((self.cursor_col // self.tab_size) + 1) * self.tab_size
        spaces = max(1, next_tab - self.cursor_col)
        for _ in range(spaces):
            self.insert_char(' ')

    def reformat_paragraph(self):
        start_r = self.cursor_row
        while start_r > 0 and self.lines[start_r - 1].strip() and not self.lines[start_r - 1].startswith('.'):
            start_r -= 1
        end_r = self.cursor_row
        while end_r < len(self.lines) - 1 and self.lines[end_r + 1].strip() and not self.lines[end_r + 1].startswith('.'):
            end_r += 1

        para_lines = self.lines[start_r : end_r + 1]
        all_words = []
        for pl in para_lines:
            all_words.extend(pl.split())

        if not all_words:
            return

        max_w = max(10, self.right_margin - self.left_margin + 1)
        new_lines = []
        cur_line_words = []
        cur_len = 0
        indent = " " * (self.left_margin - 1)

        for w in all_words:
            if not cur_line_words:
                cur_line_words.append(w)
                cur_len = len(w)
            elif cur_len + 1 + len(w) <= max_w:
                cur_line_words.append(w)
                cur_len += 1 + len(w)
            else:
                new_lines.append(indent + " ".join(cur_line_words))
                cur_line_words = [w]
                cur_len = len(w)

        if cur_line_words:
            new_lines.append(indent + " ".join(cur_line_words))

        self.lines[start_r : end_r + 1] = new_lines
        self.cursor_row = min(start_r + len(new_lines) - 1, len(self.lines) - 1)
        self.cursor_col = len(self.lines[self.cursor_row])
        self.modified = True
        self.status_msg = "Paragraph reformatted"
        self.render_screen()

    def center_line(self):
        text = self.lines[self.cursor_row].strip()
        avail_w = max(1, self.right_margin - self.left_margin + 1)
        pad = max(0, (avail_w - len(text)) // 2)
        indent = " " * (self.left_margin - 1 + pad)
        self.lines[self.cursor_row] = indent + text
        self.modified = True
        self.status_msg = "Line centered"
        self.render_screen()

    def find_text(self, target):
        if not target:
            return False
        self.find_str = target
        t_low = target.lower()
        for r in range(self.cursor_row, len(self.lines)):
            c_start = (self.cursor_col + 1) if r == self.cursor_row else 0
            pos = self.lines[r].lower().find(t_low, c_start)
            if pos != -1:
                self.cursor_row = r
                self.cursor_col = pos
                self.status_msg = f"Found '{target}'"
                self.render_screen()
                return True
        for r in range(0, self.cursor_row + 1):
            pos = self.lines[r].lower().find(t_low)
            if pos != -1 and (r < self.cursor_row or pos < self.cursor_col):
                self.cursor_row = r
                self.cursor_col = pos
                self.status_msg = f"Found '{target}' (wrapped)"
                self.render_screen()
                return True
        self.status_msg = f"'{target}' not found"
        self.render_screen()
        return False

    def replace_text(self, target, replacement, all_matches=False):
        if not target: return
        self.find_str = target
        self.replace_str = replacement
        count = 0
        t_low = target.lower()
        for r in range(len(self.lines)):
            line = self.lines[r]
            if t_low in line.lower():
                idx = 0
                while idx < len(line):
                    pos = line.lower().find(t_low, idx)
                    if pos == -1: break
                    line = line[:pos] + replacement + line[pos + len(target):]
                    idx = pos + len(replacement)
                    count += 1
                    if not all_matches: break
                self.lines[r] = line
                if not all_matches and count > 0:
                    self.cursor_row = r
                    self.cursor_col = idx
                    break
        if count > 0:
            self.modified = True
            self.status_msg = f"Replaced {count} occurrence(s)"
        else:
            self.status_msg = f"'{target}' not found"
        self.render_screen()

    # Block operations
    def set_block_begin(self):
        self.block_begin = (self.cursor_row, self.cursor_col)
        self.status_msg = f"Block begin set at Line {self.cursor_row+1}, Col {self.cursor_col+1}"
        self.render_screen()

    def set_block_end(self):
        self.block_end = (self.cursor_row, self.cursor_col)
        self.status_msg = f"Block end set at Line {self.cursor_row+1}, Col {self.cursor_col+1}"
        self.render_screen()

    def _get_block_range(self):
        if not self.block_begin or not self.block_end:
            return None, None
        b1 = min(self.block_begin, self.block_end)
        b2 = max(self.block_begin, self.block_end)
        return b1, b2

    def copy_block(self):
        b1, b2 = self._get_block_range()
        if not b1 or not b2:
            self.status_msg = "No block marked"
            self.render_screen()
            return
        r1, c1 = b1
        r2, c2 = b2
        if r1 == r2:
            blk_text = [self.lines[r1][c1:c2]]
        else:
            blk_text = [self.lines[r1][c1:]] + self.lines[r1+1 : r2] + [self.lines[r2][:c2]]

        cur_line = self.lines[self.cursor_row]
        tail = cur_line[self.cursor_col:]
        self.lines[self.cursor_row] = cur_line[:self.cursor_col] + blk_text[0]
        for idx in range(1, len(blk_text)):
            self.lines.insert(self.cursor_row + idx, blk_text[idx])
        self.lines[self.cursor_row + len(blk_text) - 1] += tail
        self.modified = True
        self.status_msg = "Block copied"
        self.render_screen()

    def delete_block(self):
        b1, b2 = self._get_block_range()
        if not b1 or not b2:
            self.status_msg = "No block marked"
            self.render_screen()
            return
        r1, c1 = b1
        r2, c2 = b2
        if r1 == r2:
            line = self.lines[r1]
            self.lines[r1] = line[:c1] + line[c2:]
        else:
            first_part = self.lines[r1][:c1]
            last_part = self.lines[r2][c2:]
            self.lines[r1] = first_part + last_part
            del self.lines[r1+1 : r2+1]
        self.cursor_row = min(r1, len(self.lines) - 1)
        self.cursor_col = min(c1, len(self.lines[self.cursor_row]))
        self.block_begin = None
        self.block_end = None
        self.modified = True
        self.status_msg = "Block deleted"
        self.render_screen()

    def move_block(self):
        b1, b2 = self._get_block_range()
        if not b1 or not b2:
            self.status_msg = "No block marked"
            self.render_screen()
            return
        r1, c1 = b1
        r2, c2 = b2
        if r1 == r2:
            blk_text = [self.lines[r1][c1:c2]]
        else:
            blk_text = [self.lines[r1][c1:]] + self.lines[r1+1 : r2] + [self.lines[r2][:c2]]
        self.delete_block()
        cur_line = self.lines[self.cursor_row]
        tail = cur_line[self.cursor_col:]
        self.lines[self.cursor_row] = cur_line[:self.cursor_col] + blk_text[0]
        for idx in range(1, len(blk_text)):
            self.lines.insert(self.cursor_row + idx, blk_text[idx])
        self.lines[self.cursor_row + len(blk_text) - 1] += tail
        self.modified = True
        self.status_msg = "Block moved"
        self.render_screen()

    def write_block(self, filename):
        b1, b2 = self._get_block_range()
        if not b1 or not b2:
            self.status_msg = "No block marked"
            self.render_screen()
            return
        r1, c1 = b1
        r2, c2 = b2
        if r1 == r2:
            blk_text = [self.lines[r1][c1:c2]]
        else:
            blk_text = [self.lines[r1][c1:]] + self.lines[r1+1 : r2] + [self.lines[r2][:c2]]
        drv, fn = self.cpm.parse_filespec(filename)
        out_data = ("\r\n".join(blk_text) + "\r\n").encode('ascii', errors='replace') + b"\x1a"
        self.cpm.put_file(drv, fn, out_data, user=self.cpm.current_user)
        self.status_msg = f"Block written to {drv}:{fn}"
        self.render_screen()

    def read_block(self, filename):
        drv, fn = self.cpm.parse_filespec(filename)
        f = self.cpm.get_file(drv, fn, self.cpm.current_user)
        if not f:
            self.status_msg = f"File {drv}:{fn} not found"
            self.render_screen()
            return
        raw = f['data']
        eof = raw.find(b'\x1a')
        if eof != -1: raw = raw[:eof]
        cleaned = "".join(chr(b & 0x7F) for b in raw if (b & 0x7F) in (10, 13) or 32 <= (b & 0x7F) <= 126)
        r_lines = cleaned.replace('\r\n', '\n').replace('\r', '\n').split('\n')
        cur_line = self.lines[self.cursor_row]
        tail = cur_line[self.cursor_col:]
        self.lines[self.cursor_row] = cur_line[:self.cursor_col] + r_lines[0]
        for idx in range(1, len(r_lines)):
            self.lines.insert(self.cursor_row + idx, r_lines[idx])
        self.lines[self.cursor_row + len(r_lines) - 1] += tail
        self.modified = True
        self.status_msg = f"Read {len(r_lines)} lines from {drv}:{fn}"
        self.render_screen()

    # Callbacks for prompts
    def cmd_open_document(self, fn):
        self.open_file(fn, is_doc=True)

    def cmd_open_non_doc(self, fn):
        self.open_file(fn, is_doc=False)

    def cmd_change_drive(self, drv_str):
        d = drv_str.strip().rstrip(':').upper()
        if d in self.cpm.drives:
            self.logged_drive = d
            self.cpm.current_drive = d
            self.status_msg = f"Logged drive is now {d}:"
        else:
            self.status_msg = "Invalid drive"
        self.open_menu()

    def cmd_print_file(self, fn):
        self.print_file(fn)

    def cmd_rename_step1(self, old_fn):
        self.status_msg = f"Old: {old_fn}"
        self.ask_prompt("NEW NAME? ", lambda new_fn: self.cmd_rename_step2(old_fn, new_fn))

    def cmd_rename_step2(self, old_fn, new_fn):
        self.cpm.cmd_ren(f"{new_fn}={old_fn}")
        self.status_msg = f"Renamed {old_fn} to {new_fn}"
        self.open_menu()

    def cmd_copy_step1(self, src_fn):
        self.status_msg = f"Source: {src_fn}"
        self.ask_prompt("DESTINATION FILE? ", lambda dst_fn: self.cmd_copy_step2(src_fn, dst_fn))

    def cmd_copy_step2(self, src_fn, dst_fn):
        self.cpm.cmd_pip(f"{dst_fn}={src_fn}")
        self.status_msg = f"Copied {src_fn} to {dst_fn}"
        self.open_menu()

    def cmd_delete_file(self, fn):
        drv, name = self.cpm.parse_filespec(fn)
        cnt = self.cpm.delete_file(drv, name, self.cpm.current_user)
        self.status_msg = f"Deleted {name}" if cnt > 0 else "File not found"
        self.open_menu()

    def cmd_set_help(self, lvl):
        try:
            self.help_level = int(lvl)
            self.status_msg = f"Help level set to {self.help_level}"
        except:
            self.status_msg = "Invalid help level"
        self.open_menu()

    def cmd_set_left_margin(self, col_str):
        try:
            c = int(col_str)
            if 1 <= c < self.right_margin:
                self.left_margin = c
                self.status_msg = f"Left margin set to {c}"
        except: pass
        self.mode = "EDIT"
        self.render_screen()

    def cmd_set_right_margin(self, col_str):
        try:
            c = int(col_str)
            if self.left_margin < c <= 50:
                self.right_margin = c
                self.status_msg = f"Right margin set to {c}"
        except: pass
        self.mode = "EDIT"
        self.render_screen()

    def cmd_find(self, target):
        self.mode = "EDIT"
        self.find_text(target)

    def cmd_replace_step1(self, target):
        self.find_str = target
        self.ask_prompt(f"REPLACE '{target}' WITH? ", self.cmd_replace_step2)

    def cmd_replace_step2(self, replacement):
        self.mode = "EDIT"
        self.replace_text(self.find_str, replacement, all_matches=True)

    def cmd_write_block(self, fn):
        self.mode = "EDIT"
        self.write_block(fn)

    def cmd_read_block(self, fn):
        self.mode = "EDIT"
        self.read_block(fn)

    # Interactive event handling in Pygame loop
    def handle_event(self, event):
        import pygame
        if self.mode == "PROMPT":
            if event.type == pygame.KEYDOWN:
                if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                    val = "".join(self.prompt_buffer).strip()
                    cb = self.prompt_callback
                    self.mode = self.prompt_prev_mode
                    if cb: cb(val)
                    return True
                elif event.key == pygame.K_BACKSPACE:
                    if self.prompt_buffer: self.prompt_buffer.pop()
                    self.render_prompt()
                    return True
                elif event.key == pygame.K_ESCAPE:
                    self.mode = self.prompt_prev_mode
                    self.render_screen()
                    return True
            elif event.type == pygame.TEXTINPUT:
                for ch in event.text:
                    if ch not in ('\r', '\n') and len(self.prompt_buffer) < 40:
                        self.prompt_buffer.append(ch)
                self.render_prompt()
                return True
            return False

        if self.mode == "MENU":
            if event.type == pygame.KEYDOWN:
                k = event.key
                if k == pygame.K_d: self.ask_prompt("NAME OF FILE TO EDIT? ", self.cmd_open_document); return True
                elif k == pygame.K_n: self.ask_prompt("NAME OF NON-DOCUMENT FILE? ", self.cmd_open_non_doc); return True
                elif k == pygame.K_l: self.ask_prompt("NEW LOGGED DRIVE (A, B, M)? ", self.cmd_change_drive); return True
                elif k == pygame.K_f: self.show_directory = not self.show_directory; self.render_screen(); return True
                elif k == pygame.K_p: self.ask_prompt("NAME OF FILE TO PRINT? ", self.cmd_print_file); return True
                elif k == pygame.K_e: self.ask_prompt("FILE TO RENAME? ", self.cmd_rename_step1); return True
                elif k == pygame.K_o: self.ask_prompt("SOURCE FILE TO COPY? ", self.cmd_copy_step1); return True
                elif k == pygame.K_y: self.ask_prompt("FILE TO DELETE? ", self.cmd_delete_file); return True
                elif k == pygame.K_h: self.ask_prompt("HELP LEVEL (0-3)? ", self.cmd_set_help); return True
                elif k in (pygame.K_x, pygame.K_q): self.exit_to_cpm(); return True
            return False

        if self.mode == "EDIT":
            if event.type == pygame.KEYDOWN:
                k = event.key
                mod = getattr(event, "mod", 0)
                is_ctrl = bool(mod & pygame.KMOD_CTRL)

                if is_ctrl:
                    if k == pygame.K_k: self.prefix_key = '^K'; self.render_screen(); return True
                    elif k == pygame.K_o: self.prefix_key = '^O'; self.render_screen(); return True
                    elif k == pygame.K_q: self.prefix_key = '^Q'; self.render_screen(); return True
                    elif k == pygame.K_j: self.prefix_key = '^J'; self.render_screen(); return True
                    elif k == pygame.K_s: self.cursor_left(); self._adjust_view(); return True
                    elif k == pygame.K_d: self.cursor_right(); self._adjust_view(); return True
                    elif k == pygame.K_e: self.cursor_up(); self._adjust_view(); return True
                    elif k == pygame.K_x: self.cursor_down(); self._adjust_view(); return True
                    elif k == pygame.K_a: self.word_left(); self._adjust_view(); return True
                    elif k == pygame.K_f: self.word_right(); self._adjust_view(); return True
                    elif k == pygame.K_r: self.page_up(); self._adjust_view(); return True
                    elif k == pygame.K_c: self.page_down(); self._adjust_view(); return True
                    elif k == pygame.K_w: self.scroll_up_line(); self.render_screen(); return True
                    elif k == pygame.K_z: self.scroll_down_line(); self.render_screen(); return True
                    elif k == pygame.K_g: self.delete_char(); self._adjust_view(); return True
                    elif k == pygame.K_h: self.backspace(); self._adjust_view(); return True
                    elif k == pygame.K_y: self.delete_line(); self._adjust_view(); return True
                    elif k == pygame.K_t: self.delete_word(); self._adjust_view(); return True
                    elif k == pygame.K_v: self.insert_mode = not self.insert_mode; self.render_screen(); return True
                    elif k == pygame.K_b: self.reformat_paragraph(); return True

                if self.prefix_key:
                    pref = self.prefix_key
                    self.prefix_key = None
                    if pref == '^K':
                        if k == pygame.K_d: self.done(); return True
                        elif k == pygame.K_s: self.save_file(); return True
                        elif k == pygame.K_x: self.exit_to_cpm(); return True
                        elif k == pygame.K_q: self.abandon(); return True
                        elif k == pygame.K_b: self.set_block_begin(); return True
                        elif k == pygame.K_k: self.set_block_end(); return True
                        elif k == pygame.K_c: self.copy_block(); return True
                        elif k == pygame.K_v: self.move_block(); return True
                        elif k == pygame.K_y: self.delete_block(); return True
                        elif k == pygame.K_w: self.ask_prompt("WRITE BLOCK TO FILE? ", self.cmd_write_block); return True
                        elif k == pygame.K_r: self.ask_prompt("READ FILE INTO TEXT? ", self.cmd_read_block); return True
                        elif k == pygame.K_p: self.print_file(); return True
                    elif pref == '^O':
                        if k == pygame.K_c: self.center_line(); return True
                        elif k == pygame.K_w: self.word_wrap = not self.word_wrap; self.status_msg = f"Word wrap {'ON' if self.word_wrap else 'OFF'}"; self.render_screen(); return True
                        elif k == pygame.K_j: self.justify = not self.justify; self.status_msg = f"Justify {'ON' if self.justify else 'OFF'}"; self.render_screen(); return True
                        elif k == pygame.K_l: self.ask_prompt("LEFT MARGIN COLUMN (1-50)? ", self.cmd_set_left_margin); return True
                        elif k == pygame.K_r: self.ask_prompt("RIGHT MARGIN COLUMN (1-50)? ", self.cmd_set_right_margin); return True
                    elif pref == '^Q':
                        if k == pygame.K_s: self.cursor_col = 0; self._adjust_view(); return True
                        elif k == pygame.K_d: self.cursor_col = len(self.lines[self.cursor_row]); self._adjust_view(); return True
                        elif k == pygame.K_r: self.cursor_row = 0; self.cursor_col = 0; self.top_line = 0; self._adjust_view(); return True
                        elif k == pygame.K_c: self.cursor_row = len(self.lines) - 1; self.cursor_col = len(self.lines[-1]); self._adjust_view(); return True
                        elif k == pygame.K_y: self.delete_to_eol(); self.render_screen(); return True
                        elif k == pygame.K_f: self.ask_prompt("FIND? ", self.cmd_find); return True
                        elif k == pygame.K_a: self.ask_prompt("FIND? ", self.cmd_replace_step1); return True
                    elif pref == '^J':
                        self.render_screen(); return True

                # Standard keys without Ctrl
                if k == pygame.K_LEFT: self.cursor_left(); self._adjust_view(); return True
                elif k == pygame.K_RIGHT: self.cursor_right(); self._adjust_view(); return True
                elif k == pygame.K_UP: self.cursor_up(); self._adjust_view(); return True
                elif k == pygame.K_DOWN: self.cursor_down(); self._adjust_view(); return True
                elif k == pygame.K_PAGEUP: self.page_up(); self._adjust_view(); return True
                elif k == pygame.K_PAGEDOWN: self.page_down(); self._adjust_view(); return True
                elif k == pygame.K_HOME: self.cursor_col = 0; self._adjust_view(); return True
                elif k == pygame.K_END: self.cursor_col = len(self.lines[self.cursor_row]); self._adjust_view(); return True
                elif k == pygame.K_BACKSPACE: self.backspace(); self._adjust_view(); return True
                elif k == pygame.K_DELETE: self.delete_char(); self._adjust_view(); return True
                elif k in (pygame.K_RETURN, pygame.K_KP_ENTER): self.newline(); self._adjust_view(); return True
                elif k == pygame.K_TAB: self.tab_indent(); self._adjust_view(); return True
                elif k == pygame.K_ESCAPE:
                    self.prefix_key = None
                    self.status_msg = ""
                    self.render_screen()
                    return True

            elif event.type == pygame.TEXTINPUT:
                if self.prefix_key is None:
                    for ch in event.text:
                        if ch not in ('\r', '\n'):
                            self.insert_char(ch)
                    self._adjust_view()
                    return True

        return False

    def _adjust_view(self):
        if self.cursor_row < self.top_line:
            self.top_line = self.cursor_row
        elif self.cursor_row >= self.top_line + 21:
            self.top_line = self.cursor_row - 20

        if self.cursor_col < self.left_col:
            self.left_col = self.cursor_col
        elif self.cursor_col >= self.left_col + 50:
            self.left_col = self.cursor_col - 49
        self.render_screen()

    # Headless / batch execution
    def execute_line(self, line):
        cmd_raw = line.strip()
        if not cmd_raw: return
        parts = cmd_raw.split(None, 1)
        verb = parts[0].upper()
        args = parts[1].strip() if len(parts) > 1 else ""

        if verb in ("D", "OPEN"): self.open_file(args, is_doc=True)
        elif verb == "N": self.open_file(args, is_doc=False)
        elif verb in ("TEXT", "INSERT"):
            for ch in args: self.insert_char(ch)
            self.newline()
            self._adjust_view()
        elif verb in ("SAVE", "^KS"): self.save_file()
        elif verb in ("DONE", "^KD"): self.done()
        elif verb in ("EXIT", "^KX", "X"): self.exit_to_cpm()
        elif verb in ("QUIT", "ABANDON", "^KQ"): self.abandon()
        elif verb in ("REFORMAT", "^B"): self.reformat_paragraph()
        elif verb in ("CENTER", "^OC"): self.center_line()
        elif verb in ("FIND", "^QF"): self.find_text(args)
        elif verb in ("REPLACE", "^QA"):
            if '=' in args:
                o, n = args.split('=', 1)
                self.replace_text(o.strip(), n.strip(), all_matches=True)
        elif verb == "BLOCK_BEGIN": self.set_block_begin()
        elif verb == "BLOCK_END": self.set_block_end()
        elif verb == "BLOCK_COPY": self.copy_block()
        elif verb == "BLOCK_MOVE": self.move_block()
        elif verb == "BLOCK_DELETE": self.delete_block()
        elif verb in ("PRINT", "P", "^KP"): self.print_file(args if args else None)
        elif verb == "L": self.cmd_change_drive(args)
        elif verb == "F": self.show_directory = not self.show_directory; self.render_screen()
        elif verb == "DIR": self.cpm.cmd_dir(args)
        elif verb == "HELP": self.status_msg = "WordStar 2.26 Help"; self.render_screen()
        else:
            for ch in cmd_raw: self.insert_char(ch)
            self.newline()
            self._adjust_view()


class CalcStar:
    """
    MicroPro CalcStar Compatible Electronic Spreadsheet System for CP/M.
    Authentic 51x24 CRT display electronic spreadsheet featuring:
    - 26 Columns (A-Z) x 255 Rows (1-255) grid model.
    - Floating point & integer arithmetic, string labels, formatting options.
    - Full formula evaluator: +, -, *, /, ^, comparisons, parentheses, cell and range references.
    - Built-in functions: SUM, AVG/AVERAGE, CNT/COUNT, MIN, MAX, ABS, INT, SQRT, ROUND, NPV, IF.
    - Formatting: General (G), Fixed (F0-F4), Currency ($), Integer (I), Label Align (L, R, C), Bar chart (*).
    - Slash commands: /F (format), /C (copy), /M (move), /D (delete row/col), /I (insert row/col),
      /W (col width), /B (blank), /S (save .CAL), /L (load .CAL), /P (print), /R (recalc),
      /A (auto-calc toggle), /G (goto), /Q, /X (exit to CP/M).
    - WordStar Diamond cursor navigation (^E, ^X, ^S, ^D, ^A, ^F, ^R, ^C) and Arrow keys.
    - Standard CP/M ASCII .CAL file persistence with \\r\\n and 0x1A EOF.
    """
    def __init__(self, cpm_system):
        self.cpm = cpm_system
        self.active = False
        self.mode = "READY"        # "READY", "EDIT", "SLASH", "PROMPT"
        self.filename = "UNTITLED.CAL"
        self.logged_drive = 'A'
        self.cells = {}           # (col, row) -> {'raw': str, 'val': any, 'formula': str, 'format': str}
        self.col_widths = [10] * 26
        self.cursor_col = 0       # 0..25 (A..Z)
        self.cursor_row = 0       # 0..254 (1..255)
        self.top_row = 0          # 0..235 (visible rows 0..19 + top_row)
        self.left_col = 0         # 0..25
        self.auto_calc = True
        self.modified = False
        self.status_msg = ""
        self.input_buffer = []
        self.prompt_text = ""
        self.prompt_buffer = []
        self.prompt_callback = None
        self.visiting = set()
        self._temp_copy_src = ""
        self._temp_move_src = ""

    def start(self, args=""):
        self.active = True
        self.cpm.active_app = "CALCSTAR"
        self.logged_drive = self.cpm.current_drive
        arg = args.strip()
        if arg:
            drv, fn = self.cpm.parse_filespec(arg)
            self.logged_drive = drv
            if not fn.upper().endswith(".CAL") and "." not in fn:
                fn += ".CAL"
            self.filename = fn
            self.load_file(fn)
        else:
            if not self.cells:
                self.filename = "UNTITLED.CAL"
            self.mode = "READY"
            self.status_msg = "CalcStar v1.4 Ready - Press '/' for menu"
            self.render_screen()

    def exit_to_cpm(self):
        self.active = False
        self.cpm.active_app = None
        self.cpm.screen.cls()
        self.cpm.screen.puts(f"\r\n{self.cpm.current_drive}>")
        self.cpm.screen.draw_cursor(True)

    def reset_sheet(self):
        self.cells.clear()
        self.col_widths = [10] * 26
        self.cursor_col = 0
        self.cursor_row = 0
        self.top_row = 0
        self.left_col = 0
        self.filename = "UNTITLED.CAL"
        self.status_msg = "New spreadsheet initialized."
        self.mode = "READY"
        self.render_screen()

    @staticmethod
    def col_to_name(c):
        return chr(ord('A') + max(0, min(25, c)))

    @staticmethod
    def name_to_col(s):
        s = s.strip().upper()
        if s and s[0].isalpha():
            return ord(s[0]) - ord('A')
        return 0

    @classmethod
    def parse_cell_coord(cls, s):
        m = re.match(r'^\$?([A-Za-z]+)\$?(\d+)$', s.strip())
        if not m:
            return None
        col_str, row_str = m.groups()
        c = cls.name_to_col(col_str)
        try:
            r = int(row_str) - 1
        except ValueError:
            return None
        if 0 <= c < 26 and 0 <= r < 255:
            return (c, r)
        return None

    @classmethod
    def parse_range(cls, s):
        parts = re.split(r':|\.\.', s.strip())
        if len(parts) != 2:
            coord = cls.parse_cell_coord(s)
            return [coord] if coord else []
        c1 = cls.parse_cell_coord(parts[0])
        c2 = cls.parse_cell_coord(parts[1])
        if not c1 or not c2:
            return []
        min_c, max_c = min(c1[0], c2[0]), max(c1[0], c2[0])
        min_r, max_r = min(c1[1], c2[1]), max(c1[1], c2[1])
        res = []
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                res.append((c, r))
        return res

    def get_cell(self, col, row):
        return self.cells.get((col, row))

    def get_cell_val(self, col, row):
        cell = self.cells.get((col, row))
        if not cell:
            return 0.0
        val = cell.get('val')
        if isinstance(val, (int, float)):
            return float(val)
        if isinstance(val, str):
            try:
                return float(val)
            except ValueError:
                return val
        return 0.0

    def get_cell_format(self, col, row):
        cell = self.cells.get((col, row))
        if cell and cell.get('format'):
            return cell['format']
        return "G"

    def set_cell(self, col, row, text, fmt=None):
        if not (0 <= col < 26 and 0 <= row < 255):
            return
        text = str(text).strip()
        if not text:
            if (col, row) in self.cells:
                del self.cells[(col, row)]
            if self.auto_calc:
                self.recalculate_all()
            self.modified = True
            return

        cell = self.cells.setdefault((col, row), {'raw': '', 'val': 0.0, 'formula': None, 'format': 'G'})
        if fmt:
            cell['format'] = fmt.upper()
        cell['raw'] = text

        fn_keywords = ('SUM', 'AVG', 'AVERAGE', 'CNT', 'COUNT', 'MIN', 'MAX', 'ABS', 'INT', 'SQRT', 'ROUND', 'NPV', 'IF')
        text_u = text.upper()
        if text.startswith('='):
            cell['formula'] = text[1:].strip()
        elif text.startswith('+') or any(text_u.startswith(k + '(') for k in fn_keywords):
            cell['formula'] = text.lstrip('+').strip()
        else:
            cell['formula'] = None
            try:
                cell['val'] = float(text) if '.' in text else int(text)
            except ValueError:
                if (text.startswith("'") and text.endswith("'")) or (text.startswith('"') and text.endswith('"')):
                    cell['val'] = text[1:-1]
                else:
                    cell['val'] = text

        self.modified = True
        if self.auto_calc:
            self.recalculate_all()

    def tokenize(self, s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
                continue
            if ch in ('(', ')', '+', '-', '*', '/', '^', ','):
                tokens.append(ch)
                i += 1
                continue
            if ch == '=':
                tokens.append(ch)
                i += 1
                continue
            if ch == '<':
                if i + 1 < n and s[i+1] in ('=', '>'):
                    tokens.append(s[i:i+2])
                    i += 2
                    continue
                tokens.append(ch)
                i += 1
                continue
            if ch == '>':
                if i + 1 < n and s[i+1] == '=':
                    tokens.append(s[i:i+2])
                    i += 2
                    continue
                tokens.append(ch)
                i += 1
                continue
            if ch in ('"', "'"):
                quote = ch
                j = i + 1
                while j < n and s[j] != quote:
                    j += 1
                tokens.append(s[i:j+1])
                i = j + 1
                continue
            if ch.isdigit() or (ch == '.' and i + 1 < n and s[i+1].isdigit()):
                j = i
                while j < n and (s[j].isdigit() or s[j] == '.'):
                    j += 1
                num_str = s[i:j]
                tokens.append(float(num_str) if '.' in num_str else int(num_str))
                i = j
                continue
            if ch.isalpha() or ch == '$':
                j = i
                while j < n and (s[j].isalnum() or s[j] in ('$', ':', '.')):
                    j += 1
                tokens.append(s[i:j])
                i = j
                continue
            i += 1
        return tokens

    def eval_formula(self, expr_str, current_cell=None):
        expr_str = str(expr_str).strip()
        if not expr_str:
            return 0.0

        tokens = self.tokenize(expr_str)
        idx = 0

        def peek():
            return tokens[idx] if idx < len(tokens) else None

        def consume(expected=None):
            nonlocal idx
            t = peek()
            if expected is not None and t != expected:
                raise ValueError(f"Expected {expected}, got {t}")
            idx += 1
            return t

        def parse_expr():
            left = parse_arith()
            t = peek()
            if t in ('=', '<>', '<', '>', '<=', '>='):
                op = consume()
                right = parse_arith()
                if op == '=': return 1.0 if left == right else 0.0
                elif op == '<>': return 1.0 if left != right else 0.0
                elif op == '<': return 1.0 if left < right else 0.0
                elif op == '>': return 1.0 if left > right else 0.0
                elif op == '<=': return 1.0 if left <= right else 0.0
                elif op == '>=': return 1.0 if left >= right else 0.0
            return left

        def parse_arith():
            node = parse_term()
            while peek() in ('+', '-'):
                op = consume()
                right = parse_term()
                if op == '+':
                    node = node + right
                else:
                    node = node - right
            return node

        def parse_term():
            node = parse_power()
            while peek() in ('*', '/'):
                op = consume()
                right = parse_power()
                if op == '*':
                    node = node * right
                else:
                    if right == 0:
                        raise ZeroDivisionError()
                    node = node / right
            return node

        def parse_power():
            node = parse_factor()
            if peek() == '^':
                consume('^')
                right = parse_power()
                node = node ** right
            return node

        def parse_factor():
            t = peek()
            if t == '+':
                consume('+')
                return parse_factor()
            elif t == '-':
                consume('-')
                return -parse_factor()
            return parse_primary()

        def parse_primary():
            t = peek()
            if t is None:
                return 0.0
            if t == '(':
                consume('(')
                res = parse_expr()
                consume(')')
                return res

            if isinstance(t, (int, float)):
                consume()
                return float(t)

            if isinstance(t, str) and (t.startswith('"') or t.startswith("'")):
                consume()
                return t[1:-1]

            if isinstance(t, str):
                ident = consume().upper()
                if peek() == '(':
                    consume('(')
                    args = []
                    if peek() != ')':
                        while True:
                            if peek_is_range():
                                r_tok = consume()
                                args.append(('RANGE', r_tok))
                            else:
                                arg_val = parse_expr()
                                args.append(('VAL', arg_val))
                            if peek() == ',':
                                consume(',')
                            else:
                                break
                    consume(')')
                    return self.call_function(ident, args)
                else:
                    coord = self.parse_cell_coord(ident)
                    if coord:
                        if coord in self.visiting:
                            raise RecursionError("Circular reference")
                        if current_cell:
                            self.visiting.add(current_cell)
                        try:
                            c_ref = self.cells.get(coord)
                            if c_ref and c_ref.get('formula'):
                                val = self.eval_formula(c_ref['formula'], current_cell=coord)
                                c_ref['val'] = val
                                return float(val) if isinstance(val, (int, float)) else val
                            return self.get_cell_val(coord[0], coord[1])
                        finally:
                            if current_cell and current_cell in self.visiting:
                                self.visiting.remove(current_cell)
                    return 0.0
            return 0.0

        def peek_is_range():
            tok = peek()
            if isinstance(tok, str) and (':' in tok or '..' in tok):
                return True
            return False

        try:
            return parse_expr()
        except ZeroDivisionError:
            return "#ERR"
        except RecursionError:
            return "#REF!"
        except Exception:
            return "#ERR"

    def call_function(self, name, args):
        name = name.upper()
        def expand_range(arg):
            if arg[0] == 'RANGE':
                coords = self.parse_range(arg[1])
                vals = []
                for c, r in coords:
                    cell = self.cells.get((c, r))
                    if cell and cell.get('val') is not None:
                        v = cell['val']
                        if isinstance(v, (int, float)):
                            vals.append(float(v))
                        elif isinstance(v, str):
                            try: vals.append(float(v))
                            except ValueError: pass
                return vals
            else:
                v = arg[1]
                if isinstance(v, (int, float)):
                    return [float(v)]
                return []

        if name in ('SUM', 'TOTAL'):
            vals = []
            for a in args: vals.extend(expand_range(a))
            return sum(vals)
        elif name in ('AVG', 'AVERAGE'):
            vals = []
            for a in args: vals.extend(expand_range(a))
            return sum(vals) / len(vals) if vals else 0.0
        elif name in ('CNT', 'COUNT'):
            vals = []
            for a in args: vals.extend(expand_range(a))
            return float(len(vals))
        elif name == 'MIN':
            vals = []
            for a in args: vals.extend(expand_range(a))
            return min(vals) if vals else 0.0
        elif name == 'MAX':
            vals = []
            for a in args: vals.extend(expand_range(a))
            return max(vals) if vals else 0.0
        elif name == 'ABS':
            v = args[0][1] if args else 0.0
            return abs(float(v))
        elif name == 'INT':
            v = args[0][1] if args else 0.0
            return float(int(float(v)))
        elif name == 'SQRT':
            v = args[0][1] if args else 0.0
            v = float(v)
            if v < 0: raise ValueError("Negative sqrt")
            return math.sqrt(v)
        elif name == 'ROUND':
            v = float(args[0][1]) if len(args) > 0 else 0.0
            d = int(args[1][1]) if len(args) > 1 else 0
            return round(v, d)
        elif name == 'NPV':
            rate = float(args[0][1]) if len(args) > 0 else 0.0
            cfs = expand_range(args[1]) if len(args) > 1 else []
            npv = 0.0
            for t, cf in enumerate(cfs, 1):
                npv += cf / ((1.0 + rate) ** t)
            return npv
        elif name == 'IF':
            cond = args[0][1] if len(args) > 0 else 0.0
            true_v = args[1][1] if len(args) > 1 else 0.0
            false_v = args[2][1] if len(args) > 2 else 0.0
            return true_v if (cond != 0 and cond is not False) else false_v
        return 0.0

    def recalculate_all(self):
        for coord, cell in self.cells.items():
            if cell.get('formula'):
                self.visiting.clear()
                cell['val'] = self.eval_formula(cell['formula'], current_cell=coord)

    def format_cell_value(self, col, row, width):
        cell = self.cells.get((col, row))
        if not cell:
            return " " * width
        val = cell.get('val')
        fmt = cell.get('format', 'G').upper()

        if val is None:
            return " " * width

        if str(val) in ("#ERR", "#REF!"):
            s = str(val)
            return s[:width].rjust(width)

        if isinstance(val, str):
            s = val
            if fmt == 'R':
                return s[:width].rjust(width)
            elif fmt == 'C':
                return s[:width].center(width)
            else:
                return s[:width].ljust(width)

        num_val = float(val)
        if fmt == '$':
            if num_val < 0:
                s = f"-${abs(num_val):,.2f}"
            else:
                s = f"${num_val:,.2f}"
        elif fmt.startswith('F') and len(fmt) > 1 and fmt[1].isdigit():
            decs = int(fmt[1])
            s = f"{num_val:.{decs}f}"
        elif fmt == 'I':
            s = f"{int(round(num_val))}"
        elif fmt == '*':
            stars = int(max(0, round(num_val)))
            s = '*' * min(width, stars)
            return s.ljust(width)
        else:
            if num_val == int(num_val):
                s = f"{int(num_val)}"
            else:
                s = f"{num_val:.4f}".rstrip('0').rstrip('.')

        if len(s) > width:
            return "*" * width
        return s.rjust(width)

    def adjust_formula_refs(self, formula_str, delta_c, delta_r):
        def repl(m):
            abs_c, col_s, abs_r, row_s = m.groups()
            c = ord(col_s.upper()) - ord('A')
            r = int(row_s) - 1
            if not abs_c:
                c = max(0, min(25, c + delta_c))
            if not abs_r:
                r = max(0, min(254, r + delta_r))
            col_name = chr(ord('A') + c)
            return f"{abs_c}{col_name}{abs_r}{r+1}"
        return re.sub(r'(\$?)([A-Za-z]+)(\$?)(\d+)', repl, formula_str)

    def copy_range(self, src_spec, dst_spec):
        src_coords = self.parse_range(src_spec)
        dst_coords = self.parse_range(dst_spec)
        if not src_coords or not dst_coords:
            self.status_msg = "Invalid copy range."
            return

        base_src_c, base_src_r = src_coords[0]
        base_dst_c, base_dst_r = dst_coords[0]

        delta_c = base_dst_c - base_src_c
        delta_r = base_dst_r - base_src_r

        if len(src_coords) == 1 and len(dst_coords) > 1:
            src_cell = self.cells.get((base_src_c, base_src_r))
            if not src_cell:
                for dc, dr in dst_coords:
                    if (dc, dr) in self.cells: del self.cells[(dc, dr)]
            else:
                for dc, dr in dst_coords:
                    d_c = dc - base_src_c
                    d_r = dr - base_src_r
                    raw = src_cell.get('raw', '')
                    fmt = src_cell.get('format', 'G')
                    if src_cell.get('formula'):
                        adj_form = self.adjust_formula_refs(src_cell['formula'], d_c, d_r)
                        prefix = "=" if raw.startswith("=") else "+"
                        self.set_cell(dc, dr, prefix + adj_form, fmt=fmt)
                    else:
                        self.set_cell(dc, dr, raw, fmt=fmt)
        else:
            for sc, sr in src_coords:
                dc = sc + delta_c
                dr = sr + delta_r
                if 0 <= dc < 26 and 0 <= dr < 255:
                    src_cell = self.cells.get((sc, sr))
                    if not src_cell:
                        if (dc, dr) in self.cells: del self.cells[(dc, dr)]
                    else:
                        raw = src_cell.get('raw', '')
                        fmt = src_cell.get('format', 'G')
                        if src_cell.get('formula'):
                            adj_form = self.adjust_formula_refs(src_cell['formula'], delta_c, delta_r)
                            prefix = "=" if raw.startswith("=") else "+"
                            self.set_cell(dc, dr, prefix + adj_form, fmt=fmt)
                        else:
                            self.set_cell(dc, dr, raw, fmt=fmt)

        if self.auto_calc:
            self.recalculate_all()
        self.status_msg = f"Copied {src_spec} to {dst_spec}."
        self.render_screen()

    def move_range(self, src_spec, dst_spec):
        src_coords = self.parse_range(src_spec)
        dst_coord = self.parse_cell_coord(dst_spec)
        if not src_coords or not dst_coord:
            self.status_msg = "Invalid move parameters."
            return

        base_src_c, base_src_r = src_coords[0]
        base_dst_c, base_dst_r = dst_coord
        delta_c = base_dst_c - base_src_c
        delta_r = base_dst_r - base_src_r

        extracted = {}
        for sc, sr in src_coords:
            if (sc, sr) in self.cells:
                extracted[(sc, sr)] = dict(self.cells[(sc, sr)])
                del self.cells[(sc, sr)]

        for (sc, sr), cell_data in extracted.items():
            dc = sc + delta_c
            dr = sr + delta_r
            if 0 <= dc < 26 and 0 <= dr < 255:
                raw = cell_data.get('raw', '')
                fmt = cell_data.get('format', 'G')
                if cell_data.get('formula'):
                    adj_form = self.adjust_formula_refs(cell_data['formula'], delta_c, delta_r)
                    prefix = "=" if raw.startswith("=") else "+"
                    self.set_cell(dc, dr, prefix + adj_form, fmt=fmt)
                else:
                    self.set_cell(dc, dr, raw, fmt=fmt)

        if self.auto_calc:
            self.recalculate_all()
        self.status_msg = f"Moved {src_spec} to {dst_spec}."
        self.render_screen()

    def delete_row(self, at_row):
        new_cells = {}
        for (c, r), cell in self.cells.items():
            if r < at_row:
                new_cells[(c, r)] = cell
            elif r > at_row:
                new_cells[(c, r - 1)] = cell
        self.cells = new_cells
        if self.auto_calc:
            self.recalculate_all()
        self.status_msg = f"Deleted row {at_row + 1}."
        self.render_screen()

    def delete_col(self, at_col):
        new_cells = {}
        for (c, r), cell in self.cells.items():
            if c < at_col:
                new_cells[(c, r)] = cell
            elif c > at_col:
                new_cells[(c - 1, r)] = cell
        self.cells = new_cells
        del self.col_widths[at_col]
        self.col_widths.append(10)
        if self.auto_calc:
            self.recalculate_all()
        self.status_msg = f"Deleted column {self.col_to_name(at_col)}."
        self.render_screen()

    def insert_row(self, at_row):
        new_cells = {}
        for (c, r), cell in self.cells.items():
            if r < at_row:
                new_cells[(c, r)] = cell
            elif r < 254:
                new_cells[(c, r + 1)] = cell
        self.cells = new_cells
        if self.auto_calc:
            self.recalculate_all()
        self.status_msg = f"Inserted blank row at {at_row + 1}."
        self.render_screen()

    def insert_col(self, at_col):
        new_cells = {}
        for (c, r), cell in self.cells.items():
            if c < at_col:
                new_cells[(c, r)] = cell
            elif c < 25:
                new_cells[(c + 1, r)] = cell
        self.cells = new_cells
        self.col_widths.insert(at_col, 10)
        self.col_widths.pop()
        if self.auto_calc:
            self.recalculate_all()
        self.status_msg = f"Inserted blank column at {self.col_to_name(at_col)}."
        self.render_screen()

    def blank_range(self, range_spec):
        coords = self.parse_range(range_spec)
        for coord in coords:
            if coord in self.cells:
                del self.cells[coord]
        if self.auto_calc:
            self.recalculate_all()
        self.status_msg = f"Blanked {range_spec}."
        self.render_screen()

    def save_cal_data(self):
        lines = [
            "; MicroPro CalcStar 1.4 Spreadsheet",
            "; Sinclair ZX Spectrum +3 CP/M Plus"
        ]
        for c in range(26):
            if self.col_widths[c] != 10:
                lines.append(f"/W {self.col_to_name(c)} {self.col_widths[c]}")

        for (c, r), cell in sorted(self.cells.items(), key=lambda item: (item[0][1], item[0][0])):
            c_name = self.col_to_name(c)
            cell_name = f"{c_name}{r+1}"
            raw = cell.get('raw', '')
            fmt = cell.get('format', 'G')
            if not raw:
                continue
            fmt_str = f" /F{fmt}" if fmt != "G" else ""
            lines.append(f"{cell_name}: {raw}{fmt_str}")

        text = "\r\n".join(lines) + "\r\n\x1a"
        return text.encode('ascii')

    def load_cal_data(self, data_bytes):
        text = data_bytes.split(b'\x1a')[0].decode('ascii', errors='replace')
        self.cells.clear()
        self.col_widths = [10] * 26
        for line in text.splitlines():
            line = line.strip()
            if not line or line.startswith(';'):
                continue
            if line.upper().startswith('/W'):
                parts = line.split()
                if len(parts) >= 3:
                    c = self.name_to_col(parts[1])
                    try: self.col_widths[c] = int(parts[2])
                    except: pass
                continue
            if ':' in line:
                cell_ref, rest = line.split(':', 1)
                coord = self.parse_cell_coord(cell_ref)
                if not coord:
                    continue
                rest = rest.strip()
                fmt = "G"
                if " /F" in rest.upper():
                    idx = rest.upper().rfind(" /F")
                    fmt = rest[idx+3:].strip()
                    rest = rest[:idx].strip()
                self.set_cell(coord[0], coord[1], rest, fmt=fmt)
        self.recalculate_all()

    def save_file(self, filename=None):
        fn = (filename or self.filename).upper().strip()
        if not fn.endswith(".CAL") and "." not in fn:
            fn += ".CAL"
        drv, name = self.cpm.parse_filespec(fn)
        if not drv:
            drv = self.logged_drive
        data = self.save_cal_data()
        self.cpm.put_file(drv, name, data, user=self.cpm.current_user)
        self.filename = name
        self.logged_drive = drv
        self.modified = False
        self.status_msg = f"Saved {drv}:{name}"
        self.render_screen()

    def load_file(self, filename):
        fn = filename.upper().strip()
        if not fn.endswith(".CAL") and "." not in fn:
            fn += ".CAL"
        drv, name = self.cpm.parse_filespec(fn)
        if not drv:
            drv = self.logged_drive
        f = self.cpm.get_file(drv, name)
        if not f:
            self.status_msg = f"File {drv}:{name} not found."
            self.render_screen()
            return False
        self.load_cal_data(f['data'])
        self.filename = name
        self.logged_drive = drv
        self.modified = False
        self.status_msg = f"Loaded {drv}:{name}"
        self.render_screen()
        return True

    def print_sheet(self):
        self.status_msg = "Spreadsheet printout generated."
        self.render_screen()

    def render_screen(self):
        if not hasattr(self.cpm, 'screen') or self.cpm.screen is None:
            return

        if self.cursor_row < self.top_row:
            self.top_row = self.cursor_row
        elif self.cursor_row >= self.top_row + 20:
            self.top_row = self.cursor_row - 19

        if self.cursor_col < self.left_col:
            self.left_col = self.cursor_col

        def get_vis_cols(start_col):
            cols = []
            used = 4
            for c in range(start_col, 26):
                w = self.col_widths[c]
                if used + w + 1 <= 51:
                    cols.append(c)
                    used += w + 1
                else:
                    break
            return cols

        vis_cols = get_vis_cols(self.left_col)
        while vis_cols and self.cursor_col > vis_cols[-1] and self.left_col < 25:
            self.left_col += 1
            vis_cols = get_vis_cols(self.left_col)

        # 1. Row 0: Status line (Inverse video)
        cur_cell = self.cells.get((self.cursor_col, self.cursor_row))
        cell_name = f"{self.col_to_name(self.cursor_col)}{self.cursor_row + 1}"
        cell_fmt = self.get_cell_format(self.cursor_col, self.cursor_row)
        if cur_cell and cur_cell.get('formula'):
            form_disp = "=" + cur_cell['formula']
        elif cur_cell and cur_cell.get('raw'):
            form_disp = cur_cell['raw']
        else:
            form_disp = ""
        status_line = f"{self.logged_drive}:{self.filename:<11} {cell_name:<4} FORM={form_disp:<18} ({cell_fmt})"[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 0, status_line[c], inverse=True)

        # 2. Row 1: Column Header
        hdr_parts = [" R# |"]
        col_start_map = {}
        curr_pos = 4
        for c in vis_cols:
            w = self.col_widths[c]
            col_start_map[c] = curr_pos
            c_name = self.col_to_name(c)
            hdr_parts.append(c_name.center(w) + "|")
            curr_pos += w + 1
        hdr_line = "".join(hdr_parts)[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 1, hdr_line[c], inverse=False)

        # 3. Rows 2-21 (20 spreadsheet rows)
        for vr in range(20):
            scr_row = 2 + vr
            sheet_row = self.top_row + vr
            if sheet_row < 255:
                row_prefix = f"{sheet_row + 1:>3} |"
                for c in range(4):
                    self.cpm.screen.draw_char(c, scr_row, row_prefix[c], inverse=False)

                pos = 4
                for c in vis_cols:
                    w = self.col_widths[c]
                    val_str = self.format_cell_value(c, sheet_row, w)
                    is_active = (c == self.cursor_col and sheet_row == self.cursor_row)
                    for i, ch in enumerate(val_str):
                        self.cpm.screen.draw_char(pos + i, scr_row, ch, inverse=is_active)
                    self.cpm.screen.draw_char(pos + w, scr_row, '|', inverse=False)
                    pos += w + 1

                for c in range(pos, 51):
                    self.cpm.screen.draw_char(c, scr_row, ' ', inverse=False)
            else:
                for c in range(51):
                    self.cpm.screen.draw_char(c, scr_row, ' ', inverse=False)

        # 4. Row 22: Separator Line
        calc_str = "AUTO" if self.auto_calc else "MANUAL"
        sep_str = f"CALC: {calc_str:<6} MODE: {self.mode:<5}  /=MENU  ^E^X^S^D=MOVE"[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 22, sep_str[c], inverse=False)

        # 5. Row 23: Prompt / Input Line
        if self.mode == "PROMPT":
            p_str = (self.prompt_text + "".join(self.prompt_buffer))[:51].ljust(51)
            for c in range(51):
                self.cpm.screen.draw_char(c, 23, p_str[c], inverse=False)
            self.cpm.screen.cursor_row = 23
            self.cpm.screen.cursor_col = min(50, len(self.prompt_text) + len(self.prompt_buffer))
            self.cpm.screen.draw_cursor(True)
        elif self.mode == "SLASH":
            menu_str = "/: F(mt) C(py) M(ov) D(el) I(ns) W(dt) B(lk) S(av) L(od) R(ec) Q(ut)"[:51].ljust(51)
            for c in range(51):
                self.cpm.screen.draw_char(c, 23, menu_str[c], inverse=False)
            self.cpm.screen.cursor_row = 23
            self.cpm.screen.cursor_col = 2
            self.cpm.screen.draw_cursor(True)
        elif self.mode == "EDIT":
            entry_str = ("ENTRY: " + "".join(self.input_buffer))[:51].ljust(51)
            for c in range(51):
                self.cpm.screen.draw_char(c, 23, entry_str[c], inverse=False)
            self.cpm.screen.cursor_row = 23
            self.cpm.screen.cursor_col = min(50, 7 + len(self.input_buffer))
            self.cpm.screen.draw_cursor(True)
        else:
            if self.status_msg:
                bot_str = self.status_msg[:51].ljust(51)
            else:
                bot_str = f"CELL {cell_name}: Press '/' for menu or ENTER to edit"[:51].ljust(51)
            for c in range(51):
                self.cpm.screen.draw_char(c, 23, bot_str[c], inverse=False)
            if self.cursor_col in col_start_map:
                scr_row = 2 + (self.cursor_row - self.top_row)
                if 2 <= scr_row <= 21:
                    self.cpm.screen.cursor_row = scr_row
                    self.cpm.screen.cursor_col = col_start_map[self.cursor_col]
                    self.cpm.screen.draw_cursor(True)
                else:
                    self.cpm.screen.draw_cursor(False)
            else:
                self.cpm.screen.draw_cursor(False)

    def ask_prompt(self, prompt_text, callback):
        self.mode = "PROMPT"
        self.prompt_text = prompt_text
        self.prompt_buffer = []
        self.prompt_callback = callback
        self.render_screen()

    # Navigation
    def cursor_up(self):
        if self.cursor_row > 0:
            self.cursor_row -= 1
            self.status_msg = ""
            self.render_screen()

    def cursor_down(self):
        if self.cursor_row < 254:
            self.cursor_row += 1
            self.status_msg = ""
            self.render_screen()

    def cursor_left(self):
        if self.cursor_col > 0:
            self.cursor_col -= 1
            self.status_msg = ""
            self.render_screen()

    def cursor_right(self):
        if self.cursor_col < 25:
            self.cursor_col += 1
            self.status_msg = ""
            self.render_screen()

    def page_up(self):
        self.cursor_row = max(0, self.cursor_row - 20)
        self.top_row = max(0, self.top_row - 20)
        self.status_msg = ""
        self.render_screen()

    def page_down(self):
        self.cursor_row = min(254, self.cursor_row + 20)
        self.top_row = min(235, self.top_row + 20)
        self.status_msg = ""
        self.render_screen()

    def goto_cell(self, cell_spec):
        coord = self.parse_cell_coord(cell_spec)
        if coord:
            self.cursor_col, self.cursor_row = coord
            self.status_msg = f"Jumped to {cell_spec.upper()}"
        else:
            self.status_msg = f"Invalid coordinate: {cell_spec}"
        self.mode = "READY"
        self.render_screen()

    # Interactive event handling
    def handle_event(self, event):
        import pygame
        if self.mode == "PROMPT":
            if event.type == pygame.KEYDOWN:
                if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                    val = "".join(self.prompt_buffer).strip()
                    cb = self.prompt_callback
                    self.mode = "READY"
                    if cb: cb(val)
                    return True
                elif event.key == pygame.K_BACKSPACE:
                    if self.prompt_buffer: self.prompt_buffer.pop()
                    self.render_screen()
                    return True
                elif event.key == pygame.K_ESCAPE:
                    self.mode = "READY"
                    self.status_msg = "Command cancelled."
                    self.render_screen()
                    return True
            elif event.type == pygame.TEXTINPUT:
                for ch in event.text:
                    if ch not in ('\r', '\n') and len(self.prompt_buffer) < 40:
                        self.prompt_buffer.append(ch)
                self.render_screen()
                return True
            return False

        if self.mode == "SLASH":
            if event.type == pygame.KEYDOWN:
                k = event.key
                if k == pygame.K_ESCAPE:
                    self.mode = "READY"
                    self.status_msg = ""
                    self.render_screen()
                    return True
                elif k == pygame.K_f:
                    self.ask_prompt("FORMAT (G, $, I, F0-F4, L, R, C, *): ", self._cmd_fmt_cb)
                    return True
                elif k == pygame.K_c:
                    cur_name = f"{self.col_to_name(self.cursor_col)}{self.cursor_row + 1}"
                    self.ask_prompt(f"COPY FROM [{cur_name}]: ", self._cmd_copy_step1)
                    return True
                elif k == pygame.K_m:
                    cur_name = f"{self.col_to_name(self.cursor_col)}{self.cursor_row + 1}"
                    self.ask_prompt(f"MOVE FROM [{cur_name}]: ", self._cmd_move_step1)
                    return True
                elif k == pygame.K_d:
                    self.ask_prompt("DELETE (R)OW OR (C)OLUMN? ", self._cmd_del_cb)
                    return True
                elif k == pygame.K_i:
                    self.ask_prompt("INSERT (R)OW OR (C)OLUMN? ", self._cmd_ins_cb)
                    return True
                elif k == pygame.K_w:
                    self.ask_prompt("COLUMN WIDTH (4-25)? ", self._cmd_width_cb)
                    return True
                elif k == pygame.K_b:
                    cur_name = f"{self.col_to_name(self.cursor_col)}{self.cursor_row + 1}"
                    self.ask_prompt(f"BLANK CELL/RANGE [{cur_name}]: ", self._cmd_blank_cb)
                    return True
                elif k == pygame.K_s:
                    self.ask_prompt(f"SAVE FILE NAME [{self.filename}]: ", self._cmd_save_cb)
                    return True
                elif k == pygame.K_l:
                    self.ask_prompt("LOAD FILE NAME (.CAL): ", self._cmd_load_cb)
                    return True
                elif k == pygame.K_p:
                    self.print_sheet()
                    self.mode = "READY"
                    return True
                elif k == pygame.K_r:
                    self.recalculate_all()
                    self.status_msg = "Spreadsheet recalculated."
                    self.mode = "READY"
                    self.render_screen()
                    return True
                elif k == pygame.K_a:
                    self.auto_calc = not self.auto_calc
                    self.status_msg = f"Auto-recalculate {'ON' if self.auto_calc else 'OFF'}"
                    self.mode = "READY"
                    self.render_screen()
                    return True
                elif k == pygame.K_g:
                    self.ask_prompt("GOTO CELL? ", self.goto_cell)
                    return True
                elif k in (pygame.K_q, pygame.K_x):
                    self.exit_to_cpm()
                    return True
            return False

        if self.mode == "EDIT":
            if event.type == pygame.KEYDOWN:
                k = event.key
                if k in (pygame.K_RETURN, pygame.K_KP_ENTER):
                    val = "".join(self.input_buffer)
                    self.set_cell(self.cursor_col, self.cursor_row, val)
                    self.input_buffer.clear()
                    self.mode = "READY"
                    self.cursor_down()
                    return True
                elif k == pygame.K_BACKSPACE:
                    if self.input_buffer: self.input_buffer.pop()
                    self.render_screen()
                    return True
                elif k == pygame.K_ESCAPE:
                    self.input_buffer.clear()
                    self.mode = "READY"
                    self.render_screen()
                    return True
            elif event.type == pygame.TEXTINPUT:
                for ch in event.text:
                    if ch not in ('\r', '\n') and len(self.input_buffer) < 45:
                        self.input_buffer.append(ch)
                self.render_screen()
                return True
            return False

        if self.mode == "READY":
            if event.type == pygame.KEYDOWN:
                k = event.key
                mod = getattr(event, "mod", 0)
                is_ctrl = bool(mod & pygame.KMOD_CTRL)

                if is_ctrl:
                    if k == pygame.K_e: self.cursor_up(); return True
                    elif k == pygame.K_x: self.cursor_down(); return True
                    elif k == pygame.K_s: self.cursor_left(); return True
                    elif k == pygame.K_d: self.cursor_right(); return True
                    elif k == pygame.K_a: self.cursor_col = 0; self.render_screen(); return True
                    elif k == pygame.K_f: self.cursor_col = 25; self.render_screen(); return True
                    elif k == pygame.K_r: self.page_up(); return True
                    elif k == pygame.K_c: self.page_down(); return True

                if k == pygame.K_SLASH or (event.type == pygame.TEXTINPUT and '/' in getattr(event, 'text', '')):
                    self.mode = "SLASH"
                    self.render_screen()
                    return True
                elif k in (pygame.K_RETURN, pygame.K_KP_ENTER):
                    cell = self.cells.get((self.cursor_col, self.cursor_row))
                    raw = cell.get('raw', '') if cell else ''
                    self.input_buffer = list(raw)
                    self.mode = "EDIT"
                    self.render_screen()
                    return True
                elif k == pygame.K_UP: self.cursor_up(); return True
                elif k == pygame.K_DOWN: self.cursor_down(); return True
                elif k == pygame.K_LEFT: self.cursor_left(); return True
                elif k == pygame.K_RIGHT: self.cursor_right(); return True
                elif k == pygame.K_HOME: self.cursor_col = 0; self.render_screen(); return True
                elif k == pygame.K_END: self.cursor_col = 25; self.render_screen(); return True
                elif k == pygame.K_PAGEUP: self.page_up(); return True
                elif k == pygame.K_PAGEDOWN: self.page_down(); return True
                elif k in (pygame.K_BACKSPACE, pygame.K_DELETE):
                    self.set_cell(self.cursor_col, self.cursor_row, "")
                    self.render_screen()
                    return True
                elif k == pygame.K_ESCAPE:
                    self.status_msg = ""
                    self.render_screen()
                    return True

            elif event.type == pygame.TEXTINPUT:
                txt = event.text
                if '/' in txt:
                    self.mode = "SLASH"
                    self.render_screen()
                    return True
                for ch in txt:
                    if ch not in ('\r', '\n'):
                        self.input_buffer = [ch]
                        self.mode = "EDIT"
                        self.render_screen()
                        return True

        return False

    def _cmd_fmt_cb(self, fmt_spec):
        fmt = fmt_spec.upper().strip()
        if fmt:
            parts = fmt.split()
            code = parts[0]
            if len(parts) > 1:
                coords = self.parse_range(parts[1])
                for c, r in coords:
                    cell = self.cells.setdefault((c, r), {'raw': '', 'val': 0.0, 'formula': None, 'format': 'G'})
                    cell['format'] = code
            else:
                cell = self.cells.setdefault((self.cursor_col, self.cursor_row), {'raw': '', 'val': 0.0, 'formula': None, 'format': 'G'})
                cell['format'] = code
            self.status_msg = f"Format set to {code}."
        self.render_screen()

    def _cmd_copy_step1(self, src):
        if not src:
            src = f"{self.col_to_name(self.cursor_col)}{self.cursor_row + 1}"
        self._temp_copy_src = src
        self.ask_prompt(f"COPY {src} TO TARGET: ", self._cmd_copy_step2)

    def _cmd_copy_step2(self, dst):
        if dst:
            self.copy_range(self._temp_copy_src, dst)
        else:
            self.mode = "READY"
            self.render_screen()

    def _cmd_move_step1(self, src):
        if not src:
            src = f"{self.col_to_name(self.cursor_col)}{self.cursor_row + 1}"
        self._temp_move_src = src
        self.ask_prompt(f"MOVE {src} TO TARGET: ", self._cmd_move_step2)

    def _cmd_move_step2(self, dst):
        if dst:
            self.move_range(self._temp_move_src, dst)
        else:
            self.mode = "READY"
            self.render_screen()

    def _cmd_del_cb(self, choice):
        ch = choice.upper().strip()
        if ch.startswith('R'):
            self.delete_row(self.cursor_row)
        elif ch.startswith('C'):
            self.delete_col(self.cursor_col)
        else:
            self.status_msg = "Delete cancelled."
            self.mode = "READY"
            self.render_screen()

    def _cmd_ins_cb(self, choice):
        ch = choice.upper().strip()
        if ch.startswith('R'):
            self.insert_row(self.cursor_row)
        elif ch.startswith('C'):
            self.insert_col(self.cursor_col)
        else:
            self.status_msg = "Insert cancelled."
            self.mode = "READY"
            self.render_screen()

    def _cmd_width_cb(self, w_str):
        try:
            w = int(w_str.strip())
            if 4 <= w <= 25:
                self.col_widths[self.cursor_col] = w
                self.status_msg = f"Column {self.col_to_name(self.cursor_col)} width set to {w}."
        except:
            self.status_msg = "Invalid width."
        self.mode = "READY"
        self.render_screen()

    def _cmd_blank_cb(self, rng):
        if not rng:
            rng = f"{self.col_to_name(self.cursor_col)}{self.cursor_row + 1}"
        self.blank_range(rng)
        self.mode = "READY"

    def _cmd_save_cb(self, fn):
        if not fn:
            fn = self.filename
        self.save_file(fn)
        self.mode = "READY"

    def _cmd_load_cb(self, fn):
        if fn:
            self.load_file(fn)
        self.mode = "READY"

    # Headless / Batch execution
    def execute_line(self, line):
        cmd_raw = line.strip()
        if not cmd_raw:
            return

        cmd_u = cmd_raw.upper()
        if cmd_u in ("QUIT", "EXIT", "Q", "X", "/Q", "/X"):
            self.exit_to_cpm()
            return
        elif cmd_u in ("CLS", "NEW"):
            self.reset_sheet()
            return
        elif cmd_u in ("RECALC", "CALC", "/R"):
            self.recalculate_all()
            self.status_msg = "Recalculated."
            self.render_screen()
            return
        elif cmd_u == "/A":
            self.auto_calc = not self.auto_calc
            self.status_msg = f"Auto-calc {'ON' if self.auto_calc else 'OFF'}"
            self.render_screen()
            return
        elif cmd_u == "/P" or cmd_u.startswith("PRINT"):
            self.print_sheet()
            return
        elif cmd_u.startswith("LOAD ") or cmd_u.startswith("CS ") or cmd_u.startswith("CALCSTAR "):
            parts = cmd_raw.split(None, 1)
            if len(parts) >= 2:
                self.load_file(parts[1])
            return
        elif cmd_u.startswith("GOTO ") or cmd_u.startswith("/G "):
            cell_spec = cmd_raw.split(None, 1)[1].strip()
            self.goto_cell(cell_spec)
            return
        elif cmd_u.startswith("/W"):
            parts = cmd_raw.split()
            if len(parts) == 2:
                try: self.col_widths[self.cursor_col] = int(parts[1])
                except: pass
            elif len(parts) >= 3:
                c = self.name_to_col(parts[1])
                try: self.col_widths[c] = int(parts[2])
                except: pass
            self.render_screen()
            return
        elif cmd_u.startswith("/F"):
            parts = cmd_raw.split()
            if len(parts) >= 2:
                fmt_code = parts[1].upper()
                if len(parts) >= 3:
                    coords = self.parse_range(parts[2])
                    for c, r in coords:
                        cell = self.cells.setdefault((c, r), {'raw': '', 'val': 0.0, 'formula': None, 'format': 'G'})
                        cell['format'] = fmt_code
                else:
                    cell = self.cells.setdefault((self.cursor_col, self.cursor_row), {'raw': '', 'val': 0.0, 'formula': None, 'format': 'G'})
                    cell['format'] = fmt_code
            self.render_screen()
            return
        elif cmd_u.startswith("/C"):
            parts = cmd_raw.split()
            if len(parts) >= 3:
                self.copy_range(parts[1], parts[2])
            return
        elif cmd_u.startswith("/M"):
            parts = cmd_raw.split()
            if len(parts) >= 3:
                self.move_range(parts[1], parts[2])
            return
        elif cmd_u.startswith("/D"):
            parts = cmd_raw.split()
            if len(parts) >= 2:
                if parts[1].upper().startswith('R'):
                    self.delete_row(self.cursor_row)
                elif parts[1].upper().startswith('C'):
                    self.delete_col(self.cursor_col)
            return
        elif cmd_u.startswith("/I"):
            parts = cmd_raw.split()
            if len(parts) >= 2:
                if parts[1].upper().startswith('R'):
                    self.insert_row(self.cursor_row)
                elif parts[1].upper().startswith('C'):
                    self.insert_col(self.cursor_col)
            return
        elif cmd_u.startswith("/B"):
            parts = cmd_raw.split()
            rng = parts[1] if len(parts) >= 2 else f"{self.col_to_name(self.cursor_col)}{self.cursor_row + 1}"
            self.blank_range(rng)
            return
        elif cmd_u.startswith("/S"):
            parts = cmd_raw.split()
            fn = parts[1] if len(parts) >= 2 else self.filename
            self.save_file(fn)
            return
        elif cmd_u.startswith("/L"):
            parts = cmd_raw.split()
            if len(parts) >= 2:
                self.load_file(parts[1])
            return

        if cmd_u.startswith("SET "):
            cmd_raw = cmd_raw[4:].strip()

        if ':' in cmd_raw:
            cell_ref, rest = cmd_raw.split(':', 1)
            coord = self.parse_cell_coord(cell_ref)
            if coord:
                rest = rest.strip()
                fmt = "G"
                if " /F" in rest.upper():
                    idx = rest.upper().rfind(" /F")
                    fmt = rest[idx+3:].strip()
                    rest = rest[:idx].strip()
                self.set_cell(coord[0], coord[1], rest, fmt=fmt)
                self.render_screen()
                return

        if '=' in cmd_raw:
            parts = cmd_raw.split('=', 1)
            target = parts[0].strip()
            coord = self.parse_cell_coord(target)
            if coord:
                val_expr = parts[1].strip()
                self.set_cell(coord[0], coord[1], val_expr)
                self.render_screen()
                return

        coord = self.parse_cell_coord(cmd_raw)
        if coord:
            self.cursor_col, self.cursor_row = coord
            self.render_screen()
            return

        self.set_cell(self.cursor_col, self.cursor_row, cmd_raw)
        self.cursor_down()
        self.render_screen()


class DataStarField:
    """Represents a visual form field specification in MicroPro DataStar."""
    def __init__(self, name, label, ftype='A', length=15, row=2, col=15, is_key=False, required=False, formula="", default=""):
        self.name = name.upper().strip()
        self.label = label.strip()
        self.type = ftype.upper().strip() # 'A' (Alphanumeric), 'N' (Numeric), '$' (Currency), 'C' (Calculated)
        self.length = int(length)
        self.row = int(row)
        self.col = int(col)
        self.is_key = bool(is_key)
        self.required = bool(required)
        self.formula = formula.strip()
        self.default = default.strip()


class DataStar:
    """
    MicroPro DataStar Compatible Database Management & Visual Forms System for CP/M.
    Authentic 51x24 CRT display database featuring:
    - Screen form designer & data entry system.
    - Field attributes: Alphanumeric, Numeric, Currency, Calculated, Primary Key, Required.
    - Real-time calculated field evaluation (e.g. AVAIL = LIMIT - BALANCE).
    - Form view, Tabular List / Browse view, and Opening Menu.
    - Record CRUD operations: Add, Update, Delete, Primary Key Seek, Full-text Search.
    - WordStar Diamond cursor navigation (^E, ^X, ^S, ^D, ^A, ^F, ^R, ^C, ^B write record).
    - Standard CP/M ASCII .DTA record storage with \\r\\n and 0x1A EOF, CSV interoperability.
    """
    def __init__(self, cpm_system):
        self.cpm = cpm_system
        self.active = False
        self.mode = "FORM"          # "FORM", "LIST", "MENU", "EDIT_FIELD", "PROMPT"
        self.filename = "CONTACTS.DTA"
        self.logged_drive = 'A'
        self.fields = []
        self.records = []
        self.current_rec = 0
        self.active_field_idx = 0
        self.edit_buffer = []
        self.prompt_text = ""
        self.prompt_buffer = []
        self.prompt_callback = None
        self.status_msg = ""
        self.modified = False
        self.list_top_rec = 0
        self.is_new_record = False
        self._temp_new_rec = {}
        self.init_default_schema()

    def init_default_schema(self):
        self.fields = [
            DataStarField("ACC_ID", "Account ID", ftype='A', length=6, row=3, col=16, is_key=True, required=True),
            DataStarField("STATUS", "Status", ftype='A', length=8, row=3, col=36, default="ACTIVE"),
            DataStarField("COMPANY", "Company", ftype='A', length=26, row=5, col=16, required=True),
            DataStarField("CONTACT", "Contact", ftype='A', length=22, row=7, col=16),
            DataStarField("PHONE", "Telephone", ftype='A', length=15, row=9, col=16),
            DataStarField("CITY", "City/Region", ftype='A', length=18, row=11, col=16),
            DataStarField("LIMIT", "Credit Limit", ftype='$', length=10, row=14, col=16),
            DataStarField("BALANCE", "Current Balance", ftype='$', length=10, row=16, col=16),
            DataStarField("AVAIL", "Credit Avail", ftype='C', length=10, row=18, col=16, formula="LIMIT - BALANCE"),
        ]

    def start(self, args=""):
        self.active = True
        self.cpm.active_app = "DATASTAR"
        self.logged_drive = self.cpm.current_drive
        arg = args.strip()
        if arg:
            drv, fn = self.cpm.parse_filespec(arg)
            self.logged_drive = drv
            if not fn.upper().endswith(".DTA") and "." not in fn:
                fn += ".DTA"
            self.filename = fn
            self.load_file(fn)
        else:
            # Check if default CONTACTS.DTA exists
            if not self.records:
                f = self.cpm.get_file(self.logged_drive, "CONTACTS.DTA")
                if f:
                    self.filename = "CONTACTS.DTA"
                    self.load_dta_data(f['data'])
            self.mode = "FORM"
            self.status_msg = "DataStar v1.4 Ready - Press '^K' for Menu"
            self.render_screen()

    def exit_to_cpm(self):
        self.active = False
        self.cpm.active_app = None
        self.cpm.screen.cls()
        self.cpm.screen.puts(f"\r\n{self.cpm.current_drive}>")
        self.cpm.screen.draw_cursor(True)

    def eval_calculated_fields(self, rec_dict):
        for f in self.fields:
            if f.type == 'C' and f.formula:
                expr = f.formula
                for ref_f in self.fields:
                    if ref_f.name in expr:
                        raw_val = rec_dict.get(ref_f.name, 0.0)
                        try:
                            num = float(str(raw_val).replace('$', '').replace(',', '').strip())
                        except ValueError:
                            num = 0.0
                        expr = re.sub(rf'\b{ref_f.name}\b', str(num), expr)
                try:
                    tokens = re.findall(r'[\d\.]+|[+\-*/()]', expr)
                    safe_expr = " ".join(tokens)
                    # Validate AST contains only numbers and basic arithmetic
                    tree = ast.parse(safe_expr, mode='eval')
                    for node in ast.walk(tree):
                        if not isinstance(node, (ast.Expression, ast.BinOp, ast.UnaryOp,
                                                 ast.Add, ast.Sub, ast.Mult, ast.Div,
                                                 ast.Pow, ast.USub, ast.UAdd,
                                                 ast.Constant)):
                            raise ValueError(f"Disallowed node in calc field: {type(node).__name__}")
                    code_obj = compile(tree, '<datastar_calc>', 'eval')
                    val = float(eval(code_obj, {"__builtins__": {}}, {}))
                    rec_dict[f.name] = val
                except Exception:
                    rec_dict[f.name] = 0.0

    def add_record(self, values_dict):
        rec = {}
        for f in self.fields:
            v = values_dict.get(f.name, f.default)
            if f.type in ('N', '$'):
                try:
                    v = float(str(v).replace('$', '').replace(',', '').strip())
                except ValueError:
                    v = 0.0
            rec[f.name] = v
        self.eval_calculated_fields(rec)
        self.records.append(rec)
        self.current_rec = len(self.records) - 1
        self.modified = True
        return self.current_rec

    def update_current_record(self, field_name, value):
        if not self.records or not (0 <= self.current_rec < len(self.records)):
            return False
        fn = field_name.upper().strip()
        f = next((x for x in self.fields if x.name == fn), None)
        if not f or f.type == 'C':
            return False
        if f.type in ('N', '$'):
            try:
                value = float(str(value).replace('$', '').replace(',', '').strip())
            except ValueError:
                value = 0.0
        self.records[self.current_rec][fn] = value
        self.eval_calculated_fields(self.records[self.current_rec])
        self.modified = True
        return True

    def delete_current_record(self):
        if not self.records or not (0 <= self.current_rec < len(self.records)):
            return False
        del self.records[self.current_rec]
        if self.current_rec >= len(self.records):
            self.current_rec = max(0, len(self.records) - 1)
        self.modified = True
        self.status_msg = "Record deleted."
        self.render_screen()
        return True

    def seek_key(self, key_str):
        key_str = str(key_str).upper().strip()
        key_f = next((f for f in self.fields if f.is_key), self.fields[0])
        for idx, rec in enumerate(self.records):
            val = str(rec.get(key_f.name, '')).upper().strip()
            if val == key_str or val.startswith(key_str):
                self.current_rec = idx
                self.status_msg = f"Found key {key_str} at record {idx + 1}."
                self.mode = "FORM"
                self.render_screen()
                return idx
        self.status_msg = f"Key {key_str} not found."
        self.render_screen()
        return -1

    def find_text(self, text):
        text = str(text).upper().strip()
        start = (self.current_rec + 1) if self.records else 0
        for idx in range(start, len(self.records)):
            for f in self.fields:
                if text in str(self.records[idx].get(f.name, '')).upper():
                    self.current_rec = idx
                    self.status_msg = f"Found '{text}' at record {idx + 1}."
                    self.mode = "FORM"
                    self.render_screen()
                    return idx
        # Wrap around
        for idx in range(0, min(start, len(self.records))):
            for f in self.fields:
                if text in str(self.records[idx].get(f.name, '')).upper():
                    self.current_rec = idx
                    self.status_msg = f"Found '{text}' at record {idx + 1} (wrapped)."
                    self.mode = "FORM"
                    self.render_screen()
                    return idx
        self.status_msg = f"Text '{text}' not found."
        self.render_screen()
        return -1

    def first_record(self):
        if self.records:
            self.current_rec = 0
            self.status_msg = "First record."
            self.render_screen()

    def last_record(self):
        if self.records:
            self.current_rec = len(self.records) - 1
            self.status_msg = "Last record."
            self.render_screen()

    def next_record(self):
        if self.records and self.current_rec < len(self.records) - 1:
            self.current_rec += 1
            self.status_msg = ""
            self.render_screen()
        else:
            self.status_msg = "At end of file."
            self.render_screen()

    def prev_record(self):
        if self.records and self.current_rec > 0:
            self.current_rec -= 1
            self.status_msg = ""
            self.render_screen()
        else:
            self.status_msg = "At top of file."
            self.render_screen()

    def goto_record(self, num):
        try:
            idx = int(num) - 1
            if 0 <= idx < len(self.records):
                self.current_rec = idx
                self.status_msg = f"Record {idx + 1}."
                self.mode = "FORM"
                self.render_screen()
                return True
        except ValueError:
            pass
        self.status_msg = "Invalid record number."
        self.render_screen()
        return False

    def format_field_val(self, f, val):
        if val is None:
            return ""
        if f.type == '$':
            try:
                num = float(val)
                if num < 0: return f"-${abs(num):,.2f}"
                return f"${num:,.2f}"
            except Exception:
                return str(val)
        elif f.type == 'N':
            try:
                num = float(val)
                return f"{int(num)}" if num == int(num) else f"{num:.2f}"
            except Exception:
                return str(val)
        elif f.type == 'C':
            try:
                num = float(val)
                return f"${num:,.2f}"
            except Exception:
                return str(val)
        return str(val)

    def save_dta_data(self):
        lines = [
            "; MicroPro DataStar 1.4 Database",
            "; Sinclair ZX Spectrum +3 CP/M Plus",
            "SCHEMA:"
        ]
        for f in self.fields:
            parts = [f"FIELD: {f.name}", f'label="{f.label}"', f"type={f.type}", f"len={f.length}", f"row={f.row}", f"col={f.col}"]
            if f.is_key: parts.append("key=1")
            if f.required: parts.append("req=1")
            if f.default: parts.append(f'def="{f.default}"')
            if f.formula: parts.append(f'form="{f.formula}"')
            lines.append(", ".join(parts))

        lines.append("DATA:")
        for rec in self.records:
            vals = []
            for f in self.fields:
                v = rec.get(f.name, '')
                if isinstance(v, (int, float)):
                    vals.append(str(v))
                else:
                    vals.append(f'"{v}"')
            lines.append(",".join(vals))

        text = "\r\n".join(lines) + "\r\n\x1a"
        return text.encode('ascii')

    def load_dta_data(self, data_bytes):
        text = data_bytes.split(b'\x1a')[0].decode('ascii', errors='replace')
        in_schema = False
        in_data = False
        loaded_fields = []
        loaded_records = []

        for line in text.splitlines():
            line = line.strip()
            if not line or line.startswith(';'):
                continue
            if line == "SCHEMA:":
                in_schema = True
                in_data = False
                continue
            elif line == "DATA:":
                in_schema = False
                in_data = True
                continue

            if in_schema and line.startswith("FIELD:"):
                m_name = re.search(r'FIELD:\s*([A-Za-z0-9_]+)', line)
                m_lbl = re.search(r'label="([^"]*)"', line)
                m_type = re.search(r'type=([A-Za-z$])', line)
                m_len = re.search(r'len=(\d+)', line)
                m_row = re.search(r'row=(\d+)', line)
                m_col = re.search(r'col=(\d+)', line)
                m_key = "key=1" in line
                m_req = "req=1" in line
                m_def = re.search(r'def="([^"]*)"', line)
                m_form = re.search(r'form="([^"]*)"', line)

                name = m_name.group(1) if m_name else "F1"
                lbl = m_lbl.group(1) if m_lbl else name
                ftype = m_type.group(1) if m_type else "A"
                flen = int(m_len.group(1)) if m_len else 15
                frow = int(m_row.group(1)) if m_row else 2
                fcol = int(m_col.group(1)) if m_col else 15
                fdef = m_def.group(1) if m_def else ""
                fform = m_form.group(1) if m_form else ""

                f = DataStarField(name, lbl, ftype=ftype, length=flen, row=frow, col=fcol,
                                  is_key=m_key, required=m_req, formula=fform, default=fdef)
                loaded_fields.append(f)

            elif in_data:
                tokens = []
                for m in re.finditer(r'"([^"]*)"|([^,]+)', line):
                    tokens.append(m.group(1) if m.group(1) is not None else m.group(2).strip())
                if tokens:
                    rec = {}
                    cur_fields = loaded_fields if loaded_fields else self.fields
                    for i, f in enumerate(cur_fields):
                        if i < len(tokens):
                            val = tokens[i]
                            if f.type in ('N', '$'):
                                try: val = float(val)
                                except Exception: pass
                            rec[f.name] = val
                        else:
                            rec[f.name] = f.default
                    self.eval_calculated_fields(rec)
                    loaded_records.append(rec)

        if loaded_fields:
            self.fields = loaded_fields
        self.records = loaded_records
        self.current_rec = 0

    def save_file(self, filename=None):
        fn = (filename or self.filename).upper().strip()
        if not fn.endswith(".DTA") and "." not in fn:
            fn += ".DTA"
        drv, name = self.cpm.parse_filespec(fn)
        if not drv:
            drv = self.logged_drive
        data = self.save_dta_data()
        self.cpm.put_file(drv, name, data, user=self.cpm.current_user)
        self.filename = name
        self.logged_drive = drv
        self.modified = False
        self.status_msg = f"Saved {drv}:{name}"
        self.render_screen()

    def load_file(self, filename):
        fn = filename.upper().strip()
        if not fn.endswith(".DTA") and "." not in fn:
            fn += ".DTA"
        drv, name = self.cpm.parse_filespec(fn)
        if not drv:
            drv = self.logged_drive
        f = self.cpm.get_file(drv, name)
        if not f:
            self.status_msg = f"File {drv}:{name} not found."
            self.render_screen()
            return False
        self.load_dta_data(f['data'])
        self.filename = name
        self.logged_drive = drv
        self.modified = False
        self.status_msg = f"Loaded {drv}:{name} ({len(self.records)} records)"
        self.mode = "FORM"
        self.render_screen()
        return True

    def export_csv(self, filename):
        fn = filename.upper().strip()
        if not fn.endswith(".CSV") and "." not in fn:
            fn += ".CSV"
        drv, name = self.cpm.parse_filespec(fn)
        if not drv:
            drv = self.logged_drive
        lines = []
        lines.append(",".join([f.name for f in self.fields]))
        for rec in self.records:
            vals = []
            for f in self.fields:
                v = rec.get(f.name, '')
                if isinstance(v, (int, float)): vals.append(str(v))
                else: vals.append(f'"{v}"')
            lines.append(",".join(vals))
        text = "\r\n".join(lines) + "\r\n\x1a"
        self.cpm.put_file(drv, name, text.encode('ascii'), user=self.cpm.current_user)
        self.status_msg = f"Exported {drv}:{name}"
        self.render_screen()

    def import_csv(self, filename):
        fn = filename.upper().strip()
        if not fn.endswith(".CSV") and "." not in fn:
            fn += ".CSV"
        drv, name = self.cpm.parse_filespec(fn)
        if not drv:
            drv = self.logged_drive
        f = self.cpm.get_file(drv, name)
        if not f:
            self.status_msg = f"CSV file {drv}:{name} not found."
            self.render_screen()
            return False
        text = f['data'].split(b'\x1a')[0].decode('ascii', errors='replace')
        lines = text.splitlines()
        if not lines:
            return False
        hdr = [x.strip().strip('"') for x in lines[0].split(',')]
        new_records = []
        for line in lines[1:]:
            tokens = []
            for m in re.finditer(r'"([^"]*)"|([^,]+)', line):
                tokens.append(m.group(1) if m.group(1) is not None else m.group(2).strip())
            if tokens:
                rec = {}
                for i, h in enumerate(hdr):
                    if i < len(tokens):
                        rec[h.upper()] = tokens[i]
                self.eval_calculated_fields(rec)
                new_records.append(rec)
        self.records.extend(new_records)
        self.status_msg = f"Imported {len(new_records)} records from {name}."
        self.render_screen()
        return True

    def ask_prompt(self, prompt_text, callback):
        self.mode = "PROMPT"
        self.prompt_text = prompt_text
        self.prompt_buffer = []
        self.prompt_callback = callback
        self.render_screen()

    # Visual rendering
    def render_screen(self):
        if not hasattr(self.cpm, 'screen') or self.cpm.screen is None:
            return
        if self.mode == "MENU":
            self.render_menu()
        elif self.mode == "LIST":
            self.render_list()
        else:
            self.render_form()

    def render_form(self):
        # 1. Row 0: Status Line (Inverse Video)
        key_val = ""
        total_recs = len(self.records)
        cur_num = (self.current_rec + 1) if (total_recs and not self.is_new_record) else (total_recs + 1 if self.is_new_record else 0)
        mode_disp = "ADD" if self.is_new_record else ("EDIT" if self.mode == "EDIT_FIELD" else "FORM")
        if self.records and not self.is_new_record and 0 <= self.current_rec < len(self.records):
            key_f = next((f for f in self.fields if f.is_key), None)
            if key_f:
                key_val = str(self.records[self.current_rec].get(key_f.name, ''))
        status_line = f"{self.logged_drive}:{self.filename:<11} REC:{cur_num:>3}/{total_recs:<3} MODE: {mode_disp:<5} KEY: {key_val:<8}"[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 0, status_line[c], inverse=True)

        # 2. Row 1: Banner Header
        hdr = "<<< MICROPRO DATASTAR - RECORD MAINTENANCE >>>".center(51)[:51]
        for c in range(51):
            self.cpm.screen.draw_char(c, 1, hdr[c], inverse=False)

        # 3. Rows 2..21: Clear form canvas
        for r in range(2, 22):
            for c in range(51):
                self.cpm.screen.draw_char(c, r, ' ', inverse=False)

        # Active record dictionary
        rec_data = self._temp_new_rec if self.is_new_record else (self.records[self.current_rec] if (self.records and 0 <= self.current_rec < len(self.records)) else {})

        # Draw each field
        for idx, f in enumerate(self.fields):
            lbl_str = f"{f.label}:"
            lbl_col = max(1, f.col - len(lbl_str) - 1)
            for i, ch in enumerate(lbl_str):
                if lbl_col + i < 51:
                    self.cpm.screen.draw_char(lbl_col + i, f.row, ch, inverse=False)

            # Draw brackets and field content
            if f.col - 1 < 51:
                self.cpm.screen.draw_char(f.col - 1, f.row, '[', inverse=False)

            val = rec_data.get(f.name, '')
            fmt_val = self.format_field_val(f, val)
            if idx == self.active_field_idx and self.mode == "EDIT_FIELD":
                fmt_val = "".join(self.edit_buffer)

            val_str = fmt_val[:f.length].ljust(f.length)
            is_active_field = (idx == self.active_field_idx)

            for i, ch in enumerate(val_str):
                if f.col + i < 50:
                    self.cpm.screen.draw_char(f.col + i, f.row, ch, inverse=is_active_field)

            br_col = f.col + f.length
            if br_col < 51:
                self.cpm.screen.draw_char(br_col, f.row, ']', inverse=False)

            if f.type == 'C' and br_col + 7 < 51:
                calc_lbl = "(CALC)"
                for i, ch in enumerate(calc_lbl):
                    self.cpm.screen.draw_char(br_col + 2 + i, f.row, ch, inverse=False)

        # 4. Row 22: Control Help Bar
        help_bar = "^E^X=FIELD  ENTER=NEXT  ^B=WRITE  ^K=MENU  ESC=EXIT"[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 22, help_bar[c], inverse=False)

        # 5. Row 23: Prompt / Input Bar
        if self.mode == "PROMPT":
            p_str = (self.prompt_text + "".join(self.prompt_buffer))[:51].ljust(51)
            for c in range(51):
                self.cpm.screen.draw_char(c, 23, p_str[c], inverse=False)
            self.cpm.screen.cursor_row = 23
            self.cpm.screen.cursor_col = min(50, len(self.prompt_text) + len(self.prompt_buffer))
            self.cpm.screen.draw_cursor(True)
        elif self.mode == "EDIT_FIELD":
            cur_f = self.fields[self.active_field_idx]
            prefix = f"EDIT {cur_f.name}: "
            e_str = (prefix + "".join(self.edit_buffer))[:51].ljust(51)
            for c in range(51):
                self.cpm.screen.draw_char(c, 23, e_str[c], inverse=False)
            self.cpm.screen.cursor_row = 23
            self.cpm.screen.cursor_col = min(50, len(prefix) + len(self.edit_buffer))
            self.cpm.screen.draw_cursor(True)
        else:
            bot = self.status_msg if self.status_msg else "Command? (A)dd (S)earch (U)pdate (D)el (L)ist (Q)uit: "
            bot_str = bot[:51].ljust(51)
            for c in range(51):
                self.cpm.screen.draw_char(c, 23, bot_str[c], inverse=False)
            # Place cursor on active field
            cur_f = self.fields[self.active_field_idx]
            self.cpm.screen.cursor_row = cur_f.row
            self.cpm.screen.cursor_col = cur_f.col
            self.cpm.screen.draw_cursor(True)

    def render_list(self):
        # 1. Row 0: Status Line
        total_recs = len(self.records)
        cur_num = (self.current_rec + 1) if total_recs else 0
        status_line = f"{self.logged_drive}:{self.filename:<11} REC:{cur_num:>3}/{total_recs:<3} MODE: LIST      "[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 0, status_line[c], inverse=True)

        # 2. Row 1: Header Line
        hdr = " REC  ID     COMPANY                  CITY        BAL"[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 1, hdr[c], inverse=False)

        # 3. Rows 2..21: Tabular records
        for i in range(20):
            scr_row = 2 + i
            rec_idx = self.list_top_rec + i
            if rec_idx < len(self.records):
                rec = self.records[rec_idx]
                r_id = str(rec.get('ACC_ID', ''))[:6]
                r_co = str(rec.get('COMPANY', ''))[:24]
                r_ci = str(rec.get('CITY', ''))[:10]
                try:
                    r_bal = float(rec.get('BALANCE', 0.0))
                    bal_str = f"{r_bal:>9.2f}"
                except Exception:
                    bal_str = str(rec.get('BALANCE', ''))[:9].rjust(9)

                line_str = f" {rec_idx+1:>3}  {r_id:<6} {r_co:<24} {r_ci:<10} {bal_str}"[:51].ljust(51)
                is_active = (rec_idx == self.current_rec)
                for c in range(51):
                    self.cpm.screen.draw_char(c, scr_row, line_str[c], inverse=is_active)
            else:
                for c in range(51):
                    self.cpm.screen.draw_char(c, scr_row, ' ', inverse=False)

        # 4. Row 22: Help Bar
        help_bar = "^E^X=MOVE  ENTER=VIEW  PGUP/DN=PAGE  ^K=MENU  ESC=FORM"[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 22, help_bar[c], inverse=False)

        # 5. Row 23: Status / Prompt
        bot = self.status_msg if self.status_msg else "Select record or (A)dd (S)earch (Q)uit: "
        bot_str = bot[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 23, bot_str[c], inverse=False)
        self.cpm.screen.cursor_row = 2 + (self.current_rec - self.list_top_rec)
        self.cpm.screen.cursor_col = 1
        self.cpm.screen.draw_cursor(True)

    def render_menu(self):
        # Row 0: Status Line
        total_recs = len(self.records)
        cur_num = (self.current_rec + 1) if total_recs else 0
        status_line = f"{self.logged_drive}:{self.filename:<11} REC:{cur_num:>3}/{total_recs:<3} MODE: MENU      "[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 0, status_line[c], inverse=True)

        menu_lines = [
            "<<<        M I C R O P R O   D A T A S T A R        >>>".center(51),
            "- - - - - - - - - - - - - - - - - - - - - - - - - -",
            " A  Add new records to database",
            " S  Search / scan records by key or text",
            " U  Update / edit current record",
            " D  Delete current record",
            " L  List / browse records in table view",
            " N  Next record           P  Previous record",
            " F  First record          E  Last record",
            " O  Open database file    C  Clear / New database",
            " X  Exit to CP/M system",
            "- - - - - - - - - - - - - - - - - - - - - - - - - -",
            f" Database: {self.logged_drive}:{self.filename}",
            f" Total Records: {len(self.records)}   Active Record: {cur_num}",
            " Key Field: ACC_ID (Account ID)",
            " " * 51,
            " " * 51,
            " " * 51,
            " " * 51,
            " " * 51,
            " " * 51,
        ]
        for r in range(1, 22):
            l_str = menu_lines[r - 1] if r - 1 < len(menu_lines) else (" " * 51)
            l_str = l_str[:51].ljust(51)
            for c in range(51):
                self.cpm.screen.draw_char(c, r, l_str[c], inverse=False)

        # Row 22
        help_bar = "Select option key or ESC to return to form view"[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 22, help_bar[c], inverse=False)

        # Row 23
        bot = self.status_msg if self.status_msg else "Command? (A, S, U, D, L, N, P, F, E, O, X): "
        bot_str = bot[:51].ljust(51)
        for c in range(51):
            self.cpm.screen.draw_char(c, 23, bot_str[c], inverse=False)
        self.cpm.screen.cursor_row = 23
        self.cpm.screen.cursor_col = min(50, len(bot))
        self.cpm.screen.draw_cursor(True)

    # Interactive event handling
    def handle_event(self, event):
        import pygame
        if self.mode == "PROMPT":
            if event.type == pygame.KEYDOWN:
                if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                    val = "".join(self.prompt_buffer).strip()
                    cb = self.prompt_callback
                    self.mode = "FORM"
                    if cb: cb(val)
                    return True
                elif event.key == pygame.K_BACKSPACE:
                    if self.prompt_buffer: self.prompt_buffer.pop()
                    self.render_screen()
                    return True
                elif event.key == pygame.K_ESCAPE:
                    self.mode = "FORM"
                    self.status_msg = "Command cancelled."
                    self.render_screen()
                    return True
            elif event.type == pygame.TEXTINPUT:
                for ch in event.text:
                    if ch not in ('\r', '\n') and len(self.prompt_buffer) < 40:
                        self.prompt_buffer.append(ch)
                self.render_screen()
                return True
            return False

        if self.mode == "EDIT_FIELD":
            if event.type == pygame.KEYDOWN:
                k = event.key
                mod = getattr(event, "mod", 0)
                is_ctrl = bool(mod & pygame.KMOD_CTRL)

                if is_ctrl and k == pygame.K_b:
                    # Write record
                    self._commit_edit_buffer()
                    self._save_record_edit()
                    return True
                elif is_ctrl and k == pygame.K_y:
                    self.edit_buffer.clear()
                    self.render_screen()
                    return True
                elif is_ctrl and k == pygame.K_g:
                    if self.edit_buffer: self.edit_buffer.pop()
                    self.render_screen()
                    return True

                if k in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_TAB, pygame.K_DOWN):
                    self._commit_edit_buffer()
                    self._advance_field(1)
                    return True
                elif k == pygame.K_UP:
                    self._commit_edit_buffer()
                    self._advance_field(-1)
                    return True
                elif k == pygame.K_BACKSPACE:
                    if self.edit_buffer: self.edit_buffer.pop()
                    self.render_screen()
                    return True
                elif k == pygame.K_ESCAPE:
                    self.mode = "FORM"
                    self.is_new_record = False
                    self.render_screen()
                    return True
            elif event.type == pygame.TEXTINPUT:
                cur_f = self.fields[self.active_field_idx]
                for ch in event.text:
                    if ch not in ('\r', '\n') and len(self.edit_buffer) < cur_f.length:
                        self.edit_buffer.append(ch)
                self.render_screen()
                return True
            return False

        if self.mode == "LIST":
            if event.type == pygame.KEYDOWN:
                k = event.key
                mod = getattr(event, "mod", 0)
                is_ctrl = bool(mod & pygame.KMOD_CTRL)
                if is_ctrl:
                    if k == pygame.K_e: self.prev_record(); self._adjust_list_view(); return True
                    elif k == pygame.K_x: self.next_record(); self._adjust_list_view(); return True
                    elif k == pygame.K_r: self._list_page(-20); return True
                    elif k == pygame.K_c: self._list_page(20); return True
                    elif k == pygame.K_k: self.mode = "MENU"; self.render_screen(); return True
                    elif k == pygame.K_q: self.exit_to_cpm(); return True

                if k == pygame.K_UP: self.prev_record(); self._adjust_list_view(); return True
                elif k == pygame.K_DOWN: self.next_record(); self._adjust_list_view(); return True
                elif k == pygame.K_PAGEUP: self._list_page(-20); return True
                elif k == pygame.K_PAGEDOWN: self._list_page(20); return True
                elif k in (pygame.K_RETURN, pygame.K_KP_ENTER):
                    self.mode = "FORM"
                    self.render_screen()
                    return True
                elif k == pygame.K_ESCAPE:
                    self.mode = "FORM"
                    self.render_screen()
                    return True
                elif k == pygame.K_a: self._start_add_record(); return True
                elif k == pygame.K_s: self.ask_prompt("SEARCH TEXT? ", self.find_text); return True
                elif k in (pygame.K_q, pygame.K_x): self.exit_to_cpm(); return True
            return False

        if self.mode == "MENU":
            if event.type == pygame.KEYDOWN:
                k = event.key
                if k == pygame.K_a: self._start_add_record(); return True
                elif k == pygame.K_s: self.ask_prompt("SEARCH TEXT? ", self.find_text); return True
                elif k == pygame.K_u: self._start_update_record(); return True
                elif k == pygame.K_d: self.delete_current_record(); return True
                elif k == pygame.K_l: self.mode = "LIST"; self.render_screen(); return True
                elif k == pygame.K_n: self.next_record(); return True
                elif k == pygame.K_p: self.prev_record(); return True
                elif k == pygame.K_f: self.first_record(); return True
                elif k == pygame.K_e: self.last_record(); return True
                elif k == pygame.K_o: self.ask_prompt("OPEN DATABASE (.DTA)? ", self.load_file); return True
                elif k == pygame.K_c: self.records.clear(); self.current_rec = 0; self.mode = "FORM"; self.render_screen(); return True
                elif k in (pygame.K_x, pygame.K_q): self.exit_to_cpm(); return True
                elif k == pygame.K_ESCAPE: self.mode = "FORM"; self.render_screen(); return True
            return False

        if self.mode == "FORM":
            if event.type == pygame.KEYDOWN:
                k = event.key
                mod = getattr(event, "mod", 0)
                is_ctrl = bool(mod & pygame.KMOD_CTRL)

                if is_ctrl:
                    if k == pygame.K_e: self._move_field(-1); return True
                    elif k == pygame.K_x: self._move_field(1); return True
                    elif k == pygame.K_r: self.prev_record(); return True
                    elif k == pygame.K_c: self.next_record(); return True
                    elif k == pygame.K_k: self.mode = "MENU"; self.render_screen(); return True
                    elif k == pygame.K_q: self.exit_to_cpm(); return True

                if k == pygame.K_UP: self._move_field(-1); return True
                elif k in (pygame.K_DOWN, pygame.K_TAB): self._move_field(1); return True
                elif k in (pygame.K_RETURN, pygame.K_KP_ENTER):
                    self._start_field_edit()
                    return True
                elif k == pygame.K_a: self._start_add_record(); return True
                elif k == pygame.K_s: self.ask_prompt("SEARCH TEXT? ", self.find_text); return True
                elif k == pygame.K_u: self._start_update_record(); return True
                elif k == pygame.K_d: self.delete_current_record(); return True
                elif k == pygame.K_l: self.mode = "LIST"; self.render_screen(); return True
                elif k == pygame.K_n or k == pygame.K_PAGEDOWN: self.next_record(); return True
                elif k == pygame.K_p or k == pygame.K_PAGEUP: self.prev_record(); return True
                elif k == pygame.K_f or k == pygame.K_HOME: self.first_record(); return True
                elif k == pygame.K_e or k == pygame.K_END: self.last_record(); return True
                elif k == pygame.K_ESCAPE: self.mode = "MENU"; self.render_screen(); return True
                elif k in (pygame.K_x, pygame.K_q): self.exit_to_cpm(); return True

            elif event.type == pygame.TEXTINPUT:
                txt = event.text.upper()
                if 'A' in txt: self._start_add_record(); return True
                elif 'S' in txt: self.ask_prompt("SEARCH TEXT? ", self.find_text); return True
                elif 'U' in txt: self._start_update_record(); return True
                elif 'D' in txt: self.delete_current_record(); return True
                elif 'L' in txt: self.mode = "LIST"; self.render_screen(); return True
                elif 'N' in txt: self.next_record(); return True
                elif 'P' in txt: self.prev_record(); return True
                elif 'F' in txt: self.first_record(); return True
                elif 'E' in txt: self.last_record(); return True
                elif 'X' in txt or 'Q' in txt: self.exit_to_cpm(); return True

        return False

    def _adjust_list_view(self):
        if self.current_rec < self.list_top_rec:
            self.list_top_rec = self.current_rec
        elif self.current_rec >= self.list_top_rec + 20:
            self.list_top_rec = self.current_rec - 19
        self.render_screen()

    def _list_page(self, delta):
        if not self.records:
            return
        self.current_rec = max(0, min(len(self.records) - 1, self.current_rec + delta))
        self._adjust_list_view()

    def _move_field(self, direction):
        n = len(self.fields)
        idx = (self.active_field_idx + direction) % n
        while self.fields[idx].type == 'C':
            idx = (idx + direction) % n
            if idx == self.active_field_idx:
                break
        self.active_field_idx = idx
        self.render_screen()

    def _start_add_record(self):
        self.is_new_record = True
        self._temp_new_rec = {f.name: f.default for f in self.fields}
        self.eval_calculated_fields(self._temp_new_rec)
        self.active_field_idx = 0
        self._start_field_edit()

    def _start_update_record(self):
        if not self.records:
            self._start_add_record()
            return
        self.is_new_record = False
        self.active_field_idx = 0
        self._start_field_edit()

    def _start_field_edit(self):
        cur_f = self.fields[self.active_field_idx]
        if cur_f.type == 'C':
            self._advance_field(1)
            return
        rec_data = self._temp_new_rec if self.is_new_record else (self.records[self.current_rec] if (self.records and 0 <= self.current_rec < len(self.records)) else {})
        val = str(rec_data.get(cur_f.name, cur_f.default))
        self.edit_buffer = list(val)
        self.mode = "EDIT_FIELD"
        self.render_screen()

    def _commit_edit_buffer(self):
        cur_f = self.fields[self.active_field_idx]
        val = "".join(self.edit_buffer).strip()
        if cur_f.type in ('N', '$'):
            try: val = float(val.replace('$', '').replace(',', '').strip())
            except Exception: val = 0.0
        if self.is_new_record:
            self._temp_new_rec[cur_f.name] = val
            self.eval_calculated_fields(self._temp_new_rec)
        else:
            if self.records and 0 <= self.current_rec < len(self.records):
                self.records[self.current_rec][cur_f.name] = val
                self.eval_calculated_fields(self.records[self.current_rec])

    def _advance_field(self, direction):
        n = len(self.fields)
        next_idx = self.active_field_idx + direction
        while 0 <= next_idx < n and self.fields[next_idx].type == 'C':
            next_idx += direction

        if next_idx >= n:
            if self.is_new_record:
                self._save_record_edit()
                self._start_add_record()
            else:
                self.mode = "FORM"
                self.render_screen()
        elif next_idx < 0:
            self.mode = "FORM"
            self.render_screen()
        else:
            self.active_field_idx = next_idx
            self._start_field_edit()

    def _save_record_edit(self):
        if self.is_new_record:
            self.add_record(self._temp_new_rec)
            self.is_new_record = False
            self.status_msg = "Record saved."
        else:
            self.status_msg = "Record updated."
        self.mode = "FORM"
        self.render_screen()

    # Headless / Batch script execution
    def execute_line(self, line):
        cmd_raw = line.strip()
        if not cmd_raw:
            return
        cmd_u = cmd_raw.upper()

        if cmd_u in ("QUIT", "EXIT", "Q", "X"):
            self.exit_to_cpm()
            return
        elif cmd_u in ("MENU", "^K"):
            self.mode = "MENU"
            self.render_screen()
            return
        elif cmd_u in ("LIST", "BROWSE", "L"):
            self.mode = "LIST"
            self.render_screen()
            return
        elif cmd_u in ("FORM", "VIEW"):
            self.mode = "FORM"
            self.render_screen()
            return
        elif cmd_u in ("FIRST", "TOP", "F"):
            self.first_record()
            return
        elif cmd_u in ("LAST", "BOTTOM", "E"):
            self.last_record()
            return
        elif cmd_u in ("NEXT", "N"):
            self.next_record()
            return
        elif cmd_u in ("PREV", "PREVIOUS", "P"):
            self.prev_record()
            return
        elif cmd_u in ("DELETE", "DEL", "D"):
            self.delete_current_record()
            return
        elif cmd_u in ("WRITE", "SAVE_REC", "^B"):
            self._save_record_edit()
            return

        parts = cmd_raw.split(None, 1)
        verb = parts[0].upper()
        args = parts[1].strip() if len(parts) > 1 else ""

        if verb in ("OPEN", "O", "LOAD", "DS", "DATASTAR"):
            if args: self.load_file(args)
            return
        elif verb == "SAVE":
            self.save_file(args if args else None)
            return
        elif verb == "EXPORT":
            if args: self.export_csv(args)
            return
        elif verb == "IMPORT":
            if args: self.import_csv(args)
            return
        elif verb in ("SEEK", "KEY"):
            self.seek_key(args)
            return
        elif verb in ("FIND", "SEARCH", "S"):
            self.find_text(args)
            return
        elif verb == "GOTO":
            self.goto_record(args)
            return
        elif verb in ("ADD", "A"):
            if args:
                # Comma separated list of values
                tokens = []
                for m in re.finditer(r'"([^"]*)"|([^,]+)', args):
                    tokens.append(m.group(1) if m.group(1) is not None else m.group(2).strip())
                rec = {}
                for i, f in enumerate(self.fields):
                    if f.type == 'C':
                        continue
                    if i < len(tokens):
                        rec[f.name] = tokens[i]
                self.add_record(rec)
                self.mode = "FORM"
                self.render_screen()
            else:
                self._start_add_record()
            return
        elif verb in ("UPDATE", "SET", "U"):
            if '=' in args:
                fn, fval = args.split('=', 1)
                self.update_current_record(fn.strip(), fval.strip())
                self.render_screen()
            else:
                self._start_update_record()
            return

        if '=' in cmd_raw:
            fn, fval = cmd_raw.split('=', 1)
            self.update_current_record(fn.strip(), fval.strip())
            self.render_screen()
            return

        # Default: try search text
        self.find_text(cmd_raw)


try:
    from cpm_adventure import InfocomAdventureEngine
except Exception:
    InfocomAdventureEngine = None


class CPMSystem:
    """
    Sinclair ZX Spectrum +3 CP/M Plus (CP/M 2.2 compatible) environment.
    Provides virtual filesystem across drives A:, B:, M:, default Amstrad/Sinclair disk suite,
    BDOS system calls, .DSK disk image loading, and interactive execution.
    """
    def __init__(self, screen_handler=None, screen=None):
        screen_obj = screen_handler if screen_handler is not None else screen
        self.screen = screen_obj if screen_obj is not None else CPMScreen()
        self.screen.cpm_system = self
        self.drives = {'A': {}, 'B': {}, 'M': {}}
        self.current_drive = 'A'
        self.current_user = 0
        self.running = False
        self.active_app = None
        self.tpa_memory = bytearray(65536)
        self.mounted_disks = {'A': None, 'B': None}
        self.mallard = MallardBASIC(self)
        self.ddt = DDT(self)
        self.ed = ED(self)
        self.wordstar = WordStar(self)
        self.calcstar = CalcStar(self)
        self.datastar = DataStar(self)
        self.adventure = InfocomAdventureEngine(self) if InfocomAdventureEngine else None
        self.cpu = None
        self.dma_address = 0x0080
        self.key_queue = []
        self.search_matches = []
        self.search_index = 0
        self.running_native = False
        self.init_default_system_disk()

    def init_default_system_disk(self):
        disk_loaded = False
        dsk_bytes = None

        # 1. Try loading authentic Sinclair +3 CP/M Plus boot disk from file
        try:
            candidates = [
                os.path.join(os.path.dirname(os.path.abspath(__file__)), "disks", "plus3_cpm3.dsk"),
                os.path.join("disks", "plus3_cpm3.dsk"),
                os.path.join(os.path.dirname(os.path.abspath(__file__)), "plus3_cpm3.dsk"),
                "plus3_cpm3.dsk",
            ]
            for p in candidates:
                if os.path.isfile(p):
                    with open(p, "rb") as f:
                        dsk_bytes = f.read()
                    break
        except Exception:
            pass

        # 2. Fall back to embedded base64 compressed data
        if not dsk_bytes:
            try:
                from disks.plus3_cpm3_b64 import get_plus3_cpm3_dsk_bytes
                dsk_bytes = get_plus3_cpm3_dsk_bytes()
            except Exception:
                try:
                    import plus3_cpm3_b64
                    dsk_bytes = plus3_cpm3_b64.get_plus3_cpm3_dsk_bytes()
                except Exception:
                    pass

        # 3. Mount authentic disk on Drive A:
        if dsk_bytes:
            try:
                disk_img = CPMDiskImage.from_data(dsk_bytes, "A:")
                disk_img.filename = "plus3_cpm3.dsk"
                disk_img.format_name = "Sinclair +3 CP/M Plus System Boot Disk (CF2 180K)"
                self.mounted_disks['A'] = disk_img
                files = disk_img.get_files()
                for fname, fbytes in files.items():
                    self.put_file('A', fname, fbytes, sync_disk=False)
                disk_loaded = True
            except Exception:
                pass

