def run_program(start_idx=0, start_sub_idx=0, is_continue=False, is_fullscreen=False):
    global last_run_index, last_sub_index, can_continue, data_pointer, current_trace_line, last_keypress, for_stack, running
    global fullscreen_mode, windowed_size, screen, canvas_dirty
    global while_stack, repeat_stack, case_stack, program_execution_mode, listing_vars_active, listing_code_active, current_running_line
    listing_vars_active = False
    listing_code_active = False
    running = True
    program_execution_mode = True
    if last_keypress:
        key_press_buffer.append(last_keypress)
        last_keypress = ""
    try:
        pygame.key.set_repeat(400, 60)
    except Exception:
        pass

    if is_fullscreen and not fullscreen_mode:
        fullscreen_mode = True
        windowed_size = screen.get_size()
        screen = pygame.display.set_mode((0, 0), pygame.FULLSCREEN)
        canvas_dirty = True
        redraw_canvas()
        update_display()

    if not is_continue:
        parse_data_lines()
        data_pointer = 0
        gosub_stack.clear()
        for_stack.clear()
        scan_proc_definitions()
        proc_stack.clear()
        loop_stack.clear()
        while_stack.clear()
        repeat_stack.clear()
        case_stack.clear()
        on_error_trap = None
        if is_frogger_program():
            udg_base = memory[23675] + (memory[23676] * 256) if len(memory) > 23676 else 65368
            if not (0 <= udg_base <= len(memory) - 168):
                udg_base = 65368
            mem_slice = memory[udg_base : udg_base + 168]
            def_slice = bytearray()
            for g in DEFAULT_UDG_BANK:
                def_slice.extend(g)
            if not any(mem_slice) or mem_slice == def_slice:
                load_frogger_udgs()
        elif is_quincy_program():
            udg_base = memory[23675] + (memory[23676] * 256) if len(memory) > 23676 else 65368
            if not (0 <= udg_base <= len(memory) - 168):
                udg_base = 65368
            h_addr = udg_base + 7 * 8
            if not any(memory[h_addr : h_addr + 8]) or memory[h_addr : h_addr + 8] == bytearray(DEFAULT_UDG_BANK[7]):
                load_quincy_udgs()
    else:
        scan_proc_definitions()

    global program_line_order
    if 'program_line_order' in globals() and program_line_order and all(k in program for k in program_line_order) and len(program_line_order) == len(program):
        line_numbers = list(program_line_order)
    else:
        line_numbers = sorted(program.keys())
    if not line_numbers:
        canvas_print("No program")
        return

    line_idx = start_idx
    sub_idx = start_sub_idx
    ln = line_numbers[line_idx] if line_idx < len(line_numbers) else 0

    held_keys = set()
    stmt_counter = 0
    try:
        while 0 <= line_idx < len(line_numbers) and running:
            stmt_counter += 1
            now_ticks = pygame.time.get_ticks()
            max_batch = 128 if globals().get('next_turbo_speed', 0) > 0 else 32
            if stmt_counter >= max_batch or (now_ticks - last_display_time >= 16):
                stmt_counter = 0
                if now_ticks - last_display_time >= 15:
                    update_display()

            ln = line_numbers[line_idx]
            current_running_line = ln
            if trace_on:
                current_trace_line = ln

            if stmt_counter == 0 or (now_ticks - last_display_time >= 15):
                pygame.event.pump()
                keys = pygame.key.get_pressed()
                if keys[pygame.K_ESCAPE] or keys[pygame.K_END]:
                    raise BASICBreak()
                evs = pygame.event.get()
            else:
                evs = ()

            for event in evs:
                if event.type == pygame.QUIT:
                    pygame.quit()
                    sys.exit()
                elif is_break_event(event):
                    raise BASICBreak()
                elif event.type == pygame.VIDEORESIZE:
                    if not fullscreen_mode:
                        screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
                elif event.type == pygame.MOUSEMOTION:
                    update_amx_from_mouse(event.pos)
                    if amx_pointer_visible:
                        update_display()
                elif event.type in (pygame.MOUSEBUTTONDOWN, pygame.MOUSEBUTTONUP):
                    update_amx_from_mouse(event.pos)
                    update_amx_buttons(event)
                    if amx_pointer_visible:
                        update_display()
                elif event.type == pygame.KEYDOWN:
                    held_keys.add(event.key)
                    k_char = None
                    if event.key in (pygame.K_BACKSPACE, pygame.K_DELETE):
                        k_char = chr(12)
                    elif event.key in (pygame.K_LEFT, pygame.K_KP4, pygame.K_KP5):
                        k_char = '5'
                    elif event.key in (pygame.K_RIGHT, pygame.K_KP8):
                        k_char = '8'
                    elif event.key in (pygame.K_DOWN, pygame.K_KP6):
                        k_char = '6'
                    elif event.key in (pygame.K_UP, pygame.K_KP7):
                        k_char = '7'
                    elif event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                        k_char = '\r'
                    elif event.key == pygame.K_SPACE:
                        k_char = ' '
                    elif event.key == pygame.K_INSERT:
                        k_char = chr(20)
                    elif event.key == pygame.K_F1:
                        k_char = chr(6)
                    elif event.key == pygame.K_F2:
                        k_char = chr(14)
                    elif event.key == pygame.K_F3:
                        k_char = chr(15)
                    elif event.key == pygame.K_F4:
                        k_char = chr(16)
                    elif event.key == pygame.K_F5:
                        k_char = chr(17)
                    elif event.key == pygame.K_F6:
                        k_char = chr(18)
                    elif event.key == pygame.K_F7:
                        k_char = chr(19)
                    elif event.key == pygame.K_F8:
                        k_char = chr(20)
                    elif event.unicode:
                        k_char = event.unicode
                        if currah_enabled and currah_keyvoice and ord(event.unicode) >= 32:
                            currah_speak(event.unicode)
                    if k_char:
                        last_keypress = k_char
                        key_press_buffer.append(k_char)
                elif event.type == pygame.KEYUP:
                    held_keys.discard(event.key)

            if not held_keys and not key_press_buffer:
                last_keypress = ""

            stmt_line = program.get(ln, "")
            sub_stmts = split_statements(stmt_line)
            
            if not sub_stmts or sub_idx >= len(sub_stmts):
                sub_idx = 0
                line_idx += 1
                continue

            sub_stmt = sub_stmts[sub_idx]
            sub_upper = sub_stmt.strip().upper()

            next_line_idx = line_idx
            next_sub_idx = sub_idx + 1
            if next_sub_idx >= len(sub_stmts):
                next_line_idx = line_idx + 1
                next_sub_idx = 0

            try:
                if sub_upper.startswith("REM"):
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper == "STOP":
                    raise BASICStop()

                elif sub_upper == "FORTH" or sub_upper.startswith("FORTH ") or sub_upper.startswith("FORTH:"):
                    line_raw = program.get(ln, "")
                    m_same = re.search(r'\bFORTH\b(.*?)\b(?:END\s+FORTH|ENDFORTH|END_FORTH)\b', line_raw, re.IGNORECASE)
                    if m_same:
                        f_code = m_same.group(1).strip()
                        if f_code:
                            execute_forth_inline_block(f_code, block_key=(ln, "single"))
                        after_text = line_raw[m_same.end():].strip()
                        if after_text.startswith(":"):
                            after_text = after_text[1:].strip()
                        if after_text:
                            consumed_stmts = split_statements(line_raw[:m_same.end()])
                            sub_idx = len(consumed_stmts)
                            if sub_idx >= len(sub_stmts):
                                line_idx = line_idx + 1
                                sub_idx = 0
                        else:
                            line_idx = line_idx + 1
                            sub_idx = 0
                        continue
                    else:
                        forth_blocks = []
                        m_f_start = re.search(r'\bFORTH\b', line_raw, re.IGNORECASE)
                        if m_f_start:
                            tail_text = line_raw[m_f_start.end():].strip()
                            if tail_text.startswith(":"):
                                tail_text = tail_text[1:].strip()
                            if tail_text:
                                forth_blocks.append(tail_text)

                        scan_l = line_idx + 1
                        found_end = False
                        resume_l = scan_l
                        resume_s = 0
                        while scan_l < len(line_numbers):
                            sln = line_numbers[scan_l]
                            sline = program.get(sln, "")
                            m_end = re.search(r'\b(?:END\s+FORTH|ENDFORTH|END_FORTH)\b', sline, re.IGNORECASE)
                            if m_end:
                                found_end = True
                                pre_text = sline[:m_end.start()].strip()
                                if pre_text:
                                    forth_blocks.append(pre_text)
                                resume_l = scan_l + 1
                                resume_s = 0
                                break
                            elif re.match(r'^\s*FORTH\s*$', sline, re.IGNORECASE):
                                found_end = True
                                resume_l = scan_l + 1
                                resume_s = 0
                                break
                            else:
                                forth_blocks.append(sline)
                            scan_l += 1

                        if forth_blocks:
                            combined_forth = "\n".join(forth_blocks)
                            execute_forth_inline_block(combined_forth, block_key=(ln, "multi"))
                            update_display()

                        if found_end:
                            line_idx = resume_l
                            sub_idx = resume_s
                        else:
                            line_idx = len(line_numbers)
                            sub_idx = 0
                        continue

                elif sub_upper in ("END FORTH", "ENDFORTH", "END_FORTH") or sub_upper.startswith("END FORTH ") or sub_upper.startswith("ENDFORTH ") or sub_upper.startswith("END_FORTH "):
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper == "LOGO" or sub_upper.startswith("LOGO ") or sub_upper.startswith("LOGO:"):
                    line_raw = program.get(ln, "")
                    m_same = re.search(r'\bLOGO\b(.*?)\b(?:END\s+LOGO|ENDLOGO|END_LOGO)\b', line_raw, re.IGNORECASE)
                    if m_same:
                        l_code = m_same.group(1).strip()
                        if l_code:
                            get_logo_engine().interpret(l_code)
                        after_text = line_raw[m_same.end():].strip()
                        if after_text.startswith(":"):
                            after_text = after_text[1:].strip()
                        if after_text:
                            consumed_stmts = split_statements(line_raw[:m_same.end()])
                            sub_idx = len(consumed_stmts)
                            if sub_idx >= len(sub_stmts):
                                line_idx = line_idx + 1
                                sub_idx = 0
                        else:
                            line_idx = line_idx + 1
                            sub_idx = 0
                        continue
                    else:
                        logo_blocks = []
                        m_l_start = re.search(r'\bLOGO\b', line_raw, re.IGNORECASE)
                        if m_l_start:
                            tail_text = line_raw[m_l_start.end():].strip()
                            if tail_text.startswith(":"):
                                tail_text = tail_text[1:].strip()
                            if tail_text:
                                logo_blocks.append(tail_text)

                        scan_l = line_idx + 1
                        found_end = False
                        resume_l = scan_l
                        resume_s = 0
                        while scan_l < len(line_numbers):
                            sln = line_numbers[scan_l]
                            sline = program.get(sln, "")
                            m_end = re.search(r'\b(?:END\s+LOGO|ENDLOGO|END_LOGO)\b', sline, re.IGNORECASE)
                            if m_end:
                                found_end = True
                                pre_text = sline[:m_end.start()].strip()
                                if pre_text:
                                    logo_blocks.append(pre_text)
                                resume_l = scan_l + 1
                                resume_s = 0
                                break
                            elif re.match(r'^\s*LOGO\s*$', sline, re.IGNORECASE):
                                found_end = True
                                resume_l = scan_l + 1
                                resume_s = 0
                                break
                            else:
                                logo_blocks.append(sline)
                            scan_l += 1

                        if logo_blocks:
                            combined_logo = "\n".join(logo_blocks)
                            get_logo_engine().interpret(combined_logo)
                            update_display()

                        if found_end:
                            line_idx = resume_l
                            sub_idx = resume_s
                        else:
                            line_idx = len(line_numbers)
                            sub_idx = 0
                        continue

                elif sub_upper in ("END LOGO", "ENDLOGO", "END_LOGO") or sub_upper.startswith("END LOGO ") or sub_upper.startswith("ENDLOGO "):
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper in ("END PROLOG", "ENDPROLOG", "END_PROLOG") or sub_upper.startswith("END PROLOG ") or sub_upper.startswith("ENDPROLOG "):
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper == "PROLOG" or sub_upper.startswith("PROLOG ") or sub_upper.startswith("PROLOG:"):
                    line_raw = program.get(ln, "")
                    m_same = re.search(r'\bPROLOG\b(.*?)\b(?:END\s+PROLOG|ENDPROLOG|END_PROLOG)\b', line_raw, re.IGNORECASE)
                    if m_same:
                        p_code = m_same.group(1).strip()
                        if p_code:
                            get_prolog_engine().interpret(p_code, print_fn=canvas_print)
                        after_text = line_raw[m_same.end():].strip()
                        if after_text.startswith(":"):
                            after_text = after_text[1:].strip()
                        if after_text:
                            consumed_stmts = split_statements(line_raw[:m_same.end()])
                            sub_idx = len(consumed_stmts)
                            if sub_idx >= len(sub_stmts):
                                line_idx = line_idx + 1
                                sub_idx = 0
                        else:
                            line_idx = line_idx + 1
                            sub_idx = 0
                        continue
                    else:
                        prolog_blocks = []
                        m_p_start = re.search(r'\bPROLOG\b', line_raw, re.IGNORECASE)
                        if m_p_start:
                            tail_text = line_raw[m_p_start.end():].strip()
                            if tail_text.startswith(":"):
                                tail_text = tail_text[1:].strip()
                            if tail_text:
                                prolog_blocks.append(tail_text)

                        scan_l = line_idx + 1
                        found_end = False
                        resume_l = scan_l
                        resume_s = 0
                        while scan_l < len(line_numbers):
                            sln = line_numbers[scan_l]
                            sline = program.get(sln, "")
                            m_end = re.search(r'\b(?:END\s+PROLOG|ENDPROLOG|END_PROLOG)\b', sline, re.IGNORECASE)
                            if m_end:
                                found_end = True
                                pre_text = sline[:m_end.start()].strip()
                                if pre_text:
                                    prolog_blocks.append(pre_text)
                                resume_l = scan_l + 1
                                resume_s = 0
                                break
                            elif re.match(r'^\s*PROLOG\s*$', sline, re.IGNORECASE):
                                found_end = True
                                resume_l = scan_l + 1
                                resume_s = 0
                                break
                            else:
                                prolog_blocks.append(sline)
                            scan_l += 1

                        if prolog_blocks:
                            combined_prolog = "\n".join(prolog_blocks)
                            get_prolog_engine().interpret(combined_prolog, print_fn=canvas_print)
                            update_display()

                        if found_end:
                            line_idx = resume_l
                            sub_idx = resume_s
                        else:
                            line_idx = len(line_numbers)
                            sub_idx = 0
                        continue

                elif sub_upper in ("END Z80", "ENDZ80", "END_Z80") or sub_upper.startswith("END Z80 ") or sub_upper.startswith("ENDZ80 "):
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper == "Z80" or sub_upper.startswith("Z80 ") or sub_upper.startswith("Z80:"):
                    line_raw = program.get(ln, "")
                    m_same = re.search(r'\bZ80\b(.*?)\b(?:END\s+Z80|ENDZ80|END_Z80)\b', line_raw, re.IGNORECASE)
                    if m_same:
                        z_code = m_same.group(1).strip()
                        if z_code:
                            execute_z80_inline_block(z_code, block_key=(ln, "single"))
                        after_text = line_raw[m_same.end():].strip()
                        if after_text.startswith(":"):
                            after_text = after_text[1:].strip()
                        if after_text:
                            consumed_stmts = split_statements(line_raw[:m_same.end()])
                            sub_idx = len(consumed_stmts)
                            if sub_idx >= len(sub_stmts):
                                line_idx = line_idx + 1
                                sub_idx = 0
                        else:
                            line_idx = line_idx + 1
                            sub_idx = 0
                        continue
                    else:
                        z80_blocks = []
                        m_z_start = re.search(r'\bZ80\b', line_raw, re.IGNORECASE)
                        if m_z_start:
                            tail_text = line_raw[m_z_start.end():].strip()
                            if tail_text.startswith(":"):
                                tail_text = tail_text[1:].strip()
                            if tail_text:
                                z80_blocks.append(tail_text)

                        scan_l = line_idx + 1
                        found_end = False
                        resume_l = scan_l
                        resume_s = 0
                        while scan_l < len(line_numbers):
                            sln = line_numbers[scan_l]
                            sline = program.get(sln, "")
                            m_end = re.search(r'\b(?:END\s+Z80|ENDZ80|END_Z80)\b', sline, re.IGNORECASE)
                            if m_end:
                                found_end = True
                                pre_text = sline[:m_end.start()].strip()
                                if pre_text:
                                    z80_blocks.append(pre_text)
                                resume_l = scan_l + 1
                                resume_s = 0
                                break
                            elif re.match(r'^\s*Z80\s*$', sline, re.IGNORECASE):
                                found_end = True
                                resume_l = scan_l + 1
                                resume_s = 0
                                break
                            else:
                                z80_blocks.append(sline)
                            scan_l += 1

                        if z80_blocks:
                            combined_z80 = "\n".join(z80_blocks)
                            execute_z80_inline_block(combined_z80, block_key=(ln, "multi"))
                            update_display()

                        if found_end:
                            line_idx = resume_l
                            sub_idx = resume_s
                        else:
                            line_idx = len(line_numbers)
                            sub_idx = 0
                        continue

                elif sub_upper.startswith("GO TO ") or sub_upper.startswith("GOTO "):
                    prefix_len = 6 if sub_upper.startswith("GO TO ") else 5
                    target = int(evaluate_expr(sub_stmt[prefix_len:]))
                    line_idx = get_target_line_idx(target, line_numbers)
                    sub_idx = 0
                    continue

                elif sub_upper.startswith("GO SUB ") or sub_upper.startswith("GOSUB "):
                    prefix_len = 7 if sub_upper.startswith("GO SUB ") else 6
                    target = int(evaluate_expr(sub_stmt[prefix_len:]))
                    target_line_idx = get_target_line_idx(target, line_numbers)
                    gosub_stack.append((next_line_idx, next_sub_idx))
                    line_idx = target_line_idx
                    sub_idx = 0
                    continue

                elif sub_upper == "RETURN" or sub_upper.startswith("RETURN "):
                    ret_val = None
                    if sub_upper.startswith("RETURN "):
                        ret_val = evaluate_expr(sub_stmt[7:].strip())
                    if ret_val is not None and proc_stack:
                        frame = proc_stack.pop()
                        if "return_box" in frame and frame["return_box"] is not None:
                            frame["return_box"][0] = ret_val
                        for formal, caller_var in frame.get("ref_map", {}).items():
                            if formal.endswith("$") and caller_var.endswith("$"):
                                string_variables[caller_var] = string_variables.get(formal, "")
                            elif not formal.endswith("$") and not caller_var.endswith("$"):
                                variables[caller_var] = variables.get(formal, 0.0)
                        for var_name, old_val in frame.get("saved_locals", {}).items():
                            if var_name.endswith("$"):
                                if old_val is not None: string_variables[var_name] = old_val
                                else: string_variables.pop(var_name, None)
                            else:
                                if old_val is not None: variables[var_name] = old_val
                                else: variables.pop(var_name, None)
                        line_idx = frame["ret_line_idx"]
                        sub_idx = frame["ret_sub_idx"]
                        continue
                    elif gosub_stack:
                        ret_line_idx, ret_sub_idx = gosub_stack.pop()
                        line_idx = ret_line_idx
                        sub_idx = ret_sub_idx
                        continue
                    elif proc_stack:
                        frame = proc_stack.pop()
                        for formal, caller_var in frame.get("ref_map", {}).items():
                            if formal.endswith("$") and caller_var.endswith("$"):
                                string_variables[caller_var] = string_variables.get(formal, "")
                            elif not formal.endswith("$") and not caller_var.endswith("$"):
                                variables[caller_var] = variables.get(formal, 0.0)
                        for var_name, old_val in frame.get("saved_locals", {}).items():
                            if var_name.endswith("$"):
                                if old_val is not None: string_variables[var_name] = old_val
                                else: string_variables.pop(var_name, None)
                            else:
                                if old_val is not None: variables[var_name] = old_val
                                else: variables.pop(var_name, None)
                        line_idx = frame["ret_line_idx"]
                        sub_idx = frame["ret_sub_idx"]
                        continue
                    else:
                        raise Exception("RETURN without GOSUB or PROC")

                elif sub_upper.startswith("DO ") or sub_upper == "DO":
                    cond_type = None
                    cond_expr = None
                    m_dw = re.match(r"^DO\s+(WHILE|UNTIL)\s+(.+)$", sub_stmt, re.IGNORECASE)
                    if m_dw:
                        cond_type = m_dw.group(1).upper()
                        cond_expr = m_dw.group(2)
                        cond_val = evaluate_expr(cond_expr)
                        if (cond_type == "WHILE" and not cond_val) or (cond_type == "UNTIL" and cond_val):
                            skip_l, skip_s = find_matching_loop(line_idx, sub_idx + 1, line_numbers)
                            stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                            sub_stmts = split_statements(stmt_line)
                            if skip_s + 1 < len(sub_stmts):
                                line_idx = skip_l
                                sub_idx = skip_s + 1
                            else:
                                line_idx = skip_l + 1
                                sub_idx = 0
                            continue
                    loop_stack.append({
                        "line_idx": line_idx,
                        "sub_idx": sub_idx,
                        "next_line_idx": next_line_idx,
                        "next_sub_idx": next_sub_idx,
                        "cond_type": cond_type,
                        "cond_expr": cond_expr
                    })
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper.startswith("LOOP ") or sub_upper == "LOOP":
                    if not loop_stack:
                        raise Exception("LOOP without DO")
                    frame = loop_stack[-1]
                    m_lw = re.match(r"^LOOP\s+(WHILE|UNTIL)\s+(.+)$", sub_stmt, re.IGNORECASE)
                    if m_lw:
                        l_type = m_lw.group(1).upper()
                        l_expr = m_lw.group(2)
                        l_val = evaluate_expr(l_expr)
                        if (l_type == "WHILE" and l_val) or (l_type == "UNTIL" and not l_val):
                            line_idx = frame["next_line_idx"]
                            sub_idx = frame["next_sub_idx"]
                            continue
                        else:
                            loop_stack.pop()
                            line_idx = next_line_idx
                            sub_idx = next_sub_idx
                            continue
                    else:
                        loop_stack.pop()
                        line_idx = frame["line_idx"]
                        sub_idx = frame["sub_idx"]
                        continue

                elif sub_upper.startswith("EXIT IF "):
                    cond_expr = sub_stmt[8:].strip()
                    if evaluate_expr(cond_expr):
                        if not loop_stack:
                            raise Exception("EXIT IF without DO")
                        loop_stack.pop()
                        skip_l, skip_s = find_matching_loop(line_idx, sub_idx + 1, line_numbers)
                        stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                        sub_stmts = split_statements(stmt_line)
                        if skip_s + 1 < len(sub_stmts):
                            line_idx = skip_l
                            sub_idx = skip_s + 1
                        else:
                            line_idx = skip_l + 1
                            sub_idx = 0
                        continue
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper == "EXIT DO":
                    if not loop_stack:
                        raise Exception("EXIT DO without DO")
                    loop_stack.pop()
                    skip_l, skip_s = find_matching_loop(line_idx, sub_idx + 1, line_numbers)
                    stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                    sub_stmts = split_statements(stmt_line)
                    if skip_s + 1 < len(sub_stmts):
                        line_idx = skip_l
                        sub_idx = skip_s + 1
                    else:
                        line_idx = skip_l + 1
                        sub_idx = 0
                    continue

                elif sub_upper == "EXIT FOR":
                    if not for_stack:
                        raise Exception("EXIT FOR without FOR")
                    top_for = for_stack.pop()
                    top_for["active"] = False
                    skip_l, skip_s = find_matching_next(line_idx, sub_idx + 1, top_for["var"], line_numbers)
                    stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                    sub_stmts = split_statements(stmt_line)
                    if skip_s + 1 < len(sub_stmts):
                        line_idx = skip_l
                        sub_idx = skip_s + 1
                    else:
                        line_idx = skip_l + 1
                        sub_idx = 0
                    continue

                elif sub_upper.startswith("WHILE "):
                    cond_expr = sub_stmt[6:].strip()
                    cond_val = evaluate_expr(cond_expr)
                    if cond_val:
                        while_stack.append({
                            "line_idx": line_idx,
                            "sub_idx": sub_idx,
                            "cond_expr": cond_expr
                        })
                        line_idx = next_line_idx
                        sub_idx = next_sub_idx
                        continue
                    else:
                        skip_l, skip_s = find_matching_wend(line_idx, sub_idx + 1, line_numbers)
                        stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                        sub_stmts = split_statements(stmt_line)
                        if skip_s + 1 < len(sub_stmts):
                            line_idx = skip_l
                            sub_idx = skip_s + 1
                        else:
                            line_idx = skip_l + 1
                            sub_idx = 0
                        continue

                elif sub_upper == "WEND" or sub_upper.startswith("WEND "):
                    if not while_stack:
                        raise Exception("WEND without WHILE")
                    frame = while_stack[-1]
                    cond_val = evaluate_expr(frame["cond_expr"])
                    if cond_val:
                        stmt_line = program.get(line_numbers[frame["line_idx"]], "")
                        sub_stmts = split_statements(stmt_line)
                        if frame["sub_idx"] + 1 < len(sub_stmts):
                            line_idx = frame["line_idx"]
                            sub_idx = frame["sub_idx"] + 1
                        else:
                            line_idx = frame["line_idx"] + 1
                            sub_idx = 0
                        continue
                    else:
                        while_stack.pop()
                        line_idx = next_line_idx
                        sub_idx = next_sub_idx
                        continue

                elif sub_upper == "EXIT WHILE":
                    if not while_stack:
                        raise Exception("EXIT WHILE without WHILE")
                    while_stack.pop()
                    skip_l, skip_s = find_matching_wend(line_idx, sub_idx + 1, line_numbers)
                    stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                    sub_stmts = split_statements(stmt_line)
                    if skip_s + 1 < len(sub_stmts):
                        line_idx = skip_l
                        sub_idx = skip_s + 1
                    else:
                        line_idx = skip_l + 1
                        sub_idx = 0
                    continue

                elif sub_upper == "REPEAT" or sub_upper.startswith("REPEAT "):
                    repeat_stack.append({
                        "line_idx": next_line_idx,
                        "sub_idx": next_sub_idx
                    })
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper.startswith("UNTIL "):
                    if not repeat_stack:
                        raise Exception("UNTIL without REPEAT")
                    cond_expr = sub_stmt[6:].strip()
                    cond_val = evaluate_expr(cond_expr)
                    if not cond_val:
                        frame = repeat_stack[-1]
                        line_idx = frame["line_idx"]
                        sub_idx = frame["sub_idx"]
                        continue
                    else:
                        repeat_stack.pop()
                        line_idx = next_line_idx
                        sub_idx = next_sub_idx
                        continue

                elif sub_upper == "EXIT REPEAT":
                    if not repeat_stack:
                        raise Exception("EXIT REPEAT without REPEAT")
                    repeat_stack.pop()
                    skip_l, skip_s = find_matching_until(line_idx, sub_idx + 1, line_numbers)
                    stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                    sub_stmts = split_statements(stmt_line)
                    if skip_s + 1 < len(sub_stmts):
                        line_idx = skip_l
                        sub_idx = skip_s + 1
                    else:
                        line_idx = skip_l + 1
                        sub_idx = 0
                    continue

                elif sub_upper == "EXIT":
                    if loop_stack:
                        loop_stack.pop()
                        skip_l, skip_s = find_matching_loop(line_idx, sub_idx + 1, line_numbers)
                    elif while_stack:
                        while_stack.pop()
                        skip_l, skip_s = find_matching_wend(line_idx, sub_idx + 1, line_numbers)
                    elif repeat_stack:
                        repeat_stack.pop()
                        skip_l, skip_s = find_matching_until(line_idx, sub_idx + 1, line_numbers)
                    elif for_stack:
                        top_for = for_stack.pop()
                        top_for["active"] = False
                        skip_l, skip_s = find_matching_next(line_idx, sub_idx + 1, top_for["var"], line_numbers)
                    else:
                        line_idx = next_line_idx
                        sub_idx = next_sub_idx
                        continue
                    stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                    sub_stmts = split_statements(stmt_line)
                    if skip_s + 1 < len(sub_stmts):
                        line_idx = skip_l
                        sub_idx = skip_s + 1
                    else:
                        line_idx = skip_l + 1
                        sub_idx = 0
                    continue

                elif sub_upper.startswith("CASE ") and bool(re.search(r'\bOF\b', sub_upper)):
                    m_case = re.match(r"^CASE\s+(.+?)\s+OF\b", sub_stmt, re.IGNORECASE)
                    if m_case:
                        c_val = evaluate_expr(m_case.group(1))
                        case_stack.append({"val": c_val, "matched": False})
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper.startswith("WHEN "):
                    if not case_stack:
                        raise Exception("WHEN without CASE")
                    frame = case_stack[-1]
                    if frame["matched"]:
                        skip_l, skip_s = find_matching_endcase(line_idx, sub_idx + 1, line_numbers)
                        stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                        sub_stmts = split_statements(stmt_line)
                        if skip_s + 1 < len(sub_stmts):
                            line_idx = skip_l
                            sub_idx = skip_s + 1
                        else:
                            line_idx = skip_l + 1
                            sub_idx = 0
                        continue
                    cand_strs = split_top_level_commas(sub_stmt[5:])
                    matched = False
                    for c_str in cand_strs:
                        c_val = evaluate_expr(c_str.strip())
                        if frame["val"] == c_val:
                            matched = True
                            break
                    if matched:
                        frame["matched"] = True
                        line_idx = next_line_idx
                        sub_idx = next_sub_idx
                        continue
                    else:
                        skip_l, skip_s = find_next_case_branch(line_idx, sub_idx + 1, line_numbers)
                        stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                        sub_stmts = split_statements(stmt_line)
                        if skip_s < len(sub_stmts):
                            line_idx = skip_l
                            sub_idx = skip_s
                        else:
                            line_idx = skip_l + 1
                            sub_idx = 0
                        continue

                elif sub_upper == "OTHERWISE" or sub_upper.startswith("OTHERWISE "):
                    if case_stack:
                        frame = case_stack[-1]
                        if frame["matched"]:
                            skip_l, skip_s = find_matching_endcase(line_idx, sub_idx + 1, line_numbers)
                            stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                            sub_stmts = split_statements(stmt_line)
                            if skip_s + 1 < len(sub_stmts):
                                line_idx = skip_l
                                sub_idx = skip_s + 1
                            else:
                                line_idx = skip_l + 1
                                sub_idx = 0
                            continue
                        else:
                            frame["matched"] = True
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper == "ENDCASE" or sub_upper.startswith("ENDCASE "):
                    if case_stack:
                        case_stack.pop()
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper == "ENDIF" or sub_upper.startswith("ENDIF "):
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper.startswith("SWAP "):
                    handle_swap_statement(sub_stmt)
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper.startswith("LOCATE "):
                    handle_locate_statement(sub_stmt)
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper.startswith("DEF PROC") or sub_upper.startswith("SUB ") or sub_upper == "SUB" or sub_upper.startswith("FUNCTION ") or sub_upper == "FUNCTION":
                    skip_l, skip_s = find_matching_end_proc(line_idx, sub_idx + 1, line_numbers)
                    stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                    sub_stmts = split_statements(stmt_line)
                    if skip_s + 1 < len(sub_stmts):
                        line_idx = skip_l
                        sub_idx = skip_s + 1
                    else:
                        line_idx = skip_l + 1
                        sub_idx = 0
                    continue

                elif sub_upper.startswith("DECLARE SUB") or sub_upper.startswith("DECLARE FUNCTION"):
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper == "ASM" or sub_upper.startswith("ASM "):
                    scan_l = line_idx
                    scan_s = sub_idx + 1
                    found_end = False
                    while scan_l < len(line_numbers):
                        sln = line_numbers[scan_l]
                        sub_stmts_asm = split_statements(program.get(sln, ""))
                        while scan_s < len(sub_stmts_asm):
                            if sub_stmts_asm[scan_s].strip().upper() in ("END ASM", "ENDASM"):
                                found_end = True
                                break
                            scan_s += 1
                        if found_end:
                            break
                        scan_s = 0
                        scan_l += 1
                    if found_end:
                        line_idx = scan_l
                        sub_idx = scan_s + 1
                        if sub_idx >= len(sub_stmts_asm):
                            line_idx += 1
                            sub_idx = 0
                    else:
                        line_idx = len(line_numbers)
                        sub_idx = 0
                    continue

                elif sub_upper.startswith("PROC ") or sub_upper == "PROC" or sub_upper.startswith("CALL ") or sub_upper == "CALL":
                    target_l, target_s = execute_proc_call(sub_stmt, line_idx, sub_idx, next_line_idx, next_sub_idx, line_numbers)
                    line_idx = target_l
                    sub_idx = target_s
                    continue

                elif sub_upper in ("END PROC", "EXIT PROC", "END SUB", "EXIT SUB", "END FUNCTION", "EXIT FUNCTION", "ENDSUB", "ENDFUNCTION") or sub_upper.startswith(("END PROC ", "EXIT PROC ", "END SUB ", "EXIT SUB ", "END FUNCTION ", "EXIT FUNCTION ", "ENDSUB ", "ENDFUNCTION ")):
                    if proc_stack:
                        frame = proc_stack.pop()
                        for formal, caller_var in frame.get("ref_map", {}).items():
                            if formal.endswith("$") and caller_var.endswith("$"):
                                string_variables[caller_var] = string_variables.get(formal, "")
                            elif not formal.endswith("$") and not caller_var.endswith("$"):
                                variables[caller_var] = variables.get(formal, 0.0)
                        for var_name, old_val in frame.get("saved_locals", {}).items():
                            if var_name.endswith("$"):
                                if old_val is not None: string_variables[var_name] = old_val
                                else: string_variables.pop(var_name, None)
                            else:
                                if old_val is not None: variables[var_name] = old_val
                                else: variables.pop(var_name, None)
                        line_idx = frame["ret_line_idx"]
                        sub_idx = frame["ret_sub_idx"]
                        continue
                    else:
                        raise Exception("END PROC without PROC")

                elif sub_upper.startswith("LOCAL "):
                    vars_list = [v.strip().upper() for v in split_top_level_commas(sub_stmt[6:]) if v.strip()]
                    top_frame = proc_stack[-1] if proc_stack else None
                    for v in vars_list:
                        if top_frame and v not in top_frame["saved_locals"]:
                            if v.endswith("$"):
                                top_frame["saved_locals"][v] = string_variables.get(v, None)
                                string_variables[v] = ""
                            else:
                                top_frame["saved_locals"][v] = variables.get(v, None)
                                variables[v] = 0.0
                        else:
                            if v.endswith("$"): string_variables[v] = ""
                            else: variables[v] = 0.0
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper.startswith("DEFAULT "):
                    m_def = re.match(r"^DEFAULT\s+([A-Za-z][A-Za-z0-9]*\$?)\s*=\s*(.+)$", sub_stmt, re.IGNORECASE)
                    if m_def:
                        v_name = m_def.group(1).upper()
                        expr_str = m_def.group(2)
                        if v_name.endswith("$"):
                            if not string_variables.get(v_name, ""):
                                string_variables[v_name] = str(evaluate_expr(expr_str))
                        else:
                            if variables.get(v_name, 0.0) == 0.0:
                                variables[v_name] = to_float(evaluate_expr(expr_str))
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper.startswith("REF "):
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper.startswith("ON "):
                    m_err = re.match(r"^ON\s+ERR(?:OR)?\s+(?:GO\s*TO\s*(\d+)|STOP|OFF|RESET)", sub_stmt, re.IGNORECASE)
                    if m_err:
                        if "STOP" in sub_upper or "OFF" in sub_upper or "RESET" in sub_upper:
                            on_error_trap = None
                        else:
                            on_error_trap = int(m_err.group(1))
                        line_idx = next_line_idx
                        sub_idx = next_sub_idx
                        continue
                    m_on = re.match(r"^ON\s+(.+?)\s+(GO\s*TO|GOTO|GO\s*SUB|GOSUB|PROC)\s+(.+)", sub_stmt, re.IGNORECASE)
                    if m_on:
                        idx_val = int(to_float(evaluate_expr(m_on.group(1))))
                        action = m_on.group(2).upper().replace(" ", "")
                        targets = [t.strip() for t in split_top_level_commas(m_on.group(3)) if t.strip()]
                        if 1 <= idx_val <= len(targets):
                            target = targets[idx_val - 1]
                            if action == "GOTO":
                                t_ln = int(evaluate_expr(target))
                                line_idx = get_target_line_idx(t_ln, line_numbers)
                                sub_idx = 0
                                continue
                            elif action == "GOSUB":
                                t_ln = int(evaluate_expr(target))
                                gosub_stack.append((next_line_idx, next_sub_idx))
                                line_idx = get_target_line_idx(t_ln, line_numbers)
                                sub_idx = 0
                                continue
                            elif action == "PROC":
                                target_l, target_s = execute_proc_call(f"PROC {target}", line_idx, sub_idx, next_line_idx, next_sub_idx, line_numbers)
                                line_idx = target_l
                                sub_idx = target_s
                                continue
                        line_idx = next_line_idx
                        sub_idx = next_sub_idx
                        continue

                elif sub_upper == "POP":
                    if gosub_stack:
                        gosub_stack.pop()
                    elif proc_stack:
                        frame = proc_stack.pop()
                        for var_name, old_val in frame.get("saved_locals", {}).items():
                            if var_name.endswith("$"):
                                if old_val is not None: string_variables[var_name] = old_val
                                else: string_variables.pop(var_name, None)
                            else:
                                if old_val is not None: variables[var_name] = old_val
                                else: variables.pop(var_name, None)
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx
                    continue

                elif sub_upper.startswith("FOR ") or (sub_upper.startswith("FOR") and not sub_upper.startswith("FORTH") and not sub_upper.startswith("FORMAT")):
                    match = re.match(r"^FOR\s*([A-Za-z][A-Za-z0-9_]*)\s*=\s*(.+?)\s+TO\s+(.+?)(?:\s+STEP\s+(.+))?$", sub_stmt, re.IGNORECASE)
                    if match:
                        v_name = match.group(1).upper()
                        start_val = to_float(evaluate_expr(match.group(2)))
                        limit_val = to_float(evaluate_expr(match.group(3)))
                        step_val = to_float(evaluate_expr(match.group(4))) if match.group(4) else 1.0
                        variables[v_name] = start_val
                        
                        # Sinclair entry bound check: bypass loop body if initial value exceeds limit
                        if (step_val > 0 and start_val > limit_val) or (step_val < 0 and start_val < limit_val):
                            skip_l, skip_s = find_matching_next(next_line_idx, next_sub_idx, v_name, line_numbers)
                            line_idx = skip_l
                            sub_idx = skip_s
                            continue
                        
                        for_stack = [f for f in for_stack if f["var"] != v_name]
                        for_stack.append({
                            "var": v_name, 
                            "limit": limit_val, 
                            "step": step_val, 
                            "line_idx": next_line_idx, 
                            "sub_idx": next_sub_idx,
                            "active": True
                        })
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx

                elif (sub_upper == "NEXT" or sub_upper.startswith("NEXT ") or sub_upper.startswith("NEXT:")) and not sub_upper.startswith("NEXTREG") and not sub_upper.startswith("NEXTBASIC"):
                    m_next = re.match(r"^NEXT\s*(.*)$", sub_stmt, re.IGNORECASE)
                    args = m_next.group(1).strip() if m_next else ""
                    var_list = [v.strip().upper() for v in split_top_level_commas(args) if v.strip()]
                    if not var_list:
                        var_list = [None]
                    
                    looped_back = False
                    for v_name in var_list:
                        target_frame_idx = -1
                        if v_name:
                            for idx in range(len(for_stack) - 1, -1, -1):
                                if for_stack[idx]["var"] == v_name:
                                    target_frame_idx = idx
                                    break
                        else:
                            for idx in range(len(for_stack) - 1, -1, -1):
                                if for_stack[idx].get("active", True):
                                    target_frame_idx = idx
                                    break
                        
                        if target_frame_idx == -1:
                            raise Exception("NEXT without FOR")
                        
                        frame = for_stack[target_frame_idx]
                        if not frame.get("active", True):
                            # Loop already completed; in Sinclair BASIC, continuing past NEXT for completed loop
                            continue
                        
                        variables[frame["var"]] += frame["step"]
                        curr = variables[frame["var"]]
                        lim = frame["limit"]
                        step = frame["step"]
                        if (step > 0 and curr <= lim) or (step < 0 and curr >= lim) or step == 0:
                            line_idx = frame["line_idx"]
                            sub_idx = frame["sub_idx"]
                            looped_back = True
                            break
                        else:
                            frame["active"] = False

                    if looped_back:
                        continue
                    else:
                        line_idx = next_line_idx
                        sub_idx = next_sub_idx

                elif sub_upper.startswith("IF "):
                    curr_stmt = sub_stmt
                    all_true = True
                    then_target = None
                    else_target = None
                    while curr_stmt.upper().startswith("IF "):
                        m_if = re.match(r"IF\s+(.+?)\s+THEN\s+(.+)", curr_stmt, re.IGNORECASE)
                        if not m_if:
                            break
                        cond_expr = m_if.group(1)
                        rest_part = m_if.group(2)
                        t_part, e_part = split_then_else(rest_part)
                        cond_val = evaluate_expr(cond_expr)
                        if isinstance(cond_val, str):
                            try: cond_val = to_float(cond_val)
                            except Exception: cond_val = 0.0
                        if not cond_val:
                            all_true = False
                            else_target = e_part
                            break
                        curr_stmt = t_part.strip()
                    if all_true:
                        then_target = curr_stmt

                    branch = then_target if all_true else else_target
                    if branch is not None:
                        branch_sub_stmts = split_statements(branch.strip())
                        jumped = False
                        for b_idx, b_sub in enumerate(branch_sub_stmts):
                            branch_clean = b_sub.strip()
                            if not branch_clean:
                                continue
                            b_upper = branch_clean.upper()
                            if branch_clean.isdigit():
                                target = int(branch_clean)
                                line_idx = get_target_line_idx(target, line_numbers)
                                sub_idx = 0
                                jumped = True
                                break
                            elif b_upper.startswith("GO TO ") or b_upper.startswith("GOTO "):
                                pfx = 6 if b_upper.startswith("GO TO ") else 5
                                target = int(evaluate_expr(branch_clean[pfx:]))
                                line_idx = get_target_line_idx(target, line_numbers)
                                sub_idx = 0
                                jumped = True
                                break
                            elif b_upper.startswith("GO SUB ") or b_upper.startswith("GOSUB "):
                                pfx = 7 if b_upper.startswith("GO SUB ") else 6
                                target = int(evaluate_expr(branch_clean[pfx:]))
                                target_line_idx = get_target_line_idx(target, line_numbers)
                                gosub_stack.append((next_line_idx, next_sub_idx))
                                line_idx = target_line_idx
                                sub_idx = 0
                                jumped = True
                                break
                            elif b_upper == "STOP":
                                raise BASICStop()
                            elif b_upper in ("END PROC", "EXIT PROC", "END SUB", "EXIT SUB", "END FUNCTION", "EXIT FUNCTION", "ENDSUB", "ENDFUNCTION") or b_upper.startswith(("END PROC ", "EXIT PROC ", "END SUB ", "EXIT SUB ", "END FUNCTION ", "EXIT FUNCTION ", "ENDSUB ", "ENDFUNCTION ")):
                                if proc_stack:
                                    frame = proc_stack.pop()
                                    for formal, caller_var in frame.get("ref_map", {}).items():
                                        if formal.endswith("$") and caller_var.endswith("$"):
                                            string_variables[caller_var] = string_variables.get(formal, "")
                                        elif not formal.endswith("$") and not caller_var.endswith("$"):
                                            variables[caller_var] = variables.get(formal, 0.0)
                                    for var_name, old_val in frame.get("saved_locals", {}).items():
                                        if var_name.endswith("$"):
                                            if old_val is not None: string_variables[var_name] = old_val
                                            else: string_variables.pop(var_name, None)
                                        else:
                                            if old_val is not None: variables[var_name] = old_val
                                            else: variables.pop(var_name, None)
                                    line_idx = frame["ret_line_idx"]
                                    sub_idx = frame["ret_sub_idx"]
                                    jumped = True
                                    break
                                else:
                                    line_idx = next_line_idx
                                    sub_idx = next_sub_idx
                                    jumped = True
                                    break
                            elif b_upper == "EXIT FOR":
                                if not for_stack:
                                    raise Exception("EXIT FOR without FOR")
                                top_for = for_stack.pop()
                                top_for["active"] = False
                                skip_l, skip_s = find_matching_next(line_idx, sub_idx + 1, top_for["var"], line_numbers)
                                stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                                sub_stmts = split_statements(stmt_line)
                                if skip_s + 1 < len(sub_stmts):
                                    line_idx = skip_l
                                    sub_idx = skip_s + 1
                                else:
                                    line_idx = skip_l + 1
                                    sub_idx = 0
                                jumped = True
                                break
                            elif b_upper == "EXIT DO":
                                if not loop_stack:
                                    raise Exception("EXIT DO without DO")
                                loop_stack.pop()
                                skip_l, skip_s = find_matching_loop(line_idx, sub_idx + 1, line_numbers)
                                stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                                sub_stmts = split_statements(stmt_line)
                                if skip_s + 1 < len(sub_stmts):
                                    line_idx = skip_l
                                    sub_idx = skip_s + 1
                                else:
                                    line_idx = skip_l + 1
                                    sub_idx = 0
                                jumped = True
                                break
                            elif b_upper == "EXIT WHILE":
                                if not while_stack:
                                    raise Exception("EXIT WHILE without WHILE")
                                while_stack.pop()
                                skip_l, skip_s = find_matching_wend(line_idx, sub_idx + 1, line_numbers)
                                stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                                sub_stmts = split_statements(stmt_line)
                                if skip_s + 1 < len(sub_stmts):
                                    line_idx = skip_l
                                    sub_idx = skip_s + 1
                                else:
                                    line_idx = skip_l + 1
                                    sub_idx = 0
                                jumped = True
                                break
                            elif b_upper == "EXIT REPEAT":
                                if not repeat_stack:
                                    raise Exception("EXIT REPEAT without REPEAT")
                                repeat_stack.pop()
                                skip_l, skip_s = find_matching_until(line_idx, sub_idx + 1, line_numbers)
                                stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                                sub_stmts = split_statements(stmt_line)
                                if skip_s + 1 < len(sub_stmts):
                                    line_idx = skip_l
                                    sub_idx = skip_s + 1
                                else:
                                    line_idx = skip_l + 1
                                    sub_idx = 0
                                jumped = True
                                break
                            elif b_upper == "EXIT":
                                if loop_stack:
                                    loop_stack.pop()
                                    skip_l, skip_s = find_matching_loop(line_idx, sub_idx + 1, line_numbers)
                                elif while_stack:
                                    while_stack.pop()
                                    skip_l, skip_s = find_matching_wend(line_idx, sub_idx + 1, line_numbers)
                                elif repeat_stack:
                                    repeat_stack.pop()
                                    skip_l, skip_s = find_matching_until(line_idx, sub_idx + 1, line_numbers)
                                elif for_stack:
                                    top_for = for_stack.pop()
                                    top_for["active"] = False
                                    skip_l, skip_s = find_matching_next(line_idx, sub_idx + 1, top_for["var"], line_numbers)
                                else:
                                    line_idx = next_line_idx
                                    sub_idx = next_sub_idx
                                    jumped = True
                                    break
                                stmt_line = program.get(line_numbers[skip_l], "") if skip_l < len(line_numbers) else ""
                                sub_stmts = split_statements(stmt_line)
                                if skip_s + 1 < len(sub_stmts):
                                    line_idx = skip_l
                                    sub_idx = skip_s + 1
                                else:
                                    line_idx = skip_l + 1
                                    sub_idx = 0
                                jumped = True
                                break
                            elif b_upper.startswith("PROC ") or b_upper == "PROC" or b_upper.startswith("CALL ") or b_upper == "CALL":
                                target_l, target_s = execute_proc_call(branch_clean, line_idx, sub_idx, next_line_idx, next_sub_idx, line_numbers)
                                line_idx = target_l
                                sub_idx = target_s
                                jumped = True
                                break
                            elif re.match(r"^([A-Za-z][A-Za-z0-9_]*)(?:\s*\(.*?\))?$", branch_clean) and re.match(r"^([A-Za-z][A-Za-z0-9_]*)(?:\s*\(.*?\))?$", branch_clean).group(1).upper() in proc_definitions and not proc_definitions[re.match(r"^([A-Za-z][A-Za-z0-9_]*)(?:\s*\(.*?\))?$", branch_clean).group(1).upper()].get("is_function", False):
                                target_l, target_s = execute_proc_call(branch_clean, line_idx, sub_idx, next_line_idx, next_sub_idx, line_numbers)
                                line_idx = target_l
                                sub_idx = target_s
                                jumped = True
                                break
                            else:
                                execute_statement(branch_clean, line_numbers)
                        if jumped:
                            continue
                    else:
                        # False and no ELSE: skip entire rest of physical line
                        line_idx += 1
                        sub_idx = 0
                        continue
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx

                else:
                    m_bare_sub = re.match(r"^([A-Za-z][A-Za-z0-9_]*)(?:\s*\((.*?)\)|\s+(.*))?$", sub_stmt.strip())
                    if m_bare_sub and m_bare_sub.group(1).upper() in proc_definitions and not proc_definitions[m_bare_sub.group(1).upper()].get("is_function", False):
                        target_l, target_s = execute_proc_call(sub_stmt, line_idx, sub_idx, next_line_idx, next_sub_idx, line_numbers)
                        line_idx = target_l
                        sub_idx = target_s
                        continue
                    execute_statement(sub_stmt, line_numbers)
                    line_idx = next_line_idx
                    sub_idx = next_sub_idx

            except BASICJump as j:
                if j.is_gosub:
                    gosub_stack.append((next_line_idx, next_sub_idx))
                if j.target_line_idx <= line_idx:
                    now_ticks = pygame.time.get_ticks()
                    if now_ticks - last_display_time >= 15:
                        update_display()
                line_idx = j.target_line_idx
                sub_idx = j.target_sub_idx
                continue
            except BASICStop:
                last_run_index = next_line_idx
                last_sub_index = next_sub_idx
                can_continue = True
                canvas_print(f"9 STOP statement, {ln}:{sub_idx+1}")
                update_display()
                return
            except BASICBreak as b:
                last_run_index = line_idx
                last_sub_index = sub_idx
                can_continue = True
                canvas_print(f"{b.msg}, {ln}:{sub_idx+1}")
                update_display()
                return
            except Exception as e:
                if on_error_trap is not None:
                    trap_ln = on_error_trap
                    line_idx = get_target_line_idx(trap_ln, line_numbers)
                    sub_idx = 0
                    continue
                else:
                    raise e

        can_continue = False
        last_sub_index = 0
    except BASICBreak as b:
        last_run_index = line_idx
        last_sub_index = sub_idx
        can_continue = True
        canvas_print(f"{b.msg}, {ln}:{sub_idx+1}")
        update_display()
        return
    except Exception as e:
        last_run_index = line_idx
        last_sub_index = sub_idx
        can_continue = True
        failed_stmt = program.get(ln, "")
        canvas_print(f"ERROR: {str(e)} at line {ln}: {failed_stmt}")
    finally:
        current_running_line = None
        program_execution_mode = False
        if fullscreen_mode:
            fullscreen_mode = False
            screen = pygame.display.set_mode(windowed_size, pygame.RESIZABLE)
            canvas_dirty = True
            redraw_canvas()
            update_display()
        try:
            pygame.mouse.set_visible(True)
        except Exception:
            pass
        try:
            pygame.key.set_repeat(0)
        except Exception:
            pass




def make_nd_array(dims, fill=0.0):
    if len(dims) == 1:
        return [fill] * (dims[0] + 1)
    return [make_nd_array(dims[1:], fill) for _ in range(dims[0] + 1)]


def handle_sprite_command(stmt_str):
    """
    Executes extended SPRITE commands in BasinPy:
      SPRITE INIT [base_addr]
      SPRITE CLEAR
      SPRITE UPDATE
      SPRITE DRAW
      SPRITE STEP
      SPRITE ON slot [, animated]
      SPRITE OFF slot
      SPRITE POS slot, x, y
      SPRITE MOVE slot, dir, speed
      SPRITE PATH slot, mode, param [, cx, cy]
      SPRITE INK slot, col
      SPRITE REBOUND slot, frames
      SPRITE DEF id FROM start_line
      SPRITE DEF id, frame, b0, b1, ...
      SPRITE ATTR slot, status, def_id, x, y, ink, dir, path_mode, speed, param, rebound
    """
    cmd = stmt_str.strip()
    upper_cmd = cmd.upper()
    if not upper_cmd.startswith("SPRITE"):
        return
    tail = cmd[6:].strip()
    if tail.startswith(":"):
        tail = tail[1:].strip()
    upper_tail = tail.upper()

    if globals().get('current_sprite_mode', 'ZX') == 'NEXT' or globals().get('spectrum_mode', '48K') == 'NEXT':
        handle_next_sprite_command(tail, upper_tail)
        return

    eng = get_sprite_engine(memory_ref=memory)

    if not upper_tail or upper_tail == "STEP":
        eng.step()
        update_display()
        return
    elif upper_tail == "EDIT" or upper_tail.startswith("EDIT ") or upper_tail.startswith("EDIT:"):
        sub_arg = tail[4:].strip()
        if sub_arg.startswith(":"): sub_arg = sub_arg[1:].strip()
        launch_sprite_editor(sub_arg)
        return
    elif upper_tail.startswith("INIT"):
        sub_arg = tail[4:].strip()
        base_addr = int(to_float(evaluate_expr(sub_arg))) if sub_arg else 50000
        eng.init_engine(base_addr=base_addr, memory_ref=memory)
        return
    elif upper_tail == "CLEAR":
        eng.clear_all()
        update_display()
        return
    elif upper_tail == "UPDATE":
        eng.update_all()
        return
    elif upper_tail == "DRAW":
        eng.draw_all()
        update_display()
        return
    elif upper_tail.startswith("ON "):
        args = split_top_level_commas(tail[3:])
        s_id = int(to_float(evaluate_expr(args[0])))
        anim = bool(to_float(evaluate_expr(args[1]))) if len(args) > 1 else False
        def_id = int(to_float(evaluate_expr(args[2]))) if len(args) > 2 else None
        eng.sprite_on(s_id, anim, def_id=def_id)
        return
    elif upper_tail.startswith("USE ") or upper_tail.startswith("SHAPE "):
        cmd_word = "USE " if upper_tail.startswith("USE ") else "SHAPE "
        args = split_top_level_commas(tail[len(cmd_word):])
        if len(args) >= 2:
            s_id = int(to_float(evaluate_expr(args[0])))
            d_id = int(to_float(evaluate_expr(args[1])))
            eng.set_sprite_attr(s_id, def_id=d_id)
        return
    elif upper_tail.startswith("OFF "):
        s_id = int(to_float(evaluate_expr(tail[4:].strip())))
        eng.sprite_off(s_id)
        update_display()
        return
    elif upper_tail.startswith("POS "):
        args = split_top_level_commas(tail[4:])
        if len(args) >= 3:
            s_id = int(to_float(evaluate_expr(args[0])))
            x = int(to_float(evaluate_expr(args[1])))
            y = int(to_float(evaluate_expr(args[2])))
            eng.set_sprite_attr(s_id, x=x, y=y)
        return
    elif upper_tail.startswith("MOVE "):
        args = split_top_level_commas(tail[5:])
        if len(args) >= 3:
            s_id = int(to_float(evaluate_expr(args[0])))
            d = int(to_float(evaluate_expr(args[1])))
            spd = int(to_float(evaluate_expr(args[2])))
            eng.set_sprite_attr(s_id, direction=d, speed=spd)
        return
    elif upper_tail.startswith("PATH "):
        args = split_top_level_commas(tail[5:])
        if len(args) >= 3:
            s_id = int(to_float(evaluate_expr(args[0])))
            mode = int(to_float(evaluate_expr(args[1])))
            param = int(to_float(evaluate_expr(args[2])))
            cx = int(to_float(evaluate_expr(args[3]))) if len(args) > 3 else None
            cy = int(to_float(evaluate_expr(args[4]))) if len(args) > 4 else None
            eng.set_sprite_attr(s_id, path_mode=mode, path_param=param, target_x=cx, target_y=cy)
        return
    elif upper_tail.startswith("INK "):
        args = split_top_level_commas(tail[4:])
        if len(args) >= 2:
            s_id = int(to_float(evaluate_expr(args[0])))
            col = int(to_float(evaluate_expr(args[1])))
            eng.set_sprite_attr(s_id, ink=col)
        return
    elif upper_tail.startswith("REBOUND "):
        args = split_top_level_commas(tail[8:])
        if len(args) >= 2:
            s_id = int(to_float(evaluate_expr(args[0])))
            f = int(to_float(evaluate_expr(args[1])))
            eng.set_sprite_attr(s_id, rebound_frames=f)
        return
    elif upper_tail.startswith("DEF "):
        m_from = re.match(r"^DEF\s+([^,\s]+)\s+FROM\s+(.+)$", tail, re.IGNORECASE)
        if m_from:
            d_id = int(to_float(evaluate_expr(m_from.group(1))))
            start_l = int(to_float(evaluate_expr(m_from.group(2))))
            if not data_pool or not any(item["line"] >= start_l for item in data_pool):
                parse_data_lines()
            vals = [int(to_float(item["val"])) & 0xFF for item in data_pool if item["line"] >= start_l][:128]
            for f in range(4):
                f_bytes = bytes(vals[f * 32 : (f + 1) * 32])
                if len(f_bytes) < 32:
                    f_bytes = f_bytes + bytes(32 - len(f_bytes))
                eng.set_sprite_def(d_id, f, f_bytes)
            return
        args = split_top_level_commas(tail[4:])
        if len(args) >= 3:
            d_id = int(to_float(evaluate_expr(args[0])))
            f_idx = int(to_float(evaluate_expr(args[1])))
            b_vals = [int(to_float(evaluate_expr(a))) & 0xFF for a in args[2:]]
            eng.set_sprite_def(d_id, f_idx, bytes(b_vals))
            return
    elif upper_tail.startswith("ATTR "):
        args = split_top_level_commas(tail[5:])
        if len(args) >= 1:
            s_id = int(to_float(evaluate_expr(args[0])))
            st = int(to_float(evaluate_expr(args[1]))) if len(args) > 1 and args[1].strip() else None
            df = int(to_float(evaluate_expr(args[2]))) if len(args) > 2 and args[2].strip() else None
            x = int(to_float(evaluate_expr(args[3]))) if len(args) > 3 and args[3].strip() else None
            y = int(to_float(evaluate_expr(args[4]))) if len(args) > 4 and args[4].strip() else None
            ink = int(to_float(evaluate_expr(args[5]))) if len(args) > 5 and args[5].strip() else None
            d = int(to_float(evaluate_expr(args[6]))) if len(args) > 6 and args[6].strip() else None
            pm = int(to_float(evaluate_expr(args[7]))) if len(args) > 7 and args[7].strip() else None
            spd = int(to_float(evaluate_expr(args[8]))) if len(args) > 8 and args[8].strip() else None
            param = int(to_float(evaluate_expr(args[9]))) if len(args) > 9 and args[9].strip() else None
            reb = int(to_float(evaluate_expr(args[10]))) if len(args) > 10 and args[10].strip() else None
            eng.set_sprite_attr(s_id, status=st, def_id=df, x=x, y=y, ink=ink, direction=d, path_mode=pm, speed=spd, path_param=param, rebound_frames=reb)
        return
    elif upper_tail.startswith("FLIP "):
        args = split_top_level_commas(tail[5:])
        if len(args) >= 1:
            s_id = int(to_float(evaluate_expr(args[0])))
            fx = bool(to_float(evaluate_expr(args[1]))) if len(args) > 1 else True
            fy = bool(to_float(evaluate_expr(args[2]))) if len(args) > 2 else False
            eng.set_sprite_attr(s_id, flip_x=fx, flip_y=fy)
        return
    elif upper_tail.startswith("ROTATE "):
        args = split_top_level_commas(tail[7:])
        if len(args) >= 2:
            s_id = int(to_float(evaluate_expr(args[0])))
            rot = int(to_float(evaluate_expr(args[1]))) & 0x03
            eng.set_sprite_attr(s_id, rotate=rot)
        return
    elif upper_tail.startswith("LOAD "):
        args = split_top_level_commas(tail[5:])
        fname = str(evaluate_expr(args[0])).strip(' "\'') if args else ""
        canvas_print(f"Loaded sprites from {fname}")
        return
    elif upper_tail == "PRINT":
        canvas_print("Next Sprites printed to canvas")
        return
    elif upper_tail == "STOP":
        eng.active = False
        return
    elif upper_tail in ("CONTINUE", "CONT"):
        eng.active = True
        return
    else:
        # NextBASIC direct sprite placement: SPRITE <id>, <x>, <y> [, <pattern>] [, <palette>] [, <flags>]
        parts = split_top_level_commas(tail)
        if len(parts) >= 3:
            try:
                s_id = int(to_float(evaluate_expr(parts[0])))
                sx = int(to_float(evaluate_expr(parts[1])))
                sy = int(to_float(evaluate_expr(parts[2])))
                sp_pat = int(to_float(evaluate_expr(parts[3]))) if len(parts) > 3 else 0
                eng.sprite_on(s_id, False, def_id=sp_pat)
                eng.set_sprite_attr(s_id, x=sx, y=sy, def_id=sp_pat)
                return
            except Exception:
                pass


def handle_tilemap_command(stmt_str):
    """
    Handles NextBASIC and extended TILEMAP commands:
      TILEMAP ON
      TILEMAP OFF
      TILEMAP DIM <w>, <h>
      TILEMAP <x>, <y>, <tile_id>
      TILEMAP <address> (set base memory location of 1st tile)
    """
    cmd = stmt_str.strip()
    tail = cmd[7:].strip()
    if tail.startswith(":"):
        tail = tail[1:].strip()
    upper_tail = tail.upper()
    if not tail:
        canvas_print("Syntax: TILEMAP ON, TILEMAP OFF, TILEMAP DIM w, h, or TILEMAP <addr>")
        return
    if upper_tail == "ON":
        if get_tilemap_engine:
            eng = get_tilemap_engine()
            eng.active = True
        canvas_print("Tilemap ON")
        return
    if upper_tail == "OFF":
        if get_tilemap_engine:
            eng = get_tilemap_engine()
            eng.active = False
        canvas_print("Tilemap OFF")
        return
    if upper_tail.startswith("DIM "):
        parts = split_top_level_commas(tail[4:])
        if len(parts) >= 2:
            try:
                w = int(to_float(evaluate_expr(parts[0])))
                h = int(to_float(evaluate_expr(parts[1])))
                if get_tilemap_engine:
                    eng = get_tilemap_engine()
                    eng.width = w
                    eng.height = h
                canvas_print(f"Tilemap DIM {w}x{h}")
            except Exception as e:
                canvas_print(f"Invalid TILEMAP DIM: {e}")
        return
    parts = split_top_level_commas(tail)
    if len(parts) >= 3:
        try:
            tx = int(to_float(evaluate_expr(parts[0])))
            ty = int(to_float(evaluate_expr(parts[1])))
            t_id = int(to_float(evaluate_expr(parts[2])))
            if get_tilemap_engine:
                eng = get_tilemap_engine()
                eng.set_tile(tx, ty, t_id)
            return
        except Exception:
            pass
    try:
        addr = int(to_float(evaluate_expr(tail))) & 0xFFFF
        if get_tilemap_engine:
            eng = get_tilemap_engine()
            eng.set_base_address(addr)
    except Exception as e:
        canvas_print(f"Invalid TILEMAP command: {tail}")


def handle_load_tilemap_command(stmt_str):
    """
    Handles LOAD TILEMAP "name" [, address] to load the map into memory as 16x16 tiles.
    """
    cmd = stmt_str.strip()
    m = re.match(r'^LOAD\s+TILEMAP\b\s*(.*)$', cmd, re.IGNORECASE)
    args_str = m.group(1).strip() if m else cmd[12:].strip()
    if args_str.startswith(":"):
        args_str = args_str[1:].strip()
    if not args_str:
        canvas_print('LOAD TILEMAP "name" [, address]')
        return

    parts = split_top_level_commas(args_str)
    file_part = parts[0].strip()
    addr_part = parts[1].strip() if len(parts) > 1 else None

    try:
        filepath = str(evaluate_expr(file_part)).strip(' "\'')
    except Exception:
        filepath = file_part.strip(' "\'')

    addr = None
    if addr_part:
        try:
            addr = int(to_float(evaluate_expr(addr_part))) & 0xFFFF
        except Exception:
            addr = None

    if get_tilemap_engine:
        eng = get_tilemap_engine()
        candidates = [filepath, filepath + ".map", filepath + ".scn", filepath + ".scr"]
        raw_clean = file_part.strip(' "\'')
        candidates.extend([raw_clean, raw_clean + ".map", raw_clean + ".scn", raw_clean + ".scr"])
        candidates.extend([raw_clean.replace('/', '\\'), raw_clean.replace('\\', '/')])
        found = None
        for c in candidates:
            if c and os.path.exists(c) and os.path.isfile(c):
                found = c
                break
        if not found:
            canvas_print(f"File not found: {filepath}")
            return
        try:
            eng.load_map_file(found, address=addr)
            globals()['canvas_dirty'] = True
        except Exception as e:
            canvas_print(f"Error loading tilemap: {e}")


def handle_grab_tiles_command(stmt_str):
    """
    Handles GRAB TILES address, "filename" to populate tile map from screen$ file.
    (also accepts "filename", address or live screen if filename omitted)
    """
    cmd = stmt_str.strip()
    m = re.match(r'^GRAB\s+(?:TILES?|TILEMAP)\b\s*(.*)$', cmd, re.IGNORECASE)
    args_str = m.group(1).strip() if m else ""
    if args_str.startswith(":"):
        args_str = args_str[1:].strip()

    if not args_str:
        if get_tilemap_engine:
            eng = get_tilemap_engine()
            scr_data = bytes(memory[16384:23296])
            eng.grab_from_screen_bytes(scr_data)
            globals()['canvas_dirty'] = True
        return

    parts = split_top_level_commas(args_str)
    p1 = parts[0].strip()
    p2 = parts[1].strip() if len(parts) > 1 else ""

    addr = None
    fname = ""
    raw_fname = ""

    # Check which part is string filename vs numeric address
    if p1.startswith(('"', "'")):
        raw_fname = p1.strip(' "\'')
        try:
            fname = str(evaluate_expr(p1)).strip(' "\'')
        except Exception:
            fname = raw_fname
        if p2:
            try:
                addr = int(to_float(evaluate_expr(p2))) & 0xFFFF
            except Exception:
                addr = None
    elif p2.startswith(('"', "'")):
        raw_fname = p2.strip(' "\'')
        try:
            fname = str(evaluate_expr(p2)).strip(' "\'')
        except Exception:
            fname = raw_fname
        try:
            addr = int(to_float(evaluate_expr(p1))) & 0xFFFF
        except Exception:
            addr = None
    else:
        # Neither starts with an explicit quote
        v1 = None
        try:
            v1 = evaluate_expr(p1)
        except Exception:
            v1 = None

        if isinstance(v1, (int, float)):
            addr = int(to_float(v1)) & 0xFFFF
            if p2:
                raw_fname = p2.strip(' "\'')
                try:
                    fname = str(evaluate_expr(p2)).strip(' "\'')
                except Exception:
                    fname = raw_fname
        else:
            if v1 is not None:
                fname = str(v1).strip(' "\'')
            raw_fname = p1.strip(' "\'')
            if p2:
                try:
                    addr = int(to_float(evaluate_expr(p2))) & 0xFFFF
                except Exception:
                    addr = None

    if get_tilemap_engine:
        eng = get_tilemap_engine()
        if addr is not None:
            eng.set_base_address(addr)

        if fname or raw_fname:
            candidates = []
            for base in [fname, raw_fname]:
                if not base:
                    continue
                candidates.extend([base, base + ".scr", base + ".scn", base + ".map"])
                candidates.extend([base.replace('/', '\\'), base.replace('\\', '/')])
                candidates.extend([base.replace('/', '\\') + ".scr", base.replace('/', '\\') + ".scn", base.replace('/', '\\') + ".map"])
                candidates.extend([base.replace('\\', '/') + ".scr", base.replace('\\', '/') + ".scn", base.replace('\\', '/') + ".map"])

            seen = set()
            uniq_candidates = []
            for c in candidates:
                if c and c not in seen:
                    seen.add(c)
                    uniq_candidates.append(c)

            found = None
            for c in uniq_candidates:
                if os.path.exists(c) and os.path.isfile(c):
                    found = c
                    break
            if not found:
                canvas_print(f"File not found: {raw_fname or fname}")
                return
            try:
                eng.load_map_file(found, address=addr)
            except Exception as e:
                canvas_print(f"Error grabbing tiles: {e}")
        else:
            scr_data = bytes(memory[16384:23296])
            eng.grab_from_screen_bytes(scr_data, address=addr)

        globals()['canvas_dirty'] = True


def execute_place_command(stmt_str):
    """
    Executes custom command PLACE to position a 16x16 tile at a specific location on screen.
    Accepts keywords inline in the same way as PRINT:
    PLACE AT row,col; INK 1; PAPER 0; TILE(x)
    """
    global print_row, print_col, canvas_dirty, current_ink, current_paper, current_bright, current_flash, current_inverse, current_over
    cmd = stmt_str.strip()
    m = re.match(r'^PLACE\b\s*(.*)$', cmd, re.IGNORECASE)
    place_str = m.group(1).strip() if m else cmd[5:].strip()
    if place_str.startswith(":"):
        place_str = place_str[1:].strip()

    if not place_str:
        return

    items_with_sep = []
    current = []
    in_string = False
    paren_depth = 0
    at_mode = False
    comma_count_in_at = 0
    current_sep = None
    i = 0
    n = len(place_str)

    while i < n:
        char = place_str[i]
        if char in ('"', "'"):
            in_string = not in_string
            current.append(char)
        elif not in_string:
            if char == '(':
                paren_depth += 1
                current.append(char)
            elif char == ')':
                paren_depth = max(0, paren_depth - 1)
                current.append(char)
            elif paren_depth == 0:
                curr_str = "".join(current).strip().upper()
                if curr_str.startswith("AT ") or curr_str == "AT":
                    at_mode = True

                if char == ';':
                    at_mode = False
                    comma_count_in_at = 0
                    items_with_sep.append((current_sep, "".join(current).strip()))
                    current = []
                    current_sep = ';'
                elif char == ',':
                    if at_mode:
                        comma_count_in_at += 1
                        if comma_count_in_at >= 2:
                            at_mode = False
                            comma_count_in_at = 0
                            items_with_sep.append((current_sep, "".join(current).strip()))
                            current = []
                            current_sep = ','
                        else:
                            current.append(char)
                    else:
                        items_with_sep.append((current_sep, "".join(current).strip()))
                        current = []
                        current_sep = ','
                else:
                    current.append(char)
            else:
                current.append(char)
        else:
            current.append(char)
        i += 1

    if current:
        items_with_sep.append((current_sep, "".join(current).strip()))

    cur_row = print_row
    cur_col = print_col
    cur_ink = None
    cur_paper = None
    cur_bright = None
    cur_flash = None
    cur_inverse = current_inverse
    cur_over = current_over

    eng = get_tilemap_engine() if get_tilemap_engine else None

    for sep, item in items_with_sep:
        if not item:
            continue
        up = item.upper()
        if up.startswith("AT "):
            coords = split_top_level_commas(item[3:].strip())
            if len(coords) >= 2:
                try:
                    cur_row = int(to_float(evaluate_expr(coords[0])))
                    cur_col = int(to_float(evaluate_expr(coords[1])))
                    print_row = cur_row
                    print_col = cur_col
                except Exception:
                    pass
            continue
        elif up.startswith("INK "):
            try: cur_ink = int(to_float(evaluate_expr(item[4:]))) % 8
            except Exception: pass
            continue
        elif up.startswith("PAPER "):
            try: cur_paper = int(to_float(evaluate_expr(item[6:]))) % 8
            except Exception: pass
            continue
        elif up.startswith("BRIGHT "):
            try: cur_bright = int(to_float(evaluate_expr(item[7:]))) & 1
            except Exception: pass
            continue
        elif up.startswith("FLASH "):
            try: cur_flash = int(to_float(evaluate_expr(item[6:]))) & 1
            except Exception: pass
            continue
        elif up.startswith("INVERSE "):
            try: cur_inverse = bool(int(to_float(evaluate_expr(item[8:]))))
            except Exception: pass
            continue
        elif up.startswith("OVER "):
            try: cur_over = bool(int(to_float(evaluate_expr(item[5:]))))
            except Exception: pass
            continue

        tile_val = None
        m_tile = re.match(r'^TILE\s*\(\s*(.+)\s*\)$', item, re.IGNORECASE)
        if m_tile:
            try:
                tile_val = int(to_float(evaluate_expr(m_tile.group(1))))
            except Exception:
                tile_val = 0
        elif up.startswith("TILE "):
            try:
                tile_val = int(to_float(evaluate_expr(item[5:].strip())))
            except Exception:
                tile_val = 0
        else:
            try:
                ev = evaluate_expr(item)
                if isinstance(ev, (int, float)):
                    tile_val = int(to_float(ev))
            except Exception:
                tile_val = None

        if tile_val is not None and eng is not None:
            if 0 <= tile_val < 192:
                tile_idx = tile_val
            elif eng.base_address <= tile_val < eng.base_address + 192 * 256:
                tile_idx = (tile_val - eng.base_address) // 256
            else:
                tile_idx = tile_val % 192

            eng.render_tile_to_screen(
                tile_idx, cur_row, cur_col,
                ink=cur_ink, paper=cur_paper, bright=cur_bright,
                flash=cur_flash, inverse=cur_inverse, over=cur_over
            )
            cur_col += 2
            if cur_col >= 32:
                cur_col = 0
                cur_row = min(23, cur_row + 2)
            print_row = cur_row
            print_col = cur_col
            canvas_dirty = True


def execute_dpoke_statement(stmt_str):
    args = split_top_level_commas(stmt_str[6:].strip() if stmt_str.upper().startswith("DPOKE ") else stmt_str.strip())
    if len(args) == 2:
        addr = int(to_float(evaluate_expr(args[0]))) & 0xFFFF
        val = int(to_float(evaluate_expr(args[1]))) & 0xFFFF
        zx_poke(addr, val & 0xFF)
        zx_poke((addr + 1) & 0xFFFF, (val >> 8) & 0xFF)


def execute_statement(stmt, line_numbers=None):
    global current_paper, current_ink, current_border, current_bright, current_flash, current_inverse, current_over, current_bold, current_italic, current_underline, current_output_stream, data_pointer, trace_on, current_trace_line, print_row, print_col, canvas_lines
    global variables, string_variables, arrays, user_functions, gosub_stack, for_stack, memory, currah_keyvoice, amx_pointer_visible
    global fullscreen_mode, windowed_size, screen
    global csize_w, csize_h, active_window, defined_windows, proc_definitions, proc_stack, loop_stack, while_stack, repeat_stack, case_stack, on_error_trap, auto_active, auto_next_line, auto_step, clock_display_active
    global forth_interactive_mode, logo_interactive_mode, prolog_interactive_mode, z80_interactive_mode, ram_disk_arrays, active_pattern, def_keys
    global listing_vars_active, listing_code_active, autorun_enabled
    if line_numbers is None:
        line_numbers = sorted(program.keys())

    stmt_raw_upper = stmt.strip().upper()
    if "USR 15619" in stmt_raw_upper or stmt_raw_upper.startswith("RANDOMIZE USR 15619") or stmt_raw_upper.startswith("RAND USR 15619"):
        rem_idx = stmt.upper().find("REM:")
        if rem_idx != -1:
            execute_trdos_command(stmt[rem_idx + 4:].strip())
            return
        rem_idx2 = stmt.upper().find("REM")
        if rem_idx2 != -1:
            execute_trdos_command(stmt[rem_idx2 + 3:].strip())
            return
        else:
            handle_set_drive_command("TRD")
            return

    for sub_stmt in split_statements(stmt):
        stmt_str = sub_stmt.strip()
        while stmt_str.startswith(r'\{') and '}' in stmt_str:
            cb = stmt_str.find('}')
            apply_basin_escapes(stmt_str[2:cb])
            stmt_str = stmt_str[cb+1:].strip()
        while stmt_str.endswith('}') and r'\{' in stmt_str:
            ob = stmt_str.rfind(r'\{')
            apply_basin_escapes(stmt_str[ob+2:-1])
            stmt_str = stmt_str[:ob].strip()
        if not stmt_str:
            continue
        stmt_upper = stmt_str.upper()

        if stmt_upper.startswith("REM"):
            if stmt_upper.startswith("REM:") and active_disk_system in ("TRD", "BETA"):
                execute_trdos_command(stmt_str[4:].strip())
            return
        elif stmt_upper.startswith("*"):
            if active_disk_system in ("TRD", "BETA") and any(stmt_upper.startswith(f'* "{ch}') or stmt_upper.startswith(f'*"{ch}') or stmt_upper.startswith(f"*{ch}") for ch in "ABCD"):
                execute_trdos_command(stmt_str)
                continue
            handle_amx_command(stmt_str, line_numbers)
        elif stmt_str.startswith(".") and not (len(stmt_str) > 1 and stmt_str[1].isdigit()):
            handle_dot_command(stmt_str)
            continue
        elif stmt_str.startswith(":"):
            handle_exdos_colon_command(stmt_str)
            continue
        elif stmt_upper.startswith("LET ") or (
            "=" in stmt_str
            and not stmt_upper.startswith(("IF ", "DEF ", "FOR ", "DIM ", "CONST ", "PRINT ", "INPUT ", "POKE ", "OUT ", "SET ", "SET-", "SETSPRITE", "SETDRIVE", "SETMDR"))
            and (lambda l: l.isidentifier() or (l.endswith("$") and l[:-1].isidentifier()) or (l.endswith(")") and "(" in l))(stmt_str.split("=", 1)[0].strip())
        ):
            assignment_str = stmt_str[4:] if stmt_upper.startswith("LET ") else stmt_str
            parts = assignment_str.split("=", 1)
            if len(parts) == 2:
                lhs = parts[0].strip()
                v_val = evaluate_expr(parts[1])
                match_mem_assign = re.match(r"^MEM(?:ORY)?\$\s*\((.+)\)$", lhs, re.IGNORECASE)
                if match_mem_assign:
                    m_args = split_top_level_commas(match_mem_assign.group(1))
                    addr = int(to_float(evaluate_expr(m_args[0]))) & 0xFFFF
                    length = int(to_float(evaluate_expr(m_args[1]))) if len(m_args) > 1 else len(str(v_val))
                    val_str = str(v_val)
                    for i in range(min(length, len(val_str))):
                        memory[(addr + i) & 0xFFFF] = ord(val_str[i]) & 0xFF
                else:
                    match_str_slice = re.match(r"^(!?[A-Za-z][A-Za-z0-9_]*\$)\s*\((.+)\)$", lhs)
                    if match_str_slice:
                        var_name = match_str_slice.group(1).upper()
                        slice_spec = match_str_slice.group(2).strip()
                        set_string_value(var_name, slice_spec, v_val)
                    else:
                        arr_match = re.match(r"^(!?[A-Za-z][A-Za-z0-9_]*)\s*\((.+)\)$", lhs)
                        if arr_match and not arr_match.group(1).upper().endswith("$"):
                            arr_name = arr_match.group(1).upper()
                            target_table = arrays
                            if arr_name.startswith("!"):
                                target_table = ram_disk_arrays
                            elif arr_name not in arrays and f"!{arr_name}" in ram_disk_arrays:
                                target_table = ram_disk_arrays
                                arr_name = f"!{arr_name}"
                            indices_str = arr_match.group(2)
                            indices = [int(evaluate_expr(ind.strip())) for ind in split_top_level_commas(indices_str)]
                            for idx in indices:
                                if idx < 1:
                                    raise Exception("Subscript out of range")
                            if arr_name not in target_table:
                                target_table[arr_name] = make_nd_array(indices, 0.0)
                            node = target_table[arr_name]
                            for idx in indices[:-1]:
                                if idx >= len(node):
                                    raise Exception("Subscript out of range")
                                node = node[idx]
                            if indices[-1] >= len(node):
                                raise Exception("Subscript out of range")
                            node[indices[-1]] = to_float(v_val)
                        else:
                            v_name = lhs.upper()
                            if v_name.endswith("$"):
                                string_variables[v_name] = str(v_val)
                                if currah_enabled and v_name == "S$":
                                    currah_speak(str(v_val))
                            else:
                                val_f = to_float(v_val)
                                variables[v_name] = val_f
                                if currah_enabled and v_name == "KEYS":
                                    currah_keyvoice = bool(val_f != 0)
        elif stmt_upper.startswith("IF "):
            curr_stmt = stmt_str
            all_true = True
            then_target = None
            else_target = None
            while curr_stmt.upper().startswith("IF "):
                m_if = re.match(r"IF\s+(.+?)\s+THEN\s+(.+)", curr_stmt, re.IGNORECASE)
                if not m_if:
                    break
                cond_expr = m_if.group(1)
                rest_part = m_if.group(2)
                t_part, e_part = split_then_else(rest_part)
                cond_val = evaluate_expr(cond_expr)
                if isinstance(cond_val, str):
                    try: cond_val = to_float(cond_val)
                    except Exception: cond_val = 0.0
                if not cond_val:
                    all_true = False
                    else_target = e_part
                    break
                curr_stmt = t_part.strip()
            if all_true:
                then_target = curr_stmt

            branch = then_target if all_true else else_target
            if branch is not None:
                branch_clean = branch.strip()
                if branch_clean.isdigit():
                    raise BASICJump(get_target_line_idx(int(branch_clean), line_numbers), 0)
                elif branch_clean.upper().startswith("GO TO ") or branch_clean.upper().startswith("GOTO "):
                    pfx = 6 if branch_clean.upper().startswith("GO TO ") else 5
                    target = int(evaluate_expr(branch_clean[pfx:]))
                    raise BASICJump(get_target_line_idx(target, line_numbers), 0)
                elif branch_clean.upper().startswith("GO SUB ") or branch_clean.upper().startswith("GOSUB "):
                    pfx = 7 if branch_clean.upper().startswith("GO SUB ") else 6
                    target = int(evaluate_expr(branch_clean[pfx:]))
                    raise BASICJump(get_target_line_idx(target, line_numbers), 0, is_gosub=True)
                elif branch_clean.upper() == "STOP":
                    raise BASICStop()
                else:
                    execute_statement(branch_clean, line_numbers)
            else:
                # Condition False and no ELSE: skip entire rest of line
                break
        elif stmt_upper == "FRAME" or stmt_upper.startswith("FRAME ") or stmt_upper.startswith("FRAME:"):
            handle_frame_command(stmt_str)
            continue
        elif stmt_upper == "MEM DUMP" or stmt_upper.startswith("MEM DUMP ") or stmt_upper.startswith("MEM DUMP:") or stmt_upper == "DUMP" or stmt_upper.startswith("DUMP ") or stmt_upper.startswith("DUMP:"):
            handle_dump_command(stmt_str)
            continue
        elif stmt_upper == "NEXTREG" or stmt_upper.startswith("NEXTREG ") or stmt_upper.startswith("NEXTREG:") or stmt_upper.startswith("NEXTREG,") or stmt_upper == "REG" or stmt_upper.startswith("REG "):
            handle_nextreg_command(stmt_str)
            continue
        elif stmt_upper == "TURBO" or stmt_upper.startswith("TURBO ") or stmt_upper.startswith("TURBO:"):
            handle_turbo_command(stmt_str)
            continue
        elif stmt_upper == "LAYER" or stmt_upper.startswith("LAYER ") or stmt_upper.startswith("LAYER:"):
            handle_layer_command(stmt_str)
            continue
        elif stmt_upper == "PALETTE" or stmt_upper.startswith("PALETTE ") or stmt_upper.startswith("PALETTE:"):
            handle_palette_command(stmt_str)
            continue
        elif stmt_upper == "LORES" or stmt_upper.startswith("LORES ") or stmt_upper.startswith("LORES:"):
            handle_lores_command(stmt_str)
            continue
        elif stmt_upper == "DRIVER" or stmt_upper.startswith("DRIVER ") or stmt_upper.startswith("DRIVER:"):
            handle_driver_command(stmt_str)
            continue
        elif stmt_upper == "PWD" or stmt_upper.startswith("PWD ") or stmt_upper.startswith("PWD:"):
            handle_pwd_command(stmt_str)
            continue
        elif stmt_upper == "CD" or stmt_upper.startswith("CD ") or stmt_upper.startswith("CD:") or stmt_upper == "CHDIR" or stmt_upper.startswith("CHDIR "):
            handle_cd_command(stmt_str)
            continue
        elif stmt_upper == "MKDIR" or stmt_upper.startswith("MKDIR ") or stmt_upper.startswith("MKDIR:") or stmt_upper == "MD" or stmt_upper.startswith("MD "):
            handle_mkdir_command(stmt_str)
            continue
        elif stmt_upper == "RMDIR" or stmt_upper.startswith("RMDIR ") or stmt_upper.startswith("RMDIR:") or stmt_upper == "RD" or stmt_upper.startswith("RD "):
            handle_rmdir_command(stmt_str)
            continue
        elif stmt_upper.startswith("RENAME ") or stmt_upper == "RENAME" or stmt_upper.startswith("REN ") or stmt_upper == "REN":
            handle_rename_command(stmt_str)
            continue
        elif stmt_upper in ("ZXNEXT", "SPECTRUMNEXT", "NEXTBASIC") or any(stmt_upper.startswith(k + " ") for k in ("ZXNEXT", "SPECTRUMNEXT", "NEXTBASIC")):
            set_zxnext_mode()
            continue
        elif stmt_upper == "STOP":
            raise BASICStop()
        elif stmt_upper == "SPRITE" or stmt_upper.startswith("SPRITE ") or stmt_upper.startswith("SPRITE:"):
            handle_sprite_command(stmt_str)
            continue
        elif stmt_upper == "PLACE" or stmt_upper.startswith("PLACE ") or stmt_upper.startswith("PLACE:"):
            execute_place_command(stmt_str)
            continue
        elif stmt_upper == "TILEMAP" or stmt_upper.startswith("TILEMAP ") or stmt_upper.startswith("TILEMAP:"):
            handle_tilemap_command(stmt_str)
            continue
        elif re.match(r'^LOAD\s+TILEMAP\b', stmt_str, re.IGNORECASE):
            handle_load_tilemap_command(stmt_str)
            continue
        elif re.match(r'^GRAB\s+(?:TILES?|TILEMAP)\b', stmt_str, re.IGNORECASE):
            handle_grab_tiles_command(stmt_str)
            continue
        elif stmt_upper == "INCLUDE" or stmt_upper.startswith("INCLUDE ") or stmt_upper.startswith("INCLUDE:"):
            inc_target = stmt_str[7:].strip()
            if inc_target.startswith(":"):
                inc_target = inc_target[1:].strip()
            target_upper = inc_target.upper()
            if "SPRITE" in target_upper:
                sp_base = DEFAULT_SPRITE_ENGINE_BASE if 'DEFAULT_SPRITE_ENGINE_BASE' in globals() else 50000
                if memory[sp_base] != 0xC3:
                    sp_bin = generate_sprite_engine_binary(sp_base)
                    for i, b in enumerate(sp_bin[:3072]):
                        memory[sp_base + i] = b
                canvas_print(f"Sprite engine included (RAM {sp_base}..{sp_base+3071})")
            elif "TILE" in target_upper:
                tl_base = DEFAULT_TILE_ENGINE_BASE if 'DEFAULT_TILE_ENGINE_BASE' in globals() else 45000
                if memory[tl_base] != 0xC3:
                    tl_bin = generate_tile_engine_binary(base=tl_base, tilemap_base=40000)
                    for i, b in enumerate(tl_bin):
                        memory[tl_base + i] = b
                canvas_print(f"Tilemap engine included (RAM {tl_base}..{tl_base+len(tl_bin)-1})")
            continue
        elif stmt_upper == "FORTH" or stmt_upper.startswith("FORTH ") or stmt_upper.startswith("FORTH:"):
            m_same = re.search(r'\bFORTH\b(.*?)\b(?:END\s+FORTH|ENDFORTH|END_FORTH)\b', stmt_str, re.IGNORECASE)
            if m_same:
                f_code = m_same.group(1).strip()
                if f_code:
                    cached = execute_forth_inline_block(f_code, block_key=("immediate", hash(f_code)))
                    canvas_print(f"Compiled and executed at {cached['address']} (0x{cached['address']:04X})")
                    update_display()
                return
            else:
                tail = stmt_str[5:].strip()
                if tail.startswith(":"): tail = tail[1:].strip()
                if tail:
                    cached = execute_forth_inline_block(tail, block_key=("immediate", hash(tail)))
                    canvas_print(f"Compiled and executed at {cached['address']} (0x{cached['address']:04X})")
                    update_display()
                    return
                else:
                    forth_interactive_mode = True
                    canvas_print("Sinclair FORTH Compiler (fig-FORTH 1.1 / ZX Spectrum 48K)")
                    canvas_print("Commands: SAVE \"name\", FORTH (Export .zxf), END FORTH / BYE (Exit)")
                    canvas_print("OK")
                    update_display()
                    return
        elif stmt_upper == "LOGO" or stmt_upper.startswith("LOGO ") or stmt_upper.startswith("LOGO:"):
            m_same = re.search(r'\bLOGO\b(.*?)\b(?:END\s+LOGO|ENDLOGO|END_LOGO)\b', stmt_str, re.IGNORECASE)
            if m_same:
                l_code = m_same.group(1).strip()
                if l_code:
                    get_logo_engine().interpret(l_code)
                    update_display()
                return
            else:
                tail = stmt_str[4:].strip()
                if tail.startswith(":"): tail = tail[1:].strip()
                if tail:
                    get_logo_engine().interpret(tail)
                    update_display()
                    return
                else:
                    logo_interactive_mode = True
                    canvas_print("Sinclair LOGO (ZX Spectrum 48K/128K)")
                    canvas_print("Type 'END LOGO' or 'BYE' to return to BASIC.")
                    canvas_print("OK")
                    update_display()
                    return
        elif stmt_upper == "PROLOG" or stmt_upper.startswith("PROLOG ") or stmt_upper.startswith("PROLOG:"):
            m_same = re.search(r'\bPROLOG\b(.*?)\b(?:END\s+PROLOG|ENDPROLOG|END_PROLOG)\b', stmt_str, re.IGNORECASE)
            if m_same:
                p_code = m_same.group(1).strip()
                if p_code:
                    get_prolog_engine().interpret(p_code, print_fn=canvas_print)
                    update_display()
                return
            else:
                tail = stmt_str[6:].strip()
                if tail.startswith(":"): tail = tail[1:].strip()
                if tail:
                    get_prolog_engine().interpret(tail, print_fn=canvas_print)
                    update_display()
                    return
                else:
                    prolog_interactive_mode = True
                    canvas_print("Micro-PROLOG 1.0 (Sinclair Research / LPA)")
                    canvas_print("Type 'END PROLOG' or 'BYE' to return to BASIC.")
                    canvas_print("&.")
                    update_display()
                    return
        elif stmt_upper == "Z80" or stmt_upper.startswith("Z80 ") or stmt_upper.startswith("Z80:"):
            m_same = re.search(r'\bZ80\b(.*?)\b(?:END\s+Z80|ENDZ80|END_Z80)\b', stmt_str, re.IGNORECASE)
            if m_same:
                z_code = m_same.group(1).strip()
                if z_code:
                    cached = execute_z80_inline_block(z_code, block_key=("immediate", hash(z_code)))
                    canvas_print(f"Assembled and executed at {cached['address']} (0x{cached['address']:04X})")
                    update_display()
                return
            else:
                tail = stmt_str[3:].strip()
                if tail.startswith(":"): tail = tail[1:].strip()
                if tail:
                    cached = execute_z80_inline_block(tail, block_key=("immediate", hash(tail)))
                    canvas_print(f"Assembled and executed at {cached['address']} (0x{cached['address']:04X})")
                    update_display()
                    return
                else:
                    z80_interactive_mode = True
                    canvas_print("Sinclair ZEUS Z80 Assembler (ZX Spectrum 48K/128K)")
                    canvas_print("Commands: A (Assemble), R (Run), L (List), N (New), D (Delete)")
                    canvas_print("          SAVE <name> (Export .asm & .tap), END Z80 / BYE (Exit)")
                    canvas_print("Z>")
                    update_display()
                    return
        elif stmt_upper == "MONITOR" or stmt_upper.startswith("MONITOR ") or stmt_upper.startswith("MONITOR:") or stmt_upper.startswith("MONITOR(") or stmt_upper == "MON" or stmt_upper.startswith("MON ") or stmt_upper.startswith("MON:"):
            arg = ""
            if stmt_upper.startswith("MONITOR"):
                arg = stmt_str[7:].strip()
            else:
                arg = stmt_str[3:].strip()
            if arg.startswith(":"): arg = arg[1:].strip()
            start_addr = parse_monitor_val(arg) if arg else None
            mon = get_crystal_monitor()
            mon.open(addr=start_addr, origin="BASIC")
            canvas_dirty = True
            update_display()
            return
        elif stmt_upper == "DECOMPILE" or stmt_upper.startswith("DECOMPILE ") or stmt_upper.startswith("DECOMPILE:") or stmt_upper.startswith("DECOMPILE("):
            args = stmt_str[9:].strip()
            if args.startswith(":"): args = args[1:].strip()
            execute_decompile_command(args)
            return
        elif stmt_upper == "ZLOAD" or stmt_upper.startswith("ZLOAD ") or stmt_upper.startswith("ZLOAD:") or stmt_upper.startswith("ZLOAD("):
            args = stmt_str[5:].strip()
            if args.startswith(":"): args = args[1:].strip()
            execute_zload_command(args)
            return
        elif stmt_upper.startswith("ADDRESS ") or stmt_upper.startswith("ADDRESS:"):
            arg = stmt_str[7:].strip()
            if arg.startswith(":"): arg = arg[1:].strip()
            try:
                addr = int(evaluate_expr(arg))
                asm = get_zeus_assembler()
                asm.org_address = addr
                canvas_print(f"Zeus address set to {addr}")
            except Exception:
                canvas_print(f"Invalid address: {arg}")
            update_display()
            return
