def create_tap_block(flag_byte, payload_bytes):
    block_len = 1 + len(payload_bytes) + 1
    checksum = flag_byte
    for b in payload_bytes:
        checksum ^= b
    block = bytearray()
    block.append(block_len & 0xFF)
    block.append((block_len >> 8) & 0xFF)
    block.append(flag_byte)
    block.extend(payload_bytes)
    block.append(checksum)
    return block


def create_tap_code_blocks(filename_str, code_bytes, start_addr=50000):
    data_len = len(code_bytes)
    hdr_payload = bytearray()
    hdr_payload.append(3)  # Type 3: Bytes / Code
    fname_bytes = filename_str[:10].ljust(10, ' ').encode('latin-1', errors='ignore')
    hdr_payload.extend(fname_bytes)
    hdr_payload.append(data_len & 0xFF)
    hdr_payload.append((data_len >> 8) & 0xFF)
    hdr_payload.append(start_addr & 0xFF)
    hdr_payload.append((start_addr >> 8) & 0xFF)
    hdr_payload.append(0x00)
    hdr_payload.append(0x80)  # param 2 = 32768

    hdr_block = create_tap_block(0x00, hdr_payload)
    data_block = create_tap_block(0xFF, code_bytes)
    return hdr_block + data_block


