def encode_sinclair_number(val_str):
    try:
        val = int(val_str)
        if 0 <= val <= 65535:
            return bytes([0x0E, 0x00, 0x00, val & 0xFF, (val >> 8) & 0xFF, 0x00])
        elif -65535 <= val < 0:
            pos_val = -val
            return bytes([0x0E, 0x00, 0xFF, pos_val & 0xFF, (pos_val >> 8) & 0xFF, 0x00])
    except ValueError:
        pass
    return b""


def tokenize_sinclair_line(line_num, text):
    payload = bytearray()
    i = 0
    in_string = False
    in_rem = False
    n = len(text)
    
    while i < n:
        if in_rem:
            payload.extend(text[i:].encode('latin-1', errors='replace'))
            break
            
        ch = text[i]
        
        if ch == '"':
            in_string = not in_string
            payload.append(ord('"'))
            i += 1
            continue
            
        if in_string:
            payload.append(ord(ch) if ord(ch) < 256 else ord('?'))
            i += 1
            continue

        if ch == ' ':
            i += 1
            continue
            
        # Try matching keyword
        matched_kw = False
        remaining = text[i:]
        prev_is_alnum = (i > 0 and (text[i-1].isalnum() or text[i-1] == '_'))
        for kw, token_val in SINCLAIR_KEYWORDS:
            kw_len = len(kw)
            if remaining[:kw_len].upper() == kw:
                if kw[0].isalpha() and prev_is_alnum:
                    continue
                if kw[-1].isalpha() or kw[-1] == '$':
                    if kw_len < len(remaining) and (remaining[kw_len].isalnum() or remaining[kw_len] == '_'):
                        continue
                payload.append(token_val)
                i += kw_len
                if i < n and text[i] == ' ' and kw != "REM":
                    i += 1
                matched_kw = True
                if kw == "REM":
                    in_rem = True
                break
                
        if matched_kw:
            continue
            
        # Try matching number
        num_m = re.match(r'^(\d+)', remaining)
        if num_m:
            num_str = num_m.group(1)
            if i > 0 and (text[i-1].isalnum() or text[i-1] == '_'):
                payload.extend(num_str.encode('ascii'))
            else:
                payload.extend(num_str.encode('ascii'))
                payload.extend(encode_sinclair_number(num_str))
            i += len(num_str)
            continue
            
        payload.append(ord(ch) if ord(ch) < 256 else ord('?'))
        i += 1
        
    payload.append(0x0D)
    line_len = len(payload)
    header = bytes([
        (line_num >> 8) & 0xFF,
        line_num & 0xFF,
        line_len & 0xFF,
        (line_len >> 8) & 0xFF
    ])
    return header + payload


def save_conforming_tap(filepath, prog_dict, filename_str="program", autostart_line=None):
    lines_data = bytearray()
    for ln in sorted(prog_dict.keys()):
        lines_data.extend(tokenize_sinclair_line(ln, prog_dict[ln]))
    
    data_block_len = len(lines_data)
    
    header_payload = bytearray()
    header_payload.append(0)  # Type 0: Program
    fname_bytes = filename_str[:10].ljust(10, ' ').encode('latin-1', errors='ignore')
    header_payload.extend(fname_bytes)
    header_payload.append(data_block_len & 0xFF)
    header_payload.append((data_block_len >> 8) & 0xFF)
    
    auto_ln = 0x8000
    if autostart_line is not None and autostart_line in prog_dict:
        auto_ln = autostart_line
            
    header_payload.append(auto_ln & 0xFF)
    header_payload.append((auto_ln >> 8) & 0xFF)
    header_payload.append(data_block_len & 0xFF)
    header_payload.append((data_block_len >> 8) & 0xFF)
    
    header_block = create_tap_block(0x00, header_payload)
    data_block = create_tap_block(0xFF, lines_data)
    
    with open(filepath, "wb") as f:
        f.write(header_block)
        f.write(data_block)


def create_tap_loader_blocks(loader_lines, filename_str="loader", autostart_line=1):
    if isinstance(loader_lines, (list, tuple)):
        raw_lines = [str(l).strip() for l in loader_lines if str(l).strip()]
    elif isinstance(loader_lines, str):
        if "\n" in loader_lines:
            raw_lines = [l.strip() for l in loader_lines.split("\n") if l.strip()]
        elif ": " in loader_lines:
            raw_lines = [l.strip() for l in loader_lines.split(": ") if l.strip()]
        elif ":" in loader_lines:
            raw_lines = [l.strip() for l in loader_lines.split(":") if l.strip()]
        else:
            raw_lines = [loader_lines.strip()]
    else:
        raw_lines = [str(loader_lines).strip()]

    lines_data = bytearray()
    cur_line = autostart_line if autostart_line is not None else 10
    first_line_num = None
    for l_str in raw_lines:
        m_num = re.match(r'^(\d+)\s+(.+)$', l_str)
        if m_num:
            l_num = int(m_num.group(1))
            l_code = m_num.group(2)
        else:
            l_num = cur_line
            l_code = l_str
            cur_line += 10
        if first_line_num is None:
            first_line_num = l_num
        line_bytes = tokenize_sinclair_line(l_num, l_code)
        lines_data.extend(line_bytes)

    data_block_len = len(lines_data)
    start_ln = autostart_line if autostart_line is not None else (first_line_num if first_line_num is not None else 10)

    header_payload = bytearray()
    header_payload.append(0)  # Type 0: Program
    fname_bytes = filename_str[:10].ljust(10, ' ').encode('latin-1', errors='ignore')
    header_payload.extend(fname_bytes)
    header_payload.append(data_block_len & 0xFF)
    header_payload.append((data_block_len >> 8) & 0xFF)
    header_payload.append(start_ln & 0xFF)
    header_payload.append((start_ln >> 8) & 0xFF)
    header_payload.append(data_block_len & 0xFF)
    header_payload.append((data_block_len >> 8) & 0xFF)

    hdr_block = create_tap_block(0x00, header_payload)
    data_block = create_tap_block(0xFF, lines_data)
    return hdr_block + data_block


def read_tap_blocks(filepath):
    blocks = []
    if not os.path.exists(filepath):
        return blocks
    with open(filepath, "rb") as f:
        data = f.read()
    idx = 0
    while idx + 2 <= len(data):
        blen = data[idx] | (data[idx + 1] << 8)
        total_len = 2 + blen
        if idx + total_len > len(data):
            break
        blocks.append(data[idx : idx + total_len])
        idx += total_len
    return blocks


def populate_sprite_defs_in_engine_binary(sp_bytes, target_prog, base=50000):
    """
    Extracts 16x16 sprite definitions (128 bytes each) from resident engine or target
    program DATA statements and embeds them directly into the sprite engine binary block
    at OFFSET_SPRITE_DEFS (3072). This ensures all sprite definitions are stored as
    machine code data on tape and immediately present in RAM upon loading at 50000.
    """
    defs_offset = 3072  # OFFSET_SPRITE_DEFS in sprite_engine_z80
    try:
        eng = get_sprite_engine()
        if eng and hasattr(eng, "definitions"):
            for d_id, frames in eng.definitions.items():
                if 0 <= d_id < 64:
                    for f_idx in range(min(4, len(frames))):
                        frame_bytes = frames[f_idx]
                        if any(frame_bytes):
                            dst = defs_offset + d_id * 128 + f_idx * 32
                            sp_bytes[dst : dst + 32] = frame_bytes[:32]
    except Exception:
        pass

    if not target_prog:
        return

    # Extract all DATA values mapped by line number
    line_data_pool = {}
    for ln in sorted(target_prog.keys()):
        line_text = target_prog[ln]
        sub_stmts = split_statements(line_text)
        vals = []
        for stmt in sub_stmts:
            stmt_s = stmt.strip()
            if stmt_s.upper().startswith("DATA "):
                data_tail = stmt_s[5:].strip()
                raw_items = split_top_level_commas(data_tail)
                for item in raw_items:
                    item_s = item.strip()
                    try:
                        val = int(round(float(item_s)))
                        vals.append(val & 0xFF)
                    except Exception:
                        pass
        if vals:
            line_data_pool[ln] = vals

    # Match SPRITE DEF <id> FROM <start_line>
    for ln in sorted(target_prog.keys()):
        line_text = target_prog[ln]
        for m in re.finditer(r'\bSPRITE\s+DEF\s+(\d+)\s+FROM\s+(\d+)\b', line_text, re.IGNORECASE):
            d_id = int(m.group(1))
            start_line = int(m.group(2))
            if 0 <= d_id < 64:
                collected = []
                for d_ln in sorted(line_data_pool.keys()):
                    if d_ln >= start_line:
                        collected.extend(line_data_pool[d_ln])
                        if len(collected) >= 128:
                            break
                if collected:
                    bytes_128 = bytes(collected[:128])
                    if len(bytes_128) < 128:
                        bytes_128 = bytes_128 + bytes(128 - len(bytes_128))
                    dst = defs_offset + d_id * 128
                    sp_bytes[dst : dst + 128] = bytes_128

    # Match inline SPRITE DEF <id>, <frame>, <b0>..<b31>
    for ln in sorted(target_prog.keys()):
        line_text = target_prog[ln]
        sub_stmts = split_statements(line_text)
        for stmt in sub_stmts:
            stmt_s = stmt.strip()
            m_bytes = re.match(r'^SPRITE\s+DEF\s+(\d+)\s*,\s*(\d+)\s*,\s*(.+)$', stmt_s, re.IGNORECASE)
            if m_bytes:
                d_id = int(m_bytes.group(1))
                f_idx = int(m_bytes.group(2))
                raw_items = split_top_level_commas(m_bytes.group(3))
                vals = []
                for item in raw_items[:32]:
                    try:
                        val = int(round(float(item.strip())))
                        vals.append(val & 0xFF)
                    except Exception:
                        pass
                if 0 <= d_id < 64 and 0 <= f_idx < 4 and vals:
                    frame_bytes = bytes(vals[:32])
                    if len(frame_bytes) < 32:
                        frame_bytes = frame_bytes + bytes(32 - len(frame_bytes))
                    dst = defs_offset + d_id * 128 + f_idx * 32
                    sp_bytes[dst : dst + 32] = frame_bytes


def make_boriel_beeper_safe(boriel_data, base_addr=24500):
    """
    Patches calls to Sinclair Spectrum 48K ROM BEEPER (CALL 0x03B5 / CD B5 03)
    in Boriel Machine Code by routing them through a small safe wrapper stub
    appended to the binary (CALL 0x03B5; DI; RET).
    This guarantees interrupts are immediately disabled upon return from ROM BEEPER,
    preventing 50Hz maskable interrupts from executing with corrupted IY/system vars
    and corrupting VRAM, attributes, or sprite restore buffers.
    """
    if b'\xCD\xB5\x03' in boriel_data:
        boriel_data = bytearray(boriel_data)
        safe_beeper_addr = (base_addr + len(boriel_data)) & 0xFFFF
        safe_call = bytes([0xCD, safe_beeper_addr & 0xFF, (safe_beeper_addr >> 8) & 0xFF])
        boriel_data = bytearray(bytes(boriel_data).replace(b'\xCD\xB5\x03', safe_call))
        boriel_data.extend([0xCD, 0xB5, 0x03, 0xF3, 0xC9])  # CALL 0x03B5; DI; RET
        return bytes(boriel_data)
    return boriel_data


def inject_sprite_engine_into_tap(tap_filepath, compiled_type, prog_name="program", target_prog=None):
    if not os.path.exists(tap_filepath):
        return
    base = DEFAULT_SPRITE_ENGINE_BASE if 'DEFAULT_SPRITE_ENGINE_BASE' in globals() else 50000
    sp_bytes = generate_sprite_engine_binary(base)
    # Extract sprite definitions (if any)
    sp_data_bytes, num_defs = extract_sprite_defs_data(target_prog, base=base)
    sp_engine_bytes = sp_bytes[:3072]

    existing_blocks = read_tap_blocks(tap_filepath)
    clean_name = re.sub(r'[^A-Za-z0-9_]', '_', prog_name)[:10] or "program"

    if compiled_type == "MC" and len(existing_blocks) >= 4:
        boriel_data = make_boriel_beeper_safe(existing_blocks[3][3:-1])
        max_addr = max(24500 + len(boriel_data), base + len(sp_engine_bytes))
        if sp_data_bytes and num_defs > 0:
            max_addr = max(max_addr, base + 3072 + len(sp_data_bytes))
        payload = bytearray(max_addr - 24500)
        payload[0 : len(boriel_data)] = boriel_data
        payload[base - 24500 : base - 24500 + len(sp_engine_bytes)] = sp_engine_bytes
        if sp_data_bytes and num_defs > 0:
            payload[base + 3072 - 24500 : base + 3072 - 24500 + len(sp_data_bytes)] = sp_data_bytes

        loader_code = '10 CLEAR 24499: 20 LOAD "" CODE: 30 RANDOMIZE USR 24500'
        loader_blocks = create_tap_loader_blocks(loader_code, filename_str="loader", autostart_line=1)
        code_blocks = create_tap_code_blocks(clean_name, bytes(payload), start_addr=24500)
        final_tap = loader_blocks + code_blocks
        with open(tap_filepath, "wb") as f:
            f.write(final_tap)
    else:
        min_addr = base
        max_addr = base + len(sp_engine_bytes)
        if sp_data_bytes and num_defs > 0:
            max_addr = max(max_addr, base + 3072 + len(sp_data_bytes))
        eng_payload = bytearray(max_addr - min_addr)
        eng_payload[0 : len(sp_engine_bytes)] = sp_engine_bytes
        if sp_data_bytes and num_defs > 0:
            eng_payload[3072 : 3072 + len(sp_data_bytes)] = sp_data_bytes
        code_blocks = create_tap_code_blocks("sp_engine", bytes(eng_payload), start_addr=min_addr)
        loader_code = f'10 CLEAR {min_addr - 1}: 20 LOAD "" CODE: 30 LOAD ""'
        loader_blocks = create_tap_loader_blocks(loader_code, filename_str="loader", autostart_line=1)
        final_tap = loader_blocks + code_blocks + b"".join(existing_blocks)
        with open(tap_filepath, "wb") as f:
            f.write(final_tap)


def inject_tilemap_engine_into_tap(tap_filepath, compiled_type, prog_name="program", target_prog=None):
    if not os.path.exists(tap_filepath):
        return

    tile_base = DEFAULT_TILE_ENGINE_BASE if 'DEFAULT_TILE_ENGINE_BASE' in globals() else 45000
    tilemap_base = 40000
    if target_prog:
        for ln, line_text in sorted(target_prog.items()):
            m_tm = re.search(r'\bTILEMAP\s+(\d+)\b', line_text, re.IGNORECASE)
            if m_tm:
                try:
                    tilemap_base = int(m_tm.group(1)) & 0xFFFF
                    break
                except Exception:
                    pass

    tile_bytes = generate_tile_engine_binary(base=tile_base, tilemap_base=tilemap_base)
    tile_data_bytes = extract_tilemap_data(target_prog, tilemap_base=tilemap_base)

    existing_blocks = read_tap_blocks(tap_filepath)
    clean_name = re.sub(r'[^A-Za-z0-9_]', '_', prog_name)[:10] or "program"

    if compiled_type == "MC" and len(existing_blocks) >= 4:
        boriel_data = make_boriel_beeper_safe(existing_blocks[3][3:-1])
        max_addr = max(24500 + len(boriel_data), tile_base + len(tile_bytes))
        if tile_data_bytes:
            max_addr = max(max_addr, tilemap_base + len(tile_data_bytes))
        payload = bytearray(max_addr - 24500)
        payload[0 : len(boriel_data)] = boriel_data
        if tile_data_bytes:
            payload[tilemap_base - 24500 : tilemap_base - 24500 + len(tile_data_bytes)] = tile_data_bytes
        payload[tile_base - 24500 : tile_base - 24500 + len(tile_bytes)] = tile_bytes

        loader_code = '10 CLEAR 24499: 20 LOAD "" CODE: 30 RANDOMIZE USR 24500'
        loader_blocks = create_tap_loader_blocks(loader_code, filename_str="loader", autostart_line=1)
        code_blocks = create_tap_code_blocks(clean_name, bytes(payload), start_addr=24500)
        final_tap = loader_blocks + code_blocks
        with open(tap_filepath, "wb") as f:
            f.write(final_tap)
    else:
        min_addr = min(tile_base, tilemap_base if tile_data_bytes else tile_base)
        max_addr = tile_base + len(tile_bytes)
        if tile_data_bytes:
            max_addr = max(max_addr, tilemap_base + len(tile_data_bytes))
        eng_payload = bytearray(max_addr - min_addr)
        if tile_data_bytes:
            eng_payload[tilemap_base - min_addr : tilemap_base - min_addr + len(tile_data_bytes)] = tile_data_bytes
        eng_payload[tile_base - min_addr : tile_base - min_addr + len(tile_bytes)] = tile_bytes
        code_blocks = create_tap_code_blocks("tl_engine", bytes(eng_payload), start_addr=min_addr)
        loader_code = f'10 CLEAR {min_addr - 1}: 20 LOAD "" CODE: 30 LOAD ""'
        loader_blocks = create_tap_loader_blocks(loader_code, filename_str="loader", autostart_line=1)
        final_tap = loader_blocks + code_blocks + b"".join(existing_blocks)
        with open(tap_filepath, "wb") as f:
            f.write(final_tap)


def bundle_engines_into_tap(tap_filepath, compiled_type, prog_name="program", target_prog=None):
    if not os.path.exists(tap_filepath):
        return

    uses_sprites = target_prog and any(re.search(r'\b(?:SPRITE|COLLISION|INCLUDE\s+SPRITES?)\b', c, re.IGNORECASE) for c in target_prog.values())
    uses_tilemap = target_prog and any(re.search(r'\b(?:TILEMAP|PLACE|TILE\s*\(|LOAD\s+TILEMAP|GRAB\s+TILES?|EDTILES?|TILED|INCLUDE\s+TILEMAPS?)\b', c, re.IGNORECASE) for c in target_prog.values())

    if uses_sprites and not uses_tilemap:
        inject_sprite_engine_into_tap(tap_filepath, compiled_type, prog_name, target_prog)
        return
    if uses_tilemap and not uses_sprites:
        inject_tilemap_engine_into_tap(tap_filepath, compiled_type, prog_name, target_prog)
        return
    if not uses_sprites and not uses_tilemap:
        return

    # BOTH Sprites and Tilemap are used in this program!
    sp_base = DEFAULT_SPRITE_ENGINE_BASE if 'DEFAULT_SPRITE_ENGINE_BASE' in globals() else 50000
    sp_bytes = generate_sprite_engine_binary(sp_base)
    sp_data_bytes, num_defs = extract_sprite_defs_data(target_prog, base=sp_base)
    sp_engine_bytes = sp_bytes[:3072]

    tile_base = DEFAULT_TILE_ENGINE_BASE if 'DEFAULT_TILE_ENGINE_BASE' in globals() else 45000
    tilemap_base = 40000
    if target_prog:
        for ln, line_text in sorted(target_prog.items()):
            m_tm = re.search(r'\bTILEMAP\s+(\d+)\b', line_text, re.IGNORECASE)
            if m_tm:
                try:
                    tilemap_base = int(m_tm.group(1)) & 0xFFFF
                    break
                except Exception:
                    pass

    tile_bytes = generate_tile_engine_binary(base=tile_base, tilemap_base=tilemap_base)
    tile_data_bytes = extract_tilemap_data(target_prog, tilemap_base=tilemap_base)

    existing_blocks = read_tap_blocks(tap_filepath)
    clean_name = re.sub(r'[^A-Za-z0-9_]', '_', prog_name)[:10] or "program"

    if compiled_type == "MC" and len(existing_blocks) >= 4:
        boriel_data = make_boriel_beeper_safe(existing_blocks[3][3:-1])
        end_mc = 24500 + len(boriel_data)
        end_tm_data = tilemap_base + len(tile_data_bytes) if tile_data_bytes else 0
        end_te = tile_base + len(tile_bytes)
        end_se = sp_base + len(sp_engine_bytes)
        end_sp_data = sp_base + 3072 + len(sp_data_bytes) if (sp_data_bytes and num_defs > 0) else 0

        max_addr = max(end_mc, end_tm_data, end_te, end_se, end_sp_data)
        payload = bytearray(max_addr - 24500)
        # 1. Boriel MC at 24500
        payload[0 : len(boriel_data)] = boriel_data
        # 2. Tilemap data
        if tile_data_bytes:
            off = tilemap_base - 24500
            payload[off : off + len(tile_data_bytes)] = tile_data_bytes
        # 3. Tile engine
        off = tile_base - 24500
        payload[off : off + len(tile_bytes)] = tile_bytes
        # 4. Sprite engine
        off = sp_base - 24500
        payload[off : off + len(sp_engine_bytes)] = sp_engine_bytes
        # 5. Sprite defs
        if sp_data_bytes and num_defs > 0:
            off = sp_base + 3072 - 24500
            payload[off : off + len(sp_data_bytes)] = sp_data_bytes

        loader_code = '10 CLEAR 24499: 20 LOAD "" CODE: 30 RANDOMIZE USR 24500'
        loader_blocks = create_tap_loader_blocks(loader_code, filename_str="loader", autostart_line=1)
        code_blocks = create_tap_code_blocks(clean_name, bytes(payload), start_addr=24500)
        final_tap = loader_blocks + code_blocks
        with open(tap_filepath, "wb") as f:
            f.write(final_tap)
    else:
        min_addr = min(tile_base, sp_base, tilemap_base if tile_data_bytes else tile_base)
        end_tm_data = tilemap_base + len(tile_data_bytes) if tile_data_bytes else 0
        end_te = tile_base + len(tile_bytes)
        end_se = sp_base + len(sp_engine_bytes)
        end_sp_data = sp_base + 3072 + len(sp_data_bytes) if (sp_data_bytes and num_defs > 0) else 0
        max_addr = max(end_tm_data, end_te, end_se, end_sp_data)

        eng_payload = bytearray(max_addr - min_addr)
        if tile_data_bytes:
            off = tilemap_base - min_addr
            eng_payload[off : off + len(tile_data_bytes)] = tile_data_bytes
        off = tile_base - min_addr
        eng_payload[off : off + len(tile_bytes)] = tile_bytes
        off = sp_base - min_addr
        eng_payload[off : off + len(sp_engine_bytes)] = sp_engine_bytes
        if sp_data_bytes and num_defs > 0:
            off = sp_base + 3072 - min_addr
            eng_payload[off : off + len(sp_data_bytes)] = sp_data_bytes

        code_blocks = create_tap_code_blocks("engines", bytes(eng_payload), start_addr=min_addr)
        loader_code = f'10 CLEAR {min_addr - 1}: 20 LOAD "" CODE: 30 LOAD ""'
        loader_blocks = create_tap_loader_blocks(loader_code, filename_str="loader", autostart_line=1)
        final_tap = loader_blocks + code_blocks + b"".join(existing_blocks)
        with open(tap_filepath, "wb") as f:
            f.write(final_tap)


def save_program_file(fname, mode, code_start=16384, code_len=6912, data_arr_name=None):
    folder = get_zx_folder()
    fname = fname.replace('"', '').replace("'", '').strip(' "\',;')
    drive_match = re.match(r'^([Mm])\s*([;,]|\d+)\s*[;,]?\s*["\']?(.+)', fname)
    is_microdrive = False
    drive_num = 1
    if drive_match:
        is_microdrive = True
        m_dig = re.search(r'\d+', drive_match.group(2))
        drive_num = int(m_dig.group(0)) if m_dig else 1
        fname = drive_match.group(3).strip('"\'')

    mode_upper = mode.upper() if mode else "PROG"
    rom_ext = ".bin" if fname.lower().endswith(".bin") else ".rom"
    if fname.lower().endswith(".zxb"):
        mode_upper = "ZXB"
        fname = fname[:-4]
    elif fname.lower().endswith(".tap"):
        mode_upper = "TAP"
        fname = fname[:-4]
    elif fname.lower().endswith(".zxbcode"):
        mode_upper = "CODE"
        fname = fname[:-8]
    elif fname.lower().endswith(".dzxdata"):
        mode_upper = "DATA"
        fname = fname[:-8]
    elif fname.lower().endswith(".zxf"):
        mode_upper = "FORTH"
        fname = fname[:-4]
    elif fname.lower().endswith(".rom"):
        mode_upper = "ROM"
        rom_ext = ".rom"
        fname = fname[:-4]
    elif fname.lower().endswith(".bin"):
        mode_upper = "ROM"
        rom_ext = ".bin"
        fname = fname[:-4]

    clean_fs_name = re.sub(r'[<>:"/\\|?*]', '_', fname).strip()
    if not clean_fs_name:
        clean_fs_name = "program"

    simulate_tape_loading_border(operation_name=f"Saving {mode_upper}")

    if mode_upper == "ZXB":
        if is_microdrive:
            canvas_print("ZXB text files not supported on Microdrive (.mdr uses binary sectors)")
            return
        path = os.path.join(folder, f"{clean_fs_name}.zxb")
        cwd_path = os.path.join(os.getcwd(), f"{clean_fs_name}.zxb")
        try:
            with open(path, "w", encoding="utf-8") as f:
                for ln in sorted(program.keys()):
                    f.write(f"{ln} {program[ln]}\n")
            if cwd_path != path:
                with open(cwd_path, "w", encoding="utf-8") as f:
                    for ln in sorted(program.keys()):
                        f.write(f"{ln} {program[ln]}\n")
            canvas_print(f"Saved plain text ZXB {os.path.basename(path)}")
        except Exception as e:
            canvas_print(f"Save error: {e}")
    elif mode_upper == "DATA":
        path = os.path.join(folder, f"{clean_fs_name}.dzxdata")
        import json
        try:
            with open(path, "w", encoding="utf-8") as f:
                if data_arr_name:
                    target_dict = ram_disk_arrays if data_arr_name.startswith("!") else arrays
                    json.dump({"type": "array", "name": data_arr_name, "data": target_dict.get(data_arr_name, [])}, f)
                else:
                    for item in data_pool:
                        f.write(f"{item['val']}\n")
            canvas_print(f"Saved DATA {data_arr_name if data_arr_name else 'block'} {os.path.basename(path)}")
        except Exception as e:
            canvas_print(f"Save error: {e}")
    elif mode_upper == "CODE":
        path = os.path.join(folder, f"{clean_fs_name}.zxbcode")
        try:
            with open(path, "wb") as f:
                f.write(memory[code_start : code_start + code_len])
            canvas_print(f"Saved CODE block {os.path.basename(path)}")
        except Exception as e:
            canvas_print(f"Save error: {e}")
    elif mode_upper == "FORTH":
        cbytes = None
        org_addr = 32768
        forth_blocks = []
        for ln in sorted(program.keys()):
            line_raw = program[ln]
            m_same = re.search(r'\bFORTH\b(.*?)\b(?:END\s+FORTH|ENDFORTH|END_FORTH)\b', line_raw, re.IGNORECASE)
            if m_same:
                fb = m_same.group(1).strip()
                if fb: forth_blocks.append(fb)
            else:
                m_start = re.search(r'\bFORTH\b', line_raw, re.IGNORECASE)
                if m_start:
                    tail = line_raw[m_start.end():].strip()
                    if tail.startswith(":"): tail = tail[1:].strip()
                    if tail and not re.search(r'\b(?:END\s+FORTH|ENDFORTH|END_FORTH)\b', tail, re.IGNORECASE):
                        forth_blocks.append(tail)
                elif re.search(r'\b(?:END\s+FORTH|ENDFORTH|END_FORTH)\b', line_raw, re.IGNORECASE):
                    pass

        if forth_blocks:
            full_forth = "\n".join(forth_blocks)
            compiler = SinclairForthCompiler(org=32768)
            asm_code = compiler.compile(full_forth)
            asm = get_zeus_assembler()
            cbytes = asm.assemble(asm_code, target_memory=memory)
            org_addr = compiler.org
        elif _last_compiled_forth is not None and _last_compiled_forth.get("code_bytes"):
            cbytes = _last_compiled_forth["code_bytes"]
            org_addr = _last_compiled_forth.get("address", 32768)
        else:
            compiler = SinclairForthCompiler(org=32768)
            asm_code = compiler.compile("")
            asm = get_zeus_assembler()
            cbytes = asm.assemble(asm_code, target_memory=memory)
            org_addr = compiler.org

        header = b"ZXF\x01" + struct.pack("<HH", org_addr & 0xFFFF, len(cbytes) & 0xFFFF)
        full_payload = header + cbytes

        path = os.path.join(folder, f"{clean_fs_name}.zxf")
        cwd_path = os.path.join(os.getcwd(), f"{clean_fs_name}.zxf")
        try:
            with open(path, "wb") as f:
                f.write(full_payload)
            if cwd_path != path:
                with open(cwd_path, "wb") as f:
                    f.write(full_payload)
            canvas_print(f"Saved compiled FORTH machine code '{clean_fs_name}.zxf' (origin {org_addr}, {len(cbytes)} bytes)")
        except Exception as e:
            canvas_print(f"Save error: {e}")
    elif mode_upper == "ROM":
        ext = rom_ext if ('rom_ext' in locals() and rom_ext) else (".bin" if fname.lower().endswith(".bin") else ".rom")
        clean_name = fname
        if clean_name.lower().endswith((".rom", ".bin")):
            clean_name = os.path.splitext(clean_name)[0]
        path = os.path.join(folder, f"{clean_name}{ext}")
        cwd_path = os.path.join(os.getcwd(), f"{clean_name}{ext}")
        try:
            rom_data = bytes(memory[0x0000:0x4000])
            with open(path, "wb") as f:
                f.write(rom_data)
            if cwd_path != path:
                with open(cwd_path, "wb") as f:
                    f.write(rom_data)
            canvas_print(f"Saved Interface 2 ROM cartridge '{clean_name}{ext}' (16384 bytes)")
        except Exception as e:
            canvas_print(f"Save error: {e}")
    elif mode_upper == "SCREEN$":
        save_screen_file(clean_fs_name)
    else:
        if is_microdrive:
            mdr_save_program(drive_num, fname, program)
        else:
            path = os.path.join(folder, f"{clean_fs_name}.tap")
            cwd_path = os.path.join(os.getcwd(), f"{clean_fs_name}.tap")
            try:
                save_conforming_tap(path, program, clean_fs_name)
                if cwd_path != path:
                    save_conforming_tap(cwd_path, program, clean_fs_name)
                canvas_print(f"Saved conforming TAP program {os.path.basename(path)}")
            except Exception as e:
                canvas_print(f"Save error: {e}")


def load_program_file(path, mode="", data_arr_name=None, load_source=None):
    global program, data_pool, arrays, program_line_order, autorun_enabled, attached_load_source
    if load_source is not None:
        attached_load_source = load_source
    if 'basic_rom_backup' in globals() and basic_rom_backup:
        memory[0:16384] = basic_rom_backup[:16384]

    path_lower = path.lower()
    # Auto-heal dummy downloads (<= 256 bytes or placeholder BASIC)
    if os.path.exists(path) and not path_lower.endswith((".com", ".bin", ".cpm", ".img", ".imd", ".raw", ".flp", ".bas", ".zxb")) and 'is_dummy_download' in globals() and is_dummy_download(path):
        base_name = os.path.basename(path)
        title_cand = os.path.splitext(base_name)[0]
        ext_cand = None
        if 'identify_zx_file' in globals():
            _, _, ext_cand = identify_zx_file(base_name)
        canvas_print(f"DUMMY FILE DETECTED: {base_name[:16]}")
        canvas_print("SEARCHING INTERNET ARCHIVE...")
        try:
            update_display()
        except Exception:
            pass
        if 'search_and_download_internet_archive' in globals():
            arch_p, arch_fn = search_and_download_internet_archive(
                title_cand,
                preferred_ext=ext_cand,
                status_cb=lambda m: (canvas_print(m), update_display() if 'update_display' in globals() else None)
            )
            if arch_p and os.path.exists(arch_p) and not is_dummy_download(arch_p):
                path = arch_p
                canvas_print(f"REPLACED WITH ARCHIVE: {arch_fn[:16]}")
                try:
                    update_display()
                except Exception:
                    pass

    mode_upper = mode.upper()
    path_lower = path.lower()
    ftype = "Bytes" if (mode_upper in ("SCREEN$", "CODE", "FORTH", "ROM") or path_lower.endswith((".scr", ".zxbcode", ".zxf", ".rom", ".bin"))) else "Program"
    if path_lower.endswith((".tap", ".tzx", ".zip")) or mode_upper in ("TAP", "TAPE"):
        simulate_tape_loading_border(operation_name="Loading", filename=path, file_type=ftype)
    try:

        if path_lower.endswith(".zip"):
            import zipfile
            try:
                with zipfile.ZipFile(path, "r") as zf:
                    extracted_target = None
                    valid_exts = ('.tap', '.tzx', '.z80', '.sna', '.dsk', '.trd', '.scl', '.bas', '.rom', '.bin', '.scr', '.mdr', '.com', '.cpm', '.img', '.imd', '.raw', '.flp')
                    for name in zf.namelist():
                        if name.startswith("__MACOSX") or name.endswith("/"):
                            continue
                        base_n = os.path.basename(name)
                        if not base_n:
                            continue
                        safe_n = re.sub(r'[<>:"/\\|?*]', '_', base_n)
                        m_data = zf.read(name)
                        out_p = os.path.join(os.getcwd(), safe_n)
                        with open(out_p, "wb") as mf:
                            mf.write(m_data)
                        zx_folder = get_zx_folder()
                        if os.path.abspath(zx_folder) != os.path.abspath(os.getcwd()):
                            try:
                                with open(os.path.join(zx_folder, safe_n), "wb") as zxf:
                                    zxf.write(m_data)
                            except Exception:
                                pass
                        for ext in valid_exts:
                            if safe_n.lower().endswith(ext):
                                if extracted_target is None or safe_n.lower().endswith('.tap'):
                                    extracted_target = out_p
                                break
                    if extracted_target and os.path.exists(extracted_target):
                        return load_program_file(extracted_target, mode, data_arr_name)
            except Exception as e:
                canvas_print(f"Zip extraction error: {e}")
                return
        elif mode_upper == "SCREEN$" or path_lower.endswith(("_scr.zxbcode", ".scr")):
            load_screen_file(path)
        elif mode_upper == "ROM" or path_lower.endswith(".rom"):
            if not os.path.exists(path):
                if os.path.exists(f"{path}.rom"):
                    path = f"{path}.rom"
                else:
                    canvas_print(f"File not found: {os.path.basename(path)}")
                    return
            with open(path, "rb") as f:
                data = f.read()
            if len(data) == 0:
                canvas_print(f"Empty ROM file: {os.path.basename(path)}")
                return
            swap_cartridge_rom(data, name=os.path.basename(path))
            canvas_print(f"Loaded Interface 2 ROM cartridge '{cartridge_file_name}' ({len(data)} bytes)")
            handle_system_reset()
            return
        elif path_lower.endswith(".bin"):
            if not os.path.exists(path):
                if os.path.exists(f"{path}.bin"):
                    path = f"{path}.bin"
                else:
                    canvas_print(f"File not found: {os.path.basename(path)}")
                    return
            with open(path, "rb") as f:
                data = f.read()
            if len(data) == 0:
                canvas_print(f"Empty binary file: {os.path.basename(path)}")
                return
            base_n = os.path.basename(path_lower)
            if base_n in ("irc.bin", "irc"):
                launch_irc_client()
                return
            elif base_n in ("gopher.bin", "gopher", "goper.bin", "goper"):
                launch_gopher_client()
                return
            elif base_n.startswith("snapcterm") or base_n in ("term.bin", "term"):
                launch_terminal_emulator()
                return
            org = 32768
            memory[org : org + len(data)] = data
            if not is_execution_mode():
                canvas_print(f"Loaded CODE block {os.path.basename(path)} ({len(data)} bytes at {org})")
            if mode_upper == "RUN":
                try:
                    zx_usr(org)
                except Exception as e:
                    canvas_print(f"Error executing binary: {e}")
            return
        elif path_lower.endswith(".zxbcode") or mode_upper == "CODE":
            with open(path, "rb") as f:
                block = f.read()
                memory[16384 : 16384 + len(block)] = block
            if not is_execution_mode():
                canvas_print(f"Loaded CODE block {os.path.basename(path)}")
        elif path_lower.endswith(".zxf") or mode_upper == "FORTH":
            global _last_compiled_forth
            if not os.path.exists(path):
                if not path.endswith(".zxf") and os.path.exists(f"{path}.zxf"):
                    path = f"{path}.zxf"
                else:
                    canvas_print(f"File not found: {os.path.basename(path)}")
                    return
            with open(path, "rb") as f:
                raw = f.read()
            if len(raw) >= 8 and raw[:4] == b"ZXF\x01":
                org_addr, code_len = struct.unpack("<HH", raw[4:8])
                code_payload = raw[8:8 + code_len]
            else:
                org_addr = 32768
                code_payload = raw
                code_len = len(raw)
            memory[org_addr : org_addr + len(code_payload)] = code_payload
            _last_compiled_forth = {
                "code_bytes": bytes(code_payload),
                "address": org_addr,
                "length": len(code_payload)
            }
            if not is_execution_mode():
                canvas_print(f"Loaded FORTH machine code '{os.path.basename(path)}' ({len(code_payload)} bytes at {org_addr})")
        elif path_lower.endswith(".dzxdata") or mode_upper == "DATA":
            if not os.path.exists(path):
                canvas_print("File not found")
                return
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                content = f.read()
            import json
            try:
                loaded = json.loads(content)
                if isinstance(loaded, dict) and loaded.get("type") == "array":
                    target_name = data_arr_name if data_arr_name else loaded.get("name", "F")
                    target_dict = ram_disk_arrays if target_name.startswith("!") else arrays
                    target_dict[target_name] = loaded.get("data", [])
                    if not is_execution_mode():
                        canvas_print(f"Loaded DATA array {target_name} from {os.path.basename(path)}")
                    return
            except Exception:
                pass
            data_pool.clear()
            for line in content.splitlines():
                val = line.strip()
                if val:
                    try:
                        parsed_val = float(val) if "." in val else int(val)
                    except ValueError:
                        parsed_val = val
                    data_pool.append({"line": 0, "val": parsed_val})
            if not is_execution_mode():
                canvas_print(f"Loaded DATA block {os.path.basename(path)}")
        elif path_lower.endswith(".sna") or mode_upper == "SNA":
            load_sna_snapshot(path)
            return
        elif path_lower.endswith(".z80") or mode_upper == "Z80":
            load_z80_snapshot(path)
            return
        elif path_lower.endswith(".tzx") or mode_upper == "TZX":
            load_tzx_file(path, mode=mode)
            return
        elif path_lower.endswith((".trd", ".scl")) or mode_upper in ("TRD", "SCL"):
            disk = TRDOSDisk(path)
            mgt_drives[mgt_default_drive] = disk
            flist = disk.list_files()
            canvas_print(f"Mounted TR-DOS disk '{os.path.basename(path)}' in Drive {mgt_default_drive} ({len(flist)} files, {disk.get_free_kb()}K free)")
            boot_prog = None
            for f in flist:
                if f["raw_type"] == 'B' and f["name"].strip().lower() in ("boot", "start", "auto", "menu"):
                    boot_prog = f
                    break
            if boot_prog is None and len(flist) == 1 and flist[0]["raw_type"] == 'B':
                boot_prog = flist[0]
            if boot_prog:
                ftype, fdata, fmeta = disk.load_file(boot_prog["name"])
                parsed = parse_bas_file(fdata)
                if parsed:
                    program.clear()
                    _z80_compiled_blocks.clear()
                    if 'program_line_order' in globals():
                        program_line_order.clear()
                    for ln in sorted(parsed.keys()):
                        program[ln] = parsed[ln]
                        if 'program_line_order' in globals():
                            program_line_order.append(ln)
                    parse_data_lines()
                    _split_cache.clear()
                    canvas_print(f"Loaded boot program '{boot_prog['name']}' ({len(parsed)} lines)")
                    if mode_upper == "RUN" or autorun_enabled:
                        run_program(0)
            update_display()
            return
        elif path_lower.endswith(".com") or mode_upper == "COM":
            if not os.path.exists(path):
                canvas_print(f"File not found: {os.path.basename(path)}")
                return
            with open(path, "rb") as f:
                com_data = f.read()
            fn_base = os.path.basename(path).upper()
            cpm = CPMSystem()
            cpm.put_file('A', fn_base, com_data)
            cpm.enter_cpm_mode(initial_cmd=fn_base)
            return
        elif path_lower.endswith((".dsk", ".img", ".imd", ".cpm", ".raw", ".flp")) or mode_upper in ("DSK", "CPM"):
            is_explicit_cpm = (mode_upper == "CPM" or path_lower.endswith((".cpm", ".raw", ".flp")))
            disk = Plus3Disk(path)
            mgt_drives[mgt_default_drive] = disk
            flist = disk.list_files()
            canvas_print(f"Mounted disk '{os.path.basename(path)}' in Drive {mgt_default_drive} ({len(flist)} files, {disk.get_free_kb()}K free)")
            boot_prog = None
            has_com_files = False
            for f in flist:
                fn_u = f["name"].strip().upper()
                if f["type"] == Plus3Disk.TYPE_BASIC and fn_u in ("DISK", "BOOT", "AUTO", "MENU"):
                    boot_prog = f
                    break
                if fn_u.endswith(".COM") or f.get("raw_type") == "C":
                    has_com_files = True
            if boot_prog and not is_explicit_cpm:
                ftype, fdata, fmeta = disk.load_file(boot_prog["name"])
                parsed = parse_bas_file(fdata)
                if parsed:
                    program.clear()
                    _z80_compiled_blocks.clear()
                    if 'program_line_order' in globals():
                        program_line_order.clear()
                    for ln in sorted(parsed.keys()):
                        program[ln] = parsed[ln]
                        if 'program_line_order' in globals():
                            program_line_order.append(ln)
                    parse_data_lines()
                    _split_cache.clear()
                    canvas_print(f"Loaded boot program '{boot_prog['name']}' ({len(parsed)} lines)")
                    if mode_upper == "RUN" or autorun_enabled:
                        run_program(0)
            elif is_explicit_cpm or (not boot_prog and has_com_files):
                cpm = CPMSystem()
                try:
                    cpm_disk = CPMDiskImage.load(path)
                    cpm.mounted_disks['A'] = cpm_disk
                    for cfn, cdata in cpm_disk.get_files().items():
                        cpm.put_file('A', cfn, cdata, sync_disk=False)
                    cpm.enter_cpm_mode()
                except Exception as e:
                    canvas_print(f"CP/M Mount error: {e}")
            update_display()
            return
        elif path_lower.endswith(".bas") or mode_upper == "BAS":
            load_bas_program(path, mode=mode)
            return
        elif path_lower.endswith(".zxb"):
            program.clear()
            _z80_compiled_blocks.clear()
            if 'program_line_order' in globals():
                program_line_order.clear()
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    parts = line.split(" ", 1)
                    if len(parts) == 2 and parts[0].isdigit():
                        ln = int(parts[0])
                        program[ln] = parts[1]
                        if 'program_line_order' in globals() and ln not in program_line_order:
                            program_line_order.append(ln)
            if not program:
                cur_ln = 10
                with open(path, "r", encoding="utf-8", errors="ignore") as f:
                    for line in f:
                        line = line.strip()
                        if not line:
                            continue
                        program[cur_ln] = line
                        if 'program_line_order' in globals():
                            program_line_order.append(cur_ln)
                        cur_ln += 10
            parse_data_lines()
            _split_cache.clear()
            if not is_execution_mode():
                canvas_print(f"Loaded ZXB text {os.path.basename(path)}")
                canvas_dirty = True
                redraw_canvas()
                update_display()
            if mode_upper == "RUN":
                run_program(0)
            return
        else:
            program.clear()
            _z80_compiled_blocks.clear()
            if 'program_line_order' in globals():
                program_line_order.clear()
            global tape_data_blocks, tape_block_index, tape_named_blocks, last_loaded_code_bytes, last_loaded_code_addr, last_loaded_screen_bytes
            global tape_raw_blocks, tape_raw_index, tape_block_headers
            tape_data_blocks.clear()
            tape_raw_blocks = []
            tape_raw_index = 0
            tape_block_headers = []
            tape_block_index = 0
            tape_named_blocks.clear()
            last_loaded_code_bytes = None
            last_loaded_code_addr = None
            last_loaded_screen_bytes = None
            auto_run = False
            autorun_ln = None
            
            with open(path, "rb") as bf:
                content_bytes = bf.read()
            
            is_binary_tap = False
            parsed_lines_from_tap = {}
            if (path_lower.endswith(".tap") or mode_upper == "TAP") and len(content_bytes) > 2:
                pos = 0
                block_type = None
                load_address = 16384
                hdr_name = ""
                prog_len = None
                try:
                    while pos < len(content_bytes):
                        if pos + 2 > len(content_bytes):
                            break
                        block_len = content_bytes[pos] + (content_bytes[pos+1] * 256)
                        pos += 2
                        if pos + block_len > len(content_bytes):
                            break
                        block_data = content_bytes[pos : pos + block_len]
                        pos += block_len
                        
                        if len(block_data) > 0:
                            flag = block_data[0]
                            payload = block_data[1:-1]
                            tape_raw_blocks.append((flag, bytes(payload)))
                            
                            if flag == 0:  # Header block
                                if len(payload) >= 15:
                                    block_type = payload[0]  # 0 = Program, 3 = Code
                                    hdr_name = payload[1:11].decode('latin-1', errors='ignore').strip()
                                    load_address = payload[13] | (payload[14] << 8)
                                    if block_type == 0:
                                        prog_len = payload[15] | (payload[16] << 8) if len(payload) >= 17 else None
                                        if load_address < 32768:
                                            autorun_ln = load_address
                                            auto_run = True
                                        parsed_lines_from_tap.clear()
                                        if 'program_line_order' in globals():
                                            program_line_order.clear()
                            elif flag == 255:  # Data block
                                tape_data_blocks.append(bytes(payload))
                                tape_block_headers.append((block_type, load_address, hdr_name))
                                clean_k = hdr_name.lower() if hdr_name else ""
                                if clean_k:
                                    tape_named_blocks[clean_k] = (block_type if block_type is not None else 3, load_address, bytes(payload))
                                if block_type == 0:  # BASIC Program block
                                    tape_block_index = len(tape_data_blocks)
                                    tape_raw_index = len(tape_raw_blocks)
                                    prog_base = 23755
                                    prog_limit = min(prog_len, len(payload)) if (prog_len is not None and prog_len > 0) else len(payload)
                                    if prog_base + len(payload) <= len(memory):
                                        memory[prog_base : prog_base + len(payload)] = payload
                                        memory[23635] = prog_base & 0xFF
                                        memory[23636] = (prog_base >> 8) & 0xFF
                                        vars_addr = prog_base + prog_limit
                                        memory[23627] = vars_addr & 0xFF
                                        memory[23628] = (vars_addr >> 8) & 0xFF
                                        memory[23641] = vars_addr & 0xFF
                                        memory[23642] = (vars_addr >> 8) & 0xFF
                                    is_tokenized = False
                                    if len(payload) >= 4:
                                        test_ln = (payload[0] << 8) | payload[1]
                                        test_len = payload[2] | (payload[3] << 8)
                                        if 0 <= test_ln <= 65535 and test_len > 0 and (test_len + 4 <= len(payload) + 1):
                                            is_tokenized = True
                                    if is_tokenized:
                                        t_pos = 0
                                        while t_pos < prog_limit:
                                            if t_pos + 4 > prog_limit:
                                                break
                                            ln = (payload[t_pos] << 8) | payload[t_pos+1]
                                            llen = payload[t_pos+2] | (payload[t_pos+3] << 8)
                                            if llen <= 0 or t_pos + 4 + llen > prog_limit:
                                                if llen > 0 and t_pos + 4 + llen <= len(payload):
                                                    line_bytes = payload[t_pos + 4 : t_pos + 4 + llen]
                                                    t_pos += 4 + llen
                                                else:
                                                    break
                                            elif payload[t_pos + 4 + llen - 1] != 13 and (prog_limit == len(payload) or t_pos + 4 + llen != prog_limit):
                                                break
                                            else:
                                                t_pos += 4
                                                line_bytes = payload[t_pos : t_pos + llen]
                                                t_pos += llen
                                            res = []
                                            i = 0
                                            while i < len(line_bytes):
                                                c = line_bytes[i]
                                                if c == 14:  # Sinclair 5-byte number marker
                                                    i += 6
                                                    continue
                                                if c == 13:  # Enter
                                                    break
                                                if c in SINCLAIR_TOKENS:
                                                    kw = SINCLAIR_TOKENS[c]
                                                    if res and res[-1] and (res[-1][-1].isalnum() or res[-1][-1] in ('=', '<', '>', ':')):
                                                        res.append(" ")
                                                    res.append(kw + " ")
                                                elif 32 <= c < 127:
                                                    res.append(chr(c))
                                                i += 1
                                            code_str = "".join(res).strip()
                                            if code_str and 0 <= ln <= 65535:
                                                m_mc = re.match(r'^((?:RANDOMIZE\s+USR|CLEAR)\s+(?:VAL\s*"[^"]*"|\d+))(.*)$', code_str, re.IGNORECASE)
                                                if m_mc and m_mc.group(2) and not m_mc.group(2).strip().startswith(':'):
                                                    code_str = m_mc.group(1)
                                                parsed_lines_from_tap[ln] = code_str
                                                if 'program_line_order' in globals() and ln not in program_line_order:
                                                    program_line_order.append(ln)
                                                is_binary_tap = True
                                    else:
                                        try:
                                            clean_bytes = bytes(b if 32 <= b < 127 or b in (10, 13, 9) else 32 for b in payload)
                                            decoded = clean_bytes.decode('latin-1', errors='ignore')
                                            for line_candidate in decoded.split('\r'):
                                                line_candidate = line_candidate.replace('\n', '').replace('\x00', '').strip()
                                                if not line_candidate:
                                                    continue
                                                match = re.match(r'^(\d+)\s+(.+)$', line_candidate)
                                                if match:
                                                    ln = int(match.group(1))
                                                    code_str = match.group(2).strip()
                                                    if 0 <= ln <= 65535:
                                                        parsed_lines_from_tap[ln] = code_str
                                                        if 'program_line_order' in globals() and ln not in program_line_order:
                                                            program_line_order.append(ln)
                                                        is_binary_tap = True
                                        except:
                                            pass
                                elif block_type == 3:  # CODE binary block
                                    target_addr = load_address & 0xFFFF
                                    last_loaded_code_bytes = bytes(payload)
                                    last_loaded_code_addr = target_addr
                                    if target_addr >= 16384 and target_addr + len(payload) <= len(memory):
                                        memory[target_addr : target_addr + len(payload)] = payload
                                        if (target_addr == 16384 or (clean_k and clean_k in ('p', 'screen', 'scr'))) and len(payload) >= 6144:
                                            last_loaded_screen_bytes = bytes(payload)
                                            load_screen_bytes(payload)
                                        if not is_execution_mode():
                                            canvas_print(f"Loaded CODE block at {target_addr} ({len(payload)} bytes)")
                                        is_binary_tap = True
                                    elif target_addr < 16384:
                                        is_binary_tap = True
                                elif block_type is None:
                                    if len(payload) == 6912 and last_loaded_screen_bytes is None:
                                        last_loaded_screen_bytes = bytes(payload)
                                block_type = None
                                hdr_name = ""
                except Exception:
                    pass

            if 'basic_rom_backup' in globals() and basic_rom_backup:
                memory[0:16384] = basic_rom_backup[:16384]

            has_speedloader = bool(
                len(tape_raw_blocks) > 2 or
                len(tape_data_blocks) > 2 or
                ext in ('.tzx', '.pzx') or
                (not parsed_lines_from_tap and (len(tape_raw_blocks) > 0 or len(tape_data_blocks) > 0))
            )
            if has_speedloader:
                if run_simulated_tape_load(path, mode=mode):
                    return

            if is_binary_tap and parsed_lines_from_tap:
                for ln, code_str in parsed_lines_from_tap.items():
                    program[ln] = code_str
                parse_data_lines()
                _split_cache.clear()
                if not is_execution_mode():
                    canvas_print(f"Loaded conforming TAP {os.path.basename(path)}")
                    canvas_dirty = True
                    redraw_canvas()
                    update_display()
                if (autorun_enabled and auto_run) or mode_upper == "RUN":
                    target_idx = 0
                    if autorun_ln is not None and autorun_ln in program:
                        line_nums = program_line_order if ('program_line_order' in globals() and program_line_order and all(k in program for k in program_line_order)) else sorted(program.keys())
                        target_idx = get_target_line_idx(autorun_ln, line_nums)
                    elif program:
                        target_idx = 0
                    if 'basic_rom_backup' in globals() and basic_rom_backup:
                        memory[0:16384] = basic_rom_backup[:16384]
                    run_program(target_idx)
            else:

                text_lines = content_bytes.decode('utf-8', errors='ignore').splitlines()
                for line in text_lines:
                    line = line.strip()
                    if not line:
                        continue
                    if line.startswith("AUTORUN="):
                        m_ar = re.match(r'^AUTORUN=(\d+)', line)
                        if m_ar:
                            autorun_ln = int(m_ar.group(1))
                        auto_run = True
                        continue
                    if line.startswith("TYPE=") or line.startswith("NAME="):
                        continue
                    m_ln = re.match(r'^(\d+)\s*(.*)$', line)
                    if m_ln:
                        ln = int(m_ln.group(1))
                        code_part = m_ln.group(2)
                        program[ln] = code_part
                        if 'program_line_order' in globals() and ln not in program_line_order:
                            program_line_order.append(ln)
                        m_save = re.search(r'\bSAVE\s+.*?\s+LINE\s+(\d+)', code_part, re.IGNORECASE)
                        if m_save and autorun_ln is None:
                            autorun_ln = int(m_save.group(1))
                            auto_run = True
                parse_data_lines()
                _split_cache.clear()
                if not is_execution_mode():
                    canvas_print(f"Loaded {os.path.basename(path)}")
                    canvas_dirty = True
                    redraw_canvas()
                    update_display()
                if (autorun_enabled and auto_run) or mode_upper == "RUN":
                    target_idx = 0
                    if autorun_ln is not None and autorun_ln in program:
                        line_nums = program_line_order if ('program_line_order' in globals() and program_line_order and all(k in program for k in program_line_order)) else sorted(program.keys())
                        target_idx = get_target_line_idx(autorun_ln, line_nums)
                    elif program:
                        target_idx = 0
                    if 'basic_rom_backup' in globals() and basic_rom_backup:
                        memory[0:16384] = basic_rom_backup[:16384]
                    run_program(target_idx)
    except Exception as e:
        canvas_print(f"Load error: {e}")


def verify_program_file(path):
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            file_lines = [line.strip() for line in f if line.strip() and not line.startswith("AUTORUN=") and not line.startswith("TYPE=")]
        prog_lines = [f"{ln} {program[ln]}" for ln in sorted(program.keys())]
        if file_lines == prog_lines:
            canvas_print("OK")
        else:
            canvas_print("Failed")
    except Exception as e:
        canvas_print(f"Verify error: {e}")


def merge_program_file(path):
    global program
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("AUTORUN=") or line.startswith("TYPE="):
                    continue
                parts = line.split(" ", 1)
                if len(parts) == 2 and parts[0].isdigit():
                    program[int(parts[0])] = parts[1]
        canvas_print(f"Merged {os.path.basename(path)}")
    except Exception as e:
        canvas_print(f"Merge error: {e}")


def renumber_line_content(stmt_line, line_map):
    result_segments = []
    in_quote = False
    quote_char = None
    i = 0
    n = len(stmt_line)
    stmt_start = 0

    while i < n:
        c = stmt_line[i]
        if c in ('"', "'"):
            if in_quote and c == quote_char:
                in_quote = False
                quote_char = None
            elif not in_quote:
                in_quote = True
                quote_char = c
            i += 1
        elif not in_quote:
            rem_match = False
            if stmt_line[i:i+3].upper() == "REM":
                before_ok = (i == 0 or stmt_line[i-1].isspace() or stmt_line[i-1] == ':')
                after_ok = (i + 3 >= n or stmt_line[i+3].isspace() or stmt_line[i+3] == ':')
                if before_ok and after_ok:
                    rem_match = True

            if rem_match:
                code_part = stmt_line[stmt_start:i]
                rem_part = stmt_line[i:]
                result_segments.append(process_code_statements(code_part, line_map))
                result_segments.append(rem_part)
                return "".join(result_segments)

            i += 1
        else:
            i += 1

    code_part = stmt_line[stmt_start:]
    result_segments.append(process_code_statements(code_part, line_map))
    return "".join(result_segments)


def process_code_statements(code_str, line_map):
    statements = []
    delimiters = []
    in_quote = False
    quote_char = None
    curr = []
    i = 0
    n = len(code_str)

    while i < n:
        c = code_str[i]
        if c in ('"', "'"):
            if in_quote and c == quote_char:
                in_quote = False
                quote_char = None
            elif not in_quote:
                in_quote = True
                quote_char = c
            curr.append(c)
            i += 1
        elif not in_quote and c == ':':
            statements.append("".join(curr))
            delimiters.append(":")
            curr = []
            i += 1
        else:
            curr.append(c)
            i += 1
    statements.append("".join(curr))

    processed = []
    for stmt in statements:
        s_strip = stmt.strip()
        if s_strip.upper().startswith("DATA ") or s_strip.upper() == "DATA":
            processed.append(stmt)
        else:
            processed.append(renumber_single_statement(stmt, line_map))

    res = []
    for idx, stmt in enumerate(processed):
        res.append(stmt)
        if idx < len(delimiters):
            res.append(delimiters[idx])
    return "".join(res)


def renumber_single_statement(stmt, line_map):
    chunks = []
    in_quote = False
    quote_char = None
    curr = []
    i = 0
    n = len(stmt)

    while i < n:
        c = stmt[i]
        if c in ('"', "'"):
            if in_quote and c == quote_char:
                curr.append(c)
                chunks.append((True, "".join(curr)))
                curr = []
                in_quote = False
                quote_char = None
            elif not in_quote:
                if curr:
                    chunks.append((False, "".join(curr)))
                    curr = []
                curr.append(c)
                in_quote = True
                quote_char = c
            i += 1
        else:
            curr.append(c)
            i += 1
    if curr:
        chunks.append((in_quote, "".join(curr)))

    out_chunks = []
    for is_str, text in chunks:
        if is_str:
            out_chunks.append(text)
        else:
            out_chunks.append(transform_code_chunk(text, line_map))

    return "".join(out_chunks)


def update_number_list(match_numbers, line_map):
    def repl_num(m):
        val = int(m.group(0))
        if val in line_map:
            return str(line_map[val])
        return m.group(0)
    return re.sub(r'\b\d+\b', repl_num, match_numbers)


def transform_code_chunk(text, line_map):
    def repl_goto_gosub(m):
        keyword = m.group(1)
        ws = m.group(2)
        nums = m.group(3)
        return f"{keyword}{ws}{update_number_list(nums, line_map)}"

    pattern_goto = r'\b(GO\s*TO|GOTO|GO\s*SUB|GOSUB)(\s+)(\d+(?:\s*,\s*\d+)*)\b(?!\s*[\+\-\*\/\^])'
    text = re.sub(pattern_goto, repl_goto_gosub, text, flags=re.IGNORECASE)

    pattern_cmds = r'\b(RESTORE|RUN|LLIST|LIST)(\s+)(\d+)\b(?!\s*[\+\-\*\/\^])'
    def repl_cmd(m):
        cmd = m.group(1)
        ws = m.group(2)
        num = int(m.group(3))
        new_num = line_map.get(num, num)
        return f"{cmd}{ws}{new_num}"
    text = re.sub(pattern_cmds, repl_cmd, text, flags=re.IGNORECASE)

    pattern_line = r'\b(LINE)(\s+)(\d+)\b(?!\s*[\+\-\*\/\^])'
    def repl_line(m):
        kw = m.group(1)
        ws = m.group(2)
        num = int(m.group(3))
        new_num = line_map.get(num, num)
        return f"{kw}{ws}{new_num}"
    text = re.sub(pattern_line, repl_line, text, flags=re.IGNORECASE)

    pattern_then_else = r'\b(THEN|ELSE)(\s+)(\d+)\b(?!\s*[\+\-\*\/\^])'
    def repl_then_else(m):
        kw = m.group(1)
        ws = m.group(2)
        num = int(m.group(3))
        new_num = line_map.get(num, num)
        return f"{kw}{ws}{new_num}"
    text = re.sub(pattern_then_else, repl_then_else, text, flags=re.IGNORECASE)

    pattern_on_err = r'\b(ON\s+ERROR\s+GO\s*TO|ON\s+ERROR\s+GOTO)(\s+)(\d+)\b'
    def repl_on_err(m):
        kw = m.group(1)
        ws = m.group(2)
        num = int(m.group(3))
        return f"{kw}{ws}{line_map.get(num, num)}"
    text = re.sub(pattern_on_err, repl_on_err, text, flags=re.IGNORECASE)

    text_strip = text.strip()
    if text_strip.isdigit():
        num = int(text_strip)
        if num in line_map:
            l_space = text[:len(text) - len(text.lstrip())]
            r_space = text[len(text.rstrip()):]
            text = f"{l_space}{line_map[num]}{r_space}"

    return text


def handle_renumber_command(args_part=""):
    global program, listing_scroll_index, current_trace_line
    if listing_edit_active:
        commit_listing_edit(advance=False)

    start = 10
    step = 10

    if args_part:
        parts = [p.strip() for p in re.split(r'[, ]+', args_part.strip()) if p.strip()]
        if len(parts) == 1:
            try:
                start = int(evaluate_expr(parts[0]))
            except Exception as e:
                canvas_print(f"Invalid start line: {e}")
                return
        elif len(parts) == 2:
            try:
                start = int(evaluate_expr(parts[0]))
                step = int(evaluate_expr(parts[1]))
            except Exception as e:
                canvas_print(f"Invalid arguments: {e}")
                return
        else:
            canvas_print("Syntax: RENUMBER [start] [, step]")
            return

    if start < 1 or step < 1:
        canvas_print("Error: Start and step must be >= 1")
        return

    old_lines = sorted(program.keys())
    if not old_lines:
        canvas_print("0 OK")
        return

    max_new_ln = start + (len(old_lines) - 1) * step
    if max_new_ln > 9999:
        canvas_print(f"Error: Line number {max_new_ln} exceeds 9999")
        return

    line_map = {}
    for i, old_ln in enumerate(old_lines):
        line_map[old_ln] = start + (i * step)

    new_program = {}
    for old_ln in old_lines:
        new_ln = line_map[old_ln]
        new_text = renumber_line_content(program[old_ln], line_map)
        new_program[new_ln] = new_text

    program = new_program
    parse_data_lines()
    _split_cache.clear()

    if current_trace_line is not None and current_trace_line in line_map:
        current_trace_line = line_map[current_trace_line]

    listing_scroll_index = 0
    canvas_print(f"Renumbered {len(old_lines)} lines ({start} to {max_new_ln} step {step})")
    update_display()


def handle_delete_command(args_str):
    global program, _split_cache
    if not args_str.strip():
        return
    m_to = re.match(r"^(\d+)\s+TO\s+(\d+)$", args_str.strip(), re.IGNORECASE)
    if m_to:
        start_l = int(m_to.group(1))
        end_l = int(m_to.group(2))
    else:
        parts = split_top_level_commas(args_str)
        if len(parts) == 2:
            start_l = int(to_float(evaluate_expr(parts[0])))
            end_l = int(to_float(evaluate_expr(parts[1])))
        elif len(parts) == 1:
            start_l = int(to_float(evaluate_expr(parts[0])))
            end_l = start_l
        else:
            canvas_print("Syntax: DELETE start TO end")
            return
    deleted_count = 0
    for ln in list(program.keys()):
        if start_l <= ln <= end_l:
            del program[ln]
            deleted_count += 1
    parse_data_lines()
    _split_cache.clear()
    canvas_print(f"Deleted {deleted_count} lines")
    update_display()


def handle_alter_command(args_str):
    global program, _split_cache
    m_to = re.search(r'\bTO\b', args_str, re.IGNORECASE)
    if m_to:
        old_part = args_str[:m_to.start()].strip()
        new_part = args_str[m_to.end():].strip()
        if (old_part.startswith('"') and old_part.endswith('"')) or (old_part.startswith("'") and old_part.endswith("'")):
            old_str = old_part[1:-1]
        else:
            old_str = old_part
        if (new_part.startswith('"') and new_part.endswith('"')) or (new_part.startswith("'") and new_part.endswith("'")):
            new_str = new_part[1:-1]
        else:
            new_str = new_part
        count = 0
        for ln in sorted(program.keys()):
            if old_str in program[ln]:
                program[ln] = program[ln].replace(old_str, new_str)
                count += 1
        parse_data_lines()
        _split_cache.clear()
        canvas_print(f"Altered {count} lines")
        update_display()
    else:
        handle_alter_screen(args_str)


def handle_find_command(args_str):
    global find_active, find_prompt_active, find_query, find_matches, find_match_idx, listing_scroll_index, input_text, input_cursor_pos
    query = args_str.strip()
    if (query.startswith('"') and query.endswith('"')) or (query.startswith("'") and query.endswith("'")):
        query = query[1:-1]

    if not query:
        canvas_print('Syntax: FIND "string"')
        find_active = False
        find_prompt_active = False
        update_display()
        return

    line_nums = sorted(program.keys())
    matches = [ln for ln in line_nums if query in program[ln]]
    if not matches:
        matches = [ln for ln in line_nums if query.upper() in program[ln].upper()]

    if not matches:
        canvas_print(f"Not found: {query}")
        find_active = False
        find_prompt_active = False
        update_display()
        return

    find_matches = matches
    find_match_idx = 0
    find_query = query
    find_active = True
    find_prompt_active = True
    input_text = ""
    input_cursor_pos = 0

    first_ln = find_matches[0]
    listing_scroll_index = line_nums.index(first_ln)
    safe_code = program[first_ln].replace('\x00', '')
    canvas_print(f"Found {first_ln}: {safe_code}")
    update_display()


def find_next():
    global find_active, find_prompt_active, find_matches, find_match_idx, listing_scroll_index, input_text, input_cursor_pos, find_suppress_textinput
    if not find_active or not find_matches:
        find_stop()
        return
    find_suppress_textinput = True
    input_text = ""
    input_cursor_pos = 0
    find_match_idx += 1
    line_nums = sorted(program.keys())
    if find_match_idx < len(find_matches):
        ln = find_matches[find_match_idx]
        if ln in line_nums:
            listing_scroll_index = line_nums.index(ln)
        safe_code = program[ln].replace('\x00', '')
        canvas_print(f"Found {ln}: {safe_code}")
        update_display()
    else:
        canvas_print("End of search")
        find_stop()


def find_stop():
    global find_active, find_prompt_active, find_matches, find_match_idx, find_query, input_text, input_cursor_pos, find_suppress_textinput
    find_active = False
    find_prompt_active = False
    find_matches = []
    find_match_idx = 0
    find_query = ""
    input_text = ""
    input_cursor_pos = 0
    find_suppress_textinput = True
    canvas_print("0 OK")
    update_display()


def handle_replace_command(args_str):
    global program, _split_cache, listing_scroll_index
    args_clean = args_str.strip()
    m_to = re.search(r'\bTO\b', args_clean, re.IGNORECASE)
    if m_to:
        old_part = args_clean[:m_to.start()].strip()
        new_part = args_clean[m_to.end():].strip()
    else:
        parts = split_top_level_commas(args_clean)
        if len(parts) == 2:
            old_part = parts[0].strip()
            new_part = parts[1].strip()
        elif ',' in args_clean:
            parts = args_clean.split(',', 1)
            old_part = parts[0].strip()
            new_part = parts[1].strip()
        else:
            canvas_print('Syntax: REPLACE "old", "new"')
            update_display()
            return

    if (old_part.startswith('"') and old_part.endswith('"')) or (old_part.startswith("'") and old_part.endswith("'")):
        old_str = old_part[1:-1]
    else:
        old_str = old_part

    if (new_part.startswith('"') and new_part.endswith('"')) or (new_part.startswith("'") and new_part.endswith("'")):
        new_str = new_part[1:-1]
    else:
        new_str = new_part

    if not old_str:
        canvas_print('Syntax: REPLACE "old", "new"')
        update_display()
        return

    count = 0
    line_nums = sorted(program.keys())
    for ln in line_nums:
        if old_str in program[ln]:
            program[ln] = program[ln].replace(old_str, new_str)
            count += 1

    parse_data_lines()
    _split_cache.clear()
    if '_z80_compiled_blocks' in globals():
        _z80_compiled_blocks.clear()

    listing_scroll_index = 0
    canvas_print("--- PROGRAM LISTING ---")
    for ln in sorted(program.keys()):
        safe_code = program[ln].replace('\x00', '')
        canvas_print(f"{ln} {safe_code}")
    canvas_print(f"Replaced in {count} line(s)")
    update_display()


