VALID_ZX_FORMATS = {
    'tap': ('TAP', 'Tape (TAP)', '.tap'),
    'tzx': ('TZX', 'Tape (TZX)', '.tzx'),
    'z80': ('Z80', 'Snapshot (Z80)', '.z80'),
    'sna': ('SNA', 'Snapshot (SNA)', '.sna'),
    'dsk': ('DSK', '+3 Disk (DSK)', '.dsk'),
    'trd': ('TRD', 'TR-DOS Disk (TRD)', '.trd'),
    'scl': ('SCL', 'TR-DOS Disk (SCL)', '.scl'),
    'bas': ('BAS', 'BASIC Program (BAS)', '.bas'),
    'rom': ('ROM', 'Cartridge/ROM (ROM)', '.rom'),
    'bin': ('BIN', 'Binary Data (BIN)', '.bin'),
    'scr': ('SCR', 'Screen Image (SCR)', '.scr'),
    'mdr': ('MDR', 'Microdrive (MDR)', '.mdr'),
}

def identify_zx_file(path, format_hint=""):
    """
    Identifies if a file path or format hint corresponds to a supported ZX Spectrum format.
    Handles archive suffixes (.zip, .gz, etc.) to uncover the true format.
    Returns (fmt_code, fmt_label, primary_ext) or (None, None, None).
    """
    p = (path or "").lower()
    hint = (format_hint or "").lower()

    for arch_ext in ('.zip', '.gz', '.bz2', '.tar', '.rar', '.7z'):
        if p.endswith(arch_ext):
            p = p[:-len(arch_ext)]
            break

    ext = os.path.splitext(p)[1].lstrip('.')
    if ext in VALID_ZX_FORMATS:
        return VALID_ZX_FORMATS[ext]

    for k, v in VALID_ZX_FORMATS.items():
        if f".{k}" in p or f"({k})" in hint or f" {k}" in hint or f"({k.upper()})" in hint:
            return v

    return None, None, None


