def is_dummy_download(target):
    """
    Returns True if target (file path or bytes) represents a dummy placeholder or error page.
    """
    if target is None:
        return True
    if isinstance(target, str):
        if not os.path.exists(target):
            return False
        try:
            sz = os.path.getsize(target)
            if sz == 0:
                return True
            if sz > 512:
                with open(target, "rb") as f:
                    head = f.read(256).lower()
                if b"<!doctype" in head or b"<html" in head or b"<head" in head or b"404 not found" in head or b"403 forbidden" in head:
                    return True
                return False
            with open(target, "rb") as f:
                data = f.read(512)
        except Exception:
            return False
    elif isinstance(target, (bytes, bytearray)):
        data = bytes(target)
        sz = len(data)
    else:
        return False

    if sz <= 256:
        return True
    low = data[:512].lower()
    if (b"<!doctype" in low or b"<html" in low or b"<head" in low or 
        b"404 not found" in low or b"403 forbidden" in low or b"access denied" in low):
        return True
    if b"10 print" in low and (b"stop" in low or b"dummy" in low):
        return True
    return False


def search_external_archives(query, source="ALL", preferred_ext=None, max_results=40):
    """
    Searches external archives (Internet Archive, World of Spectrum mirrors)
    for ZX Spectrum software files matching query.
    Returns a list of candidate file dictionaries.
    """
    import urllib.request
    import urllib.parse
    import json
    import ssl

    clean_query = re.sub(r'[<>:"/\\|?*]', ' ', query).strip()
    if not clean_query:
        return []

    ssl_ctx = ssl._create_unverified_context()
    candidates = []
    seen_urls = set()

    pref = (preferred_ext or "").lower()
    if pref and not pref.startswith("."):
        pref = "." + pref

    # 1. Internet Archive (archive.org)
    if source in ("ALL", "ARCHIVE_ORG"):
        words = [w for w in re.split(r'[\s_\-\+\(\)\[\]]+', clean_query) if len(w) > 1 and w.lower() not in ('the', 'and', 'for', 'part', 'edition', '128k', '48k', '16k', 'tap', 'tzx', 'z80', 'sna', 'zip')]
        word_query = " ".join(words) if words else clean_query

        queries = [
            f'title:("{clean_query}") AND (zx OR spectrum)',
            f'"{clean_query}" AND mediatype:software',
            f'title:("{word_query}") AND (zx OR spectrum)',
            f'{word_query} ZX Spectrum'
        ]
        if words and len(words) > 1:
            queries.append(f'title:("{words[0]}") AND (zx OR spectrum)')

        seen_idents = set()
        for q in queries:
            if len(candidates) >= max_results:
                break
            q_enc = urllib.parse.quote(q)
            url = f'https://archive.org/advancedsearch.php?q={q_enc}&fl[]=identifier,title,mediatype&rows=8&output=json'
            req = urllib.request.Request(url, headers={'User-Agent': 'BasinPy/1.0 (Sinclair ZX Spectrum IDE)'})
            try:
                with urllib.request.urlopen(req, context=ssl_ctx, timeout=6) as res:
                    res_data = json.loads(res.read().decode('utf-8'))
                docs = res_data.get('response', {}).get('docs', [])
                for doc in docs:
                    if len(candidates) >= max_results:
                        break
                    ident = doc.get('identifier', '')
                    if not ident or ident in seen_idents:
                        continue
                    seen_idents.add(ident)
                    doc_title = doc.get('title', '')
                    ident_low = ident.lower()
                    if 'pc' in ident_low and 'zx' not in ident_low and 'spectrum' not in ident_low:
                        continue

                    meta_url = f'https://archive.org/metadata/{ident}'
                    meta_req = urllib.request.Request(meta_url, headers={'User-Agent': 'BasinPy/1.0 (Sinclair ZX Spectrum IDE)'})
                    try:
                        with urllib.request.urlopen(meta_req, context=ssl_ctx, timeout=6) as m_res:
                            m_data = json.loads(m_res.read().decode('utf-8'))
                    except Exception:
                        continue

                    for f in m_data.get('files', []):
                        fn = f.get('name', '')
                        fn_low = fn.lower()
                        sz = int(f.get('size', 0) or 0)
                        if sz < 256:
                            continue
                        for ext in ('.tap', '.tzx', '.z80', '.sna', '.dsk', '.trd', '.scl', '.zip'):
                            if fn_low.endswith(ext):
                                if pref and not fn_low.endswith(pref) and not fn_low.endswith('.zip'):
                                    continue
                                dl_url = f"https://archive.org/download/{ident}/{urllib.parse.quote(fn)}"
                                if dl_url in seen_urls:
                                    continue
                                seen_urls.add(dl_url)
                                fmt_code, fmt_label, found_ext = identify_zx_file(fn)
                                sz_k = f"{(sz + 1023) // 1024}K"
                                candidates.append({
                                    'filename': fn,
                                    'size': sz,
                                    'size_str': sz_k,
                                    'format': fmt_code or (ext[1:].upper() if ext != '.zip' else 'ZIP'),
                                    'ext': found_ext or ext,
                                    'archive': 'Archive.org',
                                    'url': dl_url,
                                    'ident': ident,
                                    'title': doc_title or clean_query
                                })
                                break
            except Exception:
                pass

    # 2. World of Spectrum / Spectrum Computing Mirrors
    if source in ("ALL", "WOS_MIRRORS"):
        try:
            encoded = urllib.parse.quote(clean_query)
            zx_api = f"https://api.zxinfo.dk/v3/search?query={encoded}&mode=compact&size=15"
            req = urllib.request.Request(zx_api, headers={'User-Agent': 'BasinPy/1.0 (Sinclair ZX Spectrum IDE)'})
            with urllib.request.urlopen(req, timeout=6) as res:
                raw_data = json.loads(res.read().decode('utf-8'))
            hits = raw_data.get('hits', {}).get('hits', [])
            for h in hits:
                src = h.get('_source', {})
                t_name = src.get('title', '')
                for rel in src.get('releases', []):
                    for f in rel.get('files', []):
                        p = f.get('path', '')
                        if not p:
                            continue
                        fn = os.path.basename(p)
                        fn_low = fn.lower()
                        sz = int(f.get('size', 0) or 0)
                        if pref and not fn_low.endswith(pref) and not fn_low.endswith('.zip'):
                            continue
                        url = p if (p.startswith("http://") or p.startswith("https://")) else f"https://spectrumcomputing.co.uk{p}"
                        if url in seen_urls:
                            continue
                        seen_urls.add(url)
                        fmt_code, fmt_label, found_ext = identify_zx_file(p, f.get('format', ''))
                        sz_k = f"{(sz + 1023) // 1024}K" if sz else "ZX"
                        candidates.append({
                            'filename': fn,
                            'size': sz,
                            'size_str': sz_k,
                            'format': fmt_code or 'TAP',
                            'ext': found_ext or '.tap',
                            'archive': 'WoS Mirror',
                            'url': url,
                            'ident': t_name or clean_query,
                            'title': t_name or clean_query
                        })
        except Exception:
            pass

    # 3. ZX-Art (zxart.ee)
    if source in ("ALL", "ZXART"):
        try:
            encoded = urllib.parse.quote(clean_query)
            zxart_api = f"https://zxart.ee/api/types:zxRelease/export:zxRelease/language:eng/start:0/limit:20/filter:zxReleaseSearch={encoded};"
            req = urllib.request.Request(zxart_api, headers={'User-Agent': 'BasinPy/1.0 (Sinclair ZX Spectrum IDE)'})
            with urllib.request.urlopen(req, context=ssl_ctx, timeout=6) as res:
                raw_data = json.loads(res.read().decode('utf-8'))
            rels = raw_data.get('responseData', {}).get('zxRelease', [])
            for rel in rels:
                fl_url = rel.get('file', '')
                if not fl_url:
                    continue
                fn = rel.get('fileName') or os.path.basename(fl_url)
                fn_low = fn.lower()
                if pref and not fn_low.endswith(pref) and not fn_low.endswith('.zip'):
                    continue
                if fl_url in seen_urls:
                    continue
                seen_urls.add(fl_url)
                rel_title = rel.get('title') or clean_query
                fmt_list = rel.get('releaseFormat', [])
                fmt_hint = fmt_list[0] if fmt_list else ''
                fmt_code, fmt_label, found_ext = identify_zx_file(fn, fmt_hint)
                sz = int(rel.get('size', 0) or 0)
                sz_k = f"{(sz + 1023) // 1024}K" if sz else "ZXArt"
                candidates.append({
                    'filename': fn,
                    'size': sz,
                    'size_str': sz_k,
                    'format': fmt_code or (fmt_hint.upper() if fmt_hint else 'TAP'),
                    'ext': found_ext or ('.' + fmt_hint.lower() if fmt_hint else '.tap'),
                    'archive': 'ZX-Art',
                    'url': fl_url,
                    'ident': rel_title,
                    'title': rel_title
                })
        except Exception:
            pass

    # Deduplicate by filename
    unique_candidates = []
    seen_fns = set()
    for c in candidates:
        fn_key = c['filename'].lower()
        if fn_key not in seen_fns:
            seen_fns.add(fn_key)
            unique_candidates.append(c)

    def cand_sort_key(c):
        ext = c['ext'].lower()
        if pref and ext == pref:
            p_score = 0
        elif ext == '.tap':
            p_score = 1
        elif ext == '.tzx':
            p_score = 2
        elif ext == '.z80':
            p_score = 3
        elif ext == '.sna':
            p_score = 4
        elif ext == '.dsk':
            p_score = 5
        elif ext == '.zip':
            p_score = 6
        else:
            p_score = 7
        return (p_score, c['filename'].lower())

    unique_candidates.sort(key=cand_sort_key)
    return unique_candidates[:max_results]


def download_archive_file_candidate(candidate, clean_title="software", preferred_ext=None, status_cb=None):
    """
    Downloads a specific software file candidate discovered from external archives,
    extracts zip contents if needed, and saves to current folder and ZX folder.
    """
    import urllib.request
    import urllib.parse
    import ssl
    import zipfile
    import io

    url = candidate.get("url")
    fn = candidate.get("filename") or f"{clean_title}.tap"
    ext = candidate.get("ext") or ".tap"
    if not ext.startswith("."):
        ext = "." + ext

    ssl_ctx = ssl._create_unverified_context()

    def advise(msg):
        if status_cb:
            try:
                status_cb(msg)
            except Exception:
                pass
        try:
            if 'canvas_print' in globals() and not zxdb_browser_active:
                canvas_print(msg)
                if 'update_display' in globals():
                    update_display()
        except Exception:
            pass
        print(f"[Archive Downloader] {msg}")

    advise(f"DOWNLOADING {fn[:16]}...")
    req = urllib.request.Request(url, headers={'User-Agent': 'BasinPy/1.0 (Sinclair ZX Spectrum IDE)'})
    dl_data = None
    try:
        with urllib.request.urlopen(req, context=ssl_ctx, timeout=20) as res:
            dl_data = res.read()
    except Exception as e:
        advise(f"DOWNLOAD FAILED: {e}")
        return None, None

    if not dl_data or is_dummy_download(dl_data):
        advise("DOWNLOADED DATA IS DUMMY/CORRUPT")
        return None, None

    zx_folder = get_zx_folder()
    out_bytes = None
    out_filename = fn

    # Check if zip archive
    if dl_data.startswith(b"PK\x03\x04") or fn.lower().endswith(".zip"):
        try:
            safe_zip_fn = re.sub(r'[<>:"/\\|?*]', '_', fn)
            if not safe_zip_fn.lower().endswith(".zip"):
                safe_zip_fn += ".zip"
            zip_dest = os.path.join(os.getcwd(), safe_zip_fn)
            with open(zip_dest, "wb") as zf_save:
                zf_save.write(dl_data)
            if os.path.abspath(zx_folder) != os.path.abspath(os.getcwd()) and os.path.exists(zx_folder):
                try:
                    with open(os.path.join(zx_folder, safe_zip_fn), "wb") as zf_zx:
                        zf_zx.write(dl_data)
                except Exception:
                    pass

            zf = zipfile.ZipFile(io.BytesIO(dl_data))
            members = [m for m in zf.namelist() if not m.startswith("__MACOSX") and not m.endswith("/")]
            target_member = None
            if preferred_ext:
                p_low = preferred_ext.lower()
                for m in members:
                    if m.lower().endswith(p_low):
                        target_member = m
                        break
            if not target_member:
                for m in members:
                    if any(m.lower().endswith(ve) for ve in ('.tap', '.tzx', '.z80', '.sna', '.dsk', '.trd', '.scl')):
                        target_member = m
                        break
            if not target_member and members:
                target_member = members[0]

            for name in members:
                base_n = os.path.basename(name)
                if not base_n:
                    continue
                safe_n = re.sub(r'[<>:"/\\|?*]', '_', base_n)
                m_bytes = zf.read(name)
                with open(os.path.join(os.getcwd(), safe_n), "wb") as mf:
                    mf.write(m_bytes)
                if os.path.abspath(zx_folder) != os.path.abspath(os.getcwd()) and os.path.exists(zx_folder):
                    try:
                        with open(os.path.join(zx_folder, safe_n), "wb") as zxf:
                            zxf.write(m_bytes)
                    except Exception:
                        pass
                if name == target_member:
                    out_bytes = m_bytes
                    out_filename = safe_n
        except Exception:
            pass

    if out_bytes is None:
        out_bytes = dl_data
        out_filename = re.sub(r'[<>:"/\\|?*]', '_', fn)

    dest_path = os.path.join(os.getcwd(), out_filename)
    with open(dest_path, "wb") as f:
        f.write(out_bytes)

    if os.path.abspath(zx_folder) != os.path.abspath(os.getcwd()) and os.path.exists(zx_folder):
        try:
            with open(os.path.join(zx_folder, out_filename), "wb") as zxf:
                zxf.write(out_bytes)
        except Exception:
            pass

    advise(f"SAVED: {out_filename[:20]}")
    return dest_path, out_filename


def search_and_download_internet_archive(title, preferred_ext=None, status_cb=None):
    """
    Searches external archives for ZX Spectrum software matching title,
    advises user of progress, downloads the authentic file,
    and returns (saved_path, filename) or (None, None).
    """
    clean_title = re.sub(r'[<>:"/\\|?*]', '_', title).strip() or "software"
    candidates = search_external_archives(clean_title, source="ARCHIVE_ORG", preferred_ext=preferred_ext)
    if not candidates:
        candidates = search_external_archives(clean_title, source="ZXART", preferred_ext=preferred_ext)
    if not candidates:
        candidates = search_external_archives(clean_title, source="ALL", preferred_ext=preferred_ext)
    if not candidates:
        if status_cb:
            status_cb("NO ALTERNATE COPY FOUND ON ARCHIVES")
        return None, None
    return download_archive_file_candidate(candidates[0], clean_title=clean_title, preferred_ext=preferred_ext, status_cb=status_cb)


class ZXDBSearchEngine:
    def __init__(self):
        self.cached_results = {}

    def search(self, query=""):
        q = (query or "").strip()
        if q in self.cached_results:
            return list(self.cached_results[q])

        results = []
        if q:
            try:
                import urllib.request
                import urllib.parse
                import json
                encoded = urllib.parse.quote(q)
                url = f"https://api.zxinfo.dk/v3/search?query={encoded}&mode=compact&size=50"
                req = urllib.request.Request(url, headers={'User-Agent': 'BasinPy/1.0 (Sinclair ZX Spectrum IDE)'})
                with urllib.request.urlopen(req, timeout=6) as response:
                    raw_data = json.loads(response.read().decode('utf-8'))
                hits = raw_data.get('hits', {}).get('hits', [])
                for h in hits:
                    src = h.get('_source', {})
                    title = src.get('title', '').strip()
                    if not title:
                        continue
                    year = str(src.get('originalYearOfRelease', ''))
                    pubs = src.get('publishers', [])
                    pub_name = (pubs[0].get('name') if pubs and isinstance(pubs[0], dict) else '') or ''
                    files = []
                    for rel in src.get('releases', []):
                        rel_origin = rel.get('origin', '')
                        for f in rel.get('files', []):
                            p = f.get('path', '')
                            fmt_hint = f.get('format', '')
                            fmt_code, fmt_label, ext = identify_zx_file(p, fmt_hint)
                            if fmt_code:
                                files.append({
                                    'path': p,
                                    'size': f.get('size', 0),
                                    'format': fmt_hint or fmt_label,
                                    'fmt_code': fmt_code,
                                    'ext': ext,
                                    'origin': rel_origin
                                })
                    if files:
                        results.append({
                            'title': title,
                            'year': year,
                            'publisher': pub_name,
                            'id': h.get('_id', ''),
                            'files': files,
                            'selected_file': files[0],
                            'taps': files,
                            'selected_tap': files[0]
                        })
            except Exception:
                pass

            # 2. Backup search on ZX-Art if ZXDB returns no results
            if not results:
                try:
                    import urllib.request
                    import urllib.parse
                    import json
                    import ssl
                    ssl_ctx = ssl._create_unverified_context()
                    encoded = urllib.parse.quote(q)
                    zxart_url = f"https://zxart.ee/api/types:zxRelease/export:zxRelease/language:eng/start:0/limit:20/filter:zxReleaseSearch={encoded};"
                    req = urllib.request.Request(zxart_url, headers={'User-Agent': 'BasinPy/1.0 (Sinclair ZX Spectrum IDE)'})
                    with urllib.request.urlopen(req, context=ssl_ctx, timeout=6) as response:
                        raw_data = json.loads(response.read().decode('utf-8'))
                    rels = raw_data.get('responseData', {}).get('zxRelease', [])
                    entries_by_title = {}
                    for rel in rels:
                        t = rel.get('title', '').strip()
                        if not t:
                            continue
                        fl_url = rel.get('file', '')
                        if not fl_url:
                            continue
                        fn = rel.get('fileName') or fl_url.split('/')[-1]
                        fmt_list = rel.get('releaseFormat', [])
                        fmt_hint = fmt_list[0] if fmt_list else ''
                        fmt_code, fmt_label, ext = identify_zx_file(fn, fmt_hint)
                        if not fmt_code:
                            fmt_code = fmt_hint.upper() if fmt_hint else 'TAP'
                            ext = '.' + fmt_hint.lower() if fmt_hint else '.tap'
                        year = str(rel.get('year') or '')
                        file_obj = {
                            'path': fl_url,
                            'size': 0,
                            'format': fmt_code,
                            'fmt_code': fmt_code,
                            'ext': ext,
                            'origin': 'ZX-Art'
                        }
                        if t not in entries_by_title:
                            entry = {
                                'title': t,
                                'year': year,
                                'publisher': 'ZX-Art Archive',
                                'id': f"zxart_{rel.get('id', '')}",
                                'files': [file_obj],
                                'selected_file': file_obj,
                                'taps': [file_obj],
                                'selected_tap': file_obj
                            }
                            entries_by_title[t] = entry
                            results.append(entry)
                        else:
                            entries_by_title[t]['files'].append(file_obj)
                except Exception:
                    pass

        if results:
            self.cached_results[q] = results
            return results

        # Offline fallback matching query
        q_lower = q.lower()
        filtered_fallback = []
        for item in FALLBACK_ZXDB_TITLES:
            if not q_lower or q_lower in item['title'].lower() or q_lower in item['publisher'].lower():
                copy_item = dict(item)
                filtered_fallback.append(copy_item)

        return filtered_fallback

    def download_from_zxdb_info(self, path, title="software", preferred_ext=None, status_cb=None):
        """
        Attempts to download directly from the primary ZXDB repository using the file info.
        Returns (dest_path, filename) on success, or (None, reason_str) on failure.
        """
        import urllib.request
        import zipfile
        import io
        clean_title = re.sub(r'[<>:"/\\|?*]', '_', title).strip() or "software"

        def advise(msg):
            if status_cb:
                try:
                    status_cb(msg)
                except Exception:
                    pass
            try:
                if 'canvas_print' in globals() and not zxdb_browser_active:
                    canvas_print(msg)
                    if 'update_display' in globals():
                        update_display()
            except Exception:
                pass
            print(f"[ZXDB Info] {msg}")

        # Check if path is empty or explicitly distribution denied on ZXDB
        if not path or str(path).startswith("/denied/") or "denied" in str(path).lower():
            advise("DISTRIBUTION DENIED ON ZXDB")
            return None, "DISTRIBUTION DENIED ON ZXDB"

        if path.startswith("http://") or path.startswith("https://"):
            url = path
        else:
            url = f"https://spectrumcomputing.co.uk{path}"

        _, _, inferred_ext = identify_zx_file(path)
        target_ext = preferred_ext or inferred_ext or ".tap"
        if not target_ext.startswith('.'):
            target_ext = '.' + target_ext

        out_bytes = None
        out_filename = f"{clean_title}{target_ext}"

        try:
            import ssl
            ssl_ctx = ssl._create_unverified_context()
            req = urllib.request.Request(url, headers={'User-Agent': 'BasinPy/1.0 (Sinclair ZX Spectrum IDE)'})
            data = None
            try:
                with urllib.request.urlopen(req, timeout=12) as res:
                    data = res.read()
            except Exception:
                try:
                    with urllib.request.urlopen(req, context=ssl_ctx, timeout=12) as res:
                        data = res.read()
                except Exception as net_err:
                    advise(f"ZXDB CONNECTION FAILED: {net_err}")
                    return None, f"CONNECTION FAILED: {net_err}"

            if data is None or is_dummy_download(data):
                advise("ZXDB RETURNED EMPTY OR DUMMY DATA")
                return None, "ZXDB FILE EMPTY OR DUMMY"

            if data and (data.startswith(b"PK\x03\x04") or path.lower().endswith(".zip")):
                try:
                    zip_fn = os.path.basename(path) if path.lower().endswith(".zip") else f"{clean_title}.zip"
                    safe_zip_fn = re.sub(r'[<>:"/\\|?*]', '_', zip_fn)
                    zip_dest = os.path.join(os.getcwd(), safe_zip_fn)
                    with open(zip_dest, "wb") as zf_save:
                        zf_save.write(data)
                    zx_folder = get_zx_folder()
                    if os.path.abspath(zx_folder) != os.path.abspath(os.getcwd()):
                        try:
                            with open(os.path.join(zx_folder, safe_zip_fn), "wb") as zf_zx:
                                zf_zx.write(data)
                        except Exception:
                            pass

                    zf = zipfile.ZipFile(io.BytesIO(data))
                    members = [m for m in zf.namelist() if not m.startswith("__MACOSX") and not m.endswith("/")]

                    target_member = None
                    for m in members:
                        base_m = os.path.basename(m)
                        if base_m.lower().endswith(target_ext.lower()):
                            target_member = m
                            break
                    if not target_member:
                        for m in members:
                            base_m = os.path.basename(m)
                            _, _, m_ext = identify_zx_file(base_m)
                            if m_ext:
                                target_member = m
                                break
                    if not target_member and members:
                        target_member = members[0]

                    for name in members:
                        base_n = os.path.basename(name)
                        if not base_n:
                            continue
                        safe_n = re.sub(r'[<>:"/\\|?*]', '_', base_n)
                        member_bytes = zf.read(name)
                        out_p = os.path.join(os.getcwd(), safe_n)
                        with open(out_p, "wb") as mf:
                            mf.write(member_bytes)
                        if os.path.abspath(zx_folder) != os.path.abspath(os.getcwd()):
                            try:
                                with open(os.path.join(zx_folder, safe_n), "wb") as zxf:
                                    zxf.write(member_bytes)
                            except Exception:
                                pass
                        if name == target_member:
                            out_bytes = member_bytes
                            out_filename = safe_n
                except Exception as ze:
                    advise(f"ZIP EXTRACTION ERROR: {ze}")
                    return None, f"ZIP EXTRACTION ERROR: {ze}"

            if out_bytes is None and data is not None:
                out_bytes = data
                base_from_path = os.path.basename(path)
                if base_from_path.lower().endswith(".zip"):
                    base_from_path = base_from_path[:-4]
                if base_from_path:
                    out_filename = base_from_path

            if out_bytes is None or is_dummy_download(out_bytes):
                advise("DUMMY OR CORRUPT ZXDB DATA")
                return None, "DUMMY OR CORRUPT ZXDB DATA"

            # Ensure filename has an appropriate extension
            has_valid_ext = any(out_filename.lower().endswith(f_tuple[2]) for f_tuple in VALID_ZX_FORMATS.values())
            if not has_valid_ext:
                out_filename += target_ext

            clean_filename = re.sub(r'[<>:"/\\|?*]', '_', out_filename)
            dest_path = os.path.join(os.getcwd(), clean_filename)
            with open(dest_path, "wb") as f:
                f.write(out_bytes)

            zx_folder = get_zx_folder()
            if os.path.abspath(zx_folder) != os.path.abspath(os.getcwd()):
                try:
                    zx_path = os.path.join(zx_folder, clean_filename)
                    with open(zx_path, "wb") as f:
                        f.write(out_bytes)
                except Exception:
                    pass

            advise(f"ZXDB FILE READY: {clean_filename[:20]}")
            return dest_path, clean_filename
        except Exception as dl_err:
            advise(f"ZXDB DOWNLOAD FAILED: {dl_err}")
            return None, f"ZXDB DOWNLOAD FAILED: {dl_err}"

    def download_file(self, path, title="software", preferred_ext=None, status_cb=None, allow_fallback=True):
        # 1. Always attempt download using ZXDB file info first
        dest_path, filename_or_err = self.download_from_zxdb_info(path, title=title, preferred_ext=preferred_ext, status_cb=status_cb)
        if dest_path and os.path.exists(dest_path) and not is_dummy_download(dest_path):
            return dest_path, filename_or_err

        if not allow_fallback:
            return None, filename_or_err

        clean_title = re.sub(r'[<>:"/\\|?*]', '_', title).strip() or "software"
        arch_p, arch_fn = search_and_download_internet_archive(clean_title, preferred_ext=preferred_ext, status_cb=status_cb)
        if arch_p and os.path.exists(arch_p) and not is_dummy_download(arch_p):
            return arch_p, arch_fn

        # Check for existing valid local files (> 256 bytes and not dummy)
        zx_folder = get_zx_folder()
        search_folders = [os.getcwd()]
        if os.path.abspath(zx_folder) != os.path.abspath(os.getcwd()) and os.path.exists(zx_folder):
            search_folders.append(zx_folder)

        _, _, inferred_ext = identify_zx_file(path)
        target_ext = preferred_ext or inferred_ext or ".tap"
        if not target_ext.startswith('.'):
            target_ext = '.' + target_ext

        for s_dir in search_folders:
            cand1 = os.path.join(s_dir, f"{clean_title}{target_ext}")
            if os.path.exists(cand1) and not is_dummy_download(cand1):
                return cand1, os.path.basename(cand1)
            for cand_ext in ('.tap', '.tzx', '.z80', '.sna', '.dsk', '.trd', '.scl', '.bas'):
                cand_other = os.path.join(s_dir, f"{clean_title}{cand_ext}")
                if os.path.exists(cand_other) and not is_dummy_download(cand_other):
                    return cand_other, os.path.basename(cand_other)

        cand_lower = clean_title.lower()
        for s_dir in search_folders:
            if os.path.exists(s_dir):
                for fn in os.listdir(s_dir):
                    fp = os.path.join(s_dir, fn)
                    if os.path.isfile(fp) and not is_dummy_download(fp):
                        fn_low = fn.lower()
                        if fn_low.endswith(('.tap', '.tzx', '.z80', '.sna', '.dsk', '.trd', '.scl', '.bas')):
                            base = os.path.splitext(fn_low)[0]
                            if base and (base in cand_lower or cand_lower in base):
                                return fp, fn
        raise ValueError(f"Download failed for '{clean_title}': {filename_or_err}")

    def download_tap(self, path, title="software", status_cb=None):
        return self.download_file(path, title, preferred_ext=".tap", status_cb=status_cb, allow_fallback=True)


class ZXDBBrowser:
    def __init__(self, engine, initial_query=""):
        self.engine = engine
        self.query = (initial_query or "").strip()
        self.entries = []
        self.filtered_entries = []
        self.selected_idx = 0
        self.scroll_offset = 0
        self.max_rows = 17
        self.mode = "LIST"
        self.search_input = self.query
        self.status_msg = ""
        self.running = True
        self.downloaded_path = None
        self.file_list = []
        self.selected_file_idx = 0
        self.file_scroll_offset = 0
        self.active_entry = None

        # Extended archive search state
        self.extend_title = ""
        self.extend_query = ""
        self.archive_source = "ALL"  # "ALL", "ARCHIVE_ORG", "WOS_MIRRORS", "ZXART"
        self.archive_fmt_filter = "ALL"  # "ALL", "TAP", "TZX", "Z80", "SNA", "DSK"
        self.archive_candidates = []
        self.selected_archive_idx = 0
        self.archive_scroll_offset = 0
        self.custom_query_input = ""
        self.primary_failed_msg = ""

        self.perform_search(self.query)

    @property
    def tap_list(self):
        return self.file_list

    @tap_list.setter
    def tap_list(self, val):
        self.file_list = val

    @property
    def selected_tap_idx(self):
        return self.selected_file_idx

    @selected_tap_idx.setter
    def selected_tap_idx(self, val):
        self.selected_file_idx = val

    @property
    def tap_scroll_offset(self):
        return self.file_scroll_offset

    @tap_scroll_offset.setter
    def tap_scroll_offset(self, val):
        self.file_scroll_offset = val

    def perform_search(self, q):
        self.query = (q or "").strip()
        self.entries = self.engine.search(self.query)
        self.filtered_entries = list(self.entries)
        self.selected_idx = 0
        self.scroll_offset = 0
        self.file_list = []
        self.selected_file_idx = 0
        self.file_scroll_offset = 0
        self.active_entry = None
        if not self.filtered_entries:
            self.status_msg = "NO RELEASES FOUND"
        else:
            self.status_msg = ""

    def filter_by_text(self, part_text):
        pt = (part_text or "").strip().lower()
        if not pt:
            self.filtered_entries = list(self.entries)
        else:
            self.filtered_entries = [
                e for e in self.entries
                if pt in e.get("title", "").lower() or pt in e.get("publisher", "").lower()
            ]
        self.selected_idx = 0
        self.scroll_offset = 0

    def select_next(self):
        if self.filtered_entries:
            self.selected_idx = min(len(self.filtered_entries) - 1, self.selected_idx + 1)
            self._ensure_visible()

    def select_prev(self):
        if self.filtered_entries:
            self.selected_idx = max(0, self.selected_idx - 1)
            self._ensure_visible()

    def page_down(self):
        if self.filtered_entries:
            self.selected_idx = min(len(self.filtered_entries) - 1, self.selected_idx + self.max_rows)
            self._ensure_visible()

    def page_up(self):
        if self.filtered_entries:
            self.selected_idx = max(0, self.selected_idx - self.max_rows)
            self._ensure_visible()

    def _ensure_visible(self):
        if self.selected_idx < self.scroll_offset:
            self.scroll_offset = self.selected_idx
        elif self.selected_idx >= self.scroll_offset + self.max_rows:
            self.scroll_offset = self.selected_idx - self.max_rows + 1
        self.scroll_offset = max(0, min(self.scroll_offset, max(0, len(self.filtered_entries) - self.max_rows)))

    def open_file_selection(self):
        if not self.filtered_entries or not (0 <= self.selected_idx < len(self.filtered_entries)):
            return
        entry = self.filtered_entries[self.selected_idx]
        files = list(entry.get("files") or entry.get("taps", []))
        if not files and entry.get("selected_file"):
            files = [entry["selected_file"]]
        if not files and entry.get("selected_tap"):
            files = [entry["selected_tap"]]
        if not files:
            self.status_msg = "NO FILES AVAILABLE"
            return
        self.active_entry = entry
        self.file_list = files
        self.selected_file_idx = 0
        self.file_scroll_offset = 0
        self.mode = "FILE_SELECT"
        self.status_msg = ""

    def open_tap_selection(self):
        return self.open_file_selection()

    def select_next_file(self):
        if self.file_list:
            self.selected_file_idx = min(len(self.file_list) - 1, self.selected_file_idx + 1)
            self._ensure_file_visible()

    def select_prev_file(self):
        if self.file_list:
            self.selected_file_idx = max(0, self.selected_file_idx - 1)
            self._ensure_file_visible()

    def page_down_file(self):
        if self.file_list:
            self.selected_file_idx = min(len(self.file_list) - 1, self.selected_file_idx + self.max_rows)
            self._ensure_file_visible()

    def page_up_file(self):
        if self.file_list:
            self.selected_file_idx = max(0, self.selected_file_idx - self.max_rows)
            self._ensure_file_visible()

    def _ensure_file_visible(self):
        if self.selected_file_idx < self.file_scroll_offset:
            self.file_scroll_offset = self.selected_file_idx
        elif self.selected_file_idx >= self.file_scroll_offset + self.max_rows:
            self.file_scroll_offset = self.selected_file_idx - self.max_rows + 1
        self.file_scroll_offset = max(0, min(self.file_scroll_offset, max(0, len(self.file_list) - self.max_rows)))

    def select_next_tap(self):
        self.select_next_file()

    def select_prev_tap(self):
        self.select_prev_file()

    def page_down_tap(self):
        self.page_down_file()

    def page_up_tap(self):
        self.page_up_file()

    def download_and_run_selected_file(self):
        if not self.file_list or not (0 <= self.selected_file_idx < len(self.file_list)):
            return None
        file_info = self.file_list[self.selected_file_idx]
        entry = self.active_entry or (self.filtered_entries[self.selected_idx] if (self.filtered_entries and 0 <= self.selected_idx < len(self.filtered_entries)) else {"title": "software"})
        entry["selected_file"] = file_info
        entry["selected_tap"] = file_info
        return self.download_and_run_selected(file_info=file_info, title=entry.get("title", "software"))

    def download_and_run_selected_tap(self):
        return self.download_and_run_selected_file()

    def cycle_archive_source(self):
        sources = ["ALL", "ARCHIVE_ORG", "WOS_MIRRORS", "ZXART"]
        cur_idx = sources.index(self.archive_source) if self.archive_source in sources else 0
        self.archive_source = sources[(cur_idx + 1) % len(sources)]
        self.status_msg = f"SOURCE: {self.archive_source}"

    def cycle_archive_format(self):
        fmts = ["ALL", "TAP", "TZX", "Z80", "SNA", "DSK"]
        cur_idx = fmts.index(self.archive_fmt_filter) if self.archive_fmt_filter in fmts else 0
        self.archive_fmt_filter = fmts[(cur_idx + 1) % len(fmts)]
        self.status_msg = f"FORMAT: {self.archive_fmt_filter}"

    def execute_extended_search(self):
        self.status_msg = "SEARCHING ARCHIVES..."
        self.render()
        try:
            render_frame()
            pygame.display.flip()
        except Exception:
            pass

        pref_ext = None if self.archive_fmt_filter == "ALL" else f".{self.archive_fmt_filter.lower()}"
        q = (self.extend_query.strip() or self.extend_title.strip())
        results = search_external_archives(q, source=self.archive_source, preferred_ext=pref_ext, max_results=40)
        if not results:
            self.status_msg = "NO ARCHIVE FILES FOUND"
            self.render()
            try:
                render_frame()
                pygame.display.flip()
            except Exception:
                pass
            return []

        self.archive_candidates = results
        self.selected_archive_idx = 0
        self.archive_scroll_offset = 0
        self.mode = "ARCHIVE_FILE_SELECT"
        self.status_msg = f"FOUND {len(results)} CANDIDATES"
        self.render()
        try:
            render_frame()
            pygame.display.flip()
        except Exception:
            pass
        return results

    def select_next_archive_file(self):
        if self.archive_candidates:
            self.selected_archive_idx = min(len(self.archive_candidates) - 1, self.selected_archive_idx + 1)
            self._ensure_archive_file_visible()

    def select_prev_archive_file(self):
        if self.archive_candidates:
            self.selected_archive_idx = max(0, self.selected_archive_idx - 1)
            self._ensure_archive_file_visible()

    def page_down_archive_file(self):
        if self.archive_candidates:
            self.selected_archive_idx = min(len(self.archive_candidates) - 1, self.selected_archive_idx + self.max_rows)
            self._ensure_archive_file_visible()

    def page_up_archive_file(self):
        if self.archive_candidates:
            self.selected_archive_idx = max(0, self.selected_archive_idx - self.max_rows)
            self._ensure_archive_file_visible()

    def _ensure_archive_file_visible(self):
        if self.selected_archive_idx < self.archive_scroll_offset:
            self.archive_scroll_offset = self.selected_archive_idx
        elif self.selected_archive_idx >= self.archive_scroll_offset + self.max_rows:
            self.archive_scroll_offset = self.selected_archive_idx - self.max_rows + 1
        self.archive_scroll_offset = max(0, min(self.archive_scroll_offset, max(0, len(self.archive_candidates) - self.max_rows)))

    def download_and_run_selected_archive_file(self):
        if not self.archive_candidates or not (0 <= self.selected_archive_idx < len(self.archive_candidates)):
            return None
        cand = self.archive_candidates[self.selected_archive_idx]
        fn = cand.get("filename", "software")
        clean_title = re.sub(r'[<>:"/\\|?*]', '_', self.extend_title).strip() or "software"
        pref_ext = None if self.archive_fmt_filter == "ALL" else f".{self.archive_fmt_filter.lower()}"

        def update_status(msg):
            self.status_msg = str(msg)[:30].upper()
            self.render()
            try:
                render_frame()
                pygame.display.flip()
            except Exception:
                pass

        update_status(f"DOWNLOADING {fn[:14]}...")
        dest_p, out_fn = download_archive_file_candidate(cand, clean_title=clean_title, preferred_ext=pref_ext, status_cb=update_status)
        if dest_p and os.path.exists(dest_p) and not is_dummy_download(dest_p):
            self.downloaded_path = dest_p
            self.status_msg = f"SAVED {out_fn[:16]} | RUNNING..."
            self.render()
            try:
                render_frame()
                pygame.display.flip()
            except Exception:
                pass
            self.running = False
            return dest_p
        else:
            self.status_msg = "DOWNLOAD FAILED. TRY ANOTHER"
            self.render()
            try:
                render_frame()
                pygame.display.flip()
            except Exception:
                pass
            return None

    def render(self):
        for r in range(24):
            for c in range(32):
                screen_chars[r][c] = ' '
                cell_bitmap[r][c] = None
                attr_ink[r][c] = 7
                attr_paper[r][c] = 0
                attr_bright[r][c] = True
                attr_flash[r][c] = False
                attr_used[r][c] = True

        if self.mode == "EXTEND_SEARCH":
            # Row 0: Banner
            banner = " * EXTEND ARCHIVE SEARCH * "
            self.print_at(0, (32 - len(banner)) // 2, banner, ink=6, paper=1, bright=True)

            # Row 1: Notice
            self.print_at(1, 0, "FILE NOT AVAILABLE ON ZXDB".center(32)[:32], ink=2, paper=0, bright=True)
            # Row 2: Separator
            self.print_at(2, 0, "-" * 32, ink=5, paper=0, bright=True)

            # Row 3: Title
            t_disp = f"TITLE: {self.extend_title}"[:32]
            self.print_at(3, 0, f"{t_disp:<32}", ink=7, paper=0, bright=True)

            # Row 4: Reason
            r_disp = f"INFO : {self.primary_failed_msg}"[:32]
            self.print_at(4, 0, f"{r_disp:<32}", ink=6, paper=0, bright=True)

            # Row 5: Separator
            self.print_at(5, 0, "-" * 32, ink=5, paper=0, bright=True)

            # Row 6: Heading
            self.print_at(6, 0, "SEARCH OPTIONS:".ljust(32), ink=4, paper=0, bright=True)

            # Row 8: [1] Source
            src_lbl = {"ALL": "ALL ARCHIVES", "ARCHIVE_ORG": "INTERNET ARCHIVE", "WOS_MIRRORS": "WOS MIRRORS", "ZXART": "ZX-ART"}.get(self.archive_source, self.archive_source)
            opt1 = f"[1] SOURCE: {src_lbl}"[:32]
            self.print_at(8, 0, f"{opt1:<32}", ink=7, paper=0, bright=True)

            # Row 10: [2] Format filter
            opt2 = f"[2] FORMAT: {self.archive_fmt_filter}"[:32]
            self.print_at(10, 0, f"{opt2:<32}", ink=7, paper=0, bright=True)

            # Row 12: [3] Query
            opt3 = f"[3] QUERY : {self.extend_query[:19]}"[:32]
            self.print_at(12, 0, f"{opt3:<32}", ink=7, paper=0, bright=True)

            # Row 14: Actions header
            self.print_at(14, 0, "ACTIONS:".ljust(32), ink=4, paper=0, bright=True)
            self.print_at(16, 0, "[ENTER/Y] Search External Now".ljust(32), ink=5, paper=0, bright=True)
            self.print_at(18, 0, "[ESC/N]   Cancel to ZXDB List".ljust(32), ink=5, paper=0, bright=True)

            # Row 20: Separator
            self.print_at(20, 0, "-" * 32, ink=5, paper=0, bright=True)

            # Row 22: Status / Instruction
            if self.status_msg:
                self.print_at(22, 0, f"{self.status_msg:<32}"[:32], ink=7, paper=2, bright=True)
            else:
                self.print_at(22, 0, "PRESS [ENTER] OR [1-3] OPTION".ljust(32), ink=7, paper=1, bright=True)

            # Row 23: Help guide
            self.print_at(23, 0, "[1]:Src [2]:Fmt [3]:Edit [CR]:Go", ink=6, paper=0, bright=True)
            return

        if self.mode == "CUSTOM_QUERY":
            # Row 0: Banner
            banner = " * EDIT SEARCH QUERY * "
            self.print_at(0, (32 - len(banner)) // 2, banner, ink=6, paper=1, bright=True)
            self.print_at(1, 0, "ENTER ARCHIVE SEARCH QUERY:".ljust(32), ink=4, paper=0, bright=True)
            self.print_at(2, 0, "-" * 32, ink=5, paper=0, bright=True)

            prompt = f"QUERY: {self.custom_query_input}_"[:32]
            self.print_at(5, 0, f"{prompt:<32}", ink=7, paper=1, bright=True)

            self.print_at(9, 0, "[ENTER] Accept Query".ljust(32), ink=7, paper=0, bright=True)
            self.print_at(11, 0, "[ESC]   Cancel".ljust(32), ink=7, paper=0, bright=True)

            self.print_at(20, 0, "-" * 32, ink=5, paper=0, bright=True)
            if self.status_msg:
                self.print_at(22, 0, f"{self.status_msg:<32}"[:32], ink=7, paper=2, bright=True)
            else:
                self.print_at(22, 0, "TYPE QUERY AND PRESS ENTER".ljust(32), ink=7, paper=1, bright=True)
            self.print_at(23, 0, "[ENTER]:Accept [ESC]:Cancel     ", ink=6, paper=0, bright=True)
            return

        if self.mode == "ARCHIVE_FILE_SELECT":
            # Row 0: Banner
            banner = " * SELECT ARCHIVE FILE * "
            self.print_at(0, (32 - len(banner)) // 2, banner, ink=6, paper=1, bright=True)

            # Row 1: Title header
            hdr_str = f"FOUND: {self.extend_query[:20]}"
            self.print_at(1, 0, f"{hdr_str:<32}"[:32], ink=4, paper=0, bright=True)

            # Row 2: Separator
            self.print_at(2, 0, "-" * 32, ink=5, paper=0, bright=True)

            # Rows 3 to 19: Result lines
            for i in range(self.max_rows):
                r = 3 + i
                c_idx = self.archive_scroll_offset + i
                if c_idx < len(self.archive_candidates):
                    cand = self.archive_candidates[c_idx]
                    is_sel = (c_idx == self.selected_archive_idx)
                    prefix = ">" if is_sel else " "
                    fmt = (cand.get("format") or cand.get("ext", "ZX"))[:3].upper()
                    fmt_tag = f"[{fmt}]"
                    fn_base = os.path.basename(cand.get("filename", ""))
                    sz_str = cand.get("size_str", "")[:4]
                    arch_tag = "IA" if "Internet" in cand.get("archive", "") else "WoS"
                    line_str = f"{prefix}{fmt_tag}{fn_base[:17]:<17} {sz_str:>4} {arch_tag}"
                    if is_sel:
                        self.print_at(r, 0, f"{line_str:<32}"[:32], ink=0, paper=6, bright=True)
                    else:
                        self.print_at(r, 0, f"{line_str:<32}"[:32], ink=7, paper=0, bright=True)
                else:
                    self.print_at(r, 0, " " * 32, ink=7, paper=0, bright=False)

            # Row 20: Separator
            self.print_at(20, 0, "-" * 32, ink=5, paper=0, bright=True)

            # Row 21: Selected file detail
            if self.archive_candidates and 0 <= self.selected_archive_idx < len(self.archive_candidates):
                cur_c = self.archive_candidates[self.selected_archive_idx]
                arch_name = cur_c.get("archive", "")
                ident = cur_c.get("ident") or cur_c.get("url", "")
                detail = f"{arch_name[:12]} | {ident[:17]}"
                self.print_at(21, 0, f"{detail:<32}"[:32], ink=5, paper=0, bright=True)
            else:
                self.print_at(21, 0, " " * 32, ink=7, paper=0, bright=False)

            # Row 22: Status / Instruction
            if self.status_msg:
                self.print_at(22, 0, f"{self.status_msg:<32}"[:32], ink=7, paper=2, bright=True)
            elif self.archive_candidates:
                st = f"FILE {self.selected_archive_idx + 1}/{len(self.archive_candidates)} | [ENTER] Get"
                self.print_at(22, 0, f"{st:<32}"[:32], ink=7, paper=1, bright=True)
            else:
                self.print_at(22, 0, "NO FILES FOUND | [ESC] Options".ljust(32), ink=7, paper=2, bright=True)

            # Row 23: Help guide
            self.print_at(23, 0, "[Q/A/ARROWS]:Move [ESC]:Options ", ink=6, paper=0, bright=True)
            return

        if self.mode in ("FILE_SELECT", "TAP_SELECT"):
            # Row 0: Banner
            banner = " * SELECT FILE TO RUN * "
            self.print_at(0, (32 - len(banner)) // 2, banner, ink=6, paper=1, bright=True)

            # Row 1: Title header
            entry = self.active_entry or (self.filtered_entries[self.selected_idx] if (self.filtered_entries and 0 <= self.selected_idx < len(self.filtered_entries)) else {})
            t_name = entry.get("title", "")
            t_year = entry.get("year", "")
            hdr_str = f"FILES: {t_name[:18]} ({t_year})" if t_year else f"FILES: {t_name[:24]}"
            self.print_at(1, 0, f"{hdr_str:<32}"[:32], ink=4, paper=0, bright=True)

            # Row 2: Separator
            self.print_at(2, 0, "-" * 32, ink=5, paper=0, bright=True)

            # Rows 3 to 19: Result lines
            for i in range(self.max_rows):
                r = 3 + i
                f_idx = self.file_scroll_offset + i
                if f_idx < len(self.file_list):
                    f = self.file_list[f_idx]
                    is_sel = (f_idx == self.selected_file_idx)
                    prefix = ">" if is_sel else " "
                    fmt = (f.get("fmt_code") or f.get("format", "ZX"))[:3].upper()
                    fmt_tag = f"[{fmt}]"
                    p = f.get("path", "")
                    fn = os.path.basename(p) or f"release_{f_idx+1}"
                    size = f.get("size", 0)
                    size_str = f"{(size + 1023) // 1024}K" if size else fmt
                    line_str = f"{prefix} {fmt_tag} {fn[:18]:<18} {size_str:>5}"
                    if is_sel:
                        self.print_at(r, 0, f"{line_str:<32}"[:32], ink=0, paper=6, bright=True)
                    else:
                        self.print_at(r, 0, f"{line_str:<32}"[:32], ink=7, paper=0, bright=True)
                else:
                    self.print_at(r, 0, " " * 32, ink=7, paper=0, bright=False)

            # Row 20: Separator
            self.print_at(20, 0, "-" * 32, ink=5, paper=0, bright=True)

            # Row 21: Selected file detail
            if self.file_list and 0 <= self.selected_file_idx < len(self.file_list):
                cur_f = self.file_list[self.selected_file_idx]
                fmt_lbl = cur_f.get("format") or cur_f.get("fmt_code", "ZX")
                origin = cur_f.get("origin") or cur_f.get("path", "")
                detail = f"{fmt_lbl} | {origin}"
                self.print_at(21, 0, f"{detail:<32}"[:32], ink=5, paper=0, bright=True)
            else:
                self.print_at(21, 0, " " * 32, ink=7, paper=0, bright=False)

            # Row 22: Status / Instruction
            if self.status_msg:
                self.print_at(22, 0, f"{self.status_msg:<32}"[:32], ink=7, paper=2, bright=True)
            elif self.file_list:
                st = f"FILE {self.selected_file_idx + 1}/{len(self.file_list)} | [ENTER] Run"
                self.print_at(22, 0, f"{st:<32}"[:32], ink=7, paper=1, bright=True)
            else:
                self.print_at(22, 0, "NO FILES AVAILABLE | [ESC] Back".ljust(32), ink=7, paper=2, bright=True)

            # Row 23: Help guide
            self.print_at(23, 0, "[Q/A/ARROWS]:Move [ESC]:Back    ", ink=6, paper=0, bright=True)
            return

        # Row 0: Banner
        banner = " * SINCLAIR ZXDB ARCHIVE * "
        self.print_at(0, (32 - len(banner)) // 2, banner, ink=6, paper=1, bright=True)

        # Row 1: Query or Search bar
        if self.mode == "SEARCH":
            prompt = f"SEARCH: {self.search_input}_"
            self.print_at(1, 0, f"{prompt:<32}"[:32], ink=4, paper=0, bright=True)
        else:
            q_label = f"SEARCH: {self.query}" if self.query else "ALL ARCHIVE TITLES (S:FIND)"
            self.print_at(1, 0, f"{q_label:<32}"[:32], ink=4, paper=0, bright=True)

        # Row 2: Separator
        self.print_at(2, 0, "-" * 32, ink=5, paper=0, bright=True)

        # Rows 3 to 19: Result lines
        for i in range(self.max_rows):
            r = 3 + i
            entry_idx = self.scroll_offset + i
            if entry_idx < len(self.filtered_entries):
                e = self.filtered_entries[entry_idx]
                is_sel = (entry_idx == self.selected_idx)
                prefix = ">" if is_sel else " "
                title_str = e.get("title", "")[:18]
                year_str = e.get("year", "")[:4]
                files = e.get("files") or e.get("taps") or []
                fmts = sorted(list({f.get("fmt_code", "TAP") for f in files if f.get("fmt_code")}))
                if len(fmts) == 1:
                    badge = f"[{fmts[0]}]"
                elif len(files) > 1:
                    badge = f"{len(files)} Rel"
                else:
                    badge = " [ZX]"
                line_str = f"{prefix} {title_str:<18} {year_str:<4} {badge:>6}"
                if is_sel:
                    self.print_at(r, 0, f"{line_str:<32}"[:32], ink=0, paper=6, bright=True)
                else:
                    self.print_at(r, 0, f"{line_str:<32}"[:32], ink=7, paper=0, bright=True)
            else:
                self.print_at(r, 0, " " * 32, ink=7, paper=0, bright=False)

        # Row 20: Separator
        self.print_at(20, 0, "-" * 32, ink=5, paper=0, bright=True)

        # Row 21: Selected entry detail
        if self.filtered_entries and 0 <= self.selected_idx < len(self.filtered_entries):
            e = self.filtered_entries[self.selected_idx]
            pub = e.get("publisher", "Unknown")[:14]
            files = e.get("files") or e.get("taps") or []
            fmts = sorted(list({f.get("fmt_code", "TAP") for f in files if f.get("fmt_code")}))
            fmt_str = ",".join(fmts) if fmts else "TAP"
            detail = f"{pub} | {fmt_str}"
            self.print_at(21, 0, f"{detail:<32}"[:32], ink=5, paper=0, bright=True)
        else:
            self.print_at(21, 0, " " * 32, ink=7, paper=0, bright=False)

        # Row 22: Status / Instruction
        if self.status_msg:
            self.print_at(22, 0, f"{self.status_msg:<32}"[:32], ink=7, paper=2, bright=True)
        elif self.filtered_entries:
            st = f"Item {self.selected_idx + 1}/{len(self.filtered_entries)} | [ENTER] Files"
            self.print_at(22, 0, f"{st:<32}"[:32], ink=7, paper=1, bright=True)
        else:
            self.print_at(22, 0, "NO MATCHES | [S] Search".ljust(32), ink=7, paper=2, bright=True)

        # Row 23: Help guide
        if self.mode == "SEARCH":
            self.print_at(23, 0, "[ENTER]:Search [ESC]:Cancel    ", ink=6, paper=0, bright=True)
        else:
            self.print_at(23, 0, "[Q/A/ARROWS]:Move [S]:Find [ESC]", ink=6, paper=0, bright=True)

    def print_at(self, r, c, text, ink=7, paper=0, bright=True, flash=False):
        for i, ch in enumerate(str(text)):
            col = c + i
            if 0 <= r < 24 and 0 <= col < 32:
                screen_chars[r][col] = ch
                attr_ink[r][col] = ink
                attr_paper[r][col] = paper
                attr_bright[r][col] = bright
                attr_flash[r][col] = flash
                attr_used[r][col] = True
                cell_bitmap[r][col] = None

    def handle_keydown(self, event):
        if self.mode == "LIST":
            if event.key in (pygame.K_UP, pygame.K_q):
                self.select_prev()
            elif event.key in (pygame.K_DOWN, pygame.K_a):
                self.select_next()
            elif event.key == pygame.K_PAGEUP:
                self.page_up()
            elif event.key == pygame.K_PAGEDOWN:
                self.page_down()
            elif event.key == pygame.K_HOME:
                self.selected_idx = 0
                self.scroll_offset = 0
            elif event.key == pygame.K_END:
                if self.filtered_entries:
                    self.selected_idx = len(self.filtered_entries) - 1
                    self._ensure_visible()
            elif event.key in (pygame.K_s, pygame.K_SLASH):
                self.mode = "SEARCH"
                self.search_input = self.query
                self.status_msg = ""
            elif event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                self.open_file_selection()
            elif event.key == pygame.K_ESCAPE:
                self.running = False
        elif self.mode in ("FILE_SELECT", "TAP_SELECT"):
            if event.key in (pygame.K_UP, pygame.K_q):
                self.select_prev_file()
            elif event.key in (pygame.K_DOWN, pygame.K_a):
                self.select_next_file()
            elif event.key == pygame.K_PAGEUP:
                self.page_up_file()
            elif event.key == pygame.K_PAGEDOWN:
                self.page_down_file()
            elif event.key == pygame.K_HOME:
                self.selected_file_idx = 0
                self.file_scroll_offset = 0
            elif event.key == pygame.K_END:
                if self.file_list:
                    self.selected_file_idx = len(self.file_list) - 1
                    self._ensure_file_visible()
            elif event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                self.download_and_run_selected_file()
            elif event.key == pygame.K_ESCAPE:
                self.mode = "LIST"
                self.status_msg = ""
        elif self.mode == "SEARCH":
            if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                self.perform_search(self.search_input.strip())
                self.mode = "LIST"
            elif event.key == pygame.K_ESCAPE:
                self.mode = "LIST"
            elif event.key == pygame.K_BACKSPACE:
                if self.search_input:
                    self.search_input = self.search_input[:-1]
        elif self.mode == "EXTEND_SEARCH":
            if event.key in (pygame.K_1, pygame.K_KP1):
                self.cycle_archive_source()
            elif event.key in (pygame.K_2, pygame.K_KP2):
                self.cycle_archive_format()
            elif event.key in (pygame.K_3, pygame.K_KP3, pygame.K_e):
                self.mode = "CUSTOM_QUERY"
                self.custom_query_input = self.extend_query
                self.status_msg = ""
            elif event.key in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_y):
                self.execute_extended_search()
            elif event.key in (pygame.K_ESCAPE, pygame.K_n):
                self.mode = "FILE_SELECT" if self.file_list else "LIST"
                self.status_msg = ""
        elif self.mode == "CUSTOM_QUERY":
            if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                self.extend_query = self.custom_query_input.strip() or self.extend_title
                self.mode = "EXTEND_SEARCH"
                self.status_msg = "QUERY UPDATED"
            elif event.key == pygame.K_ESCAPE:
                self.mode = "EXTEND_SEARCH"
                self.status_msg = ""
            elif event.key == pygame.K_BACKSPACE:
                if self.custom_query_input:
                    self.custom_query_input = self.custom_query_input[:-1]
        elif self.mode == "ARCHIVE_FILE_SELECT":
            if event.key in (pygame.K_UP, pygame.K_q):
                self.select_prev_archive_file()
            elif event.key in (pygame.K_DOWN, pygame.K_a):
                self.select_next_archive_file()
            elif event.key == pygame.K_PAGEUP:
                self.page_up_archive_file()
            elif event.key == pygame.K_PAGEDOWN:
                self.page_down_archive_file()
            elif event.key == pygame.K_HOME:
                self.selected_archive_idx = 0
                self.archive_scroll_offset = 0
            elif event.key == pygame.K_END:
                if self.archive_candidates:
                    self.selected_archive_idx = len(self.archive_candidates) - 1
                    self._ensure_archive_file_visible()
            elif event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                self.download_and_run_selected_archive_file()
            elif event.key == pygame.K_ESCAPE:
                self.mode = "EXTEND_SEARCH"
                self.status_msg = ""

    def handle_textinput(self, text):
        if self.mode == "SEARCH" and text:
            self.search_input += text
        elif self.mode == "CUSTOM_QUERY" and text:
            self.custom_query_input += text
        elif self.mode == "EXTEND_SEARCH":
            t = text.strip()
            if t in ("1",):
                self.cycle_archive_source()
            elif t in ("2",):
                self.cycle_archive_format()
            elif t in ("3", "e", "E"):
                self.mode = "CUSTOM_QUERY"
                self.custom_query_input = self.extend_query
                self.status_msg = ""
            elif t in ("y", "Y"):
                self.execute_extended_search()
            elif t in ("n", "N"):
                self.mode = "FILE_SELECT" if self.file_list else "LIST"
                self.status_msg = ""

    def download_and_run_selected(self, file_info=None, title=None):
        if not self.filtered_entries and not file_info:
            return None
        entry = self.active_entry or (self.filtered_entries[self.selected_idx] if (self.filtered_entries and 0 <= self.selected_idx < len(self.filtered_entries)) else {})
        if file_info is None:
            file_info = entry.get("selected_file") or entry.get("selected_tap") or (entry.get("files", [{}])[0] if entry.get("files") else None)
        if title is None:
            title = entry.get("title", "software")
        if not file_info:
            self.status_msg = "NO FILE AVAILABLE"
            return None

        path = file_info.get("path")
        preferred_ext = file_info.get("ext")
        clean_title = re.sub(r'[<>:"/\\|?*]', '_', title).strip() or "software"

        def update_status(msg):
            self.status_msg = str(msg)[:30].upper()
            self.render()
            try:
                render_frame()
                pygame.display.flip()
            except Exception:
                try:
                    update_display()
                except Exception:
                    pass

        update_status(f"DOWNLOADING {clean_title[:14]}...")

        # 1. First attempt direct download using primary ZXDB file info
        dest_path, filename_or_reason = self.engine.download_from_zxdb_info(path, title=title, preferred_ext=preferred_ext, status_cb=update_status)
        if dest_path and os.path.exists(dest_path) and not is_dummy_download(dest_path):
            self.downloaded_path = dest_path
            self.status_msg = f"SAVED {filename_or_reason[:16]} | RUNNING..."
            self.render()
            try:
                render_frame()
                pygame.display.flip()
            except Exception:
                try:
                    update_display()
                except Exception:
                    pass
            self.running = False
            return dest_path

        # 2. ZXDB download failed, is empty/dummy, or is distribution denied.
        # Switch to EXTEND_SEARCH mode and prompt user with search options.
        self.mode = "EXTEND_SEARCH"
        self.extend_title = title
        self.extend_query = re.sub(r'[<>:"/\\|?*]', ' ', title).strip() or "software"
        self.archive_source = "ALL"
        self.archive_fmt_filter = "ALL"
        self.archive_candidates = []
        self.selected_archive_idx = 0
        self.archive_scroll_offset = 0
        self.primary_failed_msg = str(filename_or_reason or "ZXDB DOWNLOAD FAILED")[:24]
        self.status_msg = ""
        self.render()
        try:
            render_frame()
            pygame.display.flip()
        except Exception:
            try:
                update_display()
            except Exception:
                pass
        return None


def launch_zxdb_browser(args=""):
    global zxdb_browser_active, canvas_dirty, current_border
    clean_query = (args or "").strip().strip('"').strip("'").strip()

    # Save screen state
    saved_chars = [list(row) for row in screen_chars]
    saved_ink = [list(row) for row in attr_ink]
    saved_paper = [list(row) for row in attr_paper]
    saved_bright = [list(row) for row in attr_bright]
    saved_flash = [list(row) for row in attr_flash]
    saved_used = [list(row) for row in attr_used]
    saved_border = current_border

    zxdb_browser_active = True
    current_border = 1
    engine = ZXDBSearchEngine()
    browser = ZXDBBrowser(engine, initial_query=clean_query)

    is_dummy = (os.environ.get("SDL_VIDEODRIVER") == "dummy") or (not running)

    if is_dummy:
        browser.render()
        zxdb_browser_active = False
        return browser

    clock = pygame.time.Clock()
    browser.running = True
    try:
        while browser.running:
            clock.tick(60)
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    browser.running = False
                    pygame.quit()
                    sys.exit(0)
                elif event.type == pygame.KEYDOWN:
                    browser.handle_keydown(event)
                elif event.type == pygame.TEXTINPUT:
                    browser.handle_textinput(event.text)

            browser.render()
            render_frame()
            try:
                pygame.display.flip()
            except Exception:
                pass
    finally:
        zxdb_browser_active = False

    if browser.downloaded_path and os.path.exists(browser.downloaded_path):
        for r in range(ATTR_ROWS):
            for c in range(ATTR_COLS):
                attr_ink[r][c] = current_ink
                attr_paper[r][c] = current_paper
                attr_used[r][c] = False
                screen_chars[r][c] = ' '
        canvas.fill(COLORS[current_paper])
        canvas_dirty = True
        update_display()
        load_program_file(browser.downloaded_path, mode="RUN", load_source="ZXDB")
        is_snap = browser.downloaded_path.lower().endswith(('.z80', '.sna'))
        if not is_snap and not program and last_loaded_code_addr:
            canvas_print(f"Running machine code at {last_loaded_code_addr}...")
            update_display()
            cpu = get_z80_cpu()
            cpu.run_from(last_loaded_code_addr)
    else:
        current_border = saved_border
        for r in range(24):
            for c in range(32):
                screen_chars[r][c] = saved_chars[r][c]
                attr_ink[r][c] = saved_ink[r][c]
                attr_paper[r][c] = saved_paper[r][c]
                attr_bright[r][c] = saved_bright[r][c]
                attr_flash[r][c] = saved_flash[r][c]
                attr_used[r][c] = saved_used[r][c]
                cell_bitmap[r][c] = None
        canvas_dirty = True
        update_display()

    return browser


def launch_zxdb_browser_for_side2(query=""):
    """Open the ZXDB browser pre-seeded with *query* and attach the chosen
    download as Side 2 tape — without triggering a full program load.
    Returns the attached path, or None if the user cancelled.
    """
    global zxdb_browser_active, canvas_dirty, current_border

    # Save screen state so we can restore on cancel/close
    saved_border = current_border
    saved_chars  = [list(row) for row in screen_chars]
    saved_ink    = [list(row) for row in attr_ink]
    saved_paper  = [list(row) for row in attr_paper]
    saved_bright = [list(row) for row in attr_bright]
    saved_flash  = [list(row) for row in attr_flash]
    saved_used   = [list(row) for row in attr_used]

    zxdb_browser_active = True
    current_border = 1
    engine  = ZXDBSearchEngine()
    browser = ZXDBBrowser(engine, initial_query=query)

    is_dummy = (os.environ.get("SDL_VIDEODRIVER") == "dummy") or (not running)
    if is_dummy:
        browser.render()
        zxdb_browser_active = False
        return None

    clock = pygame.time.Clock()
    browser.running = True
    try:
        while browser.running:
            clock.tick(60)
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    browser.running = False
                elif event.type == pygame.KEYDOWN:
                    browser.handle_keydown(event)
                elif event.type == pygame.TEXTINPUT:
                    browser.handle_textinput(event.text)
            browser.render()
            render_frame()
            try:
                pygame.display.flip()
            except Exception:
                pass
    finally:
        zxdb_browser_active = False

    # Always restore screen
    current_border = saved_border
    for r in range(24):
        for c in range(32):
            screen_chars[r][c]  = saved_chars[r][c]
            attr_ink[r][c]      = saved_ink[r][c]
            attr_paper[r][c]    = saved_paper[r][c]
            attr_bright[r][c]   = saved_bright[r][c]
            attr_flash[r][c]    = saved_flash[r][c]
            attr_used[r][c]     = saved_used[r][c]
            cell_bitmap[r][c]   = None
    canvas_dirty = True
    update_display()

    attached_path = None
    if browser.downloaded_path and os.path.exists(browser.downloaded_path):
        _dl = browser.downloaded_path
        # Unwrap ZIP if needed — pick first tape file inside
        if _dl.lower().endswith('.zip'):
            try:
                import zipfile as _zf_s2
                with _zf_s2.ZipFile(_dl) as _zobj:
                    for _nm in _zobj.namelist():
                        if _nm.lower().endswith(('.tzx', '.tap', '.pzx')):
                            _out = os.path.join(
                                os.path.dirname(_dl), os.path.basename(_nm)
                            )
                            with open(_out, 'wb') as _fo:
                                _fo.write(_zobj.read(_nm))
                            _dl = _out
                            break
            except Exception:
                pass
        if 'universal_tape_player' in globals():
            universal_tape_player.attach(_dl)
            attached_path = _dl

    return attached_path



