class VirtualESP8266:
    def __init__(self):
        self.tx_line = bytearray()
        self.rx_fifo = bytearray()
        self.ip = "192.168.1.105"
        self.mac = "00:03:19:AA:BB:CC"
        self.gateway = "192.168.1.1"
        self.netmask = "255.255.255.0"
        self.connected_sockets = {}
        self.send_mode_bytes_left = 0
        self.send_socket_id = 0

    def write_tx(self, val):
        val &= 0xFF
        if self.send_mode_bytes_left > 0:
            self.send_mode_bytes_left -= 1
            sock = self.connected_sockets.get(self.send_socket_id)
            if sock:
                try:
                    sock.send(bytes([val]))
                except Exception:
                    pass
            if self.send_mode_bytes_left == 0:
                self.queue_rx(b"\r\nSEND OK\r\n")
            return

        if val in (10, 13):
            if self.tx_line:
                cmd = self.tx_line.decode('latin1', errors='ignore').strip()
                self.tx_line.clear()
                self.process_at_cmd(cmd)
        else:
            self.tx_line.append(val)

    def queue_rx(self, data):
        self.rx_fifo.extend(data)

    def read_rx(self):
        if self.rx_fifo:
            return self.rx_fifo.pop(0)
        return 0xFF

    def status(self):
        # Bit 0: TX ready (1), Bit 1: RX ready (2 if rx_fifo not empty)
        return 0x01 | (0x02 if len(self.rx_fifo) > 0 else 0x00)

    def process_at_cmd(self, cmd):
        c = cmd.upper()
        if c == "AT":
            self.queue_rx(b"\r\nOK\r\n")
        elif c == "AT+GMR":
            self.queue_rx(b"\\r\\nAT version:1.7.4.0\\r\\nSDK version:3.0.4\\r\\nOK\\r\\n")
        elif c == "AT+CIFSR":
            resp = f'\\r\\n+CIFSR:STAIP,"{self.ip}"\\r\\n+CIFSR:STAMAC,"{self.mac}"\\r\\nOK\\r\\n'
            self.queue_rx(resp.encode('ascii'))
        elif c.startswith("AT+CIPSTART="):
            parts = [p.strip(' "\\\'') for p in cmd[12:].split(",")]
            sock_id = 0
            if len(parts) >= 3:
                if parts[0].isdigit():
                    sock_id = int(parts[0])
                    proto = parts[1].upper()
                    host = parts[2]
                    port = int(parts[3])
                else:
                    proto = parts[0].upper()
                    host = parts[1]
                    port = int(parts[2])
                try:
                    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM if proto == "TCP" else socket.SOCK_DGRAM)
                    s.settimeout(2.0)
                    s.connect((host, port))
                    self.connected_sockets[sock_id] = s
                    self.queue_rx(b"\r\nCONNECT\r\nOK\r\n")
                except Exception:
                    self.queue_rx(b"\r\nCONNECT FAIL\r\nERROR\r\n")
            else:
                self.queue_rx(b"\r\nERROR\r\n")
        elif c.startswith("AT+CIPSEND="):
            parts = c.split("=")[1].split(",")
            if len(parts) == 2:
                self.send_socket_id = int(parts[0])
                length = int(parts[1])
            else:
                self.send_socket_id = 0
                length = int(parts[0])
            self.send_mode_bytes_left = length
            self.queue_rx(b"\r\nOK\r\n> ")
        elif c.startswith("AT+CIPCLOSE"):
            self.queue_rx(b"\r\nCLOSED\r\nOK\r\n")
        elif c.startswith("AT+CWMODE"):
            self.queue_rx(b"\r\nOK\r\n")
        elif c.startswith("AT+CWJAP?"):
            self.queue_rx(b'\r\n+CWJAP:"BasinPyWiFi"\r\nOK\r\n')
        elif c.startswith("AT+CWJAP"):
            self.queue_rx(b"\r\nWIFI CONNECTED\r\nWIFI GOT IP\r\nOK\r\n")
        elif c.startswith("AT+CIPSTATUS"):
            self.queue_rx(b"\r\nSTATUS:2\r\nOK\r\n")
        else:
            self.queue_rx(b"\r\nOK\r\n")


class SpectranextInterface:
    def __init__(self):
        self.esp = VirtualESP8266()

    def write_uart_data(self, val):
        self.esp.write_tx(val)

    def read_uart_data(self):
        return self.esp.read_rx()

    def read_uart_status(self):
        return self.esp.status()

    def write_uart_ctrl(self, val):
        pass


class SpectranetInterface:
    def __init__(self):
        self.mac = "00:03:19:00:00:01"
        self.ip = "192.168.1.100"
        self.netmask = "255.255.255.0"
        self.gateway = "192.168.1.1"
        self.dns = "8.8.8.8"
        self.dhcp_enabled = True
        self.traps_enabled = True
        self.page_a_enabled = False
        self.page_b_enabled = False
        self.page_b_bank = 0
        self.cpld_ctrl = 0x00
        
        self.w5100_regs = bytearray(0x8000)
        self.w5100_sockets = {}
        self.ram_pages = [bytearray(4096) for _ in range(8)]
        self.mounted_drives = {}

        self._init_w5100_regs()

    def _init_w5100_regs(self):
        gw_parts = [int(p) for p in self.gateway.split(".")]
        for i, p in enumerate(gw_parts):
            self.w5100_regs[0x0001 + i] = p
        sub_parts = [int(p) for p in self.netmask.split(".")]
        for i, p in enumerate(sub_parts):
            self.w5100_regs[0x0005 + i] = p
        mac_parts = [int(p, 16) for p in self.mac.split(":")]
        for i, p in enumerate(mac_parts):
            self.w5100_regs[0x0009 + i] = p
        ip_parts = [int(p) for p in self.ip.split(".")]
        for i, p in enumerate(ip_parts):
            self.w5100_regs[0x000F + i] = p

    def read_w5100(self, offset):
        offset &= 0x7FFF
        return self.w5100_regs[offset]

    def write_w5100(self, offset, val):
        offset &= 0x7FFF
        val &= 0xFF
        self.w5100_regs[offset] = val

        for s in range(4):
            base = 0x0400 + s * 0x0100
            if offset == base + 0x01:
                self._handle_socket_command(s, val)

    def _handle_socket_command(self, s, cmd):
        base = 0x0400 + s * 0x0100
        if cmd == 0x01:  # OPEN
            mode = self.w5100_regs[base + 0x00] & 0x0F
            if mode == 0x01: # TCP
                self.w5100_regs[base + 0x03] = 0x13 # SOCK_INIT
            elif mode == 0x02: # UDP
                self.w5100_regs[base + 0x03] = 0x22 # SOCK_UDP
        elif cmd == 0x02:  # LISTEN
            self.w5100_regs[base + 0x03] = 0x14 # SOCK_LISTEN
        elif cmd == 0x04:  # CONNECT
            self.w5100_regs[base + 0x03] = 0x17 # SOCK_ESTABLISHED
        elif cmd in (0x08, 0x10):  # DISCON / CLOSE
            self.w5100_regs[base + 0x03] = 0x00 # SOCK_CLOSED
            sock = self.w5100_sockets.pop(s, None)
            if sock:
                try: sock.close()
                except Exception: pass
        self.w5100_regs[base + 0x01] = 0x00

    def read_ram(self, offset):
        bank = self.page_b_bank & 0x07
        return self.ram_pages[bank][offset & 0x0FFF]

    def write_ram(self, offset, val):
        bank = self.page_b_bank & 0x07
        self.ram_pages[bank][offset & 0x0FFF] = val & 0xFF

    def handle_cpld_out(self, val):
        self.cpld_ctrl = val & 0xFF
        self.traps_enabled = (val & 0x01) == 0
        self.page_a_enabled = (val & 0x02) == 0
        self.page_b_enabled = (val & 0x04) == 0
        self.page_b_bank = (val >> 5) & 0x07

    def handle_cpld_in(self):
        return self.cpld_ctrl

    def handle_trap_call(self, cpu):
        func_id = cpu.C & 0xFF
        if func_id == 0x01:  # HGF_SOCKET
            sock_fd = len(self.w5100_sockets) % 4
            cpu.A = sock_fd
            cpu.F &= ~0x01
        elif func_id == 0x03:  # HGF_CONNECT
            cpu.F &= ~0x01
        elif func_id == 0x06:  # HGF_SEND
            cpu.F &= ~0x01
        elif func_id == 0x07:  # HGF_RECV
            cpu.BC = min(cpu.BC, 32)
            cpu.F &= ~0x01
        elif func_id == 0x08:  # HGF_CLOSE
            cpu.F &= ~0x01
        elif func_id == 0x0A:  # HGF_GETHOSTBYNAME
            host_chars = []
            ptr = cpu.HL
            for _ in range(256):
                ch = cpu.read_byte(ptr)
                if ch == 0: break
                host_chars.append(chr(ch))
                ptr += 1
            hostname = "".join(host_chars)
            try:
                ip_str = socket.gethostbyname(hostname) if hostname else self.ip
            except Exception:
                ip_str = "127.0.0.1"
            parts = [int(p) for p in ip_str.split(".")]
            for i, p in enumerate(parts):
                cpu.write_byte(cpu.DE + i, p)
            cpu.F &= ~0x01
        elif func_id == 0x0B:  # HGF_IFCONFIG
            cpu.F &= ~0x01
        elif func_id == 0x0C:  # HGF_DHCP
            cpu.F &= ~0x01
        else:
            cpu.F &= ~0x01

        ret_addr = cpu.pop_word()
        cpu.PC = ret_addr
        return True


spectranet_subsystem = SpectranetInterface()
spectranext_subsystem = SpectranextInterface()
active_tnfs_server = None

def get_spectranet():
    return spectranet_subsystem

def get_spectranext():
    return spectranext_subsystem


