class TNFSServer:
    def __init__(self, root_dir, port=16384):
        self.root_dir = os.path.abspath(root_dir)
        self.port = int(port)
        self.sock = None
        self.running = False
        self.thread = None
        self.sessions = {}
        self.next_conn_id = 0x2000
        self.open_dirs = {}
        self.open_files = {}
        self.next_handle = 1

    def start(self):
        os.makedirs(self.root_dir, exist_ok=True)
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        self.sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.sock.bind(("0.0.0.0", self.port))
        self.sock.settimeout(0.5)
        self.running = True
        self.thread = threading.Thread(target=self._run_loop, daemon=True)
        self.thread.start()

    def stop(self):
        self.running = False
        if self.sock:
            try: self.sock.close()
            except Exception: pass
        if self.thread:
            self.thread.join(timeout=1.0)
        for fh, f in list(self.open_files.items()):
            try: f.close()
            except Exception: pass
        self.open_files.clear()
        self.open_dirs.clear()

    def _run_loop(self):
        while self.running:
            try:
                data, addr = self.sock.recvfrom(4096)
            except (socket.timeout, OSError):
                continue
            if len(data) < 4:
                continue

            conn_id, seq, cmd = struct.unpack("<HBB", data[:4])
            payload = data[4:]

            if cmd == 0x00: # CMD_MOUNT
                cid = self.next_conn_id
                self.next_conn_id += 1
                self.sessions[cid] = "/"
                resp = struct.pack("<HBBBH", cid, seq, 0x00, 0x00, 0x0102) + struct.pack("<H", 100)
                self.sock.sendto(resp, addr)
            elif cmd == 0x01: # CMD_UMOUNT
                self.sessions.pop(conn_id, None)
                resp = struct.pack("<HBB", conn_id, seq, 0x01) + bytes([0x00])
                self.sock.sendto(resp, addr)
            elif cmd == 0x10: # CMD_OPENDIR
                dh = self.next_handle
                self.next_handle += 1
                files = sorted(os.listdir(self.root_dir)) if os.path.exists(self.root_dir) else []
                self.open_dirs[dh] = list(files)
                resp = struct.pack("<HBB", conn_id, seq, 0x10) + bytes([0x00, dh])
                self.sock.sendto(resp, addr)
            elif cmd == 0x11: # CMD_READDIR
                dh = payload[0] if payload else 1
                files = self.open_dirs.get(dh, [])
                if files:
                    entry = files.pop(0).encode('utf-8', errors='ignore') + b"\x00"
                    resp = struct.pack("<HBB", conn_id, seq, 0x11) + bytes([0x00]) + entry
                else:
                    resp = struct.pack("<HBB", conn_id, seq, 0x11) + bytes([0x12]) # EOF
                self.sock.sendto(resp, addr)
            elif cmd == 0x12: # CMD_CLOSEDIR
                dh = payload[0] if payload else 1
                self.open_dirs.pop(dh, None)
                resp = struct.pack("<HBB", conn_id, seq, 0x12) + bytes([0x00])
                self.sock.sendto(resp, addr)
            elif cmd in (0x20, 0x29): # CMD_OPEN / CMD_OPENX
                fh = self.next_handle
                self.next_handle += 1
                if cmd == 0x29 and len(payload) >= 4:
                    fname = payload[4:].split(b"\x00")[0].decode('utf-8', errors='ignore').strip('/')
                else:
                    fname = payload.split(b"\x00")[0].decode('utf-8', errors='ignore').strip('/')
                fpath = os.path.join(self.root_dir, fname)
                if os.path.exists(fpath) and os.path.isfile(fpath):
                    try:
                        f = open(fpath, "rb")
                        self.open_files[fh] = f
                        resp = struct.pack("<HBB", conn_id, seq, cmd) + bytes([0x00, fh])
                    except Exception:
                        resp = struct.pack("<HBB", conn_id, seq, cmd) + bytes([0x02, 0x00])
                else:
                    resp = struct.pack("<HBB", conn_id, seq, cmd) + bytes([0x02, 0x00])
                self.sock.sendto(resp, addr)
            elif cmd == 0x21: # CMD_READ
                fh = payload[0] if payload else 1
                req_sz = struct.unpack("<H", payload[1:3])[0] if len(payload) >= 3 else 512
                f = self.open_files.get(fh)
                if f:
                    chunk = f.read(req_sz)
                    resp = struct.pack("<HBB", conn_id, seq, 0x21) + bytes([0x00]) + struct.pack("<H", len(chunk)) + chunk
                else:
                    resp = struct.pack("<HBB", conn_id, seq, 0x21) + bytes([0x00, 0x00, 0x00])
                self.sock.sendto(resp, addr)
            elif cmd == 0x23: # CMD_CLOSE
                fh = payload[0] if payload else 1
                f = self.open_files.pop(fh, None)
                if f:
                    try: f.close()
                    except Exception: pass
                resp = struct.pack("<HBB", conn_id, seq, 0x23) + bytes([0x00])
                self.sock.sendto(resp, addr)
            else:
                resp = struct.pack("<HBB", conn_id, seq, cmd) + bytes([0x00])
                self.sock.sendto(resp, addr)


class TNFSClient:
    def __init__(self, host="127.0.0.1", port=16384):
        self.host = str(host).strip()
        self.port = int(port)
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        self.sock.settimeout(2.5)
        self.conn_id = 0x0000
        self.seq = 1

    def _send_recv(self, cmd, payload=b"", retries=3):
        for attempt in range(retries):
            pkt = struct.pack("<HBB", self.conn_id, self.seq, cmd) + payload
            try:
                self.sock.sendto(pkt, (self.host, self.port))
                resp, _ = self.sock.recvfrom(4096)
                if len(resp) >= 4:
                    r_conn, r_seq, r_cmd = struct.unpack("<HBB", resp[:4])
                    if r_seq == self.seq:
                        self.seq = (self.seq + 1) & 0xFF
                        status = resp[4] if len(resp) > 4 else 0
                        r_payload = resp[5:]
                        return r_conn, status, r_payload
            except socket.timeout:
                time.sleep(0.05)
                continue
            except Exception:
                break
        self.seq = (self.seq + 1) & 0xFF
        return self.conn_id, -1, b""

    def mount(self, location="/"):
        try:
            loc = location.strip() or "/"
            pkt = struct.pack("<H", 0x0102) + loc.encode('utf-8') + b"\x00\x00\x00"
            r_conn, status, _ = self._send_recv(0x00, pkt)
            if status == 0:
                self.conn_id = r_conn
                return True
        except Exception:
            pass
        return False

    def list_files(self, path="/"):
        entries = []
        try:
            clean_path = ("/" + path.strip().lstrip('/')).rstrip('/')
            if not clean_path: clean_path = "/"
            _, status, payload = self._send_recv(0x10, clean_path.encode('utf-8') + b"\x00")
            if status != 0 or not payload:
                return entries
            handle = payload[0]
            for _ in range(500):
                _, r_status, r_pay = self._send_recv(0x11, bytes([handle]))
                if r_status != 0 or not r_pay:
                    break
                name = r_pay.split(b"\x00")[0].decode('utf-8', errors='ignore')
                if not name: break
                entries.append(name)
            self._send_recv(0x12, bytes([handle]))
        except Exception:
            pass
        return entries

    def read_file(self, filename):
        clean_name = filename.strip().lstrip('/')
        try:
            # 1. Standard TNFS 0x29 (CMD_OPEN with flags=0, mode=0)
            payload = struct.pack("<HH", 0, 0) + clean_name.encode('utf-8') + b"\x00"
            _, status, payload_resp = self._send_recv(0x29, payload)

            # 2. Fallbacks for servers expecting 0x20
            if status != 0 or not payload_resp:
                _, status, payload_resp = self._send_recv(0x20, struct.pack("<HH", 0, 0) + clean_name.encode('utf-8') + b"\x00")
            if status != 0 or not payload_resp:
                _, status, payload_resp = self._send_recv(0x20, clean_name.encode('utf-8') + b"\x00\x00\x00")
            if status != 0 or not payload_resp:
                _, status, payload_resp = self._send_recv(0x20, clean_name.encode('utf-8') + b"\x00")

            if status != 0 or not payload_resp:
                return b""

            f_handle = payload_resp[0]
            chunks = []
            for _ in range(10000):
                _, r_stat, r_pay = self._send_recv(0x21, bytes([f_handle]) + struct.pack("<H", 512))
                if r_stat != 0 or len(r_pay) < 2:
                    break
                sz = struct.unpack("<H", r_pay[:2])[0]
                if sz == 0:
                    break
                chunks.append(r_pay[2:2+sz])
                if sz < 512:
                    break
            self._send_recv(0x23, bytes([f_handle]))
            return b"".join(chunks)
        except Exception:
            return b""

    def umount(self):
        try:
            if self.conn_id != 0:
                self._send_recv(0x01, b"")
                self.conn_id = 0
        except Exception:
            pass


# ==============================================================================
# 5. TNFS BROWSER CLASS
# ==============================================================================

class TNFSBrowser:
    def __init__(self, initial_host="tnfs.zxnet.co.uk", initial_port=16384):
        self.host = str(initial_host or "tnfs.zxnet.co.uk").strip()
        self.port = int(initial_port or 16384)
        self.path = "/"
        self.client = None
        self.entries = []
        self.selected_idx = 0
        self.scroll_offset = 0
        self.max_rows = 18
        self.status_msg = f"Connecting to {self.host}..."
        self.running = True
        self.downloaded_path = None
        self.mode = "BROWSE"
        self.host_input = self.host
        self.connected = False

    def connect(self, host=None, port=None):
        if host: self.host = host
        if port: self.port = port
        self.status_msg = f"Connecting to {self.host}:{self.port}..."
        self.client = TNFSClient(self.host, self.port)
        if self.client.mount(self.path):
            self.connected = True
            self.status_msg = f"CONNECTED: {self.host}"
            self.refresh_dir()
        else:
            self.connected = False
            self.status_msg = "CONNECTION FAILED / OFFLINE"
            self.entries = []

    def refresh_dir(self):
        if not self.client or not self.connected:
            return
        raw = self.client.list_files(self.path)
        self.entries = []
        if self.path != "/":
            self.entries.append("..")
        for f in raw:
            if f and f not in (".", ".."):
                self.entries.append(f)
        self.selected_idx = 0
        self.scroll_offset = 0

    def select_next(self):
        if self.entries:
            self.selected_idx = min(len(self.entries) - 1, self.selected_idx + 1)
            self._ensure_visible()

    def select_prev(self):
        if self.entries:
            self.selected_idx = max(0, self.selected_idx - 1)
            self._ensure_visible()

    def page_down(self):
        if self.entries:
            self.selected_idx = min(len(self.entries) - 1, self.selected_idx + self.max_rows)
            self._ensure_visible()

    def page_up(self):
        if self.entries:
            self.selected_idx = max(0, self.selected_idx - self.max_rows)
            self._ensure_visible()

    def _ensure_visible(self):
        if self.selected_idx < self.scroll_offset:
            self.scroll_offset = self.selected_idx
        elif self.selected_idx >= self.scroll_offset + self.max_rows:
            self.scroll_offset = self.selected_idx - self.max_rows + 1

    def handle_select(self):
        if not self.entries:
            return
        item = self.entries[self.selected_idx]
        if item == "..":
            if "/" in self.path.rstrip("/"):
                self.path = self.path.rstrip("/").rsplit("/", 1)[0]
                if not self.path: self.path = "/"
            else:
                self.path = "/"
            self.refresh_dir()
        elif "." not in item or item.endswith("/"):
            sub = item.rstrip("/")
            self.path = f"{self.path.rstrip('/')}/{sub}"
            self.refresh_dir()
        else:
            self.download_and_launch(item)

    def download_and_launch(self, filename):
        self.status_msg = f"DOWNLOADING {filename}..."
        try:
            self.render()
            if 'render_frame' in globals(): render_frame()
            if 'pygame' in globals() and pygame.display.get_init():
                pygame.display.flip()
        except Exception:
            pass
        clean_name = filename.strip().lstrip('/')
        clean_p = self.path.strip('/')
        if clean_p and not clean_name.startswith(clean_p + '/'):
            rel_path = f"{clean_p}/{clean_name}"
        else:
            rel_path = clean_name
        data = self.client.read_file(rel_path)
        if data:
            dest_dir = os.path.join(os.path.expanduser("~"), "Documents", "ZXBASIC")
            os.makedirs(dest_dir, exist_ok=True)
            base_fn = os.path.basename(filename)
            dest_path = os.path.join(dest_dir, base_fn)
            with open(dest_path, "wb") as f:
                f.write(data)
            curr_path = os.path.join(os.getcwd(), base_fn)
            if os.path.abspath(curr_path) != os.path.abspath(dest_path):
                try:
                    with open(curr_path, "wb") as cf:
                        cf.write(data)
                except Exception:
                    pass
            self.downloaded_path = dest_path
            self.status_msg = f"SAVED {filename} ({len(data)}b)"
            self.running = False
        else:
            self.status_msg = f"FAILED TO DOWNLOAD {filename}"

    def render(self):
        def print_at(r, c, text, ink=7, paper=0, bright=True, flash=False):
            for i, ch in enumerate(str(text)):
                col = c + i
                if 0 <= r < 24 and 0 <= col < 32:
                    screen_chars[r][col] = ch
                    attr_ink[r][col] = ink
                    attr_paper[r][col] = paper
                    attr_bright[r][col] = bright
                    attr_flash[r][col] = flash
                    attr_used[r][col] = True
                    if 'cell_bitmap' in globals() and cell_bitmap: cell_bitmap[r][col] = None

        title = f"TNFS: {self.host[:16]} {self.path}"[:32]
        print_at(0, 0, f"{title:<32}", ink=7, paper=1, bright=True)

        for i in range(self.max_rows):
            row = 1 + i
            idx = self.scroll_offset + i
            if idx < len(self.entries):
                entry = self.entries[idx]
                is_sel = (idx == self.selected_idx)
                prefix = "> " if is_sel else "  "
                tag = "[DIR] " if ("." not in entry or entry.endswith("/") or entry == "..") else "      "
                txt = f"{prefix}{tag}{entry}"[:32]
                ink = 0 if is_sel else (6 if tag.strip() else 7)
                paper = 7 if is_sel else 0
                print_at(row, 0, f"{txt:<32}", ink=ink, paper=paper, bright=True)
            else:
                print_at(row, 0, " " * 32, ink=7, paper=0)

        print_at(21, 0, f"{self.status_msg[:32]:<32}", ink=7, paper=2 if "FAIL" in self.status_msg else 1, bright=True)

        if self.mode == "HOST_ENTRY":
            print_at(22, 0, f"HOST: {self.host_input[:26]:<26}", ink=7, paper=0, bright=True)
            print_at(23, 0, "[ENTER]Connect [ESC]Cancel      ", ink=6, paper=0, bright=True)
        else:
            print_at(22, 0, "[ENTER]Open [U]Up [S]Host [ESC] ", ink=6, paper=0, bright=True)
            print_at(23, 0, "[Q/A/Arrows]:Move  [M]Mount %fs ", ink=5, paper=0, bright=True)


# ==============================================================================
# 6. ZX SPECTRUM IRC CLIENT
# ==============================================================================

class SpectrumIRCClient:
    def __init__(self, host="irc.libera.chat", port=6667, channel="#basinpy", nick="SpeccyUser"):
        self.host = str(host or "irc.libera.chat").strip()
        self.port = int(port or 6667)
        self.channel = str(channel or "#basinpy").strip()
        if not self.channel.startswith("#"): self.channel = "#" + self.channel
        self.nick = str(nick or "SpeccyUser").strip()
        self.sock = None
        self.running = True
        self.connected = False
        self.messages = []
        self.scroll_offset = 0
        self.max_rows = 21
        self.input_text = ""
        self.reader_thread = None

    def connect(self):
        try:
            self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.sock.settimeout(5.0)
            self.sock.connect((self.host, self.port))
            self.sock.settimeout(0.1)
            self.connected = True
            self.add_msg("SYS", f"Connected to {self.host}:{self.port}", 4)

            self.send_raw(f"NICK {self.nick}")
            self.send_raw(f"USER {self.nick} 0 * :BasinPy ZX Spectrum")
            self.send_raw(f"JOIN {self.channel}")

            self.reader_thread = threading.Thread(target=self._reader_loop, daemon=True)
            self.reader_thread.start()
        except Exception as e:
            self.connected = False
            self.add_msg("ERR", f"Connect failed: {e}", 2)

    def send_raw(self, line):
        if self.sock and self.connected:
            try:
                self.sock.sendall((line + "\r\n").encode('utf-8', errors='ignore'))
            except Exception:
                pass

    def add_msg(self, sender, text, ink=7):
        ts = time.strftime("%H:%M")
        self.messages.append((ts, sender, text, ink))
        if len(self.messages) > 200:
            self.messages.pop(0)
        self.scroll_offset = max(0, len(self.messages) - self.max_rows)

    def _reader_loop(self):
        buf = ""
        while self.running and self.connected:
            try:
                data = self.sock.recv(1024)
                if not data:
                    self.connected = False
                    self.add_msg("SYS", "Disconnected from server", 2)
                    break
                buf += data.decode('utf-8', errors='ignore')
                while "\\r\\n" in buf:
                    raw_line, buf = buf.split("\\r\\n", 1)
                    self._parse_line(raw_line)
            except socket.timeout:
                continue
            except Exception:
                break

    def _parse_line(self, line):
        if not line: return
        if line.startswith("PING"):
            pong = line.replace("PING", "PONG", 1)
            self.send_raw(pong)
            return

        prefix = ""
        trailing = ""
        if line.startswith(":"):
            parts = line[1:].split(" ", 1)
            prefix = parts[0].split("!")[0]
            line = parts[1] if len(parts) > 1 else ""
        if " :" in line:
            line, trailing = line.split(" :", 1)
            args = line.split()
            args.append(trailing)
        else:
            args = line.split()

        cmd = args.pop(0).upper() if args else ""
        if cmd == "PRIVMSG":
            target = args[0] if args else ""
            msg = args[1] if len(args) > 1 else ""
            self.add_msg(prefix, msg, 6 if prefix != self.nick else 7)
        elif cmd == "JOIN":
            ch = args[0] if args else ""
            self.add_msg("-->", f"{prefix} joined {ch}", 5)
        elif cmd == "PART":
            ch = args[0] if args else ""
            self.add_msg("<--", f"{prefix} left {ch}", 5)
        elif cmd == "QUIT":
            reason = args[0] if args else ""
            self.add_msg("<--", f"{prefix} quit ({reason})", 5)
        elif cmd in ("001", "002", "003", "004", "005", "251", "372", "376"):
            text = args[-1] if args else ""
            self.add_msg("SRV", text, 4)

    def handle_input(self, text):
        t = text.strip()
        if not t: return
        if t.startswith("/"):
            parts = t[1:].split(" ", 1)
            cmd = parts[0].upper()
            param = parts[1] if len(parts) > 1 else ""
            if cmd == "JOIN":
                ch = param.strip()
                if not ch.startswith("#"): ch = "#" + ch
                self.channel = ch
                self.send_raw(f"JOIN {self.channel}")
            elif cmd == "PART":
                self.send_raw(f"PART {self.channel}")
            elif cmd == "NICK":
                self.nick = param.strip()
                self.send_raw(f"NICK {self.nick}")
            elif cmd == "MSG":
                mp = param.split(" ", 1)
                if len(mp) == 2:
                    self.send_raw(f"PRIVMSG {mp[0]} :{mp[1]}")
                    self.add_msg(f"->{mp[0]}", mp[1], 3)
            elif cmd == "QUIT" or cmd == "EXIT":
                self.send_raw(f"QUIT :Leaving BasinPy")
                self.running = False
            else:
                self.add_msg("CMD", f"Unknown command: /{cmd}", 2)
        else:
            self.send_raw(f"PRIVMSG {self.channel} :{t}")
            self.add_msg(self.nick, t, 7)

    def render(self):
        def print_at(r, c, text, ink=7, paper=0, bright=True, flash=False):
            for i, ch in enumerate(str(text)):
                col = c + i
                if 0 <= r < 24 and 0 <= col < 32:
                    screen_chars[r][col] = ch
                    attr_ink[r][col] = ink
                    attr_paper[r][col] = paper
                    attr_bright[r][col] = bright
                    attr_flash[r][col] = flash
                    attr_used[r][col] = True
                    if 'cell_bitmap' in globals() and cell_bitmap: cell_bitmap[r][col] = None

        title = f"IRC:{self.nick} on {self.channel}"[:32]
        print_at(0, 0, f"{title:<32}", ink=7, paper=1, bright=True)

        for i in range(self.max_rows):
            row = 1 + i
            idx = self.scroll_offset + i
            if idx < len(self.messages):
                ts, sender, text, ink = self.messages[idx]
                line_str = f"<{sender[:6]}> {text}"[:32]
                print_at(row, 0, f"{line_str:<32}", ink=ink, paper=0, bright=True)
            else:
                print_at(row, 0, " " * 32, ink=7, paper=0)

        print_at(22, 0, "-" * 32, ink=1, paper=0, bright=True)
        inp = f">{self.input_text}"[-32:]
        print_at(23, 0, f"{inp:<32}", ink=7, paper=0, bright=True)


# ==============================================================================
# 7. ZX SPECTRUM GOPHER CLIENT (RFC 1436)
# ==============================================================================

class SpectrumGopherClient:
    def __init__(self, host="gopher.floodgap.com", port=70, selector="/"):
        self.host = str(host or "gopher.floodgap.com").strip()
        self.port = int(port or 70)
        self.selector = str(selector or "/").strip()
        self.history = []
        self.items = []
        self.text_lines = []
        self.mode = "MENU"
        self.selected_idx = 0
        self.scroll_offset = 0
        self.max_rows = 21
        self.running = True
        self.status_msg = f"Connecting to {self.host}..."

    def fetch(self, host=None, port=None, selector=None, is_back=False):
        if not is_back and self.host:
            self.history.append((self.host, self.port, self.selector, self.mode))
        if host: self.host = host
        if port: self.port = port
        if selector is not None: self.selector = selector

        self.status_msg = f"Fetching {self.host}:{self.port}{self.selector}..."
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.settimeout(5.0)
            s.connect((self.host, self.port))
            req = (self.selector + "\\r\\n").encode('latin1')
            s.sendall(req)

            chunks = []
            while True:
                data = s.recv(4096)
                if not data: break
                chunks.append(data)
            s.close()
            payload = b"".join(chunks).decode('latin1', errors='ignore')

            if self.mode == "TEXT":
                self.text_lines = payload.splitlines()
                self.scroll_offset = 0
            else:
                self.items = self._parse_menu(payload)
                self.selected_idx = 0
                self.scroll_offset = 0
            self.status_msg = f"LOADED {len(payload)} bytes"
        except Exception as e:
            self.status_msg = f"ERROR: {e}"

    def _parse_menu(self, text):
        items = []
        for line in text.splitlines():
            if not line or line == ".": continue
            itype = line[0]
            parts = line[1:].split("\\t")
            disp = parts[0] if len(parts) > 0 else ""
            sel = parts[1] if len(parts) > 1 else ""
            h = parts[2] if len(parts) > 2 else self.host
            p = int(parts[3]) if len(parts) > 3 and parts[3].isdigit() else self.port
            items.append({
                "type": itype,
                "display": disp,
                "selector": sel,
                "host": h,
                "port": p
            })
        return items

    def go_back(self):
        if self.history:
            h, p, sel, mode = self.history.pop()
            self.mode = mode
            self.fetch(h, p, sel, is_back=True)

    def select_item(self, idx):
        nav_items = [it for it in self.items if it["type"] not in ("i", "3")]
        if 0 <= idx < len(nav_items):
            target = nav_items[idx]
            if target["type"] == "0":
                self.mode = "TEXT"
                self.fetch(target["host"], target["port"], target["selector"])
            elif target["type"] == "1":
                self.mode = "MENU"
                self.fetch(target["host"], target["port"], target["selector"])

    def render(self):
        def print_at(r, c, text, ink=7, paper=0, bright=True, flash=False):
            for i, ch in enumerate(str(text)):
                col = c + i
                if 0 <= r < 24 and 0 <= col < 32:
                    screen_chars[r][col] = ch
                    attr_ink[r][col] = ink
                    attr_paper[r][col] = paper
                    attr_bright[r][col] = bright
                    attr_flash[r][col] = flash
                    attr_used[r][col] = True
                    if 'cell_bitmap' in globals() and cell_bitmap: cell_bitmap[r][col] = None

        title = f"GOPHER: {self.host[:18]} {self.selector[:10]}"[:32]
        print_at(0, 0, f"{title:<32}", ink=7, paper=1, bright=True)

        if self.mode == "TEXT":
            for i in range(self.max_rows):
                row = 1 + i
                idx = self.scroll_offset + i
                if idx < len(self.text_lines):
                    line = self.text_lines[idx][:32]
                    print_at(row, 0, f"{line:<32}", ink=7, paper=0, bright=True)
                else:
                    print_at(row, 0, " " * 32, ink=7, paper=0)
            print_at(22, 0, f"Line {self.scroll_offset}/{len(self.text_lines)} [B]Back [ESC]Quit"[:32], ink=6, paper=0, bright=True)
            print_at(23, 0, "[SPACE]Down [U]Up [ESC]Exit     ", ink=5, paper=0, bright=True)
        else:
            nav_idx = 1
            for i in range(self.max_rows):
                row = 1 + i
                idx = self.scroll_offset + i
                if idx < len(self.items):
                    item = self.items[idx]
                    itype = item["type"]
                    disp = item["display"]
                    if itype == "i":
                        print_at(row, 0, f"{disp[:32]:<32}", ink=6, paper=0, bright=False)
                    elif itype == "1":
                        txt = f"{nav_idx}. [DIR] {disp}"[:32]
                        print_at(row, 0, f"{txt:<32}", ink=5, paper=0, bright=True)
                        nav_idx += 1
                    elif itype == "0":
                        txt = f"{nav_idx}. [TXT] {disp}"[:32]
                        print_at(row, 0, f"{txt:<32}", ink=7, paper=0, bright=True)
                        nav_idx += 1
                    elif itype == "7":
                        txt = f"{nav_idx}. [<?> SEARCH]"[:32]
                        print_at(row, 0, f"{txt:<32}", ink=4, paper=0, bright=True)
                        nav_idx += 1
                    else:
                        txt = f"{nav_idx}. [BIN] {disp}"[:32]
                        print_at(row, 0, f"{txt:<32}", ink=3, paper=0, bright=True)
                        nav_idx += 1
                else:
                    print_at(row, 0, " " * 32, ink=7, paper=0)
            print_at(22, 0, f"{self.status_msg[:32]:<32}", ink=7, paper=2 if "ERR" in self.status_msg else 1, bright=True)
            print_at(23, 0, "[1..9]Select [U]Up [ESC]Exit    ", ink=6, paper=0, bright=True)


# ==============================================================================
# 8. ZX SPECTRUM TERMINAL EMULATOR (TELNET / BBS)
# ==============================================================================

class SpectrumTerminalEmulator:
    def __init__(self, host="telehack.com", port=23, rows=24, cols=32):
        self.host = str(host or "telehack.com").strip()
        self.port = int(port or 23)
        self.rows = rows
        self.cols = cols
        self.sock = None
        self.running = True
        self.connected = False
        self.chars = [[" " for _ in range(cols)] for _ in range(rows)]
        self.colors = [[7 for _ in range(cols)] for _ in range(rows)]
        self.papers = [[0 for _ in range(cols)] for _ in range(rows)]
        self.cur_r = 0
        self.cur_c = 0
        self.reader_thread = None

    def connect(self):
        try:
            self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.sock.settimeout(5.0)
            self.sock.connect((self.host, self.port))
            self.sock.settimeout(0.05)
            self.connected = True
            self.reader_thread = threading.Thread(target=self._reader_loop, daemon=True)
            self.reader_thread.start()
        except Exception as e:
            self.connected = False
            self.feed_text(f"Connect failed: {e}\r\n")

    def _reader_loop(self):
        while self.running and self.connected:
            try:
                data = self.sock.recv(1024)
                if not data:
                    self.connected = False
                    break
                clean_data = self._filter_telnet_iac(data)
                self.feed_text(clean_data.decode('latin1', errors='ignore'))
            except socket.timeout:
                continue
            except Exception:
                break

    def _filter_telnet_iac(self, data):
        IAC = 0xFF
        i = 0
        clean = bytearray()
        while i < len(data):
            b = data[i]
            if b == IAC:
                if i + 1 < len(data):
                    cmd = data[i + 1]
                    if cmd in (251, 252, 253, 254):
                        opt = data[i + 2] if i + 2 < len(data) else 0
                        if cmd == 253:
                            try: self.sock.sendall(bytes([IAC, 252, opt]))
                            except Exception: pass
                        elif cmd == 251:
                            try: self.sock.sendall(bytes([IAC, 253, opt]))
                            except Exception: pass
                        i += 3
                        continue
                    elif cmd == 250:
                        se_idx = data.find(bytes([IAC, 240]), i + 2)
                        if se_idx != -1: i = se_idx + 2
                        else: i = len(data)
                        continue
                    elif cmd == IAC:
                        clean.append(IAC)
                        i += 2
                        continue
                    else:
                        i += 2
                        continue
                else:
                    break
            else:
                clean.append(b)
                i += 1
        return bytes(clean)

    def feed_text(self, text):
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "\x1b":
                if i + 1 < len(text) and text[i+1] == "[":
                    j = i + 2
                    while j < len(text) and not ("A" <= text[j] <= "Z" or "a" <= text[j] <= "z"):
                        j += 1
                    if j < len(text):
                        cmd = text[j]
                        param_str = text[i+2:j]
                        self._handle_csi(cmd, param_str)
                        i = j + 1
                        continue
                    else:
                        break
                else:
                    i += 1
                    continue
            elif ch == "\r":
                self.cur_c = 0
                i += 1
            elif ch == "\n":
                self.cur_r += 1
                if self.cur_r >= self.rows:
                    self._scroll_up()
                i += 1
            elif ch == "\b":
                self.cur_c = max(0, self.cur_c - 1)
                i += 1
            else:
                if 0 <= self.cur_r < self.rows and 0 <= self.cur_c < self.cols:
                    self.chars[self.cur_r][self.cur_c] = ch
                    self.cur_c += 1
                    if self.cur_c >= self.cols:
                        self.cur_c = 0
                        self.cur_r += 1
                        if self.cur_r >= self.rows:
                            self._scroll_up()
                i += 1

    def _scroll_up(self):
        for r in range(self.rows - 1):
            self.chars[r] = list(self.chars[r+1])
            self.colors[r] = list(self.colors[r+1])
            self.papers[r] = list(self.papers[r+1])
        self.chars[self.rows - 1] = [" " for _ in range(self.cols)]
        self.colors[self.rows - 1] = [7 for _ in range(self.cols)]
        self.papers[self.rows - 1] = [0 for _ in range(self.cols)]
        self.cur_r = self.rows - 1

    def _handle_csi(self, cmd, params):
        parts = [int(p) for p in params.split(";") if p.isdigit()]
        if cmd in ("H", "f"):
            r = (parts[0] - 1) if len(parts) > 0 else 0
            c = (parts[1] - 1) if len(parts) > 1 else 0
            self.cur_r = max(0, min(self.rows - 1, r))
            self.cur_c = max(0, min(self.cols - 1, c))
        elif cmd == "A":
            n = parts[0] if parts else 1
            self.cur_r = max(0, self.cur_r - n)
        elif cmd == "B":
            n = parts[0] if parts else 1
            self.cur_r = min(self.rows - 1, self.cur_r + n)
        elif cmd == "C":
            n = parts[0] if parts else 1
            self.cur_c = min(self.cols - 1, self.cur_c + n)
        elif cmd == "D":
            n = parts[0] if parts else 1
            self.cur_c = max(0, self.cur_c - n)
        elif cmd == "J":
            self.chars = [[" " for _ in range(self.cols)] for _ in range(self.rows)]
            self.cur_r = 0
            self.cur_c = 0
        elif cmd == "K":
            if 0 <= self.cur_r < self.rows:
                for c in range(self.cur_c, self.cols):
                    self.chars[self.cur_r][c] = " "

    def send_input(self, text):
        if self.sock and self.connected:
            try:
                self.sock.sendall(text.encode('latin1', errors='ignore'))
            except Exception:
                pass

    def render(self):
        for r in range(self.rows):
            for c in range(self.cols):
                screen_chars[r][c] = self.chars[r][c]
                attr_ink[r][c] = self.colors[r][c]
                attr_paper[r][c] = self.papers[r][c]
                attr_bright[r][c] = True
                attr_flash[r][c] = (r == self.cur_r and c == self.cur_c)
                attr_used[r][c] = True
                if 'cell_bitmap' in globals() and cell_bitmap: cell_bitmap[r][c] = None


