# 9. LAUNCHERS & BASIC DISPATCH HANDLERS
# ==============================================================================

def launch_tnfs_browser(args=""):
    global current_border, canvas_dirty
    parts = (args or "").strip().split()
    host = parts[0].strip(' "\\\'') if parts else "tnfs.zxnet.co.uk"
    port = int(parts[1]) if len(parts) > 1 and parts[1].isdigit() else 16384

    saved_chars = [list(row) for row in screen_chars]
    saved_ink = [list(row) for row in attr_ink]
    saved_paper = [list(row) for row in attr_paper]
    saved_bright = [list(row) for row in attr_bright]
    saved_flash = [list(row) for row in attr_flash]
    saved_used = [list(row) for row in attr_used]
    saved_border = current_border

    current_border = 1
    browser = TNFSBrowser(host, port)
    browser.connect()

    is_dummy = (os.environ.get("SDL_VIDEODRIVER") == "dummy") or ('running' in globals() and not running)
    if is_dummy:
        browser.render()
        return browser

    clock = pygame.time.Clock()
    try:
        while browser.running:
            clock.tick(60)
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    browser.running = False
                    pygame.quit()
                    sys.exit(0)
                elif event.type == pygame.KEYDOWN:
                    if event.key in (pygame.K_UP, pygame.K_q):
                        browser.select_prev()
                    elif event.key in (pygame.K_DOWN, pygame.K_a):
                        browser.select_next()
                    elif event.key == pygame.K_PAGEUP:
                        browser.page_up()
                    elif event.key == pygame.K_PAGEDOWN:
                        browser.page_down()
                    elif event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                        browser.handle_select()
                    elif event.key in (pygame.K_u, pygame.K_BACKSPACE):
                        browser.path = browser.path.rstrip("/").rsplit("/", 1)[0] or "/"
                        browser.refresh_dir()
                    elif event.key == pygame.K_m:
                        spectranet_subsystem.mounted_drives[0] = {
                            "host": browser.host,
                            "port": browser.port,
                            "path": browser.path,
                            "client": browser.client
                        }
                        browser.status_msg = f"MOUNTED AS DRIVE 0 (%fs)"
                    elif event.key == pygame.K_ESCAPE:
                        browser.running = False

            browser.render()
            render_frame()
            try: pygame.display.flip()
            except Exception: pass
    finally:
        pass

    if browser.downloaded_path and os.path.exists(browser.downloaded_path):
        canvas.fill(COLORS[current_paper])
        canvas_dirty = True
        update_display()
        load_program_file(browser.downloaded_path, mode="RUN")
    else:
        current_border = saved_border
        for r in range(24):
            for c in range(32):
                screen_chars[r][c] = saved_chars[r][c]
                attr_ink[r][c] = saved_ink[r][c]
                attr_paper[r][c] = saved_paper[r][c]
                attr_bright[r][c] = saved_bright[r][c]
                attr_flash[r][c] = saved_flash[r][c]
                attr_used[r][c] = saved_used[r][c]
                if 'cell_bitmap' in globals() and cell_bitmap: cell_bitmap[r][c] = None
        canvas_dirty = True
        update_display()
    return browser


