def handle_tnfs_command(args=""):
    global active_tnfs_server
    a_up = (args or "").strip().upper()
    if a_up.startswith("SERVER"):
        rem = (args or "")[6:].strip()
        parts = rem.split(None, 1)
        port = int(parts[0]) if parts and parts[0].isdigit() else 16384
        folder = parts[1].strip(' "\\\'') if len(parts) > 1 else os.path.join(os.getcwd(), "tnfs_root")
        if not os.path.exists(folder):
            os.makedirs(folder, exist_ok=True)
        if active_tnfs_server:
            active_tnfs_server.stop()
        active_tnfs_server = TNFSServer(folder, port)
        active_tnfs_server.start()
        canvas_print(f"TNFS Server started on UDP {port} ({folder})")
    else:
        launch_tnfs_browser(args)


def handle_spectranet_basic_cmd(stmt_str):
    s = stmt_str.strip()
    if s.startswith("%"): s = s[1:].strip()
    parts = s.split(None, 1)
    cmd = parts[0].upper() if parts else ""
    arg = parts[1].strip() if len(parts) > 1 else ""

    if cmd == "MOUNT":
        # %mount <drive>, "<host>" [, "<path>"]
        m_parts = [p.strip(' "\\\'') for p in arg.split(",")]
        drive = int(m_parts[0]) if m_parts and m_parts[0].isdigit() else 0
        host = m_parts[1] if len(m_parts) > 1 else "tnfs.zxnet.co.uk"
        path = m_parts[2] if len(m_parts) > 2 else "/"
        client = TNFSClient(host, 16384)
        if client.mount(path):
            spectranet_subsystem.mounted_drives[drive] = {
                "host": host, "port": 16384, "path": path, "client": client
            }
            canvas_print(f"Mounted TNFS drive {drive}: {host}:{path}")
        else:
            canvas_print(f"Failed to mount TNFS {host}")
    elif cmd in ("UMOUNT", "UNMOUNT"):
        drive = int(arg) if arg.isdigit() else 0
        if drive in spectranet_subsystem.mounted_drives:
            spectranet_subsystem.mounted_drives.pop(drive, None)
            canvas_print(f"Unmounted drive {drive}")
        else:
            canvas_print(f"Drive {drive} not mounted")
    elif cmd == "FS":
        canvas_print("--- MOUNTED TNFS FILESYSTEMS ---")
        if not spectranet_subsystem.mounted_drives:
            canvas_print("No network drives mounted")
        for d, info in spectranet_subsystem.mounted_drives.items():
            canvas_print(f"Drive {d}: {info['host']} ({info['path']})")
    elif cmd in ("CAT", "LS"):
        drive = int(arg) if arg.isdigit() else 0
        info = spectranet_subsystem.mounted_drives.get(drive)
        if info:
            canvas_print(f"--- CAT DRIVE {drive}: {info['host']} ---")
            files = info["client"].list_files(info["path"])
            for f in files[:12]:
                canvas_print(f)
        else:
            canvas_print(f"Drive {drive} not mounted")
    elif cmd == "CD":
        new_path = arg.strip(' "\\\'')
        info = spectranet_subsystem.mounted_drives.get(0)
        if info:
            info["path"] = new_path
            canvas_print(f"Directory changed to {new_path}")
        else:
            canvas_print("Drive 0 not mounted")
    elif cmd in ("IFCONFIG", "NETSTAT", "STATUS"):
        handle_net_cmd("NET STATUS")
    elif cmd == "DHCP":
        spectranet_subsystem.dhcp_enabled = (arg.upper() != "OFF")
        canvas_print(f"DHCP {'Enabled' if spectranet_subsystem.dhcp_enabled else 'Disabled'}")
    elif cmd == "SETHW":
        new_mac = arg.strip(' "\\\'')
        if new_mac:
            spectranet_subsystem.mac = new_mac
            spectranet_subsystem._init_w5100_regs()
            canvas_print(f"MAC set to {new_mac}")
    elif cmd == "PING":
        host = arg.strip(' "\\\'') or "127.0.0.1"
        try:
            t0 = time.time()
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.settimeout(2.0)
            ip = socket.gethostbyname(host)
            s.connect((ip, 80 if host != "127.0.0.1" else 16384))
            s.close()
            ms = int((time.time() - t0) * 1000)
            canvas_print(f"Ping {host} ({ip}): {ms}ms OK")
        except Exception:
            try:
                ip = socket.gethostbyname(host)
                canvas_print(f"Ping {host} ({ip}): Host resolved")
            except Exception as e:
                canvas_print(f"Ping {host} failed: {e}")
    elif cmd == "TNFS":
        handle_tnfs_command(arg)
    elif cmd == "IRC":
        launch_irc_client(arg)
    elif cmd in ("GOPHER", "GOPER"):
        launch_gopher_client(arg)
    elif cmd == "TERM":
        launch_terminal_emulator(arg)
    elif cmd == "NET" or cmd.startswith("NET"):
        handle_net_cmd(s)
    elif cmd in ("HELP", "?"):
        canvas_print("--- Spectranet / Network Commands ---")
        canvas_print("%MOUNT <drv>,\"host\"[,\"path\"]")
        canvas_print("%UMOUNT <drv> | %FS | %CAT <drv>")
        canvas_print("%CD \"path\"    | %PING \"host\"")
        canvas_print("%DHCP [ON|OFF] | %SETHW \"mac\"")
        canvas_print("%IFCONFIG      | %NET [STATUS|SET|PING]")
        canvas_print("TNFS | IRC | GOPHER | TERM | NET")
    else:
        canvas_print(f"Unknown Spectranet command: %{cmd}")


def handle_net_cmd(stmt_str):
    s = stmt_str.strip()
    s_up = s.upper()
    if s_up in ("NET STATUS", "NETSTATUS", "IFCONFIG", "NETCFG", "NET"):
        canvas_print("--- BasinPy Network Status ---")
        canvas_print("Hardware: Spectranet + Next WiFi")
        canvas_print(f"MAC:      {spectranet_subsystem.mac}")
        canvas_print(f"IP:       {spectranet_subsystem.ip}")
        canvas_print(f"Mask:     {spectranet_subsystem.netmask}")
        canvas_print(f"Gateway:  {spectranet_subsystem.gateway}")
        canvas_print(f"DNS:      {spectranet_subsystem.dns}")
        canvas_print(f"DHCP:     {'Enabled' if spectranet_subsystem.dhcp_enabled else 'Disabled'}")
        canvas_print("Spectranet: W5100 + Traps Active")
        canvas_print("Next WiFi:  Ports #143B/#153B Active")
    elif s_up.startswith("NET SET") or s_up.startswith("NETSET") or s_up.startswith("NETCFG "):
        arg = s[7:].strip() if s_up.startswith("NET SET") else (s[6:].strip() if s_up.startswith("NETSET") else s[7:].strip())
        parts = split_top_level_commas(arg) if 'split_top_level_commas' in globals() else [p.strip() for p in arg.split(",")]
        if len(parts) >= 2:
            key = str(evaluate_expr(parts[0]) if 'evaluate_expr' in globals() else parts[0]).strip(' "\\\'').upper()
            val = str(evaluate_expr(parts[1]) if 'evaluate_expr' in globals() else parts[1]).strip(' "\\\'')
            if key == "IP":
                spectranet_subsystem.ip = val
            elif key in ("MASK", "NETMASK"):
                spectranet_subsystem.netmask = val
            elif key == "GATEWAY":
                spectranet_subsystem.gateway = val
            elif key == "DNS":
                spectranet_subsystem.dns = val
            elif key == "MAC":
                spectranet_subsystem.mac = val
            elif key == "DHCP":
                spectranet_subsystem.dhcp_enabled = (val in ("1", "TRUE", "ON"))
            spectranet_subsystem._init_w5100_regs()
            canvas_print(f"Network '{key}' updated to '{val}'")
        else:
            canvas_print("Syntax: NET SET <setting$>, <val>")
    elif s_up.startswith("NET PING") or s_up.startswith("NETPING"):
        arg = s[8:].strip() if s_up.startswith("NET PING") else s[7:].strip()
        handle_spectranet_basic_cmd(f"%ping {arg}")
    else:
        canvas_print("Syntax: NET STATUS | NET SET <key>, <val> | NET PING <host>")


def swap_cartridge_rom(rom_bytes, name="Custom Cartridge"):
    """
    Swap machine code / binary ROM data into the ZX Interface 2 Cartridge ROM slot (0x0000..0x3FFF).
    Maintains backup of original 48K BASIC ROM.
    """
    global basic_rom_backup, cartridge_rom, cartridge_inserted, cartridge_file_name, memory
    if 'basic_rom_backup' not in globals() or basic_rom_backup is None:
        basic_rom_backup = bytearray(memory[:16384])
    
    rom_buf = bytearray(16384)
    if len(rom_bytes) <= 8192:
        # 8KB cartridge mirrored to 16KB
        rom_buf[0 : len(rom_bytes)] = rom_bytes
        rom_buf[8192 : 8192 + len(rom_bytes)] = rom_bytes
    else:
        copy_len = min(16384, len(rom_bytes))
        rom_buf[0 : copy_len] = rom_bytes[:copy_len]
        
    cartridge_rom = rom_buf
    cartridge_inserted = True
    cartridge_file_name = name
    memory[0 : 16384] = cartridge_rom
    return len(rom_bytes)


def eject_cartridge_rom():
    """
    Eject ZX Interface 2 Cartridge ROM and restore the authentic Sinclair ZX Spectrum 48K BASIC ROM.
    """
    global basic_rom_backup, cartridge_rom, cartridge_inserted, cartridge_file_name, memory
    if 'basic_rom_backup' in globals() and basic_rom_backup is not None:
        memory[0 : 16384] = basic_rom_backup[:16384]
    elif 'ZX_48K_ROM' in globals():
        memory[0 : 16384] = ZX_48K_ROM[:16384]
    cartridge_inserted = False
    cartridge_rom = None
    cartridge_file_name = ""


def handle_cartridge_command(cmd_str):
    global cartridge_inserted, cartridge_rom, cartridge_file_name, memory, zeus_source
    s = cmd_str.strip()
    s_upper = s.upper()
    if s_upper.startswith("CARTRIDGE"):
        s = s[9:].strip()
    elif s_upper.startswith("ROM"):
        s = s[3:].strip()
    if s.startswith(":"):
        s = s[1:].strip()
    sub_upper = s.upper().strip()
    
    if sub_upper.startswith("SWAP") or sub_upper.startswith("MAP"):
        arg_part = s[4:].strip() if sub_upper.startswith("SWAP") else s[3:].strip()
        if arg_part.startswith(":"): arg_part = arg_part[1:].strip()
        if arg_part:
            parts = split_top_level_commas(arg_part)
            try:
                addr = int(to_float(evaluate_expr(parts[0]))) & 0xFFFF
                length = 16384
                if len(parts) > 1 and parts[1].strip():
                    length = min(16384, int(to_float(evaluate_expr(parts[1]))))
                code_data = memory[addr : addr + length]
                swap_cartridge_rom(code_data, name=f"Z80 code from #{addr:04X}")
                canvas_print(f"Swapped {len(code_data)} bytes from #{addr:04X} into Cartridge ROM (0x0000..0x3FFF).")
                canvas_print("Type RESET to boot into cartridge.")
            except Exception as e:
                canvas_print(f"Cartridge SWAP error: {e}")
        else:
            asm = get_zeus_assembler()
            cbytes = getattr(asm, 'code_bytes', None)
            if (not cbytes or len(cbytes) == 0) and zeus_source:
                try:
                    full_src = "\n".join(zeus_source[k] for k in sorted(zeus_source.keys()))
                    cbytes = asm.assemble(full_src, target_memory=memory)
                except Exception as ex:
                    canvas_print(f"Assembly error during cartridge swap: {ex}")
                    return
            if cbytes and len(cbytes) > 0:
                swap_cartridge_rom(cbytes, name="Zeus Assembled Cartridge")
                canvas_print(f"Swapped {len(cbytes)} bytes of Zeus machine code into Cartridge ROM (0x0000..0x3FFF).")
                canvas_print("Type RESET to boot into cartridge.")
            else:
                canvas_print("No assembled Z80 code in Zeus buffer. Provide address: CARTRIDGE SWAP <addr> [, <len>]")
    elif sub_upper in ("EJECT", "UNLOAD", "REMOVE", "OFF"):
        eject_cartridge_rom()
        canvas_print("Interface 2 Cartridge ejected. Sinclair 48K BASIC ROM restored.")
    elif sub_upper in ("RESET", "BOOT", "RUN"):
        handle_system_reset()
    elif sub_upper.startswith("LOAD "):
        handle_load_command(f"{s[5:].strip()}, ROM")
    elif sub_upper.startswith("SAVE "):
        handle_save_command(f"{s[5:].strip()}, ROM")
    else:
        if cartridge_inserted:
            canvas_print(f"Cartridge Active: '{cartridge_file_name}' ({len(cartridge_rom)} bytes in 0x0000..0x3FFF)")
            canvas_print("Commands: CARTRIDGE SWAP, CARTRIDGE EJECT, RESET")
        else:
            canvas_print("No Interface 2 Cartridge inserted (Sinclair 48K ROM active in 0x0000..0x3FFF).")
            canvas_print("Usage: LOAD \"game.rom\", ROM  or  CARTRIDGE SWAP [<addr>]")
    update_display()


def handle_system_reset():
    global cartridge_inserted, cartridge_rom, cartridge_file_name, z80_cpu, can_continue_mc, suspended_mc_cpu, autorun_enabled
    autorun_enabled = True
    can_continue_mc = False
    suspended_mc_cpu = None
    cpu = get_z80_cpu()
    cpu.reset()
    
    if cartridge_inserted and cartridge_rom:
        memory[0 : min(16384, len(cartridge_rom))] = cartridge_rom[:16384]
        execute_cls()
        init_system_variables()
        name = cartridge_file_name if cartridge_file_name else "Cartridge ROM"
        canvas_print("Sinclair ZX Interface 2 - Cartridge Boot")
        canvas_print(f"Executing '{name}' at 0x0000...")
        update_display()
        cpu.PC = 0x0000
        cpu.SP = 0xFFFE
        if len(memory) >= 0x10000:
            memory[0xFFFE] = 0x00
            memory[0xFFFF] = 0x00
        steps = cpu.run(stop_on_ret=True)
        if getattr(cpu, 'suspended_by_break', False):
            can_continue_mc = True
            suspended_mc_cpu = cpu
            canvas_print(f"[MULTIFACE BREAK at PC #{cpu.PC:04X}] - CONT to resume")
        else:
            canvas_print(f"Cartridge execution halted at PC #{cpu.PC:04X} ({steps} instructions).")
        update_display()
    else:
        memory[0 : 16384] = basic_rom_backup[:16384] if ('basic_rom_backup' in globals() and basic_rom_backup) else ZX_48K_ROM[:16384]
        perform_new()
        execute_cls()
        init_system_variables()
        canvas_print("\n(C) 1982 Sinclair Research Ltd")
        update_display()


def handle_cont_command():
    global can_continue_mc, suspended_mc_cpu, can_continue, last_run_index, last_sub_index
    if can_continue_mc and suspended_mc_cpu is not None:
        can_continue_mc = False
        cpu = suspended_mc_cpu
        suspended_mc_cpu = None
        cpu.suspended_by_break = False
        canvas_print(f"Resuming machine code at PC #{cpu.PC:04X}...")
        update_display()
        steps = cpu.run(stop_on_ret=True)
        if getattr(cpu, 'suspended_by_break', False):
            can_continue_mc = True
            suspended_mc_cpu = cpu
            canvas_print(f"[MULTIFACE BREAK at PC #{cpu.PC:04X}] - CONT to resume")
            update_display()
            return
        else:
            canvas_print(f"Machine code completed ({steps} instructions). BC={cpu.BC}")
            update_display()
            if can_continue:
                run_program(last_run_index, last_sub_index, is_continue=True)
    elif can_continue:
        run_program(last_run_index, last_sub_index, is_continue=True)
    else:
        canvas_print("0 OK")
        update_display()


def handle_peek_command(stmt_str):
    s = stmt_str.strip()
    s_upper = s.upper()
    if s_upper.startswith("PEEK"):
        s = s[4:].strip()
    elif s_upper.startswith("PEKK"):
        s = s[4:].strip()
    if s.startswith("(") and s.endswith(")"):
        s = s[1:-1].strip()
    elif s.startswith(":"):
        s = s[1:].strip()
    parts = split_top_level_commas(s)
    if not parts or not parts[0].strip():
        canvas_print("Usage: PEEK <address> [, <count>]")
        update_display()
        return
    try:
        addr = int(to_float(evaluate_expr(parts[0]))) & 0xFFFF
        count = 1
        if len(parts) > 1 and parts[1].strip():
            count = max(1, min(256, int(to_float(evaluate_expr(parts[1])))))
        
        if count == 1:
            val = memory[addr]
            ch = chr(val) if 32 <= val <= 126 else "."
            canvas_print(f"PEEK {addr} (0x{addr:04X}) = {val} (0x{val:02X}) '{ch}'")
        else:
            for b_addr in range(addr, addr + count, 16):
                c_len = min(16, addr + count - b_addr)
                chunk = memory[b_addr : b_addr + c_len]
                hex_s = " ".join(f"{b:02X}" for b in chunk)
                asc_s = "".join(chr(b) if 32 <= b <= 126 else "." for b in chunk)
                canvas_print(f"{b_addr:04X}: {hex_s:<48}  {asc_s}")
    except Exception as e:
        canvas_print(f"PEEK error: {e}")
    update_display()


# ==============================================================================
# SINCLAIR ZX 2-PANEL FILE COMMANDER (NORTON COMMANDER STYLE)
# ==============================================================================

class ZXCommanderPanel:
    """Represents one of the two panels in the Sinclair ZX File Commander."""
    def __init__(self, side="left", media_type="HOST"):
        self.side = side
        self.col_start = 0 if side == "left" else 16
        self.col_width = 15
        self.media_type = media_type.upper()
        self.current_path = "/"
        self.file_list = []
        self.selected_idx = 0
        self.scroll_offset = 0
        self.tagged = set()

    def get_selected(self):
        if self.file_list and 0 <= self.selected_idx < len(self.file_list):
            return self.file_list[self.selected_idx]
        return None


class ZXCommander:
    """
    Classic Sinclair ZX 2-Panel File Commander (Norton Commander style).
    Renders on the 32x24 Sinclair Spectrum character display (Paper Blue, Ink White/Cyan).
    Supports AMX Mouse, Lotus 1-2-3 style keyboard menu (/), and multi-media operations
    (Floppy Disk, Microdrive, Tape, RAM Disk, Host Files, Spectranet TNFS & IF1 Network).
    """
    LOTUS_MENU = [
        ("Files", "Copy, Move, Erase, Rename, Info, Refresh"),
        ("Disk", "Drive 1, Drive 2, Mount .DSK, Eject"),
        ("Microdrive", "Drive 1, Drive 2, Mount .MDR, Eject"),
        ("Tape", "Open .TAP, Info, Extract, Close"),
        ("Network", "Connect TNFS, Disconnect, Send IF1, Recv IF1"),
        ("View", "File Info, Hex Dump, Text View"),
        ("Quit", "Exit ZX Commander to Sinclair BASIC")
    ]

    def __init__(self, left_media="HOST", right_media="RAM"):
        self.left = ZXCommanderPanel("left", left_media)
        self.right = ZXCommanderPanel("right", right_media)
        self.active_side = "left"
        self.lotus_menu_active = False
        self.lotus_menu_idx = 0
        self.lotus_sub_idx = 0
        self.status_msg = "Ready. TAB=swap /:menu F5:copy F6:move F7:del"
        self.modal = None  # None or dict(type="info"|"confirm_del"|"copy"|"move"|"media_pick"|"help", ...)
        self.modal_input = ""
        self.tnfs_client = None
        self.running = True
        self.last_click_time = 0
        self.last_click_item = None
        self.refresh_all()

    @property
    def active(self):
        return self.left if self.active_side == "left" else self.right

    @property
    def passive(self):
        return self.right if self.active_side == "left" else self.left

    def refresh_all(self):
        self.refresh_panel(self.left)
        self.refresh_panel(self.right)

    def refresh_panel(self, panel):
        m = panel.media_type
        files = []
        if m == "HOST":
            folder = get_zx_folder()
            cwd = os.getcwd()
            seen = set()
            valid_exts = ('.tap', '.zxb', '.zxbcode', '.dzxdata', '.mdr', '.sbin', '.sert', '.net', '.fdi', '.bas', '.dsk', '.imd', '.img', '.fth', '.zxf', '.rom', '.bin', '.scr')
            for d in (folder, cwd):
                if os.path.exists(d):
                    try:
                        for fn in os.listdir(d):
                            fp = os.path.join(d, fn)
                            if os.path.isfile(fp) and fn.lower() not in seen:
                                seen.add(fn.lower())
                                ext = os.path.splitext(fn)[1].lower()
                                if ext in valid_exts:
                                    sz = os.path.getsize(fp)
                                    files.append({
                                        "name": fn,
                                        "size": sz,
                                        "type": ext.strip('.').upper() or "FILE",
                                        "extra": f"{sz // 1024}K" if sz >= 1024 else f"{sz}B",
                                        "raw": fp
                                    })
                    except Exception:
                        pass
            files.sort(key=lambda x: x["name"].lower())
        elif m == "RAM":
            for fname, finfo in sorted(ram_disk.items()):
                if isinstance(finfo, dict):
                    sz = finfo.get("size", len(finfo.get("data", b"")))
                    ftype = finfo.get("type", "CODE")
                else:
                    sz = len(finfo)
                    ftype = "CODE"
                files.append({
                    "name": fname,
                    "size": sz,
                    "type": ftype,
                    "extra": f"{sz}B",
                    "raw": finfo
                })
        elif m in ("DSK1", "DSK2"):
            d_num = 1 if m == "DSK1" else 2
            disk = mgt_drives.get(d_num)
            if disk and getattr(disk, 'raw_data', None):
                try:
                    dfiles = disk.list_files()
                    for f in dfiles:
                        name = f.get("name", "FILE")
                        sz = f.get("length", f.get("sectors", 1) * 512)
                        ftype = f.get("type_name", "CODE")
                        files.append({
                            "name": name,
                            "size": sz,
                            "type": ftype,
                            "extra": f"{sz}B",
                            "raw": f
                        })
                except Exception:
                    pass
            if not files:
                files = [{"name": "(No Disk)", "size": 0, "type": "DSK", "extra": "[Mount]", "raw": None}]
        elif m.startswith("MDR"):
            d_num = int(m[3:]) if len(m) > 3 and m[3:].isdigit() else 1
            path = get_mdr_path(d_num)
            if os.path.exists(path):
                try:
                    with open(path, "rb") as f:
                        data = f.read()
                    found = {}
                    ftypes = {}
                    for i in range(254):
                        rec_offset = (i * 543) + 15
                        recflg = data[rec_offset + 0]
                        reclen = data[rec_offset + 2] + (data[rec_offset + 3] * 256)
                        rec_name = data[rec_offset + 4:rec_offset + 14]
                        if recflg != 0xFF and reclen > 0 and rec_name.strip() != b'':
                            fname = rec_name.decode('latin-1', errors='ignore').strip()
                            if fname:
                                found[fname] = found.get(fname, 0) + 1
                                ftypes[fname] = "PRINT" if (recflg & 2) != 0 else "PROG"
                    for fname in sorted(found.keys()):
                        sz = found[fname] * 512
                        files.append({
                            "name": fname,
                            "size": sz,
                            "type": ftypes.get(fname, "MDR"),
                            "extra": f"{found[fname]}s",
                            "raw": fname
                        })
                except Exception:
                    pass
            if not files:
                files = [{"name": "(No Cart)", "size": 0, "type": "MDR", "extra": "[Mount]", "raw": None}]
        elif m == "TAPE":
            tap_path = panel.current_path
            if not (tap_path and os.path.exists(tap_path)):
                for d in (get_zx_folder(), os.getcwd()):
                    if os.path.exists(d):
                        taps = [os.path.join(d, f) for f in os.listdir(d) if f.lower().endswith(".tap")]
                        if taps:
                            tap_path = taps[0]
                            panel.current_path = tap_path
                            break
            if tap_path and os.path.exists(tap_path):
                try:
                    with open(tap_path, "rb") as f:
                        content = f.read()
                    pos = 0
                    idx = 1
                    cur_type = "DATA"
                    cur_name = ""
                    cur_addr = 0
                    while pos + 2 <= len(content):
                        blen = content[pos] + (content[pos+1] * 256)
                        pos += 2
                        if pos + blen > len(content): break
                        bdata = content[pos : pos + blen]
                        pos += blen
                        if len(bdata) > 0:
                            flag = bdata[0]
                            payload = bdata[1:-1]
                            if flag == 0 and len(payload) >= 15:
                                btype = payload[0]
                                cur_type = "PROG" if btype == 0 else ("CODE" if btype == 3 else "DATA")
                                cur_name = payload[1:11].decode('latin-1', errors='ignore').strip()
                                cur_addr = payload[13] | (payload[14] << 8)
                            elif flag == 255:
                                name = cur_name if cur_name else f"Block_{idx}"
                                files.append({
                                    "name": name,
                                    "size": len(payload),
                                    "type": cur_type,
                                    "extra": f"{len(payload)}B",
                                    "raw": (idx, cur_type, cur_addr, payload)
                                })
                                idx += 1
                                cur_name = ""
                except Exception:
                    pass
            if not files:
                files = [{"name": "(No Tape)", "size": 0, "type": "TAP", "extra": "[Open]", "raw": None}]
        elif m == "NET":
            if self.tnfs_client and getattr(self.tnfs_client, 'conn_id', 0) != 0:
                try:
                    t_files = self.tnfs_client.list_files(panel.current_path)
                    for fn in t_files:
                        files.append({"name": fn, "size": 0, "type": "NET", "extra": "TNFS", "raw": fn})
                except Exception:
                    pass
            if not files:
                for stn in range(1, 5):
                    files.append({"name": f"Station_{stn}", "size": 0, "type": "IF1", "extra": "Net", "raw": stn})
                files.append({"name": "[TNFS Connect]", "size": 0, "type": "NET", "extra": "tnfs", "raw": "connect"})

        panel.file_list = files
        if panel.selected_idx >= len(panel.file_list):
            panel.selected_idx = max(0, len(panel.file_list) - 1)

    def read_payload(self, panel, file_entry):
        if not file_entry or not file_entry.get("name") or file_entry["name"].startswith("("):
            return None, "CODE", 0x8000, None
        m = panel.media_type
        name = file_entry["name"]
        raw = file_entry.get("raw")
        if m == "HOST":
            if raw and os.path.exists(raw):
                with open(raw, "rb") as f:
                    return f.read(), file_entry.get("type", "CODE"), 16384, None
        elif m == "RAM":
            if name in ram_disk:
                finfo = ram_disk[name]
                data = finfo.get("data", b"") if isinstance(finfo, dict) else finfo
                ftype = finfo.get("type", "CODE") if isinstance(finfo, dict) else "CODE"
                addr = finfo.get("start_addr", 16384) if isinstance(finfo, dict) else 16384
                auto = finfo.get("autorun_line", None) if isinstance(finfo, dict) else None
                return bytes(data), ftype, addr, auto
        elif m in ("DSK1", "DSK2"):
            d_num = 1 if m == "DSK1" else 2
            disk = mgt_drives.get(d_num)
            if disk:
                try:
                    ftype_code, data, meta = disk.load_file(name)
                    type_name = "BASIC" if ftype_code == 1 else ("SCREEN" if ftype_code == 2 else "CODE")
                    start_addr = meta.get("start_addr", 16384)
                    auto = meta.get("autorun_line")
                    return bytes(data), type_name, start_addr, auto
                except Exception:
                    pass
        elif m.startswith("MDR"):
            d_num = int(m[3:]) if len(m) > 3 and m[3:].isdigit() else 1
            data = mdr_read_file_bytes(d_num, name)
            return data, file_entry.get("type", "CODE"), 16384, None
        elif m == "TAPE":
            if raw and isinstance(raw, tuple):
                return raw[3], raw[1], raw[2], None
        elif m == "NET":
            if self.tnfs_client and raw and raw != "connect":
                data = self.tnfs_client.read_file(name)
                return data, "CODE", 16384, None
        return None, "CODE", 16384, None

    def write_payload(self, panel, name, data, ftype="CODE", start_addr=16384, autorun=None):
        m = panel.media_type
        if m == "HOST":
            folder = get_zx_folder()
            clean_name = re.sub(r'[<>:"/\\|?*]', '_', name).strip()
            fpath = os.path.join(folder, clean_name)
            with open(fpath, "wb") as f:
                f.write(data)
            cwd_path = os.path.join(os.getcwd(), clean_name)
            if cwd_path != fpath:
                try:
                    with open(cwd_path, "wb") as f:
                        f.write(data)
                except Exception:
                    pass
            return True
        elif m == "RAM":
            ram_disk[name] = {
                "type": ftype,
                "data": bytes(data),
                "size": len(data),
                "start_addr": start_addr,
                "autorun_line": autorun
            }
            return True
        elif m in ("DSK1", "DSK2"):
            d_num = 1 if m == "DSK1" else 2
            disk = mgt_drives.get(d_num)
            if disk:
                code_type = 1 if ftype == "BASIC" else 4
                try:
                    disk.save_file(name, code_type, data, autorun_line=autorun, start_addr=start_addr)
                    return True
                except Exception:
                    return False
            return False
        elif m.startswith("MDR"):
            d_num = int(m[3:]) if len(m) > 3 and m[3:].isdigit() else 1
            mdr_write_file_bytes(d_num, name, data, file_type=ftype)
            return True
        elif m == "TAPE":
            tap_path = panel.current_path
            if not tap_path:
                tap_path = os.path.join(get_zx_folder(), "commander.tap")
                panel.current_path = tap_path
            hdr_type = 0 if ftype == "BASIC" else 3
            hdr_name = name[:10].ljust(10, ' ').encode('latin-1', errors='ignore')
            hdr_payload = bytearray([hdr_type]) + hdr_name + struct.pack("<HHH", len(data), start_addr or 16384, autorun or 32768)
            hdr_chk = 0
            for b in bytearray([0]) + hdr_payload: hdr_chk ^= b
            hdr_block = bytearray([0]) + hdr_payload + bytearray([hdr_chk])
            hdr_full = struct.pack("<H", len(hdr_block)) + bytes(hdr_block)

            data_chk = 0xFF
            for b in data: data_chk ^= b
            data_block = bytearray([0xFF]) + bytearray(data) + bytearray([data_chk])
            data_full = struct.pack("<H", len(data_block)) + bytes(data_block)

            with open(tap_path, "ab") as f:
                f.write(hdr_full + data_full)
            return True
        elif m == "NET":
            if name.startswith("Station_"):
                try:
                    stn = int(name.split("_")[1])
                    pkt_path = os.path.join(get_zx_folder(), f"net_station{stn}.net")
                    with open(pkt_path, "wb") as f:
                        f.write(data)
                    return True
                except Exception:
                    pass
        return False

    def delete_payload(self, panel, file_entry):
        m = panel.media_type
        name = file_entry.get("name")
        raw = file_entry.get("raw")
        if m == "HOST":
            if raw and os.path.exists(raw):
                os.remove(raw)
                return True
        elif m == "RAM":
            if name in ram_disk:
                del ram_disk[name]
                return True
        elif m in ("DSK1", "DSK2"):
            d_num = 1 if m == "DSK1" else 2
            disk = mgt_drives.get(d_num)
            if disk:
                try:
                    disk.erase_file(name)
                    return True
                except Exception:
                    return False
        elif m.startswith("MDR"):
            d_num = int(m[3:]) if len(m) > 3 and m[3:].isdigit() else 1
            mdr_erase_file(d_num, name, quiet=True)
            return True
        return False

    def copy_file(self, src_panel, dst_panel, file_entry, target_name=None):
        data, ftype, addr, auto = self.read_payload(src_panel, file_entry)
        if data is None:
            self.status_msg = f"Cannot read '{file_entry.get('name')}'"
            return False
        dest_name = target_name or file_entry.get("name")
        ok = self.write_payload(dst_panel, dest_name, data, ftype=ftype, start_addr=addr, autorun=auto)
        if ok:
            self.status_msg = f"Copied '{dest_name}' ({len(data)}B) to {dst_panel.media_type}"
            self.refresh_panel(dst_panel)
            return True
        else:
            self.status_msg = f"Failed copying to {dst_panel.media_type}"
            return False

    def move_file(self, src_panel, dst_panel, file_entry, target_name=None):
        if self.copy_file(src_panel, dst_panel, file_entry, target_name):
            self.delete_payload(src_panel, file_entry)
            self.refresh_panel(src_panel)
            self.status_msg = f"Moved '{file_entry.get('name')}' to {dst_panel.media_type}"
            return True
        return False

    def draw_text(self, r, c, text, ink=7, paper=1, bright=True, flash=False):
        if 0 <= r < 24 and c < 32:
            max_len = 32 - c
            s = text[:max_len]
            for i, ch in enumerate(s):
                col = c + i
                screen_chars[r][col] = ch
                attr_ink[r][col] = ink & 7
                attr_paper[r][col] = paper & 7
                attr_bright[r][col] = bright
                attr_flash[r][col] = flash
                attr_used[r][col] = True

    def draw_box(self, r1, c1, r2, c2, title="", ink=7, paper=1, bright=True):
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                ch = ' '
                if (r == r1 or r == r2) and (c == c1 or c == c2): ch = '+'
                elif r == r1 or r == r2: ch = '-'
                elif c == c1 or c == c2: ch = '|'
                self.draw_text(r, c, ch, ink=ink, paper=paper, bright=bright)
        if title:
            t_str = f" {title} "
            t_col = c1 + max(1, (c2 - c1 + 1 - len(t_str)) // 2)
            self.draw_text(r1, t_col, t_str, ink=6, paper=paper, bright=True)

    def render(self):
        # Clear screen to Norton Blue (Paper 1, Ink 7, Bright 1)
        for r in range(24):
            for c in range(32):
                screen_chars[r][c] = ' '
                attr_ink[r][c] = 7
                attr_paper[r][c] = 1
                attr_bright[r][c] = True
                attr_flash[r][c] = False
                attr_used[r][c] = True

        # Row 0: Top Buttons or Lotus 1-2-3 Menu
        if not self.lotus_menu_active:
            self.draw_text(0, 0, "[DISK]", ink=0, paper=5, bright=True)
            self.draw_text(0, 6, "[MDR]", ink=0, paper=5, bright=True)
            self.draw_text(0, 12, "[TAPE]", ink=0, paper=5, bright=True)
            self.draw_text(0, 19, "[NET]", ink=0, paper=5, bright=True)
            self.draw_text(0, 25, "[/:Men]", ink=7, paper=3, bright=True)
        else:
            cur_x = 0
            self.draw_text(0, cur_x, "/", ink=6, paper=0, bright=True)
            cur_x += 1
            for idx, (mname, _) in enumerate(self.LOTUS_MENU):
                is_active = (idx == self.lotus_menu_idx)
                ink = 0 if is_active else 7
                pap = 7 if is_active else 0
                self.draw_text(0, cur_x, f" {mname}", ink=ink, paper=pap, bright=True)
                cur_x += len(mname) + 1
            desc = self.LOTUS_MENU[self.lotus_menu_idx][1]
            self.draw_text(1, 0, desc.ljust(32), ink=6, paper=0, bright=True)

        # Draw Left Panel (Cols 0..14) and Right Panel (Cols 16..30), col 15 and 31 are '|'
        for panel in (self.left, self.right):
            cs = panel.col_start
            is_active = (self.active_side == panel.side)
            hdr_ink = 0 if is_active else 7
            hdr_pap = 5 if is_active else 1

            p_row = 1 if not self.lotus_menu_active else 2
            label = f"[{panel.side[0].upper()}:{panel.media_type[:5]}]"
            self.draw_text(p_row, cs, label.ljust(15), ink=hdr_ink, paper=hdr_pap, bright=True)
            self.draw_text(p_row, cs + 15, "|", ink=7, paper=1, bright=True)

            c_row = p_row + 1
            self.draw_text(c_row, cs, " Name      Size", ink=6, paper=1, bright=True)
            self.draw_text(c_row, cs + 15, "|", ink=7, paper=1, bright=True)

            r_start = c_row + 1
            max_visible = 19 - r_start
            for idx in range(max_visible):
                r = r_start + idx
                f_idx = panel.scroll_offset + idx
                self.draw_text(r, cs + 15, "|", ink=7, paper=1, bright=True)
                if f_idx < len(panel.file_list):
                    entry = panel.file_list[f_idx]
                    fname = entry["name"][:10].ljust(10)
                    sz_str = entry.get("extra", "")[:4].rjust(4)
                    line_str = f"{fname} {sz_str}"
                    is_sel = is_active and (f_idx == panel.selected_idx)
                    ink = 0 if is_sel else (4 if fname in panel.tagged else 7)
                    pap = 7 if is_sel else 1
                    self.draw_text(r, cs, line_str, ink=ink, paper=pap, bright=True)
                else:
                    self.draw_text(r, cs, " " * 15, ink=7, paper=1, bright=True)

            cnt = len(panel.file_list)
            tot_sz = sum(f.get("size", 0) for f in panel.file_list)
            f_str = f"{cnt}f {tot_sz//1024}K" if tot_sz >= 1024 else f"{cnt}f {tot_sz}B"
            self.draw_text(19, cs, f_str.ljust(15), ink=6, paper=1, bright=True)
            self.draw_text(19, cs + 15, "|", ink=7, paper=1, bright=True)

        sel = self.active.get_selected()
        if sel:
            d_str = f"> {sel['name']}  {sel.get('type','')} {sel.get('size',0)}B [{self.active.media_type}]"
        else:
            d_str = f"> [{self.active.media_type}] Empty"
        self.draw_text(20, 0, d_str[:32].ljust(32), ink=6, paper=0, bright=True)

        self.draw_text(21, 0, self.status_msg[:32].ljust(32), ink=7, paper=0, bright=True)

        self.draw_text(22, 0, "[F3:Inf]", ink=0, paper=6, bright=True)
        self.draw_text(22, 8, "[F5:Cpy]", ink=0, paper=6, bright=True)
        self.draw_text(22, 16, "[F6:Mov]", ink=0, paper=6, bright=True)
        self.draw_text(22, 24, "[F7:Del]", ink=0, paper=2, bright=True)

        self.draw_text(23, 0, "1Hlp 3Inf 5Cpy 6Mov 7Del 0Exit", ink=7, paper=1, bright=True)

        if self.modal:
            mtype = self.modal.get("type")
            if mtype == "confirm_del":
                fn = self.modal.get("name", "")
                self.draw_box(8, 2, 14, 29, title="DELETE FILE", ink=7, paper=2)
                self.draw_text(10, 4, f"Erase '{fn[:16]}'?", ink=7, paper=2, bright=True)
                self.draw_text(11, 4, f"From: {self.active.media_type}", ink=6, paper=2, bright=True)
                self.draw_text(13, 6, "[Y] Yes       [N] No", ink=0, paper=7, bright=True)
            elif mtype in ("copy", "move"):
                act = "COPY" if mtype == "copy" else "MOVE"
                fn = self.modal.get("name", "")
                self.draw_box(7, 2, 15, 29, title=f"{act} FILE", ink=7, paper=1)
                self.draw_text(9, 4, f"Source: {self.active.media_type} ({fn[:12]})", ink=7, paper=1, bright=True)
                self.draw_text(10, 4, f"Target: {self.passive.media_type}", ink=6, paper=1, bright=True)
                self.draw_text(12, 4, "Name:", ink=7, paper=1, bright=True)
                self.draw_text(12, 10, self.modal_input.ljust(16), ink=0, paper=7, bright=True)
                self.draw_text(14, 4, "[ENTER: OK]   [ESC: Cancel]", ink=6, paper=1, bright=True)
            elif mtype == "info":
                fn = self.modal.get("name", "")
                sz = self.modal.get("size", 0)
                tp = self.modal.get("type_name", "CODE")
                preview = self.modal.get("preview", "")
                self.draw_box(5, 2, 18, 29, title="FILE DETAILS", ink=7, paper=0)
                self.draw_text(7, 4, f"Name:  {fn[:20]}", ink=7, paper=0, bright=True)
                self.draw_text(8, 4, f"Media: {self.active.media_type}", ink=6, paper=0, bright=True)
                self.draw_text(9, 4, f"Type:  {tp}", ink=7, paper=0, bright=True)
                self.draw_text(10, 4, f"Size:  {sz} bytes", ink=7, paper=0, bright=True)
                self.draw_text(12, 4, "Hex Preview (first 16B):", ink=6, paper=0, bright=True)
                self.draw_text(13, 4, preview[:24], ink=4, paper=0, bright=True)
                self.draw_text(15, 4, "ASCII Preview:", ink=6, paper=0, bright=True)
                asc = self.modal.get("ascii", "")
                self.draw_text(16, 4, asc[:24], ink=5, paper=0, bright=True)
            elif mtype == "media_pick":
                side = self.modal.get("side", "left")
                self.draw_box(4, 3, 18, 28, title=f"SELECT {side.upper()} MEDIA", ink=7, paper=1)
                options = ["1. HOST  (PC Folder)", "2. RAM   (Silicon Disc)", "3. DSK1  (Floppy 1)", "4. DSK2  (Floppy 2)", "5. MDR1  (Microdrive 1)", "6. MDR2  (Microdrive 2)", "7. TAPE  (.TAP File)", "8. NET   (TNFS / IF1)"]
                for i, opt in enumerate(options):
                    self.draw_text(6 + i, 5, opt, ink=7, paper=1, bright=True)
                self.draw_text(15, 5, "Press 1-8 or Click option", ink=6, paper=1, bright=True)

        canvas_dirty = True

    def handle_key(self, key_name, unicode_char=""):
        k = key_name.upper()

        if self.modal:
            mtype = self.modal.get("type")
            if k == "ESCAPE":
                self.modal = None
                return
            if mtype == "confirm_del":
                if k in ("Y", "RETURN"):
                    sel = self.modal.get("entry")
                    self.delete_payload(self.active, sel)
                    self.status_msg = f"Deleted '{sel.get('name')}'"
                    self.refresh_panel(self.active)
                    self.modal = None
                elif k in ("N", "ESCAPE"):
                    self.modal = None
                return
            elif mtype in ("copy", "move"):
                if k == "RETURN":
                    dest_name = self.modal_input.strip() or self.modal.get("name")
                    sel = self.modal.get("entry")
                    if mtype == "copy":
                        self.copy_file(self.active, self.passive, sel, dest_name)
                    else:
                        self.move_file(self.active, self.passive, sel, dest_name)
                    self.modal = None
                elif k == "BACKSPACE":
                    self.modal_input = self.modal_input[:-1]
                elif len(unicode_char) == 1 and unicode_char.isprintable():
                    self.modal_input += unicode_char
                return
            elif mtype == "media_pick":
                side_panel = self.left if self.modal.get("side") == "left" else self.right
                media_map = {"1": "HOST", "2": "RAM", "3": "DSK1", "4": "DSK2", "5": "MDR1", "6": "MDR2", "7": "TAPE", "8": "NET"}
                if unicode_char in media_map:
                    side_panel.media_type = media_map[unicode_char]
                    side_panel.selected_idx = 0
                    side_panel.scroll_offset = 0
                    self.refresh_panel(side_panel)
                    self.status_msg = f"Switched {side_panel.side} to {side_panel.media_type}"
                    self.modal = None
                return
            elif mtype == "info":
                self.modal = None
                return

        if self.lotus_menu_active:
            if k == "ESCAPE":
                self.lotus_menu_active = False
                return
            elif k == "LEFT":
                self.lotus_menu_idx = (self.lotus_menu_idx - 1) % len(self.LOTUS_MENU)
                return
            elif k == "RIGHT":
                self.lotus_menu_idx = (self.lotus_menu_idx + 1) % len(self.LOTUS_MENU)
                return
            elif k == "RETURN":
                self.execute_lotus_menu(self.lotus_menu_idx)
                return
            elif unicode_char:
                u = unicode_char.upper()
                for idx, (mname, _) in enumerate(self.LOTUS_MENU):
                    if mname.upper().startswith(u):
                        self.lotus_menu_idx = idx
                        self.execute_lotus_menu(idx)
                        return
            return

        if unicode_char == "/" or k == "SLASH":
            self.lotus_menu_active = True
            self.lotus_menu_idx = 0
            return
        elif k == "TAB":
            self.active_side = "right" if self.active_side == "left" else "left"
            return
        elif k == "UP":
            if self.active.selected_idx > 0:
                self.active.selected_idx -= 1
                if self.active.selected_idx < self.active.scroll_offset:
                    self.active.scroll_offset = self.active.selected_idx
            return
        elif k == "DOWN":
            if self.active.selected_idx < len(self.active.file_list) - 1:
                self.active.selected_idx += 1
                if self.active.selected_idx >= self.active.scroll_offset + 14:
                    self.active.scroll_offset = self.active.selected_idx - 13
            return
        elif k == "PAGEUP":
            self.active.selected_idx = max(0, self.active.selected_idx - 14)
            self.active.scroll_offset = max(0, self.active.scroll_offset - 14)
            return
        elif k == "PAGEDOWN":
            max_idx = max(0, len(self.active.file_list) - 1)
            self.active.selected_idx = min(max_idx, self.active.selected_idx + 14)
            self.active.scroll_offset = min(max_idx, self.active.scroll_offset + 14)
            return
        elif k in ("F5", "5", "C"):
            self.prompt_copy()
        elif k in ("F6", "6", "M"):
            self.prompt_move()
        elif k in ("F7", "7", "D"):
            self.prompt_delete()
        elif k in ("F3", "3", "I"):
            self.show_info()
        elif k in ("F8", "8", "R"):
            self.refresh_all()
            self.status_msg = "Panels refreshed."
        elif k in ("F10", "0", "Q", "ESCAPE"):
            self.running = False

    def execute_lotus_menu(self, idx):
        self.lotus_menu_active = False
        mname = self.LOTUS_MENU[idx][0]
        if mname == "Files":
            self.prompt_copy()
        elif mname == "Disk":
            self.active.media_type = "DSK1" if self.active.media_type != "DSK1" else "DSK2"
            self.refresh_panel(self.active)
            self.status_msg = f"Switched to {self.active.media_type}"
        elif mname == "Microdrive":
            self.active.media_type = "MDR1" if self.active.media_type != "MDR1" else "MDR2"
            self.refresh_panel(self.active)
            self.status_msg = f"Switched to {self.active.media_type}"
        elif mname == "Tape":
            self.active.media_type = "TAPE"
            self.refresh_panel(self.active)
            self.status_msg = "Switched to TAPE"
        elif mname == "Network":
            self.active.media_type = "NET"
            self.refresh_panel(self.active)
            self.status_msg = "Switched to NET (Spectranet / IF1)"
        elif mname == "View":
            self.show_info()
        elif mname == "Quit":
            self.running = False

    def prompt_copy(self):
        sel = self.active.get_selected()
        if sel and not sel["name"].startswith("("):
            self.modal = {"type": "copy", "entry": sel, "name": sel["name"]}
            self.modal_input = sel["name"]

    def prompt_move(self):
        sel = self.active.get_selected()
        if sel and not sel["name"].startswith("("):
            self.modal = {"type": "move", "entry": sel, "name": sel["name"]}
            self.modal_input = sel["name"]

    def prompt_delete(self):
        sel = self.active.get_selected()
        if sel and not sel["name"].startswith("("):
            self.modal = {"type": "confirm_del", "entry": sel, "name": sel["name"]}

    def show_info(self):
        sel = self.active.get_selected()
        if sel:
            data, ftype, addr, _ = self.read_payload(self.active, sel)
            hex_prev = "No data"
            asc_prev = ""
            if data:
                hex_prev = " ".join(f"{b:02X}" for b in data[:12])
                asc_prev = "".join(chr(b) if 32 <= b <= 126 else "." for b in data[:16])
            self.modal = {
                "type": "info",
                "entry": sel,
                "name": sel["name"],
                "size": len(data) if data else sel.get("size", 0),
                "type_name": ftype or sel.get("type", "CODE"),
                "preview": hex_prev,
                "ascii": asc_prev
            }

    def handle_mouse_click(self, x, y, button=1):
        col = max(0, min(31, x // 8))
        row = max(0, min(23, (191 - y) // 8))

        if self.modal:
            mtype = self.modal.get("type")
            if mtype == "confirm_del":
                if row == 13:
                    if 4 <= col <= 12:
                        self.handle_key("Y")
                    elif 14 <= col <= 24:
                        self.handle_key("N")
            elif mtype == "media_pick":
                if 6 <= row <= 13:
                    opt_num = str(row - 5)
                    self.handle_key("", unicode_char=opt_num)
            elif mtype == "info":
                self.modal = None
            return

        if row == 0:
            if not self.lotus_menu_active:
                if 0 <= col <= 5:   # [DISK]
                    self.active.media_type = "DSK1" if self.active.media_type != "DSK1" else "DSK2"
                    self.refresh_panel(self.active)
                    self.status_msg = f"Mounted {self.active.media_type}"
                elif 6 <= col <= 11: # [MDR]
                    self.active.media_type = "MDR1" if self.active.media_type != "MDR1" else "MDR2"
                    self.refresh_panel(self.active)
                    self.status_msg = f"Mounted {self.active.media_type}"
                elif 12 <= col <= 18: # [TAPE]
                    self.active.media_type = "TAPE"
                    self.refresh_panel(self.active)
                    self.status_msg = "Mounted TAPE"
                elif 19 <= col <= 24: # [NET]
                    self.active.media_type = "NET"
                    self.refresh_panel(self.active)
                    self.status_msg = "Mounted NET"
                elif 25 <= col <= 31: # [ /:Men ]
                    self.lotus_menu_active = True
                    self.lotus_menu_idx = 0
            else:
                cur_x = 1
                for idx, (mname, _) in enumerate(self.LOTUS_MENU):
                    w = len(mname) + 1
                    if cur_x <= col < cur_x + w:
                        self.lotus_menu_idx = idx
                        self.execute_lotus_menu(idx)
                        break
                    cur_x += w
            return

        if row == 1:
            if col < 16:
                self.modal = {"type": "media_pick", "side": "left"}
            else:
                self.modal = {"type": "media_pick", "side": "right"}
            return

        p_row = 1 if not self.lotus_menu_active else 2
        r_start = p_row + 2
        if r_start <= row <= 18:
            target_panel = self.left if col < 16 else self.right
            self.active_side = target_panel.side
            item_row = row - r_start
            clicked_idx = target_panel.scroll_offset + item_row
            if clicked_idx < len(target_panel.file_list):
                if target_panel.selected_idx == clicked_idx:
                    self.show_info()
                else:
                    target_panel.selected_idx = clicked_idx
            return

        if row == 22:
            if 0 <= col <= 7:
                self.show_info()
            elif 8 <= col <= 15:
                self.prompt_copy()
            elif 16 <= col <= 23:
                self.prompt_move()
            elif 24 <= col <= 31:
                self.prompt_delete()
            return

        if row == 23:
            if col >= 26:
                self.running = False


def launch_zx_commander(args=""):
    global current_border, canvas_dirty, amx_pointer_visible
    parts = split_top_level_commas(args) if args else []
    left_media = parts[0].strip().strip('"\'') if len(parts) > 0 and parts[0].strip() else "HOST"
    right_media = parts[1].strip().strip('"\'') if len(parts) > 1 and parts[1].strip() else "RAM"

    saved_chars = [list(row) for row in screen_chars]
    saved_ink = [list(row) for row in attr_ink]
    saved_paper = [list(row) for row in attr_paper]
    saved_bright = [list(row) for row in attr_bright]
    saved_flash = [list(row) for row in attr_flash]
    saved_used = [list(row) for row in attr_used]
    saved_border = current_border
    saved_amx_visible = amx_pointer_visible

    current_border = 1
    amx_pointer_visible = True
    commander = ZXCommander(left_media, right_media)

    is_dummy = (os.environ.get("SDL_VIDEODRIVER") == "dummy") or ('running' in globals() and not running)
    if is_dummy:
        commander.render()
        amx_pointer_visible = saved_amx_visible
        return commander

    clock = pygame.time.Clock()
    try:
        while commander.running:
            clock.tick(60)
            sync_amx_mouse_state()
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    commander.running = False
                    pygame.quit()
                    sys.exit(0)
                elif event.type == pygame.MOUSEBUTTONDOWN:
                    update_amx_from_mouse(event.pos)
                    update_amx_buttons(event)
                    commander.handle_mouse_click(amx_x, amx_y, button=event.button)
                elif event.type == pygame.MOUSEMOTION:
                    update_amx_from_mouse(event.pos)
                elif event.type == pygame.KEYDOWN:
                    key_name = pygame.key.name(event.key).upper()
                    unicode_char = getattr(event, 'unicode', '')
                    commander.handle_key(key_name, unicode_char=unicode_char)
                elif event.type == pygame.TEXTINPUT:
                    if commander.modal and commander.modal.get("type") in ("copy", "move"):
                        commander.modal_input += event.text

            commander.render()
            render_frame()
            try:
                pygame.display.flip()
            except Exception:
                pass
    finally:
        if 'pygame' in globals() and pygame.get_init() and pygame.display.get_init():
            current_border = saved_border
            amx_pointer_visible = saved_amx_visible
            for r in range(24):
                for c in range(32):
                    screen_chars[r][c] = saved_chars[r][c]
                    attr_ink[r][c] = saved_ink[r][c]
                    attr_paper[r][c] = saved_paper[r][c]
                    attr_bright[r][c] = saved_bright[r][c]
                    attr_flash[r][c] = saved_flash[r][c]
                    attr_used[r][c] = saved_used[r][c]
                    if 'cell_bitmap' in globals() and cell_bitmap:
                        cell_bitmap[r][c] = None
            canvas_dirty = True
            try:
                update_display()
            except Exception:
                pass
    return commander


def handle_commander_command(args_str=""):
    launch_zx_commander(args_str)


def handle_join_command(args_str):
    global program, _split_cache
    parts = split_top_level_commas(args_str)
    if len(parts) == 2:
        l1 = int(to_float(evaluate_expr(parts[0])))
        l2 = int(to_float(evaluate_expr(parts[1])))
        if l1 in program and l2 in program:
            program[l1] = program[l1].rstrip() + " : " + program[l2].lstrip()
            del program[l2]
            parse_data_lines()
            _split_cache.clear()
            canvas_print(f"Joined {l1} and {l2}")
            update_display()
        else:
            canvas_print("Line not found")
    else:
        canvas_print("Syntax: JOIN line1, line2")


def handle_split_command(args_str):
    global program, _split_cache
    parts = split_top_level_commas(args_str)
    if len(parts) >= 2:
        ln = int(to_float(evaluate_expr(parts[0])))
        stmt_idx = int(to_float(evaluate_expr(parts[1])))
        if ln in program:
            stmts = split_statements(program[ln])
            if 1 <= stmt_idx < len(stmts):
                first_part = " : ".join(stmts[:stmt_idx])
                second_part = " : ".join(stmts[stmt_idx:])
                new_ln = ln + 1
                while new_ln in program:
                    new_ln += 1
                program[ln] = first_part
                program[new_ln] = second_part
                parse_data_lines()
                _split_cache.clear()
                canvas_print(f"Split {ln} into {ln} and {new_ln}")
                update_display()
            else:
                canvas_print("Invalid statement index")
        else:
            canvas_print("Line not found")
    else:
        canvas_print("Syntax: SPLIT line, stmt_num")


def handle_auto_command(args_str):
    global auto_active, auto_next_line, auto_step
    args_str = args_str.strip()
    if not args_str:
        auto_active = not auto_active
        canvas_print(f"AUTO {'ON' if auto_active else 'OFF'} (next {auto_next_line}, step {auto_step})")
        return
    if args_str.upper() == "OFF":
        auto_active = False
        canvas_print("AUTO OFF")
        return
    parts = split_top_level_commas(args_str)
    if len(parts) >= 1:
        auto_next_line = int(to_float(evaluate_expr(parts[0])))
    if len(parts) >= 2:
        auto_step = int(to_float(evaluate_expr(parts[1])))
    auto_active = True
    canvas_print(f"AUTO ON (next {auto_next_line}, step {auto_step})")


def handle_clock_command(args_str):
    global clock_display_active
    arg = args_str.strip().upper()
    if arg == "ON":
        clock_display_active = True
    elif arg == "OFF":
        clock_display_active = False
    else:
        clock_display_active = not clock_display_active
    canvas_print(f"CLOCK {'ON' if clock_display_active else 'OFF'}")
    update_display()


