def note_to_ay_period(note_tuple):
    if not note_tuple:
        return 0
    semi, octv = note_tuple
    midi = (octv + 1) * 12 + semi
    freq = 440.0 * (2.0 ** ((midi - 69) / 12.0))
    p = int(round(55420.23 / freq))
    return max(1, min(4095, p))


def reset_spectrum_screen_white():
    """
    Sets machine to ZX 48K state, clears the Spectrum screen to white paper (7)
    and black ink (0), and sets user focus directly to the command input area.
    """
    global current_paper, current_ink, current_border, current_bright, current_flash, current_inverse, current_over
    global current_bold, current_italic, current_underline, input_text, input_cursor_pos, canvas_dirty
    global listing_edit_active, listing_vars_active, listing_code_active, listing_monitor_active

    # 1. Set machine to ZX 48K state
    if "set_zx48_mode" in globals():
        set_zx48_mode(reset_vars=True, attach_defaults=True)

    # 2. White screen, black text, white border
    current_paper = 7
    current_ink = 0
    current_border = 7
    current_bright = False
    current_flash = False
    current_inverse = False
    current_over = False
    current_bold = False
    current_italic = False
    current_underline = False
    memory[23624] = 7 * 8
    memory[23693] = 0x38

    # 3. Clear screen
    execute_cls()

    # 4. Set user focus directly to command input area
    listing_edit_active = False
    listing_vars_active = False
    listing_code_active = False
    listing_monitor_active = False
    input_text = ""
    input_cursor_pos = 0
    try:
        pygame.key.start_text_input()
    except Exception:
        pass

    canvas_dirty = True
    if "redraw_canvas" in globals():
        redraw_canvas(force=True)
    if "render_frame" in globals():
        render_frame()
    if "update_display" in globals():
        update_display()
    try:
        pygame.display.flip()
    except Exception:
        pass


def play_manic_miner_splash_tune(headless_test=False, auto_reset=True):
    """
    Plays the Manic Miner theme tune ('In the Hall of the Mountain King') using
    authentic 3-channel AY-3-8912 sound chip emulation while displaying the splash screen.
    Loops until the user presses any key or clicks the mouse, then immediately stops playback,
    sets the machine to ZX 48K state with a white screen and black text, clears the screen,
    and sets user focus directly to the command input area.
    """
    is_dummy = os.environ.get("SDL_VIDEODRIVER") == "dummy"
    if is_dummy and not headless_test:
        return

    display_startup_splash()
    global screen, current_paper, current_border, canvas_dirty
    current_paper = 0
    current_border = 0
    canvas_dirty = True
    if "redraw_canvas" in globals():
        redraw_canvas(force=True)
    if "render_frame" in globals():
        render_frame()
    try:
        pygame.display.flip()
    except Exception:
        pass

    if headless_test:
        if auto_reset:
            reset_spectrum_screen_white()
        return

    # Flush any stale launch events (e.g. Enter key from terminal or mouse clicks)
    try:
        pygame.event.clear()
    except Exception:
        pass

    # Initialize AY-3-8912 emulation for Manic Miner
    fuller_ay_chip.reset()
    fuller_ay_chip.set_mode("SINCLAIR")
    fuller_ay_chip.set_stereo("ACB")

    stop_tune = False
    clock = pygame.time.Clock()
    tune_start_ticks = pygame.time.get_ticks()

    try:
        while not stop_tune:
            for dur, na, nb, nc in MANIC_MINER_AY_TUNE:
                if stop_tune:
                    break

                pa = note_to_ay_period(na)
                pb = note_to_ay_period(nb)
                pc = note_to_ay_period(nc)

                # Channel A (Melody)
                fuller_ay_chip.write_address(0)
                fuller_ay_chip.write_data(pa & 0xFF)
                fuller_ay_chip.write_address(1)
                fuller_ay_chip.write_data((pa >> 8) & 0x0F)

                # Channel B (Harmony)
                fuller_ay_chip.write_address(2)
                fuller_ay_chip.write_data(pb & 0xFF)
                fuller_ay_chip.write_address(3)
                fuller_ay_chip.write_data((pb >> 8) & 0x0F)

                # Channel C (Bass)
                fuller_ay_chip.write_address(4)
                fuller_ay_chip.write_data(pc & 0xFF)
                fuller_ay_chip.write_address(5)
                fuller_ay_chip.write_data((pc >> 8) & 0x0F)

                # Channel volumes: A=13, B=10, C=11
                fuller_ay_chip.write_address(8)
                fuller_ay_chip.write_data(13 if na else 0)
                fuller_ay_chip.write_address(9)
                fuller_ay_chip.write_data(10 if nb else 0)
                fuller_ay_chip.write_address(10)
                fuller_ay_chip.write_data(11 if nc else 0)

                # Mixer R7: tone channels enabled (0=enabled, 1=disabled)
                r7 = 0x38
                if na: r7 &= ~1
                if nb: r7 &= ~2
                if nc: r7 &= ~4
                fuller_ay_chip.write_address(7)
                fuller_ay_chip.write_data(r7)

                start_ticks = pygame.time.get_ticks()
                ms_dur = int(dur * 1000)
                articulated = False

                while (pygame.time.get_ticks() - start_ticks) < ms_dur:
                    elapsed = pygame.time.get_ticks() - start_ticks
                    # Staccato articulation: brief release before next step
                    if not articulated and elapsed >= int(ms_dur * 0.80):
                        fuller_ay_chip.write_address(8)
                        fuller_ay_chip.write_data(0)
                        articulated = True

                    for ev in pygame.event.get():
                        if ev.type == pygame.QUIT:
                            fuller_ay_chip.reset()
                            running = False
                            stop_tune = True
                            break
                        elif ev.type == pygame.VIDEORESIZE:
                            screen = pygame.display.set_mode((ev.w, ev.h), pygame.RESIZABLE)
                            canvas_dirty = True
                        elif ev.type in (pygame.KEYDOWN, pygame.MOUSEBUTTONDOWN):
                            stop_tune = True
                            break

                    if stop_tune:
                        break

                    # Polling check for held mouse button or key after initial 200ms grace period
                    if (pygame.time.get_ticks() - tune_start_ticks) > 200:
                        try:
                            if any(pygame.mouse.get_pressed()):
                                stop_tune = True
                                break
                            keys = pygame.key.get_pressed()
                            if keys.count(True) > 0:
                                stop_tune = True
                                break
                        except Exception:
                            pass

                    clock.tick(60)
                    render_frame()
                    try:
                        pygame.display.flip()
                    except Exception:
                        pass
    finally:
        fuller_ay_chip.reset()
        try:
            pygame.mixer.stop()
        except Exception:
            pass
        try:
            pygame.event.clear()
        except Exception:
            pass

    reset_spectrum_screen_white()

# Alias for backwards compatibility
play_fairlight_welcome_jingle = play_manic_miner_splash_tune


clock = pygame.time.Clock()
running = (__name__ == "__main__")
pending_def_key = False

if running and os.environ.get("SDL_VIDEODRIVER") != "dummy":
    try:
        play_manic_miner_splash_tune()
    except Exception:
        pass


while running:
    dt = clock.get_time()
    flash_timer += dt
    if listing_edit_active:
        listing_cursor_blink_timer += dt
        if listing_cursor_blink_timer >= 500:
            listing_cursor_blink_timer = 0
            listing_cursor_blink = not listing_cursor_blink
    
    frames_val = memory[23672] + (memory[23673] * 256) + (memory[23674] * 65536)
    frames_val = (frames_val + 1) % 16777216
    memory[23672] = frames_val & 0xFF
    memory[23673] = (frames_val >> 8) & 0xFF
    memory[23674] = (frames_val >> 16) & 0xFF

    if flash_timer >= 500:
        flash_timer = 0
        flash_phase = not flash_phase
        canvas_dirty = True

    try:
        if canvas_dirty:
            redraw_canvas()
        render_frame()
        pygame.display.flip()
    except Exception:
        pass

    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            running = False
        elif event.type == pygame.VIDEORESIZE:
            screen = pygame.display.set_mode((event.w, event.h), pygame.RESIZABLE)
            if listing_edit_active:
                ensure_listing_line_visible(listing_edit_ln)
        elif event.type == pygame.MOUSEMOTION:
            update_amx_from_mouse(event.pos)
            if gui_mode and WIMPDesktop:
                desktop = WIMPDesktop.get_instance()
                if scale_x > 0 and scale_y > 0:
                    cur_w = canvas.get_width() if 'canvas' in globals() and canvas else CANVAS_W
                    cur_h = canvas.get_height() if 'canvas' in globals() and canvas else CANVAS_H
                    if 'scaled_canvas_w' in globals() and scaled_canvas_w > 0 and 'scaled_canvas_h' in globals() and scaled_canvas_h > 0:
                        cx = int((event.pos[0] - canvas_blit_x) / float(scaled_canvas_w) * cur_w)
                        cy = int((event.pos[1] - canvas_blit_y) / float(scaled_canvas_h) * cur_h)
                    else:
                        cx = int((event.pos[0] - canvas_blit_x) / scale_x)
                        cy = int((event.pos[1] - canvas_blit_y) / scale_y)
                    if 0 <= cx < cur_w and 0 <= cy < cur_h:
                        desktop.handle_mouse_move(cx, cy)
                        if desktop.drag_mode:
                            canvas_dirty = True
        elif event.type == pygame.MOUSEWHEEL:
            mouse_pos = pygame.mouse.get_pos()
            if listing_rect.collidepoint(mouse_pos):
                if listing_monitor_active:
                    total_items = len(get_crystal_monitor().history)
                    max_visible_lines = max(1, (listing_rect.height - 130) // 16)
                elif listing_vars_active:
                    total_items = len(get_vars_listing_lines())
                    max_visible_lines = max(1, (listing_rect.height - 48) // 18)
                elif listing_code_active:
                    total_items = len(get_code_listing_lines())
                    max_visible_lines = max(1, (listing_rect.height - 48) // 18)
                else:
                    line_nums = sorted(program.keys())
                    total_items = len(line_nums) + (1 if (listing_edit_active and listing_edit_ln is None) else 0)
                    max_visible_lines = max(1, (listing_rect.height - 48) // 18)
                listing_scroll_index -= event.y
                listing_scroll_index = max(0, min(listing_scroll_index, max(0, total_items - max_visible_lines)))
        elif event.type == pygame.MOUSEBUTTONDOWN:
            update_amx_from_mouse(event.pos)
            update_amx_buttons(event)
            if gui_mode and WIMPDesktop:
                desktop = WIMPDesktop.get_instance()
                if scale_x > 0 and scale_y > 0:
                    cur_w = canvas.get_width() if 'canvas' in globals() and canvas else CANVAS_W
                    cur_h = canvas.get_height() if 'canvas' in globals() and canvas else CANVAS_H
                    if 'scaled_canvas_w' in globals() and scaled_canvas_w > 0 and 'scaled_canvas_h' in globals() and scaled_canvas_h > 0:
                        cx = int((event.pos[0] - canvas_blit_x) / float(scaled_canvas_w) * cur_w)
                        cy = int((event.pos[1] - canvas_blit_y) / float(scaled_canvas_h) * cur_h)
                    else:
                        cx = int((event.pos[0] - canvas_blit_x) / scale_x)
                        cy = int((event.pos[1] - canvas_blit_y) / scale_y)
                    if 0 <= cx < cur_w and 0 <= cy < cur_h:
                        desktop.handle_mouse_down(cx, cy, event.button)
                        canvas_dirty = True
            if event.button == 1:
                mouse_pos = event.pos
                if listing_rect.collidepoint(mouse_pos):
                    if not listing_vars_active and not listing_monitor_active and not listing_code_active:
                        y_start = listing_rect.y + 42
                        if mouse_pos[1] >= y_start:
                            visible_row = (mouse_pos[1] - y_start) // 18
                            item_idx = listing_scroll_index + visible_row
                            line_nums = sorted(program.keys())
                            if item_idx < len(line_nums):
                                start_listing_edit(line_nums[item_idx], click_x=mouse_pos[0], text_start_x=listing_rect.x + 10)
                            else:
                                start_listing_edit(None, click_x=mouse_pos[0], text_start_x=listing_rect.x + 10)
                    pygame.key.start_text_input()
                elif prompt_rect.collidepoint(mouse_pos):
                    if listing_edit_active:
                        commit_listing_edit(advance=False)
                    pygame.key.start_text_input()
        elif event.type == pygame.MOUSEBUTTONUP:
            update_amx_from_mouse(event.pos)
            update_amx_buttons(event)
            if gui_mode and WIMPDesktop:
                desktop = WIMPDesktop.get_instance()
                if scale_x > 0 and scale_y > 0:
                    cur_w = canvas.get_width() if 'canvas' in globals() and canvas else CANVAS_W
                    cur_h = canvas.get_height() if 'canvas' in globals() and canvas else CANVAS_H
                    if 'scaled_canvas_w' in globals() and scaled_canvas_w > 0 and 'scaled_canvas_h' in globals() and scaled_canvas_h > 0:
                        cx = int((event.pos[0] - canvas_blit_x) / float(scaled_canvas_w) * cur_w)
                        cy = int((event.pos[1] - canvas_blit_y) / float(scaled_canvas_h) * cur_h)
                    else:
                        cx = int((event.pos[0] - canvas_blit_x) / scale_x)
                        cy = int((event.pos[1] - canvas_blit_y) / scale_y)
                    if 0 <= cx < cur_w and 0 <= cy < cur_h:
                        desktop.handle_mouse_up(cx, cy, event.button)
                        canvas_dirty = True
        elif event.type == pygame.TEXTINPUT:
            if pending_def_key:
                pending_def_key = False
                continue
            if find_prompt_active or find_suppress_textinput:
                find_suppress_textinput = False
                continue
            if listing_edit_active:
                listing_edit_text = listing_edit_text[:listing_edit_cursor] + event.text + listing_edit_text[listing_edit_cursor:]
                listing_edit_cursor += len(event.text)
                listing_cursor_blink = True
                listing_cursor_blink_timer = 0
                ensure_listing_line_visible(listing_edit_ln)
            else:
                input_text = input_text[:input_cursor_pos] + event.text + input_text[input_cursor_pos:]
                input_cursor_pos += len(event.text)
        elif event.type == pygame.KEYDOWN:
            if gui_mode and WIMPDesktop:
                desktop = WIMPDesktop.get_instance()
                if desktop.active_window and desktop.active_window.app:
                    desktop.handle_key(event)
                    canvas_dirty = True
            if find_prompt_active:
                if event.key in (pygame.K_s, pygame.K_ESCAPE):
                    find_stop()
                elif event.key == pygame.K_f:
                    find_next()
                continue
            if event.unicode:
                last_keypress = event.unicode
                if currah_enabled and currah_keyvoice and ord(event.unicode) >= 32:
                    currah_speak(event.unicode)

            macro = None
            if not listing_edit_active and def_keys:
                k_char = event.unicode.upper() if event.unicode else ""
                k_code = str(ord(event.unicode)) if event.unicode else ""
                k_name = pygame.key.name(event.key).upper() if hasattr(pygame.key, "name") else ""
                if k_char and k_char in def_keys:
                    macro = def_keys[k_char]
                elif k_code and k_code in def_keys:
                    macro = def_keys[k_code]
                elif k_name and k_name in def_keys:
                    macro = def_keys[k_name]
                elif str(event.key) in def_keys:
                    macro = def_keys[str(event.key)]

            if macro is not None:
                pending_def_key = True
                if "\r" in macro or "\n" in macro or chr(13) in macro or chr(10) in macro:
                    for sub_m in re.split(r'[\r\n\x0d\x0a]+', macro):
                        if sub_m.strip():
                            m_num = re.match(r'^(\d+)\s*(.*)$', sub_m.strip())
                            if m_num and m_num.group(2):
                                program[int(m_num.group(1))] = m_num.group(2)
                                parse_data_lines()
                                _split_cache.clear()
                            elif m_num and not m_num.group(2):
                                program.pop(int(m_num.group(1)), None)
                                parse_data_lines()
                                _split_cache.clear()
                            else:
                                execute_statement(sub_m.strip())
                    input_text = ""
                    input_cursor_pos = 0
                else:
                    input_text = input_text[:input_cursor_pos] + macro + input_text[input_cursor_pos:]
                    input_cursor_pos += len(macro)
                canvas_dirty = True
                update_display()
                continue

            if listing_edit_active:
                listing_cursor_blink = True
                listing_cursor_blink_timer = 0
                if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                    commit_listing_edit(advance=True)
                elif event.key == pygame.K_ESCAPE:
                    cancel_listing_edit()
                elif event.key == pygame.K_TAB:
                    commit_listing_edit(advance=False)
                elif event.key == pygame.K_UP:
                    navigate_listing_edit(-1)
                elif event.key == pygame.K_DOWN:
                    navigate_listing_edit(1)
                elif event.key == pygame.K_LEFT:
                    if listing_edit_cursor > 0:
                        listing_edit_cursor -= 1
                elif event.key == pygame.K_RIGHT:
                    if listing_edit_cursor < len(listing_edit_text):
                        listing_edit_cursor += 1
                elif event.key == pygame.K_HOME:
                    listing_edit_cursor = 0
                elif event.key == pygame.K_END:
                    listing_edit_cursor = len(listing_edit_text)
                elif event.key == pygame.K_BACKSPACE:
                    if listing_edit_cursor > 0:
                        listing_edit_text = listing_edit_text[:listing_edit_cursor - 1] + listing_edit_text[listing_edit_cursor:]
                        listing_edit_cursor -= 1
                elif event.key == pygame.K_DELETE:
                    if listing_edit_cursor < len(listing_edit_text):
                        listing_edit_text = listing_edit_text[:listing_edit_cursor] + listing_edit_text[listing_edit_cursor + 1:]
            else:
                if event.key == pygame.K_TAB:
                    line_nums = sorted(program.keys())
                    if line_nums:
                        idx = min(listing_scroll_index, len(line_nums) - 1)
                        start_listing_edit(line_nums[idx])
                    else:
                        start_listing_edit(None)
                elif event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
                    line_str = input_text.strip()
                    should_clear_input = True
                    if z80_monitor_mode:
                        mon = get_crystal_monitor()
                        mon.handle_command(line_str)
                        input_text = ""
                        input_cursor_pos = 0
                        canvas_dirty = True
                        update_display()
                        continue

                    if z80_interactive_mode:
                        if line_str.upper() in ("END Z80", "ENDZ80", "END_Z80", "BYE", "EXIT", "Z80"):
                            z80_interactive_mode = False
                            canvas_print("OK (Returning to BASIC)")
                        elif line_str:
                            canvas_print(f"Z> {line_str}")
                            m_ln = re.match(r"^(\d+)\s*(.*)$", line_str)
                            if m_ln:
                                ln_val = int(m_ln.group(1))
                                code_part = m_ln.group(2).strip()
                                if code_part:
                                    zeus_source[ln_val] = code_part
                                else:
                                    zeus_source.pop(ln_val, None)
                            else:
                                cmd_upper = line_str.upper().strip()
                                if cmd_upper in ("A", "ASSEMBLE"):
                                    try:
                                        asm = get_zeus_assembler()
                                        full_src = "\n".join(zeus_source[k] for k in sorted(zeus_source.keys()))
                                        cbytes = asm.assemble(full_src, target_memory=memory)
                                        canvas_print(f"Assembled {len(cbytes)} bytes at ORG {asm.org_address} (0x{asm.org_address:04X})")
                                        if asm.errors:
                                            for err in asm.errors:
                                                canvas_print(f"Error: {err}")
                                        else:
                                            canvas_print("0 errors.")
                                    except Exception as ex:
                                        canvas_print(f"Assembly error: {ex}")
                                elif cmd_upper in ("C", "CARTRIDGE", "ROM") or cmd_upper.startswith(("C ", "CARTRIDGE ", "ROM ")):
                                    if cmd_upper in ("C", "CARTRIDGE", "ROM"):
                                        try:
                                            asm = get_zeus_assembler()
                                            full_src = "\n".join(zeus_source[k] for k in sorted(zeus_source.keys()))
                                            if full_src.strip():
                                                cbytes = asm.assemble(full_src, target_memory=memory)
                                            else:
                                                cbytes = getattr(asm, 'code_bytes', None)
                                            if cbytes and len(cbytes) > 0:
                                                swap_cartridge_rom(cbytes, name="Zeus Cartridge")
                                                canvas_print(f"Swapped {len(cbytes)} bytes into Cartridge ROM (0x0000..0x3FFF).")
                                                canvas_print("Type RESET to boot into cartridge.")
                                            else:
                                                canvas_print("No assembled code in Zeus buffer. Enter source or specify address.")
                                        except Exception as ex:
                                            canvas_print(f"Assembly error: {ex}")
                                    else:
                                        handle_cartridge_command(line_str)
                                elif cmd_upper == "RESET":
                                    handle_system_reset()
                                elif cmd_upper == "BOOT" or cmd_upper.startswith("BOOT ") or cmd_upper.startswith("BOOT:"):
                                    handle_boot_command(line_str)
                                elif cmd_upper == "MODE" or cmd_upper.startswith("MODE ") or cmd_upper.startswith("MODE:"):
                                    handle_mode_command(line_str)
                                elif cmd_upper in ("M", "MON", "MONITOR") or cmd_upper.startswith(("M ", "MON ", "MONITOR ")):
                                    parts = line_str.split(" ", 1)
                                    arg = parts[1].strip() if len(parts) > 1 else ""
                                    start_addr = parse_monitor_val(arg) if arg else None
                                    z80_interactive_mode = False
                                    mon = get_crystal_monitor()
                                    mon.open(addr=start_addr, origin="ZEUS")
                                    input_text = ""
                                    input_cursor_pos = 0
                                    canvas_dirty = True
                                    update_display()
                                    continue
                                elif cmd_upper in ("R", "RUN"):
                                    try:
                                        asm = get_zeus_assembler()
                                        full_src = "\n".join(zeus_source[k] for k in sorted(zeus_source.keys()))
                                        if full_src.strip():
                                            asm.assemble(full_src, target_memory=memory)
                                        cpu = get_z80_cpu()
                                        start_addr = asm.org_address
                                        canvas_print(f"Running machine code at {start_addr} (0x{start_addr:04X})...")
                                        steps = cpu.run_from(start_addr)
                                        canvas_print(f"Execution complete: {steps} instructions. BC={cpu.BC}")
                                    except Exception as ex:
                                        canvas_print(f"Execution error: {ex}")
                                elif cmd_upper == "LIST CODE":
                                    handle_list_code_command()
                                elif cmd_upper in ("L", "LIST"):
                                    listing_code_active = False
                                    listing_vars_active = False
                                    for k in sorted(zeus_source.keys()):
                                        canvas_print(f"{k} {zeus_source[k]}")
                                elif cmd_upper in ("N", "NEW"):
                                    zeus_source.clear()
                                    canvas_print("Zeus buffer cleared.")
                                elif cmd_upper.startswith("D ") or cmd_upper.startswith("DELETE "):
                                    del_arg = line_str.split(" ", 1)[1].strip()
                                    if "-" in del_arg:
                                        p1, p2 = del_arg.split("-", 1)
                                        s_ln = int(p1) if p1.strip() else 0
                                        e_ln = int(p2) if p2.strip() else 99999
                                        for k in list(zeus_source.keys()):
                                            if s_ln <= k <= e_ln:
                                                del zeus_source[k]
                                    elif del_arg.isdigit():
                                        zeus_source.pop(int(del_arg), None)
                                elif cmd_upper.startswith("SAVE ") or cmd_upper.startswith("EXPORT "):
                                    parts = line_str.split(" ", 1)
                                    name = parts[1].strip().strip('"\'') if len(parts) > 1 else "code"
                                    asm = get_zeus_assembler()
                                    full_src = "\n".join(zeus_source[k] for k in sorted(zeus_source.keys()))
                                    cbytes = asm.assemble(full_src, target_memory=memory)
                                    asm_file = f"{name}.asm"
                                    tap_file = f"{name}.tap"
                                    export_zeus_asm(asm_file, asm)
                                    export_zeus_tap(tap_file, name, asm.org_address, cbytes)
                                    canvas_print(f"Exported '{asm_file}' and '{tap_file}' ({len(cbytes)} bytes).")
                                else:
                                    try:
                                        asm = get_zeus_assembler()
                                        cbytes = asm.assemble(f"ORG 0x8000\n{line_str}\nRET", target_memory=memory)
                                        cpu = get_z80_cpu()
                                        cpu.run_from(0x8000)
                                        canvas_print(f"Executed. A={cpu.A} BC={cpu.BC} DE={cpu.DE} HL={cpu.HL}")
                                    except Exception as ex:
                                        canvas_print(f"Error: {ex}")
                            canvas_print("Z>")
                        else:
                            canvas_print("Z>")
                        input_text = ""
                        input_cursor_pos = 0
                        canvas_dirty = True
                        update_display()
                        continue

                    if prolog_interactive_mode:
                        if line_str.upper() in ("END PROLOG", "ENDPROLOG", "END_PROLOG", "BYE", "PROLOG"):
                            prolog_interactive_mode = False
                            canvas_print("OK (Returning to BASIC)")
                        elif line_str:
                            canvas_print(f"> {line_str}")
                            try:
                                get_prolog_engine().interpret(line_str, print_fn=canvas_print)
                            except Exception as pe:
                                canvas_print(f"Prolog error: {pe}")
                            canvas_print("&.")
                        else:
                            canvas_print("&.")
                        input_text = ""
                        input_cursor_pos = 0
                        canvas_dirty = True
                        update_display()
                        continue

                    if logo_interactive_mode:
                        if line_str.upper() in ("END LOGO", "ENDLOGO", "END_LOGO", "BYE", "LOGO"):
                            logo_interactive_mode = False
                            canvas_print("OK (Returning to BASIC)")
                        elif line_str:
                            canvas_print(f"> {line_str}")
                            try:
                                get_logo_engine().interpret(line_str)
                                update_display()
                            except Exception as le:
                                canvas_print(f"Logo error: {le}")
                        else:
                            canvas_print("OK")
                        input_text = ""
                        input_cursor_pos = 0
                        canvas_dirty = True
                        update_display()
                        continue

                    if forth_interactive_mode:
                        if line_str.upper() in ("END FORTH", "END_FORTH", "BYE"):
                            forth_interactive_mode = False
                            canvas_print("OK (Returning to BASIC)")
                        elif line_str:
                            canvas_print(f"> {line_str}")
                            try:
                                get_forth_engine().interpret(line_str)
                                if get_forth_engine().state == 0:
                                    canvas_print("OK")
                            except Exception as fe:
                                canvas_print(f"Forth error: {fe}")
                        else:
                            canvas_print("OK")
                        input_text = ""
                        input_cursor_pos = 0
                        canvas_dirty = True
                        update_display()
                        continue

                    if line_str:
                        parts = line_str.split(" ", 1)
                        if parts[0].isdigit():
                            ln = int(parts[0])
                            if len(parts) > 1 and parts[1].strip():
                                program[ln] = parts[1]
                                if auto_active:
                                    auto_next_line = ln + auto_step
                                    input_text = f"{auto_next_line} "
                                    input_cursor_pos = len(input_text)
                                    should_clear_input = False
                            elif ln in program:
                                del program[ln]
                                if auto_active:
                                    auto_active = False
                            elif auto_active:
                                auto_active = False
                            parse_data_lines()
                            _split_cache.clear()
                        else:
                            upper_line = line_str.upper()
                            if upper_line.startswith("GO TO "):
                                cmd = "GO TO"
                                args_part = line_str[6:].strip()
                            elif upper_line.startswith("GO SUB "):
                                cmd = "GO SUB"
                                args_part = line_str[7:].strip()
                            elif upper_line.startswith("DEF FN "):
                                cmd = "DEF FN"
                                args_part = line_str[7:].strip()
                            elif upper_line.startswith("DEF KEY ") or upper_line.startswith("DEF KEY:"):
                                cmd = "DEF KEY"
                                args_part = line_str[7:].strip().lstrip(":").strip()
                            elif upper_line.startswith("SAVE*") or upper_line.startswith("SAVE *"):
                                cmd = "SAVE"
                                args_part = line_str[4:].strip()
                            elif upper_line.startswith("LOAD*") or upper_line.startswith("LOAD *"):
                                cmd = "LOAD"
                                args_part = line_str[4:].strip()
                            elif upper_line.startswith("VERIFY*") or upper_line.startswith("VERIFY *"):
                                cmd = "VERIFY"
                                args_part = line_str[6:].strip()
                            elif upper_line.startswith("MERGE*") or upper_line.startswith("MERGE *"):
                                cmd = "MERGE"
                                args_part = line_str[5:].strip()
                            elif upper_line.startswith("MOUSEY/") or upper_line.startswith("MOUSEY:"):
                                cmd = "MOUSEY"
                                args_part = line_str[6:].strip()
                            elif upper_line.startswith("MOUSE/") or upper_line.startswith("MOUSE:"):
                                cmd = "MOUSE"
                                args_part = line_str[5:].strip()
                            elif upper_line.startswith("SPECDRUM/") or upper_line.startswith("SPECDRUM:"):
                                cmd = "SPECDRUM"
                                args_part = line_str[8:].strip()
                            elif upper_line.startswith("DRUM/") or upper_line.startswith("DRUM:"):
                                cmd = "DRUM"
                                args_part = line_str[4:].strip()
                            elif upper_line.startswith("SOUND/") or upper_line.startswith("SOUND:"):
                                cmd = "SOUND"
                                args_part = line_str[5:].strip()
                            elif upper_line.startswith("PLAY:") or upper_line.startswith("PLAY\"") or upper_line.startswith("PLAY/") or upper_line.startswith("PLAY?"):
                                cmd = "PLAY"
                                args_part = line_str[4:].strip()
                            elif upper_line.startswith("SPECTRUM:") or upper_line.startswith("SPECTRUM?"):
                                cmd = "SPECTRUM"
                                args_part = line_str[8:].strip()
                            elif upper_line.startswith("BANK:") or upper_line.startswith("BANK?") or upper_line.startswith("PAGE:") or upper_line.startswith("PAGE?"):
                                cmd = "BANK" if "BANK" in upper_line else "PAGE"
                                args_part = line_str[4:].strip()
                            elif upper_line == "HELP" or upper_line.startswith(("HELP ", "HELP:", "HELP/", "HELP?")):
                                cmd = "HELP"
                                args_part = re.sub(r'(?i)^HELP\s*[:/?]?\s*', '', line_str).strip()
                            elif upper_line == "?" or upper_line.startswith(("? ", "?:", "?/")) or (upper_line.startswith("?") and not upper_line.startswith("?=")):
                                cmd = "HELP"
                                args_part = re.sub(r'^\?\s*[:/?]?\s*', '', line_str).strip()
                            else:
                                cmd = parts[0].upper()
                                args_part = parts[1].strip() if len(parts) > 1 else ""

                            is_fs_run = False
                            if cmd == "RUN/FS" or cmd.startswith("RUN/FS"):
                                args_part = (cmd[6:] + " " + args_part).strip()
                                cmd = "RUN"
                                is_fs_run = True
                            elif cmd == "RUN":
                                m_fs = re.search(r'(?i)(?:^|\s|\d)(/FS)\b', args_part)
                                if m_fs:
                                    is_fs_run = True
                                    args_part = re.sub(r'(?i)/FS\b', '', args_part).strip()

                            is_fs_cpm = False
                            if cmd == "CPM/FS" or cmd.startswith("CPM/FS"):
                                args_part = (cmd[6:] + " " + args_part).strip()
                                cmd = "CPM"
                                is_fs_cpm = True
                            elif cmd == "CPM" or cmd.startswith("CPM:"):
                                if cmd.startswith("CPM:"):
                                    args_part = (cmd[4:] + " " + args_part).strip()
                                    cmd = "CPM"
                                m_fs = re.search(r'(?i)(?:^|\s|\d|["\'])(/FS)\b', args_part)
                                if m_fs:
                                    is_fs_cpm = True
                                    args_part = re.sub(r'(?i)(?:^|\s|\d|["\'])/FS\b', '', args_part).strip()

                            valid_commands = VALID_COMMANDS
                            valid_statements = VALID_STATEMENTS
                            is_assignment = "=" in line_str and not any(line_str.upper().startswith(kw) for kw in ["IF", "DEF", "FOR"])
                            is_amx_cmd = line_str.strip().startswith("*")
                            is_spectranet_cmd = cmd.startswith("%") or line_str.strip().startswith("%")

                            if cmd in valid_commands or cmd in valid_statements or is_assignment or is_amx_cmd or is_spectranet_cmd or line_str.strip().startswith(".") or line_str.strip().startswith(":"):
                                if cmd == "TRON":
                                    trace_on = True
                                elif cmd == "TROFF":
                                    trace_on = False
                                    current_trace_line = None
                                elif cmd == "ATTACH":
                                    handle_attach_command(args_part)
                                    pygame.key.start_text_input()
                                elif cmd == "DRIVE":
                                    handle_drive_command(args_part)
                                    pygame.key.start_text_input()
                                elif cmd in ("GUI", "GUI ON", "GUI OFF"):
                                    commit_listing_edit(advance=False)
                                    if handle_gui_command:
                                        handle_gui_command(line_str)
                                    if cmd == "GUI OFF" or line_str.upper().strip().startswith("GUI OFF"):
                                        set_zx48_mode()
                                    pygame.key.start_text_input()
                                elif cmd == "ICONED":
                                    commit_listing_edit(advance=False)
                                    if launch_icon_editor:
                                        launch_icon_editor(args_part)
                                    pygame.key.start_text_input()
                                elif cmd == "ICON":
                                    if handle_wimp_icon_command:
                                        handle_wimp_icon_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd == "MENU":
                                    if handle_wimp_menu_command:
                                        handle_wimp_menu_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd in ("MOUSE", "MOUSEY"):
                                    if handle_wimp_mouse_command and "," in line_str:
                                        handle_wimp_mouse_command(line_str)
                                    else:
                                        handle_mousey_command(line_str)
                                    pygame.key.start_text_input()

                                elif cmd == "DRUMS":
                                    commit_listing_edit(advance=False)
                                    launch_drum_editor(args_part)
                                    pygame.key.start_text_input()
                                elif cmd in ("SFX", "SFXED", "SOUNDED"):
                                    commit_listing_edit(advance=False)
                                    launch_sfx_editor(args_part)
                                    pygame.key.start_text_input()
                                elif cmd == "MUSIC":
                                    commit_listing_edit(advance=False)
                                    launch_music_editor(args_part)
                                    pygame.key.start_text_input()
                                elif cmd.startswith("SET") and ("DRIVE" in upper_line or "MDR" in upper_line):
                                    if "DRIVE" in upper_line:
                                        handle_set_drive_command(line_str)
                                    else:
                                        handle_set_mdr_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd in ("DRUM", "SPECDRUM"):
                                    handle_specdrum_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd == "SOUND":
                                    handle_sound_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd == "PLAY":
                                    handle_play_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd == "SPECTRUM":
                                    handle_spectrum_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd == "ZX48":
                                    set_zx48_mode()
                                    pygame.key.start_text_input()
                                elif cmd == "ZX128":
                                    set_zx128_mode()
                                    pygame.key.start_text_input()
                                elif cmd in ("ZXP3", "ZX+3", "PLUS3"):
                                    set_zxp3_mode()
                                    pygame.key.start_text_input()
                                elif cmd in ("TIMEX", "TS2068", "TC2068"):
                                    handle_timex_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd in ("SONIC", "SSOUND"):
                                    handle_sonic_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd == "SPLAY":
                                    handle_splay_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd == "SILVER":
                                    handle_silver_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd == "VOICE":
                                    handle_voice_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd == "TEMPO":
                                    handle_tempo_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd == "PITCH":
                                    handle_pitch_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd == "ENVELOPE":
                                    handle_envelope_command(line_str)
                                    pygame.key.start_text_input()
                                elif cmd.startswith("PRINT #4") or cmd.startswith("PRINT#4") or cmd in ("FCAT", "FDIR", "CAT #4", "DIR #4", "FLOAD", "FSAVE", "FVERIFY", "FMERGE", "FERASE", "FDELETE", "FRENAME", "FREN", "DINIT", "DCOPY", "BACKUP", "FPROTECT", "FUNPROTECT", "FEXEC", "RAMDISK"):
                                    handle_lkdos_statement(line_str)
